-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112280000_push_notifications_i18n_wave6.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.mommy_day_notifications SET title_es = '¡Agua, agua por todas partes! 💧', body_es = 'Tenía que servirse el agua en el vaso él solito. Lo ha derramado y todo está mojado. Pero mira esas manitas que han cogido un trapo e intentan limpiarlo. Aprende responsabilidad equivocándose, no te enfades.', title_fr = 'De l''eau, de l''eau partout ! 💧', body_fr = 'Il tenait absolument à verser l''eau tout seul dans le gobelet. Tout s''est renversé, tout est mouillé. Mais regardez ses petites mains qui attrapent le chiffon pour essayer de nettoyer. Il apprend la responsabilité en se trompant, ne vous énervez pas.', title_hi = 'पानी, हर तरफ़ पानी! 💧', body_hi = 'गिलास में पानी उसे खुद ही डालना था। गिरा दिया, सब कुछ भीग गया। पर उन छोटे हाथों को देखिए जो कपड़ा लेकर सब साफ़ करने की कोशिश कर रहे हैं। वह गलतियों से ज़िम्मेदारी सीख रहा है, नाराज़ मत होइए।', title_id = 'Air, air di mana-mana! 💧', body_id = 'Ia bersikeras menuang air ke gelas sendiri. Tumpah, semuanya basah. Tapi lihat tangan kecilnya yang mengambil lap dan berusaha membersihkannya. Ia belajar tanggung jawab dari kesalahannya, jangan kesal.', title_ja = 'お水、お水、どこもお水！💧', body_ja = 'コップにお水を自分で注ぐと言ってきかなかったのに、こぼしてあたりはびしょびしょ。でも、ふきんを持ってきて一生けんめい拭こうとする小さな手を見てあげて。失敗しながら責任を学んでいます。怒らないでね。', title_ko = '물, 온 사방이 물! 💧', body_ko = '컵에 물을 꼭 자기가 따르겠다더니 쏟아서 온통 젖었나요? 그래도 걸레를 집어 닦으려는 그 작은 손을 보세요. 실수하면서 책임감을 배우는 중이에요. 화내지 마세요.', title_nl = 'Water, overal water! 💧', body_nl = 'Hij moest en zou zelf water in zijn beker schenken. Gemorst, alles nat. Maar kijk eens naar die kleine handjes die een doekje pakken om het op te ruimen. Hij leert verantwoordelijkheid door fouten te maken, word niet boos.', title_pl = 'Woda, wszędzie woda! 💧', body_pl = 'Koniecznie chciał sam nalać wody do kubka. Rozlał, wszystko mokre. Ale spójrz na te małe rączki, które chwyciły ściereczkę i próbują wytrzeć. Uczy się odpowiedzialności na błędach, nie denerwuj się.', title_pt = 'Água, água por todo o lado! 💧', body_pt = 'Fazia mesmo questão de deitar sozinho a água no copo. Entornou e ficou tudo molhado. Mas olhe para aquelas mãozinhas a pegar no pano para tentar limpar. Está a aprender a ser responsável com os erros, não se zangue.', title_sv = 'Vatten, vatten överallt! 💧', body_sv = 'Barnet skulle absolut hälla upp vattnet i glaset själv. Det spilldes och allt blev blött. Men titta på de små händerna som tar trasan och försöker torka upp. Barnet lär sig ansvar genom sina misstag, bli inte arg.', title_vi = 'Nước, nước khắp nơi! 💧', body_vi = 'Bé nhất quyết tự rót nước vào cốc. Đổ hết ra, ướt khắp nơi. Nhưng hãy nhìn đôi bàn tay nhỏ đang cầm khăn cố lau chỗ đó. Bé đang học trách nhiệm qua chính lỗi sai của mình, mẹ đừng bực nhé.', title_zh = '水，到处都是水！💧', body_zh = '非要自己往杯子里倒水，结果洒了一地，到处都湿了。可你看看那双拿起抹布、努力想擦干净的小手。宝宝正在从错误中学会责任，别生气。' WHERE id = '15f19421-c415-4b7b-ad4d-54211e4ccb3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Le toca a papá 👨‍👧', body_es = 'La maternidad no es un maratón sin fin. Deja que hoy papá se encargue de la carrera por el parque y tú disfruta de la soledad en el sofá.', title_fr = 'Au tour de papa 👨‍👧', body_fr = 'La maternité n''est pas un marathon sans fin. Laissez papa gérer la course au parc aujourd''hui, et savourez un moment de solitude sur le canapé.', title_hi = 'पापा की बारी 👨‍👧', body_hi = 'माँ बनना कभी न खत्म होने वाली मैराथन नहीं है। आज पार्क की भागदौड़ पापा को संभालने दीजिए, और आप सोफ़े पर अकेलेपन का मज़ा लीजिए।', title_id = 'Giliran Ayah 👨‍👧', body_id = 'Menjadi ibu bukan maraton tanpa akhir. Biarkan Ayah yang mengurus jalan-jalan ke taman hari ini, sementara Anda menikmati waktu sendiri di sofa.', title_ja = 'パパの出番 👨‍👧', body_ja = 'ママ業は終わりのないマラソンではありません。今日の公園での追いかけっこはパパにまかせて、あなたはソファでひとりの時間を楽しみましょう。', title_ko = '아빠 차례 👨‍👧', body_ko = '엄마 노릇은 끝없는 마라톤이 아니에요. 오늘 공원 뛰어놀기는 아빠에게 맡기고, 엄마는 소파에서 혼자만의 시간을 즐기세요.', title_nl = 'Papa''s beurt 👨‍👧', body_nl = 'Moederschap is geen eindeloze marathon. Laat papa vandaag het parkrondje doen en geniet jij op de bank van wat tijd voor jezelf.', title_pl = 'Kolej taty 👨‍👧', body_pl = 'Macierzyństwo to nie niekończący się maraton. Niech dziś tata przejmie wyjście do parku, a ty rozkoszuj się chwilą samotności na kanapie.', title_pt = 'A vez do pai 👨‍👧', body_pt = 'A maternidade não é uma maratona sem fim. Deixe que hoje seja o pai a tratar da corrida no parque e aproveite um momento sozinha no sofá.', title_sv = 'Pappas tur 👨‍👧', body_sv = 'Moderskap är inget ändlöst maraton. Låt pappa ta hand om dagens springande i parken, medan du njuter av lite egen tid i soffan.', title_vi = 'Đến lượt bố 👨‍👧', body_vi = 'Làm mẹ không phải là một cuộc chạy marathon bất tận. Hôm nay hãy để bố lo buổi chạy nhảy ở công viên, còn mẹ tận hưởng chút thời gian một mình trên ghế sofa.', title_zh = '爸爸接班 👨‍👧', body_zh = '当妈妈不是一场没有终点的马拉松。今天去公园跑跑跳跳就交给爸爸吧，你在沙发上好好享受独处的时光。' WHERE id = '6d2f1d1e-d7d7-41c3-b906-1e286aab1a51' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Masaje en equipo 💆‍♂️', body_es = 'Cuando el peque se duerma, daos un masaje de hombros tú y tu pareja para soltar el estrés del día. No sois solo padres: sois el mayor apoyo de esta casa y el uno del otro.', title_fr = 'Massage d''équipe 💆‍♂️', body_fr = 'Une fois l''enfant couché, massez-vous les épaules l''un l''autre avec votre partenaire pour évacuer le stress de la journée. Vous n''êtes pas seulement des parents, vous êtes le plus grand soutien de cette maison et l''un de l''autre.', title_hi = 'टीम मसाज 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ एक-दूसरे के कंधों की मालिश कीजिए। आप सिर्फ़ माता-पिता नहीं, इस घर के और एक-दूसरे के सबसे बड़े सहारे हैं।', title_id = 'Pijat berdua 💆‍♂️', body_id = 'Setelah anak tidur, saling pijat bahu bersama pasangan untuk melepas stres seharian. Anda bukan sekadar orang tua, Anda adalah pendukung terbesar rumah ini dan satu sama lain.', title_ja = 'チームでマッサージ 💆‍♂️', body_ja = '子どもが寝たら、パートナーと肩をもみ合って一日のストレスを手放しましょう。ふたりはただの親ではなく、この家とお互いのいちばんの応援団です。', title_ko = '팀 마사지 💆‍♂️', body_ko = '아이가 잠들면 하루의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 두 사람은 그냥 부모가 아니라 이 집과 서로의 가장 큰 응원군이에요.', title_nl = 'Massage als team 💆‍♂️', body_nl = 'Geef elkaar met je partner een schoudermassage als je kind slaapt, om de stress van de dag kwijt te raken. Jullie zijn niet alleen ouders, jullie zijn ook elkaars grootste steun in dit huis.', title_pl = 'Masaż we dwoje 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres całego dnia. Nie jesteście tylko rodzicami, jesteście dla siebie największym wsparciem w tym domu.', title_pt = 'Massagem em equipa 💆‍♂️', body_pt = 'Depois de a criança adormecer, façam massagens nos ombros um ao outro para libertar o stress do dia. Não são apenas pais: são o maior apoio desta casa e um do outro.', title_sv = 'Lagmassage 💆‍♂️', body_sv = 'När barnet har somnat kan du och din partner ge varandra en axelmassage för att släppa dagens stress. Ni är inte bara föräldrar, ni är hemmets och varandras största stöd.', title_vi = 'Mát-xa cho nhau 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng chồng mát-xa vai cho nhau để xua tan căng thẳng cả ngày. Hai người không chỉ là bố mẹ, mà còn là chỗ dựa lớn nhất của nhau trong ngôi nhà này.', title_zh = '双人按摩 💆‍♂️', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天的压力。你们不只是父母，更是这个家、也是彼此最坚实的支持者。' WHERE id = 'cf9e0ee2-2f17-4a55-933b-735bc0754d7e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estoy cansada... 🔋', body_es = 'Todos esperan energía de ti, pero tu batería se ha agotado. Hoy no cocines nada: pide comida o hierve la pasta más sencilla. Ser una superheroína no te obliga a hacerlo todo sola.', title_fr = 'Je suis fatiguée... 🔋', body_fr = 'Tout le monde attend de l''énergie de vous, mais votre batterie est à plat. Ne cuisinez rien aujourd''hui : commandez ou faites cuire des pâtes toutes simples. Être une super-héroïne, ce n''est pas tout faire seule.', title_hi = 'मैं थक गई हूँ... 🔋', body_hi = 'सब आपसे ऊर्जा की उम्मीद करते हैं, पर आपकी बैटरी खत्म हो चुकी है। आज कुछ मत पकाइए, बाहर से मँगवा लीजिए या सबसे आसान पास्ता उबाल लीजिए। सुपरहीरो होने का मतलब सब कुछ अकेले करना नहीं है।', title_id = 'Aku lelah... 🔋', body_id = 'Semua orang mengharapkan energi dari Anda, padahal baterai Anda sudah habis. Hari ini jangan memasak apa pun, pesan makanan atau rebus saja pasta paling sederhana. Menjadi Super Hero tidak berarti harus melakukan semuanya sendiri.', title_ja = 'もう疲れた… 🔋', body_ja = 'みんながあなたに元気を期待しているけれど、バッテリーはもう空っぽ。今日は料理をお休みして、デリバリーを頼むか、いちばん簡単なパスタをゆでましょう。スーパーヒーローだからといって、何でもひとりでこなす必要はありません。', title_ko = '나 지쳤어... 🔋', body_ko = '모두가 엄마에게 에너지를 기대하지만 배터리가 바닥났죠. 오늘은 요리하지 말고 배달을 시키거나 가장 간단한 파스타를 삶으세요. 슈퍼히어로라고 모든 걸 혼자 해야 하는 건 아니에요.', title_nl = 'Ik ben moe... 🔋', body_nl = 'Iedereen verwacht energie van je, maar je batterij is leeg. Kook vandaag niets, bestel eten of kook de makkelijkste pasta. Supermama zijn betekent niet dat je alles alleen moet doen.', title_pl = 'Jestem zmęczona... 🔋', body_pl = 'Wszyscy oczekują od ciebie energii, a twoja bateria jest pusta. Dziś nic nie gotuj, zamów jedzenie albo ugotuj najprostszy makaron. Bycie Superbohaterką nie oznacza, że musisz robić wszystko sama.', title_pt = 'Estou cansada... 🔋', body_pt = 'Todos esperam energia de si, mas a sua bateria esgotou-se. Hoje não cozinhe nada: encomende comida ou coza a massa mais simples. Ser Super-Heroína não obriga a fazer tudo sozinha.', title_sv = 'Jag är trött... 🔋', body_sv = 'Alla väntar sig energi från dig, men batteriet är slut. Laga ingen mat i dag, beställ hem eller koka den enklaste pastan. Att vara en superhjälte betyder inte att du måste göra allt själv.', title_vi = 'Mẹ mệt rồi... 🔋', body_vi = 'Ai cũng chờ mẹ tràn đầy năng lượng, nhưng pin của mẹ đã cạn. Hôm nay đừng nấu gì cả, hãy gọi đồ ăn hoặc chỉ luộc món mì ống đơn giản nhất. Làm Siêu anh hùng không có nghĩa là phải tự gánh mọi thứ.', title_zh = '我累了…… 🔋', body_zh = '每个人都等着你充满能量，可你的电池已经耗尽了。今天什么都别做饭，点个外卖，或者煮一锅最简单的意面。当超级英雄，不等于什么事都得一个人扛。' WHERE id = '2caa3c21-d2d3-4566-921a-e08cdbce1397' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paz en la bañera 🛀', body_es = 'Todo el día ha sido un «no quiero» tras otro. Un baño templado no es solo higiene, sirve para reiniciar su sistema nervioso tenso. Escucha el sonido del agua y el ambiente cambiará al instante.', title_fr = 'La paix dans le bain 🛀', body_fr = 'Toute la journée n''a été qu''une suite de « je veux pas ». Le bain tiède n''est pas qu''une question d''hygiène, il sert à remettre à zéro son système nerveux sous tension. Écoutez le bruit de l''eau, l''ambiance de la pièce va changer aussitôt.', title_hi = 'बाथटब में शांति 🛀', body_hi = 'पूरा दिन ‘मुझे नहीं चाहिए’ में बीता। गुनगुना स्नान सिर्फ़ सफ़ाई के लिए नहीं, उसके तने हुए तंत्रिका तंत्र को रीसेट करने के लिए है। पानी की आवाज़ सुनिए, कमरे का माहौल तुरंत बदल जाएगा।', title_id = 'Damai di bak mandi 🛀', body_id = 'Seharian penuh dengan ''aku nggak mau''. Mandi air hangat bukan hanya soal kebersihan, tapi juga untuk menyegarkan kembali sarafnya yang tegang. Dengarkan suara air, suasana kamar akan langsung berubah.', title_ja = 'お風呂でひと休み 🛀', body_ja = '一日じゅう「いやだ」の連続でしたね。ぬるめのお風呂は清潔のためだけでなく、張りつめた神経をリセットするためのもの。お湯の音に耳をすませば、部屋の空気がすぐに変わります。', title_ko = '욕조 속 평화 🛀', body_ko = '하루 종일 ''싫어''로 가득했나요? 따뜻한 목욕은 위생만을 위한 게 아니라 곤두선 신경계를 초기화하는 시간이에요. 물소리에 귀 기울이면 방 안 분위기가 금세 바뀔 거예요.', title_nl = 'Rust in bad 🛀', body_nl = 'De hele dag stond in het teken van ''ik wil niet''. Een lauw bad is niet alleen voor de hygiëne, het reset ook zijn overprikkelde zenuwstelsel. Luister naar het geluid van het water en de sfeer in de kamer verandert meteen.', title_pl = 'Spokój w kąpieli 🛀', body_pl = 'Cały dzień upłynął pod znakiem „nie chcę”. Ciepła kąpiel to nie tylko higiena, ale reset dla jego przeciążonego układu nerwowego. Wsłuchaj się w szum wody, a atmosfera w pokoju od razu się zmieni.', title_pt = 'Paz na banheira 🛀', body_pt = 'O dia inteiro foi feito de "não quero". Um banho morno não serve só para a higiene, serve para reiniciar o sistema nervoso tenso dele. Ouçam o som da água e o ambiente muda logo.', title_sv = 'Fred i badkaret 🛀', body_sv = 'Hela dagen har gått åt till ”jag vill inte”. Ett ljummet bad är inte bara för hygienen, det nollställer barnets spända nervsystem. Lyssna på vattnets ljud, stämningen i rummet ändras direkt.', title_vi = 'Bình yên trong bồn tắm 🛀', body_vi = 'Cả ngày toàn là những câu "Con không muốn". Tắm nước ấm không chỉ để vệ sinh, mà còn giúp hệ thần kinh căng thẳng của bé được "khởi động lại". Hãy lắng nghe tiếng nước, không khí trong phòng sẽ thay đổi ngay.', title_zh = '浴缸里的和平 🛀', body_zh = '一整天都在“我不要”中度过。温水澡不只是为了清洁，更是为了让宝宝紧绷的神经系统重启。听听水声，房间里的气氛马上就会变。' WHERE id = '48299b62-1108-44e9-af43-b48460ffdfa2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escaleras en solitario 🧗', body_es = '¿Intenta subir las escaleras sin apoyo? ¡Su motricidad está en su mejor momento! Observa desde fuera sin intervenir. Inmortaliza este momento de independencia con la Sesión de fotos del bebé.', title_fr = 'Les escaliers en solo 🧗', body_fr = 'Il essaie de monter les escaliers sans aide ? Sa motricité est au top ! Observez de loin, n''intervenez pas. Immortalisez ce moment d''indépendance avec la Séance photo bébé.', title_hi = 'अकेले सीढ़ियाँ 🧗', body_hi = 'बिना सहारे सीढ़ियाँ चढ़ने की कोशिश कर रहा है? उसकी मोटर स्किल्स चरम पर हैं! दूर से देखिए, बीच में मत आइए। इस आत्मनिर्भर पल को बेबी फ़ोटोशूट से हमेशा के लिए सँजो लीजिए।', title_id = 'Naik tangga sendiri 🧗', body_id = 'Ia mencoba naik tangga tanpa pegangan? Motoriknya sedang di puncak! Awasi dari samping, jangan ikut campur. Abadikan momen mandiri ini dengan Pemotretan Bayi.', title_ja = 'ひとりで階段 🧗', body_ja = '支えなしで階段をのぼろうとしていますか？運動能力がぐんぐん伸びています！手を出さずに見守りましょう。このひとりでできた瞬間を「ベビーフォトセッション」で残してね。', title_ko = '혼자서 계단 오르기 🧗', body_ko = '잡지 않고 계단을 오르려 하나요? 운동 능력이 한창이에요! 끼어들지 말고 옆에서 지켜봐 주세요. 이 독립적인 순간을 아기 사진 촬영으로 남겨 두세요.', title_nl = 'Helemaal alleen de trap op 🧗', body_nl = 'Probeert hij zonder steun de trap op te klimmen? Zijn motoriek is op topniveau! Kijk van een afstand toe en grijp niet in. Leg dit zelfstandige moment vast met de Babyfotoshoot.', title_pl = 'Sam po schodach 🧗', body_pl = 'Próbuje wchodzić po schodach bez podparcia? Motoryka jest u szczytu! Obserwuj z boku i nie ingeruj. Uwiecznij tę chwilę samodzielności w Sesji zdjęciowej dziecka.', title_pt = 'Escadas sem ajuda 🧗', body_pt = 'Tenta subir as escadas sem apoio? A motricidade está no auge! Observe à distância, sem intervir. Eternize este momento de independência com a Sessão Fotográfica do Bebé.', title_sv = 'Trappan på egen hand 🧗', body_sv = 'Försöker barnet gå uppför trappan utan stöd? Motoriken är på topp! Titta på avstånd och lägg dig inte i. Förevige den här självständiga stunden med Babyfotografering.', title_vi = 'Tự leo cầu thang 🧗', body_vi = 'Bé cố leo cầu thang mà không cần vịn? Kỹ năng vận động đang ở đỉnh cao! Hãy quan sát từ xa, đừng can thiệp. Lưu giữ khoảnh khắc tự lập này bằng Chụp ảnh cho bé.', title_zh = '自己爬楼梯 🧗', body_zh = '想不扶东西自己上楼梯？动作发展正处于高峰！在一旁看着，别插手。用宝宝写真把这个独立的时刻永远留住吧。' WHERE id = 'ab5bd705-a57d-40d7-b0a0-86107e824b4d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La sorpresa de chocolate del súper 🛒', body_es = 'Antes de ir al súper abriste la Lista de la compra y viste que se había acercado por detrás, había tocado la pantalla y había garabateado algo. ¡Sí, también copia tu vida digital!', title_fr = 'Surprise chocolatée au supermarché 🛒', body_fr = 'Avant d''aller au supermarché, vous avez ouvert la Liste de courses, et il est arrivé derrière vous pour gribouiller quelque chose en tapotant l''écran. Eh oui, il copie aussi votre vie numérique !', title_hi = 'बाज़ार में चॉकलेट का सरप्राइज़ 🛒', body_hi = 'बाज़ार जाने से पहले आपने शॉपिंग लिस्ट खोली और देखा कि उसने पीछे से आकर स्क्रीन पर टैप करके कुछ लिख दिया है। हाँ, वह आपकी डिजिटल ज़िंदगी की भी नकल करता है!', title_id = 'Kejutan cokelat di supermarket 🛒', body_id = 'Sebelum ke supermarket Anda membuka Daftar Belanja, lalu ia datang dari belakang, menekan layar ponsel, dan mencoret-coret sesuatu di sana. Ya, ia juga meniru kehidupan digital Anda!', title_ja = 'スーパーでのチョコのサプライズ 🛒', body_ja = '買い物の前に「買い物リスト」を開いたら、後ろから来て画面をタップし、何か落書きしていたことに気づきましたか？そう、あなたのデジタルな暮らしもまねしているんです！', title_ko = '마트의 초콜릿 깜짝 선물 🛒', body_ko = '마트에 가기 전 쇼핑 목록을 열었는데, 아이가 뒤에서 와서 화면을 눌러 뭔가 끄적여 놓았나요? 네, 엄마의 디지털 생활까지 따라 하는 중이에요!', title_nl = 'Chocoladeverrassing in de supermarkt 🛒', body_nl = 'Je opende voor het boodschappen doen je Boodschappenlijstje en zag dat hij van achteren op het scherm drukte en er iets op krabbelde. Ja, hij kopieert ook je digitale leven!', title_pl = 'Czekoladowa niespodzianka w sklepie 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś Listę zakupów, a on podszedł od tyłu, stuknął w ekran i coś tam nabazgrał. Tak, kopiuje też twoje cyfrowe życie!', title_pt = 'A surpresa de chocolate no supermercado 🛒', body_pt = 'Antes de ir ao supermercado abriu a Lista de Compras e viu-o vir por trás, carregar no ecrã do telemóvel e rabiscar qualquer coisa? Pois é, ele também copia a sua vida digital!', title_sv = 'Chokladöverraskningen i butiken 🛒', body_sv = 'Innan du gick till butiken öppnade du Inköpslistan, och barnet kom bakifrån och klottrade något på skärmen. Ja, barnet kopierar ditt digitala liv också!', title_vi = 'Bất ngờ sô-cô-la ở siêu thị 🛒', body_vi = 'Trước khi đi siêu thị, mẹ mở Danh sách mua sắm và thấy bé từ phía sau chạm vào màn hình điện thoại, vẽ nguệch ngoạc gì đó. Đúng vậy, bé còn bắt chước cả cuộc sống số của mẹ nữa!', title_zh = '超市里的巧克力惊喜 🛒', body_zh = '去超市前你打开了购物清单，结果发现宝宝从背后过来，在手机屏幕上一通乱点，涂涂画画了一番。没错，宝宝连你的数字生活也在模仿！' WHERE id = '028ed2b5-737d-4edf-81c1-5a9151e5fbf0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El encanto de la gramática inventada 🗣️', body_es = 'Ha descubierto tiempos verbales raros pero muy dulces, como «yo fui-iba» o «él venía-vino». ¡Su vocabulario crece como un torbellino! Guarda este idioma tan suyo en el Seguimiento del desarrollo como recuerdo.', title_fr = 'Le charme de la grammaire inventée 🗣️', body_fr = 'Il a inventé des conjugaisons étranges mais adorables, comme « j''ai allé » ou « il a venu ». Son vocabulaire explose ! Gardez une trace de sa langue bien à lui dans le Suivi de développement.', title_hi = 'गढ़ी हुई व्याकरण का मज़ा 🗣️', body_hi = 'उसने ‘मैं गया-गया’, ‘वह आ रहा था-सा’ जैसे अजीब, पर बहुत प्यारे काल के रूप खोज लिए हैं। उसकी शब्दावली तूफ़ान की तरह बढ़ रही है! उसकी इस खास अपनी भाषा को ग्रोथ ट्रैकर में यादगार की तरह दर्ज कीजिए।', title_id = 'Serunya tata bahasa buatan sendiri 🗣️', body_id = 'Ia menemukan bentuk kata kerja yang aneh tapi sangat lucu, seperti ''aku udah pergi-pergian'' atau ''dia datang-datangan''. Kosakatanya berkembang pesat! Catat bahasa khasnya ini di Pelacak Perkembangan sebagai arsip.', title_ja = '手づくり文法のかわいさ 🗣️', body_ja = '「行ったった」「来てたった」のような、ふしぎだけどとてもかわいい言い方を発見しています。語彙が嵐のように育っています！この子だけの言葉を「発達トラッカー」に記録して残しましょう。', title_ko = '엉뚱한 문법의 즐거움 🗣️', body_ko = '이상하지만 너무 귀여운 시제를 만들어 쓰나요? 어휘가 폭풍처럼 늘고 있어요! 아이만의 이 특별한 말을 성장 기록에 보관해 두세요.', title_nl = 'Genieten van zelfbedachte grammatica 🗣️', body_nl = 'Hij heeft vreemde maar superschattige tijdsvormen ontdekt, zoals ''ik loopte'' of ''hij komde''. Zijn woordenschat groeit razendsnel! Leg zijn eigen taaltje vast in de Groeitracker als archief.', title_pl = 'Urok wymyślonej gramatyki 🗣️', body_pl = 'Odkrył dziwne, ale przeurocze formy czasowników, w stylu „poszedłem się” czy „przyszedłował”. Jego słownictwo rozwija się jak burza! Zapisz ten jego wyjątkowy język w Śledzeniu rozwoju na pamiątkę.', title_pt = 'O encanto da gramática inventada 🗣️', body_pt = 'Descobriu formas verbais estranhas mas muito fofas, como "eu fazi" ou "ele cabeu"? O vocabulário cresce a toda a velocidade! Guarde no Registo de Crescimento esta língua tão especial dele, como arquivo.', title_sv = 'Påhittad grammatik 🗣️', body_sv = 'Barnet har upptäckt konstiga men väldigt söta tempusformer, som ”jag gådde” och ”hon kommde”. Ordförrådet växer som en storm! Spara barnets eget speciella språk i Utvecklingsspåraren.', title_vi = 'Niềm vui ngữ pháp tự chế 🗣️', body_vi = 'Bé đã "phát minh" ra những cách nói thì kỳ lạ nhưng vô cùng đáng yêu. Vốn từ của bé đang phát triển như vũ bão! Hãy lưu lại "ngôn ngữ riêng" đặc biệt này của bé trong Theo dõi phát triển như một kỷ niệm.', title_zh = '自创语法的乐趣 🗣️', body_zh = '发明了“我去去了”“他来来过”这种奇怪又超可爱的时态说法。词汇量像风暴一样增长！把宝宝这种专属的小语言记在发育追踪里存档吧。' WHERE id = '098cd94b-6989-48a8-9fdc-160a2f819cb0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué hay debajo de la cama? 👻', body_es = '¿Cree que hay monstruos en la oscuridad? Coge una botella llena solo de agua, rocíala por la habitación como si fuera un «espray ahuyentamiedos» y convéncele. Vence a la imaginación con imaginación.', title_fr = 'Qu''y a-t-il sous le lit ? 👻', body_fr = 'Il croit qu''il y a des monstres dans le noir ? Prenez simplement un flacon rempli d''eau et vaporisez-le dans la chambre comme « spray anti-monstres » pour le convaincre. Battez l''imagination avec l''imagination.', title_hi = 'पलंग के नीचे क्या है? 👻', body_hi = 'मानता है कि अँधेरे में राक्षस हैं? बस पानी भरी एक बोतल लीजिए और उसे ‘डर भगाने वाले स्प्रे’ की तरह कमरे में छिड़ककर उसे यकीन दिलाइए। कल्पना को कल्पना से हराइए।', title_id = 'Ada apa di bawah tempat tidur? 👻', body_id = 'Ia percaya ada monster di dalam gelap? Ambil botol semprot berisi air biasa, semprotkan ke seluruh kamar sebagai ''Semprotan Pengusir Monster'', dan yakinkan dia. Kalahkan imajinasi dengan imajinasi.', title_ja = 'ベッドの下には何がいる？ 👻', body_ja = '暗闇におばけがいると信じている？お水を入れただけのボトルを用意して、「おばけ退散スプレー」として部屋にシュッとかけて安心させてあげましょう。想像には想像で勝つんです。', title_ko = '침대 밑에 뭐가 있지? 👻', body_ko = '어둠 속에 괴물이 있다고 믿나요? 맹물을 담은 분무기를 들고 ''괴물 퇴치 스프레이''처럼 방에 뿌리며 안심시켜 주세요. 상상은 상상으로 이겨요.', title_nl = 'Wat zit er onder het bed? 👻', body_nl = 'Gelooft hij dat er monsters in het donker zitten? Pak een flesje met gewoon water en spuit het als ''monsterspray'' door de kamer om hem gerust te stellen. Versla fantasie met fantasie.', title_pl = 'Co jest pod łóżkiem? 👻', body_pl = 'Wierzy, że w ciemności czają się potwory? Weź butelkę ze zwykłą wodą i spryskaj pokój jako „sprayem na strachy”, by go uspokoić. Pokonaj wyobraźnię wyobraźnią.', title_pt = 'O que está debaixo da cama? 👻', body_pt = 'Acredita que há monstros no escuro? Pegue numa garrafa com água e convença-o borrifando o quarto com um "spray afasta-medos". Vença a imaginação com imaginação.', title_sv = 'Vad finns under sängen? 👻', body_sv = 'Tror barnet att det finns monster i mörkret? Ta en sprayflaska med bara vatten i och spraya i rummet som ”monsterspray” för att övertyga barnet. Besegra fantasin med fantasi.', title_vi = 'Dưới gầm giường có gì? 👻', body_vi = 'Bé tin rằng trong bóng tối có quái vật? Hãy lấy một chai chỉ đựng nước lọc và xịt quanh phòng như "bình xịt đuổi quái vật" để bé yên tâm. Hãy dùng trí tưởng tượng để chiến thắng trí tưởng tượng.', title_zh = '床底下有什么？👻', body_zh = '相信黑暗里有怪物？拿一个装满清水的瓶子，当作“驱怪喷雾”在房间里喷一喷，让宝宝安心。用想象力打败想象力。' WHERE id = '50dce5d9-294a-44b8-b1c9-316b84d5df14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La fiesta empezó a las 5 de la mañana! ⏰', body_es = 'Aún no ha salido el sol, pero él ya ha empezado el día saltando en la cama. Aunque tú sigas medio dormida, él está listo para conquistar el mundo. Únete y deja que esta energía loca te despierte también a ti.', title_fr = 'La fête commence à 5 h du matin ! ⏰', body_fr = 'Le soleil n''est pas encore levé, mais il a déjà commencé la journée en sautant sur le lit. Vous êtes encore endormie, lui est prêt à conquérir le monde. Rejoignez-le et laissez cette énergie folle vous réveiller, vous aussi.', title_hi = 'सुबह 5 बजे पार्टी शुरू! ⏰', body_hi = 'सूरज अभी निकला भी नहीं, पर वह पलंग पर उछलकर दिन शुरू कर चुका है। आप भले नींद में हों, वह दुनिया जीतने को तैयार है। उसके साथ शामिल हो जाइए, इस धमाकेदार ऊर्जा को आपको भी जगाने दीजिए।', title_id = 'Pesta dimulai jam 5 pagi! ⏰', body_id = 'Matahari belum terbit, tapi ia sudah memulai hari dengan melompat-lompat di kasur. Meski Anda masih mengantuk, ia sudah siap menaklukkan dunia. Bergabunglah, biarkan energi gilanya ikut membangunkan Anda.', title_ja = '朝5時からパーティー開始！ ⏰', body_ja = 'まだ太陽ものぼっていないのに、ベッドでジャンプして一日をスタート。あなたはまだ眠くても、この子は世界を征服する準備万端です。仲間に入って、このすごいエネルギーにあなたも起こしてもらいましょう。', title_ko = '새벽 5시에 파티 시작! ⏰', body_ko = '해도 안 떴는데 벌써 침대에서 뛰며 하루를 시작했나요? 엄마는 아직 졸려도 아이는 세상을 정복할 준비가 됐어요. 함께해 보세요, 이 엉뚱한 에너지가 엄마도 깨워 줄 거예요.', title_nl = 'Om 5 uur ''s ochtends begint het feest! ⏰', body_nl = 'De zon is nog niet op, maar hij is de dag al begonnen door op het bed te springen. Jij bent misschien nog slaperig, maar hij is klaar om de wereld te veroveren. Doe mee en laat je wakker worden door die gekke energie.', title_pl = 'Impreza o 5 rano! ⏰', body_pl = 'Słońce jeszcze nie wzeszło, a on już zaczął dzień od skakania po łóżku. Ty jeszcze śpisz, a on jest gotów podbijać świat. Dołącz do niego i pozwól, by ta szalona energia obudziła też ciebie.', title_pt = 'A festa começou às 5 da manhã! ⏰', body_pt = 'O sol ainda não nasceu, mas ele já começou o dia aos saltos na cama. Mesmo que ainda esteja com sono, ele está pronto para conquistar o mundo. Junte-se a ele e deixe que esta energia louca também a acorde.', title_sv = 'Klockan 5 på morgonen började festen! ⏰', body_sv = 'Solen har inte gått upp än, men barnet har redan börjat dagen med att hoppa i sängen. Även om du fortfarande är sömnig är barnet redo att erövra världen. Häng med och låt den galna energin väcka dig också.', title_vi = 'Bữa tiệc bắt đầu lúc 5 giờ sáng! ⏰', body_vi = 'Mặt trời còn chưa mọc, nhưng bé đã bắt đầu ngày mới bằng cách nhảy tưng tưng trên giường. Dù mẹ vẫn còn buồn ngủ, bé đã sẵn sàng chinh phục thế giới. Hãy tham gia cùng bé, để nguồn năng lượng "điên rồ" này đánh thức cả mẹ nữa.', title_zh = '早上5点派对开始了！⏰', body_zh = '太阳还没升起，宝宝已经在床上蹦蹦跳跳开始新的一天了。你还睡意蒙眬，宝宝却已准备好征服世界。加入宝宝吧，让这股疯狂的能量也把你唤醒。' WHERE id = '2cd29d0d-0cf1-403e-806d-35f84215b2df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Buscando guardería? 🏫', body_es = '¿Cerca de los 3 años te ronda la idea de la guardería, pero no logras decidirte? Si te cansa pensarlo sola, entra en la Comunidad Anacan y lee las experiencias reales de otras mamás.', title_fr = 'À la recherche d''une crèche ? 🏫', body_fr = 'L''idée de la crèche à l''approche des 3 ans vous trotte dans la tête, mais vous n''arrivez pas à décider ? Si vous êtes fatiguée d''y réfléchir seule, rejoignez la Communauté Anacan et lisez les vraies expériences d''autres mamans.', title_hi = 'प्ले स्कूल की तलाश? 🏫', body_hi = '3 साल के करीब आते ही प्ले स्कूल का ख्याल मन में घूम रहा है, पर फ़ैसला नहीं कर पा रहीं? अगर अकेले सोचते-सोचते थक गई हैं, तो Anacan कम्युनिटी में जाकर दूसरी माँओं के असली अनुभव पढ़िए।', title_id = 'Sedang mencari TK? 🏫', body_id = 'Menjelang usia 3 tahun, pikiran soal TK terus berputar di kepala, tapi Anda belum bisa memutuskan? Jika lelah memikirkannya sendiri, masuklah ke Komunitas Anacan dan baca pengalaman nyata ibu-ibu lain soal TK.', title_ja = '保育園さがし？ 🏫', body_ja = '3歳が近づき、保育園のことが頭から離れないのに決められない？ひとりで悩むのに疲れたら、Anacanコミュニティで、ほかのママたちのリアルな保育園体験を読んでみましょう。', title_ko = '어린이집 고민 중? 🏫', body_ko = '세 살 무렵 어린이집 생각이 머릿속을 맴도는데 결정을 못 하겠나요? 혼자 고민하기 지쳤다면 Anacan 커뮤니티에서 다른 엄마들의 실제 어린이집 경험담을 읽어 보세요.', title_nl = 'Op zoek naar een kinderdagverblijf? 🏫', body_nl = 'Spookt de gedachte aan een peuteropvang rond 3 jaar door je hoofd, maar kun je geen beslissing nemen? Ben je het moe om er alleen over na te denken, ga dan naar de Anacan Community en lees de echte ervaringen van andere mama''s.', title_pl = 'Szukasz przedszkola? 🏫', body_pl = 'Myśl o przedszkolu w okolicach 3 lat krąży ci po głowie, ale nie możesz się zdecydować? Jeśli masz dość rozmyślania w pojedynkę, wejdź do Społeczności Anacan i poczytaj o prawdziwych doświadczeniach innych mam.', title_pt = 'À procura de jardim de infância? 🏫', body_pt = 'Perto dos 3 anos, a ideia do jardim de infância não lhe sai da cabeça, mas não consegue decidir? Se está cansada de pensar sozinha, entre na Comunidade Anacan e leia as experiências reais de outras mães.', title_sv = 'Letar du förskola? 🏫', body_sv = 'Snurrar tanken på förskola i huvudet när barnet närmar sig 3 år, men du kan inte bestämma dig? Om du är trött på att fundera ensam, gå in i Anacan Community och läs andra mammors verkliga erfarenheter av förskolor.', title_vi = 'Đang tìm trường mầm non? 🏫', body_vi = 'Gần 3 tuổi, ý định cho bé đi mầm non cứ quanh quẩn trong đầu nhưng mẹ chưa thể quyết định? Nếu đã mệt vì phải suy nghĩ một mình, hãy vào Cộng đồng Anacan và đọc những trải nghiệm thực tế về trường mầm non của các mẹ khác.', title_zh = '在找幼儿园吗？🏫', body_zh = '快3岁了，送幼儿园的念头在脑子里转来转去，却拿不定主意？如果一个人想累了，就进入Anacan社区，读读其他妈妈真实的幼儿园经历。' WHERE id = '48550c10-c030-428e-9c25-ccd73ca09c55' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Registro de emociones 📝', body_es = '¿Alguien te ha dicho «estás en casa, ¿de qué te cansas?»? Abre ya el Diario de ánimo y vuelca todo tu enfado en la pantalla. Escribir lo que sientes de verdad, en lugar de sonreír a la fuerza, es terapia.', title_fr = 'Noter ses émotions 📝', body_fr = 'Quelqu''un vous a dit « Tu es à la maison, de quoi tu es fatiguée ? » ? Ouvrez tout de suite le Journal d''humeur et déversez toute votre colère sur l''écran. Écrire ce que vous ressentez vraiment est une thérapie, bien mieux qu''un sourire forcé.', title_hi = 'भावनाओं का रिकॉर्ड 📝', body_hi = 'किसी ने कहा, ‘घर पर ही तो हो, किस बात की थकान’? तुरंत मूड डायरी खोलिए और अपना सारा गुस्सा उँगलियों से स्क्रीन पर उतार दीजिए। झूठी मुस्कान से बेहतर है अपनी असली भावनाएँ लिखना, यही थेरेपी है।', title_id = 'Mencatat perasaan 📝', body_id = 'Ada yang bilang ''Kamu kan di rumah saja, capek dari mana''? Segera buka Buku Harian Suasana Hati dan tumpahkan semua kekesalan Anda ke layar lewat jari Anda. Menuliskan perasaan yang sebenarnya adalah terapi, jauh lebih baik daripada senyum palsu.', title_ja = '気持ちの記録 📝', body_ja = '「家にいるのに何で疲れるの？」と言われましたか？すぐに「気分日記」を開いて、イライラを全部指で画面にはき出しましょう。作り笑いより、本当の気持ちを書くことがセラピーになります。', title_ko = '감정 기록 📝', body_ko = '누군가 ''집에 있으면서 뭐가 그렇게 피곤해?''라고 했나요? 바로 기분 일기를 열고 쌓인 속상함을 손끝으로 모두 쏟아내세요. 억지 미소보다 진짜 감정을 적는 게 치료예요.', title_nl = 'Je gevoelens vastleggen 📝', body_nl = 'Zei iemand: ''Je bent toch thuis, waar word je moe van?'' Open meteen je Stemmingsdagboek en tik al je frustratie van je af. Je echte gevoelens opschrijven is therapie, veel beter dan een geforceerde glimlach.', title_pl = 'Zapisz swoje emocje 📝', body_pl = 'Ktoś ci powiedział: „Siedzisz w domu, czym się męczysz?”. Od razu otwórz Dziennik nastroju i wyrzuć z siebie całą złość na ekran. Zapisywanie prawdziwych uczuć to terapia, lepsza niż sztuczny uśmiech.', title_pt = 'Registo das emoções 📝', body_pt = 'Alguém lhe disse "estás em casa, cansas-te de quê"? Abra já o Diário de Humor e despeje no ecrã toda a sua irritação. Em vez de sorrir à força, escrever o que sente de verdade é terapia.', title_sv = 'Skriv ner känslorna 📝', body_sv = 'Sa någon ”Du är ju hemma, vad är du trött av”? Öppna Humördagboken direkt och låt all irritation flöda genom fingrarna ut på skärmen. Att skriva ner dina verkliga känslor är terapi, bättre än ett tillgjort leende.', title_vi = 'Ghi lại cảm xúc 📝', body_vi = 'Có ai đó nói với mẹ: "Ở nhà suốt thì mệt gì chứ"? Hãy mở ngay Nhật ký tâm trạng và trút hết bực bội lên màn hình qua đầu ngón tay. Viết ra cảm xúc thật của mình là một liệu pháp, tốt hơn nhiều so với nụ cười gượng gạo.', title_zh = '情绪记录 📝', body_zh = '有人对你说“你天天在家，有什么好累的”？马上打开心情日记，用手指把所有的火气都倾倒在屏幕上。与其强颜欢笑，不如写下真实的感受，这本身就是一种疗愈。' WHERE id = 'df1cf1ea-2772-44a6-8cb7-33857989fedf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El encanto mágico de la caja 📦', body_es = 'Le compraste un juguete caro y con sonidos, pero lleva 1 hora jugando con la caja. El cerebro infantil no prefiere estructuras ya hechas, sino objetos sencillos con los que pueda imaginar. Observa y aprende.', title_fr = 'La magie du carton 📦', body_fr = 'Vous lui avez acheté un jouet cher et sonore, mais il joue depuis 1 heure avec le carton du jouet. Le cerveau d''un enfant n''aime pas les choses toutes faites, mais les objets simples qui laissent place à l''imagination. Observez et apprenez.', title_hi = 'डिब्बे का जादुई आकर्षण 📦', body_hi = 'आपने उसके लिए इतना महँगा, आवाज़ वाला खिलौना खरीदा, पर वह 1 घंटे से उसके डिब्बे से खेल रहा है। बच्चे का दिमाग बनी-बनाई चीज़ें नहीं, बल्कि ऐसी सादी चीज़ें पसंद करता है जिनसे वह कल्पना कर सके। देखिए और सीखिए।', title_id = 'Pesona ajaib sebuah kardus 📦', body_id = 'Anda membelikannya mainan mahal yang berbunyi, tapi ia sudah satu jam bermain dengan kardusnya. Otak anak tidak menyukai struktur yang sudah jadi, melainkan benda sederhana yang bisa ia khayalkan. Amati dan belajarlah.', title_ja = '箱のふしぎな魅力 📦', body_ja = '高くて音の出るおもちゃを買ったのに、1時間もおもちゃの箱で遊んでいる？子どもの脳は、できあがったものより、自由に想像をふくらませられるシンプルなものが好きなんです。見守って、学んでみましょう。', title_ko = '상자의 마법 같은 매력 📦', body_ko = '비싸고 소리 나는 장난감을 사 줬는데 한 시간째 장난감 상자만 가지고 노나요? 아이의 뇌는 완성된 구조보다 상상할 수 있는 단순한 물건을 좋아해요. 지켜보며 배워 보세요.', title_nl = 'De magische aantrekkingskracht van de doos 📦', body_nl = 'Je kocht zo''n duur speeltje met geluid, maar hij speelt al een uur met de doos. Een kinderbrein houdt niet van kant-en-klare dingen, maar van simpele voorwerpen waarbij hij kan fantaseren. Kijk en leer.', title_pl = 'Magiczny urok pudełka 📦', body_pl = 'Kupiłaś mu drogą, grającą zabawkę, a on od godziny bawi się pudełkiem po niej. Dziecięcy mózg nie kocha gotowych konstrukcji, tylko proste przedmioty, które pobudzają wyobraźnię. Obserwuj i ucz się.', title_pt = 'O encanto mágico da caixa 📦', body_pt = 'Comprou-lhe um brinquedo caro e cheio de sons, mas há 1 hora que ele brinca com a caixa. O cérebro da criança não gosta de estruturas prontas, gosta de objetos simples com que possa imaginar. Observe e aprenda.', title_sv = 'Kartongens magiska dragningskraft 📦', body_sv = 'Du köpte en dyr leksak med ljud, men barnet har lekt med kartongen den kom i i en timme. Barnets hjärna gillar inte färdiga strukturer, utan enkla saker att fantisera kring. Titta och lär.', title_vi = 'Sức hút kỳ diệu của chiếc hộp 📦', body_vi = 'Mẹ mua cho bé món đồ chơi đắt tiền, phát ra đủ thứ âm thanh, vậy mà bé lại chơi với chiếc hộp đựng nó suốt 1 tiếng. Não bộ trẻ không thích những cấu trúc làm sẵn, mà thích những đồ vật đơn giản để tha hồ tưởng tượng. Hãy quan sát và học hỏi.', title_zh = '纸箱的神奇魅力 📦', body_zh = '你给宝宝买了那么贵、会发声的玩具，可宝宝却抱着玩具的纸箱玩了1个小时。孩子的大脑喜欢的不是现成的结构，而是能让它尽情想象的简单物件。观察，也学习。' WHERE id = '33979ce6-ea09-4adc-ab85-0cf386a73156' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ruidos blancos naturales 🤫', body_es = 'Al quedarse dormido está más sensible. Para neutralizar los ruidos de la calle, activa el sonido de fondo del Medidor de sonido y llena la habitación de una calma duradera.', title_fr = 'Bruits blancs naturels 🤫', body_fr = 'Au moment de l''endormissement, il est plus sensible. Pour neutraliser les bruits de la rue, activez le bruit de fond du Sonomètre dans la chambre et installez un calme durable.', title_hi = 'प्राकृतिक व्हाइट नॉइज़ 🤫', body_hi = 'सोते समय वह ज़्यादा संवेदनशील होता है। बाहर से आने वाली आवाज़ों को बेअसर करने के लिए कमरे में साउंड मीटर की बैकग्राउंड आवाज़ चालू कीजिए और कमरे में स्थायी सुकून लाइए।', title_id = 'Suara putih alami 🤫', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Untuk meredam suara dari jalan, aktifkan suara latar Pengukur Suara di kamar dan hadirkan ketenangan yang bertahan lama.', title_ja = '自然なホワイトノイズ 🤫', body_ja = '眠りに落ちるときは、とても敏感になります。外からの音をやわらげるために、「サウンドメーター」の背景音をオンにして、部屋に落ち着いた安らぎを届けましょう。', title_ko = '자연스러운 백색소음 🤫', body_ko = '잠이 드는 순간에는 예민함이 커져요. 바깥 소리를 덮을 수 있게 소음 측정기의 배경 소리를 켜고 방에 오래가는 평온을 만들어 주세요.', title_nl = 'Natuurlijke witte ruis 🤫', body_nl = 'Tijdens het inslapen is hij extra gevoelig. Zet het achtergrondgeluid van de Geluidsmeter aan om straatgeluiden te neutraliseren en breng blijvende rust in de kamer.', title_pl = 'Naturalny biały szum 🤫', body_pl = 'W chwili zasypiania wrażliwość rośnie. Aby wyciszyć dźwięki z ulicy, włącz w pokoju dźwięk tła w Mierniku dźwięku i zapewnij trwały spokój.', title_pt = 'Ruídos brancos naturais 🤫', body_pt = 'Na hora de adormecer, a sensibilidade aumenta. Para neutralizar os sons da rua, ative o som de fundo do Medidor de Som no quarto e traga-lhe uma calma duradoura.', title_sv = 'Naturligt vitt brus 🤫', body_sv = 'Känsligheten ökar precis när barnet somnar. Sätt på bakgrundsljudet i Ljudmätaren för att dämpa ljuden från gatan och ge rummet ett varaktigt lugn.', title_vi = 'Tiếng ồn trắng tự nhiên 🤫', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc bé nhạy cảm nhất. Để át đi tiếng ồn từ ngoài đường, hãy bật âm thanh nền của Đo âm thanh trong phòng, mang lại sự yên bình lâu dài.', title_zh = '天然白噪音 🤫', body_zh = '入睡的那一刻是最敏感的时候。打开分贝仪的背景音，盖过街上传来的声音，给房间带来持久的宁静。' WHERE id = '5b89452a-e411-4130-87b7-6e1e33b0701e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Llanto de mentira 🎭', body_es = '¿Llora de mentira, sin lágrimas y con la voz temblorosa, para conseguir lo que quiere? Está aprendiendo a manipularte. Aguántate la risa, pero tampoco cedas. Que tus límites sean claros.', title_fr = 'Les fausses larmes 🎭', body_fr = 'Il fait semblant de pleurer, sans larmes, la voix tremblante, pour obtenir ce qu''il veut ? Il apprend à vous manipuler. Retenez-vous de rire, mais ne cédez pas. Gardez des limites claires.', title_hi = 'झूठमूठ का रोना 🎭', body_hi = 'जो चाहिए वह पाने के लिए बिना आँसू बहाए, आवाज़ काँपाकर झूठमूठ रोता है? वह आपको मनाने की तरकीबें सीख रहा है। हँसी रोकिए, पर झुकिए भी मत। आपकी सीमाएँ साफ़ हों।', title_id = 'Pura-pura menangis 🎭', body_id = 'Ia pura-pura menangis dengan suara bergetar tanpa air mata demi mendapatkan yang ia mau? Ia sedang belajar memanipulasi Anda. Tahan tawa Anda, tapi jangan mengalah. Buat batasan Anda jelas.', title_ja = 'うそ泣き 🎭', body_ja = 'ほしいものを手に入れるために、涙も出さずに声をふるわせてうそ泣き？あなたを動かす方法を学んでいます。笑いをこらえつつ、ゆずらないで。ルールははっきりさせておきましょう。', title_ko = '가짜 울음 🎭', body_ko = '원하는 걸 얻으려고 눈물 없이 목소리를 떨며 우는 척하나요? 엄마를 조종하는 법을 배우는 중이에요. 웃음을 꾹 참되 물러서지는 마세요. 경계는 분명하게요.', title_nl = 'Nephuilen 🎭', body_nl = 'Doet hij alsof hij huilt, met een trillend stemmetje maar zonder tranen, om zijn zin te krijgen? Hij leert je te manipuleren. Houd je lachen in, maar geef ook niet toe. Wees duidelijk in je grenzen.', title_pl = 'Udawany płacz 🎭', body_pl = 'Płacze na niby, bez łez, drżącym głosikiem, by dostać to, czego chce? Uczy się tobą manipulować. Powstrzymaj śmiech, ale też nie ustępuj. Niech twoje granice będą jasne.', title_pt = 'Choro a fingir 🎭', body_pt = 'Para conseguir o que quer, finge chorar, sem lágrimas, com a voz a tremer? Está a aprender a manipulá-la. Contenha o riso, mas também não ceda. Os seus limites devem ser claros.', title_sv = 'Låtsasgråt 🎭', body_sv = 'Låtsasgråter barnet med darrande röst, utan en enda tår, för att få som det vill? Barnet lär sig att manipulera dig. Håll dig för skratt, men ge inte efter. Var tydlig med dina gränser.', title_vi = 'Khóc giả 🎭', body_vi = 'Bé giả vờ khóc, giọng run run mà chẳng có giọt nước mắt nào để đạt được điều mình muốn? Bé đang học cách "điều khiển" mẹ. Hãy cố nhịn cười, nhưng cũng đừng nhượng bộ. Giới hạn của mẹ cần thật rõ ràng.', title_zh = '假哭 🎭', body_zh = '为了得到想要的东西，没掉一滴眼泪，只是颤着声音假哭？宝宝正在学着“操控”你。忍住别笑，但也别让步。你的边界要清清楚楚。' WHERE id = 'a09d0a7b-0632-4bcf-8833-28f5ef0f9d93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un «te quiero» por sorpresa 💖', body_es = '¿Jugando en medio de la habitación te ha mirado de repente y te ha dicho «te quieeero mucho»? ¡Vale la pena por todas las noches sin dormir y todo el cansancio! Disfruta de la paz profunda y única de este momento.', title_fr = 'Un « Je t''aime » soudain 💖', body_fr = 'En jouant au milieu de la pièce, il vous a soudain regardée et dit « Je t''aiiime très fort » ? Cela vaut toutes les nuits blanches et toute la fatigue ! Savourez la paix profonde et unique de ce moment.', title_hi = 'अचानक ‘आई लव यू’ 💖', body_hi = 'कमरे के बीच खेलते-खेलते अचानक आपकी ओर देखकर बोला, ‘मैं तुमसे बहुत-बहुत प्यार करता हूँ’? सारी जागी रातें, सारी थकान इसके लायक थी! इस पल के गहरे, अनोखे सुकून का आनंद लीजिए।', title_id = '''Aku sayang Mama'' yang tiba-tiba 💖', body_id = 'Sedang bermain di tengah kamar, tiba-tiba ia menatap Anda dan berkata ''Aku sayaaang banget sama Mama''? Itu sepadan dengan semua malam tanpa tidur dan rasa lelah! Nikmati ketenangan yang dalam dan istimewa dari momen ini.', title_ja = '不意打ちの「大好き」 💖', body_ja = '部屋のまんなかで遊んでいたのに、ふとあなたを見て「だーいすき」と言ってくれた？眠れない夜も疲れも、すべて報われますね！この瞬間がくれる深くて特別な幸せをかみしめて。', title_ko = '갑작스러운 ''사랑해'' 💖', body_ko = '방 한가운데서 놀다가 갑자기 엄마를 보며 ''엄마 너~무 사랑해''라고 했나요? 잠 못 잔 밤과 피로가 모두 보상받는 순간이에요! 이 순간의 깊고 특별한 평온을 마음껏 누리세요.', title_nl = 'Een onverwacht ''Ik hou van je'' 💖', body_nl = 'Keek hij je midden in het spelen ineens aan en zei hij ''Ik hou heeeel veel van je''? Dat is alle slapeloze nachten en vermoeidheid waard! Geniet van de diepe, unieke rust die dit moment je geeft.', title_pl = 'Nagłe „Kocham cię” 💖', body_pl = 'Bawiąc się na środku pokoju, nagle spojrzał na ciebie i powiedział „Baaardzo cię kocham”? To jest warte wszystkich nieprzespanych nocy i zmęczenia! Delektuj się tym głębokim, wyjątkowym spokojem tej chwili.', title_pt = 'Um "Amo-te" de repente 💖', body_pt = 'A brincar no meio do quarto, olhou de repente para si e disse "Amo-te muuuito"? Valeu todas as noites sem dormir e todo o cansaço! Saboreie a calma profunda e única deste momento.', title_sv = 'Ett plötsligt ”Jag älskar dig” 💖', body_sv = 'Mitt i leken tittade barnet plötsligt på dig och sa ”Jag ä-älskar dig”? Det var värt alla sömnlösa nätter och all trötthet! Njut av det djupa, unika lugn som stunden ger.', title_vi = '"Con yêu mẹ" bất ngờ 💖', body_vi = 'Đang chơi giữa phòng, bé bỗng nhìn mẹ và nói "Con yêuuu mẹ lắm"? Thật xứng đáng với mọi đêm mất ngủ và mệt mỏi! Hãy tận hưởng cảm giác bình yên sâu lắng, đặc biệt mà khoảnh khắc này mang lại.', title_zh = '突然的“我爱你” 💖', body_zh = '在房间中间玩着玩着，突然看着你说“我好～爱好～爱你”？所有不眠的夜晚、所有的疲惫都值了！好好享受这一刻带来的那份深深的、独一无二的安宁。' WHERE id = '20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile loco de papá 🕺', body_es = 'La agresividad que estalla al atardecer solo la puede resolver papá. Que pongan la música a todo volumen y bailen saltando juntos por la habitación. Y tú mira esa energía alegre desde fuera, con orgullo.', title_fr = 'La danse folle de papa 🕺', body_fr = 'Seul papa peut venir à bout de l''agressivité de fin de journée. Qu''ils mettent la musique à fond et dansent en sautant dans la pièce. Et vous, regardez fièrement cette joyeuse énergie de loin.', title_hi = 'पापा का धमाकेदार डांस 🕺', body_hi = 'शाम को फूटने वाला गुस्सा सिर्फ़ पापा ही संभाल सकते हैं। वे पूरी आवाज़ में गाना चलाकर बच्चे के साथ कमरे में उछल-उछलकर नाचें। और आप इस खुशनुमा ऊर्जा को दूर से गर्व से देखिए।', title_id = 'Joget heboh Ayah 🕺', body_id = 'Ledakan emosi menjelang malam hanya bisa diatasi Ayah. Biarkan mereka memutar musik sekencang-kencangnya dan menari sambil melompat-lompat di kamar. Kamu cukup menyaksikan energi ceria ini dari samping dengan bangga.', title_ja = 'パパのクレイジーダンス 🕺', body_ja = '夕方に爆発するイライラは、パパにしか鎮められません。音楽を大音量にして、子どもと部屋でジャンプしながら踊ってもらいましょう。あなたはその楽しいエネルギーを、そばで誇らしく見守って。', title_ko = '아빠의 신나는 막춤 🕺', body_ko = '저녁에 터지는 짜증은 아빠만 해결할 수 있어요. 음악을 크게 틀고 아이와 함께 방에서 뛰며 춤추게 하세요. 엄마는 그 즐거운 에너지를 옆에서 뿌듯하게 지켜보세요.', title_nl = 'Papa''s wilde dans 🕺', body_nl = 'Alleen papa kan de agressie van eind van de middag oplossen. Laat ze de muziek keihard zetten en samen springend door de kamer dansen. En jij kijkt trots van een afstand naar al die vrolijke energie.', title_pl = 'Szalony taniec taty 🕺', body_pl = 'Wieczorny wybuch złości może opanować tylko tata. Niech puszczą muzykę na cały regulator i razem skaczą i tańczą po pokoju. A ty z dumą obserwuj tę radosną energię z boku.', title_pt = 'A dança maluca do pai 🕺', body_pt = 'A agressividade que surge ao fim da tarde só o pai consegue resolver. Que ponham a música bem alto e dancem aos saltos pelo quarto. E a mãe observa esta energia alegre à distância, com orgulho.', title_sv = 'Pappas galna dans 🕺', body_sv = 'Den ilska som bryter ut framåt kvällen kan bara pappa lösa. Låt dem skruva upp musiken på högsta volym och hoppa och dansa tillsammans i rummet. Och du tittar stolt på den glada energin från sidan.', title_vi = 'Điệu nhảy điên rồ của bố 🕺', body_vi = 'Cơn bùng nổ lúc chiều tối chỉ có bố mới giải quyết được. Hãy để hai bố con bật nhạc thật to và cùng nhảy nhót khắp phòng. Còn mẹ, hãy tự hào ngắm nhìn nguồn năng lượng vui vẻ này từ xa.', title_zh = '爸爸的疯狂舞蹈 🕺', body_zh = '傍晚爆发的小脾气，只有爸爸能搞定。让他们把音乐开到最大，一起在房间里蹦蹦跳跳地跳舞。你就在一旁，骄傲地看着这份欢乐的能量。' WHERE id = '22b5d836-6305-422c-8cf7-c30a523392f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos solo para ti ☕', body_es = 'Mientras está entretenido con los dibujos, ¡no corras a vaciar el lavavajillas! Túmbate en el sofá. Tómate por fin ese café calentito y durante 10 minutos deja el papel de madre y sé simplemente tú.', title_fr = '10 minutes rien que pour vous ☕', body_fr = 'Pendant qu''il est absorbé par son dessin animé, ne courez pas remplir le lave-vaisselle ! Allongez-vous sur le canapé. Buvez enfin ce café bien chaud et, pendant 10 minutes, quittez votre rôle de maman pour être simplement vous-même.', title_hi = 'सिर्फ़ आपके अपने 10 मिनट ☕', body_hi = 'जब वह कार्टून में खोया है, तब डिशवॉशर खाली करने मत दौड़िए! सोफ़े पर लेट जाइए। वह कॉफ़ी आखिरकार गरम-गरम पीजिए और 10 मिनट के लिए माँ की भूमिका से बाहर आकर बस खुद बनिए।', title_id = '10 menit hanya untuk Anda ☕', body_id = 'Selagi ia asyik menonton kartun, jangan buru-buru mengisi mesin cuci piring! Berbaringlah di sofa. Akhirnya minum kopi itu selagi panas, dan selama 10 menit keluarlah dari peran ibu untuk menjadi diri Anda sendiri.', title_ja = '自分だけの10分 ☕', body_ja = 'アニメに夢中になっているすきに、食洗機を片づけに走らないで！ソファに横になりましょう。コーヒーを今度こそ温かいうちに飲んで、10分間だけママをお休みして、あなた自身に戻りましょう。', title_ko = '오롯이 나만의 10분 ☕', body_ko = '아이가 만화에 빠져 있는 동안 식기세척기 정리하러 달려가지 마세요! 소파에 누우세요. 커피를 드디어 따뜻할 때 마시고, 10분 동안은 엄마 역할에서 벗어나 그냥 나 자신이 되어 보세요.', title_nl = '10 minuten alleen voor jou ☕', body_nl = 'Is hij helemaal opgegaan in die tekenfilm? Ren dan niet naar de vaatwasser! Ga op de bank liggen. Drink die koffie eindelijk eens warm en wees 10 minuten even geen mama, maar gewoon jezelf.', title_pl = '10 minut tylko dla ciebie ☕', body_pl = 'Gdy jest pochłonięty bajką, nie biegnij ładować zmywarki! Połóż się na kanapie. Wypij wreszcie gorącą kawę i przez 10 minut wyjdź z roli mamy, po prostu bądź sobą.', title_pt = '10 minutos só para si ☕', body_pt = 'Enquanto ele está entretido com os desenhos animados, não corra a arrumar a máquina da loiça! Deite-se no sofá. Beba finalmente esse café quente e, durante 10 minutos, deixe de ser mãe e seja apenas você.', title_sv = '10 minuter bara för dig ☕', body_sv = 'Spring inte iväg och tömma diskmaskinen medan barnet är uppslukat av tecknade filmen! Lägg dig i soffan. Drick äntligen kaffet medan det är varmt och kliv ur mammarollen i 10 minuter, var bara dig själv.', title_vi = '10 phút chỉ dành cho mẹ ☕', body_vi = 'Khi bé đang mải xem phim hoạt hình, đừng vội chạy đi xếp máy rửa bát! Hãy nằm xuống sofa. Cuối cùng cũng được uống cốc cà phê khi còn nóng, và trong 10 phút, hãy tạm gác vai trò làm mẹ để chỉ là chính mình.', title_zh = '只属于你的10分钟 ☕', body_zh = '宝宝看动画片看得入迷时，别急着跑去收拾洗碗机！去沙发上躺一会儿。终于可以趁热喝完那杯咖啡，在这10分钟里放下妈妈的角色，只做你自己。' WHERE id = '909bc50f-85b7-40ab-a524-0abbcb0fac9f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha vuelto a ver ese trocito de zanahoria en la sopa y se niega a comer? Hacer puré las verduras con ayuda del Plan de alimentación y esconderlas en las albóndigas es el truco de madre más antiguo y útil. ¡Pruébalo!', body_fr = 'Il a encore vu ce petit morceau de carotte dans la soupe et refuse de manger ? Avec le Plan de nutrition, réduire les légumes en purée et les cacher dans les boulettes, c''est la plus vieille et la plus utile des astuces de maman. Essayez !', body_hi = 'सूप में गाजर का वह छोटा टुकड़ा फिर देखकर खाने से मना कर दिया? फ़ीडिंग प्लान की मदद से सब्ज़ियों की प्यूरी बनाकर कटलेट में छिपाना माँ की सबसे पुरानी और काम की तरकीब है। आज़माइए!', body_id = 'Ia melihat potongan kecil wortel di sup lagi dan menolak makan? Menghaluskan sayur lalu menyembunyikannya di dalam perkedel dengan bantuan Rencana Nutrisi adalah trik ibu yang paling tua dan paling berguna. Coba terapkan!', body_ja = 'スープの中の小さなにんじんをまた見つけて、食べるのをやめてしまった？「栄養管理ツール」を使って、野菜をピューレにしてハンバーグに隠すのは、ママのいちばん昔からある便利な技。試してみて！', body_ko = '수프 속 작은 당근 조각을 또 보고 안 먹겠다고 하나요? 식단 계획을 활용해 채소를 퓌레로 만들어 동그랑땡 속에 숨기는 건 엄마들의 가장 오래되고 유용한 비법이에요. 해 보세요!', body_nl = 'Zag hij dat kleine stukje wortel in de soep weer en wil hij niet meer eten? Groenten pureren en in gehaktballetjes verstoppen met het Voedingsplan is de oudste en handigste moedertruc. Probeer het!', body_pl = 'Znowu zobaczył w zupie ten malutki kawałek marchewki i odmówił jedzenia? Miksowanie warzyw i ukrywanie ich w kotlecikach dzięki planowi karmienia to najstarsza i najskuteczniejsza sztuczka mam. Wypróbuj!', body_pt = 'Viu outra vez aquele pedacinho de cenoura na sopa e recusou comer? Com o Registo de Alimentação, fazer puré dos legumes e escondê-los nos croquetes é o truque de mãe mais antigo e útil. Experimente!', body_sv = 'Såg barnet den lilla morotsbiten i soppan igen och vägrade äta? Att mosa grönsaker och gömma dem i biffar med hjälp av matplanen är mammans äldsta och mest användbara knep. Testa!', body_vi = 'Bé lại thấy miếng cà rốt nhỏ trong món súp và không chịu ăn? Xay nhuyễn rau rồi giấu vào thịt viên nhờ Kế hoạch dinh dưỡng là mẹo lâu đời và hữu ích nhất của các mẹ. Thử ngay nhé!', body_zh = '又在汤里看到那一小块胡萝卜，就不肯吃了？借助喂养计划把蔬菜打成泥，藏进肉饼里，这是妈妈们最古老也最管用的小妙招。试试吧！' WHERE id = '3deb7e49-2093-4c39-a51d-8dd6fd44d138' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño doctor te examina 🩺', title_fr = 'Le petit docteur vous examine 🩺', title_hi = 'छोटा डॉक्टर आपकी जाँच कर रहा है 🩺', title_id = 'Dokter kecil sedang memeriksa Anda 🩺', title_ja = '小さなお医者さんの診察です 🩺', title_ko = '꼬마 의사 선생님이 진찰 중 🩺', title_nl = 'De kleine dokter onderzoekt je 🩺', title_pl = 'Mały doktor cię bada 🩺', title_pt = 'O pequeno médico está a examiná-la 🩺', title_sv = 'Den lilla doktorn undersöker dig 🩺', title_vi = 'Bác sĩ nhí đang khám cho mẹ 🩺', title_zh = '小医生给你做检查 🩺' WHERE id = '9dd6923c-7dc5-4341-8507-b21e0f3c9ee4' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Límite de ruido 🌙', body_es = 'Por fin se ha dormido. Ahora hasta el ruido más pequeño de la casa te molesta. Baja las luces, apaga la tele y disfruta en medio de la oscuridad de ese silencio tan raro y tan dulce.', title_fr = 'La limite des bruits 🌙', body_fr = 'Il dort enfin. Maintenant, le moindre bruit de la maison vous dérange. Baissez les lumières, éteignez la télé et savourez dans l''obscurité la douceur de ce silence si rare.', title_hi = 'आवाज़ों की सीमा 🌙', body_hi = 'आखिरकार वह सो गया। अब घर की सबसे छोटी आवाज़ भी आपको परेशान करती है। रोशनी धीमी कीजिए, टीवी बंद कीजिए और अँधेरे के बीच उस दुर्लभ खामोशी की मीठी राहत का आनंद लीजिए।', title_id = 'Batas suara 🌙', body_id = 'Akhirnya ia tertidur. Kini suara sekecil apa pun di rumah membuat Anda gelisah. Redupkan lampu, matikan TV, dan nikmati manisnya keheningan langka di tengah gelap.', title_ja = '音の限界 🌙', body_ja = 'やっと眠ってくれました。今は家の中の小さな音さえ気になりますね。明かりを落とし、テレビを消して、暗やみの中でめったにない静けさをたっぷり味わいましょう。', title_ko = '소리의 한계 🌙', body_ko = '드디어 잠들었어요. 이제 집 안의 아주 작은 소리도 신경 쓰이죠. 불을 낮추고 TV를 끄고, 어둠 속에서 귀한 고요의 달콤함을 누리세요.', title_nl = 'De grens van geluid 🌙', body_nl = 'Hij slaapt eindelijk. Nu stoort zelfs het kleinste geluid in huis je. Dim de lichten, zet de tv uit en geniet midden in het donker van die zeldzame, heerlijke stilte.', title_pl = 'Granica dźwięków 🌙', body_pl = 'W końcu zasnął. Teraz przeszkadza ci nawet najcichszy dźwięk w domu. Przygaś światła, wyłącz telewizor i delektuj się słodyczą tej rzadkiej ciszy w ciemności.', title_pt = 'O limite dos sons 🌙', body_pt = 'Finalmente adormeceu. Agora até o mais pequeno som da casa a incomoda. Baixe as luzes, desligue a televisão e saboreie, no meio do escuro, a doçura deste silêncio raro.', title_sv = 'Ljudens gräns 🌙', body_sv = 'Äntligen har barnet somnat. Nu stör till och med det minsta ljud i hemmet dig. Dämpa ljuset, stäng av tv:n och njut av den sällsynta, ljuva tystnaden mitt i mörkret.', title_vi = 'Giới hạn của âm thanh 🌙', body_vi = 'Cuối cùng bé cũng đã ngủ. Giờ đây ngay cả tiếng động nhỏ nhất trong nhà cũng làm mẹ khó chịu. Hãy giảm đèn, tắt tivi và tận hưởng vị ngọt ngào của sự tĩnh lặng hiếm hoi giữa bóng tối.', title_zh = '声音的界限 🌙', body_zh = '宝宝终于睡着了。现在家里哪怕一点点声音都让你心烦。把灯光调暗，关掉电视，在黑暗中好好享受这难得的、甜甜的安静。' WHERE id = 'ebf71c8a-d8a3-4875-8021-e3145bf8ae06' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gateo y carreras con un objetivo 🐢', body_es = 'Ya no le basta con andar: corre rápido para esconderse de ti y asoma por detrás de las puertas. Quita los obstáculos de la habitación y únete tú también a este pilla-pilla con la energía de una niña grande.', title_fr = 'Ramper et courir avec un but 🐢', body_fr = 'Marcher ne lui suffit plus : il court vite se cacher et vous observe derrière les portes. Retirez les obstacles de la pièce et rejoignez ce jeu de chat avec l''énergie d''une grande enfant.', title_hi = 'मकसद भरा रेंगना और दौड़ना 🐢', body_hi = 'अब उसे सिर्फ़ चलना काफ़ी नहीं, तेज़ी से दौड़कर आपसे छिपता है, दरवाज़ों के पीछे से झाँकता है। कमरे से रुकावटें हटाइए और इस पकड़म-पकड़ाई में आप भी एक बड़े बच्चे की ऊर्जा के साथ शामिल हो जाइए।', title_id = 'Merangkak dan berlari dengan tujuan 🐢', body_id = 'Ia tak lagi puas hanya berjalan, ia berlari cepat untuk bersembunyi dari Anda dan mengintip dari balik pintu. Singkirkan rintangan di kamar dan ikutlah bermain kejar-kejaran dengan energi seperti anak besar.', title_ja = '目的のあるハイハイと走り 🐢', body_ja = 'もう歩くだけでは物足りず、すばやく走ってあなたから隠れ、ドアのかげからのぞいています。部屋の障害物を片づけて、この追いかけっこに、あなたも大きな子どもになったつもりで参加しましょう。', title_ko = '목표가 있는 기어가기와 달리기 🐢', body_ko = '이제 걷는 걸로는 부족해 재빨리 뛰어가 숨고 문 뒤에서 엿보나요? 방의 장애물을 치우고 엄마도 큰 아이처럼 이 술래잡기에 함께하세요.', title_nl = 'Doelgericht kruipen en rennen 🐢', body_nl = 'Lopen is niet meer genoeg: hij rent snel weg om zich voor je te verstoppen en gluurt achter deuren vandaan. Haal obstakels uit de kamer en doe zelf ook mee aan dit tikkertje, met de energie van een groot kind.', title_pl = 'Celowe raczkowanie i bieganie 🐢', body_pl = 'Już nie wystarcza mu chodzenie, szybko ucieka i chowa się przed tobą, zerka zza drzwi. Usuń przeszkody z pokoju i dołącz do tej zabawy w berka z energią dużego dziecka.', title_pt = 'Gatinhar e correr com um objetivo 🐢', body_pt = 'Já não lhe chega andar: corre a toda a velocidade para se esconder e espreita por trás das portas. Tire os obstáculos do quarto e entre também nesta apanhada com uma grande energia de criança.', title_sv = 'Målmedveten krypning och spring 🐢', body_sv = 'Barnet nöjer sig inte längre med att gå, det springer snabbt och gömmer sig för dig och kikar fram bakom dörrarna. Plocka undan hinder i rummet och häng med i kull-leken med stor barnslig energi.', title_vi = 'Bò và chạy có chủ đích 🐢', body_vi = 'Bé không còn chỉ chịu đi bộ nữa, mà chạy thật nhanh để trốn mẹ, ló đầu ra từ sau cánh cửa. Hãy dọn bớt chướng ngại vật trong phòng và tham gia trò đuổi bắt này với năng lượng của một "đứa trẻ lớn".', title_zh = '有目标的爬行和奔跑 🐢', body_zh = '已经不满足于走路了，飞快地跑着躲开你，从门后偷看。把房间里的障碍物收一收，带着大孩子般的劲头，你也加入这场追逐游戏吧。' WHERE id = '19419b9a-b627-43ae-9610-e43b875264b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, respuesta real 🤖', body_es = '¿Le ha aparecido una costumbre rara (por ejemplo, morderse las uñas) y los foros de internet te han asustado? Para. Pregunta a Anacan AI la verdadera causa, avalada por pediatras, y tranquilízate.', title_fr = 'Intelligence artificielle, vraie réponse 🤖', body_fr = 'Votre enfant a pris une drôle d''habitude (se ronger les ongles, par exemple) et les forums vous ont fait peur ? Stop. Demandez à Anacan AI la vraie cause, validée par des pédiatres, et rassurez-vous.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, असली जवाब 🤖', body_hi = 'बच्चे में कोई अजीब आदत आ गई है (जैसे नाखून चबाना) और इंटरनेट के फ़ोरम ने आपको डरा दिया? रुकिए। Anacan AI से इसकी बाल रोग विशेषज्ञ द्वारा पुष्ट असली वजह पूछिए और शांत हो जाइए।', title_id = 'Kecerdasan buatan, jawaban nyata 🤖', body_id = 'Anak Anda punya kebiasaan aneh (misalnya menggigit kuku) dan forum di internet membuat Anda takut? Tunggu dulu. Tanyakan pada Anacan AI penyebab sebenarnya yang disetujui dokter anak, lalu tenangkan diri.', title_ja = 'AI、リアルな答え 🤖', body_ja = 'お子さんに変なくせ（たとえば爪かみ）が出てきて、ネットの掲示板を見て怖くなりましたか？ちょっと待って。Anacan AIに、小児科医監修の本当の理由をたずねて、安心しましょう。', title_ko = '인공지능, 진짜 답 🤖', body_ko = '아이에게 손톱 물어뜯기 같은 이상한 습관이 생겼는데 인터넷 게시판 글에 겁이 났나요? 멈추세요. Anacan AI에게 소아과 의사가 확인한 진짜 이유를 물어보고 마음을 놓으세요.', title_nl = 'Kunstmatige intelligentie, echt antwoord 🤖', body_nl = 'Heeft je kind een vreemde gewoonte opgepikt (zoals nagelbijten) en word je bang van internetfora? Stop. Vraag Anacan AI naar de echte, door kinderartsen bevestigde oorzaak en kom tot rust.', title_pl = 'Sztuczna inteligencja, prawdziwa odpowiedź 🤖', body_pl = 'U dziecka pojawił się dziwny nawyk (np. obgryzanie paznokci), a fora internetowe cię przestraszyły? Stop. Zapytaj Anacan AI o prawdziwą, potwierdzoną przez pediatrów przyczynę i uspokój się.', title_pt = 'Inteligência artificial, resposta real 🤖', body_pt = 'O seu filho ganhou um hábito estranho (por exemplo, roer as unhas) e os fóruns da internet assustaram-na? Pare. Pergunte ao Anacan AI a verdadeira causa, validada por pediatras, e fique tranquila.', title_sv = 'Artificiell intelligens, riktiga svar 🤖', body_sv = 'Har barnet fått en konstig vana (till exempel att bita på naglarna) och forumen på nätet skrämde dig? Stopp. Fråga Anacan AI om den verkliga, barnläkargodkända orsaken och lugna dig.', title_vi = 'Trí tuệ nhân tạo, câu trả lời thật 🤖', body_vi = 'Bé có một thói quen lạ (ví dụ như cắn móng tay) và các diễn đàn trên mạng làm mẹ hoảng sợ? Dừng lại. Hãy hỏi Anacan AI nguyên nhân thật sự đã được bác sĩ nhi khoa xác nhận và yên tâm hơn.', title_zh = '人工智能，真实答案 🤖', body_zh = '宝宝养成了一个奇怪的习惯（比如咬指甲），网上的论坛把你吓坏了？停一下。问问Anacan AI，了解经儿科医生认可的真正原因，让自己安心下来。' WHERE id = 'c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libertad en el parque 🌳', body_es = 'Las cuatro paredes le ponen agresivo. Llévale al parque y deja que se manche de arena, que se caiga corriendo, que recoja piedras. Esta libertad en la naturaleza es la mejor medicina para el desarrollo de su cerebro.', title_fr = 'Liberté au parc 🌳', body_fr = 'Les quatre murs le rendent agressif. Emmenez-le au parc : qu''il se roule dans le sable, tombe en courant, ramasse des cailloux. Cette liberté dans la nature est le meilleur remède pour le développement de son cerveau.', title_hi = 'पार्क में आज़ादी 🌳', body_hi = 'चार दीवारें उसे चिड़चिड़ा बना देती हैं। उसे पार्क ले जाइए, उसे रेत में सनने दीजिए, दौड़ते-दौड़ते गिरने दीजिए, पत्थर इकट्ठा करने दीजिए। प्रकृति की यह आज़ादी उसके दिमाग के लिए सबसे असरदार विकास की दवा है।', title_id = 'Bebas di taman 🌳', body_id = 'Empat dinding rumah membuatnya gelisah. Ajak ia ke taman, biarkan ia berlumur pasir, jatuh saat berlari, dan mengumpulkan batu. Kebebasan di alam ini adalah obat perkembangan terbaik untuk otaknya.', title_ja = '公園での自由 🌳', body_ja = '4つの壁に囲まれていると、イライラがつのります。公園に連れ出して、砂まみれになったり、走って転んだり、石を集めたりさせてあげましょう。自然の中の自由は、脳にいちばんよく効く成長の薬です。', title_ko = '공원에서의 자유 🌳', body_ko = '네 벽 안에 있으니 공격적으로 변하나요? 공원에 데려가 모래투성이가 되고, 뛰다 넘어지고, 돌을 줍게 해 주세요. 자연 속의 이런 자유가 뇌 발달에 가장 좋은 약이에요.', title_nl = 'Vrijheid in het park 🌳', body_nl = 'Vier muren maken hem agressief. Ga met hem naar het park, laat hem onder het zand komen, vallen tijdens het rennen en steentjes verzamelen. Die vrijheid in de natuur is het beste ontwikkelingsmedicijn voor zijn brein.', title_pl = 'Wolność w parku 🌳', body_pl = 'Cztery ściany go rozdrażniają. Zabierz go do parku, niech się wytarza w piasku, przewraca w biegu, zbiera kamyki. Ta wolność na łonie natury to najlepsze lekarstwo na rozwój jego mózgu.', title_pt = 'Liberdade no parque 🌳', body_pt = 'As quatro paredes deixam-no agressivo. Leve-o ao parque, deixe que se suje na areia, que caia a correr, que apanhe pedras. Esta liberdade na natureza é o melhor remédio de desenvolvimento para o cérebro dele.', title_sv = 'Frihet i parken 🌳', body_sv = 'De fyra väggarna gör barnet argt. Ta med barnet till parken, låt det bli sandigt, springa och ramla, samla stenar. Den här friheten i naturen är den utvecklingsmedicin som påverkar hjärnan bäst.', title_vi = 'Tự do ở công viên 🌳', body_vi = 'Bốn bức tường khiến bé trở nên cáu kỉnh. Hãy đưa bé ra công viên, để bé lấm lem cát, chạy rồi ngã, nhặt sỏi đá. Sự tự do giữa thiên nhiên chính là "liều thuốc" phát triển tốt nhất cho não bộ của bé.', title_zh = '公园里的自由 🌳', body_zh = '四面墙让宝宝变得烦躁。带宝宝去公园吧，让宝宝在沙子里打滚，跑着跑着摔一跤，捡捡石头。大自然里的这份自由，是对大脑最好的发育良药。' WHERE id = '20794d75-b46f-481d-baa5-2b85b8516d4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación. La melatonina solo se libera rápido en un ambiente tranquilo, con poca luz y sin pantallas.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée rapidement que dans un environnement calme, peu éclairé et sans écran.', body_hi = 'उसे जल्दी नींद आए, इसके लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन सिर्फ़ शांत, कम रोशनी वाले और बिना स्क्रीन के माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dengan cepat di lingkungan yang tenang, redup, dan bebas layar.', body_ja = '早く寝つけるように、部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニンは、静かで薄暗く、画面のない環境でこそすばやく分泌されます。', body_ko = '더 빨리 잠들 수 있게 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌은 조용하고 어둑하며 화면이 없는 환경에서만 빠르게 분비돼요.', body_nl = 'Zet alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt alleen snel aangemaakt in een rustige, schemerige omgeving zonder schermen.', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina szybko wydziela się tylko w spokojnym, przyciemnionym otoczeniu bez ekranów.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente calmo, com pouca luz e sem ecrãs.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet. Melatonin utsöndras snabbt bara i en lugn, dämpad och skärmfri miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường yên tĩnh, ít ánh sáng và không có màn hình.', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯和平板屏幕。只有在安静、昏暗、没有屏幕的环境里，褪黑素才会快速分泌。' WHERE id = '3d4fe78e-9d18-4fa4-b11f-ee7836615ee7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Habla solo en la habitación con sus amigos invisibles y les sirve té? ¡Es la cima del desarrollo de la imaginación! Observa con orgullo a este gran guionista: ya está creando universos.', body_fr = 'Seul dans sa chambre, il parle à ses amis invisibles et leur sert du thé ? C''est le sommet du développement de l''imagination ! Observez fièrement de loin ce formidable scénariste, il crée déjà tout un univers.', body_hi = 'कमरे में अकेले अपने अदृश्य दोस्तों से बातें करता है, उन्हें चाय परोसता है? यह कल्पना के विकास का सबसे ऊँचा शिखर है! इस शानदार पटकथा लेखक को दूर से गर्व से देखिए, वह अब पूरी दुनिया रच रहा है।', body_id = 'Ia berbicara sendiri dengan teman tak kasatmata di kamar dan menuangkan teh untuk mereka? Ini puncak perkembangan imajinasi! Saksikan penulis skenario hebat ini dengan bangga dari samping, ia sedang menciptakan semesta.', body_ja = '部屋でひとり、見えないお友だちとおしゃべりして、お茶を注いであげている？想像力の発達が最高潮です！この見事な脚本家を、そっと誇らしく見守りましょう。もう宇宙をつくり出しているんです。', body_ko = '방에서 혼자 보이지 않는 친구와 이야기하고 차를 따라 주나요? 상상력 발달의 정점이에요! 이 멋진 시나리오 작가를 옆에서 뿌듯하게 지켜보세요. 벌써 자기만의 우주를 만들고 있어요.', body_nl = 'Praat hij in zijn eentje met onzichtbare vriendjes en schenkt hij ze thee in? Dit is het hoogtepunt van zijn fantasieontwikkeling! Kijk trots van een afstand naar deze geweldige scenarist, hij schept al een heel universum.', body_pl = 'Rozmawia w pokoju sam z niewidzialnymi przyjaciółmi i nalewa im herbatę? To szczyt rozwoju wyobraźni! Obserwuj z dumą tego wspaniałego scenarzystę, on już tworzy własny wszechświat.', body_pt = 'Fala sozinho no quarto com amigos invisíveis e serve-lhes chá? É o auge do desenvolvimento da imaginação! Observe com orgulho este argumentista fantástico: já está a criar universos.', body_sv = 'Pratar barnet ensamt i rummet med osynliga vänner och häller upp te åt dem? Det är fantasiutvecklingens absoluta topp! Titta stolt på den fantastiska manusförfattaren på avstånd, barnet skapar redan ett helt universum.', body_vi = 'Bé một mình trò chuyện với những người bạn vô hình trong phòng, còn rót trà mời họ? Đây là đỉnh cao của sự phát triển trí tưởng tượng! Hãy tự hào ngắm nhìn "nhà biên kịch" tuyệt vời này từ xa, bé đang tạo ra cả một vũ trụ.', body_zh = '一个人在房间里和看不见的朋友聊天，还给它们倒茶？这是想象力发展的巅峰时刻！在一旁骄傲地欣赏这位了不起的编剧吧，宝宝已经在创造整个宇宙了。' WHERE id = '5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te explica algo que tú ya sabes con una cara muy seria e inteligente. Está poniendo a prueba sus conocimientos. Aunque te cueste aguantar la risa, escúchale con mucha seriedad.', body_fr = 'Il vient vous expliquer, avec un air très sérieux et savant, quelque chose que vous savez déjà. Il teste ses connaissances. Même si vous avez du mal à ne pas rire, écoutez-le très sérieusement.', body_hi = 'जो बात आपको पहले से पता है, वही आकर बहुत गंभीर और समझदार चेहरे के साथ आपको समझाता है। वह अपने ज्ञान को परख रहा है। हँसी रोकना मुश्किल हो, फिर भी उसे बहुत गंभीरता से सुनिए।', body_id = 'Ia datang dan menjelaskan sesuatu yang sudah Anda ketahui dengan wajah sangat serius dan sok pintar. Ia sedang menguji pengetahuannya. Meski susah menahan tawa, dengarkan ia dengan sangat serius.', body_ja = 'あなたがもう知っていることを、とても真剣でかしこそうな顔で説明してくれます。自分の知識を試しているんです。笑いをこらえるのが大変でも、とても真剣に聞いてあげましょう。', body_ko = '엄마가 이미 아는 걸 아주 진지하고 똑똑한 표정으로 설명해 주나요? 자기 지식을 시험하는 중이에요. 웃음을 참기 힘들어도 아주 진지하게 들어 주세요.', body_nl = 'Hij legt je met een heel serieus en slim gezicht iets uit wat je allang weet. Hij test zijn kennis. Ook al kun je je lachen amper inhouden, luister heel serieus naar hem.', body_pl = 'Przychodzi i z bardzo poważną, mądrą miną tłumaczy ci coś, co dobrze wiesz. Sprawdza swoją wiedzę. Choć trudno ci powstrzymać śmiech, wysłuchaj go z pełną powagą.', body_pt = 'Vem explicar-lhe algo que a mãe já sabe, com uma expressão muito séria e inteligente. Está a testar o que sabe. Mesmo que mal consiga conter o riso, ouça-o com toda a seriedade.', body_sv = 'Barnet kommer och förklarar något du redan vet, med en väldigt allvarlig och klok min. Barnet testar sina kunskaper. Även om du knappt kan hålla dig för skratt, lyssna på barnet på största allvar.', body_vi = 'Bé đến giải thích cho mẹ một điều mẹ đã biết, với vẻ mặt cực kỳ nghiêm túc và thông thái. Bé đang kiểm tra kiến thức của mình. Dù phải cố lắm mới nhịn được cười, hãy lắng nghe bé thật nghiêm túc nhé.', body_zh = '把你明明知道的事情，一脸严肃又聪明地给你讲解一遍。宝宝在测试自己的知识。就算你快忍不住笑了，也请非常认真地听宝宝说。' WHERE id = '19c93357-3662-4a7d-bd13-a71d938dc00a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Coge el móvil. En lugar de deslizar la vida de otros en redes sociales, abre el Diario de ánimo y anota para el futuro el momento más gracioso que ha tenido hoy. La terapia digital funciona.', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée. La thérapie numérique, ça marche.', body_hi = 'फ़ोन उठाइए। सोशल मीडिया पर दूसरों की ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसने जो सबसे मज़ेदार काम किया, उसे भविष्य के लिए लिख लीजिए। डिजिटल थेरेपी काम करती है।', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini untuk masa depan. Terapi digital itu berhasil.', body_ja = 'スマホを手に取って。SNSでほかの人の暮らしをスクロールする代わりに、「気分日記」を開いて、今日この子がしたいちばんおもしろい瞬間を未来のために記録しましょう。デジタルセラピーは効きますよ。', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃긴 순간을 기록해 두세요. 디지털 치료, 효과 있어요.', body_nl = 'Pak je telefoon. Open in plaats van door andermans leven op social media te scrollen je Stemmingsdagboek en schrijf het grappigste moment van vandaag op voor later. Digitale therapie werkt.', body_pl = 'Weź telefon do ręki. Zamiast przewijać cudze życie w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował. Cyfrowa terapia działa.', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje. A terapia digital funciona.', body_sv = 'Ta upp telefonen. Istället för att scrolla igenom andras liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet för framtiden. Digital terapi fungerar.', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc hài hước nhất bé làm hôm nay để dành cho tương lai. Liệu pháp số thật sự có hiệu quả.', body_zh = '拿起手机。与其刷社交网络看别人的生活，不如打开心情日记，把宝宝今天最搞笑的一刻记下来留给将来。数字疗愈真的有用。' WHERE id = '6ab81ee1-daa9-4300-97cb-c7dad69d9baf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rebelión contra la siesta 🥱', body_es = '¿No quiere ir a la cama de ninguna manera? Cerca de los 3 años esta resistencia es un clásico. No le obligues ni le hagas llorar. Baja las luces de la habitación y cambia la rutina anunciando la «hora de hojear libros en silencio».', title_fr = 'La révolte de la sieste 🥱', body_fr = 'Il refuse catégoriquement d''aller au lit ? À l''approche des 3 ans, cette résistance est très classique. Ne le forcez pas, ne le faites pas pleurer. Changez la routine : baissez les lumières et annoncez « l''heure des livres en silence ».', title_hi = 'दिन की नींद से बगावत 🥱', body_hi = 'सोने जाना बिल्कुल नहीं चाहता? 3 साल के आसपास यह ज़िद बहुत आम है। ज़बरदस्ती मत कीजिए, रुलाइए मत। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और रूटीन बदल दीजिए।', title_id = 'Pemberontakan tidur siang 🥱', body_id = 'Ia sama sekali tidak mau tidur? Menjelang usia 3 tahun, penolakan ini sangat klasik. Jangan memaksa atau membuatnya menangis. Redupkan lampu kamar dan ubah rutinitas dengan mengumumkan ''Waktu membaca buku dengan tenang''.', title_ja = 'お昼寝ストライキ 🥱', body_ja = 'どうしてもベッドに行きたがらない？3歳前後のこの抵抗はとても定番です。無理強いせず、泣かせないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ルーティンを変えてみましょう。', title_ko = '낮잠 반란 🥱', body_ko = '절대 자러 가지 않겠다고 하나요? 세 살 무렵의 이런 저항은 아주 흔해요. 억지로 재우거나 울리지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 루틴을 바꿔 보세요.', title_nl = 'Opstand bij het middagslaapje 🥱', body_nl = 'Wil hij absoluut niet naar bed? Dit verzet rond 3 jaar is heel klassiek. Dwing hem niet en laat hem niet huilen. Verander de routine: dim de lichten en kondig een ''stil boekjesuurtje'' aan.', title_pl = 'Bunt przed drzemką 🥱', body_pl = 'Kategorycznie nie chce iść do łóżka? Ten opór w okolicach 3 lat to klasyka. Nie zmuszaj i nie doprowadzaj do płaczu. Zmień rutynę: przygaś światła i ogłoś „cichą godzinę z książeczką”.', title_pt = 'A revolta da sesta 🥱', body_pt = 'Não quer mesmo nada ir para a cama? Perto dos 3 anos esta resistência é muito clássica. Não o obrigue nem o faça chorar. Baixe as luzes do quarto e mude a rotina anunciando a "hora de folhear livros em silêncio".', title_sv = 'Upproret mot tuppluren 🥱', body_sv = 'Vill barnet absolut inte gå och lägga sig? Det här motståndet är väldigt klassiskt inför 3 år. Tvinga inte, få inte barnet att gråta. Dämpa ljuset i rummet och ändra rutinen genom att utlysa en ”tyst bläddra-i-böcker-stund”.', title_vi = 'Cuộc nổi loạn giờ ngủ trưa 🥱', body_vi = 'Bé nhất quyết không chịu lên giường? Sự phản kháng này rất điển hình khi gần 3 tuổi. Đừng ép, đừng làm bé khóc. Hãy thay đổi nếp sinh hoạt bằng cách giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng".', title_zh = '午睡大反抗 🥱', body_zh = '死活不肯上床？快3岁时，这种反抗非常典型。别强迫，别把宝宝弄哭。把房间灯光调暗，宣布“安静翻书时间”，换一种日常流程。' WHERE id = 'ee467fcc-7c51-4e6a-ba68-1e6466be7d10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Prohibido olvidarte de ti! 🥗', body_es = '¿Has pensado 3 menús distintos para que él coma y tú te has vuelto a quedar con hambre? Elige en Recetas saludables una comida rica en hierro y calcio que se prepara en 10 minutos y siéntete valorada.', title_fr = 'Interdit de vous oublier ! 🥗', body_fr = 'Vous avez imaginé 3 menus différents pour le nourrir, et vous, vous êtes encore restée le ventre vide ? Choisissez dans les Recettes saines un repas riche en fer et en calcium, prêt en 10 minutes, et prenez soin de vous.', title_hi = 'खुद को भूलना मना है! 🥗', body_hi = 'उसका पेट भरने के लिए 3 अलग मेन्यू सोचे, और आप फिर से भूखी रह गईं? सेहतमंद रेसिपी से 10 मिनट में बनने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और खुद को कीमती महसूस कीजिए।', title_id = 'Dilarang melupakan diri sendiri! 🥗', body_id = 'Anda memikirkan 3 menu berbeda untuk membuatnya kenyang, tapi Anda sendiri kelaparan lagi? Pilih makan siang kaya zat besi dan kalsium dari Resep Sehat yang siap dalam 10 menit, dan rasakan bahwa Anda berharga.', title_ja = '自分を忘れるのは禁止！ 🥗', body_ja = 'この子のために3種類のメニューを考えたのに、自分はまた食べそびれた？「ヘルシーレシピ」から10分でできる、鉄分とカルシウムたっぷりのランチを選んで、自分を大切にしましょう。', title_ko = '나를 잊으면 안 돼요! 🥗', body_ko = '아이를 먹이려고 메뉴를 3가지나 고민했는데 정작 엄마는 또 굶었나요? 건강한 레시피에서 10분이면 만드는 철분과 칼슘이 풍부한 식사를 골라 나를 소중히 대해 주세요.', title_nl = 'Jezelf vergeten is verboden! 🥗', body_nl = 'Drie verschillende menu''s bedacht om hem te eten te geven, maar zelf weer niets gegeten? Kies uit Gezonde recepten een ijzer- en calciumrijke lunch die in 10 minuten klaar is, en voel dat je ertoe doet.', title_pl = 'Nie wolno zapominać o sobie! 🥗', body_pl = 'Wymyśliłaś 3 różne menu, żeby go nakarmić, a sama znowu zostałaś głodna? Wybierz ze Zdrowych przepisów obiad bogaty w żelazo i wapń, gotowy w 10 minut, i poczuj, że jesteś ważna.', title_pt = 'Proibido esquecer-se de si! 🥗', body_pt = 'Pensou em 3 menus diferentes para ele comer, mas a mãe voltou a ficar com fome? Escolha nas Receitas Saudáveis um almoço rico em ferro e cálcio, pronto em 10 minutos, e sinta-se valorizada.', title_sv = 'Förbjudet att glömma bort dig själv! 🥗', body_sv = 'Du hittade på 3 olika menyer för att få barnet mätt, men själv blev du hungrig igen? Välj en järn- och kalciumrik lunch som tar 10 minuter bland Hälsosamma recept och känn dig värdefull.', title_vi = 'Cấm quên bản thân! 🥗', body_vi = 'Mẹ nghĩ ra 3 thực đơn khác nhau để bé ăn no, còn bản thân thì lại nhịn đói? Hãy chọn một bữa ăn giàu sắt và canxi, nấu trong 10 phút từ Công thức lành mạnh, và cảm nhận giá trị của chính mình.', title_zh = '不许忘了自己！🥗', body_zh = '为了喂饱宝宝想了3种不同的菜单，结果自己又饿着？从健康食谱里挑一道10分钟就能做好、富含铁和钙的午餐，让自己感受到被珍视。' WHERE id = '1bbd92c6-a12a-4c26-a63f-0946e226b656' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ataque de rabia repentino 💥', body_es = '¿Jugando se ha enfadado de golpe y ha lanzado sus juguetes? Aún no sabe controlar sus emociones. En lugar de gritar, empatiza diciendo: «Veo que estás enfadado, vamos a respirar hondo juntos».', title_fr = 'Colère soudaine 💥', body_fr = 'En jouant, il s''est soudain énervé et a lancé ses jouets ? Il ne sait pas encore gérer ses émotions. Au lieu de crier, montrez-lui de l''empathie : « Je vois que tu es en colère, respirons profondément ensemble. »', title_hi = 'अचानक गुस्से का झटका 💥', body_hi = 'खेलते-खेलते अचानक चिढ़कर खिलौने फेंक दिए? वह अभी अपनी भावनाएँ संभाल नहीं पाता। चिल्लाने के बजाय कहिए, ‘मैं देख रही हूँ कि तुम नाराज़ हो, आओ साथ में गहरी साँस लें’ और सहानुभूति से जुड़िए।', title_id = 'Ledakan amarah mendadak 💥', body_id = 'Sedang bermain, tiba-tiba ia marah dan melempar mainannya? Ia belum bisa mengendalikan emosinya. Daripada berteriak, tunjukkan empati dengan berkata ''Mama lihat kamu marah, ayo kita tarik napas dalam bersama''.', title_ja = 'いきなりの怒り爆発 💥', body_ja = '遊んでいる最中に急に怒って、おもちゃを投げた？まだ気持ちをコントロールできないんです。どなる代わりに「怒っているのがわかるよ、一緒に深呼吸しよう」と声をかけて、気持ちに寄りそいましょう。', title_ko = '갑작스러운 분노 폭발 💥', body_ko = '놀다가 갑자기 화가 나서 장난감을 던졌나요? 아직 감정을 조절하지 못해서 그래요. 소리치는 대신 ''화가 났구나, 같이 깊게 숨 쉬어 보자''라고 말하며 공감해 주세요.', title_nl = 'Plotselinge woedeaanval 💥', body_nl = 'Werd hij tijdens het spelen ineens boos en gooide hij met zijn speelgoed? Hij kan zijn emoties nog niet beheersen. Ga niet schreeuwen, maar toon empathie: ''Ik zie dat je boos bent, laten we samen diep ademhalen.''', title_pl = 'Nagły wybuch złości 💥', body_pl = 'Podczas zabawy nagle się zdenerwował i rzucił zabawkami? Nie umie jeszcze panować nad emocjami. Zamiast krzyczeć, powiedz: „Widzę, że się złościsz, weźmy razem głęboki oddech” i okaż empatię.', title_pt = 'Ataque de fúria repentino 💥', body_pt = 'A brincar, irritou-se de repente e atirou os brinquedos? Ainda não consegue controlar as emoções. Em vez de gritar, mostre empatia: "Vejo que estás zangado, vamos respirar fundo juntos".', title_sv = 'Ett plötsligt utbrott 💥', body_sv = 'Blev barnet plötsligt argt mitt i leken och kastade iväg leksakerna? Barnet kan ännu inte hantera sina känslor. Istället för att skrika, visa empati: ”Jag ser att du är arg, kom så andas vi djupt tillsammans.”', title_vi = 'Cơn giận bất chợt 💥', body_vi = 'Đang chơi, bé bỗng nổi giận và ném đồ chơi? Bé chưa biết kiểm soát cảm xúc. Thay vì quát mắng, hãy đồng cảm: "Mẹ thấy con đang bực, mình cùng hít thở thật sâu nhé".', title_zh = '突然的怒气 💥', body_zh = '玩着玩着突然生气，把玩具扔了出去？宝宝还不会管理自己的情绪。别吼，试着共情：“我看到你生气了，我们一起深呼吸吧。”' WHERE id = '31e8c246-42c7-4bad-8ff1-c08af53874b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Aunque no haya champán, servid té caliente en los vasos y brindad con tu pareja diciendo: «Hemos sobrevivido a otro día difícil». Sois los comandantes más fuertes de la casa.', body_fr = 'L''enfant dort. Pas de champagne ? Versez du thé chaud dans des verres et trinquez avec votre partenaire : « On a survécu à cette journée difficile ! » Vous êtes les plus valeureux commandants de cette maison.', body_hi = 'बच्चा सो गया। शैंपेन न सही, गिलासों में गरम चाय डालिए और अपने साथी के साथ ‘यह मुश्किल दिन भी सही-सलामत निकाल लिया’ कहकर गिलास टकराइए। आप इस घर के सबसे मज़बूत सेनापति हैं।', body_id = 'Anak sudah tidur. Tak ada sampanye pun tak apa, tuang teh hangat ke gelas dan bersulanglah dengan pasangan sambil berkata ''Kita berhasil melewati hari berat ini dengan selamat''. Kalian adalah panglima terkuat di rumah ini.', body_ja = '子どもが寝ました。シャンパンがなくても、コップに温かいお茶を注いで、パートナーと「今日の大変な一日も無事に乗りきったね」と乾杯しましょう。ふたりはこの家のいちばん強い司令官です。', body_ko = '아이가 잠들었어요. 샴페인이 없어도 컵에 따뜻한 차를 따르고 배우자와 ''오늘같이 힘든 날도 무사히 끝냈어''라며 건배하세요. 두 사람이 이 집의 가장 강한 사령관이에요.', body_nl = 'Je kind slaapt. Geen champagne in huis? Schenk dan warme thee in en klink met je partner: ''Ook deze zware dag hebben we gehaald!'' Jullie zijn de sterkste aanvoerders van dit huis.', body_pl = 'Dziecko śpi. Nie ma szampana? Nalejcie do szklanek gorącej herbaty i stuknijcie się z partnerem, mówiąc: „Ten trudny dzień też przetrwaliśmy cało”. Jesteście najdzielniejszymi dowódcami tego domu.', body_pt = 'A criança adormeceu. Mesmo sem champanhe, sirvam chá quente nos copos e brindem com o seu companheiro: "Também sobrevivemos a este dia difícil". São os comandantes mais fortes desta casa.', body_sv = 'Barnet sover. Även om det inte finns champagne, häll upp varmt te i glasen, skåla med din partner och säg ”Den här tuffa dagen klarade vi också”. Ni är hemmets starkaste befälhavare.', body_vi = 'Bé đã ngủ. Không có sâm panh cũng chẳng sao, hãy rót trà nóng vào cốc và cụng ly cùng chồng: "Chúng ta lại vượt qua thêm một ngày khó khăn nữa rồi!". Hai người là những vị chỉ huy mạnh mẽ nhất của ngôi nhà này.', body_zh = '宝宝睡着了。没有香槟也没关系，往杯子里倒上热茶，和伴侣碰个杯：“这艰难的一天，我们也平平安安地度过了。”你们是这个家里最强大的指挥官。' WHERE id = '96327d67-c216-46e6-b768-6cd8fce23852' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar energía en casa y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo levanta en el aire y hace el avión, las carcajadas llenan la habitación y el estrés físico desaparece en segundos.', body_fr = 'Il n''a pas pu se dépenser à la maison et refuse d''aller au lit. Appelez papa en renfort. Quand il le soulève pour jouer à l''avion, les éclats de rire remplissent la pièce et la tension physique disparaît en quelques secondes.', body_hi = 'घर में ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ बनाते हैं, तो कमरा ठहाकों से भर जाता है और शारीरिक तनाव सेकंडों में गायब हो जाता है।', body_id = 'Ia belum sempat menyalurkan energinya di rumah dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah mengangkatnya tinggi dan membuatnya ''terbang seperti pesawat'', tawa memenuhi kamar dan stres fisik hilang dalam hitungan detik.', body_ja = '家でエネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを持ち上げて飛行機ごっこをすると、部屋は笑い声でいっぱいになり、体のストレスはあっという間に消えていきます。', body_ko = '집에서 에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 번쩍 들어 비행기를 태우면 웃음소리가 방을 채우고, 몸의 스트레스가 몇 초 만에 사라져요.', body_nl = 'Hij is zijn energie in huis niet kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem optilt en als een vliegtuig laat vliegen, vult de kamer zich met geschater en verdwijnt de lichamelijke spanning in een paar seconden.', body_pl = 'Nie wyładował energii w domu i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy podrzuci go w górę i zrobi „samolot”, śmiech wypełni pokój, a napięcie fizyczne zniknie w kilka sekund.', body_pt = 'Não conseguiu gastar a energia em casa e recusa ir para a cama. Chame o pai para ajudar. Quando ele o levanta no ar e faz de avião, as gargalhadas enchem o quarto e o stress físico desaparece em segundos.', body_sv = 'Barnet har inte fått ur sig energin hemma och vägrar gå och lägga sig. Kalla på pappa. När han lyfter upp barnet i luften och flyger flygplan fylls rummet av skratt och den fysiska stressen försvinner på några sekunder.', body_vi = 'Bé chưa xả hết năng lượng trong nhà nên nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố nhấc bé lên cao "làm máy bay", tiếng cười sẽ ngập tràn căn phòng và mọi căng thẳng thể chất tan biến chỉ trong vài giây.', body_zh = '在家没把精力释放完，就是不肯上床。叫爸爸来帮忙吧。当爸爸把宝宝举高高“开飞机”时，笑声充满房间，身体的紧张几秒钟就消失了。' WHERE id = 'b8850dac-f142-4e24-bc24-56bb7962ebf6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pausa de mamá ☕', body_es = 'Estás cansada de hablar en idioma infantil. Busca en Lugares para mamás una cafetería con rincón infantil, tómate un café y respira charlando con otras madres.', title_fr = 'La pause de maman ☕', body_fr = 'Fatiguée de parler comme un bébé ? Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants, buvez votre café et respirez en discutant avec d''autres mamans.', title_hi = 'माँ का ब्रेक ☕', body_hi = 'बच्चों की भाषा में बात करते-करते थक गई हैं। माँ के लिए अनुकूल जगहें से बच्चों के कोने वाला कैफ़े ढूँढिए, अपनी कॉफ़ी पीजिए और दूसरी माँओं से दिल की बात करके राहत की साँस लीजिए।', title_id = 'Waktu rehat Ibu ☕', body_id = 'Lelah berbicara dengan bahasa anak? Temukan kafe dengan pojok anak di Tempat Ramah Ibu, minum kopi, mengobrol dengan ibu-ibu lain, dan bernapaslah lega.', title_ja = 'ママの休憩時間 ☕', body_ja = '赤ちゃん言葉で話すのに疲れましたか？「ママにやさしいスポット」でキッズコーナーのあるカフェを見つけて、コーヒーを飲みながら、ほかのママたちとおしゃべりしてひと息つきましょう。', title_ko = '엄마의 휴식 시간 ☕', body_ko = '아기 말투로 이야기하는 데 지쳤나요? 엄마 친화 장소에서 키즈 코너가 있는 카페를 찾아 커피 한 잔 마시며 다른 엄마들과 수다로 숨 좀 돌리세요.', title_nl = 'Pauze voor mama ☕', body_nl = 'Ben je het moe om babytaal te praten? Zoek bij Mamavriendelijke plekken een café met speelhoek, drink je koffie en klets even bij met andere mama''s.', title_pl = 'Przerwa dla mamy ☕', body_pl = 'Masz dość mówienia dziecięcym językiem. Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci, wypij kawę, pogadaj z innymi mamami i złap oddech.', title_pt = 'A pausa da mãe ☕', body_pt = 'Está cansada de falar como um bebé. Procure nos Locais Amigos das Mães um café com espaço infantil, beba o seu café, converse com outras mães e respire.', title_sv = 'Mammas paus ☕', body_sv = 'Är du trött på att prata barnspråk? Hitta ett kafé med lekhörna bland Mammavänliga platser, drick ditt kaffe, prata av dig med andra mammor och andas ut.', title_vi = 'Giờ nghỉ của mẹ ☕', body_vi = 'Mẹ đã mệt vì cứ phải nói "ngôn ngữ trẻ con". Hãy tìm một quán cà phê có góc chơi cho trẻ trong Địa điểm thân thiện với mẹ, thưởng thức cà phê, trò chuyện với các mẹ khác và hít thở thư thái.', title_zh = '妈妈的休息时间 ☕', body_zh = '说宝宝话说累了吧。在妈妈友好场所里找一家带儿童区的咖啡馆，喝杯咖啡，和其他妈妈聊聊天，喘口气。' WHERE id = 'ee7e813c-5a12-4710-b655-7b294f1ff478' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Llora detrás de ti aunque salgas de la habitación un segundo. La ansiedad por separación a veces vuelve cerca de los 3 años. Cada vez dale seguridad a distancia con tu voz: «Estoy aquí, en la cocina, ya voy».', body_fr = 'Il pleure derrière vous dès que vous quittez la pièce, même une seconde. L''angoisse de séparation revient parfois à l''approche des 3 ans. Parlez-lui à chaque fois pour lui dire que vous êtes là : « Je suis dans la cuisine, j''arrive ! » et rassurez-le à distance.', body_hi = 'आप एक पल के लिए कमरे से निकलती हैं, तब भी पीछे से रोता है। 3 साल के करीब बिछड़ने की चिंता कभी-कभी लौट आती है। हर बार आवाज़ देकर कि आप यहीं हैं, ‘मैं रसोई में हूँ, आ रही हूँ’ कहकर दूर से भरोसा दिलाइए।', body_id = 'Bahkan saat Anda keluar kamar sebentar saja, ia menangis memanggil Anda. Kecemasan berpisah kadang kembali menjelang usia 3 tahun. Setiap kali, beri ia rasa aman dari jauh dengan bersuara: ''Mama di dapur, Mama datang''.', body_ja = 'ほんの一瞬部屋を出ただけで、泣いて追いかけてくる。分離不安は3歳を前に、ときどきぶり返すことがあります。そのたびに「キッチンにいるよ、すぐ行くよ」と声をかけて、離れていても安心させてあげましょう。', body_ko = '잠깐 방을 나가도 울며 따라오나요? 분리불안은 세 살 무렵 다시 나타나기도 해요. 그때마다 ''엄마 부엌에 있어, 금방 갈게''라고 소리 내어 멀리서도 안심시켜 주세요.', body_nl = 'Gaat hij al huilen als je maar een seconde de kamer uit loopt? Scheidingsangst komt rond 3 jaar soms terug. Roep hem elke keer en stel hem op afstand gerust: ''Ik ben in de keuken, ik kom eraan.''', body_pl = 'Płacze za tobą, nawet gdy wychodzisz z pokoju na sekundę. Lęk separacyjny czasem wraca tuż przed 3. urodzinami. Za każdym razem odezwij się, że jesteś blisko: „Jestem w kuchni, już idę”, i dawaj mu poczucie bezpieczeństwa z daleka.', body_pt = 'Chora atrás de si mesmo quando sai do quarto por um segundo. A ansiedade de separação às vezes regressa perto dos 3 anos. Responda-lhe sempre, dizendo que está aqui: "estou na cozinha, já vou", e dê-lhe segurança à distância.', body_sv = 'Barnet gråter efter dig även när du lämnar rummet en sekund. Separationsångesten kan ibland komma tillbaka inför 3 år. Ge trygghet på avstånd genom att ropa varje gång att du är här: ”Jag är i köket, jag kommer.”', body_vi = 'Mẹ chỉ ra khỏi phòng vài giây mà bé đã khóc đòi theo. Lo âu chia ly đôi khi quay lại khi gần 3 tuổi. Mỗi lần như vậy, hãy lên tiếng cho bé biết mẹ vẫn ở đây: "Mẹ ở trong bếp, mẹ đến ngay!" để bé yên tâm dù ở xa.', body_zh = '哪怕你离开房间一秒钟，宝宝都会在后面哭。快3岁时，分离焦虑有时会卷土重来。每次都出声告诉宝宝你就在这里：“我在厨房，马上来”，从远处给宝宝安全感。' WHERE id = '3a35865f-054d-413c-b3ad-81c68c171c47' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tras un día ruidoso, cuando el peque se duerma, mide el silencio de la habitación con el Medidor de sonido. Solo ver esos números acercarse a cero es como el mejor masaje visual para el cerebro de una madre.', body_fr = 'Après une journée bruyante, quand il dort, mesurez le silence de la chambre avec le Sonomètre. Rien que de voir ces chiffres s''approcher de zéro, c''est le meilleur massage visuel pour le cerveau d''une maman.', body_hi = 'शोर भरे दिन के बाद, बच्चे के सोने पर साउंड मीटर से कमरे की खामोशी मापिए। शून्य के करीब पहुँचते अंक देखना ही माँ के दिमाग के लिए सबसे अच्छी विज़ुअल मसाज जैसा है।', body_id = 'Setelah hari yang bising, saat anak sudah tidur, ukur keheningan kamar dengan Pengukur Suara. Melihat angka yang mendekati nol saja sudah terasa seperti pijatan visual terbaik untuk otak seorang ibu.', body_ja = 'にぎやかな一日のあと、子どもが寝たら「サウンドメーター」で部屋の静けさを測ってみましょう。ゼロに近づいていく数字を見るだけで、ママの脳にとってはいちばんの視覚マッサージになります。', body_ko = '시끌벅적한 하루가 끝나고 아이가 잠들면 소음 측정기로 방의 고요를 재 보세요. 0에 가까워지는 숫자를 보는 것만으로도 엄마의 머리에 최고의 시각 마사지가 돼요.', body_nl = 'Meet na een drukke dag, als hij slaapt, de stilte in de kamer met de Geluidsmeter. Alleen al die getallen richting nul zien zakken werkt als de beste visuele massage voor het brein van een mama.', body_pl = 'Po hałaśliwym dniu, gdy dziecko zaśnie, zmierz ciszę w pokoju Miernikiem dźwięku. Sam widok liczb spadających do zera działa na mózg mamy jak najlepszy wizualny masaż.', body_pt = 'Depois de um dia barulhento, quando a criança adormecer, meça o silêncio do quarto com o Medidor de Som. Ver os números a aproximarem-se do zero funciona como a melhor massagem visual para o cérebro da mãe.', body_sv = 'Efter en bullrig dag, mät tystnaden i rummet med Ljudmätaren när barnet sover. Bara att se siffrorna närma sig noll fungerar som den bästa visuella massagen för en mammas hjärna.', body_vi = 'Sau một ngày ồn ào, khi bé đã ngủ, hãy dùng Đo âm thanh để đo sự yên tĩnh trong phòng. Chỉ cần nhìn những con số tiến dần về không cũng giống như một màn mát-xa thị giác tuyệt vời nhất cho não bộ của mẹ.', body_zh = '热闹的一天过后，等宝宝睡着了，用分贝仪测一测房间的安静程度。光是看着那些越来越接近零的数字，对妈妈的大脑来说就像一次最好的视觉按摩。' WHERE id = '96b4e611-59a4-4d8b-a157-87f9d477e265' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Es un día difícil y todo te parece enorme? Los consejos de las madres con experiencia de la Comunidad Anacan son las soluciones más reales, sacadas de la vida y que no aparecen en ningún libro. Inspírate en ellas.', body_fr = 'Journée difficile où tout vous paraît énorme ? Les conseils des mamans expérimentées de la Communauté Anacan sont les solutions les plus concrètes, tirées de la vraie vie et introuvables dans les livres. Inspirez-vous-en.', body_hi = 'मुश्किल दिन है और हर चीज़ बड़ी लग रही है? Anacan कम्युनिटी की अनुभवी माँओं की सलाह ज़िंदगी से निकले सबसे असली हल हैं, जो किसी किताब में नहीं लिखे, वहाँ से प्रेरणा लीजिए।', body_id = 'Hari yang berat dan semuanya terasa membesar di mata Anda? Saran ibu-ibu berpengalaman di Komunitas Anacan adalah solusi paling nyata dari kehidupan, yang tak tertulis di buku mana pun. Ambil inspirasi dari sana.', body_ja = '大変な一日で、何もかも大きく見えてしまう？Anacanコミュニティの経験豊富なママたちのアドバイスは、どんな本にも載っていない、暮らしから生まれたいちばんリアルな解決策。ヒントをもらいましょう。', body_ko = '힘든 하루라 모든 게 크게만 느껴지나요? Anacan 커뮤니티의 경험 많은 엄마들의 조언은 어떤 책에도 없는 생생한 해결책이에요. 그곳에서 힘을 얻어 보세요.', body_nl = 'Een zware dag en lijkt alles groter dan het is? De tips van ervaren mama''s in de Anacan Community zijn de meest echte oplossingen uit het leven, die je in geen enkel boek vindt. Haal daar je inspiratie vandaan.', body_pl = 'Trudny dzień i wszystko wydaje się przytłaczające? Rady doświadczonych mam ze Społeczności Anacan to najbardziej życiowe rozwiązania, których nie znajdziesz w żadnej książce. Czerp z nich inspirację.', body_pt = 'É um dia difícil e tudo parece maior do que é? Os conselhos das mães experientes da Comunidade Anacan são as soluções mais reais, tiradas da vida, que não vêm em nenhum livro. Inspire-se lá.', body_sv = 'Är det en tuff dag och allt känns överväldigande? Råden från erfarna mammor i Anacan Community är de mest verklighetsnära lösningarna, hämtade ur livet och inte skrivna i någon bok. Hämta inspiration där.', body_vi = 'Một ngày khó khăn và mọi thứ dường như to tát hơn? Lời khuyên của các mẹ giàu kinh nghiệm trong Cộng đồng Anacan là những giải pháp thực tế nhất từ cuộc sống mà chẳng cuốn sách nào viết ra. Hãy tìm cảm hứng ở đó.', body_zh = '今天很难熬，什么事都显得特别大？Anacan社区里有经验的妈妈们的建议，是任何书里都没写过、来自真实生活的最实在的办法，从那里汲取灵感吧。' WHERE id = '2d61ffa4-9df3-4b29-acca-6b87ebc82745' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir entre susurros 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, muy bajito, lo que ha pasado durante el día. Susurrar es el método más natural y potente para preparar el cerebro para dormir y olvidar el ruido.', title_fr = 'S''endormir en chuchotant 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et chuchotez-lui à l''oreille, tout bas, ce qui s''est passé dans la journée. Le chuchotement est la façon la plus naturelle et la plus puissante de préparer le cerveau au sommeil et de lui faire oublier le bruit.', title_hi = 'फुसफुसाहट के साथ नींद 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने और शोर भुलाने का सबसे प्राकृतिक और असरदार तरीका है।', title_id = 'Tidur dengan bisikan 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan kejadian hari ini ke telinganya dengan suara sangat pelan. Bisikan adalah cara paling alami dan ampuh untuk menyiapkan otak tidur dan melupakan kebisingan.', title_ja = 'ささやきで寝かしつけ 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことを耳もとでとても小さな声でささやいてあげて。ささやき声は、脳を眠りへ導き、にぎやかさを忘れさせる、いちばん自然で力強い方法です。', title_ko = '속삭임으로 재우기 🌙', body_ko = '방의 불을 모두 끄세요. 옆에 누워 오늘 있었던 일을 아주 낮은 목소리로 귓가에 속삭여 주세요. 속삭임은 뇌를 잠들 준비시키고 소음을 잊게 하는 가장 자연스럽고 강력한 방법이에요.', title_nl = 'Fluisterend in slaap 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en fluister heel zachtjes in zijn oor wat er vandaag is gebeurd. Fluisteren is de meest natuurlijke en krachtige manier om het brein klaar te maken voor de slaap en het lawaai te vergeten.', title_pl = 'Zasypianie przy szepcie 🌙', body_pl = 'Zgaś całkowicie światła w pokoju. Połóż się obok i bardzo cicho wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia. Szept to najbardziej naturalny i skuteczny sposób, by przygotować mózg do snu i zapomnieć o hałasie.', title_pt = 'Adormecer a sussurrar 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, o que aconteceu durante o dia. Sussurrar é o método mais natural e poderoso para preparar o cérebro para o sono e esquecer o barulho.', title_sv = 'Viskningar inför sömnen 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och viska mycket tyst i örat om det som hänt under dagen. Viskningar är den mest naturliga och kraftfulla metoden för att förbereda hjärnan för sömn och glömma oväsendet.', title_vi = 'Giấc ngủ cùng lời thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ vào tai bé về những gì đã xảy ra trong ngày. Thì thầm là cách tự nhiên và hiệu quả nhất giúp não bộ chuẩn bị cho giấc ngủ, quên đi những ồn ào.', title_zh = '悄悄话哄睡 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，在宝宝耳边悄悄讲今天发生的事。悄悄话是帮大脑准备入睡、忘掉喧嚣最自然也最有效的方法。' WHERE id = '5e23814c-ef4e-4708-8223-e1ab2ac7daa9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Destrucción con propósito 🧱', body_es = 'Construye una torre con mucho esfuerzo y luego la derriba riéndose. Está aprendiendo física, causa y efecto. No te enfades: las torres que caen son nuevas conexiones neuronales en su cerebro.', title_fr = 'Détruire, c''est apprendre 🧱', body_fr = 'Il construit une tour avec beaucoup d''efforts, puis la fait tomber d''un coup en riant. Il apprend la physique, la cause et l''effet. Ne vous énervez pas : ces tours qui tombent, ce sont de nouvelles connexions neuronales dans son cerveau.', title_hi = 'मकसद भरी तोड़फोड़ 🧱', body_hi = 'बड़ी मेहनत से मीनार बनाता है, फिर हँसते हुए एक झटके में गिरा देता है। वह भौतिकी और कारण-परिणाम सीख रहा है। नाराज़ मत होइए, गिरती मीनारें उसके दिमाग में बनते नए न्यूरॉन कनेक्शन हैं।', title_id = 'Merobohkan dengan tujuan 🧱', body_id = 'Ia membangun menara dengan susah payah, lalu merobohkannya sambil tertawa dengan sekali sentuh. Ia sedang belajar fisika dan sebab-akibat. Jangan kesal, menara yang roboh adalah koneksi saraf baru di otaknya.', title_ja = 'わざと壊す遊び 🧱', body_ja = 'がんばってタワーを作ったのに、笑いながら一気にくずしてしまう。物理や原因と結果を学んでいるんです。イライラしないで。くずれるタワーは、脳の中にできる新しい神経のつながりです。', title_ko = '목적 있는 부수기 🧱', body_ko = '애써 탑을 쌓고는 깔깔 웃으며 한 번에 무너뜨리나요? 물리와 원인과 결과를 배우는 중이에요. 화내지 마세요, 무너지는 탑은 뇌 속의 새로운 신경 연결이에요.', title_nl = 'Doelgerichte sloop 🧱', body_nl = 'Hij bouwt met veel moeite een toren en gooit hem dan lachend in één klap om. Hij leert natuurkunde en oorzaak en gevolg. Word niet boos: die omvallende torens zijn nieuwe verbindingen in zijn brein.', title_pl = 'Celowe burzenie 🧱', body_pl = 'Z wielkim trudem buduje wieżę, a potem ze śmiechem burzy ją jednym ruchem. Uczy się fizyki i związku przyczyny ze skutkiem. Nie denerwuj się, burzone wieże to nowe połączenia neuronów w jego mózgu.', title_pt = 'Destruição com propósito 🧱', body_pt = 'Constrói uma torre com muito esforço e depois deita-a abaixo a rir. Está a aprender física e causa-efeito. Não se irrite: as torres que caem são novas ligações neuronais no cérebro dele.', title_sv = 'Målmedveten förstörelse 🧱', body_sv = 'Barnet bygger ett torn med stor möda och river det sedan skrattande med en spark. Barnet lär sig fysik, orsak och verkan. Bli inte irriterad, de raserade tornen är nya nervkopplingar i barnets hjärna.', title_vi = 'Phá hủy có chủ đích 🧱', body_vi = 'Bé dày công xây một tòa tháp, rồi vừa cười vừa đẩy đổ chỉ bằng một cú. Bé đang học về vật lý, về nguyên nhân và kết quả. Đừng bực mình, những tòa tháp đổ chính là những kết nối thần kinh mới trong não bé.', title_zh = '有目的的破坏 🧱', body_zh = '费了好大劲搭起一座塔，然后笑着一脚把它踢倒。宝宝在学习物理和因果关系。别生气，倒下的塔，就是宝宝大脑里新建立的神经连接。' WHERE id = 'fc07a24b-5d02-4f37-9d95-b46ab5b5f190' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, no te fíes solo de lo que ves por la ventana. Con el asistente Tiempo y ropa elige el conjunto más adecuado para el viento y la temperatura reales y sal de casa tranquila y bien equipada.', body_fr = 'Avant la promenade, ne vous fiez pas à ce que vous voyez par la fenêtre. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et à la température réels, et sortez sereine et bien équipée.', body_hi = 'सैर पर निकलते समय खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े असिस्टेंट से बाहर की असली हवा और गर्मी के लिए सबसे सही कपड़े तय कीजिए और पूरी तैयारी के साथ आराम से घर से निकलिए।', body_id = 'Saat akan jalan-jalan, jangan tertipu hanya dengan melihat dari jendela. Gunakan Cuaca dan Pakaian untuk menentukan setelan yang paling cocok dengan angin dan suhu sebenarnya di luar, lalu keluar rumah dengan nyaman dan siap.', body_ja = 'お出かけ前に、窓の外の様子にだまされないで。「天気と服装」で外の本当の風や気温にぴったりのコーデを決めて、しっかり準備して安心して出かけましょう。', body_ko = '산책 나갈 때 창밖만 보고 판단하지 마세요. 날씨와 옷차림 도우미로 실제 바람과 기온에 가장 알맞은 옷차림을 정하고, 든든하게 준비해서 편하게 나가세요.', body_nl = 'Laat je niet misleiden door een blik uit het raam als je gaat wandelen. Bepaal met de assistent Weer en kleding de beste outfit voor de echte wind en temperatuur buiten en ga goed voorbereid de deur uit.', body_pl = 'Przed spacerem nie daj się zwieść widokowi za oknem. Dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do prawdziwego wiatru i temperatury na dworze i wyjdź z domu spokojnie i przygotowana.', body_pt = 'Antes de ir passear, não se deixe enganar pelo que vê da janela. Com o assistente Tempo e Roupa, escolha a combinação mais adequada ao vento e à temperatura reais lá fora e saia de casa tranquila e bem preparada.', body_sv = 'Låt dig inte luras av att titta ut genom fönstret när ni ska ut på promenad. Med hjälpen Väder och kläder hittar du den klädsel som passar bäst för den verkliga vinden och temperaturen ute, så att ni går ut bekvämt och väl rustade.', body_vi = 'Khi chuẩn bị đi dạo, đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ. Hãy dùng Thời tiết và trang phục để chọn bộ đồ phù hợp nhất với gió và nhiệt độ thực tế bên ngoài, rồi ra khỏi nhà thật thoải mái, đầy đủ đồ dùng.', body_zh = '出门散步前，别只看窗外就被骗了。用天气与穿衣助手，根据外面真实的风力和温度确定最合适的搭配，舒舒服服、准备齐全地出门吧。' WHERE id = 'aa798243-c44e-4178-957c-647030916048' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gourmets exigentes 🥦', body_es = '¿Hoy dice que no a la comida que ayer le encantaba? Las manías con la comida a los 3 años son normales. Busca en Recetas saludables presentaciones coloridas, diferentes y divertidas.', title_fr = 'Petits gourmets difficiles 🥦', body_fr = 'Il refuse aujourd''hui le plat qu''il adorait hier ? Les caprices alimentaires des 3 ans sont normaux. Trouvez dans les Recettes saines des présentations colorées et différentes qui l''amuseront.', title_hi = 'नखरीले खाने के शौकीन 🥦', body_hi = 'कल जो खाना पसंद था, आज उसे ‘नहीं’ कहता है? 3 साल में खाने की ज़िद सामान्य है। सेहतमंद रेसिपी से उसे लुभाने वाले, रंगीन और अलग तरह से परोसने के तरीके ढूँढिए।', title_id = 'Pemilih makanan 🥦', body_id = 'Makanan yang kemarin ia suka, hari ini ditolak? Sikap pilih-pilih makanan di usia 3 tahun itu normal. Temukan sajian berwarna dan berbeda yang menyenangkan di Resep Sehat.', title_ja = 'こだわりグルメさん 🥦', body_ja = '昨日好きだった料理に、今日は「いや」？3歳の食べむらはよくあることです。「ヘルシーレシピ」から、楽しくなるようなカラフルで工夫した盛りつけを見つけましょう。', title_ko = '까다로운 미식가 🥦', body_ko = '어제 좋아하던 음식을 오늘은 싫다고 하나요? 세 살의 음식 고집은 정상이에요. 건강한 레시피에서 아이를 즐겁게 할 알록달록하고 색다른 담음새를 찾아보세요.', title_nl = 'Kieskeurige fijnproevers 🥦', body_nl = 'Zegt hij vandaag nee tegen het eten waar hij gisteren dol op was? Dwarse eetbuien horen bij 3 jaar. Zoek in Gezonde recepten kleurrijke, andere manieren van opdienen die hem vermaken.', title_pl = 'Wybredni smakosze 🥦', body_pl = 'Mówi „nie” jedzeniu, które wczoraj uwielbiał? Kaprysy jedzeniowe 3-latka są normalne. Poszukaj w Zdrowych przepisach kolorowych, ciekawych sposobów podania, które go rozbawią.', title_pt = 'Pequenos gourmets exigentes 🥦', body_pt = 'Hoje diz "não" à comida de que gostava ontem? As teimosias com a comida aos 3 anos são normais. Encontre nas Receitas Saudáveis apresentações coloridas e diferentes que o divirtam.', title_sv = 'Kräsna gourmeter 🥦', body_sv = 'Säger barnet nej i dag till maten som det älskade i går? Matnycker vid 3 år är normala. Hitta roliga, färgglada och annorlunda sätt att servera bland Hälsosamma recept.', title_vi = 'Những "thực khách" kén chọn 🥦', body_vi = 'Món hôm qua bé thích thì hôm nay lại nói "không"? Kén ăn ở tuổi lên 3 là bình thường. Hãy tìm những cách bày món nhiều màu sắc, lạ mắt và vui nhộn trong Công thức lành mạnh.', title_zh = '挑剔的小美食家 🥦', body_zh = '昨天还爱吃的东西，今天却说“不要”？3岁时的吃饭小倔强很正常。去健康食谱里找找能逗宝宝开心、色彩丰富又与众不同的摆盘方式。' WHERE id = '9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La imaginación despega 🚀', body_es = '¡Ya no solo juega, crea historias! Una caja de cartón se convierte de pronto en una nave espacial. Anota con orgullo este salto cognitivo en el Seguimiento del desarrollo y únete a su juego.', title_fr = 'L''imagination prend son envol 🚀', body_fr = 'Il ne joue plus simplement, il invente des scénarios ! Un carton se transforme en un instant en vaisseau spatial. Notez fièrement ce bond cognitif dans le Suivi de développement et rejoignez son jeu.', title_hi = 'कल्पना की उड़ान 🚀', body_hi = 'वह अब सिर्फ़ खेलता नहीं, कहानियाँ गढ़ता है! गत्ते का डिब्बा पल भर में अंतरिक्ष यान बन जाता है। इस मानसिक छलाँग को गर्व से ग्रोथ ट्रैकर में दर्ज कीजिए और उसके खेल में शामिल हो जाइए।', title_id = 'Imajinasi melambung 🚀', body_id = 'Ia tak lagi sekadar bermain, ia menyusun skenario! Kardus dalam sekejap berubah menjadi pesawat luar angkasa. Catat lompatan kognitif ini dengan bangga di Pelacak Perkembangan dan ikutlah dalam permainannya.', title_ja = '想像力、離陸中 🚀', body_ja = 'もうただ遊ぶだけでなく、ストーリーをつくっています！段ボール箱があっという間に宇宙船に。この認知の飛躍を「発達トラッカー」に誇らしく記録して、遊びに加わりましょう。', title_ko = '상상력이 날아올라요 🚀', body_ko = '이제 그냥 노는 게 아니라 시나리오를 만들어요! 종이 상자가 순식간에 우주선이 되죠. 이 인지적 도약을 성장 기록에 뿌듯하게 남기고 아이의 놀이에 함께해 주세요.', title_nl = 'De fantasie vliegt 🚀', body_nl = 'Hij speelt niet meer gewoon, hij bedenkt hele scenario''s! Een kartonnen doos is ineens een ruimteschip. Noteer deze cognitieve sprong trots in de Groeitracker en speel mee.', title_pl = 'Wyobraźnia w locie 🚀', body_pl = 'Już nie tylko się bawi, ale tworzy scenariusze! Kartonowe pudło w sekundę zmienia się w statek kosmiczny. Zapisz z dumą ten skok poznawczy w Śledzeniu rozwoju i dołącz do jego zabawy.', title_pt = 'Imaginação a voar 🚀', body_pt = 'Já não se limita a brincar: cria histórias! Uma caixa de cartão transforma-se de repente numa nave espacial. Registe com orgulho este salto cognitivo no Registo de Crescimento e entre na brincadeira.', title_sv = 'Fantasin tar flykten 🚀', body_sv = 'Barnet leker inte längre bara, det bygger upp hela scenarier! En kartong förvandlas på ett ögonblick till ett rymdskepp. Anteckna stolt det här kognitiva språnget i Utvecklingsspåraren och var med i leken.', title_vi = 'Trí tưởng tượng cất cánh 🚀', body_vi = 'Bé không chỉ chơi nữa, mà đã biết dựng kịch bản! Chiếc hộp các-tông phút chốc biến thành tàu vũ trụ. Hãy tự hào ghi lại bước nhảy vọt nhận thức này trong Theo dõi phát triển và tham gia trò chơi cùng bé.', title_zh = '想象力在飞翔 🚀', body_zh = '宝宝已经不只是在玩，而是在编剧情了！纸箱一转眼就变成了宇宙飞船。骄傲地把这次认知飞跃记在发育追踪里，也加入宝宝的游戏吧。' WHERE id = 'b755d54c-d2cb-47a2-92bb-44a36d855874' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El informe del día 🌙', body_es = 'Antes de dormir, baja las luces y hablad de qué es lo que más os ha hecho reír hoy. Estas pequeñas charlas antes de dormir afinan su capacidad de expresión.', title_fr = 'Le bilan de la journée 🌙', body_fr = 'Avant de dormir, baissez les lumières et parlez de ce qui vous a le plus fait rire aujourd''hui. Ces petites conversations du coucher affinent sa capacité à s''exprimer.', title_hi = 'दिन की रिपोर्ट 🌙', body_hi = 'सोने से पहले रोशनी धीमी कीजिए और बात कीजिए कि आज किस बात पर सबसे ज़्यादा हँसे। सोने से पहले की ये छोटी बातें उसकी अभिव्यक्ति की क्षमता को निखारती हैं।', title_id = 'Laporan hari ini 🌙', body_id = 'Sebelum tidur, redupkan lampu dan bicarakan hal yang paling membuat kalian tertawa hari ini. Obrolan kecil menjelang tidur ini mengasah kemampuannya berekspresi.', title_ja = '今日のふりかえり 🌙', body_ja = '寝る前に明かりを落として、今日いちばん笑ったことについて話しましょう。寝る前のこんな小さなおしゃべりが、表現する力をみがいてくれます。', title_ko = '오늘의 보고 시간 🌙', body_ko = '자기 전에 불을 낮추고 오늘 무엇에 가장 많이 웃었는지 이야기해 보세요. 이런 짧은 잠자리 대화가 표현력을 키워 줘요.', title_nl = 'Verslag van de dag 🌙', body_nl = 'Dim voor het slapengaan de lichten en praat over waar jullie vandaag het hardst om hebben gelachen. Deze kleine gesprekjes voor het slapen scherpen zijn uitdrukkingsvermogen.', title_pl = 'Podsumowanie dnia 🌙', body_pl = 'Przed snem przygaś światła i porozmawiajcie o tym, z czego najbardziej się dziś śmialiście. Te krótkie rozmowy przed snem rozwijają jego umiejętność wyrażania się.', title_pt = 'O relatório do dia 🌙', body_pt = 'Antes de dormir, baixe as luzes e conversem sobre aquilo de que mais se riram hoje. Estas pequenas conversas antes de dormir afinam a capacidade de expressão dele.', title_sv = 'Dagens rapport 🌙', body_sv = 'Dämpa ljuset före läggdags och prata om vad ni skrattade mest åt i dag. De här små samtalen före sömnen vässar barnets förmåga att uttrycka sig.', title_vi = 'Tổng kết ngày 🌙', body_vi = 'Trước khi ngủ, hãy giảm đèn và cùng bé kể xem hôm nay điều gì khiến hai mẹ con cười nhiều nhất. Những cuộc trò chuyện nhỏ trước giờ ngủ này giúp bé rèn luyện khả năng diễn đạt.', title_zh = '今日小结 🌙', body_zh = '睡前把灯光调暗，聊聊今天最让你们开怀大笑的事。这些睡前的小对话，会让宝宝的表达能力越来越强。' WHERE id = 'ef6fe3c1-b830-477f-93ee-842f8b450ab9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Corretea por casa y se niega a meterse en la cama. Pide ayuda a papá. Cuando lo levanta en el aire y lo hace volar como un avión, las carcajadas llenan la habitación y toda la agresividad física acumulada desaparece en segundos con el sudor.', body_fr = 'Il court dans la maison et refuse d''aller au lit. Appelez papa en renfort. Quand il le soulève pour un vol en avion, les éclats de rire remplissent la pièce et toute l''agressivité physique accumulée s''évacue en quelques secondes.', body_hi = 'घर में दौड़ता है और बिस्तर में जाने से मना करता है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ की उड़ान कराते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक गुस्सा पसीने के साथ सेकंडों में गायब हो जाता है।', body_id = 'Ia berlarian di rumah dan menolak naik ke tempat tidur. Panggil Ayah untuk membantu. Saat Ayah mengangkatnya tinggi dan mengajaknya ''terbang naik pesawat'', tawa memenuhi kamar dan semua ketegangan fisik yang menumpuk lenyap dalam hitungan detik bersama keringat.', body_ja = '家の中を走りまわって、ベッドに入るのをいやがります。パパに助けを求めましょう。パパが子どもを持ち上げて飛行機のように飛ばすと、部屋は笑い声でいっぱいになり、たまっていた体のイライラも汗と一緒にあっという間に消えていきます。', body_ko = '집 안을 뛰어다니며 침대에 들어가길 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 번쩍 들어 비행기를 태우면 웃음소리가 방을 채우고, 쌓인 몸의 공격성이 땀과 함께 몇 초 만에 사라져요.', body_nl = 'Hij rent door het huis en weigert in bed te gaan. Roep papa te hulp. Als hij hem optilt voor een vliegtuigvlucht, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke agressie zwetend in een paar seconden.', body_pl = 'Biega po domu i nie chce iść do łóżka. Wezwij tatę na pomoc. Gdy podniesie go w górę na „lot samolotem”, śmiech wypełni pokój, a całe nagromadzone napięcie zniknie w kilka sekund.', body_pt = 'Corre pela casa e recusa ir para a cama. Chame o pai para ajudar. Quando ele o levanta no ar e faz voos de avião, as gargalhadas enchem o quarto e toda a agressividade física acumulada desaparece em segundos, a suar.', body_sv = 'Barnet springer runt hemma och vägrar gå och lägga sig. Kalla på pappa. När han lyfter upp barnet i luften och flyger flygplan fylls rummet av skratt, och all ansamlad fysisk ilska försvinner på några sekunder i form av svett.', body_vi = 'Bé chạy khắp nhà và không chịu lên giường. Hãy gọi bố đến giúp. Khi bố nhấc bé lên cao "bay như máy bay", tiếng cười sẽ ngập tràn căn phòng và mọi năng lượng dồn nén sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', body_zh = '在家里跑来跑去，就是不肯上床。叫爸爸来帮忙吧。当爸爸把宝宝举高高“开飞机”时，笑声充满房间，积攒的所有身体上的躁动几秒钟内就随着汗水消失了。' WHERE id = '56159a04-f4fe-4e35-a3dd-8bcc4853f3c9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dirección de escena a las 6 de la mañana 🎬', body_es = 'Tú todavía duermes, pero él ya está de pie junto a tu cabeza: «¡Tú eres el oso y yo el conejo!». Medio dormida, haz tus ruiditos y representa tu papel en este teatro absurdo. A veces la maternidad exige la mejor actuación.', title_fr = 'Mise en scène à 6 h du matin 🎬', body_fr = 'Vous dormez encore, mais il est planté au-dessus de votre tête : « Toi, tu es l''ours, moi le lapin ! » À moitié endormie, grognez et jouez votre rôle dans ce théâtre absurde. Être maman demande parfois les meilleurs talents d''actrice.', title_hi = 'सुबह 6 बजे निर्देशन 🎬', body_hi = 'आप अभी नींद में हैं, पर वह आपके सिर के पास खड़ा है: ‘तुम भालू बनो, मैं खरगोश!’ आधी नींद में कुरकुरी आवाज़ें निकालते हुए इस बेतुके नाटक में अपना किरदार निभाइए। माँ बनने में कभी-कभी सबसे अच्छी अदाकारी चाहिए।', title_id = 'Sutradara jam 6 pagi 🎬', body_id = 'Anda masih tidur, tapi ia sudah berdiri di samping kepala Anda: ''Mama jadi beruang, aku jadi kelinci!'' Dalam keadaan setengah mengantuk, mainkan peran Anda di teater absurd ini sambil menggeram. Menjadi ibu kadang butuh akting terbaik.', title_ja = '朝6時の監督さん 🎬', body_ja = 'あなたはまだ夢の中なのに、この子は頭の上に立って「ママはクマね、ぼくはウサギ！」。寝ぼけながらもガオーと声を出して、このおかしな劇で役を演じましょう。ママ業には、ときに最高の演技力が必要です。', title_ko = '새벽 6시의 감독님 🎬', body_ko = '엄마는 아직 자는데 머리맡에 서서 ''엄마는 곰, 나는 토끼!''라고 하나요? 비몽사몽 으르렁 소리를 내며 이 엉뚱한 연극에서 역할을 맡아 주세요. 엄마 노릇엔 가끔 최고의 연기력이 필요하죠.', title_nl = 'Regisseur om 6 uur ''s ochtends 🎬', body_nl = 'Jij slaapt nog, maar hij staat al boven je hoofd: ''Jij bent de beer, ik ben het konijn!'' Speel half slapend je rol in dit absurde theater en maak bromgeluidjes. Moederschap vraagt soms om je beste acteerwerk.', title_pl = 'Reżyseria o 6 rano 🎬', body_pl = 'Ty jeszcze śpisz, a on stoi nad twoją głową: „Ty bądź niedźwiedziem, a ja zajączkiem!”. Na wpół śpiąca pomrucz i zagraj swoją rolę w tym absurdalnym teatrze. Macierzyństwo czasem wymaga najlepszego aktorstwa.', title_pt = 'Realizador às 6 da manhã 🎬', body_pt = 'Ainda está a dormir, mas ele já está ao seu lado: "Tu és o urso, eu sou o coelho!" Meio a dormir, faça uns barulhinhos e cumpra o seu papel neste teatro absurdo. A maternidade às vezes exige a melhor representação.', title_sv = 'Regissör klockan 6 på morgonen 🎬', body_sv = 'Du sover fortfarande, men barnet står redan vid ditt huvud: ”Du är björn, jag är kanin!” Spela din roll i den absurda teatern halvsovande och med knastrande ljud. Moderskap kräver ibland de bästa skådespelarinsatserna.', title_vi = 'Đạo diễn lúc 6 giờ sáng 🎬', body_vi = 'Mẹ vẫn đang ngủ, nhưng bé đã đứng ngay trên đầu: "Mẹ làm gấu, con làm thỏ!". Trong lúc còn ngái ngủ, hãy gầm gừ và nhập vai trong vở kịch ngộ nghĩnh này. Làm mẹ đôi khi đòi hỏi tài diễn xuất đỉnh cao nhất.', title_zh = '早上6点当导演 🎬', body_zh = '你还在睡，宝宝却站在你头边：“你当熊，我当兔子！”半睡半醒地发出咔嚓咔嚓的声音，在这出荒诞剧里演好你的角色吧。当妈妈，有时需要最好的演技。' WHERE id = '69ac9098-fc9c-4474-aa9d-090c0c3f7cdf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La complicidad de la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie. Entra en la Comunidad Anacan y limítate a leer. Ver que otras madres sienten el mismo cansancio te hace sentir «no estoy sola», y esa es la mejor terapia.', title_fr = 'La complicité de la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie de rien expliquer à personne. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir la même fatigue chez d''autres mamans donne le sentiment de ne pas être seule, c''est la meilleure thérapie.', title_hi = 'कम्युनिटी का अपनापन 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। दूसरी माँओं की मिलती-जुलती थकान देखकर ‘मैं अकेली नहीं हूँ’ का एहसास होता है, यही सबसे अच्छी थेरेपी है।', title_id = 'Teman curhat di komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat ibu-ibu lain merasakan lelah yang sama menumbuhkan rasa ''aku tidak sendirian'', dan itu terapi terbaik.', title_ja = 'コミュニティという心の友 💬', body_ja = 'とても疲れていて、誰にも何も説明したくない。そんなときはAnacanコミュニティを開いて、読むだけにしましょう。ほかのママたちの同じような疲れを見ると「ひとりじゃない」と感じられて、いちばんのセラピーになります。', title_ko = '커뮤니티라는 단짝 💬', body_ko = '너무 지쳐서 누구에게도 아무것도 설명하고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들의 비슷한 피로를 보면 ''나만 그런 게 아니구나'' 싶어 최고의 치료가 돼요.', title_nl = 'Vertrouwen in de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen. Ga naar de Anacan Community en lees alleen mee. Zien dat andere mama''s net zo moe zijn geeft je het gevoel ''ik ben niet de enige'' en dat is de beste therapie.', title_pl = 'Zaufanie Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć. Wejdź do Społeczności Anacan i tylko czytaj. Widok podobnego zmęczenia u innych mam daje poczucie „nie jestem sama” i jest najlepszą terapią.', title_pt = 'A cumplicidade da comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém. Entre na Comunidade Anacan e limite-se a ler. Ver o cansaço parecido de outras mães dá a sensação de "não estou sozinha", e essa é a melhor terapia.', title_sv = 'Gemenskapens förtrolighet 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon. Gå in i Anacan Community och bara läs. Att se andra mammors liknande trötthet ger känslan ”jag är inte ensam” och blir den bästa terapin.', title_vi = 'Tâm sự trong Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích gì với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác cũng mệt mỏi giống mình sẽ mang lại cảm giác "mình không đơn độc", đó là liệu pháp tốt nhất.', title_zh = '社区里的知心话 💬', body_zh = '累坏了，什么都不想跟任何人解释？进入Anacan社区，只当个读者就好。看到其他妈妈也有同样的疲惫，会让你觉得“我不是一个人”，这就是最好的疗愈。' WHERE id = 'aa6e4c45-6848-4e91-8836-f55617de9313' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer digital del silencio 🤫', body_es = '¡Por fin se ha dormido! El silencio que cae sobre la casa es tan profundo que se te taponan los oídos. Activa el Medidor de sonido y, mirando los 0-10 decibelios de la pantalla, siente cómo tu cerebro se recupera poco a poco.', title_fr = 'Le plaisir numérique du silence 🤫', body_fr = 'Il dort enfin ! Le silence qui tombe sur la maison est si profond qu''il vous bourdonne aux oreilles. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau récupérer peu à peu.', title_hi = 'खामोशी का डिजिटल सुकून 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी इतनी गहरी है कि कान सुन्न हो जाते हैं। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे ठीक हो रहा है।', title_id = 'Nikmatnya hening secara digital 🤫', body_id = 'Akhirnya ia tertidur! Keheningan di rumah begitu dalam sampai telinga Anda terasa berdenging. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan secara visual bagaimana otak Anda perlahan pulih.', title_ja = '静けさをデジタルで味わう 🤫', body_ja = 'やっと寝てくれました！家に広がる静けさは、耳がツーンとするほど深いですね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ回復していくのを目で感じてみましょう。', title_ko = '고요의 디지털 즐거움 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 너무 깊어 귀가 멍할 정도죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 회복되는 걸 눈으로 느껴 보세요.', title_nl = 'Het digitale genot van stilte 🤫', body_nl = 'Hij slaapt eindelijk! De stilte in huis is zo diep dat je oren ervan suizen. Zet de Geluidsmeter aan, kijk naar de 0-10 decibel op het scherm en voel hoe je brein langzaam herstelt.', title_pl = 'Cyfrowa rozkosz ciszy 🤫', body_pl = 'W końcu zasnął! Cisza, która zapadła w domu, jest tak głęboka, że aż dzwoni w uszach. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli dochodzi do siebie.', title_pt = 'O prazer digital do silêncio 🤫', body_pt = 'Finalmente adormeceu! O silêncio que cai sobre a casa é tão profundo que até lhe zumbem os ouvidos. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta visualmente o seu cérebro a recuperar devagarinho.', title_sv = 'Tystnadens digitala njutning 🤫', body_sv = 'Äntligen har barnet somnat! Tystnaden som sänker sig över hemmet är så djup att det slår lock för öronen. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du visuellt hur hjärnan sakta återhämtar sig.', title_vi = 'Niềm vui số của sự yên lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Sự tĩnh lặng bao trùm căn nhà sâu đến mức tai mẹ như ù đi. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần hồi phục.', title_zh = '安静的数字享受 🤫', body_zh = '宝宝终于睡着了！家里一下子安静得连耳朵都有点嗡嗡的。打开分贝仪，看着屏幕上0-10分贝的数字，直观地感受大脑正在一点点恢复。' WHERE id = '7b3c2751-f23f-4467-abdf-9463831a86cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡En el súper conduzco yo! 🛒', body_es = 'Quiere empujar él solo el carro del súper y acabáis chocando con las estanterías. Para no romper su voluntad, empujad el carro juntos. Y para no olvidar nada, ten abierta la Lista de la compra de la app.', title_fr = '« C''est moi qui pousse ! » au supermarché 🛒', body_fr = 'Il veut absolument pousser lui-même le chariot, et vous finissez par heurter les rayons. Pour ne pas briser sa volonté, poussez le chariot ensemble. Et contre les oublis, gardez ouverte la Liste de courses de l''application.', title_hi = 'बाज़ार में ‘मैं चलाऊँगा!’ 🛒', body_hi = 'शॉपिंग ट्रॉली उसे खुद ही चलानी है, और नतीजा आप रैक से टकरा जाती हैं। उसकी इच्छा को ठेस न पहुँचे, इसलिए ट्रॉली साथ मिलकर चलाइए। और भूलने से बचने के लिए ऐप की शॉपिंग लिस्ट खुली रखिए।', title_id = '''Aku yang dorong!'' di supermarket 🛒', body_id = 'Ia bersikeras mendorong troli belanja sendiri, dan akhirnya kalian menabrak rak. Agar kemauannya tidak patah, dorong troli bersama-sama. Untuk melawan lupa, biarkan Daftar Belanja di aplikasi tetap terbuka.', title_ja = 'スーパーで「ぼくが押す！」 🛒', body_ja = 'ショッピングカートを絶対に自分で押したがり、結局棚にぶつかってしまう。意志をくじかないように、一緒にカートを押しましょう。買い忘れ防止には、アプリの「買い物リスト」を開いておいてね。', title_ko = '마트에서 ''내가 밀 거야!'' 🛒', body_ko = '마트 카트를 꼭 자기가 밀겠다고 해서 결국 선반에 부딪히나요? 의지를 꺾지 않도록 카트를 함께 밀어 보세요. 깜빡하지 않게 앱의 쇼핑 목록은 열어 두시고요.', title_nl = '''Ik duw!'' in de supermarkt 🛒', body_nl = 'Hij wil per se zelf het boodschappenkarretje duwen en jullie botsen tegen de schappen. Duw het karretje samen, zodat je zijn wil niet breekt. En tegen vergeetachtigheid: houd het Boodschappenlijstje in de app open.', title_pl = 'Ja będę pchać wózek! 🛒', body_pl = 'Koniecznie chce sam pchać wózek w sklepie, a w efekcie wpadacie na półki. Żeby nie łamać jego woli, pchajcie wózek razem. A na zapominalstwo trzymaj otwartą Listę zakupów w aplikacji.', title_pt = '"Eu é que conduzo!" no supermercado 🛒', body_pt = 'Quer mesmo empurrar sozinho o carrinho do supermercado e acabam por bater nas prateleiras. Para não quebrar a vontade dele, empurrem o carrinho juntos. E contra os esquecimentos, mantenha aberta a Lista de Compras da app.', title_sv = '”Jag ska köra!” i butiken 🛒', body_sv = 'Barnet vill absolut köra kundvagnen själv och till slut krockar ni med hyllorna. För att inte knäcka barnets vilja, låt er köra vagnen tillsammans. Och mot glömskan, ha Inköpslistan i appen öppen.', title_vi = '"Con đẩy xe!" ở siêu thị 🛒', body_vi = 'Bé nhất quyết đòi tự đẩy xe đẩy siêu thị và kết quả là đâm vào các kệ hàng. Để không làm tổn thương ý chí của bé, hãy cùng bé đẩy xe. Còn để khỏi quên đồ, hãy mở sẵn Danh sách mua sắm trong ứng dụng.', title_zh = '超市里：“我来推！”🛒', body_zh = '非要自己推购物车，结果你们一路撞到货架上。为了不挫伤宝宝的意志，就一起推吧。至于健忘，记得让应用里的购物清单一直开着。' WHERE id = '7d093b24-909b-4f92-b3df-fe627f2322c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Completa las frases a medias 🗣️', body_es = '¿Cuando olvida una palabra hace gestos con las manos y espera que la adivines? Fíjate en su alivio cuando dices: «Ah, ¿dices la pelota?». Su vocabulario crece, solo que su cerebro va más rápido que su lengua.', title_fr = 'Finir ses phrases 🗣️', body_fr = 'Quand il oublie un mot, il fait des gestes et attend que vous trouviez ? Observez son soulagement quand vous dites « Ah, tu veux dire le ballon ? ». Son vocabulaire grandit, c''est juste que son cerveau va plus vite que sa langue.', title_hi = 'अधूरे वाक्य पूरे कीजिए 🗣️', body_hi = 'कोई शब्द भूल जाने पर हाथ से इशारे करके आपके समझने का इंतज़ार करता है? जब आप कहती हैं, ‘अच्छा, गेंद कह रहे हो?’, उस राहत के पल को देखिए। उसकी शब्दावली बढ़ रही है, बस उसका दिमाग ज़ुबान से तेज़ चलता है।', title_id = 'Lengkapi kalimatku 🗣️', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan dan menunggu Anda menebak? Perhatikan rasa leganya saat Anda berkata ''Ooh, maksudmu bola?''. Kosakatanya bertambah, hanya saja otaknya bekerja lebih cepat daripada lidahnya.', title_ja = '途中の言葉を当ててあげよう 🗣️', body_ja = '言葉を忘れると、手でジェスチャーをしてあなたが当てるのを待っている？「ああ、ボールのこと？」と言ったときの、ほっとした顔を見てあげて。語彙は増えています。ただ、頭の回転が口より速いだけなんです。', title_ko = '끝맺지 못한 문장 채워 주기 🗣️', body_ko = '단어가 생각 안 나면 손짓하며 엄마가 맞혀 주길 기다리나요? ''아, 공 말하는 거야?'' 했을 때 안도하는 그 순간을 보세요. 어휘는 늘고 있어요, 그저 뇌가 혀보다 빠를 뿐이에요.', title_nl = 'Maak de zin af 🗣️', body_nl = 'Vergeet hij een woord en maakt hij gebaren tot jij het raadt? Kijk naar die opluchting als je zegt: ''Ah, bedoel je de bal?'' Zijn woordenschat groeit, zijn brein werkt alleen sneller dan zijn tong.', title_pl = 'Dokończ moje zdanie 🗣️', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami i czeka, aż zgadniesz? Zobacz tę ulgę, gdy mówisz: „Aaa, chodzi ci o piłkę?”. Słownictwo mu rośnie, po prostu mózg pracuje szybciej niż język.', title_pt = 'Completar frases a meio 🗣️', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos e espera que a adivinhe? Repare no alívio dele quando diz "Ah, queres dizer a bola?". O vocabulário está a crescer, o cérebro só trabalha mais depressa do que a língua.', title_sv = 'Fyll i de halva meningarna 🗣️', body_sv = 'Gör barnet tecken med händerna när det glömmer ett ord och väntar på att du ska gissa? Lägg märke till lättnaden när du säger ”Jaha, du menar bollen?”. Ordförrådet växer, hjärnan arbetar bara snabbare än tungan.', title_vi = 'Hoàn thành câu nói dở 🗣️', body_vi = 'Khi quên một từ, bé ra hiệu bằng tay và chờ mẹ đoán? Hãy để ý khoảnh khắc bé nhẹ nhõm khi mẹ nói: "À, con muốn nói quả bóng hả?". Vốn từ của bé đang lớn dần, chỉ là não bé chạy nhanh hơn lưỡi thôi.', title_zh = '帮宝宝补完半句话 🗣️', body_zh = '忘了某个词时，就用手比画，等你猜出来？留意你说“哦，你是说球？”时宝宝那如释重负的一刻。词汇量在增长，只是大脑转得比嘴巴还快。' WHERE id = '803c4a83-8bb9-4a65-a6e0-a757e4e816cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Entre cuatro paredes su energía se convierte en agresividad. Haga el tiempo que haga, abrígale según Tiempo y ropa y sácale fuera sin falta. Tocar la tierra y recoger hojas calma su sistema nervioso al instante.', body_fr = 'Entre quatre murs, son énergie se transforme en agressivité. Quel que soit le temps, équipez-le comme il faut avec Météo et tenue et sortez-le absolument. Toucher la terre et ramasser des feuilles apaise immédiatement son système nerveux.', body_hi = 'चार दीवारों के अंदर उसकी ऊर्जा गुस्से में बदल जाती है। मौसम कैसा भी हो, सही कपड़े पहनाकर उसे बाहर ज़रूर ले जाइए। मिट्टी छूना, पत्ते इकट्ठा करना उसके तंत्रिका तंत्र को तुरंत शांत कर देता है।', body_id = 'Di dalam empat dinding, energinya berubah menjadi agresi. Apa pun cuacanya, kenakan pakaian yang sesuai dan ajak ia keluar. Menyentuh tanah dan mengumpulkan daun langsung menenangkan sistem sarafnya.', body_ja = '4つの壁の中では、エネルギーがイライラに変わってしまいます。天気や服装に関係なく、しっかり準備して必ず外へ連れ出しましょう。土にさわったり、葉っぱを集めたりすると、神経がすぐに落ち着きます。', body_ko = '네 벽 안에서 에너지가 공격성으로 바뀌나요? 날씨가 어떻든 알맞게 챙겨 입혀 꼭 밖에 데리고 나가세요. 흙을 만지고 나뭇잎을 줍는 것만으로도 신경계가 바로 진정돼요.', body_nl = 'Tussen vier muren wordt zijn energie agressie. Kleed hem passend aan, ongeacht het weer, en ga hoe dan ook naar buiten. Aarde aanraken en blaadjes verzamelen kalmeert zijn zenuwstelsel meteen.', body_pl = 'W czterech ścianach jego energia zamienia się w agresję. Bez względu na pogodę ubierz go odpowiednio i koniecznie wyjdźcie na dwór. Dotykanie ziemi i zbieranie liści od razu uspokaja jego układ nerwowy.', body_pt = 'Entre quatro paredes, a energia dele transforma-se em agressividade. Seja qual for o tempo, vista-o de forma adequada e leve-o sem falta para a rua. Tocar na terra e apanhar folhas acalma logo o sistema nervoso dele.', body_sv = 'Mellan fyra väggar blir barnets energi till ilska. Oavsett väder, klä barnet rätt och se till att ni kommer ut. Att röra vid jorden och samla löv lugnar nervsystemet direkt.', body_vi = 'Ở trong bốn bức tường, năng lượng của bé biến thành sự hung hăng. Dù thời tiết thế nào, hãy chuẩn bị trang phục phù hợp và nhất định đưa bé ra ngoài. Chạm vào đất, nhặt lá cây giúp hệ thần kinh của bé dịu lại ngay lập tức.', body_zh = '被关在四面墙里，精力就会变成攻击性。不管天气如何，穿戴合适，一定要带宝宝出门。摸摸泥土、捡捡树叶，能让宝宝的神经系统马上平静下来。' WHERE id = '5625eb93-64b3-45e9-9346-29a2c6af885f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder místico del susurro 🌙', body_es = 'Tienes las cuerdas vocales cansadas de leer cuentos. Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, muy bajito, lo que ha pasado durante el día. Susurrar es la forma más relajante de preparar el cerebro para dormir.', title_fr = 'Le pouvoir mystérieux du chuchotement 🌙', body_fr = 'Votre voix est fatiguée d''avoir lu des histoires. Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et chuchotez-lui à l''oreille, tout bas, ce qui s''est passé dans la journée. Le chuchotement est la façon la plus apaisante de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाहट की रहस्यमयी ताकत 🌙', body_hi = 'कहानियाँ पढ़ते-पढ़ते आपका गला थक गया है। कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे सुकून भरा तरीका है।', title_id = 'Kekuatan ajaib bisikan 🌙', body_id = 'Pita suara Anda lelah membacakan dongeng. Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan kejadian hari ini ke telinganya dengan suara sangat pelan. Bisikan adalah cara paling menenangkan untuk menyiapkan otak tidur.', title_ja = 'ささやきのふしぎな力 🌙', body_ja = '絵本の読み聞かせで声が疲れてしまいましたか？部屋の明かりをすべて消しましょう。そばに横になって、今日あったことを耳もとでとても小さな声でささやいてあげて。ささやき声は、脳を眠りへ導くいちばん心落ち着く方法です。', title_ko = '속삭임의 신비한 힘 🌙', body_ko = '동화를 읽어 주느라 목이 지쳤나요? 방의 불을 모두 끄세요. 옆에 누워 오늘 있었던 일을 아주 낮은 목소리로 귓가에 속삭여 주세요. 속삭임은 뇌를 잠들 준비시키는 가장 차분한 방법이에요.', title_nl = 'De mystieke kracht van fluisteren 🌙', body_nl = 'Je stembanden zijn moe van het voorlezen. Doe alle lichten in de kamer uit. Ga naast hem liggen en fluister heel zachtjes in zijn oor wat er vandaag is gebeurd. Fluisteren is de meest rustgevende manier om het brein klaar te maken voor de slaap.', title_pl = 'Tajemnicza moc szeptu 🌙', body_pl = 'Twoje struny głosowe są zmęczone czytaniem bajek. Zgaś całkowicie światła w pokoju. Połóż się obok i bardzo cicho wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia. Szept to najbardziej kojący sposób, by przygotować mózg do snu.', title_pt = 'O poder místico do sussurro 🌙', body_pt = 'As suas cordas vocais estão cansadas de ler histórias. Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, o que aconteceu durante o dia. Sussurrar é a forma mais calmante de preparar o cérebro para o sono.', title_sv = 'Viskningens mystiska kraft 🌙', body_sv = 'Stämbanden är trötta av sagoläsning. Släck alla lampor i rummet. Lägg dig bredvid barnet och viska mycket tyst i örat om det som hänt under dagen. Viskningar är det mest lugnande sättet att förbereda hjärnan för sömn.', title_vi = 'Sức mạnh huyền bí của lời thì thầm 🌙', body_vi = 'Giọng mẹ đã mỏi vì đọc truyện. Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ vào tai bé về những gì đã xảy ra trong ngày. Thì thầm là cách êm dịu nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话的神奇力量 🌙', body_zh = '讲故事讲得嗓子都累了。把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，在宝宝耳边悄悄讲今天发生的事。悄悄话是帮大脑准备入睡最能让人平静的方式。' WHERE id = 'd33d70dc-19c8-4087-8ed8-270685911bfd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un ser asombroso 🎈', body_es = 'En un camino tan largo hay muchas cosas que te asombran. ¡Por ejemplo, que la palabra que aprendió ayer la use hoy en una frase filosófica! Estos días no se repetirán.', title_fr = 'Un être extraordinaire 🎈', body_fr = 'Sur un si long chemin, il y a tant de choses qui émerveillent. Par exemple, utiliser aujourd''hui dans une phrase philosophique un mot appris hier ! Ces jours-là ne reviendront pas.', title_hi = 'हैरान कर देने वाला नन्हा इंसान 🎈', body_hi = 'इतने लंबे सफ़र में हैरान होने लायक बहुत कुछ है। जैसे, कल सीखा शब्द आज किसी दार्शनिक वाक्य में इस्तेमाल करना! ये दिन दोबारा नहीं आएँगे।', title_id = 'Sosok yang menakjubkan 🎈', body_id = 'Dalam perjalanan sepanjang ini, ada begitu banyak hal yang membuat takjub. Misalnya, kata yang baru ia pelajari kemarin, hari ini ia pakai dalam kalimat yang filosofis! Hari-hari ini tidak akan terulang.', title_ja = 'おどろきの存在 🎈', body_ja = 'この長い道のりには、おどろくことがたくさんあります。たとえば、昨日覚えた言葉を今日は哲学的な文で使ってみせるなんて！こんな日々は二度と戻ってきません。', title_ko = '놀라운 존재 🎈', body_ko = '이 긴 여정에는 놀랄 일이 참 많아요. 어제 배운 단어를 오늘 철학적인 문장에 쓰는 것처럼요! 이런 날들은 다시 오지 않아요.', title_nl = 'Een verbazingwekkend wezentje 🎈', body_nl = 'Op zo''n lange weg is er zoveel om je over te verbazen. Bijvoorbeeld dat hij een woord dat hij gisteren leerde vandaag in een filosofische zin gebruikt! Deze dagen komen niet terug.', title_pl = 'Niesamowita istotka 🎈', body_pl = 'Na tak długiej drodze jest wiele powodów do zachwytu. Na przykład gdy słowo poznane wczoraj dziś używa w filozoficznym zdaniu! Te dni się nie powtórzą.', title_pt = 'Um ser surpreendente 🎈', body_pt = 'Num caminho tão longo há muito que nos surpreende. Por exemplo, usar hoje numa frase filosófica a palavra que aprendeu ontem! Estes dias não se repetem.', title_sv = 'En fantastisk varelse 🎈', body_sv = 'På den här långa resan finns så mycket att förundras över. Till exempel när barnet i dag använder ett ord det lärde sig i går i en filosofisk mening! De här dagarna kommer inte tillbaka.', title_vi = 'Một sinh linh kỳ diệu 🎈', body_vi = 'Trên chặng đường dài này có biết bao điều đáng ngạc nhiên. Chẳng hạn như từ bé mới học hôm qua, hôm nay đã được dùng trong một câu nói đầy triết lý! Những ngày này sẽ không bao giờ lặp lại.', title_zh = '惊喜满满的小人儿 🎈', body_zh = '这么长的路上，有太多值得惊叹的事。比如昨天刚学会的词，今天就用在一句充满哲理的话里！这样的日子不会再重来。' WHERE id = 'e578603f-02ec-4734-b19f-2d0ca949a8e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mamá que comes chocolate a escondidas detrás del armario de la cocina: esa glucosa te la mereces. ¡No te culpes! Para aguantar esa energía loca necesitas recargarte. Respira y sigue masticando.', body_fr = 'Maman qui mange du chocolat en cachette derrière le placard de la cuisine, ce glucose, vous l''avez mérité. Ne vous jugez pas ! Pour supporter cette énergie folle, vous devez recharger vos batteries. Respirez et continuez de croquer.', body_hi = 'रसोई की अलमारी के पीछे छिपकर चॉकलेट खाने वाली माँ, वह ग्लूकोज़ आपका हक है। खुद को दोष मत दीजिए! उस धमाकेदार ऊर्जा को झेलने के लिए आपका चार्ज रहना ज़रूरी है। साँस लीजिए और चबाते रहिए।', body_id = 'Ibu yang diam-diam makan cokelat di balik lemari dapur, glukosa itu hakmu. Jangan menyalahkan diri! Untuk mengimbangi energinya yang luar biasa, kamu wajib mengisi ulang tenaga. Tarik napas dan lanjutkan mengunyah.', body_ja = 'キッチンの棚のかげで、こっそりチョコを食べているママへ。そのブドウ糖はあなたの権利です。自分を責めないで！あのすごいエネルギーに付き合うには、あなたの充電が欠かせません。深呼吸して、そのまま食べ続けて。', body_ko = '부엌 찬장 뒤에서 몰래 초콜릿을 먹는 엄마, 그 당분은 엄마 몫이에요. 자책하지 마세요! 그 넘치는 에너지를 감당하려면 엄마도 충전해야 해요. 숨 한번 쉬고 계속 드세요.', body_nl = 'Mama die stiekem achter het keukenkastje chocola eet: die glucose heb je verdiend. Veroordeel jezelf niet! Om die gekke energie bij te houden moet jij opgeladen zijn. Haal adem en kauw rustig verder.', body_pl = 'Mamo, która po kryjomu jesz czekoladę za szafką w kuchni: ta glukoza ci się należy. Nie obwiniaj się! Żeby wytrzymać tę szaloną energię, musisz się naładować. Oddychaj i jedz dalej.', body_pt = 'Mãe que come chocolate às escondidas atrás do armário da cozinha: essa glicose é sua por direito. Não se culpe! Para aguentar aquela energia louca, precisa de recarregar. Respire e continue a mastigar.', body_sv = 'Mamma som i smyg äter choklad bakom köksskåpet: den glukosen har du rätt till. Döm inte dig själv! För att orka med den galna energin måste du ladda batterierna. Andas och fortsätt tugga.', body_vi = 'Mẹ ơi, mẹ đang lén ăn sô-cô-la sau tủ bếp, lượng đường đó là phần của mẹ. Đừng tự trách mình! Để theo kịp nguồn năng lượng "điên rồ" ấy, mẹ cần được sạc pin. Hít thở và cứ nhai tiếp đi.', body_zh = '躲在厨房柜子后面偷偷吃巧克力的妈妈，那点糖是你应得的。别责怪自己！要扛住那股疯狂的能量，你得先给自己充好电。深呼吸，继续嚼吧。' WHERE id = '0cdb7f22-d990-414a-b36e-54d6d47e1b4f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Él es el protagonista del cuento 🪄', body_es = 'Esta noche, en Cuentos inteligentes, ponle al héroe el nombre de tu peque. Cuenta que el personaje no se lavó los dientes y luego se arrepintió, y transmítele valores de forma indirecta.', title_fr = 'Le héros du Conte intelligent, c''est lui 🪄', body_fr = 'Ce soir, dans les Contes intelligents, donnez directement au héros le prénom de votre enfant. Racontez que le personnage ne s''est pas brossé les dents et l''a regretté ensuite, pour transmettre les valeurs de façon indirecte.', title_hi = 'स्मार्ट कहानी का हीरो वही 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में हीरो का नाम सीधे अपने बच्चे के नाम पर रखिए। कहानी के किरदार के दाँत ब्रश न करने और बाद में पछताने की बात सुनाकर, अच्छी बातें घुमा-फिराकर सिखाइए।', title_id = 'Ia sendiri tokoh di Dongeng Pintar 🪄', body_id = 'Malam ini di Dongeng Pintar, beri tokoh utamanya nama anak Anda. Ceritakan bahwa tokoh dalam dongeng itu juga tidak menggosok gigi lalu menyesal, dan tanamkan nilai-nilai secara tidak langsung.', title_ja = 'スマートおはなしの主人公 🪄', body_ja = '今夜は「スマートおはなし」で、主人公にお子さんの名前をつけましょう。お話の主人公も歯みがきをしなくて後悔した、という話を通して、大切なことをさりげなく伝えましょう。', title_ko = '스마트 동화 속 주인공은 아이 🪄', body_ko = '오늘 저녁 스마트 동화에서 주인공 이름을 아이 이름으로 지어 보세요. 이야기 속 주인공도 이를 닦지 않았다가 후회했다고 들려주며 가치를 자연스럽게 전해 주세요.', title_nl = 'Zelf de held van het Slimme sprookje 🪄', body_nl = 'Geef de held vanavond in Slimme sprookjes de naam van je kind. Vertel dat het personage zijn tanden niet poetste en daar later spijt van had, en breng zo op een indirecte manier waarden over.', title_pl = 'Bohater Mądrej bajki 🪄', body_pl = 'Dziś wieczorem w Mądrych bajkach nazwij bohatera imieniem twojego dziecka. Opowiadając, że postać z bajki też nie umyła zębów, a potem żałowała, przekazuj wartości w pośredni sposób.', title_pt = 'Ele é o herói das Histórias Inteligentes 🪄', body_pt = 'Esta noite, dê ao herói das Histórias Inteligentes o nome do seu filho. Conte que a personagem também não lavou os dentes e depois se arrependeu, e transmita valores de forma indireta.', title_sv = 'Barnet i sin egen smarta saga 🪄', body_sv = 'Ge hjälten i kvällens Smarta sagor barnets eget namn. Berätta att sagofiguren inte heller borstade tänderna och sedan ångrade sig, så förmedlar du värderingar på ett indirekt sätt.', title_vi = 'Bé là nhân vật chính trong truyện 🪄', body_vi = 'Tối nay, trong Truyện cổ tích thông minh, hãy đặt tên nhân vật chính theo tên của bé. Kể rằng nhân vật trong truyện không đánh răng rồi sau đó hối hận, để gián tiếp dạy bé những giá trị tốt.', title_zh = '智慧童话里的主角就是宝宝 🪄', body_zh = '今晚在智慧童话里，直接用宝宝的名字给主角命名。讲讲故事里的角色也没刷牙，后来后悔了，用间接的方式传递价值观。' WHERE id = '62a2e4b7-b7ef-4d46-a134-22e1f4da5625' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ingeniero del papel higiénico 🧻', body_es = 'Unos minutos de silencio... ¡Y al entrar en la habitación ves todo el papel higiénico desenrollado por la casa! En lugar de enfadarte, recoged el papel y haced juntos un muñeco de nieve. Vence al caos con creatividad.', title_fr = 'L''ingénieur du papier toilette 🧻', body_fr = 'Quelques minutes de silence... Et en entrant dans la pièce, vous découvrez tout le rouleau de papier toilette déroulé à travers la maison ! Au lieu de vous énerver, ramassez le papier et faites ensemble un bonhomme de neige. Battez le chaos par la créativité.', title_hi = 'टॉयलेट पेपर इंजीनियर 🧻', body_hi = 'कुछ मिनट की खामोशी... और कमरे में जाकर देखती हैं कि पूरा टॉयलेट पेपर खुलकर घर में फैला है! नाराज़ होने के बजाय वह कागज़ इकट्ठा करके साथ में स्नोमैन बनाइए। अफ़रा-तफ़री को रचनात्मकता से जीतिए।', title_id = 'Insinyur tisu toilet 🧻', body_id = 'Beberapa menit hening... Lalu saat masuk kamar, Anda melihat seluruh tisu toilet terurai dan tersebar di rumah! Daripada kesal, kumpulkan tisu itu dan buatlah boneka salju bersama. Kalahkan kekacauan dengan kreativitas.', title_ja = 'トイレットペーパーのエンジニア 🧻', body_ja = '数分間の静けさ…。そして部屋に入ると、トイレットペーパーが全部ほどかれて家じゅうに広がっていた！怒るより、紙を集めて一緒に雪だるまを作りましょう。カオスにはクリエイティブに勝つんです。', title_ko = '휴지 엔지니어 🧻', body_ko = '몇 분간의 고요... 그리고 방에 들어가 보니 휴지가 다 풀려 온 집에 퍼져 있나요? 화내는 대신 휴지를 모아 함께 눈사람을 만들어 보세요. 혼돈은 창의력으로 이겨요.', title_nl = 'Wc-papieringenieur 🧻', body_nl = 'Een paar minuten stilte... En als je de kamer binnenkomt, is de hele rol wc-papier afgerold en door het huis verspreid! Word niet boos, maar verzamel het papier en maak er samen een sneeuwpop van. Versla chaos met creativiteit.', title_pl = 'Inżynier papieru toaletowego 🧻', body_pl = 'Kilka minut ciszy... A gdy wchodzisz do pokoju, widzisz cały papier toaletowy rozwinięty po domu! Zamiast się denerwować, zbierzcie papier i ulepcie razem bałwana. Pokonaj chaos kreatywnością.', title_pt = 'Engenheiro de papel higiénico 🧻', body_pt = 'Uns minutos de silêncio... E ao entrar no quarto vê o rolo de papel higiénico todo desenrolado e espalhado pela casa! Em vez de se irritar, apanhem o papel e façam juntos um boneco de neve. Vença o caos com criatividade.', title_sv = 'Toalettpappersingenjören 🧻', body_sv = 'Några minuters tystnad... Och när du kommer in i rummet ser du att hela toalettpappersrullen är upprullad och utspridd i hemmet! Istället för att bli arg, samla ihop pappret och gör en snögubbe tillsammans. Besegra kaoset med kreativitet.', title_vi = 'Kỹ sư giấy vệ sinh 🧻', body_vi = 'Vài phút im lặng... Và khi bước vào phòng, mẹ thấy cả cuộn giấy vệ sinh đã bị kéo tung khắp nhà! Thay vì bực mình, hãy gom chỗ giấy đó lại và cùng bé làm người tuyết. Hãy chiến thắng sự hỗn loạn bằng sáng tạo.', title_zh = '卫生纸工程师 🧻', body_zh = '几分钟的安静……走进房间才发现，整卷卫生纸都被拉开铺满了家！与其生气，不如把纸收起来，一起堆个雪人。用创意战胜混乱。' WHERE id = 'ce8759a7-ff69-4b27-a788-668b48e71999' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú eres la niña, yo la mamá 👩‍👧', body_es = '¡Ha empezado el juego del cambio de papeles! Te da órdenes: «Ven aquí, cómete la comida». Acepta encantada esta experiencia de liderazgo y haz de su niña sin rechistar.', title_fr = 'Toi, tu es l''enfant, moi la maman 👩‍👧', body_fr = 'Le jeu de l''inversion des rôles a commencé ! Il vous donne des ordres : « Viens ici, mange ton repas ! » Accueillez avec grand plaisir cette expérience de chef et jouez sans broncher le rôle de son enfant.', title_hi = 'तुम बच्चे बनो, मैं माँ 👩‍👧', body_hi = 'भूमिका बदलने का खेल शुरू हो गया! वह आपको ‘इधर आओ, खाना खाओ’ जैसे आदेश दे रहा है। उसके इस नेतृत्व के अभ्यास को बड़े मज़े से स्वीकार कीजिए और चुपचाप उसके बच्चे की भूमिका निभाइए।', title_id = 'Kamu jadi anak, aku jadi Mama 👩‍👧', body_id = 'Permainan tukar peran dimulai! Ia memberi Anda perintah: ''Sini, habiskan makananmu''. Terima pengalaman memimpinnya ini dengan senang hati dan mainkan peran sebagai anaknya tanpa membantah.', title_ja = 'あなたは子ども、わたしはママ 👩‍👧', body_ja = '役割交代ごっこが始まりました！「ここにおいで、ごはん食べて」とあなたに指示を出しています。このリーダー体験を楽しく受け入れて、黙ってこの子の子ども役を演じましょう。', title_ko = '너는 아이, 나는 엄마 👩‍👧', body_ko = '역할 바꾸기 놀이가 시작됐어요! ''이리 와, 밥 먹어''라며 엄마에게 지시하나요? 이 리더십 체험을 즐겁게 받아들이고 조용히 아이 역할을 해 주세요.', title_nl = 'Jij bent het kind, ik ben mama 👩‍👧', body_nl = 'Het rollenspel is begonnen! Hij geeft jou opdrachten: ''Kom hier, eet je bord leeg!'' Geniet volop van zijn leiderschap en speel zonder morren de rol van zijn kind.', title_pl = 'Ty bądź dzieckiem, ja mamą 👩‍👧', body_pl = 'Zaczęła się zabawa w zamianę ról! Wydaje ci polecenia: „Chodź tu, zjedz obiad”. Przyjmij jego doświadczenie w roli lidera z wielką przyjemnością i bez sprzeciwu zagraj jego dziecko.', title_pt = 'Tu és a criança, eu sou a mãe 👩‍👧', body_pt = 'Começou o jogo da troca de papéis! Ele dá-lhe ordens: "anda cá, come a comida". Aceite com muito gosto esta experiência de liderança e faça de criança dele, sem refilar.', title_sv = 'Du är barnet, jag är mamma 👩‍👧', body_sv = 'Rollbyteslek har börjat! Barnet kommenderar dig: ”Kom hit, ät upp maten.” Ta emot barnets ledarerfarenhet med stor förtjusning och spela tyst barnets barn.', title_vi = 'Con làm em bé, mẹ làm mẹ 👩‍👧', body_vi = 'Trò chơi đổi vai đã bắt đầu! Bé ra lệnh cho mẹ: "Lại đây, ăn cơm đi!". Hãy vui vẻ đón nhận trải nghiệm làm "thủ lĩnh" này của bé và ngoan ngoãn đóng vai con của bé.', title_zh = '你当宝宝，我当妈妈 👩‍👧', body_zh = '角色互换游戏开始了！宝宝对你发号施令：“过来，把饭吃了。”开开心心地接受宝宝这次当领导的体验，乖乖地扮演宝宝的“孩子”吧。' WHERE id = '1f94fede-7afb-4d0a-8e39-07ab7d2da0c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, solución real 🤖', body_es = '¿Por qué un niño de 3 años empieza de repente a morderse las uñas? Olvida los artículos de internet que dan miedo y traumatizan. Pregunta a Anacan AI si es solo una reacción pasajera al estrés y obtén una respuesta científica.', title_fr = 'Intelligence artificielle, vraie solution 🤖', body_fr = 'Pourquoi un enfant de 3 ans se met-il soudain à se ronger les ongles ? Oubliez les articles effrayants et traumatisants d''Internet. Demandez à Anacan AI s''il s''agit simplement d''une réaction passagère au stress et obtenez une réponse scientifique.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, सच्चा हल 🤖', body_hi = '3 साल का बच्चा अचानक नाखून क्यों चबाने लगता है? इंटरनेट के डरावने, परेशान करने वाले लेख भूल जाइए। Anacan AI से पूछिए कि क्या यह बस एक अस्थायी तनाव की प्रतिक्रिया है, और वैज्ञानिक जवाब पाइए।', title_id = 'Kecerdasan buatan, solusi nyata 🤖', body_id = 'Mengapa anak usia 3 tahun tiba-tiba mulai menggigit kuku? Lupakan artikel menakutkan dan traumatis di internet. Tanyakan pada Anacan AI apakah ini hanya reaksi stres sementara, dan dapatkan jawaban ilmiah.', title_ja = 'AI、本当の解決策 🤖', body_ja = '3歳の子が急に爪をかみ始めるのはどうして？ネットの怖くてショッキングな記事は忘れましょう。Anacan AIに、一時的なストレス反応かどうかをたずねて、科学的な答えをもらいましょう。', title_ko = '인공지능, 진짜 해결책 🤖', body_ko = '세 살 아이가 왜 갑자기 손톱을 물어뜯을까요? 인터넷의 무섭고 충격적인 글은 잊으세요. Anacan AI에게 그저 일시적인 스트레스 반응인지 물어보고 과학적인 답을 받으세요.', title_nl = 'Kunstmatige intelligentie, echte oplossing 🤖', body_nl = 'Waarom gaat een kind van 3 ineens nagelbijten? Vergeet de enge, traumatiserende artikelen op internet. Vraag Anacan AI of het gewoon een tijdelijke stressreactie is en krijg een wetenschappelijk antwoord.', title_pl = 'Sztuczna inteligencja, prawdziwe rozwiązanie 🤖', body_pl = 'Dlaczego 3-latek nagle zaczyna obgryzać paznokcie? Zapomnij o strasznych, traumatyzujących artykułach z internetu. Zapytaj Anacan AI, czy to tylko przejściowa reakcja na stres, i uzyskaj naukową odpowiedź.', title_pt = 'Inteligência artificial, solução real 🤖', body_pt = 'Porque é que uma criança de 3 anos começa de repente a roer as unhas? Esqueça os artigos assustadores e traumatizantes da internet. Pergunte ao Anacan AI se é apenas uma reação passageira ao stress e obtenha uma resposta científica.', title_sv = 'Artificiell intelligens, verklig lösning 🤖', body_sv = 'Varför börjar ett 3-årigt barn plötsligt bita på naglarna? Glöm skrämmande, traumatiska artiklar på nätet. Fråga Anacan AI om det bara är en övergående stressreaktion och få ett vetenskapligt svar.', title_vi = 'Trí tuệ nhân tạo, giải pháp thật 🤖', body_vi = 'Vì sao một đứa trẻ 3 tuổi bỗng dưng cắn móng tay? Hãy quên đi những bài viết đáng sợ, gây hoang mang trên mạng. Hãy hỏi Anacan AI xem đó có phải chỉ là phản ứng căng thẳng tạm thời không và nhận câu trả lời khoa học.', title_zh = '人工智能，真正的解决办法 🤖', body_zh = '3岁的孩子为什么突然开始咬指甲？忘掉网上那些吓人、让人焦虑的文章。问问Anacan AI，这是否只是一种暂时的压力反应，得到科学的答案。' WHERE id = '77330b1b-94b4-4438-9dd4-9ea117490b54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Ahora deja a un lado los móviles y las tareas de casa. Sentaos frente a frente tú y tu pareja y hablad solo 20 minutos de otro tema que no sean los pagos ni el niño. ¡También sois una pareja!', body_fr = 'L''enfant dort. Maintenant, mettez de côté téléphones et tâches ménagères. Asseyez-vous face à votre partenaire et parlez juste 20 minutes d''autre chose que des factures et de l''enfant. Vous êtes aussi un couple !', body_hi = 'बच्चा सो गया। अब फ़ोन और घर के काम एक तरफ़ रख दीजिए। अपने साथी के आमने-सामने बैठिए और सिर्फ़ 20 मिनट, बिलों और बच्चे के अलावा किसी और विषय पर बात कीजिए। आप एक जोड़ा भी हैं!', body_id = 'Anak sudah tidur. Sekarang singkirkan ponsel dan pekerjaan rumah. Duduklah berhadapan dengan pasangan dan mengobrollah 20 menit saja tentang hal lain selain tagihan dan anak. Kalian juga sepasang kekasih!', body_ja = '子どもが寝ました。スマホも家事もいったん脇に置いて。パートナーと向かい合って、支払いや子どものこと以外の話題で、ただ20分話しましょう。ふたりはカップルでもあるんです！', body_ko = '아이가 잠들었어요. 이제 휴대폰과 집안일은 내려놓으세요. 배우자와 마주 앉아 딱 20분만, 공과금과 아이 이야기 말고 다른 주제로 이야기해 보세요. 두 사람은 부부이기도 하니까요!', body_nl = 'Je kind slaapt. Leg nu je telefoon en het huishouden opzij. Ga tegenover je partner zitten en praat gewoon 20 minuten over iets anders dan rekeningen en het kind. Jullie zijn ook een stel!', body_pl = 'Dziecko śpi. Teraz odłóż telefony i obowiązki domowe. Usiądźcie z partnerem twarzą w twarz i przez 20 minut porozmawiajcie o czymś innym niż rachunki i dziecko. Jesteście też parą!', body_pt = 'A criança adormeceu. Agora ponham de lado os telemóveis e as tarefas da casa. Sentem-se frente a frente com o seu companheiro e falem só 20 minutos sobre outro assunto que não sejam contas nem a criança. Também são um casal!', body_sv = 'Barnet sover. Lägg nu undan telefonerna och hushållssysslorna. Sätt dig mitt emot din partner och prata bara i 20 minuter om något annat än räkningar och barnet. Ni är också ett par!', body_vi = 'Bé đã ngủ. Giờ hãy gác điện thoại và việc nhà sang một bên. Ngồi đối diện chồng và chỉ trò chuyện 20 phút về một chủ đề khác, ngoài hóa đơn và con cái. Hai người còn là một cặp đôi nữa!', body_zh = '宝宝睡着了。现在把手机和家务都放到一边。和伴侣面对面坐下，就20分钟，聊聊账单和孩子以外的话题。你们也是一对恋人！' WHERE id = 'e7437e5e-38bf-45b1-8db0-74786f20b535' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo que sale de los bolsillos 🪨', body_es = '¿Al lavar su pantalón han salido del bolsillo 3 piedras de distintos tamaños y una cáscara de castaña? Para él es la colección más valiosa del mundo. En lugar de tirarlas, guárdalas en una cajita y cread un cofre del tesoro.', title_fr = 'Trésors de poche 🪨', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche 3 cailloux de tailles différentes et une coque de châtaigne ? Pour lui, c''est la plus précieuse collection du monde. Au lieu de les jeter, rangez-les dans une petite boîte pour créer un coffre au trésor.', title_hi = 'जेब से निकली चीज़ें 🪨', body_hi = 'पैंट धोते समय उसकी जेब से 3 अलग आकार के पत्थर और एक चेस्टनट का छिलका निकला? उसके लिए यह दुनिया का सबसे कीमती संग्रह है। इन्हें फेंकने के बजाय एक छोटे डिब्बे में रखकर खज़ाने का संदूक बनाइए।', title_id = 'Temuan dari saku 🪨', body_id = 'Saat mencuci celananya, dari saku keluar 3 batu berbeda ukuran dan kulit kastanye? Baginya, itu koleksi paling berharga di dunia. Daripada membuangnya, kumpulkan dalam kotak kecil dan buatlah peti harta karun.', title_ja = 'ポケットから出てきたもの 🪨', body_ja = 'ズボンを洗おうとしたら、ポケットから大きさのちがう石が3つと、栗のからが出てきた？この子にとっては、世界でいちばん大切なコレクションです。捨てる代わりに小さな箱に集めて、宝箱を作ってあげましょう。', title_ko = '주머니에서 나온 것들 🪨', body_ko = '바지를 빨려는데 주머니에서 크기가 다른 돌 3개와 밤 껍데기가 나왔나요? 아이에게는 세상에서 가장 귀한 수집품이에요. 버리는 대신 작은 상자에 모아 보물 상자를 만들어 주세요.', title_nl = 'Schatten uit de broekzak 🪨', body_nl = 'Kwamen er bij het wassen van zijn broek 3 steentjes van verschillende grootte en een kastanjeschil uit zijn zak? Voor hem is dat de waardevolste verzameling ter wereld. Gooi ze niet weg, maar maak er in een doosje een schatkist van.', title_pl = 'Skarby z kieszeni 🪨', body_pl = 'Podczas prania spodni wyjęłaś z jego kieszeni 3 kamyki różnej wielkości i łupinę kasztana? Dla niego to najcenniejsza kolekcja na świecie. Zamiast je wyrzucać, włóż je do małego pudełka i stwórzcie skrzynię skarbów.', title_pt = 'O que sai dos bolsos 🪨', body_pt = 'Ao lavar as calças, saíram do bolso 3 pedras de tamanhos diferentes e uma casca de castanha? Para ele, esta é a coleção mais valiosa do mundo. Em vez de as deitar fora, junte-as numa caixinha e crie uma arca do tesouro.', title_sv = 'Fynd i fickorna 🪨', body_sv = 'När du tvättade byxorna hittade du 3 stenar i olika storlekar och ett kastanjeskal i fickan? För barnet är det världens mest värdefulla samling. Istället för att slänga dem, samla dem i en liten låda och gör en skattkista.', title_vi = 'Kho báu trong túi quần 🪨', body_vi = 'Khi giặt quần cho bé, mẹ lôi ra từ túi 3 viên sỏi to nhỏ khác nhau và một vỏ hạt dẻ? Với bé, đó là bộ sưu tập quý giá nhất thế giới. Thay vì vứt đi, hãy gom chúng vào một chiếc hộp nhỏ để làm rương kho báu.', title_zh = '口袋里的宝藏 🪨', body_zh = '洗裤子时，从口袋里掏出3块大小不一的石头和一个栗子壳？对宝宝来说，这是世界上最珍贵的收藏。别扔掉，把它们收进一个小盒子，做成一个藏宝箱吧。' WHERE id = '3a4c5cc8-5f54-4aef-b016-9394a079ec83' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro y sin tecnología.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans un environnement sombre et sans écran.', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi.', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は、暗くてデジタル機器のない環境でこそすばやく分泌されます。', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어둡고 기기가 없는 환경에서만 빠르게 분비돼요.', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen snel aangemaakt in een donkere omgeving zonder technologie.', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu bez technologii.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro e sem tecnologia.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk och teknikfri miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素（睡眠激素）只有在昏暗、没有电子产品的环境里才会快速分泌。' WHERE id = '68c1a1ff-c119-4521-aae1-9a7a984caad7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te dan ganas de gritar por todo? ¿El ruido te taladra el cerebro? Esto es puro burnout. Déjale ya en un lugar seguro (o con su padre), vete a otra habitación y escribe todo tu estrés sin filtros en el Diario de ánimo.', body_fr = 'Vous avez envie de crier sur tout ? Le bruit vous transperce le cerveau ? C''est bel et bien un burn-out. Mettez-le tout de suite dans un endroit sûr (ou confiez-le à son papa), allez dans une autre pièce et écrivez tout votre stress sans filtre dans le Journal d''humeur.', body_hi = 'हर बात पर चिल्लाने का मन कर रहा है? शोर दिमाग में चुभ रहा है? यह पूरी तरह बर्नआउट है। तुरंत उसे किसी सुरक्षित जगह पर रखकर (या पापा को सौंपकर) दूसरे कमरे में जाइए और मूड डायरी में सारा तनाव बिना किसी फ़िल्टर के लिख दीजिए।', body_id = 'Ingin berteriak pada segala hal? Kebisingan terasa menembus otak? Ini benar-benar burnout. Segera letakkan ia di tempat yang aman (atau serahkan pada ayahnya), pindah ke ruangan lain, dan tuliskan semua stres tanpa filter di Buku Harian Suasana Hati.', body_ja = '何にでも叫びたくなる？騒音が頭に突きささる？それは完全にバーンアウトです。すぐに子どもを安全な場所に置いて（またはパパにまかせて）別の部屋へ行き、「気分日記」にストレスを全部そのまま書きだしましょう。', body_ko = '모든 것에 소리치고 싶나요? 소음이 머리를 뚫는 것 같나요? 완전히 번아웃이에요. 바로 아이를 안전한 곳에 두고(또는 아빠에게 맡기고) 다른 방으로 가서 기분 일기에 모든 스트레스를 걸러내지 말고 적으세요.', body_nl = 'Wil je tegen alles schreeuwen? Boort het lawaai door je hoofd? Dat is echt een burn-out. Leg hem meteen op een veilige plek (of geef hem aan zijn vader), ga naar een andere kamer en schrijf alle stress ongefilterd in je Stemmingsdagboek.', body_pl = 'Chce ci się krzyczeć na wszystko? Hałas świdruje ci w głowie? To typowe wypalenie. Od razu połóż go w bezpiecznym miejscu (albo oddaj tacie), przejdź do pokoju i wypisz w Dzienniku nastroju cały stres bez filtra.', body_pt = 'Apetece-lhe gritar com tudo? O barulho fura-lhe o cérebro? Isto é mesmo burnout. Ponha-o já num sítio seguro (ou entregue-o ao pai), vá para outra divisão e escreva todo o stress, sem filtros, no Diário de Humor.', body_sv = 'Vill du skrika åt allt? Borrar oljudet sig in i hjärnan? Det här är fullständig utbrändhet. Lägg genast barnet på ett säkert ställe (eller ge det till pappa), gå in i ett annat rum och skriv ner all stress ofiltrerat i Humördagboken.', body_vi = 'Mẹ muốn hét lên với mọi thứ? Tiếng ồn như khoan vào đầu? Đây chính là kiệt sức (burnout). Hãy đặt bé vào chỗ an toàn ngay (hoặc giao cho bố), sang phòng khác và viết hết mọi căng thẳng vào Nhật ký tâm trạng, không cần chọn lọc.', body_zh = '看什么都想吼？噪音快把脑袋钻穿了？这完全是倦怠了。马上把宝宝放在安全的地方（或者交给爸爸），走进另一个房间，把所有压力毫无保留地写进心情日记。' WHERE id = '9021ef15-5cf5-4f9d-8592-aab7e32c65a0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertar con música 🎶', body_es = 'El sol todavía no ha salido del todo, pero él ya salta en la cama haciendo sonidos rítmicos. ¡El despertador más ruidoso, pero más adorable, del mundo! Empieza el día sonriendo ante esta energía desbordante.', title_fr = 'Réveil en musique 🎶', body_fr = 'Le soleil n''est pas encore tout à fait levé, mais il saute déjà sur le lit en faisant des bruits rythmés. Le réveil le plus bruyant, mais le plus adorable du monde ! Commencez la journée en souriant à son énergie débordante.', title_hi = 'संगीत के साथ जागना 🎶', body_hi = 'सूरज अभी पूरा निकला भी नहीं, पर वह पलंग पर उछलते हुए ताल वाली आवाज़ें निकाल रहा है। दुनिया की सबसे शोर भरी, पर सबसे प्यारी अलार्म घड़ी! उसकी इस बेहिसाब ऊर्जा पर मुस्कुराते हुए दिन शुरू कीजिए।', title_id = 'Bangun dengan musik 🎶', body_id = 'Matahari belum terbit sepenuhnya, tapi ia sudah melompat di kasur sambil membuat bunyi berirama. Alarm paling berisik sekaligus paling disayang di dunia! Mulailah hari dengan tersenyum melihat energinya yang tak terbatas.', title_ja = '音楽で目覚め 🎶', body_ja = 'まだ太陽が昇りきっていないのに、ベッドでジャンプしながらリズミカルな音を出しています。世界でいちばんにぎやかで、いちばん愛しい目覚ましです！このあふれるエネルギーに笑顔で一日を始めましょう。', title_ko = '음악과 함께 기상 🎶', body_ko = '해가 다 뜨지도 않았는데 침대에서 뛰며 리듬 있는 소리를 내나요? 세상에서 가장 시끄럽지만 가장 사랑스러운 알람이에요! 이 넘치는 에너지에 미소 지으며 하루를 시작하세요.', title_nl = 'Wakker worden met muziek 🎶', body_nl = 'De zon is nog niet helemaal op, maar hij springt al op bed en maakt ritmische geluiden. De luidste, maar liefste wekker ter wereld! Begin de dag met een glimlach om zijn grenzeloze energie.', title_pl = 'Pobudka z muzyką 🎶', body_pl = 'Słońce jeszcze w pełni nie wzeszło, a on skacze po łóżku i wydaje rytmiczne dźwięki. Najgłośniejszy, ale najukochańszy budzik na świecie! Zacznij dzień z uśmiechem na widok jego bezgranicznej energii.', title_pt = 'Despertar com música 🎶', body_pt = 'O sol ainda não nasceu de todo, mas ele já salta na cama e faz sons ritmados. O despertador mais barulhento, mas mais querido do mundo! Comece o dia a sorrir para esta energia sem limites.', title_sv = 'Uppvaknande med musik 🎶', body_sv = 'Solen har inte riktigt gått upp än, men barnet hoppar i sängen och gör rytmiska ljud. Världens mest högljudda men mest älskade väckarklocka! Börja dagen med ett leende åt den gränslösa energin.', title_vi = 'Thức dậy cùng âm nhạc 🎶', body_vi = 'Mặt trời còn chưa lên hẳn, nhưng bé đã nhảy trên giường và tạo ra những âm thanh nhịp nhàng. Chiếc chuông báo thức ồn ào nhất nhưng đáng yêu nhất thế giới! Hãy bắt đầu ngày mới bằng nụ cười trước nguồn năng lượng vô tận của bé.', title_zh = '伴着音乐醒来 🎶', body_zh = '太阳还没完全升起，宝宝已经在床上蹦着跳着发出有节奏的声音。这是世界上最吵、却也最可爱的起床铃！笑着迎接宝宝这股无穷的能量，开始新的一天吧。' WHERE id = 'a5815a11-4b6f-4f3d-a6ff-4d587c286a65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Registro de sentimientos 📝', body_es = 'Cuando el peque se duerma, abre el Diario de ánimo. Anota para el futuro el momento más gracioso y absurdo de hoy, el que más te hizo reír. Cuando lo leas dentro de unos años, se te llenarán los ojos de lágrimas.', title_fr = 'Noter ses sentiments 📝', body_fr = 'Une fois l''enfant couché, ouvrez le Journal d''humeur. Notez pour plus tard son moment le plus drôle et le plus absurde de la journée, celui qui vous a fait le plus rire. Dans quelques années, en le relisant, vous aurez les larmes aux yeux.', title_hi = 'भावनाओं का रिकॉर्ड 📝', body_hi = 'बच्चे के सोने के बाद मूड डायरी खोलिए। आज उसने जो सबसे मज़ेदार, आपको सबसे ज़्यादा हँसाने वाला बेतुका काम किया, उसे भविष्य के लिए लिख लीजिए। सालों बाद पढ़ेंगी तो आँखें भर आएँगी।', title_id = 'Mencatat perasaan 📝', body_id = 'Setelah anak tidur, buka Buku Harian Suasana Hati. Catat momen absurd paling lucu yang ia buat hari ini, yang paling membuat Anda tertawa, untuk masa depan. Bertahun-tahun kemudian, membacanya akan membuat mata Anda berkaca-kaca.', title_ja = '気持ちの記録 📝', body_ja = '子どもが寝たら「気分日記」を開きましょう。今日この子がした、いちばんおもしろくて、あなたをいちばん笑わせたおかしな瞬間を、未来のために記録して。何年もたって読み返したとき、きっと涙があふれます。', title_ko = '마음 기록 📝', body_ko = '아이가 잠들면 기분 일기를 열어 보세요. 오늘 아이가 한 가장 웃기고 엉뚱한 순간을 기록해 두세요. 몇 년 뒤 읽으면 눈시울이 붉어질 거예요.', title_nl = 'Je gevoelens noteren 📝', body_nl = 'Open je Stemmingsdagboek als hij slaapt. Schrijf het grappigste, meest absurde moment van vandaag op voor later. Als je het over jaren terugleest, krijg je tranen in je ogen.', title_pl = 'Zapisz swoje uczucia 📝', body_pl = 'Gdy dziecko zaśnie, otwórz Dziennik nastroju. Zapisz na przyszłość najzabawniejszą, absurdalną chwilę, którą dziś zafundował i która najbardziej cię rozśmieszyła. Gdy przeczytasz to za lata, łzy napłyną ci do oczu.', title_pt = 'Registo dos sentimentos 📝', body_pt = 'Depois de a criança adormecer, abra o Diário de Humor. Registe para o futuro o momento absurdo mais engraçado de hoje, o que mais a fez rir. Daqui a uns anos, ao lê-lo, vai ficar com os olhos cheios de lágrimas.', title_sv = 'Anteckna känslorna 📝', body_sv = 'Öppna Humördagboken när barnet har somnat. Anteckna dagens roligaste, mest absurda stund som fick dig att skratta mest, för framtiden. När du läser det om flera år kommer du att få tårar i ögonen.', title_vi = 'Ghi lại cảm xúc 📝', body_vi = 'Sau khi bé ngủ, hãy mở Nhật ký tâm trạng. Ghi lại khoảnh khắc ngộ nghĩnh, buồn cười nhất mà bé đã làm hôm nay để dành cho tương lai. Nhiều năm sau đọc lại, mắt mẹ sẽ rưng rưng.', title_zh = '感受记录 📝', body_zh = '宝宝睡着后，打开心情日记。把宝宝今天最好笑、最让你笑出声的那个荒诞时刻记下来留给将来。多年后再读时，你会忍不住热泪盈眶。' WHERE id = 'afb9fd4f-60e2-4547-87e2-d867963a1345' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Probando la hora de calma 🥱', body_es = '¿No quiere echarse la siesta, pero se le cierran los ojos de sueño? La resistencia de los 3 años es un clásico. No le obligues: baja las luces de la habitación y crea una nueva rutina anunciando la «hora de hojear libros en silencio».', title_fr = 'Essayer l''heure calme 🥱', body_fr = 'Il ne veut pas faire la sieste, mais ses yeux se ferment tout seuls ? La résistance des 3 ans est un classique. Ne le forcez pas : baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine.', title_hi = 'शांत समय का प्रयोग 🥱', body_hi = 'दोपहर की नींद नहीं लेना चाहता, पर आँखों से नींद टपक रही है? 3 साल की ज़िद क्लासिक है। ज़बरदस्ती मत कीजिए, कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और नया रूटीन बनाइए।', title_id = 'Latihan waktu tenang 🥱', body_id = 'Ia tidak mau tidur siang, padahal matanya sudah sangat mengantuk? Penolakan di usia 3 tahun itu klasik. Jangan memaksa, redupkan lampu kamar dan ciptakan rutinitas baru dengan mengumumkan ''Waktu membaca buku dengan tenang''.', title_ja = '静かな時間の練習 🥱', body_ja = 'お昼寝したくないのに、目は眠そう？3歳の抵抗は定番です。無理強いせず、部屋の明かりを落として「静かな絵本の時間」を宣言し、新しいルーティンをつくりましょう。', title_ko = '조용한 시간 연습 🥱', body_ko = '낮잠은 싫다는데 눈에는 졸음이 가득하나요? 세 살의 저항은 아주 흔해요. 억지로 재우지 말고 방 불을 낮춘 뒤 ''조용히 책 넘기는 시간''을 선언해 새로운 루틴을 만들어 보세요.', title_nl = 'Oefenen met een rustuurtje 🥱', body_nl = 'Wil hij geen middagslaapje doen, terwijl hij bijna in slaap valt? Verzet rond 3 jaar is klassiek. Dwing hem niet, dim de lichten in de kamer en maak een nieuwe routine door een ''stil boekjesuurtje'' aan te kondigen.', title_pl = 'Ćwiczymy cichą godzinę 🥱', body_pl = 'Nie chce iść na drzemkę, choć oczy same mu się kleją? Opór 3-latka to klasyka. Nie zmuszaj, przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę.', title_pt = 'Experimentar a hora do sossego 🥱', body_pt = 'Não quer fazer a sesta, mas está a cair de sono? A resistência dos 3 anos é um clássico. Não o obrigue: baixe as luzes do quarto e crie uma nova rotina anunciando a "hora de folhear livros em silêncio".', title_sv = 'Testa en lugn stund 🥱', body_sv = 'Vill barnet inte sova middag, fast ögonen håller på att falla ihop? Motståndet vid 3 år är klassiskt. Tvinga inte, dämpa ljuset i rummet och skapa en ny rutin genom att utlysa en ”tyst bläddra-i-böcker-stund”.', title_vi = 'Tập làm quen giờ yên lặng 🥱', body_vi = 'Bé không muốn ngủ trưa, dù mắt đã díp lại? Sự phản kháng của tuổi lên 3 là điều kinh điển. Đừng ép, hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới.', title_zh = '试试安静时光 🥱', body_zh = '不肯午睡，可眼睛都快睁不开了？3岁的反抗很典型。别强迫，把房间灯光调暗，宣布“安静翻书时间”，建立一个新的日常流程。' WHERE id = 'db2d884d-1367-4ebc-a61b-9a450673d64d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando lo que haces ya no funciona, los ruidos raros y las caras graciosas de papá salvan la situación al instante. En las crisis de la tarde, pásale la pelota enseguida y mira descansando desde fuera.', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres et les grimaces de papa sauvent aussitôt la situation. Pendant les crises du soir, passez-lui vite le relais et regardez de loin en vous reposant.', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तब पापा की अजीब आवाज़ें और मज़ेदार चेहरे हालात तुरंत सँभाल लेते हैं। शाम के बिगड़े मूड में ज़िम्मेदारी तुरंत उन्हें सौंप दीजिए और आराम करते हुए दूर से देखिए।', body_id = 'Saat cara Anda tak lagi berhasil, bunyi aneh dan wajah lucu Ayah langsung menyelamatkan keadaan. Saat krisis sore hari, segera oper bolanya ke Ayah dan saksikan dari samping sambil beristirahat.', body_ja = 'あなたの手が通用しなくなったら、パパのおもしろい声やおどけた顔がすぐに状況を救ってくれます。夕方のぐずりタイムは、すぐにバトンをパパに渡して、そばで休みながら見守りましょう。', body_ko = '엄마의 방법이 더는 통하지 않을 때, 아빠의 이상한 소리와 웃긴 표정이 바로 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기고 옆에서 쉬며 지켜보세요.', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke geluiden en grappige gezichten meteen de situatie. Speel bij avondbuien de bal direct naar hem door en kijk ontspannen toe.', body_pl = 'Gdy twoje sposoby już nie działają, śmieszne odgłosy i miny taty od razu ratują sytuację. Podczas wieczornych kryzysów od razu przekaż mu pałeczkę i odpoczywaj, obserwując z boku.', body_pt = 'Quando os seus truques já não funcionam, os sons estranhos e as caretas cómicas do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola de imediato e observe à distância, a descansar.', body_sv = 'När ditt eget inte längre fungerar räddar pappas konstiga ljud och roliga miner situationen direkt. Vid kvällskriserna, skicka genast bollen till honom och vila medan du tittar på.', body_vi = 'Khi mọi chiêu của mẹ không còn hiệu quả, những âm thanh kỳ quặc và gương mặt hài hước của bố sẽ cứu nguy ngay lập tức. Trong những cơn khủng hoảng buổi tối, hãy "chuyền bóng" ngay cho bố và nghỉ ngơi quan sát từ xa.', body_zh = '当你的办法都不管用时，爸爸发出的怪声音、做的鬼脸马上就能化解局面。傍晚闹脾气时，赶紧把“球”传给爸爸，你在一旁休息着看就好。' WHERE id = '0f647bd8-9749-4a55-969b-bfc85ddb7152' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escucha a tu cuerpo 🩸', body_es = '¿Cansancio sin motivo y ganas de llorar? Abre el Calendario menstrual. Tu cuerpo te está mandando señales. Cuídate con un tentempié rico en magnesio de Recetas saludables.', title_fr = 'Écoutez votre corps 🩸', body_fr = 'Fatigue inexpliquée et envie de pleurer ? Ouvrez le Suivi des règles. Votre corps vous envoie des signaux. Soyez douce avec vous-même avec une collation riche en magnésium des Recettes saines.', title_hi = 'शरीर की सुनिए 🩸', body_hi = 'बिना वजह थकान और रोने का मन? पीरियड ट्रैकर खोलिए। आपका शरीर संकेत दे रहा है। सेहतमंद रेसिपी से मैग्नीशियम वाले स्नैक के साथ खुद पर दया कीजिए।', title_id = 'Dengarkan tubuh Anda 🩸', body_id = 'Lelah tanpa sebab dan ingin menangis? Buka Pelacak Menstruasi. Tubuh Anda sedang memberi sinyal. Sayangi diri Anda dengan camilan kaya magnesium dari Resep Sehat.', title_ja = '体の声を聞いて 🩸', body_ja = '理由のない疲れや、泣きたい気持ち？「生理トラッカー」を開いてみて。体がサインを出しています。「ヘルシーレシピ」からマグネシウムたっぷりのおやつを選んで、自分にやさしくしましょう。', title_ko = '몸의 소리를 들어요 🩸', body_ko = '이유 없이 피곤하고 울고 싶나요? 생리 주기 기록을 열어 보세요. 몸이 신호를 보내고 있어요. 건강한 레시피의 마그네슘 간식으로 나를 다정하게 돌봐 주세요.', title_nl = 'Luister naar je lichaam 🩸', body_nl = 'Ongewoon moe en zin om te huilen? Open je Cyclustracker. Je lichaam geeft signalen. Wees lief voor jezelf met een magnesiumrijk tussendoortje uit Gezonde recepten.', title_pl = 'Słuchaj swojego ciała 🩸', body_pl = 'Zmęczenie bez powodu i chce ci się płakać? Otwórz Kalendarz miesiączkowy. Twoje ciało wysyła sygnały. Okaż sobie czułość przekąską z magnezem ze Zdrowych przepisów.', title_pt = 'Ouça o seu corpo 🩸', body_pt = 'Cansaço sem razão e vontade de chorar? Abra o Registo do Período. O seu corpo está a dar sinais. Seja gentil consigo com um snack rico em magnésio das Receitas Saudáveis.', title_sv = 'Lyssna på kroppen 🩸', body_sv = 'Omotiverad trötthet och lust att gråta? Öppna Mensspåraren. Kroppen skickar signaler. Visa dig själv omtanke med ett magnesiumrikt mellanmål från Hälsosamma recept.', title_vi = 'Lắng nghe cơ thể 🩸', body_vi = 'Mệt mỏi và muốn khóc mà không rõ lý do? Hãy mở Theo dõi kỳ kinh. Cơ thể mẹ đang gửi tín hiệu. Hãy dịu dàng với bản thân bằng một món ăn nhẹ giàu magie từ Công thức lành mạnh.', title_zh = '倾听身体 🩸', body_zh = '莫名疲惫，还想哭？打开经期记录。你的身体在发出信号。从健康食谱里做一份富含镁的小零食，好好心疼一下自己。' WHERE id = 'c30ee50d-9665-4368-af0d-6578c2cc302b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Solo come 2 o 3 platos que le gustan? No te preocupes. Revisa el equilibrio semanal con el Seguimiento de tomas y evita presionarle en la mesa.', body_fr = 'Il ne mange que 2 ou 3 plats qu''il aime ? Ne vous inquiétez pas. Vérifiez l''équilibre de la semaine avec le Suivi des repas et évitez de mettre la pression à table.', body_hi = 'सिर्फ़ अपने पसंदीदा 2-3 खाने ही खाता है? चिंता मत कीजिए। फ़ीडिंग ट्रैकर से हफ़्ते का संतुलन जाँचिए और खाने की मेज़ पर दबाव बनाने से बचिए।', body_id = 'Ia hanya mau makan 2-3 makanan favoritnya? Jangan khawatir. Periksa keseimbangan mingguan dengan Pemantau Nutrisi dan hindari menciptakan tekanan di meja makan.', body_ja = '好きな2〜3品しか食べない？心配しないで。「栄養管理ツール」で1週間のバランスを確認して、食卓でプレッシャーをかけないようにしましょう。', body_ko = '좋아하는 음식 2~3가지만 먹나요? 걱정하지 마세요. 수유 기록 도구로 한 주의 균형을 확인하고, 식탁에서 압박하지 마세요.', body_nl = 'Eet hij alleen 2-3 gerechten die hij lekker vindt? Maak je geen zorgen. Controleer de weekbalans met de Voedingstracker en zorg dat er aan tafel geen druk ontstaat.', body_pl = 'Je tylko 2-3 ulubione potrawy? Nie martw się. Sprawdź tygodniowy bilans w narzędziu do śledzenia karmienia i nie wywieraj presji przy stole.', body_pt = 'Só come 2 ou 3 pratos de que gosta? Não se preocupe. Verifique o equilíbrio semanal com o Registo de Alimentação e evite fazer pressão à mesa.', body_sv = 'Äter barnet bara 2-3 favoriträtter? Oroa dig inte. Kontrollera veckans balans med verktyget Matningskoll och undvik att skapa press vid matbordet.', body_vi = 'Bé chỉ ăn 2-3 món mình thích? Đừng lo lắng. Hãy kiểm tra sự cân bằng hằng tuần bằng Theo dõi cữ bú và tránh tạo áp lực trong bữa ăn.', body_zh = '只吃自己喜欢的2-3样东西？别担心。用喂养记录工具查看一周的饮食平衡，避免在餐桌上给宝宝施加压力。' WHERE id = 'c49b057e-0774-42da-aec0-ee5fcc238471' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Él inventará el final del cuento 🪄', body_es = 'Los dos estáis hartos de los libros de siempre. Abre Cuentos inteligentes y esta noche deja que él dirija la historia. Pregúntale: «¿Y ahora adónde va ese coche?», y deja que se duerma con el final absurdo que invente.', title_fr = 'C''est lui qui trouvera la fin du conte 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques ? Ouvrez les Contes intelligents et, ce soir, laissez-le diriger l''histoire. Demandez : « Où va aller la voiture maintenant ? » et laissez-le s''endormir sur la fin absurde qu''il aura inventée.', title_hi = 'कहानी का अंत वही ढूँढेगा 🪄', body_hi = 'आप दोनों पुरानी किताबों से ऊब चुके हैं। स्मार्ट कहानियाँ खोलिए और आज शाम कहानी की दिशा उसे तय करने दीजिए। पूछिए, ‘अब वह गाड़ी कहाँ जाए?’ और उसे अपने गढ़े बेतुके अंत के साथ सोने दीजिए।', title_id = 'Ia yang akan menemukan akhir dongengnya 🪄', body_id = 'Kalian berdua sudah bosan dengan buku klasik. Buka Dongeng Pintar dan malam ini biarkan ia yang mengarahkan alur cerita. Tanyakan ''Sekarang mobilnya pergi ke mana?'', dan biarkan ia tertidur dengan akhir cerita absurd karangannya sendiri.', title_ja = 'お話の結末はこの子が決める 🪄', body_ja = '定番の絵本にはふたりとも飽きてしまった？「スマートおはなし」を開いて、今夜はストーリーの行き先をこの子にまかせましょう。「この車、次はどこへ行く？」とたずねて、考えたおかしな結末とともに眠りにつかせてあげて。', title_ko = '동화의 결말은 아이가 찾아요 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 스마트 동화를 열고 오늘 저녁엔 이야기의 방향을 아이에게 맡겨 보세요. ''이제 자동차는 어디로 갈까?'' 묻고, 아이가 지어낸 엉뚱한 결말과 함께 잠들게 해 주세요.', title_nl = 'Hij bedenkt zelf het einde van het sprookje 🪄', body_nl = 'Zijn jullie allebei de klassieke boeken beu? Open Slimme sprookjes en laat hem vanavond het verhaal sturen. Vraag: ''Waar moet die auto nu naartoe?'' en laat hem in slaap vallen met het absurde einde dat hij bedenkt.', title_pl = 'Zakończenie bajki wymyśli on 🪄', body_pl = 'Klasyczne książeczki znudziły się wam obojgu. Otwórz Mądre bajki i pozwól mu dziś wieczorem kierować fabułą. Zapytaj: „Dokąd teraz ma jechać to auto?” i niech zaśnie przy absurdalnym zakończeniu, które sam wymyśli.', title_pt = 'Ele vai inventar o final da história 🪄', body_pt = 'Estão os dois fartos dos livros clássicos. Abra as Histórias Inteligentes e deixe que esta noite seja ele a guiar o enredo. Pergunte "E agora, para onde vai o carro?" e deixe-o adormecer com o final absurdo que inventar.', title_sv = 'Barnet hittar sagans slut 🪄', body_sv = 'Ni är båda trötta på de klassiska böckerna. Öppna Smarta sagor och låt barnet styra handlingen i kväll. Fråga ”Vart ska bilen åka nu?” och låt barnet somna till sitt eget påhittade, absurda slut.', title_vi = 'Bé sẽ tự nghĩ ra cái kết 🪄', body_vi = 'Cả hai mẹ con đều đã chán những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh và tối nay để bé dẫn dắt cốt truyện. Hỏi bé: "Giờ chiếc xe nên đi đâu nhỉ?", rồi để bé chìm vào giấc ngủ với cái kết ngộ nghĩnh do chính mình nghĩ ra.', title_zh = '故事的结局由宝宝来想 🪄', body_zh = '经典故事书你们俩都看腻了。打开智慧童话，今晚让宝宝来决定故事走向。问问：“现在这辆车该开去哪儿？”就让宝宝带着自己编的荒诞结局入睡吧。' WHERE id = '462a51f8-d8f0-4c41-8551-81fbd18e8c62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Los niños de las redes ya recitan poesías y el tuyo todavía cambia las palabras? ¡Deja de comparar ahora mismo! Cada niño tiene su propio reloj de desarrollo, único y diferente. A su ritmo, es perfecto.', body_fr = 'Sur les réseaux sociaux, des enfants récitent déjà des poèmes, et le vôtre mélange encore les mots ? Arrêtez tout de suite la comparaison ! Chaque enfant a son propre rythme de développement. Il est parfait à son rythme.', body_hi = 'सोशल मीडिया पर बच्चे कविताएँ सुना रहे हैं, पर आपका बच्चा अभी शब्द उलट-पलट करता है? तुलना अभी बंद कीजिए! हर बच्चे के विकास की घड़ी अनोखी और अलग होती है। वह अपनी रफ़्तार में बिल्कुल सही है।', body_id = 'Anak-anak di media sosial sudah bisa membaca puisi, sementara anak Anda masih tertukar-tukar kata? Hentikan perbandingan sekarang juga! Jam perkembangan setiap anak unik dan berbeda. Ia sempurna dengan temponya sendiri.', body_ja = 'SNSの子どもたちはもう詩を暗唱しているのに、うちの子はまだ言葉を入れかえている？比べるのは今すぐやめましょう！成長のペースは子どもそれぞれちがいます。この子は自分のペースで完璧なんです。', body_ko = 'SNS 속 아이들은 벌써 시를 외우는데 우리 아이는 아직 단어를 바꿔 말하나요? 비교는 당장 멈추세요! 아이마다 발달 시계는 고유하고 달라요. 자기 속도로 완벽해요.', body_nl = 'Kinderen op social media zeggen al gedichtjes op, maar jouw kind haalt woorden nog door elkaar? Stop meteen met vergelijken! Elk kind heeft zijn eigen, unieke ontwikkelingsklok. Hij is perfect in zijn eigen tempo.', body_pl = 'Dzieci w mediach społecznościowych już recytują wierszyki, a twoje wciąż przekręca słowa? Natychmiast przestań porównywać! Zegar rozwoju każdego dziecka jest wyjątkowy i inny. Jest idealne w swoim tempie.', body_pt = 'As crianças das redes sociais já recitam poemas, mas o seu ainda troca as palavras? Pare já com as comparações! O relógio de desenvolvimento de cada criança é único e diferente. Ele é perfeito ao seu próprio ritmo.', body_sv = 'Barnen på sociala medier läser redan dikter, men ditt barn blandar fortfarande ihop orden? Sluta jämföra direkt! Varje barns utvecklingsklocka är unik och olika. Barnet är perfekt i sin egen takt.', body_vi = 'Trẻ con trên mạng xã hội đã đọc thơ, còn bé nhà mình vẫn nói lẫn lộn từ? Hãy dừng so sánh ngay! Mỗi trẻ có "đồng hồ phát triển" riêng, độc nhất. Bé hoàn hảo theo nhịp độ của riêng mình.', body_zh = '社交网络上别人家的孩子已经会背诗了，你家宝宝却还在把词说颠倒？马上停止比较！每个孩子的发育时间表都是独特而不同的。宝宝按自己的节奏前进，就是完美的。' WHERE id = 'a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las olimpiadas de ponerse los zapatos 👟', body_es = '¿Se ha puesto el zapato derecho en el pie izquierdo y no quiere quitárselo de ninguna manera? Déjalo así. La sensación de libertad y el orgullo de «lo he hecho yo» importan más que vestirse bien. Además, es la base para resolver problemas en el futuro.', title_fr = 'Les olympiades des chaussures 👟', body_fr = 'Il a mis la chaussure droite au pied gauche et refuse catégoriquement de l''enlever ? Laissez-la comme ça. Le sentiment de liberté et la fierté du « je l''ai fait » comptent plus que de bien s''habiller. C''est aussi la base de sa future capacité à résoudre les problèmes.', title_hi = 'जूते पहनने का ओलंपिक 👟', body_hi = 'दायाँ जूता बाएँ पैर में पहन लिया और उतारना बिल्कुल नहीं चाहता? वैसे ही रहने दीजिए। आज़ादी का एहसास और ‘मैंने किया’ का गर्व सही पहनने से ज़्यादा ज़रूरी है। यही आगे चलकर समस्याएँ सुलझाने की नींव भी है।', title_id = 'Olimpiade memakai sepatu 👟', body_id = 'Ia memakai sepatu kanan di kaki kiri dan sama sekali tidak mau melepasnya? Biarkan saja. Rasa bebas dan bangga ''aku bisa sendiri'' lebih penting daripada memakai dengan benar. Ini juga dasar kemampuan memecahkan masalah di masa depan.', title_ja = '靴はきオリンピック 👟', body_ja = '右の靴を左足にはいて、どうしても脱ぎたがらない？そのままにしておきましょう。自由な気持ちと「自分でできた」という誇りは、正しくはくことよりずっと大切です。これは将来、問題を解決する力の土台にもなります。', title_ko = '신발 신기 올림픽 👟', body_ko = '오른쪽 신발을 왼발에 신고 절대 벗지 않겠다고 하나요? 그냥 두세요. 자유롭다는 느낌과 ''내가 했어''라는 뿌듯함이 바르게 신는 것보다 중요해요. 이것이 앞으로의 문제 해결력의 바탕이에요.', title_nl = 'Olympische spelen schoenen aantrekken 👟', body_nl = 'Heeft hij de rechterschoen aan zijn linkervoet en wil hij hem absoluut niet uitdoen? Laat maar zo. Het gevoel van vrijheid en de trots van ''ik heb het zelf gedaan'' zijn belangrijker dan de schoenen goed aan hebben. Dit is ook de basis voor het oplossen van problemen later.', title_pl = 'Olimpiada wkładania butów 👟', body_pl = 'Włożył prawy but na lewą nogę i za nic nie chce go zdjąć? Niech tak zostanie. Poczucie wolności i duma „sam to zrobiłem” są ważniejsze niż poprawne ubranie się. To także fundament przyszłego rozwiązywania problemów.', title_pt = 'As olimpíadas de calçar os sapatos 👟', body_pt = 'Calçou o sapato direito no pé esquerdo e não o quer tirar de maneira nenhuma? Deixe ficar assim. A sensação de liberdade e o orgulho de "fui eu que fiz" são mais importantes do que calçar bem. É também a base para resolver problemas no futuro.', title_sv = 'Skoolympiaden 👟', body_sv = 'Har barnet tagit högerskon på vänster fot och vill absolut inte ta av den? Låt den sitta. Känslan av frihet och stoltheten över ”jag gjorde det” är viktigare än att klä sig rätt. Det är också grunden för att lösa problem i framtiden.', title_vi = 'Thế vận hội đi giày 👟', body_vi = 'Bé đi giày phải vào chân trái và nhất quyết không chịu cởi ra? Cứ để vậy. Cảm giác tự do và niềm tự hào "con tự làm được" quan trọng hơn việc đi đúng. Đây cũng là nền tảng cho khả năng giải quyết vấn đề sau này.', title_zh = '穿鞋奥运会 👟', body_zh = '把右脚的鞋穿在左脚上，还死活不肯脱？那就这样吧。自由的感觉和“我自己做到了”的骄傲，比穿对鞋更重要。这也是将来解决问题能力的基础。' WHERE id = 'fca7853a-0c3e-4553-8c15-c32fa7564774' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia de la basura invisible 🗑️', body_es = '¡Busca llorando ese papelito inútil que él mismo tiró y que tú echaste a la basura! Así es exactamente la lógica de los 3 años. Como no puedes recuperarlo, distrae su atención al instante con algo más llamativo.', title_fr = 'Le drame du déchet invisible 🗑️', body_fr = 'Il cherche en pleurant ce bout de papier inutile qu''il a lui-même jeté et que vous avez mis à la poubelle ! C''est exactement ça, la logique des 3 ans. Comme vous ne pouvez pas le récupérer, détournez aussitôt son attention vers quelque chose de plus brillant.', title_hi = 'गायब कचरे की त्रासदी 🗑️', body_hi = 'जिस बेकार कागज़ के टुकड़े को उसने खुद फेंका और आपने कूड़ेदान में डाल दिया, अब उसे ढूँढकर रो रहा है! 3 साल का तर्क बिल्कुल यही है। उसे वापस तो ला नहीं सकतीं, इसलिए तुरंत किसी चमकीली चीज़ से उसका ध्यान बँटाइए।', title_id = 'Tragedi sampah tak kasatmata 🗑️', body_id = 'Ia mencari sambil menangis potongan kertas tak berguna yang ia buang sendiri, lalu Anda masukkan ke tempat sampah! Inilah logika anak 3 tahun. Karena tak bisa dikembalikan, segera alihkan perhatiannya ke sesuatu yang lebih menarik.', title_ja = '見えないゴミの悲劇 🗑️', body_ja = '自分で捨てて、あなたもゴミ箱に入れたあのいらない紙切れをさがして泣いている！これこそ3歳の理屈です。取りもどせないので、すぐにもっとキラキラしたものに気をそらしてあげましょう。', title_ko = '보이지 않는 쓰레기 비극 🗑️', body_ko = '자기가 버리고 엄마가 쓰레기통에 넣은 쓸모없는 종이 조각을 찾으며 우나요! 이게 바로 세 살의 논리예요. 되찾을 수 없으니 더 반짝이는 무언가로 바로 관심을 돌려 주세요.', title_nl = 'Het drama van het onzichtbare afval 🗑️', body_nl = 'Hij zoekt huilend naar dat nutteloze papiertje dat hij zelf weggooide en dat jij in de prullenbak deed! Dat is precies de logica van een 3-jarige. Je kunt het niet terughalen, dus leid hem meteen af met iets glimmenders.', title_pl = 'Tragedia niewidzialnego śmiecia 🗑️', body_pl = 'Płacze i szuka niepotrzebnego skrawka papieru, który sam wyrzucił, a ty wyniosłaś do śmieci! To właśnie logika 3-latka w pełnej krasie. Skoro nie możesz go odzyskać, od razu odwróć jego uwagę czymś jeszcze bardziej błyszczącym.', title_pt = 'A tragédia do lixo invisível 🗑️', body_pt = 'Procura a chorar aquele papel inútil que ele próprio deitou fora e que a mãe também pôs no lixo! É exatamente esta a lógica dos 3 anos. Como não o pode devolver, desvie logo a atenção dele para algo mais vistoso.', title_sv = 'Den osynliga soptragedin 🗑️', body_sv = 'Barnet letar efter den onödiga pappersbiten som det själv kastade och som du slängde i soporna, och gråter! Det här är precis 3-årslogik. Eftersom du inte kan ta tillbaka den, led genast över uppmärksamheten till något mer spännande.', title_vi = 'Bi kịch rác vô hình 🗑️', body_vi = 'Bé khóc lóc đi tìm mẩu giấy vô dụng mà chính bé đã vứt đi và mẹ cũng đã bỏ vào thùng rác! Logic của tuổi lên 3 chính là như vậy. Vì không thể lấy lại được, hãy lập tức đánh lạc hướng bé bằng một thứ gì đó hấp dẫn hơn.', title_zh = '看不见的垃圾悲剧 🗑️', body_zh = '宝宝自己扔掉、你也丢进垃圾桶的那张没用的小纸片，现在宝宝却在找，还哭了起来！这就是典型的3岁逻辑。既然拿不回来，就马上用更亮眼的东西转移宝宝的注意力。' WHERE id = '344d14b0-cfc9-4ff3-af6f-44e0148ab198' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Está haciendo un puzle él solo y lleva 10 minutos en silencio. Y tú quieres aprovechar ese momento para ordenar la casa. ¡No! Túmbate en el sofá. Tu batería también tiene que cargarse para aguantar este ritmo hasta la noche.', body_fr = 'Il fait un puzzle tout seul et ne fait pas un bruit depuis 10 minutes. Et vous voulez en profiter pour ranger la maison. Non ! Allongez-vous sur le canapé. Votre batterie aussi doit se recharger pour tenir ce rythme jusqu''au soir.', body_hi = 'वह खुद पज़ल जोड़ रहा है और 10 मिनट से चुप है। और आप यह समय घर समेटने में लगाना चाहती हैं। नहीं! सोफ़े पर लेट जाइए। आपकी बैटरी भी चार्ज होनी चाहिए, ताकि शाम तक इस रफ़्तार को झेल सकें।', body_id = 'Ia menyusun puzzle sendiri dan sudah 10 menit diam. Kamu ingin memakai waktu itu untuk membereskan rumah. Jangan! Berbaringlah di sofa. Baterainya juga harus terisi agar kamu sanggup mengikuti tempo ini sampai sore.', body_ja = 'ひとりでパズルをして、もう10分も静かです。あなたはその時間で家を片づけたくなりますね。だめです！ソファに横になって。夕方までこのペースについていくには、あなたのバッテリーも充電しなくちゃ。', body_ko = '혼자 퍼즐을 맞추며 10분째 조용한가요? 엄마는 그 시간에 집을 치우고 싶겠죠. 안 돼요! 소파에 누우세요. 저녁까지 이 속도를 버티려면 엄마의 배터리도 충전돼야 해요.', body_nl = 'Hij is in zijn eentje een puzzel aan het maken en al 10 minuten stil. En jij wilt dat moment gebruiken om het huis op te ruimen. Nee! Ga op de bank liggen. Ook jouw batterij moet opladen, zodat je dit tempo tot de avond volhoudt.', body_pl = 'Układa sam puzzle i od 10 minut jest cicho. A ty chcesz wykorzystać tę chwilę na sprzątanie. Nie! Połóż się na kanapie. Twoja bateria też musi się naładować, żebyś wytrzymała to tempo do wieczora.', body_pt = 'Está a fazer um puzzle sozinho e há 10 minutos que está calado. E a mãe quer aproveitar para arrumar a casa. Não! Deite-se no sofá. A sua bateria também precisa de carregar para aguentar este ritmo até à noite.', body_sv = 'Barnet lägger pussel själv och har varit tyst i 10 minuter. Och du vill använda stunden till att städa. Nej! Lägg dig i soffan. Ditt batteri behöver också laddas för att du ska orka med tempot fram till kvällen.', body_vi = 'Bé đang tự ghép xếp hình và đã im lặng 10 phút. Còn mẹ thì muốn tranh thủ lúc này để dọn nhà. Không! Hãy nằm xuống sofa. Pin của mẹ cũng cần được sạc đầy để theo kịp nhịp độ này đến tối.', body_zh = '宝宝自己在拼拼图，已经安静10分钟了。你却想把这段时间用来收拾屋子。不！去沙发上躺下。你的电池也得充满，才能撑住这样的节奏直到晚上。' WHERE id = 'be71bad2-041d-4cb4-a658-89cb36e8a738' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se inquieta cuando se apagan las luces del dormitorio? Pon en un rincón una pequeña lamparita de luz cálida (amarilla o naranja). El resto de la habitación debe quedar totalmente a oscuras para un sueño profundo.', body_fr = 'Il s''inquiète quand on éteint la lumière de la chambre ? Posez dans un coin une petite veilleuse de couleur chaude (jaune ou orange). Le reste de la chambre doit rester complètement sombre pour un sommeil profond.', body_hi = 'सोने के कमरे में लाइटें बुझते ही बेचैन हो जाता है? कमरे के एक कोने में गर्म रंग (पीली या नारंगी) की एक छोटी नाइट लैंप रखिए। बाकी कमरा गहरी नींद के लिए पूरी तरह अँधेरा रहना चाहिए।', body_id = 'Ia gelisah saat lampu kamar dimatikan? Letakkan lampu tidur kecil berwarna hangat (kuning atau oranye) di salah satu sudut kamar. Bagian kamar lainnya harus tetap gelap total untuk tidur yang nyenyak.', body_ja = '寝室の明かりを消すと不安になる？部屋のすみに、暖かい色（黄色やオレンジ）の小さなナイトライトを置きましょう。それ以外の部分は、ぐっすり眠れるように真っ暗にしておいてね。', body_ko = '침실 불이 꺼지면 불안해하나요? 방 한쪽에 작고 따뜻한 색(노란색이나 주황색) 수면등을 두세요. 나머지 공간은 깊은 잠을 위해 완전히 어둡게 유지해야 해요.', body_nl = 'Wordt hij onrustig als het licht in de slaapkamer uitgaat? Zet een klein nachtlampje met een warme kleur (geel of oranje) in een hoek van de kamer. De rest van de kamer blijft helemaal donker voor een diepe slaap.', body_pl = 'Niepokoi się, gdy w sypialni gaśnie światło? Postaw w kącie pokoju małą lampkę nocną w ciepłym kolorze (żółtym lub pomarańczowym). Reszta pokoju powinna pozostać zupełnie ciemna, by sen był głęboki.', body_pt = 'Fica inquieto quando se apagam as luzes do quarto? Ponha num canto do quarto uma pequena luz de presença de cor quente (amarela ou laranja). O resto do quarto deve ficar totalmente escuro para um sono profundo.', body_sv = 'Blir barnet oroligt när lampan släcks i sovrummet? Ställ en liten nattlampa med varmt sken (gult eller orange) i ett hörn av rummet. Resten av rummet ska vara helt mörkt för en djup sömn.', body_vi = 'Bé lo lắng khi đèn phòng ngủ tắt? Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm (vàng hoặc cam) ở một góc phòng. Phần còn lại của căn phòng nên tối hoàn toàn để bé ngủ sâu.', body_zh = '卧室一关灯就不安？在房间一角放一盏小小的暖色（黄色或橙色）小夜灯。房间其余的地方要保持全黑，才能睡得深沉。' WHERE id = 'd2f93631-6ef4-4ba4-9cac-259dafd2fb22' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dictador matutino en acción 👑', body_es = '«¡Ahí no te sientes tú, se sienta mi osito!». En el desayuno es él quien manda en toda la mesa. Sin romper su voluntad de golpe, mantén el equilibrio diciendo: «Vale, que el osito se siente ahí y yo aquí».', title_fr = 'Le dictateur du matin est à l''œuvre 👑', body_fr = '« Ne t''assieds pas là, c''est la place de mon nounours ! » Au petit-déjeuner, c''est lui qui dirige toute la table. Sans briser sa volonté, gardez l''équilibre : « D''accord, ton nounours s''assied là, et moi ici. »', title_hi = 'सुबह का तानाशाह ड्यूटी पर 👑', body_hi = '‘वहाँ तुम मत बैठो, मेरा टेडी बैठेगा!’ नाश्ते पर पूरी मेज़ वही चलाता है। उसकी इच्छा को एकदम से तोड़े बिना, ‘ठीक है, टेडी वहाँ बैठे, मैं यहाँ बैठती हूँ’ कहकर संतुलन बनाए रखिए।', title_id = 'Diktator pagi sedang bertugas 👑', body_id = '''Jangan duduk di situ, itu tempat beruangku!'' Saat sarapan, ia yang mengatur seluruh meja. Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dengan berkata ''Baik, beruangnya duduk di situ, Mama duduk di sini''.', title_ja = '朝の独裁者、活動中 👑', body_ja = '「そこにママは座らないで、くまさんが座るの！」朝ごはんのテーブルは、すべてこの子が仕切っています。意志をばっさり折らずに、「いいよ、くまさんはそこ、ママはここね」と言ってバランスをとりましょう。', title_ko = '아침의 독재자 출근 완료 👑', body_ko = '''거기 엄마가 앉지 마, 곰돌이가 앉을 거야!'' 아침 식탁 전체를 아이가 지휘하나요? 의지를 확 꺾지 말고 ''좋아, 곰돌이는 거기 앉고 엄마는 여기 앉을게''라며 균형을 지켜 주세요.', title_nl = 'De ochtenddictator aan het werk 👑', body_nl = '''Daar mag jij niet zitten, daar zit mijn beertje!'' Bij het ontbijt heeft hij de hele tafel in handen. Breek zijn wil niet hard, maar bewaar de balans: ''Goed, het beertje zit daar en ik zit hier.''', title_pl = 'Poranny dyktator w akcji 👑', body_pl = '„Nie siadaj tam, tam usiądzie mój miś!” Przy śniadaniu to on rządzi całym stołem. Nie łamiąc ostro jego woli, zachowaj równowagę: „Dobrze, miś usiądzie tam, a ja tutaj”.', title_pt = 'O ditador da manhã em ação 👑', body_pt = '"Não te sentes aí, quem se senta é o meu ursinho!" Ao pequeno-almoço é ele quem manda na mesa toda. Sem quebrar a vontade dele de forma brusca, mantenha o equilíbrio: "Está bem, o ursinho senta-se aí e eu sento-me aqui".', title_sv = 'Morgondiktatorn i tjänst 👑', body_sv = '”Där får du inte sitta, nallen ska sitta där!” Vid frukosten styr barnet hela bordet. Utan att knäcka barnets vilja, behåll balansen genom att säga ”Okej, nallen sitter där och jag sitter här”.', title_vi = 'Nhà độc tài buổi sáng đang làm việc 👑', body_vi = '"Mẹ đừng ngồi đó, gấu bông của con sẽ ngồi đấy!" Bé điều khiển cả bàn ăn sáng. Để không bẻ gãy ý chí của bé, hãy giữ cân bằng bằng câu: "Được rồi, gấu bông ngồi đó, còn mẹ ngồi đây".', title_zh = '早晨的小独裁者上岗了 👑', body_zh = '“你别坐那儿，那是小熊的位置！”早餐时整张桌子都归宝宝指挥。别硬生生地压下宝宝的意愿，说一句“好，小熊坐那儿，我坐这儿”，保持平衡就好。' WHERE id = '5407f02f-f40a-48e1-b4f8-80cd1fc9345c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada a la naturaleza ⛅', body_es = 'Las cuatro paredes os han puesto agresivos a los dos. Consulta la herramienta Tiempo y ropa y corred enseguida al parque. Correr al aire libre y la libertad cortan de raíz hasta las rabietas más fuertes.', title_fr = 'S''évader dans la nature ⛅', body_fr = 'Les quatre murs vous rendent tous les deux agressifs. Consultez Météo et tenue et filez tout de suite au parc. Courir en plein air et cette liberté tranchent net même les crises les plus intenses des tout-petits.', title_hi = 'प्रकृति की ओर भागिए ⛅', body_hi = 'चार दीवारों ने उसे भी और आपको भी चिड़चिड़ा बना दिया है। मौसम और कपड़े टूल देखिए और तुरंत पार्क की ओर निकलिए। खुली हवा में दौड़ना और आज़ादी टॉडलर के सबसे तेज़ नखरों को भी चाकू की तरह काट देते हैं।', title_id = 'Kabur ke alam ⛅', body_id = 'Empat dinding membuat ia dan Anda sama-sama gelisah. Cek Cuaca dan Pakaian, lalu segera pergi ke taman. Berlari di udara terbuka dan rasa bebas bisa memotong krisis balita yang paling hebat sekalipun seperti pisau.', title_ja = '自然へ逃げよう ⛅', body_ja = '4つの壁の中で、この子もあなたもイライラ。「天気と服装」をチェックして、すぐに公園へ出かけましょう。外で自由に走りまわれば、いちばん激しいイヤイヤ期のかんしゃくさえ、すっぱり断ち切れます。', title_ko = '자연으로 탈출 ⛅', body_ko = '네 벽이 아이도 엄마도 날카롭게 만들었나요? 날씨와 옷차림 도구를 확인하고 바로 공원으로 달려가세요. 밖에서 마음껏 뛰는 자유는 아무리 심한 떼쓰기도 칼로 자르듯 끊어 줘요.', title_nl = 'Vluchten naar de natuur ⛅', body_nl = 'Vier muren maken jullie allebei agressief. Check de tool Weer en kleding en ga meteen naar het park. Vrij rennen in de buitenlucht snijdt zelfs de heftigste peuterbuien als een mes door.', title_pl = 'Ucieczka na łono natury ⛅', body_pl = 'Cztery ściany rozdrażniły i jego, i ciebie. Sprawdź Pogodę i ubiór i od razu biegnijcie do parku. Bieganie na świeżym powietrzu i swoboda ucinają jak nożem nawet najostrzejsze kryzysy maluchów.', title_pt = 'Fuga para a natureza ⛅', body_pt = 'As quatro paredes deixaram-no a ele, e a si, agressivos. Veja a ferramenta Tempo e Roupa e corram já para o parque. Correr ao ar livre e sentir liberdade cortam como uma faca até as crises de birra mais fortes.', title_sv = 'Flykt ut i naturen ⛅', body_sv = 'De fyra väggarna har gjort både barnet och dig irriterade. Kolla verktyget Väder och kläder och skynda er till parken. Att springa fritt i friska luften skär av även de värsta trotsutbrotten som en kniv.', title_vi = 'Trốn ra thiên nhiên ⛅', body_vi = 'Bốn bức tường khiến cả bé lẫn mẹ đều bức bối. Hãy kiểm tra Thời tiết và trang phục rồi ra công viên ngay. Chạy nhảy tự do ngoài trời có thể dập tắt ngay cả những cơn ăn vạ dữ dội nhất của trẻ nhỏ.', title_zh = '逃向大自然 ⛅', body_zh = '四面墙让宝宝和你都变得烦躁。看看天气与穿衣工具，马上奔向公园吧。在户外奔跑、自由自在，连最激烈的幼儿崩溃也能像刀切一样一下子化解。' WHERE id = 'a1a50d57-7314-4042-848d-a89f6c8fc209' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Momentos de paz por la noche 🛀', body_es = 'Todo el día ha sido un «no quiero» tras otro. Un baño templado no es solo higiene, sirve para reiniciar su sistema nervioso tenso. El sonido y el calor del agua se llevarán toda la tozudez.', title_fr = 'Les instants paisibles du soir 🛀', body_fr = 'Toute la journée n''a été qu''une suite de « je veux pas ». Le bain tiède n''est pas qu''une question d''hygiène, il sert à remettre à zéro son système nerveux sous tension. Le bruit et la chaleur de l''eau emporteront tout son entêtement.', title_hi = 'रात के सुकून भरे पल 🛀', body_hi = 'पूरा दिन ‘मुझे नहीं चाहिए’ में बीता। गुनगुना स्नान सिर्फ़ सफ़ाई के लिए नहीं, उसके तने हुए तंत्रिका तंत्र को रीसेट करने के लिए है। पानी की आवाज़ और गर्माहट सारी ज़िद धो देगी।', title_id = 'Momen damai di malam hari 🛀', body_id = 'Seharian penuh dengan ''aku nggak mau''. Mandi air hangat bukan hanya soal kebersihan, tapi juga untuk menyegarkan kembali sarafnya yang tegang. Suara dan hangatnya air akan membasuh semua sikap keras kepalanya.', title_ja = '夜のやすらぎタイム 🛀', body_ja = '一日じゅう「いやだ」の連続でしたね。ぬるめのお風呂は清潔のためだけでなく、張りつめた神経をリセットするためのもの。お湯の音とぬくもりが、がんこさを全部洗い流してくれます。', title_ko = '밤의 평온한 순간 🛀', body_ko = '하루 종일 ''싫어''로 가득했나요? 따뜻한 목욕은 위생만을 위한 게 아니라 곤두선 신경계를 초기화하는 시간이에요. 물소리와 온기가 모든 고집을 씻어 가 줄 거예요.', title_nl = 'Rustmomenten in de avond 🛀', body_nl = 'De hele dag stond in het teken van ''ik wil niet''. Een lauw bad is niet alleen voor de hygiëne, het reset ook zijn overprikkelde zenuwstelsel. Het geluid en de warmte van het water spoelen alle koppigheid weg.', title_pl = 'Wieczorne chwile spokoju 🛀', body_pl = 'Cały dzień upłynął pod znakiem „nie chcę”. Ciepła kąpiel to nie tylko higiena, ale reset dla jego przeciążonego układu nerwowego. Szum i ciepło wody zmyją cały upór.', title_pt = 'Momentos de paz à noite 🛀', body_pt = 'O dia inteiro foi feito de "não quero". Um banho morno não serve só para a higiene, serve para reiniciar o sistema nervoso tenso dele. O som e o calor da água vão levar consigo toda a teimosia.', title_sv = 'Kvällens lugna stunder 🛀', body_sv = 'Hela dagen har gått åt till ”jag vill inte”. Ett ljummet bad är inte bara för hygienen, det nollställer barnets spända nervsystem. Vattnets ljud och värme sköljer bort all envishet.', title_vi = 'Phút bình yên của đêm 🛀', body_vi = 'Cả ngày toàn là những câu "Con không muốn". Tắm nước ấm không chỉ để vệ sinh, mà còn giúp hệ thần kinh căng thẳng của bé được "khởi động lại". Âm thanh và hơi ấm của nước sẽ cuốn trôi mọi bướng bỉnh.', title_zh = '夜晚的宁静时刻 🛀', body_zh = '一整天都在“我不要”中度过。温水澡不只是为了清洁，更是为了让宝宝紧绷的神经系统重启。水声和温暖会把所有的倔强都冲走。' WHERE id = 'e61af62b-257c-41ec-8846-9d470f2646d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Fuiste al súper confiando en tu memoria y volviste sin los pañales? Son cosas que pasan. Acostúmbrate a apuntar enseguida todo lo que haga falta en la Lista de la compra y deja que la app sea tu memoria digital.', body_fr = 'Vous êtes allée au supermarché en vous fiant à votre mémoire et vous êtes revenue sans les couches ? Ça arrive. Prenez l''habitude de noter tout de suite chaque besoin dans la Liste de courses : laissez l''application être votre mémoire numérique.', body_hi = 'याददाश्त के भरोसे बाज़ार गईं और डायपर भूलकर लौट आईं? ऐसा होता है। हर ज़रूरत तुरंत शॉपिंग लिस्ट में लिखने की आदत बनाइए, ऐप को अपनी डिजिटल याददाश्त बनने दीजिए।', body_id = 'Anda pergi ke supermarket mengandalkan ingatan dan pulang lupa membeli popok? Hal seperti itu biasa terjadi. Biasakan langsung menulis semua kebutuhan di Daftar Belanja, biarkan aplikasi menjadi memori digital Anda.', body_ja = '記憶をたよりに買い物へ行ったら、おむつを買い忘れて帰ってきた？よくあることです。必要なものはすぐに「買い物リスト」に書く習慣をつけて、アプリをあなたのデジタルな記憶にしましょう。', body_ko = '기억만 믿고 마트에 갔다가 기저귀를 잊고 돌아왔나요? 그럴 수 있어요. 필요한 건 바로바로 쇼핑 목록에 적는 습관을 들이고, 앱을 디지털 기억 장치로 삼으세요.', body_nl = 'Vertrouwde je op je geheugen in de supermarkt en kwam je thuis zonder luiers? Dat gebeurt. Maak er een gewoonte van om alles meteen op het Boodschappenlijstje te zetten en laat de app je digitale geheugen zijn.', body_pl = 'Zaufałaś pamięci, poszłaś do sklepu i wróciłaś bez pieluch? Zdarza się. Wyrób sobie nawyk natychmiastowego wpisywania wszystkiego na Listę zakupów, niech aplikacja będzie twoją cyfrową pamięcią.', body_pt = 'Confiou na memória, foi ao supermercado e voltou sem as fraldas? Acontece. Habitue-se a escrever logo tudo o que faz falta na Lista de Compras e deixe que a app seja a sua memória digital.', body_sv = 'Litade du på minnet när du gick till butiken och kom hem utan blöjor? Sånt händer. Gör det till en vana att direkt skriva upp allt som behövs i Inköpslistan och låt appen vara ditt digitala minne.', body_vi = 'Tin vào trí nhớ, mẹ đi siêu thị rồi về nhà mới nhận ra quên mua tã? Chuyện thường thôi. Hãy tập thói quen ghi ngay mọi thứ cần mua vào Danh sách mua sắm, để ứng dụng làm "bộ nhớ số" cho mẹ.', body_zh = '相信自己的记性去了超市，结果忘了买尿布就回来了？这很正常。养成习惯，把所有需要的东西马上写进购物清单，让应用做你的数字记忆。' WHERE id = '8169372c-8d17-46fc-bfc3-eda3a929eaa6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando miras el móvil o estás haciendo algo, viene y te da en la mano o se pone delante. Tiene toda la razón: quiere tu atención completa. Solo 5 minutos de juego con contacto visual sin interrupciones le calmarán.', body_fr = 'Quand vous regardez votre téléphone ou que vous faites quelque chose, il vient vous taper la main ou se met devant vous. Il a tout à fait raison : il veut toute votre attention. Seulement 5 minutes de jeu en le regardant dans les yeux, sans interruption, l''apaiseront.', body_hi = 'जब आप फ़ोन देखती हैं या कोई काम करती हैं, वह आकर हाथ पर मारता है या सामने आ जाता है। वह बिल्कुल सही है, उसे आपका पूरा ध्यान चाहिए। सिर्फ़ 5 मिनट बिना रुके आँख मिलाकर खेलना उसे शांत कर देगा।', body_id = 'Saat kamu melihat ponsel atau sedang bekerja, ia datang menepuk tanganmu atau berdiri di depanmu. Ia sepenuhnya benar, ia menginginkan perhatianmu yang utuh. Bermain hanya 5 menit dengan kontak mata tanpa gangguan akan menenangkannya.', body_ja = 'スマホを見たり用事をしたりしていると、手をたたいたり、目の前に入ってきたりする。この子は正しいんです。あなたのまるごとの注意がほしいだけ。たった5分、目をしっかり合わせて遊ぶだけで落ち着きます。', body_ko = '엄마가 휴대폰을 보거나 일을 할 때 와서 손을 치거나 앞을 가로막나요? 아이가 전적으로 옳아요, 온전한 관심을 원하는 거예요. 딱 5분만 눈을 맞추며 놀아 줘도 금세 진정될 거예요.', body_nl = 'Als jij op je telefoon kijkt of bezig bent, slaat hij op je hand of gaat hij voor je staan. Hij heeft helemaal gelijk: hij wil je onverdeelde aandacht. Maar 5 minuten spelen met ononderbroken oogcontact kalmeert hem al.', body_pl = 'Gdy patrzysz w telefon albo coś robisz, podchodzi, uderza cię w rękę albo staje przed tobą. Ma zupełną rację, chce twojej niepodzielnej uwagi. Już 5 minut zabawy z nieprzerwanym kontaktem wzrokowym go uspokoi.', body_pt = 'Quando olha para o telemóvel ou está a fazer alguma coisa, ele vem bater-lhe na mão ou põe-se à sua frente. Tem toda a razão: quer a sua atenção total. Apenas 5 minutos de brincadeira com contacto visual sem interrupções vão acalmá-lo.', body_sv = 'När du tittar på telefonen eller gör något kommer barnet och slår dig på handen eller ställer sig framför dig. Barnet har helt rätt, det vill ha din odelade uppmärksamhet. Bara 5 minuters lek med oavbruten ögonkontakt lugnar barnet.', body_vi = 'Khi mẹ nhìn điện thoại hay làm việc, bé chạy đến đập vào tay hoặc đứng chắn trước mặt. Bé hoàn toàn có lý, bé muốn mẹ chú ý trọn vẹn. Chỉ cần 5 phút chơi cùng bé, nhìn vào mắt bé không gián đoạn là bé sẽ dịu lại.', body_zh = '你看手机或忙事情时，宝宝就过来拍你的手，或者挡在你面前。宝宝完全有道理，宝宝想要你全心全意的关注。只要5分钟不间断的眼神交流和游戏，就能让宝宝平静下来。' WHERE id = 'a15765ea-b7ce-42a7-91ae-209256ee1beb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tras un día ruidoso, cuando el peque se duerma, mide el silencio de la habitación con el Medidor de sonido. Ver esos números acercarse a cero, esa calma visual, es como el mejor masaje para el cerebro de una madre.', body_fr = 'Après une journée bruyante, quand il dort, mesurez le silence de la chambre avec le Sonomètre. Voir ces chiffres s''approcher de zéro, ce calme visuel, agit comme le plus doux des massages pour le cerveau d''une maman.', body_hi = 'शोर भरे दिन के बाद, बच्चे के सोने पर साउंड मीटर से कमरे की खामोशी मापिए। शून्य के करीब पहुँचते अंक और वह दिखती शांति माँ के दिमाग के लिए सबसे प्यारी मसाज जैसी है।', body_id = 'Setelah hari yang bising, saat anak sudah tidur, ukur keheningan kamar dengan Pengukur Suara. Melihat angka yang mendekati nol, ketenangan visual itu, terasa seperti pijatan terindah untuk otak seorang ibu.', body_ja = 'にぎやかな一日のあと、子どもが寝たら「サウンドメーター」で部屋の静けさを測ってみましょう。ゼロに近づいていく数字を見ること、その目に見える静けさが、ママの脳にはいちばん心地よいマッサージになります。', body_ko = '시끌벅적한 하루가 끝나고 아이가 잠들면 소음 측정기로 방의 고요를 재 보세요. 0에 가까워지는 숫자와 그 시각적인 평온이 엄마의 머리에 가장 좋은 마사지가 돼요.', body_nl = 'Meet na een lawaaiige dag, als hij slaapt, de stilte in de kamer met de Geluidsmeter. Die getallen richting nul zien zakken, die visuele rust, werkt als de fijnste massage voor het brein van een mama.', body_pl = 'Po hałaśliwym dniu, gdy dziecko zaśnie, zmierz ciszę w pokoju Miernikiem dźwięku. Widok liczb zbliżających się do zera, ten wizualny spokój, działa na mózg mamy jak najpiękniejszy masaż.', body_pt = 'Depois de um dia barulhento, quando a criança adormecer, meça o silêncio do quarto com o Medidor de Som. Ver os números a aproximarem-se do zero, essa calma visual, funciona como a melhor massagem para o cérebro da mãe.', body_sv = 'Efter en bullrig dag, mät tystnaden i rummet med Ljudmätaren när barnet sover. Att se siffrorna närma sig noll, det visuella lugnet, fungerar som den skönaste massagen för en mammas hjärna.', body_vi = 'Sau một ngày ồn ào, khi bé đã ngủ, hãy dùng Đo âm thanh để đo sự yên tĩnh trong phòng. Nhìn những con số tiến dần về không, sự yên bình hiện ra trước mắt ấy giống như màn mát-xa tuyệt vời nhất cho não bộ của mẹ.', body_zh = '热闹的一天过后，等宝宝睡着了，用分贝仪测一测房间的安静程度。看着那些越来越接近零的数字，那种视觉上的平静，对妈妈的大脑来说就像一次最美好的按摩。' WHERE id = 'de1347cd-769b-44d4-8aff-75ce2b7d2f0c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Qué rápido pasa el tiempo!', body_es = 'Ya es una persona con sus propias decisiones. Ese carácter tan fuerte te hará sentir muy orgullosa en el futuro. Estos días no se repetirán: abrázale con amor.', title_fr = 'Comme le temps passe vite !', body_fr = 'C''est déjà une vraie petite personne qui prend ses propres décisions. Ce caractère fort vous rendra très fière plus tard. Ces jours-là ne reviendront pas, serrez-le contre vous avec amour.', title_hi = 'वक्त कितनी तेज़ी से बीतता है!', body_hi = 'वह अब अपने फ़ैसले खुद लेने वाला इंसान है। उसका यह मज़बूत स्वभाव आगे चलकर आपको बहुत गर्व महसूस कराएगा। ये दिन दोबारा नहीं आएँगे, उसे प्यार से गले लगाइए।', title_id = 'Betapa cepatnya waktu berlalu!', body_id = 'Ia kini sudah menjadi pribadi yang punya keputusannya sendiri. Karakternya yang kuat ini kelak akan sangat membuat Anda bangga. Hari-hari ini tidak akan terulang, peluklah ia dengan penuh cinta.', title_ja = '時間がたつのはなんて早いの！', body_ja = 'もうすっかり、自分で決める力を持ったひとりの人間です。この強い個性は、将来あなたをとても誇らしい気持ちにしてくれるはず。こんな日々は二度と戻りません。愛をこめてぎゅっと抱きしめて。', title_ko = '시간이 정말 빨라요!', body_ko = '이제 완전히 자기 결정을 가진 한 사람이에요. 이 강한 성격이 나중에 엄마를 무척 자랑스럽게 할 거예요. 이런 날들은 다시 오지 않으니 사랑을 담아 꼭 안아 주세요.', title_nl = 'Wat vliegt de tijd!', body_nl = 'Hij is al een mensje met zijn eigen beslissingen. Dat sterke karakter gaat je later heel trots maken. Deze dagen komen niet terug, knuffel hem vol liefde.', title_pl = 'Jak ten czas szybko leci!', body_pl = 'To już człowiek z własnymi decyzjami. Jego silny charakter da ci w przyszłości wiele powodów do dumy. Te dni się nie powtórzą, przytul go z miłością.', title_pt = 'Como o tempo passa depressa!', body_pt = 'Já é uma pessoa com decisões totalmente próprias. Este caráter forte vai deixá-la muito orgulhosa no futuro. Estes dias não se repetem, abrace-o com amor.', title_sv = 'Vad tiden går fort!', body_sv = 'Barnet är redan en människa med helt egna beslut. Den starka personligheten kommer att göra dig väldigt stolt i framtiden. De här dagarna kommer inte tillbaka, krama barnet med kärlek.', title_vi = 'Thời gian trôi nhanh quá!', body_vi = 'Bé đã là một con người với những quyết định của riêng mình. Tính cách mạnh mẽ này sẽ khiến mẹ vô cùng tự hào trong tương lai. Những ngày này sẽ không lặp lại, hãy ôm bé thật nhiều yêu thương.', title_zh = '时间过得真快！', body_zh = '宝宝已经完全是一个有自己主见的人了。这种坚强的性格，将来会让你非常骄傲。这样的日子不会再重来，用满满的爱拥抱宝宝吧。' WHERE id = '0ff315d9-2ad1-4c8c-9187-ea4c26042a66' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cirujano de verduras 🥦', body_es = '¿Aparta las verduras de la sopa como si las buscara con microscopio? No luches. Descubre en Recetas saludables las formas más originales y ricas de hacer puré las verduras y esconderlas en las salsas.', title_fr = 'Le chirurgien des légumes 🥦', body_fr = 'Il met de côté les légumes de la soupe comme s''il les cherchait au microscope ? Ne luttez pas. Découvrez dans les Recettes saines les façons les plus originales et savoureuses de les réduire en purée et de les cacher dans les sauces.', title_hi = 'सब्ज़ियों का सर्जन 🥦', body_hi = 'सूप की सब्ज़ियाँ ऐसे अलग करता है जैसे माइक्रोस्कोप से ढूँढ रहा हो? लड़ाई मत कीजिए। सेहतमंद रेसिपी में सब्ज़ियों की प्यूरी बनाकर सॉस में छिपाने के सबसे अनोखे और स्वादिष्ट तरीके खोजिए।', title_id = 'Ahli bedah sayur 🥦', body_id = 'Ia menyisihkan sayur di supnya seolah mencarinya dengan mikroskop? Jangan melawan. Temukan cara paling unik dan lezat untuk menghaluskan sayur dan menyembunyikannya dalam saus di Resep Sehat.', title_ja = '野菜の外科医 🥦', body_ja = 'スープの野菜を、顕微鏡でさがすみたいに脇によけている？戦わないで。「ヘルシーレシピ」で、野菜をピューレにしてソースに隠す、ひと味ちがうおいしい方法を見つけましょう。', title_ko = '채소 외과 의사 🥦', body_ko = '수프 속 채소를 현미경으로 찾듯 골라내나요? 싸우지 마세요. 건강한 레시피에서 채소를 퓌레로 만들어 소스에 숨기는 색다르고 맛있는 방법을 찾아보세요.', title_nl = 'Groentechirurg 🥦', body_nl = 'Vist hij de groenten uit zijn soep alsof hij ze met een microscoop zoekt? Ga de strijd niet aan. Ontdek in Gezonde recepten de leukste en lekkerste manieren om groenten te pureren en in sausjes te verstoppen.', title_pl = 'Chirurg od warzyw 🥦', body_pl = 'Odkłada na bok warzywa z zupy, jakby szukał ich pod mikroskopem? Nie walcz. Odkryj w Zdrowych przepisach najciekawsze i najsmaczniejsze sposoby na zmiksowanie warzyw i ukrycie ich w sosach.', title_pt = 'Cirurgião de legumes 🥦', body_pt = 'Separa os legumes da sopa como se os procurasse ao microscópio? Não lute. Descubra nas Receitas Saudáveis as formas mais originais e saborosas de fazer puré de legumes e escondê-los nos molhos.', title_sv = 'Grönsakskirurgen 🥦', body_sv = 'Sorterar barnet bort grönsakerna i soppan som om det letade efter dem med mikroskop? Börja inte bråka. Upptäck de mest annorlunda och goda sätten att mosa grönsaker och gömma dem i såser bland Hälsosamma recept.', title_vi = 'Bác sĩ phẫu thuật rau củ 🥦', body_vi = 'Bé nhặt rau trong bát súp ra như đang soi bằng kính hiển vi? Đừng giằng co. Hãy khám phá trong Công thức lành mạnh những cách xay nhuyễn rau và giấu vào nước sốt thật độc đáo, ngon miệng.', title_zh = '蔬菜小外科医生 🥦', body_zh = '像拿着显微镜一样，把汤里的蔬菜一点点挑到一边？别较劲。在健康食谱里发现把蔬菜打成泥、藏进酱汁里最特别又美味的方法。' WHERE id = 'e4430813-5ad7-446e-9502-6e658d83eddd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de él. En cuanto se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el pilar de la casa, y los pilares también necesitan recuperarse.', body_fr = 'Vous êtes restée debout toute la journée et votre dos est en miettes à force de courir après lui. Dès que l''enfant dort, demandez à votre partenaire 10 minutes de massage des épaules. Vous êtes le pilier de la maison, et les piliers ont besoin d''être restaurés.', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते कमर टूट रही है। बच्चे के सोते ही अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप घर का खंभा हैं, और खंभों को भी फिर से मज़बूत होना ज़रूरी है।', body_id = 'Hari ini kamu terlalu lama berdiri, punggungmu serasa patah karena mengejarnya. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasanganmu. Kamu tiang rumah ini, dan tiang pun wajib dipulihkan.', body_ja = '今日は立ちっぱなしで、追いかけまわして腰がくたくたですね。子どもが寝たらすぐ、パートナーに10分の肩もみをお願いして。あなたはこの家の柱です。柱だって、ちゃんと回復しなくちゃ。', body_ko = '오늘 하루 종일 서 있었고 아이를 쫓아다니느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 이 집의 기둥이고, 기둥도 꼭 회복이 필요해요.', body_nl = 'Je hebt vandaag veel op je benen gestaan en je rug breekt van het achter hem aan rennen. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de pijler van het huis, en pijlers moeten ook hersteld worden.', body_pl = 'Dziś długo byłaś na nogach, plecy bolą cię od biegania za nim. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś filarem domu, a filary też muszą się regenerować.', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de tanto correr atrás dele. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o pilar desta casa, e os pilares também precisam de ser restaurados.', body_sv = 'Du har stått på benen länge i dag och ryggen värker av allt springande efter barnet. Så fort barnet somnar, be din partner om 10 minuters axelmassage. Du är hemmets pelare, och pelare måste också återhämta sig.', body_vi = 'Hôm nay mẹ đứng cả ngày, lưng như muốn gãy vì chạy theo bé. Ngay khi bé ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là trụ cột của gia đình, và trụ cột thì nhất định phải được phục hồi.', body_zh = '今天你站了太久，追着宝宝跑得腰都快断了。宝宝一睡着，就请伴侣给你按摩10分钟肩膀。你是这个家的顶梁柱，顶梁柱也一定要好好修复。' WHERE id = 'e44cdd54-2858-49fa-8fd7-06dc369d29b6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitación a la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación. La melatonina solo se libera rápido en un ambiente oscuro y sin tecnología, y así facilita el paso al sueño.', title_fr = 'Inviter l''obscurité 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée rapidement que dans le noir et sans écran, ce qui facilite le passage au sommeil.', title_hi = 'अँधेरे का न्योता 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है और नींद में जाना आसान करता है।', title_id = 'Undangan menuju gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi, sehingga peralihan ke tidur jadi lebih mudah.', title_ja = '暗さへのお誘い 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニンは暗くてデジタル機器のない環境でこそすばやく分泌され、眠りへの切りかえをスムーズにしてくれます。', title_ko = '어둠으로의 초대 🌙', body_ko = '더 빨리 잠들 수 있게 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌은 어둡고 기기가 없는 환경에서만 빠르게 분비되어 잠드는 걸 쉽게 해 줘요.', title_nl = 'Uitnodiging aan het donker 🌙', body_nl = 'Zet alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt alleen in een donkere omgeving zonder technologie snel aangemaakt en maakt de overgang naar de slaap makkelijker.', title_pl = 'Zaproszenie do ciemności 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina szybko wydziela się tylko w ciemnym otoczeniu bez technologii i ułatwia przejście w sen.', title_pt = 'Convite à escuridão 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia, o que facilita a passagem para o sono.', title_sv = 'En inbjudan till mörkret 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet. Melatonin utsöndras snabbt bara i en mörk och teknikfri miljö och gör övergången till sömn lättare.', title_vi = 'Lời mời gọi bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ, giúp bé chìm vào giấc ngủ dễ dàng hơn.', title_zh = '邀请黑暗 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯和平板屏幕。只有在昏暗、没有电子产品的环境里，褪黑素才会快速分泌，让入睡变得更轻松。' WHERE id = '9c8523f0-548b-4581-bde4-2a8295db3639' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pensando en la guardería 🏫', body_es = '¿Notas que ya necesita socializar más? ¿Es el momento adecuado para la guardería? Entra en la Comunidad Anacan y lee las experiencias reales de adaptación de otras mamás para que te sea más fácil decidir.', title_fr = 'Réflexions sur la crèche 🏫', body_fr = 'Vous sentez qu''il a besoin de plus de vie sociale ? Est-ce le bon moment pour la crèche ? Rejoignez la Communauté Anacan et lisez les vraies expériences d''adaptation d''autres mamans pour vous aider à décider.', title_hi = 'प्ले स्कूल के ख्याल 🏫', body_hi = 'लगता है उसे अब लोगों से घुलने-मिलने की ज़्यादा ज़रूरत है? क्या प्ले स्कूल का सही समय आ गया? Anacan कम्युनिटी में जाकर दूसरी माँओं के एडजस्टमेंट के असली अनुभव पढ़िए और फ़ैसला आसान बनाइए।', title_id = 'Memikirkan TK 🏫', body_id = 'Anda merasa ia kini lebih butuh bersosialisasi? Apakah ini waktu yang tepat untuk TK? Masuklah ke Komunitas Anacan dan baca pengalaman adaptasi nyata ibu-ibu lain agar keputusan Anda lebih mudah.', title_ja = '保育園のことを考える 🏫', body_ja = 'もっと人とかかわる時間が必要だと感じていますか？保育園にちょうどいい時期かな？Anacanコミュニティで、ほかのママたちのリアルな慣らし保育の体験を読んで、決めるヒントにしましょう。', title_ko = '어린이집 생각 🏫', body_ko = '아이에게 사회생활이 더 필요하다고 느끼나요? 어린이집에 보낼 때가 됐을까요? Anacan 커뮤니티에서 다른 엄마들의 실제 적응 경험담을 읽고 결정을 쉽게 내려 보세요.', title_nl = 'Gedachten over de opvang 🏫', body_nl = 'Heb je het gevoel dat hij meer behoefte heeft aan contact met andere kinderen? Is het de juiste tijd voor de opvang? Ga naar de Anacan Community en lees de echte wenervaringen van andere mama''s, zo wordt je beslissing makkelijker.', title_pl = 'Myśli o przedszkolu 🏫', body_pl = 'Czujesz, że potrzebuje już więcej kontaktu z rówieśnikami? Czy to dobry czas na przedszkole? Wejdź do Społeczności Anacan i poczytaj o prawdziwych doświadczeniach adaptacji innych mam, by łatwiej podjąć decyzję.', title_pt = 'A pensar no jardim de infância 🏫', body_pt = 'Sente que ele já precisa de socializar mais? Será a altura certa para o jardim de infância? Entre na Comunidade Anacan e leia as experiências reais de adaptação de outras mães para facilitar a sua decisão.', title_sv = 'Tankar om förskola 🏫', body_sv = 'Känner du att barnet nu behöver mer social kontakt? Är det rätt tid för förskola? Gå in i Anacan Community och läs andra mammors verkliga erfarenheter av inskolning, så blir beslutet lättare.', title_vi = 'Suy nghĩ về trường mầm non 🏫', body_vi = 'Mẹ cảm thấy bé cần giao tiếp xã hội nhiều hơn? Đã đến lúc cho bé đi mầm non chưa? Hãy vào Cộng đồng Anacan đọc những trải nghiệm thích nghi thực tế của các mẹ khác để quyết định dễ dàng hơn.', title_zh = '关于幼儿园的思考 🏫', body_zh = '感觉宝宝更需要社交了？现在是上幼儿园的合适时机吗？进入Anacan社区，读读其他妈妈真实的入园适应经历，让决定变得更容易。' WHERE id = 'b7c3f40e-e406-412b-86a2-1c33a12692d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te ayudo! 🧽', body_es = '¿Mientras friegas los platos quiere poner una silla a tu lado para jugar con el agua? En realidad no quiere ayudar, quiere estar en el centro de la acción. Dale un plato pequeño de plástico y deja que él también lo enjabone.', title_fr = 'Je t''aide ! 🧽', body_fr = 'Quand vous faites la vaisselle, il veut absolument installer une chaise à côté de vous pour jouer avec l''eau ? En réalité, il ne veut pas tant aider qu''être au cœur de l''action. Donnez-lui un petit bol en plastique et laissez-le savonner, lui aussi.', title_hi = 'मैं मदद करूँ! 🧽', body_hi = 'आप बर्तन धोती हैं तो वह ज़रूर पास में कुर्सी लगाकर पानी से खेलना चाहता है? असल में वह मदद नहीं, काम के बीचोंबीच रहना चाहता है। उसे एक छोटा प्लास्टिक का बर्तन दीजिए, उसे भी साबुन लगाने दीजिए।', title_id = 'Aku bantu ya! 🧽', body_id = 'Saat Anda mencuci piring, ia bersikeras menaruh kursi di samping Anda dan bermain air? Sebenarnya ia bukan ingin membantu, tapi ingin berada di pusat kegiatan. Beri ia mangkuk plastik kecil dan biarkan ia ikut menyabuninya.', title_ja = 'お手伝いするよ！ 🧽', body_ja = 'あなたが洗いものをしていると、必ずいすを持ってきて水遊びしたがる？本当はお手伝いではなく、その場の主役になりたいんです。小さなプラスチックの容器を渡して、一緒に泡立てさせてあげましょう。', title_ko = '내가 도와줄게! 🧽', body_ko = '설거지할 때 꼭 옆에 의자를 갖다 놓고 물장난을 하고 싶어 하나요? 사실 돕기보다는 일의 한가운데에 있고 싶은 거예요. 작은 플라스틱 그릇을 주고 거품을 내게 해 주세요.', title_nl = 'Ik help je! 🧽', body_nl = 'Wil hij als jij afwast per se een stoel ernaast zetten en met water spelen? Eigenlijk wil hij niet zozeer helpen, maar midden in de actie zijn. Geef hem een klein plastic bakje en laat hem ook lekker sop maken.', title_pl = 'Pomogę ci! 🧽', body_pl = 'Gdy zmywasz naczynia, koniecznie chce przystawić krzesło i bawić się wodą obok ciebie? Tak naprawdę nie chce pomagać, tylko być w centrum wydarzeń. Daj mu małą plastikową miseczkę i niech też ją namydli.', title_pt = 'Deixa-me ajudar-te! 🧽', body_pt = 'Enquanto lava a loiça, ele quer pôr uma cadeira ao seu lado e brincar com a água? Na verdade não quer ajudar, quer estar no centro do processo. Dê-lhe uma pequena taça de plástico e deixe-o ensaboá-la também.', title_sv = 'Jag hjälper dig! 🧽', body_sv = 'Vill barnet absolut ställa en stol bredvid dig och leka med vattnet när du diskar? Egentligen vill barnet inte hjälpa till, utan vara i centrum av det som händer. Ge barnet en liten plastskål och låt det också diska med lite tvål.', title_vi = 'Con giúp mẹ nhé! 🧽', body_vi = 'Khi mẹ rửa bát, bé nhất định kê ghế đứng cạnh để nghịch nước? Thật ra bé không muốn giúp, mà muốn được ở trung tâm của mọi việc. Hãy đưa bé một chiếc bát nhựa nhỏ, để bé cũng được xoa xà phòng.', title_zh = '我来帮你！🧽', body_zh = '你洗碗时，宝宝非要搬张椅子到旁边玩水？其实宝宝不是想帮忙，而是想成为整件事的中心。给宝宝一个小塑料碗，让宝宝也来打打肥皂吧。' WHERE id = 'd8d022ce-8e44-42aa-972f-aa293c4341c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos susurrados 🪄', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, muy bajito, una historia corta de Cuentos inteligentes. Susurrar es el método más natural y relajante para preparar el cerebro para dormir.', title_fr = 'Contes chuchotés 🪄', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et chuchotez-lui à l''oreille, tout bas, une courte histoire des Contes intelligents. Le chuchotement est la façon la plus naturelle et la plus apaisante de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाती कहानियाँ 🪄', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर स्मार्ट कहानियों से एक छोटी कहानी बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे प्राकृतिक और सुकून भरा तरीका है।', title_id = 'Dongeng berbisik 🪄', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan alur singkat dari Dongeng Pintar ke telinganya dengan suara sangat pelan. Bisikan adalah cara paling alami dan menenangkan untuk menyiapkan otak tidur.', title_ja = 'ささやきのおはなし 🪄', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、「スマートおはなし」から短いお話を、耳もとでとても小さな声でささやいてあげて。ささやき声は、脳を眠りへ導くいちばん自然で心落ち着く方法です。', title_ko = '속삭이는 동화 🪄', body_ko = '방의 불을 모두 끄세요. 옆에 누워 스마트 동화의 짧은 이야기를 아주 낮은 목소리로 귓가에 속삭여 주세요. 속삭임은 뇌를 잠들 준비시키는 가장 자연스럽고 차분한 방법이에요.', title_nl = 'Fluistersprookjes 🪄', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en fluister heel zachtjes een kort verhaaltje uit Slimme sprookjes in zijn oor. Fluisteren is de meest natuurlijke en rustgevende manier om het brein klaar te maken voor de slaap.', title_pl = 'Bajki szeptem 🪄', body_pl = 'Zgaś całkowicie światła w pokoju. Połóż się obok i bardzo cicho wyszeptaj mu do ucha krótką historię z Mądrych bajek. Szept to najbardziej naturalny i kojący sposób, by przygotować mózg do snu.', title_pt = 'Histórias em sussurro 🪄', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, uma história curta das Histórias Inteligentes. Sussurrar é o método mais natural e calmante para preparar o cérebro para o sono.', title_sv = 'Viskade sagor 🪄', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och viska en kort berättelse från Smarta sagor mycket tyst i örat. Viskningar är den mest naturliga och lugnande metoden för att förbereda hjärnan för sömn.', title_vi = 'Truyện kể thì thầm 🪄', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ vào tai bé một câu chuyện ngắn từ Truyện cổ tích thông minh. Thì thầm là cách tự nhiên và êm dịu nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话童话 🪄', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，在宝宝耳边悄悄讲一个智慧童话里的小故事。悄悄话是帮大脑准备入睡最自然、最能让人平静的方法。' WHERE id = '63dc600c-4255-41f7-8695-78dd689a1998' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Hoy le dice a su juguete esa frase emotiva o rara que ayer le dijiste a tu amiga por teléfono! Su vocabulario crece a una velocidad tremenda y te copia. Ahora tienes que cuidar el doble lo que dices.', body_fr = 'Cette phrase émotive ou bizarre que vous avez dite hier au téléphone à votre amie, il la répète aujourd''hui à son jouet ! Son vocabulaire s''enrichit à une vitesse folle et il vous imite. Faites désormais deux fois plus attention à vos mots.', body_hi = 'कल फ़ोन पर सहेली से कहा गया वह भावुक या अजीब वाक्य आज वह अपने खिलौने से कह रहा है! उसकी शब्दावली गज़ब की रफ़्तार से बढ़ रही है और वह आपकी नकल करता है। अब अपने शब्दों पर दोगुना ध्यान दीजिए।', body_id = 'Kalimat emosional atau aneh yang kemarin Anda ucapkan kepada teman di telepon, hari ini ia ucapkan kepada mainannya! Kosakatanya berkembang sangat cepat dan ia meniru Anda. Kini Anda harus dua kali lebih berhati-hati dengan kata-kata Anda.', body_ja = '昨日あなたが電話で友だちに言った、感情的な一言や変な言い回しを、今日はおもちゃに向かって言っている！語彙がものすごいスピードで増えていて、あなたをまねしています。言葉づかいにはこれまでの倍、気をつけましょう。', body_ko = '어제 통화하며 친구에게 했던 감정적이거나 엉뚱한 말을 오늘 장난감에게 하고 있나요! 어휘가 무서운 속도로 늘고 엄마를 그대로 따라 해요. 이제 말을 두 배로 조심해야 해요.', body_nl = 'Die emotionele of rare zin die je gisteren aan de telefoon tegen je vriendin zei, zegt hij vandaag tegen zijn knuffel! Zijn woordenschat groeit razendsnel en hij doet je na. Let vanaf nu dubbel zo goed op je woorden.', body_pl = 'To emocjonalne albo dziwne zdanie, które wczoraj powiedziałaś przez telefon przyjaciółce, dziś mówi do swojej zabawki! Jego słownictwo rośnie w zawrotnym tempie, a on cię kopiuje. Teraz musisz podwójnie uważać na słowa.', body_pt = 'Hoje diz ao brinquedo aquela frase emotiva ou estranha que ontem disse à sua amiga ao telefone! O vocabulário cresce a uma velocidade impressionante e ele copia-a. Agora tem de ter o dobro do cuidado com as palavras.', body_sv = 'Den känslosamma eller konstiga meningen du sa till din väninna i telefon i går säger barnet i dag till sin leksak! Ordförrådet växer otroligt snabbt och barnet härmar dig. Nu måste du vara dubbelt så noga med vad du säger.', body_vi = 'Câu nói đầy cảm xúc hay kỳ quặc mà hôm qua mẹ nói với bạn qua điện thoại, hôm nay bé lại nói với đồ chơi của mình! Vốn từ của bé mở rộng với tốc độ chóng mặt và bé bắt chước mẹ. Từ giờ mẹ cần cẩn thận gấp đôi với lời nói của mình.', body_zh = '昨天你打电话时对闺蜜说的那句情绪化或奇怪的话，今天宝宝就对着玩具说了出来！词汇量正在飞速扩展，宝宝在模仿你。现在你说话得加倍注意了。' WHERE id = '76d2443b-1074-45cd-a82d-59ba223792bb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Valórate 🥗', body_es = 'Has cocinado huevos de 4 formas distintas para que coma, pero ¿y tú qué has comido? Prepárate con Recetas saludables un plato especial, rico en hierro y calcio, que se hace en 5 minutos, y date un premio.', title_fr = 'Accordez-vous de la valeur 🥗', body_fr = 'Vous avez cuisiné les œufs de 4 façons différentes pour le faire manger, mais vous, qu''avez-vous mangé ? Récompensez-vous avec une assiette spéciale des Recettes saines, riche en fer et en calcium, prête en 5 minutes.', title_hi = 'अपनी कद्र कीजिए 🥗', body_hi = 'उसे खिलाने के लिए 4 तरह से अंडे बनाए, और आपने क्या खाया? सेहतमंद रेसिपी से 5 मिनट में बनने वाली, आयरन और कैल्शियम से भरपूर एक खास प्लेट तैयार कीजिए और खुद को इनाम दीजिए।', title_id = 'Hargai dirimu 🥗', body_id = 'Kamu memasak telur dengan 4 cara berbeda untuk menyuapinya, lalu kamu sendiri makan apa? Siapkan sepiring hidangan istimewa kaya zat besi dan kalsium dari Resep Sehat yang jadi dalam 5 menit, dan hadiahi diri Anda.', title_ja = '自分を大切に 🥗', body_ja = 'この子に食べさせるために卵を4通りも料理したけれど、あなたは何を食べた？「ヘルシーレシピ」から5分でできる、鉄分とカルシウムたっぷりの特別なひと皿を用意して、自分にごほうびをあげましょう。', title_ko = '나를 소중히 🥗', body_ko = '아이를 먹이려고 달걀을 4가지 방법으로 요리했는데, 엄마는 뭘 드셨나요? 건강한 레시피에서 5분이면 완성되는 철분과 칼슘이 풍부한 특별한 한 접시로 나에게 상을 주세요.', title_nl = 'Waardeer jezelf 🥗', body_nl = 'Je hebt op 4 manieren eieren gebakken om hem te laten eten, maar wat heb jij gegeten? Beloon jezelf met een speciaal bord uit Gezonde recepten, rijk aan ijzer en calcium en in 5 minuten klaar.', title_pl = 'Zadbaj o siebie 🥗', body_pl = 'Przygotowałaś jajka na 4 różne sposoby, żeby go nakarmić, a ty co zjadłaś? Nagródź się wyjątkowym talerzem ze Zdrowych przepisów, bogatym w żelazo i wapń, gotowym w 5 minut.', title_pt = 'Dê-se valor 🥗', body_pt = 'Fez ovos de 4 maneiras diferentes para ele comer, mas e a mãe, o que comeu? Prepare um prato especial rico em ferro e cálcio das Receitas Saudáveis, pronto em 5 minutos, e recompense-se.', title_sv = 'Tänk på ditt eget värde 🥗', body_sv = 'Du lagade ägg på 4 olika sätt för att få barnet att äta, men vad åt du själv? Belöna dig med en särskild tallrik rik på järn och kalcium från Hälsosamma recept, klar på 5 minuter.', title_vi = 'Trân trọng bản thân 🥗', body_vi = 'Mẹ đã nấu trứng theo 4 cách khác nhau để bé chịu ăn, còn mẹ đã ăn gì chưa? Hãy tự thưởng cho mình một đĩa đặc biệt giàu sắt và canxi, làm xong trong 5 phút từ Công thức lành mạnh.', title_zh = '珍惜你自己 🥗', body_zh = '为了让宝宝吃饭，你换了4种做法煮鸡蛋，那你自己吃了什么？从健康食谱里做一份5分钟搞定、富含铁和钙的特别餐盘，好好犒劳自己吧。' WHERE id = 'a624ef08-9c66-462b-82e4-a4aa90f5b17b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ayuda del ruido blanco 🤫', body_es = 'Al quedarse dormido está más sensible. Para neutralizar los ruidos que entran por la ventana, activa el sonido de fondo del Medidor de sonido y llena la habitación de una calma duradera.', title_fr = 'L''aide du bruit blanc 🤫', body_fr = 'Au moment de l''endormissement, il est plus sensible. Pour neutraliser les bruits venant de la fenêtre, activez le bruit de fond du Sonomètre dans la chambre et installez un calme durable.', title_hi = 'व्हाइट नॉइज़ की मदद 🤫', body_hi = 'सोते समय वह ज़्यादा संवेदनशील होता है। खिड़की से आने वाली आवाज़ों को बेअसर करने के लिए कमरे में साउंड मीटर की बैकग्राउंड आवाज़ चालू कीजिए और कमरे में स्थायी सुकून लाइए।', title_id = 'Bantuan suara putih 🤫', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Untuk meredam suara dari jendela, aktifkan suara latar Pengukur Suara di kamar dan hadirkan ketenangan yang bertahan lama.', title_ja = 'ホワイトノイズの力 🤫', body_ja = '眠りに落ちるときは、とても敏感になります。窓から入る音をやわらげるために、「サウンドメーター」の背景音をオンにして、部屋に落ち着いた安らぎを届けましょう。', title_ko = '백색소음의 도움 🤫', body_ko = '잠이 드는 순간에는 예민함이 커져요. 창밖 소리를 덮을 수 있게 소음 측정기의 배경 소리를 켜고 방에 오래가는 평온을 만들어 주세요.', title_nl = 'De hulp van witte ruis 🤫', body_nl = 'Tijdens het inslapen is hij extra gevoelig. Zet het achtergrondgeluid van de Geluidsmeter aan om geluiden van buiten te neutraliseren en breng blijvende rust in de kamer.', title_pl = 'Pomocny biały szum 🤫', body_pl = 'W chwili zasypiania wrażliwość rośnie. Aby wyciszyć dźwięki zza okna, włącz w pokoju dźwięk tła w Mierniku dźwięku i zapewnij trwały spokój.', title_pt = 'A ajuda do ruído branco 🤫', body_pt = 'Na hora de adormecer, a sensibilidade aumenta. Para neutralizar os sons que entram pela janela, ative o som de fundo do Medidor de Som no quarto e traga-lhe uma calma duradoura.', title_sv = 'Vitt brus som hjälp 🤫', body_sv = 'Känsligheten ökar precis när barnet somnar. Sätt på bakgrundsljudet i Ljudmätaren för att dämpa ljuden från fönstret och ge rummet ett varaktigt lugn.', title_vi = 'Trợ thủ tiếng ồn trắng 🤫', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc bé nhạy cảm nhất. Để át đi tiếng ồn vọng vào từ cửa sổ, hãy bật âm thanh nền của Đo âm thanh trong phòng, mang lại sự yên bình lâu dài.', title_zh = '白噪音来帮忙 🤫', body_zh = '入睡的那一刻是最敏感的时候。打开分贝仪的背景音，盖过窗外传来的声音，给房间带来持久的宁静。' WHERE id = '0f7458af-fb58-4fe6-9907-6a5b773bca96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿El pijama lleno de comida y la ropa de manchas de pintura? Los niños no tienen que crecer limpios, tienen que ensuciarse descubriendo. Usa baberos de silicona y deja el resto a la lavadora.', body_fr = 'Son pyjama est couvert de nourriture, ses vêtements de taches de peinture ? Les enfants ne doivent pas grandir propres, ils doivent se salir en explorant. Utilisez des bavoirs en silicone et laissez le reste à la machine à laver.', body_hi = 'पजामे पर खाना, कपड़ों पर रंग के दाग? बच्चों को साफ़-सुथरा बड़ा नहीं होना चाहिए, उन्हें खोजते हुए गंदा होना चाहिए। सिलिकॉन बिब इस्तेमाल कीजिए, बाकी वॉशिंग मशीन पर छोड़ दीजिए।', body_id = 'Piyamanya penuh makanan, bajunya penuh noda cat? Anak tidak harus tumbuh bersih, mereka harus kotor karena bereksplorasi. Gunakan celemek silikon, dan serahkan sisanya pada mesin cuci.', body_ja = 'パジャマは食べこぼし、服は絵の具だらけ？子どもはきれいなまま育つ必要はありません。発見しながら汚れていいんです。シリコンのスタイを使って、残りは洗濯機にまかせましょう。', body_ko = '잠옷은 음식 범벅, 옷은 물감 얼룩투성이인가요? 아이는 깨끗하게만 자라면 안 돼요, 탐험하며 더러워져야 해요. 실리콘 턱받이를 쓰고 나머지는 세탁기에 맡기세요.', body_nl = 'Zit zijn pyjama onder het eten en zijn kleren onder de verfvlekken? Kinderen hoeven niet schoon op te groeien, ze moeten vies worden van het ontdekken. Gebruik siliconen slabbetjes en laat de rest aan de wasmachine over.', body_pl = 'Piżama w jedzeniu, ubranie w plamach z farby? Dzieci nie muszą dorastać czyste, mają się brudzić, odkrywając świat. Używaj silikonowych śliniaków, a resztę zostaw pralce.', body_pt = 'O pijama cheio de comida e a roupa com manchas de tinta? As crianças não têm de crescer limpas, têm de se sujar a descobrir. Use babetes de silicone e deixe o resto para a máquina de lavar.', body_sv = 'Pyjamasen är full av mat och kläderna av färgfläckar? Barn ska inte växa upp rena, de ska bli smutsiga när de upptäcker. Använd silikonhaklappar och överlåt resten åt tvättmaskinen.', body_vi = 'Đồ ngủ dính đầy thức ăn, quần áo lem luốc màu vẽ? Trẻ con không cần lớn lên sạch sẽ, bé cần lấm bẩn khi khám phá. Hãy dùng yếm silicon, phần còn lại cứ để máy giặt lo.', body_zh = '睡衣上沾满饭粒，全身都是颜料印？孩子不该干干净净地长大，而要在探索中弄脏自己。用上硅胶围兜，剩下的就交给洗衣机吧。' WHERE id = '143f9431-42d8-41e6-9983-ce9dde347219' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se agarra al sofá o al sillón e intenta trepar? Su equilibrio y su fuerza muscular aumentan. Protégele, pero no frenes de ninguna manera sus intentos de alpinista ni que descubra la física.', body_fr = 'Il s''agrippe au canapé ou au fauteuil pour grimper ? Son équilibre et sa force musculaire augmentent. Protégez-le, mais n''empêchez surtout pas ces tentatives d''alpiniste ni sa découverte de la physique.', body_hi = 'सोफ़े और कुर्सी को पकड़कर ऊपर चढ़ने की कोशिश करता है? संतुलन और मांसपेशियों की ताकत बढ़ रही है। उसकी हिफ़ाज़त कीजिए, पर इन पर्वतारोही कोशिशों और भौतिकी की खोज में बिल्कुल रुकावट मत डालिए।', body_id = 'Ia berpegangan pada sofa dan kursi untuk memanjat ke atas? Keseimbangan dan kekuatan ototnya bertambah. Jaga keamanannya, tapi jangan sekali-kali menghalangi usaha pendakiannya dan penemuannya tentang fisika.', body_ja = 'ソファやいすにつかまって、上へよじのぼろうとしている？バランス感覚と筋力が育っています。安全は守りつつ、この登山家のチャレンジや物理の発見を、決してじゃましないでね。', body_ko = '소파나 안락의자를 붙잡고 기어오르려 하나요? 균형 감각과 근력이 자라고 있어요. 안전은 지켜 주되, 이 등반 시도와 물리 탐험은 절대 막지 마세요.', body_nl = 'Probeert hij zich aan de bank of fauteuil op te trekken en naar boven te klimmen? Zijn evenwicht en spierkracht groeien. Bescherm hem, maar houd deze klimpogingen en zijn ontdekking van de natuurkunde zeker niet tegen.', body_pl = 'Łapie się kanapy i fotela, próbując wspiąć się wyżej? Równowaga i siła mięśni rosną. Pilnuj go, ale nie przeszkadzaj mu w tych wspinaczkowych próbach i odkrywaniu fizyki.', body_pt = 'Agarra-se ao sofá e ao cadeirão e tenta trepar? O equilíbrio e a força muscular estão a aumentar. Proteja-o, mas não impeça de forma nenhuma estas tentativas de alpinismo nem a descoberta da física.', body_sv = 'Håller barnet sig i soffan och fåtöljen och försöker klättra upp? Balansen och muskelstyrkan ökar. Skydda barnet, men stoppa absolut inte klätterförsöken och upptäckten av fysiken.', body_vi = 'Bé bám vào sofa, ghế bành để cố trèo lên? Khả năng giữ thăng bằng và sức mạnh cơ bắp đang tăng lên. Hãy giữ an toàn cho bé, nhưng tuyệt đối đừng ngăn cản những lần "leo núi" và khám phá vật lý này.', body_zh = '抓着沙发、扶手椅想往上爬？平衡能力和肌肉力量都在增长。保护好宝宝，但千万别阻止这些小小登山家的尝试和对物理的探索。' WHERE id = '6aecb8fd-7228-4ba7-9f34-65a8f0cda801' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te agota pensar «este niño nunca se va a calmar»? Entra en la Comunidad Anacan: verás que todos los niños pasan por estas crisis tormentosas cerca de los 3 años y respirarás hondo.', body_fr = 'L''idée que « cet enfant ne se calmera jamais » vous épuise ? Rejoignez la Communauté Anacan : vous verrez que chaque enfant traverse ces crises orageuses à l''approche des 3 ans, et vous pourrez enfin souffler.', body_hi = '‘यह बच्चा कभी शांत नहीं होगा’ वाला ख्याल आपको थका रहा है? Anacan कम्युनिटी में जाइए, आप देखेंगी कि 3 साल के करीब हर बच्चा इन तूफ़ानी नखरों से गुज़रता है, और आप गहरी साँस ले पाएँगी।', body_id = 'Pikiran ''anak ini tidak akan pernah tenang'' membuat Anda lelah? Masuklah ke Komunitas Anacan, Anda akan melihat bahwa setiap anak melewati krisis penuh badai ini menjelang usia 3 tahun, dan Anda akan bisa menarik napas lega.', body_ja = '「この子は一生落ち着かないんじゃないか」と思って疲れていませんか？Anacanコミュニティを開いてみて。どの子も3歳前後にこの嵐のような時期を通ると知って、深く息をつけるはずです。', body_ko = '''이 아이는 절대 진정하지 않을 거야''라는 생각에 지쳤나요? Anacan 커뮤니티에 들어가 보세요. 모든 아이가 세 살 무렵 이런 폭풍 같은 시기를 지난다는 걸 알고 깊은 숨을 쉬게 될 거예요.', body_nl = 'Word je moe van de gedachte ''dit kind wordt nooit rustig''? Ga naar de Anacan Community: je ziet dat elk kind rond 3 jaar door deze stormachtige buien gaat, en je haalt opgelucht adem.', body_pl = 'Męczy cię myśl, że to dziecko nigdy się nie uspokoi? Wejdź do Społeczności Anacan, zobaczysz, że każde dziecko w okolicach 3 lat przechodzi te burzliwe kryzysy, i odetchniesz głęboko.', body_pt = 'Cansa-a pensar "esta criança nunca se vai acalmar"? Entre na Comunidade Anacan: vai ver que todas as crianças passam por estas crises tempestuosas perto dos 3 anos e vai respirar fundo.', body_sv = 'Tröttar tanken ”det här barnet kommer aldrig att lugna ner sig” ut dig? Gå in i Anacan Community, så ser du att alla barn går igenom de här stormiga kriserna inför 3 år, och du kan andas ut djupt.', body_vi = 'Ý nghĩ "đứa trẻ này sẽ không bao giờ chịu yên" khiến mẹ mệt mỏi? Hãy vào Cộng đồng Anacan, mẹ sẽ thấy đứa trẻ nào cũng trải qua những cơn khủng hoảng sóng gió này khi gần 3 tuổi, và mẹ sẽ thở phào nhẹ nhõm.', body_zh = '“这孩子永远都安静不下来”的念头让你心累？进入Anacan社区，你会看到每个孩子在快3岁时都会经历这些暴风雨般的崩溃，然后深深地松一口气。' WHERE id = '0db41c26-c87d-4bd7-8650-e9fd07449904' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Uno, dos, tres... ¡diez! 🔢', body_es = '¿Intenta contar sus dedos o sus juguetes? Se despierta su inteligencia matemática. No te pierdas estos pequeños intentos que avanzan a una velocidad increíble.', title_fr = 'Un, deux, trois... dix ! 🔢', body_fr = 'Il essaie de compter ses doigts ou ses jouets ? Son intelligence mathématique s''éveille. Ne manquez pas ces petites tentatives qui progressent à une vitesse incroyable.', title_hi = 'एक, दो, तीन... दस! 🔢', body_hi = 'अपनी उँगलियाँ या खिलौने गिनने की कोशिश करता है? गणित वाली समझ जाग रही है। गज़ब की रफ़्तार से बढ़ती इन छोटी कोशिशों को मत चूकिए।', title_id = 'Satu, dua, tiga... sepuluh! 🔢', body_id = 'Ia mencoba menghitung jari atau mainannya? Kecerdasan matematisnya mulai bangun. Jangan lewatkan usaha kecil yang berkembang luar biasa cepat ini.', title_ja = 'いち、に、さん…じゅう！ 🔢', body_ja = '指やおもちゃを数えようとしている？算数の力が目覚めています。ものすごい速さで育っていく、この小さなチャレンジを見逃さないで。', title_ko = '하나, 둘, 셋... 열! 🔢', body_ko = '손가락이나 장난감을 세려고 하나요? 수학적 사고가 깨어나고 있어요. 놀라운 속도로 발전하는 이 작은 시도들을 놓치지 마세요.', title_nl = 'Een, twee, drie... tien! 🔢', body_nl = 'Probeert hij zijn vingers of speelgoed te tellen? Zijn wiskundig inzicht wordt wakker. Mis deze kleine pogingen niet, ze ontwikkelen zich ongelooflijk snel.', title_pl = 'Raz, dwa, trzy... dziesięć! 🔢', body_pl = 'Próbuje liczyć paluszki albo zabawki? Budzi się inteligencja matematyczna. Nie przegap tych małych prób, które rozwijają się w niesamowitym tempie.', title_pt = 'Um, dois, três... dez! 🔢', body_pt = 'Tenta contar os dedos ou os brinquedos? A inteligência matemática está a despertar. Não perca estas pequenas tentativas, que evoluem a uma velocidade incrível.', title_sv = 'Ett, två, tre... tio! 🔢', body_sv = 'Försöker barnet räkna sina fingrar eller leksaker? Den matematiska intelligensen vaknar. Missa inte de små försöken som utvecklas otroligt snabbt.', title_vi = 'Một, hai, ba... mười! 🔢', body_vi = 'Bé cố đếm ngón tay hay đồ chơi của mình? Trí thông minh toán học đang thức dậy. Đừng bỏ lỡ những nỗ lực nhỏ đang phát triển với tốc độ đáng kinh ngạc này.', title_zh = '一、二、三……十！🔢', body_zh = '想数自己的手指或玩具？数学智能正在觉醒。别错过这些以惊人速度进步的小小尝试。' WHERE id = '448fd3b8-143f-4fee-a40b-1b20e42ebbba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No cargues tú sola con los despertares nocturnos ni con dormirle. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales. Esta noche el paso al sueño será de diez.', body_fr = 'Ne gérez pas seule les réveils nocturnes et le coucher. Réveillez aussi votre partenaire : être une équipe, c''est partager les responsabilités à égalité. Cette nuit, l''endormissement, c''est entièrement son tour.', body_hi = 'रात में जागना और सुलाना पूरी तरह अकेले मत झेलिए। अपने साथी को भी जगाइए, टीम होने का मतलब ज़िम्मेदारी बराबर बाँटना है। आज रात सुलाने की बारी पूरी तरह उनकी है।', body_id = 'Jangan menanggung sendiri urusan bangun malam dan menidurkan anak. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil. Malam ini, urusan menidurkan sepenuhnya giliran dia.', body_ja = '夜中の目覚めや寝かしつけを、全部ひとりで抱えこまないで。パートナーも起こしましょう。チームでいるとは、責任を平等に分けること。今夜の寝かしつけは完全にパートナーの番です。', body_ko = '밤에 깨는 일과 재우기를 혼자 다 떠안지 마세요. 배우자도 깨우세요, 팀이란 책임을 똑같이 나누는 거예요. 오늘 밤 재우기는 온전히 배우자 차례예요.', body_nl = 'Draag het nachtelijk wakker worden en het in slaap brengen niet helemaal alleen. Maak je partner ook wakker: een team zijn betekent de verantwoordelijkheid eerlijk verdelen. Vannacht is het in slaap brengen helemaal zijn taak.', body_pl = 'Nie dźwigaj nocnych pobudek i usypiania zupełnie sama. Obudź też partnera, bycie drużyną to równy podział obowiązków. Tej nocy usypianie jest całkowicie po jego stronie.', body_pt = 'Não aguente sozinha os despertares noturnos e o adormecer. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual. Esta noite, adormecê-lo fica totalmente a cargo dele.', body_sv = 'Bär inte nattvaken och nattningen helt ensam. Väck din partner också, att vara ett lag betyder att dela ansvaret lika. I natt är det helt partnerns tur att natta.', body_vi = 'Đừng một mình gánh hết những lần bé thức giấc ban đêm và việc ru bé ngủ. Hãy đánh thức cả chồng, làm một đội nghĩa là chia đều trách nhiệm. Tối nay, việc đưa bé vào giấc ngủ hoàn toàn là phần của bố.', body_zh = '夜醒和哄睡别一个人全扛。把伴侣也叫醒，作为一个团队，就是要平分责任。今晚的哄睡就全交给他吧。' WHERE id = '5a020277-4aac-4623-8f46-93168c2f54e5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Probando la hora de calma 🥱', body_es = '¿No quiere echarse la siesta y llora? No le obligues. Baja las luces de la habitación y crea una rutina nueva que os relaje a los dos anunciando la «hora de hojear libros en silencio».', title_fr = 'Essayer l''heure calme 🥱', body_fr = 'Il ne veut pas faire la sieste et pleure ? Ne le forcez pas. Baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine qui vous apaisera tous les deux.', title_hi = 'शांत समय का प्रयोग 🥱', body_hi = 'दोपहर की नींद नहीं लेना चाहता और रोता है? ज़बरदस्ती मत कीजिए। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और एक नया रूटीन बनाइए जो आप दोनों को सुकून दे।', title_id = 'Latihan waktu tenang 🥱', body_id = 'Ia tidak mau tidur siang dan menangis? Jangan memaksa. Redupkan lampu kamar dan ciptakan rutinitas baru yang menenangkan kalian berdua dengan mengumumkan ''Waktu membaca buku dengan tenang''.', title_ja = '静かな時間の練習 🥱', body_ja = 'お昼寝したくなくて泣いている？無理強いしないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ふたりともほっとできる新しいルーティンをつくりましょう。', title_ko = '조용한 시간 연습 🥱', body_ko = '낮잠을 안 자겠다며 우나요? 억지로 재우지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 두 사람 모두 편안해지는 새로운 루틴을 만들어 보세요.', title_nl = 'Oefenen met een rustuurtje 🥱', body_nl = 'Wil hij geen middagslaapje doen en huilt hij? Dwing hem niet. Dim de lichten in de kamer en kondig een ''stil boekjesuurtje'' aan, een nieuwe routine waar jullie allebei rustig van worden.', title_pl = 'Ćwiczymy cichą godzinę 🥱', body_pl = 'Nie chce iść na drzemkę i płacze? Nie zmuszaj. Przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę, która uspokoi was oboje.', title_pt = 'Experimentar a hora do sossego 🥱', body_pt = 'Não quer fazer a sesta e chora? Não o obrigue. Baixe as luzes do quarto e crie uma nova rotina, que acalme os dois, anunciando a "hora de folhear livros em silêncio".', title_sv = 'Testa en lugn stund 🥱', body_sv = 'Vill barnet inte sova middag och gråter? Tvinga inte. Dämpa ljuset i rummet och utlys en ”tyst bläddra-i-böcker-stund”, så skapar du en ny rutin som gör er båda avslappnade.', title_vi = 'Tập làm quen giờ yên lặng 🥱', body_vi = 'Bé không muốn ngủ trưa và khóc? Đừng ép. Hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới giúp cả hai mẹ con thư giãn.', title_zh = '试试安静时光 🥱', body_zh = '不肯午睡还哭闹？别强迫。把房间灯光调暗，宣布“安静翻书时间”，建立一个让你们俩都放松的新日常流程。' WHERE id = '026f00f3-6e56-4ac5-a91b-bd5bd82cd187' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fantasías en la oscuridad 🌌', body_es = '¿Cuando se apagan las luces los objetos de la habitación se convierten en monstruos? Pon el sonido del vientre materno en Ruido blanco y devuélvele aquella seguridad antigua y perfecta.', title_fr = 'Rêves dans le noir 🌌', body_fr = 'Quand la lumière s''éteint, les objets de la chambre se transforment en monstres ? Mettez le son du ventre maternel dans les Bruits blancs pour lui redonner ce sentiment de sécurité ancien et parfait.', title_hi = 'अँधेरे में कल्पनाएँ 🌌', body_hi = 'लाइटें बुझते ही कमरे की चीज़ें राक्षस बन जाती हैं? व्हाइट नॉइज़ में माँ के गर्भ की आवाज़ चलाकर उसे वह पुराना, पूरा भरोसा फिर से दीजिए।', title_id = 'Khayalan dalam gelap 🌌', body_id = 'Saat lampu padam, benda-benda di kamar berubah jadi monster? Putar suara rahim dari Suara Putih untuk memberinya kembali rasa aman yang purba dan sempurna itu.', title_ja = '暗やみの中の想像 🌌', body_ja = '明かりが消えると、部屋のものがおばけに見える？「ホワイトノイズ」で胎内音を流して、あのころの完璧な安心感をもう一度届けてあげましょう。', title_ko = '어둠 속의 상상 🌌', body_ko = '불이 꺼지면 방 안 물건들이 괴물로 변하나요? 백색소음에서 엄마 배 속 소리를 틀어 그 오래되고 완벽한 안정감을 다시 느끼게 해 주세요.', title_nl = 'Dromen in het donker 🌌', body_nl = 'Veranderen de spullen in de kamer in monsters als het licht uitgaat? Zet in Witte ruis het baarmoedergeluid aan en geef hem dat oude, volmaakte gevoel van veiligheid terug.', title_pl = 'Marzenia w ciemności 🌌', body_pl = 'Gdy gaśnie światło, przedmioty w pokoju zamieniają się w potwory? Włącz w Białym szumie dźwięk z brzucha mamy i daj mu znów to pradawne, idealne poczucie bezpieczeństwa.', title_pt = 'Fantasias no escuro 🌌', body_pt = 'Quando as luzes se apagam, os objetos do quarto transformam-se em monstros? Ponha o som do útero no Ruído Branco e devolva-lhe aquela segurança antiga e perfeita.', title_sv = 'Fantasier i mörkret 🌌', body_sv = 'Blir sakerna i rummet till monster när ljuset släcks? Sätt på ljudet från livmodern i Vitt brus och ge barnet tillbaka den urgamla, perfekta tryggheten.', title_vi = 'Giấc mơ trong bóng tối 🌌', body_vi = 'Khi đèn tắt, đồ vật trong phòng biến thành quái vật? Hãy bật âm thanh trong bụng mẹ từ Tiếng ồn trắng để trao lại cho bé cảm giác an toàn trọn vẹn, nguyên sơ ấy.', title_zh = '黑暗中的想象 🌌', body_zh = '一关灯，房间里的东西就变成了怪兽？打开白噪音里的子宫声，再次给宝宝那份久远而完美的安全感。' WHERE id = '53b445aa-e1d7-4c46-9d5a-07132c91031c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los juguetes sencillos ya no le atraen, ahora crea juegos más complejos. Busca en la sección Productos recomendados juegos que reten más su inteligencia y desarrollen el pensamiento lógico.', body_fr = 'Les jouets simples ne l''attirent plus, il invente des jeux plus complexes. Cherchez dans la rubrique Produits recommandés des jeux qui stimuleront encore plus son intelligence et développeront sa pensée logique.', body_hi = 'अब साधारण खिलौने उसे नहीं लुभाते, वह ज़्यादा पेचीदा खेल रचता है। उसकी समझ को और चुनौती देने वाले, तार्किक सोच बढ़ाने वाले खेल सुझाए गए प्रोडक्ट सेक्शन में ढूँढिए।', body_id = 'Mainan sederhana tak lagi menarik baginya, ia sudah menyusun permainan yang lebih rumit. Cari permainan yang lebih menantang kecerdasannya dan melatih berpikir logis di bagian Produk Rekomendasi.', body_ja = 'シンプルなおもちゃでは、もう物足りなくなり、もっと複雑な遊びをつくり出しています。頭をもっと使って論理的な思考を育てるゲームを、「おすすめ商品」でさがしてみましょう。', body_ko = '이제 단순한 장난감에는 흥미가 없고 더 복잡한 놀이를 만들어 내나요? 머리를 더 쓰게 하고 논리적 사고를 키우는 놀이를 추천 상품 섹션에서 찾아보세요.', body_nl = 'Gewoon speelgoed boeit hem niet meer, hij bedenkt al ingewikkeldere spelletjes. Zoek in het onderdeel Aanbevolen producten naar spellen die zijn verstand uitdagen en logisch denken stimuleren.', body_pl = 'Proste zabawki już go nie przyciągają, wymyśla coraz bardziej złożone zabawy. Poszukaj w sekcji Polecane produkty gier, które jeszcze bardziej pobudzą jego intelekt i rozwiną logiczne myślenie.', body_pt = 'Os brinquedos simples já não o atraem e cria brincadeiras mais complexas. Procure na secção Produtos Recomendados jogos que desafiem mais a inteligência dele e desenvolvam o pensamento lógico.', body_sv = 'Enkla leksaker lockar inte längre barnet, det bygger upp mer avancerade lekar. Leta efter spel som utmanar intelligensen ännu mer och utvecklar det logiska tänkandet i avsnittet Rekommenderade produkter.', body_vi = 'Đồ chơi đơn giản không còn thu hút bé nữa, bé đã tự nghĩ ra những trò phức tạp hơn. Hãy tìm trong mục Sản phẩm gợi ý những trò chơi thử thách trí tuệ và phát triển tư duy logic cho bé.', body_zh = '简单的玩具已经吸引不了宝宝，宝宝开始玩更复杂的游戏了。去推荐商品板块找找能给宝宝更多挑战、培养逻辑思维的游戏。' WHERE id = 'f4eb03a9-f74f-423a-ab2a-59d54da2db98' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El observador invisible 👻', body_es = '¿Se ha asustado de su propia sombra en la pared y se ha puesto a llorar? La lucha contra las sombras es el clásico más cómico de los 3 años. Apaga las luces, enciende una linterna y convierte el miedo en un divertido ritual para dormir haciendo bailar las sombras.', title_fr = 'Le suiveur invisible 👻', body_fr = 'Il s''est mis à pleurer, effrayé par son ombre sur le mur ? La bataille contre les ombres est un grand classique comique des 3 ans. Éteignez la lumière, allumez une lampe de poche et faites danser les ombres pour transformer cette peur en rituel du coucher amusant.', title_hi = 'अदृश्य पीछा करने वाला 👻', body_hi = 'दीवार पर अपनी परछाईं से डरकर रोने लगा? परछाईं से लड़ाई 3 साल का सबसे मज़ेदार क्लासिक है। लाइटें बंद कीजिए, टॉर्च जलाइए और परछाइयों को नचाकर इस डर को सोने की एक मज़ेदार रस्म बना दीजिए।', title_id = 'Pengikut tak kasatmata 👻', body_id = 'Ia menangis karena takut pada bayangannya sendiri di dinding? Bayangan adalah musuh klasik paling lucu di usia 3 tahun. Matikan lampu, nyalakan senter, dan buat bayangan menari untuk mengubah rasa takut ini menjadi ritual tidur yang seru.', title_ja = '見えない追跡者 👻', body_ja = '壁に映った自分の影が怖くて泣きだした？影との戦いは3歳のいちばんおもしろい定番です。明かりを消して懐中電灯をつけ、影を踊らせて、この怖さを楽しい寝る前の習慣に変えましょう。', title_ko = '보이지 않는 추적자 👻', body_ko = '벽에 비친 자기 그림자를 보고 무서워 울었나요? 그림자와의 싸움은 세 살의 가장 웃긴 단골 장면이에요. 불을 끄고 손전등을 켜서 그림자를 춤추게 하며 이 두려움을 즐거운 잠자리 의식으로 바꿔 보세요.', title_nl = 'De onzichtbare volger 👻', body_nl = 'Begon hij te huilen van schrik voor zijn eigen schaduw op de muur? Strijd met de schaduw is een grappige klassieker rond 3 jaar. Doe het licht uit, pak een zaklamp en laat de schaduwen dansen, zo wordt die angst een leuk slaapritueel.', title_pl = 'Niewidzialny towarzysz 👻', body_pl = 'Przestraszył się swojego cienia na ścianie i zaczął płakać? Walka z cieniem to najzabawniejsza klasyka 3-latków. Zgaś światło, włącz latarkę i zmień ten strach w zabawny rytuał przed snem, każąc cieniom tańczyć.', title_pt = 'O observador invisível 👻', body_pt = 'Assustou-se com a própria sombra na parede e começou a chorar? A luta com a sombra é um clássico cómico dos 3 anos. Apague as luzes, acenda uma lanterna e ponha as sombras a dançar, transformando o medo num ritual de sono divertido.', title_sv = 'Den osynliga förföljaren 👻', body_sv = 'Blev barnet rädd för sin egen skugga på väggen och började gråta? Kampen mot skuggan är en av de roligaste klassikerna vid 3 år. Släck ljuset, tänd en ficklampa och låt skuggorna dansa, så blir rädslan en rolig sovritual.', title_vi = 'Kẻ bám theo vô hình 👻', body_vi = 'Bé sợ cái bóng của mình trên tường và bật khóc? "Cuộc chiến với cái bóng" là màn kinh điển hài hước nhất của tuổi lên 3. Hãy tắt đèn, bật đèn pin và cho những chiếc bóng nhảy múa, biến nỗi sợ thành một nghi thức trước giờ ngủ thật vui.', title_zh = '看不见的跟踪者 👻', body_zh = '被墙上自己的影子吓哭了？和影子“较劲”是3岁最搞笑的经典场面。关上灯，打开手电筒，让影子跳起舞来，把这份害怕变成有趣的睡前仪式。' WHERE id = '00481a1e-da97-4621-84c5-0bde2c4df340' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia del agua caliente 🛀', body_es = 'Todo el día ha sido un «no quiero» tras otro. Un baño templado no es solo higiene, sirve para reiniciar su sistema nervioso tenso. El sonido y el calor del agua se llevarán toda la tozudez.', title_fr = 'La magie de l''eau chaude 🛀', body_fr = 'Toute la journée n''a été qu''une suite de « je veux pas ». Le bain tiède n''est pas qu''une question d''hygiène, il sert à remettre à zéro son système nerveux sous tension. Le bruit et la chaleur de l''eau emporteront tout son entêtement.', title_hi = 'गरम पानी का जादू 🛀', body_hi = 'पूरा दिन ‘मुझे नहीं चाहिए’ में बीता। गुनगुना स्नान सिर्फ़ सफ़ाई के लिए नहीं, उसके तने हुए तंत्रिका तंत्र को रीसेट करने के लिए है। पानी की आवाज़ और गर्माहट सारी ज़िद धो देगी।', title_id = 'Keajaiban air hangat 🛀', body_id = 'Seharian penuh dengan ''aku nggak mau''. Mandi air hangat bukan hanya soal kebersihan, tapi juga untuk menyegarkan kembali sarafnya yang tegang. Suara dan hangatnya air akan membasuh semua sikap keras kepalanya.', title_ja = 'お湯の魔法 🛀', body_ja = '一日じゅう「いやだ」の連続でしたね。ぬるめのお風呂は清潔のためだけでなく、張りつめた神経をリセットするためのもの。お湯の音とぬくもりが、がんこさを全部洗い流してくれます。', title_ko = '따뜻한 물의 마법 🛀', body_ko = '하루 종일 ''싫어''로 가득했나요? 따뜻한 목욕은 위생만을 위한 게 아니라 곤두선 신경계를 초기화하는 시간이에요. 물소리와 온기가 모든 고집을 씻어 가 줄 거예요.', title_nl = 'De magie van warm water 🛀', body_nl = 'De hele dag stond in het teken van ''ik wil niet''. Een lauw bad is niet alleen voor de hygiëne, het reset ook zijn overprikkelde zenuwstelsel. Het geluid en de warmte van het water spoelen alle koppigheid weg.', title_pl = 'Magia ciepłej wody 🛀', body_pl = 'Cały dzień upłynął pod znakiem „nie chcę”. Ciepła kąpiel to nie tylko higiena, ale reset dla jego przeciążonego układu nerwowego. Szum i ciepło wody zmyją cały upór.', title_pt = 'A magia da água quente 🛀', body_pt = 'O dia inteiro foi feito de "não quero". Um banho morno não serve só para a higiene, serve para reiniciar o sistema nervoso tenso dele. O som e o calor da água vão levar consigo toda a teimosia.', title_sv = 'Det varma vattnets magi 🛀', body_sv = 'Hela dagen har gått åt till ”jag vill inte”. Ett ljummet bad är inte bara för hygienen, det nollställer barnets spända nervsystem. Vattnets ljud och värme sköljer bort all envishet.', title_vi = 'Phép màu của nước ấm 🛀', body_vi = 'Cả ngày toàn là những câu "Con không muốn". Tắm nước ấm không chỉ để vệ sinh, mà còn giúp hệ thần kinh căng thẳng của bé được "khởi động lại". Âm thanh và hơi ấm của nước sẽ cuốn trôi mọi bướng bỉnh.', title_zh = '温水的魔法 🛀', body_zh = '一整天都在“我不要”中度过。温水澡不只是为了清洁，更是为了让宝宝紧绷的神经系统重启。水声和温暖会把所有的倔强都冲走。' WHERE id = '135b57f3-06e7-4fc4-b590-bec1151ee33b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El ambiente aburrido de casa os agobia a los dos. Id al parque con la misión de encontrar la piedra con la forma más rara. La naturaleza es su mayor laboratorio y se llevará toda su tensión.', body_fr = 'L''atmosphère monotone de la maison vous pèse à tous les deux. Partez au parc en mission : trouver le caillou à la forme la plus bizarre. La nature est pour lui le plus grand des laboratoires, et elle évacuera toute sa tension.', body_hi = 'घर का उबाऊ माहौल आप दोनों को घुटन दे रहा है। पार्क जाकर सबसे अजीब आकार का पत्थर ढूँढने के मिशन पर निकलिए। प्रकृति उसके लिए सबसे बड़ी प्रयोगशाला है और उसका सारा तनाव सोख लेगी।', body_id = 'Suasana rumah yang membosankan menyesakkan kalian berdua. Pergilah ke taman dengan misi mencari batu dengan bentuk paling aneh. Alam adalah laboratorium terbesar baginya dan akan menyerap semua ketegangannya.', body_ja = '家の中のどんよりした空気に、ふたりとも息がつまっていませんか？公園へ行って、いちばんへんな形の石をさがすミッションに出かけましょう。自然はこの子にとって最大の実験室。張りつめた気持ちを全部受けとめてくれます。', body_ko = '집 안의 지루한 분위기가 두 사람 모두를 답답하게 하나요? 공원에 가서 가장 이상하게 생긴 돌 찾기 미션을 떠나 보세요. 자연은 아이에게 가장 큰 실험실이고 모든 긴장을 풀어 줄 거예요.', body_nl = 'De saaie sfeer in huis drukt op jullie allebei. Ga naar het park met een missie: de steen met de gekste vorm vinden. De natuur is voor hem het grootste laboratorium en neemt al zijn spanning weg.', body_pl = 'Nudna atmosfera w domu przytłacza was oboje. Wybierzcie się do parku na misję znalezienia kamienia o najdziwniejszym kształcie. Natura to dla niego największe laboratorium, które zabierze całe napięcie.', body_pt = 'O ambiente aborrecido da casa está a sufocar os dois. Vão ao parque em missão para encontrar a pedra com a forma mais estranha. A natureza é o maior laboratório para ele e vai levar-lhe toda a tensão.', body_sv = 'Den tråkiga stämningen hemma tynger er båda. Gå till parken och ge er ut på uppdrag att hitta stenen med den konstigaste formen. Naturen är barnets största laboratorium och tar bort all spänning.', body_vi = 'Không khí tẻ nhạt trong nhà khiến cả hai mẹ con ngột ngạt. Hãy ra công viên với nhiệm vụ tìm viên sỏi có hình dạng kỳ lạ nhất. Thiên nhiên là phòng thí nghiệm lớn nhất của bé và sẽ cuốn đi mọi căng thẳng.', body_zh = '家里沉闷的气氛让你们俩都喘不过气。去公园，展开一场“寻找形状最奇怪的石头”的任务吧。大自然是宝宝最大的实验室，会带走宝宝所有的紧张。' WHERE id = '57cfce2e-d64c-49cb-9f8b-295055620f21' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No solo hace ruidos, también gatea como un perro y acecha como un gato? El lenguaje corporal y la imaginación se unen de forma asombrosa. Únete tú también al juego sobre la alfombra y suelta el estrés.', body_fr = 'Il ne fait pas que des bruits, il marche à quatre pattes comme un chien et bondit comme un chat ? Son langage corporel et son imagination s''unissent de façon étonnante. Rejoignez-le sur le tapis dans ce jeu et évacuez votre stress.', body_hi = 'सिर्फ़ आवाज़ ही नहीं निकालता, कुत्ते की तरह रेंगता और बिल्ली की तरह शिकार की ताक में रहता है? शरीर की भाषा और कल्पना कमाल तरीके से जुड़ रही हैं। कालीन पर उसके साथ इस खेल में आप भी शामिल होकर तनाव उतारिए।', body_id = 'Ia tidak hanya menirukan suara, tapi juga merangkak seperti anjing dan mengintai seperti kucing? Bahasa tubuh dan imajinasinya menyatu dengan menakjubkan. Ikutlah bermain bersamanya di atas karpet dan lepaskan stres Anda.', body_ja = '声をまねるだけでなく、犬のようにハイハイしたり、ねこのように獲物をねらったり？体の表現と想像力が見事に結びついています。じゅうたんの上で一緒にこの遊びに加わって、ストレスを発散しましょう。', body_ko = '소리만 내는 게 아니라 강아지처럼 기고 고양이처럼 덮치나요? 몸짓 언어와 상상력이 놀랍게 어우러지고 있어요. 카펫 위에서 함께 이 놀이에 빠져 스트레스를 날려 보세요.', body_nl = 'Maakt hij niet alleen geluiden, maar kruipt hij als een hond en besluipt hij als een kat? Lichaamstaal en fantasie komen prachtig samen. Doe op het tapijt mee met dit spel en raak je eigen stress kwijt.', body_pl = 'Nie tylko wydaje odgłosy, ale raczkuje jak pies i poluje jak kot? Mowa ciała i wyobraźnia łączą się w niesamowity sposób. Dołącz do tej zabawy na dywanie i zrzuć stres.', body_pt = 'Não se limita a fazer sons: gatinha como um cão e caça como um gato? A linguagem corporal e a imaginação juntam-se de forma surpreendente. Entre também neste jogo com ele no tapete e liberte o stress.', body_sv = 'Gör barnet inte bara ljud, utan kryper som en hund och smyger som en katt på jakt? Kroppsspråk och fantasi förenas på ett fantastiskt sätt. Var med i leken på mattan och släpp stressen.', body_vi = 'Bé không chỉ phát ra tiếng kêu, mà còn bò như chó, vồ như mèo? Ngôn ngữ cơ thể và trí tưởng tượng đang kết hợp thật tuyệt vời. Hãy cùng bé chơi trò này trên thảm và xả hết căng thẳng của mẹ.', body_zh = '不只学动物叫，还像小狗一样爬、像小猫一样扑？肢体语言和想象力惊人地结合在一起。你也趴到地毯上加入这个游戏，释放一下压力吧。' WHERE id = '682b0a2a-83c6-46cb-a100-02da150309f7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras juega metido en su mundo, no corras a ordenar la casa. Sírvete un té caliente, deja el móvil a un lado y siéntate 15 minutos sin pensar en nada.', body_fr = 'Quand il est plongé dans son monde et joue, ne courez pas tout de suite ranger la maison. Servez-vous un thé chaud, posez votre téléphone et restez simplement assise 15 minutes, sans penser à rien.', body_hi = 'जब बच्चा अपनी दुनिया में खोकर खेल रहा हो, तो तुरंत घर समेटने मत दौड़िए। अपने लिए गरम चाय डालिए, फ़ोन एक तरफ़ रखिए और 15 मिनट कुछ सोचे बिना बस बैठिए।', body_id = 'Saat anak asyik bermain di dunianya sendiri, jangan langsung buru-buru membereskan rumah. Tuang teh hangat untuk diri sendiri, singkirkan ponsel, dan duduklah saja selama 15 menit tanpa memikirkan apa pun.', body_ja = '子どもが自分の世界に夢中で遊んでいるとき、すぐに片づけに走らないで。温かいお茶をいれて、スマホを置き、15分だけ何も考えずに、ただ座っていましょう。', body_ko = '아이가 자기 세계에 빠져 놀 때 바로 집 치우러 달려가지 마세요. 따뜻한 차 한 잔을 따르고 휴대폰은 내려놓고, 15분 동안 아무 생각 없이 그냥 앉아 있어 보세요.', body_nl = 'Ren niet meteen naar het huishouden als je kind opgaat in zijn eigen spel. Schenk een warme thee in, leg je telefoon weg en zit 15 minuten gewoon stil, zonder aan iets te denken.', body_pl = 'Gdy dziecko zatopi się w swoim świecie zabawy, nie biegnij od razu sprzątać. Nalej sobie gorącej herbaty, odłóż telefon i przez 15 minut po prostu posiedź, o niczym nie myśląc.', body_pt = 'Enquanto a criança brinca mergulhada no seu mundo, não corra logo a arrumar a casa. Sirva-se de um chá quente, ponha o telemóvel de lado e fique 15 minutos apenas sentada, sem pensar em nada.', body_sv = 'Spring inte iväg och städa direkt när barnet är uppslukat av sin egen lekvärld. Häll upp varmt te, lägg undan telefonen och sitt bara i 15 minuter utan att tänka på något.', body_vi = 'Khi bé đang mải chơi trong thế giới riêng, đừng vội chạy đi dọn nhà. Hãy rót cho mình một cốc trà nóng, để điện thoại sang một bên và chỉ ngồi yên 15 phút, không nghĩ ngợi gì cả.', body_zh = '宝宝沉浸在自己的世界里玩耍时，别急着跑去收拾屋子。给自己倒一杯热茶，把手机放到一边，什么都不想，就这样坐上15分钟。' WHERE id = '01a8a883-66ea-4e90-9796-1cd4c7aa4386' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Ahora deja a un lado las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema que no sea el niño ni los gastos. ¡Además de padres, sois una pareja!', body_fr = 'L''enfant dort. Maintenant, mettez de côté les tâches ménagères. Parlez avec votre partenaire au moins 20 minutes de n''importe quel sujet, sauf de l''enfant et des dépenses. Vous êtes aussi un couple !', body_hi = 'बच्चा सो गया। अब घर के काम एक तरफ़ रख दीजिए। अपने साथी के साथ कम से कम 20 मिनट, बच्चे और खर्चों के अलावा किसी भी विषय पर बात कीजिए। आप साथ ही एक जोड़ा भी हैं!', body_id = 'Anak sudah tidur. Sekarang singkirkan pekerjaan rumah. Mengobrollah dengan pasangan minimal 20 menit tentang topik apa saja selain anak dan pengeluaran. Kalian juga sepasang kekasih!', body_ja = '子どもが寝ました。家事はいったん脇に置いて。パートナーと少なくとも20分、子どもやお金以外の話題でおしゃべりしましょう。ふたりはカップルでもあるんです！', body_ko = '아이가 잠들었어요. 이제 집안일은 내려놓으세요. 배우자와 적어도 20분은 아이와 지출 말고 다른 주제로 이야기해 보세요. 두 사람은 부부이기도 하니까요!', body_nl = 'Je kind slaapt. Leg het huishouden nu opzij. Praat minstens 20 minuten met je partner over iets anders dan het kind en de uitgaven. Jullie zijn ook een stel!', body_pl = 'Dziecko śpi. Teraz odłóż obowiązki domowe. Porozmawiaj z partnerem przez co najmniej 20 minut o czymkolwiek poza dzieckiem i wydatkami. Jesteście też parą!', body_pt = 'A criança adormeceu. Agora ponha de lado as tarefas da casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto que não seja a criança nem as despesas. Também são um casal!', body_sv = 'Barnet sover. Lägg nu undan hushållssysslorna. Prata med din partner i minst 20 minuter om vad som helst utom barnet och utgifterna. Ni är samtidigt ett par!', body_vi = 'Bé đã ngủ. Giờ hãy gác việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào, ngoài con cái và chi tiêu. Hai người còn là một cặp đôi nữa!', body_zh = '宝宝睡着了。现在把家务放到一边。和伴侣至少聊20分钟孩子和开销以外的任何话题。你们同时也是一对恋人！' WHERE id = '7fc36514-28e6-4738-b9f6-f0c9cd9fa57d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Lo señala todo con el dedo y pregunta cómo se llama? Te pide que le pongas nombre al mundo. ¡Es un gran salto en la comunicación! Aunque te canses, sigue repitiendo con paciencia los nombres de las cosas.', body_fr = 'Il montre tout du doigt et en demande le nom ? Il veut que vous lui nommiez le monde. C''est un grand bond dans la communication ! Même si vous êtes fatiguée, continuez à répéter patiemment le nom des objets.', body_hi = 'हर चीज़ की ओर उँगली दिखाकर उसका नाम पूछता है? वह चाहता है कि आप उसके लिए दुनिया को नाम दें। बातचीत में यह बड़ी छलाँग है! थक भी जाएँ, तो उन चीज़ों के नाम धैर्य से दोहराते रहिए।', body_id = 'Ia menunjuk segala sesuatu dengan jarinya dan menanyakan namanya? Ia ingin Anda menamai dunia untuknya. Ini lompatan besar dalam komunikasi! Meski lelah, teruslah mengulang nama benda-benda itu dengan sabar.', body_ja = '何でも指さして名前を聞いてくる？世界に名前をつけてほしいんです。コミュニケーションの大きな飛躍です！疲れていても、ものの名前をしんぼう強くくり返してあげましょう。', body_ko = '손가락으로 모든 걸 가리키며 이름을 묻나요? 엄마가 세상에 이름을 붙여 주길 바라는 거예요. 의사소통의 큰 도약이에요! 지쳐도 사물의 이름을 인내심 있게 계속 말해 주세요.', body_nl = 'Wijst hij alles aan en vraagt hij hoe het heet? Hij wil dat jij de wereld voor hem benoemt. Een grote sprong in communicatie! Ook al ben je moe, blijf geduldig de namen van die dingen herhalen.', body_pl = 'Pokazuje wszystko paluszkiem i pyta o nazwę? Chce, żebyś nazwała mu świat. To wielki skok w komunikacji! Nawet gdy jesteś zmęczona, cierpliwie powtarzaj nazwy tych rzeczy.', body_pt = 'Aponta para tudo com o dedo e pergunta o nome? Quer que lhe dê nome ao mundo. É um grande salto na comunicação! Mesmo cansada, continue a repetir com paciência os nomes das coisas.', body_sv = 'Pekar barnet på allt och frågar vad det heter? Barnet vill att du ger namn åt världen. Ett stort språng i kommunikationen! Även om du är trött, fortsätt tålmodigt att upprepa vad sakerna heter.', body_vi = 'Bé chỉ tay vào mọi thứ và hỏi tên? Bé muốn mẹ gọi tên cả thế giới cho bé. Đó là bước nhảy vọt lớn trong giao tiếp! Dù mệt, hãy kiên nhẫn tiếp tục nhắc lại tên các đồ vật.', body_zh = '什么都用手指着问叫什么？宝宝想让你为它命名整个世界。这是沟通上的一大飞跃！就算累了，也请耐心地一遍遍说出那些东西的名字。' WHERE id = '8b2d61db-8be9-4916-a184-f14d02885b17' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una tienda hecha de ropa ⛺', body_es = '¿Ha deshecho el montón de ropa limpia que acababas de doblar y se ha montado una tienda de campaña? Antes de enfadarte, asómate dentro. Ese mundo imaginario y su alegría valen más que tu esfuerzo doblando.', title_fr = 'Une tente en montagne de linge ⛺', body_fr = 'Il a défait la pile de linge propre que vous veniez de plier pour se construire une tente ? Avant de vous énerver, jetez un œil dedans. Le monde imaginaire et la joie de votre enfant valent bien plus que votre peine à plier.', title_hi = 'कपड़ों के ढेर से तंबू ⛺', body_hi = 'अभी-अभी तह किए साफ़ कपड़ों का ढेर बिखेरकर अपने लिए तंबू बना लिया? नाराज़ होने से पहले उस तंबू में झाँकिए। वहाँ की कल्पना की दुनिया और बच्चे की खुशी आपकी तह करने की मेहनत से कहीं ज़्यादा कीमती है।', title_id = 'Tenda dari gunungan baju ⛺', body_id = 'Ia mengacak-acak tumpukan baju bersih yang baru Anda lipat untuk membuat tenda? Sebelum kesal, intiplah ke dalam tenda itu. Dunia khayal dan kebahagiaannya di sana lebih berharga daripada jerih payah Anda melipat.', title_ja = '洗濯物の山でテント ⛺', body_ja = 'たたんだばかりのきれいな洗濯物の山をくずして、自分のテントを作った？怒る前に、そのテントの中をのぞいてみて。そこにある空想の世界と子どもの喜びは、たたむ手間よりずっと価値があります。', title_ko = '빨래 더미로 만든 텐트 ⛺', body_ko = '방금 갠 깨끗한 빨래 더미를 흩뜨려 텐트를 만들었나요? 화내기 전에 텐트 안을 들여다보세요. 그 안의 상상의 세계와 아이의 기쁨은 빨래 개는 수고보다 훨씬 소중해요.', title_nl = 'Een tent van de wasberg ⛺', body_nl = 'Heeft hij de stapel schone, net opgevouwen was overhoopgehaald om er een tent van te bouwen? Gluur eerst even in die tent voordat je boos wordt. Zijn fantasiewereld en zijn plezier zijn meer waard dan jouw vouwwerk.', title_pl = 'Namiot z góry prania ⛺', body_pl = 'Rozwalił stos świeżo złożonych czystych ubrań i zbudował sobie namiot? Zanim się zdenerwujesz, zajrzyj do środka. Ten świat wyobraźni i radość dziecka są warte więcej niż twój trud składania.', title_pt = 'Uma tenda com a pilha de roupa ⛺', body_pt = 'Desfez a pilha de roupa lavada que tinha acabado de dobrar e montou uma tenda? Antes de se irritar, espreite lá para dentro. O mundo de fantasia e a alegria dele valem mais do que o trabalho de dobrar.', title_sv = 'Ett tält av tvätthögen ⛺', body_sv = 'Har barnet rivit upp den nyvikta, rena tvätthögen och byggt ett tält? Innan du blir arg, kika in i tältet. Fantasivärlden där inne och barnets glädje är värda mer än ditt vikande.', title_vi = 'Lều từ núi quần áo ⛺', body_vi = 'Bé làm tung đống quần áo sạch mẹ vừa gấp để dựng cho mình một chiếc lều? Trước khi bực mình, hãy ngó vào trong chiếc lều ấy. Thế giới tưởng tượng và niềm vui của bé trong đó quý giá hơn công sức gấp đồ của mẹ.', title_zh = '衣服堆里的帐篷 ⛺', body_zh = '把你刚叠好的一堆干净衣服弄得乱七八糟，给自己搭了个帐篷？生气之前，先往帐篷里看一眼。里面的想象世界和孩子的快乐，比你叠衣服的辛苦更珍贵。' WHERE id = '81f8ee8c-8ca4-4260-b2ea-e74f425fe201' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la etiqueta 🏷️', body_es = '«¡Me pica el cuello!». Esa pequeña etiqueta de la camiseta es el mayor enemigo de esta mañana. A los 3 años la sensibilidad sensorial llega a su punto máximo. No discutas: corta la etiqueta y dale al día la oportunidad de empezar en paz.', title_fr = 'La crise de l''étiquette 🏷️', body_fr = '« Ça me gratte le cou ! » La petite étiquette au dos du t-shirt est le pire ennemi de ce matin. À 3 ans, la sensibilité sensorielle est à son maximum. Ne discutez pas, coupez simplement l''étiquette et donnez à la journée une chance de commencer en paix.', title_hi = 'लेबल का संकट 🏷️', body_hi = '‘मेरी गर्दन में खुजली हो रही है!’ कमीज़ के पीछे का वह छोटा लेबल आज सुबह का सबसे बड़ा दुश्मन है। 3 साल में संवेदी संवेदनशीलता चरम पर होती है। बहस मत कीजिए, बस वह लेबल काट दीजिए और दिन को शांति से शुरू होने का मौका दीजिए।', title_id = 'Krisis label baju 🏷️', body_id = '''Leherku gatal!'' Label kecil di bagian belakang kaus adalah musuh terbesar pagi ini. Di usia 3 tahun, kepekaan sensorik mencapai puncaknya. Jangan berdebat, cukup gunting label itu dan beri kesempatan hari dimulai dengan damai.', title_ja = 'タグ問題 🏷️', body_ja = '「首がチクチクする！」シャツの後ろの小さなタグが、今朝の最大の敵です。3歳では感覚の敏感さがピークに。言い合いはせず、タグを切ってしまって、平和な一日のスタートにしましょう。', title_ko = '옷 라벨 위기 🏷️', body_ko = '''목이 간지러워!'' 셔츠 뒤의 작은 라벨이 오늘 아침 최대의 적이에요. 세 살에는 감각 예민함이 정점에 이르러요. 말다툼하지 말고 라벨을 잘라 평화롭게 하루를 시작할 기회를 주세요.', title_nl = 'Labelcrisis 🏷️', body_nl = '''Het kriebelt in mijn nek!'' Dat kleine labeltje achter in zijn shirt is de grootste vijand van vanochtend. Rond 3 jaar is de zintuiglijke gevoeligheid op zijn hoogst. Ga niet in discussie, knip het labeltje gewoon af en geef de dag een kans om vredig te beginnen.', title_pl = 'Kryzys metki 🏷️', body_pl = '„Drapie mnie w szyję!” Mała metka z tyłu koszulki to największy wróg tego poranka. U 3-latków wrażliwość sensoryczna sięga szczytu. Nie kłóć się, po prostu odetnij metkę i daj dniu szansę zacząć się w spokoju.', title_pt = 'A crise da etiqueta 🏷️', body_pt = '"Faz-me comichão no pescoço!" Aquela etiquetazinha nas costas da camisola é o maior inimigo desta manhã. Aos 3 anos a sensibilidade sensorial está no auge. Não discuta: corte a etiqueta e dê ao dia a hipótese de começar em paz.', title_sv = 'Lappkrisen 🏷️', body_sv = '”Det kliar i nacken!” Den lilla lappen bak på tröjan är morgonens största fiende. Vid 3 år når den sensoriska känsligheten sin topp. Bråka inte, klipp bara bort lappen och ge dagen en chans att börja i fred.', title_vi = 'Khủng hoảng mác áo 🏷️', body_vi = '"Nó làm cổ con ngứa!" Chiếc mác nhỏ sau lưng áo là kẻ thù lớn nhất sáng nay. Ở tuổi lên 3, sự nhạy cảm giác quan lên đến đỉnh điểm. Đừng tranh cãi, chỉ cần cắt chiếc mác đi và cho ngày mới cơ hội bắt đầu trong bình yên.', title_zh = '标签危机 🏷️', body_zh = '“脖子好痒！”衣服后面那个小小的标签，成了今早最大的敌人。3岁时感官敏感达到顶峰。别争了，直接剪掉标签，给这一天一个平和开始的机会。' WHERE id = 'c4bb77ab-6874-45a4-8118-c089a7246538' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mando en la nevera 📺', body_es = '¿No encuentras el mando de la tele? Mira en la nevera o en el zapatero. Descubre el mundo colocando las cosas según su propia lógica. En lugar de enfadarte, tómate con risa este juego de detectives absurdo.', title_fr = 'La télécommande dans le frigo 📺', body_fr = 'Vous ne trouvez plus la télécommande ? Regardez dans le frigo ou dans le meuble à chaussures. Il découvre le monde en rangeant les objets selon sa propre logique. Au lieu de vous énerver, prenez ce jeu de détective absurde avec le sourire.', title_hi = 'फ़्रिज में रिमोट 📺', body_hi = 'टीवी का रिमोट नहीं मिल रहा? फ़्रिज या जूतों की अलमारी में देखिए। वह चीज़ों को अपने गढ़े तर्क के हिसाब से रखकर दुनिया को खोज रहा है। नाराज़ होने के बजाय इस बेतुके जासूसी खेल को हँसकर लीजिए।', title_id = 'Remote di dalam kulkas 📺', body_id = 'Tidak bisa menemukan remote TV? Coba lihat di kulkas atau rak sepatu. Ia menjelajahi dunia dengan menaruh benda sesuai logika karangannya sendiri. Daripada kesal, sikapi permainan detektif absurd ini sambil tertawa.', title_ja = '冷蔵庫の中のリモコン 📺', body_ja = 'テレビのリモコンが見つからない？冷蔵庫や靴箱をのぞいてみて。自分で考えたルールでものを置きながら、世界を発見しているんです。イライラする代わりに、このおかしな探偵ゲームを笑って楽しみましょう。', title_ko = '냉장고 속 리모컨 📺', body_ko = 'TV 리모컨이 안 보이나요? 냉장고나 신발장을 열어 보세요. 아이는 자기만의 논리로 물건을 두며 세상을 탐험하는 중이에요. 화내는 대신 이 엉뚱한 탐정 놀이를 웃으며 즐겨 보세요.', title_nl = 'De afstandsbediening in de koelkast 📺', body_nl = 'Kun je de afstandsbediening niet vinden? Kijk in de koelkast of het schoenenkastje. Hij ontdekt de wereld door spullen neer te leggen volgens zijn eigen logica. Word niet boos, maar lach om dit absurde detectivespel.', title_pl = 'Pilot w lodówce 📺', body_pl = 'Nie możesz znaleźć pilota od telewizora? Zajrzyj do lodówki albo szafki na buty. Odkrywa świat, układając rzeczy według własnej logiki. Zamiast się denerwować, podejdź do tej absurdalnej zagadki detektywistycznej ze śmiechem.', title_pt = 'O comando no frigorífico 📺', body_pt = 'Não encontra o comando da televisão? Veja no frigorífico ou no sapateiro. Ele descobre o mundo arrumando as coisas segundo uma lógica inventada por ele. Em vez de se irritar, encare este jogo de detetives absurdo a rir.', title_sv = 'Fjärrkontrollen i kylen 📺', body_sv = 'Hittar du inte tv-fjärrkontrollen? Titta i kylskåpet eller i skoskåpet. Barnet utforskar världen genom att placera saker enligt sin egen påhittade logik. Istället för att bli irriterad, ta den absurda detektivleken med ett skratt.', title_vi = 'Điều khiển trong tủ lạnh 📺', body_vi = 'Không tìm thấy điều khiển tivi? Hãy xem trong tủ lạnh hoặc tủ giày. Bé đang khám phá thế giới bằng cách sắp xếp đồ vật theo logic do mình tự nghĩ ra. Thay vì bực mình, hãy cười và đón nhận trò chơi "thám tử" ngộ nghĩnh này.', title_zh = '冰箱里的遥控器 📺', body_zh = '找不到电视遥控器？去冰箱或鞋柜里看看。宝宝在按照自己发明的逻辑摆放东西，以此探索世界。与其生气，不如笑着对待这场荒诞的侦探游戏。' WHERE id = '6716e6c0-2c87-4096-9dc2-661b570d83da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de la herida imaginaria 🩹', body_es = 'Nada más despertarse ha encontrado una herida invisible en su cuerpo y te pide con urgencia que le pongas una tirita. No es dolor físico, es pura necesidad de atención y cariño. No discutas: ponle la tirita, dale un beso y el día está salvado.', title_fr = 'À la recherche de bobos imaginaires 🩹', body_fr = 'À peine réveillé, il trouve une blessure invisible sur son corps et vous réclame affolé un pansement. Ce n''est pas une douleur physique, mais un pur besoin d''attention et de tendresse. Ne discutez pas : collez ce petit pansement, faites un bisou, et votre journée est sauvée.', title_hi = 'काल्पनिक चोट की तलाश 🩹', body_hi = 'उठते ही उसे शरीर पर एक अदृश्य चोट मिल गई और घबराकर बैंडेज लगाने की ज़िद करता है। यह शारीरिक दर्द नहीं, सिर्फ़ ध्यान और प्यार की ज़रूरत है। बहस मत कीजिए, वह छोटी बैंडेज लगाकर चूम लीजिए, आपका दिन बच जाएगा।', title_id = 'Mencari luka khayalan 🩹', body_id = 'Begitu bangun, ia menemukan luka tak terlihat di tubuhnya dan dengan panik meminta Anda menempelkan plester. Ini bukan rasa sakit fisik, murni kebutuhan akan perhatian dan kasih sayang. Jangan berdebat, tempelkan plester kecil itu lalu cium, dan hari Anda pun terselamatkan.', title_ja = '見えないけが探し 🩹', body_ja = '起きるなり体に見えない傷を見つけて、あわてて絆創膏を貼ってとせがむ。これは体の痛みではなく、ただ注目とやさしさがほしいだけ。言い合わずに小さな絆創膏を貼ってキスしてあげれば、一日が救われます。', title_ko = '상상 속 상처 찾기 🩹', body_ko = '일어나자마자 몸에서 보이지 않는 상처를 찾아내고 다급하게 반창고를 붙여 달라고 하나요? 몸이 아픈 게 아니라 관심과 다정함이 필요한 거예요. 따지지 말고 작은 반창고를 붙이고 뽀뽀해 주면 하루가 평화로워져요.', title_nl = 'Op zoek naar denkbeeldige wondjes 🩹', body_nl = 'Zodra hij wakker is, vindt hij een onzichtbaar wondje en eist hij in paniek een pleister. Dit is geen lichamelijke pijn, maar puur behoefte aan aandacht en medeleven. Ga niet in discussie, plak dat kleine pleistertje, geef er een kus op en je dag is gered.', title_pl = 'W poszukiwaniu wymyślonej rany 🩹', body_pl = 'Zaraz po przebudzeniu znalazł na ciele niewidzialną ranę i w panice domaga się plasterka. To nie fizyczny ból, tylko potrzeba uwagi i czułości. Nie kłóć się, przyklej mały plasterek, pocałuj i uratuj dzień.', title_pt = 'À procura de feridas imaginárias 🩹', body_pt = 'Mal acorda, descobre no corpo uma ferida invisível e exige, aflito, que lhe ponha um penso. Não é dor física, é pura necessidade de atenção e carinho. Não discuta: cole o pensinho, dê-lhe um beijo e o dia está salvo.', title_sv = 'Jakten på det låtsade såret 🩹', body_sv = 'Så fort barnet vaknar hittar det ett osynligt sår på kroppen och kräver oroligt att du sätter på ett plåster. Det är inte fysisk smärta, utan ett behov av uppmärksamhet och omtanke. Bråka inte, sätt på det lilla plåstret och pussa, så är dagen räddad.', title_vi = 'Đi tìm vết thương tưởng tượng 🩹', body_vi = 'Vừa thức dậy, bé đã phát hiện một vết thương vô hình trên người và cuống quýt đòi mẹ dán băng cá nhân. Đây không phải là đau thể chất, mà chỉ là nhu cầu được quan tâm và thương yêu. Đừng tranh cãi, hãy dán miếng băng nhỏ, hôn một cái, và ngày của mẹ được cứu.', title_zh = '寻找想象中的伤口 🩹', body_zh = '一醒来就在身上找到一个看不见的伤口，慌慌张张地要你给它贴创可贴。这不是身体上的疼，纯粹是需要关注和疼爱。别争了，贴上那个小创可贴，再亲一下，这一天就得救了。' WHERE id = '7e1b9939-5806-440f-9214-8ee42a76c83e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El síndrome del hambre repentina 🥱', body_es = 'Justo al meterse en la cama dice «mamá, tengo hambre» y quiere correr a la cocina. ¡Una obra maestra para retrasar el sueño! Elige en el Plan de alimentación un pequeño tentempié de noche que dé sueño (por ejemplo, un plátano) y desactiva esta excusa de antemano.', title_fr = 'Le syndrome de la faim soudaine 🥱', body_fr = 'Juste au moment d''aller au lit, il dit « Maman, j''ai faim » et veut courir à la cuisine. Un chef-d''œuvre pour retarder le coucher ! Choisissez dans le Plan de nutrition une petite collation du soir qui favorise le sommeil (une banane, par exemple) pour désamorcer cette excuse à l''avance.', title_hi = 'अचानक ‘भूख’ का सिंड्रोम 🥱', body_hi = 'ठीक बिस्तर में जाते ही ‘माँ, मुझे भूख लगी है’ कहकर रसोई भागना चाहता है। नींद टालने की यह बेमिसाल कला है! फ़ीडिंग प्लान में शाम के लिए नींद लाने वाला छोटा स्नैक (जैसे केला) चुनकर इस बहाने को पहले ही खत्म कर दीजिए।', title_id = 'Sindrom lapar mendadak 🥱', body_id = 'Tepat saat naik ke tempat tidur, ia berkata ''Ma, aku lapar'' dan ingin lari ke dapur. Mahakarya untuk menunda tidur! Pilih camilan kecil pengundang kantuk (misalnya pisang) untuk malam hari di Rencana Nutrisi, dan patahkan alasan ini sejak awal.', title_ja = 'とつぜんの「おなかすいた」症候群 🥱', body_ja = 'ちょうどベッドに入ったところで「ママ、おなかすいた」とキッチンへ走ろうとする。寝る時間を遅らせる傑作です！「栄養管理ツール」で、夜に眠りをさそう小さなおやつ（たとえばバナナ）を選んで、この言いわけを前もってつぶしておきましょう。', title_ko = '갑작스러운 ''배고파'' 증후군 🥱', body_ko = '침대에 눕자마자 ''엄마, 배고파'' 하며 부엌으로 달려가려 하나요? 잠을 미루는 데는 최고의 작품이죠! 식단 계획에서 저녁에 먹을 잠이 오는 작은 간식(예: 바나나)을 골라 이 핑계를 미리 막아 두세요.', title_nl = 'Het plotselinge hongersyndroom 🥱', body_nl = 'Net als hij in bed ligt, zegt hij ''Mama, ik heb honger'' en wil hij naar de keuken. Een meesterwerk om het slapen uit te stellen! Kies in het Voedingsplan een klein, slaapbevorderend avondsnackje (zoals een banaan) en ontkracht dit excuus van tevoren.', title_pl = 'Nagły „głód” 🥱', body_pl = 'Gdy tylko kładzie się do łóżka, mówi „Mamo, jestem głodny” i chce biec do kuchni. Mistrzowski sposób na opóźnienie snu! Wybierz w planie karmienia małą wieczorną przekąskę sprzyjającą zasypianiu (np. banana) i z góry zneutralizuj tę wymówkę.', title_pt = 'A síndrome da fome repentina 🥱', body_pt = 'Mal se deita na cama, diz "mãe, tenho fome" e quer correr para a cozinha. Uma obra-prima para adiar o sono! Escolha no Registo de Alimentação um pequeno snack para a noite que ajude a dormir (por exemplo, banana) e anule esta desculpa com antecedência.', title_sv = 'Det plötsliga hungersyndromet 🥱', body_sv = 'Precis när barnet kommer i säng säger det ”Mamma, jag är hungrig” och vill springa till köket. Ett mästerverk i att skjuta upp sömnen! Välj ett litet sömngivande kvällsmellanmål (till exempel banan) i matplanen och nollställ ursäkten i förväg.', title_vi = 'Hội chứng "đói bất chợt" 🥱', body_vi = 'Đúng lúc lên giường, bé nói "Mẹ ơi, con đói" và đòi chạy vào bếp. Đây là kiệt tác để trì hoãn giấc ngủ! Hãy chọn trong Kế hoạch dinh dưỡng một món ăn nhẹ buổi tối giúp dễ ngủ (ví dụ chuối) để vô hiệu hóa lý do này từ trước.', title_zh = '突发“饥饿综合征” 🥱', body_zh = '刚上床就喊“妈妈，我饿了”，想往厨房跑。这是拖延睡觉的杰作！在喂养计划里给晚上选一份助眠的小零食（比如香蕉），提前让这个借口失效。' WHERE id = 'ce6bc378-f040-49dc-a292-ef6ffa4a4247' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pensamientos en voz alta 💭', body_es = 'Tumbado en la cama, se cuenta a sí mismo en voz alta lo que ha pasado durante el día. Así procesa la información y los recuerdos. Abre el Seguimiento del desarrollo y anota con orgullo cómo ha crecido su capacidad de contar historias libremente.', title_fr = 'Penser à voix haute 💭', body_fr = 'Allongé dans son lit, il se raconte à voix haute sa journée. C''est ainsi qu''il traite les informations et les souvenirs. Ouvrez le Suivi de développement et notez fièrement à quel point sa capacité à construire librement des histoires progresse.', title_hi = 'ज़ोर से सोचना 💭', body_hi = 'बिस्तर में लेटकर दिनभर की बातें खुद से, पर ज़ोर-ज़ोर से बोलता है। वह जानकारी और यादों को ऐसे ही समझता है। ग्रोथ ट्रैकर खोलिए और गर्व से दर्ज कीजिए कि उसकी खुलकर कहानी बनाने की क्षमता कितनी तेज़ी से बढ़ी है।', title_id = 'Berpikir sambil bersuara 💭', body_id = 'Berbaring di tempat tidur, ia menceritakan kejadian hari ini kepada dirinya sendiri dengan suara keras. Begitulah ia mengolah informasi dan kenangan. Buka Pelacak Perkembangan dan catat dengan bangga betapa pesat kemampuannya menyusun cerita secara bebas.', title_ja = 'ひとりごとで考える 💭', body_ja = 'ベッドに寝ころんで、今日あったことを声に出してひとりで話しています。こうやって情報や思い出を整理しているんです。「発達トラッカー」を開いて、自由にお話をつくる力がぐんと伸びたことを誇らしく記録しましょう。', title_ko = '소리 내어 생각하기 💭', body_ko = '침대에 누워 오늘 있었던 일을 혼잣말로, 하지만 큰 소리로 이야기하나요? 그렇게 정보와 기억을 정리하는 거예요. 성장 기록을 열고 자유롭게 이야기를 지어내는 능력이 크게 자란 걸 뿌듯하게 기록하세요.', title_nl = 'Hardop denken 💭', body_nl = 'Hij ligt in bed en vertelt zichzelf hardop wat er vandaag is gebeurd. Zo verwerkt hij informatie en herinneringen. Open de Groeitracker en noteer trots hoe sterk zijn vermogen om vrij verhalen te vertellen groeit.', title_pl = 'Myśli na głos 💭', body_pl = 'Leżąc w łóżku, opowiada sam sobie na głos, co wydarzyło się w ciągu dnia. Tak przetwarza informacje i wspomnienia. Otwórz Śledzenie rozwoju i z dumą zanotuj, jak mocno wzrosła jego umiejętność swobodnego opowiadania.', title_pt = 'Pensamentos em voz alta 💭', body_pt = 'Deitado na cama, conta para si próprio, em voz alta, o que aconteceu durante o dia. É assim que processa a informação e as memórias. Abra o Registo de Crescimento e registe com orgulho como esta capacidade de criar histórias livremente aumentou tanto.', title_sv = 'Tankar högt 💭', body_sv = 'Barnet ligger i sängen och berättar för sig själv, men högt, om allt som hänt under dagen. Det är så barnet bearbetar information och minnen. Öppna Utvecklingsspåraren och anteckna stolt hur förmågan att fritt bygga berättelser ökar kraftigt.', title_vi = 'Suy nghĩ thành lời 💭', body_vi = 'Nằm trên giường, bé tự kể to về những gì đã xảy ra trong ngày. Đó là cách bé xử lý thông tin và ký ức. Hãy mở Theo dõi phát triển và tự hào ghi lại khả năng tự kể chuyện của bé đã tăng vọt như thế nào.', title_zh = '大声的思考 💭', body_zh = '躺在床上，自言自语地大声讲今天发生的事。宝宝正是这样处理信息和记忆的。打开发育追踪，骄傲地记下宝宝自由讲故事的能力正在飞速提升。' WHERE id = '7dcdfa61-d4a7-4888-bf22-0453312c6bae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las líneas de la alfombra 📏', body_es = 'Intenta caminar sin pisar las líneas de la alfombra y te pide que hagas lo mismo. La motricidad gruesa y la coordinación de la atención se han unido a la perfección. No rompas el juego: salta tú también unos pasos por la misma línea con él.', title_fr = 'Les lignes du tapis 📏', body_fr = 'Il essaie de marcher sans toucher les lignes du tapis et vous demande d''en faire autant. Sa motricité globale et sa coordination s''unissent parfaitement. Ne gâchez pas le jeu : faites quelques pas avec lui en sautant sur la même ligne.', title_hi = 'कालीन की लकीरें 📏', body_hi = 'कालीन की लकीरों पर पैर रखे बिना चलने की कोशिश करता है और आपसे भी यही चाहता है। बड़ी मोटर स्किल्स और ध्यान का तालमेल शानदार तरीके से जुड़ गया है। खेल मत बिगाड़िए, कुछ कदम आप भी उसके साथ उसी लकीर पर कूदते हुए चलिए।', title_id = 'Garis-garis karpet 📏', body_id = 'Ia berusaha berjalan tanpa menginjak garis-garis di karpet dan meminta Anda melakukan hal yang sama. Motorik kasar dan koordinasi perhatiannya menyatu dengan sempurna. Jangan rusak permainannya, ikutlah melompati garis yang sama beberapa langkah.', title_ja = 'じゅうたんの線 📏', body_ja = 'じゅうたんの線をふまないように歩いて、あなたにも同じことを求めてくる。体の大きな動きと注意力が見事に連携しています。遊びをこわさないで、あなたも何歩か同じ線をジャンプしてわたりましょう。', title_ko = '카펫 위의 선 📏', body_ko = '카펫의 선을 밟지 않고 걸으려 하며 엄마에게도 똑같이 하라고 하나요? 대근육 운동과 주의력 협응이 완벽하게 어우러지고 있어요. 놀이를 망치지 말고 몇 걸음 같은 선을 따라 함께 뛰어 보세요.', title_nl = 'De lijnen van het tapijt 📏', body_nl = 'Hij probeert te lopen zonder op de lijnen in het tapijt te stappen en wil dat jij hetzelfde doet. Grove motoriek en aandacht werken perfect samen. Verpest het spel niet en spring zelf ook een paar stappen over dezelfde lijn.', title_pl = 'Linie na dywanie 📏', body_pl = 'Próbuje chodzić, nie nadeptując na linie dywanu, i wymaga tego samego od ciebie. Motoryka duża i koordynacja uwagi pięknie się połączyły. Nie psuj zabawy, przeskocz z nim kilka kroków po tej samej linii.', title_pt = 'As linhas do tapete 📏', body_pt = 'Tenta andar sem pisar as linhas do tapete e exige-lhe o mesmo. A motricidade grossa e a coordenação da atenção juntaram-se na perfeição. Não estrague o jogo: dê também uns passos com ele, a saltar pela mesma linha.', title_sv = 'Mattans linjer 📏', body_sv = 'Försöker barnet gå utan att trampa på linjerna i mattan och kräver att du gör likadant? Grovmotorik och koordination av uppmärksamheten har förenats perfekt. Förstör inte leken, hoppa längs samma linje några steg du också.', title_vi = 'Những đường kẻ trên thảm 📏', body_vi = 'Bé cố đi mà không giẫm lên các đường kẻ trên thảm và đòi mẹ cũng làm y như vậy. Kỹ năng vận động thô và khả năng tập trung đã phối hợp hoàn hảo. Đừng phá trò chơi, hãy cùng bé nhảy qua vài bước trên cùng một đường kẻ.', title_zh = '地毯上的线条 📏', body_zh = '想走路时不踩到地毯上的线条，还要求你也照做。大动作和注意力协调完美地结合在一起。别破坏游戏，你也跟着在同一条线上跳几步吧。' WHERE id = 'dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Barcos que se hunden en el baño 🛀', body_es = 'Entrasteis al baño a jugar con el agua y él intenta hundir los juguetes que flotan. ¡Está descubriendo la física! Deja que el agua salpique: la energía del agua se llevará también la resistencia acumulada durante el día.', title_fr = 'Naufrages dans la baignoire 🛀', body_fr = 'Vous êtes entrés dans la salle de bain pour jouer avec l''eau, et il essaie de couler des jouets qui flottent. Il découvre la physique ! Laissez l''eau éclabousser, l''énergie de l''eau emportera avec elle toute la résistance accumulée dans la journée.', title_hi = 'बाथटब में डूबते जहाज़ 🛀', body_hi = 'पानी से खेलने के लिए बाथरूम गए और वह न डूबने वाले खिलौनों को डुबाने की कोशिश कर रहा है। वह भौतिकी खोज रहा है! पानी को चारों ओर छिटकने दीजिए, पानी की ऊर्जा दिनभर जमा हुई उसकी ज़िद को भी बहा ले जाएगी।', title_id = 'Kapal tenggelam di kamar mandi 🛀', body_id = 'Anda masuk kamar mandi untuk bermain air, dan ia berusaha menenggelamkan mainan yang mengapung. Ia sedang menemukan fisika! Biarkan air memercik ke mana-mana, energi air akan ikut membawa pergi perlawanan yang menumpuk sepanjang hari.', title_ja = 'お風呂で沈む船 🛀', body_ja = '水遊びのためにお風呂に入ったら、沈まないおもちゃを沈めようとしています。物理を発見中です！水しぶきが飛んでもいいんです。お湯のエネルギーが、一日たまった反抗心も一緒に流してくれます。', title_ko = '욕조 속 가라앉는 배 🛀', body_ko = '물놀이하러 욕실에 들어갔더니 물에 뜨는 장난감을 가라앉히려 애쓰나요? 물리를 발견하는 중이에요! 물이 튀어도 괜찮아요, 물의 에너지가 하루 동안 쌓인 고집도 함께 씻어 갈 거예요.', title_nl = 'Zinkende schepen in bad 🛀', body_nl = 'Je bent in de badkamer om met water te spelen en hij probeert speelgoed dat drijft onder te duwen. Hij ontdekt natuurkunde! Laat het water maar spetteren, de energie van het water neemt ook al het verzet van de dag mee.', title_pl = 'Tonące statki w kąpieli 🛀', body_pl = 'Weszliście do łazienki pobawić się wodą, a on próbuje zatopić zabawki, które nie toną. Odkrywa fizykę! Niech woda chlapie dookoła, jej energia zabierze ze sobą cały opór nagromadzony w ciągu dnia.', title_pt = 'Barcos a afundar na banheira 🛀', body_pt = 'Foram para a casa de banho brincar com água e ele tenta afundar brinquedos que flutuam. Está a descobrir a física! Deixe a água salpicar à volta: a energia da água vai levar consigo a resistência acumulada durante o dia.', title_sv = 'Sjunkande skepp i badkaret 🛀', body_sv = 'Ni gick in i badrummet för att leka med vatten, och barnet försöker sänka leksaker som inte sjunker. Barnet upptäcker fysiken! Låt vattnet stänka, vattnets energi tar med sig motståndet som samlats under dagen.', title_vi = 'Những con tàu chìm trong bồn tắm 🛀', body_vi = 'Mẹ vào phòng tắm cho bé nghịch nước, và bé cố dìm những món đồ chơi không chịu chìm. Bé đang khám phá vật lý! Cứ để nước bắn tung tóe, năng lượng của nước sẽ cuốn đi cả sự phản kháng tích tụ suốt cả ngày của bé.', title_zh = '浴室里的沉船 🛀', body_zh = '进浴室玩水，宝宝却想把浮在水面的玩具按下去。宝宝在探索物理！让水花四溅吧，水的能量会把宝宝一整天积攒的倔劲儿也一起带走。' WHERE id = '04cb5d8f-0591-4ccc-8e31-0cf6555eb83a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mascota imaginaria 🐕', body_es = '¿Acaricia a un perro o a un gato que no está en la habitación y le pone nombre? Su imaginación ya ha superado los límites físicos. Pon un cuenco de agua invisible en un rincón y únete tú también a esta dulce ilusión.', title_fr = 'L''animal imaginaire 🐕', body_fr = 'Il caresse un chien ou un chat qui n''existe pas et lui donne un nom ? Son imagination a dépassé les limites physiques. Posez une gamelle d''eau invisible dans un coin de la pièce et entrez, vous aussi, dans cette douce illusion.', title_hi = 'काल्पनिक पालतू जानवर 🐕', body_hi = 'कमरे में जो कुत्ता या बिल्ली है ही नहीं, उसे सहलाता है और उसका नाम रखता है? उसकी कल्पना अब भौतिक सीमाएँ पार कर चुकी है। कमरे के एक कोने में एक अदृश्य पानी का कटोरा रखिए और इस प्यारे भ्रम में आप भी शामिल हो जाइए।', title_id = 'Hewan peliharaan khayalan 🐕', body_id = 'Ia mengelus anjing atau kucing yang tidak ada di kamar dan memberinya nama? Imajinasinya sudah melampaui batas fisik. Letakkan mangkuk air tak kasatmata di sudut kamar dan ikutlah dalam ilusi manis ini.', title_ja = '空想のペット 🐕', body_ja = '部屋にいない犬やねこをなでて、名前をつけている？想像力はもう現実の境界を超えています。部屋のすみに見えない水入れを置いて、このかわいい空想にあなたも加わりましょう。', title_ko = '상상 속 반려동물 🐕', body_ko = '방에 없는 강아지나 고양이를 쓰다듬으며 이름을 지어 주나요? 상상력이 이미 물리적 경계를 넘어섰어요. 방 한쪽에 보이지 않는 물그릇을 놓고 이 귀여운 상상에 함께해 주세요.', title_nl = 'Het denkbeeldige huisdier 🐕', body_nl = 'Aait hij een hond of kat die er niet is en geeft hij hem een naam? Zijn fantasie gaat al voorbij fysieke grenzen. Zet een onzichtbaar waterbakje in een hoek van de kamer en doe mee met deze lieve illusie.', title_pl = 'Wymyślone zwierzątko 🐕', body_pl = 'Głaszcze psa albo kota, którego nie ma w pokoju, i nadaje mu imię? Jego wyobraźnia przekroczyła już fizyczne granice. Postaw w kącie pokoju niewidzialną miskę z wodą i dołącz do tej słodkiej iluzji.', title_pt = 'Um animal de estimação imaginário 🐕', body_pt = 'Faz festas a um cão ou gato que não está no quarto e dá-lhe um nome? A imaginação já ultrapassou os limites físicos. Ponha uma tigela de água invisível num canto do quarto e entre também nesta doce ilusão.', title_sv = 'Ett låtsasdjur 🐕', body_sv = 'Klappar barnet en hund eller katt som inte finns i rummet och ger den ett namn? Fantasin har redan gått bortom de fysiska gränserna. Ställ en osynlig vattenskål i ett hörn av rummet och var med i den söta illusionen.', title_vi = 'Thú cưng tưởng tượng 🐕', body_vi = 'Bé vuốt ve một chú chó hay chú mèo không có trong phòng và còn đặt tên cho nó? Trí tưởng tượng của bé đã vượt qua mọi giới hạn vật lý. Hãy đặt một bát nước vô hình ở góc phòng và cùng tham gia vào ảo tưởng ngọt ngào này.', title_zh = '想象中的宠物 🐕', body_zh = '抚摸着房间里并不存在的小狗或小猫，还给它取了名字？想象力已经超越了现实的边界。在房间一角放一个看不见的水碗，你也加入这场可爱的幻想吧。' WHERE id = '123c0368-cc37-47f7-bb36-f227dd4d9131' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Banquete en la cubitera 🧊', body_es = '¿Hagas lo que hagas no se come la verdura? Cambia por completo la presentación. Reparte tentempiés sanos en los huequitos de una cubitera. Una presentación original siempre abre el apetito.', title_fr = 'Festin dans le bac à glaçons 🧊', body_fr = 'Quoi que vous fassiez, il ne mange pas ses légumes ? Changez radicalement la présentation. Répartissez des collations saines dans les petits compartiments d''un bac à glaçons. Une présentation inhabituelle ouvre toujours l''appétit.', title_hi = 'आइस ट्रे में दावत 🧊', body_hi = 'कुछ भी कर लें, वह सब्ज़ियाँ नहीं खाता? परोसने का तरीका पूरी तरह बदल दीजिए। सेहतमंद स्नैक्स को आइस क्यूब ट्रे के छोटे-छोटे खानों में बाँट दीजिए। अनोखा तरीका हमेशा भूख जगाता है।', title_id = 'Pesta di cetakan es 🧊', body_id = 'Apa pun yang Anda lakukan, ia tetap tidak mau makan sayur? Ubah penyajiannya secara drastis. Bagikan camilan sehat ke lubang-lubang kecil cetakan es batu (ice cube tray). Penyajian yang tidak biasa selalu membangkitkan selera makan.', title_ja = '製氷皿でごちそう 🧊', body_ja = '何をしても野菜を食べない？盛りつけをがらりと変えてみましょう。体にいいおやつを製氷皿の小さなくぼみに分けて入れてみて。いつもとちがう出し方は、いつだって食欲をそそります。', title_ko = '얼음 틀 만찬 🧊', body_ko = '무슨 수를 써도 채소를 안 먹나요? 담음새를 확 바꿔 보세요. 건강한 간식을 얼음 틀의 작은 칸에 나눠 담아 주세요. 색다른 차림은 언제나 입맛을 돋워요.', title_nl = 'Feestmaal uit een ijsblokjesvorm 🧊', body_nl = 'Eet hij die groenten niet, wat je ook doet? Verander de presentatie radicaal. Verdeel gezonde snacks over de vakjes van een ijsblokjesvorm (ice cube tray). Een ongewone presentatie maakt altijd hongerig.', title_pl = 'Uczta w foremce do lodu 🧊', body_pl = 'Cokolwiek robisz, nie je warzyw? Zmień radykalnie sposób podania. Rozłóż zdrowe przekąski do małych przegródek foremki do lodu. Nietypowe podanie zawsze pobudza apetyt.', title_pt = 'Banquete na forma de gelo 🧊', body_pt = 'Faça o que fizer, não come os legumes? Mude radicalmente a apresentação. Distribua snacks saudáveis pelos pequenos compartimentos de uma forma de cubos de gelo. Uma apresentação fora do comum abre sempre o apetite.', title_sv = 'Kalas i isbitsformen 🧊', body_sv = 'Vad du än gör äter barnet inte grönsakerna? Ändra serveringen helt. Fördela nyttiga mellanmål i de små facken i en isbitsform. En ovanlig servering väcker alltid aptiten.', title_vi = 'Bữa tiệc trong khay đá 🧊', body_vi = 'Làm gì bé cũng không chịu ăn rau? Hãy thay đổi hẳn cách trình bày. Chia những món ăn vặt bổ dưỡng vào các ô nhỏ của khay làm đá. Cách bày biện lạ mắt luôn giúp bé ăn ngon miệng hơn.', title_zh = '冰格里的盛宴 🧊', body_zh = '怎么做都不肯吃那些蔬菜？彻底换个摆盘方式。把健康小零食分装进冰格（ice cube tray）的小格子里。不寻常的呈现方式总能打开胃口。' WHERE id = 'ecca6ba2-c00d-4fde-a20b-1268d23c90e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un respiro para mamá 🌬️', body_es = 'El caos de casa te hace pitar los oídos. Consulta Tiempo y ropa y, aunque sea bien abrigados, salid fuera solo 15 minutos. Que él recoja piedras del suelo y tú respira hondo el aire frío y limpio que te da en la cara.', title_fr = 'Une bouffée d''air pour maman 🌬️', body_fr = 'Le chaos de la maison vous fait bourdonner les oreilles. Consultez Météo et tenue, couvrez-vous bien s''il le faut et sortez juste 15 minutes. Qu''il ramasse les cailloux, et vous, respirez profondément l''air frais et pur sur votre visage.', title_hi = 'माँ के लिए एक साँस 🌬️', body_hi = 'घर की अफ़रा-तफ़री से कान झनझना रहे हैं। मौसम और कपड़े देखिए, मोटे कपड़े ही सही, पहनकर बस 15 मिनट बाहर निकलिए। वह ज़मीन से पत्थर इकट्ठा करे, और आप चेहरे पर लगती ठंडी, साफ़ हवा गहरी-गहरी साँसों में भरिए।', title_id = 'Napas untuk Ibu 🌬️', body_id = 'Kekacauan di rumah membuat telinga Anda berdenging. Cek Cuaca dan Pakaian, berpakaianlah tebal bila perlu, dan keluarlah 15 menit saja. Biarkan ia mengumpulkan batu, sementara Anda cukup menghirup dalam-dalam udara dingin dan segar yang menerpa wajah.', title_ja = 'ママのための深呼吸 🌬️', body_ja = '家の中のカオスで耳鳴りがしそう。「天気と服装」をチェックして、厚着をしてでも15分だけ外に出ましょう。この子は石を拾い、あなたは顔にあたる冷たくて澄んだ空気を、深く深く吸いこんで。', title_ko = '엄마를 위한 숨 고르기 🌬️', body_ko = '집 안의 혼돈에 귀가 울리나요? 날씨와 옷차림을 확인하고 두툼하게 입더라도 딱 15분만 밖에 나가 보세요. 아이는 돌을 줍게 두고, 엄마는 얼굴에 닿는 차갑고 맑은 공기를 깊이 들이마시세요.', title_nl = 'Ademruimte voor mama 🌬️', body_nl = 'De chaos in huis laat je oren suizen. Check Weer en kleding, kleed je desnoods dik aan en ga gewoon 15 minuten naar buiten. Laat hem steentjes verzamelen en adem jij diep de koude, frisse lucht in die langs je gezicht strijkt.', title_pl = 'Oddech dla mamy 🌬️', body_pl = 'Domowy chaos dzwoni ci w uszach. Sprawdź Pogodę i ubiór, ubierzcie się nawet ciepło i wyjdźcie na dwór choćby na 15 minut. Niech on zbiera kamyki, a ty po prostu głęboko wdychaj zimne, czyste powietrze.', title_pt = 'Ar para a mãe 🌬️', body_pt = 'O caos da casa faz-lhe zumbir os ouvidos. Veja o Tempo e Roupa, vista-se, nem que seja bem agasalhada, e saia só 15 minutos. Ele que apanhe pedras do chão e a mãe respira fundo o ar frio e puro que lhe bate na cara.', title_sv = 'Andrum för mamma 🌬️', body_sv = 'Kaoset hemma får det att ringa i öronen. Kolla Väder och kläder, klä er varmt om det behövs och gå ut i bara 15 minuter. Låt barnet samla stenar från marken, och andas du bara djupt in den kalla, friska luften mot ansiktet.', title_vi = 'Hít thở cho mẹ 🌬️', body_vi = 'Sự hỗn loạn trong nhà làm tai mẹ ù đi. Hãy kiểm tra Thời tiết và trang phục, dù phải mặc dày cũng hãy ra ngoài chỉ 15 phút. Để bé nhặt sỏi trên mặt đất, còn mẹ chỉ cần hít thật sâu bầu không khí mát lạnh, trong lành đang phả vào mặt.', title_zh = '妈妈的喘息时间 🌬️', body_zh = '家里的混乱让你耳朵嗡嗡作响。看看天气与穿衣，就算要穿厚一点，也出门待上15分钟吧。宝宝去捡地上的石头，你就深深地吸几口扑面而来的清冷新鲜空气。' WHERE id = '80fe5b22-0f4c-4f31-ac99-30418e5a6c6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El idioma de los dinosaurios 🦖', body_es = 'Esta mañana no es una persona, es un dinosaurio y responde a todas tus preguntas solo rugiendo. Los juegos de rol son una herramienta perfecta para el desarrollo de la personalidad. Deja de ser mamá un momento, conviértete en otro dinosaurio y respóndele en su idioma.', title_fr = 'La langue des dinosaures 🦖', body_fr = 'Ce matin, ce n''est pas un enfant mais un dinosaure, et il ne répond à vos questions qu''en rugissant. Les jeux de rôle sont un excellent outil pour le développement de la personnalité. Pour un instant, devenez vous aussi un autre dinosaure et répondez-lui dans sa langue.', title_hi = 'डायनासोर की भाषा 🦖', body_hi = 'आज सुबह वह इंसान नहीं, डायनासोर है और आपके हर सवाल का जवाब सिर्फ़ दहाड़कर देता है। रोल-प्ले खेल व्यक्तित्व के विकास का बेहतरीन ज़रिया है। आप भी एक पल के लिए माँ नहीं, एक और डायनासोर बनकर उसकी भाषा में जवाब दीजिए।', title_id = 'Bahasa dinosaurus 🦖', body_id = 'Pagi ini ia bukan manusia, tapi dinosaurus, dan menjawab semua pertanyaan Anda hanya dengan mengaum. Bermain peran adalah sarana sempurna untuk perkembangan kepribadian. Sejenak, jadilah dinosaurus lain alih-alih ibu, dan jawab ia dengan bahasanya sendiri.', title_ja = '恐竜語 🦖', body_ja = '今朝のこの子は人間ではなく恐竜で、どんな質問にもガオーとほえて答えます。ごっこ遊びは人格の発達にぴったりの方法です。あなたも少しだけママをやめて、もう1頭の恐竜になって、恐竜語で返事をしてあげましょう。', title_ko = '공룡의 언어 🦖', body_ko = '오늘 아침 아이는 사람이 아니라 공룡이라 모든 질문에 으르렁거리기만 하나요? 역할 놀이는 인격 발달에 아주 좋은 도구예요. 엄마도 잠시 다른 공룡이 되어 아이의 언어로 대답해 주세요.', title_nl = 'Dinosaurustaal 🦖', body_nl = 'Vanochtend is hij geen mens maar een dinosaurus en beantwoordt hij al je vragen alleen met gebrul. Rollenspel is een perfect middel voor de ontwikkeling van zijn persoonlijkheid. Wees even geen mama maar ook een dinosaurus en antwoord hem in zijn eigen taal.', title_pl = 'Język dinozaurów 🦖', body_pl = 'Dziś rano nie jest człowiekiem, tylko dinozaurem i na wszystkie twoje pytania odpowiada wyłącznie rykiem. Zabawy w odgrywanie ról to świetne narzędzie rozwoju osobowości. Na chwilę przestań być mamą, zostań drugim dinozaurem i odpowiedz mu w jego języku.', title_pt = 'Língua de dinossauro 🦖', body_pt = 'Esta manhã não é uma pessoa, é um dinossauro e responde a todas as perguntas só com rugidos. As brincadeiras de faz de conta são ótimas para o desenvolvimento da personalidade. Por um momento, deixe de ser mãe e seja outro dinossauro: responda-lhe na língua dele.', title_sv = 'Dinosauriespråk 🦖', body_sv = 'I morse är barnet ingen människa utan en dinosaurie, och svarar på alla dina frågor bara genom att ryta. Rollekar är ett perfekt verktyg för personlighetsutvecklingen. Var för en stund ingen mamma utan en annan dinosaurie, och svara på barnets eget språk.', title_vi = 'Ngôn ngữ khủng long 🦖', body_vi = 'Sáng nay bé không phải con người mà là một chú khủng long, và chỉ trả lời mọi câu hỏi của mẹ bằng tiếng gầm! Trò chơi nhập vai là công cụ tuyệt vời để phát triển nhân cách. Hãy tạm thôi làm mẹ, trở thành một chú khủng long khác và đáp lại bé bằng chính ngôn ngữ của bé.', title_zh = '恐龙语 🦖', body_zh = '今天早上宝宝不是人，而是一只恐龙，回答你所有问题都只会“嗷呜”。角色扮演游戏是人格发展的绝佳方式。你也暂时别当妈妈，变成另一只恐龙，用它的语言回应它吧。' WHERE id = '93c26bc0-b2a6-4580-91d3-d91792e077a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesión de cansancio 📝', body_es = '¿Sientes que nadie te entiende y que tu esfuerzo no se ve? Deja a un lado las sonrisas forzadas. Escribe en el Diario de ánimo lo agotada que estás de verdad hoy. Cada palabra que vuelques en la pantalla te quitará un peso de encima.', title_fr = 'Avouer sa fatigue 📝', body_fr = 'Vous avez l''impression que personne ne vous comprend et que vos efforts passent inaperçus ? Laissez de côté les sourires forcés. Écrivez dans le Journal d''humeur à quel point vous êtes vraiment épuisée aujourd''hui. Chaque mot posé à l''écran vous enlèvera un poids des épaules.', title_hi = 'थकान का इकरार 📝', body_hi = 'लगता है कोई आपको नहीं समझता, आपकी मेहनत किसी को दिखती नहीं? बनावटी मुस्कानें एक तरफ़ रखिए। मूड डायरी में लिखिए कि आज असल में आप कितनी थक चुकी हैं। स्क्रीन पर उतरा हर शब्द आपके कंधों से भारी बोझ उतारेगा।', title_id = 'Mengakui rasa lelah 📝', body_id = 'Merasa tidak ada yang memahami Anda dan jerih payah Anda tak terlihat? Singkirkan senyum yang dipaksakan. Tuliskan di Buku Harian Suasana Hati betapa sebenarnya Anda kehabisan tenaga hari ini. Setiap kata yang tertuang ke layar akan mengangkat beban berat dari pundak Anda.', title_ja = '疲れたと打ち明けて 📝', body_ja = '誰もわかってくれない、がんばりが見えていないと感じていますか？作り笑いは脇に置いて。「気分日記」に、今日本当はどれほど疲れきったかを書きましょう。画面に書いた言葉のひとつひとつが、肩の重荷をおろしてくれます。', title_ko = '피로 고백 📝', body_ko = '아무도 나를 이해하지 못하고 내 수고가 보이지 않는 것 같나요? 억지 미소는 내려놓으세요. 기분 일기에 오늘 사실 얼마나 지쳤는지 적어 보세요. 화면에 쏟아낸 한 마디 한 마디가 어깨의 무거운 짐을 덜어 줄 거예요.', title_nl = 'Moeheid toegeven 📝', body_nl = 'Heb je het gevoel dat niemand je begrijpt en dat niemand ziet wat je doet? Zet die geforceerde glimlach even opzij. Schrijf in je Stemmingsdagboek hoe uitgeput je je vandaag echt voelt. Elk woord op het scherm haalt een zware last van je schouders.', title_pl = 'Wyznanie zmęczenia 📝', body_pl = 'Czujesz, że nikt cię nie rozumie, a twojego trudu nie widać? Odłóż wymuszone uśmiechy. Zapisz w Dzienniku nastroju, jak bardzo jesteś dziś naprawdę wyczerpana. Każde słowo wylane na ekran zdejmie ci z ramion ciężar.', title_pt = 'Confissão de cansaço 📝', body_pt = 'Sente que ninguém a compreende e que o seu esforço não se vê? Ponha de lado os sorrisos forçados. Escreva no Diário de Humor como hoje ficou realmente esgotada. Cada palavra no ecrã vai tirar-lhe um peso dos ombros.', title_sv = 'Erkänn tröttheten 📝', body_sv = 'Tycker du att ingen förstår dig och att ingen ser ditt slit? Lägg undan de överdrivna leendena. Skriv i Humördagboken hur slut du egentligen var i dag. Varje ord på skärmen lyfter en tung börda från dina axlar.', title_vi = 'Thừa nhận sự mệt mỏi 📝', body_vi = 'Mẹ nghĩ rằng không ai hiểu mình, công sức của mình chẳng ai thấy? Hãy gác lại những nụ cười gượng gạo. Viết vào Nhật ký tâm trạng xem hôm nay mẹ thật sự đã kiệt sức thế nào. Mỗi chữ trút lên màn hình sẽ nhấc đi một gánh nặng trên vai mẹ.', title_zh = '疲惫的坦白 📝', body_zh = '觉得没人理解你，你的付出没人看见？把勉强挤出的笑容放到一边。在心情日记里写下今天你其实有多么精疲力竭。倾倒在屏幕上的每一个字，都会从你肩上卸下一份重担。' WHERE id = 'b992124a-a4ae-4e30-a81b-b79de4b95a68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial e inquietudes 🤖', body_es = '¿De repente te ha preocupado que no pronuncie algunas letras? Cierra los foros de internet poco profesionales y alarmistas. Pregunta a Anacan AI por las pautas del desarrollo del habla cerca de los 3 años y obtén una respuesta científica y tranquilizadora.', title_fr = 'Intelligence artificielle et inquiétudes 🤖', body_fr = 'Son incapacité à prononcer certains sons vous a soudain inquiétée ? Fermez les forums peu professionnels et effrayants d''Internet. Demandez à Anacan AI les normes du développement du langage à l''approche des 3 ans et obtenez une réponse scientifique et rassurante.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और चिंताएँ 🤖', body_hi = 'बच्चे का कुछ अक्षर न बोल पाना अचानक आपको परेशान कर गया? इंटरनेट के गैर-पेशेवर और डरावने फ़ोरम बंद कीजिए। Anacan AI से 3 साल के आसपास बोलने के विकास के मानक पूछिए और वैज्ञानिक, सुकून देने वाला जवाब पाइए।', title_id = 'Kecerdasan buatan dan kecemasan 🤖', body_id = 'Tiba-tiba Anda cemas karena ia belum bisa mengucapkan beberapa huruf? Tutup forum-forum internet yang tidak profesional dan menakutkan. Tanyakan pada Anacan AI tentang standar perkembangan bicara menjelang usia 3 tahun, dan dapatkan jawaban ilmiah yang menenangkan.', title_ja = 'AIと不安 🤖', body_ja = 'いくつかの音がうまく言えないことに、急に不安になりましたか？ネットの専門的でない怖い掲示板は閉じましょう。Anacan AIに3歳前後の言葉の発達の目安をたずねて、科学的で安心できる答えをもらいましょう。', title_ko = '인공지능과 걱정들 🤖', body_ko = '아이가 몇몇 발음을 못 해서 갑자기 불안해졌나요? 비전문적이고 무서운 인터넷 게시판은 닫으세요. Anacan AI에게 세 살 무렵의 언어 발달 기준을 물어보고 과학적이고 안심되는 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en zorgen 🤖', body_nl = 'Raakte je ineens in paniek omdat je kind sommige letters niet kan uitspreken? Sluit die onprofessionele, angstaanjagende fora. Vraag Anacan AI naar de normen voor taalontwikkeling rond 3 jaar en krijg een wetenschappelijk, geruststellend antwoord.', title_pl = 'Sztuczna inteligencja i niepokoje 🤖', body_pl = 'Zaniepokoiło cię nagle, że dziecko nie wymawia niektórych głosek? Zamknij nieprofesjonalne, straszące fora w internecie. Zapytaj Anacan AI o normy rozwoju mowy w okolicach 3 lat i uzyskaj naukową, uspokajającą odpowiedź.', title_pt = 'Inteligência artificial e preocupações 🤖', body_pt = 'De repente ficou aflita por ele não conseguir pronunciar algumas letras? Feche os fóruns pouco profissionais e assustadores da internet. Pergunte ao Anacan AI quais são as normas do desenvolvimento da fala perto dos 3 anos e obtenha uma resposta científica e tranquilizadora.', title_sv = 'Artificiell intelligens och oro 🤖', body_sv = 'Blev du plötsligt orolig över att barnet inte kan uttala vissa bokstäver? Stäng de oprofessionella och skrämmande forumen på nätet. Fråga Anacan AI om normerna för talutveckling inför 3 år och få ett vetenskapligt och lugnande svar.', title_vi = 'Trí tuệ nhân tạo và những lo lắng 🤖', body_vi = 'Việc bé chưa phát âm được một số chữ cái bỗng khiến mẹ lo lắng? Hãy đóng những diễn đàn thiếu chuyên môn, đáng sợ trên mạng. Hãy hỏi Anacan AI về chuẩn phát triển ngôn ngữ khi gần 3 tuổi và nhận câu trả lời khoa học, giúp mẹ yên tâm.', title_zh = '人工智能与焦虑 🤖', body_zh = '宝宝有些音发不准，突然让你很慌？关掉网上那些不专业又吓人的论坛。问问Anacan AI快3岁时语言发展的正常标准，得到科学又安心的答案。' WHERE id = '075e0950-03bc-496b-a1a2-1172377fb523' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El circo en la cama 🎪', body_es = 'Cuando llega la hora de dormir, la cama se convierte de pronto en la pista de un circo. Salta, se arrastra, grita. Sin levantar la voz, baja las luces. Está soltando sus últimas migajas de energía. Apaga poco a poco esta tormenta con una historia de ritmo muy lento de Cuentos inteligentes.', title_fr = 'Le cirque au lit 🎪', body_fr = 'À l''heure du coucher, le lit se transforme d''un coup en piste de cirque. Il saute, rampe, crie. Sans hausser la voix, baissez les lumières. Il dépense ses dernières miettes d''énergie. Éteignez peu à peu cette tempête avec une histoire au rythme très lent des Contes intelligents.', title_hi = 'बिस्तर पर सर्कस 🎪', body_hi = 'सोने का समय आते ही बिस्तर पल भर में सर्कस का मैदान बन जाता है। उछलता है, रेंगता है, चिल्लाता है। आवाज़ ऊँची किए बिना रोशनी धीमी कीजिए। वह ऊर्जा के आखिरी टुकड़े निकाल रहा है। स्मार्ट कहानियों में बहुत धीमी लय वाली कहानी से इस तूफ़ान को धीरे-धीरे शांत कीजिए।', title_id = 'Sirkus di tempat tidur 🎪', body_id = 'Saat waktu tidur tiba, tempat tidur seketika berubah jadi arena sirkus. Ia melompat, merayap, berteriak. Tanpa meninggikan suara, redupkan lampu. Ia sedang membuang sisa-sisa energinya. Padamkan badai ini perlahan dengan cerita berirama sangat lambat dari Dongeng Pintar.', title_ja = 'ベッドの上のサーカス 🎪', body_ja = '寝る時間になると、ベッドはあっという間にサーカスの舞台に。ジャンプして、はいまわって、叫んで。声を荒らげずに明かりを落としましょう。最後のエネルギーを出しきっているところです。「スマートおはなし」のゆったりしたリズムのお話で、この嵐を少しずつしずめましょう。', title_ko = '침대 위 서커스 🎪', body_ko = '잘 시간이 되면 침대가 순식간에 서커스 무대로 변하나요? 뛰고, 기고, 소리치죠. 목소리를 높이지 말고 불을 낮추세요. 남은 에너지를 털어내는 중이에요. 스마트 동화의 아주 느린 리듬의 이야기로 이 폭풍을 천천히 잠재워 주세요.', title_nl = 'Circus in bed 🎪', body_nl = 'Als het bedtijd is, verandert het bed ineens in een circusarena. Hij springt, kruipt en schreeuwt. Dim de lichten zonder je stem te verheffen. Hij gooit de laatste restjes energie eruit. Laat deze storm langzaam uitdoven met een heel rustig verhaal uit Slimme sprookjes.', title_pl = 'Cyrk w łóżku 🎪', body_pl = 'Gdy przychodzi pora snu, łóżko w jednej chwili zamienia się w arenę cyrkową. Skacze, pełza, krzyczy. Nie podnosząc głosu, przygaś światła. Wyrzuca z siebie ostatnie okruchy energii. Stopniowo wycisz tę burzę bardzo spokojną historią z Mądrych bajek.', title_pt = 'Circo na cama 🎪', body_pt = 'Quando chega a hora de dormir, a cama transforma-se de repente numa arena de circo. Salta, rasteja, grita. Sem levantar a voz, baixe as luzes. Está a gastar os últimos restos de energia. Apague aos poucos esta tempestade com uma história de ritmo muito lento das Histórias Inteligentes.', title_sv = 'Cirkus i sängen 🎪', body_sv = 'När det är dags att sova förvandlas sängen genast till en cirkusarena. Barnet hoppar, kryper och skriker. Dämpa ljuset utan att höja rösten. Barnet gör sig av med de sista smulorna energi. Släck stormen gradvis med en berättelse i mycket långsam rytm i Smarta sagor.', title_vi = 'Rạp xiếc trên giường 🎪', body_vi = 'Đến giờ ngủ, chiếc giường bỗng thành sân khấu xiếc. Bé nhảy, bò, la hét. Đừng lớn tiếng, hãy giảm đèn. Bé đang xả những chút năng lượng cuối cùng. Hãy dập tắt dần cơn bão này bằng một câu chuyện nhịp thật chậm trong Truyện cổ tích thông minh.', title_zh = '床上的马戏团 🎪', body_zh = '一到睡觉时间，床就瞬间变成了马戏场。又蹦又爬又叫。别提高嗓门，把灯光调暗。宝宝正在释放最后一点能量。用智慧童话里节奏很慢的故事，慢慢平息这场风暴吧。' WHERE id = '9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pomo de la puerta no se comparte 🚪', body_es = '«¡La puerta la abro yo!», dice, y corre para llegar antes que tú. Si la abres tú, te la hace cerrar llorando y la vuelve a abrir él. A esta edad la sensación de control lo es todo. Deja que la abra: estas pequeñas victorias alimentan su autoestima, que aún es frágil.', title_fr = 'La poignée de porte qui ne se partage pas 🚪', body_fr = '« C''est moi qui ouvre ! » dit-il en courant devant vous. Si vous l''avez ouverte, il vous la fait refermer en pleurant pour l''ouvrir lui-même. À cet âge, le sentiment de contrôle est tout. Laissez-le ouvrir : ces petites victoires nourrissent sa confiance en lui encore fragile.', title_hi = 'न बँटने वाला दरवाज़े का हैंडल 🚪', body_hi = '‘दरवाज़ा मैं खोलूँगा!’ कहकर आपसे पहले दौड़ता है। अगर आपने खोल दिया, तो रोकर फिर बंद करवाता है और खुद खोलता है। इस उम्र में नियंत्रण का एहसास ही सब कुछ है। उसे खोलने दीजिए, ये छोटी जीतें उसके नाज़ुक आत्मविश्वास को पोषण देती हैं।', title_id = 'Gagang pintu yang tak bisa dibagi 🚪', body_id = '''Aku yang buka pintunya!'' katanya sambil berlari mendahului Anda. Kalau Anda yang membuka, ia menangis minta pintu ditutup lagi lalu membukanya sendiri. Rasa memegang kendali adalah segalanya di usia ini. Biarkan ia yang membuka, kemenangan kecil ini memupuk rasa percaya dirinya yang mudah terluka.', title_ja = 'ゆずれないドアノブ 🚪', body_ja = '「ドアはわたしが開ける！」とあなたより先に走っていく。あなたが開けてしまうと、泣いてもう一度閉めさせ、自分で開けます。この年ごろは「自分で決められる」感覚がすべて。開けさせてあげましょう。こんな小さな勝利が、傷つきやすい自信を育てます。', title_ko = '양보할 수 없는 문손잡이 🚪', body_ko = '''문은 내가 열 거야!'' 하며 엄마보다 먼저 달려가나요? 엄마가 열었다면 울면서 다시 닫게 하고 자기가 열죠. 이 나이에는 통제감이 전부예요. 열게 해 주세요, 이런 작은 승리가 상처받기 쉬운 자신감을 키워 줘요.', title_nl = 'De deurklink die niet gedeeld wordt 🚪', body_nl = '''Ik doe de deur open!'' roept hij en rent voor je uit. Heb jij hem al opengedaan, dan laat hij hem huilend weer dichtdoen en doet hij hem zelf open. Het gevoel van controle is op deze leeftijd alles. Laat hem de deur openen: deze kleine overwinningen voeden zijn kwetsbare zelfvertrouwen.', title_pl = 'Klamka nie do podziału 🚪', body_pl = '„Ja otworzę drzwi!” woła i biegnie przed tobą. Jeśli to ty otworzyłaś, z płaczem każe je zamknąć i otwiera sam. Poczucie kontroli to w tym wieku wszystko. Pozwól mu otworzyć, te małe zwycięstwa karmią jego kruchą pewność siebie.', title_pt = 'O puxador da porta que não se partilha 🚪', body_pt = 'Diz "Eu é que abro a porta!" e corre à sua frente. Se for a mãe a abrir, chora, obriga a fechar e abre ele. Nesta idade, a sensação de controlo é tudo. Deixe-o abrir: estas pequenas vitórias alimentam a sua autoestima, que é tão frágil.', title_sv = 'Dörrhandtaget som inte kan delas 🚪', body_sv = 'Barnet springer före dig och säger ”Jag ska öppna dörren!”. Om du öppnade den låter barnet dig gråtande stänga den igen och öppnar själv. Känslan av kontroll är allt i den här åldern. Låt barnet öppna, de små segrarna stärker ett självförtroende som lätt tar skada.', title_vi = 'Tay nắm cửa không thể chia sẻ 🚪', body_vi = '"Con mở cửa!" bé nói và chạy vượt lên trước mẹ. Nếu mẹ đã mở, bé sẽ khóc bắt đóng lại để tự mở. Cảm giác kiểm soát là tất cả ở tuổi này. Hãy để bé mở, những chiến thắng nhỏ này nuôi dưỡng sự tự tin còn mong manh của bé.', title_zh = '不能分享的门把手 🚪', body_zh = '“我来开门！”说着就抢在你前面跑过去。要是你先开了，宝宝就哭着让你关上，再自己打开。这个年龄，掌控感就是一切。让宝宝来开吧，这些小小的胜利，滋养着宝宝容易受伤的自信心。' WHERE id = 'c4897803-48e7-46f1-aca1-db692fe7b9f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una comunidad solidaria 💬', body_es = 'Hoy se ha resistido tanto que te sientes mala madre. Entra ya en la Comunidad Anacan. Cuando leas las rebeliones de hoy de los hijos de otras madres, entenderás que no estás sola y que en realidad lo estás haciendo de maravilla.', title_fr = 'Une communauté solidaire 💬', body_fr = 'Il a tellement résisté aujourd''hui que vous vous sentez une mauvaise mère. Entrez tout de suite dans la Communauté Anacan. En lisant les révoltes du jour des enfants d''autres mamans, vous comprendrez que vous n''êtes pas seule et que vous faites en réalité un travail formidable.', title_hi = 'एकजुटता की कम्युनिटी 💬', body_hi = 'आज उसने इतनी ज़िद की कि आप खुद को बुरी माँ महसूस कर रही हैं। तुरंत Anacan कम्युनिटी में जाइए। दूसरी माँओं के बच्चों की आज की बगावतें पढ़कर आप समझेंगी कि आप अकेली नहीं हैं और असल में शानदार काम कर रही हैं।', title_id = 'Komunitas yang saling mendukung 💬', body_id = 'Hari ini ia begitu banyak membangkang sampai Anda merasa menjadi ibu yang buruk. Segera masuk ke Komunitas Anacan. Saat membaca pemberontakan anak-anak ibu lain hari ini, Anda akan sadar bahwa Anda tidak sendirian dan sebenarnya Anda sedang melakukan pekerjaan yang luar biasa.', title_ja = '支え合えるコミュニティ 💬', body_ja = '今日は反抗がひどくて、自分はダメなママだと感じていますか？すぐにAnacanコミュニティを開いて。ほかのママたちの子どもの今日の反乱を読めば、ひとりじゃないこと、そしてあなたは本当によくやっていることがわかります。', title_ko = '함께하는 커뮤니티 💬', body_ko = '오늘 너무 고집을 부려서 내가 나쁜 엄마 같다고 느껴지나요? 바로 Anacan 커뮤니티에 들어가 보세요. 다른 엄마들의 아이가 오늘 벌인 반란을 읽으면 혼자가 아니고, 사실 엄마가 정말 잘하고 있다는 걸 알게 될 거예요.', title_nl = 'Een Community die samen sterk staat 💬', body_nl = 'Hij heeft zich vandaag zo verzet dat je je een slechte moeder voelt. Ga meteen naar de Anacan Community. Als je leest over de opstandjes van andere kinderen vandaag, besef je dat je niet de enige bent en het eigenlijk geweldig doet.', title_pl = 'Wspierająca społeczność 💬', body_pl = 'Dziś tak bardzo się opierał, że czujesz się złą mamą. Od razu wejdź do Społeczności Anacan. Gdy przeczytasz o dzisiejszych buntach dzieci innych mam, zrozumiesz, że nie jesteś sama i tak naprawdę świetnie sobie radzisz.', title_pt = 'Uma comunidade solidária 💬', body_pt = 'Hoje resistiu tanto que se sente uma má mãe. Entre já na Comunidade Anacan. Ao ler as revoltas de hoje dos filhos de outras mães, vai perceber que não está sozinha e que, na verdade, está a fazer um trabalho fantástico.', title_sv = 'En gemenskap som håller ihop 💬', body_sv = 'I dag gjorde barnet så mycket motstånd att du känner dig som en dålig mamma. Gå genast in i Anacan Community. När du läser om andra mammors barns uppror i dag förstår du att du inte är ensam och att du faktiskt gör ett fantastiskt jobb.', title_vi = 'Cộng đồng đồng cảm 💬', body_vi = 'Hôm nay bé chống đối nhiều đến mức mẹ cảm thấy mình là một người mẹ tồi. Hãy vào ngay Cộng đồng Anacan. Khi đọc về những cuộc "nổi loạn" hôm nay của con các mẹ khác, mẹ sẽ hiểu rằng mình không đơn độc và thật ra đang làm rất tuyệt.', title_zh = '互相支持的社区 💬', body_zh = '今天宝宝倔得不行，让你觉得自己是个糟糕的妈妈。马上进入Anacan社区。读到其他妈妈家的孩子今天也在“造反”，你就会明白自己并不孤单，其实你做得非常棒。' WHERE id = '2b40e6c9-46bc-4fb2-8d09-1e690e1a478c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Querer y no querer a la vez 🤔', body_es = 'Viene y te suelta frases totalmente paradójicas como «dame agua, pero no me la des». En su cerebro conviven a la vez dos deseos opuestos. Sin buscar mucha lógica, deja el agua en la mesa y que decida su lucha interior.', title_fr = 'Je veux, mais je ne veux pas 🤔', body_fr = 'Il vient vous dire des phrases complètement paradoxales comme « Donne-moi de l''eau, mais ne m''en donne pas ». Deux envies contradictoires coexistent dans sa tête. Sans chercher trop de logique, posez simplement l''eau sur la table et laissez-le trancher son débat intérieur.', title_hi = 'छिपी हुई दुविधा 🤔', body_hi = 'आकर कहता है, ‘मुझे पानी दो, पर मत दो’ जैसे बिल्कुल उलटे वाक्य। उसके दिमाग में एक ही समय दो विरोधी इच्छाएँ होती हैं। ज़्यादा तर्क मत ढूँढिए, बस पानी मेज़ पर रख दीजिए और फ़ैसला उसकी अंदरूनी लड़ाई पर छोड़ दीजिए।', title_id = 'Mau tapi tidak mau 🤔', body_id = 'Ia datang dengan kalimat yang benar-benar paradoks seperti ''Kasih aku air, tapi jangan dikasih''. Di otaknya ada dua keinginan yang bertentangan sekaligus. Tak perlu mencari logikanya, letakkan saja airnya di meja dan biarkan ia memutuskan lewat pergulatan batinnya.', title_ja = 'ほしいけど、いらない 🤔', body_ja = '「お水ちょうだい、でもちょうだいしないで」なんて、まったく矛盾したことを言ってきます。頭の中に、正反対のふたつの気持ちが同時にあるんです。理屈を考えすぎずに、お水をテーブルに置いて、決めるのは本人の心の中の戦いにまかせましょう。', title_ko = '숨은 갈팡질팡 🤔', body_ko = '와서 ''물 줘, 근데 주지 마'' 같은 완전히 모순된 말을 하나요? 머릿속에 반대되는 두 바람이 동시에 있는 거예요. 논리를 너무 찾지 말고 물을 식탁에 올려 두고 결정은 아이의 마음속 싸움에 맡기세요.', title_nl = 'Verborgen tweestrijd 🤔', body_nl = 'Hij komt naar je toe met totaal tegenstrijdige zinnen als ''Geef me water, maar geef het niet''. In zijn hoofd bestaan twee tegengestelde wensen tegelijk. Zoek er niet te veel logica achter, zet het water gewoon op tafel en laat de keuze aan zijn innerlijke strijd over.', title_pl = 'Ukryte „chcę, nie chcę” 🤔', body_pl = 'Podchodzi i mówi zupełnie paradoksalne zdania w stylu: „Daj mi wody, ale nie dawaj”. W jego głowie jednocześnie istnieją dwa sprzeczne pragnienia. Nie szukaj w tym zbyt wiele logiki, po prostu postaw wodę na stole i zostaw decyzję jego wewnętrznej walce.', title_pt = 'Quero e não quero 🤔', body_pt = 'Vem ter consigo com frases totalmente paradoxais como "Dá-me água, mas não me dês". No cérebro dele há dois desejos contraditórios ao mesmo tempo. Sem procurar muita lógica, ponha a água na mesa e deixe a decisão à luta interior dele.', title_sv = 'Dold villrådighet 🤔', body_sv = 'Barnet kommer och säger helt paradoxala meningar som ”Ge mig vatten, men ge mig inte”. I barnets hjärna finns två motstridiga önskningar samtidigt. Leta inte efter för mycket logik, ställ bara vattnet på bordet och låt barnets inre kamp avgöra.', title_vi = 'Muốn mà lại không muốn 🤔', body_vi = 'Bé đến và nói những câu hoàn toàn mâu thuẫn như "Mẹ cho con nước, nhưng đừng cho". Trong đầu bé cùng lúc tồn tại hai mong muốn trái ngược. Đừng tìm logic quá nhiều, chỉ cần đặt cốc nước lên bàn và để bé tự giải quyết "cuộc đấu tranh nội tâm".', title_zh = '藏起来的矛盾心理 🤔', body_zh = '跑来对你说“给我水，但别给我”这种完全矛盾的话。宝宝的大脑里同时存在两种相反的愿望。别太较真找逻辑，把水放在桌上，让宝宝自己内心“斗争”后做决定吧。' WHERE id = '4f85a7f5-323c-4830-b901-61f69a9b8176' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos con martillo y tornillos 🛠️', body_es = 'Con cualquier juguete duro que pilla golpea los muebles para «arreglarlos». Aunque el ruido te taladre el cerebro, es un descubrimiento con el que construye la relación causa-efecto. Dale una caja de cartón vacía y una cuchara de madera y que siga ahí su reparación ruidosa.', title_fr = 'Marteau et tournevis 🛠️', body_fr = 'Il tape sur les meubles avec chaque jouet dur qui lui tombe sous la main pour les « réparer ». Même si le bruit vous perce le crâne, c''est une découverte qui lui fait comprendre la cause et l''effet. Donnez-lui un carton vide et une cuillère en bois, et que ses réparations bruyantes continuent là.', title_hi = 'हथौड़े और पेंच की कोशिशें 🛠️', body_hi = 'हाथ लगे हर सख्त खिलौने से फ़र्नीचर ठोककर ‘मरम्मत’ करता है। आवाज़ें भले दिमाग में चुभें, यह उसकी खोज है जिसमें वह कारण-परिणाम का रिश्ता बना रहा है। उसे एक खाली गत्ते का डिब्बा और लकड़ी का चम्मच दीजिए, शोर वाली मरम्मत वहीं चलने दीजिए।', title_id = 'Main palu dan obeng 🛠️', body_id = 'Ia memukul-mukul perabot dengan setiap mainan keras yang ia temukan untuk ''memperbaikinya''. Meski bunyinya menembus kepala, ini adalah penemuannya tentang sebab-akibat. Beri ia kardus kosong dan sendok kayu, biarkan perbaikan yang berisik itu berlanjut di sana.', title_ja = 'かなづちとネジのチャレンジ 🛠️', body_ja = '手に入るかたいおもちゃで、家具をトントンたたいて修理中。音が頭にひびいても、これは原因と結果のつながりを学ぶ発見です。空の段ボール箱と木のスプーンを渡して、にぎやかな修理はそこで続けてもらいましょう。', title_ko = '망치와 나사 놀이 🛠️', body_ko = '손에 잡히는 딱딱한 장난감마다 가구를 두드리며 수리하나요? 소리가 머리를 뚫어도, 원인과 결과를 연결하는 발견이에요. 빈 종이 상자와 나무 숟가락을 주고 시끄러운 수리는 거기서 계속하게 해 주세요.', title_nl = 'Hamer- en schroefpogingen 🛠️', body_nl = 'Met elk hard speeltje dat hij te pakken krijgt, slaat hij op de meubels om ze te repareren. Ook al boort het geluid door je hoofd, zo ontdekt hij oorzaak en gevolg. Geef hem een lege kartonnen doos en een houten lepel en laat de lawaaiige reparatie daar verdergaan.', title_pl = 'Próby z młotkiem i śrubką 🛠️', body_pl = 'Każdą twardą zabawką, jaka wpadnie mu w ręce, stuka w meble i je „naprawia”. Choć hałas świdruje ci w głowie, to dla niego odkrywanie związku przyczyny ze skutkiem. Daj mu puste kartonowe pudło i drewnianą łyżkę, niech głośny remont toczy się tam.', title_pt = 'Tentativas com martelo e parafusos 🛠️', body_pt = 'Bate nos móveis com qualquer brinquedo duro que lhe venha parar às mãos, a fazer "reparações". Mesmo que o barulho lhe fure o cérebro, é uma descoberta em que ele cria relações de causa-efeito. Dê-lhe uma caixa de cartão vazia e uma colher de pau e deixe as reparações barulhentas continuarem ali.', title_sv = 'Försök med hammare och skruv 🛠️', body_sv = 'Barnet ”reparerar” möblerna genom att slå på dem med varje hård leksak det får tag i. Även om ljuden borrar sig in i hjärnan är det en upptäckt där barnet lär sig orsak och verkan. Ge barnet en tom kartong och en träslev och låt den bullriga reparationen fortsätta där.', title_vi = 'Thợ búa và đinh vít 🛠️', body_vi = 'Bé cầm bất cứ đồ chơi cứng nào cũng gõ vào đồ đạc để "sửa chữa". Dù tiếng ồn như khoan vào đầu mẹ, đây là cách bé khám phá mối quan hệ nhân quả. Hãy đưa bé một hộp các-tông rỗng và một chiếc thìa gỗ, để bé tiếp tục "sửa chữa" ồn ào ở đó.', title_zh = '锤子和螺丝的尝试 🛠️', body_zh = '拿着手边每一个硬玩具敲打家具，“修理”起来。虽然那声音快把你的脑袋钻穿了，但这是宝宝建立因果关系的探索。给宝宝一个空纸箱和一把木勺，让这场吵闹的“装修”在那里继续吧。' WHERE id = 'fb64f95e-ceac-49e1-96ee-95e171273ead' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es arte 🎨', body_es = 'Ha creado en medio de la habitación una gran obra de arte con trocitos de papel e hilos cortados y no te deja tirarla. Deja a un lado la obsesión por la limpieza. Respeta el caos que ha creado: la limpieza puede esperar a mañana.', title_fr = 'Ce n''est pas du désordre, c''est de l''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art faite de petits bouts de papier et de ficelles coupées, et refuse que vous la jetiez. Laissez de côté votre obsession du rangement. Respectez le chaos qu''il a créé, le ménage peut attendre demain.', title_hi = 'कचरा नहीं, कला 🎨', body_hi = 'कमरे के बीच कागज़ के छोटे टुकड़ों और कटे धागों से एक बड़ी कलाकृति बना ली है और फेंकने नहीं देता। सफ़ाई की सनक एक तरफ़ रखिए। उसकी रची अफ़रा-तफ़री का सम्मान कीजिए, सफ़ाई कल तक भी रुक सकती है।', title_id = 'Bukan sampah, tapi seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari sobekan kertas dan potongan benang, dan tidak mengizinkan Anda membuangnya. Singkirkan dulu obsesi kebersihan. Hargai kekacauan yang ia ciptakan, bersih-bersih bisa menunggu besok.', title_ja = 'ゴミじゃない、アートです 🎨', body_ja = '部屋のまんなかに、小さな紙くずや切った毛糸で大作をつくり、捨てさせてくれない。きれい好きはちょっとお休みして、この子がつくったカオスを尊重しましょう。お掃除は明日でも大丈夫です。', title_ko = '쓰레기가 아니라 예술 🎨', body_ko = '방 한가운데 작은 종이 조각과 잘린 실로 커다란 작품을 만들고 버리지 못하게 하나요? 깔끔함에 대한 집착은 잠시 내려놓으세요. 아이가 만든 혼돈을 존중해 주세요, 청소는 내일 해도 돼요.', title_nl = 'Geen rommel, maar kunst 🎨', body_nl = 'Hij heeft midden in de kamer een groot kunstwerk gemaakt van papiersnippers en stukjes touw, en hij laat het je niet weggooien. Zet je opruimdrang even opzij. Respecteer de chaos die hij heeft gemaakt, opruimen kan ook morgen.', title_pl = 'To nie śmieci, to sztuka 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki ze skrawków papieru i pociętych sznurków i nie pozwala go wyrzucić. Odłóż na bok obsesję porządku. Uszanuj chaos, który stworzył, sprzątanie może poczekać do jutra.', title_pt = 'Não é lixo, é arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com pedacinhos de papel e fios cortados e não a deixa deitar fora. Ponha de lado a obsessão pela limpeza. Respeite o caos que ele criou, a limpeza pode ficar para amanhã.', title_sv = 'Inte skräp, utan konst 🎨', body_sv = 'Mitt i rummet har barnet skapat ett stort konstverk av små pappersbitar och avklippta snören och låter dig inte slänga det. Lägg städmanin åt sidan. Respektera kaoset barnet har skapat, städningen kan vänta till i morgon.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Giữa phòng, bé đã tạo ra một "tác phẩm nghệ thuật" lớn từ những mẩu giấy vụn và sợi dây cắt nhỏ, và không cho mẹ vứt đi. Hãy gác lại nỗi ám ảnh sạch sẽ. Tôn trọng sự hỗn loạn bé tạo ra, việc dọn dẹp có thể để đến mai.', title_zh = '不是垃圾，是艺术 🎨', body_zh = '在房间中间用碎纸片、剪断的线头创作了一件大型艺术品，还不让你扔。把洁癖先放一边。尊重宝宝创造的混乱吧，打扫可以留到明天。' WHERE id = '0b8c858b-4b69-4199-b627-a7a497686efd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terapia del Medidor de sonido 🤫', body_es = 'El ruido interminable de casa por fin se ha acabado. Está dormido. Abre el Medidor de sonido y mira cómo bajan los números hasta 0 decibelios. Siente cómo el silencio absoluto de la habitación masajea visualmente tu cerebro.', title_fr = 'La thérapie du Sonomètre 🤫', body_fr = 'Le bruit sans fin de la maison s''est enfin arrêté. Il dort. Ouvrez le Sonomètre et regardez les chiffres descendre jusqu''à 0 décibel. Sentez comme le silence absolu de la pièce masse visuellement votre cerveau.', title_hi = 'साउंड मीटर थेरेपी 🤫', body_hi = 'घर का कभी न खत्म होने वाला शोर आखिरकार थम गया। वह सो रहा है। साउंड मीटर टूल खोलिए और स्क्रीन पर 0 डेसिबल तक गिरते अंक देखिए। महसूस कीजिए कि कमरे की पूरी खामोशी आपके दिमाग की कैसे मसाज करती है।', title_id = 'Terapi Pengukur Suara 🤫', body_id = 'Kebisingan tanpa henti di rumah akhirnya berakhir. Ia sudah tidur. Buka Pengukur Suara dan perhatikan angka di layar yang turun hingga 0 desibel. Rasakan bagaimana keheningan total di kamar memijat otak Anda secara visual.', title_ja = 'サウンドメーターセラピー 🤫', body_ja = '家の中の終わりのない騒がしさが、ようやくおさまりました。この子は夢の中です。「サウンドメーター」を開いて、画面の数字が0デシベルまで下がっていくのを眺めましょう。部屋の完全な静けさが、脳を目に見えてマッサージしてくれるのを感じて。', title_ko = '소음 측정기 테라피 🤫', body_ko = '집 안의 끝없는 소음이 드디어 멈췄어요. 아이가 잠들었죠. 소음 측정기를 열고 화면 속 숫자가 0데시벨까지 내려가는 걸 지켜보세요. 방의 완전한 고요가 머리를 눈으로 마사지해 주는 걸 느껴 보세요.', title_nl = 'Geluidsmetertherapie 🤫', body_nl = 'Het eindeloze lawaai in huis is eindelijk voorbij. Hij slaapt. Open de Geluidsmeter en kijk hoe de getallen op het scherm tot 0 decibel zakken. Voel hoe de absolute stilte in de kamer je brein visueel masseert.', title_pl = 'Terapia Miernikiem dźwięku 🤫', body_pl = 'Niekończący się hałas w domu wreszcie ucichł. On śpi. Otwórz Miernik dźwięku i patrz, jak liczby na ekranie spadają do 0 decybeli. Poczuj, jak absolutna cisza w pokoju wizualnie masuje twój mózg.', title_pt = 'Terapia com o Medidor de Som 🤫', body_pt = 'O barulho interminável da casa finalmente acabou. Ele está a dormir. Abra o Medidor de Som e veja os números no ecrã descerem até aos 0 decibéis. Sinta como o silêncio absoluto do quarto massaja visualmente o seu cérebro.', title_sv = 'Ljudmätarterapi 🤫', body_sv = 'Det ändlösa oväsendet hemma har äntligen tagit slut. Barnet sover. Öppna verktyget Ljudmätare och följ siffrorna på skärmen som sjunker ner mot 0 decibel. Känn hur den totala tystnaden i rummet visuellt masserar din hjärna.', title_vi = 'Liệu pháp Đo âm thanh 🤫', body_vi = 'Tiếng ồn bất tận trong nhà cuối cùng đã dứt. Bé đã ngủ. Hãy mở Đo âm thanh và nhìn những con số trên màn hình hạ dần về 0 decibel. Cảm nhận sự tĩnh lặng tuyệt đối trong phòng đang mát-xa não bộ của mẹ qua từng con số.', title_zh = '分贝仪疗法 🤫', body_zh = '家里没完没了的吵闹终于结束了。宝宝睡着了。打开分贝仪，看着屏幕上的数字一路降到0分贝。感受房间里绝对的安静如何在视觉上给你的大脑做按摩。' WHERE id = '5f97fec7-d72f-4377-af18-4420a1663ca4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Teatro frente al espejo 🎭', body_es = 'A primera hora se pone delante del espejo a ensayar caras de llanto, de risa y de sorpresa. ¡Está aprendiendo a expresar sus emociones y cómo cambia su cara! Observa de lejos y con orgullo esta actuación genial.', title_fr = 'Théâtre devant le miroir 🎭', body_fr = 'Dès le matin, il s''installe devant le miroir pour s''entraîner à différentes mimiques : pleurer, rire, s''étonner. Il apprend à exprimer ses émotions et voit comment son visage change ! Admirez fièrement de loin cette performance d''acteur de génie.', title_hi = 'आईने के सामने नाटक 🎭', body_hi = 'सुबह-सुबह आईने के सामने खड़े होकर रोने, हँसने, हैरान होने के अलग-अलग चेहरे बनाने का अभ्यास करता है। वह सीख रहा है कि अपनी भावनाएँ कैसे दिखाए और उसका चेहरा कैसा रूप लेता है! इस शानदार अदाकारी को दूर से गर्व से देखिए।', title_id = 'Teater di depan cermin 🎭', body_id = 'Pagi-pagi ia sudah berdiri di depan cermin, berlatih berbagai ekspresi menangis, tertawa, dan terkejut. Ia sedang belajar cara mengekspresikan emosi dan bagaimana wajahnya berubah bentuk! Saksikan pertunjukan akting jenius ini dari jauh dengan bangga.', title_ja = '鏡の前の劇場 🎭', body_ja = '朝から鏡の前に立って、泣き顔や笑顔、びっくり顔の練習をしています。気持ちをどう表すか、顔がどう変わるかを学んでいるんです！この天才的な演技を、遠くから誇らしく見守りましょう。', title_ko = '거울 앞 연극 🎭', body_ko = '아침부터 거울 앞에서 우는 표정, 웃는 표정, 놀란 표정을 연습하나요? 감정을 어떻게 표현하는지, 얼굴이 어떻게 바뀌는지 배우는 중이에요! 이 천재 배우의 공연을 멀리서 뿌듯하게 지켜보세요.', title_nl = 'Theater voor de spiegel 🎭', body_nl = 'Al vroeg in de ochtend staat hij voor de spiegel huilende, lachende en verbaasde gezichtjes te oefenen. Hij leert hoe hij zijn emoties uitdrukt en hoe zijn gezicht vorm krijgt! Kijk trots van een afstand naar deze geniale acteerprestatie.', title_pl = 'Teatr przed lustrem 🎭', body_pl = 'Od samego rana staje przed lustrem i ćwiczy różne miny: płacz, śmiech, zdziwienie. Uczy się, jak wyrażać emocje i jak zmienia się jego twarz! Z dumą obserwuj z daleka ten genialny popis aktorski.', title_pt = 'Teatro em frente ao espelho 🎭', body_pt = 'Logo de manhã põe-se em frente ao espelho a ensaiar caras de choro, de riso e de espanto. Está a aprender a exprimir as emoções e a ver como o rosto muda! Observe com orgulho, à distância, esta interpretação genial.', title_sv = 'Teater framför spegeln 🎭', body_sv = 'Tidigt på morgonen ställer sig barnet framför spegeln och övar olika miner: gråt, skratt och förvåning. Barnet lär sig hur det ska uttrycka sina känslor och hur ansiktet tar form! Titta stolt på den geniala skådespelarprestationen på avstånd.', title_vi = 'Nhà hát trước gương 🎭', body_vi = 'Sáng sớm, bé đứng trước gương tập các biểu cảm khóc, cười, ngạc nhiên. Bé đang học cách thể hiện cảm xúc và khuôn mặt mình thay đổi ra sao! Hãy tự hào ngắm nhìn màn trình diễn tài năng này từ xa.', title_zh = '镜子前的剧场 🎭', body_zh = '一大早就站在镜子前，练习各种哭、笑、惊讶的表情。宝宝在学习如何表达情绪、脸会变成什么样！远远地骄傲欣赏这场天才般的表演吧。' WHERE id = '63b3f3e0-ceca-4b44-a2ea-ae171ce3413f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los brazos mágicos de papá 🫂', body_es = 'Tienes los brazos destrozados de cargarle todo el día, pero él vuelve a pedir brazos. Llama a papá. Volar en sus brazos cubrirá su necesidad de atención y dará a tus brazos y tu espalda el descanso que tanto necesitan.', title_fr = 'Les bras magiques de papa 🫂', body_fr = 'Vos bras n''en peuvent plus de l''avoir porté toute la journée, mais il réclame encore les bras. Appelez papa. Voler dans les bras de papa comblera son besoin d''attention et offrira à vos bras et à votre dos le repos dont ils ont tant besoin.', title_hi = 'पापा की जादुई बाहें 🫂', body_hi = 'दिनभर उठाते-उठाते आपकी बाहें टूट रही हैं, पर उसे फिर गोद चाहिए। पापा को आवाज़ दीजिए। पापा की बाहों में उड़ना बच्चे की ध्यान की ज़रूरत भी पूरी करेगा और आपकी बाहों और कमर को वह आराम भी देगा जिसकी उन्हें सख्त ज़रूरत है।', title_id = 'Lengan ajaib Ayah 🫂', body_id = 'Lengan Anda serasa copot karena menggendongnya seharian, tapi ia masih minta digendong. Panggil Ayah. Terbang di lengan Ayah akan memenuhi kebutuhan perhatiannya sekaligus memberi lengan dan punggung Anda istirahat yang sangat dibutuhkan.', title_ja = 'パパの魔法の腕 🫂', body_ja = '一日じゅう抱っこで腕がちぎれそうなのに、まだ抱っこをせがむ。パパを呼びましょう。パパの腕で空を飛べば、子どもは注目してもらえて満足し、あなたの腕と腰はとても必要な休けいがとれます。', title_ko = '아빠의 마법 같은 품 🫂', body_ko = '하루 종일 안고 다니느라 팔이 빠질 것 같은데 또 안아 달라고 하나요? 아빠를 불러 주세요. 아빠 품에서 날아오르면 아이의 관심 욕구도 채워지고, 엄마의 팔과 허리도 꼭 필요한 휴식을 얻어요.', title_nl = 'Papa''s magische armen 🫂', body_nl = 'Je armen vallen er bijna af van het hele dag dragen, maar hij wil weer opgetild worden. Roep papa. Vliegen in papa''s armen geeft je kind de aandacht die hij nodig heeft en geeft jouw armen en rug de rust die ze zo hard nodig hebben.', title_pl = 'Magiczne ramiona taty 🫂', body_pl = 'Ręce odpadają ci od noszenia go przez cały dzień, a on znów chce na ręce. Zawołaj tatę. Latanie w ramionach taty zaspokoi potrzebę uwagi dziecka, a twoim rękom i plecom da tak bardzo potrzebny odpoczynek.', title_pt = 'Os braços mágicos do pai 🫂', body_pt = 'Tem os braços a cair de o carregar o dia todo, mas ele continua a querer colo. Chame o pai. Voar nos braços do pai vai satisfazer a necessidade de atenção da criança e dar aos seus braços e às suas costas o descanso de que tanto precisam.', title_sv = 'Pappas magiska armar 🫂', body_sv = 'Armarna värker efter att ha burit hela dagen, men barnet vill bli upplyft igen. Ropa på pappa. Att flyga i pappas armar fyller barnets behov av uppmärksamhet och ger dina armar och din rygg den vila de så väl behöver.', title_vi = 'Vòng tay diệu kỳ của bố 🫂', body_vi = 'Tay mẹ đã rã rời vì bế bé cả ngày, nhưng bé vẫn đòi bế. Hãy gọi bố. Được "bay" trong vòng tay bố vừa đáp ứng nhu cầu được quan tâm của bé, vừa cho tay và lưng mẹ khoảng nghỉ rất cần thiết.', title_zh = '爸爸神奇的手臂 🫂', body_zh = '抱了一整天，你的胳膊都快断了，可宝宝还要抱抱。喊爸爸来吧。在爸爸的臂弯里“飞”，既能满足宝宝对关注的需要，也能让你的胳膊和腰得到急需的休息。' WHERE id = '14f4e22b-ebcd-4b44-af1e-7caf9bc49874' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lógica detrás de las preguntas 🧐', body_es = '«¿Por qué los peces no andan?». Desde primera hora su cerebro se despierta filosofando. Aunque sus preguntas te pongan contra las cuerdas, intenta explicárselo sin cansarte. Tu voz es para él la forma más segura y bonita de entender el universo.', title_fr = 'La logique derrière les questions 🧐', body_fr = '« Pourquoi les poissons ne marchent pas ? » Dès le matin, son cerveau se réveille en philosophe. Même si ses questions vous laissent sans voix, essayez d''expliquer sans vous lasser. Votre voix est pour lui la façon la plus sûre et la plus belle de comprendre l''univers.', title_hi = 'सवालों के पीछे का तर्क 🧐', body_hi = '‘मछलियाँ चलती क्यों नहीं?’ सुबह-सुबह उसका दिमाग दर्शन के साथ जागता है। उसके सवाल भले आपको उलझन में डाल दें, बिना थके समझाने की कोशिश कीजिए। आपकी आवाज़ उसके लिए दुनिया को समझने का सबसे भरोसेमंद, सबसे प्यारा रास्ता है।', title_id = 'Logika di balik pertanyaan 🧐', body_id = '''Kenapa ikan tidak berjalan?'' Pagi-pagi otaknya sudah bangun dengan filsafat. Meski pertanyaannya membuat Anda buntu, cobalah menjelaskan tanpa lelah. Suara Anda adalah cara paling aman dan indah baginya untuk memahami alam semesta.', title_ja = '「なんで？」の理屈 🧐', body_ja = '「なんでお魚は歩かないの？」朝早くから、頭は哲学で目覚めています。質問に答えにつまっても、根気よく説明してあげて。あなたの声は、この子にとって宇宙を知るためのいちばん安心で、いちばんすてきな道です。', title_ko = '질문 속의 논리 🧐', body_ko = '''물고기는 왜 안 걸어?'' 아침부터 머리가 철학으로 깨어나나요? 질문에 말문이 막혀도 지치지 말고 설명해 주세요. 엄마의 목소리는 아이가 우주를 이해하는 가장 안전하고 아름다운 길이에요.', title_nl = 'Logica in vragen 🧐', body_nl = '''Waarom lopen vissen niet?'' Al vroeg in de ochtend wordt zijn brein wakker met filosofie. Ook al brengen zijn vragen je in verlegenheid, probeer onvermoeibaar uit te leggen. Jouw stem is voor hem de veiligste en mooiste manier om het universum te begrijpen.', title_pl = 'Logika pod znakiem zapytania 🧐', body_pl = '„Dlaczego ryby nie chodzą?” Od samego rana jego mózg budzi się z filozofią. Nawet jeśli jego pytania stawiają cię w kropce, niestrudzenie próbuj tłumaczyć. Twój głos to dla niego najbezpieczniejszy i najpiękniejszy sposób, by zrozumieć wszechświat.', title_pt = 'A lógica por trás das perguntas 🧐', body_pt = '"Porque é que os peixes não andam?" Logo de manhã cedo, o cérebro dele acorda com filosofia. Mesmo que as perguntas a deixem sem saída, tente explicar sem se cansar. A sua voz é para ele a forma mais segura e bonita de compreender o universo.', title_sv = 'Logiken bakom frågan 🧐', body_sv = '”Varför går inte fiskarna?” Tidigt på morgonen vaknar barnets hjärna med filosofi. Även om frågorna sätter dig i knipa, försök att förklara utan att tröttna. Din röst är för barnet det tryggaste och vackraste sättet att förstå universum.', title_vi = 'Logic ẩn sau câu hỏi 🧐', body_vi = '"Sao cá không đi bộ?" Sáng sớm, não bé đã thức dậy cùng triết học. Dù những câu hỏi của bé khiến mẹ bí, hãy cố gắng giải thích không mệt mỏi. Giọng nói của mẹ là cách an toàn và đẹp đẽ nhất để bé hiểu về vũ trụ.', title_zh = '问题背后的逻辑 🧐', body_zh = '“鱼为什么不走路？”一大早，宝宝的大脑就伴着哲学醒来了。就算问题让你无言以对，也请不厌其烦地试着解释。你的声音，是宝宝理解宇宙最安全、最美好的方式。' WHERE id = '8e97dc44-4076-463e-90aa-e9a38f43a406' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos de la lista de la compra 🛒', body_es = 'Estás delante de la caja del súper y te das cuenta de que otra vez has olvidado lo más importante. Tu cerebro ya está dividido en mil partes. A partir de ahora, acostúmbrate a apuntarlo en la Lista de la compra de la app en el mismo segundo en que surja la necesidad. Ayúdate.', title_fr = 'Le chaos de la liste de courses 🛒', body_fr = 'Vous êtes à la caisse du supermarché et vous réalisez que vous avez encore oublié le plus important. Votre cerveau est déjà éparpillé dans mille directions. Désormais, prenez l''habitude de noter chaque besoin dans la Liste de courses de l''application à la seconde où il apparaît, et aidez-vous.', title_hi = 'शॉपिंग लिस्ट की अफ़रा-तफ़री 🛒', body_hi = 'बाज़ार में काउंटर पर खड़ी हैं और ध्यान आया कि सबसे ज़रूरी चीज़ फिर भूल गईं। आपका दिमाग वैसे ही हज़ार जगह बँटा है। अब से जिस पल ज़रूरत हो, उसी पल ऐप की शॉपिंग लिस्ट में लिखने की आदत डालिए, खुद की मदद कीजिए।', title_id = 'Kacau tanpa Daftar Belanja 🛒', body_id = 'Anda sudah di depan kasir supermarket dan sadar lagi-lagi lupa barang paling penting. Otak Anda memang sudah terbagi ke seribu arah. Mulai sekarang, biasakan mencatat kebutuhan di Daftar Belanja aplikasi begitu teringat, bantulah diri Anda sendiri.', title_ja = '買い物リストのカオス 🛒', body_ja = 'スーパーのレジの前で、いちばん大事なものをまた忘れたことに気づいた。ただでさえ頭は千のことでいっぱいですものね。これからは、必要になったその瞬間にアプリの「買い物リスト」に書く習慣をつけて、自分を助けてあげましょう。', title_ko = '쇼핑 목록 대혼란 🛒', body_ko = '마트 계산대 앞에서 가장 중요한 걸 또 잊었다는 걸 깨달았나요? 머릿속은 이미 천 갈래로 나뉘어 있죠. 이제부터 필요한 게 생기는 순간 앱의 쇼핑 목록에 적는 습관을 들여 나를 도와주세요.', title_nl = 'Chaos rond het boodschappenlijstje 🛒', body_nl = 'Je staat bij de kassa en merkt dat je het belangrijkste weer bent vergeten. Je brein is toch al in duizend stukjes verdeeld. Maak er een gewoonte van om iets meteen op het Boodschappenlijstje in de app te zetten zodra je het nodig hebt, en help jezelf.', title_pl = 'Chaos z listą zakupów 🛒', body_pl = 'Stoisz przy kasie w sklepie i orientujesz się, że znowu zapomniałaś o najważniejszym. Twój mózg i tak dzieli się na tysiąc spraw. Odtąd wpisuj potrzebną rzecz na Listę zakupów w aplikacji w tej samej sekundzie, w której o niej pomyślisz, i ułatw sobie życie.', title_pt = 'O caos da lista de compras 🛒', body_pt = 'Está na caixa do supermercado e percebe que voltou a esquecer-se da coisa mais importante. O seu cérebro já anda dividido por mil sítios. A partir de agora, habitue-se a escrever cada coisa na Lista de Compras da app no segundo em que faz falta: ajude-se a si própria.', title_sv = 'Kaos kring inköpslistan 🛒', body_sv = 'Du står vid kassan i butiken och märker att du återigen har glömt det viktigaste. Din hjärna är ändå uppdelad på tusen ställen. Hjälp dig själv: gör det till en vana att skriva upp saker i appens Inköpslista samma sekund som behovet uppstår.', title_vi = 'Hỗn loạn danh sách mua sắm 🛒', body_vi = 'Đứng trước quầy thanh toán ở siêu thị, mẹ nhận ra lại quên món quan trọng nhất. Đầu óc mẹ vốn đã chia ra nghìn việc. Từ giờ, hãy tập thói quen ghi ngay vào Danh sách mua sắm trong ứng dụng vào giây phút cần đến, để tự giúp chính mình.', title_zh = '购物清单大混乱 🛒', body_zh = '在超市收银台前，你发现又忘了最重要的那样东西。你的脑子本来就被分成了上千份。从现在起，养成一需要就马上写进应用里购物清单的习惯，帮帮自己吧。' WHERE id = 'd78d5945-d2b9-4d6b-be69-c36a9e85a337' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El orgullo de vestirse al revés 🧦', body_es = 'El talón del calcetín le queda encima del pie, pero camina orgulloso porque se lo ha puesto él. No intervengas lo más mínimo. Esa sensación de «lo he conseguido» es una base psicológica un millón de veces más valiosa que ir bien vestido o estético.', title_fr = 'La fierté de s''habiller à l''envers 🧦', body_fr = 'Le talon de sa chaussette est sur le dessus du pied, mais il marche fièrement parce qu''il s''est habillé tout seul. N''intervenez surtout pas. Ce sentiment du « j''ai réussi » est une base psychologique mille fois plus précieuse que d''être habillé joliment ou correctement.', title_hi = 'उलटा पहनने का गर्व 🧦', body_hi = 'मोज़े की एड़ी पैर के ऊपर है, पर खुद पहना है इसलिए गर्व से घूम रहा है। ज़रा भी दखल मत दीजिए। उसका यह ‘मैं कर सकता हूँ’ वाला एहसास सुंदर या सही पहनने से लाखों गुना कीमती मनोवैज्ञानिक नींव है।', title_id = 'Bangga memakai terbalik 🧦', body_id = 'Tumit kaus kakinya ada di punggung kaki, tapi ia berjalan dengan bangga karena memakainya sendiri. Jangan ikut campur sedikit pun. Rasa ''aku bisa'' ini adalah fondasi psikologis yang jutaan kali lebih berharga daripada berpakaian rapi atau benar.', title_ja = '裏返しで着た誇り 🧦', body_ja = '靴下のかかとが足の甲にきているのに、自分ではいたから得意げに歩いています。少しも手を出さないで。「自分でできた」という気持ちは、見た目や正しい着方より何百万倍も大切な心の土台です。', title_ko = '뒤집어 입은 자부심 🧦', body_ko = '양말 뒤꿈치가 발등에 가 있는데도 자기가 신었다고 당당하게 걷나요? 조금도 끼어들지 마세요. ''내가 해냈어''라는 느낌은 예쁘게, 바르게 입는 것보다 백만 배 소중한 심리적 바탕이에요.', title_nl = 'Trots op binnenstebuiten 🧦', body_nl = 'De hiel van zijn sok zit bovenop zijn voet, maar hij loopt trots rond omdat hij hem zelf heeft aangetrokken. Grijp niet in, echt helemaal niet. Dat ''ik kan het zelf''-gevoel is een psychologische basis die een miljoen keer meer waard is dan er mooi of correct gekleed uitzien.', title_pl = 'Duma z ubrania na lewą stronę 🧦', body_pl = 'Pięta skarpetki jest na wierzchu stopy, ale chodzi dumny, bo ubrał się sam. Nie ingeruj ani trochę. To jego poczucie „sam dałem radę” jest psychologicznym fundamentem milion razy cenniejszym niż estetyczny czy poprawny strój.', title_pt = 'O orgulho de vestir ao contrário 🧦', body_pt = 'O calcanhar da meia está em cima do pé, mas ele anda orgulhoso porque se vestiu sozinho. Não intervenha nem um bocadinho. Esta sensação de "eu consegui" é uma base psicológica um milhão de vezes mais valiosa do que vestir-se de forma bonita ou correta.', title_sv = 'Stolt med ut och in 🧦', body_sv = 'Hälen på strumpan sitter ovanpå foten, men barnet går stolt omkring eftersom det tagit på den själv. Lägg dig inte i det minsta. Känslan av ”jag klarade det” är en psykologisk grund som är en miljon gånger värdefullare än att vara snyggt eller rätt klädd.', title_vi = 'Tự hào vì mặc ngược 🧦', body_vi = 'Gót tất nằm trên mu bàn chân, nhưng vì tự mặc nên bé đi lại đầy kiêu hãnh. Đừng can thiệp dù chỉ một chút. Cảm giác "con làm được" của bé là nền tảng tâm lý quý giá hơn gấp triệu lần so với việc mặc đẹp hay mặc đúng.', title_zh = '穿反了的骄傲 🧦', body_zh = '袜子的后跟跑到了脚背上，可因为是自己穿的，宝宝走得可骄傲了。一点都别插手。宝宝这份“我做到了”的感觉，作为心理基础，比好看或穿对要宝贵一百万倍。' WHERE id = '62d4901b-19ff-4b33-a0e0-89d727535d96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historias susurradas 🌙', body_es = 'Hoy has hablado muy alto y tienes los pulmones cansados. Apaga las luces, túmbate a su lado y cuéntale lo que ha pasado durante el día solo susurrándole al oído. El susurro concentra su atención y prepara su cerebro de forma hipnótica para un sueño profundo.', title_fr = 'Histoires chuchotées 🌙', body_fr = 'Vous avez beaucoup élevé la voix aujourd''hui, vos poumons sont fatigués. Éteignez les lumières, allongez-vous près de lui et racontez-lui simplement sa journée en chuchotant à l''oreille. Le chuchotement concentre son attention et prépare son cerveau de façon presque hypnotique à un sommeil profond.', title_hi = 'फुसफुसाती कहानियाँ 🌙', body_hi = 'आज आपकी आवाज़ बहुत ऊँची हुई, फेफड़े थक गए। लाइटें बंद कीजिए, उसके पास लेटिए और दिनभर की बातें बस फुसफुसाकर उसके कान में कहिए। फुसफुसाहट उसका ध्यान केंद्रित करती है और उसके दिमाग को सम्मोहन की तरह गहरी नींद के लिए तैयार करती है।', title_id = 'Cerita berbisik 🌙', body_id = 'Hari ini Anda sudah banyak bersuara, paru-paru Anda lelah. Matikan lampu, berbaringlah di sampingnya, dan ceritakan kejadian hari ini ke telinganya cukup dengan berbisik. Bisikan memusatkan perhatiannya dan menyiapkan otaknya untuk tidur nyenyak seperti terhipnotis.', title_ja = 'ささやきのおはなし 🌙', body_ja = '今日はたくさん声を出して、肺も疲れていますね。明かりを消してそばに横になり、今日あったことを耳もとでささやくだけで話してあげて。ささやき声は注意を集め、脳を催眠のように深い眠りへと導きます。', title_ko = '속삭이는 이야기 🌙', body_ko = '오늘 목소리를 많이 써서 숨이 차나요? 불을 끄고 옆에 누워 오늘 있었던 일을 귓가에 속삭이기만 하세요. 속삭임은 아이의 집중을 모으고 뇌를 최면처럼 깊은 잠으로 이끌어요.', title_nl = 'Fluisterverhalen 🌙', body_nl = 'Je hebt je stem vandaag veel gebruikt en je longen zijn moe. Doe de lichten uit, ga naast hem liggen en vertel hem fluisterend in zijn oor wat er vandaag is gebeurd. Fluisteren richt zijn aandacht en maakt zijn brein op een hypnotiserende manier klaar voor een diepe slaap.', title_pl = 'Historie szeptem 🌙', body_pl = 'Dziś dużo używałaś głosu, płuca są zmęczone. Zgaś światła, połóż się obok i po prostu wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia. Szept skupia jego uwagę i niemal hipnotycznie przygotowuje mózg do głębokiego snu.', title_pt = 'Histórias em sussurro 🌙', body_pt = 'Hoje já levantou muito a voz e os pulmões estão cansados. Apague as luzes, deite-se ao lado dele e conte-lhe ao ouvido, só em sussurro, o que aconteceu durante o dia. O sussurro concentra a atenção dele e prepara o cérebro de forma hipnótica para um sono profundo.', title_sv = 'Viskade berättelser 🌙', body_sv = 'Du har höjt rösten mycket i dag och lungorna är trötta. Släck ljuset, lägg dig bredvid barnet och viska bara om det som hänt under dagen. Viskningar fokuserar barnets uppmärksamhet och förbereder hjärnan nästan hypnotiskt för djup sömn.', title_vi = 'Những câu chuyện thì thầm 🌙', body_vi = 'Hôm nay mẹ đã nói rất nhiều, phổi cũng mệt rồi. Hãy tắt đèn, nằm cạnh bé và chỉ thì thầm vào tai bé về những gì đã xảy ra trong ngày. Lời thì thầm giúp bé tập trung và đưa não bộ vào giấc ngủ sâu như bị thôi miên.', title_zh = '悄悄话故事 🌙', body_zh = '今天你说了太多话，嗓子都累了。关上灯，躺在宝宝身边，只用悄悄话在宝宝耳边讲讲今天发生的事。悄悄话能让宝宝集中注意力，像催眠一样让大脑准备好进入深度睡眠。' WHERE id = '79c5f477-357d-4a5a-a226-aa71c2153c6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto en la cocina 🥄', body_es = 'Saca las ollas y las cucharas de madera y da un concierto ruidoso en medio de la cocina. Aunque te duela la cabeza, así se desarrollan su sentido del ritmo y su motricidad. Dile «¡bravo!» y espera que el concierto acabe pronto.', title_fr = 'Concert en cuisine 🥄', body_fr = 'Il sort les casseroles et les cuillères en bois et donne un concert bruyant au milieu de la cuisine. Même si vous avez mal à la tête, c''est le développement de son sens du rythme et de sa motricité. Dites-lui bravo et espérez que le spectacle se termine vite.', title_hi = 'रसोई में कॉन्सर्ट 🥄', body_hi = 'पतीले और लकड़ी के चम्मच निकालकर रसोई के बीच शोर भरा कॉन्सर्ट दे रहा है। सिर भले दुखे, यह उसकी लय की समझ और मोटर स्किल्स का विकास है। उसे एक ‘शाबाश’ कहिए और उम्मीद कीजिए कि यह जल्दी खत्म हो।', title_id = 'Konser di dapur 🥄', body_id = 'Ia mengeluarkan panci dan sendok kayu lalu menggelar konser berisik di tengah dapur. Meski kepala Anda pusing, ini adalah perkembangan rasa irama dan motoriknya. Ucapkan ''bravo'' dan berharaplah pertunjukannya cepat selesai.', title_ja = 'キッチンでコンサート 🥄', body_ja = '鍋と木のスプーンを取り出して、キッチンのまんなかでにぎやかなコンサートを開いています。頭が痛くても、これはリズム感と運動能力の発達です。「ブラボー」と声をかけて、早く終わることを祈りましょう。', title_ko = '부엌 콘서트 🥄', body_ko = '냄비와 나무 숟가락을 꺼내 부엌 한가운데서 시끄러운 콘서트를 여나요? 머리가 아파도 리듬감과 운동 능력이 자라는 중이에요. 브라보를 외쳐 주고 공연이 빨리 끝나길 바라 보세요.', title_nl = 'Concert in de keuken 🥄', body_nl = 'Hij haalt pannen en houten lepels tevoorschijn en geeft midden in de keuken een lawaaiig concert. Ook al bonkt je hoofd, zo ontwikkelt hij zijn ritmegevoel en motoriek. Zeg ''bravo'' en hoop dat het optreden snel voorbij is.', title_pl = 'Koncert w kuchni 🥄', body_pl = 'Wyciągnął garnki i drewniane łyżki i daje głośny koncert na środku kuchni. Nawet jeśli boli cię głowa, to rozwój jego poczucia rytmu i motoryki. Powiedz mu „brawo” i miej nadzieję, że występ szybko się skończy.', title_pt = 'Concerto na cozinha 🥄', body_pt = 'Tira as panelas e as colheres de pau e dá um concerto barulhento no meio da cozinha. Mesmo com dor de cabeça, isto é o desenvolvimento do sentido de ritmo e da motricidade dele. Diga-lhe "bravo" e espere que o espetáculo acabe depressa.', title_sv = 'Konsert i köket 🥄', body_sv = 'Barnet plockar fram kastruller och träslevar och ger en bullrig konsert mitt i köket. Även om du får huvudvärk är det utvecklingen av rytmkänsla och motorik. Säg bravo och hoppas att konserten tar slut snart.', title_vi = 'Buổi hòa nhạc trong bếp 🥄', body_vi = 'Bé lôi nồi niêu và thìa gỗ ra, mở một buổi hòa nhạc ồn ào giữa bếp. Dù mẹ đau đầu, đây là sự phát triển cảm thụ nhịp điệu và kỹ năng vận động của bé. Hãy nói "Hoan hô!" và hy vọng buổi biểu diễn sớm kết thúc.', title_zh = '厨房音乐会 🥄', body_zh = '把锅和木勺都拿出来，在厨房中间开了一场吵闹的音乐会。虽然你头都疼了，但这是宝宝节奏感和动作能力在发展。给宝宝说声“好棒”，然后期待这场演出早点结束吧。' WHERE id = 'b3b80c54-4891-4e55-9e0b-d88a4a322bdd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El caos de casa por fin se ha acabado y se ha dormido. ¡No corras a fregar los platos! Abre el Medidor de sonido y, mirando el silencio absoluto de la habitación (0-10 decibelios), siente durante 15 minutos cómo descansa tu cerebro.', body_fr = 'Le chaos de la maison est enfin terminé et il s''est endormi. Ne courez pas faire la vaisselle ! Ouvrez le Sonomètre et, en regardant le silence absolu de la pièce (0 à 10 décibels), sentez pendant 15 minutes votre cerveau se reposer.', body_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई और वह सो गया। बर्तन धोने मत दौड़िए! साउंड मीटर खोलिए, कमरे की पूरी खामोशी (0-10 डेसिबल) देखते हुए 15 मिनट में महसूस कीजिए कि आपका दिमाग कैसे आराम पाता है।', body_id = 'Kekacauan di rumah akhirnya berakhir dan ia tertidur. Jangan buru-buru mencuci piring! Buka Pengukur Suara, lihat keheningan total kamar (0-10 desibel), dan selama 15 menit rasakan secara visual bagaimana otak Anda beristirahat.', body_ja = '家の中のカオスがようやく終わって、眠りにつきました。洗いものに走らないで！「サウンドメーター」を開いて、部屋の完全な静けさ（0〜10デシベル）を眺めながら、15分で脳がどれほど休まるかを目で感じましょう。', body_ko = '집 안의 혼돈이 드디어 끝나고 아이가 잠들었어요. 설거지하러 달려가지 마세요! 소음 측정기를 열고 방의 완전한 고요(0~10데시벨)를 보며 15분 동안 머리가 쉬는 걸 눈으로 느껴 보세요.', body_nl = 'De chaos in huis is eindelijk voorbij en hij slaapt. Ren niet naar de afwas! Open de Geluidsmeter, kijk naar die absolute stilte (0-10 decibel) in de kamer en voel 15 minuten lang hoe je brein tot rust komt.', body_pl = 'Domowy chaos wreszcie się skończył, a on zasnął. Nie biegnij zmywać naczyń! Otwórz Miernik dźwięku i patrząc na absolutną ciszę w pokoju (0-10 decybeli), poczuj przez 15 minut, jak twój mózg odpoczywa.', body_pt = 'O caos da casa finalmente acabou e ele adormeceu. Não corra a lavar a loiça! Abra o Medidor de Som e, a olhar para o silêncio absoluto do quarto (0-10 decibéis), sinta visualmente, durante 15 minutos, como o seu cérebro descansa.', body_sv = 'Kaoset hemma är äntligen över och barnet har somnat. Spring inte iväg och diska! Öppna Ljudmätaren och titta på den totala tystnaden i rummet (0-10 decibel), så känner du visuellt hur hjärnan vilar under 15 minuter.', body_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc và bé đã ngủ. Đừng vội đi rửa bát! Hãy mở Đo âm thanh, nhìn sự im lặng tuyệt đối trong phòng (0-10 decibel) và cảm nhận não bộ mình đang được nghỉ ngơi trong 15 phút.', body_zh = '家里的混乱终于结束，宝宝睡着了。别急着去洗碗！打开分贝仪，看着房间里那份绝对的安静（0-10分贝），在15分钟里直观地感受大脑是怎样慢慢休息下来的。' WHERE id = '26929739-4514-47f4-b2ff-3f79743e2a52' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia del plátano pelado 🍌', body_es = '¿A las 8 de la mañana ha estallado una revolución porque pelaste el plátano en su lugar? La regla de oro de esta edad: él tiene que decidirlo todo. No puedes volver a pegar la piel, así que dirige enseguida su atención a otro absurdo y apaga la crisis.', title_fr = 'Le drame de la banane épluchée 🍌', body_fr = 'Une révolution a éclaté à 8 h du matin parce que vous avez épluché la banane à sa place ? La règle d''or de cet âge : c''est lui qui doit tout décider. Vous ne pouvez pas recoller la banane, alors détournez aussitôt son attention vers une autre absurdité pour éteindre la crise.', title_hi = 'केला छीलने की त्रासदी 🍌', body_hi = 'केला उसकी जगह आपने छील दिया, इसलिए सुबह 8 बजे कमरे में क्रांति छिड़ गई? इस उम्र का सुनहरा नियम: हर चीज़ का फ़ैसला उसे ही करना है। केला वापस तो चिपका नहीं सकतीं, तुरंत उसका ध्यान किसी और बेतुकी चीज़ पर ले जाकर संकट शांत कीजिए।', title_id = 'Tragedi mengupas pisang 🍌', body_id = 'Revolusi meletus di kamar jam 8 pagi karena Anda yang mengupas pisangnya? Aturan emas usia ini: semuanya harus ia yang putuskan. Pisang tidak bisa ditempel lagi, jadi segera alihkan perhatiannya ke hal absurd lain dan padamkan krisisnya.', title_ja = 'バナナの皮むき大事件 🍌', body_ja = '本人の代わりにあなたがバナナをむいたせいで、朝8時に部屋で革命が起きた？この年ごろの黄金ルール：何でも自分で決めたいんです。バナナはもとに戻せないので、すぐに別のおかしなことに気をそらして、かんしゃくをしずめましょう。', title_ko = '바나나 껍질 비극 🍌', body_ko = '엄마가 바나나 껍질을 대신 벗겼다고 아침 8시에 방에서 혁명이 일어났나요? 이 나이의 황금률: 모든 건 아이가 정해야 해요. 바나나를 다시 붙일 순 없으니, 바로 다른 엉뚱한 것으로 관심을 돌려 위기를 꺼 주세요.', title_nl = 'Het bananenpeldrama 🍌', body_nl = 'Breekt er om 8 uur ''s ochtends een revolutie uit omdat jij zijn banaan hebt gepeld? De gouden regel van deze leeftijd: hij moet over alles beslissen. Je kunt de schil er niet weer op plakken, dus leid zijn aandacht meteen af met iets anders absurds en blus de crisis.', title_pl = 'Tragedia obranego banana 🍌', body_pl = 'O 8 rano w pokoju wybuchła rewolucja, bo to ty obrałaś mu banana? Złota zasada tego wieku: o wszystkim musi decydować on. Banana z powrotem nie skleisz, więc od razu skieruj jego uwagę na inny absurd i ugaś kryzys.', title_pt = 'A tragédia da banana descascada 🍌', body_pt = 'Houve uma revolução no quarto às 8 da manhã porque foi a mãe a descascar a banana em vez dele? A regra de ouro desta idade: é ele que tem de decidir tudo. Não consegue voltar a colar a banana, por isso desvie logo a atenção dele para outro absurdo e apague a crise.', title_sv = 'Bananskalningstragedin 🍌', body_sv = 'Bröt det ut revolution klockan 8 på morgonen för att du skalade bananen åt barnet? Den här ålderns gyllene regel: barnet ska bestämma allt. Du kan inte klistra tillbaka bananen, så led genast över uppmärksamheten till något annat absurt och släck krisen.', title_vi = 'Bi kịch bóc chuối 🍌', body_vi = 'Lúc 8 giờ sáng, cả phòng nổ ra một cuộc "cách mạng" chỉ vì mẹ bóc chuối thay bé? Quy tắc vàng của tuổi này: mọi thứ phải do bé quyết định. Mẹ không thể dán vỏ chuối lại, vậy hãy lập tức chuyển sự chú ý của bé sang một điều ngộ nghĩnh khác để dập tắt khủng hoảng.', title_zh = '剥香蕉的悲剧 🍌', body_zh = '就因为你替宝宝剥了香蕉，早上8点房间里就爆发了一场“革命”？这个年龄的黄金法则：什么都得由宝宝来决定。香蕉皮你是粘不回去的，马上把宝宝的注意力转到另一件荒诞的事上，化解这场危机。' WHERE id = '691e79df-4ad4-4dc1-80d2-9bb367dfc70e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Síndrome del oído selectivo 🙉', body_es = '¿Cuando le dices «recoge tus juguetes» no oye nada, pero desde la otra habitación oye al instante el crujido de un envoltorio de chocolate? No tiene ningún problema de oído, solo oye lo que le interesa. Prueba a decir las normas en susurros: despertará su curiosidad.', title_fr = 'Le syndrome de l''écoute sélective 🙉', body_fr = 'Il n''entend pas quand vous lui dites de ranger ses jouets, mais il perçoit aussitôt le froissement d''un papier de chocolat depuis la pièce d''à côté ? Il n''a aucun problème d''audition, il entend juste ce qui l''arrange. Essayez de dire les règles en chuchotant, sa curiosité s''éveillera.', title_hi = 'चुनिंदा सुनने का सिंड्रोम 🙉', body_hi = '‘खिलौने समेटो’ कहने पर सुनता नहीं, पर बगल के कमरे से चॉकलेट के रैपर की सरसराहट तुरंत सुन लेता है? सुनने में कोई दिक्कत नहीं, बस वही सुनता है जो उसके मतलब का है। नियम फुसफुसाकर कहकर देखिए, उत्सुकता जाग जाएगी।', title_id = 'Sindrom pendengaran selektif 🙉', body_id = 'Saat disuruh membereskan mainan ia tidak mendengar, tapi bunyi kresek bungkus cokelat dari kamar sebelah langsung terdengar? Pendengarannya baik-baik saja, ia hanya mendengar yang menguntungkannya. Coba sampaikan aturan sambil berbisik, rasa ingin tahunya akan bangkit.', title_ja = '都合のいい耳症候群 🙉', body_ja = '「おもちゃを片づけて」は聞こえないのに、となりの部屋のチョコの包み紙のカサカサにはすぐ気づく？耳には問題ありません。都合のいいことだけ聞こえているんです。ルールをささやき声で伝えてみて。興味がわきますよ。', title_ko = '선택적 듣기 증후군 🙉', body_ko = '''장난감 정리해''는 못 듣는데 옆방의 초콜릿 포장지 바스락 소리는 바로 듣나요? 청력엔 문제가 없어요, 듣고 싶은 것만 듣는 거죠. 규칙을 속삭이듯 말해 보세요, 호기심이 깨어날 거예요.', title_nl = 'Selectief-gehoorsyndroom 🙉', body_nl = 'Hoort hij niets als je zegt ''ruim je speelgoed op'', maar hoort hij het geritsel van een chocoladewikkel in de kamer ernaast meteen? Er is niets mis met zijn gehoor, hij hoort gewoon wat hem uitkomt. Probeer de regels eens te fluisteren, dan wordt hij nieuwsgierig.', title_pl = 'Syndrom wybiórczego słuchu 🙉', body_pl = 'Nie słyszy, gdy mówisz „posprzątaj zabawki”, ale szelest papierka po czekoladzie z sąsiedniego pokoju słyszy od razu? Ze słuchem wszystko w porządku, po prostu słyszy to, co mu pasuje. Spróbuj mówić zasady szeptem, ciekawość się obudzi.', title_pt = 'Síndrome da audição seletiva 🙉', body_pt = 'Quando lhe diz "arruma os brinquedos" não ouve, mas ouve logo o papel de um chocolate a estalar na outra divisão? Não tem problemas de audição, só ouve o que lhe convém. Experimente dizer as regras a sussurrar: a curiosidade desperta.', title_sv = 'Selektiv hörsel 🙉', body_sv = 'Hör barnet inte när du säger ”Plocka upp leksakerna”, men hör direkt prasslet från ett chokladpapper i rummet bredvid? Hörseln är det inget fel på, barnet hör bara det som passar. Testa att viska reglerna, så väcks nyfikenheten.', title_vi = 'Hội chứng "nghe có chọn lọc" 🙉', body_vi = 'Khi mẹ bảo "Dọn đồ chơi đi", bé không nghe thấy, nhưng tiếng sột soạt của giấy gói sô-cô-la từ phòng bên thì bé nghe ngay? Tai bé không có vấn đề gì, bé chỉ nghe những gì có lợi cho mình. Hãy thử thì thầm nói các quy tắc, bé sẽ tò mò ngay.', title_zh = '选择性听力综合征 🙉', body_zh = '叫宝宝收玩具时听不见，隔壁房间巧克力包装纸的沙沙声却一下就听到了？宝宝的听力没问题，只是只听自己想听的。试试用悄悄话说规则，好奇心就会被唤醒。' WHERE id = 'cfe53a47-5049-4180-8a26-333de41ec18f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tesoros que salen del bolsillo 🪨', body_es = '¿Al lavar su pantalón han salido del bolsillo 2 piedras, una hoja seca y un palito a medias? Lo que para ti es basura es para él una colección valiosa con la que descubre el universo. En lugar de tirarlas, guárdalas en una cajita del tesoro.', title_fr = 'Les trésors des poches 🪨', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche 2 cailloux, une feuille séchée et un bout de brindille ? Ces objets qui sont des déchets pour vous forment sa précieuse collection d''explorateur de l''univers. Au lieu de les jeter, rangez-les dans une petite boîte à trésors.', title_hi = 'जेब से निकले खज़ाने 🪨', body_hi = 'पैंट धोते समय उसकी जेब से 2 पत्थर, एक सूखा पत्ता और आधी टहनी निकली? आपके लिए जो कचरा है, वह उसके लिए दुनिया की खोज का कीमती संग्रह है। इन्हें फेंकने के बजाय एक छोटे खज़ाने के डिब्बे में रखिए।', title_id = 'Harta karun dari saku 🪨', body_id = 'Saat mencuci celananya, dari saku keluar 2 batu, sehelai daun kering, dan ranting patah? Benda yang bagi Anda sampah ini adalah koleksi berharganya saat menjelajahi alam semesta. Daripada membuangnya, kumpulkan di kotak harta karun kecil.', title_ja = 'ポケットから出てきた宝物 🪨', body_ja = 'ズボンを洗おうとしたら、ポケットから石が2つ、枯れ葉が1枚、折れた小枝が出てきた？あなたにはゴミでも、この子にとっては宇宙を発見した大切なコレクションです。捨てる代わりに、小さな宝箱に集めてあげましょう。', title_ko = '주머니 속 보물 🪨', body_ko = '바지를 빨려는데 주머니에서 돌 2개, 마른 나뭇잎, 부러진 나뭇가지가 나왔나요? 엄마에겐 쓰레기지만 아이에겐 우주를 탐험하며 모은 귀한 수집품이에요. 버리는 대신 작은 보물 상자에 모아 주세요.', title_nl = 'Schatten uit de broekzak 🪨', body_nl = 'Kwamen er bij het wassen van zijn broek 2 steentjes, een droog blaadje en een half takje uit zijn zak? Wat voor jou afval is, is voor hem een waardevolle verzameling waarmee hij het universum ontdekt. Gooi ze niet weg, maar bewaar ze in een kleine schatkist.', title_pl = 'Skarby z kieszeni 🪨', body_pl = 'Podczas prania spodni wyjęłaś z kieszeni 2 kamyki, suchy liść i złamany patyczek? Te rzeczy, które dla ciebie są śmieciami, to jego cenna kolekcja z odkrywania wszechświata. Zamiast je wyrzucać, włóż je do małego pudełka na skarby.', title_pt = 'Tesouros que saem dos bolsos 🪨', body_pt = 'Ao lavar as calças, saíram do bolso 2 pedras, uma folha seca e um pauzinho partido? Estes objetos, que para si são lixo, são a coleção valiosa com que ele descobre o universo. Em vez de os deitar fora, guarde-os numa pequena caixa do tesouro.', title_sv = 'Skatter ur fickorna 🪨', body_sv = 'När du tvättade byxorna hittade du 2 stenar, ett torkat löv och en halv pinne i fickan? Det som för dig är skräp är barnets värdefulla samling från upptäckten av universum. Istället för att slänga sakerna, lägg dem i en liten skattlåda.', title_vi = 'Kho báu trong túi quần 🪨', body_vi = 'Khi giặt quần cho bé, mẹ lôi ra 2 viên sỏi, một chiếc lá khô và một que củi gãy? Những thứ với mẹ là rác ấy lại là bộ sưu tập quý giá khi bé khám phá vũ trụ. Thay vì vứt đi, hãy gom chúng vào một hộp kho báu nhỏ.', title_zh = '口袋里掏出的宝藏 🪨', body_zh = '洗裤子时，从口袋里掏出2块石头、一片干树叶和半截小木棍？在你看来是垃圾的东西，却是宝宝探索宇宙的珍贵收藏。别扔掉，把它们收进一个小小的宝藏盒里吧。' WHERE id = '46cb3019-8e96-4dd4-93b2-6c2a4bab0f53' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Brócoli camuflado 🥦', body_es = '¿Aparta las verduras verdes de la sopa con precisión de cirujano? La selectividad con la comida está en su punto máximo. Es hora de descubrir en el Plan de alimentación recetas especiales y astutas que hagan invisibles las verduras y las conviertan en albóndigas de colores.', title_fr = 'Brocoli camouflé 🥦', body_fr = 'Il met de côté les légumes verts de la soupe avec une précision de chirurgien ? La sélectivité alimentaire est à son maximum. C''est le moment de découvrir dans le Plan de nutrition des recettes astucieuses qui rendent les légumes invisibles en les transformant en boulettes colorées.', title_hi = 'ब्रोकली का छलावा 🥦', body_hi = 'सूप की हरी सब्ज़ियाँ सर्जन जैसी सटीकता से अलग करता है? खाने में नखरे चरम पर हैं। फ़ीडिंग प्लान में सब्ज़ियों को अदृश्य बनाने वाली, उन्हें रंगीन कटलेट में बदलने वाली खास और चालाक रेसिपी खोजने का समय है।', title_id = 'Kamuflase brokoli 🥦', body_id = 'Ia menyisihkan sayur hijau di supnya dengan ketelitian seorang ahli bedah? Sikap pilih-pilih makanan sedang di puncaknya. Saatnya menemukan resep istimewa dan cerdik di Rencana Nutrisi yang membuat sayur tak terlihat dan menjadi perkedel berwarna-warni.', title_ja = 'ブロッコリーのカモフラージュ 🥦', body_ja = 'スープの緑の野菜を、外科医のような正確さでよけている？好き嫌いがピークです。「栄養管理ツール」で、野菜を見えなくしたり、カラフルなハンバーグに変えたりする、特別な工夫レシピを見つけるときです。', title_ko = '브로콜리 위장술 🥦', body_ko = '수프 속 초록 채소를 외과 의사처럼 정확하게 골라내나요? 편식이 한창이에요. 식단 계획에서 채소를 감쪽같이 숨겨 알록달록한 동그랑땡으로 바꾸는 특별하고 기발한 레시피를 찾아볼 때예요.', title_nl = 'Broccolicamouflage 🥦', body_nl = 'Sorteert hij de groene groenten met chirurgische precisie uit zijn soep? Kieskeurig eten is op zijn hoogtepunt. Tijd om in het Voedingsplan slimme recepten te ontdekken die groenten onzichtbaar maken en ze in kleurrijke burgertjes veranderen.', title_pl = 'Brokułowy kamuflaż 🥦', body_pl = 'Z chirurgiczną precyzją odkłada zielone warzywa z zupy na bok? Wybredność jedzeniowa jest u szczytu. Czas odkryć w planie karmienia specjalne, sprytne przepisy, które ukryją warzywa w kolorowych kotlecikach.', title_pt = 'Brócolos camuflados 🥦', body_pt = 'Separa os legumes verdes da sopa com precisão de cirurgião? A seletividade alimentar está no auge. É altura de descobrir no Registo de Alimentação receitas especiais e engenhosas que tornam os legumes invisíveis e os transformam em croquetes coloridos.', title_sv = 'Broccolikamouflage 🥦', body_sv = 'Sorterar barnet bort de gröna grönsakerna i soppan med kirurgisk precision? Kräsenheten är på topp. Det är dags att upptäcka särskilda, listiga recept i matplanen som gör grönsakerna osynliga och förvandlar dem till färgglada biffar.', title_vi = 'Ngụy trang bông cải xanh 🥦', body_vi = 'Bé nhặt rau xanh ra khỏi bát súp với độ chính xác của bác sĩ phẫu thuật? Kén ăn đang ở đỉnh điểm. Đã đến lúc khám phá trong Kế hoạch dinh dưỡng những công thức đặc biệt, khéo léo giúp rau "tàng hình" và biến thành những miếng chả nhiều màu sắc.', title_zh = '西兰花伪装术 🥦', body_zh = '像外科医生一样精准地把汤里的绿色蔬菜挑出来？挑食正处于高峰。是时候在喂养计划里发现那些能让蔬菜“隐身”、变成彩色肉饼的特别小妙招食谱了。' WHERE id = '4c758b24-b5bb-4fba-9fae-76aff0e5119d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Él dirige el cuento 🪄', body_es = 'Los dos estáis hartos de los libros de siempre. Abre Cuentos inteligentes y esta noche deja que él dirija la historia. Pregúntale: «¿Y ahora adónde va ese coche volador?», y deja que se duerma con el final absurdo que invente.', title_fr = 'C''est lui le metteur en scène du conte 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques ? Ouvrez les Contes intelligents et, ce soir, laissez-le diriger l''histoire. Demandez : « Où va aller la voiture volante maintenant ? » et laissez-le s''endormir sur la fin absurde qu''il aura inventée.', title_hi = 'कहानी का निर्देशक वही 🪄', body_hi = 'आप दोनों पुरानी किताबों से ऊब चुके हैं। स्मार्ट कहानियाँ खोलिए और आज शाम कहानी की दिशा उसे तय करने दीजिए। पूछिए, ‘अब वह उड़ने वाली गाड़ी कहाँ जाए?’ और उसे अपने गढ़े बेतुके अंत के साथ सोने दीजिए।', title_id = 'Ia sutradara dongengnya 🪄', body_id = 'Kalian berdua sudah bosan dengan buku klasik. Buka Dongeng Pintar dan malam ini biarkan ia yang mengarahkan alur cerita. Tanyakan ''Sekarang mobil terbang itu pergi ke mana?'', dan biarkan ia tertidur dengan akhir cerita absurd karangannya sendiri.', title_ja = 'お話の監督はこの子 🪄', body_ja = '定番の絵本にはふたりとも飽きてしまった？「スマートおはなし」を開いて、今夜はストーリーの行き先をこの子にまかせましょう。「この空飛ぶ車、次はどこへ行く？」とたずねて、考えたおかしな結末とともに眠りにつかせてあげて。', title_ko = '동화의 감독은 아이 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 스마트 동화를 열고 오늘 저녁엔 이야기의 방향을 아이에게 맡겨 보세요. ''이제 날아다니는 자동차는 어디로 갈까?'' 묻고, 아이가 지어낸 엉뚱한 결말과 함께 잠들게 해 주세요.', title_nl = 'Hij is de regisseur van het sprookje 🪄', body_nl = 'Zijn jullie allebei de klassieke boeken beu? Open Slimme sprookjes en laat hem vanavond het verhaal sturen. Vraag: ''Waar moet die vliegende auto nu naartoe?'' en laat hem in slaap vallen met het absurde einde dat hij bedenkt.', title_pl = 'On reżyseruje bajkę 🪄', body_pl = 'Klasyczne książeczki znudziły się wam obojgu. Otwórz Mądre bajki i pozwól mu dziś wieczorem kierować fabułą. Zapytaj: „Dokąd teraz ma lecieć to latające auto?” i niech zaśnie przy absurdalnym zakończeniu, które sam wymyśli.', title_pt = 'Ele é o realizador da história 🪄', body_pt = 'Estão os dois fartos dos livros clássicos. Abra as Histórias Inteligentes e deixe que esta noite seja ele a guiar o enredo. Pergunte "E agora, para onde vai aquele carro voador?" e deixe-o adormecer com o final absurdo que inventar.', title_sv = 'Barnet regisserar sagan 🪄', body_sv = 'Ni är båda trötta på de klassiska böckerna. Öppna Smarta sagor och låt barnet styra handlingen i kväll. Fråga ”Vart ska den flygande bilen åka nu?” och låt barnet somna till sitt eget påhittade, absurda slut.', title_vi = 'Bé làm đạo diễn câu chuyện 🪄', body_vi = 'Cả hai mẹ con đều đã chán những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh và tối nay để bé dẫn dắt cốt truyện. Hỏi bé: "Giờ chiếc ô tô bay nên đi đâu nhỉ?", rồi để bé chìm vào giấc ngủ với cái kết ngộ nghĩnh do chính mình nghĩ ra.', title_zh = '故事的导演是宝宝 🪄', body_zh = '经典故事书你们俩都看腻了。打开智慧童话，今晚让宝宝来决定故事走向。问问：“现在那辆会飞的车该去哪儿？”就让宝宝带着自己编的荒诞结局入睡吧。' WHERE id = '56a63f2b-c314-4614-a2a4-36e4a75775f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Estás muy cansada y te sientes la madre con menos paciencia del mundo? Abre ya la Comunidad Anacan. Leer que otras madres viven exactamente las mismas crisis absurdas es el mayor apoyo psicológico.', body_fr = 'Très fatiguée, vous vous sentez la maman la plus impatiente du monde ? Ouvrez tout de suite la Communauté Anacan. Lire que d''autres mamans vivent exactement les mêmes crises absurdes est le plus grand des soutiens psychologiques.', body_hi = 'बहुत थक गई हैं और खुद को दुनिया की सबसे बेसब्र माँ महसूस कर रही हैं? तुरंत Anacan कम्युनिटी खोलिए। यह पढ़ना कि दूसरी माँएँ भी बिल्कुल ऐसे ही बेतुके संकट झेल रही हैं, सबसे बड़ा मानसिक सहारा है।', body_id = 'Sangat lelah dan merasa menjadi ibu paling tidak sabar di dunia? Segera buka Komunitas Anacan. Membaca bahwa ibu-ibu lain mengalami krisis absurd yang persis sama adalah dukungan psikologis terbesar.', body_ja = 'とても疲れて、自分は世界でいちばんがまんのできないママだと感じていますか？すぐにAnacanコミュニティを開いて。ほかのママたちもまったく同じおかしなかんしゃくを経験していると読むことが、いちばんの心の支えになります。', body_ko = '너무 지쳐서 세상에서 가장 참을성 없는 엄마처럼 느껴지나요? 바로 Anacan 커뮤니티를 열어 보세요. 다른 엄마들도 똑같이 엉뚱한 위기를 겪는다는 걸 읽는 것이 가장 큰 마음의 버팀목이에요.', body_nl = 'Ben je heel moe en voel je je de ongeduldigste moeder ter wereld? Open meteen de Anacan Community. Lezen dat andere mama''s precies dezelfde absurde crisissen meemaken, is de grootste psychologische steun.', body_pl = 'Jesteś bardzo zmęczona i czujesz się najbardziej niecierpliwą mamą na świecie? Od razu otwórz Społeczność Anacan. Czytanie, że inne mamy przeżywają dokładnie te same absurdalne kryzysy, to największe wsparcie psychiczne.', body_pt = 'Está muito cansada e sente-se a mãe mais impaciente do mundo? Abra já a Comunidade Anacan. Ler que outras mães vivem exatamente as mesmas crises absurdas é o maior apoio psicológico.', body_sv = 'Är du väldigt trött och känner dig som världens mest otåliga mamma? Öppna Anacan Community direkt. Att läsa att andra mammor går igenom exakt samma absurda kriser är det största psykologiska stödet.', body_vi = 'Mẹ quá mệt và cảm thấy mình là người mẹ thiếu kiên nhẫn nhất thế giới? Hãy mở ngay Cộng đồng Anacan. Đọc thấy các mẹ khác cũng trải qua y hệt những cơn khủng hoảng "khó đỡ" ấy chính là chỗ dựa tâm lý lớn nhất.', body_zh = '累坏了，觉得自己是世界上最没耐心的妈妈？马上打开Anacan社区。读到其他妈妈也在经历一模一样荒诞的崩溃，就是最大的心理支持。' WHERE id = '9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El bucle infinito de los «¿por qué?» 🌪️', body_es = '«¿Por qué vuelan los pájaros?», «¿Por qué moja el agua?», «¿Por qué es por qué?»... El tren de preguntas se te echa encima a toda velocidad. Aunque estés cansada, dale respuestas lógicas y cortas. Aprende los secretos del universo a través de tu tono de voz.', title_fr = 'La boucle sans fin des « Pourquoi ? » 🌪️', body_fr = '« Pourquoi les oiseaux volent ? », « Pourquoi l''eau mouille ? », « Pourquoi pourquoi ? »... Un train de questions fonce sur vous. Même si vous êtes fatiguée, donnez-lui des réponses logiques et courtes. Il apprend les secrets de l''univers à travers le ton de votre voix.', title_hi = 'कभी न खत्म होने वाला ‘क्यों?’ 🌪️', body_hi = '‘पक्षी क्यों उड़ते हैं?’, ‘पानी गीला क्यों करता है?’, ‘क्यों, क्यों है?’... सवालों की ट्रेन तेज़ी से आपकी ओर आ रही है। थक भी जाएँ, तो उसे तर्कसंगत और छोटे जवाब दीजिए। वह दुनिया के रहस्य आपकी आवाज़ के लहजे से सीखता है।', title_id = 'Lingkaran ''Kenapa?'' tanpa akhir 🌪️', body_id = '''Kenapa burung terbang?'', ''Kenapa air membuat basah?'', ''Kenapa kenapa itu kenapa?''... Rangkaian pertanyaan datang menyerbu Anda. Meski lelah, beri ia jawaban yang logis dan singkat. Ia mempelajari rahasia alam semesta dari nada suara Anda.', title_ja = '終わらない「なんで？」ループ 🌪️', body_ja = '「鳥はなんで飛ぶの？」「お水はなんでぬれるの？」「なんでは、なんで？」…質問の列車が猛スピードでやってきます。疲れていても、論理的で短い答えを返してあげて。宇宙のふしぎを、あなたの声のトーンから学んでいるんです。', title_ko = '끝없는 ''왜?''의 굴레 🌪️', body_ko = '''새는 왜 날아?'', ''물은 왜 젖어?'', ''왜는 왜 왜야?''... 질문 열차가 빠르게 달려오나요? 지쳐도 논리적이고 짧게 답해 주세요. 아이는 엄마의 목소리 톤에서 우주의 비밀을 배워요.', title_nl = 'De eindeloze waarom-cirkel 🌪️', body_nl = '''Waarom vliegen vogels?'', ''Waarom is water nat?'', ''Waarom is waarom waarom?''... Een trein vol vragen komt op je af. Ook al ben je moe, geef hem logische en korte antwoorden. Hij leert de geheimen van het universum via de toon van jouw stem.', title_pl = 'Niekończące się „Dlaczego?” 🌪️', body_pl = '„Dlaczego ptaki latają?”, „Dlaczego woda moczy?”, „Dlaczego jest dlaczego?”... Pociąg pytań pędzi prosto na ciebie. Nawet gdy jesteś zmęczona, odpowiadaj mu logicznie i krótko. Tajemnic wszechświata uczy się z tonu twojego głosu.', title_pt = 'O ciclo infinito dos "Porquê?" 🌪️', body_pt = '"Porque é que os pássaros voam?", "Porque é que a água molha?", "Porque é que o porquê é porquê?"... O comboio de perguntas vem a toda a velocidade na sua direção. Mesmo cansada, dê-lhe respostas lógicas e curtas. Ele aprende os segredos do universo pelo seu tom de voz.', title_sv = 'Den ändlösa ”Varför?”-loopen 🌪️', body_sv = '”Varför flyger fåglarna?”, ”Varför blir man blöt av vatten?”, ”Varför är varför?”... Frågetåget rusar mot dig. Även om du är trött, ge barnet logiska och korta svar. Barnet lär sig universums hemligheter genom din röst.', title_vi = 'Vòng lặp "Tại sao?" bất tận 🌪️', body_vi = '"Sao chim bay được?", "Sao nước lại ướt?", "Sao tại sao lại là tại sao?"... Cả đoàn tàu câu hỏi lao đến mẹ. Dù mệt, hãy trả lời bé ngắn gọn và hợp lý. Bé học những bí mật của vũ trụ qua giọng nói của mẹ.', title_zh = '没完没了的“为什么？”循环 🌪️', body_zh = '“鸟为什么会飞？”“水为什么是湿的？”“为什么是为什么？”……问题列车飞速向你驶来。就算累了，也给宝宝简短又有逻辑的回答。宝宝正从你的语气里学习宇宙的奥秘。' WHERE id = 'bd33d5a6-7358-4409-91cf-48f9ce76cb44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada a la naturaleza ⛅', body_es = 'Las cuatro paredes os han puesto agresivos a los dos. Estás cansada del caos de casa. Consulta la herramienta Tiempo y ropa y corred enseguida al parque. Correr libre al aire libre corta de raíz hasta las rabietas más fuertes.', title_fr = 'S''évader dans la nature ⛅', body_fr = 'Les quatre murs vous rendent tous les deux agressifs. Vous êtes fatiguée du chaos de la maison. Consultez Météo et tenue et filez tout de suite au parc. Courir librement en plein air tranche net même les crises les plus intenses des tout-petits.', title_hi = 'प्रकृति की ओर भागिए ⛅', body_hi = 'चार दीवारों ने उसे भी और आपको भी चिड़चिड़ा बना दिया है। घर की अफ़रा-तफ़री से आप थक चुकी हैं। मौसम और कपड़े टूल देखिए और तुरंत पार्क की ओर निकलिए। खुली हवा में आज़ादी से दौड़ना टॉडलर के सबसे तेज़ नखरों को भी चाकू की तरह काट देता है।', title_id = 'Kabur ke alam ⛅', body_id = 'Empat dinding membuat ia dan Anda sama-sama gelisah. Anda lelah dengan kekacauan rumah. Cek Cuaca dan Pakaian, lalu segera pergi ke taman. Berlari bebas di udara terbuka bisa memotong krisis balita yang paling hebat sekalipun seperti pisau.', title_ja = '自然へ逃げよう ⛅', body_ja = '4つの壁の中で、この子もあなたもイライラ。家のカオスに疲れきっていますね。「天気と服装」をチェックして、すぐに公園へ出かけましょう。外で自由に走りまわれば、いちばん激しいイヤイヤ期のかんしゃくさえ、すっぱり断ち切れます。', title_ko = '자연으로 탈출 ⛅', body_ko = '네 벽이 아이도 엄마도 날카롭게 만들고, 집 안의 혼돈에 지쳤나요? 날씨와 옷차림 도구를 확인하고 바로 공원으로 달려가세요. 밖에서 마음껏 뛰면 아무리 심한 떼쓰기도 칼로 자르듯 끊어져요.', title_nl = 'Vluchten naar de natuur ⛅', body_nl = 'Vier muren maken jullie allebei agressief. Je bent moe van de chaos in huis. Check de tool Weer en kleding en ga meteen naar het park. Vrij rennen in de buitenlucht snijdt zelfs de heftigste peuterbuien als een mes door.', title_pl = 'Ucieczka na łono natury ⛅', body_pl = 'Cztery ściany rozdrażniły i jego, i ciebie. Masz dość domowego chaosu. Sprawdź Pogodę i ubiór i od razu biegnijcie do parku. Swobodne bieganie na świeżym powietrzu ucina jak nożem nawet najostrzejsze kryzysy maluchów.', title_pt = 'Fuga para a natureza ⛅', body_pt = 'As quatro paredes deixaram-no a ele, e a si, agressivos. Está cansada do caos da casa. Veja a ferramenta Tempo e Roupa e corram já para o parque. Correr à vontade ao ar livre corta como uma faca até as crises de birra mais fortes.', title_sv = 'Flykt ut i naturen ⛅', body_sv = 'De fyra väggarna har gjort både barnet och dig irriterade. Du är trött på kaoset hemma. Kolla verktyget Väder och kläder och skynda er till parken. Att springa fritt i friska luften skär av även de värsta trotsutbrotten som en kniv.', title_vi = 'Trốn ra thiên nhiên ⛅', body_vi = 'Bốn bức tường khiến cả bé lẫn mẹ đều bức bối. Mẹ đã mệt vì sự hỗn loạn trong nhà. Hãy kiểm tra Thời tiết và trang phục rồi ra công viên ngay. Chạy nhảy tự do ngoài trời có thể dập tắt ngay cả những cơn ăn vạ dữ dội nhất của trẻ nhỏ.', title_zh = '逃向大自然 ⛅', body_zh = '四面墙让宝宝和你都变得烦躁。家里的混乱让你累坏了。看看天气与穿衣工具，马上奔向公园吧。在户外自由奔跑，连最激烈的幼儿崩溃也能像刀切一样化解。' WHERE id = '5940af77-4cae-40d5-a543-2bf3a6668855' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desastre del color equivocado 🔴', body_es = '¿Se ha armado una buena porque le diste el agua en el vaso rojo y no en el azul? No es un capricho: está comprobando tus límites y si puede controlar el mundo. Sin discutir, cambia el vaso y guarda tu energía.', title_fr = 'La catastrophe de la mauvaise couleur 🔴', body_fr = 'C''est l''apocalypse parce que vous lui avez donné l''eau dans le gobelet rouge et non le bleu ? Ce n''est pas un caprice, il teste simplement vos limites et son pouvoir sur le monde. Changez le gobelet sans vous entêter et préservez votre énergie.', title_hi = 'गलत रंग की आफ़त 🔴', body_hi = 'पानी नीले नहीं, लाल गिलास में दिया, इसलिए कयामत आ गई? यह नखरा नहीं, वह बस आपकी सीमाएँ और दुनिया को चला पाने की अपनी ताकत परख रहा है। ज़िद किए बिना गिलास बदल दीजिए और अपनी ऊर्जा बचाइए।', title_id = 'Bencana salah warna 🔴', body_id = 'Kiamat terjadi karena Anda memberinya air di gelas biru, bukan merah? Ini bukan manja, ia hanya menguji batasan Anda dan kemampuannya mengatur dunia. Tukar gelasnya tanpa berdebat dan hemat energi Anda.', title_ja = 'ちがう色の大惨事 🔴', body_ja = 'お水を青じゃなく赤いコップで出したせいで、大騒ぎ？これはわがままではなく、あなたの境界線と、自分が世界を動かせるかを試しているんです。意地をはらずにコップをかえて、あなたのエネルギーを守りましょう。', title_ko = '잘못된 색깔 대참사 🔴', body_ko = '물을 빨간 컵이 아니라 파란 컵에 줘서 난리가 났나요? 변덕이 아니라 엄마의 경계와 자기가 세상을 움직일 수 있는지를 시험하는 거예요. 고집 싸움 없이 컵을 바꿔 주고 에너지를 아끼세요.', title_nl = 'De ramp van de verkeerde kleur 🔴', body_nl = 'Brak de hel los omdat je zijn water in een blauwe in plaats van een rode beker gaf? Dat is geen verwendheid, hij test gewoon jouw grenzen en of hij zijn wereld kan besturen. Wissel de beker zonder koppigheid en spaar je energie.', title_pl = 'Katastrofa złego koloru 🔴', body_pl = 'Rozpętało się piekło, bo podałaś wodę w czerwonym kubku, a nie w niebieskim? To nie kaprys, on po prostu sprawdza twoje granice i to, czy potrafi rządzić światem. Bez uporu zmień kubek i oszczędzaj energię.', title_pt = 'O desastre da cor errada 🔴', body_pt = 'Foi o fim do mundo porque lhe deu a água num copo vermelho e não no azul? Não é capricho: está só a testar os seus limites e se consegue controlar o mundo. Sem teimar, troque o copo e poupe a sua energia.', title_sv = 'Fel färg-katastrofen 🔴', body_sv = 'Blev det jordens undergång för att du gav vattnet i en röd mugg istället för den blå? Det är inte trots, barnet testar bara dina gränser och om det kan styra världen. Byt mugg utan att tjafsa och spara din energi.', title_vi = 'Thảm họa sai màu 🔴', body_vi = 'Cả nhà "náo loạn" chỉ vì mẹ đưa nước trong cốc xanh thay vì cốc đỏ? Đây không phải là đỏng đảnh, bé chỉ đang thử giới hạn của mẹ và khả năng kiểm soát thế giới của mình. Hãy đổi cốc mà không giằng co và giữ năng lượng cho bản thân.', title_zh = '颜色错了的灾难 🔴', body_zh = '就因为水没装在蓝杯子里，而是装在红杯子里，天就塌了？这不是任性，宝宝只是在测试你的边界，测试自己能不能掌控世界。别较劲，换个杯子，保存你的精力。' WHERE id = '7886ad64-9846-4990-9753-652093d6bac5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Nadie ve lo cansada que estás en casa? El Diario de ánimo es tu confidente más silencioso. Escribe ahí todos los detalles que hoy te han sacado de quicio y nota cómo se aligera tu mente.', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison ? Le Journal d''humeur est votre confident le plus discret. Écrivez-y tous les détails qui vous ont rendue folle aujourd''hui et sentez votre esprit s''alléger.', body_hi = 'किसी को नहीं दिखता कि आप घर में कितना थकती हैं? मूड डायरी आपकी सबसे खामोश राज़दार है। आज जिन बातों ने आपको पागल किया, सब वहाँ लिखिए और देखिए कि दिमाग कैसे हल्का होता है।', body_id = 'Tak ada yang melihat betapa lelahnya Anda di rumah? Buku Harian Suasana Hati adalah teman curhat Anda yang paling diam. Tuliskan di sana semua detail yang membuat Anda gila hari ini dan rasakan betapa ringannya pikiran Anda.', body_ja = '家であなたがどれほど疲れているか、誰も気づいてくれない？「気分日記」は、いちばん静かな打ち明け相手です。今日あなたをいらだたせたことを全部書いて、頭がどれほど軽くなるか感じてみて。', body_ko = '집에서 얼마나 지쳤는지 아무도 몰라주나요? 기분 일기는 가장 조용한 비밀 친구예요. 오늘 나를 미치게 한 모든 일을 적고 머리가 가벼워지는 걸 느껴 보세요.', body_nl = 'Ziet niemand hoe moe je thuis bent? Je Stemmingsdagboek is je stilste vertrouweling. Schrijf daar alle details op die je vandaag gek maakten en voel hoe je hoofd lichter wordt.', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu? Dziennik nastroju to twój najcichszy powiernik. Zapisz w nim wszystkie szczegóły, które dziś doprowadziły cię do szału, i zobacz, jak lżej robi się w głowie.', body_pt = 'Ninguém vê o quanto se cansa em casa? O Diário de Humor é o seu confidente mais silencioso. Escreva lá todos os pormenores que hoje a deixaram louca e veja como o seu cérebro fica mais leve.', body_sv = 'Ser ingen hur trött du är hemma? Humördagboken är din tystaste förtrogna. Skriv ner alla detaljer som gjorde dig galen i dag och känn hur lättare hjärnan blir.', body_vi = 'Không ai thấy mẹ mệt mỏi thế nào khi ở nhà? Nhật ký tâm trạng là người bạn tâm giao lặng lẽ nhất của mẹ. Hãy viết vào đó mọi chi tiết khiến mẹ phát điên hôm nay và cảm nhận đầu óc nhẹ nhõm hơn.', body_zh = '没人看见你在家有多累？心情日记是你最安静的知心朋友。把今天让你抓狂的所有细节都写进去，看看大脑会变得多轻松。' WHERE id = 'bfa1d504-f493-414c-a978-4ad885726ef7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, solución real 🤖', body_es = '¿Le ha aparecido una costumbre rara (por ejemplo, enroscarse el pelo) y los artículos de internet te han asustado? Para. Pregunta a Anacan AI la verdadera causa, avalada por pediatras, y líbrate del pánico innecesario.', title_fr = 'Intelligence artificielle, vraie solution 🤖', body_fr = 'Votre enfant a pris une drôle d''habitude (s''entortiller les cheveux, par exemple) et les articles sur Internet vous ont fait peur ? Stop. Demandez à Anacan AI la vraie cause, validée par des pédiatres, et évitez une panique inutile.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, असली हल 🤖', body_hi = 'बच्चे में कोई अजीब आदत आ गई है (जैसे बाल घुमाना) और इंटरनेट के लेखों ने आपको डरा दिया? रुकिए। Anacan AI से इसकी बाल रोग विशेषज्ञ द्वारा पुष्ट असली वजह पूछिए और बेवजह की घबराहट से छुटकारा पाइए।', title_id = 'Kecerdasan buatan, solusi nyata 🤖', body_id = 'Anak Anda punya kebiasaan aneh (misalnya memelintir rambut) dan artikel di internet membuat Anda takut? Tunggu dulu. Tanyakan pada Anacan AI penyebab sebenarnya yang disetujui dokter anak, dan bebaskan diri dari panik yang tidak perlu.', title_ja = 'AI、リアルな解決策 🤖', body_ja = 'お子さんに変なくせ（たとえば髪をくるくるねじる）が出てきて、ネットの記事を見て怖くなりましたか？ちょっと待って。Anacan AIに、小児科医監修の本当の理由をたずねて、必要のないパニックから抜け出しましょう。', title_ko = '인공지능, 진짜 해결책 🤖', body_ko = '아이에게 머리카락 꼬기 같은 이상한 습관이 생겼는데 인터넷 글에 겁이 났나요? 멈추세요. Anacan AI에게 소아과 의사가 확인한 진짜 이유를 물어보고 불필요한 걱정에서 벗어나세요.', title_nl = 'Kunstmatige intelligentie, echte oplossing 🤖', body_nl = 'Heeft je kind een vreemde gewoonte opgepikt (zoals aan zijn haar draaien) en word je bang van artikelen op internet? Stop. Vraag Anacan AI naar de echte, door kinderartsen bevestigde oorzaak en bespaar jezelf onnodige paniek.', title_pl = 'Sztuczna inteligencja, prawdziwe rozwiązanie 🤖', body_pl = 'U dziecka pojawił się dziwny nawyk (np. kręcenie włosów), a artykuły w internecie cię przestraszyły? Stop. Zapytaj Anacan AI o prawdziwą, potwierdzoną przez pediatrów przyczynę i pozbądź się niepotrzebnej paniki.', title_pt = 'Inteligência artificial, solução real 🤖', body_pt = 'O seu filho ganhou um hábito estranho (por exemplo, enrolar o cabelo) e os artigos da internet assustaram-na? Pare. Pergunte ao Anacan AI a verdadeira causa, validada por pediatras, e livre-se do pânico desnecessário.', title_sv = 'Artificiell intelligens, riktig lösning 🤖', body_sv = 'Har barnet fått en konstig vana (till exempel att tvinna håret) och artiklarna på nätet skrämde dig? Stopp. Fråga Anacan AI om den verkliga, barnläkargodkända orsaken och slipp onödig panik.', title_vi = 'Trí tuệ nhân tạo, giải pháp thật 🤖', body_vi = 'Bé có một thói quen lạ (ví dụ như xoắn tóc) và các bài viết trên mạng làm mẹ hoảng sợ? Dừng lại. Hãy hỏi Anacan AI nguyên nhân thật sự đã được bác sĩ nhi khoa xác nhận và thoát khỏi sự hoảng loạn không cần thiết.', title_zh = '人工智能，真实的解决办法 🤖', body_zh = '宝宝养成了一个奇怪的习惯（比如绕头发），网上的文章把你吓坏了？停一下。问问Anacan AI，了解经儿科医生认可的真正原因，摆脱不必要的恐慌。' WHERE id = '1800a436-63cf-4ef5-8469-ebb0dffa942d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lógica del escondite 🙈', body_es = '¡En medio de la habitación se tapa los ojos con las manos y espera que le encuentres! Lógica de los 3 años: «si yo no te veo, tú tampoco me ves». Hazte la engañada con esta ilusión inocente y búscale por la habitación haciendo mucho ruido.', title_fr = 'La logique du cache-cache 🙈', body_fr = 'Au milieu de la pièce, il se cache les yeux avec les mains et attend que vous le trouviez ! Logique des 3 ans : « Si je ne te vois pas, tu ne me vois pas. » Faites semblant d''être dupe de cette illusion innocente et cherchez-le bruyamment dans la pièce.', title_hi = 'छुपन-छुपाई का तर्क 🙈', body_hi = 'कमरे के बीच हाथों से आँखें ढककर इंतज़ार कर रहा है कि आप उसे ढूँढें! 3 साल का तर्क: ‘मैं तुम्हें नहीं देख रहा, तो तुम भी मुझे नहीं देख रहीं।’ उसके इस मासूम भ्रम में आने का नाटक कीजिए और कमरे में ज़ोर-शोर से उसे ढूँढिए।', title_id = 'Logika petak umpet 🙈', body_id = 'Ia berdiri di tengah kamar menutup mata dengan tangan dan menunggu Anda menemukannya! Logika usia 3 tahun: ''Kalau aku tidak melihatmu, kamu juga tidak melihatku.'' Berpura-puralah tertipu ilusi polosnya dan carilah ia di kamar dengan heboh.', title_ja = 'かくれんぼの理屈 🙈', body_ja = '部屋のまんなかで両手で目をかくして、見つけてもらうのを待っている！3歳の理屈：「ぼくが見えなければ、ママもぼくが見えない」。このかわいい思いこみにだまされたふりをして、にぎやかにさがしてあげましょう。', title_ko = '숨바꼭질의 논리 🙈', body_ko = '방 한가운데서 두 손으로 눈을 가리고 엄마가 찾아 주길 기다리나요! 세 살의 논리: ''내가 엄마를 못 보면 엄마도 나를 못 봐.'' 이 순수한 착각에 속은 척하며 요란하게 찾아 주세요.', title_nl = 'Verstoppertjeslogica 🙈', body_nl = 'Hij staat midden in de kamer met zijn handen voor zijn ogen en wacht tot je hem vindt! Logica van een 3-jarige: ''Als ik jou niet zie, zie jij mij ook niet.'' Doe alsof je in zijn onschuldige illusie trapt en zoek luidruchtig naar hem.', title_pl = 'Logika zabawy w chowanego 🙈', body_pl = 'Stoi na środku pokoju z rączkami na oczach i czeka, aż go znajdziesz! Logika 3-latka: „Jeśli ja cię nie widzę, ty mnie też nie widzisz”. Udawaj, że dajesz się nabrać na tę niewinną iluzję, i głośno szukaj go po pokoju.', title_pt = 'A lógica das escondidas 🙈', body_pt = 'No meio do quarto, tapa os olhos com as mãos e espera que o encontre! Lógica dos 3 anos: "Se eu não te vejo, tu também não me vês". Finja que cai nesta ilusão inocente e procure-o pelo quarto, fazendo barulho.', title_sv = 'Kurragömmalogik 🙈', body_sv = 'Barnet står mitt i rummet med händerna för ögonen och väntar på att du ska hitta det! 3-årslogik: om jag inte ser dig, ser du inte mig. Låtsas att du går på den oskyldiga illusionen och leta högljutt efter barnet i rummet.', title_vi = 'Logic trốn tìm 🙈', body_vi = 'Bé đứng giữa phòng, lấy tay che mắt và chờ mẹ tìm! Logic của tuổi lên 3: "Con không nhìn thấy mẹ thì mẹ cũng không nhìn thấy con". Hãy giả vờ bị đánh lừa bởi ảo tưởng ngây thơ này và ồn ào đi tìm bé khắp phòng.', title_zh = '捉迷藏的逻辑 🙈', body_zh = '站在房间中间用手捂住眼睛，等着你来找！3岁的逻辑：“我看不见你，你也就看不见我。”假装被这份天真的错觉骗到，在房间里热热闹闹地找宝宝吧。' WHERE id = '3f147988-5fe0-4104-b53b-bcd1de9eb553' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro y sin tecnología.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans un environnement sombre et sans écran.', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi.', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は、暗くてデジタル機器のない環境でこそすばやく分泌されます。', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어둡고 기기가 없는 환경에서만 빠르게 분비돼요.', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen snel aangemaakt in een donkere omgeving zonder technologie.', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu bez technologii.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro e sem tecnologia.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk och teknikfri miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素（睡眠激素）只有在昏暗、没有电子产品的环境里才会快速分泌。' WHERE id = 'e71a10b9-dee7-4968-a1f7-387196804ef0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Siempre se te olvida algo al ir al súper? La Lista de la compra te espera en la app. Apunta ahí enseguida lo que haga falta y que tu pareja lo compre con precisión al volver del trabajo. No sobrecargues tu mente.', body_fr = 'Vous oubliez toujours quelque chose en allant au supermarché ? La Liste de courses vous attend dans l''application. Notez-y tout de suite vos besoins pour que votre partenaire rapporte tout avec précision en rentrant du travail. Ne surchargez pas votre cerveau.', body_hi = 'बाज़ार जाते समय कुछ न कुछ ज़रूर भूल जाती हैं? शॉपिंग लिस्ट ऐप में आपका इंतज़ार कर रही है। ज़रूरतें तुरंत वहाँ लिखिए, ताकि आपके साथी काम से लौटते समय ठीक-ठीक सामान ले आएँ, दिमाग पर बोझ मत डालिए।', body_id = 'Selalu ada yang terlupa saat ke supermarket? Daftar Belanja menunggu Anda di aplikasi. Segera catat kebutuhan di sana, biar pasangan Anda membelinya dengan tepat sepulang kerja, jangan bebani otak Anda.', body_ja = 'スーパーに行くと、必ず何か買い忘れる？アプリの「買い物リスト」が待っています。必要なものはすぐに書きこんで、パートナーが仕事帰りにきっちり買ってこられるようにしましょう。頭に詰めこまなくて大丈夫。', body_ko = '마트에 가면 꼭 뭔가를 잊나요? 앱에서 쇼핑 목록이 기다리고 있어요. 필요한 걸 바로 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요. 머리를 혹사하지 마세요.', body_nl = 'Vergeet je altijd wel iets als je naar de supermarkt gaat? Het Boodschappenlijstje wacht in de app op je. Zet alles wat je nodig hebt er meteen op, zodat je partner het op weg naar huis precies kan meenemen. Zo belast je je hoofd niet.', body_pl = 'Idąc do sklepu, zawsze o czymś zapominasz? Lista zakupów czeka na ciebie w aplikacji. Od razu zapisuj tam potrzeby, niech partner w drodze z pracy dokładnie wszystko kupi, nie obciążaj swojej głowy.', body_pt = 'Quando vai ao supermercado, esquece-se sempre de alguma coisa? A Lista de Compras está à sua espera na app. Registe lá logo o que faz falta para que o seu companheiro compre tudo certinho ao voltar do trabalho, e não sobrecarregue o cérebro.', body_sv = 'Glömmer du alltid något när du går till butiken? Inköpslistan väntar på dig i appen. Skriv upp behoven direkt, så kan din partner handla exakt rätt på vägen hem från jobbet. Belasta inte din hjärna.', body_vi = 'Đi siêu thị lần nào cũng quên thứ gì đó? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi ngay những thứ cần mua vào đó, để chồng trên đường đi làm về mua đầy đủ, chính xác, mẹ khỏi phải nhớ.', body_zh = '去超市总会忘点什么？购物清单在应用里等着你。把需要的东西马上记进去，让伴侣下班回家时准确买齐，别再给大脑增加负担。' WHERE id = '2cc2d175-4d74-4e12-832a-3885acc3e55b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ley del «¡Yo solo!» 👟', body_es = 'Quiere atarse él solo los cordones y ya llegáis 10 minutos tarde para salir de casa. No le metas prisa. Para su desarrollo importa más un ego sin heridas que un horario sin retrasos.', title_fr = 'La loi du « Moi tout seul ! » 👟', body_fr = 'Il veut faire ses lacets tout seul et vous avez déjà 10 minutes de retard pour sortir. Ne vous pressez pas. Pour son développement, un ego intact compte bien plus qu''un emploi du temps chamboulé.', title_hi = '‘मैं खुद!’ का नियम 👟', body_hi = 'जूतों के फीते खुद बाँधना चाहता है और घर से निकलने में आप पहले ही 10 मिनट लेट हैं। जल्दबाज़ी मत कीजिए। बिगड़े हुए टाइम-टेबल से ज़्यादा, बिना ठेस पहुँचा अहं उसके विकास के लिए ज़रूरी है।', title_id = 'Hukum ''Aku sendiri!'' 👟', body_id = 'Ia ingin mengikat tali sepatunya sendiri, padahal kalian sudah terlambat 10 menit untuk keluar rumah. Jangan terburu-buru. Ego yang tidak terluka jauh lebih penting bagi perkembangannya daripada jadwal yang tidak berantakan.', title_ja = '「自分で！」のおきて 👟', body_ja = '靴ひもを自分で結びたがって、出かける時間にもう10分も遅れている。急がないで。時間どおりに進むことより、傷つかない自尊心のほうが、この子の成長にはずっと大切です。', title_ko = '''내가 할 거야!'' 법칙 👟', body_ko = '신발 끈을 자기가 묶겠다는데 벌써 10분이나 늦었나요? 서두르지 마세요. 아이의 발달에는 망가진 일정보다 다치지 않은 자존감이 더 중요해요.', title_nl = 'De ''Zelf doen!''-wet 👟', body_nl = 'Hij wil zelf zijn veters strikken en jullie zijn al 10 minuten te laat. Haast je niet. Een ongeschonden ego is voor zijn ontwikkeling veel belangrijker dan een verstoorde planning.', title_pl = 'Zasada „Ja sam!” 👟', body_pl = 'Chce sam zawiązać sznurówki, a wy już jesteście 10 minut spóźnieni. Nie poganiaj go. Dla jego rozwoju nienaruszone ego jest ważniejsze niż naruszony harmonogram.', title_pt = 'A lei do "Eu sozinho!" 👟', body_pt = 'Quer atar sozinho os atacadores e já estão 10 minutos atrasados para sair de casa. Não tenha pressa. Para o desenvolvimento dele, um ego que não sai ferido é mais importante do que um horário que fica estragado.', title_sv = 'Lagen om ”Jag själv!” 👟', body_sv = 'Barnet vill knyta skosnörena själv och ni är redan 10 minuter försenade. Stressa inte. För barnets utveckling är ett oskadat ego viktigare än ett schema som spricker.', title_vi = 'Luật "Con tự làm!" 👟', body_vi = 'Bé muốn tự buộc dây giày, còn mẹ đã trễ 10 phút để ra khỏi nhà. Đừng vội. Một cái tôi không bị tổn thương quan trọng cho sự phát triển của bé hơn nhiều so với một lịch trình bị lỡ.', title_zh = '“我自己来！”法则 👟', body_zh = '想自己系鞋带，而你们出门已经晚了10分钟。别催。对宝宝的成长来说，一个没受伤的自我，比一个被打乱的时间表重要得多。' WHERE id = '8949a363-0fca-4998-bc28-ec5b3f0fc9b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder místico del susurro 🤫', body_es = 'Está tan activo en la cama que no se duerme. En lugar de levantar la voz, baja de golpe el tono y háblale en susurros. Cuando el niño se concentra para oírte, su cerebro pasa automáticamente al modo sueño.', title_fr = 'Le pouvoir mystérieux du chuchotement 🤫', body_fr = 'Il est si agité dans son lit qu''il ne s''endort pas. Au lieu d''élever la voix, baissez soudain le ton et parlez en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau passe automatiquement en mode sommeil.', title_hi = 'फुसफुसाहट की रहस्यमयी ताकत 🤫', body_hi = 'बिस्तर में इतना सक्रिय है कि सो ही नहीं रहा। आवाज़ ऊँची करने के बजाय अचानक अपना लहजा धीमा कर दीजिए, फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए ध्यान लगाता है, तो उसका दिमाग अपने-आप नींद के मोड में चला जाता है।', title_id = 'Kekuatan ajaib bisikan 🤫', body_id = 'Ia begitu aktif di tempat tidur sampai tidak bisa tidur. Daripada meninggikan suara, turunkan nada suara Anda secara tiba-tiba dan bicaralah sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis beralih ke mode tidur.', title_ja = 'ささやきのふしぎな力 🤫', body_ja = 'ベッドの上で元気いっぱいで、なかなか寝ない。声を大きくする代わりに、急に声のトーンを落としてささやいてみましょう。あなたの声を聞こうと集中すると、脳は自然と眠りモードに切りかわります。', title_ko = '속삭임의 신비한 힘 🤫', body_ko = '침대에서 너무 활발해서 잠들지 않나요? 목소리를 높이는 대신 갑자기 톤을 낮춰 속삭이듯 말하세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 수면 모드로 바뀌어요.', title_nl = 'De mystieke kracht van fluisteren 🤫', body_nl = 'Is hij in bed zo actief dat hij niet in slaap valt? Verhef je stem niet, maar ga ineens zachter praten en fluister. Als hij zijn aandacht richt om je te verstaan, schakelt zijn brein automatisch over naar de slaapstand.', title_pl = 'Tajemnicza moc szeptu 🤫', body_pl = 'W łóżku jest tak aktywny, że nie zasypia. Zamiast podnosić głos, nagle go obniż i mów szeptem. Gdy dziecko skupia się, żeby cię usłyszeć, jego mózg automatycznie przechodzi w tryb snu.', title_pt = 'O poder místico do sussurro 🤫', body_pt = 'Está tão ativo na cama que não adormece. Em vez de levantar a voz, baixe de repente o tom e fale a sussurrar. Quando a criança se concentra para a ouvir, o cérebro passa automaticamente para o modo de sono.', title_sv = 'Viskningens mystiska kraft 🤫', body_sv = 'Barnet är så aktivt i sängen att det inte somnar. Istället för att höja rösten, sänk plötsligt tonen och viska. När barnet koncentrerar sig för att höra dig går hjärnan automatiskt över i sömnläge.', title_vi = 'Sức mạnh huyền bí của lời thì thầm 🤫', body_vi = 'Bé hiếu động trên giường đến mức không chịu ngủ. Thay vì lớn tiếng, hãy bất ngờ hạ giọng và nói thì thầm. Khi bé tập trung để nghe mẹ, não bé sẽ tự động chuyển sang chế độ ngủ.', title_zh = '悄悄话的神奇力量 🤫', body_zh = '在床上太活跃，怎么都睡不着。与其提高嗓门，不如突然压低声音，用悄悄话说话。宝宝集中注意力想听清你时，大脑会自动切换到睡眠模式。' WHERE id = 'b6dabad1-9ff8-435e-b107-865df601701d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La paz de la noche 🛁', body_es = 'De tanto correr todo el día, estáis agotados los dos. Durante el baño templado pon de fondo sonidos relajantes de la naturaleza. La armonía del agua preparará para un sueño profundo incluso al niño más tozudo.', title_fr = 'La sérénité du soir 🛁', body_fr = 'À force de courir toute la journée, vous êtes épuisés tous les deux. Pendant le bain tiède, mettez des sons apaisants de la nature en fond. L''harmonie de l''eau préparera même l''enfant le plus têtu à un sommeil profond.', title_hi = 'रात का सुकून 🛁', body_hi = 'दिनभर भागते-भागते आप दोनों थक चुके हैं। गुनगुने पानी से नहलाते समय पीछे प्रकृति की सुकून भरी आवाज़ें चलाइए। पानी का तालमेल सबसे ज़िद्दी बच्चे को भी गहरी नींद के लिए तैयार कर देगा।', title_id = 'Damai di malam hari 🛁', body_id = 'Seharian berlari membuat ia dan Anda sama-sama kehabisan tenaga. Saat mandi air hangat, putar suara alam yang menenangkan sebagai latar. Harmoni air akan menyiapkan anak yang paling keras kepala sekalipun untuk tidur nyenyak.', title_ja = '夜のやすらぎ 🛁', body_ja = '一日じゅう走りまわって、この子もあなたもくたくたですね。ぬるめのお風呂に入りながら、落ち着く自然の音を流しましょう。水のハーモニーが、いちばんがんこな子さえも深い眠りへと導いてくれます。', title_ko = '밤의 평온 🛁', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤나요? 따뜻한 물로 목욕할 때 배경에 차분한 자연의 소리를 틀어 주세요. 물의 조화가 가장 고집 센 아이도 깊은 잠으로 이끌어 줄 거예요.', title_nl = 'Rust in de avond 🛁', body_nl = 'Jullie zijn allebei uitgeput van een hele dag rennen. Zet tijdens een lauw bad rustgevende natuurgeluiden op de achtergrond aan. De harmonie van het water maakt zelfs het koppigste kind klaar voor een diepe slaap.', title_pl = 'Wieczorny spokój 🛁', body_pl = 'Po całym dniu biegania jesteście oboje wykończeni. Podczas ciepłej kąpieli włącz w tle kojące odgłosy natury. Harmonia wody przygotuje do głębokiego snu nawet najbardziej upartego malucha.', title_pt = 'A paz da noite 🛁', body_pt = 'Depois de correrem o dia inteiro, estão os dois esgotados. Durante o banho morno, ponha de fundo sons calmantes da natureza. A harmonia da água vai preparar para um sono profundo até a criança mais teimosa.', title_sv = 'Kvällens lugn 🛁', body_sv = 'Både barnet och du är helt slut efter att ha sprungit hela dagen. Sätt på lugnande naturljud i bakgrunden under det ljumma badet. Vattnets harmoni förbereder även det envisaste barn för djup sömn.', title_vi = 'Bình yên của đêm 🛁', body_vi = 'Chạy nhảy cả ngày khiến cả bé lẫn mẹ kiệt sức. Khi tắm nước ấm, hãy bật nền những âm thanh thiên nhiên êm dịu. Sự hài hòa của nước sẽ đưa ngay cả đứa trẻ bướng bỉnh nhất vào giấc ngủ sâu.', title_zh = '夜晚的宁静 🛁', body_zh = '跑了一整天，宝宝和你都累坏了。洗温水澡时，在背景里放一些舒缓的大自然声音。水的和谐能让最倔强的孩子也做好进入深睡的准备。' WHERE id = '222c5b3e-e10d-4be3-be74-5b7c060039a8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saturación de contacto 🔋', body_es = 'Todo el día se te sube encima, pide brazos y juega con tu pelo. Y tú solo quieres un poco de espacio físico. La saturación de contacto («touched out») es real. Tienes derecho a retirarte sola a una habitación al menos 15 minutos.', title_fr = 'La saturation du toucher 🔋', body_fr = 'Toute la journée, il vous grimpe dessus, réclame des câlins et joue avec vos cheveux. Et vous, vous voulez simplement un peu d''espace physique. La saturation du toucher (« touched out ») est bien réelle. Vous avez le droit de vous retirer seule dans une pièce au moins 15 minutes.', title_hi = 'छुए जाने की थकान 🔋', body_hi = 'दिनभर आप पर चढ़ता है, गोद माँगता है और आपके बालों से खेलता है। और आपको बस थोड़ी शारीरिक दूरी चाहिए। छुए जाने की थकान (टच्ड आउट) सच है। कम से कम 15 मिनट अकेले किसी कमरे में जाने का आपको हक है।', title_id = 'Lelah disentuh 🔋', body_id = 'Seharian ia memanjat tubuh Anda, minta digendong, dan memainkan rambut Anda. Anda hanya ingin sedikit ruang fisik. Lelah disentuh (touched out) itu nyata. Anda berhak menyendiri di sebuah ruangan setidaknya 15 menit.', title_ja = 'さわられ疲れ 🔋', body_ja = '一日じゅう体によじのぼって、抱っこをせがみ、髪の毛で遊ぶ。あなたはただ、体ひとつぶんの距離がほしいだけですよね。さわられ疲れ（touched out）は本当にあります。せめて15分、ひとりで別の部屋にこもる権利があなたにはあります。', title_ko = '스킨십 피로 🔋', body_ko = '하루 종일 몸에 기어오르고, 안아 달라 하고, 머리카락을 만지작거리나요? 엄마는 그저 몸의 여유 공간이 필요할 뿐이죠. 스킨십 피로(touched out)는 진짜예요. 적어도 15분은 혼자 방에 들어가 있을 자격이 있어요.', title_nl = 'Aanraakmoeheid 🔋', body_nl = 'De hele dag klimt hij op je, wil hij op schoot en speelt hij met je haar. En jij wilt gewoon even lichamelijke ruimte. Aanraakmoeheid (touched out) is echt. Je hebt het recht om je minstens 15 minuten alleen in een kamer terug te trekken.', title_pl = 'Zmęczenie dotykiem 🔋', body_pl = 'Cały dzień się na ciebie wspina, chce się przytulać i bawi się twoimi włosami. A ty chcesz po prostu odrobiny fizycznej przestrzeni. Zmęczenie dotykiem (touched out) jest prawdziwe. Masz prawo zaszyć się w pokoju sama choćby na 15 minut.', title_pt = 'Cansaço de toque 🔋', body_pt = 'O dia inteiro trepa por si, pede colo e brinca com o seu cabelo. E a mãe só quer algum espaço físico. O cansaço de toque ("touched out") é real. Tem direito a retirar-se sozinha para uma divisão pelo menos 15 minutos.', title_sv = 'Beröringströtthet 🔋', body_sv = 'Hela dagen klättrar barnet på dig, vill bli buret och leker med ditt hår. Och du vill bara ha lite fysiskt utrymme. Beröringströtthet (touched out) är verklig. Du har rätt att dra dig undan ensam i ett rum i åtminstone 15 minuter.', title_vi = 'Mệt vì bị chạm vào 🔋', body_vi = 'Cả ngày bé trèo lên người mẹ, đòi bế và nghịch tóc mẹ. Còn mẹ chỉ muốn có chút khoảng trống cho riêng mình. Cảm giác mệt vì bị chạm vào liên tục (touched out) là có thật. Mẹ hoàn toàn có quyền ở một mình trong phòng ít nhất 15 phút.', title_zh = '被触碰到疲惫 🔋', body_zh = '一整天宝宝都往你身上爬，要抱抱，玩你的头发。而你只想要一点身体上的空间。“触碰疲劳”（touched out）是真实存在的。你有权利至少一个人在房间里待上15分钟。' WHERE id = '658a0f7f-5501-4d36-97c8-25ebf4c2bf93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo al desagüe de la bañera 🛀', body_es = '¿El niño que antes no quería salir del agua de repente se asusta del desagüe de la bañera y llora? A medida que crece la imaginación, aparecen miedos sin motivo. Tapa el desagüe con un juguete de plástico y dale seguridad.', title_fr = 'La peur du trou de la baignoire 🛀', body_fr = 'Lui qui ne voulait jamais sortir de l''eau s''est soudain mis à pleurer, effrayé par le trou d''évacuation de la baignoire ? En se développant, l''imagination fait naître des peurs infondées. Couvrez le trou avec un jouet en plastique pour le rassurer.', title_hi = 'बाथटब के छेद का डर 🛀', body_hi = 'जो बच्चा पहले पानी से निकलता ही नहीं था, अचानक बाथटब के पानी निकलने वाले छेद से डरकर रोने लगा? कल्पना बढ़ने के साथ बेवजह के डर भी आते हैं। छेद को प्लास्टिक के खिलौने से ढककर उसे भरोसा दिलाइए।', title_id = 'Takut lubang bak mandi 🛀', body_id = 'Anak yang dulu tak mau keluar dari air tiba-tiba menangis karena takut lubang pembuangan di bak mandi? Seiring berkembangnya imajinasi, muncul ketakutan yang tidak beralasan. Tutup lubangnya dengan mainan plastik dan beri ia rasa aman.', title_ja = 'お風呂の排水口がこわい 🛀', body_ja = '前はお湯から出たがらなかったのに、急にバスタブの排水口がこわくて泣くようになった？想像力が育つにつれて、根拠のない怖さが生まれます。排水口をプラスチックのおもちゃでふさいで、安心させてあげましょう。', title_ko = '욕조 배수구 공포 🛀', body_ko = '물에서 나오지 않던 아이가 갑자기 욕조 배수구가 무섭다고 우나요? 상상력이 자랄수록 근거 없는 두려움도 생겨요. 배수구를 플라스틱 장난감으로 덮어 안심시켜 주세요.', title_nl = 'Bang voor het afvoerputje 🛀', body_nl = 'Wilde hij eerst nooit uit bad, en is hij nu ineens huilend bang voor het afvoerputje? Naarmate zijn fantasie groeit, ontstaan er onterechte angsten. Leg een plastic speeltje over het putje en geef hem vertrouwen.', title_pl = 'Strach przed odpływem 🛀', body_pl = 'Dziecko, którego kiedyś nie dało się wyciągnąć z wody, nagle boi się odpływu w wannie i płacze? Wraz z rozwojem wyobraźni pojawiają się nieuzasadnione lęki. Zakryj odpływ plastikową zabawką i daj mu poczucie bezpieczeństwa.', title_pt = 'Medo do ralo da banheira 🛀', body_pt = 'A criança que antes não queria sair da água começou de repente a chorar com medo do ralo da banheira? À medida que a imaginação se desenvolve, surgem medos sem razão. Tape o ralo com um brinquedo de plástico e dê-lhe segurança.', title_sv = 'Rädd för avloppet i badkaret 🛀', body_sv = 'Barnet som förut inte ville gå upp ur vattnet blev plötsligt rädd för avloppshålet i badkaret och började gråta? När fantasin utvecklas uppstår obefogade rädslor. Täck över hålet med en plastleksak och ge barnet trygghet.', title_vi = 'Nỗi sợ lỗ thoát nước 🛀', body_vi = 'Bé trước đây không chịu ra khỏi bồn tắm, giờ bỗng khóc vì sợ lỗ thoát nước? Khi trí tưởng tượng phát triển, những nỗi sợ vô cớ sẽ xuất hiện. Hãy che lỗ thoát nước bằng một món đồ chơi nhựa để bé yên tâm.', title_zh = '害怕浴缸的下水孔 🛀', body_zh = '以前泡在水里都不肯出来，现在突然害怕浴缸的下水孔，哭了起来？想象力发展时，会出现一些莫名的恐惧。用塑料玩具把下水孔盖住，给宝宝安全感。' WHERE id = 'fd872988-ca1c-4392-86ef-3fa893d01f3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Ahora deja a un lado las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema que no sea el niño, los problemas ni los gastos. ¡Antes que padres, sois una pareja!', body_fr = 'L''enfant dort. Maintenant, mettez de côté les tâches ménagères. Parlez avec votre partenaire au moins 20 minutes de n''importe quel sujet, sauf de l''enfant, des problèmes et des dépenses. Avant d''être parents, vous êtes un couple !', body_hi = 'बच्चा सो गया। अब घर के काम एक तरफ़ रख दीजिए। अपने साथी के साथ कम से कम 20 मिनट, बच्चे, समस्याओं और खर्चों के अलावा किसी भी विषय पर बात कीजिए। माता-पिता बनने से पहले आप एक जोड़ा हैं!', body_id = 'Anak sudah tidur. Sekarang singkirkan pekerjaan rumah. Mengobrollah dengan pasangan minimal 20 menit tentang topik apa saja selain anak, masalah, dan pengeluaran. Sebelum menjadi orang tua, kalian adalah sepasang kekasih!', body_ja = '子どもが寝ました。家事はいったん脇に置いて。パートナーと少なくとも20分、子どもや悩みごと、お金以外の話題でおしゃべりしましょう。ふたりは親である前に、カップルなんです！', body_ko = '아이가 잠들었어요. 이제 집안일은 내려놓으세요. 배우자와 적어도 20분은 아이, 문제, 지출 말고 다른 주제로 이야기해 보세요. 두 사람은 부모이기 전에 부부였어요!', body_nl = 'Je kind slaapt. Leg het huishouden nu opzij. Praat minstens 20 minuten met je partner over iets anders dan het kind, problemen en uitgaven. Jullie waren een stel voordat jullie ouders werden!', body_pl = 'Dziecko śpi. Teraz odłóż obowiązki domowe. Porozmawiaj z partnerem przez co najmniej 20 minut o czymkolwiek poza dzieckiem, problemami i wydatkami. Zanim zostaliście rodzicami, byliście parą!', body_pt = 'A criança adormeceu. Agora ponha de lado as tarefas da casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto que não seja a criança, os problemas ou as despesas. Antes de serem pais, são um casal!', body_sv = 'Barnet sover. Lägg nu undan hushållssysslorna. Prata med din partner i minst 20 minuter om vad som helst utom barnet, problem och utgifter. Innan ni blev föräldrar var ni ett par!', body_vi = 'Bé đã ngủ. Giờ hãy gác việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào, ngoài con cái, những vấn đề và chi tiêu. Trước khi làm bố mẹ, hai người đã là một cặp đôi!', body_zh = '宝宝睡着了。现在把家务放到一边。和伴侣至少聊20分钟孩子、烦恼和开销以外的任何话题。在成为父母之前，你们首先是一对恋人！' WHERE id = '380c78ab-6c26-4edf-8c80-e7615f9b4b80' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas con objetos 🗣️', body_es = 'En el parque le cuenta cosas muy en serio a una piedra, o en casa a una silla, y hasta les riñe. A través del juego simbólico procesa el mundo. Anota sin falta estos guiones tan especiales en el Seguimiento del desarrollo.', title_fr = 'Conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et les gronde ? Il comprend le monde à travers le jeu symbolique. Notez absolument ces scénarios particuliers dans le Suivi de développement.', title_hi = 'बेजान चीज़ों से बातचीत 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ कहता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया को समझ रहा है। उसकी इन खास कहानियों को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Mengobrol dengan benda mati 🗣️', body_id = 'Di taman ia berbicara serius dengan sebuah batu, atau di rumah memarahi kursi. Lewat permainan simbolis, ia mengolah dunia. Pastikan menandai skenario istimewanya ini di Pelacak Perkembangan.', title_ja = 'ものとのおしゃべり 🗣️', body_ja = '公園の石や家のいすに、すっかり真剣に話しかけたり、しかったりしています。象徴遊びを通して世界を整理しているんです。この特別なシナリオを、ぜひ「発達トラッカー」に記録しておきましょう。', title_ko = '사물과의 대화 🗣️', body_ko = '공원의 돌이나 집의 의자에게 아주 진지하게 무언가를 이야기하고 혼내기도 하나요? 상징 놀이로 세상을 소화하는 중이에요. 이 특별한 시나리오를 성장 기록에 꼭 표시해 두세요.', title_nl = 'Gesprekken met dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld. Noteer deze bijzondere scenario''s zeker in de Groeitracker.', title_pl = 'Rozmowy z przedmiotami 🗣️', body_pl = 'W parku zupełnie poważnie coś opowiada kamieniowi albo w domu beszta krzesło. Przez zabawę symboliczną przetwarza świat. Koniecznie zaznacz te wyjątkowe scenariusze w Śledzeniu rozwoju.', title_pt = 'Conversas com objetos 🗣️', body_pt = 'No parque, fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo. Não deixe de registar estes enredos especiais no Registo de Crescimento.', title_sv = 'Samtal med livlösa saker 🗣️', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen. Anteckna absolut barnets speciella scenarier i Utvecklingsspåraren.', title_vi = 'Trò chuyện với đồ vật 🗣️', body_vi = 'Ở công viên, bé nói chuyện rất nghiêm túc với một hòn đá, ở nhà thì "mắng" chiếc ghế? Bé đang xử lý thế giới qua trò chơi biểu tượng. Hãy nhớ đánh dấu những kịch bản đặc biệt này trong Theo dõi phát triển.', title_zh = '和没有生命的东西聊天 🗣️', body_zh = '在公园对着一块石头、在家对着一把椅子，非常认真地说着什么，还训它们。宝宝通过象征性游戏来理解世界。一定要把这些特别的小剧本记在发育追踪里。' WHERE id = '752bc100-4fdb-4f78-84aa-dd9676151255' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de él. En cuanto se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el pilar de la casa, y los pilares también necesitan recuperarse.', body_fr = 'Vous êtes restée debout toute la journée et votre dos est en miettes à force de courir après lui. Dès que l''enfant dort, demandez à votre partenaire 10 minutes de massage des épaules. Vous êtes le pilier de la maison, et les piliers ont besoin d''être restaurés.', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते कमर टूट रही है। बच्चे के सोते ही अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप घर का खंभा हैं, और खंभों को भी फिर से मज़बूत होना ज़रूरी है।', body_id = 'Hari ini kamu terlalu lama berdiri, punggungmu serasa patah karena mengejarnya. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasanganmu. Kamu tiang rumah ini, dan tiang pun wajib dipulihkan.', body_ja = '今日は立ちっぱなしで、追いかけまわして腰がくたくたですね。子どもが寝たらすぐ、パートナーに10分の肩もみをお願いして。あなたはこの家の柱です。柱だって、ちゃんと回復しなくちゃ。', body_ko = '오늘 하루 종일 서 있었고 아이를 쫓아다니느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 이 집의 기둥이고, 기둥도 꼭 회복이 필요해요.', body_nl = 'Je hebt vandaag veel op je benen gestaan en je rug breekt van het achter hem aan rennen. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de pijler van het huis, en pijlers moeten ook hersteld worden.', body_pl = 'Dziś długo byłaś na nogach, plecy bolą cię od biegania za nim. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś filarem domu, a filary też muszą się regenerować.', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de tanto correr atrás dele. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o pilar desta casa, e os pilares também precisam de ser restaurados.', body_sv = 'Du har stått på benen länge i dag och ryggen värker av allt springande efter barnet. Så fort barnet somnar, be din partner om 10 minuters axelmassage. Du är hemmets pelare, och pelare måste också återhämta sig.', body_vi = 'Hôm nay mẹ đứng cả ngày, lưng như muốn gãy vì chạy theo bé. Ngay khi bé ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là trụ cột của gia đình, và trụ cột thì nhất định phải được phục hồi.', body_zh = '今天你站了太久，追着宝宝跑得腰都快断了。宝宝一睡着，就请伴侣给你按摩10分钟肩膀。你是这个家的顶梁柱，顶梁柱也一定要好好修复。' WHERE id = '7bfbea7d-ee3e-4b33-88e0-e90f78f2538d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica para retrasar el sueño ⏱️', body_es = '¿Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared? Pon un temporizador. Aplica la norma «cuando suena la campanita, todos a dormir» y líbrate con paciencia de esta despedida sin fin.', title_fr = 'Tactiques pour retarder le dodo ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde dort » et échappez avec patience à ces adieux sans fin.', title_hi = 'नींद टालने की चाल ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है? टाइमर लगाइए। ‘घंटी बजते ही सब सो जाते हैं’ का नियम लागू करके इस अंतहीन अलविदा से धैर्य के साथ बच निकलिए।', title_id = 'Taktik menunda tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua tidur'' dan bebaskan diri dengan sabar dari perpisahan tanpa akhir ini.', title_ja = '寝る時間を遅らせる作戦 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり？タイマーをセットしましょう。「ベルが鳴ったらみんな寝る」のルールで、この終わらないおやすみのあいさつから根気よく抜け出して。', title_ko = '잠 미루기 작전 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 잔다'' 규칙을 정해 이 끝없는 작별 인사에서 차분하게 벗어나세요.', title_nl = 'Uitsteltactieken voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaat iedereen slapen'' in en verlos jezelf geduldig van dit eindeloze afscheid.', title_pl = 'Taktyka odwlekania snu ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą? Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy śpią” i cierpliwie uwolnij się od tych niekończących się pożegnań.', title_pt = 'Táticas para adiar o sono ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede? Programe um temporizador. Aplique a regra "quando a campainha toca, todos dormem" e livre-se com paciência desta despedida sem fim.', title_sv = 'Taktiken att skjuta upp sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla” och rädda dig tålmodigt från det ändlösa farvälet.', title_vi = 'Chiến thuật trì hoãn giấc ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà đi ngủ" để kiên nhẫn thoát khỏi những lời tạm biệt bất tận này.', title_zh = '拖延睡觉的战术 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见？设个计时器。立下“铃声一响，大家都睡觉”的规矩，耐心地摆脱这没完没了的告别吧。' WHERE id = '14bae514-5bcb-45ca-923d-75a7333cefe5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Has pensado menús distintos para que él coma y tú te has vuelto a quedar con hambre? Elige en Recetas saludables una comida rica en hierro y calcio que se prepara en 10 minutos y siéntete valorada.', body_fr = 'Vous avez imaginé différents menus pour le nourrir, et vous, vous êtes encore restée le ventre vide ? Choisissez dans les Recettes saines un repas riche en fer et en calcium, prêt en 10 minutes, et prenez soin de vous.', body_hi = 'उसका पेट भरने के लिए अलग-अलग मेन्यू सोचे, और आप फिर से भूखी रह गईं? सेहतमंद रेसिपी से 10 मिनट में बनने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और खुद को कीमती महसूस कीजिए।', body_id = 'Anda memikirkan berbagai menu untuk membuatnya kenyang, tapi Anda sendiri kelaparan lagi? Pilih makan siang kaya zat besi dan kalsium dari Resep Sehat yang siap dalam 10 menit, dan rasakan bahwa Anda berharga.', body_ja = 'この子のためにいろいろなメニューを考えたのに、自分はまた食べそびれた？「ヘルシーレシピ」から10分でできる、鉄分とカルシウムたっぷりのランチを選んで、自分を大切にしましょう。', body_ko = '아이를 먹이려고 여러 메뉴를 고민했는데 정작 엄마는 또 굶었나요? 건강한 레시피에서 10분이면 만드는 철분과 칼슘이 풍부한 식사를 골라 나를 소중히 대해 주세요.', body_nl = 'Verschillende menu''s bedacht om hem te eten te geven, maar zelf weer niets gegeten? Kies uit Gezonde recepten een ijzer- en calciumrijke lunch die in 10 minuten klaar is, en voel dat je ertoe doet.', body_pl = 'Wymyśliłaś różne menu, żeby go nakarmić, a sama znowu zostałaś głodna? Wybierz ze Zdrowych przepisów obiad bogaty w żelazo i wapń, gotowy w 10 minut, i poczuj, że jesteś ważna.', body_pt = 'Pensou em menus diferentes para ele comer, mas a mãe voltou a ficar com fome? Escolha nas Receitas Saudáveis um almoço rico em ferro e cálcio, pronto em 10 minutos, e sinta-se valorizada.', body_sv = 'Du hittade på olika menyer för att få barnet mätt, men själv blev du hungrig igen? Välj en järn- och kalciumrik lunch som tar 10 minuter bland Hälsosamma recept och känn dig värdefull.', body_vi = 'Mẹ nghĩ ra nhiều thực đơn khác nhau để bé ăn no, còn bản thân thì lại nhịn đói? Hãy chọn một bữa trưa giàu sắt và canxi, nấu trong 10 phút từ Công thức lành mạnh, và cảm nhận giá trị của chính mình.', body_zh = '为了喂饱宝宝想了各种不同的菜单，结果自己又饿着？从健康食谱里挑一道10分钟就能做好、富含铁和钙的午餐，让自己感受到被珍视。' WHERE id = '4ec63d29-5d5a-4c61-aeca-3683d2926fad' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ayudante de la lavadora 🧺', body_es = 'Tú doblas la ropa con mucho esfuerzo y él, «ayudando», la vuelve a esparcir por toda la habitación. En lugar de enfadarte, convierte la tarea en un juego: «¿A ver quién echa antes estos calcetines a la cesta?».', title_fr = 'Le petit assistant de la machine à laver 🧺', body_fr = 'Vous pliez le linge avec beaucoup d''efforts, et lui, sous prétexte de vous aider, éparpille tout à nouveau dans la pièce. Au lieu de vous énerver, transformez la tâche en jeu : « Voyons qui mettra ces chaussettes le plus vite dans le panier ! »', title_hi = 'वॉशिंग मशीन का सहायक 🧺', body_hi = 'आप बड़ी मेहनत से कपड़े तह करती हैं, और वह ‘मदद कर रहा हूँ’ कहकर सब फिर से कमरे में बिखेर देता है। नाराज़ होने के बजाय काम को खेल बना दीजिए: ‘देखें, ये मोज़े टोकरी में सबसे पहले कौन डालता है?’', title_id = 'Asisten mesin cuci 🧺', body_id = 'Anda melipat baju dengan susah payah, sementara ia ''membantu'' dengan menyebarkannya lagi ke seluruh kamar. Daripada kesal, jadikan permainan: ''Ayo lihat siapa yang paling cepat memasukkan kaus kaki ini ke keranjang!''', title_ja = '洗濯機のお手伝い係 🧺', body_ja = 'あなたが一生けんめい洗濯物をたたんでいると、「お手伝いする」と言って全部また部屋にばらまいてしまう。怒る代わりに、お仕事を遊びに変えましょう：「どっちが早くこの靴下をかごに入れられるかな？」', title_ko = '빨래 도우미 🧺', body_ko = '애써 빨래를 개고 있는데 ''도와줄게'' 하며 전부 다시 방에 흩뿌리나요? 화내는 대신 놀이로 바꿔 보세요: ''누가 이 양말을 더 빨리 바구니에 넣나 볼까?''', title_nl = 'Hulpje bij de wasmachine 🧺', body_nl = 'Jij vouwt met veel moeite de was op, en hij zegt ''ik help'' en strooit alles weer door de kamer. Word niet boos, maar maak er een spel van: ''Wie gooit deze sokken het snelst in de mand?''', title_pl = 'Pomocnik przy praniu 🧺', body_pl = 'Z wielkim trudem składasz ubrania, a on „pomaga” i znowu rozrzuca wszystko po pokoju. Zamiast się złościć, zamień to w zabawę: „Zobaczmy, kto szybciej wrzuci te skarpetki do kosza?”.', title_pt = 'O ajudante da máquina de lavar 🧺', body_pt = 'Dobra a roupa com muito esforço e ele, a dizer "estou a ajudar", espalha-a outra vez pelo quarto. Em vez de se irritar, transforme a tarefa num jogo: "Vamos ver quem põe estas meias mais depressa no cesto?"', title_sv = 'Tvättmaskinshjälparen 🧺', body_sv = 'Du viker kläderna med stor möda, och barnet säger ”jag hjälper till” och sprider ut allt i rummet igen. Istället för att bli arg, gör om sysslan till en lek: ”Får se vem som kastar de här strumporna i korgen snabbast?”', title_vi = 'Trợ thủ giặt giũ 🧺', body_vi = 'Mẹ vất vả gấp quần áo, còn bé nói "Con giúp mẹ" rồi lại vung hết ra khắp phòng. Thay vì bực mình, hãy biến việc này thành trò chơi: "Xem ai ném tất vào giỏ nhanh hơn nào?"', title_zh = '洗衣小帮手 🧺', body_zh = '你辛辛苦苦叠好衣服，宝宝却说“我来帮忙”，把它们又撒满一屋子。与其生气，不如把活儿变成游戏：“看谁能更快把这些袜子扔进篮子里？”' WHERE id = 'd6b3a2c2-7743-47f8-927a-59220b3461a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Moda de vanguardia 👗', body_es = '¿Se ha puesto unos pantalones cortos de verano encima del jersey de invierno y no quiere quitárselos? No pasa nada. El niño que sale a la calle con un conjunto que no pega es, en realidad, un niño que defiende con valentía su decisión. No rompas su voluntad.', title_fr = 'Une mode avant-gardiste 👗', body_fr = 'Il a enfilé un short d''été par-dessus son pull d''hiver et ne veut pas l''enlever ? Aucun mal à ça. Un enfant qui sort habillé de façon décalée est en réalité un enfant qui défend courageusement sa décision. Ne brisez pas sa volonté.', title_hi = 'अवांगार्द फ़ैशन की समझ 👗', body_hi = 'सर्दियों के स्वेटर के ऊपर गर्मियों के शॉर्ट्स पहन लिए और उतारना नहीं चाहता? कोई बात नहीं। बेमेल कपड़ों में लोगों के बीच जाने वाला बच्चा असल में अपने फ़ैसले का हिम्मत से बचाव करने वाला बच्चा है। उसकी इच्छा मत तोड़िए।', title_id = 'Gaya busana avant-garde 👗', body_id = 'Ia memakai celana pendek musim panas di atas sweter musim dingin dan tak mau melepasnya? Tidak apa-apa. Anak yang keluar dengan pakaian tak serasi sebenarnya anak yang berani membela keputusannya sendiri. Jangan patahkan kemauannya.', title_ja = 'アバンギャルドなファッション 👗', body_ja = '冬のセーターの上に夏の短パンをはいて、脱ぎたがらない？大丈夫です。ちぐはぐな服で人前に出る子は、本当は自分の決めたことを堂々と守っている子。意志をくじかないであげて。', title_ko = '아방가르드 패션 감각 👗', body_ko = '겨울 스웨터 위에 여름 반바지를 입고 벗지 않겠다고 하나요? 괜찮아요. 어울리지 않는 옷차림으로 나서는 아이는 사실 자기 결정을 용감하게 지키는 아이예요. 의지를 꺾지 마세요.', title_nl = 'Avant-gardistische mode 👗', body_nl = 'Draagt hij een zomershort over zijn wintertrui en wil hij hem niet uittrekken? Geen probleem. Een kind dat in een onpassende outfit naar buiten gaat, is eigenlijk een kind dat moedig zijn eigen beslissing verdedigt. Breek zijn wil niet.', title_pl = 'Awangardowa moda 👗', body_pl = 'Założył letnie szorty na zimowy sweter i nie chce ich zdjąć? Nic nie szkodzi. Dziecko, które wychodzi między ludzi w niepasującym stroju, tak naprawdę odważnie broni własnej decyzji. Nie łam jego woli.', title_pt = 'Moda de vanguarda 👗', body_pt = 'Vestiu uns calções de verão por cima da camisola de inverno e não os quer tirar? Não faz mal. A criança que sai à rua com roupa desajustada é, na verdade, uma criança que defende a sua decisão com coragem. Não quebre a vontade dele.', title_sv = 'Avantgardistiskt mode 👗', body_sv = 'Har barnet tagit sommarshorts utanpå vintertröjan och vill inte ta av dem? Det gör inget. Ett barn som går ut bland folk i omatchade kläder är egentligen ett barn som modigt försvarar sitt beslut. Knäck inte barnets vilja.', title_vi = 'Phong cách thời trang tiên phong 👗', body_vi = 'Bé mặc quần đùi mùa hè bên ngoài áo len mùa đông và không chịu cởi ra? Chẳng hại gì cả. Đứa trẻ dám ra ngoài với bộ đồ "không hợp" thật ra là đứa trẻ dũng cảm bảo vệ quyết định của mình. Đừng bẻ gãy ý chí của bé.', title_zh = '前卫的时尚观 👗', body_zh = '在冬天的毛衣外面套上夏天的短裤，还不肯脱？没关系。穿着不搭的衣服出门的孩子，其实是勇敢捍卫自己决定的孩子。别挫伤宝宝的意志。' WHERE id = '95036444-eb4a-4cd7-a33d-678f3daaa180' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Se ha despertado en mitad de la noche llorando con los ojos cerrados y no oye a nadie. Confírmalo con el Análisis del llanto; si es un terror nocturno, no intentes despertarle. Quédate a su lado y dale seguridad en silencio.', body_fr = 'Il s''est réveillé en pleine nuit en pleurant, les yeux fermés, sans entendre personne. Vérifiez avec l''Analyse des pleurs : s''il s''agit d''une terreur nocturne, n''essayez pas de le réveiller. Restez simplement près de lui et rassurez-le en silence.', body_hi = 'आधी रात आँखें बंद किए रोते हुए जागा और किसी की नहीं सुनता। क्राइंग एनालिसिस से पुष्टि कीजिए; अगर यह नाइट टेरर है, तो उसे जगाने की कोशिश मत कीजिए। बस पास रहकर चुपचाप भरोसा दीजिए।', body_id = 'Tengah malam ia terbangun menangis dengan mata terpejam dan tidak mendengar siapa pun. Pastikan dengan Analisis Tangisan; jika ini teror tidur (night terror), jangan mencoba membangunkannya. Cukup berada di sampingnya dan beri rasa aman tanpa bersuara.', body_ja = '夜中に目を閉じたまま泣いて起き、誰の声も聞こえていない様子。「泣き声分析」で確かめてみましょう。もし夜驚症なら、起こそうとしないで。ただそばにいて、静かに安心させてあげて。', body_ko = '한밤중에 눈을 감은 채 울며 깨어나 아무 말도 듣지 못하나요? 울음 분석으로 확인해 보세요. 야경증이라면 깨우려 하지 말고 곁에서 조용히 안심시켜 주세요.', body_nl = 'Werd hij midden in de nacht huilend wakker met zijn ogen dicht, en hoort hij niemand? Controleer het met Huilanalyse; als het een nachtmerrie-aanval (pavor nocturnus) is, probeer hem dan niet wakker te maken. Blijf gewoon bij hem en geef hem in stilte vertrouwen.', body_pl = 'W środku nocy obudził się z płaczem, z zamkniętymi oczami, i nikogo nie słyszy? Potwierdź to Analizą płaczu; jeśli to lęk nocny, nie próbuj go budzić. Po prostu bądź obok i w ciszy dawaj mu poczucie bezpieczeństwa.', body_pt = 'Acordou a meio da noite a chorar, de olhos fechados, e não ouve ninguém. Confirme com a Análise do Choro; se for terror noturno, não tente acordá-lo. Fique apenas ao lado dele e dê-lhe segurança em silêncio.', body_sv = 'Mitt i natten har barnet vaknat gråtande med slutna ögon och hör ingen. Kontrollera med Gråtanalys; om det är nattskräck, försök inte väcka barnet. Var bara nära och ge trygghet i tystnad.', body_vi = 'Nửa đêm bé thức dậy khóc, mắt vẫn nhắm và không nghe thấy ai? Hãy kiểm tra bằng Phân tích tiếng khóc; nếu đó là hoảng sợ khi ngủ (night terror), đừng cố đánh thức bé. Chỉ cần ở bên cạnh và lặng lẽ mang lại cảm giác an toàn.', body_zh = '半夜闭着眼睛哭着醒来，谁的话都听不进去。用哭声分析确认一下；如果是夜惊，别试图叫醒宝宝。只要静静地陪在身边，给宝宝安全感就好。' WHERE id = '98f4059e-feba-4e5c-88c8-f44ceadd630c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, no te fíes solo de lo que ves por la ventana. Con el asistente Tiempo y ropa elige el conjunto más adecuado para el viento y la temperatura reales y sal de casa tranquila y preparada.', body_fr = 'Avant la promenade, ne vous fiez pas à ce que vous voyez par la fenêtre. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et à la température réels, et sortez sereine et bien préparée.', body_hi = 'सैर पर निकलते समय खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े असिस्टेंट से बाहर की असली हवा और गर्मी के लिए सबसे सही कपड़े तय कीजिए और तैयारी के साथ आराम से घर से निकलिए।', body_id = 'Saat akan jalan-jalan, jangan tertipu hanya dengan melihat dari jendela. Gunakan Cuaca dan Pakaian untuk menentukan setelan yang paling cocok dengan angin dan suhu sebenarnya di luar, lalu keluar rumah dengan nyaman dan siap.', body_ja = 'お出かけ前に、窓の外の様子にだまされないで。「天気と服装」で外の本当の風や気温にぴったりのコーデを決めて、しっかり準備して安心して出かけましょう。', body_ko = '산책 나갈 때 창밖만 보고 판단하지 마세요. 날씨와 옷차림 도우미로 실제 바람과 기온에 가장 알맞은 옷차림을 정하고, 든든하게 준비해서 편하게 나가세요.', body_nl = 'Laat je niet misleiden door een blik uit het raam als je gaat wandelen. Bepaal met de assistent Weer en kleding de beste outfit voor de echte wind en temperatuur buiten en ga ontspannen en goed voorbereid de deur uit.', body_pl = 'Przed spacerem nie daj się zwieść widokowi za oknem. Dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do prawdziwego wiatru i temperatury na dworze i wyjdź z domu spokojnie i przygotowana.', body_pt = 'Antes de ir passear, não se deixe enganar pelo que vê da janela. Com o assistente Tempo e Roupa, escolha a combinação mais adequada ao vento e à temperatura reais lá fora e saia de casa tranquila e preparada.', body_sv = 'Låt dig inte luras av att titta ut genom fönstret när ni ska ut på promenad. Med hjälpen Väder och kläder hittar du den klädsel som passar bäst för den verkliga vinden och temperaturen ute, så att ni går ut bekvämt och förberedda.', body_vi = 'Khi chuẩn bị đi dạo, đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ. Hãy dùng Thời tiết và trang phục để chọn bộ đồ phù hợp nhất với gió và nhiệt độ thực tế bên ngoài, rồi ra khỏi nhà thật thoải mái, sẵn sàng.', body_zh = '出门散步前，别只看窗外就被骗了。用天气与穿衣助手，根据外面真实的风力和温度确定最合适的搭配，舒舒服服、有备而出。' WHERE id = 'bfca2126-084c-4371-a225-6bbeaa8fe2d1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La complicidad de la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie. Entra en la Comunidad Anacan y limítate a leer. Ver que otras madres sienten el mismo cansancio te hace sentir «no estoy sola», y esa es la mejor terapia.', title_fr = 'La complicité de la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie de rien expliquer à personne. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir la même fatigue chez d''autres mamans donne le sentiment de ne pas être seule, c''est la meilleure thérapie.', title_hi = 'कम्युनिटी का अपनापन 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। दूसरी माँओं की मिलती-जुलती थकान देखकर ‘मैं अकेली नहीं हूँ’ का एहसास होता है, यही सबसे अच्छी थेरेपी है।', title_id = 'Teman curhat di komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat ibu-ibu lain merasakan lelah yang sama menumbuhkan rasa ''aku tidak sendirian'', dan itu terapi terbaik.', title_ja = 'コミュニティという心の友 💬', body_ja = 'とても疲れていて、誰にも何も説明したくない。そんなときはAnacanコミュニティを開いて、読むだけにしましょう。ほかのママたちの同じような疲れを見ると「ひとりじゃない」と感じられて、いちばんのセラピーになります。', title_ko = '커뮤니티라는 단짝 💬', body_ko = '너무 지쳐서 누구에게도 아무것도 설명하고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들의 비슷한 피로를 보면 ''나만 그런 게 아니구나'' 싶어 최고의 치료가 돼요.', title_nl = 'Vertrouwen in de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen. Ga naar de Anacan Community en lees alleen mee. Zien dat andere mama''s net zo moe zijn geeft je het gevoel ''ik ben niet de enige'' en dat is de beste therapie.', title_pl = 'Zaufanie Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć. Wejdź do Społeczności Anacan i tylko czytaj. Widok podobnego zmęczenia u innych mam daje poczucie „nie jestem sama” i jest najlepszą terapią.', title_pt = 'A cumplicidade da comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém. Entre na Comunidade Anacan e limite-se a ler. Ver o cansaço parecido de outras mães dá a sensação de "não estou sozinha", e essa é a melhor terapia.', title_sv = 'Gemenskapens förtrolighet 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon. Gå in i Anacan Community och bara läs. Att se andra mammors liknande trötthet ger känslan ”jag är inte ensam” och blir den bästa terapin.', title_vi = 'Tâm sự trong Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích gì với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác cũng mệt mỏi giống mình sẽ mang lại cảm giác "mình không đơn độc", đó là liệu pháp tốt nhất.', title_zh = '社区里的知心话 💬', body_zh = '累坏了，什么都不想跟任何人解释？进入Anacan社区，只当个读者就好。看到其他妈妈也有同样的疲惫，会让你觉得“我不是一个人”，这就是最好的疗愈。' WHERE id = '25567149-e2e9-4c4d-aaff-501c9547f638' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto en directo y vecinos 🎤', body_es = 'Con una cuchara en la mano, de pie en medio de la habitación, canta a grito pelado. Que no te importe lo que piensen los vecinos. En tu casa crece una estrella: tú solo aplaude.', title_fr = 'Concert live et voisins 🎤', body_fr = 'Une cuillère à la main, planté au milieu de la pièce, il chante à tue-tête. Ne vous souciez pas de ce que penseront les voisins. Une star grandit chez vous, contentez-vous d''applaudir.', title_hi = 'लाइव कॉन्सर्ट और पड़ोसी 🎤', body_hi = 'हाथ में चम्मच लेकर कमरे के बीच खड़ा होकर पूरी ताकत से चिल्लाकर गाना गा रहा है। पड़ोसी क्या सोचेंगे, इसकी परवाह मत कीजिए। आपके घर में एक सितारा बड़ा हो रहा है, आप बस तालियाँ बजाइए।', title_id = 'Konser langsung dan para tetangga 🎤', body_id = 'Ia memegang sendok, berdiri di tengah kamar, dan bernyanyi sekeras-kerasnya. Tak usah pedulikan apa kata tetangga. Seorang bintang sedang tumbuh di rumahmu, kamu cukup bertepuk tangan.', title_ja = 'ライブコンサートとご近所さん 🎤', body_ja = 'スプーンを手に部屋のまんなかに立って、声のかぎり歌っています。ご近所さんにどう思われるかなんて気にしないで。あなたの家ではスターが育っているんです。あなたはただ拍手を送ればいいの。', title_ko = '라이브 콘서트와 이웃들 🎤', body_ko = '숟가락을 마이크 삼아 방 한가운데 서서 목청껏 노래하나요? 이웃이 뭐라 생각할지는 신경 쓰지 마세요. 집에서 스타가 자라고 있어요, 그냥 박수 쳐 주세요.', title_nl = 'Liveconcert en de buren 🎤', body_nl = 'Hij pakt een lepel, gaat midden in de kamer staan en zingt zo hard hij kan. Trek je niets aan van wat de buren denken. In jouw huis groeit een ster op, jij hoeft alleen te applaudisseren.', title_pl = 'Koncert na żywo i sąsiedzi 🎤', body_pl = 'Wziął łyżkę, stanął na środku pokoju i śpiewa na cały głos. Nie przejmuj się tym, co pomyślą sąsiedzi. W twoim domu dorasta gwiazda, ty po prostu bij brawo.', title_pt = 'Concerto ao vivo e os vizinhos 🎤', body_pt = 'Pega numa colher, põe-se no meio do quarto e canta aos gritos com toda a força. Não se preocupe com o que os vizinhos vão pensar. Está a crescer uma estrela em sua casa, só tem de aplaudir.', title_sv = 'Livekonsert och grannar 🎤', body_sv = 'Barnet tar en sked, ställer sig mitt i rummet och sjunger för full hals. Bry dig inte om vad grannarna tycker. En stjärna växer upp i ditt hem, du ska bara applådera.', title_vi = 'Hòa nhạc trực tiếp và hàng xóm 🎤', body_vi = 'Bé cầm chiếc thìa, đứng giữa phòng và hát to hết cỡ. Đừng bận tâm hàng xóm nghĩ gì. Một ngôi sao đang lớn lên trong nhà mẹ, mẹ chỉ cần vỗ tay thôi.', title_zh = '现场音乐会和邻居 🎤', body_zh = '手里拿把勺子，站在房间中间扯着嗓子大声唱歌。别管邻居怎么想。你家里正在长大一颗明星，你只要鼓掌就好。' WHERE id = '3df12920-0213-48db-ae96-b67ec62ae28a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con música 🎶', title_fr = 'S''endormir en musique 🎶', title_hi = 'संगीत के साथ नींद की ओर 🎶', title_id = 'Menuju tidur dengan musik 🎶', title_ja = '音楽で眠りへ 🎶', title_ko = '음악과 함께 잠으로 🎶', title_nl = 'Met muziek naar dromenland 🎶', title_pl = 'Muzyczne przejście w sen 🎶', title_pt = 'Adormecer com música 🎶', title_sv = 'Musik på vägen in i sömnen 🎶', title_vi = 'Vào giấc cùng âm nhạc 🎶', title_zh = '伴着音乐入睡 🎶' WHERE id = '3f3676c6-cf62-4752-a389-70e0f348c529' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La culpa del tiempo de pantalla 📺', body_es = '¿Hoy, por tus tareas, le has puesto más dibujos y te sientes culpable? No te culpes. A veces la niñera digital es la única forma de salvarte de un derrumbe psicológico.', title_fr = 'La culpabilité des écrans 📺', body_fr = 'Aujourd''hui, à cause de vos tâches, vous lui avez laissé plus de dessins animés et vous culpabilisez ? Ne vous jugez pas. Parfois, la nounou numérique est le seul moyen d''éviter l''effondrement psychologique.', title_hi = 'स्क्रीन टाइम का अपराधबोध 📺', body_hi = 'आज कामों की वजह से उसे ज़्यादा कार्टून दिखाए और मन में अपराधबोध है? खुद को दोष मत दीजिए। कभी-कभी डिजिटल आया ही आपको मानसिक रूप से टूटने से बचाने का इकलौता रास्ता होती है।', title_id = 'Rasa bersalah soal waktu layar 📺', body_id = 'Hari ini karena banyak urusan, Anda memberinya lebih banyak kartun dan kini merasa bersalah? Jangan menyalahkan diri. Kadang pengasuh digital adalah satu-satunya cara menyelamatkan Anda dari keruntuhan psikologis.', title_ja = '画面時間の罪悪感 📺', body_ja = '今日は用事のために、いつもよりアニメをたくさん見せてしまって、罪悪感を感じていますか？自分を責めないで。ときにはデジタルのベビーシッターが、あなたを心の限界から救ってくれる唯一の方法なんです。', title_ko = '영상 시간 죄책감 📺', body_ko = '오늘 일 때문에 만화를 더 보여 주고 마음이 무거운가요? 자책하지 마세요. 때로는 디지털 보모가 엄마를 마음의 붕괴에서 구해 주는 유일한 방법이에요.', title_nl = 'Schuldgevoel over schermtijd 📺', body_nl = 'Heb je hem vandaag door je bezigheden meer tekenfilms laten kijken en voel je je schuldig? Veroordeel jezelf niet. Soms is een digitale oppas de enige manier om jezelf te redden van een psychische instorting.', title_pl = 'Wyrzuty sumienia za ekran 📺', body_pl = 'Przez obowiązki dałaś mu dziś więcej bajek i masz wyrzuty sumienia? Nie obwiniaj się. Czasem cyfrowa niania to jedyny sposób, by uchronić się przed psychicznym załamaniem.', title_pt = 'A culpa do tempo de ecrã 📺', body_pt = 'Hoje, por causa das suas tarefas, deixou-o ver mais desenhos animados e sente remorsos? Não se culpe. Às vezes a ama digital é a única forma de a salvar de um colapso psicológico.', title_sv = 'Skärmtid och dåligt samvete 📺', body_sv = 'Fick barnet titta mer på tecknat i dag för att du hade saker att göra, och nu har du dåligt samvete? Klandra inte dig själv. Ibland är den digitala barnvakten det enda som räddar dig från ett psykiskt sammanbrott.', title_vi = 'Cảm giác tội lỗi vì thời gian xem màn hình 📺', body_vi = 'Hôm nay vì bận việc mà mẹ cho bé xem hoạt hình nhiều hơn và đang day dứt? Đừng tự trách mình. Đôi khi "bảo mẫu kỹ thuật số" là cách duy nhất giúp mẹ khỏi suy sụp tinh thần.', title_zh = '屏幕时间的愧疚 📺', body_zh = '今天因为忙，给宝宝多看了些动画片，心里过意不去？别责怪自己。有时候，“数字保姆”是让你免于心理崩溃的唯一办法。' WHERE id = '3e411b4b-9fe8-4f71-93e2-682182a18dba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación esconder el móvil 📱', body_es = 'No encuentras dónde dejaste el móvil y al rato aparece en la caja de los juguetes. No quiere compartir tu atención con el móvil. Deja el aparato a un lado y dale 15 minutos de atención sin interrupciones.', title_fr = 'Opération : cacher le téléphone 📱', body_fr = 'Impossible de retrouver votre téléphone, et un peu plus tard il ressort du coffre à jouets. Il ne veut pas partager votre attention avec le téléphone. Posez l''appareil et accordez-lui 15 minutes d''attention sans interruption.', title_hi = 'फ़ोन छिपाने का ऑपरेशन 📱', body_hi = 'आपको याद नहीं कि फ़ोन कहाँ रखा, और कुछ देर बाद वह खिलौनों के डिब्बे से निकलता है। वह आपका ध्यान फ़ोन के साथ बाँटना नहीं चाहता। फ़ोन एक तरफ़ रखकर उसे 15 मिनट बिना रुकावट ध्यान दीजिए।', title_id = 'Operasi menyembunyikan ponsel 📱', body_id = 'Anda tidak menemukan ponsel Anda, dan beberapa saat kemudian ponsel itu muncul dari kotak mainan. Ia tidak mau berbagi perhatian Anda dengan ponsel. Singkirkan perangkat dan beri ia perhatian penuh tanpa gangguan selama 15 menit.', title_ja = 'スマホかくし作戦 📱', body_ja = 'スマホをどこに置いたかわからなくて、しばらくするとおもちゃ箱から出てくる。あなたの注意をスマホと分け合いたくないんです。スマホを置いて、15分間、とぎれずにこの子だけを見てあげましょう。', title_ko = '휴대폰 숨기기 작전 📱', body_ko = '휴대폰을 어디 뒀는지 못 찾았는데 얼마 뒤 장난감 상자에서 나왔나요? 엄마의 관심을 휴대폰과 나누고 싶지 않은 거예요. 기기를 내려놓고 15분 동안 온전히 아이에게 집중해 주세요.', title_nl = 'Operatie telefoon verstoppen 📱', body_nl = 'Je kunt je telefoon nergens vinden en even later duikt hij op uit de speelgoedkist. Hij wil je aandacht niet met je telefoon delen. Leg het apparaat weg en geef hem 15 minuten je onverdeelde aandacht.', title_pl = 'Operacja „Schowaj telefon” 📱', body_pl = 'Nie możesz znaleźć telefonu, a po chwili wyłania się z pudła z zabawkami. Nie chce dzielić twojej uwagi z telefonem. Odłóż urządzenie i daj mu 15 minut nieprzerwanej uwagi.', title_pt = 'Operação esconder o telemóvel 📱', body_pt = 'Não encontra o telemóvel e, passado um bocado, ele aparece na caixa dos brinquedos. Não quer partilhar a sua atenção com o telemóvel. Ponha o aparelho de lado e dê-lhe 15 minutos de atenção sem interrupções.', title_sv = 'Operation göm telefonen 📱', body_sv = 'Du hittar inte telefonen och efter en stund dyker den upp i leksakslådan. Barnet vill inte dela din uppmärksamhet med telefonen. Lägg undan den och ge barnet 15 minuters oavbruten uppmärksamhet.', title_vi = 'Chiến dịch giấu điện thoại 📱', body_vi = 'Mẹ không tìm thấy điện thoại để đâu, một lúc sau nó lại xuất hiện trong hộp đồ chơi. Bé không muốn chia sẻ sự chú ý của mẹ với chiếc điện thoại. Hãy đặt thiết bị sang một bên và dành cho bé 15 phút chú ý trọn vẹn.', title_zh = '藏手机行动 📱', body_zh = '找不到手机放哪儿了，过了一会儿才从玩具箱里翻出来。宝宝不想和手机分享你的注意力。把手机放到一边，给宝宝15分钟不被打断的陪伴吧。' WHERE id = '66770f83-ef83-4481-9f8c-e9788791f68a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro descansa poco a poco.', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau se reposer peu à peu.', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे आराम पा रहा है।', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan secara visual bagaimana otak Anda perlahan beristirahat.', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ休まっていくのを目で感じてみましょう。', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬는 걸 눈으로 느껴 보세요.', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam tot rust komt.', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli odpoczywa.', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta visualmente o seu cérebro a descansar devagarinho.', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du visuellt hur hjärnan sakta vilar.', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần được nghỉ ngơi.', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，直观地感受大脑正在一点点休息下来。' WHERE id = 'b18d81af-044b-40e7-b55d-b23baee972a4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿En el tobogán o en la arena del parque no quiere dejar sitio a nadie y aprieta sus juguetes? No es egoísmo, es proteger sus límites. Enseña a compartir no obligando, sino con un sistema de turnos en forma de juego.', body_fr = 'Au parc, il ne veut laisser sa place à personne sur le toboggan ou dans le sable, et serre fort ses jouets. Ce n''est pas de l''égoïsme, il protège ses limites. Plutôt que de le forcer à partager, apprenez-lui à jouer chacun son tour sous forme de jeu.', body_hi = 'पार्क में फिसलपट्टी या रेत में किसी को जगह नहीं देना चाहता, अपने खिलौने कसकर पकड़े रहता है? यह स्वार्थ नहीं, अपनी सीमा की रक्षा है। बाँटने के लिए मजबूर करके नहीं, बल्कि बारी-बारी का तरीका खेल-खेल में सिखाइए।', body_id = 'Di taman ia tak mau memberi tempat kepada siapa pun di perosotan atau bak pasir, dan menggenggam erat mainannya. Ini bukan egois, ini menjaga batasan. Ajarkan sistem bergiliran lewat permainan, bukan dengan memaksanya berbagi.', body_ja = '公園のすべり台や砂場で誰にも場所をゆずらず、おもちゃをぎゅっと抱えている。これはわがままではなく、自分の境界を守っているんです。無理に分けさせるのではなく、順番のルールを遊びとして教えましょう。', body_ko = '공원 미끄럼틀이나 모래밭에서 아무에게도 자리를 내주지 않고 장난감을 꽉 쥐고 있나요? 이기심이 아니라 경계를 지키는 거예요. 억지로 나누게 하지 말고 차례 지키기를 놀이처럼 가르쳐 주세요.', body_nl = 'Wil hij in het park niemand op de glijbaan of in de zandbak laten, en klemt hij zijn speelgoed vast? Dat is geen egoïsme, maar grenzen bewaken. Dwing hem niet te delen, maar leer hem op een speelse manier om de beurt te gaan.', body_pl = 'W parku nie chce nikogo puścić na zjeżdżalnię ani do piaskownicy, mocno ściska swoje zabawki. To nie egoizm, tylko ochrona granic. Nie zmuszaj go do dzielenia się, ucz zasady kolejności przez zabawę.', body_pt = 'No parque, no escorrega ou na areia, não quer dar a vez a ninguém e agarra-se aos brinquedos. Não é egoísmo, é proteger os seus limites. Ensine a partilhar não à força, mas com um sistema de vez em forma de jogo.', body_sv = 'I parken vill barnet inte släppa fram någon i rutschkanan eller i sandlådan och håller hårt i sina leksaker. Det är inte egoism, det är att skydda sina gränser. Lär ut turordning genom lek, inte genom att tvinga barnet att dela.', body_vi = 'Ở công viên, bé không muốn nhường ai cầu trượt hay hố cát, ôm chặt đồ chơi của mình. Đây không phải ích kỷ, mà là bảo vệ ranh giới. Đừng ép bé chia sẻ, hãy dạy bé cách chờ đến lượt thông qua trò chơi.', body_zh = '在公园的滑梯上或沙坑里谁都不让，紧紧攥着自己的玩具。这不是自私，而是在守护边界。别强迫分享，而是用游戏的方式教宝宝学会轮流。' WHERE id = '09d17b10-a60b-4930-b773-b0f5bb7e0366' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitación a la oscuridad 🌙', body_es = '¿Se inquieta cuando se apagan las luces del dormitorio? Pon en un rincón una pequeña lamparita de luz cálida. El resto de la habitación debe quedar totalmente a oscuras para un sueño profundo.', title_fr = 'Inviter l''obscurité 🌙', body_fr = 'Il s''inquiète quand on éteint la lumière de la chambre ? Posez dans un coin une petite veilleuse de couleur chaude. Le reste de la chambre doit rester complètement sombre pour un sommeil profond.', title_hi = 'अँधेरे का न्योता 🌙', body_hi = 'सोने के कमरे में लाइटें बुझते ही बेचैन हो जाता है? कमरे के एक कोने में गर्म रंग की एक छोटी नाइट लैंप रखिए। बाकी कमरा गहरी नींद के लिए पूरी तरह अँधेरा रहना चाहिए।', title_id = 'Undangan menuju gelap 🌙', body_id = 'Ia gelisah saat lampu kamar dimatikan? Letakkan lampu tidur kecil berwarna hangat di salah satu sudut kamar. Bagian kamar lainnya harus tetap gelap total untuk tidur yang nyenyak.', title_ja = '暗さへのお誘い 🌙', body_ja = '寝室の明かりを消すと不安になる？部屋のすみに、暖かい色の小さなナイトライトを置きましょう。それ以外の部分は、ぐっすり眠れるように真っ暗にしておいてね。', title_ko = '어둠으로의 초대 🌙', body_ko = '침실 불이 꺼지면 불안해하나요? 방 한쪽에 작고 따뜻한 색의 수면등을 두세요. 나머지 공간은 깊은 잠을 위해 완전히 어둡게 유지해야 해요.', title_nl = 'Uitnodiging aan het donker 🌙', body_nl = 'Wordt hij onrustig als het licht in de slaapkamer uitgaat? Zet een klein nachtlampje met een warme kleur in een hoek van de kamer. De rest van de kamer blijft helemaal donker voor een diepe slaap.', title_pl = 'Zaproszenie do ciemności 🌙', body_pl = 'Niepokoi się, gdy w sypialni gaśnie światło? Postaw w kącie pokoju małą lampkę nocną w ciepłym kolorze. Reszta pokoju powinna pozostać zupełnie ciemna, by sen był głęboki.', title_pt = 'Convite à escuridão 🌙', body_pt = 'Fica inquieto quando se apagam as luzes do quarto? Ponha num canto do quarto uma pequena luz de presença de cor quente. O resto do quarto deve ficar totalmente escuro para um sono profundo.', title_sv = 'En inbjudan till mörkret 🌙', body_sv = 'Blir barnet oroligt när lampan släcks i sovrummet? Ställ en liten nattlampa med varmt sken i ett hörn av rummet. Resten av rummet ska vara helt mörkt för en djup sömn.', title_vi = 'Lời mời gọi bóng tối 🌙', body_vi = 'Bé lo lắng khi đèn phòng ngủ tắt? Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm ở một góc phòng. Phần còn lại của căn phòng nên tối hoàn toàn để bé ngủ sâu.', title_zh = '邀请黑暗 🌙', body_zh = '卧室一关灯就不安？在房间一角放一盏小小的暖色小夜灯。房间其余的地方要保持全黑，才能睡得深沉。' WHERE id = '0a13d571-0f47-4b38-ba09-6279a4e6c3b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No eres un robot. Si hoy no tienes fuerzas para cocinar, pide comida o simplemente hierve pasta. Ser una madre perfecta no es hacerlo todo sola. Date permiso.', body_fr = 'Vous n''êtes pas un robot. Si vous n''avez pas la force de cuisiner aujourd''hui, commandez ou faites simplement cuire des pâtes. Être une maman parfaite, ce n''est pas tout faire seule. Accordez-vous ce droit.', body_hi = 'आप रोबोट नहीं हैं। अगर आज खाना बनाने की ताकत नहीं है, तो बाहर से मँगवा लीजिए या बस पास्ता उबाल लीजिए। परफ़ेक्ट माँ होने का मतलब सब कुछ अकेले करना नहीं है। खुद को इजाज़त दीजिए।', body_id = 'Anda bukan robot. Jika hari ini tidak punya tenaga untuk memasak, pesan makanan atau rebus saja pasta. Menjadi ibu yang sempurna bukan berarti melakukan semuanya sendiri. Beri izin pada diri Anda.', body_ja = 'あなたはロボットではありません。今日料理する元気がないなら、デリバリーを頼むか、パスタをゆでるだけで十分。完璧なママとは、何でもひとりでこなすことではありません。自分を許してあげて。', body_ko = '엄마는 로봇이 아니에요. 오늘 요리할 힘이 없다면 배달을 시키거나 파스타만 삶으세요. 완벽한 엄마란 모든 걸 혼자 하는 게 아니에요. 나에게 허락해 주세요.', body_nl = 'Je bent geen robot. Heb je vandaag geen energie om te koken, bestel dan eten of kook gewoon wat pasta. Een perfecte moeder zijn betekent niet alles alleen doen. Geef jezelf toestemming.', body_pl = 'Nie jesteś robotem. Jeśli dziś nie masz siły gotować, zamów jedzenie albo po prostu ugotuj makaron. Bycie idealną mamą nie oznacza robienia wszystkiego samej. Daj sobie na to przyzwolenie.', body_pt = 'Não é um robô. Se hoje não tem forças para cozinhar, encomende comida ou coza simplesmente massa. Ser uma mãe perfeita não é fazer tudo sozinha. Dê-se essa permissão.', body_sv = 'Du är ingen robot. Om du inte orkar laga mat i dag, beställ hem eller koka bara pasta. Att vara en perfekt mamma är inte att göra allt själv. Ge dig själv lov.', body_vi = 'Mẹ không phải là robot. Nếu hôm nay không còn sức nấu ăn, hãy gọi đồ ăn hoặc chỉ luộc ít mì ống. Làm mẹ hoàn hảo không có nghĩa là tự làm mọi thứ. Hãy cho phép bản thân mình.', body_zh = '你不是机器人。如果今天没力气做饭，就点外卖，或者简单煮点意面。做完美妈妈，不等于什么事都一个人扛。允许自己这样做。' WHERE id = 'f1a7ace3-b71a-47a5-8150-e29d91b1d2f6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa en la lista 🛒', body_es = 'Antes de ir al súper abriste la Lista de la compra y viste que se había acercado por detrás, había tocado la pantalla y había garabateado algo. ¡Sí, también copia tu vida digital!', title_fr = 'Surprise dans la liste 🛒', body_fr = 'Avant d''aller au supermarché, vous avez ouvert la Liste de courses, et il est arrivé derrière vous pour gribouiller quelque chose en tapotant l''écran. Eh oui, il copie aussi votre vie numérique !', title_hi = 'लिस्ट में सरप्राइज़ 🛒', body_hi = 'बाज़ार जाने से पहले आपने शॉपिंग लिस्ट खोली और देखा कि उसने पीछे से आकर स्क्रीन पर टैप करके कुछ लिख दिया है। हाँ, वह आपकी डिजिटल ज़िंदगी की भी नकल करता है!', title_id = 'Kejutan di Daftar Belanja 🛒', body_id = 'Sebelum ke supermarket Anda membuka Daftar Belanja, lalu ia datang dari belakang, menekan layar ponsel, dan mencoret-coret sesuatu di sana. Ya, ia juga meniru kehidupan digital Anda!', title_ja = 'リストの中のサプライズ 🛒', body_ja = '買い物の前に「買い物リスト」を開いたら、後ろから来て画面をタップし、何か落書きしていたことに気づきましたか？そう、あなたのデジタルな暮らしもまねしているんです！', title_ko = '목록 속 깜짝 선물 🛒', body_ko = '마트에 가기 전 쇼핑 목록을 열었는데, 아이가 뒤에서 와서 화면을 눌러 뭔가 끄적여 놓았나요? 네, 엄마의 디지털 생활까지 따라 하는 중이에요!', title_nl = 'Verrassing op het lijstje 🛒', body_nl = 'Je opende voor het boodschappen doen je Boodschappenlijstje en zag dat hij van achteren op het scherm drukte en er iets op krabbelde. Ja, hij kopieert ook je digitale leven!', title_pl = 'Niespodzianka na liście 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś Listę zakupów, a on podszedł od tyłu, stuknął w ekran i coś tam nabazgrał. Tak, kopiuje też twoje cyfrowe życie!', title_pt = 'Surpresa na lista 🛒', body_pt = 'Antes de ir ao supermercado abriu a Lista de Compras e viu-o vir por trás, carregar no ecrã do telemóvel e rabiscar qualquer coisa? Pois é, ele também copia a sua vida digital!', title_sv = 'Överraskningen på listan 🛒', body_sv = 'Innan du gick till butiken öppnade du Inköpslistan, och barnet kom bakifrån och klottrade något på skärmen. Ja, barnet kopierar ditt digitala liv också!', title_vi = 'Bất ngờ trong danh sách 🛒', body_vi = 'Trước khi đi siêu thị, mẹ mở Danh sách mua sắm và thấy bé từ phía sau chạm vào màn hình điện thoại, vẽ nguệch ngoạc gì đó. Đúng vậy, bé còn bắt chước cả cuộc sống số của mẹ nữa!', title_zh = '清单里的惊喜 🛒', body_zh = '去超市前你打开了购物清单，结果发现宝宝从背后过来，在手机屏幕上一通乱点，涂涂画画了一番。没错，宝宝连你的数字生活也在模仿！' WHERE id = '012a4a46-c01f-4202-b7ec-b6dfb922b323' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Coge el móvil. En lugar de deslizar la vida de otros en redes sociales, abre el Diario de ánimo y anota para el futuro el momento más gracioso que ha tenido hoy. La terapia digital funciona.', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée. La thérapie numérique, ça marche.', body_hi = 'फ़ोन उठाइए। सोशल मीडिया पर दूसरों की ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसने जो सबसे मज़ेदार काम किया, उसे भविष्य के लिए लिख लीजिए। डिजिटल थेरेपी काम करती है।', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini untuk masa depan. Terapi digital itu berhasil.', body_ja = 'スマホを手に取って。SNSでほかの人の暮らしをスクロールする代わりに、「気分日記」を開いて、今日この子がしたいちばんおもしろい瞬間を未来のために記録しましょう。デジタルセラピーは効きますよ。', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃긴 순간을 기록해 두세요. 디지털 치료, 효과 있어요.', body_nl = 'Pak je telefoon. Open in plaats van door andermans leven op social media te scrollen je Stemmingsdagboek en schrijf het grappigste moment van vandaag op voor later. Digitale therapie werkt.', body_pl = 'Weź telefon do ręki. Zamiast przewijać cudze życie w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował. Cyfrowa terapia działa.', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje. A terapia digital funciona.', body_sv = 'Ta upp telefonen. Istället för att scrolla igenom andras liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet för framtiden. Digital terapi fungerar.', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc hài hước nhất bé làm hôm nay để dành cho tương lai. Liệu pháp số thật sự có hiệu quả.', body_zh = '拿起手机。与其刷社交网络看别人的生活，不如打开心情日记，把宝宝今天最搞笑的一刻记下来留给将来。数字疗愈真的有用。' WHERE id = '0f7001d8-21ca-493f-95e3-7b29b5f52d2b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te dice «solo 5 minutos más jugando y luego me visto»? Ya intenta negociar contigo como un profesional. Su desarrollo del habla es estupendo, pero no olvides proteger con cariño tus límites y tus normas.', body_fr = 'Il dit « Je joue encore 5 minutes, après je m''habille » ? Il essaie déjà de négocier avec vous comme un pro. Son langage progresse très bien, mais n''oubliez pas de tenir vos limites et vos règles avec amour.', body_hi = '‘बस 5 मिनट और खेल लूँ, फिर कपड़े पहनूँगा’ कहता है? वह अब आपसे पेशेवर तरीके से सौदा करने की कोशिश कर रहा है। बोलने का विकास शानदार है, पर अपनी सीमाओं और नियमों की प्यार से रक्षा करना मत भूलिए।', body_id = 'Ia berkata ''Main 5 menit lagi ya, nanti aku pakai baju''? Ia sudah mencoba bernegosiasi dengan Anda secara profesional. Perkembangan bicaranya luar biasa, tapi jangan lupa menjaga batasan dan aturan Anda dengan penuh kasih.', body_ja = '「あと5分だけ遊んだら着がえる」と言ってきた？もうあなたとプロのように交渉しようとしています。言葉の発達はすばらしいけれど、あなたの境界線とルールを愛情をもって守ることも忘れないで。', body_ko = '''딱 5분만 더 놀고 옷 입을게''라고 하나요? 벌써 엄마와 프로처럼 협상하려 해요. 언어 발달은 훌륭하지만, 경계와 규칙은 사랑으로 지키는 걸 잊지 마세요.', body_nl = 'Zegt hij: ''Nog 5 minuutjes spelen, dan kleed ik me aan''? Hij probeert al als een prof met je te onderhandelen. Zijn taalontwikkeling is prima, maar vergeet niet je grenzen en regels liefdevol te bewaken.', body_pl = 'Mówi: „Jeszcze tylko 5 minut się pobawię, potem się ubiorę”? Już próbuje negocjować z tobą jak zawodowiec. Rozwój mowy jest świetny, ale nie zapominaj z miłością pilnować swoich granic i zasad.', body_pt = 'Diz "Só mais 5 minutos a brincar e depois visto-me"? Já tenta negociar consigo como um profissional. O desenvolvimento da fala é ótimo, mas não se esqueça de proteger com amor os seus limites e regras.', body_sv = 'Säger barnet ”Bara 5 minuter till, sen klär jag på mig”? Barnet försöker redan förhandla med dig som ett proffs. Talutvecklingen är utmärkt, men glöm inte att kärleksfullt hålla fast vid dina gränser och regler.', body_vi = '"Cho con chơi thêm 5 phút nữa thôi, rồi con mặc đồ", bé nói vậy? Bé đã cố gắng thương lượng với mẹ như dân chuyên nghiệp. Khả năng ngôn ngữ thật tuyệt vời, nhưng đừng quên giữ vững giới hạn và quy tắc của mình bằng tình yêu thương.', body_zh = '“再玩5分钟，然后我就穿衣服”？宝宝已经在试着和你专业地谈判了。语言发展得很棒，但也别忘了带着爱守住你的边界和规矩。' WHERE id = '507a4882-997e-48f9-8d0c-a6ff5f18c3ac' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de calma 🥱', body_es = '¿No quiere echarse la siesta y llora? No le obligues. Baja las luces de la habitación y crea una rutina nueva que os haga descansar a los dos anunciando la «hora de hojear libros en silencio».', title_fr = 'L''heure calme 🥱', body_fr = 'Il ne veut pas faire la sieste et pleure ? Ne le forcez pas. Baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine qui vous reposera tous les deux.', title_hi = 'शांत समय 🥱', body_hi = 'दोपहर की नींद नहीं लेना चाहता और रोता है? ज़बरदस्ती मत कीजिए। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और एक नया रूटीन बनाइए जो आप दोनों को आराम दे।', title_id = 'Waktu tenang 🥱', body_id = 'Ia tidak mau tidur siang dan menangis? Jangan memaksa. Redupkan lampu kamar dan ciptakan rutinitas baru yang membuat kalian berdua beristirahat dengan mengumumkan ''Waktu membaca buku dengan tenang''.', title_ja = '静かな時間 🥱', body_ja = 'お昼寝したくなくて泣いている？無理強いしないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ふたりともほっとひと休みできる新しいルーティンをつくりましょう。', title_ko = '조용한 시간 🥱', body_ko = '낮잠을 안 자겠다며 우나요? 억지로 재우지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 두 사람 모두 쉴 수 있는 새로운 루틴을 만들어 보세요.', title_nl = 'Rustuurtje 🥱', body_nl = 'Wil hij geen middagslaapje doen en huilt hij? Dwing hem niet. Dim de lichten in de kamer en kondig een ''stil boekjesuurtje'' aan, een nieuwe routine waar jullie allebei van tot rust komen.', title_pl = 'Cicha godzina 🥱', body_pl = 'Nie chce iść na drzemkę i płacze? Nie zmuszaj. Przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę, która da wytchnienie wam obojgu.', title_pt = 'A hora do sossego 🥱', body_pt = 'Não quer fazer a sesta e chora? Não o obrigue. Baixe as luzes do quarto e crie uma nova rotina, que descanse os dois, anunciando a "hora de folhear livros em silêncio".', title_sv = 'Lugn stund 🥱', body_sv = 'Vill barnet inte sova middag och gråter? Tvinga inte. Dämpa ljuset i rummet och utlys en ”tyst bläddra-i-böcker-stund”, så skapar du en ny rutin som låter er båda vila.', title_vi = 'Giờ yên lặng 🥱', body_vi = 'Bé không muốn ngủ trưa và khóc? Đừng ép. Hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới giúp cả hai mẹ con được nghỉ ngơi.', title_zh = '安静时光 🥱', body_zh = '不肯午睡还哭闹？别强迫。把房间灯光调暗，宣布“安静翻书时间”，建立一个让你们俩都能休息的新日常流程。' WHERE id = '982b6e37-c6cb-46f9-bd93-9fafd76bcda8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy esto no me lo como 🥣', body_es = 'La sopa que ayer se comió con ganas hoy no hay manera de que la pruebe. Si no hay problemas de dientes, es solo una prueba de voluntad. Echa un vistazo en el Plan de alimentación a recetas alternativas que le aporten las mismas vitaminas.', title_fr = 'Aujourd''hui, je ne mange pas ça 🥣', body_fr = 'La soupe qu''il a mangée avec appétit hier, impossible de la lui faire goûter aujourd''hui. S''il n''a pas de souci de dents, c''est simplement un test de volonté. Parcourez dans le Plan de nutrition d''autres recettes qui apportent les mêmes vitamines.', title_hi = 'आज यह नहीं खाऊँगा 🥣', body_hi = 'कल जो सूप मज़े से खाया, आज उसे मुँह तक नहीं लगाता। अगर दाँतों की कोई परेशानी नहीं है, तो यह बस इच्छाशक्ति की परीक्षा है। फ़ीडिंग प्लान में वही विटामिन देने वाली दूसरी रेसिपी देखिए।', title_id = 'Hari ini aku tidak mau makan ini 🥣', body_id = 'Sup yang kemarin ia makan dengan lahap, hari ini bahkan tak mau ia cicipi. Jika tidak ada masalah gigi, ini hanya ujian kemauan. Lihat resep alternatif di Rencana Nutrisi yang memberikan vitamin yang sama.', title_ja = '今日はこれ、食べない 🥣', body_ja = '昨日はおいしそうに食べていたスープに、今日はひと口もつけない。歯のトラブルがなければ、これはただの意志のテストです。「栄養管理ツール」で、同じビタミンがとれる別のレシピをのぞいてみましょう。', title_ko = '오늘은 이거 안 먹어 🥣', body_ko = '어제 맛있게 먹던 수프를 오늘은 입에도 대지 않나요? 이 문제가 아니라면 그냥 의지 시험이에요. 식단 계획에서 같은 비타민을 채워 줄 다른 대안 레시피를 살펴보세요.', title_nl = 'Dit eet ik vandaag niet 🥣', body_nl = 'De soep die hij gisteren smakelijk at, wil hij vandaag niet eens proeven. Als er geen tandproblemen zijn, is dit gewoon een wilstest. Kijk in het Voedingsplan naar andere recepten die dezelfde vitamines geven.', title_pl = 'Dziś tego nie jem 🥣', body_pl = 'Zupy, którą wczoraj jadł ze smakiem, dziś nie chce nawet tknąć? Jeśli nie ma problemów z zębami, to po prostu test woli. Poszukaj w planie karmienia innych przepisów, które dostarczą tych samych witamin.', title_pt = 'Hoje não como isto 🥣', body_pt = 'A sopa que ontem comeu com gosto, hoje nem a deixa chegar à boca. Se não houver problemas com os dentes, é apenas um teste de vontade. Espreite no Registo de Alimentação receitas alternativas que deem as mesmas vitaminas.', title_sv = 'Det här äter jag inte i dag 🥣', body_sv = 'Soppan som barnet åt med god aptit i går vill det i dag inte ens smaka på. Om det inte är tandproblem är det bara ett test av viljan. Titta på andra alternativa recept i matplanen som ger samma vitaminer.', title_vi = 'Hôm nay con không ăn món này 🥣', body_vi = 'Món súp hôm qua bé ăn ngon lành, hôm nay mẹ không cho bé nếm nổi một thìa. Nếu không có vấn đề về răng, đây chỉ là phép thử ý chí. Hãy xem trong Kế hoạch dinh dưỡng những công thức thay thế cung cấp cùng loại vitamin.', title_zh = '今天这个我不吃 🥣', body_zh = '昨天还吃得津津有味的汤，今天连碰都不肯碰。如果不是牙齿的问题，这只是一场意志力测试。去喂养计划里看看能提供同样维生素的其他替代食谱。' WHERE id = 'dd274cad-cc38-4230-a074-0f529d065804' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando lo que haces ya no funciona, los ruidos raros y las caras graciosas de papá salvan la situación al instante. En las crisis de la tarde, pásale la pelota enseguida y mira descansando desde fuera.', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres et les grimaces de papa sauvent aussitôt la situation. Pendant les crises du soir, passez-lui vite le relais et regardez de loin en vous reposant.', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तब पापा की अजीब आवाज़ें और मज़ेदार चेहरे हालात तुरंत सँभाल लेते हैं। शाम के बिगड़े मूड में ज़िम्मेदारी तुरंत उन्हें सौंप दीजिए और आराम करते हुए दूर से देखिए।', body_id = 'Saat cara Anda tak lagi berhasil, bunyi aneh dan wajah lucu Ayah langsung menyelamatkan keadaan. Saat krisis sore hari, segera oper bolanya ke Ayah dan saksikan dari samping sambil beristirahat.', body_ja = 'あなたの手が通用しなくなったら、パパのおもしろい声やおどけた顔がすぐに状況を救ってくれます。夕方のぐずりタイムは、すぐにバトンをパパに渡して、そばで休みながら見守りましょう。', body_ko = '엄마의 방법이 더는 통하지 않을 때, 아빠의 이상한 소리와 웃긴 표정이 바로 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기고 옆에서 쉬며 지켜보세요.', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke geluiden en grappige gezichten meteen de situatie. Speel bij avondbuien de bal direct naar hem door en kijk ontspannen toe.', body_pl = 'Gdy twoje sposoby już nie działają, śmieszne odgłosy i miny taty od razu ratują sytuację. Podczas wieczornych kryzysów od razu przekaż mu pałeczkę i odpoczywaj, obserwując z boku.', body_pt = 'Quando os seus truques já não funcionam, os sons estranhos e as caretas cómicas do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola de imediato e observe à distância, a descansar.', body_sv = 'När ditt eget inte längre fungerar räddar pappas konstiga ljud och roliga miner situationen direkt. Vid kvällskriserna, skicka genast bollen till honom och vila medan du tittar på.', body_vi = 'Khi mọi chiêu của mẹ không còn hiệu quả, những âm thanh kỳ quặc và gương mặt hài hước của bố sẽ cứu nguy ngay lập tức. Trong những cơn khủng hoảng buổi tối, hãy "chuyền bóng" ngay cho bố và nghỉ ngơi quan sát từ xa.', body_zh = '当你的办法都不管用时，爸爸发出的怪声音、做的鬼脸马上就能化解局面。傍晚闹脾气时，赶紧把“球”传给爸爸，你在一旁休息着看就好。' WHERE id = 'ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El ambiente aburrido de casa os agobia a los dos. Id al parque con la misión de encontrar la piedra con la forma más rara. La naturaleza es su mayor laboratorio y se llevará todo su estrés.', body_fr = 'L''atmosphère monotone de la maison vous pèse à tous les deux. Partez au parc en mission : trouver le caillou à la forme la plus bizarre. La nature est pour lui le plus grand des laboratoires, et elle évacuera tout son stress.', body_hi = 'घर का उबाऊ माहौल आप दोनों को घुटन दे रहा है। पार्क जाकर सबसे अजीब आकार का पत्थर ढूँढने के मिशन पर निकलिए। प्रकृति उसके लिए सबसे बड़ी प्रयोगशाला है और उसका सारा तनाव सोख लेगी।', body_id = 'Suasana rumah yang membosankan menyesakkan kalian berdua. Pergilah ke taman dengan misi mencari batu dengan bentuk paling aneh. Alam adalah laboratorium terbesar baginya dan akan menyerap semua stresnya.', body_ja = '家の中のどんよりした空気に、ふたりとも息がつまっていませんか？公園へ行って、いちばんへんな形の石をさがすミッションに出かけましょう。自然はこの子にとって最大の実験室。ストレスを全部受けとめてくれます。', body_ko = '집 안의 지루한 분위기가 두 사람 모두를 답답하게 하나요? 공원에 가서 가장 이상하게 생긴 돌 찾기 미션을 떠나 보세요. 자연은 아이에게 가장 큰 실험실이고 모든 스트레스를 덜어 줄 거예요.', body_nl = 'De saaie sfeer in huis drukt op jullie allebei. Ga naar het park met een missie: de steen met de gekste vorm vinden. De natuur is voor hem het grootste laboratorium en neemt al zijn stress weg.', body_pl = 'Nudna atmosfera w domu przytłacza was oboje. Wybierzcie się do parku na misję znalezienia kamienia o najdziwniejszym kształcie. Natura to dla niego największe laboratorium, które zabierze cały stres.', body_pt = 'O ambiente aborrecido da casa está a sufocar os dois. Vão ao parque em missão para encontrar a pedra com a forma mais estranha. A natureza é o maior laboratório para ele e vai levar-lhe todo o stress.', body_sv = 'Den tråkiga stämningen hemma tynger er båda. Gå till parken och ge er ut på uppdrag att hitta stenen med den konstigaste formen. Naturen är barnets största laboratorium och tar bort all stress.', body_vi = 'Không khí tẻ nhạt trong nhà khiến cả hai mẹ con ngột ngạt. Hãy ra công viên với nhiệm vụ tìm viên sỏi có hình dạng kỳ lạ nhất. Thiên nhiên là phòng thí nghiệm lớn nhất của bé và sẽ cuốn đi mọi căng thẳng.', body_zh = '家里沉闷的气氛让你们俩都喘不过气。去公园，展开一场“寻找形状最奇怪的石头”的任务吧。大自然是宝宝最大的实验室，会带走宝宝所有的压力。' WHERE id = '805b4060-d925-4469-abb9-000b87b286a1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitados imaginarios a la mesa ☕', body_es = '¿Te ofrece una taza vacía diciendo «bébete el té» y habla con un amigo que no está en la habitación? Es la obra maestra del desarrollo de la imaginación. No interrumpas esta función que tiene lugar en un rincón: bébete tú también ese té.', title_fr = 'Invités imaginaires à table ☕', body_fr = 'Il vous tend une tasse vide en disant « Bois ton thé » et parle à un ami qui n''est pas là ? C''est un chef-d''œuvre du développement de l''imagination. Ne gâchez pas ce spectacle qui se joue dans un coin de la pièce, buvez ce thé, vous aussi.', title_hi = 'मेज़ पर काल्पनिक मेहमान ☕', body_hi = 'खाली कप आपकी ओर बढ़ाकर ‘चाय पीजिए’ कहता है और कमरे में मौजूद न होने वाले दोस्त से बात करता है? यह कल्पना के विकास की बेहतरीन मिसाल है। कमरे के कोने में चल रहे इस नाटक को मत बिगाड़िए, आप भी वह चाय पी लीजिए।', title_id = 'Tamu khayalan di meja ☕', body_id = 'Ia menyodorkan cangkir kosong, berkata ''Minum teh'', dan berbicara dengan temannya yang tidak ada di kamar? Ini mahakarya perkembangan imajinasi. Jangan ganggu pertunjukan di sudut kamar itu, ikutlah minum tehnya.', title_ja = '空想のお客さまとお茶会 ☕', body_ja = '空っぽのカップを差し出して「お茶どうぞ」と言い、部屋にいないお友だちと話している？想像力の発達の傑作です。部屋のすみで繰り広げられるこの舞台をこわさず、あなたもそのお茶を飲みましょう。', title_ko = '식탁의 상상 속 손님들 ☕', body_ko = '빈 찻잔을 내밀며 ''차 마셔'' 하고, 방에 없는 친구와 이야기하나요? 상상력 발달의 걸작이에요. 방 한쪽에서 펼쳐지는 이 공연을 망치지 말고 엄마도 그 차를 마셔 주세요.', title_nl = 'Denkbeeldige gasten aan tafel ☕', body_nl = 'Geeft hij je een leeg kopje, zegt hij ''Drink thee'' en praat hij met een vriendje dat er niet is? Een meesterwerk van fantasieontwikkeling. Verstoor dit toneelstuk in de hoek van de kamer niet en drink die thee ook op.', title_pl = 'Wymyśleni goście przy stole ☕', body_pl = 'Podaje ci pustą filiżankę, mówi „Pij herbatkę” i rozmawia z przyjacielem, którego nie ma w pokoju? To arcydzieło rozwoju wyobraźni. Nie przerywaj tego przedstawienia w kącie pokoju, wypij tę herbatkę.', title_pt = 'Convidados imaginários à mesa ☕', body_pt = 'Estende-lhe uma chávena vazia, diz "Bebe o chá" e conversa com um amigo que não está no quarto? É a obra-prima do desenvolvimento da imaginação. Não estrague este espetáculo num canto do quarto: beba também esse chá.', title_sv = 'Låtsasgäster vid bordet ☕', body_sv = 'Räcker barnet dig en tom kopp, säger ”Drick te” och pratar med en vän som inte finns i rummet? Det är fantasiutvecklingens mästerverk. Förstör inte föreställningen som pågår i ett hörn av rummet, drick du också teet.', title_vi = 'Những vị khách tưởng tượng bên bàn ☕', body_vi = 'Bé đưa mẹ chiếc tách rỗng, bảo "Mẹ uống trà đi" và trò chuyện với một người bạn không có trong phòng? Đây là kiệt tác của sự phát triển trí tưởng tượng. Đừng phá vở kịch đang diễn ra ở góc phòng, mẹ cũng uống tách trà ấy đi.', title_zh = '餐桌上的想象客人 ☕', body_zh = '递给你一个空杯子说“喝茶”，还和房间里并不存在的朋友聊天？这是想象力发展的杰作。别打断房间一角正在上演的这出戏，你也把那杯茶喝了吧。' WHERE id = '88ec7e91-36e6-4aab-9210-fc0f8e69cab3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paz en el baño 🛀', title_fr = 'La paix dans le bain 🛀', title_hi = 'बाथटब में शांति 🛀', title_id = 'Damai di bak mandi 🛀', title_ja = 'お風呂でひと休み 🛀', title_ko = '욕실 속 평화 🛀', title_nl = 'Rust in bad 🛀', title_pl = 'Spokój w kąpieli 🛀', title_pt = 'Paz no banho 🛀', title_sv = 'Fred i badkaret 🛀', title_vi = 'Bình yên trong bồn tắm 🛀', title_zh = '浴室里的和平 🛀' WHERE id = '62114884-cb2a-44c8-ab0b-33ab815b8e09' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La libertad del «¡No me cojas la mano!» 🚶‍♂️', body_es = 'En la calle se niega rotundamente a darte la mano y quiere correr libre. En lugares seguros, dale esa libertad. Sin quitarle el ojo de encima, deja que conquiste el mundo con sus propios pasos.', title_fr = 'La liberté du « Me tiens pas la main ! » 🚶‍♂️', body_fr = 'Dans la rue, il refuse catégoriquement de vous donner la main et veut courir librement. Dans les endroits sûrs, accordez-lui cette liberté. Gardez un œil sur lui et laissez-le conquérir le monde à son propre pas.', title_hi = '‘मेरा हाथ मत पकड़ो!’ वाली आज़ादी 🚶‍♂️', body_hi = 'सड़क पर आपका हाथ पकड़ने से साफ़ मना करता है, आज़ादी से दौड़ना चाहता है। सुरक्षित जगहों पर उसे यह आज़ादी दीजिए। नज़र उस पर रखिए, और उसे अपने कदमों से दुनिया जीतने दीजिए।', title_id = 'Kebebasan ''Jangan pegang tanganku!'' 🚶‍♂️', body_id = 'Di jalan ia tegas menolak bergandengan tangan dan ingin berlari bebas. Beri ia kebebasan ini di tempat yang aman. Tetap awasi, dan biarkan ia menaklukkan dunia dengan langkahnya sendiri.', title_ja = '「手をつながないで！」の自由 🚶‍♂️', body_ja = '外で手をつなぐのをきっぱりいやがって、自由に走りたがる。安全な場所では、その自由をあげましょう。目は離さずに、自分の足で世界を征服させてあげて。', title_ko = '''손 잡지 마!''의 자유 🚶‍♂️', body_ko = '길에서 손 잡기를 단호하게 거부하고 마음대로 뛰고 싶어 하나요? 안전한 곳에서는 그 자유를 주세요. 눈은 떼지 말고, 자기 발걸음으로 세상을 정복하게 해 주세요.', title_nl = 'De vrijheid van ''Niet mijn hand vasthouden!'' 🚶‍♂️', body_nl = 'Weigert hij op straat resoluut je hand vast te houden en wil hij vrij rennen? Geef hem die vrijheid op veilige plekken. Houd hem in de gaten en laat hem de wereld veroveren met zijn eigen stapjes.', title_pl = 'Wolność „Nie trzymaj mnie za rękę!” 🚶‍♂️', body_pl = 'Na ulicy stanowczo odmawia trzymania cię za rękę i chce biegać swobodnie. W bezpiecznych miejscach daj mu tę swobodę. Miej go na oku i pozwól mu podbijać świat własnymi krokami.', title_pt = 'A liberdade do "Não me dês a mão!" 🚶‍♂️', body_pt = 'Na rua, recusa terminantemente dar-lhe a mão e quer correr à vontade. Em sítios seguros, dê-lhe essa liberdade. Mantenha-o debaixo de olho e deixe-o conquistar o mundo com os seus próprios passos.', title_sv = '”Håll inte i min hand!”-friheten 🚶‍♂️', body_sv = 'Vägrar barnet bestämt att hålla din hand på gatan och vill springa fritt? Ge barnet den friheten på säkra platser. Håll ögonen på barnet och låt det erövra världen med egna steg.', title_vi = 'Tự do "Đừng nắm tay con!" 🚶‍♂️', body_vi = 'Ra đường, bé kiên quyết không nắm tay mẹ và muốn tự do chạy nhảy. Ở những nơi an toàn, hãy cho bé sự tự do ấy. Luôn để mắt đến bé, để bé chinh phục thế giới bằng chính những bước chân của mình.', title_zh = '“别牵我的手！”的自由 🚶‍♂️', body_zh = '在街上坚决不肯牵你的手，想自由地跑。在安全的地方就给宝宝这份自由吧。你的目光不离开宝宝，让宝宝用自己的脚步去征服世界。' WHERE id = '9f52c47e-5431-4d83-b54d-9c8d7cbf5228' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las huellas del desarrollo 📈', body_es = 'A los 3 años su motricidad, su vocabulario y su inteligencia emocional cambian muy deprisa. Para no olvidar sus pequeños descubrimientos, anótalos y archívalos con regularidad en el Seguimiento del desarrollo.', title_fr = 'Les traces du développement 📈', body_fr = 'Autour de 3 ans, sa motricité, son vocabulaire et son intelligence émotionnelle évoluent très vite. Pour ne pas oublier ses petites découvertes, notez-les et archivez-les régulièrement dans le Suivi de développement.', title_hi = 'विकास के निशान 📈', body_hi = '3 साल के दौर में उसकी मोटर स्किल्स, शब्दावली और भावनात्मक समझ तेज़ी से बदलती है। उसकी छोटी-छोटी खोजें भूल न जाएँ, इसलिए ग्रोथ ट्रैकर में नियमित रूप से दर्ज कीजिए और सँजोकर रखिए।', title_id = 'Jejak perkembangan 📈', body_id = 'Di usia 3 tahun, motorik, kosakata, dan kecerdasan emosionalnya berubah dengan cepat. Agar tak melupakan penemuan-penemuan kecilnya, rutinlah mencatat dan mengarsipkannya di Pelacak Perkembangan.', title_ja = '成長の足あと 📈', body_ja = '3歳のころは、運動能力も語彙も心の知能も、どんどん変わっていきます。小さな発見を忘れないように、「発達トラッカー」にこまめに記録して残しておきましょう。', title_ko = '성장의 발자취 📈', body_ko = '세 살 무렵에는 운동 능력, 어휘, 정서 지능이 빠르게 변해요. 작은 발견들을 잊지 않도록 성장 기록에 꾸준히 적어 보관해 두세요.', title_nl = 'Sporen van ontwikkeling 📈', body_nl = 'Rond 3 jaar veranderen zijn motoriek, woordenschat en emotionele intelligentie razendsnel. Noteer en archiveer regelmatig in de Groeitracker, zodat je zijn kleine ontdekkingen niet vergeet.', title_pl = 'Ślady rozwoju 📈', body_pl = 'W wieku 3 lat jego motoryka, zasób słów i inteligencja emocjonalna szybko się zmieniają. Żeby nie zapomnieć jego małych odkryć, regularnie zapisuj je w Śledzeniu rozwoju i archiwizuj.', title_pt = 'Marcas do desenvolvimento 📈', body_pt = 'Aos 3 anos, a motricidade, o vocabulário e a inteligência emocional mudam depressa. Para não esquecer as pequenas descobertas dele, registe-as e arquive-as regularmente no Registo de Crescimento.', title_sv = 'Spår av utvecklingen 📈', body_sv = 'Runt 3 år förändras barnets motorik, ordförråd och emotionella intelligens snabbt. För att inte glömma barnets små upptäckter, anteckna och spara dem regelbundet i Utvecklingsspåraren.', title_vi = 'Dấu ấn phát triển 📈', body_vi = 'Ở tuổi lên 3, kỹ năng vận động, vốn từ và trí tuệ cảm xúc của bé thay đổi rất nhanh. Để không quên những khám phá nhỏ của bé, hãy thường xuyên ghi chép và lưu lại trong Theo dõi phát triển.', title_zh = '成长的足迹 📈', body_zh = '3岁这个阶段，宝宝的动作能力、词汇量和情绪智力都在飞速变化。为了不忘记宝宝那些小小的发现，定期在发育追踪里做记录、存档吧。' WHERE id = 'd319859d-6f77-4ec4-b4f9-90c9441fac9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pedir perdón y volver a hacerlo 🧸', body_es = '¿Pide perdón de corazón por algo que ha golpeado o roto, pero 5 minutos después repite exactamente lo mismo? Todavía no controla sus impulsos. Explícale la norma con paciencia una y otra vez.', title_fr = 'S''excuser, puis recommencer 🧸', body_fr = 'Il s''excuse sincèrement d''avoir tapé ou cassé quelque chose, mais refait exactement la même chose 5 minutes plus tard ? Il ne sait pas encore contrôler ses impulsions. Expliquez la règle encore et encore, avec patience.', title_hi = 'माफ़ी माँगकर वही दोहराना 🧸', body_hi = 'किसी को मारने या कुछ तोड़ने पर दिल से माफ़ी माँगता है, पर 5 मिनट बाद बिल्कुल वही हरकत दोहराता है? वह अपने आवेग संभाल नहीं पाता। धैर्य से बार-बार नियम समझाइए।', title_id = 'Minta maaf, lalu mengulanginya 🧸', body_id = 'Ia minta maaf dengan tulus karena memukul atau memecahkan sesuatu, tapi 5 menit kemudian mengulangi hal yang persis sama? Ia belum bisa mengendalikan dorongan hatinya. Jelaskan aturannya dengan sabar, lagi dan lagi.', title_ja = 'あやまって、また同じことを 🧸', body_ja = 'たたいたり壊したりしたことを心からあやまるのに、5分後にはまったく同じことをくり返す？まだ衝動をコントロールできないんです。根気よく、何度でもルールを説明してあげましょう。', title_ko = '사과하고, 또 똑같이 🧸', body_ko = '때리거나 부순 것에 진심으로 사과하고는 5분 뒤 똑같은 행동을 반복하나요? 아직 충동을 조절하지 못해서 그래요. 규칙을 인내심 있게 몇 번이고 설명해 주세요.', title_nl = 'Sorry zeggen en het weer doen 🧸', body_nl = 'Zegt hij oprecht sorry voor iets wat hij sloeg of brak, maar doet hij 5 minuten later precies hetzelfde? Hij kan zijn impulsen nog niet beheersen. Leg de regel geduldig keer op keer uit.', title_pl = 'Przeprosić i zrobić to samo 🧸', body_pl = 'Szczerze przeprasza za to, że kogoś uderzył albo coś zepsuł, a 5 minut później robi dokładnie to samo? Nie umie jeszcze panować nad impulsami. Cierpliwie tłumacz zasadę raz za razem.', title_pt = 'Pedir desculpa e fazer igual 🧸', body_pt = 'Pede desculpa com sinceridade por algo em que bateu ou que partiu, mas 5 minutos depois repete exatamente o mesmo? Ainda não consegue controlar os impulsos. Explique a regra com paciência, vezes sem conta.', title_sv = 'Be om förlåtelse och göra om samma sak 🧸', body_sv = 'Ber barnet uppriktigt om förlåtelse för något det slagit eller haft sönder, men gör exakt samma sak igen 5 minuter senare? Barnet kan inte styra sina impulser. Förklara regeln om och om igen med tålamod.', title_vi = 'Xin lỗi rồi lại làm y như cũ 🧸', body_vi = 'Bé thành thật xin lỗi vì đã đánh hay làm vỡ thứ gì đó, nhưng 5 phút sau lại lặp lại đúng hành động ấy? Bé chưa kiểm soát được những thôi thúc của mình. Hãy kiên nhẫn giải thích quy tắc hết lần này đến lần khác.', title_zh = '道完歉，又做一遍 🧸', body_zh = '为打了人或弄坏东西真诚地道了歉，可5分钟后又一模一样地做了一遍？宝宝还控制不住自己的冲动。耐心地把规矩一遍又一遍讲给宝宝听吧。' WHERE id = '01326cb0-274c-49ad-8b92-7ce1373a0568' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de desahogarse 💬', body_es = '¿Tienes que tomar una decisión difícil? (Guardería, orinal, sueño). Los consejos de las madres con experiencia de la Comunidad Anacan son las soluciones más reales, sacadas de la vida y que no aparecen en ningún libro.', title_fr = 'Besoin de se confier 💬', body_fr = 'Une décision difficile à prendre ? (Crèche, pot, sommeil.) Les conseils des mamans expérimentées de la Communauté Anacan sont les solutions les plus concrètes, tirées de la vraie vie et introuvables dans les livres.', title_hi = 'दिल की बात कहने की ज़रूरत 💬', body_hi = 'कोई मुश्किल फ़ैसला लेना है? (प्ले स्कूल, पॉटी, नींद)। Anacan कम्युनिटी की अनुभवी माँओं की सलाह ज़िंदगी से निकले सबसे असली हल हैं, जो किसी किताब में नहीं लिखे।', title_id = 'Butuh teman curhat 💬', body_id = 'Harus mengambil keputusan sulit? (TK, pispot, tidur). Saran ibu-ibu berpengalaman di Komunitas Anacan adalah solusi paling nyata dari kehidupan, yang tak tertulis di buku mana pun.', title_ja = '話を聞いてほしいとき 💬', body_ja = 'むずかしい決断をしなければならない？（保育園、おまる、ねんね）。Anacanコミュニティの経験豊富なママたちのアドバイスは、どんな本にも載っていない、暮らしから生まれたいちばんリアルな解決策です。', title_ko = '털어놓고 싶은 마음 💬', body_ko = '어려운 결정을 앞두고 있나요? (어린이집, 배변 훈련, 수면) Anacan 커뮤니티의 경험 많은 엄마들의 조언은 어떤 책에도 없는, 삶에서 나온 가장 현실적인 해결책이에요.', title_nl = 'Behoefte om je hart te luchten 💬', body_nl = 'Moet je een moeilijke beslissing nemen? (Opvang, potje, slapen.) De tips van ervaren mama''s in de Anacan Community zijn de meest echte oplossingen uit het leven, die je in geen enkel boek vindt.', title_pl = 'Potrzeba wygadania się 💬', body_pl = 'Musisz podjąć trudną decyzję? (Przedszkole, nocnik, sen). Rady doświadczonych mam ze Społeczności Anacan to najbardziej życiowe rozwiązania, których nie znajdziesz w żadnej książce.', title_pt = 'A necessidade de desabafar 💬', body_pt = 'Tem de tomar uma decisão difícil? (Jardim de infância, bacio, sono). Os conselhos das mães experientes da Comunidade Anacan são as soluções mais reais, tiradas da vida, que não vêm em nenhum livro.', title_sv = 'Behov av att prata av sig 💬', body_sv = 'Måste du fatta ett svårt beslut? (Förskola, potta, sömn.) Råden från erfarna mammor i Anacan Community är de mest verklighetsnära lösningarna, hämtade ur livet och inte skrivna i någon bok.', title_vi = 'Cần được sẻ chia 💬', body_vi = 'Mẹ cần đưa ra một quyết định khó khăn? (Trường mầm non, bô, giấc ngủ). Lời khuyên của các mẹ giàu kinh nghiệm trong Cộng đồng Anacan là những giải pháp thực tế nhất từ cuộc sống mà chẳng cuốn sách nào viết ra.', title_zh = '想找人倾诉 💬', body_zh = '需要做一个艰难的决定？（幼儿园、便盆、睡觉）Anacan社区里有经验的妈妈们的建议，是任何书里都没写过、来自真实生活的最实在的办法。' WHERE id = '1efb2536-bf55-4365-890d-581fbbac3193' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los dos estáis cansados de los libros de siempre. Esta vez, en Cuentos inteligentes, deja que tu peque elija el final de la historia. Pregúntale «¿Quién crees que ayudó al héroe?» y deja volar su imaginación antes de dormir.', body_fr = 'Les livres classiques vous lassent tous les deux. Cette fois, dans les Contes intelligents, laissez votre enfant choisir la fin de l''histoire. Libérez son imagination avant le coucher : « À ton avis, qui a aidé ce héros ? »', body_hi = 'आप दोनों पुरानी किताबों से थक चुके हैं। इस बार स्मार्ट कहानियों में कहानी का अंत अपने बच्चे से चुनवाइए। ‘तुम्हें क्या लगता है, उस हीरो की मदद किसने की?’ पूछकर सोने से पहले उसकी कल्पना को खुला छोड़िए।', body_id = 'Kalian berdua sudah lelah dengan buku klasik. Di Dongeng Pintar, kali ini biarkan anak Anda memilih akhir ceritanya. Tanyakan ''Menurutmu siapa yang membantu tokoh itu?'', dan bebaskan imajinasinya sebelum tidur.', body_ja = '定番の絵本にはふたりとも疲れてしまった？今回は「スマートおはなし」で、お話の結末をお子さんに選ばせてみましょう。「その主人公を助けたのは誰だと思う？」と聞いて、寝る前の想像力を自由にはばたかせて。', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 이번에는 스마트 동화에서 이야기의 결말을 아이가 고르게 해 보세요. ''그 주인공을 누가 도와줬을 것 같아?'' 물으며 잠들기 전 상상력을 자유롭게 풀어 주세요.', body_nl = 'Jullie zijn allebei de klassieke boeken moe. Laat je kind in Slimme sprookjes deze keer het einde van het verhaal kiezen. Vraag: ''Wie denk jij dat die held heeft geholpen?'' en laat zijn fantasie voor het slapengaan de vrije loop.', body_pl = 'Klasyczne książeczki zmęczyły was oboje. Tym razem w Mądrych bajkach pozwól dziecku wybrać zakończenie historii. Zapytaj: „Jak myślisz, kto pomógł temu bohaterowi?” i daj jego wyobraźni swobodę przed snem.', body_pt = 'Estão os dois cansados dos livros clássicos. Desta vez, nas Histórias Inteligentes, deixe o seu filho escolher o final da história. Pergunte "Quem achas que ajudou aquele herói?" e deixe a imaginação dele à solta antes de dormir.', body_sv = 'Ni är båda trötta på de klassiska böckerna. Låt den här gången barnet välja slutet på berättelsen i Smarta sagor. Fråga ”Vem tror du hjälpte hjälten?” och släpp fantasin fri före sömnen.', body_vi = 'Cả hai mẹ con đều đã mệt với những cuốn sách quen thuộc. Lần này, trong Truyện cổ tích thông minh, hãy để bé chọn cái kết của câu chuyện. Hỏi bé: "Con nghĩ ai đã giúp nhân vật chính?" để trí tưởng tượng của bé bay xa trước giờ ngủ.', body_zh = '经典故事书你们俩都看累了。这一次在智慧童话里让宝宝来选故事的结局。问问“你觉得是谁帮了那个英雄？”，在睡前让宝宝的想象力自由飞翔。' WHERE id = 'd2d2c46d-7705-4c59-b1ff-a6a3d0986863' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, peque sano 🥑', body_es = 'Con el ajetreo diario, no comas de pie. Siéntate y prepárate con calma una ensalada diferente, rica en hierro y calcio, y disfrútala. Tu energía es el motor de esta casa: cuídala.', title_fr = 'Maman en forme, enfant en forme 🥑', body_fr = 'Dans la course du quotidien, ne déjeunez pas debout. Préparez-vous une salade différente, riche en fer et en calcium, et mangez-la assise, avec plaisir. Votre énergie est le moteur de cette maison, préservez-la.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। बैठकर, मज़े से, आयरन और कैल्शियम से भरपूर कोई नया सलाद बनाकर खाइए। आपकी ऊर्जा इस घर का इंजन है, उसका ख्याल रखिए।', title_id = 'Ibu sehat, anak sehat 🥑', body_id = 'Di tengah kesibukan harian, jangan makan siang sambil berdiri. Duduklah, siapkan salad istimewa yang kaya zat besi dan kalsium, lalu nikmati. Energimu adalah mesin rumah ini, jagalah.', title_ja = '元気なママ、元気な子ども 🥑', body_ja = '毎日のバタバタの中で、お昼ごはんを立ったまま食べないで。座って、鉄分とカルシウムたっぷりのいつもとちがうサラダをつくり、味わって食べましょう。あなたのエネルギーはこの家のエンジン。大切にしてね。', title_ko = '건강한 엄마, 건강한 아이 🥑', body_ko = '바쁜 하루 속에서 점심을 서서 때우지 마세요. 앉아서 철분과 칼슘이 풍부한 색다른 샐러드를 만들어 맛있게 드세요. 엄마의 에너지는 이 집의 엔진이에요, 지켜 주세요.', title_nl = 'Gezonde mama, gezond kind 🥑', body_nl = 'Eet in de dagelijkse drukte je lunch niet staand. Ga zitten en geniet van een andere salade, rijk aan ijzer en calcium. Jouw energie is de motor van dit huis, bescherm hem.', title_pl = 'Zdrowa mama, zdrowe dziecko 🥑', body_pl = 'W codziennym biegu nie jedz obiadu na stojąco. Usiądź i ze smakiem zjedz inną niż zwykle sałatkę bogatą w żelazo i wapń. Twoja energia to silnik tego domu, chroń ją.', title_pt = 'Mãe saudável, criança saudável 🥑', body_pt = 'Na correria do dia, não almoce de pé. Sente-se e coma com prazer uma salada diferente, rica em ferro e cálcio. A sua energia é o motor desta casa: proteja-a.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Ät inte lunch stående mitt i den dagliga rusningen. Sätt dig ner och njut av en annorlunda sallad rik på järn och kalcium. Din energi är det här hemmets motor, skydda den.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Đừng ăn trưa vội vàng giữa nhịp sống tất bật hằng ngày. Hãy ngồi xuống, chuẩn bị và thưởng thức một đĩa salad lạ miệng giàu sắt và canxi. Năng lượng của mẹ là động cơ của ngôi nhà này, hãy giữ gìn nó.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '日常忙忙碌碌，也别站着吃午饭。坐下来，做一份富含铁和钙的特别沙拉，好好地享受它。你的能量是这个家的发动机，要好好守护。' WHERE id = '37e65e72-e2dc-4492-b8ea-92aeab4db745' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tras un día ruidoso, cuando el peque se duerma, mide el silencio de la habitación con el Medidor de sonido. Solo ver esos números acercarse a cero es como el mejor masaje visual para el cerebro de una madre.', body_fr = 'Après une journée bruyante, quand il dort, mesurez le silence de la chambre avec le Sonomètre. Rien que de voir ces chiffres s''approcher de zéro, c''est le meilleur massage visuel pour le cerveau d''une maman.', body_hi = 'शोर भरे दिन के बाद, बच्चे के सोने पर साउंड मीटर से कमरे की खामोशी मापिए। शून्य के करीब पहुँचते अंक देखना ही माँ के दिमाग के लिए सबसे अच्छी विज़ुअल मसाज जैसा है।', body_id = 'Setelah hari yang bising, saat anak sudah tidur, ukur keheningan kamar dengan Pengukur Suara. Melihat angka yang mendekati nol saja sudah terasa seperti pijatan visual terbaik untuk otak seorang ibu.', body_ja = 'にぎやかな一日のあと、子どもが寝たら「サウンドメーター」で部屋の静けさを測ってみましょう。ゼロに近づいていく数字を見るだけで、ママの脳にとってはいちばんの視覚マッサージになります。', body_ko = '시끌벅적한 하루가 끝나고 아이가 잠들면 소음 측정기로 방의 고요를 재 보세요. 0에 가까워지는 숫자를 보는 것만으로도 엄마의 머리에 최고의 시각 마사지가 돼요.', body_nl = 'Meet na een drukke dag, als hij slaapt, de stilte in de kamer met de Geluidsmeter. Alleen al die getallen richting nul zien zakken werkt als de beste visuele massage voor het brein van een mama.', body_pl = 'Po hałaśliwym dniu, gdy dziecko zaśnie, zmierz ciszę w pokoju Miernikiem dźwięku. Sam widok liczb spadających do zera działa na mózg mamy jak najlepszy wizualny masaż.', body_pt = 'Depois de um dia barulhento, quando a criança adormecer, meça o silêncio do quarto com o Medidor de Som. Ver os números a aproximarem-se do zero funciona como a melhor massagem visual para o cérebro da mãe.', body_sv = 'Efter en bullrig dag, mät tystnaden i rummet med Ljudmätaren när barnet sover. Bara att se siffrorna närma sig noll fungerar som den bästa visuella massagen för en mammas hjärna.', body_vi = 'Sau một ngày ồn ào, khi bé đã ngủ, hãy dùng Đo âm thanh để đo sự yên tĩnh trong phòng. Chỉ cần nhìn những con số tiến dần về không cũng giống như một màn mát-xa thị giác tuyệt vời nhất cho não bộ của mẹ.', body_zh = '热闹的一天过后，等宝宝睡着了，用分贝仪测一测房间的安静程度。光是看着那些越来越接近零的数字，对妈妈的大脑来说就像一次最好的视觉按摩。' WHERE id = '9a78401e-398c-45fd-a3a7-dae1cd59ed31' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Asalto a la cocina 🧑‍🍳', body_es = 'Mientras extiendes la masa, se sube a una silla a tu lado y se mete en el proceso. Deja que enharine su propio cuenco de plástico. La cocina acabará hecha un desastre, pero esa cara tan seria y trabajadora vale toda esa limpieza.', title_fr = 'Coup de main en cuisine 🧑‍🍳', body_fr = 'Quand vous étalez la pâte, il installe forcément une chaise à côté de vous pour s''en mêler. Laissez-le fariner son propre bol en plastique. La cuisine sera en désordre, mais son air sérieux et appliqué vaut bien tout ce ménage.', title_hi = 'खाना बनाने में धमाका 🧑‍🍳', body_hi = 'आप आटा बेलती हैं तो वह ज़रूर पास में कुर्सी लगाकर काम में हाथ डालता है। उसे अपना प्लास्टिक का बर्तन आटे से भरने दीजिए। रसोई गंदी होगी, पर उसका वह गंभीर, कामकाजी चेहरा इस सारी सफ़ाई के लायक है।', title_id = 'Gebrakan di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia pasti menaruh kursi di samping dan ikut campur. Biarkan ia menaburi tepung ke mangkuk plastik miliknya sendiri. Dapur akan berantakan, tapi wajahnya yang serius dan sibuk itu sepadan dengan semua bersih-bersihnya.', title_ja = '料理中の乱入 🧑‍🍳', body_ja = 'あなたが生地をのばしていると、必ずそばにいすを持ってきて手を出してきます。この子専用のプラスチックの器で、粉あそびをさせてあげましょう。キッチンは粉だらけになるけれど、あの真剣でまじめな顔は、そのお掃除の価値が十分あります。', title_ko = '요리 시간의 습격 🧑‍🍳', body_ko = '반죽을 밀 때 꼭 옆에 의자를 놓고 끼어드나요? 아이만의 플라스틱 그릇에 밀가루를 뿌리게 해 주세요. 부엌은 엉망이 되겠지만, 그 진지하고 일에 몰두한 표정은 청소할 가치가 충분해요.', title_nl = 'Actie bij het koken 🧑‍🍳', body_nl = 'Als jij deeg uitrolt, zet hij per se een stoel ernaast en bemoeit hij zich ermee. Laat hem zijn eigen plastic bakje met bloem bestuiven. De keuken wordt een zooi, maar dat serieuze, zakelijke gezichtje is al het schoonmaken waard.', title_pl = 'Wkroczenie do kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, koniecznie przystawia obok krzesło i wtrąca się w pracę. Niech posypie mąką swoją plastikową miseczkę. Kuchnia będzie w opłakanym stanie, ale ta jego poważna, rzeczowa mina jest warta całego sprzątania.', title_pt = 'Ataque na preparação da comida 🧑‍🍳', body_pt = 'Enquanto estende a massa, ele põe uma cadeira ao seu lado e mete-se no processo. Deixe-o enfarinhar uma taça de plástico só dele. A cozinha vai ficar um caos, mas aquela cara séria e trabalhadora vale toda a limpeza.', title_sv = 'Matlagning med extra hjälp 🧑‍🍳', body_sv = 'När du kavlar deg ställer barnet absolut en stol bredvid dig och lägger sig i. Låt barnet mjöla sin egen plastskål. Köket blir nedkladdat, men barnets allvarliga, arbetsamma min är värd all städning.', title_vi = 'Biến cố trong bếp 🧑‍🍳', body_vi = 'Khi mẹ cán bột, bé nhất định kê ghế đứng cạnh và "nhúng tay" vào. Hãy để bé rắc bột vào chiếc bát nhựa của riêng mình. Căn bếp sẽ bừa bộn, nhưng vẻ mặt nghiêm túc, chăm chỉ ấy của bé xứng đáng với mọi công dọn dẹp.', title_zh = '做饭时的“突袭” 🧑‍🍳', body_zh = '你擀面团时，宝宝非要搬张椅子到旁边“参与”。就让宝宝往自己的塑料碗里撒面粉吧。厨房会被弄得一团糟，但宝宝那副认真又能干的小表情，值得这一切的打扫。' WHERE id = 'ba7f66f9-da13-4eea-9e4a-a968d14f269b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Daos las gracias 🥂', body_es = 'Habéis dejado atrás un día difícil. Cuando el peque se duerma, servíos un té tú y tu pareja y dale las gracias: «Hoy, con tanta tormenta, me has ayudado mucho». Así se construye el espíritu de equipo.', title_fr = 'Se remercier l''un l''autre 🥂', body_fr = 'Vous avez laissé derrière vous une journée difficile. Une fois l''enfant couché, servez-vous un thé avec votre partenaire et remerciez-le : « Tu m''as beaucoup aidée pendant cette journée agitée. » C''est ainsi que se construit l''esprit d''équipe.', title_hi = 'एक-दूसरे का शुक्रिया 🥂', body_hi = 'एक मुश्किल दिन पीछे छूट गया। बच्चे के सोने के बाद अपने साथी के साथ चाय डालिए और ‘इस तूफ़ानी दिन में तुमने मेरी बहुत मदद की’ कहकर शुक्रिया कीजिए। टीम भावना ऐसे ही बनती है।', title_id = 'Saling berterima kasih 🥂', body_id = 'Kalian sudah melewati hari yang berat. Setelah anak tidur, tuang teh bersama pasangan dan ucapkan terima kasih: ''Di hari yang penuh badai ini kamu sangat membantuku.'' Begitulah semangat tim dibangun.', title_ja = 'お互いにありがとう 🥂', body_ja = '大変な一日を乗りこえましたね。子どもが寝たら、パートナーとお茶をいれて「この嵐のような日に、たくさん助けてくれてありがとう」と伝えましょう。チームワークはこうして育ちます。', title_ko = '서로에게 고마움을 🥂', body_ko = '힘든 하루를 보냈어요. 아이가 잠들면 배우자와 차 한 잔을 따르고 ''오늘 같은 폭풍 같은 날, 많이 도와줘서 고마워''라고 말해 주세요. 팀워크는 이렇게 만들어져요.', title_nl = 'Elkaar bedanken 🥂', body_nl = 'Jullie hebben een zware dag achter de rug. Schenk als je kind slaapt een kop thee in met je partner en bedank elkaar: ''Je hebt me vandaag, op deze stormachtige dag, zo goed geholpen.'' Zo bouw je teamgeest op.', title_pl = 'Podziękujcie sobie nawzajem 🥂', body_pl = 'Trudny dzień za wami. Gdy dziecko zaśnie, nalejcie sobie z partnerem herbaty i podziękuj mu: „Bardzo mi dziś pomogłeś w tym burzliwym dniu”. Tak buduje się ducha drużyny.', title_pt = 'Agradecer um ao outro 🥂', body_pt = 'Deixaram para trás um dia difícil. Depois de a criança adormecer, sirvam um chá e agradeça ao seu companheiro: "Ajudaste-me muito neste dia tempestuoso". É assim que se constrói o espírito de equipa.', title_sv = 'Tacka varandra 🥂', body_sv = 'Ni har lagt en tuff dag bakom er. När barnet har somnat, häll upp te med din partner och tacka: ”Du hjälpte mig så mycket under den här stormiga dagen.” Det är så laganda byggs.', title_vi = 'Cảm ơn nhau 🥂', body_vi = 'Một ngày khó khăn đã qua. Sau khi bé ngủ, hãy cùng chồng pha một ấm trà và cảm ơn: "Hôm nay sóng gió thế mà anh đã giúp em rất nhiều". Tinh thần đồng đội được xây dựng như thế đấy.', title_zh = '互相道一声谢谢 🥂', body_zh = '艰难的一天过去了。宝宝睡着后，和伴侣倒杯茶，说声谢谢：“在这暴风雨般的一天里，你帮了我很多。”团队精神就是这样建立起来的。' WHERE id = '06f0acb2-a541-42e5-8b33-ed2285d3285f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, respuesta real 🤖', body_es = '¿Cuáles son las causas científicas, avaladas por pediatras, de las crisis de los 3 años? En lugar de leer comentarios de internet que dan miedo, pide ya a Anacan AI un análisis preciso y profesional de la psicología de tu peque.', title_fr = 'Intelligence artificielle, vraie réponse 🤖', body_fr = 'Quelles sont les causes scientifiques des crises des 3 ans, validées par des pédiatres ? Plutôt que de lire des commentaires effrayants sur Internet, demandez tout de suite à Anacan AI une analyse précise et professionnelle de la psychologie de votre enfant.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, असली जवाब 🤖', body_hi = '3 साल के नखरों की वैज्ञानिक और बाल रोग विशेषज्ञ द्वारा पुष्ट वजहें क्या हैं? इंटरनेट की डरावनी टिप्पणियाँ पढ़ने के बजाय तुरंत Anacan AI से बच्चे के मनोविज्ञान का सटीक और पेशेवर विश्लेषण माँगिए।', title_id = 'Kecerdasan buatan, jawaban nyata 🤖', body_id = 'Apa penyebab ilmiah krisis usia 3 tahun yang disetujui dokter anak? Daripada membaca komentar menakutkan di internet, segera minta analisis yang akurat dan profesional tentang psikologi anak dari Anacan AI.', title_ja = 'AI、リアルな答え 🤖', body_ja = '3歳のかんしゃくの、小児科医も認める科学的な理由は？ネットの怖いコメントを読むより、すぐにAnacan AIに子どもの心理について正確でプロの分析をたずねてみましょう。', title_ko = '인공지능, 진짜 답 🤖', body_ko = '세 살 떼쓰기의 과학적이고 소아과 의사가 확인한 이유는 뭘까요? 인터넷의 무서운 댓글을 읽는 대신, 바로 Anacan AI에게 아이 심리에 대한 정확하고 전문적인 분석을 요청하세요.', title_nl = 'Kunstmatige intelligentie, echt antwoord 🤖', body_nl = 'Wat zijn de wetenschappelijke, door kinderartsen bevestigde oorzaken van de buien rond 3 jaar? Lees geen enge reacties op internet, maar vraag Anacan AI meteen om een precieze en professionele analyse van de psychologie van je kind.', title_pl = 'Sztuczna inteligencja, prawdziwa odpowiedź 🤖', body_pl = 'Jakie są naukowe, potwierdzone przez pediatrów przyczyny kryzysów 3-latka? Zamiast czytać straszne komentarze w internecie, od razu poproś Anacan AI o dokładną i profesjonalną analizę psychologii dziecka.', title_pt = 'Inteligência artificial, resposta real 🤖', body_pt = 'Quais são as causas científicas, validadas por pediatras, das crises dos 3 anos? Em vez de ler comentários assustadores na internet, peça já ao Anacan AI uma análise precisa e profissional sobre a psicologia da criança.', title_sv = 'Artificiell intelligens, riktiga svar 🤖', body_sv = 'Vilka är de vetenskapliga, barnläkargodkända orsakerna till 3-årskriserna? Istället för att läsa skrämmande kommentarer på nätet, be genast Anacan AI om en exakt och professionell analys av barnets psykologi.', title_vi = 'Trí tuệ nhân tạo, câu trả lời thật 🤖', body_vi = 'Đâu là nguyên nhân khoa học, được bác sĩ nhi khoa xác nhận, của những cơn khủng hoảng tuổi lên 3? Thay vì đọc những bình luận đáng sợ trên mạng, hãy nhờ ngay Anacan AI phân tích chính xác và chuyên nghiệp về tâm lý của bé.', title_zh = '人工智能，真实答案 🤖', body_zh = '3岁崩溃背后有哪些经儿科医生认可的科学原因？与其看网上那些吓人的评论，不如马上请Anacan AI对孩子的心理做一份准确、专业的分析。' WHERE id = '4217bad1-d028-470b-a2a2-ceacb5b15105' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sobrecarga sensorial 🔋', body_es = 'Todo el día se te ha subido encima, te ha tirado del pelo y ha armado jaleo. Tu sistema nervioso está en alerta roja. La saturación de contacto es totalmente real. Deja al peque con tu pareja y retírate a una habitación.', title_fr = 'Surcharge sensorielle 🔋', body_fr = 'Toute la journée, il vous a grimpé dessus, tiré les cheveux et fait du bruit. Votre système nerveux est en alerte rouge. La saturation du toucher est bien réelle. Confiez l''enfant à votre partenaire et retirez-vous dans une pièce.', title_hi = 'इंद्रियों पर ज़रूरत से ज़्यादा बोझ 🔋', body_hi = 'दिनभर आप पर चढ़ता रहा, बाल खींचे, शोर मचाया। आपका तंत्रिका तंत्र लाल संकेत दे रहा है। छुए जाने की थकान बिल्कुल सच है। बच्चे को अपने साथी को सौंपिए और दूसरे कमरे में चली जाइए।', title_id = 'Beban sensorik berlebih 🔋', body_id = 'Seharian ia memanjat tubuh Anda, menarik rambut Anda, dan membuat keributan. Sistem saraf Anda memberi sinyal merah. Lelah disentuh itu benar-benar nyata. Serahkan anak kepada pasangan dan menyendirilah di kamar.', title_ja = '感覚のキャパオーバー 🔋', body_ja = '一日じゅう体によじのぼられ、髪を引っぱられ、大騒ぎされましたね。あなたの神経は赤信号を出しています。さわられ疲れは本当にあります。子どもをパートナーにまかせて、別の部屋で休みましょう。', title_ko = '감각 과부하 🔋', body_ko = '하루 종일 몸에 기어오르고, 머리카락을 잡아당기고, 시끄럽게 했나요? 엄마의 신경계가 빨간불을 켜고 있어요. 스킨십 피로는 정말 있어요. 아이를 배우자에게 맡기고 다른 방으로 가 쉬세요.', title_nl = 'Zintuiglijke overbelasting 🔋', body_nl = 'De hele dag klom hij op je, trok hij aan je haar en maakte hij lawaai. Je zenuwstelsel staat op rood. Aanraakmoeheid is echt. Geef je kind aan je partner en trek je terug in een andere kamer.', title_pl = 'Przeciążenie sensoryczne 🔋', body_pl = 'Cały dzień się na ciebie wspinał, ciągnął za włosy i hałasował. Twój układ nerwowy wysyła czerwony sygnał. Zmęczenie dotykiem jest całkowicie prawdziwe. Oddaj dziecko partnerowi i zaszyj się w pokoju.', title_pt = 'Sobrecarga sensorial 🔋', body_pt = 'O dia inteiro trepou por si, puxou-lhe o cabelo e fez barulho. O seu sistema nervoso está a dar sinal vermelho. O cansaço de toque é totalmente real. Entregue a criança ao seu companheiro e retire-se para outra divisão.', title_sv = 'Sensorisk överbelastning 🔋', body_sv = 'Hela dagen har barnet klättrat på dig, dragit i håret och väsnats. Ditt nervsystem visar rött ljus. Beröringströtthet är helt verklig. Lämna barnet till din partner och dra dig tillbaka till ett rum.', title_vi = 'Quá tải giác quan 🔋', body_vi = 'Cả ngày bé trèo lên người mẹ, giật tóc mẹ và làm ồn. Hệ thần kinh của mẹ đang phát tín hiệu đỏ. Mệt vì bị chạm vào liên tục là hoàn toàn có thật. Hãy giao bé cho chồng và vào phòng nghỉ một chút.', title_zh = '感官超载 🔋', body_zh = '宝宝一整天都往你身上爬、扯你头发、吵吵闹闹。你的神经系统在亮红灯。“触碰疲劳”完全是真实存在的。把孩子交给伴侣，去另一个房间待一会儿吧。' WHERE id = '50050f6d-75e8-48b1-9632-bcebb31ce6fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pronunciaciones curiosas 🗣️', body_es = 'Dice las palabras con acentos tan raros y personales que es imposible no reírse. No le corrijas riéndote; al contrario, escúchale con atención y respóndele repitiendo la frase de forma correcta.', title_fr = 'Prononciations rigolotes 🗣️', body_fr = 'Il dit les mots avec des accents si bizarres et si personnels qu''il est impossible de ne pas rire. Ne le corrigez pas en riant : écoutez-le attentivement et répondez simplement en répétant la phrase correctement.', title_hi = 'अजीब उच्चारण 🗣️', body_hi = 'शब्द इतने अजीब और अनोखे लहजे में बोलता है कि हँसी रुकती नहीं। हँसकर उसे मत सुधारिए, बल्कि ध्यान से सुनिए और जवाब में बस वाक्य का सही रूप दोहराइए।', title_id = 'Pengucapan yang lucu 🗣️', body_id = 'Ia mengucapkan kata-kata dengan tekanan yang begitu aneh dan khas sampai Anda tak bisa menahan tawa. Jangan membetulkannya sambil tertawa, sebaliknya dengarkan baik-baik lalu jawab cukup dengan mengulang kalimat yang benar.', title_ja = 'ふしぎな発音 🗣️', body_ja = 'とてもへんてこで独特なアクセントで言葉を話すので、笑わずにいられません。笑いながら直すのではなく、しっかり聞いて、正しい言い方でくり返して返事をしてあげましょう。', title_ko = '엉뚱한 발음 🗣️', body_ko = '단어를 너무 독특한 억양으로 말해서 웃음을 참을 수 없나요? 웃으면서 고쳐 주지 말고, 귀 기울여 들은 뒤 바른 문장으로 다시 말해 주며 대답하세요.', title_nl = 'Grappige uitspraak 🗣️', body_nl = 'Hij zegt woorden met zulke rare, eigen klemtonen dat je wel moet lachen. Verbeter hem niet lachend, maar luister aandachtig en antwoord gewoon door de zin correct te herhalen.', title_pl = 'Dziwna wymowa 🗣️', body_pl = 'Wymawia słowa z tak dziwnym i wyjątkowym akcentem, że trudno się nie śmiać. Nie poprawiaj go ze śmiechem, raczej uważnie wysłuchaj i odpowiedz, po prostu powtarzając zdanie poprawnie.', title_pt = 'Pronúncias estranhas 🗣️', body_pt = 'Diz as palavras com uma pronúncia tão estranha e tão sua que é impossível não rir. Não o corrija a rir: pelo contrário, ouça-o com atenção e responda repetindo simplesmente a frase da forma certa.', title_sv = 'Konstiga uttal 🗣️', body_sv = 'Barnet säger orden med så konstiga och egna betoningar att det är omöjligt att inte skratta. Rätta inte barnet skrattande, lyssna istället uppmärksamt och svara bara genom att upprepa meningen rätt.', title_vi = 'Phát âm ngộ nghĩnh 🗣️', body_vi = 'Bé nói các từ với ngữ điệu kỳ lạ và độc đáo đến mức không nhịn cười được. Đừng vừa cười vừa sửa cho bé, thay vào đó hãy chăm chú lắng nghe và đáp lại bằng cách nhắc lại câu nói đúng.', title_zh = '奇怪的发音 🗣️', body_zh = '用那么奇怪又独特的腔调说话，让人忍不住想笑。别笑着纠正宝宝，而是认真地听，然后只要用正确的说法把句子重复一遍作为回应就好。' WHERE id = '0efdad7b-f986-4a21-8e04-fc9cffca1b7d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pesadilla de los olvidos en el súper 🛒', body_es = '¿Fuiste al súper confiando en tu memoria y volviste sin los pañales? Son cosas que pasan. Acostúmbrate a apuntar enseguida todo lo que haga falta en la Lista de la compra y deja que tu memoria digital te salve.', title_fr = 'Le fléau des oublis au supermarché 🛒', body_fr = 'Vous êtes allée au supermarché en vous fiant à votre mémoire et vous êtes revenue sans les couches ? Ça arrive. Prenez l''habitude de noter tout de suite chaque besoin dans la Liste de courses : laissez votre mémoire numérique vous sauver.', title_hi = 'बाज़ार में भूलने की मुसीबत 🛒', body_hi = 'याददाश्त के भरोसे बाज़ार गईं और डायपर भूलकर लौट आईं? ऐसा होता है। हर ज़रूरत तुरंत शॉपिंग लिस्ट में लिखने की आदत बनाइए, आपकी डिजिटल याददाश्त आपको बचा लेगी।', title_id = 'Penyakit lupa di supermarket 🛒', body_id = 'Anda pergi ke supermarket mengandalkan ingatan dan pulang lupa membeli popok? Hal seperti itu biasa terjadi. Biasakan langsung menulis semua kebutuhan di Daftar Belanja, biarkan memori digital menyelamatkan Anda.', title_ja = 'スーパーでの買い忘れ問題 🛒', body_ja = '記憶をたよりに買い物へ行ったら、おむつを買い忘れて帰ってきた？よくあることです。必要なものはすぐに「買い物リスト」に書く習慣をつけて、デジタルな記憶に助けてもらいましょう。', title_ko = '마트에서의 깜빡깜빡 🛒', body_ko = '기억만 믿고 마트에 갔다가 기저귀를 잊고 돌아왔나요? 그럴 수 있어요. 필요한 건 바로바로 쇼핑 목록에 적는 습관을 들이고, 디지털 기억 장치가 엄마를 구하게 하세요.', title_nl = 'Vergeetachtig in de supermarkt 🛒', body_nl = 'Vertrouwde je op je geheugen in de supermarkt en kwam je thuis zonder luiers? Dat gebeurt. Maak er een gewoonte van om alles meteen op het Boodschappenlijstje te zetten en laat je digitale geheugen je redden.', title_pl = 'Sklepowe zapominalstwo 🛒', body_pl = 'Zaufałaś pamięci, poszłaś do sklepu i wróciłaś bez pieluch? Zdarza się. Wyrób sobie nawyk natychmiastowego wpisywania wszystkiego na Listę zakupów, niech cyfrowa pamięć cię uratuje.', title_pt = 'O drama dos esquecimentos no supermercado 🛒', body_pt = 'Confiou na memória, foi ao supermercado e voltou sem as fraldas? Acontece. Habitue-se a escrever logo tudo o que faz falta na Lista de Compras e deixe que a sua memória digital a salve.', title_sv = 'Glömskan i butiken 🛒', body_sv = 'Litade du på minnet när du gick till butiken och kom hem utan blöjor? Sånt händer. Gör det till en vana att direkt skriva upp allt som behövs i Inköpslistan och låt ditt digitala minne rädda dig.', title_vi = 'Nỗi khổ hay quên ở siêu thị 🛒', body_vi = 'Tin vào trí nhớ, mẹ đi siêu thị rồi về nhà mới nhận ra quên mua tã? Chuyện thường thôi. Hãy tập thói quen ghi ngay mọi thứ cần mua vào Danh sách mua sắm, để "bộ nhớ số" cứu nguy cho mẹ.', title_zh = '超市里的健忘烦恼 🛒', body_zh = '相信自己的记性去了超市，结果忘了买尿布就回来了？这很正常。养成习惯，把所有需要的东西马上写进购物清单，让数字记忆来拯救你。' WHERE id = '6d1f309e-d64f-4916-a1e2-48f064024563' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vuelca tus emociones en el papel 📝', body_es = '¿Nadie ve lo cansada que estás? El Diario de ánimo está ahí para escucharte. Escribe en él todos los pequeños detalles que hoy te han sacado de quicio y despeja tu mente.', title_fr = 'Couchez vos émotions sur le papier 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée ? Le Journal d''humeur est là pour vous écouter. Écrivez-y tous les petits détails qui vous ont rendue folle aujourd''hui et videz-vous la tête.', title_hi = 'भावनाएँ कागज़ पर उतारिए 📝', body_hi = 'किसी को नहीं दिखता कि आप कितनी थकी हैं? मूड डायरी आपकी सुनने के लिए है। आज जिन छोटी-छोटी बातों ने आपको पागल किया, सब वहाँ लिखिए और दिमाग साफ़ कीजिए।', title_id = 'Tuangkan perasaan ke kertas 📝', body_id = 'Tak ada yang melihat betapa lelahnya kamu? Buku Harian Suasana Hati ada untuk mendengarkanmu. Tuliskan di sana semua detail kecil yang membuatmu gila hari ini, dan jernihkan pikiranmu.', title_ja = '気持ちを書きだそう 📝', body_ja = 'あなたがこんなに疲れていることに、誰も気づいてくれない？「気分日記」はあなたの話を聞くためにあります。今日あなたをいらだたせた小さなことを全部書いて、頭をすっきりさせましょう。', title_ko = '감정을 종이에 쏟아내요 📝', body_ko = '내가 이렇게 지친 걸 아무도 몰라주나요? 기분 일기가 엄마의 이야기를 들어 줄 거예요. 오늘 나를 미치게 한 작은 일들을 모두 적고 머리를 비워 보세요.', title_nl = 'Zet je gevoelens op papier 📝', body_nl = 'Ziet niemand hoe moe je bent? Je Stemmingsdagboek is er om naar je te luisteren. Schrijf alle kleine dingen op die je vandaag gek maakten en maak je hoofd leeg.', title_pl = 'Przelej uczucia na papier 📝', body_pl = 'Nikt nie widzi, jak bardzo jesteś zmęczona? Dziennik nastroju jest po to, by cię wysłuchać. Zapisz w nim wszystkie drobiazgi, które dziś doprowadziły cię do szału, i oczyść głowę.', title_pt = 'Ponha as emoções no papel 📝', body_pt = 'Ninguém vê o quanto está cansada? O Diário de Humor está lá para a ouvir. Escreva lá todos os pequenos pormenores que hoje a deixaram louca e limpe a cabeça.', title_sv = 'Häll ut känslorna på papper 📝', body_sv = 'Ser ingen hur trött du är? Humördagboken finns där för att lyssna på dig. Skriv ner alla små detaljer som gjorde dig galen i dag och rensa hjärnan.', title_vi = 'Trút cảm xúc ra trang giấy 📝', body_vi = 'Không ai thấy mẹ mệt mỏi đến mức nào? Nhật ký tâm trạng luôn ở đó để lắng nghe mẹ. Hãy viết vào đó mọi chi tiết nhỏ khiến mẹ phát điên hôm nay và làm nhẹ đầu óc.', title_zh = '把情绪倒在纸上 📝', body_zh = '没人看见你有多累？心情日记一直在那里听你说。把今天让你抓狂的所有小细节都写进去，给大脑做个大扫除。' WHERE id = 'b478188b-090e-49fa-8067-44d7985fc9d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ambiente para la hormona del sueño 🌙', body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La hormona del sueño solo se libera en un ambiente oscuro y sin tecnología.', title_fr = 'Les conditions de l''hormone du sommeil 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. L''hormone du sommeil n''est sécrétée que dans le noir et sans écran.', title_hi = 'नींद के हार्मोन के लिए माहौल 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। नींद का हार्मोन सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में बनता है।', title_id = 'Suasana untuk hormon tidur 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Hormon tidur hanya diproduksi di lingkungan yang gelap dan bebas teknologi.', title_ja = '睡眠ホルモンのための環境 🌙', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。睡眠ホルモンは、暗くてデジタル機器のない環境でこそ分泌されます。', title_ko = '수면 호르몬을 위한 환경 🌙', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 수면 호르몬은 어둡고 기기가 없는 환경에서만 분비돼요.', title_nl = 'De juiste omstandigheden voor het slaaphormoon 🌙', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Het slaaphormoon wordt alleen aangemaakt in een donkere omgeving zonder technologie.', title_pl = 'Warunki dla hormonu snu 🌙', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Hormon snu wydziela się tylko w ciemnym otoczeniu bez technologii.', title_pt = 'Condições para a hormona do sono 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A hormona do sono só é produzida num ambiente escuro e sem tecnologia.', title_sv = 'Rätt förutsättningar för sömnhormonet 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Sömnhormonet utsöndras bara i en mörk och teknikfri miljö.', title_vi = 'Điều kiện cho hormone giấc ngủ 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Hormone giấc ngủ chỉ được tiết ra trong môi trường tối và không có thiết bị công nghệ.', title_zh = '为睡眠激素创造条件 🌙', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。睡眠激素只有在昏暗、没有电子产品的环境里才会分泌。' WHERE id = '51755ad7-f4a2-46b5-9170-1977fdac0046' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libertad en el parque 🌳', body_es = 'Las cuatro paredes le ponen agresivo. Con el asistente Tiempo y ropa elige el conjunto más adecuado para el viento de fuera y salid al parque. Deja que se manche de arena y se caiga corriendo. La libertad es su mejor medicina para el desarrollo.', title_fr = 'Liberté au parc 🌳', body_fr = 'Les quatre murs le rendent agressif. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et sortez au parc. Qu''il se roule dans le sable, tombe en courant. La liberté est pour lui le meilleur remède pour son développement.', title_hi = 'पार्क में आज़ादी 🌳', body_hi = 'चार दीवारें उसे चिड़चिड़ा बना देती हैं। मौसम और कपड़े असिस्टेंट से बाहर की हवा के लिए सबसे सही कपड़े तय कीजिए और पार्क जाइए। उसे रेत में सनने दीजिए, दौड़ते-दौड़ते गिरने दीजिए। आज़ादी उसके लिए विकास की सबसे अच्छी दवा है।', title_id = 'Bebas di taman 🌳', body_id = 'Empat dinding membuatnya gelisah. Tentukan setelan yang paling cocok untuk angin di luar dengan Cuaca dan Pakaian, lalu pergilah ke taman. Biarkan ia berlumur pasir dan jatuh saat berlari. Kebebasan adalah obat perkembangan terbaik untuknya.', title_ja = '公園での自由 🌳', body_ja = '4つの壁に囲まれていると、イライラがつのります。「天気と服装」で外の風にぴったりのコーデを決めて、公園へ出かけましょう。砂まみれになったり、走って転んだりしてもいいんです。自由はこの子にとっていちばんの成長の薬です。', title_ko = '공원에서의 자유 🌳', body_ko = '네 벽 안에 있으니 공격적으로 변하나요? 날씨와 옷차림 도우미로 바깥 바람에 가장 알맞은 옷차림을 정하고 공원으로 나가세요. 모래투성이가 되고 뛰다 넘어져도 괜찮아요. 자유가 아이에게 가장 좋은 발달의 약이에요.', title_nl = 'Vrijheid in het park 🌳', body_nl = 'Vier muren maken hem agressief. Bepaal met de assistent Weer en kleding de beste outfit voor de wind buiten en ga naar het park. Laat hem onder het zand komen en vallen tijdens het rennen. Vrijheid is voor hem het beste ontwikkelingsmedicijn.', title_pl = 'Wolność w parku 🌳', body_pl = 'Cztery ściany go rozdrażniają. Dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do wiatru na dworze i wyjdźcie do parku. Niech się wytarza w piasku, przewraca w biegu. Wolność to dla niego najlepsze lekarstwo na rozwój.', title_pt = 'Liberdade no parque 🌳', body_pt = 'As quatro paredes deixam-no agressivo. Com o assistente Tempo e Roupa, escolha a combinação mais adequada ao vento lá fora e vão ao parque. Deixe-o sujar-se na areia e cair a correr. A liberdade é o melhor remédio de desenvolvimento para ele.', title_sv = 'Frihet i parken 🌳', body_sv = 'De fyra väggarna gör barnet argt. Hitta den klädsel som passar bäst för vinden ute med hjälpen Väder och kläder och gå till parken. Låt barnet bli sandigt, springa och ramla. Frihet är den bästa utvecklingsmedicinen för barnet.', title_vi = 'Tự do ở công viên 🌳', body_vi = 'Bốn bức tường khiến bé trở nên cáu kỉnh. Hãy dùng Thời tiết và trang phục để chọn bộ đồ phù hợp nhất với gió ngoài trời, rồi ra công viên. Để bé lấm lem cát, chạy rồi ngã. Tự do là "liều thuốc" phát triển tốt nhất cho bé.', title_zh = '公园里的自由 🌳', body_zh = '四面墙让宝宝变得烦躁。用天气与穿衣助手确定最适合外面风力的搭配，去公园吧。让宝宝在沙子里打滚，跑着跑着摔一跤。自由是宝宝最好的发育良药。' WHERE id = '556d15ad-f396-4daf-9a38-c5bd773f19f0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un abrazo inesperado 💖', body_es = 'Jugando en medio de la habitación, de repente te mira, viene corriendo y se te cuelga del cuello. ¡Vale la pena por todas las noches sin dormir y todo el cansancio! Disfruta de la paz profunda y única de este momento.', title_fr = 'Un câlin inattendu 💖', body_fr = 'En jouant au milieu de la pièce, il vous regarde soudain, accourt et se jette à votre cou. Cela vaut toutes les nuits blanches et toute la fatigue ! Savourez la paix profonde et unique de ce moment.', title_hi = 'अचानक की झप्पी 💖', body_hi = 'कमरे के बीच खेलते-खेलते अचानक आपकी ओर देखकर दौड़ता आता है और गले से लिपट जाता है। सारी जागी रातें, सारी थकान इसके लायक थी! इस पल के गहरे, अनोखे सुकून का आनंद लीजिए।', title_id = 'Pelukan tak terduga 💖', body_id = 'Sedang bermain di tengah kamar, tiba-tiba ia menatap Anda, berlari, dan memeluk leher Anda. Itu sepadan dengan semua malam tanpa tidur dan rasa lelah! Nikmati ketenangan yang dalam dan istimewa dari momen ini.', title_ja = '思いがけないハグ 💖', body_ja = '部屋のまんなかで遊んでいたのに、ふとあなたを見て走ってきて、首にぎゅっと抱きついてくる。眠れない夜も疲れも、すべて報われますね！この瞬間がくれる深くて特別な幸せをかみしめて。', title_ko = '뜻밖의 포옹 💖', body_ko = '방 한가운데서 놀다가 갑자기 엄마를 보고 달려와 목을 꼭 끌어안나요? 잠 못 잔 밤과 피로가 모두 보상받는 순간이에요! 이 순간의 깊고 특별한 평온을 마음껏 누리세요.', title_nl = 'Een onverwachte knuffel 💖', body_nl = 'Midden in het spelen kijkt hij je ineens aan, rent naar je toe en slaat zijn armpjes om je nek. Dat is alle slapeloze nachten en vermoeidheid waard! Geniet van de diepe, unieke rust die dit moment je geeft.', title_pl = 'Niespodziewany uścisk 💖', body_pl = 'Bawiąc się na środku pokoju, nagle na ciebie spojrzał, przybiegł i objął cię za szyję. To jest warte wszystkich nieprzespanych nocy i zmęczenia! Delektuj się tym głębokim, wyjątkowym spokojem tej chwili.', title_pt = 'Um abraço inesperado 💖', body_pt = 'A brincar no meio do quarto, olha de repente para si, vem a correr e abraça-se ao seu pescoço. Valeu todas as noites sem dormir e todo o cansaço! Saboreie a calma profunda e única deste momento.', title_sv = 'En oväntad kram 💖', body_sv = 'Mitt i leken tittar barnet plötsligt på dig, springer fram och kramar dig om halsen. Det var värt alla sömnlösa nätter och all trötthet! Njut av det djupa, unika lugn som stunden ger.', title_vi = 'Cái ôm bất ngờ 💖', body_vi = 'Đang chơi giữa phòng, bé bỗng nhìn mẹ, chạy đến và ôm chầm lấy cổ mẹ. Thật xứng đáng với mọi đêm mất ngủ và mệt mỏi! Hãy tận hưởng cảm giác bình yên sâu lắng, đặc biệt mà khoảnh khắc này mang lại.', title_zh = '突如其来的拥抱 💖', body_zh = '在房间中间玩着玩着，突然看你一眼，跑过来搂住你的脖子。所有不眠的夜晚、所有的疲惫都值了！好好享受这一刻带来的那份深深的、独一无二的安宁。' WHERE id = 'b2f0448e-4bda-4f45-8af5-d1f543150cda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nace la noción del tiempo ⏱️', body_es = '¿Usa a menudo «mañana», «ayer» y «luego», pero a veces en el sitio equivocado? ¡Se está formando su percepción del tiempo! Escucha sus intentos con una sonrisa.', title_fr = 'La notion de temps apparaît ⏱️', body_fr = 'Il utilise souvent les mots « demain », « hier », « après », mais parfois au mauvais endroit ? Sa perception du temps se forme ! Écoutez ses tentatives avec le sourire.', title_hi = 'समय की समझ बन रही है ⏱️', body_hi = '‘कल’, ‘परसों’, ‘बाद में’ जैसे शब्द अक्सर, पर कभी-कभी गलत जगह इस्तेमाल करता है? समय की समझ आकार ले रही है! उसकी इन कोशिशों को मुस्कान के साथ सुनिए।', title_id = 'Pemahaman waktu mulai terbentuk ⏱️', body_id = 'Ia sering memakai kata ''besok'', ''kemarin'', ''nanti'', tapi kadang di tempat yang salah? Persepsi waktunya sedang terbentuk! Dengarkan usahanya dengan senyuman.', title_ja = '時間の感覚が芽生えています ⏱️', body_ja = '「あした」「きのう」「あとで」をよく使うけれど、ときどき使う場所がちがう？時間の感覚が育っています！こうしたチャレンジを笑顔で聞いてあげましょう。', title_ko = '시간 개념이 생겨요 ⏱️', body_ko = '''내일'', ''어제'', ''이따가''를 자주 쓰지만 가끔 엉뚱한 자리에 쓰나요? 시간 감각이 자라고 있어요! 이런 시도를 미소 지으며 들어 주세요.', title_nl = 'Besef van tijd ontstaat ⏱️', body_nl = 'Gebruikt hij vaak woorden als ''morgen'', ''gisteren'' en ''straks'', maar soms op de verkeerde plek? Zijn tijdsbesef ontwikkelt zich! Luister met een glimlach naar zijn pogingen.', title_pl = 'Rodzi się poczucie czasu ⏱️', body_pl = 'Często używa słów „jutro”, „wczoraj”, „potem”, choć czasem nie na miejscu? Kształtuje się poczucie czasu! Słuchaj tych prób z uśmiechem.', title_pt = 'Nasce a noção de tempo ⏱️', body_pt = 'Usa muitas vezes as palavras "amanhã", "ontem" e "depois", mas às vezes no sítio errado? A perceção do tempo está a formar-se! Ouça estas tentativas com um sorriso.', title_sv = 'Tidsuppfattningen tar form ⏱️', body_sv = 'Använder barnet orden i morgon, i går och sedan ofta, men ibland på fel ställe? Tidsuppfattningen håller på att formas! Lyssna på försöken med ett leende.', title_vi = 'Khái niệm thời gian hình thành ⏱️', body_vi = 'Bé thường dùng các từ "ngày mai", "hôm qua", "lát nữa", nhưng đôi khi đặt sai chỗ? Nhận thức về thời gian đang hình thành! Hãy mỉm cười lắng nghe những cố gắng của bé.', title_zh = '时间概念出现了 ⏱️', body_zh = '经常说“明天”“昨天”“等会儿”，但有时用错地方？时间感正在形成！笑着听宝宝的这些尝试吧。' WHERE id = '354da7a1-73e7-4191-ab3d-5f7d75ac4224' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Intenta trepar para salir de la cuna? Por seguridad, revisa de nuevo la habitación. Ya se acerca el momento de pasar a una cama de niño mayor.', body_fr = 'Il essaie d''escalader son lit à barreaux pour en sortir ? Revérifiez la sécurité de la chambre. Le moment du passage au grand lit approche.', body_hi = 'अपने पालने से चढ़कर बाहर निकलने की कोशिश करता है? सुरक्षा के लिए कमरे की फिर से जाँच कीजिए। बड़े बच्चे के बिस्तर पर जाने का समय अब आ रहा है।', body_id = 'Ia mencoba memanjat keluar dari boksnya? Periksa kembali keamanan kamar. Waktu untuk pindah ke tempat tidur anak besar sudah hampir tiba.', body_ja = 'ベビーベッドからよじのぼって出ようとしている？安全のために、部屋をもう一度見直しましょう。大きい子用のベッドに移る時期が近づいています。', body_ko = '아기 침대에서 기어 나오려 하나요? 안전을 위해 방을 다시 점검하세요. 큰 아이 침대로 옮길 때가 다가오고 있어요.', body_nl = 'Probeert hij uit zijn ledikantje te klimmen? Controleer de kamer opnieuw op veiligheid. De tijd voor de overstap naar een groot kinderbed komt eraan.', body_pl = 'Próbuje wydostać się z łóżeczka? Jeszcze raz sprawdź bezpieczeństwo pokoju. Zbliża się czas przejścia na duże łóżko.', body_pt = 'Tenta trepar para fora do berço? Por segurança, volte a verificar o quarto. Está a chegar a altura de passar para uma cama de criança grande.', body_sv = 'Försöker barnet klättra ur spjälsängen? Gå igenom rummet igen för säkerhetens skull. Det börjar bli dags att gå över till en stor barnsäng.', body_vi = 'Bé cố trèo ra khỏi cũi? Hãy kiểm tra lại độ an toàn của căn phòng. Đã sắp đến lúc chuyển sang giường lớn rồi.', body_zh = '想从婴儿床里爬出来？为了安全，重新检查一遍房间。换成大孩子床的时候已经快到了。' WHERE id = 'c1a7e066-6918-4641-ab6d-c5c20c553974' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Da de comer a sus juguetes y los cura? El juego simbólico es la base de la empatía. Anota con orgullo este salto cognitivo en el Seguimiento del desarrollo.', body_fr = 'Il donne à manger à ses jouets, les soigne ? Le jeu symbolique est la base de l''empathie. Notez fièrement ce bond cognitif dans le Suivi de développement.', body_hi = 'अपने खिलौनों को खाना खिलाता है, उनका इलाज करता है? प्रतीकात्मक खेल सहानुभूति की नींव हैं। इस मानसिक छलाँग को गर्व से ग्रोथ ट्रैकर में दर्ज कीजिए।', body_id = 'Ia menyuapi mainannya dan merawatnya seperti dokter? Permainan simbolis adalah dasar empati. Catat lompatan kognitif ini dengan bangga di Pelacak Perkembangan.', body_ja = 'おもちゃにごはんをあげたり、手当てをしたりしている？象徴遊びは思いやりの土台です。この認知の飛躍を「発達トラッカー」に誇らしく記録しましょう。', body_ko = '장난감에게 밥을 주고 치료해 주나요? 상징 놀이는 공감 능력의 바탕이에요. 이 인지적 도약을 성장 기록에 뿌듯하게 남겨 두세요.', body_nl = 'Geeft hij zijn knuffels eten en verzorgt hij ze als ze ''ziek'' zijn? Symbolisch spel is de basis van empathie. Noteer deze cognitieve sprong trots in de Groeitracker.', body_pl = 'Karmi swoje zabawki i je leczy? Zabawa symboliczna to fundament empatii. Zapisz z dumą ten skok poznawczy w Śledzeniu rozwoju.', body_pt = 'Dá de comer aos brinquedos e trata deles? O jogo simbólico é a base da empatia. Registe com orgulho este salto cognitivo no Registo de Crescimento.', body_sv = 'Matar barnet sina leksaker och behandlar dem? Symbolisk lek är grunden för empati. Anteckna stolt det här kognitiva språnget i Utvecklingsspåraren.', body_vi = 'Bé cho đồ chơi ăn, "chữa bệnh" cho chúng? Trò chơi biểu tượng là nền tảng của sự đồng cảm. Hãy tự hào ghi lại bước nhảy vọt nhận thức này trong Theo dõi phát triển.', body_zh = '给玩具喂饭、给它们“治病”？象征性游戏是共情的基础。骄傲地把这次认知飞跃记在发育追踪里吧。' WHERE id = '46401ae3-aa9a-4ec9-afa2-b6cab38572ff' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le cuesta dormirse? En Cuentos inteligentes crea la historia del osito héroe que se lava los dientes y convierte los nuevos hábitos en cuentos.', body_fr = 'Il a du mal à s''endormir ? Dans les Contes intelligents, créez l''histoire du petit ours héros qui se brosse les dents et racontez les nouvelles habitudes sous forme d''histoire.', body_hi = 'सोने में मुश्किल होती है? स्मार्ट कहानियों में ‘दाँत ब्रश करने वाला हीरो भालू’ की कहानी बनाकर नई आदतों को कहानी में ढालिए।', body_id = 'Ia sulit tertidur? Di Dongeng Pintar, buat cerita tentang ''beruang pahlawan yang menggosok gigi'' dan jadikan kebiasaan baru sebagai dongeng.', body_ja = 'なかなか寝つけない？「スマートおはなし」で「歯みがきをするくまさんヒーロー」のお話をつくって、新しい習慣をお話にしてみましょう。', body_ko = '잠드는 데 어려움을 겪나요? 스마트 동화에서 ''이를 닦는 용감한 곰돌이'' 이야기를 만들어 새로운 습관을 이야기로 전해 주세요.', body_nl = 'Heeft hij moeite met in slaap vallen? Maak in Slimme sprookjes een verhaal over ''het heldhaftige beertje dat zijn tanden poetst'' en giet nieuwe gewoontes in een verhaal.', body_pl = 'Ma trudności z zasypianiem? Stwórz w Mądrych bajkach historię o misiu-bohaterze, który myje zęby, i zamień nowe nawyki w opowieść.', body_pt = 'Tem dificuldade em adormecer? Crie nas Histórias Inteligentes a história do "ursinho herói que lava os dentes" e transforme os novos hábitos em histórias.', body_sv = 'Har barnet svårt att somna? Skapa en berättelse om nallehjälten som borstar tänderna i Smarta sagor och gör de nya vanorna till en saga.', body_vi = 'Bé khó vào giấc? Hãy kể chuyện hóa những thói quen mới bằng cách tạo trong Truyện cổ tích thông minh câu chuyện về "chú gấu anh hùng biết đánh răng".', body_zh = '入睡有困难？在智慧童话里编一个“会刷牙的小熊英雄”的故事，把新习惯变成故事讲给宝宝听。' WHERE id = '4cba464d-475d-46de-93c9-1a54b6d0a768' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Más que jugar con otros niños, juega a lo suyo a su lado? El juego en paralelo es totalmente natural a esta edad. Apoya su socialización sin presionarle.', body_fr = 'Il joue à côté des autres enfants plutôt qu''avec eux ? Le jeu parallèle est tout à fait naturel à cet âge. Soutenez sa socialisation sans le brusquer.', body_hi = 'दूसरे बच्चों के साथ खेलने से ज़्यादा, उनके पास अपना खेल खेलता है? इस उम्र में पैरेलल प्ले बिल्कुल स्वाभाविक है। उस पर दबाव डाले बिना उसके घुलने-मिलने में साथ दीजिए।', body_id = 'Daripada bermain dengan anak lain, ia lebih suka memainkan permainannya sendiri di samping mereka? Bermain paralel sangat wajar di usia ini. Dukung ia bersosialisasi tanpa menekannya.', body_ja = 'ほかの子と遊ぶより、そばで自分の遊びをしている？平行遊びはこの年ごろにはまったく自然なことです。無理強いせずに、人とかかわる力をサポートしましょう。', body_ko = '다른 아이들과 함께 놀기보다 옆에서 자기 놀이를 하나요? 병행 놀이는 이 나이에 아주 자연스러워요. 재촉하지 말고 사회성을 응원해 주세요.', body_nl = 'Speelt hij liever naast andere kinderen in plaats van met ze? Parallel spel is op deze leeftijd heel natuurlijk. Steun zijn sociale ontwikkeling zonder hem onder druk te zetten.', body_pl = 'Zamiast bawić się z innymi dziećmi, bawi się obok nich po swojemu? Zabawa równoległa jest w tym wieku zupełnie naturalna. Wspieraj jego uspołecznianie bez naciskania.', body_pt = 'Em vez de brincar com as outras crianças, brinca sozinho ao lado delas? A brincadeira paralela é totalmente natural nesta idade. Apoie a socialização dele sem o pressionar.', body_sv = 'Leker barnet sin egen lek bredvid andra barn snarare än med dem? Parallell lek är helt naturligt i den här åldern. Stöd barnets sociala utveckling utan att pressa.', body_vi = 'Thay vì chơi cùng các bạn, bé lại chơi trò riêng của mình bên cạnh các bạn? Chơi song song là hoàn toàn tự nhiên ở tuổi này. Hãy hỗ trợ bé hòa nhập mà không gây áp lực.', body_zh = '比起和其他小朋友一起玩，更喜欢在他们旁边玩自己的？平行游戏在这个年龄完全正常。别给宝宝压力，支持宝宝慢慢学会社交。' WHERE id = '7ef518fa-cecf-4467-bd34-eb7fb3a21761' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha descubierto esa única verdura verde de la sopa y se niega a comer? Busca en el Plan de alimentación las formas más ricas de mezclar las verduras con pasta de colores para despistarle y esconder alimentos nutritivos.', body_fr = 'Il a repéré l''unique légume vert de la soupe et refuse de manger ? Trouvez dans le Plan de nutrition les façons les plus savoureuses de mélanger les légumes à des pâtes colorées pour détourner son attention et cacher les aliments sains.', body_hi = 'सूप में वह एक हरी सब्ज़ी खोजकर खाने से मना कर देता है? फ़ीडिंग प्लान में सब्ज़ियों को रंगीन पास्ता में मिलाकर ध्यान बँटाने और पौष्टिक खाना छिपाने के सबसे स्वादिष्ट तरीके ढूँढिए।', body_id = 'Ia menemukan satu potong sayur hijau di supnya lalu menolak makan? Di Rencana Nutrisi, temukan cara paling lezat untuk mencampur sayur dengan pasta berwarna, mengalihkan perhatiannya, dan menyembunyikan makanan bergizi.', body_ja = 'スープの中のたったひとつの緑の野菜を見つけて、食べるのをやめてしまう？「栄養管理ツール」で、野菜をカラフルなパスタにまぜて気をそらし、体にいい食材を隠すおいしい方法を見つけましょう。', body_ko = '수프 속 초록 채소 하나를 발견하고 안 먹겠다고 하나요? 식단 계획에서 채소를 알록달록한 파스타와 섞어 관심을 돌리고 몸에 좋은 음식을 숨기는 가장 맛있는 방법을 찾아보세요.', body_nl = 'Ontdekt hij dat ene groene stukje groente in zijn soep en weigert hij te eten? Vind in het Voedingsplan de lekkerste manieren om groenten met kleurrijke pasta te mengen, de aandacht af te leiden en gezond eten te verstoppen.', body_pl = 'Odkrył w zupie ten jeden zielony kawałek warzywa i nie chce jeść? Znajdź w planie karmienia najsmaczniejsze sposoby na mieszanie warzyw z kolorowym makaronem, odwracanie uwagi i ukrywanie zdrowych składników.', body_pt = 'Descobriu aquele único legume verde na sopa e recusa comer? Encontre no Registo de Alimentação as formas mais saborosas de misturar os legumes com massa colorida, distrair a atenção e esconder os alimentos saudáveis.', body_sv = 'Upptäckte barnet den enda gröna grönsaken i soppan och vägrar äta? Hitta de godaste sätten i matplanen att blanda grönsaker med färgglad pasta, avleda uppmärksamheten och gömma nyttig mat.', body_vi = 'Bé phát hiện đúng một miếng rau xanh trong bát súp và không chịu ăn? Hãy tìm trong Kế hoạch dinh dưỡng những cách ngon nhất để trộn rau với mì ống nhiều màu, đánh lạc hướng bé và giấu thực phẩm bổ dưỡng.', body_zh = '发现汤里有一根绿色蔬菜，就不肯吃了？在喂养计划里找找最美味的办法：把蔬菜和彩色意面混在一起，转移注意力，把有营养的食物藏起来。' WHERE id = '85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesión de emociones 📝', body_es = '¿Te sientes mal por pasarte el día diciendo «no» a todo? Abre el Diario de ánimo. Escribe sin filtros ese pensamiento más oscuro de hoy, «ojalá estuviera sola». No te culpes: toda madre a veces se cansa y quiere huir.', title_fr = 'Avouer ses émotions 📝', body_fr = 'Vous vous sentez mal d''avoir dit « non » à tout toute la journée ? Ouvrez le Journal d''humeur. Écrivez sans filtre cette pensée la plus sombre : « si seulement j''étais seule ». Ne vous jugez pas, chaque maman est parfois fatiguée et a envie de fuir.', title_hi = 'भावनाओं का इकरार 📝', body_hi = 'दिनभर हर बात पर ‘ना’ कहकर बुरा लग रहा है? मूड डायरी खोलिए। आज मन के अंदर का वह सबसे अँधेरा ‘काश मैं अकेली होती’ वाला ख्याल बिना फ़िल्टर लिख दीजिए। खुद को दोष मत दीजिए, हर माँ कभी-कभी थकती है और भाग जाना चाहती है।', title_id = 'Mengakui perasaan 📝', body_id = 'Merasa buruk karena seharian berkata ''tidak'' pada segalanya? Buka Buku Harian Suasana Hati. Tuliskan tanpa filter pikiran paling gelap hari ini, ''andai saja aku sendirian''. Jangan menyalahkan diri, setiap ibu kadang lelah dan ingin kabur.', title_ja = '気持ちを打ち明けて 📝', body_ja = '一日じゅう何にでも「だめ」と言ってしまって、落ちこんでいますか？「気分日記」を開きましょう。今日、心の奥にあった「ひとりになれたらいいのに」という暗い気持ちを、そのまま書いて。自分を責めないで。どんなママもときには疲れて、逃げ出したくなるものです。', title_ko = '감정 고백 📝', body_ko = '하루 종일 모든 것에 ''안 돼''라고 해서 마음이 안 좋나요? 기분 일기를 열어 보세요. 오늘 마음속 가장 어두운 ''혼자였으면 좋겠다''는 생각도 걸러내지 말고 적으세요. 자책하지 마세요, 모든 엄마는 가끔 지치고 도망치고 싶어 해요.', title_nl = 'Je emoties toegeven 📝', body_nl = 'Voel je je rot omdat je de hele dag overal nee op zei? Open je Stemmingsdagboek. Schrijf ongefilterd die donkerste gedachte op: ''was ik maar alleen''. Veroordeel jezelf niet, elke mama is soms moe en wil weg.', title_pl = 'Przyznaj się do emocji 📝', body_pl = 'Czujesz się źle, bo cały dzień mówiłaś „nie” na wszystko? Otwórz Dziennik nastroju. Zapisz bez filtra tę najmroczniejszą myśl „gdybym tylko była sama”. Nie obwiniaj się, każda mama czasem się męczy i chce uciec.', title_pt = 'Confissão das emoções 📝', body_pt = 'Sente-se mal por dizer "não" a tudo o dia inteiro? Abra o Diário de Humor. Escreva sem filtros aquele pensamento mais sombrio de hoje: "quem me dera estar sozinha". Não se culpe, todas as mães às vezes se cansam e querem fugir.', title_sv = 'Erkänn känslorna 📝', body_sv = 'Mår du dåligt av att ha sagt nej till allt hela dagen? Öppna Humördagboken. Skriv ofiltrerat ner den mörkaste tanken du hade i dag: ”om jag bara fick vara ensam”. Döm inte dig själv, varje mamma blir ibland trött och vill fly.', title_vi = 'Thừa nhận cảm xúc 📝', body_vi = 'Cả ngày phải nói "không" với mọi thứ khiến mẹ thấy tệ? Hãy mở Nhật ký tâm trạng. Hôm nay, hãy viết ra không cần chọn lọc ý nghĩ u tối nhất trong lòng: "Giá như mình được ở một mình". Đừng tự trách, người mẹ nào cũng có lúc mệt và muốn trốn đi.', title_zh = '情绪的坦白 📝', body_zh = '一整天对什么都说“不”，让你心里很难受？打开心情日记。把今天心底最阴暗的那句“要是我能一个人待着就好了”毫无保留地写下来。别责怪自己，每个妈妈都有累了、想逃开的时候。' WHERE id = '9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No es culpa mía! 🤷‍♂️', body_es = 'Ha tirado el agua al suelo a propósito, pero le echa la culpa a la mesa: «Se ha movido la mesa». No es una mentira, es el instinto del cerebro infantil de esquivar la responsabilidad y defenderse. No discutas: transmítele la responsabilidad sin herirle diciendo «Vamos a ayudar a la mesa y a secarlo juntos».', title_fr = 'C''est pas ma faute ! 🤷‍♂️', body_fr = 'Il a renversé l''eau exprès, mais a rejeté la faute sur la table : « La table a glissé ». Ce n''est pas un mensonge, c''est l''instinct du cerveau de l''enfant pour échapper à la responsabilité et se protéger. Ne vous entêtez pas, transmettez la responsabilité sans le blesser : « Viens, on aide la table et on essuie ensemble. »', title_hi = 'यह मेरी गलती नहीं है! 🤷‍♂️', body_hi = 'जानबूझकर पानी गिराया, पर दोष मेज़ पर डालकर बोला, ‘मेज़ फिसल गई।’ यह झूठ नहीं, बच्चे के दिमाग की ज़िम्मेदारी से बचने और खुद को बचाने की स्वाभाविक प्रवृत्ति है। ज़िद मत कीजिए, ‘आओ, मेज़ की मदद करके साथ में पोंछें’ कहकर बिना ठेस पहुँचाए ज़िम्मेदारी सिखाइए।', title_id = 'Ini bukan salahku! 🤷‍♂️', body_id = 'Ia sengaja menumpahkan air ke lantai, tapi menyalahkan meja: ''Mejanya licin.'' Ini bukan bohong, ini naluri otak anak untuk menghindari tanggung jawab dan membela diri. Jangan berdebat, tanamkan tanggung jawab tanpa menyakiti dengan berkata ''Ayo kita bantu meja dan lap sama-sama''.', title_ja = 'ぼくのせいじゃない！ 🤷‍♂️', body_ja = 'わざとお水を床にこぼしたのに、テーブルのせいにして「テーブルがすべった」と言う。これはうそではなく、責任を避けて自分を守ろうとする子どもの脳の本能です。言い合わずに「テーブルを助けて、一緒に拭こう」と声をかけて、傷つけずに責任を教えましょう。', title_ko = '내 잘못 아니야! 🤷‍♂️', body_ko = '일부러 물을 쏟고는 ''식탁이 미끄러졌어''라며 식탁 탓을 하나요? 거짓말이 아니라 책임을 피하고 자신을 지키려는 아이 뇌의 본능이에요. 고집 싸움 말고 ''식탁을 도와서 같이 닦자''라며 상처 주지 않고 책임감을 가르쳐 주세요.', title_nl = 'Het is niet mijn schuld! 🤷‍♂️', body_nl = 'Hij gooide expres water op de grond, maar gaf de tafel de schuld: ''De tafel gleed weg.'' Dat is geen liegen, maar het instinct van een kinderbrein om verantwoordelijkheid te ontlopen en zichzelf te beschermen. Ga er niet tegenin, maar leer hem verantwoordelijkheid zonder te kwetsen: ''Kom, we helpen de tafel en vegen het samen op.''', title_pl = 'To nie moja wina! 🤷‍♂️', body_pl = 'Celowo wylał wodę na podłogę, ale zwalił winę na stół: „Stół się przesunął”. To nie kłamstwo, tylko instynkt dziecięcego mózgu, by uniknąć odpowiedzialności i się bronić. Nie kłóć się, ucz odpowiedzialności bez ranienia: „Pomóżmy stołowi i wytrzyjmy to razem”.', title_pt = 'A culpa não é minha! 🤷‍♂️', body_pt = 'Entornou a água no chão de propósito, mas culpou a mesa: "A mesa escorregou". Não é mentira, é o instinto do cérebro infantil de fugir à responsabilidade e se defender. Não teime: diga "Vamos ajudar a mesa e limpar juntos" e ensine responsabilidade sem o magoar.', title_sv = 'Det är inte mitt fel! 🤷‍♂️', body_sv = 'Barnet hällde ut vattnet på golvet med flit men skyllde på bordet: ”Bordet gled.” Det är ingen lögn, det är barnhjärnans instinkt att undvika ansvar och försvara sig. Bråka inte, säg ”Kom så hjälper vi bordet och torkar upp tillsammans” och lär ut ansvar utan att såra.', title_vi = 'Không phải lỗi của con! 🤷‍♂️', body_vi = 'Bé cố tình đổ nước ra sàn, nhưng lại đổ lỗi cho cái bàn: "Cái bàn bị trượt". Đây không phải nói dối, mà là bản năng né tránh trách nhiệm và tự vệ của não bộ trẻ. Đừng giằng co, hãy nhẹ nhàng dạy trách nhiệm: "Mình cùng giúp cái bàn lau sạch nhé".', title_zh = '不是我的错！🤷‍♂️', body_zh = '故意把水洒在地上，却把责任推给桌子：“是桌子滑了。”这不是撒谎，而是孩子大脑逃避责任、保护自己的本能。别较劲，说一句“我们来帮帮桌子，一起擦干净吧”，不伤害宝宝地教会责任。' WHERE id = 'df69592f-4c0f-4591-8df6-51164eef4e12' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La psicología de las cuatro paredes ⛅', body_es = 'La casa te agobia y el peque se pone agresivo. Consulta Tiempo y ropa, elige el conjunto más adecuado y salid corriendo al parque. El oxígeno y la libertad de movimiento serán el mejor detox para su cerebro y para tus nervios cansados.', title_fr = 'La psychologie des quatre murs ⛅', body_fr = 'La maison vous étouffe et l''enfant devient agressif. Consultez Météo et tenue, choisissez la tenue la plus adaptée et filez au parc. L''oxygène et la liberté de mouvement seront la meilleure détox, pour son cerveau comme pour vos nerfs fatigués.', title_hi = 'चार दीवारों का मनोविज्ञान ⛅', body_hi = 'घर आपको घुटन दे रहा है, और बच्चा चिड़चिड़ा हो रहा है। मौसम और कपड़े देखिए, सबसे सही कपड़े चुनिए और दरवाज़ा खोलकर पार्क की ओर भागिए। ऑक्सीजन और घूमने की आज़ादी उसके दिमाग और आपकी थकी नसों, दोनों के लिए सबसे अच्छा डिटॉक्स होगी।', title_id = 'Psikologi empat dinding ⛅', body_id = 'Rumah terasa menyesakkan, dan anak menjadi agresif. Cek Cuaca dan Pakaian, pilih setelan yang paling cocok, lalu bergegas ke taman. Oksigen dan kebebasan bergerak akan menjadi detoks terbaik untuk otaknya sekaligus saraf Anda yang lelah.', title_ja = '4つの壁の心理学 ⛅', body_ja = '家にいると息がつまり、子どもはイライラ。「天気と服装」をチェックして、ぴったりのコーデを選んだら、勢いよくドアを開けて公園へ！酸素と体を動かす自由は、この子の脳にも、あなたの疲れた神経にも、いちばんのデトックスになります。', title_ko = '네 벽의 심리학 ⛅', body_ko = '집이 답답하고 아이는 날카로워지나요? 날씨와 옷차림을 확인해 알맞은 옷을 고르고, 문을 박차고 공원으로 달려가세요. 산소와 움직임의 자유가 아이의 뇌와 엄마의 지친 신경 모두에 최고의 디톡스가 될 거예요.', title_nl = 'De psychologie van vier muren ⛅', body_nl = 'Het huis benauwt je en je kind wordt agressief. Check Weer en kleding, kies de beste outfit en ga snel naar het park. Zuurstof en bewegingsvrijheid zijn de beste detox voor zijn brein en voor jouw vermoeide zenuwen.', title_pl = 'Psychologia czterech ścian ⛅', body_pl = 'Dom cię przytłacza, a dziecko robi się agresywne. Sprawdź Pogodę i ubiór, wybierz najlepszy zestaw i biegnijcie do parku. Tlen i swoboda ruchu będą najlepszym detoksem i dla jego mózgu, i dla twoich zmęczonych nerwów.', title_pt = 'A psicologia das quatro paredes ⛅', body_pt = 'A casa sufoca-a e a criança fica agressiva. Veja o Tempo e Roupa, escolha a combinação mais adequada e saiam porta fora a correr para o parque. O oxigénio e a liberdade de movimento serão o melhor detox para o cérebro dele e para os seus nervos cansados.', title_sv = 'Fyra väggars psykologi ⛅', body_sv = 'Hemmet känns trångt och barnet blir argt. Kolla Väder och kläder, välj den klädsel som passar bäst och rusa ut till parken. Syre och rörelsefrihet blir den bästa detoxen både för barnets hjärna och för dina trötta nerver.', title_vi = 'Tâm lý bốn bức tường ⛅', body_vi = 'Ở nhà mẹ thấy ngột ngạt, còn bé thì cáu kỉnh. Hãy kiểm tra Thời tiết và trang phục, chọn bộ đồ phù hợp nhất rồi đóng cửa ra công viên ngay. Không khí trong lành và tự do vận động sẽ là cách "giải độc" tốt nhất cho cả não bộ của bé lẫn thần kinh mỏi mệt của mẹ.', title_zh = '四面墙心理学 ⛅', body_zh = '家里让你喘不过气，孩子也越来越烦躁。看看天气与穿衣，挑好最合适的搭配，摔门而出奔向公园吧。氧气和自由活动，对宝宝的大脑和你疲惫的神经来说，都是最好的排毒。' WHERE id = '7ac03452-73e8-4680-9a3a-f2917f96ee7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación doblar la ropa 🧺', body_es = 'Tú doblas con mucho esfuerzo la ropa limpia y él en 2 segundos se mete dentro y lo deshace todo. Se hace un gran silencio en la habitación... ¿Tienes los nervios a flor de piel? Respira hondo. Tírate encima del montón de ropa y ríndete riendo ante este caos.', title_fr = 'Opération pliage du linge 🧺', body_fr = 'Vous pliez le linge propre avec beaucoup d''efforts, et en 2 secondes il plonge dedans et défait tout. Un grand silence tombe sur la pièce... Vos nerfs sont à vif ? Respirez profondément. Jetez-vous sur la pile de linge en désordre et rendez-vous à ce chaos en riant.', title_hi = 'कपड़े तह करने का ऑपरेशन 🧺', body_hi = 'आप बड़ी मेहनत से साफ़ कपड़े तह करती हैं, और वह 2 सेकंड में उनमें घुसकर सब बिखेर देता है। कमरे में गहरी खामोशी छा जाती है... नसें तनी हुई हैं? गहरी साँस लीजिए। बिखरे कपड़ों के ढेर पर खुद भी गिर जाइए और हँसते हुए इस अफ़रा-तफ़री के आगे हार मान लीजिए।', title_id = 'Operasi melipat baju 🧺', body_id = 'Anda melipat baju bersih dengan susah payah, dan dalam 2 detik ia masuk ke tumpukan itu dan mengacak semuanya. Kamar menjadi sangat hening... Saraf Anda menegang? Tarik napas dalam. Jatuhkan diri ke tumpukan baju yang berantakan itu dan menyerahlah pada kekacauan ini sambil tertawa.', title_ja = '洗濯物たたみ作戦 🧺', body_ja = 'あなたが一生けんめいきれいな服をたたんでいると、この子は2秒でもぐりこんで全部ぐちゃぐちゃに。部屋がしーんと静まりかえる…。神経がピンと張りつめた？深呼吸して。くずれた洗濯物の山に飛びこんで、笑いながらこのカオスに降参しましょう。', title_ko = '빨래 개기 작전 🧺', body_ko = '애써 깨끗한 빨래를 개 놓았는데 2초 만에 들어가 다 흩어 놓았나요? 방에 큰 정적이 흐르고... 신경이 팽팽해졌나요? 깊게 숨 쉬세요. 흩어진 빨래 더미 위로 몸을 던져 이 혼돈에 웃으며 항복해 보세요.', title_nl = 'Operatie was opvouwen 🧺', body_nl = 'Je hebt met veel moeite de schone was opgevouwen, en hij duikt er binnen 2 seconden in en haalt alles overhoop. Het wordt heel stil in de kamer... Staan je zenuwen strak gespannen? Haal diep adem. Laat je op die berg kleren vallen en geef je lachend over aan de chaos.', title_pl = 'Operacja składania prania 🧺', body_pl = 'Z wielkim trudem składasz czyste ubrania, a on w 2 sekundy wskakuje do środka i wszystko rozwala. W pokoju zapada wielka cisza... Nerwy napięte do granic? Weź głęboki oddech. Rzuć się na rozrzucony stos ubrań i ze śmiechem poddaj się temu chaosowi.', title_pt = 'Operação dobrar a roupa 🧺', body_pt = 'Dobra a roupa lavada com muito esforço e ele, em 2 segundos, enfia-se lá dentro e desfaz tudo. Faz-se um grande silêncio no quarto... Está com os nervos em franja? Respire fundo. Atire-se para cima da pilha de roupa desfeita e renda-se a este caos a rir.', title_sv = 'Operation vik tvätt 🧺', body_sv = 'Du viker de rena kläderna med stor möda, och på 2 sekunder kryper barnet in i högen och river upp allt. Det blir knäpptyst i rummet... Är nerverna på helspänn? Andas djupt. Kasta dig själv på den raserade klädhögen och ge upp för kaoset med ett skratt.', title_vi = 'Chiến dịch gấp quần áo 🧺', body_vi = 'Mẹ vất vả gấp xong đống quần áo sạch, còn bé chỉ trong 2 giây đã chui vào và làm tung hết. Căn phòng chìm vào im lặng... Mẹ căng như dây đàn? Hãy hít thở sâu. Ngả mình lên đống quần áo bừa bộn và cười xòa đầu hàng sự hỗn loạn này.', title_zh = '叠衣服行动 🧺', body_zh = '你辛辛苦苦地叠好干净衣服，宝宝2秒钟就钻进去全弄乱了。房间里一片沉默……神经快绷断了？深呼吸。干脆扑到乱糟糟的衣服堆上，笑着向这场混乱投降吧。' WHERE id = 'ab102c70-f16b-4f7f-8521-b11e20c36d7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El director del Cuento inteligente 🪄', body_es = 'Los dos estáis hartos de los héroes de los libros de siempre. Abre Cuentos inteligentes y esta noche deja que él invente la historia. Pregúntale: «¿Y ahora adónde va ese dinosaurio volador?», y deja que se duerma en el mundo de fantasía que invente.', title_fr = 'Le metteur en scène du Conte intelligent 🪄', body_fr = 'Les héros des livres classiques vous lassent tous les deux. Ouvrez les Contes intelligents et, ce soir, laissez-le inventer l''histoire. Demandez : « Où va aller le dinosaure volant maintenant ? » et laissez-le s''endormir dans le monde imaginaire qu''il aura créé.', title_hi = 'स्मार्ट कहानी का निर्देशक 🪄', body_hi = 'आप दोनों पुरानी किताबों के हीरो से ऊब चुके हैं। स्मार्ट कहानियाँ खोलिए और आज शाम कहानी उसे गढ़ने दीजिए। पूछिए, ‘अब वह उड़ने वाला डायनासोर कहाँ जाए?’ और उसे अपनी गढ़ी कल्पना की दुनिया में सोने दीजिए।', title_id = 'Sutradara Dongeng Pintar 🪄', body_id = 'Kalian berdua sudah bosan dengan tokoh-tokoh di buku klasik. Buka Dongeng Pintar dan malam ini biarkan ia mengarang alur ceritanya. Tanyakan ''Sekarang dinosaurus terbang itu pergi ke mana?'', dan biarkan ia tertidur di dunia khayal karangannya.', title_ja = 'スマートおはなしの監督さん 🪄', body_ja = '定番の絵本の主人公には、ふたりとも飽きてしまった？「スマートおはなし」を開いて、今夜はストーリーをこの子に考えてもらいましょう。「この空飛ぶ恐竜、次はどこへ行く？」とたずねて、考えた空想の世界で眠りにつかせてあげて。', title_ko = '스마트 동화의 감독 🪄', body_ko = '늘 읽던 책 속 주인공들이 둘 다 지겨워졌나요? 스마트 동화를 열고 오늘 저녁엔 이야기를 아이가 지어내게 해 보세요. ''이제 하늘을 나는 공룡은 어디로 갈까?'' 묻고, 아이가 만든 상상의 세계에서 잠들게 해 주세요.', title_nl = 'De regisseur van het Slimme sprookje 🪄', body_nl = 'Zijn jullie allebei de helden uit de klassieke boeken beu? Open Slimme sprookjes en laat hem vanavond het verhaal bedenken. Vraag: ''Waar moet die vliegende dinosaurus nu naartoe?'' en laat hem in slaap vallen in de fantasiewereld die hij bedenkt.', title_pl = 'Reżyser Mądrej bajki 🪄', body_pl = 'Bohaterowie klasycznych książeczek znudzili się wam obojgu. Otwórz Mądre bajki i pozwól mu dziś wieczorem wymyślić fabułę. Zapytaj: „Dokąd teraz ma lecieć ten latający dinozaur?” i niech zaśnie w wymyślonym przez siebie świecie.', title_pt = 'O realizador da história inteligente 🪄', body_pt = 'Estão os dois fartos dos heróis dos livros clássicos. Abra as Histórias Inteligentes e deixe que esta noite seja ele a inventar o enredo. Pergunte "E agora, para onde vai aquele dinossauro voador?" e deixe-o adormecer no mundo de fantasia que inventar.', title_sv = 'Regissören av den smarta sagan 🪄', body_sv = 'Ni är båda trötta på hjältarna i de klassiska böckerna. Öppna Smarta sagor och låt barnet hitta på handlingen i kväll. Fråga ”Vart ska den flygande dinosaurien åka nu?” och låt barnet somna i sin egen påhittade drömvärld.', title_vi = 'Đạo diễn của câu chuyện thông minh 🪄', body_vi = 'Cả hai mẹ con đều đã chán những nhân vật trong sách quen thuộc. Hãy mở Truyện cổ tích thông minh và tối nay để bé tự sáng tác cốt truyện. Hỏi bé: "Giờ chú khủng long biết bay nên đi đâu nhỉ?", rồi để bé chìm vào giấc ngủ trong thế giới tưởng tượng của mình.', title_zh = '智慧童话的小导演 🪄', body_zh = '经典故事书里的英雄你们俩都看腻了。打开智慧童话，今晚让宝宝来编故事。问问：“现在那只会飞的恐龙该去哪儿？”就让宝宝在自己编的梦幻世界里入睡吧。' WHERE id = 'e3d6247b-8c6f-4322-9f82-93d3245cab38' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar energía en casa e inventa mil excusas para no ir a la cama. Llama a papá. Cuando lo levanta en el aire y lo hace volar como un avión, las carcajadas llenan la habitación y toda la agresividad física acumulada desaparece con el sudor.', body_fr = 'Il n''a pas pu se dépenser à la maison et invente mille excuses pour ne pas aller au lit. Appelez papa. Quand il le soulève pour un vol en avion, les éclats de rire remplissent la pièce et toute l''agressivité physique accumulée s''évacue.', body_hi = 'घर में ऊर्जा निकाल नहीं पाया और बिस्तर पर न जाने के हज़ार बहाने बना रहा है। पापा को बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ की उड़ान कराते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक गुस्सा पसीने के साथ गायब हो जाता है।', body_id = 'Ia belum sempat menyalurkan energinya di rumah dan mengarang seribu alasan agar tidak tidur. Panggil Ayah. Saat Ayah mengangkatnya tinggi dan mengajaknya ''terbang naik pesawat'', tawa memenuhi kamar dan semua ketegangan fisik yang menumpuk lenyap bersama keringat.', body_ja = '家でエネルギーを発散しきれず、寝ないための言いわけを千個も考えだします。パパを呼びましょう。パパが子どもを持ち上げて飛行機のように飛ばすと、部屋は笑い声でいっぱいになり、たまっていた体のイライラは汗と一緒に消えていきます。', body_ko = '집에서 에너지를 다 쓰지 못해 자지 않으려고 핑계를 천 개나 만들어 내나요? 아빠를 불러 주세요. 아빠가 아이를 번쩍 들어 비행기를 태우면 웃음소리가 방을 채우고, 쌓인 몸의 공격성이 땀과 함께 사라져요.', body_nl = 'Hij is zijn energie in huis niet kwijtgeraakt en verzint duizend smoesjes om niet naar bed te hoeven. Roep papa. Als hij hem optilt voor een vliegtuigvlucht, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke agressie zwetend.', body_pl = 'Nie wyładował energii w domu i wymyśla tysiąc wymówek, żeby nie iść do łóżka. Zawołaj tatę. Gdy podniesie go w górę na „lot samolotem”, śmiech wypełni pokój, a całe nagromadzone napięcie zniknie.', body_pt = 'Não conseguiu gastar a energia em casa e inventa mil desculpas para não ir para a cama. Chame o pai. Quando ele o levanta no ar e faz voos de avião, as gargalhadas enchem o quarto e toda a agressividade física acumulada desaparece a suar.', body_sv = 'Barnet har inte fått ur sig energin hemma och hittar på tusen ursäkter för att slippa gå och lägga sig. Kalla på pappa. När han lyfter upp barnet i luften och flyger flygplan fylls rummet av skratt, och all ansamlad fysisk ilska försvinner i form av svett.', body_vi = 'Bé chưa xả hết năng lượng trong nhà và nghĩ ra cả nghìn lý do để không đi ngủ. Hãy gọi bố. Khi bố nhấc bé lên cao "bay như máy bay", tiếng cười sẽ ngập tràn căn phòng và mọi năng lượng dồn nén sẽ tan biến cùng những giọt mồ hôi.', body_zh = '在家没把精力释放完，为了不上床编出一千个借口。叫爸爸来吧。当爸爸把宝宝举高高“开飞机”时，笑声充满房间，积攒的所有身体上的躁动都随着汗水消失了。' WHERE id = '62178f50-5d62-4afb-bacf-33c6e7bf5732' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Como no le compraste el juguete que quería, te ha mirado y te ha dicho «eres mala»? Que no se te rompa el corazón. Todavía no sabe expresar sus sentimientos con las palabras correctas; en realidad quiere decir «estoy muy enfadado y decepcionado». Mírale a los ojos y hazle saber que aceptas su emoción.', body_fr = 'Il vous a regardée en disant « T''es méchante » parce que vous ne lui avez pas acheté le jouet qu''il voulait ? Ne vous laissez pas blesser. Il ne sait pas encore exprimer ses sentiments avec les bons mots, il veut en fait dire « je suis très en colère et déçu ». Regardez-le dans les yeux et montrez-lui simplement que vous accueillez son émotion.', body_hi = 'उसका मनपसंद खिलौना नहीं दिलाया तो आपकी ओर देखकर बोला, ‘तुम बुरी हो’? दिल मत तोड़िए। वह अभी अपनी भावनाएँ सही शब्दों में नहीं कह पाता, असल में वह कहना चाहता है, ‘मैं बहुत नाराज़ और निराश हूँ।’ आँख मिलाइए और बस बताइए कि आप उसकी भावना समझती हैं।', body_id = 'Karena Anda tidak membelikan mainan yang ia mau, ia menatap Anda dan berkata ''Mama jahat''? Jangan sakit hati. Ia belum bisa mengungkapkan perasaannya dengan kata yang tepat, sebenarnya ia ingin berkata ''aku sangat marah dan kecewa''. Tatap matanya dan sampaikan saja bahwa Anda menerima perasaannya.', body_ja = 'ほしいおもちゃを買ってあげなかったら、あなたの顔を見て「ママ、いじわる」と言った？傷つかないで。まだ気持ちを正しい言葉で表せないだけで、本当は「すごく怒ってるし、がっかりしてる」と言いたいんです。目を合わせて、気持ちを受けとめていると伝えてあげましょう。', body_ko = '원하는 장난감을 안 사 줬다고 엄마 얼굴을 보며 ''엄마 나빠''라고 했나요? 상처받지 마세요. 아직 감정을 알맞은 말로 표현하지 못해서, 사실은 ''나 너무 화나고 속상해''라고 말하고 싶은 거예요. 눈을 맞추고 그 감정을 받아 준다는 걸 알려 주세요.', body_nl = 'Keek hij je aan en zei hij ''Jij bent stom'' omdat je het speelgoed dat hij wilde niet kocht? Laat je hart niet breken. Hij kan zijn gevoelens nog niet met de juiste woorden uitdrukken, eigenlijk wil hij zeggen: ''Ik ben heel boos en teleurgesteld.'' Maak oogcontact en laat gewoon merken dat je zijn gevoel erkent.', body_pl = 'Nie kupiłaś mu wymarzonej zabawki, więc spojrzał na ciebie i powiedział „Jesteś zła”? Nie bierz tego do serca. Nie umie jeszcze wyrazić uczuć właściwymi słowami, tak naprawdę chce powiedzieć „Jestem bardzo zły i rozczarowany”. Nawiąż kontakt wzrokowy i po prostu daj znać, że przyjmujesz jego emocje.', body_pt = 'Olhou para si e disse "és má" porque não lhe comprou o brinquedo que queria? Não fique de coração partido. Ainda não consegue exprimir os sentimentos com as palavras certas: na verdade quer dizer "estou muito zangado e desiludido". Faça contacto visual e mostre apenas que aceita a emoção dele.', body_sv = 'Sa barnet ”Du är dum” och tittade på dig för att du inte köpte leksaken det ville ha? Bli inte sårad. Barnet kan ännu inte uttrycka sina känslor med rätt ord, egentligen vill det säga ”jag är väldigt arg och besviken”. Ta ögonkontakt och visa bara att du tar emot känslan.', body_vi = 'Vì mẹ không mua món đồ chơi bé muốn, bé nhìn mẹ và nói "Mẹ xấu lắm"? Đừng buồn lòng. Bé chưa thể diễn đạt cảm xúc bằng từ ngữ đúng, thật ra bé muốn nói "Con đang rất tức và thất vọng". Hãy nhìn vào mắt bé và cho bé biết mẹ hiểu cảm xúc ấy.', body_zh = '因为没给买想要的玩具，就看着你说“你是坏人”？别伤心。宝宝还不会用正确的词表达感受，其实是想说“我很生气，也很失望”。和宝宝对视，让宝宝知道你接纳了这份情绪就好。' WHERE id = '7338bae4-7d68-4f02-8b9f-7e3603f62bb9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del «¡En el súper conduzco yo!» 🛒', body_es = 'Quiere empujar él solo el carro del súper y choca con las estanterías llamando la atención de todos. Cada vez que intervienes, llora. Empujadlo juntos. Y para no olvidar nada, ten activa la Lista de la compra de la app para que tu cerebro se canse menos.', title_fr = 'L''entêtement du « C''est moi qui pousse ! » au supermarché 🛒', body_fr = 'Il veut pousser lui-même le chariot et attire tous les regards en heurtant les rayons. Dès que vous intervenez, il pleure. Poussez-le ensemble. Et contre les oublis, gardez la Liste de courses de l''application active pour moins fatiguer votre cerveau.', title_hi = 'बाज़ार में ‘मैं चलाऊँगा’ की ज़िद 🛒', body_hi = 'शॉपिंग ट्रॉली खुद चलाना चाहता है और रैक से टकराकर सबका ध्यान खींचता है। जितना रोकेंगी, उतना रोएगा। साथ मिलकर चलाइए। और भूलने से बचने के लिए ऐप की शॉपिंग लिस्ट चालू रखिए, ताकि दिमाग कम थके।', title_id = 'Ngotot ''Aku yang dorong!'' di supermarket 🛒', body_id = 'Ia ingin mendorong troli belanja sendiri dan menabrak rak hingga menarik perhatian semua orang. Setiap kali Anda campur tangan, ia menangis. Dorong troli bersama-sama. Untuk melawan lupa, biarkan Daftar Belanja di aplikasi tetap aktif agar otak Anda tidak terlalu lelah.', title_ja = 'スーパーで「ぼくが押す」の意地 🛒', body_ja = 'ショッピングカートを自分で押したがって、棚にぶつかってはみんなの注目を集める。手を出すたびに泣いてしまいます。一緒に押しましょう。買い忘れ防止には、アプリの「買い物リスト」を開いておけば、頭の疲れも少なくてすみます。', title_ko = '마트에서 ''내가 밀 거야'' 고집 🛒', body_ko = '마트 카트를 자기가 밀겠다며 선반에 부딪혀 모두의 시선을 끌고, 말리면 우나요? 함께 밀어 보세요. 깜빡하지 않게 앱의 쇼핑 목록을 켜 두면 머리가 덜 피곤할 거예요.', title_nl = '''Ik duw!''-koppigheid in de supermarkt 🛒', body_nl = 'Hij wil zelf het boodschappenkarretje duwen, botst tegen de schappen en trekt ieders aandacht. Als je ingrijpt, gaat hij huilen. Duw het karretje samen. En tegen vergeetachtigheid: houd het Boodschappenlijstje in de app bij de hand, dan wordt je brein minder moe.', title_pl = 'Sklepowy upór „Ja będę pchać” 🛒', body_pl = 'Chce sam pchać wózek w sklepie, wpada na półki i przyciąga uwagę wszystkich. Gdy się wtrącasz, płacze. Pchajcie wózek razem. A na zapominalstwo trzymaj otwartą Listę zakupów w aplikacji, żeby twój mózg mniej się męczył.', title_pt = 'A teimosia do "Eu é que conduzo" no supermercado 🛒', body_pt = 'Quer empurrar sozinho o carrinho do supermercado e bate nas prateleiras, chamando a atenção de todos. Sempre que intervém, chora. Empurrem-no juntos. E contra os esquecimentos, mantenha ativa a Lista de Compras da app para cansar menos a cabeça.', title_sv = 'Envisheten ”Jag ska köra!” i butiken 🛒', body_sv = 'Barnet vill köra kundvagnen själv, krockar med hyllorna och drar till sig allas blickar. Ju mer du lägger dig i, desto mer gråter barnet. Kör tillsammans. Och mot glömskan, ha Inköpslistan i appen aktiv så att hjärnan blir mindre trött.', title_vi = '"Con đẩy xe!" ở siêu thị 🛒', body_vi = 'Bé muốn tự đẩy xe siêu thị, đâm vào kệ hàng khiến ai cũng phải chú ý. Mẹ càng can thiệp, bé càng khóc. Hãy cùng bé đẩy xe. Còn để khỏi quên đồ, hãy mở sẵn Danh sách mua sắm trong ứng dụng để đầu óc đỡ mệt hơn.', title_zh = '超市里“我来推”的倔强 🛒', body_zh = '非要自己推购物车，一路撞到货架上，引来所有人的目光。你一插手就哭。那就一起推吧。至于健忘，让应用里的购物清单保持打开，大脑就能少累一点。' WHERE id = 'c4d16b0b-f2b1-40f5-8462-8e7c3419883e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El silencio del Medidor de sonido 🤫', body_es = '¡Por fin se ha dormido! El silencio que cae sobre la casa es tan profundo que se te taponan los oídos. Activa el Medidor de sonido y, mirando los 0-10 decibelios de la pantalla, siente cómo tu cerebro se recupera poco a poco.', title_fr = 'Le silence du Sonomètre 🤫', body_fr = 'Il dort enfin ! Le silence qui tombe sur la maison est si profond qu''il vous bourdonne aux oreilles. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau récupérer peu à peu.', title_hi = 'साउंड मीटर की खामोशी 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी इतनी गहरी है कि कान सुन्न हो जाते हैं। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे ठीक हो रहा है।', title_id = 'Keheningan Pengukur Suara 🤫', body_id = 'Akhirnya ia tertidur! Keheningan di rumah begitu dalam sampai telinga Anda terasa berdenging. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan secara visual bagaimana otak Anda perlahan pulih.', title_ja = 'サウンドメーターの静けさ 🤫', body_ja = 'やっと寝てくれました！家に広がる静けさは、耳がツーンとするほど深いですね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ回復していくのを目で感じてみましょう。', title_ko = '소음 측정기의 고요 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 너무 깊어 귀가 멍할 정도죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 회복되는 걸 눈으로 느껴 보세요.', title_nl = 'De stilte van de Geluidsmeter 🤫', body_nl = 'Hij slaapt eindelijk! De stilte in huis is zo diep dat je oren ervan suizen. Zet de Geluidsmeter aan, kijk naar de 0-10 decibel op het scherm en voel hoe je brein langzaam herstelt.', title_pl = 'Cisza w Mierniku dźwięku 🤫', body_pl = 'W końcu zasnął! Cisza, która zapadła w domu, jest tak głęboka, że aż dzwoni w uszach. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli dochodzi do siebie.', title_pt = 'O silêncio do Medidor de Som 🤫', body_pt = 'Finalmente adormeceu! O silêncio que cai sobre a casa é tão profundo que até lhe zumbem os ouvidos. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta visualmente o seu cérebro a recuperar devagarinho.', title_sv = 'Ljudmätarens tystnad 🤫', body_sv = 'Äntligen har barnet somnat! Tystnaden som sänker sig över hemmet är så djup att det slår lock för öronen. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du visuellt hur hjärnan sakta återhämtar sig.', title_vi = 'Sự tĩnh lặng của Đo âm thanh 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Sự tĩnh lặng bao trùm căn nhà sâu đến mức tai mẹ như ù đi. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần hồi phục.', title_zh = '分贝仪的安静 🤫', body_zh = '宝宝终于睡着了！家里一下子安静得连耳朵都有点嗡嗡的。打开分贝仪，看着屏幕上0-10分贝的数字，直观地感受大脑正在一点点恢复。' WHERE id = '159b5a7f-d190-47d4-8cda-ba692f07b0d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La complicidad de la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie. Entra en la Comunidad Anacan y limítate a leer. Ver el mismo cansancio de otras madres y las crisis infantiles más cómicas te hace sentir «no estoy sola», y eso es lo que más calma.', title_fr = 'La complicité de la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie de rien expliquer à personne. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir la même fatigue et les crises comiques des enfants chez d''autres mamans donne le sentiment de ne pas être seule, c''est le meilleur des calmants.', title_hi = 'कम्युनिटी का अपनापन 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। दूसरी माँओं की मिलती-जुलती थकान और बच्चों के मज़ेदार नखरे देखकर ‘मैं अकेली नहीं हूँ’ का एहसास होता है, यही सबसे अच्छा सुकून है।', title_id = 'Teman curhat di komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat lelah yang sama dan krisis lucu anak-anak ibu lain menumbuhkan rasa ''aku tidak sendirian'', dan itu penenang terbaik.', title_ja = 'コミュニティという心の友 💬', body_ja = 'とても疲れていて、誰にも何も説明したくない。そんなときはAnacanコミュニティを開いて、読むだけにしましょう。ほかのママたちの同じような疲れや、子どものおかしなかんしゃくを見ると「ひとりじゃない」と感じられて、いちばん心が落ち着きます。', title_ko = '커뮤니티라는 단짝 💬', body_ko = '너무 지쳐서 누구에게도 아무것도 설명하고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들의 비슷한 피로와 웃긴 떼쓰기 이야기를 보면 ''나만 그런 게 아니구나'' 싶어 최고의 진정제가 돼요.', title_nl = 'Vertrouwen in de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen. Ga naar de Anacan Community en lees alleen mee. Zien dat andere mama''s net zo moe zijn en net zulke grappige peutercrisissen hebben, geeft je het gevoel ''ik ben niet de enige'' en dat kalmeert het best.', title_pl = 'Zaufanie Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć. Wejdź do Społeczności Anacan i tylko czytaj. Widok podobnego zmęczenia i zabawnych dziecięcych kryzysów u innych mam daje poczucie „nie jestem sama” i najlepiej uspokaja.', title_pt = 'A cumplicidade da comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém. Entre na Comunidade Anacan e limite-se a ler. Ver o cansaço parecido de outras mães e as crises cómicas dos filhos dá a sensação de "não estou sozinha", e esse é o melhor calmante.', title_sv = 'Gemenskapens förtrolighet 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon. Gå in i Anacan Community och bara läs. Att se andra mammors liknande trötthet och roliga barnkriser ger känslan ”jag är inte ensam” och blir det bästa lugnande medlet.', title_vi = 'Tâm sự trong Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích gì với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác cũng mệt mỏi giống mình, cũng gặp những cơn khủng hoảng hài hước của con, sẽ mang lại cảm giác "mình không đơn độc", đó là liều thuốc an thần tốt nhất.', title_zh = '社区里的知心话 💬', body_zh = '累坏了，什么都不想跟任何人解释？进入Anacan社区，只当个读者就好。看到其他妈妈同样的疲惫和孩子们好笑的崩溃，会让你觉得“我不是一个人”，这就是最好的镇静剂。' WHERE id = 'ece2fe16-c57e-4a1f-a594-5e39da1118d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras extiendes la masa, se sube a una silla a tu lado y se mete en el proceso. Deja que enharine su propio cuenco de plástico. La cocina acabará hecha un desastre, pero esa cara seria y trabajadora y ese «yo también sé» valen toda esa limpieza.', body_fr = 'Quand vous étalez la pâte, il installe forcément une chaise à côté de vous pour s''en mêler. Laissez-le fariner son propre bol en plastique. La cuisine sera en désordre, mais son air sérieux et appliqué et ce sentiment du « moi aussi je sais faire » valent bien tout ce ménage.', body_hi = 'आप आटा बेलती हैं तो वह ज़रूर पास में कुर्सी लगाकर काम में हाथ डालता है। उसे अपना प्लास्टिक का बर्तन आटे से भरने दीजिए। रसोई गंदी होगी, पर उसका वह गंभीर, कामकाजी चेहरा और ‘मैं भी कर सकता हूँ’ का एहसास इस सारी सफ़ाई के लायक है।', body_id = 'Saat Anda menggiling adonan, ia pasti menaruh kursi di samping dan ikut campur. Biarkan ia menaburi tepung ke mangkuk plastik miliknya sendiri. Dapur akan berantakan, tapi wajahnya yang serius dan sibuk serta rasa ''aku juga bisa'' itu sepadan dengan semua bersih-bersihnya.', body_ja = 'あなたが生地をのばしていると、必ずそばにいすを持ってきて手を出してきます。この子専用のプラスチックの器で、粉あそびをさせてあげましょう。キッチンは粉だらけになるけれど、あの真剣な顔と「わたしもできる」という気持ちは、そのお掃除の価値が十分あります。', body_ko = '반죽을 밀 때 꼭 옆에 의자를 놓고 끼어드나요? 아이만의 플라스틱 그릇에 밀가루를 뿌리게 해 주세요. 부엌은 엉망이 되겠지만, 그 진지한 표정과 ''나도 할 수 있어''라는 느낌은 청소할 가치가 충분해요.', body_nl = 'Als jij deeg uitrolt, zet hij per se een stoel ernaast en bemoeit hij zich ermee. Laat hem zijn eigen plastic bakje met bloem bestuiven. De keuken wordt een zooi, maar dat serieuze gezichtje en het gevoel ''ik kan het ook'' zijn al het schoonmaken waard.', body_pl = 'Gdy wałkujesz ciasto, koniecznie przystawia obok krzesło i wtrąca się w pracę. Niech posypie mąką swoją plastikową miseczkę. Kuchnia będzie w opłakanym stanie, ale jego poważna, rzeczowa mina i poczucie „ja też potrafię” są warte całego sprzątania.', body_pt = 'Enquanto estende a massa, ele põe uma cadeira ao seu lado e mete-se no processo. Deixe-o enfarinhar uma taça de plástico só dele. A cozinha vai ficar um caos, mas aquela cara séria e trabalhadora e a sensação de "eu também consigo" valem toda a limpeza.', body_sv = 'När du kavlar deg ställer barnet absolut en stol bredvid dig och lägger sig i. Låt barnet mjöla sin egen plastskål. Köket blir nedkladdat, men barnets allvarliga, arbetsamma min och känslan av ”jag kan också” är värda all städning.', body_vi = 'Khi mẹ cán bột, bé nhất định kê ghế đứng cạnh và "nhúng tay" vào. Hãy để bé rắc bột vào chiếc bát nhựa của riêng mình. Căn bếp sẽ bừa bộn, nhưng vẻ mặt nghiêm túc, chăm chỉ và cảm giác "con cũng làm được" của bé xứng đáng với mọi công dọn dẹp.', body_zh = '你擀面团时，宝宝非要搬张椅子到旁边“参与”。就让宝宝往自己的塑料碗里撒面粉吧。厨房会被弄得一团糟，但宝宝那副认真能干的小表情和“我也会”的感觉，值得这一切的打扫。' WHERE id = 'fabbf657-c431-4c98-ba31-613ca3dc8a47' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El orgullo de vestirse al revés 🧦', body_es = 'El talón del calcetín le queda encima del pie, pero camina orgulloso porque se lo ha puesto él. No intervengas lo más mínimo. Esa sensación de «lo he conseguido» es una base psicológica un millón de veces más valiosa que ir bien vestido o estético: deja que pase así el día.', title_fr = 'La fierté de s''habiller à l''envers 🧦', body_fr = 'Le talon de sa chaussette est sur le dessus du pied, mais il marche fièrement parce qu''il s''est habillé tout seul. N''intervenez surtout pas. Ce sentiment du « j''ai réussi » est une base psychologique mille fois plus précieuse que d''être habillé joliment ou correctement, laissez-le passer sa journée ainsi.', title_hi = 'उलटा पहनने का गर्व 🧦', body_hi = 'मोज़े की एड़ी पैर के ऊपर है, पर खुद पहना है इसलिए गर्व से घूम रहा है। ज़रा भी दखल मत दीजिए। उसका यह ‘मैं कर सकता हूँ’ वाला एहसास सुंदर या सही पहनने से लाखों गुना कीमती मनोवैज्ञानिक नींव है, आज का दिन उसे ऐसे ही बिताने दीजिए।', title_id = 'Bangga memakai terbalik 🧦', body_id = 'Tumit kaus kakinya ada di punggung kaki, tapi ia berjalan dengan bangga karena memakainya sendiri. Jangan ikut campur sedikit pun. Rasa ''aku bisa'' ini adalah fondasi psikologis yang jutaan kali lebih berharga daripada berpakaian rapi atau benar, biarkan ia melewati harinya begitu.', title_ja = '裏返しで着た誇り 🧦', body_ja = '靴下のかかとが足の甲にきているのに、自分ではいたから得意げに歩いています。少しも手を出さないで。「自分でできた」という気持ちは、見た目や正しい着方より何百万倍も大切な心の土台。そのまま一日を過ごさせてあげましょう。', title_ko = '뒤집어 입은 자부심 🧦', body_ko = '양말 뒤꿈치가 발등에 가 있는데도 자기가 신었다고 당당하게 걷나요? 조금도 끼어들지 마세요. ''내가 해냈어''라는 느낌은 예쁘게, 바르게 입는 것보다 백만 배 소중한 심리적 바탕이에요. 오늘은 그대로 지내게 해 주세요.', title_nl = 'Trots op binnenstebuiten 🧦', body_nl = 'De hiel van zijn sok zit bovenop zijn voet, maar hij loopt trots rond omdat hij hem zelf heeft aangetrokken. Grijp niet in, echt helemaal niet. Dat ''ik kan het zelf''-gevoel is een psychologische basis die een miljoen keer meer waard is dan er mooi of correct gekleed uitzien. Laat hem zo zijn dag doorbrengen.', title_pl = 'Duma z ubrania na lewą stronę 🧦', body_pl = 'Pięta skarpetki jest na wierzchu stopy, ale chodzi dumny, bo ubrał się sam. Nie ingeruj ani trochę. To jego poczucie „sam dałem radę” jest psychologicznym fundamentem milion razy cenniejszym niż estetyczny czy poprawny strój, niech tak spędzi dzień.', title_pt = 'O orgulho de vestir ao contrário 🧦', body_pt = 'O calcanhar da meia está em cima do pé, mas ele anda orgulhoso porque se vestiu sozinho. Não intervenha nem um bocadinho. Esta sensação de "eu consegui" é uma base psicológica um milhão de vezes mais valiosa do que vestir-se de forma bonita ou correta: deixe-o passar o dia assim.', title_sv = 'Stolt med ut och in 🧦', body_sv = 'Hälen på strumpan sitter ovanpå foten, men barnet går stolt omkring eftersom det tagit på den själv. Lägg dig inte i det minsta. Känslan av ”jag klarade det” är en psykologisk grund som är en miljon gånger värdefullare än att vara snyggt eller rätt klädd, låt barnet gå så hela dagen.', title_vi = 'Tự hào vì mặc ngược 🧦', body_vi = 'Gót tất nằm trên mu bàn chân, nhưng vì tự mặc nên bé đi lại đầy kiêu hãnh. Đừng can thiệp dù chỉ một chút. Cảm giác "con làm được" của bé là nền tảng tâm lý quý giá hơn gấp triệu lần so với việc mặc đẹp hay mặc đúng, cứ để bé trải qua ngày như thế.', title_zh = '穿反了的骄傲 🧦', body_zh = '袜子的后跟跑到了脚背上，可因为是自己穿的，宝宝走得可骄傲了。一点都别插手。宝宝这份“我做到了”的感觉，作为心理基础，比好看或穿对要宝贵一百万倍，就让宝宝这样度过这一天吧。' WHERE id = '7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Minutos offline para mamá ☕', body_es = 'Está haciendo un puzle él solo y lleva 10 minutos en silencio. Y tú quieres aprovechar ese momento para ordenar la casa. ¡No! Vete a tumbarte en el sofá. Tu batería también tiene que cargarse para aguantar este ritmo hasta la noche.', title_fr = 'Des minutes hors ligne pour maman ☕', body_fr = 'Il fait un puzzle tout seul et ne fait pas un bruit depuis 10 minutes. Et vous voulez en profiter pour ranger la maison. Non ! Allez vous allonger sur le canapé. Votre batterie aussi doit se recharger pour tenir ce rythme jusqu''au soir.', title_hi = 'माँ के लिए ऑफ़लाइन मिनट ☕', body_hi = 'वह खुद पज़ल जोड़ रहा है और 10 मिनट से चुप है। और आप यह समय घर समेटने में लगाना चाहती हैं। नहीं! जाइए, सोफ़े पर लेट जाइए। आपकी बैटरी भी चार्ज होनी चाहिए, ताकि शाम तक इस रफ़्तार को झेल सकें।', title_id = 'Menit offline untuk Ibu ☕', body_id = 'Ia menyusun puzzle sendiri dan sudah 10 menit diam. Kamu ingin memakai waktu itu untuk membereskan rumah. Jangan! Pergi berbaringlah di sofa. Baterainya juga harus terisi agar kamu sanggup mengikuti tempo ini sampai sore.', title_ja = 'ママのオフラインタイム ☕', body_ja = 'ひとりでパズルをして、もう10分も静かです。あなたはその時間で家を片づけたくなりますね。だめです！ソファで横になって。夕方までこのペースについていくには、あなたのバッテリーも充電しなくちゃ。', title_ko = '엄마를 위한 오프라인 시간 ☕', body_ko = '혼자 퍼즐을 맞추며 10분째 조용한가요? 엄마는 그 시간에 집을 치우고 싶겠죠. 안 돼요! 가서 소파에 누우세요. 저녁까지 이 속도를 버티려면 엄마의 배터리도 충전돼야 해요.', title_nl = 'Offline minuutjes voor mama ☕', body_nl = 'Hij is in zijn eentje een puzzel aan het maken en al 10 minuten stil. En jij wilt dat moment gebruiken om het huis op te ruimen. Nee! Ga op de bank liggen. Ook jouw batterij moet opladen, zodat je dit tempo tot de avond volhoudt.', title_pl = 'Minuty offline dla mamy ☕', body_pl = 'Układa sam puzzle i od 10 minut jest cicho. A ty chcesz wykorzystać tę chwilę na sprzątanie. Nie! Idź, połóż się na kanapie. Twoja bateria też musi się naładować, żebyś wytrzymała to tempo do wieczora.', title_pt = 'Minutos offline para a mãe ☕', body_pt = 'Está a fazer um puzzle sozinho e há 10 minutos que está calado. E a mãe quer aproveitar para arrumar a casa. Não! Vá deitar-se no sofá. A sua bateria também precisa de carregar para aguentar este ritmo até à noite.', title_sv = 'Offline-minuter för mamma ☕', body_sv = 'Barnet lägger pussel själv och har varit tyst i 10 minuter. Och du vill använda stunden till att städa. Nej! Gå och lägg dig i soffan. Ditt batteri behöver också laddas för att du ska orka med tempot fram till kvällen.', title_vi = 'Những phút "offline" của mẹ ☕', body_vi = 'Bé đang tự ghép xếp hình và đã im lặng 10 phút. Còn mẹ thì muốn tranh thủ lúc này để dọn nhà. Không! Hãy đi nằm xuống sofa. Pin của mẹ cũng cần được sạc đầy để theo kịp nhịp độ này đến tối.', title_zh = '妈妈的离线时间 ☕', body_zh = '宝宝自己在拼拼图，已经安静10分钟了。你却想把这段时间用来收拾屋子。不！去沙发上躺下。你的电池也得充满，才能撑住这样的节奏直到晚上。' WHERE id = 'ca2fd133-6b0b-4852-a4b2-b830a12f0bc0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con la oscuridad 🐰', body_es = '¿No quiere dormirse y dice que le dan miedo las sombras de la habitación? Oscurece del todo la habitación y haz con las manos sombras de pájaros y perros en la pared. Convierte el miedo en diversión y ayúdale a hacerse amigo de la oscuridad y a dominar su imaginación.', title_fr = 'Se réconcilier avec le noir 🐰', body_fr = 'Il ne veut pas dormir et dit qu''il a peur des ombres de la chambre ? Faites le noir complet et créez avec vos mains des ombres d''oiseau ou de chien sur le mur. En transformant la peur en jeu, aidez-le à se lier d''amitié avec le noir et à maîtriser son imagination.', title_hi = 'अँधेरे से दोस्ती 🐰', body_hi = 'सोना नहीं चाहता और कहता है कि कमरे की परछाइयों से डर लगता है? कमरा पूरी तरह अँधेरा कीजिए और दीवार पर हाथों से चिड़िया, कुत्ते की परछाइयाँ बनाइए। डर को मज़े में बदलकर उसे अँधेरे से दोस्ती करने और अपनी कल्पना सँभालने में मदद कीजिए।', title_id = 'Berdamai dengan gelap 🐰', body_id = 'Ia tidak mau tidur dan bilang takut bayangan di kamar? Gelapkan kamar sepenuhnya dan buat bayangan burung atau anjing di dinding dengan tangan Anda. Ubah rasa takut menjadi hiburan, bantu ia berteman dengan gelap dan mengendalikan imajinasinya.', title_ja = '暗やみと仲直り 🐰', body_ja = '眠りたくなくて、部屋の影が怖いと言う？部屋を真っ暗にして、壁に手で鳥や犬の影絵をつくりましょう。怖さを楽しさに変えて、暗やみと友だちになり、想像力をコントロールできるよう手伝ってあげて。', title_ko = '어둠과 화해하기 🐰', body_ko = '자기 싫다며 방의 그림자가 무섭다고 하나요? 방을 완전히 어둡게 하고 손으로 벽에 새와 강아지 그림자를 만들어 보세요. 두려움을 놀이로 바꿔 어둠과 친해지고 상상력을 다스리도록 도와주세요.', title_nl = 'Vrede sluiten met het donker 🐰', body_nl = 'Wil hij niet slapen en zegt hij dat hij bang is voor de schaduwen in de kamer? Maak de kamer helemaal donker en maak met je handen schaduwen van vogels en honden op de muur. Maak van angst plezier en help hem vriendschap te sluiten met het donker en zijn fantasie te sturen.', title_pl = 'Pogodzić się z ciemnością 🐰', body_pl = 'Nie chce zasnąć i mówi, że boi się cieni w pokoju? Zaciemnij pokój całkowicie i zrób dłońmi na ścianie cienie ptaka czy psa. Zamieniając strach w zabawę, pomożesz mu zaprzyjaźnić się z ciemnością i zapanować nad wyobraźnią.', title_pt = 'Fazer as pazes com o escuro 🐰', body_pt = 'Não quer adormecer e diz que tem medo das sombras do quarto? Escureça bem o quarto e faça com as mãos sombras de pássaros e cães na parede. Transforme o medo em diversão e ajude-o a fazer amizade com o escuro e a dominar a imaginação.', title_sv = 'Bli vän med mörkret 🐰', body_sv = 'Vill barnet inte somna och säger att det är rädd för skuggorna i rummet? Gör rummet helt mörkt och forma fåglar och hundar som skuggor på väggen med händerna. Gör rädslan till lek och hjälp barnet att bli vän med mörkret och styra sin fantasi.', title_vi = 'Làm hòa với bóng tối 🐰', body_vi = 'Bé không muốn ngủ và nói rằng sợ những cái bóng trong phòng? Hãy làm tối hẳn căn phòng và dùng tay tạo bóng chim, bóng chó trên tường. Biến nỗi sợ thành trò chơi để giúp bé kết bạn với bóng tối và làm chủ trí tưởng tượng của mình.', title_zh = '和黑暗和解 🐰', body_zh = '不想睡觉，说害怕房间里的影子？把房间完全调暗，用手在墙上做出小鸟、小狗的影子。把害怕变成乐趣，帮宝宝和黑暗交朋友，学会驾驭自己的想象力。' WHERE id = 'e264b682-e7a9-4579-80a1-6e47fe7bccb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial e inquietudes 🤖', body_es = '¿Te ha preocupado que todavía no pronuncie bien algunas letras? Cierra los foros de internet que dan miedo. Pregunta a Anacan AI por las pautas del desarrollo del habla cerca de los 38 meses y obtén una respuesta científica y realista.', title_fr = 'Intelligence artificielle et inquiétudes 🤖', body_fr = 'Son incapacité à prononcer encore correctement certains sons vous inquiète ? Fermez les forums effrayants d''Internet. Demandez à Anacan AI les normes du développement du langage autour de 38 mois et obtenez une réponse scientifique et réaliste.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और चिंताएँ 🤖', body_hi = 'बच्चे का कुछ अक्षर अब भी ठीक से न बोल पाना आपको परेशान कर गया? डरावने फ़ोरम बंद कीजिए। Anacan AI से 38 महीने के आसपास बोलने के विकास के मानक पूछिए और वैज्ञानिक, सच्चाई से मेल खाता जवाब पाइए।', title_id = 'Kecerdasan buatan dan kecemasan 🤖', body_id = 'Anda cemas karena ia masih belum bisa mengucapkan beberapa huruf dengan benar? Tutup forum-forum internet yang menakutkan. Tanyakan pada Anacan AI tentang standar perkembangan bicara menjelang usia 38 bulan, dan dapatkan jawaban ilmiah yang sesuai kenyataan.', title_ja = 'AIと不安 🤖', body_ja = 'いくつかの音がまだうまく言えないことに、不安になりましたか？ネットの怖い掲示板は閉じましょう。Anacan AIに38か月前後の言葉の発達の目安をたずねて、科学的で現実に合った答えをもらいましょう。', title_ko = '인공지능과 걱정들 🤖', body_ko = '아이가 아직 몇몇 발음을 바르게 못 해서 불안해졌나요? 무서운 인터넷 게시판은 닫으세요. Anacan AI에게 38개월 무렵의 언어 발달 기준을 물어보고 과학적이고 현실적인 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en zorgen 🤖', body_nl = 'Maak je je zorgen omdat je kind sommige letters nog steeds niet goed uitspreekt? Sluit die angstaanjagende fora. Vraag Anacan AI naar de normen voor taalontwikkeling rond 38 maanden en krijg een wetenschappelijk, realistisch antwoord.', title_pl = 'Sztuczna inteligencja i niepokoje 🤖', body_pl = 'Zaniepokoiło cię, że dziecko wciąż nie wymawia poprawnie niektórych głosek? Zamknij straszące fora w internecie. Zapytaj Anacan AI o normy rozwoju mowy w okolicach 38 miesięcy i uzyskaj naukową, realistyczną odpowiedź.', title_pt = 'Inteligência artificial e preocupações 🤖', body_pt = 'Ficou aflita por ele ainda não conseguir pronunciar bem algumas letras? Feche os fóruns assustadores da internet. Pergunte ao Anacan AI quais são as normas do desenvolvimento da fala perto dos 38 meses e obtenha uma resposta científica e realista.', title_sv = 'Artificiell intelligens och oro 🤖', body_sv = 'Blev du orolig över att barnet fortfarande inte kan uttala vissa bokstäver rätt? Stäng de skrämmande forumen på nätet. Fråga Anacan AI om normerna för talutveckling runt 38 månader och få ett vetenskapligt och realistiskt svar.', title_vi = 'Trí tuệ nhân tạo và những lo lắng 🤖', body_vi = 'Việc bé vẫn chưa phát âm đúng một số chữ cái khiến mẹ lo lắng? Hãy đóng những diễn đàn đáng sợ trên mạng. Hãy hỏi Anacan AI về chuẩn phát triển ngôn ngữ ở khoảng 38 tháng và nhận câu trả lời khoa học, sát với thực tế.', title_zh = '人工智能与焦虑 🤖', body_zh = '宝宝有些音还是发不准，让你很慌？关掉网上那些吓人的论坛。问问Anacan AI快38个月时语言发展的正常标准，得到科学又符合实际的答案。' WHERE id = '03f9e2c0-9e7a-47b1-892e-0261f73bfa13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú eres la niña, yo la mamá 👩‍👧', body_es = '¡Ha empezado el juego del cambio de papeles! Te da órdenes: «Ven aquí, cómete la comida, no llores». Acepta encantada esta experiencia de liderazgo y haz de su niña sin rechistar: es la vía más básica para desarrollar la empatía.', title_fr = 'Toi, tu es l''enfant, moi la maman 👩‍👧', body_fr = 'Le jeu de l''inversion des rôles a commencé ! Il vous donne des ordres : « Viens ici, mange ton repas, pleure pas ! » Accueillez avec grand plaisir cette expérience de chef et jouez sans broncher le rôle de son enfant : c''est la voie la plus fondamentale du développement de l''empathie.', title_hi = 'तुम बच्चे बनो, मैं माँ 👩‍👧', body_hi = 'भूमिका बदलने का खेल शुरू हो गया! वह आपको ‘इधर आओ, खाना खाओ, रोओ मत’ जैसे आदेश दे रहा है। उसके इस नेतृत्व के अभ्यास को बड़े मज़े से स्वीकार कीजिए और चुपचाप उसके बच्चे की भूमिका निभाइए, यही सहानुभूति के विकास का सबसे बुनियादी रास्ता है।', title_id = 'Kamu jadi anak, aku jadi Mama 👩‍👧', body_id = 'Permainan tukar peran dimulai! Ia memberi Anda perintah: ''Sini, habiskan makananmu, jangan menangis''. Terima pengalaman memimpinnya ini dengan senang hati dan mainkan peran sebagai anaknya tanpa membantah, ini cara paling mendasar untuk mengembangkan empati.', title_ja = 'あなたは子ども、わたしはママ 👩‍👧', body_ja = '役割交代ごっこが始まりました！「ここにおいで、ごはん食べて、泣かないの」とあなたに指示を出しています。このリーダー体験を楽しく受け入れて、黙ってこの子の子ども役を演じましょう。これが思いやりを育てるいちばん基本の方法です。', title_ko = '너는 아이, 나는 엄마 👩‍👧', body_ko = '역할 바꾸기 놀이가 시작됐어요! ''이리 와, 밥 먹어, 울지 마''라며 엄마에게 지시하나요? 이 리더십 체험을 즐겁게 받아들이고 조용히 아이 역할을 해 주세요. 공감 능력을 키우는 가장 기본적인 방법이에요.', title_nl = 'Jij bent het kind, ik ben mama 👩‍👧', body_nl = 'Het rollenspel is begonnen! Hij geeft jou opdrachten: ''Kom hier, eet je bord leeg, niet huilen!'' Geniet volop van zijn leiderschap en speel zonder morren de rol van zijn kind: dit is de meest basale manier om empathie te ontwikkelen.', title_pl = 'Ty bądź dzieckiem, ja mamą 👩‍👧', body_pl = 'Zaczęła się zabawa w zamianę ról! Wydaje ci polecenia: „Chodź tu, zjedz obiad, nie płacz”. Przyjmij jego doświadczenie w roli lidera z wielką przyjemnością i bez sprzeciwu zagraj jego dziecko, to najbardziej podstawowa droga rozwoju empatii.', title_pt = 'Tu és a criança, eu sou a mãe 👩‍👧', body_pt = 'Começou o jogo da troca de papéis! Ele dá-lhe ordens: "anda cá, come a comida, não chores". Aceite com muito gosto esta experiência de liderança e faça de criança dele, sem refilar: é o caminho mais básico para desenvolver a empatia.', title_sv = 'Du är barnet, jag är mamma 👩‍👧', body_sv = 'Rollbyteslek har börjat! Barnet kommenderar dig: ”Kom hit, ät upp maten, gråt inte.” Ta emot barnets ledarerfarenhet med stor förtjusning och spela tyst barnets barn, det är det mest grundläggande sättet att utveckla empati.', title_vi = 'Con làm em bé, mẹ làm mẹ 👩‍👧', body_vi = 'Trò chơi đổi vai đã bắt đầu! Bé ra lệnh cho mẹ: "Lại đây, ăn cơm đi, đừng khóc!". Hãy vui vẻ đón nhận trải nghiệm làm "thủ lĩnh" này của bé và ngoan ngoãn đóng vai con của bé, đây là cách cơ bản nhất để phát triển sự đồng cảm.', title_zh = '你当宝宝，我当妈妈 👩‍👧', body_zh = '角色互换游戏开始了！宝宝对你发号施令：“过来，把饭吃了，别哭。”开开心心地接受宝宝这次当领导的体验，乖乖地扮演宝宝的“孩子”，这是培养共情最基础的方式。' WHERE id = '8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina solo se libera rápido en un ambiente oscuro y sin tecnología.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine n''est sécrétée rapidement que dans le noir et sans écran.', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi.', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニンは、暗くてデジタル機器のない環境でこそすばやく分泌されます。', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌은 어둡고 기기가 없는 환경에서만 빠르게 분비돼요.', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt alleen snel aangemaakt in een donkere omgeving zonder technologie.', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina szybko wydziela się tylko w ciemnym otoczeniu bez technologii.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin utsöndras snabbt bara i en mörk och teknikfri miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素只有在昏暗、没有电子产品的环境里才会快速分泌。' WHERE id = 'b97073a4-f745-41b1-953a-0e776ded1591' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Teatro frente al espejo 🎭', body_es = 'A primera hora se pone delante del espejo a ensayar caras de llanto, de risa y de sorpresa. Está descubriendo cómo expresar sus emociones y cómo cambia su cara. Observa de lejos y sonriendo esta actuación genial.', title_fr = 'Théâtre devant le miroir 🎭', body_fr = 'Dès le matin, il s''installe devant le miroir pour s''entraîner à différentes mimiques : pleurer, rire, s''étonner. Il découvre comment exprimer ses émotions et comment son visage change. Admirez en souriant, de loin, cette performance d''acteur de génie.', title_hi = 'आईने के सामने नाटक 🎭', body_hi = 'सुबह-सुबह आईने के सामने खड़े होकर रोने, हँसने, हैरान होने के अलग-अलग चेहरे बनाने का अभ्यास करता है। वह खोज रहा है कि अपनी भावनाएँ कैसे दिखाए और उसका चेहरा कैसा रूप लेता है। इस शानदार अदाकारी को दूर से मुस्कुराते हुए देखिए।', title_id = 'Teater di depan cermin 🎭', body_id = 'Pagi-pagi ia sudah berdiri di depan cermin, berlatih berbagai ekspresi menangis, tertawa, dan terkejut. Ia sedang menemukan cara mengekspresikan emosi dan bagaimana wajahnya berubah bentuk. Saksikan pertunjukan akting jenius ini dari jauh sambil tersenyum.', title_ja = '鏡の前の劇場 🎭', body_ja = '朝から鏡の前に立って、泣き顔や笑顔、びっくり顔の練習をしています。気持ちをどう表すか、顔がどう変わるかを発見しているんです。この天才的な演技を、遠くからほほえんで見守りましょう。', title_ko = '거울 앞 연극 🎭', body_ko = '아침부터 거울 앞에서 우는 표정, 웃는 표정, 놀란 표정을 연습하나요? 감정을 어떻게 표현하는지, 얼굴이 어떻게 바뀌는지 발견하는 중이에요. 이 천재 배우의 공연을 멀리서 미소 지으며 지켜보세요.', title_nl = 'Theater voor de spiegel 🎭', body_nl = 'Al vroeg in de ochtend staat hij voor de spiegel huilende, lachende en verbaasde gezichtjes te oefenen. Hij ontdekt hoe hij zijn emoties uitdrukt en hoe zijn gezicht vorm krijgt. Kijk met een glimlach van een afstand naar deze geniale acteerprestatie.', title_pl = 'Teatr przed lustrem 🎭', body_pl = 'Od samego rana staje przed lustrem i ćwiczy różne miny: płacz, śmiech, zdziwienie. Odkrywa, jak wyrażać emocje i jak zmienia się jego twarz. Obserwuj z daleka z uśmiechem ten genialny popis aktorski.', title_pt = 'Teatro em frente ao espelho 🎭', body_pt = 'Logo de manhã põe-se em frente ao espelho a ensaiar caras de choro, de riso e de espanto. Está a descobrir como exprimir as emoções e como o rosto muda. Observe a sorrir, à distância, esta interpretação genial.', title_sv = 'Teater framför spegeln 🎭', body_sv = 'Tidigt på morgonen ställer sig barnet framför spegeln och övar olika miner: gråt, skratt och förvåning. Barnet upptäcker hur det ska uttrycka sina känslor och hur ansiktet tar form. Titta leende på den geniala skådespelarprestationen på avstånd.', title_vi = 'Nhà hát trước gương 🎭', body_vi = 'Sáng sớm, bé đứng trước gương tập các biểu cảm khóc, cười, ngạc nhiên. Bé đang khám phá cách thể hiện cảm xúc và khuôn mặt mình thay đổi ra sao. Hãy mỉm cười ngắm nhìn màn trình diễn tài năng này từ xa.', title_zh = '镜子前的剧场 🎭', body_zh = '一大早就站在镜子前，练习各种哭、笑、惊讶的表情。宝宝在探索如何表达情绪、脸会变成什么样。远远地微笑着欣赏这场天才般的表演吧。' WHERE id = '66da20be-59e4-4c6a-b44a-168bd86bf8c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los brazos mágicos de papá 🫂', body_es = 'Tienes los brazos destrozados de cargarle todo el día, pero él vuelve a pedir brazos. Llama a papá. Volar en sus brazos cubrirá su necesidad de atención y dará a tus brazos el descanso que tanto necesitan.', title_fr = 'Les bras magiques de papa 🫂', body_fr = 'Vos bras n''en peuvent plus de l''avoir porté toute la journée, mais il réclame encore les bras. Appelez papa. Voler dans les bras de papa comblera son besoin d''attention et offrira à vos bras le repos dont ils ont tant besoin.', title_hi = 'पापा की जादुई बाहें 🫂', body_hi = 'दिनभर उठाते-उठाते आपकी बाहें टूट रही हैं, पर उसे फिर गोद चाहिए। पापा को आवाज़ दीजिए। पापा की बाहों में उड़ना बच्चे की ध्यान की ज़रूरत भी पूरी करेगा और आपकी बाहों को वह आराम भी देगा जिसकी उन्हें सख्त ज़रूरत है।', title_id = 'Lengan ajaib Ayah 🫂', body_id = 'Lengan Anda serasa copot karena menggendongnya seharian, tapi ia masih minta digendong. Panggil Ayah. Terbang di lengan Ayah akan memenuhi kebutuhan perhatiannya sekaligus memberi lengan Anda istirahat yang sangat dibutuhkan.', title_ja = 'パパの魔法の腕 🫂', body_ja = '一日じゅう抱っこで腕がちぎれそうなのに、まだ抱っこをせがむ。パパを呼びましょう。パパの腕で空を飛べば、子どもは注目してもらえて満足し、あなたの腕はとても必要な休けいがとれます。', title_ko = '아빠의 마법 같은 품 🫂', body_ko = '하루 종일 안고 다니느라 팔이 빠질 것 같은데 또 안아 달라고 하나요? 아빠를 불러 주세요. 아빠 품에서 날아오르면 아이의 관심 욕구도 채워지고, 엄마의 팔도 꼭 필요한 휴식을 얻어요.', title_nl = 'Papa''s magische armen 🫂', body_nl = 'Je armen vallen er bijna af van het hele dag dragen, maar hij wil weer opgetild worden. Roep papa. Vliegen in papa''s armen geeft je kind de aandacht die hij nodig heeft en geeft jouw armen de rust die ze zo hard nodig hebben.', title_pl = 'Magiczne ramiona taty 🫂', body_pl = 'Ręce odpadają ci od noszenia go przez cały dzień, a on znów chce na ręce. Zawołaj tatę. Latanie w ramionach taty zaspokoi potrzebę uwagi dziecka, a twoim rękom da tak bardzo potrzebny odpoczynek.', title_pt = 'Os braços mágicos do pai 🫂', body_pt = 'Tem os braços a cair de o carregar o dia todo, mas ele continua a querer colo. Chame o pai. Voar nos braços do pai vai satisfazer a necessidade de atenção da criança e dar aos seus braços o descanso de que tanto precisam.', title_sv = 'Pappas magiska armar 🫂', body_sv = 'Armarna värker efter att ha burit hela dagen, men barnet vill bli upplyft igen. Ropa på pappa. Att flyga i pappas armar fyller barnets behov av uppmärksamhet och ger dina armar den vila de så väl behöver.', title_vi = 'Vòng tay diệu kỳ của bố 🫂', body_vi = 'Tay mẹ đã rã rời vì bế bé cả ngày, nhưng bé vẫn đòi bế. Hãy gọi bố. Được "bay" trong vòng tay bố vừa đáp ứng nhu cầu được quan tâm của bé, vừa cho đôi tay mẹ khoảng nghỉ rất cần thiết.', title_zh = '爸爸神奇的手臂 🫂', body_zh = '抱了一整天，你的胳膊都快断了，可宝宝还要抱抱。喊爸爸来吧。在爸爸的臂弯里“飞”，既能满足宝宝对关注的需要，也能让你的胳膊得到急需的休息。' WHERE id = '69d26c82-f68d-4fca-acec-f2cabf4901f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es arte 🎨', body_es = 'Ha creado en medio de la habitación una gran obra de arte con trocitos de papel e hilos cortados y no te deja tirarla. Deja a un lado la obsesión por la limpieza. Respeta el caos que ha creado: la limpieza puede esperar a mañana.', title_fr = 'Ce n''est pas du désordre, c''est de l''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art faite de petits bouts de papier et de ficelles coupées, et refuse que vous la jetiez. Laissez de côté votre obsession du rangement. Respectez le chaos qu''il a créé, le ménage peut attendre demain.', title_hi = 'कचरा नहीं, कला 🎨', body_hi = 'कमरे के बीच कागज़ के छोटे टुकड़ों और कटे धागों से एक बड़ी कलाकृति बना ली है और फेंकने नहीं देता। सफ़ाई की सनक एक तरफ़ रखिए। उसकी रची अफ़रा-तफ़री का सम्मान कीजिए, सफ़ाई कल तक भी रुक सकती है।', title_id = 'Bukan sampah, tapi seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari sobekan kertas dan potongan benang, dan tidak mengizinkan Anda membuangnya. Singkirkan dulu obsesi kebersihan. Hargai kekacauan yang ia ciptakan, bersih-bersih bisa menunggu besok.', title_ja = 'ゴミじゃない、アートです 🎨', body_ja = '部屋のまんなかに、小さな紙くずや切った毛糸で大作をつくり、捨てさせてくれない。きれい好きはちょっとお休みして、この子がつくったカオスを尊重しましょう。お掃除は明日でも大丈夫です。', title_ko = '쓰레기가 아니라 예술 🎨', body_ko = '방 한가운데 작은 종이 조각과 잘린 실로 커다란 작품을 만들고 버리지 못하게 하나요? 깔끔함에 대한 집착은 잠시 내려놓으세요. 아이가 만든 혼돈을 존중해 주세요, 청소는 내일 해도 돼요.', title_nl = 'Geen rommel, maar kunst 🎨', body_nl = 'Hij heeft midden in de kamer een groot kunstwerk gemaakt van papiersnippers en stukjes touw, en hij laat het je niet weggooien. Zet je opruimdrang even opzij. Respecteer de chaos die hij heeft gemaakt, opruimen kan ook morgen.', title_pl = 'To nie śmieci, to sztuka 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki ze skrawków papieru i pociętych sznurków i nie pozwala go wyrzucić. Odłóż na bok obsesję porządku. Uszanuj chaos, który stworzył, sprzątanie może poczekać do jutra.', title_pt = 'Não é lixo, é arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com pedacinhos de papel e fios cortados e não a deixa deitar fora. Ponha de lado a obsessão pela limpeza. Respeite o caos que ele criou, a limpeza pode ficar para amanhã.', title_sv = 'Inte skräp, utan konst 🎨', body_sv = 'Mitt i rummet har barnet skapat ett stort konstverk av små pappersbitar och avklippta snören och låter dig inte slänga det. Lägg städmanin åt sidan. Respektera kaoset barnet har skapat, städningen kan vänta till i morgon.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Giữa phòng, bé đã tạo ra một "tác phẩm nghệ thuật" lớn từ những mẩu giấy vụn và sợi dây cắt nhỏ, và không cho mẹ vứt đi. Hãy gác lại nỗi ám ảnh sạch sẽ. Tôn trọng sự hỗn loạn bé tạo ra, việc dọn dẹp có thể để đến mai.', title_zh = '不是垃圾，是艺术 🎨', body_zh = '在房间中间用碎纸片、剪断的线头创作了一件大型艺术品，还不让你扔。把洁癖先放一边。尊重宝宝创造的混乱吧，打扫可以留到明天。' WHERE id = 'b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La resistencia del «¡Yo solo!» 🛑', body_es = 'Quiere atarse él solo los cordones y ya llegáis 10 minutos tarde para salir de casa. No le metas prisa. Para su desarrollo importa más un ego sin heridas que un horario sin retrasos. Deja que lo intente.', title_fr = 'La résistance du « Moi tout seul ! » 🛑', body_fr = 'Il veut faire ses lacets tout seul et vous avez déjà 10 minutes de retard pour sortir. Ne vous pressez pas. Pour son développement, un ego intact compte bien plus qu''un emploi du temps chamboulé. Laissez-le essayer.', title_hi = '‘मैं खुद!’ की ज़िद 🛑', body_hi = 'जूतों के फीते खुद बाँधना चाहता है और घर से निकलने में आप पहले ही 10 मिनट लेट हैं। जल्दबाज़ी मत कीजिए। बिगड़े हुए टाइम-टेबल से ज़्यादा, बिना ठेस पहुँचा अहं उसके विकास के लिए ज़रूरी है। उसे कोशिश करने दीजिए।', title_id = 'Perlawanan ''Aku sendiri!'' 🛑', body_id = 'Ia ingin mengikat tali sepatunya sendiri, padahal kalian sudah terlambat 10 menit untuk keluar rumah. Jangan terburu-buru. Ego yang tidak terluka jauh lebih penting bagi perkembangannya daripada jadwal yang tidak berantakan. Biarkan ia mencoba.', title_ja = '「自分で！」の抵抗 🛑', body_ja = '靴ひもを自分で結びたがって、出かける時間にもう10分も遅れている。急がないで。時間どおりに進むことより、傷つかない自尊心のほうが、この子の成長にはずっと大切です。チャレンジさせてあげましょう。', title_ko = '''내가 할 거야!'' 고집 🛑', body_ko = '신발 끈을 자기가 묶겠다는데 벌써 10분이나 늦었나요? 서두르지 마세요. 아이의 발달에는 망가진 일정보다 다치지 않은 자존감이 더 중요해요. 해 보게 해 주세요.', title_nl = 'Het ''Zelf doen!''-verzet 🛑', body_nl = 'Hij wil zelf zijn veters strikken en jullie zijn al 10 minuten te laat. Haast je niet. Een ongeschonden ego is voor zijn ontwikkeling veel belangrijker dan een verstoorde planning. Laat hem het proberen.', title_pl = 'Opór „Ja sam!” 🛑', body_pl = 'Chce sam zawiązać sznurówki, a wy już jesteście 10 minut spóźnieni. Nie poganiaj go. Dla jego rozwoju nienaruszone ego jest ważniejsze niż naruszony harmonogram. Pozwól mu spróbować.', title_pt = 'A resistência do "Eu sozinho!" 🛑', body_pt = 'Quer atar sozinho os atacadores e já estão 10 minutos atrasados para sair de casa. Não tenha pressa. Para o desenvolvimento dele, um ego que não sai ferido é mais importante do que um horário que fica estragado. Deixe-o tentar.', title_sv = '”Jag själv!”-motståndet 🛑', body_sv = 'Barnet vill knyta skosnörena själv och ni är redan 10 minuter försenade. Stressa inte. För barnets utveckling är ett oskadat ego viktigare än ett schema som spricker. Låt barnet försöka.', title_vi = 'Sự kháng cự "Con tự làm!" 🛑', body_vi = 'Bé muốn tự buộc dây giày, còn mẹ đã trễ 10 phút để ra khỏi nhà. Đừng vội. Một cái tôi không bị tổn thương quan trọng cho sự phát triển của bé hơn nhiều so với một lịch trình bị lỡ. Hãy để bé thử.', title_zh = '“我自己来！”的坚持 🛑', body_zh = '想自己系鞋带，而你们出门已经晚了10分钟。别催。对宝宝的成长来说，一个没受伤的自我，比一个被打乱的时间表重要得多。让宝宝试试吧。' WHERE id = '3613ef28-90fe-4c93-a13a-cc4ded2b5ad4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historias susurradas 🌙', body_es = 'Hoy has hablado muy alto y tienes los pulmones cansados. Apaga las luces, túmbate a su lado y cuéntale lo que ha pasado durante el día solo susurrándole al oído. El susurro concentra su atención y prepara su cerebro de forma hipnótica para un sueño profundo.', title_fr = 'Histoires chuchotées 🌙', body_fr = 'Vous avez beaucoup élevé la voix aujourd''hui, vos poumons sont fatigués. Éteignez les lumières, allongez-vous près de lui et racontez-lui simplement sa journée en chuchotant à l''oreille. Le chuchotement concentre son attention et prépare son cerveau de façon presque hypnotique à un sommeil profond.', title_hi = 'फुसफुसाती कहानियाँ 🌙', body_hi = 'आज आपकी आवाज़ बहुत ऊँची हुई, फेफड़े थक गए। लाइटें बंद कीजिए, उसके पास लेटिए और दिनभर की बातें बस फुसफुसाकर उसके कान में कहिए। फुसफुसाहट उसका ध्यान केंद्रित करती है और उसके दिमाग को सम्मोहन की तरह गहरी नींद के लिए तैयार करती है।', title_id = 'Cerita berbisik 🌙', body_id = 'Hari ini Anda sudah banyak bersuara, paru-paru Anda lelah. Matikan lampu, berbaringlah di sampingnya, dan ceritakan kejadian hari ini ke telinganya cukup dengan berbisik. Bisikan memusatkan perhatiannya dan menyiapkan otaknya untuk tidur nyenyak seperti terhipnotis.', title_ja = 'ささやきのおはなし 🌙', body_ja = '今日はたくさん声を出して、肺も疲れていますね。明かりを消してそばに横になり、今日あったことを耳もとでささやくだけで話してあげて。ささやき声は注意を集め、脳を催眠のように深い眠りへと導きます。', title_ko = '속삭이는 이야기 🌙', body_ko = '오늘 목소리를 많이 써서 숨이 차나요? 불을 끄고 옆에 누워 오늘 있었던 일을 귓가에 속삭이기만 하세요. 속삭임은 아이의 집중을 모으고 뇌를 최면처럼 깊은 잠으로 이끌어요.', title_nl = 'Fluisterverhalen 🌙', body_nl = 'Je hebt je stem vandaag veel gebruikt en je longen zijn moe. Doe de lichten uit, ga naast hem liggen en vertel hem fluisterend in zijn oor wat er vandaag is gebeurd. Fluisteren richt zijn aandacht en maakt zijn brein op een hypnotiserende manier klaar voor een diepe slaap.', title_pl = 'Historie szeptem 🌙', body_pl = 'Dziś dużo używałaś głosu, płuca są zmęczone. Zgaś światła, połóż się obok i po prostu wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia. Szept skupia jego uwagę i niemal hipnotycznie przygotowuje mózg do głębokiego snu.', title_pt = 'Histórias em sussurro 🌙', body_pt = 'Hoje já levantou muito a voz e os pulmões estão cansados. Apague as luzes, deite-se ao lado dele e conte-lhe ao ouvido, só em sussurro, o que aconteceu durante o dia. O sussurro concentra a atenção dele e prepara o cérebro de forma hipnótica para um sono profundo.', title_sv = 'Viskade berättelser 🌙', body_sv = 'Du har höjt rösten mycket i dag och lungorna är trötta. Släck ljuset, lägg dig bredvid barnet och viska bara om det som hänt under dagen. Viskningar fokuserar barnets uppmärksamhet och förbereder hjärnan nästan hypnotiskt för djup sömn.', title_vi = 'Những câu chuyện thì thầm 🌙', body_vi = 'Hôm nay mẹ đã nói rất nhiều, phổi cũng mệt rồi. Hãy tắt đèn, nằm cạnh bé và chỉ thì thầm vào tai bé về những gì đã xảy ra trong ngày. Lời thì thầm giúp bé tập trung và đưa não bộ vào giấc ngủ sâu như bị thôi miên.', title_zh = '悄悄话故事 🌙', body_zh = '今天你说了太多话，嗓子都累了。关上灯，躺在宝宝身边，只用悄悄话在宝宝耳边讲讲今天发生的事。悄悄话能让宝宝集中注意力，像催眠一样让大脑准备好进入深度睡眠。' WHERE id = '67736a86-09e4-4211-ade6-1d5d48e8a05f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Los niños de las redes ya cuentan los colores y los números en inglés y el tuyo no quiere? ¡Deja de comparar ahora mismo! Cada niño tiene su propio reloj de desarrollo, único y diferente. A su ritmo, es perfecto.', body_fr = 'Sur les réseaux sociaux, des enfants comptent déjà les couleurs et les chiffres en anglais, et le vôtre n''en a pas envie ? Arrêtez tout de suite la comparaison ! Chaque enfant a son propre rythme de développement. Il est parfait à son rythme.', body_hi = 'सोशल मीडिया पर बच्चे रंग और गिनती अंग्रेज़ी में बोल रहे हैं, पर आपका बच्चा नहीं चाहता? तुलना अभी बंद कीजिए! हर बच्चे के विकास की घड़ी अनोखी और अलग होती है। वह अपनी रफ़्तार में बिल्कुल सही है।', body_id = 'Anak-anak di media sosial sudah bisa menyebut warna dan berhitung dalam bahasa Inggris, sementara anak Anda tidak mau? Hentikan perbandingan sekarang juga! Jam perkembangan setiap anak unik dan berbeda. Ia sempurna dengan temponya sendiri.', body_ja = 'SNSの子どもたちはもう色や数を英語で言えるのに、うちの子はいやがる？比べるのは今すぐやめましょう！成長のペースは子どもそれぞれちがいます。この子は自分のペースで完璧なんです。', body_ko = 'SNS 속 아이들은 벌써 영어로 색깔과 숫자를 세는데 우리 아이는 관심이 없나요? 비교는 당장 멈추세요! 아이마다 발달 시계는 고유하고 달라요. 자기 속도로 완벽해요.', body_nl = 'Kinderen op social media tellen al kleuren en cijfers in het Engels, maar jouw kind heeft er geen zin in? Stop meteen met vergelijken! Elk kind heeft zijn eigen, unieke ontwikkelingsklok. Hij is perfect in zijn eigen tempo.', body_pl = 'Dzieci w mediach społecznościowych już liczą i nazywają kolory po angielsku, a twoje nie chce? Natychmiast przestań porównywać! Zegar rozwoju każdego dziecka jest wyjątkowy i inny. Jest idealne w swoim tempie.', body_pt = 'As crianças das redes sociais já dizem as cores e contam em inglês, mas o seu não quer? Pare já com as comparações! O relógio de desenvolvimento de cada criança é único e diferente. Ele é perfeito ao seu próprio ritmo.', body_sv = 'Barnen på sociala medier räknar redan färger och siffror på engelska, men ditt barn vill inte? Sluta jämföra direkt! Varje barns utvecklingsklocka är unik och olika. Barnet är perfekt i sin egen takt.', body_vi = 'Trẻ con trên mạng xã hội đã đếm màu sắc, con số bằng tiếng Anh, còn bé nhà mình thì không muốn? Hãy dừng so sánh ngay! Mỗi trẻ có "đồng hồ phát triển" riêng, độc nhất. Bé hoàn hảo theo nhịp độ của riêng mình.', body_zh = '社交网络上别人家的孩子已经会用英语说颜色、数数字了，你家宝宝却不感兴趣？马上停止比较！每个孩子的发育时间表都是独特而不同的。宝宝按自己的节奏前进，就是完美的。' WHERE id = '8d9fad31-a8cd-481f-953a-35d411108040' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se acabó la siesta? ⏱️', body_es = '¿Por la noche tarda más de 1 hora en dormirse? Mira el gráfico del temporizador de sueño. En plena tormenta de los 3 años, ha llegado el momento de quitar del todo la siesta y adelantar la hora de dormir.', title_fr = 'La sieste, c''est fini ? ⏱️', body_fr = 'L''endormissement du soir prend plus d''1 heure ? Regardez le graphique du Minuteur de sommeil. Dans la tempête des 3 ans, il est peut-être temps de supprimer complètement la sieste et d''avancer l''heure du coucher.', title_hi = 'दिन की नींद खत्म? ⏱️', body_hi = 'रात को सोने में 1 घंटे से ज़्यादा लगता है? स्लीप टाइमर का शेड्यूल देखिए। 3 साल के तूफ़ान में दिन की नींद पूरी तरह बंद करने और रात का समय पहले करने का वक्त आ गया है।', title_id = 'Tidur siang sudah berakhir? ⏱️', body_id = 'Tidur malamnya butuh lebih dari 1 jam? Lihat jadwal di Timer Tidur. Di tengah badai usia 3 tahun, sudah waktunya menghentikan tidur siang sepenuhnya dan memajukan jam tidur malam.', title_ja = 'お昼寝は卒業？ ⏱️', body_ja = '夜、寝つくまでに1時間以上かかる？「睡眠タイマー」の記録を見てみましょう。3歳の嵐の時期には、お昼寝を完全にやめて、夜の寝る時間を早める時期が来ています。', title_ko = '낮잠 졸업일까요? ⏱️', body_ko = '밤에 잠드는 데 1시간 넘게 걸리나요? 수면 타이머의 기록을 확인해 보세요. 세 살의 폭풍 속에서 낮잠을 완전히 끊고 밤잠 시간을 앞당길 때가 됐을 수 있어요.', title_nl = 'Is het middagslaapje voorbij? ⏱️', body_nl = 'Duurt het ''s avonds meer dan een uur voor hij slaapt? Kijk naar het schema van de Slaaptimer. In de storm van 3 jaar is het misschien tijd om het middagslaapje helemaal te schrappen en de avond te vervroegen.', title_pl = 'Koniec z drzemką? ⏱️', body_pl = 'Wieczorne zasypianie trwa ponad godzinę? Spójrz na wykres w timerze snu. W burzliwym okresie 3 lat może przyszedł czas, by całkowicie zrezygnować z drzemki w dzień i przesunąć wieczorny sen wcześniej.', title_pt = 'A sesta acabou? ⏱️', body_pt = 'À noite demora mais de 1 hora a adormecer? Veja o gráfico do temporizador de sono. Na tempestade dos 3 anos, chegou a altura de acabar de vez com a sesta e antecipar a hora de deitar.', title_sv = 'Slut på tuppluren? ⏱️', body_sv = 'Tar det mer än 1 timme att somna på kvällen? Titta på diagrammet i sömntimern. I 3-årsstormen är det dags att helt slopa tuppluren och tidigarelägga kvällen.', title_vi = 'Hết thời ngủ trưa? ⏱️', body_vi = 'Buổi tối bé mất hơn 1 tiếng mới ngủ được? Hãy xem lịch trong Bộ hẹn giờ ngủ. Trong "cơn bão" tuổi lên 3, có lẽ đã đến lúc bỏ hẳn giấc ngủ trưa và cho bé đi ngủ sớm hơn vào buổi tối.', title_zh = '午睡结束了？⏱️', body_zh = '晚上要花1个多小时才能睡着？看看睡眠计时器的图表。在3岁的风暴期，或许是时候完全取消午睡，把晚上的睡觉时间提前了。' WHERE id = '4c7e076f-90de-4c2c-ae58-d9d897931fd4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las infinitas preguntas del «¿por qué?» 🌪️', body_es = '«¿Por qué los peces no andan?», «¿Adónde se ha ido el sol?». Desde primera hora su cerebro busca filosofía a un ritmo de 100 preguntas por hora. Aunque estés cansada, dale respuestas lógicas y cortas. Aprende los secretos del universo a través de tu tono de voz.', title_fr = 'Les « Pourquoi ? » sans fin 🌪️', body_fr = '« Pourquoi les poissons ne marchent pas ? », « Où est parti le soleil ? » Dès le matin, son cerveau cherche de la philosophie au rythme de 100 questions à l''heure. Même si vous êtes fatiguée, donnez-lui des réponses logiques et courtes. Il apprend les secrets de l''univers à travers le ton de votre voix.', title_hi = 'कभी न खत्म होने वाले ‘क्यों?’ 🌪️', body_hi = '‘मछलियाँ चलती क्यों नहीं?’, ‘सूरज कहाँ गया?’ सुबह-सुबह उसका दिमाग 100 सवाल प्रति घंटे की रफ़्तार से दर्शन खोजता है। थक भी जाएँ, तो उसे तर्कसंगत और छोटे जवाब दीजिए। वह दुनिया के रहस्य आपकी आवाज़ के लहजे से सीखता है।', title_id = 'Pertanyaan ''Kenapa?'' tanpa akhir 🌪️', body_id = '''Kenapa ikan tidak berjalan?'', ''Mataharinya pergi ke mana?'' Sejak pagi otaknya mencari filsafat dengan kecepatan 100 pertanyaan per jam. Meski lelah, beri ia jawaban yang logis dan singkat. Ia mempelajari rahasia alam semesta dari nada suara Anda.', title_ja = '終わらない「なんで？」 🌪️', body_ja = '「なんでお魚は歩かないの？」「お日さまはどこへ行ったの？」朝早くから、1時間に100問のペースで哲学を追い求めています。疲れていても、論理的で短い答えを返してあげて。宇宙のふしぎを、あなたの声のトーンから学んでいるんです。', title_ko = '끝없는 ''왜?'' 질문 🌪️', body_ko = '''물고기는 왜 안 걸어?'', ''해는 어디 갔어?'' 아침부터 머리가 시간당 100개의 질문 속도로 철학을 찾나요? 지쳐도 논리적이고 짧게 답해 주세요. 아이는 엄마의 목소리 톤에서 우주의 비밀을 배워요.', title_nl = 'De eindeloze waarom-vragen 🌪️', body_nl = '''Waarom lopen vissen niet?'', ''Waar is de zon gebleven?'' Al vroeg in de ochtend zoekt zijn brein filosofie met een snelheid van 100 vragen per uur. Ook al ben je moe, geef hem logische en korte antwoorden. Hij leert de geheimen van het universum via de toon van jouw stem.', title_pl = 'Niekończące się pytania „Dlaczego?” 🌪️', body_pl = '„Dlaczego ryby nie chodzą?”, „Gdzie poszło słońce?” Od samego rana jego mózg szuka filozofii w tempie 100 pytań na godzinę. Nawet gdy jesteś zmęczona, odpowiadaj mu logicznie i krótko. Tajemnic wszechświata uczy się z tonu twojego głosu.', title_pt = 'As perguntas infinitas do "Porquê?" 🌪️', body_pt = '"Porque é que os peixes não andam?", "Para onde foi o sol?" Logo de manhã cedo, o cérebro dele procura filosofia à velocidade de 100 perguntas por hora. Mesmo cansada, dê-lhe respostas lógicas e curtas. Ele aprende os segredos do universo pelo seu tom de voz.', title_sv = 'De ändlösa ”Varför?”-frågorna 🌪️', body_sv = '”Varför går inte fiskarna?”, ”Vart tog solen vägen?” Tidigt på morgonen söker barnets hjärna filosofi i en takt av 100 frågor i timmen. Även om du är trött, ge barnet logiska och korta svar. Barnet lär sig universums hemligheter genom din röst.', title_vi = 'Những câu hỏi "Tại sao?" bất tận 🌪️', body_vi = '"Sao cá không đi bộ?", "Mặt trời đi đâu rồi?" Sáng sớm, não bé đã đi tìm triết học với tốc độ 100 câu hỏi mỗi giờ. Dù mệt, hãy trả lời bé ngắn gọn và hợp lý. Bé học những bí mật của vũ trụ qua giọng nói của mẹ.', title_zh = '没完没了的“为什么？” 🌪️', body_zh = '“鱼为什么不走路？”“太阳去哪儿了？”一大早，宝宝的大脑就以每小时100个问题的速度探寻哲学。就算累了，也给宝宝简短又有逻辑的回答。宝宝正从你的语气里学习宇宙的奥秘。' WHERE id = 'b52dda4e-86c5-4200-973f-b7fbeb8869cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Quiere jugar con barro y arena? ¡Deja que se ensucie! Busca en Productos recomendados los accesorios más fáciles de limpiar para estas actividades que apoyan el desarrollo sensorial y déjale libre.', body_fr = 'Il veut jouer avec la boue et le sable ? Laissez-le se salir ! Trouvez dans les Produits recommandés le matériel le plus facile à nettoyer pour ces activités qui soutiennent son développement sensoriel, et laissez-le libre.', body_hi = 'कीचड़ और रेत से खेलना चाहता है? गंदा होने दीजिए! संवेदी विकास को बढ़ाने वाली इन गतिविधियों के लिए सबसे आसानी से साफ़ होने वाला सामान सुझाए गए प्रोडक्ट में ढूँढिए और उसे आज़ादी से खेलने दीजिए।', body_id = 'Ia ingin bermain lumpur dan pasir? Biarkan ia kotor! Temukan perlengkapan yang paling mudah dibersihkan untuk kegiatan pendukung perkembangan sensorik ini di Produk Rekomendasi, lalu biarkan ia bebas.', body_ja = 'どろんこや砂で遊びたがる？汚れてもいいんです！感覚の発達を助けるこうした遊びのために、いちばんお手入れが楽なグッズを「おすすめ商品」で見つけて、自由に遊ばせてあげましょう。', body_ko = '진흙과 모래로 놀고 싶어 하나요? 더러워져도 괜찮아요! 감각 발달을 돕는 이런 활동을 위해 가장 쉽게 씻기는 용품을 추천 상품에서 찾아 마음껏 놀게 해 주세요.', body_nl = 'Wil hij met modder en zand spelen? Laat hem vies worden! Zoek in Aanbevolen producten de spullen die het makkelijkst schoon te maken zijn voor deze activiteiten die de zintuiglijke ontwikkeling steunen, en laat hem vrij.', body_pl = 'Chce bawić się w błocie i piasku? Niech się ubrudzi! Znajdź w Polecanych produktach najłatwiejsze do czyszczenia akcesoria do tych zabaw wspierających rozwój sensoryczny i daj mu swobodę.', body_pt = 'Quer brincar com lama e areia? Deixe-o sujar-se! Encontre nos Produtos Recomendados os materiais mais fáceis de limpar para estas atividades que apoiam o desenvolvimento sensorial e deixe-o à vontade.', body_sv = 'Vill barnet leka med lera och sand? Låt det bli smutsigt! Hitta de mest lättstädade tillbehören för de här aktiviteterna som stödjer den sensoriska utvecklingen i Rekommenderade produkter och släpp barnet fritt.', body_vi = 'Bé muốn nghịch bùn, nghịch cát? Cứ để bé lấm bẩn! Hãy tìm trong Sản phẩm gợi ý những đồ dùng dễ vệ sinh nhất cho các hoạt động hỗ trợ phát triển giác quan này và để bé tự do khám phá.', body_zh = '想玩泥巴、玩沙子？让宝宝弄脏吧！在推荐商品里找找最容易清洗的用品，放手让宝宝做这些促进感官发展的活动。' WHERE id = 'c583d30d-5142-4b40-bcb3-399830284928' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Batalla con las sombras 👻', body_es = '¿Se asusta de su sombra en la pared y se esconde detrás de ti? La imaginación no conoce límites. Oscurece la habitación y, con una linterna, crea juegos de sombras con las manos en la pared.', title_fr = 'La bataille des ombres 👻', body_fr = 'Il a peur de son ombre sur le mur et se cache derrière vous ? L''imagination ne connaît pas de limites. Faites le noir dans la pièce et créez avec vos mains et une lampe de poche des jeux d''ombres sur le mur.', title_hi = 'परछाईं से लड़ाई 👻', body_hi = 'दीवार पर अपनी परछाईं से डरकर आपके पीछे छिपता है? कल्पना कोई सीमा नहीं मानती। कमरा अँधेरा करके टॉर्च से दीवार पर हाथों से परछाइयों के खेल बनाइए।', title_id = 'Bertarung dengan bayangan 👻', body_id = 'Ia takut pada bayangannya sendiri di dinding dan bersembunyi di belakang Anda? Imajinasi tidak mengenal batas. Gelapkan kamar, lalu dengan senter dan tangan Anda buat permainan bayangan di dinding.', title_ja = '影とのたたかい 👻', body_ja = '壁に映った自分の影が怖くて、あなたの後ろに隠れる？想像力に限界はありません。部屋を暗くして、懐中電灯を使って壁に手で影絵遊びをしましょう。', title_ko = '그림자와의 전투 👻', body_ko = '벽에 비친 자기 그림자가 무서워 엄마 뒤에 숨나요? 상상력에는 한계가 없어요. 방을 어둡게 하고 손전등을 비춰 손으로 벽에 그림자 놀이를 만들어 주세요.', title_nl = 'Strijd met de schaduw 👻', body_nl = 'Is hij bang voor zijn schaduw op de muur en verstopt hij zich achter je? Fantasie kent geen grenzen. Maak de kamer donker en maak met een zaklamp en je handen schaduwspelletjes op de muur.', title_pl = 'Walka z cieniem 👻', body_pl = 'Przestraszył się swojego cienia na ścianie i chowa się za tobą? Wyobraźnia nie zna granic. Zaciemnij pokój i z latarką twórz dłońmi na ścianie teatrzyk cieni.', title_pt = 'Luta com a sombra 👻', body_pt = 'Assustou-se com a sombra na parede e esconde-se atrás de si? A imaginação não tem limites. Escureça o quarto e, com uma lanterna, faça jogos de sombras com as mãos na parede.', title_sv = 'Strid mot skuggan 👻', body_sv = 'Blir barnet rädd för sin egen skugga på väggen och gömmer sig bakom dig? Fantasin känner inga gränser. Gör rummet mörkt och skapa skuggspel på väggen med händerna och en ficklampa.', title_vi = 'Chiến đấu với cái bóng 👻', body_vi = 'Bé sợ cái bóng của mình trên tường và nấp sau lưng mẹ? Trí tưởng tượng không có giới hạn. Hãy làm tối căn phòng, dùng đèn pin và đôi tay tạo những trò chơi bóng trên tường.', title_zh = '和影子大战 👻', body_zh = '被墙上自己的影子吓得躲到你身后？想象力没有边界。把房间调暗，打开手电筒，用手在墙上玩影子游戏吧。' WHERE id = '0446eb50-5fac-4056-ad65-76a95baf67f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con música 🎶', body_es = 'Prueba a cortar las tormentas sin motivo que estallan al atardecer con música clásica suave. Muchas veces este truco sencillo pero eficaz hace milagros en casa y llena la habitación de una calma absoluta y reparadora.', title_fr = 'S''endormir en musique 🎶', body_fr = 'Essayez de calmer les tempêtes sans raison de fin de journée avec une musique classique douce. Souvent, cette astuce simple mais efficace fait des miracles à la maison et apporte un calme absolu et reposant dans la pièce.', title_hi = 'संगीत के साथ नींद की ओर 🎶', body_hi = 'शाम को बिना वजह उठने वाले तूफ़ानों को हल्के शास्त्रीय संगीत से रोककर देखिए। अक्सर यह सीधी-सादी, पर असरदार तरकीब घर में चमत्कार करती है और कमरे में गहरा, आरामदायक सुकून लाती है।', title_id = 'Menuju tidur dengan musik 🎶', body_id = 'Coba redakan badai tanpa sebab menjelang malam dengan musik klasik yang lembut. Sering kali trik sederhana tapi ampuh ini membuat keajaiban di rumah dan menghadirkan ketenangan yang menenteramkan di kamar.', title_ja = '音楽で眠りへ 🎶', body_ja = '夕方のわけのわからない嵐を、やさしいクラシック音楽でしずめてみましょう。このシンプルだけど効果的な技は、家の中で奇跡を起こし、部屋に心やすらぐ落ち着きをもたらしてくれることが多いんです。', title_ko = '음악과 함께 잠으로 🎶', body_ko = '저녁 무렵 이유 없이 터지는 폭풍을 잔잔한 클래식 음악으로 가라앉혀 보세요. 이 단순하지만 효과적인 방법이 집에 기적을 일으키고 방에 깊고 편안한 평온을 가져다줄 때가 많아요.', title_nl = 'Met muziek naar dromenland 🎶', body_nl = 'Probeer onverklaarbare buien aan het eind van de middag te doorbreken met zachte klassieke muziek. Vaak doet dit simpele maar effectieve trucje wonderen en brengt het absolute, ontspannende rust in de kamer.', title_pl = 'Muzyczne przejście w sen 🎶', body_pl = 'Spróbuj uciszać wieczorne burze bez powodu łagodną muzyką klasyczną. Często ten prosty, ale skuteczny trik czyni w domu cuda i wnosi do pokoju absolutny, kojący spokój.', title_pt = 'Adormecer com música 🎶', body_pt = 'Experimente travar as tempestades sem razão do fim da tarde com música clássica suave. Muitas vezes este truque simples mas eficaz faz milagres em casa e traz ao quarto uma calma absoluta e repousante.', title_sv = 'Musik på vägen in i sömnen 🎶', body_sv = 'Testa att bryta de omotiverade stormarna framåt kvällen med lätt klassisk musik. Ofta gör det här enkla men effektiva knepet underverk hemma och ger rummet ett totalt, vilsamt lugn.', title_vi = 'Vào giấc cùng âm nhạc 🎶', body_vi = 'Hãy thử dùng nhạc cổ điển nhẹ nhàng để dập tắt những cơn bùng nổ vô cớ lúc chiều tối. Thường thì mẹo đơn giản nhưng hiệu quả này tạo nên phép màu trong nhà và mang lại sự bình yên, thư thái tuyệt đối cho căn phòng.', title_zh = '伴着音乐入睡 🎶', body_zh = '傍晚莫名爆发的小风暴，试试用轻柔的古典音乐来化解。这个简单又有效的小妙招，常常能在家里创造奇迹，给房间带来绝对放松的宁静。' WHERE id = 'b090e002-92d1-408a-8249-476d9566115b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La llamada del cuerpo 🩸', body_es = 'No te rindas a la irritación y el cansancio sin motivo. Mira el Calendario menstrual: tu cuerpo te está mandando señales. En lugar de culparte, descansa con un tentempié rico en magnesio.', title_fr = 'Le cri du corps 🩸', body_fr = 'Ne cédez pas à l''irritabilité et à la fatigue sans raison. Regardez le Suivi des règles, votre corps vous envoie des signaux. Au lieu de vous blâmer, reposez-vous avec une collation riche en magnésium.', title_hi = 'शरीर की पुकार 🩸', body_hi = 'बिना वजह की चिढ़ और थकान के आगे हार मत मानिए। पीरियड ट्रैकर देखिए, आपका शरीर संकेत दे रहा है। खुद को दोष देने के बजाय मैग्नीशियम वाले स्नैक के साथ आराम कीजिए।', title_id = 'Jeritan tubuh 🩸', body_id = 'Jangan menyerah pada rasa kesal dan lelah tanpa sebab. Lihat Pelacak Menstruasi, tubuh Anda sedang memberi sinyal. Daripada menyalahkan diri, beristirahatlah dengan camilan kaya magnesium.', title_ja = '体のSOS 🩸', body_ja = '理由のないイライラや疲れに負けないで。「生理トラッカー」を見てみましょう。体がサインを出しています。自分を責める代わりに、マグネシウムたっぷりのおやつで休みましょう。', title_ko = '몸이 보내는 외침 🩸', body_ko = '이유 없는 짜증과 피로에 지지 마세요. 생리 주기 기록을 확인해 보세요, 몸이 신호를 보내고 있어요. 자책하는 대신 마그네슘이 든 간식으로 쉬어 가세요.', title_nl = 'De roep van je lichaam 🩸', body_nl = 'Geef niet toe aan onverklaarbare prikkelbaarheid en vermoeidheid. Kijk in je Cyclustracker, je lichaam geeft signalen. Veroordeel jezelf niet, maar ontspan met een magnesiumrijk tussendoortje.', title_pl = 'Wołanie ciała 🩸', body_pl = 'Nie poddawaj się drażliwości i zmęczeniu bez powodu. Zajrzyj do Kalendarza miesiączkowego, twoje ciało wysyła sygnały. Zamiast się obwiniać, odpocznij z przekąską bogatą w magnez.', title_pt = 'O grito do corpo 🩸', body_pt = 'Não se renda à irritação e ao cansaço sem razão. Veja o Registo do Período: o seu corpo está a dar sinais. Em vez de se culpar, descanse com um snack rico em magnésio.', title_sv = 'Kroppens rop 🩸', body_sv = 'Ge inte efter för omotiverad irritation och trötthet. Titta i Mensspåraren, kroppen skickar signaler. Istället för att döma dig själv, vila med ett magnesiumrikt mellanmål.', title_vi = 'Tiếng gọi của cơ thể 🩸', body_vi = 'Đừng đầu hàng sự cáu kỉnh và mệt mỏi không rõ lý do. Hãy xem Theo dõi kỳ kinh, cơ thể mẹ đang gửi tín hiệu. Thay vì tự trách mình, hãy nghỉ ngơi với một món ăn nhẹ giàu magie.', title_zh = '身体的呼唤 🩸', body_zh = '别向莫名的烦躁和疲惫投降。看看经期记录，你的身体在发出信号。与其责怪自己，不如吃点富含镁的小零食，好好休息。' WHERE id = 'ba177a78-642c-483b-9a15-4d4a68a758af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cambiar palabras a propósito 🗣️', body_es = 'En lugar de «coche» dice a propósito «choque» y espera que te rías. Ya está descubriendo el sentido del humor. Ríete, pero no olvides recalcar suavemente cada vez la pronunciación correcta para que su cerebro también la codifique.', title_fr = 'Déformer les mots exprès 🗣️', body_fr = 'Au lieu de « voiture », il dit obstinément « boiture » et attend que vous en riiez. Il découvre la notion d''humour. Riez, mais n''oubliez pas de souligner doucement à chaque fois la bonne prononciation, pour que son cerveau enregistre aussi la bonne version.', title_hi = 'जानबूझकर शब्द बदलना 🗣️', body_hi = '‘गाड़ी’ की जगह ज़िद से ‘डाड़ी’ कहता है और आपके हँसने का इंतज़ार करता है। वह अब हास्य की समझ खोज रहा है। हँसिए, पर हर बार सही उच्चारण पर हल्का-सा ज़ोर देना भी मत भूलिए, ताकि उसका दिमाग सही रूप भी याद रखे।', title_id = 'Sengaja memelesetkan kata 🗣️', body_id = 'Ia ngotot menyebut ''mobil'' sebagai ''mobul'' dan menunggu Anda tertawa. Ia sedang menemukan rasa humor. Tertawalah, tapi jangan lupa setiap kali menekankan pengucapan yang benar dengan ringan agar otaknya juga merekam yang benar.', title_ja = 'わざと言いまちがえる 🗣️', body_ja = '「くるま」の代わりにわざと「まくる」と言って、あなたが笑うのを待っている。ユーモアのセンスを発見しているんです。笑っていいけれど、正しい言い方もそのたびに軽く添えてあげて。脳が正しいほうも覚えられるように。', title_ko = '일부러 단어 바꾸기 🗣️', body_ko = '''자동차''를 일부러 엉뚱하게 바꿔 말하고 엄마가 웃기를 기다리나요? 유머 감각을 발견하는 중이에요. 함께 웃되, 뇌가 바른 말도 기억하도록 매번 바른 발음을 살짝 강조해 주세요.', title_nl = 'Expres woorden verdraaien 🗣️', body_nl = 'Zegt hij steeds ''tuto'' in plaats van ''auto'' en wacht hij tot je lacht? Hij ontdekt humor. Lach mee, maar vergeet niet om elke keer licht de juiste uitspraak te benadrukken, zodat zijn brein ook de juiste vorm opslaat.', title_pl = 'Celowe przekręcanie słów 🗣️', body_pl = 'Uparcie mówi „samochodek-pomidorek” zamiast „samochód” i czeka, aż się roześmiejesz? Odkrywa już poczucie humoru. Śmiej się, ale za każdym razem delikatnie podkreśl poprawną wymowę, żeby jego mózg też ją zakodował.', title_pt = 'Trocar as palavras de propósito 🗣️', body_pt = 'Em vez de "carro" insiste em dizer "carrão" e espera que se ria? Já está a descobrir o sentido de humor. Ria-se, mas não se esqueça de realçar de leve, todas as vezes, a pronúncia certa, para que o cérebro também guarde a forma correta.', title_sv = 'Byter ut ord med flit 🗣️', body_sv = 'Barnet säger envist ”bal” istället för ”bil” och väntar på att du ska skratta. Barnet håller på att upptäcka humor. Skratta, men glöm inte att varje gång lätt betona det rätta uttalet, så att hjärnan också lagrar det rätta.', title_vi = 'Cố tình nói sai từ 🗣️', body_vi = 'Bé cứ cố tình nói sai tên một đồ vật và chờ mẹ bật cười. Bé đang khám phá khiếu hài hước. Hãy cười, nhưng mỗi lần cũng đừng quên nhẹ nhàng nhấn vào cách phát âm đúng để não bé ghi nhớ cả cách nói chuẩn.', title_zh = '故意说错词 🗣️', body_zh = '明明是“汽车”，却偏要说成“气扯”，还等着你笑？宝宝已经在发现幽默感了。笑吧，但每次也别忘了轻轻强调一下正确的发音，让大脑也记住正确的说法。' WHERE id = '1a2422fa-5d4e-4bbc-9f26-d69dd838496d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá, aliméntate 🥗', body_es = 'Has cocinado huevos de 4 formas distintas para que coma, pero ¿y tú qué has comido? Prepárate con Recetas saludables un plato especial, rico en hierro y calcio, que se hace en 5 minutos, date un premio y cuida tu energía.', title_fr = 'Maman, nourrissez-vous 🥗', body_fr = 'Vous avez cuisiné les œufs de 4 façons différentes pour le faire manger, mais vous, qu''avez-vous mangé ? Récompensez-vous avec une assiette spéciale des Recettes saines, riche en fer et en calcium, prête en 5 minutes, et préservez votre énergie.', title_hi = 'माँ, खुद का पेट भी भरिए 🥗', body_hi = 'उसे खिलाने के लिए 4 तरह से अंडे बनाए, और आपने क्या खाया? सेहतमंद रेसिपी से 5 मिनट में बनने वाली, आयरन और कैल्शियम से भरपूर एक खास प्लेट तैयार कीजिए, खुद को इनाम दीजिए और अपनी ऊर्जा बचाइए।', title_id = 'Ibu, kenyangkan dirimu 🥗', body_id = 'Kamu memasak telur dengan 4 cara berbeda untuk menyuapinya, lalu kamu sendiri makan apa? Siapkan sepiring hidangan istimewa kaya zat besi dan kalsium dari Resep Sehat yang jadi dalam 5 menit, hadiahi diri Anda, dan jaga energi Anda.', title_ja = 'ママも、しっかり食べて 🥗', body_ja = 'この子に食べさせるために卵を4通りも料理したけれど、あなたは何を食べた？「ヘルシーレシピ」から5分でできる、鉄分とカルシウムたっぷりの特別なひと皿を用意して、自分にごほうびをあげ、エネルギーを守りましょう。', title_ko = '엄마, 나부터 든든하게 🥗', body_ko = '아이를 먹이려고 달걀을 4가지 방법으로 요리했는데, 엄마는 뭘 드셨나요? 건강한 레시피에서 5분이면 완성되는 철분과 칼슘이 풍부한 특별한 한 접시로 나에게 상을 주고 에너지를 지키세요.', title_nl = 'Mama, zorg dat jij ook eet 🥗', body_nl = 'Je hebt op 4 manieren eieren gebakken om hem te laten eten, maar wat heb jij gegeten? Beloon jezelf met een speciaal bord uit Gezonde recepten, rijk aan ijzer en calcium en in 5 minuten klaar, en bescherm je energie.', title_pl = 'Mamo, nakarm siebie 🥗', body_pl = 'Przygotowałaś jajka na 4 różne sposoby, żeby go nakarmić, a ty co zjadłaś? Nagródź się wyjątkowym talerzem ze Zdrowych przepisów, bogatym w żelazo i wapń, gotowym w 5 minut, i chroń swoją energię.', title_pt = 'Mãe, alimente-se 🥗', body_pt = 'Fez ovos de 4 maneiras diferentes para ele comer, mas e a mãe, o que comeu? Prepare um prato especial rico em ferro e cálcio das Receitas Saudáveis, pronto em 5 minutos, recompense-se e proteja a sua energia.', title_sv = 'Mamma, ät du också 🥗', body_sv = 'Du lagade ägg på 4 olika sätt för att få barnet att äta, men vad åt du själv? Belöna dig med en särskild tallrik rik på järn och kalcium från Hälsosamma recept, klar på 5 minuter, och skydda din energi.', title_vi = 'Mẹ ơi, ăn no nhé 🥗', body_vi = 'Mẹ đã nấu trứng theo 4 cách khác nhau để bé chịu ăn, còn mẹ đã ăn gì chưa? Hãy tự thưởng cho mình một đĩa đặc biệt giàu sắt và canxi, làm xong trong 5 phút từ Công thức lành mạnh, để giữ gìn năng lượng.', title_zh = '妈妈，先喂饱自己 🥗', body_zh = '为了让宝宝吃饭，你换了4种做法煮鸡蛋，那你自己吃了什么？从健康食谱里做一份5分钟搞定、富含铁和钙的特别餐盘，犒劳自己，守护好自己的能量。' WHERE id = '21b5ead3-32a1-4d0e-96a9-1e38bf19fcec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica para retrasar el sueño ⏱️', body_es = '¿Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared? Pon un temporizador. Aplica la norma «cuando suena la campanita, todos a dormir» y líbrate con paciencia y calma de esta despedida sin fin.', title_fr = 'Tactiques pour retarder le dodo ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde dort » et échappez avec patience et calme à ces adieux sans fin.', title_hi = 'नींद टालने की चाल ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है? टाइमर लगाइए। ‘घंटी बजते ही सब सो जाते हैं’ का नियम लागू करके इस अंतहीन अलविदा से धैर्य और शांति के साथ बच निकलिए।', title_id = 'Taktik menunda tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua tidur'' dan bebaskan diri dari perpisahan tanpa akhir ini dengan sabar dan tenang.', title_ja = '寝る時間を遅らせる作戦 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり？タイマーをセットしましょう。「ベルが鳴ったらみんな寝る」のルールで、この終わらないおやすみのあいさつから、根気よく落ち着いて抜け出して。', title_ko = '잠 미루기 작전 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 잔다'' 규칙을 정해 이 끝없는 작별 인사에서 차분하게 벗어나세요.', title_nl = 'Uitsteltactieken voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaat iedereen slapen'' in en verlos jezelf geduldig en rustig van dit eindeloze afscheid.', title_pl = 'Taktyka odwlekania snu ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą? Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy śpią” i cierpliwie, spokojnie uwolnij się od tych niekończących się pożegnań.', title_pt = 'Táticas para adiar o sono ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede? Programe um temporizador. Aplique a regra "quando a campainha toca, todos dormem" e livre-se com paciência e calma desta despedida sem fim.', title_sv = 'Taktiken att skjuta upp sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla” och rädda dig tålmodigt och lugnt från det ändlösa farvälet.', title_vi = 'Chiến thuật trì hoãn giấc ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà đi ngủ" để kiên nhẫn, bình tĩnh thoát khỏi những lời tạm biệt bất tận này.', title_zh = '拖延睡觉的战术 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见？设个计时器。立下“铃声一响，大家都睡觉”的规矩，耐心又平静地摆脱这没完没了的告别吧。' WHERE id = 'cc6b3853-5963-47b7-b4f5-310bfd1919c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reunión con los juguetes 🧸', body_es = '¿Pone en fila todos sus osos y coches y les explica algo muy en serio señalando con el dedo? Se están formando el liderazgo y la atención. Quédate en un rincón de la habitación y observa en silencio, sin molestarle, esta reunión inventada.', title_fr = 'Réunion avec les jouets 🧸', body_fr = 'Il aligne tous ses nounours et ses voitures et leur explique très sérieusement quelque chose en pointant le doigt ? Son leadership et son attention se forment. Restez dans un coin de la pièce et observez en silence cette réunion imaginaire, sans le déranger.', title_hi = 'खिलौनों के साथ मीटिंग 🧸', body_hi = 'अपने सारे भालू और गाड़ियाँ लाइन में लगाकर उँगली दिखाते हुए बड़ी गंभीरता से उन्हें कुछ समझा रहा है? नेतृत्व और ध्यान आकार ले रहे हैं। कमरे के एक कोने में खड़े होकर उसकी इस काल्पनिक सभा को चुपचाप, उसे परेशान किए बिना देखिए।', title_id = 'Rapat dengan mainan 🧸', body_id = 'Ia menjajarkan semua beruang dan mobilnya, lalu dengan sangat serius menjelaskan sesuatu sambil menunjuk? Kepemimpinan dan perhatiannya sedang terbentuk. Berdirilah di sudut kamar dan saksikan rapat khayalannya diam-diam tanpa mengganggu.', title_ja = 'おもちゃたちの会議 🧸', body_ja = 'くまさんや車を全部一列に並べて、指でとても真剣に何かを説明している？リーダーシップと集中力が育っています。部屋のすみに立って、このごっこの会議を、じゃまをせずに静かに見守りましょう。', title_ko = '장난감 회의 🧸', body_ko = '곰 인형과 자동차를 줄 세워 놓고 손가락으로 아주 진지하게 무언가를 설명하나요? 리더십과 집중력이 자라고 있어요. 방 한쪽에 서서 이 상상 속 회의를 방해하지 말고 조용히 지켜보세요.', title_nl = 'Vergadering met de knuffels 🧸', body_nl = 'Zet hij al zijn beren en auto''s op een rij en legt hij ze heel serieus met zijn vingertje iets uit? Leiderschap en concentratie ontwikkelen zich. Blijf aan de kant van de kamer staan en kijk stil naar zijn verzonnen vergadering, zonder hem te storen.', title_pl = 'Zebranie zabawek 🧸', body_pl = 'Ustawił w rzędzie wszystkie misie i samochody i bardzo poważnie coś im tłumaczy, wskazując palcem? Kształtują się przywództwo i uwaga. Stań z boku pokoju i w ciszy, nie przeszkadzając, obserwuj to wymyślone zebranie.', title_pt = 'Reunião com os brinquedos 🧸', body_pt = 'Pôs todos os ursos e carros em fila e explica-lhes algo muito a sério, a apontar com o dedo? A liderança e a atenção estão a formar-se. Fique num canto do quarto e observe esta assembleia imaginária em silêncio, sem o incomodar.', title_sv = 'Möte med leksakerna 🧸', body_sv = 'Ställer barnet upp alla nallar och bilar på rad och förklarar något för dem på största allvar med pekfingret? Ledarskap och uppmärksamhet håller på att formas. Stå i ett hörn av rummet och titta tyst på det påhittade mötet utan att störa.', title_vi = 'Cuộc họp của đồ chơi 🧸', body_vi = 'Bé xếp hàng tất cả gấu bông và ô tô, rồi chỉ tay giảng giải cho chúng điều gì đó rất nghiêm túc? Khả năng lãnh đạo và sự tập trung đang hình thành. Hãy đứng ở một góc phòng và lặng lẽ quan sát "cuộc họp" tưởng tượng này mà không làm phiền bé.', title_zh = '和玩具开会 🧸', body_zh = '把所有小熊和小汽车排成一排，用手指着非常认真地给它们讲着什么？领导力和注意力正在形成。站在房间一边，不打扰宝宝，安静地欣赏这场编出来的会议吧。' WHERE id = '629ea652-62bd-4947-96b6-0e7f4cabb751' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando lo que haces ya no funciona, los ruidos de animales raros y las caras graciosas de papá salvan la situación al instante. En las crisis de la tarde, pásale la pelota y disfruta desde fuera de las carcajadas.', body_fr = 'Quand vos astuces ne marchent plus, les drôles de cris d''animaux et les grimaces de papa sauvent aussitôt la situation. Pendant les crises du soir, passez-lui le relais et profitez de loin des joyeux éclats de rire.', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तब पापा की जानवरों जैसी अजीब आवाज़ें और मज़ेदार चेहरे हालात तुरंत सँभाल लेते हैं। शाम के बिगड़े मूड में ज़िम्मेदारी उन्हें सौंप दीजिए और दूर से खुशी भरे ठहाके देखिए।', body_id = 'Saat cara Anda tak lagi berhasil, suara binatang yang aneh dan wajah lucu Ayah langsung menyelamatkan keadaan. Saat krisis sore hari, oper bolanya ke Ayah dan saksikan tawa riang dari samping.', body_ja = 'あなたの手が通用しなくなったら、パパのへんてこな動物の鳴きまねやおどけた顔がすぐに状況を救ってくれます。夕方のぐずりタイムはバトンをパパに渡して、そばで楽しい笑い声を聞きましょう。', body_ko = '엄마의 방법이 더는 통하지 않을 때, 아빠의 이상한 동물 소리와 웃긴 표정이 바로 상황을 구해 줘요. 저녁 떼쓰기 때는 아빠에게 공을 넘기고 옆에서 즐거운 웃음소리를 감상하세요.', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke dierengeluiden en grappige gezichten meteen de situatie. Speel bij avondbuien de bal naar hem door en geniet van een afstand van het vrolijke geschater.', body_pl = 'Gdy twoje sposoby już nie działają, śmieszne zwierzęce odgłosy i miny taty od razu ratują sytuację. Podczas wieczornych kryzysów przekaż mu pałeczkę i z boku słuchaj radosnych chichotów.', body_pt = 'Quando os seus truques já não funcionam, os sons de animais estranhos e as caretas cómicas do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola e observe à distância as gargalhadas alegres.', body_sv = 'När ditt eget inte längre fungerar räddar pappas konstiga djurläten och roliga miner situationen direkt. Vid kvällskriserna, skicka bollen till honom och titta på de glada skratten från sidan.', body_vi = 'Khi mọi chiêu của mẹ không còn hiệu quả, những tiếng kêu con vật kỳ quặc và gương mặt hài hước của bố sẽ cứu nguy ngay lập tức. Trong những cơn khủng hoảng buổi tối, hãy "chuyền bóng" cho bố và thưởng thức những tràng cười vui vẻ từ xa.', body_zh = '当你的办法都不管用时，爸爸学的奇怪动物叫声和搞怪表情马上就能化解局面。傍晚闹脾气时，把“球”传给爸爸，在一旁欣赏欢乐的笑声吧。' WHERE id = '8fdbd74e-0b03-4420-a816-6a0ea6ecdb73' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rebelión contra la siesta 🥱', body_es = '¿No quiere ir a la cama y llora? No le obligues. Baja las luces de la habitación y crea una rutina nueva anunciando la «hora de hojear libros en silencio»: así descansaréis los dos.', title_fr = 'La révolte de la sieste 🥱', body_fr = 'Il ne veut pas aller au lit et pleure ? Ne le forcez pas. Baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine qui vous reposera tous les deux, lui comme vous.', title_hi = 'दिन की नींद से बगावत 🥱', body_hi = 'सोने नहीं जाना चाहता और रोता है? ज़बरदस्ती मत कीजिए। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और एक नया रूटीन बनाइए, ताकि आप और वह, दोनों आराम कर सकें।', title_id = 'Pemberontakan tidur siang 🥱', body_id = 'Ia tidak mau tidur dan menangis? Jangan memaksa. Redupkan lampu kamar dan ciptakan rutinitas baru dengan mengumumkan ''Waktu membaca buku dengan tenang'', agar Anda dan ia sama-sama beristirahat.', title_ja = 'お昼寝ストライキ 🥱', body_ja = 'ベッドに行きたくなくて泣いている？無理強いしないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ふたりともほっとできる新しいルーティンをつくりましょう。そうすれば、あなたもこの子も休めます。', title_ko = '낮잠 반란 🥱', body_ko = '자러 가기 싫다며 우나요? 억지로 재우지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 새로운 루틴을 만들어 보세요. 그러면 엄마도 아이도 함께 쉴 수 있어요.', title_nl = 'Opstand bij het middagslaapje 🥱', body_nl = 'Wil hij niet naar bed en huilt hij? Dwing hem niet. Dim de lichten in de kamer en kondig een ''stil boekjesuurtje'' aan, een nieuwe routine waar jullie allebei van tot rust komen.', title_pl = 'Bunt przed drzemką 🥱', body_pl = 'Nie chce iść do łóżka i płacze? Nie zmuszaj. Przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę, dzięki której odpoczniecie oboje.', title_pt = 'A revolta da sesta 🥱', body_pt = 'Não quer ir para a cama e chora? Não o obrigue. Baixe as luzes do quarto e crie uma nova rotina anunciando a "hora de folhear livros em silêncio": assim descansam os dois.', title_sv = 'Upproret mot tuppluren 🥱', body_sv = 'Vill barnet inte gå och lägga sig och gråter? Tvinga inte. Dämpa ljuset i rummet och utlys en ”tyst bläddra-i-böcker-stund”, så skapar du en ny rutin där både du och barnet får vila.', title_vi = 'Cuộc nổi loạn giờ ngủ trưa 🥱', body_vi = 'Bé không muốn lên giường và khóc? Đừng ép. Hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới, nhờ đó cả mẹ và bé đều được nghỉ ngơi.', title_zh = '午睡大反抗 🥱', body_zh = '不肯上床还哭闹？别强迫。把房间灯光调暗，宣布“安静翻书时间”，建立一个新的、让你们俩都能休息的日常流程，这样你和宝宝都能放松下来。' WHERE id = 'b32c30b6-11a0-4afc-aed3-bdfb0cc56622' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pensando en la guardería 🏫', body_es = '¿Notas que ya necesita socializar más? ¿Es el momento adecuado para la guardería? Entra en la Comunidad Anacan y lee las experiencias reales de adaptación de otras mamás para que te sea más fácil decidir.', title_fr = 'Réflexions sur la crèche 🏫', body_fr = 'Vous sentez qu''il a besoin de plus de vie sociale ? Est-ce le bon moment pour la crèche ? Rejoignez la Communauté Anacan et lisez les vraies expériences d''adaptation d''autres mamans pour vous aider à décider.', title_hi = 'प्ले स्कूल के ख्याल 🏫', body_hi = 'लगता है उसे अब लोगों से घुलने-मिलने की ज़्यादा ज़रूरत है? क्या प्ले स्कूल का सही समय आ गया? Anacan कम्युनिटी में जाकर दूसरी माँओं के एडजस्टमेंट के असली अनुभव पढ़िए और फ़ैसला आसान बनाइए।', title_id = 'Memikirkan TK 🏫', body_id = 'Anda merasa ia kini lebih butuh bersosialisasi? Apakah ini waktu yang tepat untuk TK? Masuklah ke Komunitas Anacan dan baca pengalaman adaptasi nyata ibu-ibu lain agar keputusan Anda lebih mudah.', title_ja = '保育園のことを考える 🏫', body_ja = 'もっと人とかかわる時間が必要だと感じていますか？保育園にちょうどいい時期かな？Anacanコミュニティで、ほかのママたちのリアルな慣らし保育の体験を読んで、決めるヒントにしましょう。', title_ko = '어린이집 생각 🏫', body_ko = '아이에게 사회생활이 더 필요하다고 느끼나요? 어린이집에 보낼 때가 됐을까요? Anacan 커뮤니티에서 다른 엄마들의 실제 적응 경험담을 읽고 결정을 쉽게 내려 보세요.', title_nl = 'Gedachten over de opvang 🏫', body_nl = 'Heb je het gevoel dat hij meer behoefte heeft aan contact met andere kinderen? Is het de juiste tijd voor de opvang? Ga naar de Anacan Community en lees de echte wenervaringen van andere mama''s, zo wordt je beslissing makkelijker.', title_pl = 'Myśli o przedszkolu 🏫', body_pl = 'Czujesz, że potrzebuje już więcej kontaktu z rówieśnikami? Czy to dobry czas na przedszkole? Wejdź do Społeczności Anacan i poczytaj o prawdziwych doświadczeniach adaptacji innych mam, by łatwiej podjąć decyzję.', title_pt = 'A pensar no jardim de infância 🏫', body_pt = 'Sente que ele já precisa de socializar mais? Será a altura certa para o jardim de infância? Entre na Comunidade Anacan e leia as experiências reais de adaptação de outras mães para facilitar a sua decisão.', title_sv = 'Tankar om förskola 🏫', body_sv = 'Känner du att barnet nu behöver mer social kontakt? Är det rätt tid för förskola? Gå in i Anacan Community och läs andra mammors verkliga erfarenheter av inskolning, så blir beslutet lättare.', title_vi = 'Suy nghĩ về trường mầm non 🏫', body_vi = 'Mẹ cảm thấy bé cần giao tiếp xã hội nhiều hơn? Đã đến lúc cho bé đi mầm non chưa? Hãy vào Cộng đồng Anacan đọc những trải nghiệm thích nghi thực tế của các mẹ khác để quyết định dễ dàng hơn.', title_zh = '关于幼儿园的思考 🏫', body_zh = '感觉宝宝更需要社交了？现在是上幼儿园的合适时机吗？进入Anacan社区，读读其他妈妈真实的入园适应经历，让决定变得更容易。' WHERE id = '07209316-984c-477d-a3c0-ff2c7202c5fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ataque de rabia repentino 💥', body_es = '¿Jugando se ha enfadado de golpe y ha lanzado sus juguetes? Aún no sabe controlar sus emociones. En lugar de gritar, empatiza y conecta con él diciendo: «Veo que estás enfadado, vamos a respirar hondo juntos».', title_fr = 'Colère soudaine 💥', body_fr = 'En jouant, il s''est soudain énervé et a lancé ses jouets ? Il ne sait pas encore gérer ses émotions. Au lieu de crier, montrez-lui de l''empathie et créez le lien : « Je vois que tu es en colère, respirons profondément ensemble. »', title_hi = 'अचानक गुस्से का झटका 💥', body_hi = 'खेलते-खेलते अचानक चिढ़कर खिलौने फेंक दिए? वह अभी अपनी भावनाएँ संभाल नहीं पाता। चिल्लाने के बजाय कहिए, ‘मैं देख रही हूँ कि तुम नाराज़ हो, आओ साथ में गहरी साँस लें’, सहानुभूति दिखाइए और उससे जुड़िए।', title_id = 'Ledakan amarah mendadak 💥', body_id = 'Sedang bermain, tiba-tiba ia marah dan melempar mainannya? Ia belum bisa mengendalikan emosinya. Daripada berteriak, tunjukkan empati dan jalin kedekatan dengan berkata ''Mama lihat kamu marah, ayo kita tarik napas dalam bersama''.', title_ja = 'いきなりの怒り爆発 💥', body_ja = '遊んでいる最中に急に怒って、おもちゃを投げた？まだ気持ちをコントロールできないんです。どなる代わりに「怒っているのがわかるよ、一緒に深呼吸しよう」と声をかけて、気持ちに寄りそい、心をつなぎましょう。', title_ko = '갑작스러운 분노 폭발 💥', body_ko = '놀다가 갑자기 화가 나서 장난감을 던졌나요? 아직 감정을 조절하지 못해서 그래요. 소리치는 대신 ''화가 났구나, 같이 깊게 숨 쉬어 보자''라고 말하며 공감하고 마음을 이어 주세요.', title_nl = 'Plotselinge woedeaanval 💥', body_nl = 'Werd hij tijdens het spelen ineens boos en gooide hij met zijn speelgoed? Hij kan zijn emoties nog niet beheersen. Ga niet schreeuwen, maar toon empathie en maak contact: ''Ik zie dat je boos bent, laten we samen diep ademhalen.''', title_pl = 'Nagły wybuch złości 💥', body_pl = 'Podczas zabawy nagle się zdenerwował i rzucił zabawkami? Nie umie jeszcze panować nad emocjami. Zamiast krzyczeć, powiedz: „Widzę, że się złościsz, weźmy razem głęboki oddech”, okaż empatię i bądź blisko.', title_pt = 'Ataque de fúria repentino 💥', body_pt = 'A brincar, irritou-se de repente e atirou os brinquedos? Ainda não consegue controlar as emoções. Em vez de gritar, diga "Vejo que estás zangado, vamos respirar fundo juntos", mostre empatia e crie ligação.', title_sv = 'Ett plötsligt utbrott 💥', body_sv = 'Blev barnet plötsligt argt mitt i leken och kastade iväg leksakerna? Barnet kan ännu inte hantera sina känslor. Istället för att skrika, säg ”Jag ser att du är arg, kom så andas vi djupt tillsammans”, visa empati och håll kontakten.', title_vi = 'Cơn giận bất chợt 💥', body_vi = 'Đang chơi, bé bỗng nổi giận và ném đồ chơi? Bé chưa biết kiểm soát cảm xúc. Thay vì quát mắng, hãy đồng cảm và kết nối với bé: "Mẹ thấy con đang bực, mình cùng hít thở thật sâu nhé".', title_zh = '突然的怒气 💥', body_zh = '玩着玩着突然生气，把玩具扔了出去？宝宝还不会管理自己的情绪。别吼，说一句“我看到你生气了，我们一起深呼吸吧”，用共情和宝宝建立连接。' WHERE id = '3f7992d5-c092-46f7-84f8-f10e51f36593' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se inquieta cuando se apagan las luces del dormitorio? 🌙', body_es = 'Pon en un rincón de la habitación una pequeña lamparita de luz cálida. El resto de la habitación debe quedar totalmente a oscuras para un sueño profundo.', title_fr = 'Il s''inquiète quand la lumière s''éteint ? 🌙', body_fr = 'Posez dans un coin de la chambre une petite veilleuse de couleur chaude. Le reste de la chambre doit rester complètement sombre pour un sommeil profond.', title_hi = 'लाइटें बुझते ही बेचैन हो जाता है? 🌙', body_hi = 'कमरे के एक कोने में गर्म रंग की एक छोटी नाइट लैंप रखिए। बाकी कमरा गहरी नींद के लिए पूरी तरह अँधेरा रहना चाहिए।', title_id = 'Ia gelisah saat lampu kamar padam? 🌙', body_id = 'Letakkan lampu tidur kecil berwarna hangat di salah satu sudut kamar. Bagian kamar lainnya harus tetap gelap total untuk tidur yang nyenyak.', title_ja = '寝室の明かりを消すと不安になる？ 🌙', body_ja = '部屋のすみに、暖かい色の小さなナイトライトを置きましょう。それ以外の部分は、ぐっすり眠れるように真っ暗にしておいてね。', title_ko = '침실 불이 꺼지면 불안해하나요? 🌙', body_ko = '방 한쪽에 작고 따뜻한 색의 수면등을 두세요. 나머지 공간은 깊은 잠을 위해 완전히 어둡게 유지해야 해요.', title_nl = 'Wordt hij onrustig als het licht in de slaapkamer uitgaat? 🌙', body_nl = 'Zet een klein nachtlampje met een warme kleur in een hoek van de kamer. De rest van de kamer blijft helemaal donker voor een diepe slaap.', title_pl = 'Boi się, gdy gaśnie światło? 🌙', body_pl = 'Postaw w kącie pokoju małą lampkę nocną w ciepłym kolorze. Reszta pokoju powinna pozostać zupełnie ciemna, by sen był głęboki.', title_pt = 'Fica inquieto quando as luzes do quarto se apagam? 🌙', body_pt = 'Ponha num canto do quarto uma pequena luz de presença de cor quente. O resto do quarto deve ficar totalmente escuro para um sono profundo.', title_sv = 'Blir barnet oroligt när lampan släcks i sovrummet? 🌙', body_sv = 'Ställ en liten nattlampa med varmt sken i ett hörn av rummet. Resten av rummet ska vara helt mörkt för en djup sömn.', title_vi = 'Bé lo lắng khi đèn phòng ngủ tắt? 🌙', body_vi = 'Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm ở một góc phòng. Phần còn lại của căn phòng nên tối hoàn toàn để bé ngủ sâu.', title_zh = '卧室一关灯就不安？🌙', body_zh = '在房间一角放一盏小小的暖色小夜灯。房间其余的地方要保持全黑，才能睡得深沉。' WHERE id = 'a376f906-e66c-4618-827e-79f3b75ebd16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas con objetos 🗣️', body_es = 'En el parque le cuenta cosas muy en serio a una piedra, o en casa a una silla, y hasta les riñe. A través del juego simbólico procesa el mundo. Anota sin falta estos guiones tan especiales en el Seguimiento del desarrollo.', title_fr = 'Conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et les gronde ? Il comprend le monde à travers le jeu symbolique. Notez absolument ces scénarios particuliers dans le Suivi de développement.', title_hi = 'बेजान चीज़ों से बातचीत 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ कहता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया को समझ रहा है। उसकी इन खास कहानियों को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Mengobrol dengan benda mati 🗣️', body_id = 'Di taman ia berbicara serius dengan sebuah batu, atau di rumah memarahi kursi. Lewat permainan simbolis, ia mengolah dunia. Pastikan menandai skenario istimewanya ini di Pelacak Perkembangan.', title_ja = 'ものとのおしゃべり 🗣️', body_ja = '公園の石や家のいすに、すっかり真剣に話しかけたり、しかったりしています。象徴遊びを通して世界を整理しているんです。この特別なシナリオを、ぜひ「発達トラッカー」に記録しておきましょう。', title_ko = '사물과의 대화 🗣️', body_ko = '공원의 돌이나 집의 의자에게 아주 진지하게 무언가를 이야기하고 혼내기도 하나요? 상징 놀이로 세상을 소화하는 중이에요. 이 특별한 시나리오를 성장 기록에 꼭 표시해 두세요.', title_nl = 'Gesprekken met dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld. Noteer deze bijzondere scenario''s zeker in de Groeitracker.', title_pl = 'Rozmowy z przedmiotami 🗣️', body_pl = 'W parku zupełnie poważnie coś opowiada kamieniowi albo w domu beszta krzesło. Przez zabawę symboliczną przetwarza świat. Koniecznie zaznacz te wyjątkowe scenariusze w Śledzeniu rozwoju.', title_pt = 'Conversas com objetos 🗣️', body_pt = 'No parque, fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo. Não deixe de registar estes enredos especiais no Registo de Crescimento.', title_sv = 'Samtal med livlösa saker 🗣️', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen. Anteckna absolut barnets speciella scenarier i Utvecklingsspåraren.', title_vi = 'Trò chuyện với đồ vật 🗣️', body_vi = 'Ở công viên, bé nói chuyện rất nghiêm túc với một hòn đá, ở nhà thì "mắng" chiếc ghế? Bé đang xử lý thế giới qua trò chơi biểu tượng. Hãy nhớ đánh dấu những kịch bản đặc biệt này trong Theo dõi phát triển.', title_zh = '和没有生命的东西聊天 🗣️', body_zh = '在公园对着一块石头、在家对着一把椅子，非常认真地说着什么，还训它们。宝宝通过象征性游戏来理解世界。一定要把这些特别的小剧本记在发育追踪里。' WHERE id = '171bedf4-3516-44a5-9404-c089661d5bbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El milagro del agua caliente 🛀', body_es = 'A veces nada funciona y llora por todo. Mételo en una bañera de agua templada y échale un poco de espuma. El poder místico del agua para quitar la tensión llenará de calma al instante la habitación y su sistema nervioso.', title_fr = 'Le miracle de l''eau chaude 🛀', body_fr = 'Parfois, rien ne marche, il pleure pour tout. Mettez-le dans un bain d''eau tiède avec un peu de mousse. Le pouvoir presque magique de l''eau, qui absorbe la tension, apportera aussitôt la paix à toute la pièce et à son système nerveux.', title_hi = 'गरम पानी का चमत्कार 🛀', body_hi = 'कभी-कभी कुछ भी काम नहीं करता, वह बस हर बात पर रोता है। उसे गुनगुने पानी से भरे टब में बिठाइए, थोड़ा झाग डाल दीजिए। पानी की वह रहस्यमयी, तनाव सोखने वाली ताकत पूरे कमरे और उसके तंत्रिका तंत्र में तुरंत सुकून ले आएगी।', title_id = 'Keajaiban air hangat 🛀', body_id = 'Kadang tak ada yang berhasil, ia menangisi segala hal. Masukkan ia ke bak berisi air hangat dan tambahkan sedikit busa. Kekuatan air yang ajaib dan meredakan ketegangan akan langsung membawa ketenangan ke seluruh ruangan dan sistem sarafnya.', title_ja = 'お湯の奇跡 🛀', body_ja = '何をしてもうまくいかず、ただ何にでも泣いてしまう日もあります。ぬるめのお湯をはったバスタブに入れて、泡を少し加えてみましょう。お湯のふしぎな、緊張をほぐす力が、部屋全体とこの子の神経にすぐに落ち着きをもたらします。', title_ko = '따뜻한 물의 기적 🛀', body_ko = '가끔은 아무것도 통하지 않고 모든 일에 울기만 하죠. 따뜻한 물을 받은 욕조에 거품을 조금 풀고 들어가게 해 주세요. 긴장을 풀어 주는 물의 신비한 힘이 방 안과 아이의 신경계에 바로 평온을 가져다줄 거예요.', title_nl = 'Het wonder van warm water 🛀', body_nl = 'Soms werkt niets en huilt hij gewoon om alles. Zet hem in een bad met lauw water en doe er wat schuim in. De mystieke, ontspannende kracht van het water brengt meteen rust in de hele kamer en in zijn zenuwstelsel.', title_pl = 'Cud ciepłej wody 🛀', body_pl = 'Czasem nic nie działa, a on po prostu płacze o wszystko. Włóż go do wanny z ciepłą wodą i dodaj trochę piany. Tajemnicza, kojąca moc wody od razu wniesie spokój do całego pokoju i do jego układu nerwowego.', title_pt = 'O milagre da água quente 🛀', body_pt = 'Às vezes nada resulta, ele simplesmente chora por tudo. Ponha-o numa banheira com água morna e junte um pouco de espuma. O poder místico da água, que alivia a tensão, vai trazer logo calma a todo o quarto e ao sistema nervoso dele.', title_sv = 'Det varma vattnets under 🛀', body_sv = 'Ibland hjälper ingenting, barnet gråter bara åt allt. Sätt barnet i ett badkar med ljummet vatten och lite skum. Vattnets mystiska, spänningsdämpande kraft ger direkt lugn åt hela rummet och barnets nervsystem.', title_vi = 'Phép màu của nước ấm 🛀', body_vi = 'Đôi khi chẳng cách nào hiệu quả, bé cứ khóc vì mọi thứ. Hãy cho bé vào bồn nước ấm, thêm chút bọt xà phòng. Sức mạnh kỳ diệu, xua tan căng thẳng của nước sẽ lập tức mang lại bình yên cho cả căn phòng và hệ thần kinh của bé.', title_zh = '温水的奇迹 🛀', body_zh = '有时候什么办法都不管用，宝宝就是什么都哭。把宝宝放进装满温水的浴缸，再加一点泡泡。水那种神奇的、能吸走紧张的力量，会马上给整个房间和宝宝的神经系统带来安宁。' WHERE id = 'a74f3aea-565f-455f-bdbe-9ee44f6c7e35' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, no te fíes solo de lo que ves por la ventana. Con el asistente Tiempo y ropa elige el conjunto más adecuado para el viento y la temperatura reales, sal de casa tranquila y preparada y deja que suelte su energía al aire libre.', body_fr = 'Avant la promenade, ne vous fiez pas à ce que vous voyez par la fenêtre. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et à la température réels, sortez sereine et bien préparée, et laissez-le se dépenser en plein air.', body_hi = 'सैर पर निकलते समय खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े असिस्टेंट से बाहर की असली हवा और गर्मी के लिए सबसे सही कपड़े तय कीजिए, तैयारी के साथ आराम से घर से निकलिए और बच्चे को खुली हवा में ऊर्जा निकालने का मौका दीजिए।', body_id = 'Saat akan jalan-jalan, jangan tertipu hanya dengan melihat dari jendela. Gunakan Cuaca dan Pakaian untuk menentukan setelan yang paling cocok dengan angin dan suhu sebenarnya, keluar rumah dengan nyaman dan siap, dan biarkan ia menyalurkan energinya di udara terbuka.', body_ja = 'お出かけ前に、窓の外の様子にだまされないで。「天気と服装」で外の本当の風や気温にぴったりのコーデを決めて、しっかり準備して安心して出かけ、外でエネルギーを発散させてあげましょう。', body_ko = '산책 나갈 때 창밖만 보고 판단하지 마세요. 날씨와 옷차림 도우미로 실제 바람과 기온에 가장 알맞은 옷차림을 정하고 든든하게 준비해서 나가, 아이가 바깥에서 에너지를 마음껏 쓰게 해 주세요.', body_nl = 'Laat je niet misleiden door een blik uit het raam als je gaat wandelen. Bepaal met de assistent Weer en kleding de beste outfit voor de echte wind en temperatuur buiten, ga goed voorbereid de deur uit en laat hem zijn energie in de buitenlucht kwijtraken.', body_pl = 'Przed spacerem nie daj się zwieść widokowi za oknem. Dobierz w narzędziu Pogoda i ubiór zestaw pasujący do prawdziwego wiatru i temperatury, wyjdź z domu spokojnie i przygotowana i pozwól dziecku wyładować energię na świeżym powietrzu.', body_pt = 'Antes de ir passear, não se deixe enganar pelo que vê da janela. Com o assistente Tempo e Roupa, escolha a combinação mais adequada ao vento e à temperatura reais lá fora, saia de casa tranquila e preparada e deixe a criança gastar a energia ao ar livre.', body_sv = 'Låt dig inte luras av att titta ut genom fönstret när ni ska ut på promenad. Med hjälpen Väder och kläder hittar du den klädsel som passar bäst för den verkliga vinden och temperaturen ute, så att ni går ut bekvämt och förberedda och barnet kan göra av med energin i friska luften.', body_vi = 'Khi chuẩn bị đi dạo, đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ. Hãy dùng Thời tiết và trang phục để chọn bộ đồ phù hợp nhất với gió và nhiệt độ thực tế bên ngoài, ra khỏi nhà thật thoải mái, sẵn sàng, và để bé xả năng lượng ngoài trời.', body_zh = '出门散步前，别只看窗外就被骗了。用天气与穿衣助手，根据外面真实的风力和温度确定最合适的搭配，舒舒服服、有备而出，让宝宝在户外尽情释放能量。' WHERE id = 'b4c6b7ac-81bd-476f-9816-9e8c14627206' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te cuenta los dibujos que ha visto con su propia gramática y te explica muy serio quién fue adónde. Escúchale con atención, como si te sorprendiera. Deja que se sienta la persona más lista del mundo.', body_fr = 'Il vous raconte le dessin animé qu''il a vu avec sa propre grammaire et vous explique très sérieusement qui est allé où. Écoutez-le attentivement, comme si vous étiez étonnée. Laissez-le se sentir le plus intelligent du monde.', body_hi = 'जो कार्टून देखा, वह आपको अपनी व्याकरण में सुनाता है, गंभीरता से समझाता है कि कौन कहाँ गया। उसे ध्यान से, हैरान होने के अंदाज़ में सुनिए। उसे खुद को दुनिया का सबसे समझदार महसूस करने दीजिए।', body_id = 'Ia menceritakan kartun yang ditontonnya dengan tata bahasanya sendiri, menjelaskan dengan serius siapa pergi ke mana. Dengarkan baik-baik, seolah Anda takjub. Biarkan ia merasa menjadi orang paling pintar di dunia.', body_ja = '見たアニメの話を自分なりの文法で話してくれて、誰がどこへ行ったかを真剣に説明しています。おどろいたふりをして、しっかり聞いてあげましょう。自分が世界でいちばんかしこいと感じさせてあげて。', body_ko = '본 만화를 자기만의 문법으로 들려주며 누가 어디에 갔는지 진지하게 설명하나요? 놀란 듯 귀 기울여 들어 주세요. 세상에서 가장 똑똑한 사람이 된 기분을 느끼게 해 주세요.', body_nl = 'Hij vertelt je de tekenfilm die hij keek in zijn eigen grammatica en legt heel serieus uit wie waarheen ging. Luister aandachtig, alsof je verbaasd bent. Laat hem zich de slimste van de wereld voelen.', body_pl = 'Opowiada ci obejrzaną bajkę po swojemu, z własną gramatyką, i poważnie tłumaczy, kto dokąd poszedł. Słuchaj go uważnie, jakbyś była zdumiona. Pozwól mu poczuć się najmądrzejszym na świecie.', body_pt = 'Conta-lhe os desenhos animados que viu com a sua própria gramática e explica muito a sério quem foi para onde. Ouça-o com atenção, como se estivesse surpreendida. Deixe-o sentir-se a pessoa mais inteligente do mundo.', body_sv = 'Barnet återberättar tecknade filmen med sin egen grammatik och förklarar på största allvar vem som gick vart. Lyssna uppmärksamt, som om du vore förvånad. Låt barnet känna sig som världens klokaste.', body_vi = 'Bé kể lại cho mẹ bộ phim hoạt hình vừa xem bằng "ngữ pháp" của riêng mình, nghiêm túc giải thích ai đi đâu. Hãy chăm chú lắng nghe như thể thật sự ngạc nhiên. Để bé cảm thấy mình là người thông minh nhất thế giới.', body_zh = '用自己的语法给你讲正在看的动画片，一本正经地解释谁去了哪里。认真地、带着惊讶的样子听宝宝讲吧。让宝宝觉得自己是世界上最聪明的人。' WHERE id = '2fc82c8d-f425-4306-866a-3f621177b592' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy nada ha salido según lo previsto? No te culpes. Eres una madre real, no una ilusión con filtro de las redes sociales. Tu peque solo necesita tu sonrisa y tus abrazos.', body_fr = 'Rien ne s''est passé comme prévu aujourd''hui ? Ne vous culpabilisez pas. Vous êtes une vraie maman, pas une illusion filtrée des réseaux sociaux. Votre enfant a juste besoin de votre sourire et de vos bras.', body_hi = 'आज कुछ भी प्लान के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। आप एक असली माँ हैं, सोशल मीडिया का फ़िल्टर किया हुआ भ्रम नहीं। बच्चे को बस आपकी मुस्कान और गोद की ज़रूरत है।', body_id = 'Hari ini tak ada yang berjalan sesuai rencana? Jangan menyalahkan dirimu. Kamu ibu yang nyata, bukan ilusi berfilter di media sosial. Anakmu hanya butuh senyum dan pelukanmu.', body_ja = '今日は何も計画どおりにいかなかった？自分を責めないで。あなたはリアルなママで、SNSのフィルターがかかった幻ではありません。子どもに必要なのは、あなたの笑顔と抱っこだけです。', body_ko = '오늘 아무것도 계획대로 되지 않았나요? 자책하지 마세요. 엄마는 SNS 속 필터 낀 환상이 아니라 진짜 엄마예요. 아이에게 필요한 건 엄마의 미소와 품뿐이에요.', body_nl = 'Ging vandaag niets volgens plan? Geef jezelf niet de schuld. Je bent een echte mama, geen gefilterde illusie van social media. Je kind heeft alleen je glimlach en je knuffel nodig.', body_pl = 'Dziś nic nie poszło zgodnie z planem? Nie obwiniaj się. Jesteś prawdziwą mamą, a nie przefiltrowaną iluzją z mediów społecznościowych. Dziecko potrzebuje tylko twojego uśmiechu i twoich objęć.', body_pt = 'Hoje nada correu como planeado? Não se culpe. É uma mãe real, não uma ilusão filtrada das redes sociais. A criança só precisa do seu sorriso e do seu colo.', body_sv = 'Gick ingenting enligt planen i dag? Skyll inte på dig själv. Du är en verklig mamma, inte en filtrerad illusion på sociala medier. Barnet behöver bara ditt leende och din famn.', body_vi = 'Hôm nay chẳng có gì diễn ra theo kế hoạch? Đừng tự trách mình. Mẹ là một người mẹ thật, không phải ảo ảnh qua bộ lọc trên mạng xã hội. Bé chỉ cần nụ cười và vòng tay của mẹ thôi.', body_zh = '今天什么都没按计划走？别责怪自己。你是一位真实的妈妈，不是社交网络上加了滤镜的幻象。孩子只需要你的微笑和拥抱。' WHERE id = '63daef22-cfd1-421f-8f7d-267873d17f9e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Se ha despertado en mitad de la noche llorando con los ojos cerrados y no oye a nadie. Confírmalo con el Análisis del llanto; si es un terror nocturno, no intentes despertarle. Quédate a su lado y dale seguridad en silencio.', body_fr = 'Il s''est réveillé en pleine nuit en pleurant, les yeux fermés, sans entendre personne. Vérifiez avec l''Analyse des pleurs : s''il s''agit d''une terreur nocturne, n''essayez pas de le réveiller. Restez simplement près de lui et rassurez-le en silence.', body_hi = 'आधी रात आँखें बंद किए रोते हुए जागा और किसी की नहीं सुनता। क्राइंग एनालिसिस से पुष्टि कीजिए; अगर यह नाइट टेरर है, तो उसे जगाने की कोशिश मत कीजिए। बस पास रहकर चुपचाप भरोसा दीजिए।', body_id = 'Tengah malam ia terbangun menangis dengan mata terpejam dan tidak mendengar siapa pun. Pastikan dengan Analisis Tangisan; jika ini teror tidur (night terror), jangan mencoba membangunkannya. Cukup berada di sampingnya dan beri rasa aman tanpa bersuara.', body_ja = '夜中に目を閉じたまま泣いて起き、誰の声も聞こえていない様子。「泣き声分析」で確かめてみましょう。もし夜驚症なら、起こそうとしないで。ただそばにいて、静かに安心させてあげて。', body_ko = '한밤중에 눈을 감은 채 울며 깨어나 아무 말도 듣지 못하나요? 울음 분석으로 확인해 보세요. 야경증이라면 깨우려 하지 말고 곁에서 조용히 안심시켜 주세요.', body_nl = 'Werd hij midden in de nacht huilend wakker met zijn ogen dicht, en hoort hij niemand? Controleer het met Huilanalyse; als het een nachtmerrie-aanval (pavor nocturnus) is, probeer hem dan niet wakker te maken. Blijf gewoon bij hem en geef hem in stilte vertrouwen.', body_pl = 'W środku nocy obudził się z płaczem, z zamkniętymi oczami, i nikogo nie słyszy? Potwierdź to Analizą płaczu; jeśli to lęk nocny, nie próbuj go budzić. Po prostu bądź obok i w ciszy dawaj mu poczucie bezpieczeństwa.', body_pt = 'Acordou a meio da noite a chorar, de olhos fechados, e não ouve ninguém. Confirme com a Análise do Choro; se for terror noturno, não tente acordá-lo. Fique apenas ao lado dele e dê-lhe segurança em silêncio.', body_sv = 'Mitt i natten har barnet vaknat gråtande med slutna ögon och hör ingen. Kontrollera med Gråtanalys; om det är nattskräck, försök inte väcka barnet. Var bara nära och ge trygghet i tystnad.', body_vi = 'Nửa đêm bé thức dậy khóc, mắt vẫn nhắm và không nghe thấy ai? Hãy kiểm tra bằng Phân tích tiếng khóc; nếu đó là hoảng sợ khi ngủ (night terror), đừng cố đánh thức bé. Chỉ cần ở bên cạnh và lặng lẽ mang lại cảm giác an toàn.', body_zh = '半夜闭着眼睛哭着醒来，谁的话都听不进去。用哭声分析确认一下；如果是夜惊，别试图叫醒宝宝。只要静静地陪在身边，给宝宝安全感就好。' WHERE id = 'e3cb9a40-b6ca-4e32-b4da-ab6d4899625b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te repite riéndose esa palabrota que ha oído por ahí y espera tu reacción? Tu mejor arma es no reaccionar. No te rías ni te enfades, simplemente ignóralo. Pronto olvidará esa palabra.', body_fr = 'Il vous répète en riant un gros mot entendu on ne sait où et attend votre réaction ? Votre meilleure arme, c''est l''absence de réaction. Ne riez pas, ne vous fâchez pas, ignorez simplement. Il oubliera vite ce mot.', body_hi = 'कहीं से सुना वह बुरा शब्द हँसते हुए आपके सामने दोहराता है और आपकी प्रतिक्रिया का इंतज़ार करता है? आपका सबसे बड़ा हथियार है कोई प्रतिक्रिया न देना। हँसिए मत, नाराज़ मत होइए, बस अनदेखा कीजिए। वह जल्द ही वह शब्द भूल जाएगा।', body_id = 'Ia mengulang kata kasar yang entah didengar dari mana sambil tertawa, lalu menunggu reaksi Anda? Senjata terbesar Anda adalah tidak bereaksi. Jangan tertawa, jangan marah, cukup abaikan. Ia akan segera melupakan kata itu.', body_ja = 'どこかで聞いた悪い言葉を、笑いながらくり返してあなたの反応を待っている？いちばんの武器は、反応しないこと。笑わず、怒らず、ただ聞き流しましょう。その言葉はすぐに忘れます。', body_ko = '어디서 들은 나쁜 말을 웃으며 따라 하고 엄마의 반응을 기다리나요? 가장 강력한 무기는 무반응이에요. 웃지도, 화내지도 말고 그냥 못 들은 척하세요. 곧 그 말을 잊을 거예요.', body_nl = 'Herhaalt hij lachend een lelijk woord dat hij ergens heeft gehoord en wacht hij op je reactie? Je grootste wapen is geen reactie. Lach niet, word niet boos, negeer het gewoon. Hij vergeet het woord snel.', body_pl = 'Ze śmiechem powtarza ci brzydkie słowo, które gdzieś usłyszał, i czeka na twoją reakcję? Twoją największą bronią jest brak reakcji. Nie śmiej się, nie złość, po prostu udawaj, że nie słyszysz. Szybko zapomni to słowo.', body_pt = 'Repete-lhe a rir aquela palavra feia que ouviu algures e espera pela sua reação? A sua maior arma é não reagir. Não se ria, não se irrite, simplesmente ignore. Em breve vai esquecer a palavra.', body_sv = 'Upprepar barnet skrattande ett fult ord det hört någonstans och väntar på din reaktion? Ditt största vapen är att inte reagera. Skratta inte, bli inte arg, låtsas bara inte höra. Barnet glömmer snart ordet.', body_vi = 'Bé cười và nhắc lại với mẹ một từ xấu nghe được ở đâu đó, rồi chờ xem mẹ phản ứng ra sao? Vũ khí lớn nhất của mẹ là không phản ứng. Đừng cười, đừng bực, chỉ cần lờ đi. Bé sẽ sớm quên từ đó thôi.', body_zh = '笑着跟你重复从哪儿听来的脏话，等着看你的反应？你最强大的武器就是不反应。别笑，别生气，假装没听见就好。宝宝很快就会忘掉那个词。' WHERE id = '3860d960-f463-4c1e-873a-4917b9b7c101' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Permiso para una casa desordenada 🌪️', body_es = '¿Estás cansada de recoger los mismos juguetes cada día? ¡Hoy no los recojas! La casa no es un museo, es un lugar lleno de vida. Descansa y céntrate no en el desorden, sino en la alegría de tu peque aprendiendo con libertad.', title_fr = 'Permission de maison en désordre 🌪️', body_fr = 'Fatiguée de ranger les mêmes jouets tous les jours ? Aujourd''hui, ne rangez pas ! La maison n''est pas un musée, c''est un lieu où la vie bouillonne. Concentrez-vous non pas sur le désordre, mais sur la joie de votre enfant qui apprend librement, et reposez-vous.', title_hi = 'बिखरे घर की इजाज़त 🌪️', body_hi = 'रोज़ वही खिलौने समेटते-समेटते थक गई हैं? आज मत समेटिए! घर कोई म्यूज़ियम नहीं, ज़िंदगी से भरी जगह है। बिखराव पर नहीं, बच्चे के आज़ादी से सीखने की खुशी पर ध्यान दीजिए और आराम कीजिए।', title_id = 'Izin untuk rumah berantakan 🌪️', body_id = 'Lelah membereskan mainan yang sama setiap hari? Hari ini jangan dibereskan! Rumah bukan museum, melainkan tempat yang penuh kehidupan. Fokuslah pada kebahagiaan anak Anda belajar dengan bebas, bukan pada kekacauannya, dan beristirahatlah.', title_ja = '散らかった家、OK 🌪️', body_ja = '毎日同じおもちゃを片づけるのに疲れましたか？今日は片づけないで！家は博物館ではなく、暮らしがあふれる場所です。散らかりではなく、お子さんが自由に学ぶ喜びに目を向けて、ひと休みしましょう。', title_ko = '어질러진 집 허가증 🌪️', body_ko = '매일 같은 장난감을 치우는 데 지쳤나요? 오늘은 치우지 마세요! 집은 박물관이 아니라 삶이 살아 숨 쉬는 곳이에요. 어질러진 것 말고 아이가 자유롭게 배우는 기쁨에 집중하며 쉬세요.', title_nl = 'Toestemming voor een rommelig huis 🌪️', body_nl = 'Ben je het moe om elke dag hetzelfde speelgoed op te ruimen? Ruim vandaag niet op! Je huis is geen museum, maar een plek vol leven. Focus niet op de rommel, maar op het plezier van je kind dat vrij leert, en ontspan.', title_pl = 'Pozwolenie na bałagan 🌪️', body_pl = 'Masz dość codziennego zbierania tych samych zabawek? Dziś nie sprzątaj! Dom to nie muzeum, tylko miejsce, w którym tętni życie. Skup się nie na bałaganie, a na radości swobodnego uczenia się dziecka, i odpocznij.', title_pt = 'Autorização para a casa desarrumada 🌪️', body_pt = 'Está cansada de arrumar os mesmos brinquedos todos os dias? Hoje não arrume! A casa não é um museu, é um lugar cheio de vida. Concentre-se não na desarrumação, mas na alegria do seu filho a aprender em liberdade, e descanse.', title_sv = 'Tillåtelse till ett stökigt hem 🌪️', body_sv = 'Är du trött på att plocka upp samma leksaker varje dag? Plocka inte upp i dag! Hemmet är inget museum, det är en plats som sjuder av liv. Fokusera inte på stöket utan på barnets glädje i att lära fritt, och vila.', title_vi = 'Giấy phép cho ngôi nhà bừa bộn 🌪️', body_vi = 'Mẹ đã mệt vì ngày nào cũng dọn đúng những món đồ chơi ấy? Hôm nay đừng dọn! Nhà không phải là bảo tàng, mà là nơi cuộc sống sôi động. Hãy nghỉ ngơi, tập trung vào niềm vui được tự do học hỏi của bé chứ không phải sự bừa bộn.', title_zh = '允许家里乱一点 🌪️', body_zh = '每天收拾同样的玩具，收得累坏了？今天就别收了！家不是博物馆，而是充满生活气息的地方。别盯着乱，把注意力放在孩子自由学习的快乐上，好好休息吧。' WHERE id = 'fbd7d1b9-4e13-463d-80fa-fbbd34869d9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Le encanta andar descalzo y tocar la alfombra o las piedras de la habitación. Estimular los nervios de la planta del pie es muy importante para su equilibrio y su motricidad: déjale andar sin calcetines.', body_fr = 'Il adore marcher pieds nus et toucher le tapis ou les cailloux de la pièce. L''éveil des nerfs de la plante des pieds est très important pour son équilibre et sa motricité, laissez-le marcher sans chaussettes.', body_hi = 'नंगे पैर चलने, कालीन या कमरे के पत्थरों को छूने में उसे मज़ा आता है। तलवों की नसों का जागना उसके संतुलन और मोटर स्किल्स के लिए बहुत ज़रूरी है, उसे बिना मोज़ों के चलने दीजिए।', body_id = 'Ia senang berjalan tanpa alas kaki, menyentuh karpet atau batu-batu di kamar. Rangsangan saraf di telapak kaki sangat penting untuk keseimbangan dan motoriknya, izinkan ia berjalan tanpa kaus kaki.', body_ja = 'はだしで歩いて、じゅうたんや部屋の石にふれるのが大好き。足の裏の神経が目覚めることは、バランスと運動能力にとってとても大切です。靴下なしで歩かせてあげましょう。', body_ko = '맨발로 걸으며 카펫이나 방의 돌을 만지는 걸 좋아하나요? 발바닥 신경을 깨우는 건 균형 감각과 운동 능력에 아주 중요해요. 양말 없이 걷게 해 주세요.', body_nl = 'Hij geniet ervan om op blote voeten te lopen en het tapijt of de steentjes in de kamer te voelen. Het prikkelen van de zenuwen onder zijn voeten is heel belangrijk voor zijn evenwicht en motoriek, laat hem zonder sokken lopen.', body_pl = 'Uwielbia chodzić boso, dotykać dywanu albo kamyków na podłodze. Pobudzanie nerwów na stopach jest bardzo ważne dla jego równowagi i motoryki, pozwól mu chodzić bez skarpetek.', body_pt = 'Adora andar descalço e tocar no tapete ou nas pedras do quarto. Estimular os nervos da planta dos pés é muito importante para o equilíbrio e a motricidade: deixe-o andar sem meias.', body_sv = 'Barnet njuter av att gå barfota och känna mattan eller stenarna i rummet under fötterna. När nerverna under fötterna väcks är det väldigt viktigt för balansen och motoriken, låt barnet gå utan strumpor.', body_vi = 'Bé thích đi chân trần, cảm nhận tấm thảm hay những viên sỏi trong phòng. Việc kích thích các dây thần kinh ở lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng và vận động của bé, hãy để bé đi không tất.', body_zh = '喜欢光着脚走路，喜欢触摸地毯或房间里的石头。脚底神经被唤醒，对宝宝的平衡和动作能力非常重要，就让宝宝不穿袜子走吧。' WHERE id = '267500b1-a84b-4046-a247-9d2097325550' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Ahora deja a un lado las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema que no sea el niño ni los gastos. ¡Además de padres, sois una pareja!', body_fr = 'L''enfant dort. Maintenant, mettez de côté les tâches ménagères. Parlez avec votre partenaire au moins 20 minutes de n''importe quel sujet, sauf de l''enfant et des dépenses. Vous êtes aussi un couple !', body_hi = 'बच्चा सो गया। अब घर के काम एक तरफ़ रख दीजिए। अपने साथी के साथ कम से कम 20 मिनट, बच्चे और खर्चों के अलावा किसी भी विषय पर बात कीजिए। आप साथ ही एक जोड़ा भी हैं!', body_id = 'Anak sudah tidur. Sekarang singkirkan pekerjaan rumah. Mengobrollah dengan pasangan minimal 20 menit tentang topik apa saja selain anak dan pengeluaran. Kalian juga sepasang kekasih!', body_ja = '子どもが寝ました。家事はいったん脇に置いて。パートナーと少なくとも20分、子どもやお金以外の話題でおしゃべりしましょう。ふたりはカップルでもあるんです！', body_ko = '아이가 잠들었어요. 이제 집안일은 내려놓으세요. 배우자와 적어도 20분은 아이와 지출 말고 다른 주제로 이야기해 보세요. 두 사람은 부부이기도 하니까요!', body_nl = 'Je kind slaapt. Leg het huishouden nu opzij. Praat minstens 20 minuten met je partner over iets anders dan het kind en de uitgaven. Jullie zijn ook een stel!', body_pl = 'Dziecko śpi. Teraz odłóż obowiązki domowe. Porozmawiaj z partnerem przez co najmniej 20 minut o czymkolwiek poza dzieckiem i wydatkami. Jesteście też parą!', body_pt = 'A criança adormeceu. Agora ponha de lado as tarefas da casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto que não seja a criança nem as despesas. Também são um casal!', body_sv = 'Barnet sover. Lägg nu undan hushållssysslorna. Prata med din partner i minst 20 minuter om vad som helst utom barnet och utgifterna. Ni är samtidigt ett par!', body_vi = 'Bé đã ngủ. Giờ hãy gác việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào, ngoài con cái và chi tiêu. Hai người còn là một cặp đôi nữa!', body_zh = '宝宝睡着了。现在把家务放到一边。和伴侣至少聊20分钟孩子和开销以外的任何话题。你们同时也是一对恋人！' WHERE id = '2b6e6b05-f741-49ca-84e3-fa8deb8b2661' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Siempre se te olvida lo más importante al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que haga falta y que tu pareja lo compre con precisión al volver del trabajo. No canses tu mente.', body_fr = 'Vous oubliez toujours le plus important en allant au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins pour que votre partenaire rapporte tout avec précision en rentrant du travail. Ne fatiguez pas votre cerveau.', body_hi = 'बाज़ार जाते समय सबसे ज़रूरी चीज़ ज़रूर भूल जाती हैं? शॉपिंग लिस्ट ऐप में आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके साथी काम से लौटते समय ठीक-ठीक सामान ले आएँ, आप दिमाग मत थकाइए।', body_id = 'Selalu lupa barang paling penting saat ke supermarket? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan Anda membelinya dengan tepat sepulang kerja, dan Anda tak perlu membebani otak.', body_ja = '買い物に行くと、必ずいちばん大事なものを忘れる？アプリの「買い物リスト」が待っています。必要なものを書きこんで、パートナーが仕事帰りにきっちり買ってこられるようにしましょう。あなたは頭を休ませて。', body_ko = '마트에 가면 꼭 가장 중요한 걸 잊나요? 앱에서 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요. 머리를 혹사하지 마세요.', body_nl = 'Vergeet je altijd het belangrijkste als je naar de supermarkt gaat? Het Boodschappenlijstje wacht in de app op je. Zet er alles op wat je nodig hebt, zodat je partner het op weg naar huis precies kan meenemen. Zo hoef jij je hoofd niet te vermoeien.', body_pl = 'Idąc do sklepu, zawsze zapominasz o najważniejszej rzeczy? Lista zakupów czeka na ciebie w aplikacji. Zapisuj tam potrzeby, niech partner w drodze z pracy dokładnie wszystko kupi, a ty nie męcz głowy.', body_pt = 'Quando vai ao supermercado, esquece-se sempre da coisa mais importante? A Lista de Compras está à sua espera na app. Registe lá o que faz falta para que o seu companheiro compre tudo certinho ao voltar do trabalho, e não canse a cabeça.', body_sv = 'Glömmer du alltid det allra viktigaste när du går till butiken? Inköpslistan väntar på dig i appen. Skriv upp behoven där, så kan din partner handla exakt rätt på vägen hem från jobbet, och du slipper trötta ut hjärnan.', body_vi = 'Đi siêu thị lần nào cũng quên món quan trọng nhất? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó, để chồng trên đường đi làm về mua đầy đủ, chính xác, còn mẹ khỏi phải nhọc đầu.', body_zh = '去超市总会忘掉最重要的那样东西？购物清单在应用里等着你。把需要的东西记进去，让伴侣下班回家时准确买齐，你就别再费脑子了。' WHERE id = '9d8da9d6-f615-4275-a01c-20687a161090' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Alguien te ha dicho «estás en casa, ¿de qué te cansas?»? Abre ya el Diario de ánimo y vuelca todo tu enfado en la pantalla. Escribir lo que sientes de verdad, en lugar de sonreír a la fuerza, es terapia.', body_fr = 'Quelqu''un vous a dit « Tu es à la maison, de quoi tu es fatiguée ? » ? Ouvrez tout de suite le Journal d''humeur et déversez toute votre colère sur l''écran. Écrire ce que vous ressentez vraiment est une thérapie, bien mieux qu''un sourire forcé.', body_hi = 'किसी ने कहा, ‘घर पर ही तो हो, किस बात की थकान’? तुरंत मूड डायरी खोलिए और अपना सारा गुस्सा उँगलियों से स्क्रीन पर उतार दीजिए। झूठी मुस्कान से बेहतर है अपनी असली भावनाएँ लिखना, यही थेरेपी है।', body_id = 'Ada yang bilang ''Kamu kan di rumah saja, capek dari mana''? Segera buka Buku Harian Suasana Hati dan tumpahkan semua kekesalan Anda ke layar lewat jari Anda. Menuliskan perasaan yang sebenarnya adalah terapi, jauh lebih baik daripada senyum palsu.', body_ja = '「家にいるのに何で疲れるの？」と言われましたか？すぐに「気分日記」を開いて、イライラを全部指で画面にはき出しましょう。作り笑いより、本当の気持ちを書くことがセラピーになります。', body_ko = '누군가 ''집에 있으면서 뭐가 그렇게 피곤해?''라고 했나요? 바로 기분 일기를 열고 쌓인 속상함을 손끝으로 모두 쏟아내세요. 억지 미소보다 진짜 감정을 적는 게 치료예요.', body_nl = 'Zei iemand: ''Je bent toch thuis, waar word je moe van?'' Open meteen je Stemmingsdagboek en tik al je frustratie van je af. Je echte gevoelens opschrijven is therapie, veel beter dan een geforceerde glimlach.', body_pl = 'Ktoś ci powiedział: „Siedzisz w domu, czym się męczysz?”. Od razu otwórz Dziennik nastroju i wyrzuć z siebie całą złość na ekran. Zapisywanie prawdziwych uczuć to terapia, lepsza niż sztuczny uśmiech.', body_pt = 'Alguém lhe disse "estás em casa, cansas-te de quê"? Abra já o Diário de Humor e despeje no ecrã toda a sua irritação. Em vez de sorrir à força, escrever o que sente de verdade é terapia.', body_sv = 'Sa någon ”Du är ju hemma, vad är du trött av”? Öppna Humördagboken direkt och låt all irritation flöda genom fingrarna ut på skärmen. Att skriva ner dina verkliga känslor är terapi, bättre än ett tillgjort leende.', body_vi = 'Có ai đó nói với mẹ: "Ở nhà suốt thì mệt gì chứ"? Hãy mở ngay Nhật ký tâm trạng và trút hết bực bội lên màn hình qua đầu ngón tay. Viết ra cảm xúc thật của mình là một liệu pháp, tốt hơn nhiều so với nụ cười gượng gạo.', body_zh = '有人对你说“你天天在家，有什么好累的”？马上打开心情日记，用手指把所有的火气都倾倒在屏幕上。与其强颜欢笑，不如写下真实的感受，这本身就是一种疗愈。' WHERE id = '2b451101-7b49-4ea1-a25f-f07ea36f7e85' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te explica algo que tú ya sabes con una cara muy seria e inteligente. Está poniendo a prueba sus conocimientos. Aunque te cueste aguantar la risa, escúchale con mucha seriedad y dale la razón.', body_fr = 'Il vient vous expliquer, avec un air très sérieux et savant, quelque chose que vous savez déjà. Il teste ses connaissances. Même si vous avez du mal à ne pas rire, écoutez-le très sérieusement et approuvez ce qu''il dit.', body_hi = 'जो बात आपको पहले से पता है, वही आकर बहुत गंभीर और समझदार चेहरे के साथ आपको समझाता है। वह अपने ज्ञान को परख रहा है। हँसी रोकना मुश्किल हो, फिर भी उसे बहुत गंभीरता से सुनिए और उसकी बात की पुष्टि कीजिए।', body_id = 'Ia datang dan menjelaskan sesuatu yang sudah Anda ketahui dengan wajah sangat serius dan sok pintar. Ia sedang menguji pengetahuannya. Meski susah menahan tawa, dengarkan ia dengan sangat serius dan benarkan pendapatnya.', body_ja = 'あなたがもう知っていることを、とても真剣でかしこそうな顔で説明してくれます。自分の知識を試しているんです。笑いをこらえるのが大変でも、とても真剣に聞いて、その考えを認めてあげましょう。', body_ko = '엄마가 이미 아는 걸 아주 진지하고 똑똑한 표정으로 설명해 주나요? 자기 지식을 시험하는 중이에요. 웃음을 참기 힘들어도 아주 진지하게 듣고 생각을 인정해 주세요.', body_nl = 'Hij legt je met een heel serieus en slim gezicht iets uit wat je allang weet. Hij test zijn kennis. Ook al kun je je lachen amper inhouden, luister heel serieus naar hem en bevestig wat hij zegt.', body_pl = 'Przychodzi i z bardzo poważną, mądrą miną tłumaczy ci coś, co dobrze wiesz. Sprawdza swoją wiedzę. Choć trudno ci powstrzymać śmiech, wysłuchaj go z pełną powagą i przyznaj mu rację.', body_pt = 'Vem explicar-lhe algo que a mãe já sabe, com uma expressão muito séria e inteligente. Está a testar o que sabe. Mesmo que mal consiga conter o riso, ouça-o com toda a seriedade e confirme o que ele diz.', body_sv = 'Barnet kommer och förklarar något du redan vet, med en väldigt allvarlig och klok min. Barnet testar sina kunskaper. Även om du knappt kan hålla dig för skratt, lyssna på största allvar och bekräfta det barnet säger.', body_vi = 'Bé đến giải thích cho mẹ một điều mẹ đã biết, với vẻ mặt cực kỳ nghiêm túc và thông thái. Bé đang kiểm tra kiến thức của mình. Dù phải cố lắm mới nhịn được cười, hãy lắng nghe thật nghiêm túc và công nhận ý kiến của bé.', body_zh = '把你明明知道的事情，一脸严肃又聪明地给你讲解一遍。宝宝在测试自己的知识。就算你快忍不住笑了，也请非常认真地听，并肯定宝宝的想法。' WHERE id = '5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro descansa poco a poco.', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau se reposer peu à peu.', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे आराम पा रहा है।', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan bagaimana otak Anda perlahan beristirahat.', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ休まっていくのを感じてみましょう。', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬는 걸 느껴 보세요.', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam tot rust komt.', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli odpoczywa.', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta o seu cérebro a descansar devagarinho.', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du hur hjärnan sakta vilar.', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần được nghỉ ngơi.', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，感受大脑正在一点点休息下来。' WHERE id = '62a5480b-e62d-48dc-a56f-7c512e104949' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apoyo de papá 🫂', title_fr = 'Le soutien de papa 🫂', title_hi = 'पापा का सहारा 🫂', title_id = 'Dukungan dari Ayah 🫂', title_ja = 'パパからのサポート 🫂', title_ko = '아빠의 든든한 응원 🫂', title_nl = 'Steun van papa 🫂', title_pl = 'Wsparcie od taty 🫂', title_pt = 'O apoio do pai 🫂', title_sv = 'Stöd från pappa 🫂', title_vi = 'Hậu thuẫn từ bố 🫂', title_zh = '来自爸爸的支持 🫂' WHERE id = 'cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baño que impide dormir 🚽', body_es = 'Justo cuando se va a dormir, dice de repente «tengo pis». Le llevas y no hay nada. Es la táctica más fina del arte de retrasar el sueño. No grites: marca un límite claro: «Vamos por última vez y volvemos directos a la cama».', title_fr = 'Les toilettes anti-sommeil 🚽', body_fr = 'Il est sur le point de s''endormir et dit soudain qu''il doit aller aux toilettes. Vous l''emmenez, rien. C''est la tactique la plus subtile de l''art de retarder le sommeil. Ne criez pas, posez une limite claire : « On y va une dernière fois et on retourne directement au lit. »', title_hi = 'नींद रोकने वाला टॉयलेट 🚽', body_hi = 'बस सोने ही वाला है कि अचानक कहता है, ‘मुझे टॉयलेट आई है।’ ले जाती हैं, कुछ नहीं होता। यह नींद टालने की कला की सबसे बारीक चाल है। चिल्लाइए मत, ‘आखिरी बार चल रहे हैं और सीधे बिस्तर पर लौटेंगे’ कहकर साफ़ सीमा खींचिए।', title_id = 'Toilet si penghalang tidur 🚽', body_id = 'Tepat saat akan terlelap, tiba-tiba ia bilang ''Aku mau pipis''. Anda mengantarnya, ternyata tidak ada apa-apa. Ini taktik paling halus dalam seni menunda tidur. Jangan berteriak, tarik batas yang jelas: ''Ini terakhir kali, lalu langsung kembali ke tempat tidur''.', title_ja = '眠りをじゃまするトイレ 🚽', body_ja = 'もう少しで寝つくところで、急に「トイレ行きたい」。連れていっても何も出ない。これは寝る時間を遅らせる技の、いちばん巧妙な作戦です。どならずに「これが最後だよ、そのままベッドに戻ろうね」と、はっきり線を引きましょう。', title_ko = '잠을 방해하는 화장실 🚽', body_ko = '막 잠들려는 순간 갑자기 ''쉬 마려워''라고 하나요? 데려가면 아무것도 없죠. 잠을 미루는 기술의 가장 섬세한 작전이에요. 소리치지 말고 ''이번이 마지막이고 바로 침대로 돌아가는 거야''라고 경계를 분명히 그어 주세요.', title_nl = 'De wc die de slaap tegenhoudt 🚽', body_nl = 'Net als hij in slaap valt, zegt hij ineens: ''Ik moet plassen.'' Je brengt hem, maar er komt niets. Dit is de fijnste tactiek in de kunst van het slapen uitstellen. Ga niet schreeuwen, maar trek een duidelijke grens: ''We gaan nog één keer en dan meteen terug naar bed.''', title_pl = 'Toaleta, która przeszkadza w zasypianiu 🚽', body_pl = 'Już ma zasnąć, a nagle mówi: „Chce mi się siku”. Zanosisz go, a tu nic. To najsubtelniejsza taktyka w sztuce odwlekania snu. Nie krzycz, wyraźnie wyznacz granicę: „Idziemy ostatni raz i od razu wracamy do łóżka”.', title_pt = 'A casa de banho que trava o sono 🚽', body_pt = 'Está quase a adormecer e de repente diz "tenho de fazer xixi". Leva-o e não há nada. É a tática mais subtil da arte de adiar o sono. Não grite: trace um limite claro, "Vamos pela última vez e voltamos direto para a cama".', title_sv = 'Toaletten som stoppar sömnen 🚽', body_sv = 'Precis när barnet ska somna säger det plötsligt ”Jag måste på toa”. Ni går dit, men det kommer ingenting. Det är den finaste taktiken i konsten att skjuta upp sömnen. Skrik inte, dra en tydlig gräns: ”Vi går en sista gång och sedan direkt tillbaka till sängen.”', title_vi = 'Nhà vệ sinh "chặn giấc ngủ" 🚽', body_vi = 'Bé sắp ngủ thì bỗng nói "Con buồn đi vệ sinh". Mẹ đưa đi, nhưng chẳng có gì cả. Đây là chiến thuật tinh vi nhất trong nghệ thuật trì hoãn giấc ngủ. Đừng quát, hãy vạch ranh giới rõ ràng: "Đây là lần cuối, xong mình về thẳng giường nhé".', title_zh = '妨碍睡觉的厕所 🚽', body_zh = '马上就要睡着了，突然说“我要上厕所”。带去了，什么都没有。这是拖延睡觉艺术里最精妙的战术。别吼，清楚地划出边界：“这是最后一次，去完直接回床上。”' WHERE id = '3522ca83-324c-49f9-ba7a-ffdc8c379ba2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El viajero de la cama 🛏️', body_es = 'Empieza la noche en su cama y por la mañana se despierta en la tuya, totalmente atravesado y con los pies en tu cara. Recibe esta ocupación del espacio con una sonrisa. Tu olor cálido es su mayor zona de seguridad.', title_fr = 'Le voyageur du lit 🛏️', body_fr = 'Il commence la nuit dans son lit et se réveille le matin dans le vôtre, allongé en travers, les pieds sur votre visage. Accueillez cette invasion de territoire en riant. Votre odeur chaude est sa plus grande zone de sécurité.', title_hi = 'बिस्तर का यात्री 🛏️', body_hi = 'रात अपने बिस्तर में शुरू करता है, और सुबह आपके बिस्तर में, बिल्कुल आड़ा लेटा, पैर आपके चेहरे पर रखे जागता है। उसके इस कब्ज़े का हँसकर स्वागत कीजिए। आपकी गर्म खुशबू उसका सबसे बड़ा सुरक्षित ठिकाना है।', title_id = 'Penjelajah tempat tidur 🛏️', body_id = 'Ia memulai malam di tempat tidurnya sendiri, tapi paginya bangun di tempat tidur Anda, tidur melintang dengan kaki di wajah Anda. Sambut pendudukan wilayah ini sambil tertawa. Aroma hangat Anda adalah zona aman terbesarnya.', title_ja = 'ベッドの旅人 🛏️', body_ja = '夜は自分のベッドで寝始めたのに、朝にはあなたのベッドで、しかも真横になって、足をあなたの顔にのせて目を覚ます。この陣地取りを笑って受けとめて。あなたのあたたかなにおいが、この子のいちばんの安心ゾーンなんです。', title_ko = '침대 여행가 🛏️', body_ko = '밤에는 자기 침대에서 시작했는데 아침에는 엄마 침대에, 그것도 완전히 가로로 누워 발을 엄마 얼굴에 올린 채 깨나요? 이 영토 점령을 웃으며 맞아 주세요. 엄마의 따뜻한 냄새가 아이에게 가장 큰 안심 구역이에요.', title_nl = 'De bedreiziger 🛏️', body_nl = 'Hij begint de nacht in zijn eigen bed, maar wordt ''s ochtends wakker in het jouwe, dwars over het bed met zijn voeten in je gezicht. Lach om deze bezetting. Jouw warme geur is zijn grootste veilige zone.', title_pl = 'Łóżkowy podróżnik 🛏️', body_pl = 'Zaczyna noc w swoim łóżku, a rano budzi się w twoim, w poprzek, z nogami na twojej twarzy. Przyjmij tę okupację terytorium z uśmiechem. Twój ciepły zapach to jego największa strefa bezpieczeństwa.', title_pt = 'O viajante da cama 🛏️', body_pt = 'Começa a noite na cama dele e acorda de manhã na sua, completamente atravessado e com os pés na sua cara. Receba esta ocupação de território a rir. O seu cheiro quente é a maior zona de segurança dele.', title_sv = 'Sängresenären 🛏️', body_sv = 'Barnet börjar natten i sin egen säng men vaknar på morgonen i din, dessutom liggande helt på tvären med fötterna i ditt ansikte. Möt ockupationen med ett skratt. Din varma doft är barnets största trygghetszon.', title_vi = 'Nhà thám hiểm giường ngủ 🛏️', body_vi = 'Bé bắt đầu đêm trên giường của mình, nhưng sáng ra lại thức dậy trên giường mẹ, nằm ngang hẳn, chân gác lên mặt mẹ. Hãy mỉm cười đón nhận cuộc "chiếm đóng lãnh thổ" này. Mùi hương ấm áp của mẹ là vùng an toàn lớn nhất của bé.', title_zh = '床上的旅行家 🛏️', body_zh = '晚上在自己床上开始睡，早上却在你的床上醒来，还整个横着躺，脚丫子搭在你脸上。笑着迎接这场“领地占领”吧。你温暖的气味，是宝宝最大的安全区。' WHERE id = '676880bc-91f2-426e-9b15-e2ce61b68fc4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de la caja 📦', body_es = '¿Ha dejado a un lado ese juguete caro y con sonidos que le compraste y lleva 1 hora jugando con la caja? El cerebro infantil no prefiere guiones ya hechos, sino objetos vacíos que pueda llenar de imaginación. La caja de cartón es para él una nave espacial: no la toques.', title_fr = 'La magie du carton 📦', body_fr = 'Il a mis de côté le jouet cher et sonore que vous lui avez acheté et joue depuis 1 heure avec le carton du jouet ? Le cerveau d''un enfant n''aime pas les scénarios tout faits, mais les objets vides qu''il peut remplir d''imagination. Pour lui, ce carton est un vaisseau spatial, n''y touchez pas.', title_hi = 'डिब्बे का जादू 📦', body_hi = 'आपका लाया वह महँगा, आवाज़ वाला खिलौना एक तरफ़ फेंककर 1 घंटे से उसके डिब्बे से खेल रहा है? बच्चे का दिमाग बनी-बनाई कहानियाँ नहीं, बल्कि ऐसी खाली चीज़ें पसंद करता है जिनमें वह कल्पना भर सके। गत्ते का डिब्बा उसके लिए अंतरिक्ष यान है, उसे मत छेड़िए।', title_id = 'Keajaiban kardus 📦', body_id = 'Ia mengesampingkan mainan mahal yang berbunyi itu dan sudah satu jam bermain dengan kardusnya? Otak anak tidak menyukai skenario jadi, melainkan benda kosong yang bisa ia isi dengan khayalan. Kardus itu baginya pesawat luar angkasa, jangan disentuh.', title_ja = '箱の魔法 📦', body_ja = 'せっかく買った高くて音の出るおもちゃは放り出して、1時間もおもちゃの箱で遊んでいる？子どもの脳は、できあがったストーリーより、想像を詰めこめる空っぽのものが好きなんです。段ボール箱はこの子にとって宇宙船。そっとしておきましょう。', title_ko = '상자의 마법 📦', body_ko = '비싸고 소리 나는 장난감은 던져 두고 한 시간째 장난감 상자만 가지고 노나요? 아이의 뇌는 정해진 시나리오보다 상상을 담을 수 있는 빈 물건을 좋아해요. 종이 상자는 아이에게 우주선이에요, 건드리지 마세요.', title_nl = 'De magie van de doos 📦', body_nl = 'Heeft hij dat dure speeltje met geluid dat je kocht aan de kant gegooid en speelt hij al een uur met de doos? Een kinderbrein houdt niet van kant-en-klare scenario''s, maar van lege dingen waar hij zijn fantasie in kwijt kan. De kartonnen doos is voor hem een ruimteschip, laat hem.', title_pl = 'Magia pudełka 📦', body_pl = 'Odrzucił na bok drogą, grającą zabawkę, którą mu kupiłaś, i od godziny bawi się pudełkiem po niej? Dziecięcy mózg nie kocha gotowych scenariuszy, tylko puste przedmioty, które może wypełnić wyobraźnią. Kartonowe pudło to dla niego statek kosmiczny, nie ruszaj go.', title_pt = 'A magia da caixa 📦', body_pt = 'Pôs de lado aquele brinquedo caro e cheio de sons que lhe comprou e há 1 hora que brinca com a caixa? O cérebro da criança não gosta de histórias prontas, gosta de objetos vazios onde possa pôr a imaginação. Para ele, a caixa de cartão é uma nave espacial: não lhe toque.', title_sv = 'Kartongens magi 📦', body_sv = 'Har barnet lagt den dyra leksaken med ljud åt sidan och lekt med kartongen den kom i i en timme? Barnets hjärna gillar inte färdiga scenarier, utan tomma saker att fylla med fantasi. Kartongen är ett rymdskepp för barnet, rör den inte.', title_vi = 'Phép màu của chiếc hộp 📦', body_vi = 'Bé gạt món đồ chơi đắt tiền, phát ra đủ âm thanh mẹ mua sang một bên và chơi với chiếc hộp đựng nó suốt 1 tiếng? Não bộ trẻ không thích những kịch bản có sẵn, mà thích những đồ vật trống để thả trí tưởng tượng vào. Chiếc hộp các-tông là tàu vũ trụ của bé, đừng động vào.', title_zh = '纸箱的魔法 📦', body_zh = '把你买的那个又贵又会响的玩具扔到一边，抱着玩具的纸箱玩了1个小时？孩子的大脑喜欢的不是现成的剧本，而是能装进想象的空东西。纸箱对宝宝来说就是一艘宇宙飞船，别碰它。' WHERE id = 'bf74dbb7-0eae-47bc-acea-2beeb831e679' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rebelión veraniega en invierno ❄️', body_es = 'Fuera sopla el viento, pero él insiste en ponerse los pantalones cortos de verano. Explicárselo es perder el tiempo. Abre la herramienta Tiempo y ropa y enséñale el icono del niño bien abrigado en la pantalla. El truco de «mira, el móvil también dice que hoy hay que ponerse pantalón» funciona de maravilla.', title_fr = 'Révolte estivale en plein hiver ❄️', body_fr = 'Dehors, le vent souffle, mais il veut absolument mettre son short d''été. Expliquer, c''est perdre son temps. Ouvrez Météo et tenue et montrez-lui à l''écran l''icône de l''enfant bien couvert. L''astuce « Regarde, même le téléphone dit qu''aujourd''hui on doit mettre un pantalon » marche à merveille.', title_hi = 'सर्दी में गर्मी की बगावत ❄️', body_hi = 'बाहर ठंडी हवा चल रही है, पर वह ज़िद करके गर्मियों के शॉर्ट्स पहनना चाहता है। समझाना समय की बर्बादी है। मौसम और कपड़े टूल खोलकर स्क्रीन पर मोटे कपड़े पहने बच्चे का चिह्न उसे दिखाइए। ‘देखो, फ़ोन भी कह रहा है कि आज पैंट पहननी है’ वाली तरकीब कमाल करती है।', title_id = 'Pemberontakan musim panas di musim dingin ❄️', body_id = 'Di luar angin bertiup, tapi ia bersikeras memakai celana pendek musim panas. Menjelaskan hanya buang waktu. Buka Cuaca dan Pakaian dan tunjukkan simbol anak berpakaian tebal di layar. Trik ''Lihat, ponsel juga bilang hari ini kita harus pakai celana panjang'' sangat ampuh.', title_ja = '冬の夏ファッション反乱 ❄️', body_ja = '外は風が吹いているのに、どうしても夏の短パンをはきたがる。説明するのは時間のむだです。「天気と服装」を開いて、画面の厚着をした子どものマークを見せましょう。「ほら、スマホも今日は長ズボンだって」という作戦がよく効きます。', title_ko = '겨울의 여름 반란 ❄️', body_ko = '밖엔 바람이 부는데 꼭 여름 반바지를 입겠다고 하나요? 설명은 시간 낭비예요. 날씨와 옷차림 도구를 열어 화면 속 따뜻하게 입은 아이 그림을 보여 주세요. ''봐, 휴대폰도 오늘은 긴바지 입어야 한대'' 작전이 아주 잘 통해요.', title_nl = 'Zomeropstand in de winter ❄️', body_nl = 'Buiten waait het, maar hij wil per se zijn zomershort aan. Uitleggen is tijdverspilling. Open de tool Weer en kleding en laat hem het icoontje van het warm aangeklede kind op het scherm zien. Het trucje ''Kijk, de telefoon zegt ook dat we vandaag een lange broek aan moeten'' werkt perfect.', title_pl = 'Letni bunt zimą ❄️', body_pl = 'Na dworze wieje wiatr, a on uparcie chce założyć letnie szorty. Tłumaczenie to strata czasu. Otwórz Pogodę i ubiór i pokaż mu na ekranie ikonkę ciepło ubranego dziecka. Sztuczka „Zobacz, nawet telefon mówi, że dziś musimy założyć spodnie” działa świetnie.', title_pt = 'Revolta de verão no inverno ❄️', body_pt = 'Lá fora está vento, mas ele insiste em vestir os calções de verão. Explicar é perder tempo. Abra a ferramenta Tempo e Roupa e mostre-lhe no ecrã o símbolo da criança bem agasalhada. O truque "Olha, até o telemóvel diz que hoje temos de vestir calças" funciona na perfeição.', title_sv = 'Sommaruppror mitt i vintern ❄️', body_sv = 'Det blåser ute, men barnet vill envist ha sommarshorts. Att förklara är slöseri med tid. Öppna verktyget Väder och kläder och visa barnet symbolen med det varmt klädda barnet på skärmen. Knepet ”Titta, telefonen säger också att vi ska ha byxor i dag” fungerar utmärkt.', title_vi = 'Nổi loạn mùa hè giữa mùa đông ❄️', body_vi = 'Ngoài trời gió thổi, nhưng bé nhất quyết đòi mặc quần đùi mùa hè. Giải thích chỉ mất thời gian. Hãy mở Thời tiết và trang phục và chỉ cho bé hình em bé mặc ấm trên màn hình. Mẹo "Nhìn này, điện thoại cũng bảo hôm nay mình phải mặc quần dài" rất hiệu quả.', title_zh = '冬天里的夏日叛逆 ❄️', body_zh = '外面刮着风，宝宝却坚持要穿夏天的短裤。解释只是浪费时间。打开天气与穿衣工具，给宝宝看屏幕上那个穿得厚厚的小孩图标。“你看，手机也说今天要穿长裤”，这个小妙招特别管用。' WHERE id = '42b797ef-b169-4515-ad62-c08b78bfdaca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mordisco imaginario 🍏', body_es = 'No tiene nada en la mano, pero se te acerca y te ofrece una manzana imaginaria: «Toma, muerde». Los juegos de rol son el lugar más importante donde se forma la personalidad. Muerde ese vacío con muchas ganas, haz «crunch» y confirma que es la manzana más rica del mundo.', title_fr = 'Croquer dans le vide 🍏', body_fr = 'Il n''a rien dans la main, mais s''approche de vous et vous tend une pomme imaginaire : « Tiens, croque ! » Les jeux de rôle sont le lieu le plus important de la formation de la personnalité. Croquez ce vide avec grand appétit et confirmez que c''est la pomme la plus délicieuse du monde.', title_hi = 'काल्पनिक बाइट 🍏', body_hi = 'हाथ में कुछ नहीं है, फिर भी पास आकर ‘लो, काटो’ कहकर एक काल्पनिक सेब बढ़ाता है। रोल-प्ले खेल वह सबसे अहम जगह है जहाँ व्यक्तित्व बनता है। उस खालीपन को बड़े चाव से कुरकुराती आवाज़ के साथ काटिए और मान लीजिए कि यह दुनिया का सबसे स्वादिष्ट सेब है।', title_id = 'Gigitan khayalan 🍏', body_id = 'Tangannya kosong, tapi ia mendekat dan menyodorkan apel khayalan: ''Nih, gigit''. Bermain peran adalah tempat terpenting terbentuknya kepribadian. Gigit udara kosong itu dengan lahap sambil berbunyi ''kres'' dan tegaskan bahwa itu apel paling enak di dunia.', title_ja = '空想のひと口 🍏', body_ja = '手には何も持っていないのに、近づいてきて「はい、かじって」と空想のりんごを差し出す。ごっこ遊びは人格が形づくられるいちばん大切な場です。その空っぽを大きな口でシャリッとかじって、世界でいちばんおいしいりんごだと認めてあげましょう。', title_ko = '상상 속 한 입 🍏', body_ko = '손에 아무것도 없는데 다가와서 ''자, 한 입 먹어'' 하며 상상 속 사과를 내미나요? 역할 놀이는 인격이 만들어지는 가장 중요한 곳이에요. 그 빈 손을 아삭 크게 베어 물고 세상에서 가장 맛있는 사과라고 인정해 주세요.', title_nl = 'Denkbeeldige hapjes 🍏', body_nl = 'Hij heeft niets in zijn hand, maar komt naar je toe en geeft je een denkbeeldige appel: ''Hier, neem een hap.'' Rollenspel is de belangrijkste plek waar zijn persoonlijkheid vorm krijgt. Neem met grote eetlust een knapperige hap uit het niets en bevestig dat het de lekkerste appel ter wereld is.', title_pl = 'Wymyślony gryz 🍏', body_pl = 'Nie ma nic w ręce, ale podchodzi do ciebie i podaje wymyślone jabłko: „Masz, ugryź”. Zabawy w odgrywanie ról to najważniejsze miejsce kształtowania osobowości. Ugryź tę pustkę z wielkim apetytem i chrupnięciem i potwierdź, że to najsmaczniejsze jabłko na świecie.', title_pt = 'Uma dentada imaginária 🍏', body_pt = 'Não tem nada na mão, mas aproxima-se e estende-lhe uma maçã imaginária: "Toma, dá uma dentada". As brincadeiras de faz de conta são o lugar mais importante para formar a personalidade. Dê uma grande dentada nesse vazio, com muito apetite, e confirme que é a maçã mais saborosa do mundo.', title_sv = 'Ett låtsastugg 🍏', body_sv = 'Barnet har ingenting i handen, men kommer fram och räcker dig ett låtsasäpple: ”Här, ta en tugga.” Rollekar är den viktigaste platsen där personligheten formas. Bit i tomrummet med ett krasande ljud och stor aptit och bekräfta att det är världens godaste äpple.', title_vi = 'Cắn táo tưởng tượng 🍏', body_vi = 'Tay chẳng cầm gì, nhưng bé tiến lại gần và đưa mẹ một quả táo tưởng tượng: "Mẹ cắn đi". Trò chơi nhập vai là nơi quan trọng nhất hình thành nhân cách. Hãy cắn "rộp" vào khoảng trống ấy thật ngon lành và khẳng định đó là quả táo ngon nhất thế giới.', title_zh = '想象中的咬一口 🍏', body_zh = '手里什么都没有，却走过来递给你一个想象中的苹果：“给，咬一口。”角色扮演游戏是人格形成最重要的地方。大口“咔嚓”咬一下那团空气，告诉宝宝这是世界上最好吃的苹果。' WHERE id = '74bf7168-d7dc-468c-87a3-562a3bef9f2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El monstruo de la ventana 👻', body_es = 'La sombra de un árbol que se mece fuera entra en la habitación y él se asusta y se refugia detrás de ti. No enciendas la luz. Coge una linterna, apunta a la sombra y convierte el miedo en magia diciendo: «Mira, es solo el árbol bailando».', title_fr = 'Le monstre à la fenêtre 👻', body_fr = 'L''ombre d''un arbre qui se balance dehors tombe dans la chambre, et il se réfugie derrière vous, effrayé. N''allumez pas la lumière. Prenez une lampe de poche, éclairez l''ombre et transformez la peur en magie : « Regarde, c''est juste l''arbre qui danse. »', title_hi = 'खिड़की पर राक्षस 👻', body_hi = 'बाहर हिलते पेड़ की परछाईं कमरे में पड़ती है और वह डरकर आपके पीछे छिप जाता है। कमरे की लाइट मत जलाइए। हाथ में टॉर्च लीजिए, परछाईं पर रोशनी डालिए और ‘देखो, यह तो बस पेड़ का डांस है’ कहकर डर को जादू में बदल दीजिए।', title_id = 'Monster di jendela 👻', body_id = 'Bayangan pohon yang bergoyang di luar jatuh ke kamar, dan ia ketakutan lalu berlindung di belakang Anda. Jangan nyalakan lampu kamar. Ambil senter, sorotkan ke arah bayangan, dan ubah rasa takut menjadi keajaiban dengan berkata ''Lihat, ini cuma pohon yang sedang menari''.', title_ja = '窓の外のおおかみ 👻', body_ja = '外でゆれる木の影が部屋に映って、怖がってあなたの後ろに隠れる。部屋の明かりはつけないで。懐中電灯を手に影を照らし、「ほら、木が踊っているだけだよ」と言って、怖さを魔法に変えましょう。', title_ko = '창문 속 괴물 👻', body_ko = '밖에서 흔들리는 나무 그림자가 방에 비쳐 무서워 엄마 뒤에 숨나요? 방 불을 켜지 마세요. 손전등을 들고 그림자를 비추며 ''봐, 나무가 춤추는 거야''라고 말해 두려움을 마법으로 바꿔 주세요.', title_nl = 'Het monster in het raam 👻', body_nl = 'De schaduw van een wiegende boom buiten valt de kamer in en hij kruipt geschrokken achter je weg. Doe het licht niet aan. Pak een zaklamp, schijn op de schaduw en zeg: ''Kijk, dat is gewoon de boom die danst.'' Zo verander je angst in magie.', title_pl = 'Potwór w oknie 👻', body_pl = 'Cień kołyszącego się za oknem drzewa pada na pokój, a on ze strachu chowa się za tobą. Nie zapalaj światła. Weź latarkę, poświeć na cień i powiedz: „Zobacz, to tylko taniec drzewa”, zamieniając strach w magię.', title_pt = 'O monstro na janela 👻', body_pt = 'A sombra de uma árvore a abanar lá fora entra no quarto e ele assusta-se e esconde-se atrás de si. Não acenda a luz do quarto. Pegue numa lanterna, aponte-a para a sombra e transforme o medo em magia: "Olha, é só a árvore a dançar".', title_sv = 'Monstret i fönstret 👻', body_sv = 'Skuggan av ett träd som gungar ute faller in i rummet, och barnet blir rädd och söker skydd bakom dig. Tänd inte lampan i rummet. Ta en ficklampa, lys mot skuggan och säg ”Titta, det är bara trädet som dansar”, så blir rädslan till magi.', title_vi = 'Quái vật ngoài cửa sổ 👻', body_vi = 'Bóng cây đung đưa ngoài trời đổ vào phòng, bé sợ hãi nép sau lưng mẹ. Đừng bật đèn phòng. Hãy cầm đèn pin, rọi về phía cái bóng và nói: "Nhìn này, chỉ là cái cây đang nhảy múa thôi", biến nỗi sợ thành phép màu.', title_zh = '窗户上的怪兽 👻', body_zh = '外面摇晃的树影映进房间，宝宝吓得躲到你身后。别开房间的灯。拿起手电筒照向影子，说一句“你看，这只是树在跳舞”，把害怕变成魔法。' WHERE id = 'd3d1367f-aa40-489c-9f91-b803403dff09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El maratón del «¡Mírame!» 👀', body_es = '¿Nada más despertarse te ha dicho exactamente 40 veces «Mamá, mírame»? Salta, gira y quiere tu aprobación. Aparta los ojos del móvil, mírale solo 3 minutos con toda tu atención y dile «eres genial». Esa atención sin interrupciones bastará para llenarle.', title_fr = 'Le marathon du « Regarde-moi ! » 👀', body_fr = 'Dès le réveil, il vous a dit 40 fois « Maman, regarde-moi » ? Il saute, tourne sur lui-même et veut votre approbation. Quittez le téléphone des yeux, regardez-le juste 3 minutes avec toute votre attention et dites-lui « Tu es génial ». Cette attention sans interruption suffira à le combler.', title_hi = '‘मुझे देखो!’ की मैराथन 👀', body_hi = 'सुबह उठते ही पूरे 40 बार ‘माँ, मुझे देखो’ कहा? उछलता है, घूमता है और आपकी शाबाशी चाहता है। फ़ोन से नज़र हटाइए, बस 3 मिनट पूरे ध्यान से उसे देखिए और कहिए ‘तुम कमाल हो।’ यह बिना रुकावट ध्यान उसका मन भरने के लिए काफ़ी होगा।', title_id = 'Maraton ''Lihat aku!'' 👀', body_id = 'Sejak bangun pagi ia sudah 40 kali berkata ''Ma, lihat aku''? Ia melompat, berputar, dan ingin Anda mengakuinya. Alihkan mata dari ponsel, tatap ia dengan fokus penuh 3 menit saja, dan katakan ''Kamu hebat''. Perhatian tanpa gangguan ini cukup untuk membuatnya puas.', title_ja = '「見て！」マラソン 👀', body_ja = '起きてすぐ、ちょうど40回も「ママ、見て」と言った？ジャンプしたり、くるくる回ったりして、あなたに認めてほしいんです。スマホから目を離して、3分だけしっかり見つめて「すごいね」と言ってあげて。そのとぎれない注目で、心が満たされます。', title_ko = '''나 좀 봐!'' 마라톤 👀', body_ko = '아침에 일어나자마자 ''엄마, 나 좀 봐''를 40번이나 했나요? 뛰고, 돌고, 엄마의 인정을 원해요. 휴대폰에서 눈을 떼고 딱 3분만 온전히 바라보며 ''정말 멋지다''라고 말해 주세요. 그 온전한 관심이면 충분히 채워질 거예요.', title_nl = 'De ''Kijk naar mij!''-marathon 👀', body_nl = 'Zei hij meteen na het wakker worden precies 40 keer ''Mama, kijk naar mij''? Hij springt, draait rondjes en wil jouw goedkeuring. Kijk weg van je telefoon, kijk hem maar 3 minuten met volle aandacht aan en zeg ''Je bent geweldig''. Die onverdeelde aandacht is genoeg om hem te vullen.', title_pl = 'Maraton „Patrz na mnie!” 👀', body_pl = 'Zaraz po przebudzeniu powiedział równo 40 razy „Mamo, patrz na mnie”? Skacze, kręci się i czeka na twoje uznanie. Oderwij wzrok od telefonu, przez 3 minuty patrz na niego z pełnym skupieniem i powiedz „Jesteś wspaniały”. Ta nieprzerwana uwaga wystarczy, by się nasycił.', title_pt = 'A maratona do "Olha para mim!" 👀', body_pt = 'Mal acordou, disse exatamente 40 vezes "Mãe, olha para mim"? Salta, rodopia e quer a sua aprovação. Tire os olhos do telemóvel, olhe para ele só 3 minutos com toda a atenção e diga "és fantástico". Esta atenção sem interrupções chega para o satisfazer.', title_sv = '”Titta på mig!”-maraton 👀', body_sv = 'Så fort barnet vaknade sa det ”Mamma, titta på mig” precis 40 gånger? Barnet hoppar, snurrar och vill ha din bekräftelse. Ta blicken från telefonen, titta på barnet med full fokus i bara 3 minuter och säg ”du är fantastisk”. Den oavbrutna uppmärksamheten räcker för att barnet ska bli mätt på den.', title_vi = 'Cuộc marathon "Mẹ nhìn con này!" 👀', body_vi = 'Vừa thức dậy, bé đã nói đúng 40 lần "Mẹ ơi, nhìn con này"? Bé nhảy, xoay vòng và chờ mẹ công nhận. Hãy rời mắt khỏi điện thoại, chỉ cần 3 phút nhìn bé thật tập trung và nói "Con tuyệt lắm". Sự chú ý trọn vẹn này đủ để bé thấy thỏa mãn.', title_zh = '“看我！”马拉松 👀', body_zh = '早上一醒来就说了整整40遍“妈妈，看我”？又跳又转，想得到你的肯定。把目光从手机上移开，只要3分钟全神贯注地看着宝宝，说一句“你真了不起”。这份不被打断的关注，就足以让宝宝满足。' WHERE id = '2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El derecho de mamá a la pereza 🍕', body_es = '¿Hoy te dan ganas de gritar por todo? ¿La casa está patas arriba? Olvídate de limpiar y no entres en la cocina. Pide una pizza o algo sencillo. Rompe la ilusión de la madre perfecta: tu salud mental vale mucho más que la comida casera.', title_fr = 'Le droit à la paresse de maman 🍕', body_fr = 'Aujourd''hui, vous avez envie de crier sur tout ? La maison est sens dessus dessous ? Laissez tomber le ménage, n''entrez pas dans la cuisine. Commandez une pizza ou quelque chose de simple. Brisez l''illusion de la maman parfaite : votre santé psychologique vaut bien plus qu''un repas fait maison.', title_hi = 'माँ का आलस का हक 🍕', body_hi = 'आज हर बात पर चिल्लाने का मन है? घर बिखरा पड़ा है? सफ़ाई छोड़िए, रसोई में मत जाइए। बाहर से पिज़्ज़ा या कुछ आसान मँगवा लीजिए। परफ़ेक्ट माँ का भ्रम तोड़िए, आपका मानसिक स्वास्थ्य घर के खाने से कहीं ज़्यादा कीमती है।', title_id = 'Hak Ibu untuk bermalas-malasan 🍕', body_id = 'Hari ini ingin berteriak pada segala hal? Rumah berantakan? Lupakan bersih-bersih, jangan masuk dapur. Pesan pizza atau sesuatu yang mudah. Patahkan ilusi ibu sempurna, kesehatan jiwa Anda jauh lebih berharga daripada masakan rumahan.', title_ja = 'ママのなまける権利 🍕', body_ja = '今日は何にでも叫びたくなる？家はぐちゃぐちゃ？掃除はやめて、キッチンにも立たないで。ピザか手軽なものをデリバリーしましょう。完璧なママという幻想をこわして。あなたの心の健康は、手料理よりずっと大切です。', title_ko = '엄마의 게으를 권리 🍕', body_ko = '오늘 모든 것에 소리치고 싶나요? 집은 엉망인가요? 청소는 잊고 부엌에도 들어가지 마세요. 피자나 간단한 걸 배달시키세요. 완벽한 엄마라는 환상은 깨 버리세요, 엄마의 마음 건강이 집밥보다 훨씬 소중해요.', title_nl = 'Mama''s recht op luiheid 🍕', body_nl = 'Wil je vandaag tegen alles schreeuwen? Is het huis een puinhoop? Laat het schoonmaken zitten en ga de keuken niet in. Bestel een pizza of iets makkelijks. Doorbreek de illusie van de perfecte moeder: je mentale gezondheid is veel meer waard dan zelfgekookt eten.', title_pl = 'Mama ma prawo do lenistwa 🍕', body_pl = 'Dziś chce ci się krzyczeć na wszystko? W domu totalny bałagan? Odpuść sprzątanie, nie wchodź do kuchni. Zamów pizzę albo coś prostego. Rozbij iluzję idealnej mamy, twoje zdrowie psychiczne jest dużo cenniejsze niż domowy obiad.', title_pt = 'O direito da mãe à preguiça 🍕', body_pt = 'Hoje apetece-lhe gritar com tudo? A casa está um caos? Esqueça a limpeza e não entre na cozinha. Encomende uma pizza ou algo simples. Quebre a ilusão da mãe perfeita: a sua saúde psicológica vale muito mais do que comida caseira.', title_sv = 'Mammas rätt att vara lat 🍕', body_sv = 'Vill du skrika åt allt i dag? Är hemmet i kaos? Strunta i städningen och gå inte in i köket. Beställ pizza eller något enkelt. Krossa illusionen om den perfekta mamman, din psykiska hälsa är mycket mer värd än hemlagad mat.', title_vi = 'Quyền được lười của mẹ 🍕', body_vi = 'Hôm nay mẹ muốn hét lên với mọi thứ? Nhà cửa bừa bộn? Kệ việc dọn dẹp, đừng bước vào bếp. Hãy gọi pizza hoặc món gì đó đơn giản. Phá bỏ ảo tưởng về người mẹ hoàn hảo, sức khỏe tinh thần của mẹ quý giá hơn nhiều so với bữa cơm nhà.', title_zh = '妈妈有偷懒的权利 🍕', body_zh = '今天看什么都想吼？家里一团乱？别管打扫了，也别进厨房。点个披萨或者什么简单的外卖。打破“完美妈妈”的幻象，你的心理健康比家常饭重要得多。' WHERE id = '4e536027-0b7a-4ac3-acef-a7ba874bd609' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Coma en pareja 📺', body_es = '¡El peque se ha dormido! Por fin os sentáis en el sofá tú y tu pareja a ver una peli, pero a los 10 minutos los dos estáis dormidos. Esta es vuestra realidad. Esa imagen cansada pero dulce de dormiros apoyados el uno en el otro es el amor mismo.', title_fr = 'Le coma du couple 📺', body_fr = 'L''enfant dort ! Vous vous installez enfin sur le canapé avec votre partenaire pour regarder un film, mais 10 minutes plus tard, vous dormez tous les deux. C''est votre réalité. Cette image fatiguée mais si douce de vous endormir l''un contre l''autre, c''est l''amour lui-même.', title_hi = 'जोड़े की गहरी नींद 📺', body_hi = 'बच्चा सो गया! आखिरकार साथी के साथ फ़िल्म देखने सोफ़े पर बैठे, पर 10 मिनट बाद दोनों सो गए। यही आपकी हकीकत है। एक-दूसरे से टिककर सोने का वह थका, पर प्यारा नज़ारा ही असली प्यार है।', title_id = 'Koma berdua di depan TV 📺', body_id = 'Anak sudah tidur! Akhirnya Anda duduk di sofa bersama pasangan untuk menonton film, tapi 10 menit kemudian kalian berdua tertidur. Inilah kenyataan kalian. Pemandangan lelah namun manis saat tertidur saling bersandar itu adalah cinta itu sendiri.', title_ja = 'ふたりで寝落ち 📺', body_ja = '子どもが寝ました！やっとパートナーと映画を見ようとソファに座ったのに、10分後にはふたりとも寝落ち。これがあなたたちのリアルです。寄りかかり合って眠る、疲れているけれど甘いその光景こそ、愛そのものです。', title_ko = '부부의 소파 기절 📺', body_ko = '아이가 잠들었어요! 드디어 배우자와 영화를 보려고 소파에 앉았는데 10분 만에 둘 다 잠들었나요? 이게 지금의 현실이죠. 서로에게 기대어 잠든 그 지치지만 달콤한 모습이 바로 사랑이에요.', title_nl = 'Bankcoma voor twee 📺', body_nl = 'Je kind slaapt! Eindelijk zitten jullie op de bank voor een film, maar na 10 minuten zijn jullie allebei in slaap gevallen. Dat is jullie realiteit. Dat vermoeide maar lieve beeld van tegen elkaar aan in slaap vallen, dat is liefde.', title_pl = 'Śpiączka we dwoje 📺', body_pl = 'Dziecko śpi! W końcu usiedliście z partnerem na kanapie, żeby obejrzeć film, ale po 10 minutach oboje zasnęliście. Taka jest wasza rzeczywistość. Ten zmęczony, ale słodki widok, gdy śpicie oparci o siebie, to właśnie miłość.', title_pt = 'O coma do casal 📺', body_pt = 'A criança adormeceu! Finalmente sentaram-se no sofá para ver um filme com o seu companheiro, mas 10 minutos depois estavam os dois a dormir. Esta é a vossa realidade. Essa imagem cansada mas doce de adormecerem encostados um ao outro é o próprio amor.', title_sv = 'Parkoma 📺', body_sv = 'Barnet sover! Äntligen satte du dig i soffan med din partner för att se en film, men efter 10 minuter hade ni båda somnat. Det är er verklighet. Den trötta men söta bilden av er som sover lutade mot varandra är kärlek i sig.', title_vi = '"Hôn mê" của hai vợ chồng 📺', body_vi = 'Bé đã ngủ! Cuối cùng hai vợ chồng cũng ngồi xuống sofa xem phim, nhưng 10 phút sau cả hai đều ngủ gật. Đó là thực tế của mẹ. Khung cảnh mệt mỏi mà ngọt ngào khi tựa vào nhau ngủ thiếp đi chính là tình yêu.', title_zh = '夫妻“昏迷” 📺', body_zh = '宝宝睡着了！你和伴侣终于坐到沙发上准备看部电影，可10分钟后你们俩都睡着了。这就是你们的现实。互相依偎着睡着的那副疲惫又甜蜜的画面，本身就是爱。' WHERE id = 'c57f5d91-caec-47eb-964d-abcee011e0e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ser selectivo con la comida no tiene lógica. 🥦', body_es = '¿La sopa que hasta ayer se comía con ganas hoy ni la prueba? Entra en Recetas saludables y descubre cómo esconder las verduras en puré dentro de salsas de pasta de colores. Aprende el arte del camuflaje.', title_fr = 'La sélectivité alimentaire n''a aucune logique. 🥦', body_fr = 'Il refuse aujourd''hui la soupe qu''il mangeait encore hier avec appétit ? Passez aux Recettes saines et découvrez comment cacher les légumes en purée dans des sauces pour pâtes colorées. Apprenez l''art du camouflage.', title_hi = 'खाने के नखरों में कोई तर्क नहीं। 🥦', body_hi = 'कल तक जो सूप मज़े से खाता था, आज उसे मुँह नहीं लगाता? सेहतमंद रेसिपी में जाइए और जानिए कि सब्ज़ियों की प्यूरी बनाकर रंगीन पास्ता सॉस में कैसे छिपाएँ। छिपाने की कला सीखिए।', title_id = 'Pilih-pilih makanan tak ada logikanya 🥦', body_id = 'Sup yang sampai kemarin ia makan dengan lahap, hari ini tak mau ia sentuh? Buka Resep Sehat dan temukan cara menyembunyikan sayur yang dihaluskan ke dalam saus pasta berwarna. Pelajari seni kamuflase.', title_ja = '好き嫌いに理屈はありません。 🥦', body_ja = '昨日までおいしく食べていたスープに、今日はひと口もつけない？「ヘルシーレシピ」で、野菜をピューレにしてカラフルなパスタソースに隠す方法を見つけましょう。カモフラージュの技を身につけて。', title_ko = '편식에는 논리가 없어요. 🥦', body_ko = '어제까지 맛있게 먹던 수프를 오늘은 입에도 대지 않나요? 건강한 레시피로 가서 채소를 퓌레로 만들어 알록달록한 파스타 소스에 숨기는 법을 찾아보세요. 위장술을 배워 보세요.', title_nl = 'Kieskeurig eten heeft geen logica. 🥦', body_nl = 'Wil hij de soep die hij tot gisteren smakelijk at vandaag niet eens proeven? Ga naar Gezonde recepten en ontdek hoe je gepureerde groenten in kleurrijke pastasausjes verstopt. Leer de kunst van het camoufleren.', title_pl = 'W wybrednym jedzeniu nie ma logiki 🥦', body_pl = 'Zupy, którą jeszcze wczoraj jadł ze smakiem, dziś nie chce tknąć? Zajrzyj do Zdrowych przepisów i odkryj, jak ukryć zmiksowane warzywa w kolorowych sosach do makaronu. Naucz się sztuki kamuflażu.', title_pt = 'A seletividade alimentar não tem lógica. 🥦', body_pt = 'Até ontem comia com gosto aquela sopa e hoje nem lhe toca? Vá às Receitas Saudáveis e descubra como esconder os legumes em puré em molhos coloridos para massa. Aprenda a arte da camuflagem.', title_sv = 'Det finns ingen logik i kräsenhet. 🥦', body_sv = 'Soppan som barnet åt med god aptit fram till i går vill det i dag inte röra? Gå till Hälsosamma recept och upptäck hur du kan gömma mosade grönsaker i färgglada pastasåser. Lär dig kamouflagets konst.', title_vi = 'Kén ăn chẳng có logic nào cả. 🥦', body_vi = 'Món súp đến hôm qua bé còn ăn ngon lành, hôm nay lại không chịu đụng đến? Hãy vào Công thức lành mạnh và khám phá cách giấu rau xay nhuyễn vào những món sốt mì ống nhiều màu sắc. Hãy học nghệ thuật "ngụy trang".', title_zh = '挑食没有逻辑可言。🥦', body_zh = '直到昨天还吃得津津有味的汤，今天碰都不碰？去健康食谱里看看，如何把蔬菜打成泥，藏进彩色的意面酱汁里。学学这门“伪装艺术”吧。' WHERE id = '2333a8bc-122b-4087-9603-3c895b2daf77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El reino submarino 🛀', body_es = 'El baño ya no es higiene, es una misión de submarino. Deja que el agua salpique. Ese efecto imán del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'Le royaume sous-marin 🛀', body_fr = 'Le bain n''est plus une question de propreté, c''est une mission en sous-marin. Laissez l''eau éclabousser. L''effet magnétique de l''eau emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'पानी के नीचे का राज्य 🛀', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, पनडुब्बी मिशन है। पानी को चारों ओर छिटकने दीजिए। पानी का वह चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Kerajaan bawah air 🛀', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi misi kapal selam. Biarkan air memercik ke mana-mana. Efek magnet air akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = '海の中の王国 🛀', body_ja = 'お風呂はもうきれいにするためではなく、潜水艦のミッションです。水しぶきが飛んでもいいんです。お湯の磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '물속 왕국 🛀', body_ko = '이제 목욕은 씻는 시간이 아니라 잠수함 미션이에요. 물이 사방으로 튀어도 괜찮아요. 물의 자석 같은 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'Het onderwaterrijk 🛀', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een onderzeebootmissie. Laat het water maar spetteren. Het magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Podwodne królestwo 🛀', body_pl = 'Kąpiel w wannie to już nie mycie, tylko misja łodzi podwodnej. Niech woda chlapie dookoła. Magnetyczny efekt wody zmyje cały uparty, negatywny ładunek, który nagromadził w ciągu dnia, i spłynie z nim do kanalizacji.', title_pt = 'O reino subaquático 🛀', body_pt = 'O banho já não é limpeza, é uma missão de submarino. Deixe a água salpicar à volta. O efeito magnético da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Undervattensriket 🛀', body_sv = 'Badet handlar inte längre om renlighet, det är ett ubåtsuppdrag. Låt vattnet stänka. Vattnets magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Vương quốc dưới nước 🛀', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là nhiệm vụ của tàu ngầm. Cứ để nước bắn tung tóe. Sức hút kỳ diệu của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '水下王国 🛀', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场潜水艇任务。让水花四溅吧。水那种磁力般的效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = '5e903417-88bd-42b5-bb8c-507e12e432bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de silencio digital 🤫', body_es = 'Por fin reina un silencio absoluto en la habitación. No corras a vaciar el lavavajillas. Activa el Medidor de sonido y, mirando cómo bajan los números hasta 0 decibelios, siente cómo se despeja tu cerebro cansado.', title_fr = 'La thérapie numérique du silence 🤫', body_fr = 'Un silence absolu est enfin tombé sur la pièce. Ne vous précipitez pas sur le lave-vaisselle. Activez le Sonomètre et, en regardant les chiffres descendre jusqu''à 0 décibel, sentez votre cerveau fatigué se vider.', title_hi = 'डिजिटल खामोशी थेरेपी 🤫', body_hi = 'आखिरकार कमरे में पूरी खामोशी छा गई। डिशवॉशर खाली करने की जल्दी मत कीजिए। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0 डेसिबल तक गिरते अंक देखते हुए महसूस कीजिए कि आपका थका दिमाग कैसे हल्का हो रहा है।', title_id = 'Terapi hening digital 🤫', body_id = 'Akhirnya keheningan total menyelimuti kamar. Jangan buru-buru membereskan mesin cuci piring. Aktifkan Pengukur Suara dan perhatikan angka di layar turun hingga 0 desibel, rasakan bagaimana otak Anda yang lelah menjadi jernih.', title_ja = 'デジタルな静けさセラピー 🤫', body_ja = 'ついに部屋が完全な静けさに包まれました。食洗機の片づけは急がないで。「サウンドメーター」をオンにして、画面の数字が0デシベルまで下がっていくのを眺めながら、疲れた脳がすっきりしていくのを感じましょう。', title_ko = '디지털 고요 테라피 🤫', body_ko = '방에 드디어 완전한 고요가 내려앉았어요. 식기세척기 정리하러 서두르지 마세요. 소음 측정기를 켜고 화면 속 숫자가 0데시벨까지 내려가는 걸 보며 지친 머리가 맑아지는 걸 느껴 보세요.', title_nl = 'Therapie met digitale stilte 🤫', body_nl = 'Eindelijk is er absolute stilte in de kamer. Haast je niet om de vaatwasser in te ruimen. Zet de Geluidsmeter aan, kijk hoe de getallen op het scherm tot 0 decibel zakken en voel hoe je vermoeide brein leeg wordt.', title_pl = 'Terapia cyfrową ciszą 🤫', body_pl = 'W pokoju wreszcie zapadła absolutna cisza. Nie spiesz się do zmywarki. Włącz Miernik dźwięku i patrząc, jak liczby na ekranie spadają do 0 decybeli, poczuj, jak twój zmęczony mózg się oczyszcza.', title_pt = 'Terapia digital do silêncio 🤫', body_pt = 'Finalmente caiu um silêncio absoluto no quarto. Não se apresse a arrumar a máquina da loiça. Ative o Medidor de Som e, a ver os números no ecrã descerem até aos 0 decibéis, sinta o seu cérebro cansado a limpar-se.', title_sv = 'Digital tystnadsterapi 🤫', body_sv = 'Äntligen har en total tystnad sänkt sig över rummet. Skynda dig inte att tömma diskmaskinen. Aktivera verktyget Ljudmätare och följ siffrorna på skärmen som sjunker ner mot 0 decibel, så känner du hur din trötta hjärna rensas.', title_vi = 'Liệu pháp im lặng số 🤫', body_vi = 'Cuối cùng sự im lặng tuyệt đối cũng bao trùm căn phòng. Đừng vội đi xếp máy rửa bát. Hãy bật Đo âm thanh, nhìn những con số trên màn hình hạ dần về 0 decibel và cảm nhận đầu óc mỏi mệt của mình đang được làm sạch.', title_zh = '数字安静疗法 🤫', body_zh = '房间里终于彻底安静下来了。别急着去收拾洗碗机。打开分贝仪，看着屏幕上的数字一路降到0分贝，感受疲惫的大脑正在一点点被清空。' WHERE id = '185309c1-aba3-48ec-9411-535c92af4024' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El artista que multiplica la basura ✂️', body_es = '¿Rompe en mil trocitos cualquier papel limpio que pilla y los esparce por la habitación? ¡Su motricidad fina está trabajando! No te enfades ni corras a por la escoba. Recoged los trocitos en una caja y jugad a hacer nevar.', title_fr = 'L''artiste des confettis ✂️', body_fr = 'Il déchire chaque feuille propre qui lui tombe sous la main en mille petits morceaux et les éparpille dans la pièce ? Sa motricité fine travaille ! Ne courez pas, énervée, chercher le balai. Rassemblez les morceaux dans une boîte et jouez à faire tomber la neige.', title_hi = 'कचरा बढ़ाने वाला कलाकार ✂️', body_hi = 'हाथ लगा साफ़ कागज़ हज़ार छोटे टुकड़ों में फाड़कर कमरे में बिखेर देता है? उसकी बारीक मोटर स्किल्स काम कर रही हैं! गुस्से में झाड़ू की ओर मत दौड़िए। वे टुकड़े एक डिब्बे में भरिए और बर्फ़ गिराने का खेल खेलिए।', title_id = 'Seniman pembuat sampah ✂️', body_id = 'Ia menyobek kertas bersih yang ia temukan menjadi seribu potongan kecil dan menyebarkannya di kamar? Motorik halusnya sedang bekerja! Jangan kesal lalu lari mengambil sapu. Kumpulkan sobekan itu dalam kotak dan mainkan permainan hujan salju.', title_ja = 'ゴミを増やすアーティスト ✂️', body_ja = '手に入ったきれいな紙を、千もの小さな切れはしにして部屋にばらまいている？指先の力が育っています！怒ってほうきに走らないで。切れはしを箱に集めて、雪を降らせる遊びをしましょう。', title_ko = '쓰레기를 늘리는 예술가 ✂️', body_ko = '손에 잡힌 깨끗한 종이를 천 조각으로 찢어 방에 뿌리나요? 소근육이 일하고 있어요! 화내며 빗자루를 들지 마세요. 종이 조각을 상자에 모아 눈 내리기 놀이를 해 보세요.', title_nl = 'Kunstenaar die rommel maakt ✂️', body_nl = 'Scheurt hij elk schoon papiertje dat hij te pakken krijgt in duizend snippers en strooit hij ze door de kamer? Zijn fijne motoriek is aan het werk! Ren niet geërgerd naar de bezem. Verzamel de snippers in een doos en speel samen dat het sneeuwt.', title_pl = 'Artysta od śmieci ✂️', body_pl = 'Każdą czystą kartkę, która wpadnie mu w ręce, drze na tysiąc kawałeczków i rozsypuje po pokoju? Pracuje motoryka mała! Nie denerwuj się i nie biegnij po miotłę. Zbierzcie skrawki do pudełka i pobawcie się w padający śnieg.', title_pt = 'O artista que multiplica o lixo ✂️', body_pt = 'Rasga em mil pedacinhos qualquer papel limpo que lhe venha parar às mãos e espalha-os pelo quarto? A motricidade fina está a trabalhar! Não se irrite nem corra para a vassoura. Junte os pedacinhos numa caixa e brinquem a fazer nevar.', title_sv = 'Konstnären som skapar mer skräp ✂️', body_sv = 'River barnet varje rent papper det får tag i i tusen små bitar och strör ut dem i rummet? Finmotoriken arbetar! Bli inte arg och spring inte efter kvasten. Samla bitarna i en låda och lek att det snöar.', title_vi = 'Nghệ sĩ "sản xuất" rác ✂️', body_vi = 'Bé xé tờ giấy sạch thành cả nghìn mảnh nhỏ rồi rải khắp phòng? Kỹ năng vận động tinh của bé đang hoạt động! Đừng bực mình chạy đi lấy chổi. Hãy gom những mẩu giấy vụn vào một chiếc hộp và cùng chơi trò "tuyết rơi".', title_zh = '制造垃圾的小艺术家 ✂️', body_zh = '把拿到手的白纸撕成一千片小碎片，撒满整个房间？精细动作正在锻炼！别生气地冲去拿扫帚。把碎纸收进一个盒子里，一起玩“下雪”的游戏吧。' WHERE id = '4794fa88-36bd-4251-a4ea-871854d0d5ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El rival del espejo 🪞', body_es = 'Delante del espejo frunce el ceño y pone caras enfadadas y raras. Está comprobando cómo se ven las emociones en su cara. Observa con curiosidad y sin hacer ruido el ensayo de este pequeño actor de teatro.', title_fr = 'Le rival dans le miroir 🪞', body_fr = 'Devant le miroir, il fronce les sourcils et fait des grimaces fâchées ou bizarres. Il teste à quoi ressemblent les émotions sur son visage. Observez sans bruit, avec curiosité, la répétition de ce petit acteur de théâtre.', title_hi = 'आईने में प्रतिद्वंद्वी 🪞', body_hi = 'आईने के सामने खड़े होकर खुद ही भौंहें चढ़ाता है, गुस्से वाले और अजीब चेहरे बनाता है। वह परख रहा है कि भावनाएँ चेहरे पर कैसी दिखती हैं। बिना आवाज़ किए दूर से इस नन्हे थिएटर कलाकार की रिहर्सल दिलचस्पी से देखिए।', title_id = 'Saingan di cermin 🪞', body_id = 'Ia berdiri di depan cermin, mengerutkan alis dan membuat ekspresi marah dan aneh pada dirinya sendiri. Ia sedang menguji bagaimana emosi terlihat di wajahnya. Saksikan latihan aktor teater mini ini dengan penuh minat dari jauh tanpa bersuara.', title_ja = '鏡の中のライバル 🪞', body_ja = '鏡の前に立って、ひとりで眉をしかめたり、怒った顔やへんな顔をしたりしている。気持ちが顔にどう表れるかを試しているんです。音を立てずに、この小さな舞台俳優の練習を興味深く見守りましょう。', title_ko = '거울 속 라이벌 🪞', body_ko = '거울 앞에 서서 혼자 눈살을 찌푸리고 화난 표정, 이상한 표정을 짓나요? 감정이 얼굴에 어떻게 보이는지 시험하는 중이에요. 옆에서 소리 내지 말고 이 작은 연극배우의 연습을 흥미롭게 지켜보세요.', title_nl = 'De rivaal in de spiegel 🪞', body_nl = 'Hij staat voor de spiegel en fronst zijn wenkbrauwen, trekt boze en rare gezichten. Hij test hoe emoties eruitzien op zijn gezicht. Kijk zonder geluid te maken met interesse naar de repetitie van deze kleine toneelspeler.', title_pl = 'Rywal w lustrze 🪞', body_pl = 'Stoi przed lustrem, marszczy brwi i robi do siebie złe i dziwne miny. Sprawdza, jak emocje wyglądają na jego twarzy. Bezgłośnie, z boku, obserwuj z ciekawością próbę tego miniaturowego aktora teatralnego.', title_pt = 'O rival no espelho 🪞', body_pt = 'Põe-se em frente ao espelho a franzir a testa e a fazer caras zangadas e estranhas para si próprio. Está a testar como as emoções aparecem no rosto. Observe com interesse, à distância e sem fazer barulho, o ensaio deste pequeno ator de teatro.', title_sv = 'Rivalen i spegeln 🪞', body_sv = 'Barnet står framför spegeln och rynkar pannan, gör arga och konstiga miner. Barnet testar hur känslorna syns i ansiktet. Titta nyfiket och tyst från sidan på den lilla teaterskådespelarens repetition.', title_vi = 'Đối thủ trong gương 🪞', body_vi = 'Bé đứng trước gương, tự nhíu mày, làm những biểu cảm giận dữ và kỳ quặc. Bé đang thử xem cảm xúc hiện lên trên khuôn mặt mình ra sao. Hãy lặng lẽ, thích thú theo dõi buổi tập của "diễn viên kịch" tí hon này từ xa.', title_zh = '镜子里的对手 🪞', body_zh = '站在镜子前，对着自己皱眉，做出生气又奇怪的表情。宝宝在测试情绪在脸上是什么样子。在一旁别出声，饶有兴致地欣赏这位迷你剧场演员的排练吧。' WHERE id = 'bcbae78a-e00a-4482-8778-25c54ab9a376' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de soledad 🚪', body_es = 'Estás cansada de un peque que se te sube y se te pega todo el día. Te has metido en el baño, has cerrado la puerta y has estado 5 minutos sola. Abre enseguida el Diario de ánimo, vuelca en la pantalla esa sensación de agobio y siente el alivio.', title_fr = 'Envie de solitude 🚪', body_fr = 'Vous êtes épuisée par cet enfant qui vous a grimpé dessus et collée toute la journée. Vous vous êtes enfermée aux toilettes et vous avez eu 5 minutes rien qu''à vous. Ouvrez tout de suite le Journal d''humeur, déversez à l''écran ce sentiment d''étouffement et soufflez.', title_hi = 'अकेलेपन की चाह 🚪', body_hi = 'दिनभर आपके शरीर पर चढ़ने, चिपके रहने वाले बच्चे से आप थक चुकी हैं। बाथरूम में जाकर दरवाज़ा बंद किया और 5 मिनट अकेली रहीं। तुरंत मूड डायरी खोलिए और अंदर की घुटन स्क्रीन पर उतारकर हल्की हो जाइए।', title_id = 'Rindu menyendiri 🚪', body_id = 'Anda lelah dengan anak yang seharian memanjat dan menempel di tubuh Anda. Anda masuk toilet, mengunci pintu, dan menyendiri 5 menit. Segera buka Buku Harian Suasana Hati, tumpahkan rasa sesak itu ke layar, dan rasakan lega.', title_ja = 'ひとりになりたい 🚪', body_ja = '一日じゅう体によじのぼって、くっついてくる子どもに疲れましたね。トイレに入ってドアを閉め、5分だけひとりになれた。すぐに「気分日記」を開いて、心の中の息苦しさを画面にはき出して、すっきりしましょう。', title_ko = '혼자 있고 싶은 마음 🚪', body_ko = '하루 종일 몸에 기어오르고 매달리는 아이에게 지쳤나요? 화장실에 들어가 문을 잠그고 5분 혼자 있게 됐다면, 바로 기분 일기를 열고 마음속 답답함을 화면에 쏟아내며 숨을 돌리세요.', title_nl = 'Verlangen naar alleen zijn 🚪', body_nl = 'Ben je moe van een kind dat de hele dag op je klimt en aan je hangt? Je ging naar de wc, deed de deur op slot en was 5 minuten alleen. Open meteen je Stemmingsdagboek, gooi dat benauwde gevoel eruit op het scherm en kom tot rust.', title_pl = 'Tęsknota za samotnością 🚪', body_pl = 'Masz dość dziecka, które cały dzień się na ciebie wspina i do ciebie klei. Weszłaś do toalety, zamknęłaś drzwi i przez 5 minut byłaś sama. Od razu otwórz Dziennik nastroju, wyrzuć na ekran to uczucie przytłoczenia i poczuj ulgę.', title_pt = 'Saudades de estar sozinha 🚪', body_pt = 'Está cansada da criança que lhe trepa e se agarra ao corpo o dia todo. Entrou na casa de banho, fechou a porta e ficou 5 minutos sozinha. Abra já o Diário de Humor, despeje no ecrã aquela sensação de sufoco e alivie-se.', title_sv = 'Längtan efter ensamhet 🚪', body_sv = 'Du är trött på barnet som klättrar på och klänger på dig hela dagen. Du gick in på toaletten, låste dörren och fick vara ensam i 5 minuter. Öppna Humördagboken direkt, häll ut den kvävda känslan på skärmen och slappna av.', title_vi = 'Khao khát được ở một mình 🚪', body_vi = 'Mẹ đã mệt vì bé cả ngày trèo lên người, bám chặt lấy mẹ. Mẹ vào nhà vệ sinh, đóng cửa và được ở một mình 5 phút. Hãy mở ngay Nhật ký tâm trạng, trút hết cảm giác ngột ngạt trong lòng lên màn hình và thả lỏng.', title_zh = '渴望独处 🚪', body_zh = '一整天孩子都往你身上爬、黏着你，你累坏了。走进卫生间关上门，独自待了5分钟。马上打开心情日记，把心里那份憋闷倒在屏幕上，让自己轻松一下。' WHERE id = '9ecbc8da-836b-48fc-a294-6aaa4bafb6f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche tienes la voz cansada. Abre Cuentos inteligentes. Dile a tu peque: «Hoy el héroe eres tú, y de fondo está lloviendo», crea un ambiente sonoro especial, relajante y personalizado, y deja que se rinda al sueño.', body_fr = 'Ce soir, votre voix est fatiguée. Ouvrez les Contes intelligents. Dites à votre enfant « Aujourd''hui, c''est toi le héros, et dehors il pleut » pour créer une ambiance sonore spéciale, apaisante et personnalisée qui l''emmènera vers le sommeil.', body_hi = 'आज शाम आपकी आवाज़ थक गई है। स्मार्ट कहानियाँ खोलिए। बच्चे से कहिए, ‘आज हीरो तुम हो, और पीछे बारिश हो रही है’, और एक खास, सुकून भरा, उसके लिए बना आवाज़ों वाला माहौल रचकर उसे नींद के हवाले कीजिए।', body_id = 'Malam ini suara Anda sudah lelah. Buka Dongeng Pintar. Katakan pada anak Anda ''Hari ini kamu yang jadi tokohnya, dan di luar sedang hujan'', ciptakan suasana suara yang istimewa, menenangkan, dan personal, lalu biarkan ia larut dalam tidur.', body_ja = '今夜は声が疲れていますね。「スマートおはなし」を開きましょう。「今日の主人公はあなた、外では雨が降っているよ」と伝えて、特別で心落ち着く、この子だけの音の世界をつくって、眠りへと導いてあげて。', body_ko = '오늘 저녁엔 목이 지쳤나요? 스마트 동화를 열어 보세요. ''오늘은 네가 주인공이고, 배경엔 비가 내려''라고 말해 주며 특별하고 차분한 나만의 소리 환경을 만들어 잠들게 해 주세요.', body_nl = 'Je stem is vanavond moe. Open Slimme sprookjes. Zeg tegen je kind: ''Vandaag ben jij de held en op de achtergrond regent het'', en maak zo een speciale, rustgevende en persoonlijke geluidssfeer waarin hij in slaap valt.', body_pl = 'Dziś wieczorem twój głos jest zmęczony. Otwórz Mądre bajki. Powiedz dziecku: „Dziś bohaterem jesteś ty, a w tle pada deszcz”, stwórz wyjątkowe, kojące i spersonalizowane tło dźwiękowe i oddaj go w objęcia snu.', body_pt = 'Esta noite a sua voz está cansada. Abra as Histórias Inteligentes. Diga ao seu filho "Hoje o herói és tu, e lá fora está a chover", crie um ambiente sonoro especial, calmante e personalizado, e entregue-o ao sono.', body_sv = 'Din röst är trött i kväll. Öppna Smarta sagor. Säg till barnet ”I dag är det du som är hjälten, och i bakgrunden regnar det”, skapa en särskild, lugnande och personlig ljudmiljö och låt barnet ge sig åt sömnen.', body_vi = 'Tối nay giọng mẹ đã mỏi. Hãy mở Truyện cổ tích thông minh. Nói với bé: "Hôm nay con là nhân vật chính, và ngoài kia trời đang mưa", tạo ra một không gian âm thanh đặc biệt, êm dịu và riêng cho bé để đưa bé vào giấc ngủ.', body_zh = '今晚你的嗓子累了。打开智慧童话。对宝宝说“今天你来当英雄，外面还下着雨”，营造一个专属的、安神的个性化声音氛围，让宝宝安然入睡。' WHERE id = 'acb8e717-26b4-427c-9df9-4c6aeb16734c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El primer chiste sin lógica 🤡', body_es = 'Dice «¡El perro se subió al coche y explotó!» y se parte de risa él solo. No tiene ningún sentido, pero está descubriendo el sentido del humor. No busques lógica: únete tú también en voz alta a sus carcajadas puras y alegres.', title_fr = 'La première blague absurde 🤡', body_fr = '« Le chien est monté dans la voiture, elle a explosé ! » dit-il avant d''éclater de rire tout seul. Ça n''a aucun sens, mais il découvre la notion d''humour. Ne cherchez pas de logique, joignez-vous à voix haute à son rire pur et joyeux.', title_hi = 'पहला बेतुका मज़ाक 🤡', body_hi = '‘कुत्ता गाड़ी में बैठा, फट गया!’ कहकर खुद ही ठहाके लगाकर हँसता है। कोई मतलब नहीं, पर वह हास्य की समझ अभी-अभी खोज रहा है। तर्क मत ढूँढिए, उसकी इस मासूम, खुशनुमा हँसी में आप भी ज़ोर से शामिल हो जाइए।', title_id = 'Lelucon tanpa logika pertamanya 🤡', body_id = '''Anjingnya naik mobil, terus meledak!'' katanya sambil tertawa terbahak-bahak sendiri. Tak ada maknanya, tapi ia baru saja menemukan rasa humor. Jangan mencari logika, ikutlah tertawa keras bersama tawanya yang murni dan riang.', title_ja = '初めての、理屈のないジョーク 🤡', body_ja = '「犬が車に乗って、ばくはつした！」と言って、自分で大笑い。意味はないけれど、ユーモアのセンスを発見したばかりなんです。理屈は考えずに、この純粋で楽しい笑い声に、あなたも大きな声で加わりましょう。', title_ko = '첫 엉뚱한 농담 🤡', body_ko = '''강아지가 차를 탔는데 펑 터졌어!'' 하고 혼자 깔깔 웃나요? 아무 의미 없지만 유머 감각을 막 발견하는 중이에요. 논리를 찾지 말고 그 순수하고 즐거운 웃음에 엄마도 크게 함께 웃어 주세요.', title_nl = 'De eerste onlogische grap 🤡', body_nl = '''De hond stapte in de auto en ontplofte!'' zegt hij, en hij schatert het uit. Het slaat nergens op, maar hij ontdekt net wat humor is. Zoek geen logica en lach luidkeels mee met zijn pure, vrolijke lach.', title_pl = 'Pierwszy bezsensowny żart 🤡', body_pl = '„Pies wsiadł do samochodu i wybuchł!” mówi i sam zanosi się śmiechem. Nie ma w tym sensu, ale właśnie odkrywa poczucie humoru. Nie szukaj logiki, głośno dołącz do jego czystego, radosnego śmiechu.', title_pt = 'A primeira piada sem lógica 🤡', body_pt = 'Diz "O cão entrou no carro e rebentou!" e desata a rir sozinho. Não faz sentido nenhum, mas está a descobrir o sentido de humor. Não procure lógica: junte-se em voz alta a esta gargalhada pura e alegre.', title_sv = 'Det första ologiska skämtet 🤡', body_sv = '”Hunden körde bil och den sprack!” säger barnet och skrattar högt åt sig själv. Det finns ingen mening, men barnet håller just på att upptäcka humor. Leta inte efter logik, skratta högt med i det rena, glada skrattet.', title_vi = 'Câu đùa vô lý đầu tiên 🤡', body_vi = '"Con chó lên ô tô, nổ tung luôn!" bé nói rồi tự cười ngặt nghẽo. Chẳng có ý nghĩa gì, nhưng bé đang khám phá khiếu hài hước. Đừng tìm logic, hãy cười thật to cùng tiếng cười trong trẻo, vui tươi của bé.', title_zh = '第一个没逻辑的笑话 🤡', body_zh = '“小狗坐上汽车，砰！炸了！”说完自己哈哈大笑。根本没什么意思，但宝宝刚刚发现了幽默感。别找逻辑，你也跟着宝宝纯真又欢乐的笑声一起大声笑吧。' WHERE id = 'c58d19cd-28c0-452e-ab4b-85c75da1f2b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La política del tobogán 🛝', body_es = 'En el parque se planta en lo alto del tobogán y no deja subir a los demás niños. No te avergüences ni le bajes de un tirón. Sin hacer caso a quien mire, recuérdale con voz suave la norma de los turnos. Así protege su sentido de la propiedad.', title_fr = 'La politique du toboggan 🛝', body_fr = 'Au parc, il se poste en haut du toboggan et empêche les autres enfants de descendre. Ne le tirez pas brusquement vers le bas par gêne. Sans vous soucier des regards, rappelez-lui d''une voix douce la règle du chacun son tour. C''est sa façon de protéger son sentiment de propriété.', title_hi = 'फिसलपट्टी की नीति 🛝', body_hi = 'पार्क में फिसलपट्टी के ऊपर खड़ा होकर दूसरे बच्चों को चढ़ने नहीं देता। शर्मिंदा होकर उसे सख्ती से नीचे मत खींचिए। देखने वालों की परवाह किए बिना उसे नरम आवाज़ में बारी का नियम याद दिलाइए। वह ऐसे ही अपनी चीज़ों के हक की रक्षा करता है।', title_id = 'Politik perosotan 🛝', body_id = 'Di taman, ia berdiri di puncak perosotan dan tidak membiarkan anak lain meluncur. Jangan malu lalu menariknya turun dengan kasar. Tanpa memedulikan orang yang melihat, ingatkan ia tentang aturan bergiliran dengan suara lembut. Begitulah ia menjaga rasa kepemilikannya.', title_ja = 'すべり台の政治 🛝', body_ja = '公園のすべり台のてっぺんに立って、ほかの子をすべらせない。恥ずかしくなって、きつく引きずりおろさないで。まわりの目は気にせず、やさしい声で順番のルールを思い出させてあげましょう。こうやって「自分のもの」という感覚を守っているんです。', title_ko = '미끄럼틀 정책 🛝', body_ko = '공원 미끄럼틀 꼭대기에 서서 다른 아이들이 못 타게 막나요? 창피해서 거칠게 끌어내리지 마세요. 보는 사람은 신경 쓰지 말고 부드러운 목소리로 차례 규칙을 알려 주세요. 이렇게 소유감을 지키는 중이에요.', title_nl = 'Glijbaanpolitiek 🛝', body_nl = 'Hij staat boven op de glijbaan in het park en laat andere kinderen er niet af. Schaam je niet en trek hem er niet hard af. Trek je niets aan van toeschouwers en herinner hem met een zachte stem aan de regel van om de beurt. Zo beschermt hij zijn gevoel van bezit.', title_pl = 'Polityka zjeżdżalni 🛝', body_pl = 'Stoi na szczycie zjeżdżalni w parku i nie pozwala innym dzieciom zjechać. Nie wstydź się i nie ściągaj go ostro na dół. Nie zwracając uwagi na gapiów, łagodnym głosem przypomnij mu zasadę kolejności. W ten sposób chroni swoje poczucie własności.', title_pt = 'A política do escorrega 🛝', body_pt = 'No parque, põe-se no topo do escorrega e não deixa as outras crianças descer. Não fique envergonhada nem o puxe para baixo com brusquidão. Sem ligar a quem está a ver, lembre-lhe com voz suave a regra da vez. É assim que ele protege o sentido de posse.', title_sv = 'Rutschkanepolitik 🛝', body_sv = 'Barnet står högst upp i rutschkanan i parken och släpper inte fram de andra barnen. Skäms inte och dra inte ner barnet hårdhänt. Strunta i åskådarna och påminn barnet med mild röst om turordningsregeln. Så skyddar barnet sin känsla av ägande.', title_vi = 'Chính sách cầu trượt 🛝', body_vi = 'Ở công viên, bé đứng trên đỉnh cầu trượt và không cho các bạn khác trượt. Đừng xấu hổ mà kéo bé xuống thô bạo. Đừng để ý đến người xung quanh, hãy nhẹ nhàng nhắc bé về luật chờ đến lượt. Đó là cách bé bảo vệ cảm giác sở hữu của mình.', title_zh = '滑梯政治 🛝', body_zh = '站在公园的滑梯顶上，不让其他小朋友滑。别因为尴尬就粗暴地把宝宝拉下来。别在意旁人的目光，温柔地提醒宝宝轮流的规矩。宝宝正是这样守护自己的“所有权”。' WHERE id = '0a22f56d-c8f3-477d-a3c0-1cf48a52b75f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ya no es un bebé! 🌟', body_es = 'Es una persona completa, con sus propias decisiones, sus preguntas curiosas y un corazón enorme. Date las gracias por criarle guiando ese carácter tan fuerte sin romperlo. Lo estás haciendo de maravilla.', title_fr = 'Ce n''est plus un bébé ! 🌟', body_fr = 'C''est une vraie personne, avec ses propres décisions, ses questions étonnantes et un cœur immense. Remerciez-vous chaleureusement d''avoir élevé ce caractère fort en le guidant sans le briser. Vous faites un travail formidable.', title_hi = 'वह अब छोटा बच्चा नहीं! 🌟', body_hi = 'वह अपने फ़ैसलों, अजीब सवालों और बड़े दिल वाला पूरा इंसान है। उसके मज़बूत स्वभाव को तोड़े बिना, सही दिशा देकर बड़ा करने के लिए खुद को एक बड़ा शुक्रिया कहिए। आप बहुत अच्छा काम कर रही हैं।', title_id = 'Ia bukan bayi lagi! 🌟', body_id = 'Ia sudah menjadi pribadi utuh dengan keputusannya sendiri, pertanyaan-pertanyaan aneh, dan hati yang besar. Ucapkan terima kasih besar untuk diri Anda karena membesarkan karakternya yang kuat ini dengan mengarahkan, tanpa mematahkannya. Kamu melakukannya dengan sangat baik.', title_ja = 'もう赤ちゃんじゃない！ 🌟', body_ja = '自分の考えと、ふしぎな質問と、大きな心を持った、ひとりの立派な人です。この強い個性を折らずに導きながら育ててきた自分に、大きなありがとうを。あなたは本当によくやっています。', title_ko = '이제 아기가 아니에요! 🌟', body_ko = '자기 결정과 엉뚱한 질문, 커다란 마음을 가진 온전한 한 사람이에요. 이 강한 성격을 꺾지 않고 이끌어 주며 키워 온 나 자신에게 크게 고맙다고 말해 주세요. 정말 잘하고 있어요.', title_nl = 'Hij is geen baby meer! 🌟', body_nl = 'Hij is een compleet mensje met zijn eigen beslissingen, rare vragen en een enorm groot hart. Bedank jezelf flink dat je dit sterke karakter niet breekt, maar bijstuurt terwijl hij opgroeit. Je doet het geweldig.', title_pl = 'To już nie maluszek! 🌟', body_pl = 'To pełny człowiek z własnymi decyzjami, dziwnymi pytaniami i ogromnym sercem. Podziękuj sobie mocno za to, że wychowujesz jego silny charakter, nie łamiąc go, tylko kierując. Świetnie sobie radzisz.', title_pt = 'Já não é um bebé! 🌟', body_pt = 'É uma pessoa completa, com decisões próprias, perguntas estranhas e um coração enorme. Agradeça muito a si própria por educar este caráter forte orientando-o, sem o quebrar. Está a fazer um trabalho excelente.', title_sv = 'Barnet är ingen bebis längre! 🌟', body_sv = 'Barnet är en hel människa med egna beslut, konstiga frågor och ett enormt hjärta. Tacka dig själv ordentligt för att du fostrar den starka personligheten genom att vägleda den utan att knäcka den. Du gör ett fantastiskt jobb.', title_vi = 'Bé không còn là em bé nữa! 🌟', body_vi = 'Bé đã là một con người trọn vẹn với những quyết định riêng, những câu hỏi kỳ lạ và một trái tim to lớn. Hãy tự cảm ơn bản thân thật nhiều vì đã nuôi dạy tính cách mạnh mẽ này bằng cách định hướng chứ không bẻ gãy. Mẹ đang làm rất tuyệt.', title_zh = '宝宝已经不是小婴儿了！🌟', body_zh = '一个有自己主见、有奇怪问题、有一颗大大的心的完整的人。你没有压垮宝宝坚强的性格，而是引导着把宝宝养大，为此好好感谢一下自己吧。你做得非常棒。' WHERE id = '2e61e71c-40b9-4acb-82fb-ac9b3ee6a222' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Victoria sin champán 🥂', body_es = 'Después de un día difícil, sirve en los vasos un simple té caliente. Sentaos frente a frente en el sofá tú y tu pareja y brindad diciendo: «Hoy también hemos sobrevivido a este caos». Sois los comandantes de la casa y también un equipo.', title_fr = 'Victoire sans champagne 🥂', body_fr = 'Après cette journée difficile, versez du simple thé chaud dans des verres. Asseyez-vous face à votre partenaire sur le canapé et trinquez : « On a survécu à ce chaos aujourd''hui aussi ! » Vous êtes à la fois les commandants et l''équipe de cette maison.', title_hi = 'बिना शैंपेन की जीत 🥂', body_hi = 'मुश्किल दिन के बाद गिलासों में सादी गरम चाय डालिए। अपने साथी के साथ सोफ़े पर आमने-सामने बैठिए और ‘आज उस अफ़रा-तफ़री से भी सही-सलामत निकल आए’ कहकर गिलास टकराइए। आप इस घर के सेनापति भी हैं और टीम भी।', title_id = 'Kemenangan tanpa sampanye 🥂', body_id = 'Setelah hari yang berat, tuang teh hangat biasa ke gelas. Duduklah berhadapan dengan pasangan di sofa dan bersulanglah sambil berkata ''Hari ini pun kita selamat dari kekacauan itu''. Kalian adalah panglima sekaligus tim di rumah ini.', title_ja = 'シャンパンなしの祝杯 🥂', body_ja = '大変な一日のあと、コップにふつうの温かいお茶を注ぎましょう。パートナーとソファで向かい合って「今日もあのカオスを無事に乗りきったね」と乾杯を。ふたりはこの家の司令官であり、チームでもあります。', title_ko = '샴페인 없는 승리 🥂', body_ko = '힘든 하루가 끝나면 컵에 평범한 따뜻한 차를 따르세요. 배우자와 소파에 마주 앉아 ''오늘 그 혼돈에서도 살아남았어''라며 건배하세요. 두 사람은 이 집의 사령관이자 한 팀이에요.', title_nl = 'Overwinning zonder champagne 🥂', body_nl = 'Schenk na een zware dag gewone warme thee in. Ga tegenover je partner op de bank zitten en klink: ''Ook die chaos van vandaag hebben we overleefd.'' Jullie zijn de aanvoerders en tegelijk het team van dit huis.', title_pl = 'Zwycięstwo bez szampana 🥂', body_pl = 'Po trudnym dniu nalejcie do szklanek zwykłej gorącej herbaty. Usiądźcie z partnerem na kanapie twarzą w twarz i stuknijcie się szklankami: „Z tego chaosu też dziś wyszliśmy cało”. Jesteście i dowódcami, i drużyną tego domu.', title_pt = 'Vitória sem champanhe 🥂', body_pt = 'Depois de um dia difícil, sirvam simplesmente chá quente nos copos. Sentem-se frente a frente no sofá com o seu companheiro e brindem: "Hoje também sobrevivemos ao caos". São os comandantes desta casa e também uma equipa.', title_sv = 'Seger utan champagne 🥂', body_sv = 'Efter den tuffa dagen, häll upp vanligt varmt te i glasen. Sätt dig mitt emot din partner i soffan och skåla: ”I dag överlevde vi det här kaoset också.” Ni är både hemmets befälhavare och dess lag.', title_vi = 'Chiến thắng không cần sâm panh 🥂', body_vi = 'Sau một ngày vất vả, hãy rót trà nóng bình thường vào cốc. Ngồi đối diện chồng trên sofa và cụng ly: "Hôm nay mình lại sống sót qua mớ hỗn loạn đó rồi!". Hai người vừa là những vị chỉ huy, vừa là một đội của ngôi nhà này.', title_zh = '没有香槟的胜利 🥂', body_zh = '艰难的一天过后，往杯子里倒上普通的热茶。和伴侣面对面坐在沙发上，碰个杯：“今天这场混乱，我们也挺过来了。”你们既是这个家的指挥官，也是一个团队。' WHERE id = 'a5162fa5-e190-42b6-b85c-5309ce76b381' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ritmo de las luces 🌙', body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina solo se libera rápido en un ambiente oscuro y sin tecnología, y te facilita el trabajo.', title_fr = 'Le rythme des lumières 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine n''est sécrétée rapidement que dans le noir et sans écran, ce qui vous facilite la tâche.', title_hi = 'रोशनी की लय 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है और आपका काम आसान करता है।', title_id = 'Irama cahaya 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi, sehingga tugas Anda jadi lebih mudah.', title_ja = '明かりのリズム 🌙', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニンは暗くてデジタル機器のない環境でこそすばやく分泌され、寝かしつけを楽にしてくれます。', title_ko = '불빛의 리듬 🌙', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌은 어둡고 기기가 없는 환경에서만 빠르게 분비되어 엄마의 일을 덜어 줘요.', title_nl = 'Het ritme van het licht 🌙', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt alleen in een donkere omgeving zonder technologie snel aangemaakt, en dat maakt het jou makkelijker.', title_pl = 'Rytm świateł 🌙', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina szybko wydziela się tylko w ciemnym otoczeniu bez technologii, co ułatwia ci zadanie.', title_pt = 'O ritmo das luzes 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia, o que lhe facilita a tarefa.', title_sv = 'Ljusets rytm 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin utsöndras snabbt bara i en mörk och teknikfri miljö och gör det lättare för dig.', title_vi = 'Nhịp điệu của ánh sáng 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ, giúp mẹ nhẹ việc hơn.', title_zh = '灯光的节奏 🌙', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素只有在昏暗、没有电子产品的环境里才会快速分泌，让你轻松不少。' WHERE id = '450f109f-b886-4ee2-8c86-66186d74b732' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desayuno del dinosaurio 🦖', body_es = 'En el desayuno quiere comer como un dinosaurio, sin usar las manos y llevando la boca directamente al plato. ¡No le des una lección de modales! Deja que sea dinosaurio 5 minutos: se aburrirá del juego y cogerá la cuchara de todos modos.', title_fr = 'Le petit-déjeuner du dinosaure 🦖', body_fr = 'Au petit-déjeuner, il veut manger comme un dinosaure, sans les mains, la bouche directement dans l''assiette. Pas de leçon de bonnes manières ! Laissez-le être un dinosaure 5 minutes, il se lassera du jeu et prendra sa cuillère de toute façon.', title_hi = 'डायनासोर का नाश्ता 🦖', body_hi = 'नाश्ते में हाथों का इस्तेमाल किए बिना, मुँह सीधे प्लेट पर ले जाकर डायनासोर की तरह खाना चाहता है। तमीज़ का पाठ मत पढ़ाइए! उसे 5 मिनट डायनासोर रहने दीजिए, वह इस खेल से ऊबकर वैसे भी चम्मच उठा लेगा।', title_id = 'Sarapan dinosaurus 🦖', body_id = 'Saat sarapan ia ingin makan seperti dinosaurus, tanpa tangan, langsung mendekatkan mulut ke piring. Jangan memberi pelajaran sopan santun! Biarkan ia jadi dinosaurus 5 menit, ia akan bosan dengan permainan ini dan mengambil sendok dengan sendirinya.', title_ja = '恐竜の朝ごはん 🦖', body_ja = '朝ごはんで手を使わずに、口を直接お皿に近づけて恐竜のように食べたがる。お行儀の授業は始めないで！5分だけ恐竜にさせてあげましょう。そのうち飽きて、自分からスプーンを持ちますよ。', title_ko = '공룡의 아침 식사 🦖', body_ko = '아침 식사 때 손을 쓰지 않고 입을 접시에 바로 대고 공룡처럼 먹고 싶어 하나요? 예절 수업은 하지 마세요! 5분만 공룡이 되게 두면 놀이에 싫증 나서 어차피 숟가락을 들 거예요.', title_nl = 'Het ontbijt van de dinosaurus 🦖', body_nl = 'Bij het ontbijt wil hij zonder handen eten, met zijn mond direct in het bord, als een dinosaurus. Geef geen les in tafelmanieren! Laat hem 5 minuten een dinosaurus zijn, hij is het spel snel zat en pakt dan vanzelf zijn lepel.', title_pl = 'Śniadanie dinozaura 🦖', body_pl = 'Przy śniadaniu chce jeść jak dinozaur, bez rąk, przykładając buzię prosto do talerza. Nie prowadź wykładu o manierach! Niech przez 5 minut będzie dinozaurem, znudzi mu się ta zabawa i i tak weźmie łyżkę do ręki.', title_pt = 'O pequeno-almoço do dinossauro 🦖', body_pt = 'Ao pequeno-almoço quer comer como um dinossauro, sem usar as mãos, levando a boca diretamente ao prato. Não dê lições de boas maneiras! Deixe-o ser dinossauro 5 minutos: vai fartar-se da brincadeira e pegar na colher de qualquer forma.', title_sv = 'Dinosauriens frukost 🦖', body_sv = 'Vid frukosten vill barnet äta som en dinosaurie, utan händerna och med munnen direkt mot tallriken. Håll ingen lektion i uppfostran! Låt barnet vara dinosaurie i 5 minuter, det tröttnar på leken och tar skeden ändå.', title_vi = 'Bữa sáng của khủng long 🦖', body_vi = 'Bữa sáng, bé muốn ăn như khủng long, không dùng tay mà cúi thẳng miệng xuống đĩa. Đừng giảng bài về phép lịch sự! Hãy để bé làm khủng long 5 phút, bé sẽ chán trò này và tự cầm thìa lên thôi.', title_zh = '恐龙的早餐 🦖', body_zh = '早餐时不用手，直接把嘴凑到盘子上，像恐龙一样吃饭。别急着讲规矩！就让宝宝当5分钟恐龙吧，玩腻了自然会拿起勺子。' WHERE id = 'b4a0c1d1-e187-401c-89d3-83448ef5f879' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La velocidad del «Yo solo» 🐢', body_es = 'Tenéis que salir, pero él se pondrá los zapatos solo sí o sí, y a velocidad de tortuga tarda 15 minutos. Si intervienes, la crisis de llanto durará 30 minutos. Espera centrándote no en el tiempo perdido, sino en su ego sin heridas.', title_fr = 'À mon rythme 🐢', body_fr = 'Vous devez sortir, mais il tient absolument à mettre ses chaussures tout seul, et à cette vitesse de tortue, ça prend 15 minutes. Si vous intervenez, la crise de larmes durera 30 minutes. Ne vous concentrez pas sur l''heure, mais sur son ego à préserver, et attendez.', title_hi = '‘मैं खुद’ की रफ़्तार 🐢', body_hi = 'घर से निकलना है, पर वह जूते खुद ही पहनेगा, और कछुए की इस रफ़्तार में 15 मिनट लगते हैं। बीच में आईं तो रोने का तूफ़ान 30 मिनट चलेगा। समय पर नहीं, उसके बिना ठेस पहुँचे अहं पर ध्यान देकर इंतज़ार कीजिए।', title_id = 'Kecepatan ''aku sendiri'' 🐢', body_id = 'Kalian harus keluar rumah, tapi ia bersikeras memakai sepatunya sendiri dan dengan kecepatan kura-kura itu butuh 15 menit. Jika Anda campur tangan, krisis tangisnya akan berlangsung 30 menit. Fokuslah pada egonya yang tidak terluka, bukan pada waktu, dan tunggulah.', title_ja = '「自分で」のスピード 🐢', body_ja = '出かけなきゃいけないのに、靴は絶対に自分ではくと言って、カメのペースで15分。手を出せば、泣きじゃくりが30分続きます。時間のことより、傷つかない自尊心に目を向けて待ちましょう。', title_ko = '''내가 할래'' 속도 🐢', body_ko = '나가야 하는데 신발을 꼭 자기가 신겠다며 거북이 속도로 15분이나 걸리나요? 끼어들면 울음 폭발이 30분 걸릴 거예요. 늘어지는 시간 말고 상처받지 않을 자존감에 집중하며 기다려 주세요.', title_nl = 'Mijn eigen tempo 🐢', body_nl = 'Jullie moeten de deur uit, maar hij wil per se zelf zijn schoenen aantrekken, en in dat slakkentempo duurt dat 15 minuten. Grijp je in, dan duurt de huilbui 30 minuten. Focus niet op de tijd, maar op zijn ego dat ongeschonden blijft, en wacht.', title_pl = 'Tempo „Ja sam” 🐢', body_pl = 'Musicie wyjść z domu, ale on koniecznie sam założy buty, a w żółwim tempie zajmuje to 15 minut. Jeśli się wtrącisz, kryzys z płaczem potrwa 30 minut. Nie skupiaj się na straconym czasie, tylko na jego nienaruszonym ego, i poczekaj.', title_pt = 'A velocidade do "Eu sozinho" 🐢', body_pt = 'Têm de sair de casa, mas ele quer mesmo calçar os sapatos sozinho e, a esta velocidade de tartaruga, demora 15 minutos. Se intervier, a crise de choro vai durar 30. Concentre-se no ego dele, que não pode sair ferido, e não no relógio: espere.', title_sv = '”Jag själv”-tempot 🐢', body_sv = 'Ni måste gå hemifrån, men barnet ska absolut ta på sig skorna själv, och i sköldpaddstakt tar det 15 minuter. Lägger du dig i blir det en gråtkris på 30 minuter. Fokusera inte på tiden utan på barnets oskadade ego, och vänta.', title_vi = 'Tốc độ "con tự làm" 🐢', body_vi = 'Mẹ cần ra khỏi nhà, nhưng bé nhất định tự đi giày, với tốc độ rùa bò mất 15 phút. Nếu mẹ can thiệp, cơn khóc sẽ kéo dài 30 phút. Đừng tập trung vào thời gian, hãy tập trung giữ cho cái tôi của bé không bị tổn thương và chờ đợi.', title_zh = '“我自己来”的速度 🐢', body_zh = '你们得出门了，可宝宝非要自己穿鞋，以乌龟般的速度要花15分钟。要是你插手，哭闹会持续30分钟。别盯着没定的时间，专注于宝宝那颗不受伤的自我，耐心等一等。' WHERE id = '331d91d4-ea8d-4af5-be08-e82eb1b8836d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las llaves que desaparecen 🔑', body_es = '¿No encuentras las llaves de casa? Mira en la nevera o en el zapatero. Escondiendo cosas comprueba la permanencia de los objetos. En esta cómica búsqueda del tesoro, elige reírte en lugar de enfadarte.', title_fr = 'Les clés disparues 🔑', body_fr = 'Vous ne trouvez plus les clés de la maison ? Regardez dans le frigo ou dans le meuble à chaussures. En cachant les objets, il teste la permanence de l''objet. Dans cette chasse au trésor comique, choisissez de rire plutôt que de vous énerver.', title_hi = 'गायब होती चाबियाँ 🔑', body_hi = 'घर की चाबियाँ नहीं मिल रहीं? फ़्रिज या जूतों की अलमारी में देखिए। चीज़ें छिपाकर वह परख रहा है कि चीज़ें नज़र से हटकर भी मौजूद रहती हैं। इस मज़ेदार खज़ाने की खोज में नाराज़ होने के बजाय हँसना चुनिए।', title_id = 'Kunci yang menghilang 🔑', body_id = 'Tidak bisa menemukan kunci rumah? Coba lihat di kulkas atau rak sepatu. Ia menyembunyikan benda untuk menguji ketetapan objek. Dalam perburuan harta karun yang lucu ini, pilihlah tertawa daripada kesal.', title_ja = '消えたカギ 🔑', body_ja = '家のカギが見つからない？冷蔵庫や靴箱をのぞいてみて。ものを隠しながら、見えなくても存在し続けることを確かめているんです。このおかしな宝探しには、イライラより笑いを選びましょう。', title_ko = '사라진 열쇠 🔑', body_ko = '집 열쇠가 안 보이나요? 냉장고나 신발장을 열어 보세요. 물건을 숨기며 대상 영속성을 시험하는 중이에요. 이 웃긴 보물찾기에서 화내는 대신 웃는 쪽을 택하세요.', title_nl = 'Verdwenen sleutels 🔑', body_nl = 'Kun je je huissleutels niet vinden? Kijk in de koelkast of het schoenenkastje. Door dingen te verstoppen test hij of voorwerpen blijven bestaan. Kies ervoor om te lachen in plaats van boos te worden tijdens deze grappige schattenjacht.', title_pl = 'Zaginione klucze 🔑', body_pl = 'Nie możesz znaleźć kluczy do domu? Zajrzyj do lodówki albo szafki na buty. Chowając rzeczy, sprawdza stałość przedmiotów. W tym zabawnym poszukiwaniu skarbu zamiast się złościć, wybierz śmiech.', title_pt = 'As chaves desaparecidas 🔑', body_pt = 'Não encontra as chaves de casa? Veja no frigorífico ou no sapateiro. Ao esconder as coisas, ele está a testar a permanência dos objetos. Nesta caça ao tesouro cómica, em vez de se irritar, escolha rir.', title_sv = 'Nycklarna som försvann 🔑', body_sv = 'Hittar du inte husnycklarna? Titta i kylskåpet eller i skoskåpet. Barnet testar objektpermanens genom att gömma saker. Välj att skratta istället för att bli arg i den här roliga skattjakten.', title_vi = 'Chùm chìa khóa biến mất 🔑', body_vi = 'Không tìm thấy chìa khóa nhà? Hãy xem trong tủ lạnh hoặc tủ giày. Bé đang thử nghiệm sự tồn tại của đồ vật bằng cách giấu chúng đi. Trong cuộc truy tìm kho báu hài hước này, hãy chọn cười thay vì bực mình.', title_zh = '消失的钥匙 🔑', body_zh = '找不到家里的钥匙？去冰箱或鞋柜里看看。宝宝在藏东西，测试物体恒存的概念。在这场搞笑的寻宝游戏里，选择笑，而不是生气。' WHERE id = 'bd96c118-6b22-4005-829a-5d2036e47887' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hipnosis del susurro 🤫', body_es = 'Tumbado en la cama levanta los pies al aire y no quiere dormirse. En lugar de gritar, baja de golpe el tono y háblale solo en susurros. Cuando el niño se concentra para oírte, su cerebro se hipnotiza automáticamente y pasa al modo sueño.', title_fr = 'L''hypnose du chuchotement 🤫', body_fr = 'Allongé dans son lit, il lève les jambes en l''air et ne veut pas dormir. Au lieu de crier, baissez soudain le ton et ne lui parlez plus qu''en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau entre automatiquement dans une sorte d''hypnose et passe en mode sommeil.', title_hi = 'फुसफुसाहट का सम्मोहन 🤫', body_hi = 'बिस्तर में लेटकर पैर हवा में उठाता है, सोना नहीं चाहता। चिल्लाने के बजाय अचानक आवाज़ धीमी कीजिए, उससे सिर्फ़ फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए पूरा ध्यान लगाता है, तो उसका दिमाग अपने-आप सम्मोहित होकर नींद के मोड में चला जाएगा।', title_id = 'Hipnosis bisikan 🤫', body_id = 'Ia berbaring di tempat tidur sambil mengangkat kaki ke udara dan tidak mau tidur. Daripada berteriak, turunkan nada suara Anda tiba-tiba dan bicaralah dengannya hanya sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis terhipnosis dan beralih ke mode tidur.', title_ja = 'ささやきの催眠術 🤫', body_ja = 'ベッドに寝ころんで足を宙にあげ、眠ろうとしない。どなる代わりに急に声のトーンを落として、ささやき声だけで話しかけてみましょう。あなたの声を聞こうと集中すると、脳は自然と催眠にかかったように眠りモードへ切りかわります。', title_ko = '속삭임의 최면 🤫', body_ko = '침대에 누워 다리를 허공에 들고 잠들기 싫어하나요? 소리치는 대신 갑자기 톤을 낮춰 속삭이듯만 말하세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 최면에 걸린 듯 수면 모드로 바뀔 거예요.', title_nl = 'De hypnose van het fluisteren 🤫', body_nl = 'Hij ligt in bed met zijn benen in de lucht en wil niet slapen. Ga niet schreeuwen, maar ga ineens zachter praten en spreek alleen nog fluisterend tegen hem. Als hij zijn best doet om je te verstaan, raakt zijn brein vanzelf in een soort hypnose en schakelt het over naar de slaapstand.', title_pl = 'Hipnoza szeptu 🤫', body_pl = 'Leży w łóżku z nogami w górze i nie chce zasnąć. Zamiast krzyczeć, nagle ścisz głos i mów do niego wyłącznie szeptem. Gdy dziecko zamieni się w słuch, żeby cię usłyszeć, jego mózg automatycznie wpadnie w hipnozę i przejdzie w tryb snu.', title_pt = 'A hipnose do sussurro 🤫', body_pt = 'Deitado na cama, levanta as pernas no ar e não quer adormecer. Em vez de gritar, baixe de repente o tom de voz e fale com ele só a sussurrar. Quando a criança se concentra para a ouvir, o cérebro fica automaticamente hipnotizado e passa para o modo de sono.', title_sv = 'Viskningens hypnos 🤫', body_sv = 'Barnet ligger i sängen med benen i luften och vill inte somna. Istället för att skrika, sänk plötsligt rösten och prata bara viskande. När barnet lyssnar spänt för att höra dig blir hjärnan automatiskt hypnotiserad och går över i sömnläge.', title_vi = 'Lời thì thầm thôi miên 🤫', body_vi = 'Bé nằm trên giường, giơ chân lên trời và không chịu ngủ. Thay vì quát, hãy bất ngờ hạ giọng và chỉ thì thầm với bé. Khi bé chú ý để nghe mẹ, não bé sẽ tự động như bị thôi miên và chuyển sang chế độ ngủ.', title_zh = '悄悄话的催眠术 🤫', body_zh = '躺在床上把腿翘到半空，就是不想睡。别吼，突然压低声音，只用悄悄话和宝宝说话。宝宝聚精会神想听清你时，大脑会自动被“催眠”，切换到睡眠模式。' WHERE id = 'c22e7a31-d31e-4595-845a-77f2550b33d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descanso para los brazos 🫂', body_es = 'Te duele el cuerpo de que se te suba encima y pida brazos todo el día. Por la tarde, pásale la pelota a papá. Cuando lo sube a caballito y galopa, se cubre su necesidad de atención y tus brazos encuentran el descanso que necesitan.', title_fr = 'Repos pour vos bras 🫂', body_fr = 'À force qu''il vous grimpe dessus et réclame les bras toute la journée, votre corps a mal. Le soir, passez le relais à papa. Quand il le prend sur son dos pour jouer au cheval, l''enfant a l''attention qu''il réclame, et vos bras trouvent le repos dont ils ont besoin.', title_hi = 'बाहों का आराम 🫂', body_hi = 'दिनभर आप पर चढ़ने और गोद माँगने से शरीर दुख रहा है। शाम को ज़िम्मेदारी पापा को सौंप दीजिए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो बच्चे की ध्यान की ज़रूरत भी पूरी होती है और आपकी बाहों को ज़रूरी आराम भी मिलता है।', title_id = 'Istirahat untuk lengan 🫂', body_id = 'Tubuh Anda pegal karena seharian ia memanjat dan minta digendong. Sore hari, oper bolanya ke Ayah. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, kebutuhan perhatian anak terpenuhi dan lengan Anda mendapat istirahat yang dibutuhkan.', title_ja = '腕の休けい 🫂', body_ja = '一日じゅうよじのぼられ、抱っこをせがまれて、体じゅうが痛いですね。夜はバトンをパパに渡しましょう。パパが子どもを背中にのせてお馬さんになれば、子どもは注目してもらえて満足し、あなたの腕は必要な休けいがとれます。', title_ko = '팔의 휴식 🫂', body_ko = '하루 종일 몸에 기어오르고 안아 달라는 통에 온몸이 아픈가요? 저녁엔 아빠에게 공을 넘기세요. 아빠가 아이를 등에 태우고 말처럼 달리면 아이의 관심 욕구도 채워지고, 엄마의 팔도 꼭 필요한 휴식을 얻어요.', title_nl = 'Rust voor je armen 🫂', body_nl = 'Je lichaam doet pijn van een hele dag klimmen en optillen. Speel ''s avonds de bal door naar papa. Als hij je kind op zijn rug neemt en paardje speelt, krijgt je kind de aandacht die hij nodig heeft en krijgen jouw armen de rust die ze nodig hebben.', title_pl = 'Odpoczynek dla rąk 🫂', body_pl = 'Ciało boli cię od całodziennego wspinania się na ciebie i noszenia na rękach. Wieczorem przekaż pałeczkę tacie. Gdy weźmie dziecko na barana i pogalopuje jak koń, potrzeba uwagi dziecka zostanie zaspokojona, a twoje ręce dostaną potrzebny odpoczynek.', title_pt = 'Descanso para os braços 🫂', body_pt = 'O corpo dói-lhe de ele lhe trepar para cima e pedir colo o dia todo. À noite, passe a bola ao pai. Quando ele põe a criança às costas e faz de cavalo a galopar, a necessidade de atenção da criança fica satisfeita e os seus braços têm o descanso de que precisam.', title_sv = 'Vila för armarna 🫂', body_sv = 'Kroppen värker efter att barnet klättrat på dig och velat bli buret hela dagen. På kvällen, skicka bollen till pappa. När han tar barnet på ryggen och leker häst fylls barnets behov av uppmärksamhet, och dina armar får den vila de behöver.', title_vi = 'Cho đôi tay nghỉ ngơi 🫂', body_vi = 'Cả ngày bé trèo lên người, đòi bế khiến cơ thể mẹ đau nhức. Buổi tối, hãy "chuyền bóng" cho bố. Khi bố cõng bé chơi trò cưỡi ngựa, nhu cầu được quan tâm của bé được đáp ứng, còn đôi tay mẹ có được khoảng nghỉ rất cần thiết.', title_zh = '让胳膊休息一下 🫂', body_zh = '一整天宝宝往你身上爬、要抱抱，你浑身酸痛。晚上把“球”传给爸爸。爸爸把宝宝驮在背上“骑大马”，既能满足宝宝对关注的需要，也能让你的胳膊得到需要的休息。' WHERE id = '11c8bab9-c92e-47a2-b7c0-34d8c43e8735' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto matutino 🎤', body_es = 'El sol todavía no ha salido del todo y él salta en la cama cantando a pleno pulmón en un idioma que no entiendes. Sí, tienes sueño, pero esta energía vital que gira por la habitación también te levantará a ti. Simplemente sonríe al oír su voz.', title_fr = 'Le concert du matin 🎤', body_fr = 'Le soleil n''est pas encore tout à fait levé, et lui saute sur le lit en chantant à tue-tête dans une langue que vous ne comprenez pas. Oui, vous avez sommeil, mais cette énergie de vie qui tourbillonne dans la pièce vous remettra aussi sur pied. Souriez simplement à sa voix.', title_hi = 'सुबह का कॉन्सर्ट 🎤', body_hi = 'सूरज अभी पूरा निकला भी नहीं, और वह पलंग पर उछलते हुए ऐसी भाषा में ज़ोर से गा रहा है जो आपको समझ नहीं आती। हाँ, नींद आ रही है, पर कमरे में घूमती यह जीवन ऊर्जा आपको भी उठा देगी। उसकी आवाज़ पर बस मुस्कुराइए।', title_id = 'Konser pagi 🎤', body_id = 'Matahari belum terbit sepenuhnya, tapi ia sudah melompat di kasur sambil bernyanyi keras dengan bahasa yang tidak Anda pahami. Ya, Anda masih mengantuk, tapi energi kehidupan yang berputar di kamar ini akan ikut membangunkan Anda. Tersenyumlah saja mendengar suaranya.', title_ja = '朝のコンサート 🎤', body_ja = 'まだ太陽が昇りきっていないのに、ベッドでジャンプしながら、あなたにはわからない言葉で大声で歌っています。そう、眠いですよね。でも部屋に渦巻くこの生命力が、あなたも起こしてくれます。その声に、ただほほえんで。', title_ko = '아침 콘서트 🎤', body_ko = '해가 다 뜨지도 않았는데 침대에서 뛰며 알아들을 수 없는 말로 크게 노래하나요? 네, 졸리겠지만 방 안을 도는 이 생명력이 엄마도 일으켜 줄 거예요. 그 목소리에 그냥 미소 지어 주세요.', title_nl = 'Ochtendconcert 🎤', body_nl = 'De zon is nog niet helemaal op, en hij springt op bed en zingt luidkeels in een taal die jij niet verstaat. Ja, je bent slaperig, maar die levensenergie die door de kamer wervelt, tilt jou ook op. Glimlach gewoon om zijn stem.', title_pl = 'Poranny koncert 🎤', body_pl = 'Słońce jeszcze w pełni nie wzeszło, a on skacze po łóżku i głośno śpiewa w języku, którego nie rozumiesz. Tak, chce ci się spać, ale ta energia życia krążąca po pokoju postawi na nogi i ciebie. Po prostu uśmiechnij się na dźwięk jego głosu.', title_pt = 'Concerto matinal 🎤', body_pt = 'O sol ainda não nasceu de todo e ele já salta na cama a cantar bem alto numa língua que não entende. Sim, está com sono, mas esta energia de vida que anda pelo quarto também a vai levantar. Limite-se a sorrir à voz dele.', title_sv = 'Morgonkonsert 🎤', body_sv = 'Solen har inte riktigt gått upp än, men barnet hoppar i sängen och sjunger högt på ett språk du inte förstår. Ja, du är sömnig, men livsenergin som snurrar i rummet lyfter dig också. Le bara åt barnets röst.', title_vi = 'Buổi hòa nhạc buổi sáng 🎤', body_vi = 'Mặt trời còn chưa lên hẳn, bé đã nhảy trên giường và hát to bằng một thứ ngôn ngữ mẹ không hiểu. Đúng vậy, mẹ vẫn buồn ngủ, nhưng nguồn năng lượng sống đang lan tỏa khắp phòng này sẽ đánh thức cả mẹ. Hãy mỉm cười với giọng hát của bé.', title_zh = '清晨音乐会 🎤', body_zh = '太阳还没完全升起，宝宝就在床上蹦着，用你听不懂的语言大声唱歌。是的，你还很困，但房间里旋转的这股生命能量也会把你带起来。对着宝宝的歌声笑一笑吧。' WHERE id = '5ddf0bc2-3619-404d-a56d-27e47d73626e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La inteligencia artificial al rescate 🤖', body_es = '«Mamá, ¿adónde se va a dormir el sol?». ¿Te has quedado en blanco ante la pregunta? No compliques la explicación. Hazle la pregunta a Anacan AI indicando la edad de tu peque, recibe una respuesta genial en forma de cuento que un cerebro de 3 años entienda fácilmente y cuéntasela.', title_fr = 'L''intelligence artificielle à la rescousse 🤖', body_fr = '« Maman, où va dormir le soleil ? » Cette question vous a laissée sans voix ? Ne compliquez pas l''explication. Posez la question à Anacan AI en précisant l''âge de votre enfant, obtenez une réponse formidable sous forme d''histoire, facile à comprendre pour un cerveau de 3 ans, et racontez-la-lui.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस बचाने आया 🤖', body_hi = '‘माँ, सूरज सोने कहाँ जाता है?’ इस सवाल पर ठिठक गईं? समझाने को उलझाइए मत। बच्चे की उम्र बताकर Anacan AI से यही सवाल पूछिए, और 3 साल का दिमाग आसानी से समझ सके ऐसा कहानी जैसा शानदार जवाब लेकर उसे सुनाइए।', title_id = 'Penyelamat kecerdasan buatan 🤖', body_id = '''Ma, matahari tidurnya di mana?'' Anda terdiam membeku di depan pertanyaan ini? Jangan memperumit penjelasan. Tanyakan pada Anacan AI dengan menyebutkan usia anak, dapatkan jawaban hebat bergaya cerita yang mudah dipahami otak anak 3 tahun, lalu ceritakan padanya.', title_ja = 'AIが助けてくれる 🤖', body_ja = '「ママ、お日さまはどこへ寝に行くの？」という質問に固まってしまった？説明をむずかしくしないで。Anacan AIに子どもの年齢を入れてこの質問をすれば、3歳の頭でもすっとわかる、お話のようなすてきな答えがもらえます。それを話してあげましょう。', title_ko = '구원 투수 인공지능 🤖', body_ko = '''엄마, 해는 어디로 자러 가?'' 질문 앞에서 얼어붙었나요? 설명을 어렵게 하지 마세요. Anacan AI에게 아이 나이를 적어 이 질문을 하고, 세 살 뇌가 쉽게 이해할 수 있는 이야기 같은 멋진 답을 받아 들려주세요.', title_nl = 'Redder in nood: kunstmatige intelligentie 🤖', body_nl = '''Mama, waar gaat de zon slapen?'' Sta je met je mond vol tanden? Maak de uitleg niet ingewikkeld. Stel deze vraag aan Anacan AI met de leeftijd van je kind erbij, krijg dat prachtige antwoord in verhaalvorm dat een 3-jarig brein makkelijk begrijpt en vertel het hem.', title_pl = 'Sztuczna inteligencja na ratunek 🤖', body_pl = '„Mamo, gdzie słońce idzie spać?” Zamarłaś na to pytanie? Nie komplikuj wyjaśnień. Zadaj to pytanie Anacan AI, podając wiek dziecka, i opowiedz mu wspaniałą odpowiedź w formie historyjki, którą mózg 3-latka łatwo zrozumie.', title_pt = 'A inteligência artificial ao resgate 🤖', body_pt = '"Mãe, para onde vai o sol dormir?" Ficou sem resposta? Não complique a explicação. Faça a pergunta ao Anacan AI indicando a idade da criança, receba aquela resposta fantástica em forma de história, que um cérebro de 3 anos entende facilmente, e conte-lha.', title_sv = 'AI som räddare 🤖', body_sv = '”Mamma, vart går solen och sover?” Blev du helt ställd av frågan? Gör inte förklaringen krånglig. Ställ frågan till Anacan AI och ange barnets ålder, så får du ett fantastiskt svar i sagoform som en 3-årig hjärna lätt förstår, och kan berätta det för barnet.', title_vi = 'Trí tuệ nhân tạo cứu nguy 🤖', body_vi = '"Mẹ ơi, mặt trời đi ngủ ở đâu?" Mẹ đứng hình trước câu hỏi này? Đừng giải thích phức tạp. Hãy hỏi Anacan AI câu này, kèm theo tuổi của bé, để nhận một câu trả lời tuyệt vời như chuyện kể mà não bộ trẻ 3 tuổi dễ hiểu, rồi kể lại cho bé.', title_zh = '人工智能救星 🤖', body_zh = '“妈妈，太阳去哪儿睡觉了？”被问得愣住了？别把解释弄得太复杂。告诉Anacan AI孩子的年龄，问它这个问题，拿到一个3岁小脑袋能轻松听懂的故事式好答案，讲给宝宝听。' WHERE id = 'c7c4ce1e-98e4-4beb-992c-e1f8c9783567' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas silenciosas 💖', body_es = 'Te ha vuelto loca todo el día. Pero ahora duerme en la cama tan inocente que al mirarle te emocionas, ¿verdad? Esa es la mayor paradoja de la maternidad. Esa lágrima que te cae es tu gratitud por tenerle.', title_fr = 'Larmes silencieuses 💖', body_fr = 'Il vous a rendue folle toute la journée. Mais maintenant, il dort si innocemment dans son lit que vous êtes émue en le regardant, n''est-ce pas ? C''est exactement le plus grand paradoxe de la maternité. Cette larme qui coule de vos yeux, c''est votre gratitude pour son existence.', title_hi = 'खामोश आँसू 💖', body_hi = 'उसने दिनभर आपको परेशान किया। पर अब बिस्तर में इतना मासूम सोया है कि देखकर आपका मन भर आता है, है न? माँ बनने का सबसे बड़ा विरोधाभास यही है। आँख से गिरा वह एक आँसू उसके होने के लिए आपका शुक्राना है।', title_id = 'Air mata tanpa suara 💖', body_id = 'Seharian ia membuat Anda hampir gila. Tapi kini ia tidur begitu polos di tempat tidur sampai Anda terharu memandanginya, bukan? Inilah paradoks terbesar menjadi ibu. Setetes air mata yang jatuh itu adalah rasa syukur Anda atas kehadirannya.', title_ja = '声のない涙 💖', body_ja = '一日じゅう振りまわされたのに、ベッドでこんなにあどけなく眠る姿を見ると、胸がいっぱいになりますよね？これこそママであることのいちばん大きなパラドックス。こぼれたひとしずくの涙は、この子がいてくれることへの感謝です。', title_ko = '소리 없는 눈물 💖', body_ko = '하루 종일 엄마를 미치게 했는데, 지금 침대에서 이렇게 순하게 자는 모습을 보면 울컥하죠? 이게 엄마가 된다는 것의 가장 큰 역설이에요. 눈에서 떨어지는 그 한 방울은 아이가 있어 감사하다는 마음이에요.', title_nl = 'Stille tranen 💖', body_nl = 'Hij heeft je de hele dag gek gemaakt. Maar nu ligt hij zo onschuldig in bed te slapen dat je ontroerd raakt als je naar hem kijkt, toch? Dat is de grootste paradox van het moederschap. Die ene traan die over je wang rolt, is je dankbaarheid dat hij er is.', title_pl = 'Ciche łzy 💖', body_pl = 'Cały dzień doprowadzał cię do szału. Ale teraz śpi w łóżku tak niewinnie, że patrząc na niego, się wzruszasz, prawda? To właśnie największy paradoks macierzyństwa. Ta jedna łza, która spływa ci z oka, to twoja wdzięczność za to, że jest.', title_pt = 'Lágrimas silenciosas 💖', body_pt = 'Passou o dia todo a deixá-la louca. Mas agora dorme na cama com um ar tão inocente que se comove ao olhar para ele, não é? É exatamente este o maior paradoxo da maternidade. Aquela lágrima que lhe cai é a sua gratidão por ele existir.', title_sv = 'Tysta tårar 💖', body_sv = 'Barnet har gjort dig galen hela dagen. Men nu ligger det så oskyldigt i sängen att du blir rörd när du tittar, eller hur? Det är moderskapets största paradox. Den enda tår som rinner från ditt öga är din tacksamhet för att barnet finns.', title_vi = 'Những giọt nước mắt lặng lẽ 💖', body_vi = 'Cả ngày bé làm mẹ phát điên. Nhưng giờ nhìn bé ngủ say ngây thơ trên giường, mẹ lại thấy nghẹn ngào, đúng không? Đó chính là nghịch lý lớn nhất của việc làm mẹ. Giọt nước mắt rơi xuống ấy là lời cảm ơn của mẹ vì bé có mặt trên đời.', title_zh = '无声的泪水 💖', body_zh = '宝宝把你折腾了一整天。可现在在床上睡得那么天真，看着看着你就心软了，对吧？这正是当妈妈最大的矛盾。从你眼里落下的那一滴泪，是你对宝宝存在的感恩。' WHERE id = '0daa509c-a73b-47b1-a76d-b85764cf98f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación comida secreta 🥣', body_es = 'El huevo que hasta ayer le encantaba hoy no hay manera de que lo pruebe. No luches contra su voluntad. Usa en Recetas saludables recetas de tentempiés astutos que den a las proteínas formas diferentes, coloridas e interesantes, y gana tú.', title_fr = 'Opération nourriture cachée 🥣', body_fr = 'L''œuf qu''il adorait encore hier, impossible de le lui faire goûter aujourd''hui. Ne luttez pas contre sa volonté. Essayez dans les Recettes saines des collations astucieuses qui donnent aux protéines des formes différentes, colorées et amusantes, et c''est vous qui gagnerez.', title_hi = 'खाना छिपाने का गुप्त ऑपरेशन 🥣', body_hi = 'कल तक जो अंडा पसंद था, आज उसे मुँह तक नहीं लगाता। उसकी इच्छा से मत लड़िए। सेहतमंद रेसिपी में प्रोटीन को अलग, रंगीन और दिलचस्प आकार देने वाली चालाक स्नैक रेसिपी आज़माइए और जीत आपकी हो।', title_id = 'Operasi makanan tersembunyi 🥣', body_id = 'Telur yang sampai kemarin ia suka, hari ini sama sekali tak mau ia makan. Jangan melawan kemauannya. Terapkan resep camilan cerdik di Resep Sehat yang mengubah protein menjadi bentuk berbeda, berwarna, dan menarik, dan jadilah pemenangnya.', title_ja = 'こっそり栄養作戦 🥣', body_ja = '昨日まで大好きだった卵を、今日はひと口も食べない。意志と戦わないで。「ヘルシーレシピ」で、たんぱく質をカラフルで楽しい形に変える工夫おやつのレシピを試して、勝ちをつかみましょう。', title_ko = '비밀 음식 작전 🥣', body_ko = '어제까지 좋아하던 달걀을 오늘은 입에도 대지 않나요? 의지와 싸우지 마세요. 건강한 레시피에서 단백질을 색다르고 알록달록하고 재미있는 모양으로 바꾸는 기발한 간식 레시피를 활용해 승자가 되세요.', title_nl = 'Geheime voedingsoperatie 🥣', body_nl = 'Het ei waar hij tot gisteren dol op was, wil hij vandaag niet eens proeven. Vecht niet tegen zijn wil. Probeer de slimme snackrecepten uit Gezonde recepten die eiwitten in andere, kleurrijke en leuke vormen gieten, en win.', title_pl = 'Tajna operacja jedzeniowa 🥣', body_pl = 'Jajka, które jeszcze wczoraj uwielbiał, dziś nie chce tknąć. Nie walcz z jego wolą. Wypróbuj ze Zdrowych przepisów sprytne przekąski, które nadadzą białku inne, kolorowe i ciekawe kształty, i to ty wygrywasz.', title_pt = 'Operação comida escondida 🥣', body_pt = 'Até ontem adorava ovos e hoje nem os deixa chegar à boca. Não lute contra a vontade dele. Experimente nas Receitas Saudáveis snacks engenhosos que dão às proteínas formas diferentes, coloridas e interessantes, e seja a mãe a ganhar.', title_sv = 'Hemlig matoperation 🥣', body_sv = 'Ägget som barnet älskade fram till i går får du i dag inte ens i barnets mun. Kämpa inte mot barnets vilja. Använd listiga mellanmålsrecept från Hälsosamma recept som ger proteinerna nya, färgglada och spännande former, och vinn.', title_vi = 'Chiến dịch giấu thức ăn 🥣', body_vi = 'Món trứng đến hôm qua bé còn thích, hôm nay lại không chịu ăn. Đừng đấu với ý chí của bé. Hãy áp dụng trong Công thức lành mạnh những công thức món ăn nhẹ khéo léo biến chất đạm thành những hình dạng khác lạ, nhiều màu sắc, thú vị và giành chiến thắng.', title_zh = '秘密食物行动 🥣', body_zh = '直到昨天还喜欢的鸡蛋，今天碰都不肯碰。别和宝宝的意志较劲。用上健康食谱里那些把蛋白质做成不同、彩色又有趣造型的小零食妙招，赢下这一局吧。' WHERE id = '2d96922a-7550-4150-a8ed-19cdd56a8801' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El derrumbe de la lógica 🛑', body_es = 'Grita «¡dame el agua en el vaso rojo!», se la sirves en el rojo y ahora llora: «¿Por qué la has echado aquí?». Aquí no hay lógica. Simplemente está cansado y necesita una crisis. Espera con calma: la tormenta se calmará sola.', title_fr = 'L''effondrement de la logique 🛑', body_fr = 'Il crie qu''il veut son eau dans le gobelet rouge, vous la versez dans le rouge, et cette fois il pleure : « Pourquoi tu l''as versée là ? » Il n''y a aucune logique. Il est simplement fatigué et a besoin de vider son trop-plein. Attendez calmement, la tempête se calmera d''elle-même.', title_hi = 'तर्क ढह गया 🛑', body_hi = '‘पानी लाल गिलास में दो’ चिल्लाता है, आप लाल में डालती हैं, तो इस बार ‘यहाँ क्यों डाला’ कहकर रोता है। यहाँ कोई तर्क नहीं। वह बस थका है और उसे यह तूफ़ान निकालना है। चुपचाप इंतज़ार कीजिए, तूफ़ान अपने-आप थम जाएगा।', title_id = 'Runtuhnya logika 🛑', body_id = 'Ia berteriak minta airnya di gelas merah, Anda menuangnya ke gelas merah, lalu ia menangis ''Kenapa dituang di sini?''. Tak ada logika di sini. Ia hanya lelah dan butuh melampiaskan krisis. Tunggulah dengan tenang, badai akan reda dengan sendirinya.', title_ja = '理屈の崩壊 🛑', body_ja = '「お水は赤いコップで！」と叫ぶので赤に注ぐと、今度は「なんでそこに注いだの」と泣く。ここに理屈はありません。ただ疲れていて、爆発が必要なだけ。静かに待ちましょう。嵐は自然におさまります。', title_ko = '논리의 붕괴 🛑', body_ko = '''물 빨간 컵에 줘'' 해서 빨간 컵에 따랐더니 ''왜 여기 따랐어''라며 우나요? 여기엔 논리가 없어요. 그냥 피곤해서 터뜨릴 곳이 필요한 거예요. 조용히 기다리면 폭풍은 저절로 잦아들 거예요.', title_nl = 'De ineenstorting van de logica 🛑', body_nl = 'Hij schreeuwt dat hij zijn water in de rode beker wil, je schenkt het in de rode, en dan huilt hij: ''Waarom heb je het hierin gedaan?'' Er zit geen logica in. Hij is gewoon moe en heeft een bui nodig. Wacht rustig af, de storm gaat vanzelf liggen.', title_pl = 'Upadek logiki 🛑', body_pl = 'Krzyczy „Daj mi wodę w czerwonym kubku”, nalewasz do czerwonego, a on płacze: „Czemu nalałaś tutaj?”. Tu nie ma logiki. Jest po prostu zmęczony i potrzebuje kryzysu. Spokojnie poczekaj, burza sama ucichnie.', title_pt = 'O colapso da lógica 🛑', body_pt = 'Grita "Põe-me a água no copo vermelho", deita-a no vermelho e desta vez chora: "porque é que a puseste aqui?". Aqui não há lógica. Está só cansado e precisa de uma crise. Espere com calma, a tempestade passa sozinha.', title_sv = 'Logikens kollaps 🛑', body_sv = 'Barnet skriker ”Ge mig vattnet i den röda muggen”, du häller upp i den röda, och nu gråter barnet ”varför hällde du här?”. Här finns ingen logik. Barnet är bara trött och behöver en kris. Vänta lugnt, stormen lägger sig av sig själv.', title_vi = 'Logic sụp đổ 🛑', body_vi = 'Bé hét lên đòi uống nước bằng cốc đỏ, mẹ rót vào cốc đỏ, lần này bé lại khóc "Sao mẹ rót vào đây?". Ở đây chẳng có logic nào cả. Bé chỉ mệt và cần một cơn bùng nổ. Hãy bình tĩnh chờ đợi, cơn bão sẽ tự lặng.', title_zh = '逻辑崩塌 🛑', body_zh = '哭喊着“用红杯子给我装水”，你倒进红杯子里，宝宝又哭“你为什么倒在这里”。这里没有逻辑可言。宝宝只是累了，需要发泄一下。安静地等着，风暴会自己平息。' WHERE id = 'a6a15ff2-f8a6-4007-b1d8-974680e64a8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por sorpresa 🥰', body_es = 'En pleno juego suelta el juguete, viene corriendo, te rodea el cuello con los brazos y te dice «te quiero». Este momento es la magia que borra todo el agotamiento y la falta de sueño. Abrázale fuerte contra tu pecho y respira su olor.', title_fr = 'Un élan d''amour soudain 🥰', body_fr = 'En plein jeu, il lâche son jouet, accourt, passe ses bras autour de votre cou et dit « Je t''aime ». Voilà la magie qui efface tout l''épuisement et le manque de sommeil. Serrez-le fort contre votre cœur et respirez son odeur.', title_hi = 'अचानक उमड़ा प्यार 🥰', body_hi = 'खेलते-खेलते खिलौना छोड़कर दौड़ता आता है, बाहें गले में डालकर कहता है, ‘मैं तुमसे प्यार करता हूँ।’ यही वह जादू है जो सारी थकान और जागी रातें मिटा देता है। उसे सीने से कसकर लगाइए और उसकी खुशबू अपने अंदर भर लीजिए।', title_id = 'Cinta yang datang tiba-tiba 🥰', body_id = 'Di tengah bermain ia membuang mainannya, berlari ke arah Anda, melingkarkan lengan di leher Anda, dan berkata ''Aku sayang Mama''. Inilah keajaiban yang menghapus semua rasa lelah dan kurang tidur. Peluk ia erat ke dada Anda dan hirup aromanya.', title_ja = '不意打ちの愛 🥰', body_ja = '遊んでいたおもちゃを放り出して走ってきて、首に腕をまわして「大好き」と言う。ほら、この瞬間こそ、疲れも寝不足も消し去ってくれる魔法です。ぎゅっと胸に抱きしめて、そのにおいを胸いっぱいに吸いこんで。', title_ko = '갑자기 찾아온 사랑 🥰', body_ko = '놀던 장난감을 던지고 달려와 목을 끌어안으며 ''사랑해''라고 하나요? 바로 이 순간이 모든 피로와 잠 못 잔 밤을 지워 주는 마법이에요. 꼭 끌어안고 그 냄새를 깊이 들이마셔 보세요.', title_nl = 'Plotselinge liefde 🥰', body_nl = 'Midden in het spelen gooit hij zijn speelgoed neer, rent naar je toe, slaat zijn armen om je nek en zegt ''Ik hou van je''. Kijk, dit is de magie die alle uitputting en slaapgebrek wegveegt. Druk hem stevig tegen je aan en adem zijn geur in.', title_pl = 'Nagły przypływ miłości 🥰', body_pl = 'W środku zabawy rzuca zabawkę, przybiega, obejmuje cię za szyję i mówi „Kocham cię”. Właśnie ta chwila to magia, która wymazuje całe wyczerpanie i niewyspanie. Przytul go mocno do piersi i wdychaj jego zapach.', title_pt = 'Amor de repente 🥰', body_pt = 'No meio da brincadeira, larga o brinquedo, vem a correr, põe-lhe os braços à volta do pescoço e diz "Amo-te". Pois é, este momento é a magia que apaga todo o esgotamento e a falta de sono. Aperte-o bem contra o peito e respire aquele cheirinho.', title_sv = 'Plötslig kärlek 🥰', body_sv = 'Mitt i leken släpper barnet leksaken, springer fram, slår armarna om din hals och säger ”Jag älskar dig”. Titta, den här stunden är magin som sopar bort all utmattning och sömnlöshet. Tryck barnet hårt mot bröstet och andas in doften.', title_vi = 'Tình yêu bất chợt 🥰', body_vi = 'Đang chơi, bé vứt đồ chơi, chạy đến vòng tay ôm cổ mẹ và nói "Con yêu mẹ". Đó chính là phép màu xóa tan mọi kiệt sức và mất ngủ. Hãy ôm chặt bé vào lòng và hít thật sâu mùi hương của bé.', title_zh = '突如其来的爱 🥰', body_zh = '正玩着，突然扔下玩具跑过来，搂住你的脖子说“我爱你”。看，这一刻就是能抹去所有疲惫和缺觉的魔法。把宝宝紧紧抱在怀里，深深吸一口那份气味吧。' WHERE id = '15c2879b-fa80-4ef3-b734-53366c8b7916' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento raro de papá 📖', body_es = 'Esta noche tienes la voz cansada. Deja la lectura del cuento a papá. Contará una historia inventada y cómica que no tiene nada que ver con los dibujos del libro y hará que el peque se parta de risa. Y tú, a un lado y con un té, disfruta de la escena.', title_fr = 'L''histoire farfelue de papa 📖', body_fr = 'Ce soir, votre voix est fatiguée. Confiez la lecture du conte à papa. Il racontera une histoire inventée et comique, complètement différente des images du livre, et l''enfant éclatera de rire. Vous, installez-vous un peu à l''écart avec un thé et savourez la scène.', title_hi = 'पापा की अजीब कहानी 📖', body_hi = 'आज शाम आपकी आवाज़ थक गई है। कहानी सुनाने का काम पापा को सौंप दीजिए। वे किताब की तस्वीर से बिल्कुल अलग, गढ़ी हुई मज़ेदार कहानी सुनाकर बच्चे को हँसा-हँसाकर लोटपोट कर देंगे। और आप एक तरफ़ चाय के कप के साथ इस नज़ारे का मज़ा लीजिए।', title_id = 'Dongeng aneh Ayah 📖', body_id = 'Malam ini suaramu sudah lelah. Serahkan tugas membacakan dongeng kepada Ayah. Ia akan mengarang cerita lucu yang sama sekali berbeda dari gambar di buku dan membuat anak tertawa terbahak-bahak. Kamu cukup menikmati pemandangan ini dari samping dengan secangkir teh.', title_ja = 'パパのへんてこおはなし 📖', body_ja = '今夜は声が疲れていますね。読み聞かせはパパにバトンタッチ。絵本の絵とはまったくちがう、作り話のおもしろいお話で子どもを大笑いさせてくれるはず。あなたはそばで、お茶を片手にこの光景を楽しんで。', title_ko = '아빠의 엉뚱한 동화 📖', body_ko = '오늘 저녁엔 목이 지쳤나요? 동화 읽기는 아빠에게 넘기세요. 아빠는 책 속 그림과 전혀 다른 지어낸 웃긴 이야기로 아이를 웃음바다에 빠뜨릴 거예요. 엄마는 옆에서 차 한 잔과 함께 이 장면을 즐기세요.', title_nl = 'Papa''s rare sprookje 📖', body_nl = 'Je stem is vanavond moe. Draag het voorlezen over aan papa. Hij vertelt een verzonnen, grappig verhaal dat totaal niet bij de plaatjes in het boek past, en je kind ligt dubbel van het lachen. En jij kijkt met een kop thee van een afstand van dit plaatje te genieten.', title_pl = 'Dziwna bajka taty 📖', body_pl = 'Dziś wieczorem twój głos jest zmęczony. Przekaż czytanie bajki tacie. Opowie zupełnie inną niż na obrazkach w książce, wymyśloną i zabawną historię, a dziecko będzie się zaśmiewać. A ty z boku, z kubkiem herbaty, delektuj się tym widokiem.', title_pt = 'A história esquisita do pai 📖', body_pt = 'Esta noite a sua voz está cansada. Passe a leitura da história para o pai. Ele vai contar uma história inventada e cómica, totalmente diferente das imagens do livro, e a criança vai desfazer-se em gargalhadas. E a mãe, de lado, com uma chávena de chá, desfruta deste quadro.', title_sv = 'Pappas konstiga saga 📖', body_sv = 'Din röst är trött i kväll. Lämna över sagoläsningen till pappa. Han berättar en påhittad och rolig historia som är helt annorlunda än bilden i boken, så barnet kiknar av skratt. Och du, titta på det hela från sidan med en kopp te och njut.', title_vi = 'Câu chuyện kỳ lạ của bố 📖', body_vi = 'Tối nay giọng mẹ đã mỏi. Hãy giao việc đọc truyện cho bố. Bố sẽ kể một câu chuyện tự nghĩ ra, hài hước và khác hẳn tranh trong sách, khiến bé cười ngặt nghẽo. Còn mẹ, hãy ngồi một bên với cốc trà và thưởng thức khung cảnh ấy.', title_zh = '爸爸的怪故事 📖', body_zh = '今晚你的嗓子累了。把讲故事的任务交给爸爸吧。他会讲一个和书里图画完全不同、天马行空又搞笑的故事，把宝宝逗得哈哈大笑。你就在一旁，端杯茶，好好欣赏这幅画面。' WHERE id = 'c0446dd4-cfe7-4c72-9419-07304cef46d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tormenta del carro del súper 🛒', body_es = 'Quiere empujar él solo el carro grande del súper aunque sea más grande que él. En lugar de que acabe llorando en público, deja que ponga las manos en el borde del carro y tú dirige a escondidas.', title_fr = 'La tempête du chariot 🛒', body_fr = 'Le grand chariot est plus grand que lui, mais il veut absolument le pousser tout seul. Plutôt que de le faire pleurer en public, laissez ses mains sur le bord du chariot et guidez discrètement la direction.', title_hi = 'शॉपिंग ट्रॉली का तूफ़ान 🛒', body_hi = 'बड़ी शॉपिंग ट्रॉली उससे बड़ी होने के बावजूद उसे खुद ही चलानी है। लोगों के बीच रुलाने के बजाय, उसके हाथ ट्रॉली के किनारे पर रहने दीजिए और आप चुपके से दिशा देती रहिए।', title_id = 'Badai troli belanja 🛒', body_id = 'Meski troli supermarket jauh lebih besar dari tubuhnya, ia bersikeras mendorongnya sendiri. Daripada membuatnya menangis di depan umum, biarkan tangannya tetap di pinggir troli, sementara Anda diam-diam mengarahkannya.', title_ja = 'ショッピングカートの嵐 🛒', body_ja = '自分より大きなショッピングカートを、どうしても自分で押したがる。人前で泣かせるより、両手はカートのはしに置かせたまま、あなたがこっそり方向を決めてあげましょう。', title_ko = '마트 카트 폭풍 🛒', body_ko = '자기보다 큰 마트 카트를 꼭 자기가 밀겠다고 하나요? 사람들 앞에서 울리기보다 손은 카트 가장자리에 두게 하고 엄마가 몰래 방향을 잡아 주세요.', title_nl = 'Storm met het boodschappenkarretje 🛒', body_nl = 'Hij wil per se zelf het grote boodschappenkarretje duwen, ook al is het groter dan hij. Laat hem niet in het openbaar huilen, maar laat zijn handen op de rand van het karretje en stuur jij stiekem bij.', title_pl = 'Burza z wózkiem w sklepie 🛒', body_pl = 'Koniecznie chce sam pchać wielki sklepowy wózek, choć jest większy od niego. Zamiast doprowadzać go do płaczu przy ludziach, niech trzyma ręce na brzegu wózka, a ty dyskretnie nadawaj kierunek.', title_pt = 'A tempestade do carrinho de compras 🛒', body_pt = 'Quer mesmo empurrar sozinho o grande carrinho do supermercado, apesar de ser maior do que ele. Em vez de o fazer chorar em público, deixe as mãos dele na borda do carrinho e vá guiando a direção às escondidas.', title_sv = 'Kundvagnsstormen 🛒', body_sv = 'Barnet vill absolut köra den stora kundvagnen själv, fast den är större än barnet. Istället för att barnet ska gråta bland folk, låt barnets händer vara på vagnens kant medan du i smyg styr.', title_vi = 'Cơn bão xe đẩy siêu thị 🛒', body_vi = 'Chiếc xe đẩy siêu thị to hơn cả bé, vậy mà bé nhất định đòi tự đẩy. Thay vì để bé khóc giữa đám đông, hãy để tay bé đặt trên thành xe, còn mẹ khéo léo lái hướng.', title_zh = '购物车风暴 🛒', body_zh = '大大的购物车明明比自己还大，却非要自己推。与其在大家面前把宝宝弄哭，不如让宝宝把手扶在车边，你悄悄地掌握方向。' WHERE id = 'df2fef22-961b-4197-8f8b-a55345b6bbaa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libertad vestida del revés 👗', body_es = 'Se ha puesto el pantalón del revés y dice muy decidido: «Me he vestido yo». Olvídate de la estética. Su autoestima creciente y su sensación de independencia importan muchísimo más que llevar la ropa bien puesta. Siéntete orgullosa de este pequeño rebelde.', title_fr = 'La liberté à l''envers 👗', body_fr = 'Il a mis son pantalon à l''envers et déclare d''un air très décidé « Je me suis habillé ». Laissez tomber l''esthétique. Sa confiance en lui qui grandit et son sentiment d''indépendance comptent bien plus qu''une tenue bien mise. Soyez fière de ce petit rebelle.', title_hi = 'उलटे कपड़ों वाली आज़ादी 👗', body_hi = 'पैंट उलटी पहन ली और बड़े पक्के इरादे से कहता है, ‘मैंने पहनी।’ सुंदरता को छोड़िए। उसका बढ़ता आत्मविश्वास और आत्मनिर्भरता का एहसास कपड़ों के सही होने से कई गुना ज़रूरी है। इस नन्हे बागी पर गर्व कीजिए।', title_id = 'Kebebasan yang dipakai terbalik 👗', body_id = 'Ia memakai celana terbalik dan dengan sangat yakin berkata ''Aku pakai sendiri''. Lupakan soal estetika. Rasa percaya dirinya yang meninggi dan rasa mandirinya jauh lebih penting daripada pakaian yang benar. Banggalah pada pemberontak kecil ini.', title_ja = '後ろ前の自由 👗', body_ja = 'ズボンを後ろ前にはいて、とても堂々と「自分で着た」と言う。見た目は気にしないで。ぐんぐん高まる自信と自立心は、服を正しく着ることよりずっと大切です。この小さな反逆児を誇りに思いましょう。', title_ko = '거꾸로 입은 자유 👗', body_ko = '바지를 거꾸로 입고 아주 단호하게 ''내가 입었어''라고 하나요? 보기 좋은 건 잊으세요. 쑥쑥 자라는 자신감과 독립심이 옷을 바르게 입는 것보다 훨씬 중요해요. 이 작은 반항아를 자랑스러워하세요.', title_nl = 'Achterstevoren aangetrokken vrijheid 👗', body_nl = 'Hij heeft zijn broek achterstevoren aan en zegt vastberaden: ''Ik heb hem zelf aangedaan.'' Laat de esthetiek zitten. Zijn groeiende zelfvertrouwen en gevoel van zelfstandigheid zijn veel belangrijker dan kleren die goed zitten. Wees trots op deze kleine rebel.', title_pl = 'Wolność na lewą stronę 👗', body_pl = 'Założył spodnie tyłem do przodu i bardzo stanowczo mówi „Sam się ubrałem”. Odpuść estetykę. Jego rosnąca pewność siebie i poczucie niezależności są o wiele ważniejsze niż poprawnie założone ubranie. Bądź dumna z tego małego buntownika.', title_pt = 'Liberdade vestida ao contrário 👗', body_pt = 'Vestiu as calças ao contrário e diz, muito decidido, "fui eu que vesti". Esqueça a estética. A autoestima a crescer e a sensação de independência são muito mais importantes do que a roupa bem vestida. Orgulhe-se deste pequeno rebelde.', title_sv = 'Frihet med kläderna bakfram 👗', body_sv = 'Barnet har tagit byxorna bakfram och säger väldigt bestämt ”jag klädde på mig”. Strunta i estetiken. Barnets växande självförtroende och känsla av självständighet är mycket viktigare än att kläderna sitter rätt. Var stolt över den lilla rebellen.', title_vi = 'Tự do mặc ngược 👗', body_vi = 'Bé mặc ngược quần và nói đầy quyết tâm "Con tự mặc đấy". Kệ chuyện thẩm mỹ. Sự tự tin đang lớn dần và cảm giác tự lập của bé quan trọng hơn nhiều so với việc mặc đúng. Hãy tự hào về "kẻ nổi loạn" tí hon này.', title_zh = '穿反了的自由 👗', body_zh = '把裤子穿反了，还非常坚定地说“我穿好了”。别管好不好看。宝宝那份高涨的自信和独立感，比衣服穿得对不对重要得多。为这个小小的叛逆者骄傲吧。' WHERE id = '1528a888-1cfa-4bf5-b2b7-c533244518f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un café en medio del caos ☕', body_es = 'En medio de la habitación ha desparramado todos sus juguetes y se construye un castillo. En cuanto recojas el desastre, volverá a desordenarlo. Así que deja la lucha, ve a un rincón, tómate el café calentito y descansa mirando el caos desde fuera.', title_fr = 'Un café au milieu du chaos ☕', body_fr = 'Au milieu de la pièce, il éparpille tous ses jouets pour se construire un château. Dès que vous aurez rangé, il recommencera. Alors abandonnez la lutte, buvez votre café bien chaud dans un coin de la pièce et reposez-vous en regardant le chaos de loin.', title_hi = 'अफ़रा-तफ़री के बीच कॉफ़ी ☕', body_hi = 'कमरे के बीच सारे खिलौने बिखेरकर अपना किला बना रहा है। आप समेटेंगी तो वह फिर बिखेर देगा। इसलिए लड़ाई छोड़िए, कमरे के एक कोने में अपनी कॉफ़ी गरम-गरम पीजिए और दूर से अफ़रा-तफ़री देखते हुए आराम कीजिए।', title_id = 'Kopi di tengah kekacauan ☕', body_id = 'Di tengah kamar ia menghamburkan semua mainannya untuk membangun benteng. Begitu Anda membereskannya, ia akan menghamburkannya lagi. Jadi berhentilah berjuang, pergilah ke sudut kamar, minum kopi selagi panas, dan beristirahatlah sambil memandangi kekacauan dari jauh.', title_ja = 'カオスの中のコーヒー ☕', body_ja = '部屋のまんなかでおもちゃを全部ひっくり返して、お城を作っています。片づけたそばから、また散らかすでしょう。だから戦いはやめて、部屋のすみでコーヒーを温かいうちに飲み、カオスを遠くから眺めてひと休みしましょう。', title_ko = '혼돈 속 커피 한 잔 ☕', body_ko = '방 한가운데 장난감을 다 쏟아 놓고 성을 쌓나요? 치우자마자 또 쏟을 거예요. 그러니 싸움은 내려놓고 방 한쪽에서 커피를 따뜻할 때 마시며 혼돈을 멀리서 바라보고 쉬세요.', title_nl = 'Koffie midden in de chaos ☕', body_nl = 'Hij gooit midden in de kamer al zijn speelgoed overhoop en bouwt er een kasteel van. Zodra jij die puinhoop opruimt, haalt hij alles weer overhoop. Geef de strijd dus op, drink in een hoekje van de kamer je koffie lekker warm en ontspan terwijl je van een afstand naar de chaos kijkt.', title_pl = 'Kawa w środku chaosu ☕', body_pl = 'Rozrzucił wszystkie zabawki na środku pokoju i buduje sobie zamek. Gdy tylko posprzątasz, znowu wszystko rozrzuci. Dlatego odpuść walkę, usiądź w kącie pokoju, wypij gorącą kawę i odpocznij, patrząc na chaos z boku.', title_pt = 'Café no meio do caos ☕', body_pt = 'No meio do quarto, espalhou todos os brinquedos e construiu um castelo. Assim que arrumar a confusão, ele volta a desarrumar. Por isso, desista da luta: vá para um canto do quarto, beba o seu café bem quente e descanse a ver o caos à distância.', title_sv = 'Kaffe mitt i kaoset ☕', body_sv = 'Mitt i rummet river barnet ut alla leksaker och bygger ett slott. Så fort du plockar upp röran river barnet igen. Så släpp kampen, gå och drick ditt kaffe medan det är varmt i ett hörn av rummet och vila medan du ser på kaoset från sidan.', title_vi = 'Cà phê giữa hỗn loạn ☕', body_vi = 'Bé bày hết đồ chơi ra giữa phòng để xây lâu đài. Mẹ vừa dọn xong, bé sẽ lại bày ra. Vì vậy, hãy buông bỏ cuộc chiến, ngồi ở một góc phòng uống cà phê khi còn nóng và thư giãn ngắm sự hỗn loạn từ xa.', title_zh = '混乱中的咖啡 ☕', body_zh = '在房间中间把所有玩具都倒出来，给自己搭了座城堡。你一收拾，宝宝又会弄乱。所以别较劲了，去房间一角趁热喝杯咖啡，远远看着这片混乱，好好休息一下。' WHERE id = '3b7890c9-fcdd-4513-a90d-c39e56fa7a0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sombras en la habitación 🐰', body_es = '¿Empieza a tenerle miedo a la oscuridad? Oscurece del todo la habitación y, con una linternita, crea juegos de luz y sombras de animales en el techo. Convierte la oscuridad que le asusta en diversión, en una pequeña exploración antes de dormir de la que os reiréis juntos.', title_fr = 'Les ombres de la chambre 🐰', body_fr = 'Il commence à avoir peur du noir ? Faites le noir complet dans la chambre et, avec une petite lampe de poche, créez des jeux de lumière et des ombres d''animaux au plafond. Transformez le noir qui lui fait peur en jeu, en petite exploration avant le dodo où vous rirez ensemble.', title_hi = 'कमरे की परछाइयाँ 🐰', body_hi = 'अँधेरे से डरने लगा है? कमरा पूरी तरह अँधेरा कीजिए और छोटी टॉर्च से छत पर रोशनी के खेल और जानवरों की परछाइयाँ बनाइए। जिस अँधेरे से वह डरता है, उसे मज़े में, सोने से पहले साथ हँसने वाली एक छोटी खोज-यात्रा में बदल दीजिए।', title_id = 'Bayangan di kamar 🐰', body_id = 'Ia mulai takut gelap? Gelapkan kamar sepenuhnya dan dengan senter kecil buat permainan cahaya dan bayangan binatang di langit-langit. Ubah gelap yang ia takuti menjadi hiburan, petualangan kecil sebelum tidur yang membuat kalian tertawa bersama.', title_ja = '部屋の影 🐰', body_ja = '暗やみを怖がるようになった？部屋を真っ暗にして、小さな懐中電灯で天井に光の遊びや動物の影絵をつくりましょう。怖がっていた暗やみを、寝る前に一緒に笑える小さな探検に変えてあげて。', title_ko = '방 안의 그림자 🐰', body_ko = '어둠을 무서워하기 시작했나요? 방을 완전히 어둡게 하고 작은 손전등으로 천장에 불빛 놀이와 동물 그림자를 만들어 보세요. 무서운 어둠을 잠들기 전 함께 웃는 작은 탐험으로 바꿔 주세요.', title_nl = 'Schaduwen in de kamer 🐰', body_nl = 'Begint hij het donker eng te vinden? Maak de kamer helemaal donker en maak met een kleine zaklamp lichtspelletjes en dierenschaduwen op het plafond. Verander het donker waar hij bang voor is in plezier, een kleine ontdekkingstocht voor het slapen waar jullie samen om lachen.', title_pl = 'Cienie w pokoju 🐰', body_pl = 'Zaczął bać się ciemności? Zaciemnij pokój całkowicie i małą latarką twórz na suficie gry świateł i cienie zwierzątek. Zamień ciemność, której się boi, w zabawę i małą wyprawę przed snem, podczas której razem się pośmiejecie.', title_pt = 'Sombras no quarto 🐰', body_pt = 'Começou a ter receio do escuro? Escureça bem o quarto e, com uma pequena lanterna, faça jogos de luz e sombras de animais no teto. Transforme o escuro de que tem medo numa diversão, uma pequena exploração antes de dormir para rirem juntos.', title_sv = 'Skuggorna i rummet 🐰', body_sv = 'Har barnet börjat bli rädd för mörkret? Gör rummet helt mörkt och skapa ljuslekar och djurskuggor i taket med en liten ficklampa. Gör det mörker barnet är rädd för till en lek, en liten upptäcktsfärd som ni skrattar åt tillsammans före sömnen.', title_vi = 'Những cái bóng trong phòng 🐰', body_vi = 'Bé bắt đầu sợ bóng tối? Hãy làm tối hẳn căn phòng và dùng một chiếc đèn pin nhỏ tạo trò chơi ánh sáng, bóng con vật trên trần nhà. Biến bóng tối bé sợ thành trò vui, một chuyến thám hiểm nhỏ trước giờ ngủ để hai mẹ con cùng cười.', title_zh = '房间里的影子 🐰', body_zh = '开始害怕黑暗了？把房间完全调暗，用小手电筒在天花板上玩光影游戏，做出动物的影子。把宝宝害怕的黑暗变成乐趣，变成睡前一起欢笑的小小探险。' WHERE id = '903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La esperanza de un sueño sin interrupciones 🤞', body_es = 'Se ha dormido y en casa reina un silencio profundo. Tu mayor deseo es que esta noche no se despierte. Pon a volumen bajo el suave susurro del bosque del sonido de fondo del Medidor de sonido y asegúrate de que se mantenga en la fase de sueño profundo.', title_fr = 'L''espoir d''une nuit sans réveil 🤞', body_fr = 'Il dort, et un silence profond est tombé sur la maison. Votre plus grand souhait : qu''il ne se réveille pas cette nuit. Mettez à faible volume le doux bruissement de forêt du bruit de fond du Sonomètre pour l''aider à rester en sommeil profond.', title_hi = 'बिना टूटी नींद की उम्मीद 🤞', body_hi = 'वह सो गया और घर में गहरी खामोशी छा गई। आपकी सबसे बड़ी चाहत है कि वह आज रात न जागे। साउंड मीटर की बैकग्राउंड आवाज़ में धीमी जंगल की सरसराहट हल्की आवाज़ में चलाइए और पक्का कीजिए कि वह गहरी नींद में रहे।', title_id = 'Harapan tidur tanpa terbangun 🤞', body_id = 'Ia sudah tidur dan rumah diselimuti keheningan yang dalam. Harapan terbesar Anda adalah ia tidak terbangun malam ini. Putar pelan suara latar gemerisik hutan yang lembut dari Pengukur Suara untuk memastikan ia tetap dalam fase tidur nyenyak.', title_ja = '朝までぐっすりの願い 🤞', body_ja = 'この子が寝て、家に深い静けさが訪れました。いちばんの願いは、今夜一度も起きないこと。「サウンドメーター」の背景音から、やさしい森のさざめきを小さな音で流して、深い眠りを守りましょう。', title_ko = '깨지 않고 푹 자기를 🤞', body_ko = '아이가 잠들고 집에 깊은 고요가 내려앉았어요. 가장 큰 바람은 오늘 밤 깨지 않는 것이죠. 소음 측정기의 배경 소리 중 잔잔한 숲 소리를 작게 틀어 깊은 잠에 머물도록 지켜 주세요.', title_nl = 'Hoop op een nacht doorslapen 🤞', body_nl = 'Hij slaapt en er is een diepe stilte in huis. Je grootste wens is dat hij vannacht niet wakker wordt. Zet zachtjes het achtergrondgeluid van de Geluidsmeter aan, het rustige ruisen van het bos, en zorg dat hij in zijn diepe slaap blijft.', title_pl = 'Nadzieja na nieprzerwany sen 🤞', body_pl = 'Zasnął, a w domu zapadła głęboka cisza. Twoim największym marzeniem jest, żeby tej nocy się nie obudził. Włącz cicho dźwięk tła w Mierniku dźwięku, łagodny szum lasu, i zadbaj, by pozostał w fazie głębokiego snu.', title_pt = 'A esperança de uma noite sem interrupções 🤞', body_pt = 'Ele adormeceu e caiu um silêncio profundo sobre a casa. O seu maior desejo é que não acorde esta noite. Ligue baixinho o suave murmúrio da floresta, o som de fundo do Medidor de Som, e garanta que ele fica na fase de sono profundo.', title_sv = 'Hopp om en hel natts sömn 🤞', body_sv = 'Barnet har somnat och en djup tystnad har sänkt sig över hemmet. Din största önskan är att barnet inte vaknar i natt. Sätt på Ljudmätarens bakgrundsljud, ett milt skogssus, på låg volym och se till att barnet stannar i den djupa sömnfasen.', title_vi = 'Hy vọng một giấc ngủ không gián đoạn 🤞', body_vi = 'Bé đã ngủ và căn nhà chìm vào im lặng. Điều mẹ mong nhất là đêm nay bé không thức giấc. Hãy bật nhỏ tiếng rì rào êm dịu của khu rừng, âm thanh nền trong Đo âm thanh, để giữ bé ở giai đoạn ngủ sâu.', title_zh = '盼望一觉到天亮 🤞', body_zh = '宝宝睡着了，家里一片深深的安静。你最大的愿望就是宝宝今晚别醒。把分贝仪背景音里轻柔的森林沙沙声调到小音量，帮宝宝稳稳地待在深睡阶段。' WHERE id = '86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El laboratorio de la naturaleza 🍂', body_es = 'La casa te agobia y el peque está inquieto. Consulta Tiempo y ropa y sácale fuera sin falta. Con la simple misión de recoger ramas y hojas secas, él gastará energía y tú también te librarás de las cuatro paredes y respirarás.', title_fr = 'Le laboratoire de la nature 🍂', body_fr = 'La maison vous étouffe et l''enfant est agité. Consultez Météo et tenue et sortez-le absolument. Avec une simple mission, ramasser des branches et des feuilles sèches, il dépensera son énergie, et vous, vous échapperez aux quatre murs pour respirer.', title_hi = 'प्रकृति की प्रयोगशाला 🍂', body_hi = 'घर आपको घुटन दे रहा है, और बच्चा बेचैन है। मौसम और कपड़े देखिए और उसे बाहर ज़रूर ले जाइए। सूखी टहनियाँ और पत्ते इकट्ठा करने के मिशन से उसकी ऊर्जा भी निकालिए और खुद भी चार दीवारों से निकलकर खुली साँस लीजिए।', title_id = 'Laboratorium alam 🍂', body_id = 'Rumah terasa menyesakkan, dan anak gelisah. Cek Cuaca dan Pakaian, lalu pastikan mengajaknya keluar. Dengan misi sederhana mengumpulkan ranting dan daun kering, ia menyalurkan energinya, dan Anda pun lepas dari empat dinding dan bisa bernapas.', title_ja = '自然の実験室 🍂', body_ja = '家にいると息がつまり、子どもも落ち着かない。「天気と服装」をチェックして、必ず外へ連れ出しましょう。枯れ枝や葉っぱを集めるミッションだけで、この子はエネルギーを発散でき、あなたも4つの壁から抜け出して深呼吸できます。', title_ko = '자연 실험실 🍂', body_ko = '집은 답답하고 아이는 불안해하나요? 날씨와 옷차림을 확인하고 꼭 밖에 데리고 나가세요. 마른 나뭇가지와 나뭇잎 모으기 미션만으로도 아이는 에너지를 쓰고, 엄마도 네 벽에서 벗어나 숨을 쉴 수 있어요.', title_nl = 'Natuurlaboratorium 🍂', body_nl = 'Het huis benauwt je en je kind is onrustig. Check Weer en kleding en ga hoe dan ook met hem naar buiten. Met een simpele missie als droge takjes en blaadjes verzamelen raakt hij zijn energie kwijt, en ontsnap jij aan de vier muren en kun je weer ademhalen.', title_pl = 'Laboratorium natury 🍂', body_pl = 'Dom cię przytłacza, a dziecko jest niespokojne. Sprawdź Pogodę i ubiór i koniecznie wyjdźcie na dwór. Zwykła misja zbierania suchych gałązek i liści pozwoli mu wyładować energię, a ty uciekniesz od czterech ścian i złapiesz oddech.', title_pt = 'Laboratório da natureza 🍂', body_pt = 'A casa sufoca-a e a criança está inquieta. Veja o Tempo e Roupa e leve-o sem falta para a rua. Com uma simples missão de apanhar ramos secos e folhas, ele gasta energia e a mãe escapa às quatro paredes e respira.', title_sv = 'Naturens laboratorium 🍂', body_sv = 'Hemmet känns trångt och barnet är oroligt. Kolla Väder och kläder och se till att ni kommer ut. Med ett enkelt uppdrag att samla torra kvistar och löv gör barnet av med energin, och du själv slipper de fyra väggarna och kan andas.', title_vi = 'Phòng thí nghiệm thiên nhiên 🍂', body_vi = 'Ở nhà mẹ thấy ngột ngạt, còn bé thì bồn chồn. Hãy kiểm tra Thời tiết và trang phục và nhất định đưa bé ra ngoài. Chỉ với nhiệm vụ nhặt cành khô và lá cây, bé được xả năng lượng, còn mẹ thoát khỏi bốn bức tường và được hít thở.', title_zh = '大自然实验室 🍂', body_zh = '家里让你喘不过气，宝宝也坐立不安。看看天气与穿衣，一定要带宝宝出门。展开一场“收集干树枝和树叶”的任务，既能让宝宝释放精力，你也能逃离四面墙，好好喘口气。' WHERE id = '906c34fb-a999-448f-8756-7ba4d8fc80cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La mamá de los juguetes 🧸', body_es = 'Se oye algo en la habitación. Escuchas con atención: ¡está riñendo a su osito con tu mismo tono de voz y tus mismas frases! Es tu mejor copia. Es una oportunidad perfecta para ver tu comportamiento desde fuera.', title_fr = 'La maman des jouets 🧸', body_fr = 'Un bruit vient de la chambre. Vous tendez l''oreille : il gronde son nounours avec exactement votre ton de voix et vos phrases ! Il est votre meilleure copie. C''est une occasion parfaite de voir votre propre comportement de l''extérieur.', title_hi = 'खिलौनों की माँ 🧸', body_hi = 'कमरे से आवाज़ आती है। ध्यान से सुनती हैं, तो वह अपने टेडी को बिल्कुल आपके लहजे और आपके ही वाक्यों में डाँट रहा है! वह आपकी सबसे अच्छी नकल है। अपने व्यवहार को बाहर से देखने का यह बढ़िया मौका है।', title_id = 'Ibu bagi mainannya 🧸', body_id = 'Ada suara dari kamar. Anda mendengarkan baik-baik, dan ternyata ia sedang memarahi beruangnya persis dengan nada suara dan kalimat Anda! Ia adalah tiruan terbaik Anda. Ini kesempatan sempurna untuk melihat perilaku Anda sendiri dari luar.', title_ja = 'おもちゃたちのママ 🧸', body_ja = '部屋から声が聞こえます。耳をすませると、くまさんをあなたとまったく同じ声のトーン、同じ言葉でしかっている！この子はあなたのいちばんのコピーです。自分のふるまいを外から見直す絶好のチャンスです。', title_ko = '장난감들의 엄마 🧸', body_ko = '방에서 소리가 들려 귀 기울여 보니, 곰 인형을 엄마와 똑같은 톤, 똑같은 말로 혼내고 있나요! 아이는 엄마의 가장 완벽한 복사본이에요. 내 행동을 밖에서 바라볼 수 있는 완벽한 기회예요.', title_nl = 'De mama van de knuffels 🧸', body_nl = 'Er komt geluid uit de kamer. Je luistert goed, en hij moppert op zijn beertje met precies jouw toon en jouw zinnen! Hij is je beste kopie. Een perfecte kans om je eigen gedrag eens van buitenaf te bekijken.', title_pl = 'Mama zabawek 🧸', body_pl = 'Z pokoju dochodzi głos. Słuchasz uważnie, a on beszta swojego misia dokładnie twoim tonem i twoimi zdaniami! Jest twoją najlepszą kopią. To świetna okazja, by spojrzeć na swoje zachowanie z boku.', title_pt = 'A mãe dos brinquedos 🧸', body_pt = 'Vem um som do quarto. Ouve com atenção e ele está a ralhar com o ursinho exatamente com o seu tom de voz e as suas frases! É a sua melhor cópia. É uma oportunidade perfeita para ver o seu comportamento de fora.', title_sv = 'Leksakernas mamma 🧸', body_sv = 'Det hörs ljud från rummet. Du lyssnar noga, och barnet skäller på sin nalle med exakt din röst och dina meningar! Barnet är din bästa kopia. Det är ett perfekt tillfälle att se ditt eget beteende utifrån.', title_vi = 'Mẹ của những món đồ chơi 🧸', body_vi = 'Có tiếng động trong phòng. Mẹ lắng nghe và nhận ra bé đang mắng gấu bông bằng đúng giọng điệu, đúng những câu nói của mẹ! Bé là bản sao hoàn hảo nhất của mẹ. Đây là cơ hội tuyệt vời để nhìn lại hành vi của chính mình từ bên ngoài.', title_zh = '玩具们的妈妈 🧸', body_zh = '房间里传来声音。你仔细一听，宝宝正用和你一模一样的语气、一模一样的话在训它的小熊！宝宝是你最好的复制品。这是从旁观察自己言行的绝佳机会。' WHERE id = 'af0535a2-83d1-4838-8bfc-0cfb607ff2f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desayuno que no se comparte 🍳', body_es = 'No te da nada de su plato, pero viene e insiste en comer del huevo de tu plato. Los niños siempre confían más en lo que eligen sus padres. No luches: pásale con cariño tu bocado a este pequeño egoísta.', title_fr = 'Un petit-déjeuner qui ne se partage pas 🍳', body_fr = 'Il refuse catégoriquement de vous donner quoi que ce soit de son assiette, mais vient réclamer avec insistance l''œuf de la vôtre. Les enfants font toujours plus confiance aux choix de leurs parents. Ne luttez pas, cédez avec amour votre bouchée à ce petit égoïste.', title_hi = 'न बँटने वाला नाश्ता 🍳', body_hi = 'अपनी प्लेट का कुछ भी आपको बिल्कुल नहीं देता, पर आकर ज़िद से आपकी प्लेट का अंडा खाना चाहता है। बच्चे हमेशा माता-पिता की पसंद पर ज़्यादा भरोसा करते हैं। लड़ाई मत कीजिए, अपना निवाला प्यार से इस नन्हे स्वार्थी को दे दीजिए।', title_id = 'Sarapan yang tak bisa dibagi 🍳', body_id = 'Ia sama sekali tak mau memberi isi piringnya kepada Anda, tapi bersikeras ingin makan telur dari piring Anda. Anak selalu lebih percaya pada pilihan orang tuanya. Jangan melawan, berikan suapan Anda dengan penuh kasih kepada si egois kecil ini.', title_ja = '分けてくれない朝ごはん 🍳', body_ja = '自分のお皿のものは絶対にくれないのに、あなたのお皿の卵はどうしても食べたがる。子どもはいつも、親が選んだものをより信頼するんです。戦わずに、あなたのひと口を愛をこめてこの小さなわがままさんに渡しましょう。', title_ko = '나눌 수 없는 아침 식사 🍳', body_ko = '자기 접시는 절대 안 주면서 엄마 접시의 달걀은 꼭 먹겠다고 하나요? 아이는 늘 부모의 선택을 더 믿어요. 싸우지 말고 한 입을 이 작은 욕심쟁이에게 사랑으로 건네주세요.', title_nl = 'Ontbijt dat niet gedeeld wordt 🍳', body_nl = 'Van zijn eigen bord geeft hij je absoluut niets, maar hij wil per se van het ei op jouw bord eten. Kinderen vertrouwen altijd meer op de keuze van hun ouders. Ga de strijd niet aan en geef je hapje liefdevol aan deze kleine egoïst.', title_pl = 'Śniadanie nie do podziału 🍳', body_pl = 'Ze swojego talerza nie da ci ani kęsa, ale uparcie chce jeść jajko z twojego. Dzieci zawsze bardziej ufają wyborom rodziców. Nie walcz, z miłością oddaj swój kęs temu małemu egoiście.', title_pt = 'Um pequeno-almoço que não se partilha 🍳', body_pt = 'Não lhe dá nada do prato dele, mas insiste em comer o ovo do seu prato. As crianças confiam sempre mais nas escolhas dos pais. Não lute: passe com amor o seu bocado a este pequeno egoísta.', title_sv = 'Frukosten som inte delas 🍳', body_sv = 'Barnet ger dig absolut ingenting från sin egen tallrik, men kommer och vill envist äta av ägget på din. Barn litar alltid mer på föräldrarnas val. Börja inte bråka, ge din tugga med kärlek till den lilla egoisten.', title_vi = 'Bữa sáng không chia sẻ 🍳', body_vi = 'Bé nhất quyết không cho mẹ chút gì trong đĩa của mình, nhưng lại cứ đòi ăn trứng trong đĩa của mẹ. Trẻ con luôn tin vào lựa chọn của bố mẹ hơn. Đừng giằng co, hãy yêu thương nhường miếng ăn của mình cho "kẻ ích kỷ" bé nhỏ này.', title_zh = '不肯分享的早餐 🍳', body_zh = '自己盘子里的东西绝对不给你，却偏要来吃你盘子里的鸡蛋。孩子总是更相信父母的选择。别较劲，带着爱把你的那一口递给这个小小的“自私鬼”吧。' WHERE id = '0300b128-8698-433f-8d28-7ef165f88a96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desastre sin lista 🛒', body_es = 'Confiaste en tu memoria y al llegar a casa te diste cuenta de que no habías comprado la leche, lo más importante para el peque. Tu cerebro ya está muy lleno. A partir de ahora, acostúmbrate a apuntarlo en la Lista de la compra de la app en el mismo segundo en que surja la necesidad y protégete del estrés.', title_fr = 'La catastrophe sans liste 🛒', body_fr = 'Vous êtes rentrée en vous fiant à votre mémoire et vous avez réalisé que vous n''aviez pas acheté le lait, le plus important pour l''enfant. Votre cerveau est déjà bien assez rempli. Désormais, prenez l''habitude de noter chaque besoin dans la Liste de courses de l''application à la seconde où il apparaît, et protégez-vous du stress.', title_hi = 'बिना लिस्ट की आफ़त 🛒', body_hi = 'याददाश्त के भरोसे घर लौटीं और ध्यान आया कि बच्चे के लिए सबसे ज़रूरी दूध ही नहीं लिया। आपका दिमाग वैसे ही बहुत भरा है। अब से जिस पल ज़रूरत हो, उसी पल ऐप की शॉपिंग लिस्ट में लिखने की आदत डालिए और तनाव से बचिए।', title_id = 'Bencana tanpa daftar 🛒', body_id = 'Anda pulang mengandalkan ingatan dan sadar tidak membeli susu, barang paling penting untuk anak. Otak Anda memang sudah sangat penuh. Mulai sekarang, biasakan mencatat kebutuhan di Daftar Belanja aplikasi begitu teringat, dan lindungi diri dari stres.', title_ja = 'リストなしの大失敗 🛒', body_ja = '記憶をたよりに帰ってきたら、子どものためにいちばん大事な牛乳を買い忘れていた。ただでさえ頭はいっぱいですものね。これからは、必要になったその瞬間にアプリの「買い物リスト」に書く習慣をつけて、ストレスから身を守りましょう。', title_ko = '목록 없는 대참사 🛒', body_ko = '기억만 믿고 집에 왔는데 아이에게 가장 중요한 우유를 안 샀다는 걸 알았나요? 머릿속은 이미 꽉 차 있죠. 이제부터 필요한 게 생기는 순간 앱의 쇼핑 목록에 적는 습관으로 스트레스를 막으세요.', title_nl = 'Ramp zonder lijstje 🛒', body_nl = 'Je vertrouwde op je geheugen, kwam thuis en merkte dat je de melk, het allerbelangrijkste voor je kind, bent vergeten. Je hoofd zit toch al overvol. Maak er een gewoonte van om iets meteen op het Boodschappenlijstje in de app te zetten zodra je het nodig hebt, en bespaar jezelf stress.', title_pl = 'Katastrofa bez listy 🛒', body_pl = 'Zaufałaś pamięci, wróciłaś do domu i zorientowałaś się, że nie kupiłaś mleka, najważniejszej rzeczy dla dziecka. Twój mózg i tak jest przepełniony. Odtąd wpisuj potrzebną rzecz na Listę zakupów w aplikacji w tej samej sekundzie i chroń się przed stresem.', title_pt = 'O desastre sem lista 🛒', body_pt = 'Confiou na memória, chegou a casa e percebeu que não comprou o leite, a coisa mais importante para a criança. O seu cérebro já anda muito cheio. A partir de agora, habitue-se a escrever cada coisa na Lista de Compras da app no segundo em que faz falta e proteja-se do stress.', title_sv = 'Katastrof utan lista 🛒', body_sv = 'Du litade på minnet, kom hem och märkte att du inte köpt det viktigaste för barnet, mjölken. Din hjärna är redan väldigt full. Gör det till en vana att skriva upp saker i appens Inköpslista samma sekund som behovet uppstår och skydda dig mot stress.', title_vi = 'Thảm họa không có danh sách 🛒', body_vi = 'Tin vào trí nhớ, mẹ về đến nhà mới nhận ra quên mua sữa, thứ quan trọng nhất cho bé. Đầu óc mẹ vốn đã quá tải. Từ giờ, hãy tập thói quen ghi ngay vào Danh sách mua sắm trong ứng dụng vào giây phút cần đến, để tránh căng thẳng.', title_zh = '没有清单的灾难 🛒', body_zh = '相信自己的记性回到家，才发现忘了买孩子最需要的牛奶。你的脑子本来就塞得满满的。从现在起，养成一需要就马上写进应用里购物清单的习惯，远离压力。' WHERE id = '334f9c8b-ef27-4cd7-845a-eb18706654fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un océano en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de hacer olas. Deja que el agua salpique. Ese efecto imán del agua se llevará por el desagüe toda la energía tozuda y negativa acumulada durante el día y hará su sueño más profundo.', title_fr = 'L''océan dans la baignoire 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu de vagues. Laissez l''eau éclabousser. L''effet magnétique de l''eau emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée et rendra son sommeil plus profond.', title_hi = 'बाथटब में समुद्र 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, लहरें बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए। पानी का वह चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा और उसकी नींद गहरी करेगा।', title_id = 'Samudra di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat ombak. Biarkan air memercik ke mana-mana. Efek magnet air akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, membawanya ke saluran pembuangan, dan membuat tidurnya lebih nyenyak.', title_ja = 'お風呂の中の海 🌊', body_ja = 'お風呂はもうきれいにするためではなく、波をつくる遊びです。水しぶきが飛んでもいいんです。お湯の磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して排水口へ運び、眠りも深くしてくれます。', title_ko = '욕조 속 바다 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 파도 만들기 놀이예요. 물이 사방으로 튀어도 괜찮아요. 물의 자석 같은 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보내고 잠을 더 깊게 해 줄 거예요.', title_nl = 'De oceaan in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met golven maken. Laat het water maar spetteren. Het magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in, en maakt zijn slaap dieper.', title_pl = 'Ocean w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w robienie fal. Niech woda chlapie dookoła. Magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia, spłynie z nim do kanalizacji i pogłębi jego sen.', title_pt = 'O oceano na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer ondas. Deixe a água salpicar à volta. O efeito magnético da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia, e tornar o sono dele mais profundo.', title_sv = 'Havet i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att göra vågor. Låt vattnet stänka. Vattnets magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet, och gör sömnen djupare.', title_vi = 'Đại dương trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo sóng. Cứ để nước bắn tung tóe. Sức hút kỳ diệu của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống và giúp bé ngủ sâu hơn.', title_zh = '浴缸里的海洋 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起浪花的游戏。让水花四溅吧。水那种磁力般的效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道，让宝宝睡得更沉。' WHERE id = 'ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Eres perfecta 🛑', body_es = '¿Te culpas al ver en redes a madres que cada día crean obras de arte con sus hijos y tienen la casa reluciente? No te creas esos filtros. Tu casa desordenada, ruidosa y real es para tu peque el nido de amor más cálido y perfecto.', title_fr = 'Vous êtes parfaite 🛑', body_fr = 'Vous vous jugez en voyant sur les réseaux sociaux des mamans qui créent chaque jour des œuvres d''art avec leur enfant dans une maison étincelante ? Ne croyez pas ces filtres. Votre maison en désordre, bruyante et bien réelle est pour votre enfant le nid d''amour le plus chaleureux et le plus parfait.', title_hi = 'आप कमाल हैं 🛑', body_hi = 'सोशल मीडिया पर रोज़ बच्चे के साथ कलाकृतियाँ बनाती, चमचमाते घर वाली माँओं को देखकर खुद को कोसती हैं? उन फ़िल्टरों पर यकीन मत कीजिए। आपका बिखरा, शोर भरा और असली घर आपके बच्चे के लिए सबसे गर्म, सबसे परफ़ेक्ट प्यार का घोंसला है।', title_id = 'Kamu sempurna 🛑', body_id = 'Anda menyalahkan diri saat melihat ibu-ibu di media sosial yang setiap hari membuat karya seni bersama anaknya dan rumahnya berkilau? Jangan percaya filter itu. Rumah Anda yang berantakan, berisik, dan nyata adalah sarang cinta paling hangat dan sempurna bagi anak Anda.', title_ja = 'あなたは完璧 🛑', body_ja = 'SNSで、毎日子どもと作品をつくり、家がぴかぴかのママたちを見て、自分を責めていませんか？そのフィルターを信じないで。散らかってにぎやかなリアルなあなたの家こそ、子どもにとっていちばんあたたかく完璧な愛の巣です。', title_ko = '엄마는 충분히 완벽해요 🛑', body_ko = 'SNS에서 매일 아이와 작품을 만들고 집이 반짝반짝한 엄마들을 보며 자책하나요? 그 필터를 믿지 마세요. 어질러지고 시끄러운 진짜 우리 집이 아이에게는 가장 따뜻하고 완벽한 사랑의 둥지예요.', title_nl = 'Je bent perfect 🛑', body_nl = 'Veroordeel je jezelf als je op social media mama''s ziet die elke dag kunstwerken maken met hun kind en een glimmend schoon huis hebben? Geloof die filters niet. Jouw rommelige, lawaaiige en echte huis is voor je kind het warmste, meest perfecte liefdesnest.', title_pl = 'Jesteś wspaniała 🛑', body_pl = 'Widzisz w mediach społecznościowych mamy, które codziennie tworzą z dzieckiem dzieła sztuki w lśniących domach, i się obwiniasz? Nie wierz w te filtry. Twój nieposprzątany, głośny i prawdziwy dom to dla dziecka najcieplejsze, najdoskonalsze gniazdo miłości.', title_pt = 'É perfeita 🛑', body_pt = 'Culpa-se ao ver nas redes sociais mães que todos os dias criam obras de arte com os filhos e têm a casa a brilhar? Não acredite nesses filtros. A sua casa desarrumada, barulhenta e real é, para o seu filho, o ninho de amor mais quente e perfeito.', title_sv = 'Du är perfekt 🛑', body_sv = 'Ser du mammor på sociala medier som varje dag skapar konstverk med sina barn och har skinande rena hem, och dömer dig själv? Tro inte på filtren. Ditt stökiga, bullriga och verkliga hem är det varmaste, mest perfekta kärleksboet för ditt barn.', title_vi = 'Mẹ là hoàn hảo 🛑', body_vi = 'Thấy những bà mẹ trên mạng xã hội ngày nào cũng cùng con tạo ra "kiệt tác", nhà cửa sáng bóng, mẹ lại tự trách mình? Đừng tin vào những bộ lọc ấy. Ngôi nhà bừa bộn, ồn ào và chân thật của mẹ chính là tổ ấm yêu thương ấm áp, hoàn hảo nhất cho con.', title_zh = '你已经很完美了 🛑', body_zh = '在社交网络上看到别的妈妈每天和孩子一起创作艺术品、家里一尘不染，就开始责怪自己？别相信那些滤镜。你那个乱糟糟、吵吵闹闹的真实的家，对孩子来说就是最温暖、最完美的爱巢。' WHERE id = '056e606b-664d-4a4e-94b5-81db6f2adf23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El argumento del pequeño abogado 🗣️', body_es = '«Quiero comer chocolate porque ya soy mayor». ¡Ya construye relaciones de causa y efecto para negociar y regatear contigo! Su desarrollo del habla es estupendo. Valóralo, pero protege también con cariño tus límites y tus normas.', title_fr = 'L''argument du petit avocat 🗣️', body_fr = '« Je mange du chocolat parce que je suis grand. » Il construit déjà des liens de cause à effet pour négocier et marchander avec vous ! Son langage progresse très bien. Félicitez-le, mais tenez aussi vos limites et vos règles avec douceur.', title_hi = 'नन्हे वकील की दलील 🗣️', body_hi = '‘चॉकलेट खाऊँ, क्योंकि मैं बड़ा हो गया हूँ।’ वह अब कारण-परिणाम जोड़कर आपसे समझौता, मोलभाव करने की कोशिश कर रहा है! बोलने का विकास शानदार है। उसकी तारीफ़ कीजिए, पर अपनी सीमाओं और नियमों की भी प्यार से रक्षा कीजिए।', title_id = 'Argumen si pengacara kecil 🗣️', body_id = '''Aku boleh makan cokelat, soalnya aku sudah besar.'' Ia sudah mencoba bernegosiasi dan tawar-menawar dengan Anda dengan menyusun hubungan sebab-akibat! Perkembangan bicaranya luar biasa. Hargai dia, tapi jaga batasan dan aturan Anda dengan ramah.', title_ja = '小さな弁護士の主張 🗣️', body_ja = '「チョコ食べていいよね、だってもう大きいもん」。原因と結果を組み立てて、あなたと交渉しようとしています！言葉の発達はすばらしいですね。ほめてあげつつ、あなたの境界線とルールもやさしく守りましょう。', title_ko = '꼬마 변호사의 논리 🗣️', body_ko = '''나 이제 컸으니까 초콜릿 먹을래.'' 원인과 결과를 엮어 엄마와 협상하고 흥정하려 하나요! 언어 발달이 훌륭해요. 칭찬해 주되 경계와 규칙은 다정하게 지켜 주세요.', title_nl = 'Het argument van de kleine advocaat 🗣️', body_nl = '''Ik mag chocola eten, want ik ben groot.'' Hij legt al verbanden tussen oorzaak en gevolg om met je te onderhandelen en af te dingen! Zijn taalontwikkeling is prima. Waardeer dat, maar bewaak ook vriendelijk je grenzen en regels.', title_pl = 'Argument małego adwokata 🗣️', body_pl = '„Zjem czekoladę, bo jestem już duży.” Już próbuje się z tobą dogadać i targować, budując związki przyczyny i skutku! Rozwój mowy jest świetny. Doceń go, ale życzliwie pilnuj swoich granic i zasad.', title_pt = 'O argumento do pequeno advogado 🗣️', body_pt = '"Quero comer chocolate porque já sou crescido." Já tenta negociar e regatear consigo, criando relações de causa-efeito! O desenvolvimento da fala é ótimo. Elogie-o, mas proteja com carinho os seus limites e regras.', title_sv = 'Den lilla advokatens argument 🗣️', body_sv = '”Jag ska äta choklad, för jag är stor.” Barnet kopplar redan ihop orsak och verkan och försöker förhandla och köpslå med dig! Talutvecklingen är utmärkt. Uppskatta det, men håll vänligt fast vid dina gränser och regler.', title_vi = 'Lý lẽ của "luật sư" nhí 🗣️', body_vi = '"Cho con ăn sô-cô-la, vì con lớn rồi." Bé đã biết dùng quan hệ nhân quả để thỏa thuận, mặc cả với mẹ! Khả năng ngôn ngữ thật tuyệt vời. Hãy khen bé, nhưng cũng nhẹ nhàng giữ vững giới hạn và quy tắc của mình.', title_zh = '小律师的论据 🗣️', body_zh = '“我要吃巧克力，因为我长大了。”宝宝已经在用因果关系和你谈判、讨价还价了！语言发展得很棒。夸夸宝宝吧，但也要温和地守住你的边界和规矩。' WHERE id = '156b6d8e-1bbe-4769-b258-c89d41a67564' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de silencio 🤫', body_es = '¡Por fin se ha dormido! Activa el Medidor de sonido y, mirando cómo bajan los números hasta 0 decibelios, siente cómo se despeja tu cerebro cansado y cómo te masajea este silencio visual.', title_fr = 'La thérapie par le silence 🤫', body_fr = 'Il dort enfin ! Activez le Sonomètre et, en regardant les chiffres descendre jusqu''à 0 décibel, sentez votre cerveau fatigué se vider et ce silence visuel vous masser.', title_hi = 'खामोशी से थेरेपी 🤫', body_hi = 'आखिरकार वह सो गया! साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0 डेसिबल तक गिरते अंक देखते हुए महसूस कीजिए कि आपका थका दिमाग कैसे हल्का हो रहा है और यह दिखती खामोशी कैसे आपकी मसाज करती है।', title_id = 'Terapi dengan hening 🤫', body_id = 'Akhirnya ia tertidur! Aktifkan Pengukur Suara dan perhatikan angka di layar turun hingga 0 desibel, rasakan bagaimana otak Anda yang lelah menjadi jernih dan keheningan visual ini memijat Anda.', title_ja = '静けさでセラピー 🤫', body_ja = 'やっと寝てくれました！「サウンドメーター」をオンにして、画面の数字が0デシベルまで下がっていくのを眺めましょう。疲れた脳がすっきりしていくのを、この目に見える静けさがマッサージしてくれるのを感じて。', title_ko = '고요 테라피 🤫', body_ko = '드디어 잠들었어요! 소음 측정기를 켜고 화면 속 숫자가 0데시벨까지 내려가는 걸 보며 지친 머리가 맑아지고 이 시각적인 고요가 마사지해 주는 걸 느껴 보세요.', title_nl = 'Therapie met stilte 🤫', body_nl = 'Hij slaapt eindelijk! Zet de Geluidsmeter aan, kijk hoe de getallen op het scherm tot 0 decibel zakken en voel hoe je vermoeide brein leeg wordt en hoe deze visuele stilte je masseert.', title_pl = 'Terapia ciszą 🤫', body_pl = 'W końcu zasnął! Włącz Miernik dźwięku i patrząc, jak liczby na ekranie spadają do 0 decybeli, poczuj, jak twój zmęczony mózg się oczyszcza, a ta wizualna cisza robi ci masaż.', title_pt = 'Terapia com silêncio 🤫', body_pt = 'Finalmente adormeceu! Ative o Medidor de Som e, a ver os números no ecrã descerem até aos 0 decibéis, sinta o seu cérebro cansado a limpar-se e este silêncio visual a fazer-lhe uma massagem.', title_sv = 'Terapi med tystnad 🤫', body_sv = 'Äntligen har barnet somnat! Aktivera verktyget Ljudmätare och följ siffrorna på skärmen som sjunker ner mot 0 decibel. Känn hur din trötta hjärna rensas och hur den visuella tystnaden masserar dig.', title_vi = 'Liệu pháp tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Hãy bật Đo âm thanh, nhìn những con số trên màn hình hạ dần về 0 decibel và cảm nhận đầu óc mỏi mệt của mình đang được làm sạch, sự tĩnh lặng hiện ra trước mắt đang mát-xa cho mẹ.', title_zh = '安静疗法 🤫', body_zh = '宝宝终于睡着了！打开分贝仪，看着屏幕上的数字一路降到0分贝，感受疲惫的大脑如何被清空，这份看得见的安静如何给你做按摩。' WHERE id = '838e23dd-ecaf-4568-9687-59518e77bc77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Accidente en la cocina 🧑‍🍳', body_es = 'Mientras extiendes la masa, viene, mete la mano en la harina y lo deja todo blanco. Sí, la cocina está hecha un desastre y tienes más trabajo. Pero graba al instante esa cara seria y trabajadora con la Sesión de fotos del bebé. La suciedad se irá, el recuerdo quedará.', title_fr = 'Accident en cuisine 🧑‍🍳', body_fr = 'Pendant que vous étalez la pâte, il plonge la main dans la farine et blanchit tout. Oui, la cuisine est sens dessus dessous et vous avez plus de travail. Mais immortalisez tout de suite son air sérieux et appliqué avec la Séance photo bébé. La saleté partira, le souvenir restera.', title_hi = 'रसोई में हादसा 🧑‍🍳', body_hi = 'आप आटा बेल रही हैं और वह आकर आटे में हाथ डालकर हर जगह सफ़ेद कर देता है। हाँ, रसोई गंदी हो गई, काम बढ़ गया। पर उसका वह गंभीर, कामकाजी चेहरा बेबी फ़ोटोशूट से तुरंत कैद कर लीजिए। गंदगी चली जाएगी, याद रह जाएगी।', title_id = 'Kecelakaan di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia datang, memasukkan tangan ke tepung, dan membuat semuanya putih. Ya, dapur berantakan dan pekerjaan Anda bertambah. Tapi segera abadikan wajahnya yang serius dan sibuk itu dengan Pemotretan Bayi. Kotorannya akan hilang, kenangannya akan tetap ada.', title_ja = 'キッチンの大惨事 🧑‍🍳', body_ja = 'あなたが生地をのばしていると、やってきて粉に手をつっこみ、あたりを真っ白に。そう、キッチンは粉だらけで仕事も増えました。でもその真剣でまじめな顔を、すぐに「ベビーフォトセッション」で撮っておきましょう。汚れは消えても、思い出は残ります。', title_ko = '부엌 사고 🧑‍🍳', body_ko = '반죽을 밀고 있는데 와서 밀가루에 손을 넣고 온 사방을 하얗게 만들었나요? 네, 부엌은 엉망이고 일은 늘었죠. 하지만 그 진지하고 바쁜 표정을 바로 아기 사진 촬영으로 담아 두세요. 얼룩은 사라져도 추억은 남아요.', title_nl = 'Ongelukje in de keuken 🧑‍🍳', body_nl = 'Terwijl jij deeg uitrolt, steekt hij zijn hand in de bloem en maakt alles spierwit. Ja, de keuken is een zooi en je hebt meer werk. Maar leg dat serieuze, zakelijke gezichtje meteen vast met de Babyfotoshoot. De rommel verdwijnt, de herinnering blijft.', title_pl = 'Katastrofa w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, wkłada rękę do mąki i wszystko robi się białe. Tak, kuchnia w opłakanym stanie, pracy przybyło. Ale od razu uwiecznij jego poważną, rzeczową minę w Sesji zdjęciowej dziecka. Brud zniknie, wspomnienie zostanie.', title_pt = 'Acidente na cozinha 🧑‍🍳', body_pt = 'Enquanto estende a massa, ele vem, mete a mão na farinha e deixa tudo branquinho. Sim, a cozinha ficou um caos e tem mais trabalho. Mas registe já aquela cara séria e trabalhadora com a Sessão Fotográfica do Bebé. A sujidade vai-se, a recordação fica.', title_sv = 'Olycka i köket 🧑‍🍳', body_sv = 'När du kavlar deg kommer barnet, sticker ner handen i mjölet och gör allt kritvitt. Ja, köket blev nedkladdat och du fick mer att göra. Men fånga genast barnets allvarliga, arbetsamma min med Babyfotografering. Smutsen försvinner, minnet stannar.', title_vi = 'Tai nạn trong bếp 🧑‍🍳', body_vi = 'Mẹ đang cán bột thì bé chạy đến thọc tay vào bột, làm mọi thứ trắng xóa. Đúng vậy, bếp bừa bộn, việc của mẹ tăng thêm. Nhưng hãy ghi lại ngay vẻ mặt nghiêm túc, chăm chỉ ấy của bé bằng Chụp ảnh cho bé. Vết bẩn sẽ hết, còn kỷ niệm thì ở lại.', title_zh = '厨房事故 🧑‍🍳', body_zh = '你擀面团时，宝宝跑过来把手伸进面粉里，弄得到处白茫茫。是的，厨房一团糟，你的活儿也多了。但马上用宝宝写真把宝宝那副认真能干的小表情拍下来吧。脏乱会过去，回忆会留下。' WHERE id = '1645ac24-40c0-4cef-8645-e26caf67a799' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siéntete orgullosa de ti 🚀', body_es = 'Al mirar atrás, ves en qué carácter tan fuerte se ha convertido. Hoy míralo largo rato y siéntete orgullosa de ti por criar a una persona tan maravillosa.', title_fr = 'Soyez fière de vous 🚀', body_fr = 'En regardant en arrière, vous voyez quel caractère fort il est devenu. Aujourd''hui, regardez-le longuement et soyez fière d''avoir élevé une si belle personne.', title_hi = 'खुद पर गर्व कीजिए 🚀', body_hi = 'पीछे मुड़कर देखती हैं तो दिखता है कि वह कितना मज़बूत स्वभाव वाला बन गया है। आज उसे देर तक निहारिए और इतना प्यारा इंसान बड़ा करने के लिए खुद पर गर्व कीजिए।', title_id = 'Banggalah pada diri Anda 🚀', body_id = 'Saat menoleh ke belakang, Anda melihat betapa ia telah tumbuh menjadi pribadi yang kuat. Hari ini pandangi ia lama-lama, dan banggalah pada diri Anda karena telah membesarkan manusia yang begitu baik.', title_ja = '自分を誇りに思って 🚀', body_ja = 'ふり返ってみると、この子がなんて強い個性に育ったかがわかります。今日はこの子をゆっくり見つめて、こんなにすてきな人を育ててきた自分を誇りに思いましょう。', title_ko = '나를 자랑스러워하세요 🚀', body_ko = '돌아보면 아이가 얼마나 강한 성격으로 자랐는지 보일 거예요. 오늘은 아이를 오래오래 바라보고, 이렇게 멋진 사람을 키워 낸 나 자신을 자랑스러워하세요.', title_nl = 'Wees trots op jezelf 🚀', body_nl = 'Als je terugkijkt, zie je wat een sterk karakter hij is geworden. Kijk vandaag lang naar hem en wees trots op jezelf dat je zo''n mooi mens grootbrengt.', title_pl = 'Bądź z siebie dumna 🚀', body_pl = 'Gdy patrzysz wstecz, widzisz, jak silny charakter z niego wyrósł. Popatrz dziś na niego długo i bądź z siebie dumna, że wychowujesz tak wspaniałego człowieka.', title_pt = 'Orgulhe-se de si 🚀', body_pt = 'Ao olhar para trás, vê como ele se tornou num caráter forte. Hoje olhe para ele demoradamente e orgulhe-se de si por estar a criar uma pessoa tão bonita.', title_sv = 'Var stolt över dig själv 🚀', body_sv = 'När du blickar tillbaka ser du vilken stark personlighet barnet har blivit. Titta länge på barnet i dag och var stolt över dig själv för att du har fostrat en så fin människa.', title_vi = 'Hãy tự hào về bản thân 🚀', body_vi = 'Nhìn lại, mẹ sẽ thấy bé đã trở thành một người có tính cách mạnh mẽ thế nào. Hôm nay hãy ngắm bé thật lâu và tự hào về bản thân vì đã nuôi dạy nên một con người tuyệt vời đến thế.', title_zh = '为自己骄傲 🚀', body_zh = '回头看看，你会发现宝宝已经成长为一个性格多么坚强的人。今天好好地多看看宝宝，为自己养大了这样一个美好的人而骄傲吧。' WHERE id = '58f0130e-9824-44fe-9963-a1e86c3e18cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gracias en equipo 🥂', body_es = 'Habéis dejado atrás otro día difícil y tormentoso. Cuando el peque se duerma, servíos un té tú y tu pareja y dile: «Hoy me has ayudado mucho, gracias». Criar no es cosa de uno solo: se vuelve bonito con un buen equipo.', title_fr = 'Merci, l''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une nouvelle journée difficile et agitée. Une fois l''enfant couché, servez-vous un thé avec votre partenaire et dites-lui : « Tu m''as beaucoup aidée aujourd''hui, merci. » Être parent, ça ne se fait pas seul, c''est plus beau avec une équipe solide.', title_hi = 'टीम का शुक्रिया 🥂', body_hi = 'एक और मुश्किल, तूफ़ानी दिन पीछे छूट गया। बच्चे के सोने के बाद अपने साथी के साथ चाय डालिए और कहिए, ‘आज तुमने मेरी बहुत मदद की, शुक्रिया।’ पेरेंटिंग अकेले नहीं, एक मज़बूत टीम के साथ खूबसूरत बनती है।', title_id = 'Terima kasih untuk tim 🥂', body_id = 'Kalian sudah melewati satu lagi hari yang berat dan penuh badai. Setelah anak tidur, tuang teh bersama pasangan dan katakan ''Hari ini kamu sangat membantuku, terima kasih''. Menjadi orang tua bukan perjalanan sendirian, ia menjadi indah dengan tim yang kuat.', title_ja = 'チームでありがとう 🥂', body_ja = '大変で嵐のような一日を、また乗りこえましたね。子どもが寝たら、パートナーとお茶をいれて「今日はたくさん助けてくれてありがとう」と伝えましょう。子育てはひとりではなく、いいチームでこそすてきになります。', title_ko = '팀에게 고마움을 🥂', body_ko = '또 하루, 힘들고 폭풍 같은 날을 보냈어요. 아이가 잠들면 배우자와 차 한 잔을 따르고 ''오늘 많이 도와줘서 고마워''라고 말해 주세요. 육아는 혼자가 아니라 든든한 팀과 함께할 때 아름다워져요.', title_nl = 'Bedankt, team 🥂', body_nl = 'Weer een zware, stormachtige dag achter de rug. Schenk als je kind slaapt een kop thee in met je partner en zeg: ''Je hebt me vandaag zo goed geholpen, dankjewel.'' Ouderschap doe je niet alleen, het wordt mooi met een gezond team.', title_pl = 'Podziękowanie dla drużyny 🥂', body_pl = 'Kolejny trudny i burzliwy dzień za wami. Gdy dziecko zaśnie, nalejcie sobie z partnerem herbaty i powiedz: „Bardzo mi dziś pomogłeś, dziękuję”. Rodzicielstwo nie jest w pojedynkę, piękne staje się w zgranej drużynie.', title_pt = 'Agradecimento de equipa 🥂', body_pt = 'Deixaram para trás mais um dia difícil e tempestuoso. Depois de a criança adormecer, sirvam um chá e diga ao seu companheiro: "Hoje ajudaste-me muito, obrigada". A parentalidade não fica bonita sozinha, mas com uma equipa saudável.', title_sv = 'Lagets tack 🥂', body_sv = 'Ännu en tuff och stormig dag ligger bakom er. När barnet har somnat, häll upp te med din partner och säg ”Du hjälpte mig så mycket i dag, tack”. Föräldraskap gör man inte ensam, det blir vackert med ett sunt lag.', title_vi = 'Lời cảm ơn của đồng đội 🥂', body_vi = 'Thêm một ngày khó khăn, sóng gió đã qua. Sau khi bé ngủ, hãy cùng chồng pha một ấm trà và nói: "Hôm nay anh đã giúp em rất nhiều, cảm ơn anh". Làm cha mẹ không phải hành trình một mình, mà đẹp hơn khi có một đội vững vàng.', title_zh = '团队的感谢 🥂', body_zh = '又一个艰难又暴风雨般的一天过去了。宝宝睡着后，和伴侣倒杯茶，说一句：“今天你帮了我很多，谢谢你。”育儿不是一个人的事，有一个健康的团队才会变得美好。' WHERE id = 'f65305c4-c08d-4180-9df9-53864d7df4a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Destellos de empatía 🧸', body_es = '¿Cuando se cae su juguete lo acaricia y le dice «no llores»? ¡Está naciendo su empatía! Anota sin falta esta etapa tan dulce en el Seguimiento del desarrollo.', title_fr = 'Les lueurs de l''empathie 🧸', body_fr = 'Quand son jouet tombe, il le caresse et lui dit « Pleure pas » ? Le sentiment d''empathie naît en lui ! Notez absolument cette jolie étape dans le Suivi de développement.', title_hi = 'सहानुभूति की झलक 🧸', body_hi = 'खिलौना गिरने पर उसे सहलाता है और कहता है, ‘मत रो’? उसमें सहानुभूति जाग रही है! इस प्यारे पड़ाव को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Percikan empati 🧸', body_id = 'Saat mainannya jatuh, ia mengelusnya dan berkata ''Jangan menangis''? Rasa empatinya mulai tumbuh! Pastikan mencatat tahap manis ini di Pelacak Perkembangan.', title_ja = '思いやりの芽生え 🧸', body_ja = 'おもちゃが倒れるとなでてあげて「泣かないで」と言う？思いやりの気持ちが育っています！このかわいい成長を、ぜひ「発達トラッカー」に記録しましょう。', title_ko = '공감의 불씨 🧸', body_ko = '장난감이 넘어지면 쓰다듬으며 ''울지 마'' 하나요? 공감 능력이 생기고 있어요! 이 사랑스러운 단계를 성장 기록에 꼭 남겨 두세요.', title_nl = 'Vonkjes van empathie 🧸', body_nl = 'Aait hij zijn speelgoed als het valt en zegt hij ''Niet huilen''? Er ontstaat empathie! Noteer deze lieve fase zeker in de Groeitracker.', title_pl = 'Iskierki empatii 🧸', body_pl = 'Gdy zabawka spada, głaszcze ją i mówi „Nie płacz”? Rodzi się w nim empatia! Koniecznie zapisz ten słodki etap w Śledzeniu rozwoju.', title_pt = 'Sinais de empatia 🧸', body_pt = 'Quando o brinquedo cai, faz-lhe festas e diz "Não chores"? Está a nascer nele a empatia! Não deixe de registar esta fase tão doce no Registo de Crescimento.', title_sv = 'Glimtar av empati 🧸', body_sv = 'Klappar barnet sin leksak när den ramlar och säger ”Gråt inte”? Empatin håller på att väckas! Anteckna absolut den söta fasen i Utvecklingsspåraren.', title_vi = 'Những tia đồng cảm 🧸', body_vi = 'Khi đồ chơi bị ngã, bé vuốt ve và nói "Đừng khóc"? Sự đồng cảm đang hình thành trong bé! Hãy nhớ ghi lại cột mốc đáng yêu này trong Theo dõi phát triển.', title_zh = '共情的火花 🧸', body_zh = '玩具摔倒时，会摸摸它说“别哭”？宝宝的共情能力正在萌芽！一定要把这个可爱的阶段记在发育追踪里。' WHERE id = '52fd1b46-da9f-4903-91e9-9855c04a5c68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa del revés 👗', body_es = '¿Quiere ponerse la camiseta con la parte de atrás delante sí o sí? No luches. Deja que un día ande así por casa, no rompas su voluntad.', title_fr = 'Vêtements à l''envers 👗', body_fr = 'Il veut absolument mettre son t-shirt devant derrière ? Ne luttez pas. Laissez-le se promener ainsi à la maison pour une journée, ne brisez pas sa volonté.', title_hi = 'उलटे कपड़े 👗', body_hi = 'हाथ की कमीज़ ज़रूर पीछे से आगे पहननी है? लड़ाई मत कीजिए। एक दिन घर में ऐसे ही घूमने दीजिए, उसकी इच्छा मत तोड़िए।', title_id = 'Baju terbalik 👗', body_id = 'Ia bersikeras memakai kausnya terbalik depan-belakang? Jangan melawan. Biarkan ia berkeliling rumah seperti itu satu hari, jangan patahkan kemauannya.', title_ja = '後ろ前の服 👗', body_ja = '手に持ったシャツを、どうしても後ろ前に着たがる？戦わないで。家の中なら一日そのままでもいいんです。意志をくじかないであげて。', title_ko = '거꾸로 입은 옷 👗', body_ko = '셔츠를 꼭 앞뒤 거꾸로 입겠다고 하나요? 싸우지 마세요. 하루쯤 집에서 그렇게 다니게 두고 의지를 꺾지 마세요.', title_nl = 'Achterstevoren kleren 👗', body_nl = 'Wil hij zijn shirt per se achterstevoren aantrekken? Ga de strijd niet aan. Laat hem een dagje zo thuis rondlopen en breek zijn wil niet.', title_pl = 'Ubrania na odwrót 👗', body_pl = 'Koniecznie chce założyć koszulkę tyłem do przodu? Nie walcz. Niech przez jeden dzień chodzi tak po domu, nie łam jego woli.', title_pt = 'Roupa ao contrário 👗', body_pt = 'Quer mesmo vestir a camisola com a frente para trás? Não lute. Deixe-o andar assim em casa por um dia, não quebre a vontade dele.', title_sv = 'Kläder bakfram 👗', body_sv = 'Vill barnet absolut ha tröjan bakfram? Börja inte bråka. Låt barnet gå så hemma en dag, knäck inte barnets vilja.', title_vi = 'Mặc ngược quần áo 👗', body_vi = 'Bé nhất định muốn mặc ngược áo, mặt sau ra trước? Đừng giằng co. Cứ để bé mặc như vậy ở nhà một ngày, đừng bẻ gãy ý chí của bé.', title_zh = '穿反的衣服 👗', body_zh = '非要把手里的衬衫前后反着穿？别较劲。就让宝宝这样在家里待一天吧，别挫伤宝宝的意志。' WHERE id = '8cc847d7-8dbe-41eb-84d4-4cb88879af35' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos frente a frente tú y tu pareja y desahogaos. Apoyaros el uno al otro reparte la carga justo por la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre partenaire et confiez-vous l''un à l''autre. Se soutenir divise vraiment la charge par deux.', body_hi = 'मुश्किल दिन के बाद अपने साथी के आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ देना बोझ को बिल्कुल आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung benar-benar membagi beban menjadi dua.', body_ja = '大変な一日のあとは、パートナーと向かい合って話を聞いてもらいましょう。支え合えば、重荷はちょうど半分になります。', body_ko = '힘든 하루가 끝나면 배우자와 마주 앉아 마음을 나누세요. 서로를 응원하면 짐이 정말 반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last echt.', body_pl = 'Po trudnym dniu usiądźcie z partnerem twarzą w twarz i wygadajcie się. Wzajemne wsparcie dzieli ciężar dokładnie na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e desabafem. Apoiarem-se um ao outro divide o peso exatamente a meio.', body_sv = 'Efter en tuff dag, sätt dig mitt emot din partner och prata av er. Att stötta varandra delar bördan helt på mitten.', body_vi = 'Sau một ngày khó khăn, hãy ngồi đối diện chồng và tâm sự. Hỗ trợ lẫn nhau sẽ chia đôi gánh nặng.', body_zh = '艰难的一天过后，和伴侣面对面坐下来聊聊心事。互相支持，能让肩上的担子减轻一半。' WHERE id = '8ec0eb18-27f1-4127-9c31-f0777f9a4904' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ingeniería de mantas 🛏️', body_es = 'Justo cuando se va a dormir, rompe a llorar: «¡Se ha doblado la punta de la manta!». Que la manta esté recta al milímetro es para él cuestión de vida o muerte. Respira hondo, estírala como si estuviera planchada y sonríe ante esta obsesión tan cómica.', title_fr = 'L''ingénierie de la couverture 🛏️', body_fr = 'Il est sur le point de s''endormir et se met soudain à pleurer : « Le coin de la couverture est plié ! » Pour lui, une couverture parfaitement plate au millimètre près est vitale. Respirez profondément, lissez la couverture comme si vous la repassiez et souriez simplement à cette manie comique.', title_hi = 'रज़ाई की इंजीनियरिंग 🛏️', body_hi = 'बस सोने ही वाला है कि अचानक रोने लगता है: ‘रज़ाई का कोना मुड़ गया!’ रज़ाई का मिलीमीटर तक सीधा होना उसके लिए ज़िंदगी-मौत का सवाल है। गहरी साँस लीजिए, रज़ाई को इस्त्री जैसा सीधा कीजिए और इस मज़ेदार सनक पर बस मुस्कुराइए।', title_id = 'Teknik selimut 🛏️', body_id = 'Tepat saat akan terlelap, tiba-tiba ia menangis: ''Ujung selimutnya terlipat!'' Kerapian selimut hingga ke milimeter sangat penting baginya. Tarik napas dalam, rapikan selimut itu seolah baru disetrika, dan tersenyumlah saja pada kerewelan lucu ini.', title_ja = '毛布のエンジニア 🛏️', body_ja = 'もう少しで寝つくところで、急に泣きだす：「毛布のはしが折れてる！」毛布がミリ単位でまっすぐなことが、この子には一大事なんです。深呼吸して、毛布をアイロンをかけたようにきれいに整え、このおかしなこだわりにただほほえみましょう。', title_ko = '이불 엔지니어링 🛏️', body_ko = '막 잠들려는데 갑자기 ''이불 끝이 접혔어!'' 하며 우나요? 이불이 밀리미터 단위로 반듯한 게 아이에게는 아주 중요해요. 깊게 숨 쉬고 다림질하듯 이불을 펴 준 뒤, 이 귀여운 집착에 그냥 미소 지어 주세요.', title_nl = 'Dekentechniek 🛏️', body_nl = 'Net als hij in slaap valt, begint hij ineens te huilen: ''Het puntje van de deken is omgevouwen!'' Dat de deken op de millimeter recht ligt, is voor hem van levensbelang. Haal diep adem, strijk die deken glad alsof hij gestreken is en glimlach gewoon om dit grappige perfectionisme.', title_pl = 'Inżynieria kołdry 🛏️', body_pl = 'Już ma zasnąć, a nagle zaczyna płakać: „Róg kołdry się zagiął!”. Idealnie, co do milimetra, wygładzona kołdra ma dla niego życiowe znaczenie. Weź głęboki oddech, wygładź kołdrę jak wyprasowaną i po prostu uśmiechnij się do tej zabawnej pedanterii.', title_pt = 'Engenharia do cobertor 🛏️', body_pt = 'Está quase a adormecer e de repente começa a chorar: "A ponta do cobertor dobrou-se!" O alinhamento milimétrico do cobertor é de importância vital para ele. Respire fundo, estique o cobertor como se estivesse passado a ferro e limite-se a sorrir a esta obsessão cómica.', title_sv = 'Täckeingenjören 🛏️', body_sv = 'Precis när barnet ska somna börjar det plötsligt gråta: ”Hörnet på täcket är vikt!” Att täcket ligger millimeterrakt är livsviktigt för barnet. Andas djupt, släta till täcket som om det vore struket och le bara åt den roliga noggrannheten.', title_vi = 'Kỹ sư chăn gối 🛏️', body_vi = 'Bé sắp ngủ thì bỗng bật khóc: "Góc chăn bị gấp rồi!". Với bé, chiếc chăn phẳng đến từng milimét là chuyện sống còn. Hãy hít thở sâu, vuốt phẳng chiếc chăn như vừa là ủi, và mỉm cười trước sự cầu toàn đáng yêu này.', title_zh = '被子工程学 🛏️', body_zh = '马上就要睡着了，突然哭了起来：“被子角折起来了！”被子平不平整到毫米，对宝宝来说是天大的事。深吸一口气，把被子弄得像熨过一样平，对这种搞笑的较真笑一笑就好。' WHERE id = '47e4625b-1969-49f3-9819-a17d4bddc0c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio sospechoso 🤫', body_es = 'De repente reina un silencio profundo en casa. El Medidor de sonido marca 0 decibelios. Si el peque está callado, es que en algún sitio está ocurriendo una gran exploración. Entra en la habitación psicológicamente preparada para ver dibujos en la pared o papeles recortados.', title_fr = 'Un silence suspect 🤫', body_fr = 'Un silence profond s''installe soudain dans la maison. Le Sonomètre affiche 0 décibel. Si l''enfant ne fait pas de bruit, c''est qu''une grande exploration est en cours quelque part. Entrez dans la pièce psychologiquement prête à découvrir des dessins sur les murs ou des papiers découpés.', title_hi = 'संदिग्ध खामोशी 🤫', body_hi = 'घर में अचानक गहरी खामोशी छा गई। साउंड मीटर 0 डेसिबल दिखा रहा है। बच्चा चुप है, मतलब कहीं कोई बड़ी खोजबीन चल रही है। दीवार पर बनी तस्वीरें या कटे कागज़ देखने के लिए मन से तैयार होकर कमरे में जाइए।', title_id = 'Hening yang mencurigakan 🤫', body_id = 'Tiba-tiba rumah menjadi sangat hening. Pengukur Suara menunjukkan 0 desibel. Jika anak diam, berarti ada penjelajahan besar sedang terjadi di suatu tempat. Masuklah ke kamar dengan kesiapan mental untuk melihat coretan di dinding atau kertas yang digunting.', title_ja = 'あやしい静けさ 🤫', body_ja = '家の中が急にしーんとしました。「サウンドメーター」は0デシベル。子どもが静かなら、どこかで大きな探検が進行中ということ。壁の落書きや切りきざまれた紙を見る心の準備をして、部屋に入りましょう。', title_ko = '수상한 고요 🤫', body_ko = '집에 갑자기 깊은 정적이 흐르고 소음 측정기가 0데시벨을 가리키나요? 아이가 조용하다면 어딘가에서 큰 탐험이 벌어지고 있다는 뜻이에요. 벽 낙서나 잘린 종이를 볼 마음의 준비를 하고 방에 들어가세요.', title_nl = 'Verdachte stilte 🤫', body_nl = 'Ineens is het doodstil in huis. De Geluidsmeter geeft 0 decibel aan. Als je kind stil is, vindt er ergens een grote ontdekkingstocht plaats. Ga de kamer binnen en wees mentaal voorbereid op tekeningen op de muur of geknipt papier.', title_pl = 'Podejrzana cisza 🤫', body_pl = 'W domu nagle zapadła głęboka cisza. Miernik dźwięku pokazuje 0 decybeli. Jeśli dziecko jest cicho, gdzieś trwa wielka wyprawa odkrywcza. Wejdź do pokoju psychicznie przygotowana na rysunki na ścianie albo pocięte kartki.', title_pt = 'Silêncio suspeito 🤫', body_pt = 'De repente caiu um silêncio profundo em casa. O Medidor de Som mostra 0 decibéis. Se a criança está calada, há uma grande exploração a decorrer algures. Entre no quarto psicologicamente preparada para ver desenhos na parede ou papéis recortados.', title_sv = 'Misstänkt tystnad 🤫', body_sv = 'Plötsligt blev det djupt tyst hemma. Ljudmätaren visar 0 decibel. Är barnet tyst pågår det en stor upptäcktsfärd någonstans. Gå in i rummet psykiskt förberedd på att se teckningar på väggen eller klippta papper.', title_vi = 'Sự im lặng đáng ngờ 🤫', body_vi = 'Căn nhà bỗng im phăng phắc. Đo âm thanh hiển thị 0 decibel. Nếu bé im lặng, nghĩa là đâu đó đang có một cuộc thám hiểm lớn. Hãy chuẩn bị tinh thần nhìn thấy tranh vẽ trên tường hoặc giấy bị cắt vụn khi bước vào phòng.', title_zh = '可疑的安静 🤫', body_zh = '家里突然一片死寂。分贝仪显示0分贝。孩子安静了，说明某个地方正在进行一场大探险。做好心理准备，看到墙上的涂鸦或剪碎的纸再走进房间吧。' WHERE id = '743bf968-dea7-4d72-ac2d-22654230f0a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No entres a discutir. 💼', body_es = '«No me como esas gachas porque son amarillas». Sostiene una lógica absurda tan impecable y convincente que casi te sentirás culpable. No entres a discutir. Gánate al abogado diciendo: «Tienes razón, son amarillas. ¿Y si les echamos frutos rojos?».', title_fr = 'N''entrez pas dans le débat. 💼', body_fr = '« Je mange pas cette bouillie, parce qu''elle est jaune ! » Sa logique absurde est si parfaite et si convaincante que vous vous sentiriez presque coupable. N''entrez pas dans le débat. Amadouez le petit avocat : « Tu as raison, elle est jaune. Et si on y ajoutait des fruits rouges ? »', title_hi = 'बहस में मत पड़िए। 💼', body_hi = '‘मैं वह दलिया नहीं खाऊँगा, क्योंकि वह पीला है!’ वह इतना बेदाग और भरोसेमंद बेतुका तर्क देता है कि आप खुद को लगभग दोषी मानने लगेंगी। बहस में मत पड़िए। ‘तुम सही हो, पीला है। अगर इसमें लाल बेरी डालें तो?’ कहकर वकील साहब को मना लीजिए।', title_id = 'Jangan ikut berdebat 💼', body_id = '''Aku nggak mau makan bubur itu, soalnya warnanya kuning!'' Ia menyusun logika absurd yang begitu sempurna dan meyakinkan sampai Anda hampir merasa bersalah. Jangan ikut berdebat. Ajak si pengacara kecil berdamai dengan berkata ''Kamu benar, warnanya kuning. Bagaimana kalau kita tambahkan buah beri merah?''.', title_ja = '言い合いはしないで。 💼', body_ja = '「このおかゆは食べない、だって黄色いから！」あまりに完璧で説得力のあるおかしな理屈に、自分が悪い気さえしてきます。言い合いはしないで。「そうだね、黄色いね。じゃあ赤いベリーを入れたらどうかな？」と言って、小さな弁護士を説得しましょう。', title_ko = '말다툼에 끼어들지 마세요. 💼', body_ko = '''그 죽은 노란색이라서 안 먹어!'' 너무 완벽하고 그럴듯한 엉뚱한 논리라 엄마가 잘못한 것 같기까지 하죠. 말다툼하지 마세요. ''맞아, 노랗네. 그럼 빨간 베리를 넣어 볼까?''라며 꼬마 변호사를 달래 보세요.', title_nl = 'Ga niet in discussie. 💼', body_nl = '''Ik eet die pap niet, want hij is geel!'' Hij brengt zo''n feilloze en overtuigende absurde logica dat je je bijna schuldig gaat voelen. Ga niet in discussie. Haal de advocaat over: ''Je hebt gelijk, hij is geel. Maar wat als we er rode bessen in doen?''', title_pl = 'Nie wdawaj się w kłótnię 💼', body_pl = '„Nie zjem tej kaszki, bo jest żółta!” Prowadzi tak bezbłędną i przekonującą absurdalną logikę, że prawie poczujesz się winna. Nie wdawaj się w kłótnię. Udobruchaj adwokata: „Masz rację, jest żółta. A może wrzucimy do niej czerwone jagódki?”.', title_pt = 'Não entre em discussões. 💼', body_pt = '"Não como essa papa porque é amarela!" Apresenta uma lógica absurda tão impecável e convincente que quase se sente culpada. Não entre em discussões. Convença o advogado: "Tens razão, é amarela. E se lhe pusermos frutos vermelhos?"', title_sv = 'Börja inte argumentera. 💼', body_sv = '”Jag äter inte gröten, för den är gul!” Barnet för fram en så felfri och övertygande absurd logik att du nästan känner dig skyldig. Börja inte argumentera. Säg ”Du har rätt, den är gul. Men om vi lägger i röda bär då?” och få advokaten med dig.', title_vi = 'Đừng sa vào tranh cãi. 💼', body_vi = '"Con không ăn cháo đó vì nó màu vàng!" Bé đưa ra lý lẽ ngộ nghĩnh mà hoàn hảo, thuyết phục đến mức mẹ suýt thấy mình có lỗi. Đừng tranh cãi. Hãy nói: "Con nói đúng, nó màu vàng. Thế mình cho thêm quả mọng đỏ vào thì sao?" để thuyết phục "luật sư" nhí.', title_zh = '别去争论。💼', body_zh = '“我不吃那碗粥，因为它是黄色的！”宝宝推出的荒诞逻辑如此严密又有说服力，你差点都觉得是自己错了。别去争论。说一句“你说得对，是黄色的。那我们往里面放点红色的浆果怎么样？”，就能把这位小律师哄好。' WHERE id = '9fa0703c-5759-4d65-aa22-1042aa7b5843' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El médico jefe de la casa 🩺', body_es = 'Coge su estetoscopio de juguete, te lo pone en el pecho, frunce el ceño y dice «no respires». Tú eres la paciente obediente. Aprovecha este juego de rol: cierra los ojos y, durante los 3 minutos de revisión, quédate tumbada en el suelo y descansa la espalda.', title_fr = 'Le médecin-chef de la maison 🩺', body_fr = 'Il prend son stéthoscope en plastique, le pose sur votre poitrine, fronce les sourcils et dit « Respire pas ». Vous êtes la patiente obéissante. Profitez de ce jeu de rôle : fermez les yeux et, pendant les 3 minutes de l''examen, restez simplement allongée par terre pour reposer votre dos.', title_hi = 'घर का मुख्य डॉक्टर 🩺', body_hi = 'खिलौने वाला स्टेथोस्कोप आपके सीने पर रखकर, भौंहें चढ़ाकर कहता है, ‘साँस मत लो।’ आप आज्ञाकारी मरीज़ हैं। इस खेल को मौका बनाइए, आँखें बंद करके 3 मिनट की जाँच के दौरान बस ज़मीन पर लेटकर कमर को आराम दीजिए।', title_id = 'Kepala dokter di rumah 🩺', body_id = 'Ia mengambil stetoskop mainan, menempelkannya ke dada Anda, mengerutkan alis, dan berkata ''Jangan bernapas''. Anda adalah pasien yang patuh. Jadikan permainan peran ini kesempatan: pejamkan mata dan berbaringlah saja di lantai selama pemeriksaan 3 menit untuk mengistirahatkan punggung.', title_ja = 'おうちのお医者さん 🩺', body_ja = 'おもちゃの聴診器をあなたの胸にあてて、眉をしかめ「息しないで」。あなたは言うことを聞く患者さんです。このごっこ遊びをチャンスにして、目を閉じ、3分間の診察中は床に寝ころんで腰を休めましょう。', title_ko = '우리 집 의사 선생님 🩺', body_ko = '장난감 청진기를 엄마 가슴에 대고 눈살을 찌푸리며 ''숨 쉬지 마''라고 하나요? 엄마는 말 잘 듣는 환자예요. 이 역할 놀이를 기회로 삼아 눈을 감고, 3분 진찰 동안 바닥에 누워 허리를 쉬게 하세요.', title_nl = 'De hoofdarts van het huis 🩺', body_nl = 'Hij zet zijn speelgoedstethoscoop op je borst, fronst en zegt: ''Niet ademen.'' Jij bent de gehoorzame patiënt. Maak van dit rollenspel een kans: doe je ogen dicht en laat tijdens het onderzoek van 3 minuten gewoon je rug rusten terwijl je op de grond ligt.', title_pl = 'Ordynator domu 🩺', body_pl = 'Bierze zabawkowy stetoskop, przykłada ci do piersi, marszczy brwi i mówi „Nie oddychaj”. Jesteś posłuszną pacjentką. Zamień tę zabawę w okazję: zamknij oczy i przez 3-minutowe badanie po prostu leż na podłodze, dając odpocząć plecom.', title_pt = 'O médico-chefe da casa 🩺', body_pt = 'Pega no estetoscópio de brincar, põe-lho no peito, franze a testa e diz "Não respire". A mãe é a paciente obediente. Aproveite esta brincadeira: feche os olhos e, durante os 3 minutos de consulta, fique simplesmente deitada no chão a descansar as costas.', title_sv = 'Hemmets överläkare 🩺', body_sv = 'Barnet tar sitt leksaksstetoskop, sätter det mot ditt bröst, rynkar pannan och säger ”Andas inte”. Du är den lydiga patienten. Gör rollleken till ett tillfälle: blunda och vila ryggen genom att bara ligga på golvet under den 3 minuter långa undersökningen.', title_vi = 'Bác sĩ trưởng của gia đình 🩺', body_vi = 'Bé cầm ống nghe đồ chơi đặt lên ngực mẹ, nhíu mày nói "Hít vào!". Mẹ là bệnh nhân ngoan ngoãn. Hãy biến trò nhập vai này thành cơ hội: nhắm mắt lại và chỉ nằm dài trên sàn suốt 3 phút "khám bệnh" để lưng được nghỉ ngơi.', title_zh = '家里的主任医生 🩺', body_zh = '拿起玩具听诊器放在你胸口，皱着眉说“别呼吸”。你是乖乖听话的病人。把这个角色扮演游戏变成机会吧，闭上眼睛，在3分钟的“检查”里就这样躺在地上，让腰休息一下。' WHERE id = '454d0433-fa13-4bd5-95fe-c40365aff560' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las cuerdas vocales de papá 📖', body_es = 'Hoy tienes la voz cansada y la garganta seca. Deja el cuento de la noche a papá. Contará una historia cómica e inventada que no tiene nada que ver con los dibujos del libro y hará que el peque se parta de risa. Y tú disfruta de la escena desde un lado con un té caliente.', title_fr = 'Les cordes vocales de papa 📖', body_fr = 'Aujourd''hui, votre voix est fatiguée et votre gorge sèche. Confiez le conte du soir à papa. Il racontera une histoire inventée et comique, complètement différente des images du livre, et l''enfant éclatera de rire. Vous, regardez cette jolie scène de loin avec un thé chaud.', title_hi = 'पापा की आवाज़ 📖', body_hi = 'आज आपकी आवाज़ थक गई है, गला सूख गया है। शाम की कहानी पापा को सौंप दीजिए। वे किताब की तस्वीर से बिल्कुल अलग, मज़ेदार गढ़ी हुई कहानी सुनाकर बच्चे को हँसा-हँसाकर लोटपोट कर देंगे। और आप इस प्यारे नज़ारे को एक तरफ़ से गरम चाय के साथ देखिए।', title_id = 'Pita suara Ayah 📖', body_id = 'Hari ini suaramu lelah, tenggorokanmu kering. Serahkan dongeng malam kepada Ayah. Ia akan mengarang cerita lucu yang sama sekali berbeda dari gambar di buku dan membuat anak tertawa terbahak-bahak. Kamu cukup menyaksikan pemandangan indah ini dari samping dengan teh hangat.', title_ja = 'パパの声 📖', body_ja = '今日は声が疲れて、のどもカラカラですね。夜の読み聞かせはパパにバトンタッチ。絵本の絵とはまったくちがう、おもしろい作り話で子どもを大笑いさせてくれるはず。あなたはこのほほえましい光景を、温かいお茶を片手にそばで眺めて。', title_ko = '아빠의 목소리 📖', body_ko = '오늘은 목이 지치고 말랐나요? 저녁 동화는 아빠에게 넘기세요. 아빠는 책 속 그림과 전혀 다른 웃기고 지어낸 이야기로 아이를 웃음바다에 빠뜨릴 거예요. 엄마는 이 즐거운 장면을 따뜻한 차와 함께 지켜보세요.', title_nl = 'Papa''s stembanden 📖', body_nl = 'Je stem is vandaag moe en je keel is droog. Draag het avondsprookje over aan papa. Hij vertelt een grappig, verzonnen verhaal dat totaal niet bij de plaatjes in het boek past, en je kind ligt dubbel van het lachen. En jij kijkt met een warme thee van een afstand naar dit fijne plaatje.', title_pl = 'Struny głosowe taty 📖', body_pl = 'Dziś twój głos jest zmęczony, a gardło suche. Przekaż wieczorną bajkę tacie. Opowie zupełnie inną niż na obrazkach w książce, zabawną i wymyśloną historię, a dziecko będzie się zaśmiewać. A ty obserwuj ten miły widok z boku z gorącą herbatą.', title_pt = 'As cordas vocais do pai 📖', body_pt = 'Hoje a sua voz está cansada e a garganta seca. Passe a história da noite para o pai. Ele vai contar uma história cómica e inventada, totalmente diferente das imagens do livro, e a criança vai desfazer-se em gargalhadas. E a mãe observa este quadro feliz de lado, com um chá quente.', title_sv = 'Pappas stämband 📖', body_sv = 'Din röst är trött i dag och halsen är torr. Lämna över kvällssagan till pappa. Han berättar en rolig och påhittad historia som är helt annorlunda än bilden i boken, så barnet kiknar av skratt. Och du, titta på den fina bilden från sidan med varmt te.', title_vi = 'Giọng kể của bố 📖', body_vi = 'Hôm nay giọng mẹ đã mỏi, cổ họng khô rát. Hãy giao việc kể chuyện buổi tối cho bố. Bố sẽ kể một câu chuyện tự nghĩ ra, hài hước và khác hẳn tranh trong sách, khiến bé cười ngặt nghẽo. Còn mẹ, hãy ngắm khung cảnh vui vẻ ấy từ xa bên cốc trà nóng.', title_zh = '爸爸的嗓子 📖', body_zh = '今天你的嗓子累了，喉咙也干了。把晚上的故事交给爸爸吧。他会讲一个和书里图画完全不同、搞笑又天马行空的故事，把宝宝逗得哈哈大笑。你就在一旁，端杯热茶欣赏这幅温馨的画面。' WHERE id = '603f7d3e-e83f-41b9-ade3-bd0fa858fbaf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Mamá, mira!» 👀', body_es = 'Salta del sofá y, haciendo el mismo movimiento exactamente 50 veces, dice cada vez: «¡Mamá, mírame!». Aparta los ojos del móvil. No salta por el movimiento en sí, sino por ese brillo de aprobación en tus ojos. Dale 5 minutos sin interrupciones para que se llene.', title_fr = 'La période du « Maman, regarde ! » 👀', body_fr = 'Il saute du canapé et refait exactement le même geste 50 fois en criant « Maman, regarde-moi ! ». Quittez le téléphone des yeux. Il ne saute pas pour le geste lui-même, mais pour cette lueur d''approbation dans vos yeux. Donnez-lui 5 minutes sans interruption, qu''il soit comblé.', title_hi = '‘माँ, देखो!’ का दौर 👀', body_hi = 'सोफ़े से कूदता है और पूरे 50 बार वही हरकत करके कहता है, ‘माँ, मुझे देखो!’ फ़ोन से नज़र हटाइए। वह हरकत के लिए नहीं, आपकी आँखों में शाबाशी की उस चमक के लिए कूदता है। उसे बिना रुकावट 5 मिनट दीजिए, ताकि उसका मन भर जाए।', title_id = 'Masa ''Ma, lihat!'' 👀', body_id = 'Ia melompat dari sofa, mengulang gerakan yang sama tepat 50 kali, dan setiap kali berkata ''Ma, lihat aku!''. Alihkan mata dari ponsel. Ia melompat bukan demi gerakannya, tapi demi kilau pengakuan di mata Anda. Beri ia 5 menit tanpa gangguan, biar ia puas.', title_ja = '「ママ、見て！」の時期 👀', body_ja = 'ソファからジャンプして、同じ動きをちょうど50回くり返すたびに「ママ、見て！」。スマホから目を離して。ジャンプそのもののためではなく、あなたの目に浮かぶ「すごいね」の輝きのために跳んでいるんです。とぎれない5分をあげて、満たしてあげましょう。', title_ko = '''엄마, 봐!'' 시기 👀', body_ko = '소파에서 뛰어내리며 똑같은 동작을 50번이나 하고 매번 ''엄마, 나 좀 봐!''라고 하나요? 휴대폰에서 눈을 떼세요. 동작 자체가 아니라 엄마 눈 속 인정의 반짝임을 위해 뛰는 거예요. 5분만 온전히 봐 주면 마음이 채워질 거예요.', title_nl = 'De ''Mama, kijk!''-fase 👀', body_nl = 'Hij springt van de bank en doet precies 50 keer hetzelfde, en elke keer roept hij ''Mama, kijk naar mij!''. Kijk weg van je telefoon. Hij springt niet om het springen, maar voor die glinstering van goedkeuring in jouw ogen. Geef hem 5 minuten ononderbroken aandacht, tot hij vol is.', title_pl = 'Etap „Mamo, patrz!” 👀', body_pl = 'Skacze z kanapy, powtarza ten sam ruch równo 50 razy i za każdym razem woła „Mamo, patrz na mnie!”. Oderwij wzrok od telefonu. Nie skacze dla samego ruchu, tylko dla tego błysku uznania w twoich oczach. Daj mu 5 minut nieprzerwanej uwagi, niech się nasyci.', title_pt = 'A fase do "Mãe, olha!" 👀', body_pt = 'Salta do sofá e, de cada vez, repete o mesmo movimento exatamente 50 vezes a dizer "Mãe, olha para mim!". Tire os olhos do telemóvel. Ele não salta pelo movimento em si, mas por aquele brilho de aprovação nos seus olhos. Dê-lhe 5 minutos sem interrupções e ele fica satisfeito.', title_sv = 'Perioden ”Mamma, titta!” 👀', body_sv = 'Barnet hoppar från soffan och gör samma sak precis 50 gånger och säger varje gång ”Mamma, titta på mig!”. Ta blicken från telefonen. Barnet hoppar inte för rörelsens skull, utan för bekräftelsen som glittrar i dina ögon. Ge barnet 5 oavbrutna minuter, så blir det mätt på det.', title_vi = 'Giai đoạn "Mẹ nhìn này!" 👀', body_vi = 'Bé nhảy từ sofa xuống, lặp lại đúng một động tác tới 50 lần và lần nào cũng nói "Mẹ ơi, nhìn con này!". Hãy rời mắt khỏi điện thoại. Bé nhảy không phải vì động tác, mà vì ánh mắt công nhận lấp lánh của mẹ. Hãy dành cho bé 5 phút trọn vẹn để bé thấy đủ đầy.', title_zh = '“妈妈，看！”时期 👀', body_zh = '从沙发上跳下来，同一个动作做了整整50遍，每次都喊“妈妈，看我！”。把目光从手机上移开。宝宝跳，不是为了动作本身，而是为了你眼中那一闪而过的肯定。给宝宝不被打断的5分钟，让宝宝满足吧。' WHERE id = 'e4995ac6-5e09-45b3-8f40-851f3616a9f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hipnosis musical 🎶', body_es = 'Han empezado las tormentas sin motivo del atardecer y las crisis de llanto. Apaga la tele, baja las luces y pon en la habitación una música clásica muy suave. La frecuencia profunda de la música cambiará el ambiente como por arte de magia y traerá calma a la habitación.', title_fr = 'Hypnose musicale 🎶', body_fr = 'Les tempêtes sans raison et les crises de larmes de fin de journée ont commencé. Éteignez la télé, baissez les lumières et mettez une musique classique très douce dans la pièce. La fréquence profonde de la musique changera l''atmosphère comme par magie et apportera la paix dans la pièce.', title_hi = 'संगीत का सम्मोहन 🎶', body_hi = 'शाम को बिना वजह के तूफ़ान, रोने के दौर शुरू हो गए हैं। टीवी बंद कीजिए, रोशनी धीमी कीजिए और कमरे में बहुत हल्का शास्त्रीय संगीत चलाइए। संगीत की वह गहरी तरंग माहौल को जादुई तरीके से बदल देगी और कमरे में सुकून लाएगी।', title_id = 'Hipnosis musik 🎶', body_id = 'Badai tanpa sebab dan krisis tangis menjelang malam sudah dimulai. Matikan TV, redupkan lampu, dan putar musik klasik yang sangat lembut di kamar. Frekuensi musik yang dalam akan mengubah suasana secara ajaib dan menghadirkan ketenangan di kamar.', title_ja = '音楽の催眠術 🎶', body_ja = '夕方のわけのわからない嵐や、泣きじゃくりが始まりました。テレビを消して明かりを落とし、部屋にとてもやさしいクラシック音楽を流しましょう。音楽の深い響きが空気を魔法のように変えて、部屋に落ち着きをもたらしてくれます。', title_ko = '음악 최면 🎶', body_ko = '저녁 무렵 이유 없는 폭풍과 울음이 시작됐나요? TV를 끄고 불을 낮춘 뒤 아주 잔잔한 클래식 음악을 틀어 주세요. 음악의 깊은 울림이 분위기를 마법처럼 바꾸고 방에 평온을 가져다줄 거예요.', title_nl = 'Muzikale hypnose 🎶', body_nl = 'De onverklaarbare stormen en huilbuien van eind van de middag zijn begonnen. Zet de tv uit, dim de lichten en zet heel zachte klassieke muziek op. De diepe frequentie van de muziek verandert de sfeer op magische wijze en brengt rust in de kamer.', title_pl = 'Muzyczna hipnoza 🎶', body_pl = 'Zaczęły się wieczorne burze bez powodu i kryzysy z płaczem. Wyłącz telewizor, przygaś światła i puść w pokoju bardzo cichą muzykę klasyczną. Głęboka częstotliwość muzyki magicznie zmieni atmosferę i wniesie do pokoju spokój.', title_pt = 'Hipnose musical 🎶', body_pt = 'Começaram as tempestades sem razão e as crises de choro do fim da tarde. Desligue a televisão, baixe as luzes e ponha no quarto uma música clássica muito suave. A frequência profunda da música vai mudar o ambiente como por magia e trazer calma ao quarto.', title_sv = 'Musikalisk hypnos 🎶', body_sv = 'Omotiverade stormar och gråtkriser framåt kvällen har börjat. Stäng av tv:n, dämpa ljuset och sätt på mycket lätt klassisk musik i rummet. Musikens djupa frekvens förändrar stämningen magiskt och ger rummet lugn.', title_vi = 'Thôi miên bằng âm nhạc 🎶', body_vi = 'Những cơn bùng nổ vô cớ, những trận khóc lúc chiều tối đã bắt đầu. Hãy tắt tivi, giảm đèn và bật thật khẽ một bản nhạc cổ điển nhẹ nhàng. Tần số sâu lắng của âm nhạc sẽ thay đổi bầu không khí một cách kỳ diệu và mang lại bình yên cho căn phòng.', title_zh = '音乐催眠 🎶', body_zh = '傍晚莫名的小风暴和哭闹开始了。关掉电视，把灯光调暗，在房间里放一点很轻柔的古典音乐。音乐深沉的频率会神奇地改变气氛，给房间带来安宁。' WHERE id = '41b57fa8-5ee9-47c4-bdaf-6650d5ddc287' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Guionista de dibujos animados 📺', body_es = 'Te cuenta los dibujos que ha visto con una trama tan distinta y tan convincente que casi te lo crees. Se está formando una imaginación perfecta.', title_fr = 'Le scénariste de dessins animés 📺', body_fr = 'Il vous raconte le dessin animé qu''il a vu avec une intrigue si différente et de façon si convaincante que vous allez presque y croire. Une imagination formidable est en train de se former.', title_hi = 'कार्टून का पटकथा लेखक 📺', body_hi = 'जो कार्टून देखा, उसे ऐसी अलग कहानी के साथ, इतने भरोसे से सुनाता है कि आप लगभग यकीन कर लेंगी। एक शानदार कल्पना आकार ले रही है।', title_id = 'Penulis skenario kartun 📺', body_id = 'Ia menceritakan kartun yang ditontonnya dengan alur yang begitu berbeda dan meyakinkan sampai Anda hampir percaya. Imajinasi yang hebat sedang terbentuk.', title_ja = 'アニメの脚本家 📺', body_ja = '見たアニメの話を、まったくちがうストーリーで、思わず信じてしまいそうなほど説得力たっぷりに説明してくれます。すばらしい想像力が育っています。', title_ko = '만화 시나리오 작가 📺', body_ko = '본 만화를 전혀 다른 줄거리로 어찌나 그럴듯하게 설명하는지 엄마도 믿을 뻔하죠. 멋진 상상력이 자라고 있어요.', title_nl = 'Tekenfilmscenarist 📺', body_nl = 'Hij vertelt de tekenfilm die hij keek met zo''n ander verhaal en zo overtuigend na, dat je het bijna gelooft. Er ontwikkelt zich een geweldige fantasie.', title_pl = 'Scenarzysta bajek 📺', body_pl = 'Opowiada ci obejrzaną bajkę z zupełnie inną fabułą i tak przekonująco, że prawie w to uwierzysz. Kształtuje się wspaniała wyobraźnia.', title_pt = 'Argumentista de desenhos animados 📺', body_pt = 'Explica-lhe os desenhos animados que viu com um enredo tão diferente e de forma tão convincente que quase acredita. Está a formar-se uma imaginação perfeita.', title_sv = 'Manusförfattare till tecknad film 📺', body_sv = 'Barnet återberättar tecknade filmen med en så annorlunda handling och så övertygande att du nästan tror på det. En fantastisk fantasi håller på att formas.', title_vi = 'Biên kịch phim hoạt hình 📺', body_vi = 'Bé kể lại bộ phim hoạt hình vừa xem với một cốt truyện khác hẳn, thuyết phục đến mức mẹ suýt tin. Một trí tưởng tượng tuyệt vời đang hình thành.', title_zh = '动画片编剧 📺', body_zh = '给你讲正在看的动画片，讲出一个完全不同的剧情，而且讲得那么有说服力，你都快信了。宝宝的想象力正在完美地成形。' WHERE id = 'bfa22ff0-d771-4756-a950-034bebcc6d6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El botón de reinicio de mamá 🚪', body_es = 'El ruido te taladra el cerebro y te dan ganas de gritar por todo. Abre el Diario de ánimo. Escribe ahí libremente todo tu agotamiento. Esta breve terapia digital te volverá a reiniciar.', title_fr = 'Le bouton reset de maman 🚪', body_fr = 'Le bruit vous transperce le cerveau, vous avez envie de crier sur tout. Ouvrez le Journal d''humeur. Écrivez-y librement tout votre épuisement. Cette courte thérapie numérique vous remettra à zéro.', title_hi = 'माँ का रीसेट बटन 🚪', body_hi = 'शोर दिमाग में चुभ रहा है, हर बात पर चिल्लाने का मन है। मूड डायरी खोलिए। अपनी सारी थकान खुलकर वहाँ लिखिए। यह छोटी डिजिटल थेरेपी आपको फिर से रीसेट कर देगी।', title_id = 'Tombol reset Ibu 🚪', body_id = 'Kebisingan menembus otak Anda, Anda ingin berteriak pada segala hal. Buka Buku Harian Suasana Hati. Tuliskan semua rasa lelah Anda di sana dengan bebas. Terapi digital singkat ini akan me-reset Anda kembali.', title_ja = 'ママのリセットボタン 🚪', body_ja = '騒がしさが頭に突きささり、何にでも叫びたくなる。「気分日記」を開きましょう。疲れきった気持ちを全部自由に書きだして。この短いデジタルセラピーが、あなたをもう一度リセットしてくれます。', title_ko = '엄마의 리셋 버튼 🚪', body_ko = '소음이 머리를 뚫고 모든 것에 소리치고 싶나요? 기분 일기를 열고 지친 마음을 자유롭게 적어 보세요. 이 짧은 디지털 치료가 엄마를 다시 리셋해 줄 거예요.', title_nl = 'Mama''s resetknop 🚪', body_nl = 'Het lawaai boort door je hoofd en je wilt tegen alles schreeuwen. Open je Stemmingsdagboek. Schrijf daar vrijuit al je uitputting op. Deze korte digitale therapie zet je weer op reset.', title_pl = 'Przycisk reset dla mamy 🚪', body_pl = 'Hałas świdruje ci w głowie, chce ci się krzyczeć na wszystko. Otwórz Dziennik nastroju. Wypisz tam swobodnie całe swoje wyczerpanie. Ta krótka cyfrowa terapia znów cię zresetuje.', title_pt = 'O botão Reset da mãe 🚪', body_pt = 'O barulho fura-lhe o cérebro e apetece-lhe gritar com tudo. Abra o Diário de Humor. Escreva lá à vontade todo o seu esgotamento. Esta curta terapia digital vai fazer-lhe um reset.', title_sv = 'Mammas återställningsknapp 🚪', body_sv = 'Oljudet borrar sig in i hjärnan och du vill skrika åt allt. Öppna Humördagboken. Skriv fritt ner all din utmattning där. Den här korta digitala terapin återställer dig igen.', title_vi = 'Nút "Reset" của mẹ 🚪', body_vi = 'Tiếng ồn như khoan vào đầu, mẹ muốn hét lên với mọi thứ. Hãy mở Nhật ký tâm trạng. Viết thoải mái mọi kiệt sức của mình vào đó. Liệu pháp số ngắn ngủi này sẽ giúp mẹ "khởi động lại".', title_zh = '妈妈的“重启”按钮 🚪', body_zh = '噪音快把脑袋钻穿了，你看什么都想吼。打开心情日记，把所有的疲惫都自由地写进去。这短短的数字疗愈，会帮你重新“重启”。' WHERE id = 'd113ec32-8781-4153-b853-ad718dad74e9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra de agua de papá 🛁', body_es = 'Esta noche el ritual del baño es cosa de papá. Deja que salpiquen agua por todas partes y tú, detrás de la puerta, disfruta del silencio total.', title_fr = 'La bataille d''eau de papa 🛁', body_fr = 'Ce soir, le rituel du bain est entièrement confié à papa. Laissez-les éclabousser partout, et vous, savourez le silence total derrière la porte.', title_hi = 'पापा की पानी वाली जंग 🛁', body_hi = 'आज शाम नहाने की रस्म पूरी तरह पापा की ज़िम्मेदारी है। उन्हें चारों ओर पानी छिटकाने दीजिए, और आप दरवाज़े के पीछे पूरी खामोशी का मज़ा लीजिए।', title_id = 'Perang air bersama Ayah 🛁', body_id = 'Malam ini ritual mandi sepenuhnya tanggung jawab Ayah. Biarkan mereka memercikkan air ke mana-mana, sementara Anda menikmati keheningan total di balik pintu.', title_ja = 'パパの水かけバトル 🛁', body_ja = '今夜のお風呂タイムは、完全にパパの担当です。水しぶきを飛ばして遊んでもらって、あなたはドアの向こうで完全な静けさを味わいましょう。', title_ko = '아빠의 물싸움 🛁', body_ko = '오늘 저녁 목욕 의식은 온전히 아빠 몫이에요. 둘이 물을 사방으로 튀기게 두고, 엄마는 문 밖에서 완전한 고요를 즐기세요.', title_nl = 'Papa''s watergevecht 🛁', body_nl = 'Vanavond is het badritueel helemaal aan papa. Laat ze het water maar rondspetteren, en geniet jij achter de deur van de complete stilte.', title_pl = 'Wodna bitwa taty 🛁', body_pl = 'Dzisiejszy rytuał kąpieli jest całkowicie na głowie taty. Niech chlapią wodą dookoła, a ty za drzwiami delektuj się pełną ciszą.', title_pt = 'A guerra de água do pai 🛁', body_pt = 'Esta noite o ritual do banho fica totalmente a cargo do pai. Deixe-os salpicar água à volta e saboreie o silêncio total do outro lado da porta.', title_sv = 'Pappas vattenkrig 🛁', body_sv = 'I kväll är badritualen helt pappas ansvar. Låt dem stänka vatten runt omkring, och du njuter av den totala tystnaden bakom dörren.', title_vi = 'Trận chiến nước của bố 🛁', body_vi = 'Tối nay, giờ tắm hoàn toàn do bố đảm nhận. Cứ để hai bố con té nước tung tóe, còn mẹ tận hưởng sự yên tĩnh tuyệt đối sau cánh cửa.', title_zh = '爸爸的水仗 🛁', body_zh = '今晚的洗澡仪式全部交给爸爸。让他们把水溅得到处都是，你就在门外好好享受彻底的安静吧。' WHERE id = '15c2d5ec-3e4a-4b1d-b6d2-a891cc587847' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rebelión del armario 🥽', body_es = 'Quiere andar por casa con gafas de natación y gorro de invierno. Insiste y no se los quita. Olvida las normas sociales. Para no romper su creatividad ni su libertad de decidir, deja que pase el día con ese conjunto tan distinto y cómico.', title_fr = 'La révolte de la garde-robe 🥽', body_fr = 'Il veut se promener dans la maison avec des lunettes de natation et un bonnet d''hiver. Il insiste et refuse de les enlever. Oubliez les normes sociales. Pour ne pas briser sa créativité et sa liberté de décider, laissez-le passer la journée dans cette tenue originale et comique.', title_hi = 'अलमारी की बगावत 🥽', body_hi = 'घर में स्विमिंग चश्मा और सर्दियों की टोपी पहनकर घूमना चाहता है। ज़िद करता है, उतारता नहीं। लोगों के कायदे भूल जाइए। उसकी रचनात्मकता और फ़ैसले की आज़ादी न टूटे, इसलिए उसे आज का दिन इसी अनोखे, मज़ेदार पहनावे में बिताने दीजिए।', title_id = 'Pemberontakan lemari baju 🥽', body_id = 'Ia ingin berkeliling rumah memakai kacamata renang dan topi musim dingin. Ia ngotot dan tidak mau melepasnya. Lupakan norma sosial. Agar kreativitas dan kebebasannya memutuskan tidak patah, biarkan ia melewati hari dengan setelan unik dan lucu itu.', title_ja = 'クローゼットの反乱 🥽', body_ja = '家の中で水泳ゴーグルと冬の帽子をつけて歩きたがり、ゆずらず、はずさない。世間の常識は忘れましょう。創造力と自分で決める自由をくじかないように、そのちょっと変わったおもしろいコーデで一日を過ごさせてあげて。', title_ko = '옷장 반란 🥽', body_ko = '집 안에서 수경과 겨울 모자를 쓰고 다니겠다며 절대 벗지 않나요? 사회적 기준은 잊으세요. 창의력과 선택의 자유를 꺾지 않도록 그 독특하고 웃긴 차림으로 하루를 보내게 해 주세요.', title_nl = 'Opstand in de kledingkast 🥽', body_nl = 'Hij wil in huis rondlopen met een zwembril en een wintermuts. Hij houdt vol en zet ze niet af. Vergeet wat ''hoort''. Laat hem de dag in die aparte, grappige outfit doorbrengen, zodat je zijn creativiteit en keuzevrijheid niet breekt.', title_pl = 'Bunt w garderobie 🥽', body_pl = 'Chce chodzić po domu w okularach do pływania i zimowej czapce. Upiera się i nie zdejmuje. Zapomnij o normach społecznych. Żeby nie łamać jego kreatywności i swobody decydowania, niech spędzi dzień w tym nietypowym, zabawnym zestawie.', title_pt = 'Revolta no guarda-roupa 🥽', body_pt = 'Quer andar pela casa com óculos de natação e gorro de inverno. Insiste e não os tira. Esqueça as normas sociais. Para não quebrar a criatividade e a liberdade de decidir, deixe-o passar o dia com esse visual diferente e cómico.', title_sv = 'Garderobsuppror 🥽', body_sv = 'Barnet vill gå runt hemma i simglasögon och vintermössa. Barnet insisterar och tar inte av dem. Glöm samhällets normer. För att inte knäcka barnets kreativitet och frihet att bestämma, låt barnet tillbringa dagen i den annorlunda, roliga klädseln.', title_vi = 'Cuộc nổi loạn tủ quần áo 🥽', body_vi = 'Bé muốn đi lại trong nhà với kính bơi và mũ len mùa đông. Bé nhất quyết không cởi ra. Hãy quên chuẩn mực xã hội đi. Để không bẻ gãy sự sáng tạo và quyền tự quyết của bé, cứ để bé trải qua ngày với bộ đồ khác lạ, hài hước ấy.', title_zh = '衣柜大叛乱 🥽', body_zh = '想在家里戴着泳镜和冬天的帽子走来走去。坚持不肯摘。忘掉那些社会规范吧。为了不挫伤宝宝的创造力和自己做决定的自由，就让宝宝穿着这身与众不同又搞笑的搭配过一天吧。' WHERE id = '2054a805-49e3-459b-8315-84f392392707' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa en el carro del súper 🛒', body_es = 'Al llegar a la caja, del carro han salido 3 chocolates distintos y una pastilla de jabón con forma rara que tú no elegiste. Devuélvelos con una maniobra rápida. Y para no olvidar nada, ten siempre un ojo en la Lista de la compra y no te desvíes del objetivo.', title_fr = 'Surprise dans le chariot 🛒', body_fr = 'En arrivant à la caisse, vous trouvez dans le chariot 3 chocolats différents et un savon à la forme bizarre que vous n''avez pas choisis. Remettez-les en place d''une manœuvre rapide. Et contre les oublis, gardez toujours un œil sur la Liste de courses pour ne pas perdre le cap.', title_hi = 'शॉपिंग ट्रॉली का सरप्राइज़ 🛒', body_hi = 'काउंटर के पास पहुँचीं तो ट्रॉली से 3 अलग चॉकलेट और एक अजीब आकार का साबुन निकला, जो आपने नहीं चुने थे। फुर्ती से वे चीज़ें वापस रखिए। और भूलने से बचने के लिए नज़र हमेशा शॉपिंग लिस्ट पर रखिए, ताकि निशाने से न भटकें।', title_id = 'Kejutan troli belanja 🛒', body_id = 'Saat mendekati kasir, dari troli muncul 3 cokelat berbeda dan 1 sabun berbentuk aneh yang tidak Anda pilih. Kembalikan barang-barang itu dengan manuver cepat. Untuk melawan lupa, pastikan mata Anda selalu pada Daftar Belanja agar tidak melenceng dari tujuan.', title_ja = 'ショッピングカートのサプライズ 🛒', body_ja = 'レジに近づくと、カートからあなたが選んでいないチョコが3種類と、へんな形の石けんがひとつ出てきた。すばやくもとの場所に戻しましょう。買い忘れ防止には、いつも「買い物リスト」に目を向けて、目的を見失わないようにね。', title_ko = '마트 카트 속 깜짝 선물 🛒', body_ko = '계산대에 다가가니 카트에서 엄마가 고르지 않은 초콜릿 3개와 이상한 모양의 비누 1개가 나왔나요? 재빠르게 제자리로 돌려놓으세요. 깜빡하지 않게 늘 쇼핑 목록을 보며 목표에서 벗어나지 마세요.', title_nl = 'Verrassing in het boodschappenkarretje 🛒', body_nl = 'Bij de kassa komen er uit je karretje 3 verschillende chocoladerepen en 1 raar gevormd stuk zeep die jij niet koos. Breng ze met een snelle manoeuvre terug. En tegen vergeetachtigheid: houd je ogen op het Boodschappenlijstje, zodat je niet van je doel afwijkt.', title_pl = 'Niespodzianka w sklepowym wózku 🛒', body_pl = 'Przy kasie z wózka wyłoniły się 3 różne czekolady i mydełko o dziwnym kształcie, których nie wybierałaś. Szybkim manewrem odłóż je z powrotem. A na zapominalstwo miej oko na Liście zakupów, żeby nie zboczyć z celu.', title_pt = 'A surpresa do carrinho de compras 🛒', body_pt = 'Ao chegar à caixa, saíram do carrinho 3 chocolates diferentes e um sabonete de forma estranha que não escolheu. Devolva-os com uma manobra rápida. E contra os esquecimentos, mantenha os olhos sempre na Lista de Compras para não se desviar do objetivo.', title_sv = 'Överraskning i kundvagnen 🛒', body_sv = 'När ni närmar er kassan dyker 3 olika chokladkakor och en konstigt formad tvål som du inte valt upp ur kundvagnen. Ställ snabbt tillbaka sakerna. Och mot glömskan, ha alltid blicken på Inköpslistan så att du inte tappar målet.', title_vi = 'Bất ngờ trong xe đẩy siêu thị 🛒', body_vi = 'Khi đến gần quầy thanh toán, từ xe đẩy lôi ra 3 loại sô-cô-la khác nhau và 1 bánh xà phòng hình thù kỳ lạ mà mẹ không hề chọn. Hãy nhanh tay trả chúng về chỗ cũ. Còn để khỏi quên đồ, hãy luôn để mắt đến Danh sách mua sắm để không đi chệch mục tiêu.', title_zh = '购物车里的惊喜 🛒', body_zh = '快到收银台时，购物车里冒出了3种你没挑过的巧克力和1块形状奇怪的香皂。迅速出手把它们放回去。至于健忘，眼睛要一直盯着购物清单，才不会偏离目标。' WHERE id = '5be61e62-9e95-417b-9db3-15386a93c72a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El audífono se ha apagado 🙉', body_es = 'Le dices «recoge los juguetes», «ven a lavarte las manos» y la reacción es cero. Hacerse el sordo es el pasatiempo favorito de los 3 años. En lugar de gritar, acércate y susúrrale al oído con una voz muy fina. El cambio repentino de tono captará su atención al instante.', title_fr = 'L''appareil auditif est éteint 🙉', body_fr = 'Vous dites « Range tes jouets », « Viens te laver les mains », et zéro réaction. Faire la sourde oreille est le passe-temps préféré des 3 ans. Au lieu de crier, approchez-vous et chuchotez-lui à l''oreille d''une voix très douce. Le changement soudain de ton attirera aussitôt son attention.', title_hi = 'सुनने की मशीन बंद 🙉', body_hi = '‘खिलौने समेटो’, ‘आओ हाथ धो लो’ कहती हैं, पर कोई प्रतिक्रिया नहीं। अनसुना करना 3 साल का सबसे पसंदीदा शौक है। चिल्लाने के बजाय पास जाइए और कान में बहुत नरम आवाज़ में फुसफुसाइए। लहजे का अचानक बदलना उसका ध्यान तुरंत खींच लेगा।', title_id = 'Alat pendengaran sedang mati 🙉', body_id = 'Anda berkata ''Bereskan mainanmu'', ''Ayo cuci tangan'', dan reaksinya nol. Pura-pura tidak mendengar adalah hobi favorit anak 3 tahun. Daripada berteriak, datangi ia dan berbisiklah dengan sangat lembut di telinganya. Perubahan nada suara yang tiba-tiba akan langsung menarik perhatiannya.', title_ja = '聞こえないスイッチ、オフ 🙉', body_ja = '「おもちゃを片づけて」「手を洗いにおいで」と言っても、反応はゼロ。聞こえないふりは3歳のいちばん好きな趣味です。叫ぶ代わりにそばへ行って、耳もとでとてもやさしい声でささやいてみて。急に声のトーンが変わると、すぐに注意をひきつけられます。', title_ko = '보청기가 꺼졌어요 🙉', body_ko = '''장난감 정리해'', ''와서 손 씻자'' 해도 반응이 전혀 없나요? 못 들은 척하기는 세 살의 가장 좋아하는 취미예요. 소리치는 대신 다가가 귓가에 아주 부드럽게 속삭여 보세요. 갑자기 바뀐 목소리가 바로 관심을 끌 거예요.', title_nl = 'Gehoorapparaat uitgeschakeld 🙉', body_nl = 'Je zegt ''Ruim je speelgoed op'' of ''Kom je handen wassen'', en er komt nul reactie. Oostindisch doof zijn is de favoriete hobby van een 3-jarige. Ga niet schreeuwen, maar loop naar hem toe en fluister heel zacht in zijn oor. De plotselinge verandering in toon trekt meteen zijn aandacht.', title_pl = 'Aparat słuchowy wyłączony 🙉', body_pl = 'Mówisz „Posprzątaj zabawki”, „Chodź umyć ręce”, a reakcja zerowa. Udawanie, że nie słyszy, to ulubione hobby 3-latka. Zamiast krzyczeć, podejdź i wyszeptaj mu do ucha bardzo cichutko. Nagła zmiana tonu od razu przyciągnie jego uwagę.', title_pt = 'O aparelho auditivo desligou-se 🙉', body_pt = 'Diz "Arruma os brinquedos", "Vem lavar as mãos" e a reação é zero. Fazer-se de surdo é o passatempo preferido dos 3 anos. Em vez de gritar, vá até ele e sussurre-lhe ao ouvido com uma voz muito suave. A mudança repentina no tom de voz vai captar logo a atenção dele.', title_sv = 'Hörapparaten är avstängd 🙉', body_sv = 'Du säger ”Plocka upp leksakerna” och ”Kom och tvätta händerna”, och reaktionen är noll. Att låtsas inte höra är 3-åringens favorithobby. Istället för att skrika, gå fram och viska mycket mjukt i barnets öra. Den plötsliga förändringen i rösten fångar genast barnets uppmärksamhet.', title_vi = 'Máy trợ thính đã tắt 🙉', body_vi = 'Mẹ nói "Dọn đồ chơi đi", "Lại đây rửa tay nào", phản ứng bằng không. Giả vờ không nghe là sở thích yêu thích nhất của tuổi lên 3. Thay vì quát, hãy đến gần và thì thầm thật khẽ vào tai bé. Sự thay đổi giọng điệu bất ngờ sẽ thu hút sự chú ý của bé ngay lập tức.', title_zh = '“听力设备”关机了 🙉', body_zh = '你说“收玩具”“过来洗手”，反应为零。装没听见是3岁最爱的爱好。别吼，走到宝宝身边，在耳边用很轻的声音悄悄说。语气的突然变化，会马上吸引宝宝的注意。' WHERE id = '22ac2508-9b42-4e19-b15b-cc1dca8c750b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Chantaje en el baño 🛀', body_es = 'Al entrar lloraba y ahora llora a gritos para no salir del agua. El efecto imán del agua le ha hechizado. Avísale con 3 minutos de antelación y pon un temporizador. El ritual de «cuando suena la campanita, se acaba el juego» siempre funciona.', title_fr = 'Le chantage de la salle de bain 🛀', body_fr = 'Il pleurait en entrant dans le bain, et maintenant il hurle pour ne pas en sortir. L''effet magnétique de l''eau l''a envoûté. Prévenez-le 3 minutes à l''avance et réglez un minuteur. Le rituel « Quand la sonnerie retentit, le jeu est fini » marche toujours.', title_hi = 'बाथरूम की ब्लैकमेलिंग 🛀', body_hi = 'अंदर जाते समय रो रहा था, और अब पानी से न निकलने के लिए चीख रहा है। पानी के चुंबकीय असर ने उस पर जादू कर दिया है। पहले से 3 मिनट की चेतावनी दीजिए और टाइमर लगाइए। ‘घंटी बजी, खेल खत्म’ वाली रस्में हमेशा काम करती हैं।', title_id = 'Pemerasan di kamar mandi 🛀', body_id = 'Saat masuk ia menangis, sekarang ia meraung tidak mau keluar dari air. Daya tarik magnet air telah menyihirnya. Beri peringatan 3 menit sebelumnya dan pasang timer. Ritual ''Saat bel berbunyi, permainan selesai'' selalu berhasil.', title_ja = 'お風呂の駆け引き 🛀', body_ja = '入るときは泣いていたのに、今はお湯から出たくなくて大泣き。お湯の磁石のような力に魔法をかけられたんです。前もって3分前に声をかけ、タイマーをセットしましょう。「ベルが鳴ったら遊びはおしまい」の習慣は、いつだって効果的です。', title_ko = '욕실 협박 🛀', body_ko = '들어갈 땐 울더니 이제는 안 나오겠다고 울부짖나요? 물의 자석 같은 힘에 홀린 거예요. 3분 전에 미리 알려 주고 타이머를 맞추세요. ''종이 울리면 놀이 끝'' 의식은 언제나 통해요.', title_nl = 'Chantage in de badkamer 🛀', body_nl = 'Bij het erin gaan huilde hij, nu krijst hij om niet uit het water te hoeven. Het water heeft hem betoverd. Waarschuw hem 3 minuten van tevoren en zet een timer. Rituelen als ''als de bel gaat, is het spel voorbij'' werken altijd.', title_pl = 'Łazienkowy szantaż 🛀', body_pl = 'Wchodząc, płakał, a teraz krzyczy, żeby nie wychodzić z wody. Magnetyczna moc wody go zaczarowała. Uprzedź go 3 minuty wcześniej i nastaw minutnik. Rytuał „gdy zadzwoni dzwonek, zabawa się kończy” zawsze działa.', title_pt = 'Chantagem na casa de banho 🛀', body_pt = 'Ao entrar chorava e agora grita para não sair da água. O efeito magnético da água enfeitiçou-o. Avise com 3 minutos de antecedência e programe um temporizador. Os rituais de "quando a campainha toca, a brincadeira acaba" resultam sempre.', title_sv = 'Badrumsutpressning 🛀', body_sv = 'Barnet grät när det skulle i, och nu skriker det för att slippa gå upp ur vattnet. Vattnets magnetiska kraft har förtrollat barnet. Varna 3 minuter i förväg och ställ in en timer. Ritualen ”när klockan ringer är leken slut” fungerar alltid.', title_vi = 'Màn "mặc cả" trong phòng tắm 🛀', body_vi = 'Lúc vào thì khóc, giờ lại gào lên không chịu ra khỏi nước. Sức hút của nước đã "bỏ bùa" bé. Hãy báo trước 3 phút và đặt hẹn giờ. Nghi thức "Chuông reo là hết giờ chơi" luôn hiệu quả.', title_zh = '浴室里的“要挟” 🛀', body_zh = '进去时在哭，现在却为了不出来而大声哭喊。水的魔力把宝宝迷住了。提前3分钟提醒，再设个计时器。“铃声一响，游戏结束”的仪式总是很管用。' WHERE id = '4bb7714f-90ea-44a6-8f84-3a989d3c428e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diseñador de comida 🥦', body_es = 'Separa la comida del plato por colores y formas y empuja lo verde al borde de la mesa. Entra en el Plan de alimentación. Descubre cómo convertir esas verduras en un puré invisible y esconderlas en albóndigas y salsas, y gana este juego.', title_fr = 'Le designer culinaire 🥦', body_fr = 'Il trie les aliments de son assiette par couleur et par forme, et pousse les verts au bord de la table. Ouvrez le Plan de nutrition. Gagnez cette partie en découvrant comment transformer ces légumes en purée invisible à cacher dans les boulettes et les sauces.', title_hi = 'खाने का डिज़ाइनर 🥦', body_hi = 'प्लेट का खाना रंग और आकार के हिसाब से अलग करता है, और हरी चीज़ें मेज़ के किनारे सरका देता है। फ़ीडिंग प्लान खोलिए। जानिए कि उन सब्ज़ियों की अदृश्य प्यूरी बनाकर कटलेट और सॉस में कैसे छिपाएँ, और इस खेल में जीत जाइए।', title_id = 'Desainer makanan 🥦', body_id = 'Ia memisahkan makanan di piring berdasarkan warna dan bentuknya, lalu mendorong yang hijau ke pinggir meja. Buka Rencana Nutrisi. Menangkan permainan ini dengan menemukan cara menghaluskan sayur hingga tak terlihat dan menyembunyikannya di perkedel atau saus.', title_ja = '食べ物デザイナー 🥦', body_ja = 'お皿の料理を色や形で分けて、緑のものはテーブルのはしに押しやっている。「栄養管理ツール」を開いてみましょう。野菜を見えないピューレにしてハンバーグやソースに隠す方法を見つけて、このゲームに勝ちましょう。', title_ko = '음식 디자이너 🥦', body_ko = '접시 위 음식을 색깔과 모양별로 나누고 초록색은 식탁 가장자리로 밀어내나요? 식단 계획에 들어가 보세요. 채소를 감쪽같은 퓌레로 만들어 동그랑땡이나 소스에 숨기는 법을 찾아 이 게임에서 이기세요.', title_nl = 'Voedselontwerper 🥦', body_nl = 'Hij sorteert het eten op zijn bord op kleur en vorm en schuift alles wat groen is naar de rand van de tafel. Open het Voedingsplan. Win dit spel door te ontdekken hoe je die groenten onzichtbaar pureert en in gehaktballetjes en sausjes verstopt.', title_pl = 'Projektant jedzenia 🥦', body_pl = 'Rozdziela jedzenie na talerzu według kolorów i kształtów, a zielone odsuwa na brzeg stołu. Zajrzyj do planu karmienia. Odkryj, jak zamienić te warzywa w niewidzialne purée i ukryć je w kotlecikach i sosach, i wygraj tę grę.', title_pt = 'Designer de comida 🥦', body_pt = 'Separa a comida do prato por cores e formas e empurra o que é verde para a borda da mesa. Entre no Registo de Alimentação. Descubra como transformar esses legumes num puré invisível e escondê-los em croquetes e molhos, e ganhe este jogo.', title_sv = 'Matdesignern 🥦', body_sv = 'Barnet sorterar maten på tallriken efter färg och form och skjuter de gröna bitarna till kanten av bordet. Gå in i matplanen. Vinn leken genom att upptäcka hur du gör grönsakerna till osynligt mos och gömmer dem i biffar och såser.', title_vi = 'Nhà thiết kế món ăn 🥦', body_vi = 'Bé phân loại thức ăn trên đĩa theo màu sắc và hình dạng, còn những thứ màu xanh thì đẩy ra mép bàn. Hãy vào Kế hoạch dinh dưỡng. Khám phá cách xay rau thành dạng nhuyễn "vô hình" để giấu vào thịt viên, nước sốt và giành chiến thắng trong trò chơi này.', title_zh = '食物设计师 🥦', body_zh = '把盘子里的食物按颜色和形状分开，绿色的全推到桌边。去喂养计划里看看，学会把那些蔬菜做成看不见的泥，藏进肉饼和酱汁里，赢下这场游戏吧。' WHERE id = 'a6053646-98c9-47f9-ae28-32c8e38f416e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile con la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro y sin tecnología, y asegura el paso al sueño.', title_fr = 'Danser avec la nuit 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans le noir et sans écran, ce qui assure le passage au sommeil.', title_hi = 'अँधेरे के साथ नृत्य 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है और नींद में जाना पक्का करता है।', title_id = 'Berdansa dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi, sehingga peralihan ke tidur lebih terjamin.', title_ja = '暗やみとダンス 🌙', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は暗くてデジタル機器のない環境でこそすばやく分泌され、眠りへの切りかえを確かなものにしてくれます。', title_ko = '어둠과 춤을 🌙', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어둡고 기기가 없는 환경에서만 빠르게 분비되어 잠으로 넘어가는 걸 도와줘요.', title_nl = 'Dansen met het donker 🌙', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen in een donkere omgeving zonder technologie snel aangemaakt en zorgt voor een soepele overgang naar de slaap.', title_pl = 'Taniec z ciemnością 🌙', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu bez technologii i zapewnia płynne przejście w sen.', title_pt = 'Dançar com o escuro 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro e sem tecnologia, o que garante a passagem para o sono.', title_sv = 'Dans med mörkret 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk och teknikfri miljö och säkrar övergången till sömn.', title_vi = 'Khiêu vũ cùng bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ, giúp bé vào giấc trọn vẹn.', title_zh = '和黑暗共舞 🌙', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素（睡眠激素）只有在昏暗、没有电子产品的环境里才会快速分泌，让入睡更有保障。' WHERE id = '0b46f253-2b1f-4b21-b471-54a500b94e42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un tesoro en la calle 🍁', body_es = 'Te enseña con alegría un tapón de botella sucio o una piedra de un color distinto que ha encontrado en el suelo, como si hubiera encontrado oro. En lugar de decirle «tíralo, está sucio», valora sus ganas de descubrir: «¡Qué color tan raro! Vamos a lavarlo en casa».', title_fr = 'Trésors de la rue 🍁', body_fr = 'Il vous montre, ravi, un bouchon de bouteille sale ou un caillou d''une couleur étonnante trouvé par terre, comme s''il avait trouvé de l''or. Plutôt que de dire « Jette ça, c''est sale », saluez sa soif de découverte : « Quelle drôle de couleur, on va le laver à la maison. »', title_hi = 'सड़क का खज़ाना 🍁', body_hi = 'ज़मीन पर मिला कोई गंदा बोतल का ढक्कन या अलग रंग का पत्थर ऐसे खुश होकर दिखाता है जैसे सोना मिल गया हो। ‘फेंक दो, गंदा है’ कहने के बजाय ‘कितना अनोखा रंग है, आओ घर पर धो लें’ कहकर उसकी खोज की लगन की तारीफ़ कीजिए।', title_id = 'Harta karun di jalan 🍁', body_id = 'Ia dengan gembira menunjukkan tutup botol kotor atau batu berwarna unik yang ia temukan di tanah, seolah menemukan emas. Daripada berkata ''Buang, itu kotor'', hargai semangat penjelajahannya dengan berkata ''Warnanya unik sekali, ayo kita cuci di rumah''.', title_ja = '道ばたの宝物 🍁', body_ja = '地面で見つけた汚れたペットボトルのふたや、めずらしい色の石を、金を見つけたように大喜びで見せてくれる。「捨てなさい、汚いよ」と言うより、「ふしぎな色だね、おうちで洗おうか」と言って、発見への意欲をほめてあげましょう。', title_ko = '길 위의 보물 🍁', body_ko = '바닥에서 주운 더러운 병뚜껑이나 색다른 돌을 금이라도 찾은 듯 기뻐하며 보여 주나요? ''버려, 더러워'' 대신 ''색깔 정말 신기하다, 집에 가서 씻자''라며 탐험심을 칭찬해 주세요.', title_nl = 'Schatten op straat 🍁', body_nl = 'Hij laat je blij een vies flessendopje of een steentje met een aparte kleur zien dat hij op de grond vond, alsof hij goud heeft gevonden. Zeg niet ''Gooi weg, dat is vies'', maar waardeer zijn ontdekkingsdrang: ''Wat een gekke kleur, laten we het thuis afwassen.''', title_pl = 'Skarb z ulicy 🍁', body_pl = 'Z radością pokazuje ci brudną nakrętkę od butelki albo kamyk w innym kolorze, który znalazł na ziemi, jakby znalazł złoto. Zamiast mówić „Wyrzuć, to brudne”, doceń jego ciekawość: „Jaki dziwny kolor, umyjmy go w domu”.', title_pt = 'O tesouro da rua 🍁', body_pt = 'Mostra-lhe, feliz como se tivesse encontrado ouro, uma tampa de garrafa suja ou uma pedra de cor diferente que achou no chão. Em vez de dizer "deita fora, está sujo", diga "Que cor tão estranha, vamos lavá-la em casa" e valorize a vontade dele de descobrir.', title_sv = 'Skatten på gatan 🍁', body_sv = 'Barnet visar dig glatt en smutsig flaskkork eller en sten i en annorlunda färg som det hittat på marken, som om det hittat guld. Istället för att säga ”Släng den, den är smutsig”, säg ”Vilken konstig färg den har, vi tvättar den hemma” och uppmuntra barnets upptäckarlust.', title_vi = 'Kho báu ngoài đường 🍁', body_vi = 'Bé hớn hở khoe với mẹ chiếc nắp chai bẩn hay viên sỏi có màu lạ nhặt được dưới đất như thể vừa tìm thấy vàng. Thay vì nói "Vứt đi, bẩn lắm", hãy khen ngợi sự tò mò khám phá của bé: "Màu lạ quá, mình mang về nhà rửa nhé".', title_zh = '街上的宝藏 🍁', body_zh = '把地上捡到的脏瓶盖或颜色特别的石头，像找到金子一样开心地拿给你看。与其说“扔掉，脏”，不如说“颜色好特别啊，我们回家洗洗吧”，肯定宝宝探索的热情。' WHERE id = '53f4b2ce-2dcb-457d-bccf-d9242c156c63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vuelve la hora de la filosofía 🤔', body_es = '«¿Por qué sopla el viento? ¿Por qué se caen las hojas?». Las preguntas filosóficas profundas te queman el cerebro desde primera hora. No compliques la explicación: explícale la naturaleza en un lenguaje de cuento que entienda. Tu tono de voz es para él la forma más segura de entender el universo.', title_fr = 'L''heure de la philosophie est de retour 🤔', body_fr = '« Pourquoi le vent souffle ? Pourquoi les feuilles tombent ? » Dès le matin, ces profondes questions philosophiques vous font chauffer le cerveau. Ne compliquez pas l''explication, racontez-lui la nature comme un conte qu''il peut comprendre. Le ton de votre voix est pour lui la façon la plus sûre de comprendre l''univers.', title_hi = 'दर्शन का समय फिर शुरू 🤔', body_hi = '‘हवा क्यों चलती है? पत्ते क्यों गिरते हैं?’ गहरे दार्शनिक सवाल सुबह-सुबह आपका दिमाग गरम कर देते हैं। समझाने को उलझाइए मत, प्रकृति को उसकी समझ वाली कहानी की भाषा में समझाइए। आपकी आवाज़ का लहजा उसके लिए दुनिया को समझने का सबसे भरोसेमंद रास्ता है।', title_id = 'Jam filsafat dibuka kembali 🤔', body_id = '''Kenapa angin bertiup? Kenapa daun berjatuhan?'' Pertanyaan filosofis yang dalam membakar otak Anda sejak pagi. Jangan memperumit penjelasan, terangkan alam dengan bahasa dongeng yang bisa ia pahami. Nada suara Anda adalah cara paling aman baginya untuk memahami alam semesta.', title_ja = '哲学の時間、再開 🤔', body_ja = '「風はなんで吹くの？」「葉っぱはなんで落ちるの？」朝から深い哲学的な質問で頭がフル回転。説明をむずかしくせず、自然のことを、この子にわかるお話の言葉で伝えましょう。あなたの声のトーンは、宇宙を知るためのいちばん安心な道です。', title_ko = '철학 시간 재개 🤔', body_ko = '''바람은 왜 불어?'', ''나뭇잎은 왜 떨어져?'' 아침부터 깊은 철학적 질문이 머리를 달구나요? 설명을 어렵게 하지 말고 자연을 아이가 이해할 수 있는 동화 같은 말로 들려주세요. 엄마의 목소리 톤은 아이가 우주를 이해하는 가장 안전한 길이에요.', title_nl = 'Het filosofie-uurtje is terug 🤔', body_nl = '''Waarom waait de wind? Waarom vallen de blaadjes?'' Al vroeg in de ochtend laten diepe filosofische vragen je hoofd roken. Maak de uitleg niet ingewikkeld, leg de natuur uit in sprookjestaal die hij begrijpt. Jouw stem is voor hem de veiligste manier om het universum te begrijpen.', title_pl = 'Godzina filozofii wraca 🤔', body_pl = '„Dlaczego wieje wiatr? Dlaczego liście spadają?” Głębokie filozoficzne pytania od rana palą ci mózg. Nie komplikuj wyjaśnień, tłumacz przyrodę językiem bajki, który zrozumie. Ton twojego głosu to dla niego najbezpieczniejszy sposób, by zrozumieć wszechświat.', title_pt = 'A hora da filosofia está de volta 🤔', body_pt = '"Porque é que o vento sopra? Porque é que as folhas caem?" Perguntas filosóficas profundas queimam-lhe o cérebro logo de manhã. Não complique a explicação: explique a natureza numa linguagem de conto que ele entenda. O seu tom de voz é para ele a forma mais segura de compreender o universo.', title_sv = 'Filosofistunden är tillbaka 🤔', body_sv = '”Varför blåser vinden?” ”Varför faller löven?” Djupa filosofiska frågor tidigt på morgonen får hjärnan att gå varm. Gör inte förklaringen krånglig, förklara naturen på ett sagospråk som barnet förstår. Din röst är för barnet det tryggaste sättet att förstå universum.', title_vi = 'Giờ triết học đã trở lại 🤔', body_vi = '"Sao gió thổi?", "Sao lá rụng?" Những câu hỏi triết lý sâu xa làm đầu mẹ nóng lên từ sáng sớm. Đừng giải thích phức tạp, hãy giải thích thiên nhiên bằng ngôn ngữ cổ tích mà bé hiểu được. Giọng nói của mẹ là cách an toàn nhất để bé hiểu về vũ trụ.', title_zh = '哲学时间又回来了 🤔', body_zh = '“风为什么会吹？”“叶子为什么会掉？”一大早，深奥的哲学问题就让你脑袋发烫。别把解释弄得太复杂，用宝宝能听懂的童话语言讲讲大自然。你的语气，是宝宝理解宇宙最安全的方式。' WHERE id = 'd8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto en la cocina 🥄', body_es = 'Saca las ollas y las cucharas de madera y da un concierto en medio de la cocina. Aunque te duela la cabeza, así se desarrollan su sentido del ritmo y su creatividad. No intervengas con prisas: deja unos minutos que esa energía loca se extienda por la habitación en ondas sonoras.', title_fr = 'Concert en cuisine 🥄', body_fr = 'Il sort les casseroles et les cuillères en bois et donne un concert au milieu de la cuisine. Même si vous avez mal à la tête, c''est le développement de son sens du rythme et de sa créativité. N''intervenez pas trop vite, laissez cette énergie folle se répandre quelques minutes en ondes sonores dans la pièce.', title_hi = 'रसोई में कॉन्सर्ट 🥄', body_hi = 'पतीले और लकड़ी के चम्मच निकालकर रसोई के बीच कॉन्सर्ट दे रहा है। सिर भले दुखे, यह उसकी लय की समझ और रचनात्मकता का विकास है। जल्दबाज़ी में बीच में मत आइए, कुछ मिनट उस धमाकेदार ऊर्जा को आवाज़ की लहरों के साथ कमरे में फैलने दीजिए।', title_id = 'Konser di dapur 🥄', body_id = 'Ia mengeluarkan panci dan sendok kayu lalu menggelar konser di tengah dapur. Meski kepala Anda pusing, ini adalah perkembangan rasa irama dan kreativitasnya. Jangan buru-buru campur tangan, biarkan energi gilanya menyebar ke seluruh ruangan lewat gelombang suara selama beberapa menit.', title_ja = 'キッチンでコンサート 🥄', body_ja = '鍋や木のスプーンを取り出して、キッチンのまんなかでコンサート中。頭が痛くても、これはリズム感と創造力の発達です。あわてて止めないで、数分間はそのすごいエネルギーを音の波にのせて部屋に広げさせてあげましょう。', title_ko = '부엌 콘서트 🥄', body_ko = '냄비와 나무 숟가락을 꺼내 부엌 한가운데서 콘서트를 여나요? 머리가 아파도 리듬감과 창의력이 자라는 중이에요. 서둘러 끼어들지 말고 몇 분만 그 넘치는 에너지가 소리로 방을 채우게 해 주세요.', title_nl = 'Concert in de keuken 🥄', body_nl = 'Hij haalt pannen en houten lepels tevoorschijn en geeft midden in de keuken een concert. Ook al krijg je er hoofdpijn van, zo ontwikkelt hij zijn ritmegevoel en creativiteit. Grijp niet te snel in en laat die gekke energie een paar minuten met geluidsgolven door de kamer gaan.', title_pl = 'Koncert w kuchni 🥄', body_pl = 'Wyciągnął garnki i drewniane łyżki i daje koncert na środku kuchni. Nawet jeśli boli cię głowa, to rozwój jego poczucia rytmu i kreatywności. Nie wtrącaj się w pośpiechu, pozwól przez kilka minut tej szalonej energii rozchodzić się po pokoju falami dźwięku.', title_pt = 'Concerto na cozinha 🥄', body_pt = 'Tira as panelas e as colheres de pau e dá um concerto no meio da cozinha. Mesmo com dor de cabeça, isto é o desenvolvimento do sentido de ritmo e da criatividade dele. Não intervenha à pressa: deixe por uns minutos aquela energia louca espalhar-se pelo quarto em ondas sonoras.', title_sv = 'Konsert i köket 🥄', body_sv = 'Barnet plockar fram kastruller och träslevar och ger konsert mitt i köket. Även om du får huvudvärk är det utvecklingen av rytmkänsla och kreativitet. Lägg dig inte i för snabbt, låt den galna energin spridas i rummet med ljudvågorna i några minuter.', title_vi = 'Buổi hòa nhạc trong bếp 🥄', body_vi = 'Bé lôi nồi niêu và thìa gỗ ra, mở một buổi hòa nhạc giữa bếp. Dù mẹ đau đầu, đây là sự phát triển cảm thụ nhịp điệu và khả năng sáng tạo của bé. Đừng vội can thiệp, hãy để nguồn năng lượng "điên rồ" ấy lan tỏa khắp phòng qua những làn sóng âm thanh trong vài phút.', title_zh = '厨房音乐会 🥄', body_zh = '把锅和木勺都拿出来，在厨房中间开起了音乐会。虽然你头都疼了，但这是宝宝节奏感和创造力在发展。别急着插手，让那股疯狂的能量随着声波在房间里飘荡几分钟吧。' WHERE id = '4a8b061c-822f-4468-b267-6996ffaeb6d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El pensamiento «¿Por qué mi hijo es tan tozudo?» te está comiendo por dentro. Entra en la Comunidad Anacan. Cuando leas las crisis absurdas parecidas que estallan en casa de otras madres, verás que no estás sola y que estás criando a un niño totalmente normal y sano.', body_fr = 'La pensée « Pourquoi mon enfant est-il si têtu ? » vous ronge de l''intérieur ? Rejoignez la Communauté Anacan. En lisant les crises absurdes qui éclatent chez d''autres mamans, vous verrez que vous n''êtes pas seule et que vous élevez un enfant tout à fait normal et en bonne santé.', body_hi = '‘मेरा बच्चा इतना ज़िद्दी क्यों है?’ वाला ख्याल आपको अंदर से खा रहा है। Anacan कम्युनिटी में जाइए। दूसरी माँओं के घरों में होने वाले ऐसे ही बेतुके नखरे पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और एक बिल्कुल सामान्य, स्वस्थ बच्चा बड़ा कर रही हैं।', body_id = 'Pikiran ''Kenapa anakku keras kepala sekali?'' menggerogoti Anda dari dalam. Masuklah ke Komunitas Anacan. Saat membaca krisis absurd serupa di rumah ibu-ibu lain, Anda akan melihat bahwa Anda tidak sendirian dan sedang membesarkan anak yang sepenuhnya normal dan sehat.', body_ja = '「どうしてうちの子はこんなにがんこなの？」という思いが、心をむしばんでいませんか。Anacanコミュニティを開いてみましょう。ほかのママたちの家で起きている同じようなおかしなかんしゃくを読めば、ひとりじゃないこと、そしてごく普通の健康な子を育てていることがわかります。', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각이 마음을 갉아먹나요? Anacan 커뮤니티에 들어가 보세요. 다른 집에서 터지는 비슷하게 엉뚱한 떼쓰기를 읽으면 혼자가 아니고, 아주 정상적이고 건강한 아이를 키우고 있다는 걸 알게 될 거예요.', body_nl = 'Vreet de gedachte ''Waarom is mijn kind zo koppig?'' van binnen aan je? Ga naar de Anacan Community. Als je leest over net zulke absurde buien bij andere mama''s thuis, zie je dat je niet de enige bent en dat je een heel normaal, gezond kind grootbrengt.', body_pl = 'Myśl „Dlaczego moje dziecko jest takie uparte?” zjada cię od środka. Wejdź do Społeczności Anacan. Gdy przeczytasz o podobnych absurdalnych kryzysach w domach innych mam, zobaczysz, że nie jesteś sama i wychowujesz zupełnie normalne, zdrowe dziecko.', body_pt = 'O pensamento "Porque é que o meu filho é tão teimoso?" consome-a por dentro. Entre na Comunidade Anacan. Ao ler as crises absurdas parecidas que rebentam em casa de outras mães, vai ver que não está sozinha e que está a criar uma criança totalmente normal e saudável.', body_sv = 'Tanken ”Varför är mitt barn så envist?” äter upp dig inifrån. Gå in i Anacan Community. När du läser om liknande absurda kriser hemma hos andra mammor ser du att du inte är ensam och att du fostrar ett helt normalt, friskt barn.', body_vi = 'Ý nghĩ "Sao con mình bướng thế?" cứ gặm nhấm mẹ. Hãy vào Cộng đồng Anacan. Khi đọc về những cơn khủng hoảng "khó đỡ" tương tự ở nhà các mẹ khác, mẹ sẽ thấy mình không đơn độc và đang nuôi dạy một đứa trẻ hoàn toàn bình thường, khỏe mạnh.', body_zh = '“我的孩子怎么这么倔？”这个念头从心底折磨着你。进入Anacan社区。读到其他妈妈家里也在上演类似的荒诞崩溃，你就会发现自己并不孤单，你养大的是一个完全正常、健康的孩子。' WHERE id = '79b03a5c-cc04-4f7b-9361-f8120f787406' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El calor de su respiración 💖', body_es = 'Te ha vuelto loca todo el día y ha llorado por todo. Pero ahora está acurrucado en tu pecho en la cama y su respiración rítmica y cálida llena la habitación. Esa es la mayor recompensa de la maternidad. Abrázale contra tu pecho y siente cómo todo el cansancio se va volando con esa respiración.', title_fr = 'La chaleur de son souffle 💖', body_fr = 'Il vous a rendue folle toute la journée et a pleuré pour tout. Mais maintenant, il est blotti contre vous dans le lit, et son souffle chaud et régulier remplit la chambre. C''est exactement la plus belle récompense de la maternité. Serrez-le contre votre cœur et sentez toute votre fatigue s''envoler avec ce souffle.', title_hi = 'उसकी साँसों की गर्माहट 💖', body_hi = 'उसने दिनभर आपको परेशान किया, हर बात पर रोया। पर अब बिस्तर में आपके सीने से सटा है, कमरा उसकी लयबद्ध, गर्म साँसों से भरा है। माँ बनने का सबसे बड़ा इनाम यही है। उसे सीने से लगाइए और महसूस कीजिए कि सारी थकान इन साँसों के साथ उड़ गई।', title_id = 'Hangatnya napasnya 💖', body_id = 'Seharian ia membuat Anda hampir gila dan menangisi segala hal. Tapi kini ia meringkuk di dada Anda di tempat tidur, dan napasnya yang hangat dan berirama memenuhi kamar. Inilah hadiah terbesar menjadi ibu. Peluk ia erat dan rasakan semua lelah terbang bersama napas itu.', title_ja = '寝息のぬくもり 💖', body_ja = '一日じゅう振りまわされて、何にでも泣いていたのに、今はベッドであなたの胸に寄りそい、部屋はリズミカルで温かい寝息に満ちています。これこそママであることのいちばんのごほうび。ぎゅっと抱きしめて、疲れがこの寝息とともに飛んでいくのを感じて。', title_ko = '따뜻한 숨결 💖', body_ko = '하루 종일 엄마를 미치게 하고 모든 일에 울었죠. 그런데 지금은 침대에서 엄마 가슴에 파고들어, 리듬 있는 따뜻한 숨소리로 방을 채우고 있어요. 이게 엄마가 받는 가장 큰 선물이에요. 꼭 안고 모든 피로가 그 숨결과 함께 날아가는 걸 느껴 보세요.', title_nl = 'De warmte van zijn adem 💖', body_nl = 'Hij heeft je de hele dag gek gemaakt en huilde om alles. Maar nu ligt hij in bed tegen je borst gekropen en vult zijn ritmische, warme adem de kamer. Dit is de grootste beloning van het moederschap. Druk hem tegen je aan en voel hoe alle vermoeidheid met die adem wegvliegt.', title_pl = 'Ciepło jego oddechu 💖', body_pl = 'Cały dzień doprowadzał cię do szału i płakał o wszystko. Ale teraz w łóżku przytulił się do twojej piersi, a pokój wypełnia jego miarowy, ciepły oddech. To właśnie największa nagroda macierzyństwa. Przytul go mocno i poczuj, jak całe zmęczenie odlatuje z tym oddechem.', title_pt = 'O calor da respiração dele 💖', body_pt = 'Passou o dia todo a deixá-la louca e a chorar por tudo. Mas agora está na cama aninhado no seu peito e a respiração ritmada e quente dele enche o quarto. É exatamente esta a maior recompensa da maternidade. Aperte-o contra o peito e sinta todo o cansaço a desaparecer com esta respiração.', title_sv = 'Värmen i andetaget 💖', body_sv = 'Barnet har gjort dig galen hela dagen och gråtit åt allt. Men nu ligger det tryckt mot ditt bröst i sängen och rummet fylls av barnets rytmiska, varma andetag. Det är moderskapets största belöning. Tryck barnet mot bröstet och känn hur all trötthet flyger bort med andetaget.', title_vi = 'Hơi thở ấm áp 💖', body_vi = 'Cả ngày bé làm mẹ phát điên, khóc vì mọi thứ. Nhưng giờ bé đang rúc vào ngực mẹ trên giường, hơi thở đều đặn, ấm áp của bé lấp đầy căn phòng. Đó chính là phần thưởng lớn nhất của việc làm mẹ. Hãy ôm chặt bé vào lòng và cảm nhận mọi mệt mỏi bay đi theo từng hơi thở.', title_zh = '呼吸的温度 💖', body_zh = '宝宝把你折腾了一整天，什么都哭。可现在在床上依偎在你胸前，房间里满是宝宝有节奏的、温暖的呼吸声。这正是当妈妈最大的奖赏。把宝宝搂在怀里，感受所有的疲惫都随着这呼吸飞走了。' WHERE id = 'c0b67368-8315-449a-b685-71a8e309a2c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mudanza en la cama 🛏️', body_es = 'Empieza la noche durmiendo en una postura correcta y por la mañana se despierta con los pies en la almohada y la cabeza en la esquina opuesta de la cama. ¡Explora el mundo incluso dormido! Antes de despertarle, disfruta riéndote de esta cómica migración por la cama.', title_fr = 'La migration nocturne 🛏️', body_fr = 'Il s''est endormi dans la bonne position, et se réveille le matin les pieds sur l''oreiller et la tête dans le coin opposé du lit. Il explore le monde même en dormant ! Avant de le réveiller, observez en riant cette migration comique.', title_hi = 'बिस्तर पर प्रवास 🛏️', body_hi = 'रात को सही तरह सोता है, और सुबह पैर तकिए पर, सिर बिस्तर के बिल्कुल उलटे कोने में रखे जागता है। नींद में भी दुनिया खोज रहा है! उसे जगाने से पहले उसके इस मज़ेदार बिस्तर-प्रवास को हँसते हुए देखिए।', title_id = 'Migrasi di tempat tidur 🛏️', body_id = 'Ia tidur dengan posisi yang benar, tapi paginya bangun dengan kaki di bantal dan kepala di sudut tempat tidur yang berlawanan. Bahkan dalam tidur ia menjelajahi dunia! Saksikan migrasi lucu ini sambil tertawa sebelum membangunkannya.', title_ja = 'ベッドの大移動 🛏️', body_ja = '夜はちゃんとした姿勢で寝たのに、朝には足が枕の上、頭はベッドの反対側のすみで目を覚ます。眠っていても世界を探検中！このおかしなベッドの大移動を、起こす前に笑いながら眺めましょう。', title_ko = '침대 대이동 🛏️', body_ko = '밤에는 반듯하게 잠들었는데 아침에는 발은 베개에, 머리는 침대 반대쪽 구석에 가 있나요? 자면서도 세상을 탐험하는 중이에요! 깨우기 전에 이 웃긴 침대 대이동을 웃으며 감상해 보세요.', title_nl = 'Verhuizen in bed 🛏️', body_nl = 'Hij viel netjes in slaap, maar wordt ''s ochtends wakker met zijn voeten op het kussen en zijn hoofd in de tegenovergestelde hoek van het bed. Zelfs in zijn slaap ontdekt hij de wereld! Kijk lachend naar deze grappige bedmigratie voordat je hem wakker maakt.', title_pl = 'Łóżkowa przeprowadzka 🛏️', body_pl = 'Zasnął w porządnej pozycji, a rano budzi się z nogami na poduszce i głową w zupełnie przeciwnym rogu łóżka. Nawet we śnie odkrywa świat! Zanim go obudzisz, obserwuj ze śmiechem tę zabawną łóżkową wędrówkę.', title_pt = 'Mudança de cama 🛏️', body_pt = 'Adormece na posição certa e de manhã acorda com os pés na almofada e a cabeça no canto oposto da cama. Até a dormir descobre o mundo! Antes de o acordar, observe a rir esta migração cómica pela cama.', title_sv = 'Flytt i sängen 🛏️', body_sv = 'Barnet somnar i rätt ställning, men vaknar på morgonen med fötterna på kudden och huvudet i motsatta hörnet av sängen. Till och med i sömnen upptäcker barnet världen! Titta skrattande på den roliga sängvandringen innan du väcker barnet.', title_vi = 'Cuộc di cư trên giường 🛏️', body_vi = 'Đi ngủ thì nằm đúng tư thế, sáng ra bé thức dậy với chân gác lên gối, còn đầu ở góc đối diện của giường. Ngay cả khi ngủ, bé cũng đang khám phá thế giới! Hãy cười thích thú ngắm "cuộc di cư" ngộ nghĩnh này trước khi đánh thức bé.', title_zh = '床上大迁徙 🛏️', body_zh = '晚上睡觉时姿势端端正正，早上醒来却脚在枕头上，头在床的另一个对角。连睡觉都在探索世界！在叫醒宝宝之前，先笑着欣赏一下这场搞笑的“床上迁徙”吧。' WHERE id = '1d548457-d3f9-490c-889a-735e0fede3a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Retraso filosófico del sueño 🦉', body_es = 'Justo al meterse en la cama hace preguntas profundas como «Mamá, ¿por qué no se caen las estrellas?». El objetivo no es aprender ciencia, sino retrasar el sueño. Dale respuestas cortas, inventadas y dulces, y llena enseguida la habitación de calma con Cuentos inteligentes.', title_fr = 'Le retard philosophique du coucher 🦉', body_fr = 'Juste au moment d''aller au lit, il pose des questions profondes comme « Maman, pourquoi les étoiles ne tombent pas ? ». Le but n''est pas d''apprendre la science, mais de retarder le sommeil. Donnez des réponses courtes, inventées et mignonnes, puis installez aussitôt le silence du coucher avec les Contes intelligents.', title_hi = 'दार्शनिक बहाने से नींद टालना 🦉', body_hi = 'ठीक बिस्तर में जाते ही पूछता है, ‘माँ, तारे गिरते क्यों नहीं?’ जैसे गहरे सवाल। मकसद विज्ञान सीखना नहीं, नींद टालना है। सवालों के छोटे, गढ़े हुए और प्यारे जवाब दीजिए और तुरंत स्मार्ट कहानियों से कमरे में नींद वाली खामोशी लाइए।', title_id = 'Penundaan tidur filosofis 🦉', body_id = 'Tepat saat naik ke tempat tidur, ia mengajukan pertanyaan dalam seperti ''Ma, kenapa bintang tidak jatuh?''. Tujuannya bukan belajar sains, tapi menunda tidur. Beri jawaban singkat, karangan, dan manis, lalu segera hadirkan keheningan tidur di kamar dengan Dongeng Pintar.', title_ja = '哲学で寝る時間を引きのばし 🦉', body_ja = 'ちょうどベッドに入ったところで「ママ、お星さまはなんで落ちてこないの？」と深い質問。目的は科学を学ぶことではなく、寝る時間を遅らせること。短くて作り話のかわいい答えを返したら、すぐに「スマートおはなし」で部屋を眠りの静けさで包みましょう。', title_ko = '철학적인 잠 미루기 🦉', body_ko = '침대에 눕자마자 ''엄마, 별은 왜 안 떨어져?'' 같은 깊은 질문을 하나요? 목적은 과학이 아니라 잠을 미루는 거예요. 짧고 지어낸 달콤한 답을 해 주고 바로 스마트 동화로 방에 잠의 고요를 불러오세요.', title_nl = 'Filosofisch uitstel van de slaap 🦉', body_nl = 'Net als hij in bed ligt, stelt hij diepe vragen als ''Mama, waarom vallen de sterren niet naar beneden?''. Het doel is niet om wetenschap te leren, maar om het slapen uit te stellen. Geef korte, verzonnen en lieve antwoorden en breng meteen slaapstilte in de kamer met Slimme sprookjes.', title_pl = 'Filozoficzne odwlekanie snu 🦉', body_pl = 'Gdy tylko kładzie się do łóżka, zadaje głębokie pytania w stylu „Mamo, dlaczego gwiazdy nie spadają?”. Celem nie jest nauka, tylko odwleczenie snu. Odpowiadaj krótko, słodko i z wyobraźnią, a potem od razu wprowadź do pokoju senną ciszę z Mądrymi bajkami.', title_pt = 'Adiar o sono com filosofia 🦉', body_pt = 'Mal se deita na cama, faz perguntas profundas como "Mãe, porque é que as estrelas não caem?". O objetivo não é aprender ciência, é adiar o sono. Dê respostas curtas, inventadas e doces e faça logo cair no quarto o silêncio do sono com as Histórias Inteligentes.', title_sv = 'Filosofisk sömnfördröjning 🦉', body_sv = 'Precis när barnet kommer i säng ställer det djupa frågor som ”Mamma, varför faller inte stjärnorna ner?”. Målet är inte att lära sig vetenskap, utan att skjuta upp sömnen. Ge korta, påhittade och söta svar och låt sedan direkt sömnens tystnad sänka sig med Smarta sagor.', title_vi = 'Triết lý trì hoãn giấc ngủ 🦉', body_vi = 'Đúng lúc lên giường, bé lại hỏi những câu sâu xa như "Mẹ ơi, sao các ngôi sao không rơi xuống?". Mục đích không phải là học khoa học, mà là trì hoãn giấc ngủ. Hãy trả lời ngắn gọn, ngọt ngào, tự nghĩ ra, rồi dùng ngay Truyện cổ tích thông minh để mang sự yên tĩnh của giấc ngủ vào phòng.', title_zh = '哲学式拖延睡觉 🦉', body_zh = '刚上床就问“妈妈，星星为什么不掉下来？”这种深奥的问题。目的不是学科学，而是拖延睡觉。用简短、编出来的甜甜答案回应，然后马上用智慧童话让房间安静下来，进入睡眠。' WHERE id = '9fa8e885-34cc-4a52-b9b9-6155faa47396' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un héroe disfrazado 🦸‍♂️', body_es = '¿Insiste en andar por casa con botas de invierno o con una máscara de superhéroe? Olvídate de las normas sociales y de la estética. Está descubriendo su personalidad. Deja que se sienta un héroe con sus botas por la habitación.', title_fr = 'Le héros costumé 🦸‍♂️', body_fr = 'Il veut absolument se promener dans la maison en bottes d''hiver ou avec un masque de super-héros ? Laissez tomber les normes sociales et l''esthétique. C''est sa découverte de lui-même. Laissez-le se sentir héros dans ses bottes.', title_hi = 'पोशाक वाला हीरो 🦸‍♂️', body_hi = 'घर में ज़िद से सर्दियों के जूते या सुपरहीरो का मास्क पहनकर घूमना चाहता है? लोगों के कायदे और सुंदरता छोड़िए। यह उसकी अपनी पहचान की खोज है। उसे जूतों में कमरे में खुद को हीरो महसूस करने दीजिए।', title_id = 'Pahlawan berkostum 🦸‍♂️', body_id = 'Ia bersikeras berkeliling rumah memakai sepatu bot musim dingin atau topeng superhero? Lupakan norma sosial dan estetika. Ini penemuan jati dirinya. Biarkan ia merasa seperti pahlawan dengan sepatu botnya di kamar.', title_ja = 'コスチュームのヒーロー 🦸‍♂️', body_ja = '家の中で、どうしても冬のブーツやスーパーヒーローのマスクで歩きたがる？世間の常識や見た目は気にしないで。これは自分らしさの発見です。部屋の中でブーツをはいて、ヒーロー気分を味わわせてあげましょう。', title_ko = '망토 두른 영웅 🦸‍♂️', body_ko = '집 안에서 꼭 겨울 부츠나 슈퍼히어로 가면을 쓰고 다니겠다고 하나요? 사회적 기준과 보기 좋은 건 잊으세요. 자기 자신을 발견하는 중이에요. 방에서 부츠를 신고 영웅이 된 기분을 느끼게 해 주세요.', title_nl = 'Held in kostuum 🦸‍♂️', body_nl = 'Wil hij per se met winterlaarzen of een superheldenmasker door het huis lopen? Laat wat ''hoort'' en esthetiek maar zitten. Zo ontdekt hij wie hij is. Laat hem zich in zijn kamer met zijn laarzen een held voelen.', title_pl = 'Bohater w kostiumie 🦸‍♂️', body_pl = 'Uparcie chce chodzić po domu w zimowych kozakach albo w masce superbohatera? Odpuść normy społeczne i estetykę. To odkrywanie własnej tożsamości. Niech w kozakach czuje się w pokoju jak bohater.', title_pt = 'Um herói de fato 🦸‍♂️', body_pt = 'Insiste em andar pela casa com botas de inverno ou máscara de super-herói? Esqueça as normas sociais e a estética. É a descoberta da personalidade dele. Deixe-o sentir-se um herói no quarto, de botas calçadas.', title_sv = 'Hjälte i kostym 🦸‍♂️', body_sv = 'Vill barnet envist gå runt hemma i vinterstövlar eller med en superhjältemask? Strunta i samhällets normer och estetiken. Det är barnets upptäckt av sin personlighet. Låt barnet känna sig som en hjälte i stövlarna i rummet.', title_vi = 'Anh hùng trong bộ trang phục 🦸‍♂️', body_vi = 'Bé nhất quyết đi lại trong nhà với ủng mùa đông hay mặt nạ siêu anh hùng? Kệ chuẩn mực xã hội và thẩm mỹ đi. Đây là hành trình khám phá bản thân của bé. Cứ để bé đi ủng trong phòng và thấy mình như một người hùng.', title_zh = '穿戏服的英雄 🦸‍♂️', body_zh = '非要在家里穿着冬天的靴子或戴着超级英雄面具走来走去？别管社会规范和好不好看了。这是宝宝在探索自我。就让宝宝穿着靴子，在房间里觉得自己是个英雄吧。' WHERE id = 'b5e65866-a678-4ef1-91b0-5f12331c2cae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los dientes del dinosaurio 🦖', body_es = 'Se niega rotundamente a lavarse los dientes y tira el cepillo. ¡Pasa al juego! Dale un cepillo de repuesto y dile: «Vamos a lavarle primero los dientes a tu dinosaurio de juguete». Mientras cepilla al dinosaurio, tú lávale los dientes con astucia.', title_fr = 'Les dents du dinosaure 🦖', body_fr = 'Il refuse catégoriquement de se brosser les dents et jette la brosse. Passez au jeu ! Donnez-lui une brosse de rechange et dites : « Viens, on lave d''abord les dents de ton dinosaure. » Pendant qu''il brosse le dinosaure, brossez-lui les dents l''air de rien.', title_hi = 'डायनासोर के दाँत 🦖', body_hi = 'अपने दाँत ब्रश करने से साफ़ मना करता है, ब्रश फेंक देता है। खेल शुरू कीजिए! उसके हाथ में एक अतिरिक्त ब्रश दीजिए और कहिए, ‘आओ, पहले तुम्हारे खिलौने वाले डायनासोर के दाँत साफ़ करें।’ जब वह डायनासोर को ब्रश करे, आप चालाकी से उसके दाँत साफ़ कर दीजिए।', title_id = 'Gigi dinosaurus 🦖', body_id = 'Ia tegas menolak menggosok gigi dan membuang sikat giginya. Beralihlah ke permainan! Beri ia sikat gigi cadangan dan katakan ''Ayo kita sikat dulu gigi dinosaurus mainanmu''. Selagi ia menyikat dinosaurus, diam-diam sikat juga giginya.', title_ja = '恐竜の歯 🦖', body_ja = '自分の歯みがきをきっぱりいやがって、歯ブラシを投げる。遊びに切りかえましょう！予備の歯ブラシを渡して「まずはあなたの恐竜の歯をみがこうか」と声をかけて。この子が恐竜をみがいているあいだに、あなたもこっそりこの子の歯をみがきましょう。', title_ko = '공룡의 이 🦖', body_ko = '자기 이 닦기를 단호하게 거부하고 칫솔을 던지나요? 놀이로 바꿔 보세요! 여분의 칫솔을 쥐여 주고 ''먼저 네 공룡 인형 이부터 닦아 주자''라고 하세요. 아이가 공룡을 닦는 동안 엄마는 슬쩍 아이의 이를 닦아 주세요.', title_nl = 'De tanden van de dinosaurus 🦖', body_nl = 'Hij weigert resoluut zijn tanden te poetsen en gooit de tandenborstel weg. Maak er een spel van! Geef hem een extra tandenborstel en zeg: ''Kom, eerst poetsen we de tanden van je speelgoeddinosaurus.'' Terwijl hij de dinosaurus poetst, poets jij slim zijn tanden.', title_pl = 'Zęby dinozaura 🦖', body_pl = 'Stanowczo odmawia mycia zębów i rzuca szczoteczką. Przejdź do zabawy! Daj mu zapasową szczoteczkę i powiedz: „Najpierw umyjmy zęby twojemu dinozaurowi”. Gdy on szoruje dinozaura, ty sprytnie myj jego zęby.', title_pt = 'Os dentes do dinossauro 🦖', body_pt = 'Recusa terminantemente lavar os dentes e atira a escova. Passe para o jogo! Dê-lhe uma escova de reserva e diga "Vamos primeiro lavar os dentes ao teu dinossauro de brincar". Enquanto ele escova o dinossauro, a mãe, com toda a esperteza, lava-lhe os dentes.', title_sv = 'Dinosauriens tänder 🦖', body_sv = 'Barnet vägrar bestämt att borsta tänderna och kastar tandborsten. Gör det till en lek! Ge barnet en extra tandborste och säg ”Kom, först borstar vi tänderna på din leksaksdinosaurie”. Medan barnet borstar dinosaurien borstar du listigt barnets tänder.', title_vi = 'Răng của khủng long 🦖', body_vi = 'Bé nhất quyết không chịu đánh răng, còn ném bàn chải đi. Hãy chuyển sang trò chơi! Đưa bé một chiếc bàn chải dự phòng và nói: "Mình cùng đánh răng cho chú khủng long đồ chơi của con trước nhé". Trong lúc bé chải cho khủng long, mẹ khéo léo đánh răng cho bé.', title_zh = '恐龙的牙齿 🦖', body_zh = '坚决不肯刷牙，还把牙刷扔了。切换到游戏模式！给宝宝一把备用牙刷，说“我们先给你的玩具恐龙刷刷牙吧”。宝宝给恐龙刷牙时，你也巧妙地帮宝宝把牙刷了。' WHERE id = '0497aa5e-024a-43eb-ba38-bda044dfec73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manchas de libertad 🥣', body_es = 'Se empeña en comer el yogur con tenedor y lo pone todo perdido. No intervengas ni se lo quites de la mano. La comida derramada se limpia, pero es difícil reparar su ego del «lo hago yo solo». Ponle el babero de silicona y observa la escena con paciencia.', title_fr = 'Les taches de la liberté 🥣', body_fr = 'Il veut absolument manger son yaourt à la fourchette et il en met partout. N''intervenez pas pour la lui reprendre. Les aliments renversés se nettoient, mais son ego du « je le fais tout seul » est difficile à reconstruire. Mettez-lui un bavoir en silicone et observez la scène avec patience.', title_hi = 'आज़ादी के दाग 🥣', body_hi = 'दही ज़रूर काँटे से खाना है, और सब गंदा हो जाता है। बीच में आकर हाथ से मत छीनिए। बिखरा खाना साफ़ हो जाता है, पर उसका ‘मैं खुद कर रहा हूँ’ वाला अहं ठीक करना मुश्किल है। सिलिकॉन बिब बाँधिए और धैर्य से यह नज़ारा देखिए।', title_id = 'Noda kebebasan 🥣', body_id = 'Ia bersikeras makan yogurt dengan garpu dan semuanya berlepotan. Jangan campur tangan dan merebutnya. Makanan yang tumpah bisa dibersihkan, tapi ego ''aku bisa sendiri'' sulit dipulihkan. Pakaikan celemek silikon dan saksikan pemandangan ini dengan sabar.', title_ja = '自由のしるし 🥣', body_ja = 'ヨーグルトをどうしてもフォークで食べたがって、あたりはべたべた。横から手を出して取りあげないで。こぼれた食べ物はきれいにできるけれど、「自分でやる」という気持ちを取りもどすのはむずかしいもの。シリコンのスタイをつけて、この光景を根気よく見守りましょう。', title_ko = '자유의 얼룩 🥣', body_ko = '요거트를 꼭 포크로 먹겠다며 온 사방을 엉망으로 만드나요? 끼어들어 뺏지 마세요. 흘린 음식은 닦으면 되지만 ''내가 할래''라는 자존감은 되돌리기 어려워요. 실리콘 턱받이를 채우고 인내심 있게 지켜보세요.', title_nl = 'Vlekken van vrijheid 🥣', body_nl = 'Hij wil per se zijn yoghurt met een vork eten en alles wordt vies. Grijp niet in en pak de vork niet af. Gemorst eten kun je opruimen, maar zijn ''ik doe het zelf''-ego herstellen is moeilijk. Doe hem een siliconen slabbetje om en kijk geduldig toe.', title_pl = 'Plamy wolności 🥣', body_pl = 'Koniecznie chce jeść jogurt widelcem, a wszystko jest wysmarowane. Nie wtrącaj się i nie zabieraj mu go. Rozlane jedzenie da się sprzątnąć, ale trudno odbudować jego ego „ja sam”. Załóż silikonowy śliniak i cierpliwie obserwuj.', title_pt = 'Manchas de liberdade 🥣', body_pt = 'Quer mesmo comer o iogurte com o garfo e suja tudo. Não intervenha nem lho tire das mãos. A comida que cai limpa-se, mas aquele ego de "sou eu que faço" é difícil de recuperar. Ponha-lhe o babete de silicone e observe a cena com paciência.', title_sv = 'Självständighetens fläckar 🥣', body_sv = 'Barnet vill absolut äta yoghurten med gaffel och allt blir nedkladdat. Lägg dig inte i och ta inte gaffeln ifrån barnet. Utspilld mat går att torka upp, men egot som säger ”jag gör det själv” är svårt att reparera. Sätt på silikonhaklappen och titta tålmodigt på.', title_vi = 'Những vết bẩn của tự do 🥣', body_vi = 'Bé nhất định đòi ăn sữa chua bằng nĩa và làm bẩn khắp nơi. Đừng can thiệp và giật lấy. Thức ăn rơi vãi thì lau được, nhưng cái tôi "con tự làm" của bé thì khó mà hàn gắn. Hãy đeo yếm silicon cho bé và kiên nhẫn quan sát.', title_zh = '自由的污渍 🥣', body_zh = '非要用叉子吃酸奶，弄得到处都是。别从旁插手把叉子拿走。洒了的食物能擦干净，可宝宝那份“我自己来”的自我一旦受伤就很难修复。给宝宝戴上硅胶围兜，耐心地看着吧。' WHERE id = '2824815e-ab93-4e74-b868-7dee6ae3bcac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los 10 minutos de mamá 🚪', body_es = 'El ruido te ha dejado el cerebro entumecido. Abre el Diario de ánimo, vuelca libremente en la pantalla todo lo que hoy te ha sacado de quicio y pulsa tu botón interior de reinicio.', title_fr = 'Les 10 minutes de maman 🚪', body_fr = 'Le bruit vous a engourdi le cerveau. Ouvrez le Journal d''humeur, déversez librement à l''écran tout ce qui vous a rendue folle aujourd''hui et appuyez sur votre bouton reset intérieur.', title_hi = 'माँ के 10 मिनट 🚪', body_hi = 'शोर ने आपका दिमाग सुन्न कर दिया है। मूड डायरी खोलिए, आज जिन बातों ने आपको पागल किया, सब खुलकर स्क्रीन पर उतारिए और अपना अंदर का रीसेट बटन दबाइए।', title_id = '10 menit milik Ibu 🚪', body_id = 'Kebisingan telah membuat otak Anda kebas. Buka Buku Harian Suasana Hati, tumpahkan dengan bebas semua yang membuat Anda gila hari ini ke layar, dan tekan tombol reset dalam diri Anda.', title_ja = 'ママの10分 🚪', body_ja = '騒がしさで頭がぼーっとしていますね。「気分日記」を開いて、今日あなたをいらだたせたことを全部自由に画面にはき出し、心のリセットボタンを押しましょう。', title_ko = '엄마의 10분 🚪', body_ko = '소음에 머리가 마비된 것 같나요? 기분 일기를 열고 오늘 나를 미치게 한 모든 걸 화면에 자유롭게 쏟아내며 마음속 리셋 버튼을 눌러 보세요.', title_nl = 'Mama''s 10 minuten 🚪', body_nl = 'Het lawaai heeft je brein verdoofd. Open je Stemmingsdagboek, schrijf vrijuit alles op wat je vandaag gek maakte en druk op je innerlijke resetknop.', title_pl = '10 minut dla mamy 🚪', body_pl = 'Hałas otępił ci mózg. Otwórz Dziennik nastroju, swobodnie wyrzuć na ekran wszystko, co dziś doprowadziło cię do szału, i wciśnij swój wewnętrzny przycisk reset.', title_pt = 'Os 10 minutos da mãe 🚪', body_pt = 'O barulho deixou-lhe o cérebro dormente. Abra o Diário de Humor, despeje à vontade no ecrã tudo o que hoje a deixou louca e carregue no seu botão interior de reset.', title_sv = 'Mammas 10 minuter 🚪', body_sv = 'Oljudet har bedövat din hjärna. Öppna Humördagboken, häll fritt ut allt som gjorde dig galen i dag på skärmen och tryck på din inre återställningsknapp.', title_vi = '10 phút của mẹ 🚪', body_vi = 'Tiếng ồn khiến đầu óc mẹ tê liệt. Hãy mở Nhật ký tâm trạng và trút thoải mái mọi thứ khiến mẹ phát điên hôm nay lên màn hình để nhấn nút "khởi động lại" bên trong mình.', title_zh = '妈妈的10分钟 🚪', body_zh = '噪音让你的大脑都麻木了。打开心情日记，把今天让你抓狂的一切自由地倒在屏幕上，按下内心的“重启”按钮。' WHERE id = '33c034f1-168d-424b-b367-21b9eb4799c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El encanto del cubo de la basura 📦', body_es = 'Con tantos juguetes caros y con luces, se pasa horas jugando con una botella de plástico vacía o una caja de cartón. La imaginación infantil no prefiere guiones ya hechos, sino objetos vacíos abiertos a la creatividad. Observa y aprende.', title_fr = 'L''attrait de la poubelle 📦', body_fr = 'Avec tous ces jouets chers et lumineux, il va jouer pendant des heures avec une bouteille d''eau en plastique vide ou un carton. L''imagination de l''enfant n''aime pas les scénarios tout faits, mais les objets vides ouverts à la créativité. Observez et apprenez.', title_hi = 'कचरे के डिब्बे का आकर्षण 📦', body_hi = 'इतने महँगे, रोशनी वाले खिलौने होते हुए भी वह एक खाली प्लास्टिक की बोतल या गत्ते के डिब्बे से घंटों खेलता है। बच्चे की कल्पना बनी-बनाई कहानियाँ नहीं, रचनात्मकता के लिए खुली खाली चीज़ें पसंद करती है। देखिए और सीखिए।', title_id = 'Daya tarik tempat sampah 📦', body_id = 'Padahal ada begitu banyak mainan mahal yang menyala, ia malah bermain berjam-jam dengan botol air plastik kosong atau kardus. Imajinasi anak tidak menyukai skenario jadi, melainkan benda kosong yang terbuka untuk kreativitas. Amati dan belajarlah.', title_ja = 'ゴミ箱の魅力 📦', body_ja = '高くて光るおもちゃがたくさんあるのに、空のペットボトルや段ボール箱で何時間も遊んでいる。子どもの想像力は、できあがったストーリーではなく、自由につくり変えられる空っぽのものが好きなんです。見守って、学んでみましょう。', title_ko = '쓰레기통의 매력 📦', body_ko = '비싸고 반짝이는 장난감이 그렇게 많은데 빈 플라스틱 물병이나 종이 상자로 몇 시간씩 노나요? 아이의 상상력은 정해진 시나리오보다 창의력에 열린 빈 물건을 좋아해요. 지켜보며 배워 보세요.', title_nl = 'De aantrekkingskracht van de prullenbak 📦', body_nl = 'Er liggen zoveel dure speeltjes met lichtjes, maar hij speelt urenlang met een lege plastic waterfles of een kartonnen doos. De fantasie van een kind houdt niet van kant-en-klare scenario''s, maar van lege dingen die openstaan voor creativiteit. Kijk en leer.', title_pl = 'Urok kosza na śmieci 📦', body_pl = 'Ma tyle drogich, świecących zabawek, a godzinami bawi się pustą plastikową butelką albo kartonowym pudełkiem. Dziecięca wyobraźnia nie kocha gotowych scenariuszy, tylko proste przedmioty otwarte na kreatywność. Obserwuj i ucz się.', title_pt = 'O encanto do caixote do lixo 📦', body_pt = 'Com tantos brinquedos caros e cheios de luzes, ele vai brincar horas a fio com uma garrafa de plástico vazia ou uma caixa de cartão. A imaginação da criança não gosta de histórias prontas, gosta de objetos vazios abertos à criatividade. Observe e aprenda.', title_sv = 'Soptunnans dragningskraft 📦', body_sv = 'Trots alla dyra leksaker med lampor leker barnet i timmar med en tom plastflaska eller en kartong. Barnets fantasi gillar inte färdiga scenarier, utan tomma saker som är öppna för kreativitet. Titta och lär.', title_vi = 'Sức hút của thùng rác 📦', body_vi = 'Có biết bao đồ chơi đắt tiền, phát sáng, vậy mà bé lại chơi hàng giờ với một chai nước nhựa rỗng hay hộp các-tông. Trí tưởng tượng của trẻ không thích kịch bản có sẵn, mà thích những đồ vật trống để thỏa sức sáng tạo. Hãy quan sát và học hỏi.', title_zh = '垃圾桶的魅力 📦', body_zh = '明明有那么多又贵又会发光的玩具，宝宝却抱着一个空塑料水瓶或纸箱玩上好几个小时。孩子的想象力喜欢的不是现成的剧本，而是能自由创造的空东西。观察，也学习。' WHERE id = '1fc95e57-80a1-42af-8907-c939c12adef9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La revolución del sueño ☁️', body_es = 'Nada más despertarse frunce el ceño y se enfada contigo. ¿El motivo? ¡En su sueño no le diste el juguete que quería! El cerebro infantil todavía no separa del todo el sueño de la realidad. Pídele perdón muy en serio y sonríe por dentro ante esta situación absurda.', title_fr = 'La révolution du rêve ☁️', body_fr = 'Dès son réveil, il fronce les sourcils et vous boude. La raison ? Dans son rêve, vous ne lui avez pas donné le jouet qu''il voulait ! Le cerveau de l''enfant ne sait pas encore bien séparer le rêve de la réalité. Excusez-vous sérieusement et souriez intérieurement de cette situation absurde.', title_hi = 'सपनों की क्रांति ☁️', body_hi = 'सुबह उठते ही भौंहें चढ़ाकर आपसे रूठ जाता है। वजह? उसके सपने में आपने उसे मनचाहा खिलौना नहीं दिया! बच्चे का दिमाग अभी सपने और हकीकत को पूरी तरह अलग नहीं कर पाता। गंभीरता से माफ़ी माँगिए और इस बेतुके हाल पर मन ही मन मुस्कुराइए।', title_id = 'Revolusi mimpi ☁️', body_id = 'Begitu bangun pagi, ia mengerutkan alis dan merajuk pada Anda. Alasannya? Di dalam mimpinya, Anda tidak memberinya mainan yang ia mau! Otak anak belum bisa sepenuhnya memisahkan mimpi dan kenyataan. Minta maaflah dengan serius dan tersenyumlah dalam hati pada situasi absurd ini.', title_ja = '夢の中の反乱 ☁️', body_ja = '朝起きるなり、眉をしかめてすねている。理由は？夢の中であなたがほしいおもちゃをくれなかったから！子どもの脳は、まだ夢と現実をきちんと区別できません。まじめにあやまって、このおかしな状況に心の中でほほえみましょう。', title_ko = '꿈의 혁명 ☁️', body_ko = '아침에 일어나자마자 눈살을 찌푸리며 삐졌나요? 이유는? 꿈속에서 엄마가 원하던 장난감을 안 줬대요! 아이의 뇌는 아직 꿈과 현실을 완전히 구분하지 못해요. 진지하게 사과하고 이 엉뚱한 상황에 속으로 미소 지어 보세요.', title_nl = 'Droomrevolutie ☁️', body_nl = 'Zodra hij wakker is, fronst hij en is hij boos op je. De reden? In zijn droom gaf je hem het speelgoed niet dat hij wilde! Een kinderbrein kan droom en werkelijkheid nog niet helemaal scheiden. Bied heel serieus je excuses aan en glimlach vanbinnen om deze absurde situatie.', title_pl = 'Rewolucja ze snu ☁️', body_pl = 'Zaraz po przebudzeniu marszczy brwi i się na ciebie obraża. Powód? We śnie nie dałaś mu zabawki, którą chciał! Dziecięcy mózg nie odróżnia jeszcze w pełni snu od rzeczywistości. Przeproś go z powagą i uśmiechnij się w duchu do tej absurdalnej sytuacji.', title_pt = 'A revolução do sonho ☁️', body_pt = 'Mal acorda, franze a testa e fica amuado consigo. A razão? No sonho dele, não lhe deu o brinquedo que queria! O cérebro da criança ainda não separa bem o sonho da realidade. Peça desculpa muito a sério e sorria por dentro desta situação absurda.', title_sv = 'Drömrevolutionen ☁️', body_sv = 'Så fort barnet vaknar rynkar det pannan och tjurar mot dig. Varför? I drömmen gav du inte barnet leksaken det ville ha! Barnets hjärna kan ännu inte helt skilja dröm från verklighet. Be om ursäkt på allvar och le inombords åt den absurda situationen.', title_vi = 'Cuộc cách mạng giấc mơ ☁️', body_vi = 'Vừa thức dậy, bé đã nhíu mày giận dỗi mẹ. Lý do? Trong giấc mơ của bé, mẹ đã không cho bé món đồ chơi bé muốn! Não bộ trẻ chưa phân biệt rõ được giấc mơ và thực tế. Hãy nghiêm túc xin lỗi và thầm mỉm cười trước tình huống ngộ nghĩnh này.', title_zh = '梦里的“革命” ☁️', body_zh = '早上一醒来就皱着眉生你的气。原因？在宝宝的梦里，你没给宝宝想要的玩具！孩子的大脑还没法完全分清梦和现实。认真地道个歉，心里对这荒诞的局面偷偷笑一笑吧。' WHERE id = '61bc311a-ba5b-43dc-b36e-6a65967f1df0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una mirada en silencio 🥂', body_es = 'Por fin se ha dormido. Tú y tu pareja estáis sentados juntos en el sofá y no tenéis fuerzas ni para hablar. Simplemente os miráis en silencio y sonreís. Sí, esa mirada silenciosa es la forma más bonita de decir «podemos con este caos».', title_fr = 'Un regard silencieux 🥂', body_fr = 'L''enfant dort enfin. Vous êtes assis côte à côte sur le canapé avec votre partenaire et vous n''avez même plus la force de parler. Vous vous regardez simplement en silence et vous souriez. Oui, ce regard silencieux est la plus belle façon de dire « on vient à bout de ce chaos ».', title_hi = 'खामोश नज़रें 🥂', body_hi = 'बच्चा आखिरकार सो गया। आप और आपके साथी सोफ़े पर साथ बैठे हैं और बात करने की भी ताकत नहीं। बस खामोशी में एक-दूसरे को देखकर मुस्कुरा रहे हैं। हाँ, यह खामोश नज़र ‘हम इस अफ़रा-तफ़री को संभाल रहे हैं’ कहने का सबसे प्यारा तरीका है।', title_id = 'Saling pandang tanpa kata 🥂', body_id = 'Anak akhirnya tidur. Anda dan pasangan duduk berdampingan di sofa, bahkan tak punya tenaga untuk bicara. Kalian hanya saling memandang dalam hening dan tersenyum. Ya, tatapan tanpa kata ini adalah cara terindah untuk berkata ''Kita sanggup menghadapi kekacauan ini''.', title_ja = '言葉のない見つめ合い 🥂', body_ja = 'やっと子どもが寝ました。あなたとパートナーはソファに並んで座り、話す元気さえ残っていません。ただ静けさの中で見つめ合って、ほほえむだけ。そう、この無言の見つめ合いこそ「わたしたち、このカオスを乗りこえている」と伝えるいちばんすてきな方法です。', title_ko = '말없는 눈맞춤 🥂', body_ko = '아이가 드디어 잠들었어요. 배우자와 소파에 나란히 앉았지만 말할 힘조차 없죠. 그저 조용히 서로를 보며 미소 짓나요? 네, 이 말없는 눈맞춤이 ''우리 이 혼돈을 잘 해내고 있어''라고 말하는 가장 아름다운 방법이에요.', title_nl = 'Een stille blik 🥂', body_nl = 'Je kind slaapt eindelijk. Jij en je partner zitten naast elkaar op de bank en hebben niet eens de energie om te praten. Jullie kijken elkaar alleen in stilte aan en glimlachen. Ja, die stille blik is de mooiste manier om te zeggen: ''We kunnen deze chaos aan.''', title_pl = 'Ciche spojrzenia 🥂', body_pl = 'Dziecko w końcu zasnęło. Siedzicie z partnerem obok siebie na kanapie i nie macie siły nawet rozmawiać. Po prostu patrzycie na siebie w ciszy i się uśmiechacie. Tak, to ciche spojrzenie to najpiękniejszy sposób, by powiedzieć „dajemy radę z tym chaosem”.', title_pt = 'Olhares em silêncio 🥂', body_pt = 'A criança finalmente adormeceu. Está sentada no sofá ao lado do seu companheiro e nem têm forças para falar. Limitam-se a olhar um para o outro e a sorrir em silêncio. Pois é, este olhar silencioso é a forma mais bonita de dizer "estamos a dar conta deste caos".', title_sv = 'Tysta blickar 🥂', body_sv = 'Äntligen sover barnet. Du och din partner sitter bredvid varandra i soffan och orkar inte ens prata. Ni bara tittar på varandra i tystnad och ler. Ja, den tysta blicken är det vackraste sättet att säga ”vi klarar det här kaoset”.', title_vi = 'Ánh mắt lặng lẽ 🥂', body_vi = 'Cuối cùng bé cũng ngủ. Hai vợ chồng ngồi cạnh nhau trên sofa, mệt đến mức chẳng còn sức nói. Chỉ nhìn nhau trong im lặng và mỉm cười. Đúng vậy, ánh mắt lặng lẽ ấy là cách đẹp nhất để nói "Chúng ta đang vượt qua mớ hỗn loạn này".', title_zh = '无声的对视 🥂', body_zh = '宝宝终于睡着了。你和伴侣并排坐在沙发上，连说话的力气都没有了。只是在安静中看着对方笑一笑。是的，这无声的对视，就是说“这场混乱我们能搞定”最美的方式。' WHERE id = 'c193e688-7d18-417e-aa1d-53580a727596' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Teatro en la pared 🐰', body_es = 'Con la excusa de que le da miedo la oscuridad, se escapa de la cama. Apaga todas las luces de la habitación, enciende una linterna y haz con las manos sombras de pájaros y perros en la pared. La oscuridad que le asusta se convertirá en segundos en el teatro más seguro del mundo.', title_fr = 'Théâtre sur le mur 🐰', body_fr = 'Il prétexte avoir peur du noir pour s''échapper du lit. Éteignez toutes les lumières de la chambre, allumez une lampe de poche et créez avec vos mains des ombres d''oiseau et de chien sur le mur. En quelques secondes, le noir qui lui faisait peur deviendra le théâtre le plus rassurant du monde.', title_hi = 'दीवार पर नाटक 🐰', body_hi = 'अँधेरे से डर का बहाना बनाकर बिस्तर से भागता है। कमरे की सारी लाइटें बंद कीजिए, टॉर्च जलाइए और दीवार पर हाथों से चिड़िया, कुत्ते की परछाइयाँ बनाइए। जिस अँधेरे से वह डरता है, वह सेकंडों में उसके लिए दुनिया का सबसे सुरक्षित थिएटर बन जाएगा।', title_id = 'Teater di dinding 🐰', body_id = 'Ia menjadikan takut gelap sebagai alasan untuk kabur dari tempat tidur. Matikan semua lampu kamar, nyalakan senter, dan buat bayangan burung dan anjing di dinding dengan tangan Anda. Dalam hitungan detik, gelap yang ia takuti akan berubah menjadi teater paling aman di dunia baginya.', title_ja = '壁の劇場 🐰', body_ja = '暗いのが怖いと言いわけしてベッドから逃げだす。部屋の明かりを全部消して懐中電灯をつけ、壁に手で鳥や犬の影絵をつくりましょう。怖がっていた暗やみが、あっという間に世界でいちばん安全な劇場に変わります。', title_ko = '벽 위의 극장 🐰', body_ko = '어둠이 무섭다는 핑계로 침대에서 도망치나요? 방의 불을 모두 끄고 손전등을 켜서 손으로 벽에 새와 강아지 그림자를 만들어 보세요. 무서웠던 어둠이 몇 초 만에 세상에서 가장 안전한 극장으로 바뀔 거예요.', title_nl = 'Theater op de muur 🐰', body_nl = 'Hij gebruikt zijn angst voor het donker als smoes om uit bed te gaan. Doe alle lichten in de kamer uit, zet een zaklamp aan en maak met je handen schaduwen van vogels en honden op de muur. Het donker waar hij bang voor was, wordt binnen een paar seconden het veiligste theater ter wereld.', title_pl = 'Teatr na ścianie 🐰', body_pl = 'Wymawia się strachem przed ciemnością i ucieka z łóżka. Zgaś wszystkie światła w pokoju, włącz latarkę i zrób dłońmi na ścianie cienie ptaka i pieska. Ciemność, której się bał, w kilka sekund zmieni się dla niego w najbezpieczniejszy teatr na świecie.', title_pt = 'Teatro na parede 🐰', body_pt = 'Usa o medo do escuro como desculpa para fugir da cama. Apague todas as luzes do quarto, acenda a lanterna e faça com as mãos sombras de pássaros e cães na parede. Em segundos, o escuro de que tem medo vai transformar-se no teatro mais seguro do mundo.', title_sv = 'Teater på väggen 🐰', body_sv = 'Barnet skyller på att det är mörkrädd och springer ur sängen. Släck alla lampor i rummet, tänd ficklampan och forma fåglar och hundar som skuggor på väggen med händerna. Mörkret som barnet är rädd för blir på några sekunder världens tryggaste teater.', title_vi = 'Nhà hát trên tường 🐰', body_vi = 'Bé lấy cớ sợ bóng tối để trốn khỏi giường. Hãy tắt hết đèn trong phòng, bật đèn pin và dùng tay tạo bóng chim, bóng chó trên tường. Bóng tối bé sợ sẽ biến thành nhà hát an toàn nhất thế giới chỉ trong vài giây.', title_zh = '墙上的剧场 🐰', body_zh = '拿怕黑当借口从床上溜走。关掉房间所有的灯，打开手电筒，用手在墙上做出小鸟、小狗的影子。宝宝害怕的黑暗，几秒钟就会变成世界上最安全的剧场。' WHERE id = '98f98e2b-5170-4983-96d7-fe8b44837cdf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica para salir del parque 🌳', body_es = 'Es hora de volver del parque y han empezado las crisis de llanto. No intentes llevártelo a rastras. Crea una competición: «¿A ver quién llega antes corriendo al coche?». Los niños nunca dicen que no a competir y ganar.', title_fr = 'Tactique pour quitter le parc 🌳', body_fr = 'C''est l''heure de rentrer du parc et la crise de larmes commence. N''essayez pas de le traîner. Lancez un défi : « Voyons qui courra le plus vite jusqu''à la voiture ! » Les enfants ne disent jamais non à une course et à une victoire.', title_hi = 'पार्क से निकलने की चाल 🌳', body_hi = 'पार्क से लौटने का समय है और रोना शुरू हो गया है। उसे घसीटकर ले जाने की कोशिश मत कीजिए। ‘देखें, गाड़ी तक पहले कौन दौड़कर पहुँचता है?’ कहकर मुकाबला बनाइए। बच्चे दौड़ने और जीतने को कभी ‘ना’ नहीं कहते।', title_id = 'Taktik pulang dari taman 🌳', body_id = 'Saatnya pulang dari taman, dan krisis tangis dimulai. Jangan mencoba menyeretnya. Ciptakan persaingan dengan berkata ''Ayo lihat siapa yang paling cepat lari sampai ke mobil!''. Anak-anak tak pernah menolak berlomba dan menang.', title_ja = '公園から帰る作戦 🌳', body_ja = '公園から帰る時間になって、大泣きが始まりました。引きずって連れていこうとしないで。「車までどっちが早く走れるかな？」と競争にしましょう。子どもは競争と勝つことに、決して「いや」とは言いません。', title_ko = '공원 탈출 작전 🌳', body_ko = '공원에서 돌아갈 시간인데 울음이 터졌나요? 끌고 가려 하지 마세요. ''차까지 누가 먼저 뛰어가나 볼까?''라며 경쟁을 만들어 보세요. 아이들은 시합과 승리에 절대 ''싫어''라고 하지 않아요.', title_nl = 'Vertrektactiek in het park 🌳', body_nl = 'Het is tijd om uit het park te gaan en de huilbuien zijn begonnen. Probeer hem niet mee te sleuren. Maak er een wedstrijdje van: ''Wie is het eerst bij de auto?'' Kinderen zeggen nooit nee tegen een wedstrijd en winnen.', title_pl = 'Taktyka wyjścia z parku 🌳', body_pl = 'Czas wracać z parku i zaczynają się kryzysy z płaczem. Nie próbuj go ciągnąć. Zrób z tego wyścig: „Zobaczmy, kto szybciej dobiegnie do samochodu?”. Dzieci nigdy nie odmawiają rywalizacji i wygranej.', title_pt = 'Tática para sair do parque 🌳', body_pt = 'É hora de voltar do parque e começaram as crises de choro. Não tente levá-lo de arrasto. Crie uma competição: "Vamos ver quem chega primeiro ao carro?". As crianças nunca dizem não a uma corrida e a ganhar.', title_sv = 'Taktik för att lämna parken 🌳', body_sv = 'Det är dags att gå hem från parken och gråtkriserna har börjat. Försök inte släpa iväg barnet. Skapa en tävling: ”Får se vem som springer snabbast till bilen?” Barn säger aldrig nej till att tävla och vinna.', title_vi = 'Chiến thuật rời công viên 🌳', body_vi = 'Đã đến giờ về nhà và những cơn khóc bắt đầu. Đừng cố kéo bé đi. Hãy tạo một cuộc thi: "Xem ai chạy đến xe nhanh hơn nào?". Trẻ con không bao giờ từ chối một cuộc đua và cơ hội chiến thắng.', title_zh = '离开公园的战术 🌳', body_zh = '该从公园回家了，哭闹也开始了。别想着把宝宝硬拖走。说一句“看谁先跑到车那儿？”，来点小比赛。孩子从来不会拒绝比赛和赢。' WHERE id = 'bf60fea7-a806-46ec-a023-ae8a1e62e95a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El invitado invisible 👻', body_es = 'En el desayuno te pide que pongas también un plato en la mesa para su amigo imaginario. No es un vacío psicológico, es un salto de la inteligencia. Pon ese plato y sírvele también un té imaginario a vuestro invitado: forma parte de este teatro maravilloso.', title_fr = 'L''invité invisible 👻', body_fr = 'Au petit-déjeuner, il exige que vous mettiez aussi une assiette pour son ami imaginaire. Ce n''est pas un manque psychologique, c''est un bond de son intelligence. Posez cette assiette et servez aussi un thé imaginaire à votre invité pour faire partie de ce formidable théâtre.', title_hi = 'अदृश्य मेहमान 👻', body_hi = 'नाश्ते पर ज़िद करता है कि मेज़ पर उसके काल्पनिक दोस्त के लिए भी प्लेट रखी जाए। यह कोई मानसिक कमी नहीं, समझ की छलाँग है। वह प्लेट वहाँ रखिए, मेहमान के लिए काल्पनिक चाय डालिए और इस शानदार नाटक का हिस्सा बनिए।', title_id = 'Tamu tak kasatmata 👻', body_id = 'Saat sarapan ia menuntut Anda menaruh piring juga untuk teman khayalannya. Ini bukan kekosongan psikologis, melainkan lompatan kecerdasan. Taruh piring itu di sana, tuangkan teh khayalan untuk tamu Anda, dan jadilah bagian dari teater hebat ini.', title_ja = '見えないお客さま 👻', body_ja = '朝ごはんのテーブルに、空想のお友だちの分のお皿も置いてとせがむ。これは心のすきまではなく、知能の飛躍です。お皿を置いて、お客さまにも空想のお茶を注ぎ、このすばらしい劇の一員になりましょう。', title_ko = '보이지 않는 손님 👻', body_ko = '아침 식사 때 상상 속 친구의 접시도 놓아 달라고 하나요? 마음의 공백이 아니라 지능의 도약이에요. 접시를 놓아 주고 손님에게 상상의 차도 따라 주며 이 멋진 연극의 일부가 되어 보세요.', title_nl = 'De onzichtbare gast 👻', body_nl = 'Bij het ontbijt wil hij dat je ook een bord neerzet voor zijn denkbeeldige vriendje. Dat is geen psychische leegte, maar een sprong in intelligentie. Zet dat bord neer, schenk je gast ook denkbeeldige thee in en word deel van dit prachtige theater.', title_pl = 'Niewidzialny gość 👻', body_pl = 'Przy śniadaniu domaga się, żebyś postawiła talerz także dla jego wymyślonego przyjaciela. To nie psychologiczna pustka, tylko skok inteligencji. Postaw ten talerz, nalej gościowi wymyślonej herbaty i stań się częścią tego wspaniałego teatru.', title_pt = 'O convidado invisível 👻', body_pt = 'Ao pequeno-almoço exige que ponha na mesa um prato também para o amigo imaginário. Não é um vazio psicológico, é um salto da inteligência. Ponha lá o prato, sirva também um chá imaginário ao convidado e faça parte deste espetáculo fantástico.', title_sv = 'Den osynliga gästen 👻', body_sv = 'Vid frukosten kräver barnet att du ställer fram en tallrik till dess låtsasvän också. Det är inte ett psykologiskt tomrum, det är ett språng i intelligensen. Ställ fram tallriken, häll upp låtsaste åt gästen och bli en del av den fantastiska teatern.', title_vi = 'Vị khách vô hình 👻', body_vi = 'Bữa sáng, bé đòi mẹ đặt thêm một chiếc đĩa cho người bạn tưởng tượng. Đây không phải là khoảng trống tâm lý, mà là bước nhảy vọt của trí tuệ. Hãy đặt chiếc đĩa ấy lên bàn, rót cho vị khách một tách trà tưởng tượng và trở thành một phần của vở kịch tuyệt vời này.', title_zh = '看不见的客人 👻', body_zh = '早餐时要求你在桌上也给想象中的朋友摆一个盘子。这不是心理上的空缺，而是智力的飞跃。把盘子摆上，也给客人倒一杯想象中的茶，成为这出精彩戏剧的一部分吧。' WHERE id = 'e6013d08-4f44-4955-a2ce-c8556d1e2010' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El fruto del trabajo en equipo 🥂', body_es = 'Habéis dejado atrás otro día difícil y tormentoso. Cuando el peque se duerma, servíos un té tú y tu pareja y daos las gracias: «Hoy también hemos sobrevivido a este caos, somos un gran equipo». Criar no es cosa de uno solo: se vuelve bonito con apoyo.', title_fr = 'Le fruit du travail d''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une nouvelle journée difficile et agitée. Une fois l''enfant couché, servez-vous un thé avec votre partenaire et remerciez-vous : « On a survécu à ce chaos aujourd''hui aussi, on fait une super équipe. » Être parent, ça ne se fait pas seul, c''est plus beau avec du soutien.', title_hi = 'टीमवर्क का फल 🥂', body_hi = 'एक और मुश्किल, तूफ़ानी दिन पीछे छूट गया। बच्चे के सोने के बाद अपने साथी के साथ चाय डालिए और ‘आज हम इस अफ़रा-तफ़री से भी निकल आए, हम कमाल की टीम हैं’ कहकर शुक्रिया कीजिए। पेरेंटिंग अकेले नहीं, साथ से खूबसूरत बनती है।', title_id = 'Buah kerja sama tim 🥂', body_id = 'Kalian sudah melewati satu lagi hari yang berat dan penuh badai. Setelah anak tidur, tuang teh bersama pasangan dan berterima kasihlah: ''Hari ini kita selamat dari kekacauan ini, kita tim yang hebat''. Menjadi orang tua bukan perjalanan sendirian, ia menjadi indah dengan dukungan.', title_ja = 'チームワークの成果 🥂', body_ja = '大変で嵐のような一日を、また乗りこえましたね。子どもが寝たら、パートナーとお茶をいれて「今日もこのカオスを乗りきったね、最高のチームだね」と感謝を伝えましょう。子育てはひとりではなく、支え合うことですてきになります。', title_ko = '팀워크의 열매 🥂', body_ko = '또 하루, 힘들고 폭풍 같은 날을 보냈어요. 아이가 잠들면 배우자와 차 한 잔을 따르고 ''오늘도 이 혼돈에서 살아남았어, 우리 최고의 팀이야''라며 고마움을 전하세요. 육아는 혼자가 아니라 서로의 응원으로 아름다워져요.', title_nl = 'De vruchten van teamwerk 🥂', body_nl = 'Weer een zware, stormachtige dag achter de rug. Schenk als je kind slaapt een kop thee in met je partner en bedank elkaar: ''Ook deze chaos hebben we vandaag overleefd, we zijn een top-team.'' Ouderschap doe je niet alleen, het wordt mooi met steun.', title_pl = 'Owoce pracy zespołowej 🥂', body_pl = 'Kolejny trudny i burzliwy dzień za wami. Gdy dziecko zaśnie, nalejcie sobie z partnerem herbaty i podziękujcie sobie: „Dziś też wyszliśmy cało z tego chaosu, jesteśmy świetną drużyną”. Rodzicielstwo nie jest w pojedynkę, piękne staje się dzięki wsparciu.', title_pt = 'Os frutos do trabalho de equipa 🥂', body_pt = 'Deixaram para trás mais um dia difícil e tempestuoso. Depois de a criança adormecer, sirvam um chá e agradeça ao seu companheiro: "Hoje também sobrevivemos ao caos, somos uma ótima equipa". A parentalidade não fica bonita sozinha, mas com apoio.', title_sv = 'Frukten av lagarbetet 🥂', body_sv = 'Ännu en tuff och stormig dag ligger bakom er. När barnet har somnat, häll upp te med din partner och tacka: ”I dag överlevde vi det här kaoset också, vi är ett toppenlag.” Föräldraskap gör man inte ensam, det blir vackert med stöd.', title_vi = 'Thành quả của tinh thần đồng đội 🥂', body_vi = 'Thêm một ngày khó khăn, sóng gió đã qua. Sau khi bé ngủ, hãy cùng chồng pha một ấm trà và cảm ơn nhau: "Hôm nay mình lại vượt qua mớ hỗn loạn này rồi, mình là một đội tuyệt vời". Làm cha mẹ không phải hành trình một mình, mà đẹp hơn khi có sự hỗ trợ.', title_zh = '团队合作的成果 🥂', body_zh = '又一个艰难又暴风雨般的一天过去了。宝宝睡着后，和伴侣倒杯茶，说声谢谢：“今天这场混乱我们也挺过来了，我们是最棒的团队。”育儿不是一个人的事，有了支持才会变得美好。' WHERE id = '07a807e7-5500-4214-ab98-d5372a84c109' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Zapatos al revés 👟', body_es = 'Se ha puesto los zapatos al revés, pero camina tan orgulloso como si hubiera conquistado el mundo. Si intervienes para arreglarlo, se estropeará todo. Su autoestima y su independencia importan más que la estética. Deja que este pequeño rebelde camine con orgullo.', title_fr = 'Chaussures inversées 👟', body_fr = 'Il a mis ses chaussures au mauvais pied, mais il marche si fièrement qu''on dirait qu''il a conquis le monde. Si vous intervenez pour corriger, tout sera gâché. Sa confiance en lui et son indépendance comptent plus que l''esthétique. Laissez ce petit rebelle avancer fièrement.', title_hi = 'उलटे जूते 👟', body_hi = 'जूते उलटे पहन लिए, पर इतने गर्व से चल रहा है जैसे दुनिया जीत ली हो। बीच में आकर ठीक करने की कोशिश करेंगी तो सब बिगड़ जाएगा। उसका आत्मविश्वास और आत्मनिर्भरता सुंदरता से ज़्यादा ज़रूरी है। इस नन्हे बागी को गर्व से कदम बढ़ाने दीजिए।', title_id = 'Sepatu terbalik 👟', body_id = 'Ia memakai sepatu terbalik, tapi berjalan dengan begitu bangga seolah baru menaklukkan dunia. Jika Anda campur tangan dan membetulkannya, semuanya akan hancur. Rasa percaya diri dan kemandiriannya lebih penting daripada estetika. Biarkan pemberontak kecil ini melangkah dengan bangga.', title_ja = '左右反対の靴 👟', body_ja = '靴を左右反対にはいているのに、世界を征服したかのように誇らしげに歩いています。手を出して直そうとしたら、すべてが台なし。自信と自立心は見た目より大切です。この小さな反逆児に、胸をはって歩かせてあげましょう。', title_ko = '거꾸로 신은 신발 👟', body_ko = '신발을 좌우 바꿔 신고도 세상을 정복한 듯 당당하게 걷나요? 끼어들어 고치려 하면 모든 게 무너질 거예요. 자신감과 독립심이 보기 좋은 것보다 중요해요. 이 작은 반항아가 뿌듯하게 걷게 해 주세요.', title_nl = 'Verkeerde schoenen 👟', body_nl = 'Hij heeft zijn schoenen aan de verkeerde voeten, maar loopt zo trots alsof hij de wereld heeft veroverd. Probeer je in te grijpen en het te verbeteren, dan is alles verpest. Zijn zelfvertrouwen en zelfstandigheid zijn belangrijker dan esthetiek. Laat deze kleine rebel trots verder stappen.', title_pl = 'But nie na tę nogę 👟', body_pl = 'Założył buty na odwrót, ale chodzi tak dumny, jakby podbił świat. Jeśli spróbujesz to poprawić, wszystko legnie w gruzach. Jego pewność siebie i samodzielność są ważniejsze niż estetyka. Niech ten mały buntownik kroczy z dumą.', title_pt = 'Sapatos trocados 👟', body_pt = 'Calçou os sapatos trocados, mas anda tão orgulhoso como se tivesse conquistado o mundo. Se intervier para os trocar, estraga tudo. A autoestima e a independência são mais importantes do que a estética. Deixe este pequeno rebelde caminhar com orgulho.', title_sv = 'Skorna på fel fot 👟', body_sv = 'Barnet har tagit skorna på fel fötter men går så stolt omkring som om det erövrat världen. Försöker du lägga dig i och rätta till förstörs allt. Självförtroende och självständighet är viktigare än estetik. Låt den lilla rebellen gå stolt.', title_vi = 'Đi giày ngược 👟', body_vi = 'Bé đi ngược giày nhưng bước đi kiêu hãnh như vừa chinh phục cả thế giới. Nếu mẹ can thiệp sửa lại, mọi thứ sẽ đổ vỡ. Sự tự tin và tự lập của bé quan trọng hơn thẩm mỹ. Cứ để "kẻ nổi loạn" tí hon này tự hào sải bước.', title_zh = '穿反的鞋 👟', body_zh = '鞋穿反了，却走得那么骄傲，好像征服了全世界。要是你插手去纠正，一切就全毁了。自信和独立比好看更重要。就让这个小小的叛逆者骄傲地迈步吧。' WHERE id = '7715199a-4ef6-480d-9548-a833acc549dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sabotaje en la cocina 🧑‍🍳', body_es = 'Mientras extiendes la masa, viene, mete la mano en la harina y lo deja todo blanco. Sí, la cocina está hecha un desastre. Pero graba al instante esa cara seria y trabajadora con la Sesión de fotos del bebé. La limpieza se resolverá, y esa escena tan cómica quedará para siempre.', title_fr = 'Sabotage en cuisine 🧑‍🍳', body_fr = 'Pendant que vous étalez la pâte, il plonge la main dans la farine et blanchit tout. Oui, la cuisine est sens dessus dessous. Mais immortalisez tout de suite son air sérieux et appliqué avec la Séance photo bébé. Le ménage se fera, cette photo comique, elle, restera pour toujours.', title_hi = 'रसोई में तोड़फोड़ 🧑‍🍳', body_hi = 'आप आटा बेल रही हैं और वह आकर आटे में हाथ डालकर हर जगह सफ़ेद कर देता है। हाँ, रसोई गंदी हो गई। पर उसका वह गंभीर, कामकाजी चेहरा बेबी फ़ोटोशूट से तुरंत कैद कर लीजिए। सफ़ाई तो हो जाएगी, पर वह मज़ेदार तस्वीर हमेशा रहेगी।', title_id = 'Sabotase di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia datang, memasukkan tangan ke tepung, dan membuat semuanya putih. Ya, dapur berantakan. Tapi segera abadikan wajahnya yang serius dan sibuk itu dengan Pemotretan Bayi. Bersih-bersih akan beres, tapi foto lucu itu akan abadi.', title_ja = 'キッチンで妨害工作 🧑‍🍳', body_ja = 'あなたが生地をのばしていると、やってきて粉に手をつっこみ、あたりを真っ白に。そう、キッチンは粉だらけ。でもその真剣でまじめな顔を、すぐに「ベビーフォトセッション」で撮っておきましょう。お掃除はなんとかなるけれど、このおかしな一枚はずっと残ります。', title_ko = '부엌의 대소동 🧑‍🍳', body_ko = '반죽을 밀고 있는데 와서 밀가루에 손을 넣고 온 사방을 하얗게 만들었나요? 네, 부엌은 엉망이죠. 하지만 그 진지하고 바쁜 표정을 바로 아기 사진 촬영으로 담아 두세요. 청소는 끝나겠지만 그 웃긴 장면은 영원히 남아요.', title_nl = 'Sabotage in de keuken 🧑‍🍳', body_nl = 'Terwijl jij deeg uitrolt, steekt hij zijn hand in de bloem en maakt alles spierwit. Ja, de keuken is een zooi. Maar leg dat serieuze, zakelijke gezichtje meteen vast met de Babyfotoshoot. Het schoonmaken komt wel goed, dat grappige plaatje blijft voor altijd.', title_pl = 'Dywersja w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, wkłada rękę do mąki i wszystko robi się białe. Tak, kuchnia w opłakanym stanie. Ale od razu uwiecznij jego poważną, rzeczową minę w Sesji zdjęciowej dziecka. Sprzątanie się załatwi, a ten zabawny kadr zostanie na zawsze.', title_pt = 'Sabotagem na cozinha 🧑‍🍳', body_pt = 'Enquanto estende a massa, ele vem, mete a mão na farinha e deixa tudo branquinho. Sim, a cozinha ficou um caos. Mas registe já aquela cara séria e trabalhadora com a Sessão Fotográfica do Bebé. A limpeza resolve-se, mas aquela imagem cómica fica para sempre.', title_sv = 'Sabotage i köket 🧑‍🍳', body_sv = 'När du kavlar deg kommer barnet, sticker ner handen i mjölet och gör allt kritvitt. Ja, köket blev nedkladdat. Men fånga genast barnets allvarliga, arbetsamma min med Babyfotografering. Städningen löser sig, men den roliga bilden blir kvar för alltid.', title_vi = 'Phá phách trong bếp 🧑‍🍳', body_vi = 'Mẹ đang cán bột thì bé chạy đến thọc tay vào bột, làm mọi thứ trắng xóa. Đúng vậy, bếp bừa bộn rồi. Nhưng hãy ghi lại ngay vẻ mặt nghiêm túc, chăm chỉ ấy của bé bằng Chụp ảnh cho bé. Việc dọn dẹp rồi sẽ xong, còn khoảnh khắc hài hước ấy sẽ ở lại mãi.', title_zh = '厨房里的“破坏行动” 🧑‍🍳', body_zh = '你擀面团时，宝宝跑过来把手伸进面粉里，弄得到处白茫茫。是的，厨房一团糟。但马上用宝宝写真把宝宝那副认真能干的小表情拍下来吧。打扫总能搞定，而那个搞笑的画面会永远留下。' WHERE id = 'b205ec5f-9776-4abd-8a5c-b967e050819e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un espejo viviente 🦜', body_es = 'Riñe a su juguete poniendo exactamente la misma cara que pones tú cuando te enfadas. ¡Mírate desde fuera ahora mismo! Copia todo lo que ve. Esta escena cómica pero que da que pensar es un buen espejo para prestar más atención a tu comportamiento.', title_fr = 'Le miroir vivant 🦜', body_fr = 'Il gronde son jouet en reproduisant exactement la mimique que vous faites quand vous êtes énervée. Observez-vous tout de suite de l''extérieur ! Il copie tout ce qu''il voit. Cette scène comique mais qui fait réfléchir est un joli miroir pour faire plus attention à votre comportement.', title_hi = 'जीता-जागता आईना 🦜', body_hi = 'आप गुस्से में जो चेहरा बनाती हैं, हूबहू वैसा ही बनाकर अपने खिलौने को डाँट रहा है। तुरंत खुद को बाहर से देखिए! वह जो देखता है, वही नकल करता है। यह मज़ेदार, पर सोचने पर मजबूर करने वाला नज़ारा अपने व्यवहार पर और ध्यान देने के लिए एक अच्छा आईना है।', title_id = 'Cermin hidup 🦜', body_id = 'Ia memarahi mainannya dengan ekspresi wajah yang persis sama seperti saat Anda marah. Segera amati diri Anda dari luar! Ia meniru apa pun yang ia lihat. Pemandangan lucu namun membuat berpikir ini adalah cermin yang baik untuk lebih memperhatikan perilaku Anda.', title_ja = '生きている鏡 🦜', body_ja = 'あなたが怒ったときの顔をそっくりまねして、おもちゃをしかっています。すぐに自分のことを外から見てみて！この子は見たものをそのまままねします。おかしいけれど考えさせられるこの光景は、自分のふるまいにもっと気をつけるためのすてきな鏡です。', title_ko = '살아 있는 거울 🦜', body_ko = '엄마가 화날 때 짓는 표정을 똑같이 지으며 장난감을 혼내나요? 바로 나를 밖에서 바라보세요! 아이는 보는 대로 따라 해요. 이 웃기지만 생각하게 만드는 장면은 내 행동을 더 살피게 해 주는 멋진 거울이에요.', title_nl = 'Levende spiegel 🦜', body_nl = 'Hij moppert op zijn knuffel en trekt precies hetzelfde gezicht als jij wanneer je boos bent. Bekijk jezelf meteen van buitenaf! Hij kopieert alles wat hij ziet. Dit grappige maar ook tot nadenken stemmende beeld is een mooie spiegel om beter op je eigen gedrag te letten.', title_pl = 'Żywe lustro 🦜', body_pl = 'Beszta swoją zabawkę, robiąc dokładnie taką minę jak ty, gdy się złościsz. Od razu spójrz na siebie z boku! Kopiuje wszystko, co widzi. Ten zabawny, ale dający do myślenia widok to piękne lustro, które przypomina, by bardziej uważać na swoje zachowanie.', title_pt = 'Um espelho vivo 🦜', body_pt = 'Ralha com o brinquedo fazendo exatamente a cara que a mãe faz quando se irrita. Observe-se já de fora! Ele copia tudo o que vê. Esta cena cómica, mas que dá que pensar, é um ótimo espelho para prestar mais atenção ao seu comportamento.', title_sv = 'En levande spegel 🦜', body_sv = 'Barnet skäller på sin leksak med exakt samma min som du gör när du blir irriterad. Titta genast på dig själv utifrån! Barnet kopierar det det ser. Den roliga men tankeväckande bilden är en fin spegel som påminner dig om att vara mer uppmärksam på ditt beteende.', title_vi = 'Tấm gương sống 🦜', body_vi = 'Bé mắng đồ chơi với đúng vẻ mặt mẹ hay làm khi bực bội. Hãy nhìn lại bản thân ngay! Bé thấy gì sẽ bắt chước nấy. Khung cảnh hài hước nhưng đáng suy ngẫm này là tấm gương tuyệt vời để mẹ chú ý hơn đến hành vi của mình.', title_zh = '活生生的镜子 🦜', body_zh = '模仿你生气时的表情，一模一样地训斥自己的玩具。马上从旁看看自己吧！宝宝看到什么就模仿什么。这个搞笑却发人深省的画面，是一面让你更留意自己言行的好镜子。' WHERE id = '18bd2439-9788-43c4-81c5-8852d0241a0d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te sabes de memoria los libros de siempre y estás cansada de leerlos. Abre Cuentos inteligentes. Diseña una historia con tu peque como protagonista y sonidos relajantes del bosque de fondo, y crea una sesión de sueño original que no exige ningún esfuerzo.', body_fr = 'Vous connaissez les livres classiques par cœur et vous êtes fatiguée de les lire. Ouvrez les Contes intelligents. Faites de votre enfant le héros, avec des sons apaisants de la forêt en fond, et créez une séance d''endormissement originale qui ne demande aucun effort.', body_hi = 'पुरानी किताबें आपको रट चुकी हैं और पढ़ते-पढ़ते थक गई हैं। स्मार्ट कहानियाँ खोलिए। मुख्य हीरो अपने बच्चे को और बैकग्राउंड में सुकून भरी जंगल की आवाज़ें रखकर एक अनोखा, बिना मेहनत वाला नींद का सत्र बनाइए।', body_id = 'Anda sudah hafal buku-buku klasik dan lelah membacanya. Buka Dongeng Pintar. Jadikan anak Anda tokoh utamanya dan suara hutan yang menenangkan sebagai latar, lalu ciptakan sesi tidur yang tidak biasa tanpa usaha apa pun.', body_ja = '定番の絵本はもう暗記してしまって、読むのに疲れた？「スマートおはなし」を開きましょう。主人公はお子さん、背景には心落ち着く森の音を選んで、いつもとちがう、まったく手間のかからない寝かしつけタイムをつくりましょう。', body_ko = '늘 읽던 책은 다 외웠고 읽는 것도 지쳤나요? 스마트 동화를 열어 보세요. 주인공은 아이로, 배경은 차분한 숲 소리로 꾸며 특별하고 힘들이지 않는 잠자리 시간을 만들어 보세요.', body_nl = 'Je kent de klassieke boeken uit je hoofd en bent het voorlezen moe. Open Slimme sprookjes. Maak je kind de hoofdpersoon, kies rustgevende bosgeluiden als achtergrond en creëer een bijzondere slaapsessie die je geen moeite kost.', body_pl = 'Klasyczne książeczki znasz już na pamięć i masz dość czytania. Otwórz Mądre bajki. Uczyń głównym bohaterem swoje dziecko, a tłem kojące odgłosy lasu, i stwórz niezwykły seans usypiania, który nie wymaga żadnego wysiłku.', body_pt = 'Já sabe os livros clássicos de cor e está cansada de os ler. Abra as Histórias Inteligentes. Crie uma história com o seu filho como herói principal e sons calmantes da floresta como fundo, e prepare uma sessão de sono fora do comum, sem esforço nenhum.', body_sv = 'Du kan de klassiska böckerna utantill och är trött på att läsa dem. Öppna Smarta sagor. Gör barnet till huvudperson och lugnande skogsljud till bakgrund, så skapar du en ovanlig sovstund som inte kräver någon ansträngning.', body_vi = 'Mẹ đã thuộc lòng những cuốn sách quen thuộc và mệt vì phải đọc mãi. Hãy mở Truyện cổ tích thông minh. Thiết kế một buổi ru ngủ khác lạ, chẳng tốn chút công sức: bé là nhân vật chính, còn nền là âm thanh rừng xanh êm dịu.', body_zh = '经典故事书你都背熟了，读也读累了。打开智慧童话。把宝宝设计成主角，背景配上安神的森林声，打造一场不寻常、毫不费力的哄睡时光。' WHERE id = '57b60f69-46b8-4792-b8f6-95c7ec477f5b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aire fresco ⛅', body_es = 'Consulta Tiempo y ropa y sácale fuera sin falta. Con la simple misión de recoger ramas secas y piedras, él gastará energía y tú también te librarás de las cuatro paredes y respirarás hondo.', title_fr = 'Bon air frais ⛅', body_fr = 'Consultez Météo et tenue et sortez-le absolument. Avec une simple mission, ramasser des branches sèches et des cailloux, il dépensera son énergie, et vous, vous échapperez aux quatre murs pour respirer profondément.', title_hi = 'ताज़ी हवा ⛅', body_hi = 'मौसम और कपड़े देखिए और उसे बाहर ज़रूर ले जाइए। सूखी टहनियाँ और पत्थर इकट्ठा करने के मिशन से उसकी ऊर्जा भी निकालिए और खुद भी चार दीवारों से निकलकर गहरी साँस लीजिए।', title_id = 'Udara segar ⛅', body_id = 'Cek Cuaca dan Pakaian, lalu pastikan mengajaknya keluar. Dengan misi sederhana mengumpulkan ranting kering dan batu, ia menyalurkan energinya, dan Anda pun lepas dari empat dinding dan bisa bernapas dalam-dalam.', title_ja = '新鮮な空気 ⛅', body_ja = '「天気と服装」をチェックして、必ず外へ連れ出しましょう。枯れ枝や石を集めるミッションだけで、この子はエネルギーを発散でき、あなたも4つの壁から抜け出して深呼吸できます。', title_ko = '맑은 공기 ⛅', body_ko = '날씨와 옷차림을 확인하고 꼭 밖에 데리고 나가세요. 마른 나뭇가지와 돌 모으기 미션만으로도 아이는 에너지를 쓰고, 엄마도 네 벽에서 벗어나 깊게 숨을 쉴 수 있어요.', title_nl = 'Frisse lucht ⛅', body_nl = 'Check Weer en kleding en ga hoe dan ook met hem naar buiten. Met een simpele missie als droge takjes en steentjes verzamelen raakt hij zijn energie kwijt, en ontsnap jij aan de vier muren en kun je diep ademhalen.', title_pl = 'Świeże powietrze ⛅', body_pl = 'Sprawdź Pogodę i ubiór i koniecznie wyjdźcie na dwór. Zwykła misja zbierania suchych gałązek i kamyków pozwoli mu wyładować energię, a ty uciekniesz od czterech ścian i głęboko odetchniesz.', title_pt = 'Ar puro ⛅', body_pt = 'Veja o Tempo e Roupa e leve-o sem falta para a rua. Com uma simples missão de apanhar ramos secos e pedras, ele gasta energia e a mãe escapa às quatro paredes e respira fundo.', title_sv = 'Frisk luft ⛅', body_sv = 'Kolla Väder och kläder och se till att ni kommer ut. Med ett enkelt uppdrag att samla torra kvistar och stenar gör barnet av med energin, och du själv slipper de fyra väggarna och kan andas djupt.', title_vi = 'Không khí trong lành ⛅', body_vi = 'Hãy kiểm tra Thời tiết và trang phục và nhất định đưa bé ra ngoài. Chỉ với nhiệm vụ nhặt cành khô và sỏi đá, bé được xả năng lượng, còn mẹ thoát khỏi bốn bức tường và được hít thở thật sâu.', title_zh = '新鲜空气 ⛅', body_zh = '看看天气与穿衣，一定要带宝宝出门。展开一场“收集干树枝和石头”的任务，既能让宝宝释放精力，你也能逃离四面墙，深深地吸几口气。' WHERE id = '8391ff6e-4225-4aa9-9011-6c07f64cfe8a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los decibelios del silencio 🤫', body_es = '¡Por fin se ha dormido! No corras a ordenar la habitación. Activa el Medidor de sonido y mira esos 0-10 decibelios de la pantalla. Esa confirmación visual del silencio absoluto en casa será como el mejor masaje para tu cerebro cansado.', title_fr = 'Les décibels du silence 🤫', body_fr = 'Il dort enfin ! Ne courez pas ranger la pièce. Activez le Sonomètre et regardez les 0 à 10 décibels à l''écran. Cette preuve visuelle du silence absolu de la maison agira comme le plus doux des massages pour votre cerveau fatigué.', title_hi = 'खामोशी के डेसिबल 🤫', body_hi = 'आखिरकार वह सो गया! कमरा समेटने मत दौड़िए। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखिए। घर की पूरी खामोशी की यह दिखती पुष्टि आपके थके दिमाग के लिए सबसे प्यारी मसाज होगी।', title_id = 'Desibel keheningan 🤫', body_id = 'Akhirnya ia tertidur! Jangan buru-buru membereskan kamar. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar. Bukti visual keheningan total di rumah itu akan terasa seperti pijatan terindah untuk otak Anda yang lelah.', title_ja = '静けさのデシベル 🤫', body_ja = 'やっと寝てくれました！部屋の片づけに走らないで。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を眺めましょう。家の中の完全な静けさを目で確かめることが、疲れた脳へのいちばんのマッサージになります。', title_ko = '고요의 데시벨 🤫', body_ko = '드디어 잠들었어요! 방 치우러 달려가지 마세요. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보세요. 집 안의 완전한 고요를 눈으로 확인하는 것이 지친 머리에 가장 좋은 마사지가 될 거예요.', title_nl = 'De decibel van stilte 🤫', body_nl = 'Hij slaapt eindelijk! Ren niet weg om de kamer op te ruimen. Zet de Geluidsmeter aan en kijk naar die 0-10 decibel op het scherm. Die visuele bevestiging van de absolute stilte in huis werkt als de fijnste massage voor je vermoeide brein.', title_pl = 'Decybele ciszy 🤫', body_pl = 'W końcu zasnął! Nie biegnij sprzątać pokoju. Włącz Miernik dźwięku i spójrz na wynik 0-10 decybeli na ekranie. To wizualne potwierdzenie absolutnej ciszy w domu podziała na twój zmęczony mózg jak najpiękniejszy masaż.', title_pt = 'Os decibéis do silêncio 🤫', body_pt = 'Finalmente adormeceu! Não corra a arrumar o quarto. Ative o Medidor de Som e olhe para os 0-10 decibéis no ecrã. A confirmação visual do silêncio absoluto da casa vai funcionar como a melhor massagem para o seu cérebro cansado.', title_sv = 'Tystnadens decibel 🤫', body_sv = 'Äntligen har barnet somnat! Spring inte iväg och städa rummet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen. Den visuella bekräftelsen av den totala tystnaden hemma blir den skönaste massagen för din trötta hjärna.', title_vi = 'Decibel của sự tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Đừng vội chạy đi dọn phòng. Hãy bật Đo âm thanh và nhìn con số 0-10 decibel trên màn hình. Sự xác nhận bằng hình ảnh về sự im lặng tuyệt đối trong nhà sẽ như màn mát-xa tuyệt vời nhất cho não bộ mỏi mệt của mẹ.', title_zh = '安静的分贝 🤫', body_zh = '宝宝终于睡着了！别急着跑去收拾房间。打开分贝仪，看看屏幕上0-10分贝的数字。家里绝对安静的这份视觉确认，对你疲惫的大脑来说就像一次最美好的按摩。' WHERE id = '267b7226-68df-4c3e-8db0-91462616e5aa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Profesor de filosofía 🧐', body_es = 'Ya no pregunta «Mamá, ¿por qué está ahí el sol?», sino simplemente «¿Por qué existe el sol?». Sus preguntas son cada vez más abstractas. No te agotes intentando dar explicaciones científicas durante horas. Una respuesta corta, cálida y de cuento como «porque le gusta darnos calor» le dejará totalmente satisfecho.', title_fr = 'Le professeur de philosophie 🧐', body_fr = 'Il ne demande plus « Maman, pourquoi le soleil est là ? » mais simplement « Pourquoi le soleil ? ». Ses questions deviennent de plus en plus abstraites. Ne vous épuisez pas en explications scientifiques pendant des heures. Une réponse courte, chaleureuse, comme dans un conte, du type « Parce qu''il aime nous réchauffer », le satisfera complètement.', title_hi = 'दर्शन के प्रोफ़ेसर 🧐', body_hi = '‘माँ, सूरज वहाँ क्यों है?’ नहीं, बस ‘सूरज क्यों है?’ पूछता है। उसके सवाल धीरे-धीरे और गहरे होते जा रहे हैं। घंटों वैज्ञानिक व्याख्या देकर दिमाग मत थकाइए। ‘क्योंकि उसे हमें गर्म रखना अच्छा लगता है’ जैसा छोटा, कहानी जैसा, गर्मजोशी भरा जवाब उसे पूरी तरह संतुष्ट कर देगा।', title_id = 'Profesor filsafat 🧐', body_id = 'Ia tidak bertanya ''Ma, kenapa matahari ada di sana?'', tapi cukup ''Kenapa matahari?''. Pertanyaannya makin lama makin abstrak. Jangan melelahkan otak dengan berusaha memberi penjelasan ilmiah berjam-jam. Jawaban singkat, hangat, dan seperti dongeng, misalnya ''karena ia suka menghangatkan kita'', sudah sangat memuaskannya.', title_ja = '哲学の教授 🧐', body_ja = '「ママ、お日さまはなんであそこにあるの？」ではなく、ただ「お日さまはなんで？」と聞いてくる。質問はだんだん抽象的になっています。何時間も科学的に説明しようとして頭を疲れさせないで。「わたしたちを温めるのが好きなんだよ」のような、短くてお話のようなあたたかい答えで十分満足します。', title_ko = '철학 교수님 🧐', body_ko = '''엄마, 해는 왜 저기 있어?''가 아니라 그냥 ''해는 왜야?''라고 묻나요? 질문이 점점 추상적으로 변해요. 몇 시간씩 과학적으로 설명하느라 머리를 혹사하지 마세요. ''우리를 따뜻하게 해 주는 걸 좋아해서''처럼 짧고 동화 같은 따뜻한 답이면 충분해요.', title_nl = 'Professor filosofie 🧐', body_nl = 'Hij vraagt niet ''Mama, waarom staat de zon daar?'', maar gewoon ''Waarom is de zon?''. Zijn vragen worden steeds abstracter. Vermoei je brein niet met urenlange wetenschappelijke uitleg. Een kort, warm sprookjesachtig antwoord als ''Omdat hij ons graag warm houdt'' is voor hem genoeg.', title_pl = 'Profesor filozofii 🧐', body_pl = 'Nie pyta już „Mamo, dlaczego słońce tam jest?”, tylko po prostu „Dlaczego jest słońce?”. Jego pytania stają się coraz bardziej abstrakcyjne. Nie męcz głowy godzinami naukowych wyjaśnień. Krótka, bajkowa i ciepła odpowiedź w stylu „bo lubi nas ogrzewać” w pełni go zadowoli.', title_pt = 'Professor de filosofia 🧐', body_pt = 'Já não pergunta "Mãe, porque é que o sol está ali?", mas simplesmente "Porque é que o sol é?". As perguntas são cada vez mais abstratas. Não canse a cabeça a tentar dar explicações científicas durante horas. Uma resposta curta, quente e de conto, como "Porque gosta de nos aquecer", deixa-o totalmente satisfeito.', title_sv = 'Filosofiprofessorn 🧐', body_sv = 'Barnet frågar inte ”Mamma, varför är solen där?” utan bara ”Varför är solen?”. Frågorna blir alltmer abstrakta. Trötta inte ut hjärnan med att försöka ge vetenskapliga förklaringar i timmar. Ett kort, sagolikt och varmt svar som ”För att den tycker om att värma oss” räcker helt för barnet.', title_vi = 'Giáo sư triết học 🧐', body_vi = 'Bé không hỏi "Mẹ ơi, sao mặt trời ở đó?" mà chỉ hỏi "Sao lại có mặt trời?". Câu hỏi của bé ngày càng trừu tượng. Đừng làm mệt đầu óc bằng cách giải thích khoa học hàng giờ. Một câu trả lời ngắn gọn, ấm áp như cổ tích kiểu "Vì mặt trời thích sưởi ấm cho chúng ta" sẽ khiến bé hoàn toàn hài lòng.', title_zh = '哲学教授 🧐', body_zh = '不再问“妈妈，太阳为什么在那儿？”，而是直接问“太阳为什么？”问题越来越抽象了。别花几个小时做科学解释把自己累坏。一句简短、像童话一样温暖的回答，比如“因为它喜欢给我们取暖”，就能让宝宝完全满意。' WHERE id = '9a9573ec-71e1-4545-84fd-a3a1f5b2af6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Piernas de vacaciones 🚶‍♂️', body_es = 'En plena calle se sienta de repente en el suelo y dice: «Se me han roto las piernas, cógeme en brazos». No, no está cansado, solo te está poniendo a prueba. No cedas al chantaje. Métele en el juego: «¿A ver cómo llegamos al coche andando como pingüinos?».', title_fr = 'Les jambes en vacances 🚶‍♂️', body_fr = 'En pleine rue, il s''assoit soudain par terre : « J''ai les jambes cassées, porte-moi. » Non, il n''est pas fatigué, il vous met simplement à l''épreuve. Ne cédez pas au chantage. Entraînez-le dans un jeu : « Voyons comment on va jusqu''à la voiture en marchant comme des pingouins ! »', title_hi = 'पैर छुट्टी पर 🚶‍♂️', body_hi = 'सड़क के बीच अचानक ज़मीन पर बैठकर कहता है, ‘मेरे पैर टूट गए, मुझे गोद लो।’ नहीं, वह थका नहीं, बस आपको परख रहा है। ब्लैकमेल के आगे मत झुकिए। ‘देखें, गाड़ी तक पेंगुइन की तरह कैसे चलेंगे?’ कहकर उसे खेल में शामिल कीजिए।', title_id = 'Kaki sedang libur 🚶‍♂️', body_id = 'Di tengah jalan ia tiba-tiba duduk di tanah dan berkata ''Kakiku patah, gendong aku''. Tidak, ia tidak lelah, ia hanya sedang menguji Anda. Jangan menyerah pada pemerasan ini. Ajak ia bermain dengan berkata ''Ayo kita lihat, bagaimana kita jalan seperti penguin sampai ke mobil?''.', title_ja = '足がお休み中 🚶‍♂️', body_ja = '道のまんなかで急に座りこんで「足がこわれた、抱っこして」。いいえ、疲れたのではなく、あなたを試しているだけ。駆け引きに負けないで。「車までペンギンみたいに歩いてみようか？」と言って、遊びに引きこみましょう。', title_ko = '다리가 휴가 중 🚶‍♂️', body_ko = '길 한가운데서 갑자기 주저앉아 ''다리 부러졌어, 안아 줘''라고 하나요? 아니요, 지친 게 아니라 엄마를 시험하는 거예요. 떼에 넘어가지 마세요. ''차까지 펭귄처럼 걸어가 볼까?''라며 놀이로 끌어들이세요.', title_nl = 'Voetjes met vakantie 🚶‍♂️', body_nl = 'Midden op straat gaat hij ineens op de grond zitten: ''Mijn benen zijn kapot, til me op.'' Nee, hij is niet moe, hij test je gewoon. Geef niet toe aan de chantage. Betrek hem bij een spel: ''Zullen we als pinguïns naar de auto waggelen?''', title_pl = 'Nogi na urlopie 🚶‍♂️', body_pl = 'Nagle siada na środku ulicy i mówi „Nogi mi się połamały, weź mnie na ręce”. Nie, nie jest zmęczony, po prostu cię testuje. Nie ulegaj szantażowi. Wciągnij go w zabawę: „Zobaczmy, jak dojdziemy do samochodu jak pingwiny?”.', title_pt = 'Pernas de férias 🚶‍♂️', body_pt = 'No meio da rua, senta-se de repente no chão e diz "as minhas pernas partiram-se, pega-me ao colo". Não, não está cansado, está só a pô-la à prova. Não ceda à chantagem. Puxe-o para a brincadeira: "Vamos ver como chegamos ao carro a andar como pinguins?"', title_sv = 'Benen tar semester 🚶‍♂️', body_sv = 'Mitt på gatan sätter sig barnet plötsligt ner och säger ”benen gick sönder, bär mig”. Nej, barnet är inte trött, det testar dig bara. Ge inte efter för utpressningen. Säg ”Får se hur vi går som pingviner till bilen?” och locka in barnet i leken.', title_vi = 'Đôi chân đi nghỉ 🚶‍♂️', body_vi = 'Giữa đường, bé bỗng ngồi phịch xuống và nói "Chân con gãy rồi, mẹ bế con đi". Không, bé không mệt đâu, bé chỉ đang thử mẹ thôi. Đừng chiều theo "màn mặc cả" này. Hãy lôi cuốn bé vào trò chơi: "Xem mình đi đến xe như chim cánh cụt thế nào nhé?".', title_zh = '小脚放假了 🚶‍♂️', body_zh = '走在路中间突然坐到地上：“我的腿断了，抱我。”不，宝宝不是累了，只是在考验你。别向“要挟”低头。说一句“看看我们怎么像企鹅一样走到车那儿？”，把宝宝带进游戏里。' WHERE id = 'c8cadde3-c829-4a73-89c2-d28ffc494046' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dieta de colores 🥕', body_es = 'Hoy ha decidido comer solo cosas de color naranja y rechaza todo lo demás. ¡La lógica infantil vuelve a estar en acción! Descubre en Recetas saludables cómo camuflar las verduras. Vence esta terquedad con recetas diferentes hechas con puré de calabaza y zanahoria.', title_fr = 'Un régime coloré 🥕', body_fr = 'Aujourd''hui, il a décidé de ne manger que des choses orange et refuse tout le reste. La logique enfantine est encore à l''œuvre ! Découvrez dans les Recettes saines comment camoufler les légumes. Venez à bout de cet entêtement avec des recettes à la purée de potiron et de carottes.', title_hi = 'रंगीन डाइट 🥕', body_hi = 'आज उसने सिर्फ़ नारंगी रंग की चीज़ें खाने का फ़ैसला किया है और बाकी सब ठुकरा देता है। बच्चे का तर्क फिर काम पर है! सेहतमंद रेसिपी में जानिए कि सब्ज़ियों को कैसे छिपाएँ। कद्दू और गाजर की प्यूरी से बनी अलग रेसिपी से इस ज़िद को जीतिए।', title_id = 'Diet berwarna 🥕', body_id = 'Hari ini ia memutuskan hanya mau makan yang berwarna oranye dan menolak semua yang lain. Logika anak sedang bekerja lagi! Temukan cara menyamarkan sayur di Resep Sehat. Kalahkan sikap keras kepala ini dengan resep berbeda dari labu kuning dan wortel yang dihaluskan.', title_ja = 'カラフルダイエット 🥕', body_ja = '今日はオレンジ色のものだけ食べると決めて、ほかは全部いやがる。子どもの理屈がまた働いています！「ヘルシーレシピ」で、野菜をカモフラージュする方法を見つけましょう。かぼちゃやにんじんのピューレを使ったひと味ちがうレシピで、このがんこさに勝ちましょう。', title_ko = '알록달록 식단 🥕', body_ko = '오늘은 주황색 음식만 먹기로 하고 나머지는 다 거부하나요? 아이의 논리가 또 출동했어요! 건강한 레시피에서 채소를 위장하는 법을 찾아보세요. 단호박과 당근 퓌레로 만든 색다른 레시피로 이 고집을 이겨 보세요.', title_nl = 'Kleurrijk dieet 🥕', body_nl = 'Hij heeft besloten vandaag alleen oranje dingen te eten en weigert al het andere. De kinderlogica is weer aan het werk! Ontdek in Gezonde recepten hoe je groenten camoufleert. Win van deze koppigheid met recepten met pompoen- en wortelpuree.', title_pl = 'Kolorowa dieta 🥕', body_pl = 'Dziś postanowił jeść tylko rzeczy w kolorze pomarańczowym i odrzuca wszystko inne. Dziecięca logika znów w akcji! Odkryj w Zdrowych przepisach, jak zakamuflować warzywa. Pokonaj ten upór różnymi przepisami z purée z dyni i marchewki.', title_pt = 'Dieta colorida 🥕', body_pt = 'Hoje decidiu comer só coisas cor de laranja e recusa tudo o resto. A lógica infantil volta a atacar! Descubra nas Receitas Saudáveis como camuflar os legumes. Vença esta teimosia com receitas diferentes feitas com puré de abóbora e de cenoura.', title_sv = 'Färgglad diet 🥕', body_sv = 'I dag har barnet bestämt sig för att bara äta orange saker och vägrar allt annat. Barnlogiken är i full gång igen! Upptäck hur du kamouflerar grönsaker bland Hälsosamma recept. Vinn över envisheten med annorlunda recept med pumpa- och morotspuré.', title_vi = 'Thực đơn sắc màu 🥕', body_vi = 'Hôm nay bé quyết định chỉ ăn đồ màu cam và từ chối mọi thứ khác. Logic trẻ con lại "lên sóng" rồi! Hãy khám phá trong Công thức lành mạnh cách "ngụy trang" rau củ. Chiến thắng sự bướng bỉnh này bằng những công thức khác lạ với bí đỏ và cà rốt nghiền.', title_zh = '彩色饮食 🥕', body_zh = '今天决定只吃橙色的东西，别的一概不要。孩子的逻辑又上线了！去健康食谱里看看如何给蔬菜“伪装”。用南瓜泥和胡萝卜泥做的特别食谱，赢下这场倔强吧。' WHERE id = 'd2c59147-ed1d-426c-a22f-74bab5a93a1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El solista de la mañana 🎤', body_es = 'Al amanecer, mientras tú apenas abres los ojos, él da un concierto en medio de la habitación con un juguete en la mano. No intentes callarle. Esta energía vital, loca e inagotable de los niños, en realidad llena la casa de abundancia y alegría. Mírale sonriendo.', title_fr = 'Le soliste du matin 🎤', body_fr = 'Au petit matin, pendant que vous ouvrez péniblement les yeux, il donne un concert au milieu de la chambre avec un jouet à la main. N''essayez pas de le faire taire. Cette énergie de vie folle et inépuisable des enfants apporte en réalité abondance et joie à la maison. Regardez-le en souriant.', title_hi = 'सुबह का सोलो गायक 🎤', body_hi = 'बिल्कुल तड़के, जब आप मुश्किल से आँखें खोल रही हैं, वह हाथ में खिलौना लेकर कमरे के बीच कॉन्सर्ट दे रहा है। उसे चुप कराने की कोशिश मत कीजिए। बच्चों की यह धमाकेदार, कभी न खत्म होने वाली जीवन ऊर्जा असल में घर में बरकत और खुशी लाती है। उसे मुस्कुराकर देखिए।', title_id = 'Penyanyi solo pagi hari 🎤', body_id = 'Pagi buta, saat Anda masih susah membuka mata, ia sudah menggelar konser di tengah kamar dengan mainan di tangan. Jangan mencoba membuatnya diam. Energi hidup anak-anak yang gila dan tak habis-habis ini sebenarnya membawa berkah dan kebahagiaan ke rumah. Pandangi ia sambil tersenyum.', title_ja = '朝のソリスト 🎤', body_ja = 'まだ夜明け前、あなたがやっと目を開けたころ、この子はおもちゃを手に部屋のまんなかでコンサート中。静かにさせようとしないで。子どものこのすごい、尽きることのない生命力は、本当は家に豊かさと喜びを運んでくれます。笑顔で見てあげましょう。', title_ko = '아침의 독창자 🎤', body_ko = '이른 새벽, 엄마는 겨우 눈을 뜨는데 아이는 장난감을 들고 방 한가운데서 콘서트를 여나요? 조용히 시키려 하지 마세요. 아이들의 이 넘치는 생명력은 사실 집에 복과 기쁨을 가져와요. 미소 지으며 바라봐 주세요.', title_nl = 'Ochtendsolist 🎤', body_nl = 'Het is nog vroeg en jij krijgt je ogen amper open, maar hij geeft al een concert midden in de kamer met een speeltje in zijn hand. Probeer hem niet stil te krijgen. Die gekke, eindeloze levensenergie van kinderen brengt eigenlijk zegen en vreugde in huis. Kijk glimlachend naar hem.', title_pl = 'Poranny solista 🎤', body_pl = 'Jest jeszcze wczesny świt, ledwo otwierasz oczy, a on z zabawką w ręce daje koncert na środku pokoju. Nie próbuj go uciszać. Ta szalona, niewyczerpana energia życia dzieci tak naprawdę wnosi do domu dobrobyt i radość. Patrz na niego z uśmiechem.', title_pt = 'O solista da manhã 🎤', body_pt = 'Ainda de madrugada, quando a mãe mal consegue abrir os olhos, ele dá um concerto no meio do quarto com um brinquedo na mão. Não tente calá-lo. Esta energia de vida louca e sem fim das crianças traz, na verdade, abundância e alegria à casa. Olhe para ele a sorrir.', title_sv = 'Morgonsolisten 🎤', body_sv = 'Tidigt i gryningen, medan du knappt får upp ögonen, ger barnet konsert mitt i rummet med en leksak i handen. Försök inte tysta barnet. Barnens galna, ändlösa livsenergi ger faktiskt hemmet välsignelse och glädje. Titta på barnet med ett leende.', title_vi = 'Ca sĩ hát đơn buổi sáng 🎤', body_vi = 'Trời mới tờ mờ sáng, mẹ còn chưa mở nổi mắt thì bé đã cầm đồ chơi mở buổi hòa nhạc giữa phòng. Đừng cố bắt bé im lặng. Nguồn năng lượng sống "điên rồ", bất tận của trẻ thật ra mang lại may mắn và niềm vui cho ngôi nhà. Hãy mỉm cười ngắm nhìn bé.', title_zh = '清晨独唱家 🎤', body_zh = '天刚蒙蒙亮，你还睁不开眼，宝宝就拿着玩具在房间中间开起了音乐会。别想着让宝宝安静。孩子这股疯狂、用不完的生命力，其实给家里带来了福气和欢乐。笑着看着宝宝吧。' WHERE id = 'd7d30904-6d53-4964-8b13-c4680a8d7346' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El toque que cura 💆‍♂️', body_es = 'En la cama no hay manera de que se calme. Deja a un lado el cuento y la música. Hazle un masaje muy suave y acariciador en los piececitos o en la espalda. El contacto físico reducirá al instante el cortisol (la hormona del estrés) en su cuerpo y en el tuyo y traerá el sueño.', title_fr = 'Le toucher qui guérit 💆‍♂️', body_fr = 'Il n''arrive pas du tout à se calmer dans son lit. Mettez de côté les contes et la musique. Massez très légèrement, en caressant, ses petits pieds ou son dos. Le contact physique fait baisser aussitôt le cortisol (l''hormone du stress) dans son corps comme dans le vôtre et amène le sommeil.', title_hi = 'सुकून देने वाला स्पर्श 💆‍♂️', body_hi = 'बिस्तर में किसी तरह शांत नहीं होता। कहानी, संगीत एक तरफ़ रखिए। उसके छोटे पैरों या पीठ पर बहुत हल्की, सहलाने वाली मालिश कीजिए। शारीरिक स्पर्श उसके और आपके, दोनों के शरीर में कोर्टिसोल (तनाव का हार्मोन) तुरंत कम करके नींद लाएगा।', title_id = 'Sentuhan yang menyembuhkan 💆‍♂️', body_id = 'Ia sama sekali tidak bisa tenang di tempat tidur. Singkirkan dongeng dan musik. Pijat kaki kecilnya atau punggungnya dengan usapan yang sangat lembut. Sentuhan fisik akan langsung menurunkan kortisol (hormon stres) di tubuhnya dan tubuh Anda, lalu mendatangkan kantuk.', title_ja = '癒やしのタッチ 💆‍♂️', body_ja = 'ベッドの上でどうしても落ち着かない。お話も音楽もいったんお休みして、小さな足や背中を、とても軽くなでるようにマッサージしてあげましょう。肌のふれあいは、この子とあなたの体のコルチゾール（ストレスホルモン）をすぐに下げ、眠りへ導きます。', title_ko = '치유의 손길 💆‍♂️', body_ko = '침대에서 도무지 진정하지 못하나요? 동화와 음악은 잠시 내려놓으세요. 작은 발이나 등을 아주 살살 쓰다듬듯 마사지해 주세요. 스킨십은 아이와 엄마 몸속의 코르티솔(스트레스 호르몬)을 바로 줄여 잠을 불러와요.', title_nl = 'Een helende aanraking 💆‍♂️', body_nl = 'Hij komt in bed maar niet tot rust. Leg het sprookje en de muziek opzij. Geef hem een heel lichte, strelende massage op zijn voetjes of rug. Lichamelijk contact verlaagt meteen het cortisol (stresshormoon) in zijn lichaam en het jouwe, en brengt de slaap.', title_pl = 'Kojący dotyk 💆‍♂️', body_pl = 'W łóżku za nic nie może się uspokoić. Odłóż bajkę i muzykę. Zrób mu bardzo delikatny, głaszczący masaż małych stópek albo pleców. Dotyk od razu obniży kortyzol (hormon stresu) w jego i twoim ciele i sprowadzi sen.', title_pt = 'O toque que cura 💆‍♂️', body_pt = 'Na cama, não há maneira de se acalmar. Ponha de lado a história e a música. Faça uma massagem muito leve e carinhosa nos pezinhos ou nas costas dele. O contacto físico reduz logo o cortisol (hormona do stress) no corpo dele e no seu e traz o sono.', title_sv = 'Läkande beröring 💆‍♂️', body_sv = 'Barnet lugnar sig inte alls i sängen. Lägg sagan och musiken åt sidan. Ge barnets små fötter eller rygg en mycket lätt, smekande massage. Fysisk kontakt sänker direkt kortisolet (stresshormonet) både i barnets och i din kropp och för med sig sömn.', title_vi = 'Cái chạm chữa lành 💆‍♂️', body_vi = 'Bé mãi không chịu nằm yên trên giường. Hãy tạm gác truyện và nhạc sang một bên. Mát-xa thật nhẹ nhàng, vuốt ve đôi bàn chân nhỏ hay lưng của bé. Sự tiếp xúc cơ thể sẽ lập tức giảm cortisol (hormone căng thẳng) trong cơ thể cả bé lẫn mẹ và mang lại giấc ngủ.', title_zh = '治愈的抚触 💆‍♂️', body_zh = '在床上怎么都安静不下来。把故事和音乐都先放一边。轻轻地给宝宝的小脚丫或后背做一个很轻柔的抚触按摩。肌肤接触会马上降低宝宝和你体内的皮质醇（压力激素），带来睡意。' WHERE id = 'e2fc49a4-e751-47d3-a247-fa5b6429b0ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Migas invisibles 🧹', body_es = 'Con su escobita limpia el polvo invisible de la alfombra con una cara muy seria. Simplemente te imita. Graba este momento tan responsable con la Sesión de fotos del bebé: el ayudante de limpieza más pequeño y más dulce de la casa está en acción.', title_fr = 'Les miettes invisibles 🧹', body_fr = 'Avec son petit balai, il nettoie très sérieusement la poussière invisible du tapis. Il vous imite, tout simplement. Immortalisez ce moment de responsabilité avec la Séance photo bébé : le plus petit et le plus mignon des agents d''entretien est au travail.', title_hi = 'अदृश्य टुकड़े 🧹', body_hi = 'हाथ की छोटी झाड़ू से कालीन पर की अदृश्य धूल बहुत गंभीर चेहरे के साथ साफ़ कर रहा है। वह बस आपकी नकल कर रहा है। उसके इस ज़िम्मेदार पल को बेबी फ़ोटोशूट में कैद कीजिए, घर का सबसे छोटा और सबसे प्यारा सफ़ाईकर्मी ड्यूटी पर है।', title_id = 'Remah-remah tak terlihat 🧹', body_id = 'Dengan sapu kecil di tangannya, ia membersihkan debu tak terlihat di karpet dengan wajah sangat serius. Ia hanya meniru Anda. Abadikan momen penuh tanggung jawab ini di Pemotretan Bayi, petugas kebersihan terkecil dan termanis di rumah sedang bertugas.', title_ja = '見えないパンくず 🧹', body_ja = '小さなほうきを手に、じゅうたんの上の見えないほこりを、とても真剣な顔でお掃除中。あなたをまねしているんです。この責任感あふれる瞬間を「ベビーフォトセッション」で撮っておきましょう。家でいちばん小さくてかわいいお手伝いさんが、お仕事中です。', title_ko = '보이지 않는 부스러기 🧹', body_ko = '작은 빗자루로 카펫 위 보이지 않는 먼지를 아주 진지한 표정으로 쓸고 있나요? 엄마를 따라 하는 거예요. 이 책임감 넘치는 순간을 아기 사진 촬영으로 담아 두세요. 우리 집 가장 작고 귀여운 청소 도우미가 출근했어요.', title_nl = 'Onzichtbare kruimels 🧹', body_nl = 'Met een klein bezempje veegt hij met een heel serieus gezicht onzichtbaar stof van het tapijt. Hij doet je gewoon na. Leg dit verantwoordelijke moment vast met de Babyfotoshoot: de kleinste en liefste schoonmaker van het huis is aan het werk.', title_pl = 'Niewidzialne okruszki 🧹', body_pl = 'Z bardzo poważną miną zamiata małą miotełką niewidzialny kurz z dywanu. Po prostu cię naśladuje. Uwiecznij tę odpowiedzialną chwilę w Sesji zdjęciowej dziecka, najmniejsza i najsłodsza pomoc domowa jest w pracy.', title_pt = 'Migalhas invisíveis 🧹', body_pt = 'Com uma pequena vassoura na mão, limpa o pó invisível do tapete com uma expressão muito séria. Está só a imitá-la. Registe este momento responsável na Sessão Fotográfica do Bebé: a empregada de limpeza mais pequena e mais querida da casa está em ação.', title_sv = 'Osynliga smulor 🧹', body_sv = 'Med en liten borste sopar barnet bort osynligt damm från mattan med en väldigt allvarlig min. Barnet härmar dig bara. Fånga den ansvarsfulla stunden med Babyfotografering, hemmets minsta och sötaste städare är i tjänst.', title_vi = 'Những mẩu vụn vô hình 🧹', body_vi = 'Bé cầm chiếc chổi nhỏ, vẻ mặt cực kỳ nghiêm túc quét những hạt bụi vô hình trên thảm. Bé chỉ đang bắt chước mẹ thôi. Hãy ghi lại khoảnh khắc đầy trách nhiệm này bằng Chụp ảnh cho bé, "người giúp việc" nhỏ nhất và đáng yêu nhất nhà đang làm nhiệm vụ.', title_zh = '看不见的碎屑 🧹', body_zh = '拿着小扫帚，一脸严肃地打扫地毯上看不见的灰尘。宝宝只是在模仿你。用宝宝写真把这个负责任的时刻拍下来吧，家里最小、最可爱的“保洁员”正在上岗。' WHERE id = '297d6ab5-a5e9-4978-98b2-bd85528e89d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terapia del Medidor de sonido 🤫', body_es = 'Ese huracán loco de casa por fin se ha rendido a la cama. En la habitación no se oye nada salvo el lavavajillas. Abre el Medidor de sonido, mira esos decibelios mínimos de la pantalla y cierra los ojos. Este silencio visual es el mejor masaje para tu cerebro.', title_fr = 'La thérapie du Sonomètre 🤫', body_fr = 'Le tourbillon fou de la maison s''est enfin rendu au sommeil. On n''entend plus que le lave-vaisselle. Ouvrez le Sonomètre, regardez les décibels minimes à l''écran et fermez les yeux. Ce silence visuel est le meilleur des massages pour votre cerveau.', title_hi = 'साउंड मीटर थेरेपी 🤫', body_hi = 'घर का वह पागल तूफ़ान आखिरकार बिस्तर के आगे हार गया। कमरे में डिशवॉशर की आवाज़ के सिवा कुछ नहीं। साउंड मीटर टूल खोलिए, स्क्रीन पर कम से कम डेसिबल के अंक देखते हुए आँखें बंद कीजिए। यह दिखती खामोशी आपके दिमाग के लिए सबसे अच्छी मसाज है।', title_id = 'Terapi Pengukur Suara 🤫', body_id = 'Badai gila di rumah akhirnya menyerah pada tempat tidur. Di kamar tak ada suara selain mesin cuci piring. Buka Pengukur Suara, lihat angka desibel yang minimal di layar, dan pejamkan mata. Keheningan visual ini adalah pijatan terbaik untuk otak Anda.', title_ja = 'サウンドメーターセラピー 🤫', body_ja = '家の中の大あらしが、ようやくベッドに降参しました。部屋に聞こえるのは食洗機の音だけ。「サウンドメーター」を開いて、画面の小さなデシベルの数字を見たら、目を閉じましょう。この目に見える静けさが、脳へのいちばんのマッサージです。', title_ko = '소음 측정기 테라피 🤫', body_ko = '집 안의 그 정신없는 회오리가 드디어 잠에 항복했어요. 방엔 식기세척기 소리뿐이죠. 소음 측정기를 열고 화면 속 아주 낮은 데시벨 숫자를 보며 눈을 감으세요. 이 시각적인 고요가 머리에 가장 좋은 마사지예요.', title_nl = 'Geluidsmetertherapie 🤫', body_nl = 'De gekke wervelwind in huis heeft zich eindelijk aan het bed overgegeven. Je hoort niets anders dan de vaatwasser. Open de Geluidsmeter, kijk naar die minimale decibelwaarden op het scherm en doe je ogen dicht. Deze visuele stilte is de beste massage voor je brein.', title_pl = 'Terapia Miernikiem dźwięku 🤫', body_pl = 'Szalony huragan w domu w końcu poddał się łóżku. W pokoju słychać tylko zmywarkę. Otwórz Miernik dźwięku, spójrz na minimalne liczby decybeli na ekranie i zamknij oczy. Ta wizualna cisza to najlepszy masaż dla twojego mózgu.', title_pt = 'Terapia com o Medidor de Som 🤫', body_pt = 'Aquele furacão louco da casa finalmente rendeu-se à cama. No quarto só se ouve a máquina da loiça. Abra o Medidor de Som e feche os olhos depois de ver os decibéis mínimos no ecrã. Este silêncio visual é a melhor massagem para o seu cérebro.', title_sv = 'Ljudmätarterapi 🤫', body_sv = 'Den galna orkanen hemma har äntligen gett upp för sängen. I rummet hörs inget annat än diskmaskinen. Öppna verktyget Ljudmätare, titta på de minimala decibelsiffrorna på skärmen och blunda. Den visuella tystnaden är den bästa massagen för din hjärna.', title_vi = 'Liệu pháp Đo âm thanh 🤫', body_vi = '"Cơn lốc" điên rồ trong nhà cuối cùng cũng chịu đầu hàng giấc ngủ. Trong phòng chẳng còn gì ngoài tiếng máy rửa bát. Hãy mở Đo âm thanh, nhìn những con số decibel tối thiểu trên màn hình và nhắm mắt lại. Sự tĩnh lặng hiện ra trước mắt ấy là màn mát-xa tốt nhất cho não bộ của mẹ.', title_zh = '分贝仪疗法 🤫', body_zh = '家里那场疯狂的“龙卷风”终于向床投降了。房间里除了洗碗机的声音，什么都没有。打开分贝仪，看着屏幕上那些极低的分贝数字，闭上眼睛。这份看得见的安静，是给大脑最好的按摩。' WHERE id = '79e7bb66-f1dd-4164-bbd9-7c802b073b10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertar de gato 🐾', body_es = 'Esta mañana no es una persona. Anda a cuatro patas, se frota contra tus piernas y solo se comunica diciendo «miau». Es el punto más dulce y alto de la imaginación. En lugar de poner normas, ofrécele tú también un cuenco de leche imaginario y disfruta del juego.', title_fr = 'Un réveil de chat 🐾', body_fr = 'Ce matin, ce n''est pas un être humain. Il marche à quatre pattes, se frotte contre vos jambes et ne communique qu''en disant « miaou ». C''est le sommet le plus mignon de l''imagination. Au lieu de poser des règles, tendez-lui une gamelle de lait imaginaire et savourez ce jeu.', title_hi = 'बिल्ली की तरह जागना 🐾', body_hi = 'आज सुबह वह इंसान नहीं है। चारों हाथ-पैरों पर चलता है, आपके पैरों से लिपटता है और बस ‘म्याऊँ’ कहकर बात करता है। यह कल्पना का सबसे प्यारा और ऊँचा शिखर है। नियम बनाने के बजाय आप भी उसकी ओर काल्पनिक दूध का कटोरा बढ़ाकर इस खेल का मज़ा लीजिए।', title_id = 'Bangun seperti kucing 🐾', body_id = 'Pagi ini ia bukan manusia. Ia berjalan merangkak, menggosokkan tubuh ke kaki Anda, dan berkomunikasi hanya dengan ''meong''. Ini puncak imajinasi yang paling manis. Daripada membuat aturan, sodorkan juga mangkuk susu khayalan dan nikmati permainan ini.', title_ja = 'ねこの目覚め 🐾', body_ja = '今朝のこの子は人間ではありません。よつんばいで歩き、あなたの足にすりよって、「にゃー」とだけ言ってお話しします。想像力のいちばんかわいいピークです。ルールを決める代わりに、空想のミルク皿を差し出して、この遊びを楽しみましょう。', title_ko = '고양이처럼 기상 🐾', body_ko = '오늘 아침 아이는 사람이 아니에요. 네 발로 걷고, 엄마 다리에 몸을 비비고, ''야옹''으로만 대화하나요? 상상력의 가장 사랑스러운 절정이에요. 규칙을 세우는 대신 상상의 우유 그릇을 내밀며 이 놀이를 즐겨 보세요.', title_nl = 'Wakker worden als een kat 🐾', body_nl = 'Vanochtend is hij geen mens. Hij loopt op handen en voeten, wrijft langs je benen en communiceert alleen met ''miauw''. Dit is het liefste hoogtepunt van zijn fantasie. Stel geen regels, maar geef hem een denkbeeldig bakje melk en geniet van het spel.', title_pl = 'Kocia pobudka 🐾', body_pl = 'Dziś rano nie jest człowiekiem. Chodzi na czworakach, ociera się o twoje nogi i porozumiewa się tylko przez „miau”. To najsłodszy szczyt wyobraźni. Zamiast ustalać zasady, podsuń mu wymyśloną miseczkę mleka i ciesz się tą zabawą.', title_pt = 'Acordar como um gato 🐾', body_pt = 'Esta manhã ele não é uma pessoa. Anda de gatas, roça-se nas suas pernas e só comunica com "miau". É o ponto mais doce e alto da imaginação. Em vez de impor regras, estenda-lhe também uma tigela de leite imaginária e aproveite a brincadeira.', title_sv = 'Vaknar som en katt 🐾', body_sv = 'I morse är barnet ingen människa. Det går på alla fyra, stryker sig mot dina ben och kommunicerar bara med ”mjau”. Det är fantasins sötaste topp. Istället för att sätta regler, räck fram en låtsasmjölkskål och njut av leken du också.', title_vi = 'Thức dậy như một chú mèo 🐾', body_vi = 'Sáng nay bé không phải là con người. Bé bò bằng bốn chân, cọ vào chân mẹ và chỉ giao tiếp bằng tiếng "meo". Đây là đỉnh cao đáng yêu nhất của trí tưởng tượng. Thay vì đặt quy tắc, hãy đưa bé một bát sữa tưởng tượng và tận hưởng trò chơi này.', title_zh = '像小猫一样醒来 🐾', body_zh = '今天早上宝宝不是人。四脚着地走来走去，蹭你的腿，只用“喵”来交流。这是想象力最可爱的巅峰时刻。别急着定规矩，你也递给它一个想象中的牛奶碗，好好享受这个游戏吧。' WHERE id = 'fee25f48-2972-4bf2-9d26-d0fbea33a7f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesiones en la Comunidad 💬', body_es = '¿Hoy has gritado por todo y te sientes la madre con menos paciencia del mundo? Por favor, debes saber que no estás sola. Entra en la Comunidad Anacan, lee que otras madres también están hoy igual de agotadas y acalla la culpa.', title_fr = 'Se confier à la Communauté 💬', body_fr = 'Aujourd''hui, vous avez crié pour tout et vous vous sentez la maman la plus impatiente du monde ? Sachez que vous n''êtes pas seule. Rejoignez la Communauté Anacan, lisez que d''autres mamans sont tout aussi épuisées aujourd''hui, et faites taire votre culpabilité.', title_hi = 'कम्युनिटी में इकरार 💬', body_hi = 'आज हर बात पर चिल्लाईं और खुद को दुनिया की सबसे बेसब्र माँ महसूस कर रही हैं? कृपया जान लीजिए कि आप अकेली नहीं हैं। Anacan कम्युनिटी में जाइए, पढ़िए कि दूसरी माँएँ भी आज उतनी ही थकी हैं, और अपने अपराधबोध को शांत कीजिए।', title_id = 'Pengakuan di komunitas 💬', body_id = 'Hari ini Anda meneriaki segala hal dan merasa menjadi ibu paling tidak sabar di dunia? Ketahuilah bahwa Anda tidak sendirian. Masuklah ke Komunitas Anacan, baca bahwa ibu-ibu lain juga sama lelahnya hari ini, dan redakan rasa bersalah Anda.', title_ja = 'コミュニティで打ち明けよう 💬', body_ja = '今日は何にでも叫んでしまって、自分は世界でいちばんがまんのできないママだと感じていますか？ひとりじゃないと知ってください。Anacanコミュニティを開いて、ほかのママたちも今日同じくらい疲れきっていると読んで、罪悪感をしずめましょう。', title_ko = '커뮤니티에 털어놓기 💬', body_ko = '오늘 모든 것에 소리치고 세상에서 가장 참을성 없는 엄마처럼 느껴지나요? 혼자가 아니라는 걸 꼭 알아 주세요. Anacan 커뮤니티에 들어가 다른 엄마들도 오늘 똑같이 지쳤다는 걸 읽으며 죄책감을 내려놓으세요.', title_nl = 'Bekentenis in de Community 💬', body_nl = 'Heb je vandaag tegen alles geschreeuwd en voel je je de ongeduldigste moeder ter wereld? Weet alsjeblieft dat je niet de enige bent. Ga naar de Anacan Community, lees dat andere mama''s vandaag net zo op waren en maak je schuldgevoel stil.', title_pl = 'Wyznanie w Społeczności 💬', body_pl = 'Dziś krzyczałaś na wszystko i czujesz się najbardziej niecierpliwą mamą na świecie? Wiedz, proszę, że nie jesteś sama. Wejdź do Społeczności Anacan, przeczytaj, że inne mamy są dziś tak samo wyczerpane, i ucisz wyrzuty sumienia.', title_pt = 'Desabafo na comunidade 💬', body_pt = 'Hoje gritou com tudo e sente-se a mãe mais impaciente do mundo? Saiba, por favor, que não está sozinha. Entre na Comunidade Anacan, leia que hoje outras mães também ficaram igualmente esgotadas e cale os remorsos.', title_sv = 'Ett erkännande i gemenskapen 💬', body_sv = 'Skrek du åt allt i dag och känner dig som världens mest otåliga mamma? Var snäll och vet att du inte är ensam. Gå in i Anacan Community, läs att andra mammor också var lika slut i dag och tysta ditt dåliga samvete.', title_vi = 'Lời thú nhận trong Cộng đồng 💬', body_vi = 'Hôm nay mẹ đã quát tháo mọi thứ và thấy mình là người mẹ thiếu kiên nhẫn nhất thế giới? Xin hãy biết rằng mẹ không đơn độc. Hãy vào Cộng đồng Anacan, đọc thấy các mẹ khác hôm nay cũng kiệt sức y như vậy, và làm dịu đi cảm giác tội lỗi của mình.', title_zh = '在社区里说出心里话 💬', body_zh = '今天对什么都吼了，觉得自己是世界上最没耐心的妈妈？请你知道，你并不孤单。进入Anacan社区，读读其他妈妈今天也一样精疲力竭，让心里的愧疚安静下来。' WHERE id = '0d53c056-84aa-4820-a905-2f2e60542791' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento loco de papá 📖', body_es = 'Esta noche la voz de la habitación no es la tuya. Dale el libro de cuentos a papá y deja que cuente la historia a propósito al revés, de forma cómica y absurda. Mira desde fuera cómo disfruta el peque corrigiéndole y cómo se ríe a carcajadas con su padre.', title_fr = 'Le conte farfelu de papa 📖', body_fr = 'Ce soir, ce n''est pas votre voix qu''on entendra dans la chambre. Donnez le livre de contes à papa et laissez-le raconter l''histoire à l''envers, exprès, de façon comique et absurde. Regardez de loin le plaisir de l''enfant à le corriger et ses éclats de rire.', title_hi = 'पापा की धमाकेदार कहानी 📖', body_hi = 'आज शाम कमरे में आवाज़ आपकी नहीं होगी। कहानी की किताब पापा को दीजिए और उन्हें कहानी जानबूझकर उलटी, मज़ेदार और बेतुकी तरह सुनाने दीजिए। दूर से देखिए कि बच्चा उन्हें सुधारने में कितना मज़ा लेता है और पापा पर कैसे ठहाके लगाता है।', title_id = 'Dongeng gila Ayah 📖', body_id = 'Malam ini suara di kamar bukan milik Anda. Serahkan buku dongeng kepada Ayah dan biarkan ia sengaja menceritakan kisahnya terbalik, lucu, dan absurd. Saksikan dari samping betapa anak senang membetulkannya dan tertawa terbahak-bahak pada ayahnya.', title_ja = 'パパのめちゃくちゃおはなし 📖', body_ja = '今夜の部屋の主役は、あなたの声ではありません。絵本をパパに渡して、お話をわざとあべこべに、おもしろおかしく話してもらいましょう。子どもがそれを直すのを楽しんで、パパに大笑いする姿をそばで眺めて。', title_ko = '아빠의 엉뚱한 동화 📖', body_ko = '오늘 저녁 방 안의 목소리는 엄마 몫이 아니에요. 동화책을 아빠에게 건네고 일부러 거꾸로, 웃기고 엉뚱하게 이야기하게 하세요. 아이가 아빠를 고쳐 주며 얼마나 즐거워하고 깔깔 웃는지 옆에서 지켜보세요.', title_nl = 'Papa''s gekke sprookje 📖', body_nl = 'Vanavond is de stem in de kamer niet die van jou. Geef het sprookjesboek aan papa en laat hem het verhaal expres achterstevoren, grappig en absurd vertellen. Kijk van een afstand hoe je kind geniet van het verbeteren en hoe hij om zijn papa schatert.', title_pl = 'Szalona bajka taty 📖', body_pl = 'Dziś wieczorem w pokoju nie słychać twojego głosu. Daj tacie książkę z bajkami i niech celowo opowie historię na opak, zabawnie i absurdalnie. Obserwuj z boku, z jaką przyjemnością dziecko go poprawia i jak zaśmiewa się z taty.', title_pt = 'A história maluca do pai 📖', body_pt = 'Esta noite a voz no quarto não é a sua. Dê o livro de histórias ao pai e deixe-o contar a história ao contrário de propósito, de forma cómica e absurda. Observe à distância como a criança adora corrigi-lo e se ri às gargalhadas com o pai.', title_sv = 'Pappas galna saga 📖', body_sv = 'I kväll är det inte din röst som hörs i rummet. Ge sagoboken till pappa och låt honom berätta historien medvetet bakvänt, roligt och absurt. Titta från sidan på hur barnet njuter av att rätta honom och skrattar åt pappa.', title_vi = 'Câu chuyện điên rồ của bố 📖', body_vi = 'Tối nay giọng nói trong phòng không phải của mẹ. Hãy đưa cuốn truyện cho bố và để bố cố tình kể ngược, hài hước và ngớ ngẩn. Ngắm nhìn từ xa bé thích thú sửa lời bố và cười ngặt nghẽo thế nào.', title_zh = '爸爸的疯狂童话 📖', body_zh = '今晚房间里的声音不属于你。把故事书交给爸爸，让他故意把故事讲反、讲得搞笑又荒诞。在一旁看看宝宝多么享受纠正爸爸，又是怎样对着爸爸哈哈大笑的。' WHERE id = '844a3d1a-225d-46c7-945c-c5eaf88248c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un arquitecto de vanguardia 🥞', body_es = 'Apila las tortitas del desayuno para construir una torre, les hace un agujero en el centro y mete el dedo. Jugar con la comida es para él un nuevo proyecto de ingeniería. Haz la vista gorda con la mesa sucia: así descubre la textura de la comida.', title_fr = 'Un architecte avant-gardiste 🥞', body_fr = 'Au petit-déjeuner, il empile ses crêpes en tour, fait un trou au milieu et y passe le doigt. Jouer avec la nourriture est pour lui un nouveau projet d''ingénierie. Fermez les yeux sur la table salie, c''est ainsi qu''il découvre la texture des aliments.', title_hi = 'अवांगार्द वास्तुकार 🥞', body_hi = 'नाश्ते के पैनकेक एक के ऊपर एक रखकर मीनार बनाता है, बीच में छेद करता है और उसमें से उँगली निकालता है। खाने से खेलना उसके लिए नया इंजीनियरिंग प्रोजेक्ट है। मेज़ गंदी होने को नज़रअंदाज़ कीजिए, वह ऐसे ही खाने की बनावट खोज रहा है।', title_id = 'Arsitek avant-garde 🥞', body_id = 'Saat sarapan ia menumpuk panekuk menjadi menara, melubangi tengahnya, dan memasukkan jarinya ke dalam. Bermain dengan makanan baginya adalah proyek teknik baru. Abaikan meja yang kotor, begitulah ia menjelajahi tekstur makanan.', title_ja = 'アバンギャルドな建築家 🥞', body_ja = '朝ごはんのパンケーキを積み重ねてタワーを作り、まんなかに穴をあけて指を通している。食べ物で遊ぶのは、この子にとって新しいエンジニアリングのプロジェクトです。テーブルが汚れるのは目をつぶって。こうして食べ物の感触を発見しているんです。', title_ko = '아방가르드 건축가 🥞', body_ko = '아침 팬케이크를 쌓아 탑을 만들고 가운데 구멍을 뚫어 손가락을 넣나요? 음식 놀이는 아이에게 새로운 공학 프로젝트예요. 식탁이 더러워지는 건 눈감아 주세요, 음식의 질감을 탐험하는 중이에요.', title_nl = 'Avant-gardistische architect 🥞', body_nl = 'Hij stapelt de pannenkoekjes van het ontbijt tot een toren, prikt er een gat in en steekt er zijn vinger doorheen. Spelen met eten is voor hem een nieuw bouwproject. Kijk niet naar de vieze tafel, zo ontdekt hij de structuur van eten.', title_pl = 'Awangardowy architekt 🥞', body_pl = 'Układa naleśniki ze śniadania w wieżę, robi w środku dziurę i przekłada przez nią palec. Zabawa jedzeniem to dla niego nowy projekt inżynieryjny. Przymknij oko na brudny stół, w ten sposób poznaje fakturę jedzenia.', title_pt = 'Arquiteto de vanguarda 🥞', body_pt = 'Empilha as panquecas do pequeno-almoço numa torre, fura-as ao meio e passa o dedo por dentro. Brincar com a comida é para ele um novo projeto de engenharia. Feche os olhos à mesa suja: é assim que descobre a textura dos alimentos.', title_sv = 'Den avantgardistiska arkitekten 🥞', body_sv = 'Barnet staplar frukostpannkakorna till ett torn, gör hål i mitten och sticker fingret igenom. Att leka med maten är ett nytt ingenjörsprojekt för barnet. Blunda för det smutsiga bordet, det är så barnet upptäcker matens konsistens.', title_vi = 'Kiến trúc sư tiên phong 🥞', body_vi = 'Bữa sáng, bé xếp bánh kếp chồng lên nhau thành tòa tháp, chọc thủng ở giữa rồi luồn ngón tay qua. Nghịch đồ ăn là một dự án kỹ thuật mới của bé. Hãy làm ngơ chuyện bàn ăn bị bẩn, bé đang khám phá kết cấu của thức ăn đấy.', title_zh = '前卫建筑师 🥞', body_zh = '把早餐的薄饼一张张摞起来盖塔，在中间戳个洞，再把手指穿过去。对宝宝来说，玩食物是一个新的工程项目。桌子脏了就睁一只眼闭一只眼吧，宝宝正是这样探索食物的质地。' WHERE id = 'c862c51e-5b03-4e55-bd66-35165e58d3d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tienda imaginaria 🍅', body_es = 'En un rincón de la habitación ha juntado sus juguetes y te vende tomates imaginarios con dinero imaginario. Ponte muy seria en este juego de comercio. Compra ese tomate imaginario y haz como que te lo comes con ganas. Los juegos de rol son la base más sólida de su inteligencia social y su lógica matemática.', title_fr = 'Le magasin imaginaire 🍅', body_fr = 'Dans un coin de la pièce, il a rassemblé ses jouets et vous vend des tomates imaginaires avec de l''argent imaginaire. Soyez très sérieuse dans ce jeu de commerce. Achetez cette tomate imaginaire et faites semblant de la manger avec appétit. Les jeux de rôle sont la base la plus solide de son intelligence sociale et de sa logique mathématique.', title_hi = 'काल्पनिक दुकान 🍅', body_hi = 'कमरे के एक कोने में खिलौने जमा करके आपको काल्पनिक पैसों में काल्पनिक टमाटर बेच रहा है। इस व्यापार के खेल में बहुत गंभीर रहिए। वह काल्पनिक टमाटर खरीदकर ऐसे दिखाइए जैसे चाव से खा रही हों। रोल-प्ले खेल उसकी सामाजिक समझ और गणितीय तर्क की सबसे मज़बूत नींव हैं।', title_id = 'Toko khayalan 🍅', body_id = 'Di sudut kamar ia mengumpulkan mainan dan menjual tomat khayalan kepada Anda dengan uang khayalan. Bersikaplah sangat serius dalam permainan dagang ini. Belilah tomat khayalan itu dan berpura-puralah memakannya dengan lahap. Bermain peran adalah fondasi terkuat kecerdasan sosial dan logika matematisnya.', title_ja = '空想のお店 🍅', body_ja = '部屋のすみにおもちゃを集めて、空想のお金で空想のトマトを売ってくれる。このお店ごっこでは、とても真剣にふるまいましょう。そのトマトを買って、おいしそうに食べるふりをして。ごっこ遊びは、社会性と算数の考え方のいちばん強い土台です。', title_ko = '상상 속 가게 🍅', body_ko = '방 한쪽에 장난감을 모아 놓고 상상의 돈으로 상상의 토마토를 파나요? 이 장사 놀이에서는 아주 진지해야 해요. 그 토마토를 사서 맛있게 먹는 척해 주세요. 역할 놀이는 사회적 지능과 수학적 논리의 가장 튼튼한 바탕이에요.', title_nl = 'De denkbeeldige winkel 🍅', body_nl = 'Hij heeft in een hoek van de kamer zijn speelgoed verzameld en verkoopt je denkbeeldige tomaten voor denkbeeldig geld. Wees heel serieus in dit handelsspel. Koop die denkbeeldige tomaat en doe alsof je hem met smaak opeet. Rollenspel is de sterkste basis voor zijn sociale intelligentie en wiskundige logica.', title_pl = 'Wymyślony sklep 🍅', body_pl = 'W kącie pokoju zebrał zabawki i sprzedaje ci wymyślone pomidory za wymyślone pieniądze. Bądź w tej grze w handel bardzo poważna. Kup ten wymyślony pomidor i udawaj, że zajadasz go z apetytem. Zabawy w odgrywanie ról to najmocniejszy fundament jego inteligencji społecznej i logiki matematycznej.', title_pt = 'Loja imaginária 🍅', body_pt = 'Num canto do quarto, junta os brinquedos e vende-lhe tomates imaginários com dinheiro imaginário. Leve este jogo de comércio muito a sério. Compre aquele tomate imaginário e finja que o come com apetite. As brincadeiras de faz de conta são a base mais forte da inteligência social e da lógica matemática dele.', title_sv = 'Låtsasaffären 🍅', body_sv = 'I ett hörn av rummet samlar barnet leksaker och säljer låtsastomater till dig för låtsaspengar. Var väldigt seriös i handelsleken. Köp låtsastomaten och låtsas äta den med god aptit. Rollekar är den starkaste grunden för barnets sociala intelligens och matematiska logik.', title_vi = 'Cửa hàng tưởng tượng 🍅', body_vi = 'Bé gom đồ chơi vào một góc phòng và bán cho mẹ cà chua tưởng tượng bằng tiền tưởng tượng. Hãy thật nghiêm túc trong trò chơi buôn bán này. Mua quả cà chua tưởng tượng và giả vờ ăn thật ngon lành. Trò chơi nhập vai là nền tảng vững chắc nhất cho trí tuệ xã hội và tư duy toán học của bé.', title_zh = '想象中的商店 🍅', body_zh = '在房间一角把玩具堆起来，用想象中的钱卖给你想象中的番茄。在这场买卖游戏里要非常认真。买下那个想象中的番茄，装作吃得津津有味。角色扮演游戏是宝宝社交智力和数学逻辑最坚实的基础。' WHERE id = '772055c7-02e3-4df1-ab25-b0a7ed011afe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mamá que comes a escondidas un trozo de chocolate detrás del armario de la cocina: esa glucosa es tu derecho más natural. Para aguantar todo el día esa energía y esos «por qué» sin fin, tú también necesitas recargarte. Respira y mastica a gusto.', body_fr = 'Maman qui mange un bout de chocolat en cachette derrière le placard de la cuisine, ce glucose est votre droit le plus naturel. Pour supporter toute la journée cette énergie et ces « pourquoi » sans fin, vous devez recharger vos batteries. Respirez et croquez avec plaisir.', body_hi = 'रसोई की अलमारी के पीछे छिपकर चॉकलेट का एक टुकड़ा खाने वाली माँ, वह ग्लूकोज़ आपका सबसे स्वाभाविक हक है। दिनभर उस ऊर्जा और कभी न खत्म होने वाले ‘क्यों’ को झेलने के लिए आपका भी चार्ज रहना ज़रूरी है। साँस लीजिए और मज़े से चबाइए।', body_id = 'Ibu yang diam-diam makan sepotong cokelat di balik lemari dapur, glukosa itu hak paling alami milikmu. Untuk tahan menghadapi energi itu dan ''kenapa'' yang tak ada habisnya seharian, kamu wajib mengisi ulang tenaga. Tarik napas dan kunyah dengan nikmat.', body_ja = 'キッチンの棚のかげで、こっそりチョコをひとかけら食べているママへ。そのブドウ糖は、あなたのいちばん自然な権利です。一日じゅうあのエネルギーと終わらない「なんで？」に付き合うには、あなたの充電が欠かせません。深呼吸して、味わって食べて。', body_ko = '부엌 찬장 뒤에서 몰래 초콜릿 한 조각을 먹는 엄마, 그 당분은 엄마의 가장 당연한 권리예요. 하루 종일 그 에너지와 끝없는 ''왜?''를 견디려면 엄마도 충전해야 해요. 숨 한번 쉬고 맛있게 드세요.', body_nl = 'Mama die stiekem achter het keukenkastje een stukje chocola eet: die glucose is je meest natuurlijke recht. Om de hele dag die energie en die eindeloze waaroms aan te kunnen, moet jij ook opgeladen zijn. Haal adem en kauw met plezier.', body_pl = 'Mamo, która po kryjomu jesz kawałek czekolady za szafką w kuchni: ta glukoza to twoje najbardziej naturalne prawo. Żeby przez cały dzień znosić tę energię i niekończące się „dlaczego”, musisz się naładować. Oddychaj i jedz z przyjemnością.', body_pt = 'Mãe que come um pedaço de chocolate às escondidas atrás do armário da cozinha: essa glicose é o seu direito mais natural. Para aguentar o dia todo aquela energia e aqueles "porquês" sem fim, precisa de recarregar. Respire e mastigue com prazer.', body_sv = 'Mamma som i smyg äter en bit choklad bakom köksskåpet: den glukosen är din mest naturliga rättighet. För att orka med den energin och alla ändlösa varför hela dagen måste du också ladda batterierna. Andas och tugga med njutning.', body_vi = 'Mẹ ơi, mẹ đang lén ăn một miếng sô-cô-la sau tủ bếp, lượng đường đó là quyền tự nhiên nhất của mẹ. Để chịu được nguồn năng lượng ấy và những câu "tại sao" bất tận suốt cả ngày, mẹ cũng cần được sạc pin. Hít thở và thưởng thức đi.', body_zh = '躲在厨房柜子后面偷偷吃一块巧克力的妈妈，那点糖是你最天经地义的权利。要整天扛住那股能量、那些没完没了的“为什么”，你也得充好电。深呼吸，好好享受地嚼吧。' WHERE id = '9c4fcd9f-eca4-4781-b7b6-58a379dc2126' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terror nocturno 😭', body_es = 'Se ha despertado en mitad de la noche llorando con los ojos cerrados y no oye a nadie. Confírmalo con el Análisis del llanto; si es un terror nocturno, no le sacudas ni intentes despertarle. Quédate a su lado en silencio y dale seguridad: pasará.', title_fr = 'Terreur nocturne 😭', body_fr = 'Il s''est réveillé en pleine nuit en pleurant, les yeux fermés, sans entendre personne. Vérifiez avec l''Analyse des pleurs : s''il s''agit d''une terreur nocturne, ne le secouez pas et n''essayez pas de le réveiller. Restez simplement près de lui en silence pour le rassurer, ça va passer.', title_hi = 'रात का डर 😭', body_hi = 'आधी रात आँखें बंद किए रोते हुए जागा और किसी की नहीं सुनता। क्राइंग एनालिसिस से पुष्टि कीजिए; अगर यह नाइट टेरर है, तो उसे हिलाइए मत और जगाने की कोशिश मत कीजिए। बस चुपचाप पास रहकर भरोसा दीजिए, यह गुज़र जाएगा।', title_id = 'Ketakutan malam 😭', body_id = 'Tengah malam ia terbangun menangis dengan mata terpejam dan tidak mendengar siapa pun. Pastikan dengan Analisis Tangisan; jika ini teror tidur, jangan mengguncang atau mencoba membangunkannya. Cukup berdiri di sampingnya tanpa bersuara dan beri rasa aman, ini akan berlalu.', title_ja = '夜のこわい夢 😭', body_ja = '夜中に目を閉じたまま泣いて起き、誰の声も聞こえていない様子。「泣き声分析」で確かめてみましょう。もし夜驚症なら、ゆさぶったり起こそうとしたりしないで。ただ静かにそばにいて安心させてあげれば、おさまります。', title_ko = '밤 공포 😭', body_ko = '한밤중에 눈을 감은 채 울며 깨어나 아무 말도 듣지 못하나요? 울음 분석으로 확인해 보세요. 야경증이라면 흔들거나 깨우려 하지 말고 곁에서 조용히 안심시켜 주세요. 곧 지나갈 거예요.', title_nl = 'Nachtangst 😭', body_nl = 'Werd hij midden in de nacht huilend wakker met zijn ogen dicht, en hoort hij niemand? Controleer het met Huilanalyse; als het een nachtmerrie-aanval (pavor nocturnus) is, schud hem dan niet door elkaar en probeer hem niet wakker te maken. Blijf stil bij hem en geef hem vertrouwen, het gaat over.', title_pl = 'Lęk nocny 😭', body_pl = 'W środku nocy obudził się z płaczem, z zamkniętymi oczami, i nikogo nie słyszy. Potwierdź to Analizą płaczu; jeśli to lęk nocny, nie potrząsaj nim i nie próbuj go budzić. Po prostu bądź obok w ciszy i dawaj poczucie bezpieczeństwa, minie.', title_pt = 'Medo noturno 😭', body_pt = 'Acordou a meio da noite a chorar, de olhos fechados, e não ouve ninguém. Confirme com a Análise do Choro; se for terror noturno, não o abane nem tente acordá-lo. Fique apenas ao lado dele em silêncio e dê-lhe segurança: vai passar.', title_sv = 'Nattskräck 😭', body_sv = 'Mitt i natten har barnet vaknat gråtande med slutna ögon och hör ingen. Kontrollera med Gråtanalys; om det är nattskräck, skaka inte barnet och försök inte väcka det. Stå bara tyst bredvid och ge trygghet, det går över.', title_vi = 'Hoảng sợ ban đêm 😭', body_vi = 'Nửa đêm bé thức dậy khóc, mắt vẫn nhắm và không nghe thấy ai? Hãy kiểm tra bằng Phân tích tiếng khóc; nếu đó là hoảng sợ khi ngủ (night terror), đừng lay hay cố đánh thức bé. Chỉ cần lặng lẽ ở bên cạnh để bé an tâm, rồi sẽ qua thôi.', title_zh = '夜惊 😭', body_zh = '半夜闭着眼睛哭着醒来，谁的话都听不进去。用哭声分析确认一下；如果是夜惊，别摇晃宝宝，也别试图叫醒宝宝。只要静静地陪在身边，给宝宝安全感，会过去的。' WHERE id = 'a0a70ea3-00c4-4338-848e-bcb45a1157ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una lógica helada 🥶', body_es = 'Abre la nevera, pide la cubitera y no la suelta aunque se le congelen las manos. Está comprobando con su cuerpo el concepto de frío y calor. Pon agua templada en un cuenco y agua con hielo en otro y convierte este descubrimiento en un pequeño experimento científico: su terquedad se romperá al instante.', title_fr = 'Une logique glaciale 🥶', body_fr = 'Il ouvre le frigo, réclame le bac à glaçons et refuse de le lâcher alors que ses mains ont froid. Il teste avec son corps la notion de chaud et de froid. Mettez de l''eau tiède dans un bol et de l''eau glacée dans un autre pour transformer cette découverte en petite expérience scientifique : son entêtement fondra aussitôt.', title_hi = 'बर्फ़ जैसा तर्क 🥶', body_hi = 'फ़्रिज खोलकर आइस ट्रे माँगता है और हाथ ठंडे होने के बावजूद उसे नहीं छोड़ता। वह गर्म और ठंडे की समझ अपने शरीर से परख रहा है। एक बर्तन में गुनगुना, दूसरे में बर्फ़ वाला पानी रखकर इस खोज को छोटे वैज्ञानिक प्रयोग में बदल दीजिए, ज़िद तुरंत टूट जाएगी।', title_id = 'Logika sedingin es 🥶', body_id = 'Ia membuka kulkas, meminta cetakan es, dan tidak mau melepasnya meski tangannya kedinginan. Ia sedang menguji konsep panas dan dingin dengan tubuhnya. Isi satu wadah dengan air hangat dan satu lagi dengan air es, ubah penemuan ini menjadi eksperimen ilmiah kecil, dan sikap keras kepalanya akan langsung luluh.', title_ja = '氷のような理屈 🥶', body_ja = '冷蔵庫を開けて製氷皿をほしがり、手が冷たくなっても離さない。体で温かい・冷たいを確かめているんです。ひとつの器にぬるま湯、もうひとつに氷水を入れて、この発見を小さな科学実験に変えましょう。がんこさもすぐにとけますよ。', title_ko = '얼음 같은 논리 🥶', body_ko = '냉장고를 열어 얼음 틀을 달라고 하고, 손이 시려도 놓지 않나요? 몸으로 따뜻함과 차가움을 시험하는 중이에요. 한 그릇엔 미지근한 물, 한 그릇엔 얼음물을 담아 작은 과학 실험으로 바꿔 주면 고집이 금세 풀릴 거예요.', title_nl = 'IJskoude logica 🥶', body_nl = 'Hij doet de koelkast open, eist het ijsblokjesbakje op en laat het niet los, hoe koud zijn handen ook worden. Hij test warm en koud met zijn lichaam. Doe lauw water in het ene bakje en ijswater in het andere en maak van deze ontdekking een klein wetenschappelijk experiment, dan breekt zijn koppigheid meteen.', title_pl = 'Lodowata logika 🥶', body_pl = 'Otwiera lodówkę, domaga się foremki z lodem i choć marzną mu ręce, nie chce jej puścić. Ciałem sprawdza, czym jest ciepło i zimno. Nalej do jednej miski letniej, a do drugiej lodowatej wody i zamień to odkrycie w mały eksperyment naukowy, a upór od razu zniknie.', title_pt = 'Lógica gelada 🥶', body_pt = 'Abre o frigorífico, exige a forma de gelo e, apesar de ter as mãos geladas, não a larga. Está a testar com o corpo a noção de quente e frio. Ponha água morna numa taça e água gelada noutra e transforme esta descoberta numa pequena experiência científica: a teimosia passa logo.', title_sv = 'Iskall logik 🥶', body_sv = 'Barnet öppnar kylskåpet, kräver isbitsformen och släpper den inte trots att händerna fryser. Barnet testar begreppen varmt och kallt med kroppen. Häll ljummet vatten i en skål och isvatten i en annan och gör upptäckten till ett litet vetenskapligt experiment, så bryts envisheten direkt.', title_vi = 'Logic lạnh như băng 🥶', body_vi = 'Bé mở tủ lạnh, đòi lấy khay đá và nhất quyết không buông dù tay đã lạnh cóng. Bé đang dùng cơ thể để thử cảm nhận nóng và lạnh. Hãy cho nước ấm vào một bát, nước đá vào một bát để biến khám phá này thành một thí nghiệm khoa học nhỏ, sự bướng bỉnh sẽ tan biến ngay.', title_zh = '冰一样的逻辑 🥶', body_zh = '打开冰箱非要拿冰格，手冻得冰凉也不肯放。宝宝在用身体测试冷和热的概念。一个碗里倒温水，一个碗里放冰水，把这次探索变成一个小小的科学实验，倔劲儿马上就没了。' WHERE id = '2d19f095-845a-4bde-a575-de7451355856' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada obligatoria a la naturaleza ⛅', body_es = 'Entre cuatro paredes su energía se convierte en agresividad y cada frase empieza por «no». Haga el tiempo que haga, abrígale según Tiempo y ropa y sácale fuera sin falta. Tocar la tierra reiniciará su sistema nervioso al instante.', title_fr = 'S''évader absolument dans la nature ⛅', body_fr = 'Entre quatre murs, son énergie se transforme en agressivité et chacune de ses phrases commence par « non ». Quel que soit le temps, équipez-le comme il faut et sortez-le absolument. Toucher la terre remettra aussitôt son système nerveux à zéro.', title_hi = 'प्रकृति की ओर ज़रूर भागिए ⛅', body_hi = 'चार दीवारों के अंदर उसकी ऊर्जा गुस्से में बदल जाती है और उसका हर वाक्य ‘नहीं’ से शुरू होता है। मौसम कैसा भी हो, सही कपड़े पहनाकर उसे बाहर ज़रूर ले जाइए। मिट्टी छूना उसके तंत्रिका तंत्र को तुरंत रीसेट कर देगा।', title_id = 'Wajib kabur ke alam ⛅', body_id = 'Di dalam empat dinding, energinya berubah menjadi agresi dan setiap kalimatnya diawali dengan ''nggak''. Apa pun cuacanya, kenakan pakaian yang sesuai dan pastikan mengajaknya keluar. Menyentuh tanah akan langsung me-reset sistem sarafnya.', title_ja = 'とにかく自然へ ⛅', body_ja = '4つの壁の中で、エネルギーがイライラに変わり、口を開けば「いや」から始まる。天気や服装に関係なく、しっかり準備して必ず外へ連れ出しましょう。土にさわれば、神経がすぐにリセットされます。', title_ko = '꼭 필요한 자연 탈출 ⛅', body_ko = '네 벽 안에서 에너지가 공격성으로 바뀌고 말마다 ''싫어''로 시작하나요? 날씨가 어떻든 알맞게 챙겨 입혀 꼭 밖에 데리고 나가세요. 흙을 만지면 신경계가 바로 초기화돼요.', title_nl = 'Echt even de natuur in ⛅', body_nl = 'Tussen vier muren wordt zijn energie agressie en begint elke zin met ''nee''. Kleed hem passend aan, ongeacht het weer, en ga hoe dan ook naar buiten. Aarde aanraken zet zijn zenuwstelsel meteen op nul.', title_pl = 'Konieczna ucieczka na łono natury ⛅', body_pl = 'W czterech ścianach jego energia zamienia się w agresję, a każde zdanie zaczyna się od „nie”. Bez względu na pogodę ubierz go odpowiednio i koniecznie wyjdźcie na dwór. Dotyk ziemi od razu zresetuje jego układ nerwowy.', title_pt = 'Fuga obrigatória para a natureza ⛅', body_pt = 'Entre quatro paredes, a energia dele transforma-se em agressividade e cada frase começa com "não". Seja qual for o tempo, vista-o de forma adequada e leve-o sem falta para a rua. Tocar na terra vai reiniciar logo o sistema nervoso dele.', title_sv = 'Ut i naturen, absolut ⛅', body_sv = 'Mellan fyra väggar blir barnets energi till ilska och varje mening börjar med ”nej”. Oavsett väder, klä barnet rätt och se till att ni kommer ut. Att röra vid jorden nollställer nervsystemet direkt.', title_vi = 'Nhất định phải ra với thiên nhiên ⛅', body_vi = 'Ở trong bốn bức tường, năng lượng của bé biến thành sự hung hăng và câu nào cũng bắt đầu bằng "không". Dù thời tiết thế nào, hãy chuẩn bị trang phục phù hợp và nhất định đưa bé ra ngoài. Chạm vào đất sẽ lập tức "khởi động lại" hệ thần kinh của bé.', title_zh = '一定要奔向大自然 ⛅', body_zh = '被关在四面墙里，精力就会变成攻击性，每句话都以“不”开头。不管天气如何，穿戴合适，一定要带宝宝出门。摸摸泥土，能让宝宝的神经系统马上重启。' WHERE id = '5b70990d-933c-46b2-be30-1407db2c7b1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lamparita de noche 🌙', body_es = '¿Se inquieta cuando se apagan las luces del dormitorio? Pon en un rincón una pequeña lamparita de luz cálida (naranja o roja). El resto de la habitación debe quedar totalmente a oscuras para que se libere la melatonina y tenga un sueño profundo.', title_fr = 'La veilleuse 🌙', body_fr = 'Il s''inquiète quand on éteint la lumière de la chambre ? Posez dans un coin une petite veilleuse de couleur chaude (orange ou rouge). Le reste de la chambre doit rester complètement sombre pour la sécrétion de mélatonine et un sommeil profond.', title_hi = 'नाइट लैंप 🌙', body_hi = 'सोने के कमरे में लाइटें बुझते ही बेचैन हो जाता है? कमरे के एक कोने में गर्म रंग (नारंगी या लाल) की एक छोटी नाइट लैंप रखिए। बाकी कमरा मेलाटोनिन बनने और गहरी नींद के लिए पूरी तरह अँधेरा रहना चाहिए।', title_id = 'Lampu tidur 🌙', body_id = 'Ia gelisah saat lampu kamar dimatikan? Letakkan lampu tidur kecil berwarna hangat (oranye atau merah) di salah satu sudut kamar. Bagian kamar lainnya harus tetap gelap total untuk produksi melatonin dan tidur yang nyenyak.', title_ja = 'ナイトライト 🌙', body_ja = '寝室の明かりを消すと不安になる？部屋のすみに、暖かい色（オレンジや赤）の小さなナイトライトを置きましょう。それ以外の部分は、メラトニンの分泌と深い眠りのために真っ暗にしておいてね。', title_ko = '수면등 🌙', body_ko = '침실 불이 꺼지면 불안해하나요? 방 한쪽에 작고 따뜻한 색(주황색이나 빨간색) 수면등을 두세요. 나머지 공간은 멜라토닌 분비와 깊은 잠을 위해 완전히 어둡게 유지해야 해요.', title_nl = 'Nachtlampje 🌙', body_nl = 'Wordt hij onrustig als het licht in de slaapkamer uitgaat? Zet een klein nachtlampje met een warme kleur (oranje of rood) in een hoek van de kamer. De rest van de kamer blijft helemaal donker voor de aanmaak van melatonine en een diepe slaap.', title_pl = 'Lampka nocna 🌙', body_pl = 'Niepokoi się, gdy w sypialni gaśnie światło? Postaw w kącie pokoju małą lampkę nocną w ciepłym kolorze (pomarańczowym lub czerwonym). Reszta pokoju powinna pozostać zupełnie ciemna, by wydzielała się melatonina, a sen był głęboki.', title_pt = 'Luz de presença 🌙', body_pt = 'Fica inquieto quando se apagam as luzes do quarto? Ponha num canto do quarto uma pequena luz de presença de cor quente (laranja ou vermelha). O resto do quarto deve ficar totalmente escuro para a produção de melatonina e um sono profundo.', title_sv = 'Nattlampan 🌙', body_sv = 'Blir barnet oroligt när lampan släcks i sovrummet? Ställ en liten nattlampa med varmt sken (orange eller röd) i ett hörn av rummet. Resten av rummet ska vara helt mörkt för melatoninutsöndringen och en djup sömn.', title_vi = 'Đèn ngủ 🌙', body_vi = 'Bé lo lắng khi đèn phòng ngủ tắt? Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm (cam hoặc đỏ) ở một góc phòng. Phần còn lại của căn phòng nên tối hoàn toàn để melatonin được tiết ra và bé ngủ sâu.', title_zh = '小夜灯 🌙', body_zh = '卧室一关灯就不安？在房间一角放一盏小小的暖色（橙色或红色）小夜灯。房间其余的地方要保持全黑，才能分泌褪黑素、睡得深沉。' WHERE id = '72b51261-3fd9-4ba4-a07e-a52ab32038d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista digital al rescate 🛒', body_es = 'En medio del súper te preguntas: «¿Qué había venido a comprar?». El cerebro de una madre ya está dividido en mil partes. Acostúmbrate a apuntarlo en la Lista de la compra de la app en el primer segundo en que surja la necesidad y aligera tu carga.', title_fr = 'La liste numérique qui vous sauve 🛒', body_fr = 'Plantée au milieu du supermarché, vous vous demandez : « Qu''est-ce que je suis venue acheter ? » Le cerveau de maman est déjà éparpillé dans mille directions. Prenez l''habitude de noter chaque besoin dans la Liste de courses de l''application dès la première seconde, et allégez votre charge.', title_hi = 'डिजिटल लिस्ट बचाने आई 🛒', body_hi = 'बाज़ार के बीच खड़ी सोच रही हैं, ‘मैं यहाँ क्या लेने आई थी?’ माँ का दिमाग वैसे ही हज़ार जगह बँटा होता है। ज़रूरत के पहले ही पल उसे ऐप की शॉपिंग लिस्ट में लिखने की आदत डालिए और अपना बोझ हल्का कीजिए।', title_id = 'Penyelamat daftar digital 🛒', body_id = 'Anda berdiri di tengah supermarket dan berpikir ''Aku ke sini mau beli apa ya?''. Otak seorang ibu memang sudah terbagi ke seribu arah. Biasakan mencatat kebutuhan di Daftar Belanja aplikasi di detik pertama teringat, dan ringankan beban Anda.', title_ja = 'デジタルリストが救世主 🛒', body_ja = 'スーパーのまんなかで「何を買いに来たんだっけ？」と立ちつくす。ママの頭はただでさえ千のことでいっぱいです。必要になった最初の瞬間に、アプリの「買い物リスト」に書く習慣をつけて、負担を軽くしましょう。', title_ko = '디지털 목록 구원 투수 🛒', body_ko = '마트 한가운데서 ''내가 뭘 사러 왔더라?'' 하고 서 있나요? 엄마의 머릿속은 이미 천 갈래로 나뉘어 있죠. 필요한 게 생기는 첫 순간 앱의 쇼핑 목록에 적는 습관으로 짐을 덜어 보세요.', title_nl = 'Digitaal lijstje als redder 🛒', body_nl = 'Sta je midden in de supermarkt te denken: ''Wat kwam ik hier ook alweer halen?'' Een mamabrein is toch al in duizend stukjes verdeeld. Maak er een gewoonte van om iets meteen op het Boodschappenlijstje in de app te zetten zodra je het nodig hebt, en maak je last lichter.', title_pl = 'Cyfrowa lista na ratunek 🛒', body_pl = 'Stoisz na środku sklepu i myślisz: „Po co ja tu przyszłam?”. Mamusiowy mózg i tak dzieli się na tysiąc spraw. Wyrób sobie nawyk wpisywania potrzebnej rzeczy na Listę zakupów w aplikacji w pierwszej sekundzie i odciąż się.', title_pt = 'A lista digital que salva 🛒', body_pt = 'Parada no meio do supermercado, pensa "o que é que eu vim aqui comprar?". O cérebro de mãe já anda dividido por mil sítios. Habitue-se a escrever cada coisa na Lista de Compras da app no primeiro segundo em que faz falta e alivie o seu peso.', title_sv = 'Den digitala listan som räddare 🛒', body_sv = 'Du står mitt i butiken och tänker ”vad var det jag skulle köpa här?”. Mammahjärnan är ändå uppdelad på tusen ställen. Gör det till en vana att skriva upp saker i appens Inköpslista första sekunden behovet uppstår och lätta din börda.', title_vi = 'Danh sách số cứu nguy 🛒', body_vi = 'Đứng giữa siêu thị, mẹ tự hỏi: "Mình đến đây mua gì nhỉ?". Đầu óc của mẹ vốn đã chia ra nghìn việc. Hãy tập thói quen ghi ngay vào Danh sách mua sắm trong ứng dụng vào giây phút đầu tiên cần đến, để nhẹ gánh hơn.', title_zh = '数字清单救星 🛒', body_zh = '站在超市中间想：“我来这儿是要买什么来着？”当妈妈的大脑本来就被分成了上千份。养成一需要就马上写进应用里购物清单的习惯，减轻你的负担吧。' WHERE id = '0bee47e7-94df-4d8c-b500-e8adc690d1ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sabotaje del «¡Te ayudo!» 🧽', body_es = '¿Mientras friegas los platos quiere poner una silla a tu lado para jugar con el agua? En realidad no quiere ayudar, quiere estar en el centro mismo de la acción. Dale un plato pequeño de plástico y una esponja. La cocina acabará empapada, pero su ego se hará gigante.', title_fr = 'Le sabotage du « Je t''aide ! » 🧽', body_fr = 'Quand vous faites la vaisselle, il veut absolument installer une chaise à côté de vous pour jouer avec l''eau ? En réalité, il ne veut pas tant aider qu''être au cœur même de l''action. Donnez-lui un petit bol en plastique et une éponge. La cuisine sera inondée, mais son ego sera immense.', title_hi = '‘मैं मदद करूँ!’ वाली तोड़फोड़ 🧽', body_hi = 'आप बर्तन धोती हैं तो वह ज़रूर पास में कुर्सी लगाकर पानी से खेलना चाहता है? असल में वह मदद नहीं, काम के ठीक बीचोंबीच रहना चाहता है। उसे एक छोटा प्लास्टिक का बर्तन और स्पंज दीजिए। रसोई गीली होगी, पर उसका आत्मविश्वास आसमान छू लेगा।', title_id = 'Sabotase ''Aku bantu ya!'' 🧽', body_id = 'Saat Anda mencuci piring, ia bersikeras menaruh kursi di samping Anda dan bermain air? Sebenarnya ia bukan ingin membantu, tapi ingin berada tepat di pusat kegiatan. Beri ia mangkuk plastik kecil dan spons. Dapur akan basah kuyup, tapi egonya akan tumbuh besar.', title_ja = '「お手伝いするよ！」の妨害工作 🧽', body_ja = 'あなたが洗いものをしていると、必ずいすを持ってきて水遊びしたがる？本当はお手伝いではなく、その場のど真ん中にいたいんです。小さなプラスチックの容器とスポンジを渡しましょう。キッチンは水びたしになるけれど、この子の自信はぐんと大きくなります。', title_ko = '''내가 도와줄게!'' 대작전 🧽', body_ko = '설거지할 때 꼭 옆에 의자를 갖다 놓고 물장난을 하고 싶어 하나요? 사실 돕기보다는 일의 한가운데에 있고 싶은 거예요. 작은 플라스틱 그릇과 스펀지를 주세요. 부엌은 엉망이 되겠지만 아이의 자존감은 쑥쑥 자랄 거예요.', title_nl = '''Ik help je!''-sabotage 🧽', body_nl = 'Wil hij als jij afwast per se een stoel ernaast zetten en met water spelen? Eigenlijk wil hij niet helpen, maar helemaal midden in de actie zijn. Geef hem een klein plastic bakje en een sponsje. De keuken wordt nat, maar zijn ego groeit enorm.', title_pl = 'Dywersja „Pomogę ci!” 🧽', body_pl = 'Gdy zmywasz naczynia, koniecznie chce przystawić krzesło i bawić się wodą obok ciebie? Tak naprawdę nie chce pomagać, tylko być w samym centrum wydarzeń. Daj mu małą plastikową miseczkę i gąbkę. Kuchnia będzie w opłakanym stanie, ale jego ego urośnie do wielkich rozmiarów.', title_pt = 'A sabotagem do "Deixa-me ajudar-te!" 🧽', body_pt = 'Enquanto lava a loiça, ele quer pôr uma cadeira ao seu lado e brincar com a água? Na verdade não quer ajudar, quer estar mesmo no centro do processo. Dê-lhe uma pequena taça de plástico e uma esponja. A cozinha vai ficar um caos, mas o ego dele vai ficar gigante.', title_sv = 'Sabotaget ”Jag hjälper dig!” 🧽', body_sv = 'Vill barnet absolut ställa en stol bredvid dig och leka med vattnet när du diskar? Egentligen vill barnet inte hjälpa till, utan vara mitt i centrum av det som händer. Ge barnet en liten plastskål och en svamp. Köket blir blött, men barnets ego växer sig enormt.', title_vi = 'Sự cố "Con giúp mẹ nhé!" 🧽', body_vi = 'Khi mẹ rửa bát, bé nhất định kê ghế đứng cạnh để nghịch nước? Thật ra bé không muốn giúp, mà muốn được ở ngay trung tâm của mọi việc. Hãy đưa bé một chiếc bát nhựa nhỏ và miếng bọt biển. Căn bếp sẽ ướt sũng, nhưng cái tôi của bé sẽ lớn bổng lên.', title_zh = '“我来帮你！”的捣乱 🧽', body_zh = '你洗碗时，宝宝非要搬张椅子到旁边玩水？其实宝宝不是想帮忙，而是想成为整件事的正中心。给宝宝一个小塑料碗和一块海绵吧。厨房会被弄得一团糟，但宝宝的自信会变得超级强大。' WHERE id = '7574c80e-2022-481c-9e84-dd04a5dc3520' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La frecuencia mágica de la música 🎶', body_es = 'Prueba a cortar con música clásica suave las tormentas y los gritos sin motivo que estallan al atardecer. Muchas veces este truco sencillo pero eficaz cambia como por arte de magia el ambiente agresivo de la habitación y sumerge al peque en una calma absoluta.', title_fr = 'La fréquence magique de la musique 🎶', body_fr = 'Essayez de calmer les tempêtes et les cris sans raison de fin de journée avec une musique classique douce. Souvent, cette astuce simple mais efficace change comme par magie l''atmosphère agressive de la pièce et plonge l''enfant dans un calme absolu.', title_hi = 'संगीत की जादुई तरंग 🎶', body_hi = 'शाम को बिना वजह उठने वाले तूफ़ानों और चीखों को हल्के शास्त्रीय संगीत से रोककर देखिए। अक्सर यह सीधी-सादी, पर असरदार तरकीब कमरे के गुस्से भरे माहौल को जादू की तरह बदल देती है और बच्चे को गहरे सुकून में डुबो देती है।', title_id = 'Frekuensi ajaib musik 🎶', body_id = 'Coba redakan badai dan teriakan tanpa sebab menjelang malam dengan musik klasik yang lembut. Sering kali trik sederhana tapi ampuh ini secara ajaib mengubah suasana kamar yang tegang dan membenamkan anak dalam ketenangan total.', title_ja = '音楽の魔法の周波数 🎶', body_ja = '夕方のわけのわからない嵐や叫び声を、やさしいクラシック音楽でしずめてみましょう。このシンプルだけど効果的な技は、部屋のとげとげした空気を魔法のように変え、子どもを深い落ち着きで包んでくれることが多いんです。', title_ko = '음악의 마법 주파수 🎶', body_ko = '저녁 무렵 이유 없이 터지는 폭풍과 고함을 잔잔한 클래식 음악으로 가라앉혀 보세요. 이 단순하지만 효과적인 방법이 방 안의 날 선 분위기를 마법처럼 바꾸고 아이를 깊은 평온으로 감싸 줄 때가 많아요.', title_nl = 'De magische frequentie van muziek 🎶', body_nl = 'Probeer onverklaarbare buien en geschreeuw aan het eind van de middag te doorbreken met zachte klassieke muziek. Vaak verandert dit simpele maar effectieve trucje de agressieve sfeer in de kamer op magische wijze en hult het je kind in absolute rust.', title_pl = 'Magiczna częstotliwość muzyki 🎶', body_pl = 'Spróbuj uciszać wieczorne burze i krzyki bez powodu łagodną muzyką klasyczną. Często ten prosty, ale skuteczny trik magicznie zmienia napiętą atmosferę w pokoju i zanurza dziecko w absolutnym spokoju.', title_pt = 'A frequência mágica da música 🎶', body_pt = 'Experimente travar as tempestades sem razão e os gritos do fim da tarde com música clássica suave. Muitas vezes este truque simples mas eficaz muda como por magia o ambiente agressivo do quarto e mergulha a criança numa calma absoluta.', title_sv = 'Musikens magiska frekvens 🎶', body_sv = 'Testa att bryta de omotiverade stormarna och skriken framåt kvällen med lätt klassisk musik. Ofta förändrar det här enkla men effektiva knepet den aggressiva stämningen i rummet på ett magiskt sätt och försänker barnet i ett totalt lugn.', title_vi = 'Tần số kỳ diệu của âm nhạc 🎶', body_vi = 'Hãy thử dùng nhạc cổ điển nhẹ nhàng để dập tắt những cơn bùng nổ và la hét vô cớ lúc chiều tối. Thường thì mẹo đơn giản nhưng hiệu quả này thay đổi bầu không khí căng thẳng trong phòng một cách kỳ diệu và đưa bé vào trạng thái bình yên tuyệt đối.', title_zh = '音乐的神奇频率 🎶', body_zh = '傍晚莫名爆发的小风暴和尖叫，试试用轻柔的古典音乐来化解。这个简单又有效的小妙招，常常能神奇地改变房间里紧张的气氛，让宝宝沉浸在绝对的宁静中。' WHERE id = 'ed6ba029-b0b0-4d21-8825-996dcfdf7f9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ingeniero del armario 👗', body_es = 'Hoy quiere salir con calcetines desparejados y la camiseta del revés. Olvídate de las normas sociales de qué combina. La libertad de tomar sus propias decisiones y defenderlas es una lección de vida mucho más grande que combinar los colores. Dale permiso.', title_fr = 'L''ingénieur de la garde-robe 👗', body_fr = 'Aujourd''hui, il veut sortir avec des chaussettes dépareillées et un t-shirt à l''envers. Laissez tomber les normes d''assortiment. La liberté de prendre sa propre décision et de la défendre est une leçon de vie bien plus grande que des couleurs assorties. Laissez-le faire.', title_hi = 'अलमारी का इंजीनियर 👗', body_hi = 'आज अलग-अलग जोड़ी के मोज़े और उलटी कमीज़ पहनकर बाहर जाना चाहता है। लोगों के मेल-जोल वाले कायदे छोड़िए। अपना फ़ैसला लेने और उस पर टिके रहने की आज़ादी रंगों के मेल से कहीं बड़ा जीवन का सबक है। इजाज़त दीजिए।', title_id = 'Insinyur lemari baju 👗', body_id = 'Hari ini ia ingin keluar dengan kaus kaki yang tidak sepasang dan baju terbalik. Lupakan norma keserasian di masyarakat. Kebebasan membuat keputusan sendiri dan membelanya adalah pelajaran hidup yang jauh lebih besar daripada warna yang serasi. Izinkan saja.', title_ja = 'クローゼットのエンジニア 👗', body_ja = '今日は左右ちがう靴下と、後ろ前のシャツで出かけたいそう。世間の「ふつう」は気にしないで。自分で決めてそれを守る自由は、色の組み合わせよりずっと大きな人生のレッスンです。許してあげましょう。', title_ko = '옷장 엔지니어 👗', body_ko = '오늘은 짝짝이 양말에 뒤집어 입은 셔츠로 나가겠다고 하나요? 어울려야 한다는 기준은 잊으세요. 스스로 정하고 그 결정을 지키는 자유는 색깔 맞추기보다 훨씬 큰 인생 수업이에요. 허락해 주세요.', title_nl = 'Kledingkastingenieur 👗', body_nl = 'Hij wil vandaag naar buiten met twee verschillende sokken en een binnenstebuiten shirt. Vergeet wat er ''hoort''. De vrijheid om zelf te beslissen en die keuze te verdedigen is een veel grotere levensles dan kleuren die bij elkaar passen. Laat hem.', title_pl = 'Inżynier garderoby 👗', body_pl = 'Dziś chce wyjść na dwór w dwóch różnych skarpetkach i koszulce na lewą stronę. Odpuść społeczne normy dopasowania. Wolność podejmowania własnych decyzji i ich obrony to o wiele większa lekcja życia niż pasujące kolory. Pozwól mu.', title_pt = 'Engenheiro do guarda-roupa 👗', body_pt = 'Hoje quer sair com meias trocadas e a camisola ao contrário. Esqueça as normas sociais de combinar. A liberdade de tomar uma decisão e defendê-la é uma lição de vida muito maior do que combinar as cores. Deixe-o.', title_sv = 'Garderobsingenjören 👗', body_sv = 'I dag vill barnet gå ut med omaka strumpor och tröjan ut och in. Strunta i samhällets normer om vad som passar. Friheten att fatta sina egna beslut och försvara dem är en mycket större livsläxa än att färgerna matchar. Ge barnet lov.', title_vi = 'Kỹ sư tủ quần áo 👗', body_vi = 'Hôm nay bé muốn ra ngoài với hai chiếc tất lệch đôi và áo mặc trái. Kệ chuẩn mực "hợp mốt" của xã hội. Quyền tự đưa ra quyết định và bảo vệ nó là bài học cuộc sống lớn hơn nhiều so với việc phối màu. Hãy cho phép bé.', title_zh = '衣柜工程师 👗', body_zh = '今天想穿两只不一样的袜子、把衣服穿反了出门。别管社会上的搭配规范了。自己做决定并捍卫它的自由，是比颜色搭不搭重要得多的人生一课。就随宝宝吧。' WHERE id = 'df056dc0-b341-46d5-89e8-51170248ba0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y calma 🤖', body_es = '¿Te preocupan los cambios bruscos de humor de tu peque cerca de los 3 años y medio? Cierra los foros de internet que dan miedo y traumatizan. Obtén de Anacan AI una respuesta tranquilizadora y fundamentada científica y psicológicamente sobre las crisis de esta edad.', title_fr = 'Intelligence artificielle et sérénité 🤖', body_fr = 'Les changements d''humeur brusques de votre enfant à l''approche des 3 ans et demi vous inquiètent ? Fermez les forums effrayants et traumatisants d''Internet. Obtenez d''Anacan AI une réponse apaisante, fondée sur la science et la psychologie, sur les crises de cet âge.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और सुकून 🤖', body_hi = 'साढ़े 3 साल के करीब बच्चे के तेज़ी से बदलते मूड ने आपको परेशान कर दिया? इंटरनेट के डरावने और परेशान करने वाले फ़ोरम बंद कीजिए। Anacan AI से इस उम्र के नखरों के बारे में वैज्ञानिक और मनोवैज्ञानिक आधार वाला, सुकून देने वाला जवाब पाइए।', title_id = 'Kecerdasan buatan dan ketenangan 🤖', body_id = 'Perubahan emosinya yang tajam menjelang usia 3,5 tahun membuat Anda cemas? Tutup forum-forum internet yang menakutkan dan traumatis. Dapatkan jawaban yang menenangkan dan berdasar secara ilmiah dan psikologis tentang krisis usia ini dari Anacan AI.', title_ja = 'AIと安心 🤖', body_ja = '3歳半が近づき、子どもの気分の激しい変わりように不安になりましたか？ネットの怖くてショッキングな掲示板は閉じましょう。Anacan AIに、この年ごろのかんしゃくについて科学的・心理学的な根拠のある、安心できる答えをもらいましょう。', title_ko = '인공지능과 평온 🤖', body_ko = '세 살 반 무렵 아이의 급격한 감정 변화에 불안해졌나요? 무섭고 충격적인 인터넷 게시판은 닫으세요. Anacan AI에게 이 시기의 위기에 대해 과학적, 심리학적 근거가 있는 안심되는 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en rust 🤖', body_nl = 'Maken de heftige stemmingswisselingen van je kind rond 3,5 jaar je ongerust? Sluit die enge, traumatiserende fora op internet. Krijg van Anacan AI een wetenschappelijk en psychologisch onderbouwd, geruststellend antwoord over deze leeftijdscrisissen.', title_pl = 'Sztuczna inteligencja i spokój 🤖', body_pl = 'Gwałtowne zmiany nastroju dziecka w okolicach 3,5 roku cię zaniepokoiły? Zamknij straszne, traumatyzujące fora w internecie. Uzyskaj od Anacan AI naukowo i psychologicznie uzasadnioną, uspokajającą odpowiedź na temat kryzysów tego wieku.', title_pt = 'Inteligência artificial e serenidade 🤖', body_pt = 'As mudanças bruscas de humor da criança perto dos 3 anos e meio deixaram-na aflita? Feche os fóruns assustadores e traumatizantes da internet. Obtenha do Anacan AI uma resposta tranquilizadora, com base científica e psicológica, sobre as crises desta idade.', title_sv = 'Artificiell intelligens och lugn 🤖', body_sv = 'Blev du orolig över barnets kraftiga humörsvängningar närmare 3,5 år? Stäng de skrämmande och traumatiska forumen på nätet. Få ett vetenskapligt och psykologiskt underbyggt, lugnande svar om den här ålderns kriser från Anacan AI.', title_vi = 'Trí tuệ nhân tạo và sự bình yên 🤖', body_vi = 'Những thay đổi cảm xúc đột ngột của bé khi gần 3 tuổi rưỡi khiến mẹ lo lắng? Hãy đóng những diễn đàn đáng sợ, gây hoang mang trên mạng. Hãy hỏi Anacan AI để nhận câu trả lời có cơ sở khoa học và tâm lý, giúp mẹ yên tâm về những khủng hoảng của độ tuổi này.', title_zh = '人工智能与平静 🤖', body_zh = '快3岁半时，孩子剧烈的情绪变化让你很慌？关掉网上那些吓人、让人焦虑的论坛。问问Anacan AI这个年龄的崩溃，得到有科学和心理学依据、让人安心的回答。' WHERE id = 'ed70e165-6613-45b8-9098-e5a1501e357a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los dos estáis hartos de los libros de siempre y en la habitación hay un ambiente aburrido. Abre Cuentos inteligentes y esta noche deja que él dirija la historia. Pregúntale: «¿Y ahora adónde va ese coche volador?», y deja que se duerma conquistando su imaginación.', body_fr = 'Vous en avez assez tous les deux des livres classiques, et l''ambiance de la chambre est monotone. Ouvrez les Contes intelligents et, ce soir, laissez-le diriger l''histoire. Demandez : « Où va aller la voiture volante maintenant ? » et laissez-le s''endormir en conquérant le monde dans son imagination.', body_hi = 'आप दोनों पुरानी किताबों से ऊब चुके हैं और कमरे का माहौल उबाऊ है। स्मार्ट कहानियाँ खोलिए और आज शाम कहानी की दिशा उसे तय करने दीजिए। पूछिए, ‘अब वह उड़ने वाली गाड़ी कहाँ जाए?’ और उसे अपनी कल्पना में दुनिया जीतते हुए सोने दीजिए।', body_id = 'Kalian berdua sudah bosan dengan buku klasik dan suasana kamar terasa membosankan. Buka Dongeng Pintar dan malam ini biarkan ia yang mengarahkan alur cerita. Tanyakan ''Sekarang mobil terbang itu pergi ke mana?'', dan biarkan ia tertidur sambil menaklukkan dunia khayalnya.', body_ja = '定番の絵本にはふたりとも飽きて、部屋はなんだかたいくつな雰囲気。「スマートおはなし」を開いて、今夜はストーリーの行き先をこの子にまかせましょう。「この空飛ぶ車、次はどこへ行く？」とたずねて、空想の中で冒険しながら眠りにつかせてあげて。', body_ko = '늘 읽던 책이 둘 다 지겨워지고 방 안 분위기도 따분한가요? 스마트 동화를 열고 오늘 저녁엔 이야기의 방향을 아이에게 맡겨 보세요. ''이제 날아다니는 자동차는 어디로 갈까?'' 묻고, 상상 속 세상을 정복하며 잠들게 해 주세요.', body_nl = 'Jullie zijn allebei de klassieke boeken beu en er hangt een saaie sfeer in de kamer. Open Slimme sprookjes en laat hem vanavond het verhaal sturen. Vraag: ''Waar moet die vliegende auto nu naartoe?'' en laat hem in slaap vallen terwijl hij in zijn fantasie de wereld verovert.', body_pl = 'Klasyczne książeczki znudziły się wam obojgu, a w pokoju panuje nudna atmosfera. Otwórz Mądre bajki i pozwól mu dziś wieczorem kierować fabułą. Zapytaj: „Dokąd teraz ma lecieć to latające auto?” i niech zaśnie, podbijając świat w wyobraźni.', body_pt = 'Estão os dois fartos dos livros clássicos e há um ambiente aborrecido no quarto. Abra as Histórias Inteligentes e deixe que esta noite seja ele a guiar o enredo. Pergunte "E agora, para onde vai aquele carro voador?" e deixe-o adormecer a conquistar mundos na imaginação.', body_sv = 'Ni är båda trötta på de klassiska böckerna och stämningen i rummet är tråkig. Öppna Smarta sagor och låt barnet styra handlingen i kväll. Fråga ”Vart ska den flygande bilen åka nu?” och låt barnet somna medan det erövrar sin drömvärld.', body_vi = 'Cả hai mẹ con đều đã chán những cuốn sách quen thuộc và không khí trong phòng thật tẻ nhạt. Hãy mở Truyện cổ tích thông minh và tối nay để bé dẫn dắt cốt truyện. Hỏi bé: "Giờ chiếc ô tô bay nên đi đâu nhỉ?", rồi để bé chìm vào giấc ngủ trong khi chinh phục thế giới tưởng tượng.', body_zh = '经典故事书你们俩都看腻了，房间里的气氛也有点沉闷。打开智慧童话，今晚让宝宝来决定故事走向。问问：“现在那辆会飞的车该去哪儿？”就让宝宝在想象中征服一切后入睡吧。' WHERE id = 'fd525f60-163f-4a76-b89b-734831b1ea09' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hipnosis del susurro 🤫', body_es = 'Tumbado en la cama levanta los pies al aire y no quiere dormirse de ninguna manera. En lugar de gritar, baja de golpe el tono y háblale solo en susurros. Cuando el niño se concentra para oírte, su cerebro se hipnotiza automáticamente y pasa al modo sueño.', title_fr = 'L''hypnose du chuchotement 🤫', body_fr = 'Allongé dans son lit, il lève les jambes en l''air et refuse catégoriquement de dormir. Au lieu de crier, baissez soudain le ton et ne lui parlez plus qu''en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau entre automatiquement dans une sorte d''hypnose et passe en mode sommeil.', title_hi = 'फुसफुसाहट का सम्मोहन 🤫', body_hi = 'बिस्तर में लेटकर पैर हवा में उठाता है, सोना बिल्कुल नहीं चाहता। चिल्लाने के बजाय अचानक आवाज़ धीमी कीजिए, उससे सिर्फ़ फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए पूरा ध्यान लगाता है, तो उसका दिमाग अपने-आप सम्मोहित होकर नींद के मोड में चला जाएगा।', title_id = 'Hipnosis bisikan 🤫', body_id = 'Ia berbaring di tempat tidur sambil mengangkat kaki ke udara dan sama sekali tidak mau tidur. Daripada berteriak, turunkan nada suara Anda tiba-tiba dan bicaralah dengannya hanya sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis terhipnosis dan beralih ke mode tidur.', title_ja = 'ささやきの催眠術 🤫', body_ja = 'ベッドに寝ころんで足を宙にあげ、まったく眠ろうとしない。どなる代わりに急に声のトーンを落として、ささやき声だけで話しかけてみましょう。あなたの声を聞こうと集中すると、脳は自然と催眠にかかったように眠りモードへ切りかわります。', title_ko = '속삭임의 최면 🤫', body_ko = '침대에 누워 다리를 허공에 들고 절대 잠들기 싫어하나요? 소리치는 대신 갑자기 톤을 낮춰 속삭이듯만 말하세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 최면에 걸린 듯 수면 모드로 바뀔 거예요.', title_nl = 'De hypnose van het fluisteren 🤫', body_nl = 'Hij ligt in bed met zijn benen in de lucht en wil absoluut niet slapen. Ga niet schreeuwen, maar ga ineens zachter praten en spreek alleen nog fluisterend tegen hem. Als hij zijn best doet om je te verstaan, raakt zijn brein vanzelf in een soort hypnose en schakelt het over naar de slaapstand.', title_pl = 'Hipnoza szeptu 🤫', body_pl = 'Leży w łóżku z nogami w górze i za nic nie chce zasnąć. Zamiast krzyczeć, nagle ścisz głos i mów do niego wyłącznie szeptem. Gdy dziecko zamieni się w słuch, żeby cię usłyszeć, jego mózg automatycznie wpadnie w hipnozę i przejdzie w tryb snu.', title_pt = 'A hipnose do sussurro 🤫', body_pt = 'Deitado na cama, levanta as pernas no ar e não quer mesmo nada adormecer. Em vez de gritar, baixe de repente o tom de voz e fale com ele só a sussurrar. Quando a criança se concentra para a ouvir, o cérebro fica automaticamente hipnotizado e passa para o modo de sono.', title_sv = 'Viskningens hypnos 🤫', body_sv = 'Barnet ligger i sängen med benen i luften och vill absolut inte somna. Istället för att skrika, sänk plötsligt rösten och prata bara viskande. När barnet lyssnar spänt för att höra dig blir hjärnan automatiskt hypnotiserad och går över i sömnläge.', title_vi = 'Lời thì thầm thôi miên 🤫', body_vi = 'Bé nằm trên giường, giơ chân lên trời và nhất quyết không chịu ngủ. Thay vì quát, hãy bất ngờ hạ giọng và chỉ thì thầm với bé. Khi bé chú ý để nghe mẹ, não bé sẽ tự động như bị thôi miên và chuyển sang chế độ ngủ.', title_zh = '悄悄话的催眠术 🤫', body_zh = '躺在床上把腿翘到半空，怎么都不想睡。别吼，突然压低声音，只用悄悄话和宝宝说话。宝宝聚精会神想听清你时，大脑会自动被“催眠”，切换到睡眠模式。' WHERE id = '4cc9dfab-73bb-408b-8fd7-0cdb3ba02840' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento offline para mamá 🛋️', body_es = '¿Mientras ve los dibujos o está metido en sus juguetes, corres a vaciar el lavavajillas o a tender la ropa? ¡Para! Dedica esos 10 minutos solo a tumbarte en el sofá, mirar al techo y no pensar en nada. No eres un robot.', title_fr = 'Un moment hors ligne pour maman 🛋️', body_fr = 'Pendant qu''il regarde un dessin animé ou qu''il est plongé dans ses jouets, vous courez vider le lave-vaisselle ou étendre le linge ? Stop ! Passez ces 10 minutes allongée sur le canapé à regarder le plafond, sans penser à rien. Vous n''êtes pas un robot.', title_hi = 'माँ के लिए ऑफ़लाइन पल 🛋️', body_hi = 'जब वह कार्टून देख रहा है या खिलौनों में खोया है, आप डिशवॉशर खाली करने या कपड़े सुखाने दौड़ती हैं? रुकिए! वे 10 मिनट बस सोफ़े पर लेटकर छत निहारने और कुछ न सोचने में बिताइए। आप रोबोट नहीं हैं।', title_id = 'Momen offline untuk Ibu 🛋️', body_id = 'Saat ia asyik menonton kartun atau bermain, kamu buru-buru mengosongkan mesin cuci piring atau menjemur baju? Berhenti! Habiskan 10 menit itu hanya untuk berbaring di sofa, memandangi langit-langit, dan tidak memikirkan apa pun. Kamu bukan robot.', title_ja = 'ママのオフラインタイム 🛋️', body_ja = 'アニメを見ていたり、おもちゃに夢中になっていたりするすきに、食洗機を空にしたり洗濯物を干したりしに走っていませんか？ストップ！その10分はソファに横になって天井を眺め、何も考えないことに使いましょう。あなたはロボットではありません。', title_ko = '엄마를 위한 오프라인 시간 🛋️', body_ko = '아이가 만화나 장난감에 빠져 있을 때 식기세척기를 비우거나 빨래를 널러 달려가나요? 멈추세요! 그 10분은 소파에 누워 천장을 바라보며 아무 생각 없이 보내세요. 엄마는 로봇이 아니에요.', title_nl = 'Offline moment voor mama 🛋️', body_nl = 'Ren jij, als hij naar een tekenfilm kijkt of opgaat in zijn speelgoed, naar de vaatwasser of de was? Stop! Besteed die 10 minuten alleen aan op de bank liggen, naar het plafond staren en nergens aan denken. Je bent geen robot.', title_pl = 'Chwila offline dla mamy 🛋️', body_pl = 'Gdy ogląda bajkę albo jest pochłonięty zabawkami, ty biegniesz rozładować zmywarkę albo rozwiesić pranie? Stop! Przeznacz te 10 minut tylko na leżenie na kanapie, patrzenie w sufit i niemyślenie o niczym. Nie jesteś robotem.', title_pt = 'Um momento offline para a mãe 🛋️', body_pt = 'Enquanto ele vê desenhos animados ou está mergulhado nos brinquedos, corre a esvaziar a máquina da loiça ou a estender a roupa? Pare! Use esses 10 minutos só para se deitar no sofá a olhar para o teto, sem pensar em nada. Não é um robô.', title_sv = 'En offline-stund för mamma 🛋️', body_sv = 'Springer du iväg och tömmer diskmaskinen eller hänger tvätt medan barnet tittar på tecknat eller är uppslukat av leksakerna? Stopp! Använd de 10 minuterna bara till att ligga i soffan, titta i taket och inte tänka på något. Du är ingen robot.', title_vi = 'Khoảnh khắc "offline" của mẹ 🛋️', body_vi = 'Khi bé đang xem hoạt hình hay mải chơi đồ chơi, mẹ lại vội chạy đi dỡ máy rửa bát hay phơi đồ? Dừng lại! Hãy dành 10 phút đó chỉ để nằm trên sofa, ngắm trần nhà và không nghĩ gì cả. Mẹ không phải là robot.', title_zh = '妈妈的离线时刻 🛋️', body_zh = '宝宝看动画片或玩玩具玩得入迷时，你就跑去清空洗碗机或晾衣服？停！把这10分钟只用来躺在沙发上望着天花板，什么都不想。你不是机器人。' WHERE id = '815c8c47-103f-4098-9702-cdb4705b486d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Completa las frases a medias 🗣️', body_es = 'Cuando olvida una palabra hace gestos con las manos, frunce el ceño y espera que la adivines. Su vocabulario crece, solo que su cerebro va más rápido que su lengua. Cuando completes su frase con paciencia, fíjate en ese alivio de «¡sí, eso es lo que decía!» en su cara.', title_fr = 'Finir ses phrases 🗣️', body_fr = 'Quand il oublie un mot, il fait des gestes, fronce les sourcils et attend que vous trouviez. Son vocabulaire grandit, c''est juste que son cerveau va plus vite que sa langue. Quand vous finissez patiemment sa phrase, observez ce soulagement sur son visage : « Oui, c''est exactement ça ! »', title_hi = 'अधूरे वाक्य पूरे कीजिए 🗣️', body_hi = 'कोई शब्द भूल जाने पर हाथ से इशारे करके, भौंहें चढ़ाकर आपके समझने का इंतज़ार करता है। उसकी शब्दावली बढ़ रही है, बस उसका दिमाग ज़ुबान से तेज़ चलता है। जब आप धैर्य से उसका वाक्य पूरा करती हैं, तो उसके चेहरे पर आई ‘हाँ, यही कह रहा था’ वाली राहत देखिए।', title_id = 'Lengkapi kalimatku 🗣️', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan, mengerutkan alis, dan menunggu Anda menebak. Kosakatanya bertambah, hanya saja otaknya bekerja lebih cepat daripada lidahnya. Saat Anda dengan sabar melengkapi kalimatnya, perhatikan rasa lega di wajahnya: ''Iya, itu maksudku!''.', title_ja = '途中の言葉を当ててあげよう 🗣️', body_ja = '言葉を忘れると、手でジェスチャーをして眉をしかめ、あなたが当てるのを待っています。語彙は増えています。ただ、頭の回転が口より速いだけ。根気よく文を完成させてあげたときの、「そう、それが言いたかったの」というほっとした顔を見てあげて。', title_ko = '끝맺지 못한 문장 채워 주기 🗣️', body_ko = '단어가 생각 안 나면 손짓하고 눈살을 찌푸리며 엄마가 맞혀 주길 기다리나요? 어휘는 늘고 있어요, 그저 뇌가 혀보다 빠를 뿐이에요. 문장을 인내심 있게 완성해 줄 때 아이 얼굴에 떠오르는 ''맞아, 그거야!'' 하는 안도감을 지켜보세요.', title_nl = 'Maak de zin af 🗣️', body_nl = 'Vergeet hij een woord, dan maakt hij gebaren, fronst hij en wacht hij tot jij het raadt. Zijn woordenschat groeit, zijn brein werkt alleen sneller dan zijn tong. Kijk naar die opluchting op zijn gezicht als jij geduldig zijn zin afmaakt: ''Ja, dát bedoelde ik!''', title_pl = 'Dokończ moje zdanie 🗣️', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami, marszczy brwi i czeka, aż zgadniesz. Słownictwo mu rośnie, po prostu mózg pracuje szybciej niż język. Gdy cierpliwie dokończysz jego zdanie, zobacz tę ulgę na jego twarzy: „Aaa, właśnie o to mi chodziło”.', title_pt = 'Completar frases a meio 🗣️', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos, franze a testa e espera que a adivinhe. O vocabulário está a crescer, o cérebro só trabalha mais depressa do que a língua. Quando completa a frase com paciência, repare no alívio na cara dele: "Ah, é isso mesmo que eu queria dizer".', title_sv = 'Fyll i de halva meningarna 🗣️', body_sv = 'När barnet glömmer ett ord gör det tecken med händerna, rynkar pannan och väntar på att du ska gissa. Ordförrådet växer, hjärnan arbetar bara snabbare än tungan. När du tålmodigt fyller i meningen, lägg märke till lättnaden i barnets ansikte: ”Jaa, det var precis det jag menade.”', title_vi = 'Hoàn thành câu nói dở 🗣️', body_vi = 'Khi quên một từ, bé ra hiệu bằng tay, nhíu mày và chờ mẹ đoán. Vốn từ của bé đang lớn dần, chỉ là não bé chạy nhanh hơn lưỡi thôi. Hãy để ý vẻ nhẹ nhõm "À, đúng cái đó đấy" trên gương mặt bé khi mẹ kiên nhẫn nói nốt câu giúp bé.', title_zh = '帮宝宝补完半句话 🗣️', body_zh = '忘了某个词时，就用手比画、皱着眉，等你猜出来。词汇量在增长，只是大脑转得比嘴巴还快。当你耐心地帮宝宝把句子补完时，看看宝宝脸上那种“对，我就是想说这个”的如释重负吧。' WHERE id = 'ac5c326d-30b1-4f87-8420-9236c8047849' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diseñador de comida 🥦', body_es = 'Separa la comida del plato por colores y formas y empuja lo verde a un lado. Entra en Recetas saludables. Descubre cómo convertir esas verduras en un puré invisible y esconderlas en salsas ricas, y gana este juego a escondidas.', title_fr = 'Le designer culinaire 🥦', body_fr = 'Il trie les aliments de son assiette par couleur et par forme, et pousse les verts sur le côté. Ouvrez les Recettes saines. Gagnez discrètement cette partie en découvrant comment transformer ces légumes en purée invisible à cacher dans de délicieuses sauces.', title_hi = 'खाने का डिज़ाइनर 🥦', body_hi = 'प्लेट का खाना रंग और आकार के हिसाब से अलग करता है, और हरी चीज़ें एक तरफ़ सरका देता है। सेहतमंद रेसिपी खोलिए। जानिए कि उन सब्ज़ियों की अदृश्य प्यूरी बनाकर स्वादिष्ट सॉस में कैसे छिपाएँ, और इस खेल में चुपके से जीत जाइए।', title_id = 'Desainer makanan 🥦', body_id = 'Ia memisahkan makanan di piring berdasarkan warna dan bentuknya, lalu mendorong yang hijau ke pinggir. Buka Resep Sehat. Menangkan permainan ini diam-diam dengan menemukan cara menghaluskan sayur hingga tak terlihat dan menyembunyikannya dalam saus yang lezat.', title_ja = '食べ物デザイナー 🥦', body_ja = 'お皿の料理を色や形で分けて、緑のものは脇に押しやっている。「ヘルシーレシピ」を開いてみましょう。野菜を見えないピューレにして、おいしいソースに隠す方法を見つけて、このゲームにこっそり勝ちましょう。', title_ko = '음식 디자이너 🥦', body_ko = '접시 위 음식을 색깔과 모양별로 나누고 초록색은 옆으로 밀어내나요? 건강한 레시피에 들어가 보세요. 채소를 감쪽같은 퓌레로 만들어 맛있는 소스에 숨기는 법을 찾아 이 게임에서 몰래 이기세요.', title_nl = 'Voedselontwerper 🥦', body_nl = 'Hij sorteert het eten op zijn bord op kleur en vorm en schuift alles wat groen is aan de kant. Open Gezonde recepten. Win dit spel stiekem door te ontdekken hoe je die groenten onzichtbaar pureert en in lekkere sausjes verstopt.', title_pl = 'Projektant jedzenia 🥦', body_pl = 'Rozdziela jedzenie na talerzu według kolorów i kształtów, a zielone odsuwa na bok. Zajrzyj do Zdrowych przepisów. Odkryj, jak zamienić te warzywa w niewidzialne purée i ukryć je w pysznych sosach, i po cichu wygraj tę grę.', title_pt = 'Designer de comida 🥦', body_pt = 'Separa a comida do prato por cores e formas e empurra o que é verde para o lado. Entre nas Receitas Saudáveis. Descubra como transformar esses legumes num puré invisível e escondê-los em molhos saborosos, e ganhe este jogo às escondidas.', title_sv = 'Matdesignern 🥦', body_sv = 'Barnet sorterar maten på tallriken efter färg och form och skjuter de gröna bitarna åt sidan. Gå in i Hälsosamma recept. Vinn leken i smyg genom att upptäcka hur du gör grönsakerna till osynligt mos och gömmer dem i goda såser.', title_vi = 'Nhà thiết kế món ăn 🥦', body_vi = 'Bé phân loại thức ăn trên đĩa theo màu sắc và hình dạng, còn những thứ màu xanh thì đẩy ra một bên. Hãy vào Công thức lành mạnh. Khám phá cách xay rau thành dạng nhuyễn "vô hình" để giấu vào những món sốt ngon lành và âm thầm chiến thắng trò chơi này.', title_zh = '食物设计师 🥦', body_zh = '把盘子里的食物按颜色和形状分开，绿色的全推到一边。去健康食谱里看看，学会把那些蔬菜做成看不见的泥，藏进美味的酱汁里，悄悄赢下这场游戏吧。' WHERE id = '7eaa01a6-6e1b-4778-9360-22935e0a6bcc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar toda su energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo sube a caballito y galopa, las carcajadas llenan la habitación y todo el estrés físico acumulado, esa energía sin fin, desaparece en segundos con el sudor.', body_fr = 'Il n''a pas pu se dépenser complètement et refuse d''aller au lit. Appelez papa en renfort. Quand il le prend sur son dos pour jouer au cheval, les éclats de rire remplissent la pièce, et toute la tension physique accumulée, cette énergie sans fin, s''évacue en quelques secondes.', body_hi = 'पूरी ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक तनाव, वह अंतहीन ऊर्जा पसीने के साथ सेकंडों में गायब हो जाती है।', body_id = 'Ia belum sempat menyalurkan seluruh energinya dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar, dan semua stres fisik serta energi yang tak habis-habis itu lenyap dalam hitungan detik bersama keringat.', body_ja = 'エネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを背中にのせてお馬さんになれば、部屋は笑い声でいっぱいになり、たまっていた体のストレスも尽きないエネルギーも、汗と一緒にあっという間に消えていきます。', body_ko = '에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음소리가 방을 채우고, 쌓인 몸의 스트레스와 끝없는 에너지가 땀과 함께 몇 초 만에 사라져요.', body_nl = 'Hij is zijn energie niet helemaal kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem op zijn rug neemt en paardje speelt, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke stress en die eindeloze energie zwetend in een paar seconden.', body_pl = 'Nie wyładował do końca energii i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy weźmie go na barana i pogalopuje jak koń, śmiech wypełni pokój, a całe nagromadzone napięcie i ta niewyczerpana energia znikną w kilka sekund.', body_pt = 'Não conseguiu gastar toda a energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele põe a criança às costas e faz de cavalo a galopar, as gargalhadas enchem o quarto e todo o stress físico acumulado, aquela energia sem fim, desaparece em segundos, a suar.', body_sv = 'Barnet har inte fått ur sig all energi och vägrar gå och lägga sig. Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och all ansamlad fysisk stress och den ändlösa energin försvinner på några sekunder i form av svett.', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố cõng bé chơi trò cưỡi ngựa, tiếng cười ngập tràn căn phòng, mọi căng thẳng thể chất và nguồn năng lượng bất tận ấy sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', body_zh = '精力还没释放完，就是不肯上床。叫爸爸来帮忙吧。爸爸把宝宝驮在背上“骑大马”时，笑声充满房间，积攒的所有身体压力和用不完的精力，几秒钟内就随着汗水消失了。' WHERE id = '91e22232-e032-41dd-a3bf-200483eec697' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te repite riéndose esa palabrota que ha oído en la calle o en la tele y espera tu reacción con mucha curiosidad. Tu mejor arma es no reaccionar. No te rías ni te enfades, simplemente ignóralo. Pronto olvidará esa palabra.', body_fr = 'Il vous répète en riant un gros mot entendu dans la rue ou à la télé et attend votre réaction avec une grande curiosité. Votre meilleure arme, c''est l''absence de réaction. Ne riez pas, ne vous fâchez pas, ignorez simplement. Il oubliera vite ce mot.', body_hi = 'सड़क या टीवी से सुना वह बुरा शब्द हँसते हुए आपके सामने दोहराता है और बड़ी उत्सुकता से आपकी प्रतिक्रिया का इंतज़ार करता है। आपका सबसे बड़ा हथियार है कोई प्रतिक्रिया न देना। हँसिए मत, नाराज़ मत होइए, बस अनदेखा कीजिए। वह जल्द ही वह शब्द भूल जाएगा।', body_id = 'Ia mengulang kata kasar yang ia dengar di jalan atau di TV sambil tertawa, lalu menunggu reaksi Anda dengan penasaran. Senjata terbesar Anda adalah tidak bereaksi. Jangan tertawa, jangan marah, cukup abaikan. Ia akan segera melupakan kata itu.', body_ja = '外やテレビで聞いた悪い言葉を、笑いながらくり返して、興味しんしんであなたの反応を待っている？いちばんの武器は、反応しないこと。笑わず、怒らず、ただ聞き流しましょう。その言葉はすぐに忘れます。', body_ko = '길이나 TV에서 들은 나쁜 말을 웃으며 따라 하고 잔뜩 기대하며 엄마의 반응을 기다리나요? 가장 강력한 무기는 무반응이에요. 웃지도, 화내지도 말고 그냥 못 들은 척하세요. 곧 그 말을 잊을 거예요.', body_nl = 'Herhaalt hij lachend een lelijk woord dat hij op straat of op tv hoorde, en wacht hij heel benieuwd op je reactie? Je grootste wapen is geen reactie. Lach niet, word niet boos, negeer het gewoon. Hij vergeet het woord snel.', body_pl = 'Ze śmiechem powtarza ci brzydkie słowo, które usłyszał na ulicy albo w telewizji, i z wielką ciekawością czeka na twoją reakcję. Twoją największą bronią jest brak reakcji. Nie śmiej się, nie złość, po prostu udawaj, że nie słyszysz. Szybko zapomni to słowo.', body_pt = 'Repete-lhe a rir aquela palavra feia que ouviu na rua ou na televisão e espera com grande curiosidade pela sua reação. A sua maior arma é não reagir. Não se ria, não se irrite, simplesmente ignore. Em breve vai esquecer a palavra.', body_sv = 'Upprepar barnet skrattande ett fult ord det hört på gatan eller på tv och väntar med stor nyfikenhet på din reaktion? Ditt största vapen är att inte reagera. Skratta inte, bli inte arg, låtsas bara inte höra. Barnet glömmer snart ordet.', body_vi = 'Bé cười và nhắc lại với mẹ một từ xấu nghe được ngoài đường hay trên tivi, rồi háo hức chờ xem mẹ phản ứng ra sao. Vũ khí lớn nhất của mẹ là không phản ứng. Đừng cười, đừng bực, chỉ cần lờ đi. Bé sẽ sớm quên từ đó thôi.', body_zh = '笑着跟你重复从街上或电视里听来的脏话，满怀好奇地等着看你的反应。你最强大的武器就是不反应。别笑，别生气，假装没听见就好。宝宝很快就会忘掉那个词。' WHERE id = 'f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un océano en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de hacer olas. Deja que el agua salpique y que se moje el baño. Ese efecto imán del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'L''océan dans la baignoire 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu de vagues. Laissez l''eau éclabousser, tant pis si la salle de bain est mouillée. L''effet magnétique de l''eau emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'बाथटब में समुद्र 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, लहरें बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए, बाथरूम भीगने दीजिए। पानी का वह चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Samudra di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat ombak. Biarkan air memercik ke mana-mana dan kamar mandi basah. Efek magnet air akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = 'お風呂の中の海 🌊', body_ja = 'お風呂はもうきれいにするためではなく、波をつくる遊びです。水しぶきが飛んで、バスルームがびしょびしょになってもいいんです。お湯の磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '욕조 속 바다 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 파도 만들기 놀이예요. 물이 사방으로 튀고 욕실이 젖어도 괜찮아요. 물의 자석 같은 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'De oceaan in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met golven maken. Laat het water maar spetteren, ook al wordt de badkamer nat. Het magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Ocean w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w robienie fal. Niech woda chlapie dookoła, niech łazienka będzie mokra. Magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia i spłynie z nim do kanalizacji.', title_pt = 'O oceano na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer ondas. Deixe a água salpicar à volta e a casa de banho ficar molhada. O efeito magnético da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Havet i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att göra vågor. Låt vattnet stänka och badrummet bli blött. Vattnets magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Đại dương trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo sóng. Cứ để nước bắn tung tóe, phòng tắm ướt một chút cũng được. Sức hút kỳ diệu của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '浴缸里的海洋 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起浪花的游戏。让水花四溅吧，浴室湿了也没关系。水那种磁力般的效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = '07324b19-8c8c-4d15-8c79-0b07b4d8c8cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Secretos tras la puerta 🚪', body_es = '¿Quiere entrar en su habitación, cerrar la puerta y quedarse solo? Está naciendo el concepto de espacio personal y de individualidad. Toma las medidas de seguridad y reconócele este pequeño derecho a la intimidad. Está creciendo.', title_fr = 'Les secrets derrière la porte 🚪', body_fr = 'Il veut entrer dans sa chambre, fermer la porte derrière lui et rester seul ? La notion d''espace personnel et d''individualité apparaît. Prenez les mesures de sécurité nécessaires et reconnaissez-lui ce petit droit à l''intimité. Il grandit.', title_hi = 'बंद दरवाज़े के पीछे के राज़ 🚪', body_hi = 'अपने कमरे में जाकर दरवाज़ा बंद करके अकेला रहना चाहता है? निजी जगह की समझ और अपनी पहचान बन रही है। सुरक्षा के इंतज़ाम कर लीजिए और उसके इस छोटे से निजता के हक को मानिए। वह बड़ा हो रहा है।', title_id = 'Rahasia di balik pintu 🚪', body_id = 'Ia ingin masuk kamarnya, menutup pintu, dan menyendiri? Konsep ruang pribadi dan individualitasnya sedang terbentuk. Pastikan keamanannya, lalu akui haknya atas privasi kecil ini. Ia sedang tumbuh.', title_ja = 'ドアの向こうの秘密 🚪', body_ja = '自分の部屋に入ってドアを閉め、ひとりになりたがる？プライベートな空間や「自分」という感覚が芽生えています。安全対策をしたうえで、この小さなプライバシーの権利を認めてあげましょう。成長している証です。', title_ko = '문 뒤의 비밀 🚪', body_ko = '자기 방에 들어가 문을 닫고 혼자 있고 싶어 하나요? 개인 공간과 개성에 대한 개념이 생기고 있어요. 안전은 챙기되 이 작은 사생활의 권리를 인정해 주세요. 아이가 자라고 있어요.', title_nl = 'Geheimen achter de deur 🚪', body_nl = 'Wil hij naar zijn kamer, de deur achter zich dichtdoen en alleen zijn? Het besef van een eigen ruimte en individualiteit ontstaat. Zorg dat het veilig is en gun hem dit kleine recht op privacy. Hij wordt groot.', title_pl = 'Tajemnice za drzwiami 🚪', body_pl = 'Chce wejść do swojego pokoju, zamknąć za sobą drzwi i pobyć sam? Rodzi się poczucie przestrzeni osobistej i indywidualności. Zadbaj o bezpieczeństwo i przyznaj mu to małe prawo do prywatności. On rośnie.', title_pt = 'Segredos atrás da porta 🚪', body_pt = 'Quer entrar no quarto, fechar a porta e ficar sozinho? Está a nascer a noção de espaço pessoal e de individualidade. Tome as medidas de segurança e reconheça-lhe este pequeno direito à privacidade. Ele está a crescer.', title_sv = 'Hemligheter bakom dörren 🚪', body_sv = 'Vill barnet gå in i sitt rum, stänga dörren och vara ensamt? Begreppet personligt utrymme och individualitet håller på att formas. Vidta säkerhetsåtgärder och ge barnet rätten till den här lilla integriteten. Barnet växer.', title_vi = 'Bí mật sau cánh cửa 🚪', body_vi = 'Bé muốn vào phòng, đóng cửa lại và ở một mình? Khái niệm không gian riêng và cá tính đang hình thành. Hãy đảm bảo an toàn và tôn trọng quyền riêng tư nho nhỏ này của bé. Bé đang lớn lên.', title_zh = '门后的秘密 🚪', body_zh = '想进自己的房间把门关上，一个人待着？私人空间的概念和个性正在形成。做好安全措施，承认宝宝这一点小小的隐私权吧。宝宝在长大。' WHERE id = '501e8f67-b2b7-4164-9b32-0326fabd781c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Coge el móvil. En lugar de deslizar la vida perfecta de otros en redes sociales, abre el Diario de ánimo y anota para el futuro el momento más gracioso que ha tenido hoy, el que más te hizo reír. Escribir ahí es la terapia más pura.', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie parfaite des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée, celui qui vous a le plus fait rire. Écrire, c''est la thérapie la plus pure.', body_hi = 'फ़ोन उठाइए। सोशल मीडिया पर दूसरों की परफ़ेक्ट ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसने जो सबसे मज़ेदार, आपको सबसे ज़्यादा हँसाने वाला काम किया, उसे भविष्य के लिए लिख लीजिए। वहाँ लिखना सबसे सच्ची थेरेपी है।', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan sempurna orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini, yang paling membuat Anda tertawa, untuk masa depan. Menulis di sana adalah terapi paling murni.', body_ja = 'スマホを手に取って。SNSでほかの人の完璧な暮らしをスクロールする代わりに、「気分日記」を開いて、今日この子がした、いちばんおもしろくてあなたをいちばん笑わせた瞬間を未来のために記録しましょう。そこに書くことが、いちばん純粋なセラピーです。', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 완벽한 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃기고 엄마를 가장 많이 웃게 한 순간을 기록해 두세요. 적는 것이 가장 깨끗한 치료예요.', body_nl = 'Pak je telefoon. Open in plaats van door het perfecte leven van anderen op social media te scrollen je Stemmingsdagboek en schrijf het grappigste moment van vandaag op, het moment waar je het hardst om lachte, voor later. Opschrijven is de zuiverste therapie.', body_pl = 'Weź telefon do ręki. Zamiast przewijać idealne życie innych w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował i która najbardziej cię rozśmieszyła. Pisanie tam to najczystsza terapia.', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida perfeita dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje, o que mais a fez rir. Escrever lá é a terapia mais pura.', body_sv = 'Ta upp telefonen. Istället för att scrolla igenom andras perfekta liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet, den som fick dig att skratta mest, för framtiden. Att skriva där är den renaste terapin.', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống hoàn hảo của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc hài hước nhất, khiến mẹ cười nhiều nhất mà bé làm hôm nay để dành cho tương lai. Viết ra là liệu pháp trong lành nhất.', body_zh = '拿起手机。与其刷社交网络看别人完美的生活，不如打开心情日记，把宝宝今天最搞笑、最让你笑出声的一刻记下来留给将来。写下来，就是最纯粹的疗愈。' WHERE id = '9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Aunque no haya champán, servid té caliente en los vasos y brindad con tu pareja diciendo: «Hemos sobrevivido a otro día tormentoso». Sois los comandantes de la casa y también un equipo inquebrantable.', body_fr = 'L''enfant dort. Pas de champagne ? Versez du thé chaud dans des verres et trinquez avec votre partenaire : « On a survécu à cette journée agitée aussi ! » Vous êtes à la fois les commandants de cette maison et une équipe inébranlable.', body_hi = 'बच्चा सो गया। शैंपेन न सही, गिलासों में गरम चाय डालिए और अपने साथी के साथ ‘यह तूफ़ानी दिन भी सही-सलामत निकाल लिया’ कहकर गिलास टकराइए। आप इस घर के सेनापति भी हैं और अटूट टीम भी।', body_id = 'Anak sudah tidur. Tak ada sampanye pun tak apa, tuang teh hangat ke gelas dan bersulanglah dengan pasangan sambil berkata ''Kita berhasil melewati hari penuh badai ini dengan selamat''. Kalian adalah panglima sekaligus tim yang tak tergoyahkan di rumah ini.', body_ja = '子どもが寝ました。シャンパンがなくても、コップに温かいお茶を注いで、パートナーと「この嵐のような一日も無事に乗りきったね」と乾杯しましょう。ふたりはこの家の司令官であり、揺るがないチームでもあります。', body_ko = '아이가 잠들었어요. 샴페인이 없어도 컵에 따뜻한 차를 따르고 배우자와 ''오늘같이 폭풍 같은 날도 무사히 끝냈어''라며 건배하세요. 두 사람은 이 집의 사령관이자 흔들림 없는 한 팀이에요.', body_nl = 'Je kind slaapt. Geen champagne in huis? Schenk dan warme thee in en klink met je partner: ''Ook deze stormachtige dag hebben we gehaald!'' Jullie zijn de aanvoerders én het onverwoestbare team van dit huis.', body_pl = 'Dziecko śpi. Nie ma szampana? Nalejcie do szklanek gorącej herbaty i stuknijcie się z partnerem, mówiąc: „Ten burzliwy dzień też przetrwaliśmy cało”. Jesteście i dowódcami tego domu, i niezłomną drużyną.', body_pt = 'A criança adormeceu. Mesmo sem champanhe, sirvam chá quente nos copos e brindem com o seu companheiro: "Também sobrevivemos a este dia tempestuoso". São os comandantes desta casa e também uma equipa inabalável.', body_sv = 'Barnet sover. Även om det inte finns champagne, häll upp varmt te i glasen, skåla med din partner och säg ”Den här stormiga dagen klarade vi också”. Ni är både hemmets befälhavare och ett orubbligt lag.', body_vi = 'Bé đã ngủ. Không có sâm panh cũng chẳng sao, hãy rót trà nóng vào cốc và cụng ly cùng chồng: "Chúng ta lại vượt qua thêm một ngày sóng gió nữa rồi!". Hai người vừa là những vị chỉ huy, vừa là đội ăn ý không gì lay chuyển được của ngôi nhà này.', body_zh = '宝宝睡着了。没有香槟也没关系，往杯子里倒上热茶，和伴侣碰个杯：“这暴风雨般的一天，我们也平平安安地度过了。”你们既是这个家的指挥官，也是坚不可摧的团队。' WHERE id = '4acc88e2-20b2-4215-8fcd-8a14393b92b9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha llorado a lágrima viva porque un perro de la calle no le miró o porque se cayó una hoja? No busques lógica. Para él es una tristeza realmente profunda. Simplemente valida su emoción: «Lo sé, querías que te mirara».', body_fr = 'Il a éclaté en sanglots parce que le chien croisé dans la rue ne l''a pas regardé, ou parce qu''une feuille est tombée ? Ne cherchez pas de logique. Pour lui, c''est un vrai et profond chagrin. Validez simplement son émotion : « Je sais, tu voulais qu''il te regarde. »', body_hi = 'सड़क पर दिखे कुत्ते ने उसकी ओर नहीं देखा, या पत्ता ज़मीन पर गिर गया, इसलिए फूट-फूटकर रोया? यहाँ तर्क मत ढूँढिए। उसके लिए यह सच में गहरा दुख है। ‘मुझे पता है, तुम चाहते थे कि वह तुम्हें देखे’ कहकर बस उसकी भावना को मान दीजिए।', body_id = 'Ia menangis tersedu-sedu karena anjing yang kalian lihat di jalan tidak menoleh padanya, atau karena sehelai daun jatuh ke tanah? Jangan mencari logika. Baginya ini benar-benar kesedihan yang dalam. Cukup akui perasaannya dengan berkata ''Mama tahu, kamu ingin anjing itu melihatmu''.', body_ja = '道で見かけた犬が自分を見てくれなかった、葉っぱが地面に落ちた、と言って大泣き？そこに理屈を求めないで。この子にとっては本当に深い悲しみなんです。「そうだよね、あの子に見てほしかったんだよね」と、ただ気持ちを認めてあげましょう。', body_ko = '길에서 본 강아지가 자기를 안 봤다고, 나뭇잎이 떨어졌다고 엉엉 울었나요? 논리를 찾지 마세요. 아이에게는 정말 깊은 슬픔이에요. ''알아, 강아지가 너를 봐 주길 바랐구나''라며 감정을 인정해 주세요.', body_nl = 'Huilde hij tranen met tuiten omdat de hond op straat niet naar hem keek, of omdat er een blaadje viel? Zoek er geen logica achter. Voor hem is dit echt diep verdriet. Bevestig gewoon zijn gevoel: ''Ik weet het, je wilde dat hij naar je keek.''', body_pl = 'Rozpłakał się w głos, bo pies na ulicy na niego nie spojrzał albo liść spadł na ziemię? Nie szukaj w tym logiki. Dla niego to naprawdę głęboki smutek. Po prostu uznaj jego emocje: „Wiem, chciałeś, żeby na ciebie spojrzał”.', body_pt = 'Chorou desalmadamente porque o cão que viram na rua não olhou para ele ou porque uma folha caiu? Não procure lógica. Para ele, é mesmo uma tristeza profunda. Diga apenas "Eu sei, querias que ele olhasse para ti" e valide a emoção dele.', body_sv = 'Grät barnet hejdlöst för att hunden ni såg på gatan inte tittade på det, eller för att ett löv föll till marken? Leta inte efter logik. För barnet är det verkligen en djup sorg. Säg bara ”Jag vet, du ville att den skulle titta på dig” och bekräfta känslan.', body_vi = 'Bé khóc nức nở chỉ vì chú chó gặp ngoài đường không nhìn bé, hay vì một chiếc lá rơi xuống đất? Đừng tìm logic ở đây. Với bé, đó thật sự là một nỗi buồn sâu sắc. Chỉ cần công nhận cảm xúc của bé: "Mẹ biết, con muốn bạn ấy nhìn con mà".', body_zh = '因为街上看到的小狗没看自己一眼，或者一片叶子掉到地上，就嚎啕大哭？别在这里找逻辑。对宝宝来说，这真的是很深的难过。说一句“我知道，你想让它看看你”，肯定宝宝的情绪就好。' WHERE id = '4b9f4b0d-becb-4db4-85ec-0a0caae64162' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Política en el parque 🤝', body_es = '¿Empuja a otro niño en el tobogán para subir él? Compartir todavía es un concepto complicado que no ha asentado del todo. En lugar de avergonzarte o castigarle, recuérdale la norma del sistema diciendo: «Ahora es su turno».', title_fr = 'Diplomatie au parc 🤝', body_fr = 'Il pousse un autre enfant sur le toboggan pour y monter lui-même ? Le partage est encore pour lui une notion complexe, pas tout à fait acquise. Plutôt que d''avoir honte ou de le punir, rappelez simplement la règle : « Maintenant, c''est son tour. »', title_hi = 'पार्क की नीति 🤝', body_hi = 'फिसलपट्टी पर किसी दूसरे बच्चे को धक्का देकर खुद चढ़ना चाहता है? बाँटना उसके लिए अभी पूरी तरह न बैठी, पेचीदा समझ है। शर्मिंदा होने या सज़ा देने के बजाय ‘अब उसकी बारी है’ कहकर बस नियम याद दिलाइए।', title_id = 'Politik di taman 🤝', body_id = 'Ia mendorong anak lain di perosotan karena ingin meluncur sendiri? Berbagi masih konsep rumit yang belum sepenuhnya ia kuasai. Daripada malu atau menghukum, cukup ingatkan aturannya dengan berkata ''Sekarang gilirannya''.', title_ja = '公園での政治 🤝', body_ja = 'すべり台でほかの子を押しのけて、自分がすべりたがる？分け合うことは、この子にとってまだ身についていない、むずかしい考えです。恥ずかしがったり罰したりする代わりに、「今はあの子の番だよ」と、ルールを思い出させるだけにしましょう。', title_ko = '놀이터의 외교 🤝', body_ko = '미끄럼틀에서 다른 아이를 밀치고 자기가 타려 하나요? 나누기는 아직 완전히 자리 잡지 않은 어려운 개념이에요. 창피해하거나 벌주는 대신 ''지금은 저 친구 차례야''라며 규칙만 알려 주세요.', title_nl = 'Politiek in het park 🤝', body_nl = 'Duwt hij op de glijbaan een ander kind weg om zelf te kunnen glijden? Delen is voor hem nog een ingewikkeld begrip dat nog niet helemaal zit. Schaam je niet en straf niet, maar herinner hem gewoon aan de regel: ''Nu is hij aan de beurt.''', title_pl = 'Polityka w parku 🤝', body_pl = 'Odpycha inne dziecko na zjeżdżalni, bo sam chce zjechać? Dzielenie się to dla niego wciąż trudne, jeszcze nieutrwalone pojęcie. Zamiast się wstydzić czy karać, po prostu przypomnij zasadę: „Teraz jego kolej”.', title_pt = 'Política no parque 🤝', body_pt = 'Empurra outra criança no escorrega para ir ele? Partilhar ainda é para ele um conceito complicado e pouco assente. Em vez de ficar envergonhada ou de o castigar, lembre-lhe simplesmente a regra do sistema: "Agora é a vez dele".', title_sv = 'Politik i parken 🤝', body_sv = 'Knuffar barnet bort ett annat barn i rutschkanan för att åka själv? Att dela är fortfarande ett krångligt begrepp som inte riktigt satt sig. Istället för att skämmas eller straffa, påminn bara om regeln: ”Nu är det hens tur.”', title_vi = 'Ngoại giao ở công viên 🤝', body_vi = 'Bé đẩy một bạn khác ở cầu trượt để được trượt trước? Chia sẻ vẫn là khái niệm phức tạp mà bé chưa thật sự nắm được. Thay vì xấu hổ hay phạt bé, hãy nhắc lại quy tắc: "Giờ là lượt của bạn ấy".', title_zh = '公园里的政治 🤝', body_zh = '在滑梯上把别的小朋友推开，想自己先滑？分享对宝宝来说还是个没完全建立起来的复杂概念。别感到丢脸，也别惩罚，只要提醒一下规则：“现在轮到他了。”' WHERE id = '9ae0817a-4137-49f1-8c45-fb16cc1d750b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La llamada del cuerpo 🩸', body_es = 'No te rindas a la irritación y el cansancio sin motivo. Mira el Calendario menstrual: tu cuerpo te está mandando señales. En lugar de culparte, descansa con un tentempié rico en magnesio.', title_fr = 'Le cri du corps 🩸', body_fr = 'Ne cédez pas à l''irritabilité et à la fatigue sans raison. Regardez le Suivi des règles, votre corps vous envoie des signaux. Au lieu de vous blâmer, reposez-vous avec une collation riche en magnésium.', title_hi = 'शरीर की पुकार 🩸', body_hi = 'बिना वजह की चिढ़ और थकान के आगे हार मत मानिए। पीरियड ट्रैकर देखिए, आपका शरीर संकेत दे रहा है। खुद को दोष देने के बजाय मैग्नीशियम वाले स्नैक के साथ आराम कीजिए।', title_id = 'Jeritan tubuh 🩸', body_id = 'Jangan menyerah pada rasa kesal dan lelah tanpa sebab. Lihat Pelacak Menstruasi, tubuh Anda sedang memberi sinyal. Daripada menyalahkan diri, beristirahatlah dengan camilan kaya magnesium.', title_ja = '体のSOS 🩸', body_ja = '理由のないイライラや疲れに負けないで。「生理トラッカー」を見てみましょう。体がサインを出しています。自分を責める代わりに、マグネシウムたっぷりのおやつで休みましょう。', title_ko = '몸이 보내는 외침 🩸', body_ko = '이유 없는 짜증과 피로에 지지 마세요. 생리 주기 기록을 확인해 보세요, 몸이 신호를 보내고 있어요. 자책하는 대신 마그네슘이 든 간식으로 쉬어 가세요.', title_nl = 'De roep van je lichaam 🩸', body_nl = 'Geef niet toe aan onverklaarbare prikkelbaarheid en vermoeidheid. Kijk in je Cyclustracker, je lichaam geeft signalen. Veroordeel jezelf niet, maar ontspan met een magnesiumrijk tussendoortje.', title_pl = 'Wołanie ciała 🩸', body_pl = 'Nie poddawaj się drażliwości i zmęczeniu bez powodu. Zajrzyj do Kalendarza miesiączkowego, twoje ciało wysyła sygnały. Zamiast się obwiniać, odpocznij z przekąską bogatą w magnez.', title_pt = 'O grito do corpo 🩸', body_pt = 'Não se renda à irritação e ao cansaço sem razão. Veja o Registo do Período: o seu corpo está a dar sinais. Em vez de se culpar, descanse com um snack rico em magnésio.', title_sv = 'Kroppens rop 🩸', body_sv = 'Ge inte efter för omotiverad irritation och trötthet. Titta i Mensspåraren, kroppen skickar signaler. Istället för att döma dig själv, vila med ett magnesiumrikt mellanmål.', title_vi = 'Tiếng gọi của cơ thể 🩸', body_vi = 'Đừng đầu hàng sự cáu kỉnh và mệt mỏi không rõ lý do. Hãy xem Theo dõi kỳ kinh, cơ thể mẹ đang gửi tín hiệu. Thay vì tự trách mình, hãy nghỉ ngơi với một món ăn nhẹ giàu magie.', title_zh = '身体的呼唤 🩸', body_zh = '别向莫名的烦躁和疲惫投降。看看经期记录，你的身体在发出信号。与其责怪自己，不如吃点富含镁的小零食，好好休息。' WHERE id = '23303195-392c-42b3-a778-b5f932e7d2fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Batalla con las sombras 👻', body_es = '¿Se asusta de su sombra en la pared y se esconde detrás de ti? Cerca de los 3 años y medio la imaginación no conoce límites. Oscurece la habitación y, con una linterna, crea juegos de sombras con las manos en la pared. Convierte la oscuridad que le asusta en su mayor diversión.', title_fr = 'La bataille des ombres 👻', body_fr = 'Il a peur de son ombre sur le mur et se cache derrière vous ? Vers le milieu de sa 3e année, l''imagination ne connaît pas de limites. Faites le noir dans la pièce et créez avec vos mains et une lampe de poche des jeux d''ombres sur le mur. Transformez le noir qui lui fait peur en son plus grand amusement.', title_hi = 'परछाईं से लड़ाई 👻', body_hi = 'दीवार पर अपनी परछाईं से डरकर आपके पीछे छिपता है? 3 साल के बीच तक कल्पना कोई सीमा नहीं मानती। कमरा अँधेरा करके टॉर्च से दीवार पर हाथों से परछाइयों के खेल बनाइए। जिस अँधेरे से वह डरता है, उसे उसके लिए सबसे बड़ा मज़ा बना दीजिए।', title_id = 'Bertarung dengan bayangan 👻', body_id = 'Ia takut pada bayangannya sendiri di dinding dan bersembunyi di belakang Anda? Menjelang pertengahan usia 3 tahun, imajinasi tidak mengenal batas. Gelapkan kamar, lalu dengan senter dan tangan Anda buat permainan bayangan di dinding. Ubah gelap yang ia takuti menjadi hiburan terbesarnya.', title_ja = '影とのたたかい 👻', body_ja = '壁に映った自分の影が怖くて、あなたの後ろに隠れる？3歳なかばにかけて、想像力に限界はありません。部屋を暗くして、懐中電灯を使って壁に手で影絵遊びをしましょう。怖がっていた暗やみを、いちばんの楽しみに変えてあげて。', title_ko = '그림자와의 전투 👻', body_ko = '벽에 비친 자기 그림자가 무서워 엄마 뒤에 숨나요? 세 살 중반이 되면 상상력에 한계가 없어요. 방을 어둡게 하고 손전등을 비춰 손으로 벽에 그림자 놀이를 만들어 주세요. 무서운 어둠을 가장 큰 즐거움으로 바꿔 주세요.', title_nl = 'Strijd met de schaduw 👻', body_nl = 'Is hij bang voor zijn schaduw op de muur en verstopt hij zich achter je? Rond 3,5 jaar kent de fantasie geen grenzen. Maak de kamer donker en maak met een zaklamp en je handen schaduwspelletjes op de muur. Maak van het donker waar hij bang voor is zijn grootste plezier.', title_pl = 'Walka z cieniem 👻', body_pl = 'Przestraszył się swojego cienia na ścianie i chowa się za tobą? W połowie 3. roku życia wyobraźnia nie zna granic. Zaciemnij pokój i z latarką twórz dłońmi na ścianie teatrzyk cieni. Zamień ciemność, której się boi, w jego największą rozrywkę.', title_pt = 'Luta com a sombra 👻', body_pt = 'Assustou-se com a sombra na parede e esconde-se atrás de si? Perto dos 3 anos e meio, a imaginação não tem limites. Escureça o quarto e, com uma lanterna, faça jogos de sombras com as mãos na parede. Transforme o escuro de que tem medo na sua maior diversão.', title_sv = 'Strid mot skuggan 👻', body_sv = 'Blir barnet rädd för sin egen skugga på väggen och gömmer sig bakom dig? Mitt i 3-årsåldern känner fantasin inga gränser. Gör rummet mörkt och skapa skuggspel på väggen med händerna och en ficklampa. Gör mörkret barnet är rädd för till det största nöjet.', title_vi = 'Chiến đấu với cái bóng 👻', body_vi = 'Bé sợ cái bóng của mình trên tường và nấp sau lưng mẹ? Gần 3 tuổi rưỡi, trí tưởng tượng không có giới hạn. Hãy làm tối căn phòng, dùng đèn pin và đôi tay tạo những trò chơi bóng trên tường. Biến bóng tối bé sợ thành niềm vui lớn nhất của bé.', title_zh = '和影子大战 👻', body_zh = '被墙上自己的影子吓得躲到你身后？快3岁半时，想象力没有边界。把房间调暗，打开手电筒，用手在墙上玩影子游戏吧。把宝宝害怕的黑暗变成最大的乐趣。' WHERE id = '455a26dd-2714-4e7f-a8b0-c2319880fdbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de los cuentos 🪄', body_es = 'Deja a un lado la lectura clásica. Abre Cuentos inteligentes. Imita con la boca el sonido del viento del cuento, el chirrido de la puerta y los pasos del héroe, y crea en la habitación un pequeño teatro sonoro. Se quedará fascinado con la actuación.', title_fr = 'La magie des contes 🪄', body_fr = 'Laissez de côté la lecture classique. Ouvrez les Contes intelligents. Faites avec la bouche le bruit du vent, le grincement de la porte, les pas du héros, et créez un petit théâtre sonore dans la chambre. Il sera émerveillé par cette performance.', title_hi = 'कहानियों का जादू 🪄', body_hi = 'पढ़ने का पुराना तरीका एक तरफ़ रखिए। स्मार्ट कहानियाँ खोलिए। कहानी में हवा की आवाज़, दरवाज़े की चरमराहट, हीरो के कदमों की आवाज़ मुँह से निकालकर कमरे में एक छोटा आवाज़ों वाला थिएटर बनाइए। वह इस प्रदर्शन पर फ़िदा हो जाएगा।', title_id = 'Keajaiban Dongeng Pintar 🪄', body_id = 'Tinggalkan cara membaca yang biasa. Buka Dongeng Pintar. Tirukan suara angin, derit pintu, dan langkah kaki tokohnya dengan mulut Anda, dan ciptakan teater suara kecil di kamar. Ia akan terpukau oleh pertunjukan ini.', title_ja = 'おはなしの魔法 🪄', body_ja = 'いつもの読み方はお休みしましょう。「スマートおはなし」を開いて、お話の中の風の音、ドアのきしむ音、主人公の足音を口で出して、部屋に小さな音の劇場をつくりましょう。このパフォーマンスにきっと夢中になります。', title_ko = '동화의 마법 🪄', body_ko = '평소의 읽어 주기 방식은 잠시 접어 두세요. 스마트 동화를 열고 이야기 속 바람 소리, 삐걱거리는 문소리, 주인공의 발소리를 입으로 내며 방에 작은 소리 극장을 만들어 보세요. 아이가 이 공연에 푹 빠질 거예요.', title_nl = 'De magie van sprookjes 🪄', body_nl = 'Leg de klassieke manier van voorlezen opzij. Open Slimme sprookjes. Maak met je mond het geluid van de wind, het kraken van de deur en de voetstappen van de held, en maak zo een klein geluidstheater in de kamer. Hij zal betoverd zijn door deze voorstelling.', title_pl = 'Magia bajek 🪄', body_pl = 'Odłóż klasyczny sposób czytania. Otwórz Mądre bajki. Naśladuj ustami szum wiatru, skrzypienie drzwi i kroki bohatera, tworząc w pokoju mały teatr dźwięku. Będzie zachwycony tym występem.', title_pt = 'A magia das histórias 🪄', body_pt = 'Ponha de lado a leitura clássica. Abra as Histórias Inteligentes. Faça com a boca o som do vento, o ranger da porta e os passos do herói e crie no quarto um pequeno teatro de sons. Ele vai ficar encantado com o espetáculo.', title_sv = 'Sagornas magi 🪄', body_sv = 'Lägg den klassiska högläsningen åt sidan. Öppna Smarta sagor. Gör vindens sus, dörrens knarr och hjältens fotsteg i sagan med munnen och skapa en liten ljudteater i rummet. Barnet kommer att bli förtjust i föreställningen.', title_vi = 'Phép màu của truyện cổ tích 🪄', body_vi = 'Hãy gác lại cách đọc truyện thông thường. Mở Truyện cổ tích thông minh. Dùng miệng tạo tiếng gió, tiếng cửa kẽo kẹt, tiếng bước chân của nhân vật để tạo nên một nhà hát âm thanh nho nhỏ trong phòng. Bé sẽ mê mẩn màn trình diễn này.', title_zh = '童话的魔法 🪄', body_zh = '把传统的读法放一边。打开智慧童话。用嘴模仿故事里的风声、门的吱呀声、英雄的脚步声，在房间里打造一个小小的声音剧场。宝宝会被这场表演迷住的。' WHERE id = 'ca0412c4-f03e-412b-a720-1ce839d731c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica para retrasar el sueño ⏱️', body_es = '¿Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared? Pon un temporizador. Aplica la norma «cuando suena la campanita, todos a dormir» y líbrate con paciencia de esta despedida sin fin, de esta manipulación tan experta.', title_fr = 'Tactiques pour retarder le dodo ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde dort » et échappez avec patience à ces adieux sans fin, à cette manipulation de maître.', title_hi = 'नींद टालने की चाल ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है? टाइमर लगाइए। ‘घंटी बजते ही सब सो जाते हैं’ का नियम लागू करके इस अंतहीन अलविदा, इस माहिर चाल से धैर्य के साथ बच निकलिए।', title_id = 'Taktik menunda tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua tidur'' dan bebaskan diri dengan sabar dari perpisahan tanpa akhir dan manipulasi cerdik ini.', title_ja = '寝る時間を遅らせる作戦 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり？タイマーをセットしましょう。「ベルが鳴ったらみんな寝る」のルールで、この終わらないおやすみのあいさつ、この見事な作戦から根気よく抜け出して。', title_ko = '잠 미루기 작전 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 잔다'' 규칙을 정해 이 끝없는 작별 인사, 이 노련한 작전에서 차분하게 벗어나세요.', title_nl = 'Uitsteltactieken voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaat iedereen slapen'' in en verlos jezelf geduldig van dit eindeloze afscheid, deze meesterlijke manipulatie.', title_pl = 'Taktyka odwlekania snu ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą? Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy śpią” i cierpliwie uwolnij się od tych niekończących się pożegnań, tej mistrzowskiej manipulacji.', title_pt = 'Táticas para adiar o sono ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede? Programe um temporizador. Aplique a regra "quando a campainha toca, todos dormem" e livre-se com paciência desta despedida sem fim, desta manipulação de mestre.', title_sv = 'Taktiken att skjuta upp sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla” och rädda dig tålmodigt från det ändlösa farvälet och den här mästerliga manipulationen.', title_vi = 'Chiến thuật trì hoãn giấc ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà đi ngủ" để kiên nhẫn thoát khỏi những lời tạm biệt bất tận, màn "thao túng" bậc thầy này.', title_zh = '拖延睡觉的战术 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见？设个计时器。立下“铃声一响，大家都睡觉”的规矩，耐心地摆脱这没完没了的告别和高明的“操控”吧。' WHERE id = '5ee7392d-5b0b-4213-bc93-84f42871cfbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La mamá de los juguetes 🧸', body_es = 'Se oye algo en la habitación. Escuchas con atención: ¡está riñendo a su osito con tu mismo tono de voz y tus frases más típicas! Es tu copia más exacta. Es una oportunidad perfecta para ver tu propio comportamiento desde fuera.', title_fr = 'La maman des jouets 🧸', body_fr = 'Un bruit vient de la chambre. Vous tendez l''oreille : il gronde son nounours avec exactement votre ton de voix et vos phrases bien à vous ! Il est votre copie la plus fidèle. C''est une occasion parfaite de voir votre propre comportement de l''extérieur.', title_hi = 'खिलौनों की माँ 🧸', body_hi = 'कमरे से आवाज़ आती है। ध्यान से सुनती हैं, तो वह अपने टेडी को बिल्कुल आपके लहजे और आपके ही खास वाक्यों में डाँट रहा है! वह आपकी सबसे सटीक नकल है। अपने व्यवहार को बाहर से देखने का यह बढ़िया मौका है।', title_id = 'Ibu bagi mainannya 🧸', body_id = 'Ada suara dari kamar. Anda mendengarkan baik-baik, dan ternyata ia sedang memarahi beruangnya persis dengan nada suara dan kalimat khas Anda! Ia adalah tiruan Anda yang paling akurat. Ini kesempatan sempurna untuk melihat perilaku Anda sendiri dari luar.', title_ja = 'おもちゃたちのママ 🧸', body_ja = '部屋から声が聞こえます。耳をすませると、くまさんをあなたとまったく同じ声のトーン、あなたのおなじみのセリフでしかっている！この子はあなたのいちばん正確なコピーです。自分のふるまいを外から見直す絶好のチャンスです。', title_ko = '장난감들의 엄마 🧸', body_ko = '방에서 소리가 들려 귀 기울여 보니, 곰 인형을 엄마와 똑같은 톤, 엄마가 자주 쓰는 말로 혼내고 있나요! 아이는 엄마의 가장 정확한 복사본이에요. 내 행동을 밖에서 바라볼 수 있는 완벽한 기회예요.', title_nl = 'De mama van de knuffels 🧸', body_nl = 'Er komt geluid uit de kamer. Je luistert goed, en hij moppert op zijn beertje met precies jouw toon en jouw typische zinnetjes! Hij is je meest nauwkeurige kopie. Een perfecte kans om je eigen gedrag eens van buitenaf te bekijken.', title_pl = 'Mama zabawek 🧸', body_pl = 'Z pokoju dochodzi głos. Słuchasz uważnie, a on beszta swojego misia dokładnie twoim tonem i twoimi charakterystycznymi zdaniami! Jest twoją najwierniejszą kopią. To świetna okazja, by spojrzeć na swoje zachowanie z boku.', title_pt = 'A mãe dos brinquedos 🧸', body_pt = 'Vem um som do quarto. Ouve com atenção e ele está a ralhar com o ursinho exatamente com o seu tom de voz e as suas frases mais típicas! É a sua cópia mais fiel. É uma oportunidade perfeita para ver o seu próprio comportamento de fora.', title_sv = 'Leksakernas mamma 🧸', body_sv = 'Det hörs ljud från rummet. Du lyssnar noga, och barnet skäller på sin nalle med exakt din röst och dina specifika meningar! Barnet är din mest exakta kopia. Det är ett perfekt tillfälle att se ditt eget beteende utifrån.', title_vi = 'Mẹ của những món đồ chơi 🧸', body_vi = 'Có tiếng động trong phòng. Mẹ lắng nghe và nhận ra bé đang mắng gấu bông bằng đúng giọng điệu, đúng những câu nói đặc trưng của mẹ! Bé là bản sao chính xác nhất của mẹ. Đây là cơ hội tuyệt vời để nhìn lại hành vi của chính mình từ bên ngoài.', title_zh = '玩具们的妈妈 🧸', body_zh = '房间里传来声音。你仔细一听，宝宝正用和你一模一样的语气、你特有的那些话在训它的小熊！宝宝是你最精准的复制品。这是从旁观察自己言行的绝佳机会。' WHERE id = '8ed6ac5e-566a-43de-a26f-f6688bac7a5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Fuera el tiempo no está claro, hace sol pero también sopla viento? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado, y sal de paseo sin perder tiempo dudando en la puerta.', body_fr = 'Le temps dehors n''est pas très clair, du soleil mais aussi du vent ? Laissez Météo et tenue vous indiquer aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue, et partez en promenade sans perdre de temps à hésiter sur le pas de la porte.', body_hi = 'बाहर मौसम पूरा साफ़ नहीं, धूप है पर हवा भी चल रही है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताए, ताकि दरवाज़े पर दुविधा में समय गँवाए बिना सैर पर निकल सकें।', body_id = 'Cuaca di luar tidak menentu, ada matahari tapi angin juga bertiup? Biarkan Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan setelan yang tepat, lalu pergilah jalan-jalan tanpa membuang waktu ragu-ragu di depan pintu.', body_ja = '外は晴れているのか、日は出ているけれど風も吹いている？「天気と服装」に、窓からは見えない風の強さとぴったりのコーデをすぐに教えてもらいましょう。玄関で迷って時間をむだにせず、お散歩に出かけましょう。', body_ko = '밖의 날씨가 애매하게 해는 났는데 바람도 부나요? 창밖으로는 보이지 않는 풍속과 알맞은 옷차림을 날씨와 옷차림 도구가 바로 알려 줄 거예요. 현관에서 망설이며 시간 보내지 말고 산책을 나가세요.', body_nl = 'Is het weer buiten niet helemaal duidelijk, met zon maar ook wind? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je vanuit het raam niet ziet, en de juiste outfit, en ga wandelen zonder twijfelend tijd te verliezen bij de deur.', body_pl = 'Pogoda na dworze niepewna, świeci słońce, ale wieje wiatr? Niech narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru, której nie widać przez okno, i właściwy zestaw ubrań. Wyjdźcie na spacer, nie tracąc czasu na wahanie w progu.', body_pt = 'O tempo lá fora não está bem definido: há sol, mas também vento? Deixe que a ferramenta Tempo e Roupa lhe diga logo a velocidade do vento, que não se vê da janela, e a roupa certa, e saia para passear sem perder tempo indecisa à porta.', body_sv = 'Är vädret ute inte riktigt klart, solen skiner men det blåser också? Låt verktyget Väder och kläder direkt visa vindhastigheten som inte syns genom fönstret och rätt klädsel, så kommer ni ut på promenad utan att stå villrådiga och förlora tid i dörren.', body_vi = 'Thời tiết ngoài trời không rõ ràng, có nắng nhưng cũng có gió? Hãy để Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp, để ra ngoài đi dạo mà không mất thời gian lưỡng lự ở cửa.', body_zh = '外面天气说不准，有太阳但也刮着风？让天气与穿衣工具马上告诉你从窗户看不出的风速和正确的搭配，别再犹豫着在门口浪费时间，出门散步吧。' WHERE id = 'fcc9b956-df18-4d44-8e28-2c6ce0162f8e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ya has tenido bastante cansancio y ruido durante el día. Deja a los juegos de papá la preparación para dormir y el lavado de dientes del atardecer, y tú descansa aparte, en otra habitación, en silencio absoluto.', body_fr = 'La fatigue et le bruit de la journée, ça suffit. En fin de journée, confiez la préparation au coucher et le brossage des dents aux jeux de papa, et reposez-vous dans le silence absolu d''une autre pièce.', body_hi = 'दिन की थकान और शोर काफ़ी हो चुके। शाम को बच्चे को सोने के लिए तैयार करने, दाँत ब्रश करवाने का काम पापा की मस्ती के हवाले कीजिए, और आप किसी दूसरे कमरे में पूरी खामोशी में आराम कीजिए।', body_id = 'Lelah dan bising seharian sudah cukup bagi Anda. Sore hari, serahkan proses menyiapkan anak tidur dan menyikat giginya kepada permainan seru Ayah, sementara Anda beristirahat dalam keheningan total di ruangan lain.', body_ja = '昼間の疲れと騒がしさで、もう限界ですね。夕方の寝る準備や歯みがきはパパの遊び心にまかせて、あなたは別の部屋で、完全な静けさの中で休みましょう。', body_ko = '낮의 피로와 소음은 이걸로 충분해요. 저녁에 아이 재울 준비와 양치는 아빠의 장난스러운 방식에 맡기고, 엄마는 다른 방에서 완전한 고요 속에 쉬세요.', body_nl = 'Je hebt genoeg van de vermoeidheid en het lawaai van de dag. Laat het klaarmaken voor bed en het tandenpoetsen ''s avonds over aan papa''s speelse grapjes, en rust jij in absolute stilte in een andere kamer.', body_pl = 'Masz dość dziennego zmęczenia i hałasu. Wieczorne przygotowanie dziecka do snu i mycie zębów powierz zabawom taty, a ty odpocznij z boku, w innym pokoju, w absolutnej ciszy.', body_pt = 'Já chega de cansaço e barulho durante o dia. Ao fim da tarde, entregue às brincadeiras do pai a preparação para dormir e a lavagem dos dentes, e descanse noutra divisão, em silêncio absoluto.', body_sv = 'Du har fått nog av dagens trötthet och oljud. Överlåt kvällens nattning och tandborstning åt pappas lekfullhet, och vila du i total tystnad i ett annat rum.', body_vi = 'Mệt mỏi và ồn ào ban ngày đã quá đủ với mẹ. Buổi tối, hãy giao việc chuẩn bị đi ngủ, đánh răng cho bé cho những trò tinh nghịch của bố, còn mẹ sang một phòng khác nghỉ ngơi trong yên tĩnh tuyệt đối.', body_zh = '白天的疲惫和噪音已经够你受的了。傍晚哄宝宝准备睡觉、刷牙这些事，就交给爱玩的爸爸吧，你去另一个房间，在绝对的安静中好好休息。' WHERE id = '542ab746-c3f8-40a2-81ae-c00828c5ed07' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Has preparado 4 menús distintos para que coma, pero ¿y tú qué has comido? Elige en Recetas saludables un tentempié especial rico en calcio que se hace en 5 minutos y disfrútalo aunque sea de pie: eres el motor de esta casa.', body_fr = 'Vous avez imaginé 4 menus différents pour le nourrir, mais vous, qu''avez-vous mangé ? Choisissez dans les Recettes saines une collation spéciale riche en calcium, prête en 5 minutes, et savourez-la, même debout : vous êtes le moteur de cette maison.', body_hi = 'उसे खिलाने के लिए 4 तरह का मेन्यू बनाया, और आपने क्या खाया? सेहतमंद रेसिपी से 5 मिनट में बनने वाला, कैल्शियम से भरपूर एक खास स्नैक चुनिए और खड़े-खड़े ही सही, उसका मज़ा लीजिए, आप इस घर का इंजन हैं।', body_id = 'Kamu menyusun menu dengan 4 cara berbeda untuk menyuapinya, lalu kamu sendiri makan apa? Pilih camilan istimewa kaya kalsium dari Resep Sehat yang siap dalam 5 menit, dan nikmati meski sambil berdiri. Kamu adalah mesin rumah ini.', body_ja = 'この子に食べさせるために4通りもメニューを考えたけれど、あなたは何を食べた？「ヘルシーレシピ」から5分でできる、カルシウムたっぷりの特別なおやつを選んで、立ったままでも味わって。あなたはこの家のエンジンです。', body_ko = '아이를 먹이려고 메뉴를 4가지나 짰는데, 엄마는 뭘 드셨나요? 건강한 레시피에서 5분이면 되는 칼슘이 풍부한 특별한 간식을 골라 서서라도 맛있게 드세요. 엄마는 이 집의 엔진이에요.', body_nl = 'Je hebt op 4 manieren een menu bedacht om hem te laten eten, maar wat heb jij gegeten? Kies uit Gezonde recepten een speciaal, calciumrijk tussendoortje dat in 5 minuten klaar is en geniet ervan, al is het staand. Jij bent de motor van dit huis.', body_pl = 'Wymyśliłaś menu na 4 różne sposoby, żeby go nakarmić, a ty co zjadłaś? Wybierz ze Zdrowych przepisów wyjątkową przekąskę bogatą w wapń, gotową w 5 minut, i delektuj się nią, nawet na stojąco. Jesteś silnikiem tego domu.', body_pt = 'Preparou 4 menus diferentes para ele comer, mas e a mãe, o que comeu? Escolha nas Receitas Saudáveis um snack especial rico em cálcio, pronto em 5 minutos, e saboreie-o, nem que seja de pé: é o motor desta casa.', body_sv = 'Du gjorde 4 olika menyer för att få barnet att äta, men vad åt du själv? Välj ett särskilt kalciumrikt mellanmål från Hälsosamma recept som tar 5 minuter och njut av det, även om du står upp. Du är det här hemmets motor.', body_vi = 'Mẹ đã nghĩ ra thực đơn theo 4 cách khác nhau để bé chịu ăn, còn mẹ đã ăn gì chưa? Hãy chọn từ Công thức lành mạnh một món ăn nhẹ đặc biệt giàu canxi, làm xong trong 5 phút, và thưởng thức dù chỉ đứng ăn, mẹ là động cơ của ngôi nhà này.', body_zh = '为了让宝宝吃饭，你想了4种不同的菜单，那你自己吃了什么？从健康食谱里挑一份5分钟搞定、富含钙的特别小零食，哪怕站着吃也好好享受，你是这个家的发动机。' WHERE id = '843abd1b-ca68-4402-b6ea-b248f8954a8f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desayuno que no se comparte 🍳', body_es = 'No te da nada de su plato, pero viene e insiste en comer del huevo o del queso de tu plato. Los niños siempre confían plenamente en lo que eligen sus padres. No luches: pásale tu bocado con cariño.', title_fr = 'Un petit-déjeuner qui ne se partage pas 🍳', body_fr = 'Il refuse catégoriquement de vous donner quoi que ce soit de son assiette, mais vient réclamer avec insistance l''œuf ou le fromage de la vôtre. Les enfants font toujours entièrement confiance aux choix de leurs parents. Ne luttez pas, cédez-lui votre bouchée avec amour.', title_hi = 'न बँटने वाला नाश्ता 🍳', body_hi = 'अपनी प्लेट का कुछ भी आपको बिल्कुल नहीं देता, पर आकर ज़िद से आपकी प्लेट का अंडा या चीज़ खाना चाहता है। बच्चे हमेशा माता-पिता की पसंद पर पूरा भरोसा करते हैं। लड़ाई मत कीजिए, अपना निवाला प्यार से उसे दे दीजिए।', title_id = 'Sarapan yang tak bisa dibagi 🍳', body_id = 'Ia sama sekali tak mau memberi isi piringnya kepada Anda, tapi bersikeras ingin makan telur atau keju dari piring Anda. Anak selalu percaya penuh pada pilihan orang tuanya. Jangan melawan, berikan suapan Anda kepadanya dengan penuh kasih.', title_ja = '分けてくれない朝ごはん 🍳', body_ja = '自分のお皿のものは絶対にくれないのに、あなたのお皿の卵やチーズはどうしても食べたがる。子どもはいつも、親が選んだものを心から信頼するんです。戦わずに、あなたのひと口を愛をこめて渡してあげましょう。', title_ko = '나눌 수 없는 아침 식사 🍳', body_ko = '자기 접시는 절대 안 주면서 엄마 접시의 달걀이나 치즈는 꼭 먹겠다고 하나요? 아이는 늘 부모의 선택을 온전히 믿어요. 싸우지 말고 한 입을 사랑으로 건네주세요.', title_nl = 'Ontbijt dat niet gedeeld wordt 🍳', body_nl = 'Van zijn eigen bord geeft hij je absoluut niets, maar hij wil per se van het ei of de kaas op jouw bord eten. Kinderen vertrouwen altijd volledig op de keuze van hun ouders. Ga de strijd niet aan en geef je hapje liefdevol aan hem.', title_pl = 'Śniadanie nie do podziału 🍳', body_pl = 'Ze swojego talerza nie da ci ani kęsa, ale uparcie chce jeść jajko albo ser z twojego. Dzieci zawsze w pełni ufają wyborom rodziców. Nie walcz, z miłością oddaj mu swój kęs.', title_pt = 'Um pequeno-almoço que não se partilha 🍳', body_pt = 'Não lhe dá nada do prato dele, mas insiste em comer o ovo ou o queijo do seu prato. As crianças confiam sempre totalmente nas escolhas dos pais. Não lute: passe-lhe o seu bocado com amor.', title_sv = 'Frukosten som inte delas 🍳', body_sv = 'Barnet ger dig absolut ingenting från sin egen tallrik, men kommer och vill envist äta av ägget eller osten på din. Barn litar alltid helt på föräldrarnas val. Börja inte bråka, ge din tugga till barnet med kärlek.', title_vi = 'Bữa sáng không chia sẻ 🍳', body_vi = 'Bé nhất quyết không cho mẹ chút gì trong đĩa của mình, nhưng lại cứ đòi ăn trứng hay phô mai trong đĩa của mẹ. Trẻ con luôn tin tưởng tuyệt đối vào lựa chọn của bố mẹ. Đừng giằng co, hãy yêu thương nhường miếng ăn của mình cho bé.', title_zh = '不肯分享的早餐 🍳', body_zh = '自己盘子里的东西绝对不给你，却偏要来吃你盘子里的鸡蛋或奶酪。孩子总是完全相信父母的选择。别较劲，带着爱把你的那一口递给宝宝吧。' WHERE id = '9b9022d6-2ceb-4fd3-b3c5-141395cf895c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Masaje en equipo 💆‍♂️', body_es = 'Cuando el peque se duerma, daos un masaje de hombros tú y tu pareja para soltar todo el estrés físico y psicológico del día. No sois solo padres que comparten casa: sois un equipo de apoyo inquebrantable.', title_fr = 'Massage d''équipe 💆‍♂️', body_fr = 'Une fois l''enfant couché, massez-vous les épaules l''un l''autre avec votre partenaire pour évacuer tout le stress physique et psychologique de la journée. Vous n''êtes pas seulement des parents qui partagent une maison, vous êtes une équipe de soutien inébranlable.', title_hi = 'टीम मसाज 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का सारा शारीरिक और मानसिक तनाव उतारने के लिए अपने साथी के साथ एक-दूसरे के कंधों की मालिश कीजिए। आप सिर्फ़ एक घर बाँटने वाले माता-पिता नहीं, एक अटूट सहारा देने वाली टीम हैं।', title_id = 'Pijat berdua 💆‍♂️', body_id = 'Setelah anak tidur, saling pijat bahu bersama pasangan untuk melepas semua stres fisik dan psikologis seharian. Kalian bukan sekadar orang tua yang berbagi rumah, kalian adalah tim pendukung yang tak tergoyahkan.', title_ja = 'チームでマッサージ 💆‍♂️', body_ja = '子どもが寝たら、パートナーと肩をもみ合って、一日の体と心のストレスを全部手放しましょう。ふたりはただ同じ家に暮らす親ではなく、揺るがない支え合いのチームです。', title_ko = '팀 마사지 💆‍♂️', body_ko = '아이가 잠들면 하루의 몸과 마음의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 두 사람은 한집에 사는 부모일 뿐 아니라 흔들림 없는 응원 팀이에요.', title_nl = 'Massage als team 💆‍♂️', body_nl = 'Geef elkaar met je partner een schoudermassage als je kind slaapt, om alle lichamelijke en mentale stress van de dag kwijt te raken. Jullie zijn niet zomaar ouders die een huis delen, jullie zijn een onverwoestbaar steunteam.', title_pl = 'Masaż we dwoje 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić cały fizyczny i psychiczny stres dnia. Nie jesteście tylko rodzicami dzielącymi jeden dom, jesteście niezłomną drużyną wsparcia.', title_pt = 'Massagem em equipa 💆‍♂️', body_pt = 'Depois de a criança adormecer, façam massagens nos ombros um ao outro para libertar todo o stress físico e psicológico do dia. Não são apenas pais a partilhar a mesma casa: são uma equipa de apoio inabalável.', title_sv = 'Lagmassage 💆‍♂️', body_sv = 'När barnet har somnat kan du och din partner ge varandra en axelmassage för att släppa dagens fysiska och psykiska stress. Ni är inte bara föräldrar som delar samma hem, ni är ett orubbligt stödlag.', title_vi = 'Mát-xa cho nhau 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng chồng mát-xa vai cho nhau để xua tan mọi căng thẳng thể chất và tinh thần của cả ngày. Hai người không chỉ là bố mẹ sống chung một nhà, mà là một đội hỗ trợ nhau không gì lay chuyển được.', title_zh = '双人按摩 💆‍♂️', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天所有身体和心理上的压力。你们不只是住在同一个家里的父母，更是一支坚不可摧的支持团队。' WHERE id = '3a219301-d574-4311-87ab-5dc04ddcfd8f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No es culpa mía! 🤷‍♂️', body_es = 'Ha tirado el agua al suelo a propósito, pero le echa la culpa a la mesa: «Se ha movido la mesa». No es una mentira, es un instinto de defensa. No discutas: transmítele la responsabilidad sin herirle diciendo «Vamos a ayudar a la mesa y a secarlo juntos».', title_fr = 'C''est pas ma faute ! 🤷‍♂️', body_fr = 'Il a renversé l''eau exprès, mais a rejeté la faute sur la table : « La table a glissé ». Ce n''est pas un mensonge, c''est un instinct d''autodéfense. Ne vous entêtez pas, transmettez la responsabilité sans le blesser : « Viens, on aide la table et on essuie ensemble. »', title_hi = 'यह मेरी गलती नहीं है! 🤷‍♂️', body_hi = 'जानबूझकर पानी गिराया, पर दोष मेज़ पर डालकर बोला, ‘मेज़ फिसल गई।’ यह झूठ नहीं, खुद को बचाने की स्वाभाविक प्रवृत्ति है। ज़िद मत कीजिए, ‘आओ, मेज़ की मदद करके साथ में पोंछें’ कहकर बिना ठेस पहुँचाए ज़िम्मेदारी सिखाइए।', title_id = 'Ini bukan salahku! 🤷‍♂️', body_id = 'Ia sengaja menumpahkan air ke lantai, tapi menyalahkan meja: ''Mejanya licin.'' Ini bukan bohong, ini naluri membela diri. Jangan berdebat, tanamkan tanggung jawab tanpa menyakiti dengan berkata ''Ayo kita bantu meja dan lap sama-sama''.', title_ja = 'ぼくのせいじゃない！ 🤷‍♂️', body_ja = 'わざとお水を床にこぼしたのに、テーブルのせいにして「テーブルがすべった」と言う。これはうそではなく、自分を守ろうとする本能です。言い合わずに「テーブルを助けて、一緒に拭こう」と声をかけて、傷つけずに責任を教えましょう。', title_ko = '내 잘못 아니야! 🤷‍♂️', body_ko = '일부러 물을 쏟고는 ''식탁이 미끄러졌어''라며 식탁 탓을 하나요? 거짓말이 아니라 자신을 지키려는 본능이에요. 고집 싸움 말고 ''식탁을 도와서 같이 닦자''라며 상처 주지 않고 책임감을 가르쳐 주세요.', title_nl = 'Het is niet mijn schuld! 🤷‍♂️', body_nl = 'Hij gooide expres water op de grond, maar gaf de tafel de schuld: ''De tafel gleed weg.'' Dat is geen liegen, maar een instinct om zichzelf te beschermen. Ga er niet tegenin, maar leer hem verantwoordelijkheid zonder te kwetsen: ''Kom, we helpen de tafel en vegen het samen op.''', title_pl = 'To nie moja wina! 🤷‍♂️', body_pl = 'Celowo wylał wodę na podłogę, ale zwalił winę na stół: „Stół się przesunął”. To nie kłamstwo, tylko instynkt samoobrony. Nie kłóć się, ucz odpowiedzialności bez ranienia: „Pomóżmy stołowi i wytrzyjmy to razem”.', title_pt = 'A culpa não é minha! 🤷‍♂️', body_pt = 'Entornou a água no chão de propósito, mas culpou a mesa: "A mesa escorregou". Não é mentira, é o instinto de se defender. Não teime: diga "Vamos ajudar a mesa e limpar juntos" e ensine responsabilidade sem o magoar.', title_sv = 'Det är inte mitt fel! 🤷‍♂️', body_sv = 'Barnet hällde ut vattnet på golvet med flit men skyllde på bordet: ”Bordet gled.” Det är ingen lögn, det är en instinkt att försvara sig. Bråka inte, säg ”Kom så hjälper vi bordet och torkar upp tillsammans” och lär ut ansvar utan att såra.', title_vi = 'Không phải lỗi của con! 🤷‍♂️', body_vi = 'Bé cố tình đổ nước ra sàn, nhưng lại đổ lỗi cho cái bàn: "Cái bàn bị trượt". Đây không phải nói dối, mà là bản năng tự vệ. Đừng giằng co, hãy nhẹ nhàng dạy trách nhiệm: "Mình cùng giúp cái bàn lau sạch nhé".', title_zh = '不是我的错！🤷‍♂️', body_zh = '故意把水洒在地上，却把责任推给桌子：“是桌子滑了。”这不是撒谎，而是自我保护的本能。别较劲，说一句“我们来帮帮桌子，一起擦干净吧”，不伤害宝宝地教会责任。' WHERE id = '77e473a7-cc66-4af3-964b-ebd4e0ce22a0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apoyo de la Comunidad 💬', body_es = '¿De repente te ahoga el pensamiento «Nunca volveré a ser la de antes, la que era libre»? Comparte este sentimiento pasajero pero muy pesado y profundo con las madres de la Comunidad Anacan y recibe consuelo y apoyo de quienes han pasado por lo mismo.', title_fr = 'Le soutien de la Communauté 💬', body_fr = 'La pensée « Je ne serai plus jamais la femme libre d''avant » vous étouffe soudain ? Partagez ce sentiment passager, mais très lourd et profond, avec les mamans de la Communauté Anacan et recevez le réconfort et le soutien de celles qui sont passées par là.', title_hi = 'कम्युनिटी का सहारा 💬', body_hi = '‘मैं फिर कभी पहले वाली आज़ाद मैं नहीं बन पाऊँगी’ वाला ख्याल अचानक आपका दम घोंट रहा है? Anacan कम्युनिटी की माँओं के साथ यह अस्थायी, पर बहुत भारी और गहरी भावना बाँटिए और उनसे सांत्वना और सहारा पाइए, जो इसी राह से गुज़र चुकी हैं।', title_id = 'Dukungan komunitas 💬', body_id = 'Pikiran ''Aku tidak akan pernah bisa menjadi diriku yang dulu dan bebas'' tiba-tiba membuat Anda sesak? Bagikan perasaan yang sementara namun sangat berat dan dalam ini dengan para ibu di Komunitas Anacan, dan dapatkan penghiburan serta dukungan dari mereka yang pernah melalui jalan yang sama.', title_ja = 'コミュニティの支え 💬', body_ja = '「もう前の自由な自分には戻れない」という思いに、急に胸がつまることはありませんか？Anacanコミュニティのママたちと、この一時的だけれどとても重くて深い気持ちを分かち合いましょう。同じ道を通ってきた人たちから、なぐさめと支えをもらえます。', title_ko = '커뮤니티의 응원 💬', body_ko = '''다시는 예전의 자유로운 나로 돌아갈 수 없을 거야''라는 생각이 갑자기 숨을 막히게 하나요? 이 지나가지만 무겁고 깊은 감정을 Anacan 커뮤니티의 엄마들과 나누고, 같은 길을 걸어온 이들에게 위로와 응원을 받으세요.', title_nl = 'Steun van de Community 💬', body_nl = 'Overvalt de gedachte ''Ik word nooit meer de oude, vrije ik'' je ineens? Deel dit tijdelijke maar heel zware, diepe gevoel met de mama''s in de Anacan Community en krijg troost en steun van wie dezelfde weg is gegaan.', title_pl = 'Wsparcie Społeczności 💬', body_pl = 'Nagle dławi cię myśl „Już nigdy nie będę dawną, wolną sobą”? Podziel się tym przemijającym, ale bardzo ciężkim, głębokim uczuciem z mamami w Społeczności Anacan i znajdź pocieszenie i wsparcie u tych, które przeszły tę samą drogę.', title_pt = 'O apoio da comunidade 💬', body_pt = 'De repente sufoca-a o pensamento "nunca mais vou voltar a ser a pessoa livre que era"? Partilhe este sentimento passageiro, mas muito pesado e profundo, com as mães da Comunidade Anacan e receba conforto e apoio de quem já passou pelo mesmo.', title_sv = 'Gemenskapens stöd 💬', body_sv = 'Kväver tanken ”jag kommer aldrig att kunna bli mitt gamla, fria jag igen” dig plötsligt? Dela den här övergående men väldigt tunga, djupa känslan med mammorna i Anacan Community och få tröst och stöd från dem som gått samma väg.', title_vi = 'Sự hỗ trợ từ Cộng đồng 💬', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ được tự do như ngày xưa nữa" bỗng khiến mẹ nghẹt thở? Hãy chia sẻ cảm xúc thoáng qua nhưng nặng nề, sâu sắc này với các mẹ trong Cộng đồng Anacan, và nhận sự an ủi, hỗ trợ từ những người đã đi qua cùng con đường.', title_zh = '社区的支持 💬', body_zh = '“我再也回不到从前那个自由的自己了”，这个念头突然让你喘不过气？在Anacan社区和妈妈们分享这份短暂却沉重、深刻的感受，从走过同样道路的她们那里得到安慰和支持。' WHERE id = 'a43b3c7f-b8b9-440c-abc6-6650d2627176' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos de vocabulario 🗣️', body_es = 'Pone a las cosas nombres nuevos inventados por él que no existen en ningún idioma. ¡Y exige que tú también uses esa palabra! Abre el Seguimiento del desarrollo y anota sin falta estas palabras tan cómicas para leerlas en el futuro y reírte.', title_fr = 'Nouvelles découvertes de vocabulaire 🗣️', body_fr = 'Il donne aux objets des noms tout neufs qu''il a inventés, qui n''existent dans aucune langue. Et il exige que vous les utilisiez aussi ! Ouvrez le Suivi de développement et notez absolument ces mots comiques pour les relire plus tard en riant.', title_hi = 'नए शब्दों की खोज 🗣️', body_hi = 'चीज़ों को अपने गढ़े, किसी भाषा में न होने वाले नए नाम देता है। और ज़िद करता है कि आप भी वही शब्द बोलें! ग्रोथ ट्रैकर खोलिए और उसके इन मज़ेदार शब्दों को ज़रूर दर्ज कीजिए, ताकि आगे पढ़कर हँस सकें।', title_id = 'Penemuan kosakata baru 🗣️', body_id = 'Ia memberi benda-benda nama baru karangannya sendiri yang tidak ada dalam bahasa mana pun. Dan ia bersikeras Anda juga harus memakai kata itu! Buka Pelacak Perkembangan dan pastikan mencatat kata-kata lucunya agar kelak bisa dibaca sambil tertawa.', title_ja = '新しい言葉の発見 🗣️', body_ja = 'ものに、どの言語にもない自分で考えた新しい名前をつけている。しかも、あなたにもその言葉を使うよう強く求めてくる！「発達トラッカー」を開いて、このおかしな言葉を、将来読み返して笑えるようにぜひ記録しましょう。', title_ko = '새로운 어휘 발견 🗣️', body_ko = '어떤 언어에도 없는, 자기가 지어낸 새 이름을 물건에 붙이고 엄마도 그 말을 쓰라고 고집하나요! 성장 기록을 열고 나중에 읽으며 웃을 수 있게 이 웃긴 단어들을 꼭 기록해 두세요.', title_nl = 'Nieuwe woordontdekkingen 🗣️', body_nl = 'Hij geeft dingen nieuwe namen die hij zelf verzint en die in geen enkele taal bestaan. En hij wil per se dat jij die woorden ook gebruikt! Open de Groeitracker en leg deze grappige woorden zeker vast, zodat je ze later kunt teruglezen en erom kunt lachen.', title_pl = 'Nowe odkrycia słownikowe 🗣️', body_pl = 'Nadaje rzeczom zupełnie nowe, wymyślone nazwy, których nie ma w żadnym języku. I uparcie wymaga, żebyś też ich używała! Otwórz Śledzenie rozwoju i koniecznie zapisz te zabawne słowa, żeby kiedyś je przeczytać i się pośmiać.', title_pt = 'Novas descobertas no vocabulário 🗣️', body_pt = 'Dá às coisas nomes novos, inventados por ele, que não existem em língua nenhuma. E insiste que também os use! Abra o Registo de Crescimento e não deixe de registar estas palavras cómicas para as ler e rir no futuro.', title_sv = 'Nya ordupptäckter 🗣️', body_sv = 'Barnet ger saker helt egna, påhittade namn som inte finns på något språk. Och kräver envist att du också använder ordet! Öppna Utvecklingsspåraren och skriv absolut upp de roliga orden, så att ni kan läsa och skratta åt dem i framtiden.', title_vi = 'Khám phá từ vựng mới 🗣️', body_vi = 'Bé đặt cho đồ vật những cái tên mới hoàn toàn do mình nghĩ ra, chẳng có trong ngôn ngữ nào. Và còn bắt mẹ phải dùng những từ đó! Hãy mở Theo dõi phát triển và nhất định ghi lại những từ ngộ nghĩnh này để sau này đọc lại và bật cười.', title_zh = '新词汇大发现 🗣️', body_zh = '给东西起了完全是自己发明的、任何语言里都没有的新名字。还坚持要你也用那个词！打开发育追踪，一定要把这些搞笑的词记下来，将来读起来乐一乐。' WHERE id = '3cde3483-1ec6-4721-b8a3-2803d38e22f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los tesoros secretos de la casa 🔑', body_es = '¿No encuentras las llaves de casa o el mando? Mira dentro de su horno de juguete o debajo de su cama. Escondiendo cosas pone a prueba el universo. En esta cómica búsqueda del tesoro, elige reírte y respirar hondo en lugar de enfadarte.', title_fr = 'Les trésors cachés de la maison 🔑', body_fr = 'Vous ne trouvez plus les clés de la maison ou la télécommande ? Allez voir dans le four de sa dînette ou sous son lit. En cachant les objets, il teste l''univers. Dans cette chasse au trésor comique, choisissez de rire et de respirer profondément plutôt que de vous énerver.', title_hi = 'घर के छिपे खज़ाने 🔑', body_hi = 'घर की चाबियाँ या रिमोट नहीं मिल रहा? जाकर खिलौने वाले चूल्हे के अंदर या उसके बिस्तर के नीचे देखिए। चीज़ें छिपाकर वह दुनिया को परख रहा है। इस मज़ेदार खज़ाने की खोज में नाराज़ होने के बजाय हँसना और गहरी साँस लेना चुनिए।', title_id = 'Harta karun rahasia di rumah 🔑', body_id = 'Tidak bisa menemukan kunci rumah atau remote? Coba lihat di dalam oven mainan atau di bawah tempat tidurnya. Ia sedang menguji alam semesta dengan menyembunyikan benda. Dalam perburuan harta karun yang lucu ini, pilihlah tertawa dan menarik napas dalam daripada kesal.', title_ja = '家の中の秘密の宝物 🔑', body_ja = '家のカギやリモコンが見つからない？おもちゃのオーブンの中や、ベッドの下を見てみて。ものを隠しながら、世界を確かめているんです。このおかしな宝探しでは、イライラするより、笑って深呼吸することを選びましょう。', title_ko = '집 안의 숨은 보물 🔑', body_ko = '집 열쇠나 리모컨이 안 보이나요? 장난감 오븐 안이나 침대 밑을 확인해 보세요. 물건을 숨기며 세상을 시험하는 중이에요. 이 웃긴 보물찾기에서 화내는 대신 웃으며 깊게 숨 쉬는 쪽을 택하세요.', title_nl = 'De verborgen schatten van het huis 🔑', body_nl = 'Kun je je huissleutels of de afstandsbediening niet vinden? Kijk in zijn speelgoedoventje of onder zijn bed. Door dingen te verstoppen test hij het universum. Kies ervoor om te lachen en diep adem te halen in plaats van boos te worden tijdens deze grappige schattenjacht.', title_pl = 'Ukryte skarby domu 🔑', body_pl = 'Nie możesz znaleźć kluczy albo pilota? Zajrzyj do zabawkowego piekarnika albo pod jego łóżko. Chowając rzeczy, sprawdza wszechświat. W tym zabawnym poszukiwaniu skarbu zamiast się złościć, wybierz śmiech i głęboki oddech.', title_pt = 'Os tesouros escondidos da casa 🔑', body_pt = 'Não encontra as chaves de casa ou o comando? Vá ver dentro do fogão de brincar ou debaixo da cama dele. Ao esconder as coisas, está a testar o universo. Nesta caça ao tesouro cómica, em vez de se irritar, escolha rir e respirar fundo.', title_sv = 'Hemmets dolda skatter 🔑', body_sv = 'Hittar du inte husnycklarna eller fjärrkontrollen? Titta i leksaksspisen eller under barnets säng. Barnet testar universum genom att gömma saker. Välj att skratta och andas djupt istället för att bli arg i den här roliga skattjakten.', title_vi = 'Kho báu bí mật trong nhà 🔑', body_vi = 'Không tìm thấy chìa khóa nhà hay điều khiển? Hãy xem trong lò nướng đồ chơi hoặc dưới gầm giường của bé. Bé đang thử nghiệm vũ trụ bằng cách giấu đồ vật. Trong cuộc truy tìm kho báu hài hước này, hãy chọn cười và hít thở sâu thay vì bực mình.', title_zh = '家里的秘密宝藏 🔑', body_zh = '找不到家里的钥匙或遥控器？去玩具烤箱里或者床底下看看。宝宝在藏东西，测试这个宇宙。在这场搞笑的寻宝游戏里，选择笑一笑、深呼吸，而不是生气。' WHERE id = '50316f93-f1fa-4052-831d-66931b46940d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La paradoja del baño 🛀', body_es = '¡Lloraba porque no quería meterse en la bañera y ahora llora a gritos para no salir! El efecto mágico y relajante del agua le ha hipnotizado. Para no convertir la salida en un drama, llama a la toalla «abrazo calentito», envuélvele y sácale.', title_fr = 'Le paradoxe du bain 🛀', body_fr = 'Il pleurait parce qu''il ne voulait pas entrer dans le bain, et maintenant il hurle pour ne pas en sortir ! L''effet magique et apaisant de l''eau l''a hypnotisé. Pour ne pas dramatiser la sortie, appelez la serviette « un câlin tout chaud », enveloppez-le dedans et sortez-le.', title_hi = 'नहाने का विरोधाभास 🛀', body_hi = 'बाथटब में न जाने के लिए रो रहा था, और अब न निकलने के लिए चीख रहा है! पानी के जादुई, सुकून भरे असर ने उसे सम्मोहित कर दिया है। पानी से निकलने को नाटकीय न बनाने के लिए तौलिए को ‘गर्म झप्पी’ कहिए, उसमें लपेटिए और बाहर निकालिए।', title_id = 'Paradoks kamar mandi 🛀', body_id = 'Tadi ia menangis karena tidak mau masuk bak mandi, sekarang ia meraung tidak mau keluar! Efek air yang ajaib dan menenangkan telah menghipnotisnya. Agar keluar dari air tidak jadi drama, sebut handuk sebagai ''pelukan hangat'', bungkus ia, lalu angkat keluar.', title_ja = 'お風呂のパラドックス 🛀', body_ja = 'お風呂に入りたくないと泣いていたのに、今は出たくなくて大泣き！お湯の魔法のような心落ち着く力に、催眠術をかけられたんです。お湯から出るときにドラマにしないよう、タオルを「あったか抱っこ」と呼んで、くるんで出してあげましょう。', title_ko = '목욕의 역설 🛀', body_ko = '욕조에 들어가기 싫다고 울더니 이제는 안 나오겠다고 울부짖나요! 물의 마법 같은 진정 효과에 홀린 거예요. 나오는 순간을 극적으로 만들지 않도록 수건을 ''따뜻한 포옹''이라 부르며 감싸 안고 꺼내 주세요.', title_nl = 'De badparadox 🛀', body_nl = 'Hij huilde omdat hij niet in bad wilde, en nu krijst hij om er niet uit te hoeven! Het magische, kalmerende effect van het water heeft hem gehypnotiseerd. Maak geen drama van het uit bad gaan: noem de handdoek ''een warme knuffel'', wikkel hem erin en til hem eruit.', title_pl = 'Kąpielowy paradoks 🛀', body_pl = 'Płakał, bo nie chciał wejść do wanny, a teraz krzyczy, żeby z niej nie wychodzić! Magiczna, kojąca moc wody go zahipnotyzowała. Żeby wyjście z wody nie było dramatem, nazwij ręcznik „ciepłym uściskiem”, otul go nim i wyjmij.', title_pt = 'O paradoxo do banho 🛀', body_pt = 'Chorava porque não queria entrar na banheira e agora grita para não sair! O efeito mágico e calmante da água hipnotizou-o. Para não dramatizar a saída da água, chame à toalha "abraço quente", envolva-o nela e tire-o.', title_sv = 'Badparadoxen 🛀', body_sv = 'Barnet grät för att det inte ville i badet, och nu skriker det för att slippa gå upp! Vattnets magiska, lugnande effekt har hypnotiserat barnet. För att inte göra uppstigningen dramatisk, kalla handduken för ”en varm kram”, svep in barnet och lyft upp det.', title_vi = 'Nghịch lý phòng tắm 🛀', body_vi = 'Lúc nãy bé khóc vì không muốn vào bồn tắm, giờ lại gào lên không chịu ra! Tác dụng kỳ diệu, êm dịu của nước đã thôi miên bé. Để việc ra khỏi nước không thành "bi kịch", hãy gọi chiếc khăn tắm là "cái ôm ấm áp", quấn lấy bé và bế ra.', title_zh = '浴室悖论 🛀', body_zh = '刚才还哭着不肯进浴缸，现在却为了不出来大声哭喊！水那种神奇的安抚作用把宝宝“催眠”了。为了不把出浴变成一场大戏，把浴巾叫作“温暖的拥抱”，把宝宝裹起来抱出来吧。' WHERE id = 'e6c3f535-9f72-4297-8076-fd7145c977da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No hace falta ningún juego, libro con sonidos ni cuento. Esta noche simplemente abrázale contra tu pecho, respira hondo su olor limpio y susúrrale en la oscuridad lo valioso que es para ti y cuánto le quieres.', body_fr = 'Pas besoin de jeu, de livre sonore ni de conte. Ce soir, serrez-le simplement contre votre cœur, respirez profondément son odeur si pure et chuchotez-lui dans le noir combien il est précieux et combien vous l''aimez.', body_hi = 'किसी खेल, शोर वाली किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी साफ़ खुशबू गहरी-गहरी साँसों में भरिए और अँधेरे में उसके कान में फुसफुसाइए कि वह कितना कीमती है और आप उसे कितना प्यार करती हैं।', body_id = 'Tak perlu permainan, buku berbunyi, atau dongeng. Malam ini cukup peluk ia ke dada Anda, hirup dalam-dalam aromanya yang bersih, dan dalam gelap bisikkan betapa berharganya ia dan betapa Anda menyayanginya.', body_ja = '遊びも、にぎやかな絵本も、お話もいりません。今夜はただ胸に抱きしめて、その清らかなにおいを深く吸いこみ、暗やみの中で、この子がどれほど大切で、どれほど愛しているかをささやいてあげましょう。', body_ko = '놀이도, 시끄러운 책도, 동화도 필요 없어요. 오늘 저녁엔 그냥 꼭 안고 그 깨끗한 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한지, 얼마나 사랑하는지 속삭여 주세요.', body_nl = 'Geen spelletjes, lawaaiige boeken of sprookjes nodig. Druk hem vanavond gewoon tegen je aan, adem diep zijn zuivere geur in en fluister in het donker hoe kostbaar hij is en hoeveel je van hem houdt.', body_pl = 'Nie potrzeba żadnej zabawy, głośnej książeczki ani bajki. Dziś wieczorem po prostu przytul go do piersi, głęboko wdychaj jego czysty zapach i wyszeptaj mu w ciemności, jak bardzo jest cenny i jak bardzo go kochasz.', body_pt = 'Não precisa de brincadeiras, livros barulhentos nem histórias. Esta noite, aperte-o simplesmente contra o peito, respire fundo aquele cheirinho limpo e sussurre-lhe no escuro o quanto ele é precioso e o quanto o ama.', body_sv = 'Det behövs ingen lek, ingen bullrig bok eller saga. I kväll, tryck bara barnet mot bröstet, andas djupt in den rena doften och viska i mörkret hur värdefullt barnet är och hur mycket du älskar det.', body_vi = 'Không cần trò chơi, sách phát tiếng hay truyện cổ tích nào cả. Tối nay, chỉ cần ôm bé vào lòng, hít thật sâu mùi hương trong trẻo của bé và thì thầm trong bóng tối rằng bé quý giá biết bao, mẹ yêu bé nhường nào.', body_zh = '不需要任何游戏、吵闹的书或故事。今晚就把宝宝搂在怀里，深深地吸一口那份干净的气味，在黑暗中悄悄告诉宝宝，宝宝有多珍贵，你有多爱宝宝。' WHERE id = '1eb146d3-b624-4eb5-88ee-21bab3e1a546' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del «¡En el súper conduzco yo!» 🛒', body_es = 'Quiere empujar él solo el carro del súper y choca con las estanterías provocando un desastre. En lugar de que acabe llorando en público, deja que ponga las manos en el borde del carro y tú dirige a escondidas. Y lo que se te olvide, compruébalo en la Lista de la compra.', title_fr = 'L''entêtement du « C''est moi qui pousse ! » au supermarché 🛒', body_fr = 'Il veut pousser lui-même le chariot et provoque une catastrophe en heurtant les rayons. Plutôt que de le faire pleurer en public, laissez ses mains sur le bord du chariot et guidez discrètement la direction. Et pour ce que vous avez oublié, vérifiez la Liste de courses.', title_hi = 'बाज़ार में ‘मैं चलाऊँगा’ की ज़िद 🛒', body_hi = 'शॉपिंग ट्रॉली खुद चलाना चाहता है और रैक से टकराकर आफ़त मचाता है। लोगों के बीच रुलाने के बजाय, उसके हाथ ट्रॉली के किनारे पर रहने दीजिए और आप चुपके से दिशा देती रहिए। और जो भूल गईं, उसे शॉपिंग लिस्ट में जाँच लीजिए।', title_id = 'Ngotot ''Aku yang dorong!'' di supermarket 🛒', body_id = 'Ia ingin mendorong troli belanja sendiri dan menabrak rak hingga terjadi bencana. Daripada membuatnya menangis di depan umum, biarkan tangannya tetap di pinggir troli, sementara Anda diam-diam mengarahkannya. Barang yang terlupa, cek saja di Daftar Belanja.', title_ja = 'スーパーで「ぼくが押す」の意地 🛒', body_ja = 'ショッピングカートを自分で押したがって、棚にぶつかっては大騒ぎ。人前で泣かせるより、両手はカートのはしに置かせたまま、あなたがこっそり方向を決めてあげましょう。買い忘れは「買い物リスト」でチェックしてね。', title_ko = '마트에서 ''내가 밀 거야'' 고집 🛒', body_ko = '마트 카트를 자기가 밀겠다며 선반에 부딪혀 난리가 났나요? 사람들 앞에서 울리기보다 손은 카트 가장자리에 두게 하고 엄마가 몰래 방향을 잡아 주세요. 잊은 건 쇼핑 목록에서 확인하세요.', title_nl = '''Ik duw!''-koppigheid in de supermarkt 🛒', body_nl = 'Hij wil zelf het boodschappenkarretje duwen, botst tegen de schappen en veroorzaakt een ramp. Laat hem niet in het openbaar huilen, maar laat zijn handen op de rand van het karretje en stuur jij stiekem bij. En wat je vergeten bent, check je op het Boodschappenlijstje.', title_pl = 'Sklepowy upór „Ja będę pchać” 🛒', body_pl = 'Chce sam pchać wózek w sklepie i wpadając na półki, sieje spustoszenie. Zamiast doprowadzać go do płaczu przy ludziach, niech trzyma ręce na brzegu wózka, a ty dyskretnie nadawaj kierunek. A to, o czym zapomniałaś, sprawdź na Liście zakupów.', title_pt = 'A teimosia do "Eu é que conduzo" no supermercado 🛒', body_pt = 'Quer empurrar sozinho o carrinho do supermercado e provoca desastres ao bater nas prateleiras. Em vez de o fazer chorar em público, deixe as mãos dele na borda do carrinho e vá guiando a direção às escondidas. E o que se esqueceu, confirme na Lista de Compras.', title_sv = 'Envisheten ”Jag ska köra!” i butiken 🛒', body_sv = 'Barnet vill köra kundvagnen själv, krockar med hyllorna och ställer till med katastrof. Istället för att barnet ska gråta bland folk, låt barnets händer vara på vagnens kant medan du i smyg styr. Och det du glömt kollar du i Inköpslistan.', title_vi = '"Con đẩy xe!" ở siêu thị 🛒', body_vi = 'Bé muốn tự đẩy xe siêu thị và đâm vào kệ hàng gây "thảm họa". Thay vì để bé khóc giữa đám đông, hãy để tay bé đặt trên thành xe, còn mẹ khéo léo lái hướng. Còn những gì đã quên, hãy kiểm tra trong Danh sách mua sắm.', title_zh = '超市里“我来推”的倔强 🛒', body_zh = '非要自己推购物车，一路撞到货架上，闯下“大祸”。与其在大家面前把宝宝弄哭，不如让宝宝把手扶在车边，你悄悄地掌握方向。至于忘了的东西，就对照购物清单检查一下。' WHERE id = '39c13cd6-54ea-4fd8-a9da-7ceece969e6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos de los juguetes 🌪️', body_es = '¿Estás cansada de recoger los mismos juguetes cada día? ¡Hoy no los recojas! La casa no es un museo, es un lugar cálido lleno de vida donde crece un pequeño explorador. Descansa y céntrate no en el desorden, sino en la alegría de tu peque descubriendo con libertad.', title_fr = 'Le chaos des jouets 🌪️', body_fr = 'Fatiguée de ranger les mêmes jouets tous les jours ? Aujourd''hui, ne rangez pas ! La maison n''est pas un musée, c''est un lieu chaleureux où la vie bouillonne et où grandit un petit explorateur. Concentrez-vous non pas sur le désordre, mais sur la joie de votre enfant qui découvre librement, et reposez-vous.', title_hi = 'खिलौनों की अफ़रा-तफ़री 🌪️', body_hi = 'रोज़ वही खिलौने समेटते-समेटते थक गई हैं? आज मत समेटिए! घर कोई म्यूज़ियम नहीं, ज़िंदगी से भरी, एक नन्हे खोजी के बड़े होने की गर्म जगह है। बिखराव पर नहीं, बच्चे की आज़ादी से खोजने की खुशी पर ध्यान दीजिए और आराम कीजिए।', title_id = 'Kekacauan mainan 🌪️', body_id = 'Lelah membereskan mainan yang sama setiap hari? Hari ini jangan dibereskan! Rumah bukan museum, melainkan tempat hangat yang penuh kehidupan, tempat seorang penjelajah kecil tumbuh. Fokuslah pada kebahagiaan anak Anda menjelajah dengan bebas, bukan pada kekacauannya, dan beristirahatlah.', title_ja = 'おもちゃのカオス 🌪️', body_ja = '毎日同じおもちゃを片づけるのに疲れましたか？今日は片づけないで！家は博物館ではなく、暮らしがあふれ、小さな探検家が育つあたたかな場所です。散らかりではなく、お子さんが自由に発見する喜びに目を向けて、ひと休みしましょう。', title_ko = '장난감 혼돈 🌪️', body_ko = '매일 같은 장난감을 치우는 데 지쳤나요? 오늘은 치우지 마세요! 집은 박물관이 아니라 삶이 살아 숨 쉬고 작은 탐험가가 자라는 따뜻한 곳이에요. 어질러진 것 말고 아이가 자유롭게 탐험하는 기쁨에 집중하며 쉬세요.', title_nl = 'Speelgoedchaos 🌪️', body_nl = 'Ben je het moe om elke dag hetzelfde speelgoed op te ruimen? Ruim vandaag niet op! Je huis is geen museum, maar een warme plek vol leven waar een kleine ontdekkingsreiziger opgroeit. Focus niet op de rommel, maar op het plezier van je kind dat vrij ontdekt, en ontspan.', title_pl = 'Zabawkowy chaos 🌪️', body_pl = 'Masz dość codziennego zbierania tych samych zabawek? Dziś nie sprzątaj! Dom to nie muzeum, tylko ciepłe miejsce, w którym tętni życie i dorasta mały odkrywca. Skup się nie na bałaganie, a na radości swobodnego odkrywania dziecka, i odpocznij.', title_pt = 'O caos dos brinquedos 🌪️', body_pt = 'Está cansada de arrumar os mesmos brinquedos todos os dias? Hoje não arrume! A casa não é um museu, é um lugar quente, cheio de vida, onde cresce um pequeno explorador. Concentre-se não na desarrumação, mas na alegria do seu filho a descobrir em liberdade, e descanse.', title_sv = 'Leksakskaos 🌪️', body_sv = 'Är du trött på att plocka upp samma leksaker varje dag? Plocka inte upp i dag! Hemmet är inget museum, det är en varm plats som sjuder av liv, där en liten upptäcktsresande växer upp. Fokusera inte på stöket utan på barnets glädje i att upptäcka fritt, och vila.', title_vi = 'Hỗn loạn đồ chơi 🌪️', body_vi = 'Mẹ đã mệt vì ngày nào cũng dọn đúng những món đồ chơi ấy? Hôm nay đừng dọn! Nhà không phải là bảo tàng, mà là nơi ấm áp, sôi động, nơi một nhà thám hiểm nhỏ đang lớn lên. Hãy nghỉ ngơi, tập trung vào niềm vui được tự do khám phá của bé chứ không phải sự bừa bộn.', title_zh = '玩具大混乱 🌪️', body_zh = '每天收拾同样的玩具，收得累坏了？今天就别收了！家不是博物馆，而是充满生活气息、一个小探险家正在长大的温暖地方。别盯着乱，把注意力放在孩子自由探索的快乐上，好好休息吧。' WHERE id = 'dcf51c40-2de5-47dc-a87f-c99740f37d0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Le encanta andar descalzo y tocar la alfombra, las piedras de la habitación o las baldosas frías. Estimular los nervios de la planta del pie es muy importante para su equilibrio y su desarrollo neurológico: no le impidas de ninguna manera andar sin calcetines.', body_fr = 'Il adore marcher pieds nus et toucher le tapis, les cailloux ou le carrelage froid. L''éveil des nerfs de la plante des pieds est très important pour son équilibre et son développement neurologique, ne l''empêchez surtout pas de marcher sans chaussettes.', body_hi = 'नंगे पैर चलने, कालीन, कमरे के पत्थरों या ठंडी टाइलों को छूने में उसे मज़ा आता है। तलवों की नसों का जागना उसके संतुलन और तंत्रिका विकास के लिए बहुत ज़रूरी है, उसे बिना मोज़ों के चलने से बिल्कुल मत रोकिए।', body_id = 'Ia senang berjalan tanpa alas kaki, menyentuh karpet, batu-batu di kamar, atau ubin yang dingin. Rangsangan saraf di telapak kaki sangat penting untuk keseimbangan dan perkembangan sarafnya, jangan sekali-kali melarangnya berjalan tanpa kaus kaki.', body_ja = 'はだしで歩いて、じゅうたんや部屋の石、冷たいタイルにふれるのが大好き。足の裏の神経が目覚めることは、バランスと神経の発達にとってとても大切です。靴下なしで歩くのを、決してじゃましないで。', body_ko = '맨발로 걸으며 카펫, 방의 돌, 차가운 타일을 만지는 걸 좋아하나요? 발바닥 신경을 깨우는 건 균형 감각과 신경 발달에 아주 중요해요. 양말 없이 걷는 걸 절대 막지 마세요.', body_nl = 'Hij geniet ervan om op blote voeten te lopen en het tapijt, de steentjes of de koude tegels te voelen. Het prikkelen van de zenuwen onder zijn voeten is heel belangrijk voor zijn evenwicht en neurologische ontwikkeling, houd hem dus zeker niet tegen als hij zonder sokken wil lopen.', body_pl = 'Uwielbia chodzić boso, dotykać dywanu, kamyków na podłodze i zimnych kafelków. Pobudzanie nerwów na stopach jest bardzo ważne dla jego równowagi i rozwoju neurologicznego, nie przeszkadzaj mu chodzić bez skarpetek.', body_pt = 'Adora andar descalço e tocar no tapete, nas pedras do quarto ou no azulejo frio. Estimular os nervos da planta dos pés é muito importante para o equilíbrio e o desenvolvimento neurológico: não o impeça de andar sem meias.', body_sv = 'Barnet njuter av att gå barfota och känna mattan, stenarna i rummet eller det kalla kaklet under fötterna. När nerverna under fötterna väcks är det väldigt viktigt för balansen och den neurologiska utvecklingen, hindra absolut inte barnet från att gå utan strumpor.', body_vi = 'Bé thích đi chân trần, cảm nhận tấm thảm, những viên sỏi hay sàn gạch mát lạnh. Việc kích thích các dây thần kinh ở lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng và sự phát triển thần kinh của bé, tuyệt đối đừng ngăn bé đi không tất.', body_zh = '喜欢光着脚走路，喜欢触摸地毯、房间里的石头和冰凉的瓷砖。脚底神经被唤醒，对宝宝的平衡和神经发展非常重要，千万别阻止宝宝不穿袜子走路。' WHERE id = '7f0898f3-4281-4b25-877c-f3060088913f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, solución real 🤖', body_es = '¿Te ha asustado que tu peque reaccione de forma exagerada a todo? Olvida los artículos traumatizantes de internet. Pregunta a Anacan AI si es solo una reacción pasajera al estrés, obtén una respuesta científica avalada por pediatras y tranquilízate.', title_fr = 'Intelligence artificielle, vraie solution 🤖', body_fr = 'Les réactions vives de votre enfant à tout vous ont fait peur ? Oubliez les articles traumatisants d''Internet. Demandez à Anacan AI s''il s''agit simplement d''une réaction passagère au stress et rassurez-vous avec une réponse scientifique, validée par des pédiatres.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, असली हल 🤖', body_hi = 'बच्चे की हर बात पर तीखी प्रतिक्रिया ने आपको डरा दिया? इंटरनेट के परेशान करने वाले लेख भूल जाइए। Anacan AI से पूछिए कि क्या यह बस एक अस्थायी तनाव की प्रतिक्रिया है, और वैज्ञानिक, बाल रोग विशेषज्ञ द्वारा पुष्ट जवाब पाकर निश्चिंत हो जाइए।', title_id = 'Kecerdasan buatan, solusi nyata 🤖', body_id = 'Reaksinya yang tajam terhadap segala hal membuat Anda takut? Lupakan artikel traumatis di internet. Tanyakan pada Anacan AI apakah ini hanya reaksi stres sementara, dapatkan jawaban ilmiah yang disetujui dokter anak, dan tenanglah.', title_ja = 'AI、リアルな解決策 🤖', body_ja = 'お子さんが何にでも激しく反応するのが心配になりましたか？ネットのショッキングな記事は忘れましょう。Anacan AIに、一時的なストレス反応かどうかをたずねて、科学的で小児科医も認める答えをもらって安心しましょう。', title_ko = '인공지능, 진짜 해결책 🤖', body_ko = '아이가 모든 일에 격하게 반응해서 겁이 났나요? 인터넷의 충격적인 글은 잊으세요. Anacan AI에게 그저 일시적인 스트레스 반응인지 물어보고, 과학적이고 소아과 의사가 확인한 답으로 마음을 놓으세요.', title_nl = 'Kunstmatige intelligentie, echte oplossing 🤖', body_nl = 'Schrok je ervan dat je kind overal heftig op reageert? Vergeet de traumatiserende artikelen op internet. Vraag Anacan AI of het gewoon een tijdelijke stressreactie is en kom tot rust met een wetenschappelijk, door kinderartsen bevestigd antwoord.', title_pl = 'Sztuczna inteligencja, prawdziwe rozwiązanie 🤖', body_pl = 'Przestraszyło cię, że dziecko na wszystko reaguje gwałtownie? Zapomnij o traumatyzujących artykułach z internetu. Zapytaj Anacan AI, czy to tylko przejściowa reakcja na stres, i uspokój się dzięki naukowej, potwierdzonej przez pediatrów odpowiedzi.', title_pt = 'Inteligência artificial, solução real 🤖', body_pt = 'Assustou-se por ele reagir a tudo de forma tão intensa? Esqueça os artigos traumatizantes da internet. Pergunte ao Anacan AI se é apenas uma reação passageira ao stress e fique tranquila com uma resposta científica, validada por pediatras.', title_sv = 'Artificiell intelligens, riktig lösning 🤖', body_sv = 'Blev du rädd för att barnet reagerar så kraftigt på allt? Glöm traumatiska artiklar på nätet. Fråga Anacan AI om det bara är en övergående stressreaktion och slappna av med ett vetenskapligt, barnläkargodkänt svar.', title_vi = 'Trí tuệ nhân tạo, giải pháp thật 🤖', body_vi = 'Việc bé phản ứng gay gắt với mọi thứ khiến mẹ lo sợ? Hãy quên những bài viết gây hoang mang trên mạng. Hãy hỏi Anacan AI xem đó có phải chỉ là phản ứng căng thẳng tạm thời không và yên tâm với câu trả lời khoa học, được bác sĩ nhi khoa xác nhận.', title_zh = '人工智能，真实的解决办法 🤖', body_zh = '孩子对什么都反应激烈，把你吓到了？忘掉网上那些让人焦虑的文章。问问Anacan AI，这是否只是一种暂时的压力反应，得到科学、经儿科医生认可的答案，放下心来。' WHERE id = 'a17ad881-1738-43fa-b18c-dd0c7b263be1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro y sin tecnología, y asegura el paso al sueño.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans le noir et sans écran, ce qui assure le passage au sommeil.', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है और नींद में जाना पक्का करता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi, sehingga peralihan ke tidur lebih terjamin.', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は暗くてデジタル機器のない環境でこそすばやく分泌され、眠りへの切りかえを確かなものにしてくれます。', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어둡고 기기가 없는 환경에서만 빠르게 분비되어 잠으로 넘어가는 걸 도와줘요.', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen in een donkere omgeving zonder technologie snel aangemaakt en zorgt voor een soepele overgang naar de slaap.', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu bez technologii i zapewnia płynne przejście w sen.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro e sem tecnologia, o que garante a passagem para o sono.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk och teknikfri miljö och säkrar övergången till sömn.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ, giúp bé vào giấc trọn vẹn.', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素（睡眠激素）只有在昏暗、没有电子产品的环境里才会快速分泌，让入睡更有保障。' WHERE id = '602df0e4-a84c-493f-a594-485626339a2a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cuáles son los saltos de desarrollo cerca de los 40 meses? ¿Qué debería saber hacer? Echa un vistazo a los blogs de desarrollo de la app, mira lo avanzado que va tu peque en comprensión y lógica, y alégrate por dentro.', body_fr = 'Quels sont les bonds de développement à l''approche du 40e mois ? Que doit-il savoir faire ? Parcourez les blogs sur le développement dans l''application, et réjouissez-vous en secret de voir combien votre enfant est en avance en compréhension et en logique.', body_hi = '40वें महीने के करीब बच्चे के विकास में कौन-सी छलाँगें आती हैं? उसे क्या-क्या आना चाहिए? ऐप के विकास वाले ब्लॉग देखिए और जानकर मन ही मन खुश होइए कि आपका बच्चा समझ और तर्क में कितना आगे है।', body_id = 'Apa saja lompatan perkembangan anak menjelang bulan ke-40? Apa yang seharusnya sudah bisa ia lakukan? Lihat blog perkembangan di aplikasi, dan bergembiralah dalam hati melihat betapa majunya anak Anda dalam pemahaman dan logika.', body_ja = '40か月ごろの発達の飛躍にはどんなものがある？何ができるようになるの？アプリの発達ブログをのぞいてみて、お子さんが理解力や論理の面でどれほど成長しているかを知って、心の中で喜びましょう。', body_ko = '40개월 무렵의 발달 도약은 무엇일까요? 무엇을 할 수 있어야 할까요? 앱의 발달 블로그를 살펴보고, 우리 아이가 이해력과 논리에서 얼마나 앞서 있는지 보며 속으로 기뻐하세요.', body_nl = 'Welke ontwikkelingssprongen maakt je kind rond de 40e maand? Wat zou hij moeten kunnen? Kijk in de ontwikkelingsblogs in de app, zie hoe ver je kind al is in begrip en logica, en wees stiekem blij.', body_pl = 'Jakie skoki rozwojowe czekają dziecko w okolicach 40. miesiąca? Co powinno już umieć? Zajrzyj do artykułów o rozwoju na Blogu w aplikacji, zobacz, jak bardzo twoje dziecko wyprzedza w rozumieniu i logice, i ciesz się w duchu.', body_pt = 'Quais são os saltos de desenvolvimento perto dos 40 meses? O que deve saber fazer? Espreite os artigos sobre desenvolvimento no Blogue da app, veja como o seu filho está adiantado na compreensão e na lógica e alegre-se por dentro.', body_sv = 'Vilka utvecklingssprång gör barnet runt 40 månader? Vad ska barnet kunna? Titta i utvecklingsbloggarna i appen, se hur långt fram barnet ligger i uppfattning och logik och gläds inombords.', body_vi = 'Gần 40 tháng, bé có những bước nhảy vọt phát triển nào? Bé nên làm được gì? Hãy xem các bài viết về phát triển trong Blog của ứng dụng và thầm vui khi thấy bé nhà mình tiến bộ thế nào về nhận thức và tư duy logic.', body_zh = '快40个月时，孩子有哪些发育飞跃？应该会做什么？看看应用里的发育博客，你会发现孩子在认知和逻辑上进步了多少，在心里偷偷高兴一下吧。' WHERE id = '871e1c8b-981d-456b-8f8e-49b3f9df1255' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final de las frases a medias 🗣️', body_es = 'Cuando olvida una palabra hace gestos con las manos, frunce el ceño y espera que la adivines. Cuando completes su frase con paciencia, fíjate en ese alivio de «¡sí, eso es lo que decía!» en su cara. Su única traductora eres tú.', title_fr = 'La fin des phrases inachevées 🗣️', body_fr = 'Quand il oublie un mot, il fait des gestes, fronce les sourcils et attend que vous trouviez. Quand vous finissez patiemment sa phrase, observez ce soulagement sur son visage : « Oui, c''est exactement ça ! » Vous êtes sa seule traductrice.', title_hi = 'अधूरे वाक्यों का अंत 🗣️', body_hi = 'कोई शब्द भूल जाने पर हाथ से इशारे करके, भौंहें चढ़ाकर आपके समझने का इंतज़ार करता है। जब आप धैर्य से उसका वाक्य पूरा करती हैं, तो उसके चेहरे पर आई ‘हाँ, यही कह रहा था’ वाली राहत देखिए। उसकी अनुवादक सिर्फ़ आप हैं।', title_id = 'Ujung kalimat yang menggantung 🗣️', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan, mengerutkan alis, dan menunggu Anda menebak. Saat Anda dengan sabar melengkapi kalimatnya, perhatikan rasa lega di wajahnya: ''Iya, itu maksudku!''. Hanya Anda penerjemahnya.', title_ja = '途中の言葉の続き 🗣️', body_ja = '言葉を忘れると、手でジェスチャーをして眉をしかめ、あなたが当てるのを待っています。根気よく文を完成させてあげたときの、「そう、それが言いたかったの」というほっとした顔を見てあげて。この子の通訳は、あなただけです。', title_ko = '끝맺지 못한 문장의 끝 🗣️', body_ko = '단어가 생각 안 나면 손짓하고 눈살을 찌푸리며 엄마가 맞혀 주길 기다리나요? 문장을 인내심 있게 완성해 줄 때 아이 얼굴에 떠오르는 ''맞아, 그거야!'' 하는 안도감을 지켜보세요. 아이의 통역사는 엄마뿐이에요.', title_nl = 'Halve zinnen afmaken 🗣️', body_nl = 'Vergeet hij een woord, dan maakt hij gebaren, fronst hij en wacht hij tot jij het raadt. Kijk naar die opluchting op zijn gezicht als jij geduldig zijn zin afmaakt: ''Ja, dát bedoelde ik!'' Alleen jij bent zijn tolk.', title_pl = 'Koniec niedokończonych zdań 🗣️', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami, marszczy brwi i czeka, aż zgadniesz. Gdy cierpliwie dokończysz jego zdanie, zobacz tę ulgę na jego twarzy: „Aaa, właśnie o to mi chodziło”. Tylko ty jesteś jego tłumaczką.', title_pt = 'O final das frases a meio 🗣️', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos, franze a testa e espera que a adivinhe. Quando completa a frase com paciência, repare no alívio na cara dele: "Ah, é isso mesmo que eu queria dizer". Só a mãe é a tradutora dele.', title_sv = 'Slutet på de halva meningarna 🗣️', body_sv = 'När barnet glömmer ett ord gör det tecken med händerna, rynkar pannan och väntar på att du ska gissa. När du tålmodigt fyller i meningen, lägg märke till lättnaden i barnets ansikte: ”Jaa, det var precis det jag menade.” Du är barnets enda tolk.', title_vi = 'Hoàn thành câu nói dở 🗣️', body_vi = 'Khi quên một từ, bé ra hiệu bằng tay, nhíu mày và chờ mẹ đoán. Hãy để ý vẻ nhẹ nhõm "À, đúng cái đó đấy" trên gương mặt bé khi mẹ kiên nhẫn nói nốt câu giúp bé. Mẹ là "phiên dịch viên" duy nhất của bé.', title_zh = '补完半句话 🗣️', body_zh = '忘了某个词时，就用手比画、皱着眉，等你猜出来。当你耐心地帮宝宝把句子补完时，看看宝宝脸上那种“对，我就是想说这个”的如释重负吧。宝宝唯一的翻译官就是你。' WHERE id = 'dc309f01-53dd-4d8e-b0a5-566a9cb979d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El síndrome del hambre repentina 🥱', body_es = 'Justo al meterse en la cama dice «mamá, tengo hambre» y quiere correr a la cocina. ¡Una obra maestra para retrasar el sueño! Elige en el Plan de alimentación un pequeño tentempié de noche que dé sueño y desactiva esta excusa de antemano.', title_fr = 'Le syndrome de la faim soudaine 🥱', body_fr = 'Juste au moment d''aller au lit, il dit « Maman, j''ai faim » et veut courir à la cuisine. Un chef-d''œuvre pour retarder le coucher ! Choisissez dans le Plan de nutrition une petite collation du soir qui favorise le sommeil pour désamorcer cette excuse à l''avance.', title_hi = 'अचानक ‘भूख’ का सिंड्रोम 🥱', body_hi = 'ठीक बिस्तर में जाते ही ‘माँ, मुझे भूख लगी है’ कहकर रसोई भागना चाहता है। नींद टालने की यह बेमिसाल कला है! फ़ीडिंग प्लान में शाम के लिए नींद लाने वाला छोटा स्नैक चुनकर इस बहाने को पहले ही खत्म कर दीजिए।', title_id = 'Sindrom lapar mendadak 🥱', body_id = 'Tepat saat naik ke tempat tidur, ia berkata ''Ma, aku lapar'' dan ingin lari ke dapur. Mahakarya untuk menunda tidur! Pilih camilan kecil pengundang kantuk untuk malam hari di Rencana Nutrisi, dan patahkan alasan ini sejak awal.', title_ja = 'とつぜんの「おなかすいた」症候群 🥱', body_ja = 'ちょうどベッドに入ったところで「ママ、おなかすいた」とキッチンへ走ろうとする。寝る時間を遅らせる傑作です！「栄養管理ツール」で、夜に眠りをさそう小さなおやつを選んで、この言いわけを前もってつぶしておきましょう。', title_ko = '갑작스러운 ''배고파'' 증후군 🥱', body_ko = '침대에 눕자마자 ''엄마, 배고파'' 하며 부엌으로 달려가려 하나요? 잠을 미루는 데는 최고의 작품이죠! 식단 계획에서 저녁에 먹을 잠이 오는 작은 간식을 골라 이 핑계를 미리 막아 두세요.', title_nl = 'Het plotselinge hongersyndroom 🥱', body_nl = 'Net als hij in bed ligt, zegt hij ''Mama, ik heb honger'' en wil hij naar de keuken. Een meesterwerk om het slapen uit te stellen! Kies in het Voedingsplan een klein, slaapbevorderend avondsnackje en ontkracht dit excuus van tevoren.', title_pl = 'Nagły „głód” 🥱', body_pl = 'Gdy tylko kładzie się do łóżka, mówi „Mamo, jestem głodny” i chce biec do kuchni. Mistrzowski sposób na opóźnienie snu! Wybierz w planie karmienia małą wieczorną przekąskę sprzyjającą zasypianiu i z góry zneutralizuj tę wymówkę.', title_pt = 'A síndrome da fome repentina 🥱', body_pt = 'Mal se deita na cama, diz "mãe, tenho fome" e quer correr para a cozinha. Uma obra-prima para adiar o sono! Escolha no Registo de Alimentação um pequeno snack para a noite que ajude a dormir e anule esta desculpa com antecedência.', title_sv = 'Det plötsliga hungersyndromet 🥱', body_sv = 'Precis när barnet kommer i säng säger det ”Mamma, jag är hungrig” och vill springa till köket. Ett mästerverk i att skjuta upp sömnen! Välj ett litet sömngivande kvällsmellanmål i matplanen och nollställ ursäkten i förväg.', title_vi = 'Hội chứng "đói bất chợt" 🥱', body_vi = 'Đúng lúc lên giường, bé nói "Mẹ ơi, con đói" và đòi chạy vào bếp. Đây là kiệt tác để trì hoãn giấc ngủ! Hãy chọn trong Kế hoạch dinh dưỡng một món ăn nhẹ buổi tối giúp dễ ngủ để vô hiệu hóa lý do này từ trước.', title_zh = '突发“饥饿综合征” 🥱', body_zh = '刚上床就喊“妈妈，我饿了”，想往厨房跑。这是拖延睡觉的杰作！在喂养计划里给晚上选一份助眠的小零食，提前让这个借口失效。' WHERE id = '35170eca-5526-4a79-8f60-bb6c6204b11e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El chantaje de «me duelen las piernas» 🚶‍♂️', body_es = '¿Andando por la calle se deja caer de repente al suelo y dice «se me han roto las piernas, cógeme en brazos»? No es cansancio físico, es pura manipulación a mamá. Conviértelo en un juego: «¿A ver quién llega antes a casa saltando como un conejo?».', title_fr = 'Le chantage du « J''ai mal aux jambes » 🚶‍♂️', body_fr = 'En marchant dans la rue, il s''effondre soudain par terre : « J''ai les jambes cassées, porte-moi » ? Ce n''est pas de la fatigue physique, c''est de la pure manipulation de maman. Transformez ça en jeu : « Voyons qui rentrera le plus vite à la maison en sautant comme un lapin ! »', title_hi = '‘मेरे पैर थक गए’ वाला ब्लैकमेल 🚶‍♂️', body_hi = 'सड़क पर चलते-चलते अचानक बैठ जाता है और कहता है, ‘मेरे पैर टूट गए, मुझे गोद लो’? यह शारीरिक थकान नहीं, बस माँ को मनाने की चाल है। खेल बना दीजिए: ‘देखें, घर तक खरगोश की तरह सबसे पहले कौन कूदकर पहुँचता है?’', title_id = 'Pemerasan ''Kakiku capek'' 🚶‍♂️', body_id = 'Saat berjalan di jalan, ia tiba-tiba ambruk ke tanah dan berkata ''Kakiku patah, gendong aku''? Ini bukan lelah fisik, murni memanipulasi ibunya. Jadikan permainan: ''Ayo lihat siapa yang paling cepat melompat seperti kelinci sampai rumah!''', title_ja = '「足が疲れた」の駆け引き 🚶‍♂️', body_ja = '歩いている途中で急にしゃがみこんで「足がこわれた、抱っこして」と言う？これは体の疲れではなく、ママを動かそうとしているだけ。遊びに変えましょう：「おうちまで、ウサギみたいにどっちが早くはねられるかな？」', title_ko = '''다리 아파'' 작전 🚶‍♂️', body_ko = '길을 걷다 갑자기 주저앉아 ''다리 부러졌어, 안아 줘''라고 하나요? 몸이 지친 게 아니라 순전히 엄마를 움직이려는 작전이에요. 놀이로 바꿔 보세요: ''집까지 누가 토끼처럼 더 빨리 뛰어가나 볼까?''', title_nl = 'De ''Mijn benen zijn moe''-chantage 🚶‍♂️', body_nl = 'Zakt hij tijdens het lopen op straat ineens op de grond: ''Mijn benen zijn kapot, til me op''? Dat is geen lichamelijke vermoeidheid, maar pure manipulatie van mama. Maak er een spel van: ''Wie huppelt er als een konijn het snelst naar huis?''', title_pl = 'Szantaż „Nogi mnie bolą” 🚶‍♂️', body_pl = 'Idąc ulicą, nagle siada na ziemi i mówi „Nogi mi się połamały, weź mnie na ręce”? To nie fizyczne zmęczenie, tylko czysta manipulacja mamą. Zamień to w zabawę: „Zobaczmy, kto szybciej doskacze do domu jak zajączek?”.', title_pt = 'A chantagem do "Tenho as pernas cansadas" 🚶‍♂️', body_pt = 'A andar na rua, deixa-se cair de repente no chão e diz "as minhas pernas partiram-se, pega-me ao colo"? Não é cansaço físico, é pura manipulação da mãe. Transforme-o num jogo: "Vamos ver quem chega primeiro a casa aos saltos como um coelho?"', title_sv = 'Utpressningen ”Benen är trötta” 🚶‍♂️', body_sv = 'Sjunker barnet plötsligt ihop på gatan och säger ”benen gick sönder, bär mig”? Det är inte fysisk trötthet, det är ren manipulation av mamma. Gör det till en lek: ”Får se vem som hoppar snabbast hem som en kanin?”', title_vi = 'Màn "mặc cả" chân mỏi 🚶‍♂️', body_vi = 'Đang đi ngoài đường, bé bỗng ngồi phịch xuống và nói "Chân con gãy rồi, mẹ bế con đi"? Đây không phải mệt thể chất, mà chỉ là cách "điều khiển" mẹ. Hãy biến nó thành trò chơi: "Xem ai nhảy về nhà như thỏ nhanh hơn nào?".', title_zh = '“我腿累了”的要挟 🚶‍♂️', body_zh = '走在街上突然蹲坐在地上：“我的腿断了，抱我”？这不是身体累了，纯粹是在“操控”妈妈。把它变成游戏：“看谁能像小兔子一样先跳到家？”' WHERE id = 'a52300ac-c13a-4b61-bfa8-c7cb27b41cfa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El botón de reinicio de mamá 🚪', body_es = 'El ruido te taladra el cerebro y te dan ganas de gritar por todo. Abre el Diario de ánimo. Escribe ahí libremente todo tu agotamiento. Esta breve terapia digital te volverá a reiniciar.', title_fr = 'Le bouton reset de maman 🚪', body_fr = 'Le bruit vous transperce le cerveau, vous avez envie de crier sur tout. Ouvrez le Journal d''humeur. Écrivez-y librement tout votre épuisement. Cette courte thérapie numérique vous remettra à zéro.', title_hi = 'माँ का रीसेट बटन 🚪', body_hi = 'शोर दिमाग में चुभ रहा है, हर बात पर चिल्लाने का मन है। मूड डायरी खोलिए। अपनी सारी थकान खुलकर वहाँ लिखिए। यह छोटी डिजिटल थेरेपी आपको फिर से रीसेट कर देगी।', title_id = 'Tombol reset Ibu 🚪', body_id = 'Kebisingan menembus otak Anda, Anda ingin berteriak pada segala hal. Buka Buku Harian Suasana Hati. Tuliskan semua rasa lelah Anda di sana dengan bebas. Terapi digital singkat ini akan me-reset Anda kembali.', title_ja = 'ママのリセットボタン 🚪', body_ja = '騒がしさが頭に突きささり、何にでも叫びたくなる。「気分日記」を開きましょう。疲れきった気持ちを全部自由に書きだして。この短いデジタルセラピーが、あなたをもう一度リセットしてくれます。', title_ko = '엄마의 리셋 버튼 🚪', body_ko = '소음이 머리를 뚫고 모든 것에 소리치고 싶나요? 기분 일기를 열고 지친 마음을 자유롭게 적어 보세요. 이 짧은 디지털 치료가 엄마를 다시 리셋해 줄 거예요.', title_nl = 'Mama''s resetknop 🚪', body_nl = 'Het lawaai boort door je hoofd en je wilt tegen alles schreeuwen. Open je Stemmingsdagboek. Schrijf daar vrijuit al je uitputting op. Deze korte digitale therapie zet je weer op reset.', title_pl = 'Przycisk reset dla mamy 🚪', body_pl = 'Hałas świdruje ci w głowie, chce ci się krzyczeć na wszystko. Otwórz Dziennik nastroju. Wypisz tam swobodnie całe swoje wyczerpanie. Ta krótka cyfrowa terapia znów cię zresetuje.', title_pt = 'O botão Reset da mãe 🚪', body_pt = 'O barulho fura-lhe o cérebro e apetece-lhe gritar com tudo. Abra o Diário de Humor. Escreva lá à vontade todo o seu esgotamento. Esta curta terapia digital vai fazer-lhe um reset.', title_sv = 'Mammas återställningsknapp 🚪', body_sv = 'Oljudet borrar sig in i hjärnan och du vill skrika åt allt. Öppna Humördagboken. Skriv fritt ner all din utmattning där. Den här korta digitala terapin återställer dig igen.', title_vi = 'Nút "Reset" của mẹ 🚪', body_vi = 'Tiếng ồn như khoan vào đầu, mẹ muốn hét lên với mọi thứ. Hãy mở Nhật ký tâm trạng. Viết thoải mái mọi kiệt sức của mình vào đó. Liệu pháp số ngắn ngủi này sẽ giúp mẹ "khởi động lại".', title_zh = '妈妈的“重启”按钮 🚪', body_zh = '噪音快把脑袋钻穿了，你看什么都想吼。打开心情日记，把所有的疲惫都自由地写进去。这短短的数字疗愈，会帮你重新“重启”。' WHERE id = 'ed5f6008-15d7-44f7-a33c-21fd4bedec89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del «¡Es mío!» 🧸', body_es = 'Abraza cualquier objeto de la casa, grita «¡esto es mío!» y no se lo da a nadie. Está descubriendo los límites de la propiedad. No le acuses de egoísta: simplemente deja que ese objeto sea suyo en ese momento.', title_fr = 'L''entêtement du « C''est à moi ! » 🧸', body_fr = 'Il serre dans ses bras un objet quelconque de la maison en criant « C''est à moi ! » et ne le donne à personne. Il découvre les limites de la propriété. Ne l''accusez pas d''égoïsme, laissez-lui simplement cet objet pour le moment.', title_hi = '‘मेरा है!’ की ज़िद 🧸', body_hi = 'घर की कोई भी चीज़ गले लगाकर ‘यह मेरा है!’ चिल्लाता है और किसी को नहीं देता। वह अपनी चीज़ों की सीमाएँ खोज रहा है। उसे स्वार्थी मत कहिए, बस उस पल के लिए वह चीज़ उसकी मान लीजिए।', title_id = 'Ngotot ''Punyaku!'' 🧸', body_id = 'Ia memeluk benda apa saja di rumah sambil berteriak ''Ini punyaku!'' dan tidak mau memberikannya kepada siapa pun. Ia sedang menemukan batas kepemilikan. Jangan menuduhnya egois, biarkan saja benda itu menjadi miliknya untuk saat itu.', title_ja = '「ぼくの！」の意地 🧸', body_ja = '家にある適当なものを抱きかかえて「これ、ぼくの！」と叫び、誰にも渡さない。自分のものという境界を発見しているんです。わがままだと責めずに、そのときだけはそれをこの子のものにしてあげましょう。', title_ko = '''내 거야!'' 고집 🧸', body_ko = '집 안의 아무 물건이나 끌어안고 ''이건 내 거야!''라고 소리치며 아무에게도 주지 않나요? 소유의 경계를 발견하는 중이에요. 이기적이라고 탓하지 말고 그 순간만큼은 그 물건을 아이 것으로 인정해 주세요.', title_nl = 'De ''Van mij!''-koppigheid 🧸', body_nl = 'Hij knuffelt een willekeurig ding in huis, roept ''Dit is van mij!'' en geeft het aan niemand. Hij ontdekt de grenzen van bezit. Beschuldig hem niet van egoïsme, laat dat ding op dat moment gewoon van hem zijn.', title_pl = 'Upór „To moje!” 🧸', body_pl = 'Przytula jakąkolwiek przypadkową rzecz w domu, krzyczy „To moje!” i nikomu jej nie daje. Odkrywa granice własności. Nie zarzucaj mu egoizmu, po prostu niech ta rzecz na tę chwilę należy do niego.', title_pt = 'A teimosia do "É meu!" 🧸', body_pt = 'Agarra-se a um objeto qualquer da casa, grita "Isto é meu!" e não o dá a ninguém. Está a descobrir os limites da posse. Não o acuse de egoísmo: naquele momento, deixe simplesmente que o objeto seja dele.', title_sv = 'Envisheten ”Den är min!” 🧸', body_sv = 'Barnet kramar en slumpmässig sak hemma, skriker ”Den är min!” och ger den inte till någon. Barnet upptäcker gränserna för ägande. Anklaga inte barnet för egoism, låt bara saken vara barnets just då.', title_vi = 'Sự bướng bỉnh "Của con!" 🧸', body_vi = 'Bé ôm chặt một món đồ ngẫu nhiên trong nhà và hét lên "Cái này của con!", không cho ai đụng vào. Bé đang khám phá ranh giới sở hữu. Đừng trách bé ích kỷ, chỉ cần để món đồ đó thuộc về bé trong lúc ấy.', title_zh = '“这是我的！”的倔强 🧸', body_zh = '抱着家里随便一样东西大喊“这是我的！”，谁都不给。宝宝在探索所有权的边界。别指责宝宝自私，那一刻就让那样东西归宝宝吧。' WHERE id = '0d31e21b-368c-475e-b2bc-811f2bd6c64c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El color de tu voz 🌙', body_es = 'No escucha la trama del cuento del libro, sino tu tono de voz. Esta noche olvídate de la trama. Lee la historia despacio, alargándola, con un tono bajo como una melodía suave, y envía una señal de sueño directa a su sistema nervioso.', title_fr = 'La couleur de votre voix 🌙', body_fr = 'Il n''écoute pas l''intrigue du conte, mais le ton de votre voix. Ce soir, oubliez l''histoire. Lisez-la en traînant sur les mots, d''une voix basse comme une douce mélodie, pour envoyer directement un signal de sommeil à son système nerveux.', title_hi = 'आवाज़ का रंग 🌙', body_hi = 'वह किताब की कहानी नहीं, आपकी आवाज़ का लहजा सुनता है। आज शाम कहानी भूल जाइए। कहानी को खींच-खींचकर, धीमे संगीत की तरह नीची आवाज़ में पढ़कर उसके तंत्रिका तंत्र को सीधे नींद का संकेत भेजिए।', title_id = 'Warna suara Anda 🌙', body_id = 'Ia tidak mendengarkan alur dongeng di buku, melainkan nada suara Anda. Malam ini lupakan alurnya. Bacakan cerita dengan lambat dan nada rendah seperti musik yang lembut, dan kirim sinyal tidur langsung ke sistem sarafnya.', title_ja = '声の色 🌙', body_ja = 'この子が聞いているのは、絵本のストーリーではなく、あなたの声のトーンです。今夜はストーリーは忘れましょう。お話をゆっくりと、やさしい音楽のように低い声で読んで、神経に直接「おやすみ」のサインを送ってあげて。', title_ko = '목소리의 빛깔 🌙', body_ko = '아이는 책 속 줄거리가 아니라 엄마의 목소리 톤을 듣고 있어요. 오늘 저녁엔 줄거리는 잊으세요. 이야기를 천천히, 잔잔한 음악처럼 낮은 목소리로 읽어 아이의 신경계에 바로 잠의 신호를 보내 주세요.', title_nl = 'De kleur van je stem 🌙', body_nl = 'Hij luistert niet naar het verhaal in het boek, maar naar de toon van jouw stem. Vergeet vanavond het verhaal. Lees het langzaam en zacht voor, als een rustig muziekje, en stuur zo direct een slaapsignaal naar zijn zenuwstelsel.', title_pl = 'Kolor twojego głosu 🌙', body_pl = 'Nie słucha fabuły bajki z książki, tylko tonu twojego głosu. Dziś wieczorem zapomnij o fabule. Czytaj powoli, przeciągle, niskim głosem jak łagodną melodię i wysyłaj jego układowi nerwowemu bezpośredni sygnał do snu.', title_pt = 'A cor da sua voz 🌙', body_pt = 'Ele não ouve o enredo da história do livro, ouve o seu tom de voz. Esta noite, esqueça o enredo. Leia a história devagar, arrastando as palavras em tom baixo como uma melodia suave, e envie diretamente ao sistema nervoso dele um sinal de sono.', title_sv = 'Rösten färg 🌙', body_sv = 'Barnet lyssnar inte på handlingen i bokens saga, utan på din röst. Glöm handlingen i kväll. Läs berättelsen långsamt och utdraget med låg röst, som en mild melodi, så skickar du en sömnsignal direkt till barnets nervsystem.', title_vi = 'Sắc màu giọng nói 🌙', body_vi = 'Bé không nghe cốt truyện trong sách, mà nghe giọng nói của mẹ. Tối nay hãy quên cốt truyện đi. Đọc câu chuyện thật chậm, giọng trầm và êm như một bản nhạc du dương để gửi trực tiếp tín hiệu ngủ đến hệ thần kinh của bé.', title_zh = '声音的颜色 🌙', body_zh = '宝宝听的不是书里故事的情节，而是你的语气。今晚就忘掉情节吧。把故事拖得慢慢的，用低低的声音像一首轻柔的曲子那样读出来，直接给宝宝的神经系统发送入睡信号。' WHERE id = '81e2b129-a3fd-4f20-b3aa-69e3df1d9014' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de las redes sociales 📱', body_es = '¿Ves a las madres perfectas de internet y te culpas por el desorden de tu casa? Para. No te creas esos vídeos de 15 segundos con filtro.', title_fr = 'L''illusion des réseaux sociaux 📱', body_fr = 'Vous voyez des mamans parfaites sur Internet et vous vous jugez pour le désordre de votre maison ? Stop. Ne croyez pas ces vidéos filtrées de 15 secondes.', title_hi = 'सोशल मीडिया का भ्रम 📱', body_hi = 'इंटरनेट पर परफ़ेक्ट माँओं को देखकर अपने बिखरे घर के लिए खुद को कोसती हैं? रुकिए। उन 15 सेकंड के फ़िल्टर वाले वीडियो पर यकीन मत कीजिए।', title_id = 'Ilusi media sosial 📱', body_id = 'Melihat ibu-ibu sempurna di internet lalu menyalahkan diri karena rumah Anda berantakan? Berhenti. Jangan percaya video berfilter berdurasi 15 detik itu.', title_ja = 'SNSの幻想 📱', body_ja = 'ネットで完璧なママたちを見て、散らかった家のことで自分を責めていませんか？ストップ。あの15秒のフィルターがかかった動画を信じないで。', title_ko = 'SNS의 환상 📱', body_ko = '인터넷 속 완벽한 엄마들을 보며 어질러진 집 때문에 자책하나요? 멈추세요. 그 15초짜리 필터 영상을 믿지 마세요.', title_nl = 'De illusie van social media 📱', body_nl = 'Zie je de perfecte mama''s op internet en veroordeel je jezelf om je rommelige huis? Stop. Geloof die gefilterde filmpjes van 15 seconden niet.', title_pl = 'Iluzja mediów społecznościowych 📱', body_pl = 'Widzisz w internecie idealne mamy i obwiniasz się za bałagan w domu? Stop. Nie wierz w te 15-sekundowe filmiki z filtrem.', title_pt = 'A ilusão das redes sociais 📱', body_pt = 'Culpa-se pela desarrumação da casa ao ver as mães perfeitas da internet? Pare. Não acredite nesses vídeos filtrados de 15 segundos.', title_sv = 'Sociala mediers illusion 📱', body_sv = 'Ser du perfekta mammor på nätet och dömer dig själv för stöket hemma? Stopp. Tro inte på de filtrerade 15-sekundersvideorna.', title_vi = 'Ảo ảnh mạng xã hội 📱', body_vi = 'Thấy những bà mẹ hoàn hảo trên mạng, mẹ lại tự trách vì nhà cửa bừa bộn? Dừng lại. Đừng tin vào những video 15 giây qua bộ lọc ấy.', title_zh = '社交媒体的幻象 📱', body_zh = '看到网上那些完美的妈妈，就因为家里乱而责怪自己？停一下。别相信那些加了滤镜的15秒视频。' WHERE id = '92e01489-6842-4c96-9e36-b31b3377a1e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá 📖', body_es = 'Esta noche tienes la voz cansada. Deja la lectura del cuento a papá. Contará una historia inventada y cómica que no tiene nada que ver con los dibujos del libro y hará que el peque se parta de risa. Y tú, a un lado y con un té, disfruta de la escena.', title_fr = 'Le conte de papa 📖', body_fr = 'Ce soir, votre voix est fatiguée. Confiez la lecture du conte à papa. Il racontera une histoire inventée et comique, complètement différente des images du livre, et l''enfant éclatera de rire. Vous, installez-vous un peu à l''écart avec un thé et savourez la scène.', title_hi = 'पापा की कहानी 📖', body_hi = 'आज शाम आपकी आवाज़ थक गई है। कहानी सुनाने का काम पापा को सौंप दीजिए। वे किताब की तस्वीर से बिल्कुल अलग, गढ़ी हुई मज़ेदार कहानी सुनाकर बच्चे को हँसा-हँसाकर लोटपोट कर देंगे। और आप एक तरफ़ चाय के कप के साथ इस नज़ारे का मज़ा लीजिए।', title_id = 'Dongeng Ayah 📖', body_id = 'Malam ini suaramu sudah lelah. Serahkan tugas membacakan dongeng kepada Ayah. Ia akan mengarang cerita lucu yang sama sekali berbeda dari gambar di buku dan membuat anak tertawa terbahak-bahak. Kamu cukup menikmati pemandangan ini dari samping dengan secangkir teh.', title_ja = 'パパのおはなし 📖', body_ja = '今夜は声が疲れていますね。読み聞かせはパパにバトンタッチ。絵本の絵とはまったくちがう、作り話のおもしろいお話で子どもを大笑いさせてくれるはず。あなたはそばで、お茶を片手にこの光景を楽しんで。', title_ko = '아빠의 동화 📖', body_ko = '오늘 저녁엔 목이 지쳤나요? 동화 읽기는 아빠에게 넘기세요. 아빠는 책 속 그림과 전혀 다른 지어낸 웃긴 이야기로 아이를 웃음바다에 빠뜨릴 거예요. 엄마는 옆에서 차 한 잔과 함께 이 장면을 즐기세요.', title_nl = 'Papa''s sprookje 📖', body_nl = 'Je stem is vanavond moe. Draag het voorlezen over aan papa. Hij vertelt een verzonnen, grappig verhaal dat totaal niet bij de plaatjes in het boek past, en je kind ligt dubbel van het lachen. En jij kijkt met een kop thee van een afstand van dit plaatje te genieten.', title_pl = 'Bajka taty 📖', body_pl = 'Dziś wieczorem twój głos jest zmęczony. Przekaż czytanie bajki tacie. Opowie zupełnie inną niż na obrazkach w książce, wymyśloną i zabawną historię, a dziecko będzie się zaśmiewać. A ty z boku, z kubkiem herbaty, delektuj się tym widokiem.', title_pt = 'A história do pai 📖', body_pt = 'Esta noite a sua voz está cansada. Passe a leitura da história para o pai. Ele vai contar uma história inventada e cómica, totalmente diferente das imagens do livro, e a criança vai desfazer-se em gargalhadas. E a mãe, de lado, com uma chávena de chá, desfruta deste quadro.', title_sv = 'Pappas saga 📖', body_sv = 'Din röst är trött i kväll. Lämna över sagoläsningen till pappa. Han berättar en påhittad och rolig historia som är helt annorlunda än bilden i boken, så barnet kiknar av skratt. Och du, titta på det hela från sidan med en kopp te och njut.', title_vi = 'Câu chuyện của bố 📖', body_vi = 'Tối nay giọng mẹ đã mỏi. Hãy giao việc đọc truyện cho bố. Bố sẽ kể một câu chuyện tự nghĩ ra, hài hước và khác hẳn tranh trong sách, khiến bé cười ngặt nghẽo. Còn mẹ, hãy ngồi một bên với cốc trà và thưởng thức khung cảnh ấy.', title_zh = '爸爸讲故事 📖', body_zh = '今晚你的嗓子累了。把讲故事的任务交给爸爸吧。他会讲一个和书里图画完全不同、天马行空又搞笑的故事，把宝宝逗得哈哈大笑。你就在一旁，端杯茶，好好欣赏这幅画面。' WHERE id = '045a4c72-4a86-41d2-b03b-ae2eaef10270' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ayudante de la lavadora 🧺', body_es = 'Tú doblas la ropa con mucho esfuerzo y él, «ayudando», la vuelve a esparcir por toda la habitación. En lugar de enfadarte, convierte la tarea en un juego: «¿A ver quién echa antes y mejor estos calcetines a la cesta?».', title_fr = 'Le petit assistant de la machine à laver 🧺', body_fr = 'Vous pliez le linge avec beaucoup d''efforts, et lui, sous prétexte de vous aider, éparpille tout à nouveau dans la pièce. Au lieu de vous énerver, transformez la tâche en jeu : « Voyons qui mettra ces chaussettes le plus vite et le plus précisément dans le panier ! »', title_hi = 'वॉशिंग मशीन का सहायक 🧺', body_hi = 'आप बड़ी मेहनत से कपड़े तह करती हैं, और वह ‘मदद कर रहा हूँ’ कहकर सब फिर से कमरे में बिखेर देता है। नाराज़ होने के बजाय काम को खेल बना दीजिए: ‘देखें, ये मोज़े टोकरी में सबसे पहले और सबसे सही कौन डालता है?’', title_id = 'Asisten mesin cuci 🧺', body_id = 'Anda melipat baju dengan susah payah, sementara ia ''membantu'' dengan menyebarkannya lagi ke seluruh kamar. Daripada kesal, jadikan permainan: ''Ayo lihat siapa yang paling cepat dan tepat memasukkan kaus kaki ini ke keranjang!''', title_ja = '洗濯機のお手伝い係 🧺', body_ja = 'あなたが一生けんめい洗濯物をたたんでいると、「お手伝いする」と言って全部また部屋にばらまいてしまう。怒る代わりに、お仕事を遊びに変えましょう：「どっちが早く、しかもうまくこの靴下をかごに入れられるかな？」', title_ko = '빨래 도우미 🧺', body_ko = '애써 빨래를 개고 있는데 ''도와줄게'' 하며 전부 다시 방에 흩뿌리나요? 화내는 대신 놀이로 바꿔 보세요: ''누가 이 양말을 더 빨리, 더 정확하게 바구니에 넣나 볼까?''', title_nl = 'Hulpje bij de wasmachine 🧺', body_nl = 'Jij vouwt met veel moeite de was op, en hij zegt ''ik help'' en strooit alles weer door de kamer. Word niet boos, maar maak er een spel van: ''Wie gooit deze sokken het snelst en het preciest in de mand?''', title_pl = 'Pomocnik przy praniu 🧺', body_pl = 'Z wielkim trudem składasz ubrania, a on „pomaga” i znowu rozrzuca wszystko po pokoju. Zamiast się złościć, zamień to w zabawę: „Zobaczmy, kto szybciej i celniej wrzuci te skarpetki do kosza?”.', title_pt = 'O ajudante da máquina de lavar 🧺', body_pt = 'Dobra a roupa com muito esforço e ele, a dizer "estou a ajudar", espalha-a outra vez pelo quarto. Em vez de se irritar, transforme a tarefa num jogo: "Vamos ver quem põe estas meias no cesto mais depressa e com mais pontaria?"', title_sv = 'Tvättmaskinshjälparen 🧺', body_sv = 'Du viker kläderna med stor möda, och barnet säger ”jag hjälper till” och sprider ut allt i rummet igen. Istället för att bli arg, gör om sysslan till en lek: ”Får se vem som kastar de här strumporna i korgen snabbast och mest exakt?”', title_vi = 'Trợ thủ giặt giũ 🧺', body_vi = 'Mẹ vất vả gấp quần áo, còn bé nói "Con giúp mẹ" rồi lại vung hết ra khắp phòng. Thay vì bực mình, hãy biến việc này thành trò chơi: "Xem ai ném tất vào giỏ nhanh và chuẩn hơn nào?"', title_zh = '洗衣小帮手 🧺', body_zh = '你辛辛苦苦叠好衣服，宝宝却说“我来帮忙”，把它们又撒满一屋子。与其生气，不如把活儿变成游戏：“看谁能又快又准地把这些袜子扔进篮子里？”' WHERE id = '4f62a7a1-3c14-48ad-8798-069c557ed2c1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada obligatoria a la naturaleza ⛅', body_es = 'Entre cuatro paredes su energía se convierte en agresividad y cada frase empieza por «no». Haga el tiempo que haga, abrígale según Tiempo y ropa y sácale fuera sin falta. Tocar la tierra reiniciará su sistema nervioso al instante.', title_fr = 'S''évader absolument dans la nature ⛅', body_fr = 'Entre quatre murs, son énergie se transforme en agressivité et chacune de ses phrases commence par « non ». Quel que soit le temps, équipez-le comme il faut et sortez-le absolument. Toucher la terre remettra aussitôt son système nerveux à zéro.', title_hi = 'प्रकृति की ओर ज़रूर भागिए ⛅', body_hi = 'चार दीवारों के अंदर उसकी ऊर्जा गुस्से में बदल जाती है और उसका हर वाक्य ‘नहीं’ से शुरू होता है। मौसम कैसा भी हो, सही कपड़े पहनाकर उसे बाहर ज़रूर ले जाइए। मिट्टी छूना उसके तंत्रिका तंत्र को तुरंत रीसेट कर देगा।', title_id = 'Wajib kabur ke alam ⛅', body_id = 'Di dalam empat dinding, energinya berubah menjadi agresi dan setiap kalimatnya diawali dengan ''nggak''. Apa pun cuacanya, kenakan pakaian yang sesuai dan pastikan mengajaknya keluar. Menyentuh tanah akan langsung me-reset sistem sarafnya.', title_ja = 'とにかく自然へ ⛅', body_ja = '4つの壁の中で、エネルギーがイライラに変わり、口を開けば「いや」から始まる。天気や服装に関係なく、しっかり準備して必ず外へ連れ出しましょう。土にさわれば、神経がすぐにリセットされます。', title_ko = '꼭 필요한 자연 탈출 ⛅', body_ko = '네 벽 안에서 에너지가 공격성으로 바뀌고 말마다 ''싫어''로 시작하나요? 날씨가 어떻든 알맞게 챙겨 입혀 꼭 밖에 데리고 나가세요. 흙을 만지면 신경계가 바로 초기화돼요.', title_nl = 'Echt even de natuur in ⛅', body_nl = 'Tussen vier muren wordt zijn energie agressie en begint elke zin met ''nee''. Kleed hem passend aan, ongeacht het weer, en ga hoe dan ook naar buiten. Aarde aanraken zet zijn zenuwstelsel meteen op nul.', title_pl = 'Konieczna ucieczka na łono natury ⛅', body_pl = 'W czterech ścianach jego energia zamienia się w agresję, a każde zdanie zaczyna się od „nie”. Bez względu na pogodę ubierz go odpowiednio i koniecznie wyjdźcie na dwór. Dotyk ziemi od razu zresetuje jego układ nerwowy.', title_pt = 'Fuga obrigatória para a natureza ⛅', body_pt = 'Entre quatro paredes, a energia dele transforma-se em agressividade e cada frase começa com "não". Seja qual for o tempo, vista-o de forma adequada e leve-o sem falta para a rua. Tocar na terra vai reiniciar logo o sistema nervoso dele.', title_sv = 'Ut i naturen, absolut ⛅', body_sv = 'Mellan fyra väggar blir barnets energi till ilska och varje mening börjar med ”nej”. Oavsett väder, klä barnet rätt och se till att ni kommer ut. Att röra vid jorden nollställer nervsystemet direkt.', title_vi = 'Nhất định phải ra với thiên nhiên ⛅', body_vi = 'Ở trong bốn bức tường, năng lượng của bé biến thành sự hung hăng và câu nào cũng bắt đầu bằng "không". Dù thời tiết thế nào, hãy chuẩn bị trang phục phù hợp và nhất định đưa bé ra ngoài. Chạm vào đất sẽ lập tức "khởi động lại" hệ thần kinh của bé.', title_zh = '一定要奔向大自然 ⛅', body_zh = '被关在四面墙里，精力就会变成攻击性，每句话都以“不”开头。不管天气如何，穿戴合适，一定要带宝宝出门。摸摸泥土，能让宝宝的神经系统马上重启。' WHERE id = 'b2fc2b4c-64df-4f47-be2c-e630a4d24c5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El derrumbe de la lógica 🔴', body_es = 'Grita «¡dame el agua en el vaso rojo!», se la sirves en el rojo y ahora llora: «¿Por qué la has echado aquí?». Aquí no hay lógica. Simplemente está cansado y necesita una crisis. Espera con calma: la tormenta se calmará sola.', title_fr = 'L''effondrement de la logique 🔴', body_fr = 'Il crie qu''il veut son eau dans le gobelet rouge, vous la versez dans le rouge, et cette fois il pleure : « Pourquoi tu l''as versée là ? » Il n''y a aucune logique. Il est simplement fatigué et a besoin de vider son trop-plein. Attendez calmement, la tempête se calmera d''elle-même.', title_hi = 'तर्क ढह गया 🔴', body_hi = '‘पानी लाल गिलास में दो’ चिल्लाता है, आप लाल में डालती हैं, तो इस बार ‘यहाँ क्यों डाला’ कहकर रोता है। यहाँ कोई तर्क नहीं। वह बस थका है और उसे यह तूफ़ान निकालना है। चुपचाप इंतज़ार कीजिए, तूफ़ान अपने-आप थम जाएगा।', title_id = 'Runtuhnya logika 🔴', body_id = 'Ia berteriak minta airnya di gelas merah, Anda menuangnya ke gelas merah, lalu ia menangis ''Kenapa dituang di sini?''. Tak ada logika di sini. Ia hanya lelah dan butuh melampiaskan krisis. Tunggulah dengan tenang, badai akan reda dengan sendirinya.', title_ja = '理屈の崩壊 🔴', body_ja = '「お水は赤いコップで！」と叫ぶので赤に注ぐと、今度は「なんでそこに注いだの」と泣く。ここに理屈はありません。ただ疲れていて、爆発が必要なだけ。静かに待ちましょう。嵐は自然におさまります。', title_ko = '논리의 붕괴 🔴', body_ko = '''물 빨간 컵에 줘'' 해서 빨간 컵에 따랐더니 ''왜 여기 따랐어''라며 우나요? 여기엔 논리가 없어요. 그냥 피곤해서 터뜨릴 곳이 필요한 거예요. 조용히 기다리면 폭풍은 저절로 잦아들 거예요.', title_nl = 'De ineenstorting van de logica 🔴', body_nl = 'Hij schreeuwt dat hij zijn water in de rode beker wil, je schenkt het in de rode, en dan huilt hij: ''Waarom heb je het hierin gedaan?'' Er zit geen logica in. Hij is gewoon moe en heeft een bui nodig. Wacht rustig af, de storm gaat vanzelf liggen.', title_pl = 'Upadek logiki 🔴', body_pl = 'Krzyczy „Daj mi wodę w czerwonym kubku”, nalewasz do czerwonego, a on płacze: „Czemu nalałaś tutaj?”. Tu nie ma logiki. Jest po prostu zmęczony i potrzebuje kryzysu. Spokojnie poczekaj, burza sama ucichnie.', title_pt = 'O colapso da lógica 🔴', body_pt = 'Grita "Põe-me a água no copo vermelho", deita-a no vermelho e desta vez chora: "porque é que a puseste aqui?". Aqui não há lógica. Está só cansado e precisa de uma crise. Espere com calma, a tempestade passa sozinha.', title_sv = 'Logikens kollaps 🔴', body_sv = 'Barnet skriker ”Ge mig vattnet i den röda muggen”, du häller upp i den röda, och nu gråter barnet ”varför hällde du här?”. Här finns ingen logik. Barnet är bara trött och behöver en kris. Vänta lugnt, stormen lägger sig av sig själv.', title_vi = 'Logic sụp đổ 🔴', body_vi = 'Bé hét lên đòi uống nước bằng cốc đỏ, mẹ rót vào cốc đỏ, lần này bé lại khóc "Sao mẹ rót vào đây?". Ở đây chẳng có logic nào cả. Bé chỉ mệt và cần một cơn bùng nổ. Hãy bình tĩnh chờ đợi, cơn bão sẽ tự lặng.', title_zh = '逻辑崩塌 🔴', body_zh = '哭喊着“用红杯子给我装水”，你倒进红杯子里，宝宝又哭“你为什么倒在这里”。这里没有逻辑可言。宝宝只是累了，需要发泄一下。安静地等着，风暴会自己平息。' WHERE id = '20cf0e7c-3293-4269-b577-f8012d7d5117' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tesoros que salen del bolsillo 🪨', body_es = '¿Al lavar su pantalón han salido del bolsillo 2 piedras, una hoja seca y un palito a medias? Lo que para ti es basura es para él una colección valiosa con la que descubre el universo. En lugar de tirarlas, guárdalas en una cajita del tesoro.', title_fr = 'Les trésors des poches 🪨', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche 2 cailloux, une feuille séchée et un bout de brindille ? Ces objets qui sont des déchets pour vous forment sa précieuse collection d''explorateur de l''univers. Au lieu de les jeter, rangez-les dans une petite boîte à trésors.', title_hi = 'जेब से निकले खज़ाने 🪨', body_hi = 'पैंट धोते समय उसकी जेब से 2 पत्थर, एक सूखा पत्ता और आधी टहनी निकली? आपके लिए जो कचरा है, वह उसके लिए दुनिया की खोज का कीमती संग्रह है। इन्हें फेंकने के बजाय एक छोटे खज़ाने के डिब्बे में रखिए।', title_id = 'Harta karun dari saku 🪨', body_id = 'Saat mencuci celananya, dari saku keluar 2 batu, sehelai daun kering, dan ranting patah? Benda yang bagi Anda sampah ini adalah koleksi berharganya saat menjelajahi alam semesta. Daripada membuangnya, kumpulkan di kotak harta karun kecil.', title_ja = 'ポケットから出てきた宝物 🪨', body_ja = 'ズボンを洗おうとしたら、ポケットから石が2つ、枯れ葉が1枚、折れた小枝が出てきた？あなたにはゴミでも、この子にとっては宇宙を発見した大切なコレクションです。捨てる代わりに、小さな宝箱に集めてあげましょう。', title_ko = '주머니 속 보물 🪨', body_ko = '바지를 빨려는데 주머니에서 돌 2개, 마른 나뭇잎, 부러진 나뭇가지가 나왔나요? 엄마에겐 쓰레기지만 아이에겐 우주를 탐험하며 모은 귀한 수집품이에요. 버리는 대신 작은 보물 상자에 모아 주세요.', title_nl = 'Schatten uit de broekzak 🪨', body_nl = 'Kwamen er bij het wassen van zijn broek 2 steentjes, een droog blaadje en een half takje uit zijn zak? Wat voor jou afval is, is voor hem een waardevolle verzameling waarmee hij het universum ontdekt. Gooi ze niet weg, maar bewaar ze in een kleine schatkist.', title_pl = 'Skarby z kieszeni 🪨', body_pl = 'Podczas prania spodni wyjęłaś z kieszeni 2 kamyki, suchy liść i złamany patyczek? Te rzeczy, które dla ciebie są śmieciami, to jego cenna kolekcja z odkrywania wszechświata. Zamiast je wyrzucać, włóż je do małego pudełka na skarby.', title_pt = 'Tesouros que saem dos bolsos 🪨', body_pt = 'Ao lavar as calças, saíram do bolso 2 pedras, uma folha seca e um pauzinho partido? Estes objetos, que para si são lixo, são a coleção valiosa com que ele descobre o universo. Em vez de os deitar fora, guarde-os numa pequena caixa do tesouro.', title_sv = 'Skatter ur fickorna 🪨', body_sv = 'När du tvättade byxorna hittade du 2 stenar, ett torkat löv och en halv pinne i fickan? Det som för dig är skräp är barnets värdefulla samling från upptäckten av universum. Istället för att slänga sakerna, lägg dem i en liten skattlåda.', title_vi = 'Kho báu trong túi quần 🪨', body_vi = 'Khi giặt quần cho bé, mẹ lôi ra 2 viên sỏi, một chiếc lá khô và một que củi gãy? Những thứ với mẹ là rác ấy lại là bộ sưu tập quý giá khi bé khám phá vũ trụ. Thay vì vứt đi, hãy gom chúng vào một hộp kho báu nhỏ.', title_zh = '口袋里掏出的宝藏 🪨', body_zh = '洗裤子时，从口袋里掏出2块石头、一片干树叶和半截小木棍？在你看来是垃圾的东西，却是宝宝探索宇宙的珍贵收藏。别扔掉，把它们收进一个小小的宝藏盒里吧。' WHERE id = '3d467b3e-4418-42f9-965d-e11c13d74805' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te sabes de memoria los libros de siempre. Abre Cuentos inteligentes, diseña una historia con tu peque como protagonista y su habitación como el lugar por conquistar, y crea una sesión de sueño sonora y original que no exige ningún esfuerzo.', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents : faites de votre enfant le héros et de sa chambre le territoire à conquérir, et créez une séance d''endormissement sonore originale qui ne demande aucun effort.', body_hi = 'पुरानी किताबें आपको रट चुकी हैं। स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाकर एक अनोखा, बिना मेहनत वाला आवाज़ों भरा नींद का सत्र बनाइए।', body_id = 'Anda sudah hafal buku-buku klasik. Buka Dongeng Pintar, jadikan anak Anda tokoh utamanya dan kamarnya sendiri sebagai tempat yang akan ditaklukkan, lalu ciptakan sesi tidur bersuara yang tidak biasa tanpa usaha apa pun.', body_ja = '定番の絵本はもう暗記してしまいましたね。「スマートおはなし」を開いて、主人公はお子さん、征服する場所はこの子の部屋にして、いつもとちがう、まったく手間のかからない音声の寝かしつけタイムをつくりましょう。', body_ko = '늘 읽던 책은 다 외웠나요? 스마트 동화를 열고 주인공은 아이로, 정복할 장소는 아이의 방으로 정해 특별하고 힘들이지 않는 소리 잠자리 시간을 만들어 보세요.', body_nl = 'Je kent de klassieke boeken uit je hoofd. Open Slimme sprookjes, maak je kind de hoofdpersoon en zijn kamer het land dat veroverd moet worden, en creëer een bijzondere luistersessie om in slaap te vallen die je geen moeite kost.', body_pl = 'Klasyczne książeczki znasz już na pamięć. Otwórz Mądre bajki, uczyń głównym bohaterem swoje dziecko, a krainą do podbicia jego pokój, i stwórz niezwykły dźwiękowy seans usypiania, który nie wymaga żadnego wysiłku.', body_pt = 'Já sabe os livros clássicos de cor. Abra as Histórias Inteligentes, crie uma história com o seu filho como herói principal e o quarto dele como terra a conquistar, e prepare uma sessão de sono sonora fora do comum, sem esforço nenhum.', body_sv = 'Du kan de klassiska böckerna utantill. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska erövras, och skapa en ovanlig ljudsovstund som inte kräver någon ansträngning.', body_vi = 'Mẹ đã thuộc lòng những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh, thiết kế một buổi ru ngủ bằng âm thanh khác lạ, chẳng tốn chút công sức: bé là nhân vật chính, còn vùng đất cần chinh phục chính là căn phòng của bé.', body_zh = '经典故事书你都背熟了。打开智慧童话，把宝宝设计成主角，把要征服的地方设定为宝宝的房间，打造一场不寻常、毫不费力的有声哄睡时光。' WHERE id = '78fd11f7-de1e-4540-906f-51f08156be41' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es arte 🎨', body_es = 'Ha creado en medio de la habitación una gran obra de arte con trocitos de papel e hilos cortados y no te deja tirarla. Deja a un lado la obsesión por la limpieza. Respeta el caos que ha creado: la limpieza puede esperar a mañana.', title_fr = 'Ce n''est pas du désordre, c''est de l''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art faite de petits bouts de papier et de ficelles coupées, et refuse que vous la jetiez. Laissez de côté votre obsession du rangement. Respectez le chaos qu''il a créé, le ménage peut attendre demain.', title_hi = 'कचरा नहीं, कला 🎨', body_hi = 'कमरे के बीच कागज़ के छोटे टुकड़ों और कटे धागों से एक बड़ी कलाकृति बना ली है और फेंकने नहीं देता। सफ़ाई की सनक एक तरफ़ रखिए। उसकी रची अफ़रा-तफ़री का सम्मान कीजिए, सफ़ाई कल तक भी रुक सकती है।', title_id = 'Bukan sampah, tapi seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari sobekan kertas dan potongan benang, dan tidak mengizinkan Anda membuangnya. Singkirkan dulu obsesi kebersihan. Hargai kekacauan yang ia ciptakan, bersih-bersih bisa menunggu besok.', title_ja = 'ゴミじゃない、アートです 🎨', body_ja = '部屋のまんなかに、小さな紙くずや切った毛糸で大作をつくり、捨てさせてくれない。きれい好きはちょっとお休みして、この子がつくったカオスを尊重しましょう。お掃除は明日でも大丈夫です。', title_ko = '쓰레기가 아니라 예술 🎨', body_ko = '방 한가운데 작은 종이 조각과 잘린 실로 커다란 작품을 만들고 버리지 못하게 하나요? 깔끔함에 대한 집착은 잠시 내려놓으세요. 아이가 만든 혼돈을 존중해 주세요, 청소는 내일 해도 돼요.', title_nl = 'Geen rommel, maar kunst 🎨', body_nl = 'Hij heeft midden in de kamer een groot kunstwerk gemaakt van papiersnippers en stukjes touw, en hij laat het je niet weggooien. Zet je opruimdrang even opzij. Respecteer de chaos die hij heeft gemaakt, opruimen kan ook morgen.', title_pl = 'To nie śmieci, to sztuka 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki ze skrawków papieru i pociętych sznurków i nie pozwala go wyrzucić. Odłóż na bok obsesję porządku. Uszanuj chaos, który stworzył, sprzątanie może poczekać do jutra.', title_pt = 'Não é lixo, é arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com pedacinhos de papel e fios cortados e não a deixa deitar fora. Ponha de lado a obsessão pela limpeza. Respeite o caos que ele criou, a limpeza pode ficar para amanhã.', title_sv = 'Inte skräp, utan konst 🎨', body_sv = 'Mitt i rummet har barnet skapat ett stort konstverk av små pappersbitar och avklippta snören och låter dig inte slänga det. Lägg städmanin åt sidan. Respektera kaoset barnet har skapat, städningen kan vänta till i morgon.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Giữa phòng, bé đã tạo ra một "tác phẩm nghệ thuật" lớn từ những mẩu giấy vụn và sợi dây cắt nhỏ, và không cho mẹ vứt đi. Hãy gác lại nỗi ám ảnh sạch sẽ. Tôn trọng sự hỗn loạn bé tạo ra, việc dọn dẹp có thể để đến mai.', title_zh = '不是垃圾，是艺术 🎨', body_zh = '在房间中间用碎纸片、剪断的线头创作了一件大型艺术品，还不让你扔。把洁癖先放一边。尊重宝宝创造的混乱吧，打扫可以留到明天。' WHERE id = '5294e5b4-881b-4e55-b798-fa4dd914d649' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ayuda del Análisis del llanto😭', body_es = 'Se ha despertado en mitad de la noche llorando con los ojos cerrados y no oye a nadie. Confírmalo con el Análisis del llanto; si es un terror nocturno, no intentes despertarle. Quédate a su lado en silencio: en unos minutos volverá a dormirse.', title_fr = 'Le soutien de l''Analyse des pleurs 😭', body_fr = 'Il s''est réveillé en pleine nuit en pleurant, les yeux fermés, sans entendre personne. Vérifiez avec l''Analyse des pleurs : s''il s''agit d''une terreur nocturne, n''essayez pas de le réveiller. Restez simplement près de lui en silence, il se rendormira en quelques minutes.', title_hi = 'क्राइंग एनालिसिस का सहारा😭', body_hi = 'आधी रात आँखें बंद किए रोते हुए जागा और किसी की नहीं सुनता। क्राइंग एनालिसिस से पुष्टि कीजिए; अगर यह नाइट टेरर है, तो उसे जगाने की कोशिश मत कीजिए। बस चुपचाप पास रहिए, वह कुछ मिनटों में फिर सो जाएगा।', title_id = 'Bantuan dari Analisis Tangisan😭', body_id = 'Tengah malam ia terbangun menangis dengan mata terpejam dan tidak mendengar siapa pun. Pastikan dengan Analisis Tangisan; jika ini teror tidur, jangan mencoba membangunkannya. Cukup berdiri di sampingnya tanpa bersuara, dalam beberapa menit ia akan kembali tidur.', title_ja = '泣き声分析でサポート😭', body_ja = '夜中に目を閉じたまま泣いて起き、誰の声も聞こえていない様子。「泣き声分析」で確かめてみましょう。もし夜驚症なら、起こそうとしないで。ただ静かにそばにいてあげれば、数分でまた眠りにつきます。', title_ko = '울음 분석의 도움 😭', body_ko = '한밤중에 눈을 감은 채 울며 깨어나 아무 말도 듣지 못하나요? 울음 분석으로 확인해 보세요. 야경증이라면 깨우려 하지 말고 곁에 조용히 있어 주세요. 몇 분 안에 다시 잠들 거예요.', title_nl = 'Steun van Huilanalyse 😭', body_nl = 'Werd hij midden in de nacht huilend wakker met zijn ogen dicht, en hoort hij niemand? Controleer het met Huilanalyse; als het een nachtmerrie-aanval (pavor nocturnus) is, probeer hem dan niet wakker te maken. Blijf stil bij hem, binnen een paar minuten slaapt hij weer.', title_pl = 'Wsparcie z Analizy płaczu 😭', body_pl = 'W środku nocy obudził się z płaczem, z zamkniętymi oczami, i nikogo nie słyszy. Potwierdź to Analizą płaczu; jeśli to lęk nocny, nie próbuj go budzić. Po prostu bądź obok w ciszy, za kilka minut znów zaśnie.', title_pt = 'Apoio da Análise do Choro 😭', body_pt = 'Acordou a meio da noite a chorar, de olhos fechados, e não ouve ninguém. Confirme com a Análise do Choro; se for terror noturno, não tente acordá-lo. Fique apenas ao lado dele em silêncio: em poucos minutos volta a adormecer.', title_sv = 'Stöd från Gråtanalys😭', body_sv = 'Mitt i natten har barnet vaknat gråtande med slutna ögon och hör ingen. Kontrollera med Gråtanalys; om det är nattskräck, försök inte väcka barnet. Stå bara tyst bredvid, barnet somnar om på några minuter.', title_vi = 'Hỗ trợ từ Phân tích tiếng khóc 😭', body_vi = 'Nửa đêm bé thức dậy khóc, mắt vẫn nhắm và không nghe thấy ai? Hãy kiểm tra bằng Phân tích tiếng khóc; nếu đó là hoảng sợ khi ngủ (night terror), đừng cố đánh thức bé. Chỉ cần lặng lẽ ở bên cạnh, vài phút sau bé sẽ ngủ lại.', title_zh = '哭声分析来帮忙😭', body_zh = '半夜闭着眼睛哭着醒来，谁的话都听不进去。用哭声分析确认一下；如果是夜惊，别试图叫醒宝宝。只要静静地陪在身边，宝宝几分钟后就会重新睡着。' WHERE id = 'b303b530-f33d-4aed-9563-288f674e5686' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas con objetos 🗣️', body_es = 'En el parque le cuenta cosas muy en serio a una piedra, o en casa a una silla, y hasta les riñe. A través del juego simbólico procesa el mundo y las normas. Anota sin falta estos guiones tan especiales en el Seguimiento del desarrollo.', title_fr = 'Conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et les gronde. À travers le jeu symbolique, il comprend le monde et ses règles. Notez absolument ces scénarios particuliers dans le Suivi de développement.', title_hi = 'बेजान चीज़ों से बातचीत 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ कहता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया और नियमों को समझ रहा है। उसकी इन खास कहानियों को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Mengobrol dengan benda mati 🗣️', body_id = 'Di taman ia berbicara serius dengan sebuah batu, atau di rumah memarahi kursi. Lewat permainan simbolis, ia mengolah dunia dan aturan-aturannya. Pastikan menandai skenario istimewanya ini di Pelacak Perkembangan.', title_ja = 'ものとのおしゃべり 🗣️', body_ja = '公園の石や家のいすに、すっかり真剣に話しかけたり、しかったりしています。象徴遊びを通して、世界やルールを整理しているんです。この特別なシナリオを、ぜひ「発達トラッカー」に記録しておきましょう。', title_ko = '사물과의 대화 🗣️', body_ko = '공원의 돌이나 집의 의자에게 아주 진지하게 무언가를 이야기하고 혼내기도 하나요? 상징 놀이로 세상과 규칙을 소화하는 중이에요. 이 특별한 시나리오를 성장 기록에 꼭 표시해 두세요.', title_nl = 'Gesprekken met dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld en de regels. Noteer deze bijzondere scenario''s zeker in de Groeitracker.', title_pl = 'Rozmowy z przedmiotami 🗣️', body_pl = 'W parku zupełnie poważnie coś opowiada kamieniowi albo w domu beszta krzesło. Przez zabawę symboliczną przetwarza świat i zasady. Koniecznie zaznacz te wyjątkowe scenariusze w Śledzeniu rozwoju.', title_pt = 'Conversas com objetos 🗣️', body_pt = 'No parque, fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo e as regras. Não deixe de registar estes enredos especiais no Registo de Crescimento.', title_sv = 'Samtal med livlösa saker 🗣️', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen och reglerna. Anteckna absolut barnets speciella scenarier i Utvecklingsspåraren.', title_vi = 'Trò chuyện với đồ vật 🗣️', body_vi = 'Ở công viên, bé nói chuyện rất nghiêm túc với một hòn đá, ở nhà thì "mắng" chiếc ghế. Bé đang xử lý thế giới và các quy tắc qua trò chơi biểu tượng. Hãy nhớ đánh dấu những kịch bản đặc biệt này trong Theo dõi phát triển.', title_zh = '和没有生命的东西聊天 🗣️', body_zh = '在公园对着一块石头、在家对着一把椅子，非常认真地说着什么，还训它们。宝宝通过象征性游戏来理解世界和规则。一定要把这些特别的小剧本记在发育追踪里。' WHERE id = 'd0b48160-e2df-4f83-a2aa-8dad8ce91b39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de hacer olas. Deja que el agua salpique y que se moje el baño. Ese efecto imán del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'Jeux dans le bain 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu de vagues. Laissez l''eau éclabousser, tant pis si la salle de bain est mouillée. L''effet magnétique de l''eau emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'बाथटब में खेल 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, लहरें बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए, बाथरूम भीगने दीजिए। पानी का वह चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Bermain di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat ombak. Biarkan air memercik ke mana-mana dan kamar mandi basah. Efek magnet air akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = 'お風呂で遊ぼう 🌊', body_ja = 'お風呂はもうきれいにするためではなく、波をつくる遊びです。水しぶきが飛んで、バスルームがびしょびしょになってもいいんです。お湯の磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '욕조 놀이 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 파도 만들기 놀이예요. 물이 사방으로 튀고 욕실이 젖어도 괜찮아요. 물의 자석 같은 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'Spelen in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met golven maken. Laat het water maar spetteren, ook al wordt de badkamer nat. Het magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Zabawa w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w robienie fal. Niech woda chlapie dookoła, niech łazienka będzie mokra. Magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia i spłynie z nim do kanalizacji.', title_pt = 'Brincadeira na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer ondas. Deixe a água salpicar à volta e a casa de banho ficar molhada. O efeito magnético da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Lek i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att göra vågor. Låt vattnet stänka och badrummet bli blött. Vattnets magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Chơi đùa trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo sóng. Cứ để nước bắn tung tóe, phòng tắm ướt một chút cũng được. Sức hút kỳ diệu của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '浴缸里的游戏 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起浪花的游戏。让水花四溅吧，浴室湿了也没关系。水那种磁力般的效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = '3486268f-4b63-480f-87b2-0334f163c85e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Destrucción con propósito 🧱', body_es = 'Construye una torre con mucho esfuerzo y luego la derriba riéndose. Está aprendiendo física, causa y efecto. No te enfades: las torres que caen son nuevas conexiones neuronales en su cerebro. Ayúdale a construirla de nuevo.', title_fr = 'Détruire, c''est apprendre 🧱', body_fr = 'Il construit une tour avec beaucoup d''efforts, puis la fait tomber d''un coup en riant. Il apprend la physique, la cause et l''effet. Ne vous énervez pas : ces tours qui tombent, ce sont de nouvelles connexions neuronales dans son cerveau. Aidez-le à la reconstruire.', title_hi = 'मकसद भरी तोड़फोड़ 🧱', body_hi = 'बड़ी मेहनत से मीनार बनाता है, फिर हँसते हुए एक झटके में गिरा देता है। वह भौतिकी और कारण-परिणाम सीख रहा है। नाराज़ मत होइए, गिरती मीनारें उसके दिमाग में बनते नए न्यूरॉन कनेक्शन हैं। उसे फिर से बनाने में मदद कीजिए।', title_id = 'Merobohkan dengan tujuan 🧱', body_id = 'Ia membangun menara dengan susah payah, lalu merobohkannya sambil tertawa dengan sekali sentuh. Ia sedang belajar fisika dan sebab-akibat. Jangan kesal, menara yang roboh adalah koneksi saraf baru di otaknya. Bantu ia membangunnya kembali.', title_ja = 'わざと壊す遊び 🧱', body_ja = 'がんばってタワーを作ったのに、笑いながら一気にくずしてしまう。物理や原因と結果を学んでいるんです。イライラしないで。くずれるタワーは、脳の中にできる新しい神経のつながりです。また作るのを手伝ってあげましょう。', title_ko = '목적 있는 부수기 🧱', body_ko = '애써 탑을 쌓고는 깔깔 웃으며 한 번에 무너뜨리나요? 물리와 원인과 결과를 배우는 중이에요. 화내지 마세요, 무너지는 탑은 뇌 속의 새로운 신경 연결이에요. 다시 쌓도록 도와주세요.', title_nl = 'Doelgerichte sloop 🧱', body_nl = 'Hij bouwt met veel moeite een toren en gooit hem dan lachend in één klap om. Hij leert natuurkunde en oorzaak en gevolg. Word niet boos: die omvallende torens zijn nieuwe verbindingen in zijn brein. Help hem de toren opnieuw te bouwen.', title_pl = 'Celowe burzenie 🧱', body_pl = 'Z wielkim trudem buduje wieżę, a potem ze śmiechem burzy ją jednym ruchem. Uczy się fizyki i związku przyczyny ze skutkiem. Nie denerwuj się, burzone wieże to nowe połączenia neuronów w jego mózgu. Pomóż mu zbudować ją od nowa.', title_pt = 'Destruição com propósito 🧱', body_pt = 'Constrói uma torre com muito esforço e depois deita-a abaixo a rir. Está a aprender física e causa-efeito. Não se irrite: as torres que caem são novas ligações neuronais no cérebro dele. Ajude-o a construir de novo.', title_sv = 'Målmedveten förstörelse 🧱', body_sv = 'Barnet bygger ett torn med stor möda och river det sedan skrattande med en spark. Barnet lär sig fysik, orsak och verkan. Bli inte irriterad, de raserade tornen är nya nervkopplingar i barnets hjärna. Hjälp barnet att bygga igen.', title_vi = 'Phá hủy có chủ đích 🧱', body_vi = 'Bé dày công xây một tòa tháp, rồi vừa cười vừa đẩy đổ chỉ bằng một cú. Bé đang học về vật lý, về nguyên nhân và kết quả. Đừng bực mình, những tòa tháp đổ chính là những kết nối thần kinh mới trong não bé. Hãy giúp bé xây lại.', title_zh = '有目的的破坏 🧱', body_zh = '费了好大劲搭起一座塔，然后笑着一脚把它踢倒。宝宝在学习物理和因果关系。别生气，倒下的塔，就是宝宝大脑里新建立的神经连接。帮宝宝再搭起来吧。' WHERE id = 'c30e7d23-adbf-430f-894c-89ab12e4b61e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rebelión de la siesta 🥱', body_es = '¿No quiere ir a la cama y llora? No le obligues. Baja las luces de la habitación y crea una rutina nueva anunciando la «hora de hojear libros en silencio»: así descansaréis los dos, cada uno a su manera.', title_fr = 'L''apocalypse de la sieste 🥱', body_fr = 'Il ne veut pas aller au lit et pleure ? Ne le forcez pas. Baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine qui vous reposera tous les deux, chacun à votre façon.', title_hi = 'दिन की नींद पर तूफ़ान 🥱', body_hi = 'सोने नहीं जाना चाहता और रोता है? ज़बरदस्ती मत कीजिए। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और एक नया रूटीन बनाइए जो आप दोनों को आराम दे, ताकि आप और वह, दोनों अलग तरह से आराम कर सकें।', title_id = 'Kiamat tidur siang 🥱', body_id = 'Ia tidak mau tidur dan menangis? Jangan memaksa. Redupkan lampu kamar dan ciptakan rutinitas baru dengan mengumumkan ''Waktu membaca buku dengan tenang'', agar Anda dan ia sama-sama beristirahat dengan cara yang berbeda.', title_ja = 'お昼寝の大反乱 🥱', body_ja = 'ベッドに行きたくなくて泣いている？無理強いしないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ふたりともほっとできる新しいルーティンをつくりましょう。そうすれば、あなたもこの子も、いつもとちがう形で休めます。', title_ko = '낮잠 대소동 🥱', body_ko = '자러 가기 싫다며 우나요? 억지로 재우지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 새로운 루틴을 만들어 보세요. 그러면 엄마도 아이도 색다르게 쉴 수 있어요.', title_nl = 'Opstand bij het middagslaapje 🥱', body_nl = 'Wil hij niet naar bed en huilt hij? Dwing hem niet. Dim de lichten in de kamer en kondig een ''stil boekjesuurtje'' aan, een nieuwe routine waar jullie allebei op een andere manier van tot rust komen.', title_pl = 'Rewolucja przed drzemką 🥱', body_pl = 'Nie chce iść do łóżka i płacze? Nie zmuszaj. Przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę, dzięki której oboje odpoczniecie, każde na swój sposób.', title_pt = 'A grande revolta da sesta 🥱', body_pt = 'Não quer ir para a cama e chora? Não o obrigue. Baixe as luzes do quarto e crie uma nova rotina anunciando a "hora de folhear livros em silêncio": assim descansam os dois, cada um à sua maneira.', title_sv = 'Upproret mot tuppluren 🥱', body_sv = 'Vill barnet inte gå och lägga sig och gråter? Tvinga inte. Dämpa ljuset i rummet och utlys en ”tyst bläddra-i-böcker-stund”, så skapar du en ny rutin där både du och barnet får vila på ett annat sätt.', title_vi = 'Cuộc nổi loạn giờ ngủ trưa 🥱', body_vi = 'Bé không muốn lên giường và khóc? Đừng ép. Hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới, nhờ đó cả mẹ và bé đều được nghỉ ngơi theo một cách khác.', title_zh = '午睡大起义 🥱', body_zh = '不肯上床还哭闹？别强迫。把房间灯光调暗，宣布“安静翻书时间”，建立一个新的、让你们俩都能休息的日常流程，这样你和宝宝都能换个方式放松一下。' WHERE id = 'f4280214-1e8a-4015-949d-34ae67c41790' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dictador matutino en acción 👑', body_es = '«¡Ahí no te sientes tú, se sienta mi osito!». En el desayuno es él quien manda en toda la mesa. Sin romper su voluntad de golpe, mantén el equilibrio y la paz diciendo: «Vale, que el osito se siente ahí y yo aquí».', title_fr = 'Le dictateur du matin est à l''œuvre 👑', body_fr = '« Ne t''assieds pas là, c''est la place de mon nounours ! » Au petit-déjeuner, c''est lui qui dirige toute la table. Sans briser sa volonté, préservez l''équilibre et la paix : « D''accord, ton nounours s''assied là, et moi ici. »', title_hi = 'सुबह का तानाशाह ड्यूटी पर 👑', body_hi = '‘वहाँ तुम मत बैठो, मेरा टेडी बैठेगा!’ नाश्ते पर पूरी मेज़ वही चलाता है। उसकी इच्छा को एकदम से तोड़े बिना, ‘ठीक है, टेडी वहाँ बैठे, मैं यहाँ बैठती हूँ’ कहकर संतुलन और कमरे की शांति बनाए रखिए।', title_id = 'Diktator pagi sedang bertugas 👑', body_id = '''Jangan duduk di situ, itu tempat beruangku!'' Saat sarapan, ia yang mengatur seluruh meja. Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dan kedamaian dengan berkata ''Baik, beruangnya duduk di situ, Mama duduk di sini''.', title_ja = '朝の独裁者、活動中 👑', body_ja = '「そこにママは座らないで、くまさんが座るの！」朝ごはんのテーブルは、すべてこの子が仕切っています。意志をばっさり折らずに、「いいよ、くまさんはそこ、ママはここね」と言って、バランスと部屋の平和を守りましょう。', title_ko = '아침의 독재자 출근 완료 👑', body_ko = '''거기 엄마가 앉지 마, 곰돌이가 앉을 거야!'' 아침 식탁 전체를 아이가 지휘하나요? 의지를 확 꺾지 말고 ''좋아, 곰돌이는 거기 앉고 엄마는 여기 앉을게''라며 균형과 평화를 지켜 주세요.', title_nl = 'De ochtenddictator aan het werk 👑', body_nl = '''Daar mag jij niet zitten, daar zit mijn beertje!'' Bij het ontbijt heeft hij de hele tafel in handen. Breek zijn wil niet hard, maar bewaar de balans en de vrede: ''Goed, het beertje zit daar en ik zit hier.''', title_pl = 'Poranny dyktator w akcji 👑', body_pl = '„Nie siadaj tam, tam usiądzie mój miś!” Przy śniadaniu to on rządzi całym stołem. Nie łamiąc ostro jego woli, zachowaj równowagę i spokój: „Dobrze, miś usiądzie tam, a ja tutaj”.', title_pt = 'O ditador da manhã em ação 👑', body_pt = '"Não te sentes aí, quem se senta é o meu ursinho!" Ao pequeno-almoço é ele quem manda na mesa toda. Sem quebrar a vontade dele de forma brusca, diga "Está bem, o ursinho senta-se aí e eu sento-me aqui" e mantenha o equilíbrio e a paz.', title_sv = 'Morgondiktatorn i tjänst 👑', body_sv = '”Där får du inte sitta, nallen ska sitta där!” Vid frukosten styr barnet hela bordet. Utan att knäcka barnets vilja, säg ”Okej, nallen sitter där och jag sitter här” och behåll balansen och freden i rummet.', title_vi = 'Nhà độc tài buổi sáng đang làm việc 👑', body_vi = '"Mẹ đừng ngồi đó, gấu bông của con sẽ ngồi đấy!" Bé điều khiển cả bàn ăn sáng. Để không bẻ gãy ý chí của bé, hãy giữ cân bằng và hòa khí bằng câu: "Được rồi, gấu bông ngồi đó, còn mẹ ngồi đây".', title_zh = '早晨的小独裁者上岗了 👑', body_zh = '“你别坐那儿，那是小熊的位置！”早餐时整张桌子都归宝宝指挥。别硬生生地压下宝宝的意愿，说一句“好，小熊坐那儿，我坐这儿”，守住平衡和房间里的和平。' WHERE id = 'b2543089-e56e-4e5f-b7a7-8528d7fea1b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El peque se ha dormido. Apaga las luces y enciende una vela en la mesa. No es por romanticismo, sino para calmar tus nervios irritados todo el día y tus ojos cansados de pantallas y ruido.', body_fr = 'L''enfant dort. Éteignez les lumières et allumez une bougie sur la table. Pas pour le romantisme, simplement pour apaiser vos nerfs irrités toute la journée et vos yeux fatigués par les écrans et le bruit.', body_hi = 'बच्चा सो गया। लाइटें बंद कीजिए, मेज़ पर एक मोमबत्ती जलाइए। यह रोमांस के लिए नहीं, बस दिनभर की चिढ़ी हुई नसों और स्क्रीन व शोर से थकी आँखों को सुकून देने के लिए है।', body_id = 'Anak sudah tidur. Matikan lampu dan nyalakan sebatang lilin di meja. Ini bukan untuk romantis, tapi sekadar menenangkan saraf yang tegang seharian dan mata yang lelah oleh layar dan kebisingan.', body_ja = '子どもが寝ました。明かりを消して、テーブルにキャンドルを灯しましょう。ロマンスのためではなく、一日じゅう張りつめていた神経と、画面や騒音で疲れた目を落ち着かせるためです。', body_ko = '아이가 잠들었어요. 불을 끄고 식탁에 초 하나를 켜 보세요. 로맨스를 위해서가 아니라, 하루 종일 곤두선 신경과 화면과 소음에 지친 눈을 달래기 위해서예요.', body_nl = 'Je kind slaapt. Doe de lichten uit en steek een kaarsje aan op tafel. Niet voor de romantiek, maar om je zenuwen, die de hele dag geprikkeld waren, en je ogen, moe van schermen en lawaai, tot rust te brengen.', body_pl = 'Dziecko śpi. Zgaś światła i zapal na stole świecę. Nie dla romantyzmu, tylko po to, by ukoić nerwy, podrażnione przez cały dzień, i oczy zmęczone ekranami i hałasem.', body_pt = 'A criança adormeceu. Apague as luzes e acenda uma vela na mesa. Não é por romantismo: é só para acalmar os nervos irritados o dia todo e os olhos cansados de ecrãs e barulho.', body_sv = 'Barnet sover. Släck lamporna och tänd ett ljus på bordet. Det är inte för romantikens skull, utan bara för att lugna dina nerver som varit irriterade hela dagen och dina ögon som är trötta av skärmar och oväsen.', body_vi = 'Bé đã ngủ. Hãy tắt đèn, thắp một ngọn nến trên bàn. Không phải để lãng mạn, mà chỉ để xoa dịu thần kinh căng thẳng cả ngày và đôi mắt mỏi mệt vì màn hình, tiếng ồn.', body_zh = '宝宝睡着了。关上灯，在桌上点一支蜡烛。这不是为了浪漫，只是为了让你一整天被刺激的神经，以及被屏幕和噪音累坏的眼睛平静下来。' WHERE id = 'c7639a79-f169-46c8-bd32-85e01fd08685' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saturación de contacto 🔋', body_es = 'Todo el día se te sube encima, pide brazos y juega con tu pelo. La saturación de contacto («touched out») es real. Tienes derecho a retirarte sola a una habitación al menos 15 minutos y a que tu cuerpo sea solo tuyo.', title_fr = 'La saturation du toucher 🔋', body_fr = 'Toute la journée, il vous grimpe dessus, réclame des câlins et joue avec vos cheveux. La saturation du toucher (« touched out ») est bien réelle. Vous avez le droit de vous retirer seule dans une pièce au moins 15 minutes, pour que votre corps n''appartienne qu''à vous.', title_hi = 'छुए जाने की थकान 🔋', body_hi = 'दिनभर आप पर चढ़ता है, गोद माँगता है और आपके बालों से खेलता है। छुए जाने की थकान (टच्ड आउट) सच है। कम से कम 15 मिनट अकेले किसी कमरे में जाने का, अपने शरीर को सिर्फ़ अपना महसूस करने का आपको हक है।', title_id = 'Lelah disentuh 🔋', body_id = 'Seharian ia memanjat tubuh Anda, minta digendong, dan memainkan rambut Anda. Lelah disentuh (touched out) itu nyata. Anda berhak menyendiri di sebuah ruangan setidaknya 15 menit, agar tubuh Anda hanya milik Anda.', title_ja = 'さわられ疲れ 🔋', body_ja = '一日じゅう体によじのぼって、抱っこをせがみ、髪の毛で遊ぶ。さわられ疲れ（touched out）は本当にあります。せめて15分、ひとりで別の部屋にこもって、自分の体を自分だけのものにする権利が、あなたにはあります。', title_ko = '스킨십 피로 🔋', body_ko = '하루 종일 몸에 기어오르고, 안아 달라 하고, 머리카락을 만지작거리나요? 스킨십 피로(touched out)는 진짜예요. 적어도 15분은 혼자 방에 들어가, 내 몸이 오롯이 나만의 것이 될 권리가 있어요.', title_nl = 'Aanraakmoeheid 🔋', body_nl = 'De hele dag klimt hij op je, wil hij op schoot en speelt hij met je haar. Aanraakmoeheid (touched out) is echt. Je hebt het recht om je minstens 15 minuten alleen in een kamer terug te trekken, zodat je lichaam even alleen van jou is.', title_pl = 'Zmęczenie dotykiem 🔋', body_pl = 'Cały dzień się na ciebie wspina, chce się przytulać i bawi się twoimi włosami. Zmęczenie dotykiem (touched out) jest prawdziwe. Masz prawo zaszyć się sama w pokoju choćby na 15 minut, by twoje ciało należało tylko do ciebie.', title_pt = 'Cansaço de toque 🔋', body_pt = 'O dia inteiro trepa por si, pede colo e brinca com o seu cabelo. O cansaço de toque ("touched out") é real. Tem direito a retirar-se sozinha para uma divisão pelo menos 15 minutos e a ter o seu corpo só para si.', title_sv = 'Beröringströtthet 🔋', body_sv = 'Hela dagen klättrar barnet på dig, vill bli buret och leker med ditt hår. Beröringströtthet (touched out) är verklig. Du har rätt att dra dig undan ensam i ett rum i åtminstone 15 minuter, och att din kropp får vara bara din.', title_vi = 'Mệt vì bị chạm vào 🔋', body_vi = 'Cả ngày bé trèo lên người mẹ, đòi bế và nghịch tóc mẹ. Cảm giác mệt vì bị chạm vào liên tục (touched out) là có thật. Mẹ có quyền ở một mình trong phòng ít nhất 15 phút, để cơ thể chỉ thuộc về riêng mình.', title_zh = '被触碰到疲惫 🔋', body_zh = '一整天宝宝都往你身上爬，要抱抱，玩你的头发。“触碰疲劳”（touched out）是真实存在的。你有权利至少一个人在房间里待上15分钟，让身体只属于你自己。' WHERE id = 'c83edf54-e27c-4125-b28b-f2d18dfa66d3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar toda su energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo sube a caballito y galopa, las carcajadas llenan la habitación y todo el estrés físico acumulado, esa energía sin fin, desaparece en segundos con el sudor.', body_fr = 'Il n''a pas pu se dépenser complètement et refuse d''aller au lit. Appelez papa en renfort. Quand il le prend sur son dos pour jouer au cheval, les éclats de rire remplissent la pièce, et toute la tension physique accumulée, cette énergie sans fin, s''évacue en quelques secondes.', body_hi = 'पूरी ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक तनाव, वह अंतहीन ऊर्जा पसीने के साथ सेकंडों में गायब हो जाती है।', body_id = 'Ia belum sempat menyalurkan seluruh energinya dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar, dan semua stres fisik serta energi yang tak habis-habis itu lenyap dalam hitungan detik bersama keringat.', body_ja = 'エネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを背中にのせてお馬さんになれば、部屋は笑い声でいっぱいになり、たまっていた体のストレスも尽きないエネルギーも、汗と一緒にあっという間に消えていきます。', body_ko = '에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음소리가 방을 채우고, 쌓인 몸의 스트레스와 끝없는 에너지가 땀과 함께 몇 초 만에 사라져요.', body_nl = 'Hij is zijn energie niet helemaal kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem op zijn rug neemt en paardje speelt, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke stress en die eindeloze energie zwetend in een paar seconden.', body_pl = 'Nie wyładował do końca energii i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy weźmie go na barana i pogalopuje jak koń, śmiech wypełni pokój, a całe nagromadzone napięcie i ta niewyczerpana energia znikną w kilka sekund.', body_pt = 'Não conseguiu gastar toda a energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele põe a criança às costas e faz de cavalo a galopar, as gargalhadas enchem o quarto e todo o stress físico acumulado, aquela energia sem fim, desaparece em segundos, a suar.', body_sv = 'Barnet har inte fått ur sig all energi och vägrar gå och lägga sig. Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och all ansamlad fysisk stress och den ändlösa energin försvinner på några sekunder i form av svett.', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố cõng bé chơi trò cưỡi ngựa, tiếng cười ngập tràn căn phòng, mọi căng thẳng thể chất và nguồn năng lượng bất tận ấy sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', body_zh = '精力还没释放完，就是不肯上床。叫爸爸来帮忙吧。爸爸把宝宝驮在背上“骑大马”时，笑声充满房间，积攒的所有身体压力和用不完的精力，几秒钟内就随着汗水消失了。' WHERE id = '01e96341-0baa-4735-9565-edc8b43ed916' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesiones en la Comunidad 💬', body_es = '¿Hoy has gritado por todo y te sientes la madre con menos paciencia del mundo? Por favor, debes saber que no estás sola. Entra en la Comunidad Anacan, lee que otras madres también están hoy igual de agotadas y respira aliviada.', title_fr = 'Se confier à la Communauté 💬', body_fr = 'Aujourd''hui, vous avez crié pour tout et vous vous sentez la maman la plus impatiente du monde ? Sachez que vous n''êtes pas seule. Rejoignez la Communauté Anacan, lisez que d''autres mamans sont tout aussi épuisées aujourd''hui, et soufflez.', title_hi = 'कम्युनिटी में इकरार 💬', body_hi = 'आज हर बात पर चिल्लाईं और खुद को दुनिया की सबसे बेसब्र माँ महसूस कर रही हैं? कृपया जान लीजिए कि आप अकेली नहीं हैं। Anacan कम्युनिटी में जाइए, पढ़िए कि दूसरी माँएँ भी आज उतनी ही थकी हैं, और राहत पाइए।', title_id = 'Pengakuan di komunitas 💬', body_id = 'Hari ini Anda meneriaki segala hal dan merasa menjadi ibu paling tidak sabar di dunia? Ketahuilah bahwa Anda tidak sendirian. Masuklah ke Komunitas Anacan, baca bahwa ibu-ibu lain juga sama lelahnya hari ini, dan tenangkan diri.', title_ja = 'コミュニティで打ち明けよう 💬', body_ja = '今日は何にでも叫んでしまって、自分は世界でいちばんがまんのできないママだと感じていますか？ひとりじゃないと知ってください。Anacanコミュニティを開いて、ほかのママたちも今日同じくらい疲れきっていると読んで、ほっとしましょう。', title_ko = '커뮤니티에 털어놓기 💬', body_ko = '오늘 모든 것에 소리치고 세상에서 가장 참을성 없는 엄마처럼 느껴지나요? 혼자가 아니라는 걸 꼭 알아 주세요. Anacan 커뮤니티에 들어가 다른 엄마들도 오늘 똑같이 지쳤다는 걸 읽으며 마음을 놓으세요.', title_nl = 'Bekentenis in de Community 💬', body_nl = 'Heb je vandaag tegen alles geschreeuwd en voel je je de ongeduldigste moeder ter wereld? Weet alsjeblieft dat je niet de enige bent. Ga naar de Anacan Community, lees dat andere mama''s vandaag net zo op waren en kom tot rust.', title_pl = 'Wyznanie w Społeczności 💬', body_pl = 'Dziś krzyczałaś na wszystko i czujesz się najbardziej niecierpliwą mamą na świecie? Wiedz, proszę, że nie jesteś sama. Wejdź do Społeczności Anacan, przeczytaj, że inne mamy są dziś tak samo wyczerpane, i poczuj ulgę.', title_pt = 'Desabafo na comunidade 💬', body_pt = 'Hoje gritou com tudo e sente-se a mãe mais impaciente do mundo? Saiba, por favor, que não está sozinha. Entre na Comunidade Anacan, leia que hoje outras mães também ficaram igualmente esgotadas e fique mais aliviada.', title_sv = 'Ett erkännande i gemenskapen 💬', body_sv = 'Skrek du åt allt i dag och känner dig som världens mest otåliga mamma? Var snäll och vet att du inte är ensam. Gå in i Anacan Community, läs att andra mammor också var lika slut i dag och slappna av.', title_vi = 'Lời thú nhận trong Cộng đồng 💬', body_vi = 'Hôm nay mẹ đã quát tháo mọi thứ và thấy mình là người mẹ thiếu kiên nhẫn nhất thế giới? Xin hãy biết rằng mẹ không đơn độc. Hãy vào Cộng đồng Anacan, đọc thấy các mẹ khác hôm nay cũng kiệt sức y như vậy và nhẹ lòng hơn.', title_zh = '在社区里说出心里话 💬', body_zh = '今天对什么都吼了，觉得自己是世界上最没耐心的妈妈？请你知道，你并不孤单。进入Anacan社区，读读其他妈妈今天也一样精疲力竭，让自己放松下来。' WHERE id = '384ff620-f71d-4bc9-9283-5e83ec033e38' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El rival del espejo 🪞', body_es = 'Delante del espejo frunce el ceño y pone caras enfadadas y raras. Está comprobando cómo se ven las emociones en su cara. Observa con curiosidad y sin hacer ruido el ensayo de este pequeño actor de teatro.', title_fr = 'Le rival dans le miroir 🪞', body_fr = 'Devant le miroir, il fronce les sourcils et fait des grimaces fâchées ou bizarres. Il teste à quoi ressemblent les émotions sur son visage. Observez sans bruit, avec curiosité, la répétition de ce petit acteur de théâtre.', title_hi = 'आईने में प्रतिद्वंद्वी 🪞', body_hi = 'आईने के सामने खड़े होकर खुद ही भौंहें चढ़ाता है, गुस्से वाले और अजीब चेहरे बनाता है। वह परख रहा है कि भावनाएँ चेहरे पर कैसी दिखती हैं। बिना आवाज़ किए दूर से इस नन्हे थिएटर कलाकार की रिहर्सल दिलचस्पी से देखिए।', title_id = 'Saingan di cermin 🪞', body_id = 'Ia berdiri di depan cermin, mengerutkan alis dan membuat ekspresi marah dan aneh pada dirinya sendiri. Ia sedang menguji bagaimana emosi terlihat di wajahnya. Saksikan latihan aktor teater mini ini dengan penuh minat dari jauh tanpa bersuara.', title_ja = '鏡の中のライバル 🪞', body_ja = '鏡の前に立って、ひとりで眉をしかめたり、怒った顔やへんな顔をしたりしている。気持ちが顔にどう表れるかを試しているんです。音を立てずに、この小さな舞台俳優の練習を興味深く見守りましょう。', title_ko = '거울 속 라이벌 🪞', body_ko = '거울 앞에 서서 혼자 눈살을 찌푸리고 화난 표정, 이상한 표정을 짓나요? 감정이 얼굴에 어떻게 보이는지 시험하는 중이에요. 옆에서 소리 내지 말고 이 작은 연극배우의 연습을 흥미롭게 지켜보세요.', title_nl = 'De rivaal in de spiegel 🪞', body_nl = 'Hij staat voor de spiegel en fronst zijn wenkbrauwen, trekt boze en rare gezichten. Hij test hoe emoties eruitzien op zijn gezicht. Kijk zonder geluid te maken met interesse naar de repetitie van deze kleine toneelspeler.', title_pl = 'Rywal w lustrze 🪞', body_pl = 'Stoi przed lustrem, marszczy brwi i robi do siebie złe i dziwne miny. Sprawdza, jak emocje wyglądają na jego twarzy. Bezgłośnie, z boku, obserwuj z ciekawością próbę tego miniaturowego aktora teatralnego.', title_pt = 'O rival no espelho 🪞', body_pt = 'Põe-se em frente ao espelho a franzir a testa e a fazer caras zangadas e estranhas para si próprio. Está a testar como as emoções aparecem no rosto. Observe com interesse, à distância e sem fazer barulho, o ensaio deste pequeno ator de teatro.', title_sv = 'Rivalen i spegeln 🪞', body_sv = 'Barnet står framför spegeln och rynkar pannan, gör arga och konstiga miner. Barnet testar hur känslorna syns i ansiktet. Titta nyfiket och tyst från sidan på den lilla teaterskådespelarens repetition.', title_vi = 'Đối thủ trong gương 🪞', body_vi = 'Bé đứng trước gương, tự nhíu mày, làm những biểu cảm giận dữ và kỳ quặc. Bé đang thử xem cảm xúc hiện lên trên khuôn mặt mình ra sao. Hãy lặng lẽ, thích thú theo dõi buổi tập của "diễn viên kịch" tí hon này từ xa.', title_zh = '镜子里的对手 🪞', body_zh = '站在镜子前，对着自己皱眉，做出生气又奇怪的表情。宝宝在测试情绪在脸上是什么样子。在一旁别出声，饶有兴致地欣赏这位迷你剧场演员的排练吧。' WHERE id = 'da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tienda imaginaria 🍅', body_es = 'En un rincón de la habitación ha juntado sus juguetes y te vende tomates imaginarios con dinero imaginario. Ponte muy seria en este juego de comercio. Compra ese tomate imaginario y haz como que te lo comes con ganas. Los juegos de rol son la base más sólida de su inteligencia social.', title_fr = 'Le magasin imaginaire 🍅', body_fr = 'Dans un coin de la pièce, il a rassemblé ses jouets et vous vend des tomates imaginaires avec de l''argent imaginaire. Soyez très sérieuse dans ce jeu de commerce. Achetez cette tomate imaginaire et faites semblant de la manger avec appétit. Les jeux de rôle sont la base la plus solide de son intelligence sociale.', title_hi = 'काल्पनिक दुकान 🍅', body_hi = 'कमरे के एक कोने में खिलौने जमा करके आपको काल्पनिक पैसों में काल्पनिक टमाटर बेच रहा है। इस व्यापार के खेल में बहुत गंभीर रहिए। वह काल्पनिक टमाटर खरीदकर ऐसे दिखाइए जैसे चाव से खा रही हों। रोल-प्ले खेल उसकी सामाजिक समझ की सबसे मज़बूत नींव हैं।', title_id = 'Toko khayalan 🍅', body_id = 'Di sudut kamar ia mengumpulkan mainan dan menjual tomat khayalan kepada Anda dengan uang khayalan. Bersikaplah sangat serius dalam permainan dagang ini. Belilah tomat khayalan itu dan berpura-puralah memakannya dengan lahap. Bermain peran adalah fondasi terkuat kecerdasan sosialnya.', title_ja = '空想のお店 🍅', body_ja = '部屋のすみにおもちゃを集めて、空想のお金で空想のトマトを売ってくれる。このお店ごっこでは、とても真剣にふるまいましょう。そのトマトを買って、おいしそうに食べるふりをして。ごっこ遊びは、社会性のいちばん強い土台です。', title_ko = '상상 속 가게 🍅', body_ko = '방 한쪽에 장난감을 모아 놓고 상상의 돈으로 상상의 토마토를 파나요? 이 장사 놀이에서는 아주 진지해야 해요. 그 토마토를 사서 맛있게 먹는 척해 주세요. 역할 놀이는 사회적 지능의 가장 튼튼한 바탕이에요.', title_nl = 'De denkbeeldige winkel 🍅', body_nl = 'Hij heeft in een hoek van de kamer zijn speelgoed verzameld en verkoopt je denkbeeldige tomaten voor denkbeeldig geld. Wees heel serieus in dit handelsspel. Koop die denkbeeldige tomaat en doe alsof je hem met smaak opeet. Rollenspel is de sterkste basis voor zijn sociale intelligentie.', title_pl = 'Wymyślony sklep 🍅', body_pl = 'W kącie pokoju zebrał zabawki i sprzedaje ci wymyślone pomidory za wymyślone pieniądze. Bądź w tej grze w handel bardzo poważna. Kup ten wymyślony pomidor i udawaj, że zajadasz go z apetytem. Zabawy w odgrywanie ról to najmocniejszy fundament jego inteligencji społecznej.', title_pt = 'Loja imaginária 🍅', body_pt = 'Num canto do quarto, junta os brinquedos e vende-lhe tomates imaginários com dinheiro imaginário. Leve este jogo de comércio muito a sério. Compre aquele tomate imaginário e finja que o come com apetite. As brincadeiras de faz de conta são a base mais forte da inteligência social dele.', title_sv = 'Låtsasaffären 🍅', body_sv = 'I ett hörn av rummet samlar barnet leksaker och säljer låtsastomater till dig för låtsaspengar. Var väldigt seriös i handelsleken. Köp låtsastomaten och låtsas äta den med god aptit. Rollekar är den starkaste grunden för barnets sociala intelligens.', title_vi = 'Cửa hàng tưởng tượng 🍅', body_vi = 'Bé gom đồ chơi vào một góc phòng và bán cho mẹ cà chua tưởng tượng bằng tiền tưởng tượng. Hãy thật nghiêm túc trong trò chơi buôn bán này. Mua quả cà chua tưởng tượng và giả vờ ăn thật ngon lành. Trò chơi nhập vai là nền tảng vững chắc nhất cho trí tuệ xã hội của bé.', title_zh = '想象中的商店 🍅', body_zh = '在房间一角把玩具堆起来，用想象中的钱卖给你想象中的番茄。在这场买卖游戏里要非常认真。买下那个想象中的番茄，装作吃得津津有味。角色扮演游戏是宝宝社交智力最坚实的基础。' WHERE id = '4a5979ea-637a-48c3-a6a9-1af57b3d55c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hipnosis musical 🎶', body_es = 'Han empezado las tormentas sin motivo del atardecer y las crisis de llanto. Apaga la tele, baja las luces y pon en la habitación una música clásica muy suave. La frecuencia profunda de la música cambiará el ambiente como por arte de magia.', title_fr = 'Hypnose musicale 🎶', body_fr = 'Les tempêtes sans raison et les crises de larmes de fin de journée ont commencé. Éteignez la télé, baissez les lumières et mettez une musique classique très douce dans la pièce. La fréquence profonde de la musique changera l''atmosphère comme par magie.', title_hi = 'संगीत का सम्मोहन 🎶', body_hi = 'शाम को बिना वजह के तूफ़ान, रोने के दौर शुरू हो गए हैं। टीवी बंद कीजिए, रोशनी धीमी कीजिए और कमरे में बहुत हल्का शास्त्रीय संगीत चलाइए। संगीत की वह गहरी तरंग माहौल को जादुई तरीके से बदल देगी।', title_id = 'Hipnosis musik 🎶', body_id = 'Badai tanpa sebab dan krisis tangis menjelang malam sudah dimulai. Matikan TV, redupkan lampu, dan putar musik klasik yang sangat lembut di kamar. Frekuensi musik yang dalam akan mengubah suasana secara ajaib.', title_ja = '音楽の催眠術 🎶', body_ja = '夕方のわけのわからない嵐や、泣きじゃくりが始まりました。テレビを消して明かりを落とし、部屋にとてもやさしいクラシック音楽を流しましょう。音楽の深い響きが、空気を魔法のように変えてくれます。', title_ko = '음악 최면 🎶', body_ko = '저녁 무렵 이유 없는 폭풍과 울음이 시작됐나요? TV를 끄고 불을 낮춘 뒤 아주 잔잔한 클래식 음악을 틀어 주세요. 음악의 깊은 울림이 분위기를 마법처럼 바꿔 줄 거예요.', title_nl = 'Muzikale hypnose 🎶', body_nl = 'De onverklaarbare stormen en huilbuien van eind van de middag zijn begonnen. Zet de tv uit, dim de lichten en zet heel zachte klassieke muziek op. De diepe frequentie van de muziek verandert de sfeer op magische wijze.', title_pl = 'Muzyczna hipnoza 🎶', body_pl = 'Zaczęły się wieczorne burze bez powodu i kryzysy z płaczem. Wyłącz telewizor, przygaś światła i puść w pokoju bardzo cichą muzykę klasyczną. Głęboka częstotliwość muzyki magicznie zmieni atmosferę.', title_pt = 'Hipnose musical 🎶', body_pt = 'Começaram as tempestades sem razão e as crises de choro do fim da tarde. Desligue a televisão, baixe as luzes e ponha no quarto uma música clássica muito suave. A frequência profunda da música vai mudar o ambiente como por magia.', title_sv = 'Musikalisk hypnos 🎶', body_sv = 'Omotiverade stormar och gråtkriser framåt kvällen har börjat. Stäng av tv:n, dämpa ljuset och sätt på mycket lätt klassisk musik i rummet. Musikens djupa frekvens förändrar stämningen magiskt.', title_vi = 'Thôi miên bằng âm nhạc 🎶', body_vi = 'Những cơn bùng nổ vô cớ, những trận khóc lúc chiều tối đã bắt đầu. Hãy tắt tivi, giảm đèn và bật thật khẽ một bản nhạc cổ điển nhẹ nhàng. Tần số sâu lắng của âm nhạc sẽ thay đổi bầu không khí một cách kỳ diệu.', title_zh = '音乐催眠 🎶', body_zh = '傍晚莫名的小风暴和哭闹开始了。关掉电视，把灯光调暗，在房间里放一点很轻柔的古典音乐。音乐深沉的频率会神奇地改变气氛。' WHERE id = '58c30ae3-2599-434d-af6b-bb25c9a1766d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy se te ha acabado la paciencia? No te sientas mal. Aléjate de esas ilusiones de madres impecables de internet. Eres una madre real y tienes derecho a vivir tus emociones y tu cansancio.', body_fr = 'Votre patience a lâché aujourd''hui ? Ne vous sentez pas coupable. Éloignez-vous de ces illusions de mamans parfaites sur Internet. Vous êtes une vraie maman, vous avez le droit de vivre vos émotions et votre fatigue.', body_hi = 'आज आपका धैर्य जवाब दे गया? खुद को बुरा महसूस मत कराइए। इंटरनेट की उन बेदाग माँओं के भ्रम से दूर रहिए। आप एक असली माँ हैं, आपको अपनी भावनाएँ और थकान जीने का हक है।', body_id = 'Hari ini kesabaran Anda menipis? Jangan merasa buruk. Jauhi ilusi ibu sempurna di internet. Kamu ibu yang nyata, kamu boleh merasakan emosi dan lelahmu.', body_ja = '今日はがまんの限界でしたか？落ちこまないで。ネットの完璧なママという幻想から離れましょう。あなたはリアルなママ。自分の気持ちや疲れを、ちゃんと感じていいんです。', body_ko = '오늘 인내심이 바닥났나요? 자책하지 마세요. 인터넷 속 완벽한 엄마라는 환상에서 멀어지세요. 엄마는 진짜 엄마이고, 감정과 피로를 느껴도 괜찮아요.', body_nl = 'Was je geduld vandaag op? Voel je niet slecht. Blijf weg van die illusies van de perfecte moeder op internet. Je bent een echte mama, je mag je emoties en je vermoeidheid voelen.', body_pl = 'Dziś zabrakło ci cierpliwości? Nie czuj się z tym źle. Odsuń się od tych nieskazitelnych iluzji mam z internetu. Jesteś prawdziwą mamą i masz prawo przeżywać swoje emocje i zmęczenie.', body_pt = 'Hoje perdeu a paciência? Não se sinta mal. Afaste-se das ilusões de mãe perfeita da internet. É uma mãe real: tem direito a viver as suas emoções e o seu cansaço.', body_sv = 'Tröt tålamodet i dag? Må inte dåligt. Håll dig borta från de felfria mammaillusionerna på nätet. Du är en verklig mamma, du får leva ut dina känslor och din trötthet.', body_vi = 'Hôm nay mẹ hết kiên nhẫn? Đừng thấy mình tệ. Hãy tránh xa những ảo tưởng về người mẹ hoàn hảo trên mạng. Mẹ là một người mẹ thật, mẹ được phép sống với cảm xúc và sự mệt mỏi của mình.', body_zh = '今天快没耐心了？别觉得自己很糟。远离网上那些完美妈妈的幻象。你是一位真实的妈妈，你有权经历自己的情绪和疲惫。' WHERE id = 'd8b0e257-5429-4bf7-b2a7-1bb116658651' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Siempre se te olvida lo más importante al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que haga falta y que tu pareja lo compre con precisión al volver del trabajo. No canses tu mente.', body_fr = 'Vous oubliez toujours le plus important en allant au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins pour que votre partenaire rapporte tout avec précision en rentrant du travail. Ne fatiguez pas votre cerveau.', body_hi = 'बाज़ार जाते समय सबसे ज़रूरी चीज़ ज़रूर भूल जाती हैं? शॉपिंग लिस्ट ऐप में आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके साथी काम से लौटते समय ठीक-ठीक सामान ले आएँ, आप दिमाग मत थकाइए।', body_id = 'Selalu lupa barang paling penting saat ke supermarket? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan Anda membelinya dengan tepat sepulang kerja, dan Anda tak perlu membebani otak.', body_ja = '買い物に行くと、必ずいちばん大事なものを忘れる？アプリの「買い物リスト」が待っています。必要なものを書きこんで、パートナーが仕事帰りにきっちり買ってこられるようにしましょう。あなたは頭を休ませて。', body_ko = '마트에 가면 꼭 가장 중요한 걸 잊나요? 앱에서 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요. 머리를 혹사하지 마세요.', body_nl = 'Vergeet je altijd het belangrijkste als je naar de supermarkt gaat? Het Boodschappenlijstje wacht in de app op je. Zet er alles op wat je nodig hebt, zodat je partner het op weg naar huis precies kan meenemen. Zo hoef jij je hoofd niet te vermoeien.', body_pl = 'Idąc do sklepu, zawsze zapominasz o najważniejszej rzeczy? Lista zakupów czeka na ciebie w aplikacji. Zapisuj tam potrzeby, niech partner w drodze z pracy dokładnie wszystko kupi, a ty nie męcz głowy.', body_pt = 'Quando vai ao supermercado, esquece-se sempre da coisa mais importante? A Lista de Compras está à sua espera na app. Registe lá o que faz falta para que o seu companheiro compre tudo certinho ao voltar do trabalho, e não canse a cabeça.', body_sv = 'Glömmer du alltid det allra viktigaste när du går till butiken? Inköpslistan väntar på dig i appen. Skriv upp behoven där, så kan din partner handla exakt rätt på vägen hem från jobbet, och du slipper trötta ut hjärnan.', body_vi = 'Đi siêu thị lần nào cũng quên món quan trọng nhất? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó, để chồng trên đường đi làm về mua đầy đủ, chính xác, còn mẹ khỏi phải nhọc đầu.', body_zh = '去超市总会忘掉最重要的那样东西？购物清单在应用里等着你。把需要的东西记进去，让伴侣下班回家时准确买齐，你就别再费脑子了。' WHERE id = '4673a3e6-d285-4515-9173-039b8bcbc1e0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Mamá, mírame!» 👀', body_es = 'Salta del sofá y, haciendo el mismo movimiento exactamente 50 veces, dice cada vez: «¡Mamá, mírame!». Aparta los ojos del móvil. Salta por ese brillo de aprobación en tus ojos. Dale 5 minutos sin interrupciones para que se llene de atención.', title_fr = 'La période du « Maman, regarde-moi ! » 👀', body_fr = 'Il saute du canapé et refait exactement le même geste 50 fois en criant « Maman, regarde-moi ! ». Quittez le téléphone des yeux. Il saute pour cette lueur d''approbation dans vos yeux. Donnez-lui 5 minutes sans interruption, qu''il soit comblé d''attention.', title_hi = '‘माँ, मुझे देखो!’ का दौर 👀', body_hi = 'सोफ़े से कूदता है और पूरे 50 बार वही हरकत करके कहता है, ‘माँ, मुझे देखो!’ फ़ोन से नज़र हटाइए। वह आपकी आँखों में शाबाशी की उस चमक के लिए कूदता है। उसे बिना रुकावट 5 मिनट दीजिए, ताकि ध्यान से उसका मन भर जाए।', title_id = 'Masa ''Ma, lihat aku!'' 👀', body_id = 'Ia melompat dari sofa, mengulang gerakan yang sama tepat 50 kali, dan setiap kali berkata ''Ma, lihat aku!''. Alihkan mata dari ponsel. Ia melompat demi kilau pengakuan di mata Anda. Beri ia 5 menit tanpa gangguan, biar ia kenyang perhatian.', title_ja = '「ママ、見て！」の時期 👀', body_ja = 'ソファからジャンプして、同じ動きをちょうど50回くり返すたびに「ママ、見て！」。スマホから目を離して。あなたの目に浮かぶ「すごいね」の輝きのために跳んでいるんです。とぎれない5分をあげて、注目で満たしてあげましょう。', title_ko = '''엄마, 나 좀 봐!'' 시기 👀', body_ko = '소파에서 뛰어내리며 똑같은 동작을 50번이나 하고 매번 ''엄마, 나 좀 봐!''라고 하나요? 휴대폰에서 눈을 떼세요. 엄마 눈 속 인정의 반짝임을 위해 뛰는 거예요. 5분만 온전히 봐 주면 관심이 가득 채워질 거예요.', title_nl = 'De ''Mama, kijk naar mij!''-fase 👀', body_nl = 'Hij springt van de bank en doet precies 50 keer hetzelfde, en elke keer roept hij ''Mama, kijk naar mij!''. Kijk weg van je telefoon. Hij springt voor die glinstering van goedkeuring in jouw ogen. Geef hem 5 minuten ononderbroken aandacht, tot hij vol is.', title_pl = 'Etap „Mamo, patrz na mnie!” 👀', body_pl = 'Skacze z kanapy, powtarza ten sam ruch równo 50 razy i za każdym razem woła „Mamo, patrz na mnie!”. Oderwij wzrok od telefonu. Skacze dla tego błysku uznania w twoich oczach. Daj mu 5 minut nieprzerwanej uwagi, niech się nią nasyci.', title_pt = 'A fase do "Mãe, olha para mim!" 👀', body_pt = 'Salta do sofá e, de cada vez, repete o mesmo movimento exatamente 50 vezes a dizer "Mãe, olha para mim!". Tire os olhos do telemóvel. Ele salta por aquele brilho de aprovação nos seus olhos. Dê-lhe 5 minutos sem interrupções e ele fica saciado de atenção.', title_sv = 'Perioden ”Mamma, titta på mig!” 👀', body_sv = 'Barnet hoppar från soffan och gör samma sak precis 50 gånger och säger varje gång ”Mamma, titta på mig!”. Ta blicken från telefonen. Barnet hoppar för bekräftelsen som glittrar i dina ögon. Ge barnet 5 oavbrutna minuter, så blir det mätt på uppmärksamhet.', title_vi = 'Giai đoạn "Mẹ ơi, nhìn con này!" 👀', body_vi = 'Bé nhảy từ sofa xuống, lặp lại đúng một động tác tới 50 lần và lần nào cũng nói "Mẹ ơi, nhìn con này!". Hãy rời mắt khỏi điện thoại. Bé nhảy vì ánh mắt công nhận lấp lánh của mẹ. Hãy dành cho bé 5 phút trọn vẹn để bé được chú ý đủ đầy.', title_zh = '“妈妈，看我！”时期 👀', body_zh = '从沙发上跳下来，同一个动作做了整整50遍，每次都喊“妈妈，看我！”。把目光从手机上移开。宝宝跳，是为了你眼中那一闪而过的肯定。给宝宝不被打断的5分钟，让宝宝的关注需求得到满足吧。' WHERE id = 'dd38c03c-a89e-4942-af31-f459dbf71386' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historias susurradas 🌙', body_es = 'Hoy has hablado muy alto y tienes los pulmones cansados. Apaga las luces, túmbate a su lado y cuéntale lo que ha pasado durante el día solo susurrándole al oído. El susurro concentra su atención y prepara su cerebro de forma hipnótica para un sueño profundo.', title_fr = 'Histoires chuchotées 🌙', body_fr = 'Vous avez beaucoup élevé la voix aujourd''hui, vos poumons sont fatigués. Éteignez les lumières, allongez-vous près de lui et racontez-lui simplement sa journée en chuchotant à l''oreille. Le chuchotement concentre son attention et prépare son cerveau de façon presque hypnotique à un sommeil profond.', title_hi = 'फुसफुसाती कहानियाँ 🌙', body_hi = 'आज आपकी आवाज़ बहुत ऊँची हुई, फेफड़े थक गए। लाइटें बंद कीजिए, उसके पास लेटिए और दिनभर की बातें बस फुसफुसाकर उसके कान में कहिए। फुसफुसाहट उसका ध्यान केंद्रित करती है और उसके दिमाग को सम्मोहन की तरह गहरी नींद के लिए तैयार करती है।', title_id = 'Cerita berbisik 🌙', body_id = 'Hari ini Anda sudah banyak bersuara, paru-paru Anda lelah. Matikan lampu, berbaringlah di sampingnya, dan ceritakan kejadian hari ini ke telinganya cukup dengan berbisik. Bisikan memusatkan perhatiannya dan menyiapkan otaknya untuk tidur nyenyak seperti terhipnotis.', title_ja = 'ささやきのおはなし 🌙', body_ja = '今日はたくさん声を出して、肺も疲れていますね。明かりを消してそばに横になり、今日あったことを耳もとでささやくだけで話してあげて。ささやき声は注意を集め、脳を催眠のように深い眠りへと導きます。', title_ko = '속삭이는 이야기 🌙', body_ko = '오늘 목소리를 많이 써서 숨이 차나요? 불을 끄고 옆에 누워 오늘 있었던 일을 귓가에 속삭이기만 하세요. 속삭임은 아이의 집중을 모으고 뇌를 최면처럼 깊은 잠으로 이끌어요.', title_nl = 'Fluisterverhalen 🌙', body_nl = 'Je hebt je stem vandaag veel gebruikt en je longen zijn moe. Doe de lichten uit, ga naast hem liggen en vertel hem fluisterend in zijn oor wat er vandaag is gebeurd. Fluisteren richt zijn aandacht en maakt zijn brein op een hypnotiserende manier klaar voor een diepe slaap.', title_pl = 'Historie szeptem 🌙', body_pl = 'Dziś dużo używałaś głosu, płuca są zmęczone. Zgaś światła, połóż się obok i po prostu wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia. Szept skupia jego uwagę i niemal hipnotycznie przygotowuje mózg do głębokiego snu.', title_pt = 'Histórias em sussurro 🌙', body_pt = 'Hoje já levantou muito a voz e os pulmões estão cansados. Apague as luzes, deite-se ao lado dele e conte-lhe ao ouvido, só em sussurro, o que aconteceu durante o dia. O sussurro concentra a atenção dele e prepara o cérebro de forma hipnótica para um sono profundo.', title_sv = 'Viskade berättelser 🌙', body_sv = 'Du har höjt rösten mycket i dag och lungorna är trötta. Släck ljuset, lägg dig bredvid barnet och viska bara om det som hänt under dagen. Viskningar fokuserar barnets uppmärksamhet och förbereder hjärnan nästan hypnotiskt för djup sömn.', title_vi = 'Những câu chuyện thì thầm 🌙', body_vi = 'Hôm nay mẹ đã nói rất nhiều, phổi cũng mệt rồi. Hãy tắt đèn, nằm cạnh bé và chỉ thì thầm vào tai bé về những gì đã xảy ra trong ngày. Lời thì thầm giúp bé tập trung và đưa não bộ vào giấc ngủ sâu như bị thôi miên.', title_zh = '悄悄话故事 🌙', body_zh = '今天你说了太多话，嗓子都累了。关上灯，躺在宝宝身边，只用悄悄话在宝宝耳边讲讲今天发生的事。悄悄话能让宝宝集中注意力，像催眠一样让大脑准备好进入深度睡眠。' WHERE id = 'effd03a1-4f68-42a7-8c25-eabba9947bc3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación comida secreta 🥣', body_es = 'El huevo que hasta ayer le encantaba hoy no hay manera de que lo pruebe. No luches contra su voluntad. Usa en Recetas saludables recetas de tentempiés astutos que den a las proteínas formas diferentes, coloridas e interesantes, y gana tú.', title_fr = 'Opération nourriture cachée 🥣', body_fr = 'L''œuf qu''il adorait encore hier, impossible de le lui faire goûter aujourd''hui. Ne luttez pas contre sa volonté. Essayez dans les Recettes saines des collations astucieuses qui donnent aux protéines des formes différentes, colorées et amusantes, et c''est vous qui gagnerez.', title_hi = 'खाना छिपाने का गुप्त ऑपरेशन 🥣', body_hi = 'कल तक जो अंडा पसंद था, आज उसे मुँह तक नहीं लगाता। उसकी इच्छा से मत लड़िए। सेहतमंद रेसिपी में प्रोटीन को अलग, रंगीन और दिलचस्प आकार देने वाली चालाक स्नैक रेसिपी आज़माइए और जीत आपकी हो।', title_id = 'Operasi makanan tersembunyi 🥣', body_id = 'Telur yang sampai kemarin ia suka, hari ini sama sekali tak mau ia makan. Jangan melawan kemauannya. Terapkan resep camilan cerdik di Resep Sehat yang mengubah protein menjadi bentuk berbeda, berwarna, dan menarik, dan jadilah pemenangnya.', title_ja = 'こっそり栄養作戦 🥣', body_ja = '昨日まで大好きだった卵を、今日はひと口も食べない。意志と戦わないで。「ヘルシーレシピ」で、たんぱく質をカラフルで楽しい形に変える工夫おやつのレシピを試して、勝ちをつかみましょう。', title_ko = '비밀 음식 작전 🥣', body_ko = '어제까지 좋아하던 달걀을 오늘은 입에도 대지 않나요? 의지와 싸우지 마세요. 건강한 레시피에서 단백질을 색다르고 알록달록하고 재미있는 모양으로 바꾸는 기발한 간식 레시피를 활용해 승자가 되세요.', title_nl = 'Geheime voedingsoperatie 🥣', body_nl = 'Het ei waar hij tot gisteren dol op was, wil hij vandaag niet eens proeven. Vecht niet tegen zijn wil. Probeer de slimme snackrecepten uit Gezonde recepten die eiwitten in andere, kleurrijke en leuke vormen gieten, en win.', title_pl = 'Tajna operacja jedzeniowa 🥣', body_pl = 'Jajka, które jeszcze wczoraj uwielbiał, dziś nie chce tknąć. Nie walcz z jego wolą. Wypróbuj ze Zdrowych przepisów sprytne przekąski, które nadadzą białku inne, kolorowe i ciekawe kształty, i to ty wygrywasz.', title_pt = 'Operação comida escondida 🥣', body_pt = 'Até ontem adorava ovos e hoje nem os deixa chegar à boca. Não lute contra a vontade dele. Experimente nas Receitas Saudáveis snacks engenhosos que dão às proteínas formas diferentes, coloridas e interessantes, e seja a mãe a ganhar.', title_sv = 'Hemlig matoperation 🥣', body_sv = 'Ägget som barnet älskade fram till i går får du i dag inte ens i barnets mun. Kämpa inte mot barnets vilja. Använd listiga mellanmålsrecept från Hälsosamma recept som ger proteinerna nya, färgglada och spännande former, och vinn.', title_vi = 'Chiến dịch giấu thức ăn 🥣', body_vi = 'Món trứng đến hôm qua bé còn thích, hôm nay lại không chịu ăn. Đừng đấu với ý chí của bé. Hãy áp dụng trong Công thức lành mạnh những công thức món ăn nhẹ khéo léo biến chất đạm thành những hình dạng khác lạ, nhiều màu sắc, thú vị và giành chiến thắng.', title_zh = '秘密食物行动 🥣', body_zh = '直到昨天还喜欢的鸡蛋，今天碰都不肯碰。别和宝宝的意志较劲。用上健康食谱里那些把蛋白质做成不同、彩色又有趣造型的小零食妙招，赢下这一局吧。' WHERE id = '2c31302d-18e1-44cd-8719-76e1444cd735' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tras un día ruidoso, cuando el peque se duerma, mide el silencio de la habitación con el Medidor de sonido. Ver esos números acercarse a cero, esa calma visual, es como el mejor masaje para el cerebro de una madre.', body_fr = 'Après une journée bruyante, quand il dort, mesurez le silence de la chambre avec le Sonomètre. Voir ces chiffres s''approcher de zéro, ce calme visuel, agit comme le plus doux des massages pour le cerveau d''une maman.', body_hi = 'शोर भरे दिन के बाद, बच्चे के सोने पर साउंड मीटर से कमरे की खामोशी मापिए। शून्य के करीब पहुँचते अंक और वह दिखती शांति माँ के दिमाग के लिए सबसे प्यारी मसाज जैसी है।', body_id = 'Setelah hari yang bising, saat anak sudah tidur, ukur keheningan kamar dengan Pengukur Suara. Melihat angka yang mendekati nol, ketenangan visual itu, terasa seperti pijatan terindah untuk otak seorang ibu.', body_ja = 'にぎやかな一日のあと、子どもが寝たら「サウンドメーター」で部屋の静けさを測ってみましょう。ゼロに近づいていく数字を見ること、その目に見える静けさが、ママの脳にはいちばん心地よいマッサージになります。', body_ko = '시끌벅적한 하루가 끝나고 아이가 잠들면 소음 측정기로 방의 고요를 재 보세요. 0에 가까워지는 숫자와 그 시각적인 평온이 엄마의 머리에 가장 좋은 마사지가 돼요.', body_nl = 'Meet na een lawaaiige dag, als hij slaapt, de stilte in de kamer met de Geluidsmeter. Die getallen richting nul zien zakken, die visuele rust, werkt als de fijnste massage voor het brein van een mama.', body_pl = 'Po hałaśliwym dniu, gdy dziecko zaśnie, zmierz ciszę w pokoju Miernikiem dźwięku. Widok liczb zbliżających się do zera, ten wizualny spokój, działa na mózg mamy jak najpiękniejszy masaż.', body_pt = 'Depois de um dia barulhento, quando a criança adormecer, meça o silêncio do quarto com o Medidor de Som. Ver os números a aproximarem-se do zero, essa calma visual, funciona como a melhor massagem para o cérebro da mãe.', body_sv = 'Efter en bullrig dag, mät tystnaden i rummet med Ljudmätaren när barnet sover. Att se siffrorna närma sig noll, det visuella lugnet, fungerar som den skönaste massagen för en mammas hjärna.', body_vi = 'Sau một ngày ồn ào, khi bé đã ngủ, hãy dùng Đo âm thanh để đo sự yên tĩnh trong phòng. Nhìn những con số tiến dần về không, sự yên bình hiện ra trước mắt ấy giống như màn mát-xa tuyệt vời nhất cho não bộ của mẹ.', body_zh = '热闹的一天过后，等宝宝睡着了，用分贝仪测一测房间的安静程度。看着那些越来越接近零的数字，那种视觉上的平静，对妈妈的大脑来说就像一次最美好的按摩。' WHERE id = '723d3b58-0a46-493d-ba9b-9e4d8c6656ee' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un «te quiero» por sorpresa 💖', body_es = 'Jugando en medio de la habitación, de repente te mira, viene corriendo y se te cuelga del cuello. ¡Vale la pena por todas las noches sin dormir y todo el cansancio! Disfruta de la paz profunda y única de este momento.', title_fr = 'Un « Je t''aime » soudain 💖', body_fr = 'En jouant au milieu de la pièce, il vous regarde soudain, accourt et se jette à votre cou. Cela vaut toutes les nuits blanches et toute la fatigue ! Savourez la paix profonde et unique de ce moment.', title_hi = 'अचानक ‘आई लव यू’ 💖', body_hi = 'कमरे के बीच खेलते-खेलते अचानक आपकी ओर देखकर दौड़ता आता है और गले से लिपट जाता है। सारी जागी रातें, सारी थकान इसके लायक थी! इस पल के गहरे, अनोखे सुकून का आनंद लीजिए।', title_id = '''Aku sayang Mama'' yang tiba-tiba 💖', body_id = 'Sedang bermain di tengah kamar, tiba-tiba ia menatap Anda, berlari, dan memeluk leher Anda. Itu sepadan dengan semua malam tanpa tidur dan rasa lelah! Nikmati ketenangan yang dalam dan istimewa dari momen ini.', title_ja = '不意打ちの「大好き」 💖', body_ja = '部屋のまんなかで遊んでいたのに、ふとあなたを見て走ってきて、首にぎゅっと抱きついてくる。眠れない夜も疲れも、すべて報われますね！この瞬間がくれる深くて特別な幸せをかみしめて。', title_ko = '갑작스러운 ''사랑해'' 💖', body_ko = '방 한가운데서 놀다가 갑자기 엄마를 보고 달려와 목을 꼭 끌어안나요? 잠 못 잔 밤과 피로가 모두 보상받는 순간이에요! 이 순간의 깊고 특별한 평온을 마음껏 누리세요.', title_nl = 'Een onverwacht ''Ik hou van je'' 💖', body_nl = 'Midden in het spelen kijkt hij je ineens aan, rent naar je toe en slaat zijn armpjes om je nek. Dat is alle slapeloze nachten en vermoeidheid waard! Geniet van de diepe, unieke rust die dit moment je geeft.', title_pl = 'Nagłe „Kocham cię” 💖', body_pl = 'Bawiąc się na środku pokoju, nagle na ciebie spojrzał, przybiegł i objął cię za szyję. To jest warte wszystkich nieprzespanych nocy i zmęczenia! Delektuj się tym głębokim, wyjątkowym spokojem tej chwili.', title_pt = 'Um "Amo-te" de repente 💖', body_pt = 'A brincar no meio do quarto, olha de repente para si, vem a correr e abraça-se ao seu pescoço. Valeu todas as noites sem dormir e todo o cansaço! Saboreie a calma profunda e única deste momento.', title_sv = 'Ett plötsligt ”Jag älskar dig” 💖', body_sv = 'Mitt i leken tittar barnet plötsligt på dig, springer fram och kramar dig om halsen. Det var värt alla sömnlösa nätter och all trötthet! Njut av det djupa, unika lugn som stunden ger.', title_vi = '"Con yêu mẹ" bất ngờ 💖', body_vi = 'Đang chơi giữa phòng, bé bỗng nhìn mẹ, chạy đến và ôm chầm lấy cổ mẹ. Thật xứng đáng với mọi đêm mất ngủ và mệt mỏi! Hãy tận hưởng cảm giác bình yên sâu lắng, đặc biệt mà khoảnh khắc này mang lại.', title_zh = '突然的“我爱你” 💖', body_zh = '在房间中间玩着玩着，突然看你一眼，跑过来搂住你的脖子。所有不眠的夜晚、所有的疲惫都值了！好好享受这一刻带来的那份深深的、独一无二的安宁。' WHERE id = 'f226f50f-54a9-4f4e-ad02-b0959087d7d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces, es hora de dormir 🌙', body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina (la hormona del sueño) solo se libera rápido en un ambiente oscuro y sin tecnología.', title_fr = 'On éteint, c''est l''heure de dormir 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine (l''hormone du sommeil) n''est sécrétée rapidement que dans un environnement sombre et sans écran.', title_hi = 'लाइटें बंद, सोने का समय 🌙', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन (नींद का हार्मोन) सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है।', title_id = 'Matikan lampu, saatnya tidur 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin (hormon tidur) hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi.', title_ja = '明かりを消して、おやすみの時間 🌙', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニン（睡眠ホルモン）は、暗くてデジタル機器のない環境でこそすばやく分泌されます。', title_ko = '불 끄고, 이제 잘 시간 🌙', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌(수면 호르몬)은 어둡고 기기가 없는 환경에서만 빠르게 분비돼요.', title_nl = 'Lichten uit, tijd om te slapen 🌙', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine (het slaaphormoon) wordt alleen snel aangemaakt in een donkere omgeving zonder technologie.', title_pl = 'Gasimy światło, czas spać 🌙', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina (hormon snu) szybko wydziela się tylko w ciemnym otoczeniu bez technologii.', title_pt = 'Apague as luzes, é hora de dormir 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina (hormona do sono) só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Släck lamporna, dags att sova 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin (sömnhormonet) utsöndras snabbt bara i en mörk och teknikfri miljö.', title_vi = 'Tắt đèn, đến giờ ngủ rồi 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin (hormone giấc ngủ) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '关灯，该睡觉了 🌙', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素（睡眠激素）只有在昏暗、没有电子产品的环境里才会快速分泌。' WHERE id = '3517ce10-8615-407d-be3b-394eda1c9fa6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Corre mucho, pero se le olvida beber agua. Fíjate en lo que hace en el orinal. Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida avena y ciruelas al menú con el Seguimiento de tomas.', body_fr = 'Il court beaucoup mais oublie de boire. Surveillez ses selles dans le pot. En cas de risque de constipation, notez-le dans l''application et ajoutez tout de suite de l''avoine et des pruneaux à son menu avec le Suivi des repas.', body_hi = 'बहुत दौड़ता है, पर पानी पीना भूल जाता है। पॉटी में उसका मल देखते रहिए। अगर कब्ज़ का खतरा है, तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से मेन्यू में ओट्स और आलूबुखारा जोड़िए।', body_id = 'Ia banyak berlari, tapi lupa minum air. Pantau buang airnya di pispot. Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan oat dan plum ke menunya dengan Pemantau Nutrisi.', body_ja = 'たくさん走りまわるのに、お水を飲むのを忘れがち。おまるでのうんちをチェックしましょう。便秘が心配なら、アプリに記録して、すぐに「栄養管理ツール」でオートミールとプルーンをメニューに加えましょう。', body_ko = '많이 뛰어다니지만 물 마시는 건 잊나요? 변기에서 배변을 살펴보세요. 변비 위험이 있다면 앱에 기록하고 바로 수유 기록 도구로 메뉴에 오트밀과 자두를 추가하세요.', body_nl = 'Hij rent veel, maar vergeet te drinken. Let op zijn ontlasting in het potje. Is er kans op verstopping, noteer het dan in de app en voeg met de Voedingstracker meteen havermout en pruimen aan het menu toe.', body_pl = 'Dużo biega, ale zapomina pić wodę. Obserwuj, co zostawia w nocniku. Jeśli jest ryzyko zaparcia, zapisz to w aplikacji i od razu dodaj do menu owsiankę i suszone śliwki za pomocą narzędzia do śledzenia karmienia.', body_pt = 'Corre muito, mas esquece-se de beber água. Esteja atenta ao que faz no bacio. Se houver risco de obstipação, registe-o na app e junte já à ementa aveia e ameixas com o Registo de Alimentação.', body_sv = 'Barnet springer mycket men glömmer att dricka vatten. Håll koll på det som kommer i pottan. Om det finns risk för förstoppning, anteckna det i appen och lägg genast till havre och plommon i menyn med verktyget Matningskoll.', body_vi = 'Bé chạy nhảy nhiều nhưng lại quên uống nước. Hãy để ý chuyện đi vệ sinh trong bô. Nếu có nguy cơ táo bón, hãy ghi lại trong ứng dụng và thêm ngay yến mạch, mận khô vào thực đơn bằng Theo dõi cữ bú.', body_zh = '跑得多，却忘了喝水。留意一下便盆里的排便情况。如果有便秘风险，记到应用里，马上用喂养记录工具在菜单里加入燕麦和西梅。' WHERE id = '7daa2d64-db1d-42ea-8cec-a0101d304bbf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te repite riéndose esa palabrota que ha oído en la calle o en la tele y espera tu reacción con mucha curiosidad. Tu mejor arma es no reaccionar. No te rías ni te enfades, simplemente ignóralo. Pronto olvidará esa palabra.', body_fr = 'Il vous répète en riant un gros mot entendu dans la rue ou à la télé et attend votre réaction avec une grande curiosité. Votre meilleure arme, c''est l''absence de réaction. Ne riez pas, ne vous fâchez pas, ignorez simplement. Il oubliera vite ce mot.', body_hi = 'सड़क या टीवी से सुना वह बुरा शब्द हँसते हुए आपके सामने दोहराता है और बड़ी उत्सुकता से आपकी प्रतिक्रिया का इंतज़ार करता है। आपका सबसे बड़ा हथियार है कोई प्रतिक्रिया न देना। हँसिए मत, नाराज़ मत होइए, बस अनदेखा कीजिए। वह जल्द ही वह शब्द भूल जाएगा।', body_id = 'Ia mengulang kata kasar yang ia dengar di jalan atau di TV sambil tertawa, lalu menunggu reaksi Anda dengan penasaran. Senjata terbesar Anda adalah tidak bereaksi. Jangan tertawa, jangan marah, cukup abaikan. Ia akan segera melupakan kata itu.', body_ja = '外やテレビで聞いた悪い言葉を、笑いながらくり返して、興味しんしんであなたの反応を待っている？いちばんの武器は、反応しないこと。笑わず、怒らず、ただ聞き流しましょう。その言葉はすぐに忘れます。', body_ko = '길이나 TV에서 들은 나쁜 말을 웃으며 따라 하고 잔뜩 기대하며 엄마의 반응을 기다리나요? 가장 강력한 무기는 무반응이에요. 웃지도, 화내지도 말고 그냥 못 들은 척하세요. 곧 그 말을 잊을 거예요.', body_nl = 'Herhaalt hij lachend een lelijk woord dat hij op straat of op tv hoorde, en wacht hij heel benieuwd op je reactie? Je grootste wapen is geen reactie. Lach niet, word niet boos, negeer het gewoon. Hij vergeet het woord snel.', body_pl = 'Ze śmiechem powtarza ci brzydkie słowo, które usłyszał na ulicy albo w telewizji, i z wielką ciekawością czeka na twoją reakcję. Twoją największą bronią jest brak reakcji. Nie śmiej się, nie złość, po prostu udawaj, że nie słyszysz. Szybko zapomni to słowo.', body_pt = 'Repete-lhe a rir aquela palavra feia que ouviu na rua ou na televisão e espera com grande curiosidade pela sua reação. A sua maior arma é não reagir. Não se ria, não se irrite, simplesmente ignore. Em breve vai esquecer a palavra.', body_sv = 'Upprepar barnet skrattande ett fult ord det hört på gatan eller på tv och väntar med stor nyfikenhet på din reaktion? Ditt största vapen är att inte reagera. Skratta inte, bli inte arg, låtsas bara inte höra. Barnet glömmer snart ordet.', body_vi = 'Bé cười và nhắc lại với mẹ một từ xấu nghe được ngoài đường hay trên tivi, rồi háo hức chờ xem mẹ phản ứng ra sao. Vũ khí lớn nhất của mẹ là không phản ứng. Đừng cười, đừng bực, chỉ cần lờ đi. Bé sẽ sớm quên từ đó thôi.', body_zh = '笑着跟你重复从街上或电视里听来的脏话，满怀好奇地等着看你的反应。你最强大的武器就是不反应。别笑，别生气，假装没听见就好。宝宝很快就会忘掉那个词。' WHERE id = 'e079d221-e081-498b-8457-7e4dc4555c89' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los dos estáis cansados de los libros de siempre. Esta vez, en Cuentos inteligentes, deja que tu peque elija el final de la historia. Pregúntale «¿Quién crees que ayudó al héroe?» y deja volar su imaginación antes de dormir.', body_fr = 'Les livres classiques vous lassent tous les deux. Cette fois, dans les Contes intelligents, laissez votre enfant choisir la fin de l''histoire. Libérez son imagination avant le coucher : « À ton avis, qui a aidé ce héros ? »', body_hi = 'आप दोनों पुरानी किताबों से थक चुके हैं। इस बार स्मार्ट कहानियों में कहानी का अंत अपने बच्चे से चुनवाइए। ‘तुम्हें क्या लगता है, उस हीरो की मदद किसने की?’ पूछकर सोने से पहले उसकी कल्पना को खुला छोड़िए।', body_id = 'Kalian berdua sudah lelah dengan buku klasik. Di Dongeng Pintar, kali ini biarkan anak Anda memilih akhir ceritanya. Tanyakan ''Menurutmu siapa yang membantu tokoh itu?'', dan bebaskan imajinasinya sebelum tidur.', body_ja = '定番の絵本にはふたりとも疲れてしまった？今回は「スマートおはなし」で、お話の結末をお子さんに選ばせてみましょう。「その主人公を助けたのは誰だと思う？」と聞いて、寝る前の想像力を自由にはばたかせて。', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 이번에는 스마트 동화에서 이야기의 결말을 아이가 고르게 해 보세요. ''그 주인공을 누가 도와줬을 것 같아?'' 물으며 잠들기 전 상상력을 자유롭게 풀어 주세요.', body_nl = 'Jullie zijn allebei de klassieke boeken moe. Laat je kind in Slimme sprookjes deze keer het einde van het verhaal kiezen. Vraag: ''Wie denk jij dat die held heeft geholpen?'' en laat zijn fantasie voor het slapengaan de vrije loop.', body_pl = 'Klasyczne książeczki zmęczyły was oboje. Tym razem w Mądrych bajkach pozwól dziecku wybrać zakończenie historii. Zapytaj: „Jak myślisz, kto pomógł temu bohaterowi?” i daj jego wyobraźni swobodę przed snem.', body_pt = 'Estão os dois cansados dos livros clássicos. Desta vez, nas Histórias Inteligentes, deixe o seu filho escolher o final da história. Pergunte "Quem achas que ajudou aquele herói?" e deixe a imaginação dele à solta antes de dormir.', body_sv = 'Ni är båda trötta på de klassiska böckerna. Låt den här gången barnet välja slutet på berättelsen i Smarta sagor. Fråga ”Vem tror du hjälpte hjälten?” och släpp fantasin fri före sömnen.', body_vi = 'Cả hai mẹ con đều đã mệt với những cuốn sách quen thuộc. Lần này, trong Truyện cổ tích thông minh, hãy để bé chọn cái kết của câu chuyện. Hỏi bé: "Con nghĩ ai đã giúp nhân vật chính?" để trí tưởng tượng của bé bay xa trước giờ ngủ.', body_zh = '经典故事书你们俩都看累了。这一次在智慧童话里让宝宝来选故事的结局。问问“你觉得是谁帮了那个英雄？”，在睡前让宝宝的想象力自由飞翔。' WHERE id = '2b47e995-a54a-442e-b303-43e9894db748' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una lógica helada 🥶', body_es = 'Abre la nevera, pide la cubitera y no la suelta aunque se le congelen las manos. Está comprobando con su cuerpo el concepto de frío y calor. Pon agua templada en un cuenco y agua con hielo en otro y convierte este descubrimiento en un pequeño experimento científico.', title_fr = 'Une logique glaciale 🥶', body_fr = 'Il ouvre le frigo, réclame le bac à glaçons et refuse de le lâcher alors que ses mains ont froid. Il teste avec son corps la notion de chaud et de froid. Mettez de l''eau tiède dans un bol et de l''eau glacée dans un autre pour transformer cette découverte en petite expérience scientifique.', title_hi = 'बर्फ़ जैसा तर्क 🥶', body_hi = 'फ़्रिज खोलकर आइस ट्रे माँगता है और हाथ ठंडे होने के बावजूद उसे नहीं छोड़ता। वह गर्म और ठंडे की समझ अपने शरीर से परख रहा है। एक बर्तन में गुनगुना, दूसरे में बर्फ़ वाला पानी रखकर इस खोज को छोटे वैज्ञानिक प्रयोग में बदल दीजिए।', title_id = 'Logika sedingin es 🥶', body_id = 'Ia membuka kulkas, meminta cetakan es, dan tidak mau melepasnya meski tangannya kedinginan. Ia sedang menguji konsep panas dan dingin dengan tubuhnya. Isi satu wadah dengan air hangat dan satu lagi dengan air es, lalu ubah penemuan ini menjadi eksperimen ilmiah kecil.', title_ja = '氷のような理屈 🥶', body_ja = '冷蔵庫を開けて製氷皿をほしがり、手が冷たくなっても離さない。体で温かい・冷たいを確かめているんです。ひとつの器にぬるま湯、もうひとつに氷水を入れて、この発見を小さな科学実験に変えましょう。', title_ko = '얼음 같은 논리 🥶', body_ko = '냉장고를 열어 얼음 틀을 달라고 하고, 손이 시려도 놓지 않나요? 몸으로 따뜻함과 차가움을 시험하는 중이에요. 한 그릇엔 미지근한 물, 한 그릇엔 얼음물을 담아 이 발견을 작은 과학 실험으로 바꿔 주세요.', title_nl = 'IJskoude logica 🥶', body_nl = 'Hij doet de koelkast open, eist het ijsblokjesbakje op en laat het niet los, hoe koud zijn handen ook worden. Hij test warm en koud met zijn lichaam. Doe lauw water in het ene bakje en ijswater in het andere en maak van deze ontdekking een klein wetenschappelijk experiment.', title_pl = 'Lodowata logika 🥶', body_pl = 'Otwiera lodówkę, domaga się foremki z lodem i choć marzną mu ręce, nie chce jej puścić. Ciałem sprawdza, czym jest ciepło i zimno. Nalej do jednej miski letniej, a do drugiej lodowatej wody i zamień to odkrycie w mały eksperyment naukowy.', title_pt = 'Lógica gelada 🥶', body_pt = 'Abre o frigorífico, exige a forma de gelo e, apesar de ter as mãos geladas, não a larga. Está a testar com o corpo a noção de quente e frio. Ponha água morna numa taça e água gelada noutra e transforme esta descoberta numa pequena experiência científica.', title_sv = 'Iskall logik 🥶', body_sv = 'Barnet öppnar kylskåpet, kräver isbitsformen och släpper den inte trots att händerna fryser. Barnet testar begreppen varmt och kallt med kroppen. Häll ljummet vatten i en skål och isvatten i en annan och gör upptäckten till ett litet vetenskapligt experiment.', title_vi = 'Logic lạnh như băng 🥶', body_vi = 'Bé mở tủ lạnh, đòi lấy khay đá và nhất quyết không buông dù tay đã lạnh cóng. Bé đang dùng cơ thể để thử cảm nhận nóng và lạnh. Hãy cho nước ấm vào một bát, nước đá vào một bát để biến khám phá này thành một thí nghiệm khoa học nhỏ.', title_zh = '冰一样的逻辑 🥶', body_zh = '打开冰箱非要拿冰格，手冻得冰凉也不肯放。宝宝在用身体测试冷和热的概念。一个碗里倒温水，一个碗里放冰水，把这次探索变成一个小小的科学实验吧。' WHERE id = 'e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá corre en el parque 👨‍👧', body_es = 'La maternidad no es un turno 24/7. ¡Activa la función pareja! Deja que hoy papá le haga gastar en el parque esa energía sin fin y tú disfruta en casa del silencio absoluto.', title_fr = 'La course au parc avec papa 👨‍👧', body_fr = 'La maternité n''est pas une garde 24 h/24 et 7 j/7. Activez le mode Partenaire ! Laissez papa dépenser aujourd''hui au parc cette énergie sans fin, et savourez à la maison un silence absolu.', title_hi = 'पापा की पार्क दौड़ 👨‍👧', body_hi = 'माँ बनना 24/7 चलने वाली शिफ़्ट नहीं है। साथी वाला फ़ीचर चालू कीजिए! आज वह अंतहीन ऊर्जा पापा को पार्क में निकलवाने दीजिए, और आप घर पर पूरी खामोशी का मज़ा लीजिए।', title_id = 'Ayah lari-lari di taman 👨‍👧', body_id = 'Menjadi ibu bukan giliran jaga 24/7. Aktifkan fungsi pasangan! Biarkan hari ini Ayah yang menyalurkan energinya yang tak habis-habis di taman, sementara Anda menikmati keheningan total di rumah.', title_ja = 'パパと公園でかけっこ 👨‍👧', body_ja = 'ママ業は24時間365日続くシフトではありません。「パートナーモード」をオンにしましょう！今日はあの尽きないエネルギーを、パパに公園で発散させてもらって、あなたは家で完全な静けさを味わって。', title_ko = '아빠의 공원 달리기 👨‍👧', body_ko = '엄마 노릇은 24시간 쉬지 않는 근무가 아니에요. 파트너 모드를 켜세요! 오늘은 그 끝없는 에너지를 아빠가 공원에서 풀게 하고, 엄마는 집에서 완전한 고요를 즐기세요.', title_nl = 'Papa''s parkrondje 👨‍👧', body_nl = 'Moederschap is geen dienst die 24/7 doorgaat. Zet de partnerfunctie aan! Laat papa die eindeloze energie vandaag in het park laten opbranden, en geniet jij thuis van de absolute stilte.', title_pl = 'Bieganie z tatą w parku 👨‍👧', body_pl = 'Macierzyństwo to nie zmiana 24/7. Włącz tryb Partnera! Niech dziś tata pomoże mu wyładować tę niewyczerpaną energię w parku, a ty delektuj się w domu absolutną ciszą.', title_pt = 'A corrida do pai no parque 👨‍👧', body_pt = 'A maternidade não é um turno 24/7. Ative a função de companheiro! Deixe que hoje seja o pai a gastar no parque aquela energia sem fim e saboreie em casa um silêncio absoluto.', title_sv = 'Pappas springtur i parken 👨‍👧', body_sv = 'Moderskap är inget skift som pågår dygnet runt. Aktivera partnerfunktionen! Låt pappa få ur barnet den ändlösa energin i parken i dag, medan du njuter av total tystnad hemma.', title_vi = 'Bố dẫn bé ra công viên 👨‍👧', body_vi = 'Làm mẹ không phải là ca trực 24/7. Hãy bật Chế độ đối tác! Hôm nay để bố cho bé xả hết nguồn năng lượng bất tận ở công viên, còn mẹ ở nhà tận hưởng sự yên tĩnh tuyệt đối.', title_zh = '爸爸带去公园跑 👨‍👧', body_zh = '当妈妈不是一份24/7不停歇的班。启动“伴侣功能”吧！今天就让爸爸带宝宝去公园释放那用不完的精力，你在家里好好享受绝对的安静。' WHERE id = 'fd41f13f-2abd-4cce-ba8e-06a55c0b506f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto en la cocina 🥄', body_es = 'Saca las ollas y las cucharas de madera y da un concierto en medio de la cocina. Aunque te duela la cabeza, así se desarrollan su sentido del ritmo y su creatividad. No intervengas con prisas: deja unos minutos que esa energía loca se extienda por la habitación en ondas sonoras.', title_fr = 'Concert en cuisine 🥄', body_fr = 'Il sort les casseroles et les cuillères en bois et donne un concert au milieu de la cuisine. Même si vous avez mal à la tête, c''est le développement de son sens du rythme et de sa créativité. N''intervenez pas trop vite, laissez cette énergie folle se répandre quelques minutes en ondes sonores dans la pièce.', title_hi = 'रसोई में कॉन्सर्ट 🥄', body_hi = 'पतीले और लकड़ी के चम्मच निकालकर रसोई के बीच कॉन्सर्ट दे रहा है। सिर भले दुखे, यह उसकी लय की समझ और रचनात्मकता का विकास है। जल्दबाज़ी में बीच में मत आइए, कुछ मिनट उस धमाकेदार ऊर्जा को आवाज़ की लहरों के साथ कमरे में फैलने दीजिए।', title_id = 'Konser di dapur 🥄', body_id = 'Ia mengeluarkan panci dan sendok kayu lalu menggelar konser di tengah dapur. Meski kepala Anda pusing, ini adalah perkembangan rasa irama dan kreativitasnya. Jangan buru-buru campur tangan, biarkan energi gilanya menyebar ke seluruh ruangan lewat gelombang suara selama beberapa menit.', title_ja = 'キッチンでコンサート 🥄', body_ja = '鍋や木のスプーンを取り出して、キッチンのまんなかでコンサート中。頭が痛くても、これはリズム感と創造力の発達です。あわてて止めないで、数分間はそのすごいエネルギーを音の波にのせて部屋に広げさせてあげましょう。', title_ko = '부엌 콘서트 🥄', body_ko = '냄비와 나무 숟가락을 꺼내 부엌 한가운데서 콘서트를 여나요? 머리가 아파도 리듬감과 창의력이 자라는 중이에요. 서둘러 끼어들지 말고 몇 분만 그 넘치는 에너지가 소리로 방을 채우게 해 주세요.', title_nl = 'Concert in de keuken 🥄', body_nl = 'Hij haalt pannen en houten lepels tevoorschijn en geeft midden in de keuken een concert. Ook al krijg je er hoofdpijn van, zo ontwikkelt hij zijn ritmegevoel en creativiteit. Grijp niet te snel in en laat die gekke energie een paar minuten met geluidsgolven door de kamer gaan.', title_pl = 'Koncert w kuchni 🥄', body_pl = 'Wyciągnął garnki i drewniane łyżki i daje koncert na środku kuchni. Nawet jeśli boli cię głowa, to rozwój jego poczucia rytmu i kreatywności. Nie wtrącaj się w pośpiechu, pozwól przez kilka minut tej szalonej energii rozchodzić się po pokoju falami dźwięku.', title_pt = 'Concerto na cozinha 🥄', body_pt = 'Tira as panelas e as colheres de pau e dá um concerto no meio da cozinha. Mesmo com dor de cabeça, isto é o desenvolvimento do sentido de ritmo e da criatividade dele. Não intervenha à pressa: deixe por uns minutos aquela energia louca espalhar-se pelo quarto em ondas sonoras.', title_sv = 'Konsert i köket 🥄', body_sv = 'Barnet plockar fram kastruller och träslevar och ger konsert mitt i köket. Även om du får huvudvärk är det utvecklingen av rytmkänsla och kreativitet. Lägg dig inte i för snabbt, låt den galna energin spridas i rummet med ljudvågorna i några minuter.', title_vi = 'Buổi hòa nhạc trong bếp 🥄', body_vi = 'Bé lôi nồi niêu và thìa gỗ ra, mở một buổi hòa nhạc giữa bếp. Dù mẹ đau đầu, đây là sự phát triển cảm thụ nhịp điệu và khả năng sáng tạo của bé. Đừng vội can thiệp, hãy để nguồn năng lượng "điên rồ" ấy lan tỏa khắp phòng qua những làn sóng âm thanh trong vài phút.', title_zh = '厨房音乐会 🥄', body_zh = '把锅和木勺都拿出来，在厨房中间开起了音乐会。虽然你头都疼了，但这是宝宝节奏感和创造力在发展。别急着插手，让那股疯狂的能量随着声波在房间里飘荡几分钟吧。' WHERE id = '587f6b4e-5494-4f6a-8efa-28e0cb53f529' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Fuera el tiempo no está claro, hace sol pero también sopla viento? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado, y sal de paseo sin perder tiempo dudando en la puerta.', body_fr = 'Le temps dehors n''est pas très clair, du soleil mais aussi du vent ? Laissez Météo et tenue vous indiquer aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue, et partez en promenade sans perdre de temps à hésiter sur le pas de la porte.', body_hi = 'बाहर मौसम पूरा साफ़ नहीं, धूप है पर हवा भी चल रही है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताए, ताकि दरवाज़े पर दुविधा में समय गँवाए बिना सैर पर निकल सकें।', body_id = 'Cuaca di luar tidak menentu, ada matahari tapi angin juga bertiup? Biarkan Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan setelan yang tepat, lalu pergilah jalan-jalan tanpa membuang waktu ragu-ragu di depan pintu.', body_ja = '外は晴れているのか、日は出ているけれど風も吹いている？「天気と服装」に、窓からは見えない風の強さとぴったりのコーデをすぐに教えてもらいましょう。玄関で迷って時間をむだにせず、お散歩に出かけましょう。', body_ko = '밖의 날씨가 애매하게 해는 났는데 바람도 부나요? 창밖으로는 보이지 않는 풍속과 알맞은 옷차림을 날씨와 옷차림 도구가 바로 알려 줄 거예요. 현관에서 망설이며 시간 보내지 말고 산책을 나가세요.', body_nl = 'Is het weer buiten niet helemaal duidelijk, met zon maar ook wind? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je vanuit het raam niet ziet, en de juiste outfit, en ga wandelen zonder twijfelend tijd te verliezen bij de deur.', body_pl = 'Pogoda na dworze niepewna, świeci słońce, ale wieje wiatr? Niech narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru, której nie widać przez okno, i właściwy zestaw ubrań. Wyjdźcie na spacer, nie tracąc czasu na wahanie w progu.', body_pt = 'O tempo lá fora não está bem definido: há sol, mas também vento? Deixe que a ferramenta Tempo e Roupa lhe diga logo a velocidade do vento, que não se vê da janela, e a roupa certa, e saia para passear sem perder tempo indecisa à porta.', body_sv = 'Är vädret ute inte riktigt klart, solen skiner men det blåser också? Låt verktyget Väder och kläder direkt visa vindhastigheten som inte syns genom fönstret och rätt klädsel, så kommer ni ut på promenad utan att stå villrådiga och förlora tid i dörren.', body_vi = 'Thời tiết ngoài trời không rõ ràng, có nắng nhưng cũng có gió? Hãy để Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp, để ra ngoài đi dạo mà không mất thời gian lưỡng lự ở cửa.', body_zh = '外面天气说不准，有太阳但也刮着风？让天气与穿衣工具马上告诉你从窗户看不出的风速和正确的搭配，别再犹豫着在门口浪费时间，出门散步吧。' WHERE id = 'a36ee256-d6c9-4345-a732-3a052e7dd260' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Masaje en equipo 💆‍♂️', body_es = 'Cuando el peque se duerma, daos un masaje de hombros tú y tu pareja para soltar el estrés del día. No sois solo padres que comparten casa: sois un equipo de apoyo inquebrantable.', title_fr = 'Massage d''équipe 💆‍♂️', body_fr = 'Une fois l''enfant couché, massez-vous les épaules l''un l''autre avec votre partenaire pour évacuer le stress de la journée. Vous n''êtes pas seulement des parents qui partagent une maison, vous êtes une équipe de soutien inébranlable.', title_hi = 'टीम मसाज 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ एक-दूसरे के कंधों की मालिश कीजिए। आप सिर्फ़ एक घर बाँटने वाले माता-पिता नहीं, एक अटूट सहारा देने वाली टीम हैं।', title_id = 'Pijat berdua 💆‍♂️', body_id = 'Setelah anak tidur, saling pijat bahu bersama pasangan untuk melepas stres seharian. Kalian bukan sekadar orang tua yang berbagi rumah, kalian adalah tim pendukung yang tak tergoyahkan.', title_ja = 'チームでマッサージ 💆‍♂️', body_ja = '子どもが寝たら、パートナーと肩をもみ合って一日のストレスを手放しましょう。ふたりはただ同じ家に暮らす親ではなく、揺るがない支え合いのチームです。', title_ko = '팀 마사지 💆‍♂️', body_ko = '아이가 잠들면 하루의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 두 사람은 한집에 사는 부모일 뿐 아니라 흔들림 없는 응원 팀이에요.', title_nl = 'Massage als team 💆‍♂️', body_nl = 'Geef elkaar met je partner een schoudermassage als je kind slaapt, om de stress van de dag kwijt te raken. Jullie zijn niet zomaar ouders die een huis delen, jullie zijn een onverwoestbaar steunteam.', title_pl = 'Masaż we dwoje 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres dnia. Nie jesteście tylko rodzicami dzielącymi jeden dom, jesteście niezłomną drużyną wsparcia.', title_pt = 'Massagem em equipa 💆‍♂️', body_pt = 'Depois de a criança adormecer, façam massagens nos ombros um ao outro para libertar o stress do dia. Não são apenas pais a partilhar a mesma casa: são uma equipa de apoio inabalável.', title_sv = 'Lagmassage 💆‍♂️', body_sv = 'När barnet har somnat kan du och din partner ge varandra en axelmassage för att släppa dagens stress. Ni är inte bara föräldrar som delar samma hem, ni är ett orubbligt stödlag.', title_vi = 'Mát-xa cho nhau 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng chồng mát-xa vai cho nhau để xua tan căng thẳng cả ngày. Hai người không chỉ là bố mẹ sống chung một nhà, mà là một đội hỗ trợ nhau không gì lay chuyển được.', title_zh = '双人按摩 💆‍♂️', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天的压力。你们不只是住在同一个家里的父母，更是一支坚不可摧的支持团队。' WHERE id = 'c95b298d-8316-46aa-ace1-1fc1956a0fda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño empresario 🍅', body_es = 'En un rincón de la habitación ha juntado sus juguetes y te vende tomates imaginarios con dinero imaginario. Ponte muy seria en este juego de comercio. Compra ese tomate imaginario y haz como que te lo comes con ganas. Los juegos de rol son la base más sólida de su inteligencia social y su lógica matemática.', title_fr = 'Le petit commerçant 🍅', body_fr = 'Dans un coin de la pièce, il a rassemblé ses jouets et vous vend des tomates imaginaires avec de l''argent imaginaire. Soyez très sérieuse dans ce jeu de commerce. Achetez cette tomate imaginaire et faites semblant de la manger avec appétit. Les jeux de rôle sont la base la plus solide de son intelligence sociale et de sa logique mathématique.', title_hi = 'नन्हा बिज़नेसमैन 🍅', body_hi = 'कमरे के एक कोने में खिलौने जमा करके आपको काल्पनिक पैसों में काल्पनिक टमाटर बेच रहा है। इस व्यापार के खेल में बहुत गंभीर रहिए। वह काल्पनिक टमाटर खरीदकर ऐसे दिखाइए जैसे चाव से खा रही हों। रोल-प्ले खेल उसकी सामाजिक समझ और गणितीय तर्क की सबसे मज़बूत नींव हैं।', title_id = 'Pebisnis kecil 🍅', body_id = 'Di sudut kamar ia mengumpulkan mainan dan menjual tomat khayalan kepada Anda dengan uang khayalan. Bersikaplah sangat serius dalam permainan dagang ini. Belilah tomat khayalan itu dan berpura-puralah memakannya dengan lahap. Bermain peran adalah fondasi terkuat kecerdasan sosial dan logika matematisnya.', title_ja = '小さなビジネスマン 🍅', body_ja = '部屋のすみにおもちゃを集めて、空想のお金で空想のトマトを売ってくれる。このお店ごっこでは、とても真剣にふるまいましょう。そのトマトを買って、おいしそうに食べるふりをして。ごっこ遊びは、社会性と算数の考え方のいちばん強い土台です。', title_ko = '꼬마 사업가 🍅', body_ko = '방 한쪽에 장난감을 모아 놓고 상상의 돈으로 상상의 토마토를 파나요? 이 장사 놀이에서는 아주 진지해야 해요. 그 토마토를 사서 맛있게 먹는 척해 주세요. 역할 놀이는 사회적 지능과 수학적 논리의 가장 튼튼한 바탕이에요.', title_nl = 'Kleine zakenman 🍅', body_nl = 'Hij heeft in een hoek van de kamer zijn speelgoed verzameld en verkoopt je denkbeeldige tomaten voor denkbeeldig geld. Wees heel serieus in dit handelsspel. Koop die denkbeeldige tomaat en doe alsof je hem met smaak opeet. Rollenspel is de sterkste basis voor zijn sociale intelligentie en wiskundige logica.', title_pl = 'Mały biznesmen 🍅', body_pl = 'W kącie pokoju zebrał zabawki i sprzedaje ci wymyślone pomidory za wymyślone pieniądze. Bądź w tej grze w handel bardzo poważna. Kup ten wymyślony pomidor i udawaj, że zajadasz go z apetytem. Zabawy w odgrywanie ról to najmocniejszy fundament jego inteligencji społecznej i logiki matematycznej.', title_pt = 'Pequeno empresário 🍅', body_pt = 'Num canto do quarto, junta os brinquedos e vende-lhe tomates imaginários com dinheiro imaginário. Leve este jogo de comércio muito a sério. Compre aquele tomate imaginário e finja que o come com apetite. As brincadeiras de faz de conta são a base mais forte da inteligência social e da lógica matemática dele.', title_sv = 'Den lilla affärskvinnan 🍅', body_sv = 'I ett hörn av rummet samlar barnet leksaker och säljer låtsastomater till dig för låtsaspengar. Var väldigt seriös i handelsleken. Köp låtsastomaten och låtsas äta den med god aptit. Rollekar är den starkaste grunden för barnets sociala intelligens och matematiska logik.', title_vi = 'Doanh nhân nhí 🍅', body_vi = 'Bé gom đồ chơi vào một góc phòng và bán cho mẹ cà chua tưởng tượng bằng tiền tưởng tượng. Hãy thật nghiêm túc trong trò chơi buôn bán này. Mua quả cà chua tưởng tượng và giả vờ ăn thật ngon lành. Trò chơi nhập vai là nền tảng vững chắc nhất cho trí tuệ xã hội và tư duy toán học của bé.', title_zh = '小小生意人 🍅', body_zh = '在房间一角把玩具堆起来，用想象中的钱卖给你想象中的番茄。在这场买卖游戏里要非常认真。买下那个想象中的番茄，装作吃得津津有味。角色扮演游戏是宝宝社交智力和数学逻辑最坚实的基础。' WHERE id = '7a91d538-17ac-47d6-a73e-975aed76abb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para unos huesos que crecen deprisa, el calcio es imprescindible. ¿No bebe leche? Calcula sin falta hoy con el Seguimiento de tomas cuánto queso, yogur o brócoli ha tomado.', body_fr = 'Le calcium est indispensable à des os qui grandissent vite. Il ne boit pas de lait ? Calculez absolument aujourd''hui ses apports en fromage, yaourt ou brocoli avec le Suivi des repas.', body_hi = 'तेज़ी से बढ़ती हड्डियों के लिए कैल्शियम ज़रूरी है। दूध नहीं पीता? फ़ीडिंग ट्रैकर से आज का पनीर, दही या ब्रोकली ज़रूर गिनिए।', body_id = 'Kalsium wajib untuk tulang yang tumbuh cepat. Ia tidak mau minum susu? Pastikan hari ini menghitung asupan keju, yogurt, atau brokoli dengan Pemantau Nutrisi.', body_ja = 'ぐんぐん伸びる骨にはカルシウムが欠かせません。牛乳を飲まない？「栄養管理ツール」で、今日のチーズ、ヨーグルト、ブロッコリーの量をしっかり計算しましょう。', body_ko = '빠르게 자라는 뼈에는 칼슘이 꼭 필요해요. 우유를 안 마시나요? 수유 기록 도구로 오늘 치즈, 요거트, 브로콜리 섭취량을 꼭 계산해 보세요.', body_nl = 'Calcium is onmisbaar voor snelgroeiende botten. Drinkt hij geen melk? Bereken vandaag met de Voedingstracker zeker hoeveel kaas, yoghurt of broccoli hij binnenkrijgt.', body_pl = 'Dla szybko rosnących kości wapń jest niezbędny. Nie pije mleka? Koniecznie policz dziś w narzędziu do śledzenia karmienia, ile zjadł sera, jogurtu albo brokułów.', body_pt = 'Para ossos que crescem depressa, o cálcio é essencial. Não bebe leite? Não deixe de calcular hoje, com o Registo de Alimentação, o consumo de queijo, iogurte ou brócolos.', body_sv = 'Kalcium är ett måste för skelett som växer snabbt. Dricker barnet inte mjölk? Räkna absolut ut dagens intag av ost, yoghurt eller broccoli med verktyget Matningskoll.', body_vi = 'Canxi là điều kiện cần cho xương đang phát triển nhanh. Bé không uống sữa? Hôm nay hãy nhớ tính lượng phô mai, sữa chua hoặc bông cải xanh bé ăn bằng Theo dõi cữ bú.', body_zh = '快速生长的骨骼离不开钙。不肯喝奶？今天一定要用喂养记录工具算一算奶酪、酸奶或西兰花的摄入量。' WHERE id = '87c32869-7e9b-4faa-bbbe-1c640a3da5bb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Huida de la cama 🏃‍♂️', body_es = '«Dame agua», «busca mi juguete»... Las excusas de los 3 años para no dormirse no se acaban nunca. Pon el temporizador de sueño y protege los límites con firmeza.', title_fr = 'L''évasion du lit 🏃‍♂️', body_fr = '« Donne de l''eau », « Trouve mon jouet »... Les excuses des 3 ans pour ne pas dormir sont sans fin. Lancez le Minuteur de sommeil et tenez fermement vos limites.', title_hi = 'बिस्तर से भागना 🏃‍♂️', body_hi = '‘पानी दो’, ‘मेरा खिलौना ढूँढो’... न सोने के लिए 3 साल के बहाने खत्म ही नहीं होते। स्लीप टाइमर चालू कीजिए, सीमाओं की पक्के इरादे से रक्षा कीजिए।', title_id = 'Kabur dari tempat tidur 🏃‍♂️', body_id = '''Minta air'', ''Carikan mainanku''... Alasan anak 3 tahun untuk tidak tidur tidak ada habisnya. Nyalakan Timer Tidur dan jaga batasan dengan tegas.', title_ja = 'ベッドからの脱走 🏃‍♂️', body_ja = '「お水ちょうだい」「おもちゃさがして」…寝ないための3歳の言いわけは尽きません。「睡眠タイマー」をスタートして、きっぱりと境界線を守りましょう。', title_ko = '침대 탈출 🏃‍♂️', body_ko = '''물 줘'', ''내 장난감 찾아 줘''... 잠들지 않으려는 세 살의 핑계는 끝이 없어요. 수면 타이머를 켜고 경계를 단호하게 지켜 주세요.', title_nl = 'Ontsnappen uit bed 🏃‍♂️', body_nl = '''Geef water'', ''Zoek mijn knuffel''... De smoesjes van een 3-jarige om niet te gaan slapen houden nooit op. Zet de Slaaptimer aan en bewaak je grenzen vastberaden.', title_pl = 'Ucieczka z łóżka 🏃‍♂️', body_pl = '„Daj wody”, „Znajdź moją zabawkę”... Wymówki 3-latka, żeby nie zasnąć, nie mają końca. Włącz timer snu i stanowczo pilnuj granic.', title_pt = 'Fuga da cama 🏃‍♂️', body_pt = '"Dá-me água", "Encontra o meu brinquedo"... As desculpas dos 3 anos para não adormecer nunca acabam. Ligue o temporizador de sono e defenda os limites com firmeza.', title_sv = 'Flykt från sängen 🏃‍♂️', body_sv = '”Ge mig vatten”, ”Hitta min leksak”... 3-åringens ursäkter för att slippa somna tar aldrig slut. Starta sömntimern och håll bestämt fast vid gränserna.', title_vi = 'Trốn khỏi giường 🏃‍♂️', body_vi = '"Cho con nước", "Tìm đồ chơi cho con"... Lý do để không ngủ của tuổi lên 3 chẳng bao giờ hết. Hãy bật Bộ hẹn giờ ngủ và kiên quyết giữ vững giới hạn.', title_zh = '从床上逃跑 🏃‍♂️', body_zh = '“给我水”“帮我找玩具”……为了不睡觉，3岁的借口永远说不完。打开睡眠计时器，坚定地守住边界。' WHERE id = 'dca4203c-2783-4935-8d52-5e2abbd31c77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una carga enorme 🎒', body_es = 'Quiere llevar él solo tus bolsas pesadas o el paraguas grande; los arrastra, pero rechaza rotundamente la ayuda. Deja que ponga a prueba su fuerza: quiere sentirse el héroe más fuerte de la casa. No frenes su independencia.', title_fr = 'Un fardeau énorme 🎒', body_fr = 'Il veut absolument porter lui-même vos sacs lourds ou le grand parapluie, il les traîne mais refuse catégoriquement votre aide. Laissez-le tester sa force, il veut se sentir le héros le plus fort de la maison, ne freinez pas son indépendance.', title_hi = 'भारी बोझ 🎒', body_hi = 'आपके भारी थैले या बड़ा छाता खुद ही उठाना चाहता है, घसीटकर ले जाता है पर मदद साफ़ ठुकरा देता है। उसे अपनी ताकत आज़माने दीजिए, वह खुद को घर का सबसे ताकतवर हीरो महसूस करना चाहता है, उसकी आत्मनिर्भरता में रुकावट मत डालिए।', title_id = 'Beban raksasa 🎒', body_id = 'Ia bersikeras membawa sendiri tas berat atau payung besar Anda, menyeretnya, tapi tegas menolak dibantu. Biarkan ia menguji kekuatannya, ia ingin merasa menjadi pahlawan terkuat di rumah. Jangan menghalangi kemandiriannya.', title_ja = '大きな荷物 🎒', body_ja = 'あなたの重いバッグや大きな傘を、どうしても自分で運びたがる。引きずりながらでも、手伝おうとするときっぱり断ります。力を試させてあげましょう。家でいちばん強いヒーローだと感じたいんです。自立をじゃましないで。', title_ko = '거대한 짐 🎒', body_ko = '엄마의 무거운 가방이나 큰 우산을 꼭 자기가 들겠다며 질질 끌면서도 도움은 단호하게 거절하나요? 힘을 시험하게 해 주세요. 집에서 가장 힘센 영웅이 된 기분을 느끼고 싶은 거예요. 독립심을 막지 마세요.', title_nl = 'Een enorme last 🎒', body_nl = 'Hij wil per se zelf je zware tassen of de grote paraplu dragen, sleept ze over de grond mee, maar weigert resoluut elke hulp. Laat hem zijn kracht testen, hij wil zich de sterkste held van het huis voelen. Houd zijn zelfstandigheid niet tegen.', title_pl = 'Ogromny ciężar 🎒', body_pl = 'Koniecznie chce sam nieść twoje ciężkie torby albo duży parasol, ciągnie je po ziemi, ale stanowczo odrzuca pomoc. Niech sprawdzi swoją siłę, chce się poczuć najsilniejszym bohaterem w domu, nie przeszkadzaj jego samodzielności.', title_pt = 'Uma carga gigante 🎒', body_pt = 'Quer mesmo carregar sozinho os seus sacos pesados ou o guarda-chuva grande, arrasta-os pelo chão, mas recusa terminantemente ajuda. Deixe-o testar a força: quer sentir-se o herói mais forte da casa. Não trave a independência dele.', title_sv = 'En jättebörda 🎒', body_sv = 'Barnet vill absolut bära dina tunga väskor eller det stora paraplyet själv, släpar dem efter sig men vägrar bestämt att ta emot hjälp. Låt barnet testa sin styrka, det vill känna sig som hemmets starkaste hjälte. Stoppa inte självständigheten.', title_vi = 'Gánh nặng khổng lồ 🎒', body_vi = 'Bé nhất định đòi tự mang chiếc túi nặng hay chiếc ô to của mẹ, kéo lê dưới đất nhưng kiên quyết từ chối sự giúp đỡ. Hãy để bé thử sức mình, bé muốn cảm thấy mình là người hùng mạnh nhất nhà, đừng cản trở sự tự lập của bé.', title_zh = '超重的行李 🎒', body_zh = '非要自己拿你沉重的包或者大雨伞，拖着往前走，却坚决不要帮忙。让宝宝试试自己的力量吧，宝宝想觉得自己是家里最强壮的英雄，别妨碍宝宝的独立。' WHERE id = '0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nueva identidad 🕷️', body_es = 'Se despierta y te dice muy serio: «Yo no soy un niño, soy una araña». Cerca de los 40 meses la imaginación supera todos los límites. No discutas: dale el papel de araña que se toma el desayuno y únete a este teatro absurdo.', title_fr = 'Nouvelle identité 🕷️', body_fr = 'Il se réveille et vous dit très sérieusement : « Je suis pas un enfant, je suis une araignée. » À l''approche du 40e mois, l''imagination dépasse toutes les limites. Ne discutez pas, donnez-lui le rôle d''une araignée qui prend son petit-déjeuner et rejoignez ce théâtre absurde.', title_hi = 'नई पहचान 🕷️', body_hi = 'सुबह उठकर बड़ी गंभीरता से कहता है, ‘मैं बच्चा नहीं हूँ, मैं मकड़ी हूँ।’ 40वें महीने के करीब कल्पना सीमाएँ पार कर जाती है। बहस मत कीजिए, उसे नाश्ता करने वाली मकड़ी की भूमिका दीजिए और इस बेतुके नाटक में शामिल हो जाइए।', title_id = 'Identitas baru 🕷️', body_id = 'Ia bangun pagi dan dengan sangat serius berkata ''Aku bukan anak-anak, aku laba-laba''. Menjelang bulan ke-40, imajinasinya melampaui batas. Jangan berdebat, beri ia peran laba-laba yang sedang sarapan dan ikutlah dalam teater absurd ini.', title_ja = '新しい自分 🕷️', body_ja = '朝起きるなり、とても真剣に「わたしは子どもじゃない、クモなの」と言う。40か月が近づき、想像力は境界を超えています。言い合わずに、朝ごはんを食べるクモの役をあげて、このおかしな劇に参加しましょう。', title_ko = '새로운 정체성 🕷️', body_ko = '아침에 일어나 아주 진지하게 ''나 아이 아니야, 거미야''라고 하나요? 40개월 무렵에는 상상력이 경계를 넘어서요. 따지지 말고 아침밥을 먹는 거미 역할을 주며 이 엉뚱한 연극에 함께하세요.', title_nl = 'Een nieuwe identiteit 🕷️', body_nl = 'Hij wordt wakker en zegt heel serieus: ''Ik ben geen kind, ik ben een spin.'' Rond de 40e maand gaat de fantasie alle grenzen voorbij. Ga niet in discussie, geef hem de rol van een spin die ontbijt en doe mee met dit absurde theater.', title_pl = 'Nowa tożsamość 🕷️', body_pl = 'Rano budzi się i bardzo poważnie mówi: „Nie jestem dzieckiem, jestem pająkiem”. W okolicach 40. miesiąca wyobraźnia przekracza wszelkie granice. Nie kłóć się, daj mu rolę pająka, który je śniadanie, i dołącz do tego absurdalnego teatru.', title_pt = 'Uma nova identidade 🕷️', body_pt = 'Acorda de manhã e diz-lhe muito a sério: "Não sou uma criança, sou uma aranha". Perto dos 40 meses, a imaginação ultrapassa todos os limites. Não discuta: dê-lhe o papel de aranha que toma o pequeno-almoço e entre neste teatro absurdo.', title_sv = 'En ny identitet 🕷️', body_sv = 'Barnet vaknar och säger på största allvar: ”Jag är inget barn, jag är en spindel.” Närmare 40 månader går fantasin över alla gränser. Bråka inte, ge barnet rollen som spindeln som äter frukost och var med i den absurda teatern.', title_vi = 'Nhân cách mới 🕷️', body_vi = 'Sáng thức dậy, bé nói với mẹ rất nghiêm túc: "Con không phải em bé, con là con nhện". Gần 40 tháng, trí tưởng tượng vượt mọi giới hạn. Đừng tranh cãi, hãy giao cho bé vai "con nhện ăn sáng" và tham gia vở kịch ngộ nghĩnh này.', title_zh = '新身份 🕷️', body_zh = '早上醒来，非常认真地对你说：“我不是小孩，我是蜘蛛。”快40个月时，想象力会跨越边界。别争了，让宝宝扮演“吃早餐的蜘蛛”，加入这出荒诞剧吧。' WHERE id = '13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Excusas sin fin 🦶', body_es = 'Justo cuando se va a dormir, quiere levantarse de la cama con la excusa de «me pica el dedo del pie». Se ha vuelto un experto en el arte de retrasar el sueño. Ponte seria, ráscale el pie de mentira y apaga las luces con firmeza: los límites los marcas tú.', title_fr = 'Des excuses sans fin 🦶', body_fr = 'Au moment de s''endormir, il veut se lever sous prétexte que « mon orteil me gratte ». Il est passé maître dans l''art de retarder le sommeil. Soyez ferme, faites semblant de lui gratter le pied et éteignez la lumière avec détermination : c''est vous qui posez les limites.', title_hi = 'कभी न खत्म होने वाले बहाने 🦶', body_hi = 'बस सोने ही वाला है कि ‘मेरे पैर की उँगली में खुजली हो रही है’ के बहाने बिस्तर से उठना चाहता है। नींद टालने की कला में माहिर हो गया है। गंभीर रहिए, झूठमूठ उसका पैर खुजाइए और पक्के इरादे से लाइटें बंद कीजिए, सीमा आप खींचिए।', title_id = 'Alasan yang tak ada habisnya 🦶', body_id = 'Tepat saat akan terlelap, ia ingin bangun dari tempat tidur dengan alasan ''Jari kakiku gatal''. Ia sudah mahir dalam seni menunda tidur. Bersikaplah serius, garuk kakinya pura-pura, lalu matikan lampu dengan tegas. Andalah yang menarik batas.', title_ja = '終わらない言いわけ 🦶', body_ja = 'もう少しで寝つくところで「足の指がかゆい」と言ってベッドから起きようとする。寝る時間を遅らせる技の達人になりました。きっぱりと、足をかくふりをして、明かりを消しましょう。線を引くのはあなたです。', title_ko = '끝없는 핑계 🦶', body_ko = '막 잠들려는데 ''발가락이 간지러워''라며 침대에서 일어나려 하나요? 잠 미루기의 달인이 됐어요. 단호하게, 발을 긁어 주는 척하고 확실하게 불을 끄세요. 경계는 엄마가 정해요.', title_nl = 'Eindeloze smoesjes 🦶', body_nl = 'Net als hij in slaap valt, wil hij uit bed met de smoes ''Mijn teen jeukt''. Hij is een meester geworden in de kunst van het slapen uitstellen. Wees serieus, krab even quasi aan zijn voet en doe vastberaden het licht uit. Jij bepaalt de grenzen.', title_pl = 'Niekończące się wymówki 🦶', body_pl = 'Gdy już zasypia, chce wstać z łóżka pod pretekstem „Swędzi mnie palec u nogi”. Opanował do perfekcji sztukę odwlekania snu. Bądź poważna, udawaj, że drapiesz mu stopę, i stanowczo zgaś światło. To ty wyznaczasz granice.', title_pt = 'Desculpas sem fim 🦶', body_pt = 'Quando está quase a adormecer, quer levantar-se com a desculpa "o dedo do pé faz-me comichão". Tornou-se mestre na arte de adiar o sono. Seja firme: coce-lhe o pé a fingir e apague as luzes com determinação. Quem traça os limites é a mãe.', title_sv = 'Ändlösa ursäkter 🦶', body_sv = 'Precis när barnet ska somna vill det gå upp ur sängen med ursäkten ”det kliar på tån”. Barnet har blivit en mästare i konsten att skjuta upp sömnen. Var bestämd, låtsasklia foten och släck bestämt lampan. Det är du som drar gränserna.', title_vi = 'Những lý do không bao giờ hết 🦶', body_vi = 'Sắp ngủ thì bé lại đòi dậy với lý do "Ngón chân con ngứa". Bé đã thành bậc thầy trong nghệ thuật trì hoãn giấc ngủ. Hãy nghiêm túc, giả vờ gãi chân cho bé rồi dứt khoát tắt đèn, chính mẹ là người vạch ra giới hạn.', title_zh = '没完没了的借口 🦶', body_zh = '快睡着时，以“脚趾头痒”为借口想从床上爬起来。拖延睡觉的艺术已经练得炉火纯青。认真一点，假装给宝宝挠挠脚，然后坚定地关灯，边界由你来划。' WHERE id = 'b2a11f30-5597-4b15-9f01-835c2894a09b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cambios bruscos de humor 🤖', body_es = '¿Te preocupan los cambios bruscos de humor de tu peque cerca de los 3 años y medio? Cierra los foros de internet que dan miedo y traumatizan. Obtén de Anacan AI una respuesta tranquilizadora y fundamentada científica y psicológicamente sobre las crisis de esta edad.', title_fr = 'Sautes d''humeur brusques 🤖', body_fr = 'Les changements d''humeur brusques de votre enfant à l''approche des 3 ans et demi vous inquiètent ? Fermez les forums effrayants et traumatisants d''Internet. Obtenez d''Anacan AI une réponse apaisante, fondée sur la science et la psychologie, sur les crises de cet âge.', title_hi = 'तेज़ी से बदलता मूड 🤖', body_hi = 'साढ़े 3 साल के करीब बच्चे के तेज़ी से बदलते मूड ने आपको परेशान कर दिया? इंटरनेट के डरावने और परेशान करने वाले फ़ोरम बंद कीजिए। Anacan AI से इस उम्र के नखरों के बारे में वैज्ञानिक और मनोवैज्ञानिक आधार वाला, सुकून देने वाला जवाब पाइए।', title_id = 'Perubahan emosi yang tajam 🤖', body_id = 'Perubahan emosinya yang tajam menjelang usia 3,5 tahun membuat Anda cemas? Tutup forum-forum internet yang menakutkan dan traumatis. Dapatkan jawaban yang menenangkan dan berdasar secara ilmiah dan psikologis tentang krisis usia ini dari Anacan AI.', title_ja = '激しい気分の変化 🤖', body_ja = '3歳半が近づき、子どもの気分の激しい変わりように不安になりましたか？ネットの怖くてショッキングな掲示板は閉じましょう。Anacan AIに、この年ごろのかんしゃくについて科学的・心理学的な根拠のある、安心できる答えをもらいましょう。', title_ko = '급격한 감정 변화 🤖', body_ko = '세 살 반 무렵 아이의 급격한 감정 변화에 불안해졌나요? 무섭고 충격적인 인터넷 게시판은 닫으세요. Anacan AI에게 이 시기의 위기에 대해 과학적, 심리학적 근거가 있는 안심되는 답을 받으세요.', title_nl = 'Heftige stemmingswisselingen 🤖', body_nl = 'Maken de heftige stemmingswisselingen van je kind rond 3,5 jaar je ongerust? Sluit die enge, traumatiserende fora op internet. Krijg van Anacan AI een wetenschappelijk en psychologisch onderbouwd, geruststellend antwoord over deze leeftijdscrisissen.', title_pl = 'Nagłe zmiany nastroju 🤖', body_pl = 'Gwałtowne zmiany nastroju dziecka w okolicach 3,5 roku cię zaniepokoiły? Zamknij straszne, traumatyzujące fora w internecie. Uzyskaj od Anacan AI naukowo i psychologicznie uzasadnioną, uspokajającą odpowiedź na temat kryzysów tego wieku.', title_pt = 'Mudanças bruscas de humor 🤖', body_pt = 'As mudanças bruscas de humor da criança perto dos 3 anos e meio deixaram-na aflita? Feche os fóruns assustadores e traumatizantes da internet. Obtenha do Anacan AI uma resposta tranquilizadora, com base científica e psicológica, sobre as crises desta idade.', title_sv = 'Kraftiga humörsvängningar 🤖', body_sv = 'Blev du orolig över barnets kraftiga humörsvängningar närmare 3,5 år? Stäng de skrämmande och traumatiska forumen på nätet. Få ett vetenskapligt och psykologiskt underbyggt, lugnande svar om den här ålderns kriser från Anacan AI.', title_vi = 'Cảm xúc thay đổi đột ngột 🤖', body_vi = 'Những thay đổi cảm xúc đột ngột của bé khi gần 3 tuổi rưỡi khiến mẹ lo lắng? Hãy đóng những diễn đàn đáng sợ, gây hoang mang trên mạng. Hãy hỏi Anacan AI để nhận câu trả lời có cơ sở khoa học và tâm lý, giúp mẹ yên tâm về những khủng hoảng của độ tuổi này.', title_zh = '剧烈的情绪变化 🤖', body_zh = '快3岁半时，孩子剧烈的情绪变化让你很慌？关掉网上那些吓人、让人焦虑的论坛。问问Anacan AI这个年龄的崩溃，得到有科学和心理学依据、让人安心的回答。' WHERE id = '272c7bb7-edd9-4323-8db9-05fe3c752757' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El milagro del agua caliente 🛀', body_es = 'A veces nada funciona y llora por todo. Mételo en una bañera de agua templada y échale un poco de espuma. El poder místico del agua para quitar la tensión llenará de calma al instante la habitación y su sistema nervioso.', title_fr = 'Le miracle de l''eau chaude 🛀', body_fr = 'Parfois, rien ne marche, il pleure pour tout. Mettez-le dans un bain d''eau tiède avec un peu de mousse. Le pouvoir presque magique de l''eau, qui absorbe la tension, apportera aussitôt la paix à toute la pièce et à son système nerveux.', title_hi = 'गरम पानी का चमत्कार 🛀', body_hi = 'कभी-कभी कुछ भी काम नहीं करता, वह बस हर बात पर रोता है। उसे गुनगुने पानी से भरे टब में बिठाइए, थोड़ा झाग डाल दीजिए। पानी की वह रहस्यमयी, तनाव सोखने वाली ताकत पूरे कमरे और उसके तंत्रिका तंत्र में तुरंत सुकून ले आएगी।', title_id = 'Keajaiban air hangat 🛀', body_id = 'Kadang tak ada yang berhasil, ia menangisi segala hal. Masukkan ia ke bak berisi air hangat dan tambahkan sedikit busa. Kekuatan air yang ajaib dan meredakan ketegangan akan langsung membawa ketenangan ke seluruh ruangan dan sistem sarafnya.', title_ja = 'お湯の奇跡 🛀', body_ja = '何をしてもうまくいかず、ただ何にでも泣いてしまう日もあります。ぬるめのお湯をはったバスタブに入れて、泡を少し加えてみましょう。お湯のふしぎな、緊張をほぐす力が、部屋全体とこの子の神経にすぐに落ち着きをもたらします。', title_ko = '따뜻한 물의 기적 🛀', body_ko = '가끔은 아무것도 통하지 않고 모든 일에 울기만 하죠. 따뜻한 물을 받은 욕조에 거품을 조금 풀고 들어가게 해 주세요. 긴장을 풀어 주는 물의 신비한 힘이 방 안과 아이의 신경계에 바로 평온을 가져다줄 거예요.', title_nl = 'Het wonder van warm water 🛀', body_nl = 'Soms werkt niets en huilt hij gewoon om alles. Zet hem in een bad met lauw water en doe er wat schuim in. De mystieke, ontspannende kracht van het water brengt meteen rust in de hele kamer en in zijn zenuwstelsel.', title_pl = 'Cud ciepłej wody 🛀', body_pl = 'Czasem nic nie działa, a on po prostu płacze o wszystko. Włóż go do wanny z ciepłą wodą i dodaj trochę piany. Tajemnicza, kojąca moc wody od razu wniesie spokój do całego pokoju i do jego układu nerwowego.', title_pt = 'O milagre da água quente 🛀', body_pt = 'Às vezes nada resulta, ele simplesmente chora por tudo. Ponha-o numa banheira com água morna e junte um pouco de espuma. O poder místico da água, que alivia a tensão, vai trazer logo calma a todo o quarto e ao sistema nervoso dele.', title_sv = 'Det varma vattnets under 🛀', body_sv = 'Ibland hjälper ingenting, barnet gråter bara åt allt. Sätt barnet i ett badkar med ljummet vatten och lite skum. Vattnets mystiska, spänningsdämpande kraft ger direkt lugn åt hela rummet och barnets nervsystem.', title_vi = 'Phép màu của nước ấm 🛀', body_vi = 'Đôi khi chẳng cách nào hiệu quả, bé cứ khóc vì mọi thứ. Hãy cho bé vào bồn nước ấm, thêm chút bọt xà phòng. Sức mạnh kỳ diệu, xua tan căng thẳng của nước sẽ lập tức mang lại bình yên cho cả căn phòng và hệ thần kinh của bé.', title_zh = '温水的奇迹 🛀', body_zh = '有时候什么办法都不管用，宝宝就是什么都哭。把宝宝放进装满温水的浴缸，再加一点泡泡。水那种神奇的、能吸走紧张的力量，会马上给整个房间和宝宝的神经系统带来安宁。' WHERE id = '53a9bbe1-a99a-4438-963b-9b63a44c8eb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ingeniero del armario 👗', body_es = 'Hoy quiere salir con calcetines desparejados y la camiseta del revés. Olvídate de las normas sociales de qué combina. La libertad de tomar sus propias decisiones y defenderlas es una lección de vida mucho más grande que combinar los colores. Dale permiso.', title_fr = 'L''ingénieur de la garde-robe 👗', body_fr = 'Aujourd''hui, il veut sortir avec des chaussettes dépareillées et un t-shirt à l''envers. Laissez tomber les normes d''assortiment. La liberté de prendre sa propre décision et de la défendre est une leçon de vie bien plus grande que des couleurs assorties. Laissez-le faire.', title_hi = 'अलमारी का इंजीनियर 👗', body_hi = 'आज अलग-अलग जोड़ी के मोज़े और उलटी कमीज़ पहनकर बाहर जाना चाहता है। लोगों के मेल-जोल वाले कायदे छोड़िए। अपना फ़ैसला लेने और उस पर टिके रहने की आज़ादी रंगों के मेल से कहीं बड़ा जीवन का सबक है। इजाज़त दीजिए।', title_id = 'Insinyur lemari baju 👗', body_id = 'Hari ini ia ingin keluar dengan kaus kaki yang tidak sepasang dan baju terbalik. Lupakan norma keserasian di masyarakat. Kebebasan membuat keputusan sendiri dan membelanya adalah pelajaran hidup yang jauh lebih besar daripada warna yang serasi. Izinkan saja.', title_ja = 'クローゼットのエンジニア 👗', body_ja = '今日は左右ちがう靴下と、後ろ前のシャツで出かけたいそう。世間の「ふつう」は気にしないで。自分で決めてそれを守る自由は、色の組み合わせよりずっと大きな人生のレッスンです。許してあげましょう。', title_ko = '옷장 엔지니어 👗', body_ko = '오늘은 짝짝이 양말에 뒤집어 입은 셔츠로 나가겠다고 하나요? 어울려야 한다는 기준은 잊으세요. 스스로 정하고 그 결정을 지키는 자유는 색깔 맞추기보다 훨씬 큰 인생 수업이에요. 허락해 주세요.', title_nl = 'Kledingkastingenieur 👗', body_nl = 'Hij wil vandaag naar buiten met twee verschillende sokken en een binnenstebuiten shirt. Vergeet wat er ''hoort''. De vrijheid om zelf te beslissen en die keuze te verdedigen is een veel grotere levensles dan kleuren die bij elkaar passen. Laat hem.', title_pl = 'Inżynier garderoby 👗', body_pl = 'Dziś chce wyjść na dwór w dwóch różnych skarpetkach i koszulce na lewą stronę. Odpuść społeczne normy dopasowania. Wolność podejmowania własnych decyzji i ich obrony to o wiele większa lekcja życia niż pasujące kolory. Pozwól mu.', title_pt = 'Engenheiro do guarda-roupa 👗', body_pt = 'Hoje quer sair com meias trocadas e a camisola ao contrário. Esqueça as normas sociais de combinar. A liberdade de tomar uma decisão e defendê-la é uma lição de vida muito maior do que combinar as cores. Deixe-o.', title_sv = 'Garderobsingenjören 👗', body_sv = 'I dag vill barnet gå ut med omaka strumpor och tröjan ut och in. Strunta i samhällets normer om vad som passar. Friheten att fatta sina egna beslut och försvara dem är en mycket större livsläxa än att färgerna matchar. Ge barnet lov.', title_vi = 'Kỹ sư tủ quần áo 👗', body_vi = 'Hôm nay bé muốn ra ngoài với hai chiếc tất lệch đôi và áo mặc trái. Kệ chuẩn mực "hợp mốt" của xã hội. Quyền tự đưa ra quyết định và bảo vệ nó là bài học cuộc sống lớn hơn nhiều so với việc phối màu. Hãy cho phép bé.', title_zh = '衣柜工程师 👗', body_zh = '今天想穿两只不一样的袜子、把衣服穿反了出门。别管社会上的搭配规范了。自己做决定并捍卫它的自由，是比颜色搭不搭重要得多的人生一课。就随宝宝吧。' WHERE id = 'b49dbabf-98b6-4f35-8748-de30793c2722' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Esta mañana le dice a su juguete una palabra cualquiera, y quizá poco apropiada, que usaste ayer hablando con tu pareja! Es tu espejo viviente. Cuida especialmente las emociones de lo que hablas delante de él: lo copia todo, una a una.', body_fr = 'Un mot pris au hasard, et peut-être inutile, que vous avez dit hier en parlant avec votre partenaire, il le répète ce matin à son jouet ! Il est votre miroir vivant. Faites particulièrement attention aux émotions que vous exprimez devant lui, il copie tout, une à une.', body_hi = 'कल साथी से बात करते समय आपने जो कोई भी, शायद बेकार-सा शब्द बोला, आज सुबह वह उसे अपने खिलौने से कह रहा है! वह आपका जीता-जागता आईना है। उसके सामने आप जिन भावनाओं से बात करती हैं, उन पर खास ध्यान दीजिए, वह एक-एक करके नकल करता है।', body_id = 'Kata acak yang mungkin tidak perlu, yang kemarin Anda ucapkan saat mengobrol dengan pasangan, pagi ini ia ucapkan kepada mainannya! Ia adalah cermin hidup Anda. Perhatikan baik-baik emosi yang Anda ungkapkan di dekatnya, ia meniru satu per satu.', body_ja = '昨日パートナーと話していたときに使った、なにげない、もしかしたら言わなくてよかった言葉を、今朝おもちゃに向かって言っている！この子はあなたの生きた鏡です。そばで話すときの感情には特に気をつけて。ひとつひとつまねしています。', body_ko = '어제 배우자와 이야기하며 무심코 쓴, 어쩌면 안 써도 될 말을 오늘 아침 장난감에게 하고 있나요! 아이는 엄마의 살아 있는 거울이에요. 아이 앞에서 드러내는 감정에 특히 신경 쓰세요, 하나하나 따라 해요.', body_nl = 'Een toevallig en misschien overbodig woord dat je gisteren tegen je partner zei, zegt hij vanochtend tegen zijn knuffel! Hij is je levende spiegel. Let extra op de emoties die je in zijn bijzijn uitspreekt, hij kopieert ze een voor een.', body_pl = 'Przypadkowe, może niepotrzebne słowo, którego wczoraj użyłaś w rozmowie z partnerem, dziś rano mówi do swojej zabawki! Jest twoim żywym lustrem. Szczególnie uważaj na emocje, które przy nim okazujesz, kopiuje je jedna po drugiej.', body_pt = 'Esta manhã diz ao brinquedo uma palavra qualquer, e talvez desnecessária, que usou ontem a falar com o seu companheiro! É o seu espelho vivo. Preste especial atenção às emoções que exprime perto dele: ele copia tudo, uma a uma.', body_sv = 'Ett slumpmässigt och kanske onödigt ord som du använde när du pratade med din partner i går säger barnet till sin leksak i morse! Barnet är din levande spegel. Var särskilt uppmärksam på känslorna i det du säger när barnet är med, det kopierar allt.', body_vi = 'Một từ ngẫu nhiên, có lẽ chẳng cần thiết, mà hôm qua mẹ dùng khi nói chuyện với chồng, sáng nay bé lại nói với đồ chơi của mình! Bé là tấm gương sống của mẹ. Hãy đặc biệt chú ý đến những cảm xúc khi nói chuyện trước mặt bé, bé sao chép từng chút một.', body_zh = '昨天和伴侣聊天时随口说的一个、可能不该说的词，今天早上宝宝就对着玩具说了出来！宝宝是你活生生的镜子。在宝宝身边说话时要格外注意情绪，宝宝会一个个照搬。' WHERE id = '00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento divertido de papá 📖', body_es = 'Esta noche la voz de la habitación no es la tuya. Dale el libro de cuentos a papá y deja que cuente la historia a propósito al revés, de forma cómica y absurda. Mira desde fuera cómo disfruta el peque corrigiéndole y cómo se ríe a carcajadas con su padre.', title_fr = 'Le conte rigolo de papa 📖', body_fr = 'Ce soir, ce n''est pas votre voix qu''on entendra dans la chambre. Donnez le livre de contes à papa et laissez-le raconter l''histoire à l''envers, exprès, de façon comique et absurde. Regardez de loin le plaisir de l''enfant à le corriger et ses éclats de rire.', title_hi = 'पापा की मज़ेदार कहानी 📖', body_hi = 'आज शाम कमरे में आवाज़ आपकी नहीं होगी। कहानी की किताब पापा को दीजिए और उन्हें कहानी जानबूझकर उलटी, मज़ेदार और बेतुकी तरह सुनाने दीजिए। दूर से देखिए कि बच्चा उन्हें सुधारने में कितना मज़ा लेता है और पापा पर कैसे ठहाके लगाता है।', title_id = 'Dongeng seru Ayah 📖', body_id = 'Malam ini suara di kamar bukan milik Anda. Serahkan buku dongeng kepada Ayah dan biarkan ia sengaja menceritakan kisahnya terbalik, lucu, dan absurd. Saksikan dari samping betapa anak senang membetulkannya dan tertawa terbahak-bahak pada ayahnya.', title_ja = 'パパの楽しいおはなし 📖', body_ja = '今夜の部屋の主役は、あなたの声ではありません。絵本をパパに渡して、お話をわざとあべこべに、おもしろおかしく話してもらいましょう。子どもがそれを直すのを楽しんで、パパに大笑いする姿をそばで眺めて。', title_ko = '아빠의 재미있는 동화 📖', body_ko = '오늘 저녁 방 안의 목소리는 엄마 몫이 아니에요. 동화책을 아빠에게 건네고 일부러 거꾸로, 웃기고 엉뚱하게 이야기하게 하세요. 아이가 아빠를 고쳐 주며 얼마나 즐거워하고 깔깔 웃는지 옆에서 지켜보세요.', title_nl = 'Papa''s leuke sprookje 📖', body_nl = 'Vanavond is de stem in de kamer niet die van jou. Geef het sprookjesboek aan papa en laat hem het verhaal expres achterstevoren, grappig en absurd vertellen. Kijk van een afstand hoe je kind geniet van het verbeteren en hoe hij om zijn papa schatert.', title_pl = 'Zabawna bajka taty 📖', body_pl = 'Dziś wieczorem w pokoju nie słychać twojego głosu. Daj tacie książkę z bajkami i niech celowo opowie historię na opak, zabawnie i absurdalnie. Obserwuj z boku, z jaką przyjemnością dziecko go poprawia i jak zaśmiewa się z taty.', title_pt = 'A história divertida do pai 📖', body_pt = 'Esta noite a voz no quarto não é a sua. Dê o livro de histórias ao pai e deixe-o contar a história ao contrário de propósito, de forma cómica e absurda. Observe à distância como a criança adora corrigi-lo e se ri às gargalhadas com o pai.', title_sv = 'Pappas roliga saga 📖', body_sv = 'I kväll är det inte din röst som hörs i rummet. Ge sagoboken till pappa och låt honom berätta historien medvetet bakvänt, roligt och absurt. Titta från sidan på hur barnet njuter av att rätta honom och skrattar åt pappa.', title_vi = 'Câu chuyện vui nhộn của bố 📖', body_vi = 'Tối nay giọng nói trong phòng không phải của mẹ. Hãy đưa cuốn truyện cho bố và để bố cố tình kể ngược, hài hước và ngớ ngẩn. Ngắm nhìn từ xa bé thích thú sửa lời bố và cười ngặt nghẽo thế nào.', title_zh = '爸爸的趣味童话 📖', body_zh = '今晚房间里的声音不属于你。把故事书交给爸爸，让他故意把故事讲反、讲得搞笑又荒诞。在一旁看看宝宝多么享受纠正爸爸，又是怎样对着爸爸哈哈大笑的。' WHERE id = '885b2dd9-966f-46c2-bbae-00f0fd65a479' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la Comunidad 💬', body_es = 'El pensamiento «¿Por qué mi hijo es tan tozudo?» te está comiendo por dentro. Entra en la Comunidad Anacan. Cuando leas las crisis absurdas parecidas que estallan en casa de otras madres, verás que no estás sola y que vas por un camino totalmente normal.', title_fr = 'La force de la communauté 💬', body_fr = 'La pensée « Pourquoi mon enfant est-il si têtu ? » vous ronge ? Rejoignez la Communauté Anacan. En lisant les crises absurdes qui éclatent chez d''autres mamans, vous verrez que vous n''êtes pas seule et que vous êtes sur une voie tout à fait normale.', title_hi = 'कम्युनिटी की ताकत 💬', body_hi = '‘मेरा बच्चा इतना ज़िद्दी क्यों है?’ वाला ख्याल आपका दिमाग खा रहा है। Anacan कम्युनिटी में जाइए। दूसरी माँओं के घरों में होने वाले ऐसे ही बेतुके नखरे पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और बिल्कुल सही रास्ते पर हैं।', title_id = 'Kekuatan komunitas 💬', body_id = 'Pikiran ''Kenapa anakku keras kepala sekali?'' terus menggerogoti otak Anda. Masuklah ke Komunitas Anacan. Saat membaca krisis absurd serupa di rumah ibu-ibu lain, Anda akan melihat bahwa Anda tidak sendirian dan sedang berada di jalur yang sepenuhnya normal.', title_ja = 'コミュニティの力 💬', body_ja = '「うちの子はどうしてこんなにがんこなの？」という思いが頭から離れない。Anacanコミュニティを開いてみましょう。ほかのママたちの家で起きている、同じようなおかしなかんしゃくを読めば、ひとりじゃないこと、ごく普通の道を歩んでいることがわかります。', title_ko = '커뮤니티의 힘 💬', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각이 머리를 갉아먹나요? Anacan 커뮤니티에 들어가 보세요. 다른 집에서 터지는 비슷하게 엉뚱한 떼쓰기를 읽으면 혼자가 아니고 아주 정상적인 길을 걷고 있다는 걸 알게 될 거예요.', title_nl = 'De kracht van de Community 💬', body_nl = 'Vreet de gedachte ''Waarom is mijn kind zo koppig?'' aan je? Ga naar de Anacan Community. Als je leest over net zulke absurde buien bij andere mama''s thuis, zie je dat je niet de enige bent en dat je helemaal op de normale weg zit.', title_pl = 'Siła Społeczności 💬', body_pl = 'Myśl „Dlaczego moje dziecko jest takie uparte?” nie daje ci spokoju. Wejdź do Społeczności Anacan. Gdy przeczytasz o podobnych absurdalnych kryzysach w domach innych mam, zobaczysz, że nie jesteś sama i wszystko idzie zupełnie normalnym torem.', title_pt = 'A força da comunidade 💬', body_pt = 'O pensamento "Porque é que o meu filho é tão teimoso?" não lhe sai da cabeça. Entre na Comunidade Anacan. Ao ler as crises absurdas parecidas que rebentam em casa de outras mães, vai ver que não está sozinha e que está no caminho perfeitamente normal.', title_sv = 'Gemenskapens kraft 💬', body_sv = 'Tanken ”Varför är mitt barn så envist?” äter upp dig. Gå in i Anacan Community. När du läser om liknande absurda kriser hemma hos andra mammor ser du att du inte är ensam och att du är helt på rätt väg.', title_vi = 'Sức mạnh của Cộng đồng 💬', body_vi = 'Ý nghĩ "Sao con mình bướng thế?" cứ ám ảnh mẹ. Hãy vào Cộng đồng Anacan. Khi đọc về những cơn khủng hoảng "khó đỡ" tương tự ở nhà các mẹ khác, mẹ sẽ thấy mình không đơn độc và mọi thứ đều hoàn toàn bình thường.', title_zh = '社区的力量 💬', body_zh = '“我的孩子怎么这么倔？”这个念头一直折磨着你。进入Anacan社区。读到其他妈妈家里也在上演类似的荒诞崩溃，你就会发现自己并不孤单，一切完全正常。' WHERE id = 'fdf68496-5c5f-493c-aaed-7e9ab140b9c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hace sol, pero quiere ponerse el abrigo de invierno. No discutas. Abre la herramienta Tiempo y ropa y enséñale el icono del niño con ropa ligera en la pantalla. El truco de «mira, el móvil dice que hoy hace calor» siempre funciona de maravilla.', body_fr = 'Il fait soleil, mais il veut mettre sa doudoune d''hiver. Ne discutez pas. Ouvrez Météo et tenue et montrez-lui à l''écran l''icône de l''enfant habillé léger. L''astuce « Regarde, le téléphone dit qu''il fait chaud aujourd''hui » marche à tous les coups.', body_hi = 'धूप निकली है, पर वह सर्दियों की जैकेट पहनना चाहता है। बहस मत कीजिए। मौसम और कपड़े टूल खोलकर स्क्रीन पर हल्के कपड़े पहने बच्चे का चिह्न उसे दिखाइए। ‘देखो, फ़ोन कह रहा है कि आज गर्मी है’ वाली तरकीब हमेशा कमाल करती है।', body_id = 'Matahari bersinar, tapi ia ingin memakai jaket musim dingin. Jangan berdebat. Buka Cuaca dan Pakaian dan tunjukkan simbol anak berpakaian tipis di layar. Trik ''Lihat, ponsel bilang hari ini panas'' selalu sangat ampuh.', body_ja = '日が出ているのに、冬のジャンパーを着たがる。言い合わないで。「天気と服装」を開いて、画面の薄着の子どものマークを見せましょう。「ほら、スマホも今日はあったかいって」という作戦は、いつだってよく効きます。', body_ko = '해가 쨍쨍한데 겨울 점퍼를 입겠다고 하나요? 따지지 마세요. 날씨와 옷차림 도구를 열어 화면 속 얇게 입은 아이 그림을 보여 주세요. ''봐, 휴대폰이 오늘은 덥대'' 작전은 언제나 잘 통해요.', body_nl = 'De zon schijnt, maar hij wil zijn winterjas aan. Ga niet in discussie. Open de tool Weer en kleding en laat hem het icoontje van het dun geklede kind op het scherm zien. Het trucje ''Kijk, de telefoon zegt dat het vandaag warm is'' werkt altijd perfect.', body_pl = 'Świeci słońce, a on chce założyć zimową kurtkę. Nie kłóć się. Otwórz Pogodę i ubiór i pokaż mu na ekranie ikonkę lekko ubranego dziecka. Sztuczka „Zobacz, telefon mówi, że dziś jest ciepło” zawsze świetnie działa.', body_pt = 'Está sol, mas ele quer vestir o casaco de inverno. Não discuta. Abra a ferramenta Tempo e Roupa e mostre-lhe no ecrã o símbolo da criança com roupa leve. O truque "Olha, o telemóvel diz que hoje está calor" funciona sempre na perfeição.', body_sv = 'Solen skiner, men barnet vill ha vinterjacka. Bråka inte. Öppna verktyget Väder och kläder och visa barnet symbolen med det tunt klädda barnet på skärmen. Knepet ”Titta, telefonen säger att det är varmt i dag” fungerar alltid utmärkt.', body_vi = 'Trời nắng, nhưng bé lại muốn mặc áo khoác mùa đông. Đừng tranh cãi. Hãy mở Thời tiết và trang phục và chỉ cho bé hình em bé mặc đồ mỏng trên màn hình. Mẹo "Nhìn này, điện thoại bảo hôm nay trời nóng" luôn rất hiệu quả.', body_zh = '太阳出来了，宝宝却想穿冬天的外套。别争了。打开天气与穿衣工具，给宝宝看屏幕上那个穿得薄薄的小孩图标。“你看，手机说今天很暖和”，这个小妙招一直都特别管用。' WHERE id = '489a0197-f1e2-44a5-bece-55d85fa323ae' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El guion está en sus manos 🪄', body_es = 'Los cuentos clásicos ya no le llaman la atención. Abre Cuentos inteligentes y pregúntale: «¿Y ahora adónde va este tren mágico?». Deja que se duerma soñando con el final raro y totalmente absurdo que invente.', title_fr = 'C''est lui qui tient le scénario 🪄', body_fr = 'Les contes classiques n''attirent plus son attention. Ouvrez les Contes intelligents et posez-lui la question : « Où va aller ce train magique maintenant ? » Laissez-le s''endormir en rêvant à la fin bizarre et complètement absurde qu''il aura inventée.', title_hi = 'कहानी उसके हाथ में 🪄', body_hi = 'पुरानी कहानियाँ अब उसका ध्यान नहीं खींचतीं। स्मार्ट कहानियाँ खोलिए और उससे पूछिए: ‘अब यह जादुई ट्रेन कहाँ जाए?’ उसे अपने गढ़े अजीब और बिल्कुल बेतुके अंत के साथ खुद भी सपनों में खोकर सोने दीजिए।', title_id = 'Skenario ada di tangannya 🪄', body_id = 'Dongeng klasik tak lagi menarik perhatiannya. Buka Dongeng Pintar dan tanyakan padanya: ''Sekarang kereta ajaib ini pergi ke mana?''. Biarkan ia larut dalam khayalan dan tertidur dengan akhir cerita yang aneh dan absurd karangannya sendiri.', title_ja = 'ストーリーはこの子しだい 🪄', body_ja = '定番のお話には、もう興味を示さない。「スマートおはなし」を開いて、「この魔法の列車、次はどこへ行く？」と聞いてみましょう。考えたふしぎでまったくおかしな結末とともに、自分も夢の世界へ入って眠らせてあげて。', title_ko = '시나리오는 아이 손에 🪄', body_ko = '늘 읽던 동화에 더는 관심이 없나요? 스마트 동화를 열고 물어보세요: ''이제 이 마법 기차는 어디로 갈까?'' 아이가 지어낸 엉뚱하고 기발한 결말과 함께 꿈나라로 가게 해 주세요.', title_nl = 'Het scenario is in zijn handen 🪄', body_nl = 'Klassieke sprookjes trekken zijn aandacht niet meer. Open Slimme sprookjes en vraag hem: ''Waar moet deze magische trein nu naartoe?'' Laat hem wegdromen en in slaap vallen met het rare, totaal absurde einde dat hij zelf bedenkt.', title_pl = 'Scenariusz w jego rękach 🪄', body_pl = 'Klasyczne bajki już go nie wciągają. Otwórz Mądre bajki i zapytaj: „Dokąd teraz ma pojechać ten magiczny pociąg?”. Niech zaśnie, zatopiony w marzeniach, przy dziwnym i zupełnie absurdalnym zakończeniu, które sam wymyśli.', title_pt = 'O guião está nas mãos dele 🪄', body_pt = 'As histórias clássicas já não lhe prendem a atenção. Abra as Histórias Inteligentes e pergunte-lhe: "E agora, para onde vai este comboio mágico?". Deixe-o adormecer perdido nos sonhos com o final estranho e totalmente absurdo que inventar.', title_sv = 'Manuset ligger i barnets händer 🪄', body_sv = 'Klassiska sagor fångar inte längre barnets uppmärksamhet. Öppna Smarta sagor och fråga barnet: ”Vart ska det magiska tåget åka nu?” Låt barnet själv försjunka i drömmar och somna till sitt eget konstiga och helt absurda slut.', title_vi = 'Kịch bản trong tay bé 🪄', body_vi = 'Truyện cổ tích quen thuộc không còn thu hút bé nữa. Hãy mở Truyện cổ tích thông minh và hỏi bé: "Giờ đoàn tàu thần kỳ này nên đi đâu nhỉ?". Để bé chìm vào giấc mơ cùng cái kết kỳ lạ, ngộ nghĩnh do chính mình nghĩ ra.', title_zh = '剧本由宝宝来写 🪄', body_zh = '经典童话已经吸引不了宝宝了。打开智慧童话，问问宝宝：“现在这列魔法火车该去哪儿？”就让宝宝带着自己编的那个奇怪又完全荒诞的结局，沉入梦乡吧。' WHERE id = '64df174c-9f28-403f-83be-8452dd687caf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cita con el dentista 🦷', body_es = 'Coge el cepillo y quiere examinarte los dientes muy en serio. Abre la boca y obedece a este médico tan cómico. Los juegos de rol son la forma más eficaz y divertida de desarrollar la personalidad y vencer los miedos.', title_fr = 'Rendez-vous chez le dentiste 🦷', body_fr = 'Il prend la brosse à dents et veut examiner très sérieusement vos dents. Ouvrez la bouche et obéissez à ce drôle de docteur. Les jeux de rôle sont la façon la plus efficace et la plus amusante de développer sa personnalité et de vaincre ses peurs.', title_hi = 'दाँतों के डॉक्टर के पास 🦷', body_hi = 'हाथ में ब्रश लेकर गंभीरता से आपके दाँतों की जाँच करना चाहता है। मुँह खोलिए और इस मज़ेदार डॉक्टर की बात मानिए। रोल-प्ले खेल व्यक्तित्व के विकास और डर पर जीत पाने का सबसे असरदार, सबसे मज़ेदार तरीका हैं।', title_id = 'Periksa ke dokter gigi 🦷', body_id = 'Ia mengambil sikat gigi dan ingin memeriksa gigi Anda dengan serius. Buka mulut Anda dan patuhi dokter lucu ini. Bermain peran adalah cara paling efektif dan menyenangkan untuk mengembangkan kepribadian dan mengalahkan rasa takut.', title_ja = '歯医者さんの診察 🦷', body_ja = '歯ブラシを手に、あなたの歯を真剣に診察したがる。口を開けて、このおかしなお医者さんに従いましょう。ごっこ遊びは、人格の発達と怖さを乗りこえるための、いちばん効果的で楽しい方法です。', title_ko = '치과 진료 시간 🦷', body_ko = '칫솔을 들고 엄마의 이를 아주 진지하게 검사하고 싶어 하나요? 입을 크게 벌리고 이 귀여운 의사 선생님을 따라 주세요. 역할 놀이는 인격을 키우고 두려움을 이기는 가장 효과적이고 즐거운 방법이에요.', title_nl = 'Bij de tandarts 🦷', body_nl = 'Hij pakt een tandenborstel en wil heel serieus jouw tanden onderzoeken. Doe je mond open en gehoorzaam deze grappige dokter. Rollenspel is de meest effectieve en leukste manier om zijn persoonlijkheid te ontwikkelen en angsten te overwinnen.', title_pl = 'Wizyta u dentysty 🦷', body_pl = 'Bierze szczoteczkę do ręki i chce poważnie zbadać twoje zęby. Otwórz buzię i poddaj się temu zabawnemu doktorowi. Zabawy w odgrywanie ról to najskuteczniejszy i najzabawniejszy sposób na rozwój osobowości i pokonywanie lęków.', title_pt = 'Consulta no dentista 🦷', body_pt = 'Pega na escova e quer examinar-lhe os dentes muito a sério. Abra a boca e obedeça a este médico cómico. As brincadeiras de faz de conta são a forma mais eficaz e divertida de desenvolver a personalidade e vencer os medos.', title_sv = 'Besök hos tandläkaren 🦷', body_sv = 'Barnet tar tandborsten och vill undersöka dina tänder på största allvar. Gapa och lyd den roliga doktorn. Rollekar är det mest effektiva och roligaste sättet att utveckla personligheten och övervinna rädslor.', title_vi = 'Khám nha sĩ 🦷', body_vi = 'Bé cầm bàn chải và muốn khám răng cho mẹ thật nghiêm túc. Hãy há miệng và ngoan ngoãn nghe lời "bác sĩ" hài hước này. Trò chơi nhập vai là cách hiệu quả và vui nhất để phát triển nhân cách và vượt qua nỗi sợ.', title_zh = '看牙医 🦷', body_zh = '拿起牙刷，要非常认真地给你检查牙齿。张开嘴，乖乖听这位搞笑医生的话吧。角色扮演游戏是人格发展和战胜恐惧最有效、也最有趣的方式。' WHERE id = 'e9ba59d9-6287-434c-823d-456c6d21f0ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es un tesoro 🍬', body_es = '¿Se ha armado una buena porque tiraste a la basura ese envoltorio viejo de chocolate que guardaba desde hace días y con el que ni jugaba? Lo que para ti es basura puede ser su colección valiosa. Para cortar el llanto, distrae su atención al instante con algo más atractivo.', title_fr = 'Pas un déchet, un trésor 🍬', body_fr = 'C''est l''apocalypse parce que vous avez jeté ce vieux papier de chocolat qu''il gardait depuis des jours sans jouer avec ? Ce qui est un déchet pour vous peut être sa précieuse collection. Pour arrêter ses pleurs, détournez aussitôt son attention avec un objet plus attirant.', title_hi = 'कचरा नहीं, खज़ाना 🍬', body_hi = 'दिनों से रखा और कभी न खेला वह पुराना चॉकलेट रैपर आपने फेंक दिया, इसलिए कयामत आ गई? जो आपके लिए कचरा है, वह उसका कीमती संग्रह हो सकता है। रोना रोकने के लिए तुरंत किसी और दिलचस्प चीज़ से उसका ध्यान बँटाइए।', title_id = 'Bukan sampah, tapi harta karun 🍬', body_id = 'Kiamat terjadi karena Anda membuang bungkus cokelat lama yang sudah berhari-hari ia simpan dan tak pernah ia mainkan? Yang bagi Anda sampah bisa jadi koleksi berharganya. Untuk menghentikan tangisnya, segera alihkan perhatiannya dengan benda yang lebih menarik.', title_ja = 'ゴミじゃない、宝物 🍬', body_ja = '何日も取っておいて遊んでもいなかった古いチョコの包み紙を捨てたら、大騒ぎ？あなたにはゴミでも、この子には大切なコレクションかもしれません。泣きやませるには、すぐにもっと魅力的なもので気をそらしてあげましょう。', title_ko = '쓰레기가 아니라 보물 🍬', body_ko = '며칠째 간직하던, 가지고 놀지도 않던 낡은 초콜릿 포장지를 버렸다고 난리가 났나요? 엄마에겐 쓰레기여도 아이에겐 귀한 수집품일 수 있어요. 울음을 멈추려면 더 끌리는 물건으로 바로 관심을 돌려 주세요.', title_nl = 'Geen afval, maar een schat 🍬', body_nl = 'Brak de hel los omdat je dat oude chocoladepapiertje weggooide dat hij al dagen bewaarde maar waar hij niet mee speelde? Wat voor jou afval is, kan voor hem een waardevolle verzameling zijn. Leid zijn aandacht meteen af met iets wat nog leuker is om zijn tranen te stoppen.', title_pl = 'To nie śmieć, to skarb 🍬', body_pl = 'Rozpętało się piekło, bo wyrzuciłaś stary papierek po czekoladzie, który trzymał od dni i którym się nie bawił? To, co dla ciebie jest śmieciem, może być jego cenną kolekcją. Żeby przerwać płacz, od razu odwróć jego uwagę czymś bardziej atrakcyjnym.', title_pt = 'Não é lixo, é tesouro 🍬', body_pt = 'Foi o fim do mundo porque deitou fora aquele papel de chocolate velho que ele guardava há dias e com que nem brincava? O que para si é lixo pode ser a coleção valiosa dele. Para parar o choro, desvie logo a atenção dele para algo mais apelativo.', title_sv = 'Inte skräp, utan en skatt 🍬', body_sv = 'Bröt jordens undergång ut för att du slängde det gamla chokladpapperet som barnet sparat i flera dagar och inte lekt med? Det som är skräp för dig kan vara barnets värdefulla samling. För att stoppa gråten, led genast över uppmärksamheten till något mer lockande.', title_vi = 'Không phải rác, mà là kho báu 🍬', body_vi = 'Cả nhà "náo loạn" chỉ vì mẹ vứt tờ giấy gói sô-cô-la cũ mà bé giữ mấy ngày nay dù chẳng chơi đến? Thứ với mẹ là rác có thể là bộ sưu tập quý giá của bé. Để bé nín khóc, hãy lập tức đánh lạc hướng bằng một món đồ hấp dẫn hơn.', title_zh = '不是垃圾，是宝藏 🍬', body_zh = '就因为你把宝宝藏了好几天、从没玩过的旧巧克力包装纸扔了，天就塌了？在你看来的垃圾，可能是宝宝珍贵的收藏。想让宝宝不哭，就马上用一样更吸引人的东西转移注意力。' WHERE id = 'cafa10cc-4494-418e-834e-6ddf05c49140' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Victoria sin champán 🥂', body_es = 'El peque se ha dormido. Aunque no haya champán, servid té caliente en los vasos y brindad con tu pareja diciendo: «Hoy también hemos podido con este caos tormentoso». Sois el equipo inquebrantable e incansable de la casa.', title_fr = 'Victoire sans champagne 🥂', body_fr = 'L''enfant dort. Pas de champagne ? Versez du thé chaud dans des verres et trinquez avec votre partenaire : « Aujourd''hui encore, on a réussi à gérer ce chaos agité ! » Vous êtes l''équipe inébranlable et infatigable de cette maison.', title_hi = 'बिना शैंपेन की जीत 🥂', body_hi = 'बच्चा सो गया। शैंपेन न सही, गिलासों में गरम चाय डालिए और अपने साथी के साथ ‘आज भी इस तूफ़ानी अफ़रा-तफ़री को संभाल लिया’ कहकर गिलास टकराइए। आप इस घर की अटूट और कभी न थकने वाली टीम हैं।', title_id = 'Kemenangan tanpa sampanye 🥂', body_id = 'Anak sudah tidur. Tak ada sampanye pun tak apa, tuang teh hangat ke gelas dan bersulanglah dengan pasangan sambil berkata ''Hari ini pun kita berhasil mengendalikan kekacauan penuh badai ini''. Kalian adalah tim rumah yang tak tergoyahkan dan tak kenal lelah.', title_ja = 'シャンパンなしの祝杯 🥂', body_ja = '子どもが寝ました。シャンパンがなくても、コップに温かいお茶を注いで、パートナーと「今日もこの嵐のようなカオスを乗りきったね」と乾杯しましょう。ふたりはこの家の、揺るがない疲れ知らずのチームです。', title_ko = '샴페인 없는 승리 🥂', body_ko = '아이가 잠들었어요. 샴페인이 없어도 컵에 따뜻한 차를 따르고 배우자와 ''오늘도 이 폭풍 같은 혼돈을 해냈어''라며 건배하세요. 두 사람은 이 집의 흔들림 없고 지치지 않는 한 팀이에요.', title_nl = 'Overwinning zonder champagne 🥂', body_nl = 'Je kind slaapt. Geen champagne in huis? Schenk dan warme thee in en klink met je partner: ''Ook vandaag hebben we deze stormachtige chaos de baas gekund!'' Jullie zijn het onverwoestbare, onvermoeibare team van dit huis.', title_pl = 'Zwycięstwo bez szampana 🥂', body_pl = 'Dziecko śpi. Nie ma szampana? Nalejcie do szklanek gorącej herbaty i stuknijcie się z partnerem, mówiąc: „Dziś też opanowaliśmy ten burzliwy chaos”. Jesteście niezłomną i niezmordowaną drużyną tego domu.', title_pt = 'Vitória sem champanhe 🥂', body_pt = 'A criança adormeceu. Mesmo sem champanhe, sirvam chá quente nos copos e brindem com o seu companheiro: "Hoje também conseguimos gerir este caos tempestuoso". São uma equipa inabalável e incansável cá de casa.', title_sv = 'Seger utan champagne 🥂', body_sv = 'Barnet sover. Även om det inte finns champagne, häll upp varmt te i glasen, skåla med din partner och säg ”Det här stormiga kaoset klarade vi av i dag också”. Ni är hemmets orubbliga och outtröttliga lag.', title_vi = 'Chiến thắng không cần sâm panh 🥂', body_vi = 'Bé đã ngủ. Không có sâm panh cũng chẳng sao, hãy rót trà nóng vào cốc và cụng ly cùng chồng: "Hôm nay mình lại kiểm soát được cơn bão hỗn loạn này rồi!". Hai người là đội không gì lay chuyển được, không biết mệt mỏi của ngôi nhà này.', title_zh = '没有香槟的胜利 🥂', body_zh = '宝宝睡着了。没有香槟也没关系，往杯子里倒上热茶，和伴侣碰个杯：“今天这场暴风雨般的混乱，我们也搞定了。”你们是这个家坚不可摧、不知疲倦的团队。' WHERE id = 'd9ad6664-d013-4d53-b45b-e81b7aa6c58c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha descubierto esa única verdura verde de la sopa y se niega a comer? Usa en el Plan de alimentación los trucos más hábiles para mezclar las verduras con pasta de colores, despistarle y esconderlas en puré.', body_fr = 'Il a repéré l''unique légume vert de la soupe et refuse de manger ? Appliquez les astuces les plus habiles du Plan de nutrition : mélanger les légumes à des pâtes colorées pour détourner son attention, ou les cacher en purée.', body_hi = 'सूप में वह एक हरी सब्ज़ी खोजकर खाने से मना कर देता है? फ़ीडिंग प्लान में सब्ज़ियों को रंगीन पास्ता में मिलाकर ध्यान बँटाने और प्यूरी बनाकर छिपाने के सबसे माहिर तरीके आज़माइए।', body_id = 'Ia menemukan satu potong sayur hijau di supnya lalu menolak makan? Di Rencana Nutrisi, terapkan cara paling jitu untuk mencampur sayur dengan pasta berwarna, mengalihkan perhatiannya, dan menyembunyikan sayur dengan menghaluskannya.', body_ja = 'スープの中のたったひとつの緑の野菜を見つけて、食べるのをやめてしまう？「栄養管理ツール」で、野菜をカラフルなパスタにまぜて気をそらしたり、ピューレにして隠したりする、達人の技を試してみましょう。', body_ko = '수프 속 초록 채소 하나를 발견하고 안 먹겠다고 하나요? 식단 계획에서 채소를 알록달록한 파스타와 섞어 관심을 돌리고, 퓌레로 만들어 숨기는 고수의 방법을 써 보세요.', body_nl = 'Ontdekt hij dat ene groene stukje groente in zijn soep en weigert hij te eten? Pas in het Voedingsplan de slimste manieren toe om groenten met kleurrijke pasta te mengen, de aandacht af te leiden en ze gepureerd te verstoppen.', body_pl = 'Odkrył w zupie ten jeden zielony kawałek warzywa i nie chce jeść? Zastosuj z planu karmienia najsprytniejsze sposoby: mieszaj warzywa z kolorowym makaronem, odwracaj uwagę i ukrywaj je, miksując na purée.', body_pt = 'Descobriu aquele único legume verde na sopa e recusa comer? Aplique as técnicas mais engenhosas do Registo de Alimentação: misture os legumes com massa colorida para distrair a atenção e esconda-os em puré.', body_sv = 'Upptäckte barnet den enda gröna grönsaken i soppan och vägrar äta? Använd matplanens skickligaste sätt att blanda grönsaker med färgglad pasta, avleda uppmärksamheten och gömma dem som mos.', body_vi = 'Bé phát hiện đúng một miếng rau xanh trong bát súp và không chịu ăn? Hãy áp dụng trong Kế hoạch dinh dưỡng những cách khéo léo nhất để trộn rau với mì ống nhiều màu, đánh lạc hướng bé, hoặc xay nhuyễn để giấu đi.', body_zh = '发现汤里有一根绿色蔬菜，就不肯吃了？用上喂养计划里最高明的办法：把蔬菜和彩色意面混在一起转移注意力，或者打成泥藏起来。' WHERE id = 'e8db8e88-207e-4ac3-9421-9b1c49bdfd27' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La condición del gorro de papá 🧢', body_es = 'Para irse a la cama exige que papá se ponga sí o sí el gorro de invierno. Que papá se lo ponga y haga ruidos cómicos. Este absurdo tan raro de la noche os hará reír antes de dormir y romperá su terquedad al instante.', title_fr = 'La condition du bonnet de papa 🧢', body_fr = 'Pour aller au lit, il exige que papa mette son bonnet d''hiver. Que papa le mette et fasse des bruits comiques. Cette absurdité du soir vous fera rire avant le coucher et brisera aussitôt l''entêtement de l''enfant.', title_hi = 'पापा की टोपी वाली शर्त 🧢', body_hi = 'सोने जाने के लिए ज़िद करता है कि पापा सर्दियों की टोपी पहनें। पापा वह टोपी पहनकर मज़ेदार आवाज़ें निकालें। शाम का यह अजीब बेतुकापन सोने से पहले आपको भी हँसाएगा और बच्चे की ज़िद भी तुरंत तोड़ देगा।', title_id = 'Syarat topi Ayah 🧢', body_id = 'Ia menuntut Ayah memakai topi musim dingin sebagai syarat mau tidur. Biarkan Ayah memakai topi itu dan membuat suara-suara lucu. Keanehan absurd malam ini akan membuat kalian tertawa sebelum tidur dan langsung mematahkan sikap keras kepala anak.', title_ja = 'パパの帽子が条件 🧢', body_ja = 'ベッドに行く条件は、パパが冬の帽子をかぶること。パパに帽子をかぶって、おもしろい声を出してもらいましょう。夜のこのおかしな一幕は、寝る前にあなたを笑わせ、子どものがんこさもすぐにほぐしてくれます。', title_ko = '아빠의 모자 조건 🧢', body_ko = '자러 가려면 아빠가 꼭 겨울 모자를 써야 한다고 하나요? 아빠가 모자를 쓰고 웃긴 소리를 내게 하세요. 이 엉뚱한 저녁 풍경이 잠들기 전 엄마도 웃게 하고 아이의 고집도 바로 꺾어 줄 거예요.', title_nl = 'Papa''s mutsvoorwaarde 🧢', body_nl = 'Hij wil alleen naar bed als papa per se een wintermuts opzet. Laat papa die muts opzetten en gekke geluiden maken. Deze rare absurditeit van de avond laat jullie lachen voor het slapen en breekt meteen de koppigheid van je kind.', title_pl = 'Warunek z czapką taty 🧢', body_pl = 'Żeby pójść do łóżka, żąda, by tata założył zimową czapkę. Niech tata ją założy i wydaje śmieszne odgłosy. Ten dziwny wieczorny absurd przed snem rozśmieszy i ciebie, i od razu złamie upór dziecka.', title_pt = 'A condição do gorro do pai 🧢', body_pt = 'Para ir para a cama, exige que o pai ponha um gorro de inverno. Que o pai ponha o gorro e faça sons cómicos. Este absurdo estranho da noite vai fazê-la rir antes de dormir e quebrar logo a teimosia da criança.', title_sv = 'Pappas mössvillkor 🧢', body_sv = 'Barnet kräver att pappa absolut har vintermössa på sig för att det ska gå och lägga sig. Låt pappa sätta på mössan och göra roliga ljud. Kvällens konstiga absurditet får dig att skratta före sömnen och bryter direkt barnets envishet.', title_vi = 'Điều kiện chiếc mũ của bố 🧢', body_vi = 'Bé đòi bố phải đội mũ len mùa đông thì mới chịu đi ngủ. Hãy để bố đội mũ và phát ra những âm thanh hài hước. Sự ngộ nghĩnh kỳ lạ của buổi tối này vừa khiến mẹ bật cười trước giờ ngủ, vừa lập tức hóa giải sự bướng bỉnh của bé.', title_zh = '爸爸的帽子条件 🧢', body_zh = '非要爸爸戴上冬天的帽子才肯上床。让爸爸戴上那顶帽子，发出搞笑的声音吧。晚上这份奇妙的荒诞，既能在睡前把你逗笑，也能一下子打破宝宝的倔强。' WHERE id = '417acfcf-4492-4093-aa86-48285ecc470a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una terquedad que desafía a la física 💧', body_es = '¿Llora a lágrima viva diciendo «quiero el agua seca»? Pidiendo cosas imposibles, el cerebro infantil en realidad pone a prueba tu voluntad. No busques lógica: distrae su atención al instante con otro objeto de colores.', title_fr = 'Un entêtement qui défie la physique 💧', body_fr = 'Il pleure à chaudes larmes en disant « je veux de l''eau sèche » ? En exigeant l''impossible, le cerveau de l''enfant teste en réalité votre volonté. Ne cherchez pas de logique, détournez simplement et aussitôt son attention avec un autre objet coloré.', title_hi = 'भौतिकी को चुनौती देती ज़िद 💧', body_hi = '‘मुझे सूखा पानी चाहिए’ कहकर फूट-फूटकर रोता है? बच्चे का दिमाग नामुमकिन चीज़ें माँगकर असल में आपकी इच्छाशक्ति परखता है। यहाँ तर्क मत ढूँढिए, बस किसी और रंगीन चीज़ से उसका ध्यान तुरंत बँटाइए।', title_id = 'Keras kepala yang menantang fisika 💧', body_id = 'Ia menangis tersedu-sedu sambil berkata ''Aku mau air yang kering''? Dengan menuntut hal yang mustahil, otak anak sebenarnya sedang menguji kemauan Anda. Jangan mencari logika, cukup segera alihkan perhatiannya dengan benda lain yang berwarna-warni.', title_ja = '物理に挑戦するがんこさ 💧', body_ja = '「かわいたお水がほしい」と大泣き？子どもの脳は、ありえないことを求めることで、実はあなたの意志を確かめているんです。そこに理屈を求めず、別のカラフルなもので、すぐに気をそらしてあげましょう。', title_ko = '물리 법칙에 도전하는 고집 💧', body_ko = '''마른 물 줘''라며 엉엉 우나요? 아이의 뇌는 불가능한 걸 요구하며 사실 엄마의 의지를 시험하는 거예요. 논리를 찾지 말고 다른 알록달록한 물건으로 바로 관심을 돌려 주세요.', title_nl = 'Koppigheid die de natuurkunde uitdaagt 💧', body_nl = 'Huilt hij tranen met tuiten omdat hij ''droog water'' wil? Door het onmogelijke te eisen, test een kinderbrein eigenlijk jouw wil. Zoek er geen logica achter, maar leid zijn aandacht meteen af met een ander kleurrijk voorwerp.', title_pl = 'Upór na przekór fizyce 💧', body_pl = 'Płacze w głos, bo chce „suchej wody”? Domagając się rzeczy niemożliwych, dziecięcy mózg tak naprawdę sprawdza twoją wolę. Nie szukaj w tym logiki, po prostu od razu odwróć jego uwagę innym kolorowym przedmiotem.', title_pt = 'A teimosia que desafia a física 💧', body_pt = 'Chora desalmadamente a dizer "quero a água seca"? Ao exigir coisas impossíveis, o cérebro da criança está, na verdade, a testar a sua vontade. Não procure lógica: desvie logo a atenção dele com outro objeto colorido.', title_sv = 'Envishet som utmanar fysiken 💧', body_sv = 'Gråter barnet hejdlöst och säger ”jag vill ha torrt vatten”? Genom att kräva det omöjliga testar barnets hjärna egentligen din vilja. Leta inte efter logik, avled bara genast uppmärksamheten med en annan färgglad sak.', title_vi = 'Sự bướng bỉnh thách thức vật lý 💧', body_vi = 'Bé khóc nức nở đòi "nước khô"? Khi đòi những điều không thể, não bộ trẻ thật ra đang thử ý chí của mẹ. Đừng tìm logic ở đây, chỉ cần lập tức chuyển sự chú ý của bé sang một món đồ nhiều màu sắc khác.', title_zh = '挑战物理的倔强 💧', body_zh = '哭着喊着“我要干的水”？孩子的大脑通过要求不可能的事，其实是在试探你的意志。别在这里找逻辑，马上用另一样彩色的东西转移宝宝的注意力。' WHERE id = '7516076d-1a63-4620-b73e-63a31b706bac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio dentro del armario 🚪', body_es = 'De repente se ha hecho el silencio en casa y le has encontrado escondido dentro del armario jugando solo. Está buscando su espacio personal. No le saques enseguida: él también quiere alejarse del ruido, estar solo y descansar la mente.', title_fr = 'Le silence dans le placard 🚪', body_fr = 'Un silence soudain s''est installé dans la maison, et vous l''avez trouvé caché dans le placard en train de jouer tout seul. C''est une recherche d''espace personnel. Ne l''en sortez pas tout de suite, lui aussi veut s''éloigner du bruit, être seul et reposer son cerveau.', title_hi = 'अलमारी के अंदर की खामोशी 🚪', body_hi = 'घर में अचानक खामोशी छा गई और आपने उसे अलमारी के अंदर छिपकर अकेले खेलते पाया। यह निजी जगह की तलाश है। उसे तुरंत वहाँ से मत निकालिए, वह भी शोर से दूर अकेले रहकर दिमाग को आराम देना चाहता है।', title_id = 'Hening di dalam lemari 🚪', body_id = 'Tiba-tiba rumah hening, dan Anda menemukannya bersembunyi di dalam lemari sambil bermain sendiri. Ini pencarian ruang pribadi. Jangan langsung mengeluarkannya, ia juga ingin menjauh dari kebisingan, menyendiri, dan mengistirahatkan otaknya.', title_ja = 'クローゼットの中の静けさ 🚪', body_ja = '家の中が急に静かになって、見るとクローゼットに隠れてひとりで遊んでいた。これは自分だけの空間さがしです。すぐに引っぱり出さないで。この子も騒がしさから離れてひとりになり、頭を休めたいんです。', title_ko = '옷장 속 고요 🚪', body_ko = '집에 갑자기 정적이 흐르고, 옷장 안에 숨어 혼자 놀고 있는 아이를 발견했나요? 개인 공간을 찾는 중이에요. 바로 꺼내지 마세요, 아이도 소음에서 벗어나 혼자서 머리를 쉬게 하고 싶은 거예요.', title_nl = 'Stilte in de kast 🚪', body_nl = 'Ineens was het stil in huis en vond je hem verstopt in de kast, in zijn eentje spelend. Hij zoekt een eigen plekje. Haal hem er niet meteen uit, ook hij wil even weg van het lawaai, alleen zijn en zijn hoofd laten rusten.', title_pl = 'Cisza w szafie 🚪', body_pl = 'W domu nagle zapadła cisza, a ty znalazłaś go schowanego w szafie, gdzie bawił się sam. To szukanie przestrzeni osobistej. Nie wyciągaj go stamtąd od razu, on też chce uciec od hałasu, pobyć sam i dać odpocząć głowie.', title_pt = 'O silêncio dentro do armário 🚪', body_pt = 'De repente fez-se silêncio em casa e encontrou-o escondido dentro do armário a brincar sozinho. É a procura de espaço pessoal. Não o tire de lá logo: ele também quer afastar-se do barulho, ficar sozinho e descansar a cabeça.', title_sv = 'Tystnaden i garderoben 🚪', body_sv = 'Plötsligt blev det tyst hemma och du hittade barnet gömt i garderoben, lekande för sig själv. Det är ett sökande efter eget utrymme. Ta inte genast ut barnet därifrån, det vill också komma bort från oväsendet, vara ensamt och låta hjärnan vila.', title_vi = 'Sự im lặng trong tủ quần áo 🚪', body_vi = 'Căn nhà bỗng im ắng, và mẹ thấy bé đang trốn trong tủ quần áo, một mình chơi đùa. Đó là bé đang tìm không gian riêng. Đừng lôi bé ra ngay, bé cũng muốn tránh xa tiếng ồn, ở một mình và cho não bộ nghỉ ngơi.', title_zh = '衣柜里的安静 🚪', body_zh = '家里突然安静下来，你发现宝宝躲在衣柜里自己玩。这是在寻找私人空间。别马上把宝宝拉出来，宝宝也想远离喧闹，一个人待会儿，让大脑休息一下。' WHERE id = 'b726a724-b8d0-4de2-92f7-30636fde8d1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enfado silencioso 😤', body_es = 'Cuando no consigue lo que quiere, en lugar de llorar se cruza de brazos, mira a la pared y se enfurruña contigo. Es un nuevo escalón muy importante en la gestión emocional. No le presiones: a los 3 minutos volverá riendo como si nada.', title_fr = 'La colère silencieuse 😤', body_fr = 'Quand il n''obtient pas ce qu''il veut, au lieu de pleurer, il croise les bras, regarde le mur et vous boude. C''est une nouvelle étape très importante de la gestion des émotions. N''insistez pas, 3 minutes plus tard il reviendra en riant comme si de rien n''était.', title_hi = 'खामोश गुस्सा 😤', body_hi = 'मन का न होने पर रोने के बजाय हाथ बाँधकर, दीवार की ओर देखकर आपसे रूठ जाता है। यह भावनाएँ सँभालने की नई और बहुत अहम सीढ़ी है। उसके पीछे मत पड़िए, 3 मिनट बाद वह ऐसे हँसते हुए लौटेगा जैसे कुछ हुआ ही न हो।', title_id = 'Marah tanpa suara 😤', body_id = 'Saat keinginannya tak terpenuhi, alih-alih menangis, ia menyilangkan tangan, menghadap dinding, dan merajuk pada Anda. Ini tahap baru yang sangat penting dalam mengelola emosi. Jangan mendesaknya, 3 menit kemudian ia akan kembali sambil tertawa seolah tak terjadi apa-apa.', title_ja = '静かな怒り 😤', body_ja = '思いどおりにならないと、泣く代わりに腕を組んで壁のほうを向き、すねてしまう。これは気持ちをコントロールする、新しくてとても大切なステップです。追いつめないで。3分後には、何もなかったように笑って戻ってきます。', title_ko = '소리 없는 분노 😤', body_ko = '원하는 대로 안 되면 우는 대신 팔짱을 끼고 벽을 보며 삐지나요? 감정 조절의 새롭고 아주 중요한 단계예요. 다그치지 마세요, 3분 뒤면 아무 일 없었다는 듯 웃으며 돌아올 거예요.', title_nl = 'Stille woede 😤', body_nl = 'Als hij zijn zin niet krijgt, gaat hij niet huilen, maar slaat hij zijn armen over elkaar, kijkt naar de muur en is hij boos op je. Dit is een nieuwe en heel belangrijke stap in het reguleren van emoties. Dring niet aan, na 3 minuten komt hij lachend terug alsof er niets gebeurd is.', title_pl = 'Cicha złość 😤', body_pl = 'Gdy nie dostaje tego, czego chce, zamiast płakać, krzyżuje ręce, odwraca się do ściany i się obraża. To nowy, bardzo ważny etap w panowaniu nad emocjami. Nie naciskaj, za 3 minuty wróci z uśmiechem, jakby nic się nie stało.', title_pt = 'Fúria silenciosa 😤', body_pt = 'Quando não consegue o que quer, em vez de chorar cruza os braços, vira-se para a parede e fica amuado consigo. É uma fase nova e muito importante da gestão emocional. Não insista: 3 minutos depois volta a rir como se nada fosse.', title_sv = 'Tyst ilska 😤', body_sv = 'När barnet inte får som det vill, istället för att gråta korsar det armarna, tittar in i väggen och tjurar mot dig. Det är ett nytt och väldigt viktigt steg i känsloregleringen. Gå inte på, efter 3 minuter kommer barnet tillbaka skrattande som om inget hänt.', title_vi = 'Cơn giận im lặng 😤', body_vi = 'Khi không được như ý, thay vì khóc, bé khoanh tay, quay mặt vào tường và giận dỗi mẹ. Đây là nấc thang mới và rất quan trọng trong việc kiểm soát cảm xúc. Đừng dồn ép, 3 phút sau bé sẽ cười và quay lại như chưa có gì xảy ra.', title_zh = '无声的怒气 😤', body_zh = '没如愿时，不再哭闹，而是双臂抱胸、对着墙生你的气。这是情绪管理一个新的、非常重要的阶段。别追着宝宝不放，3分钟后宝宝就会像什么都没发生过一样笑着回来。' WHERE id = '4b514d29-e0d8-49a4-850f-900d0c46bffa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El ruido de casa te hace pitar los oídos. Cuando por fin se duerma, activa el Medidor de sonido. Mirar esos números cercanos a cero de la pantalla, ese silencio digital, es el mejor masaje visual para el cerebro de una madre cansada.', body_fr = 'Le bruit de la maison vous fait bourdonner les oreilles. Quand il s''endort enfin, activez le Sonomètre. Regarder ces chiffres proches de zéro à l''écran, ce silence numérique, c''est le plus beau massage visuel pour le cerveau d''une maman fatiguée.', body_hi = 'घर के शोर से कान झनझना रहे हैं। जब वह आखिरकार सो जाए, तो साउंड मीटर टूल चालू कीजिए। स्क्रीन पर शून्य के करीब के अंक, वह डिजिटल खामोशी देखना थकी माँ के दिमाग के लिए सबसे प्यारी विज़ुअल मसाज है।', body_id = 'Kebisingan di rumah membuat telinga Anda berdenging. Saat akhirnya ia tertidur, aktifkan Pengukur Suara. Melihat angka mendekati nol di layar, keheningan digital itu, adalah pijatan visual terindah untuk otak ibu yang lelah.', body_ja = '家の中の騒がしさで耳鳴りがしそう。やっと寝てくれたら、「サウンドメーター」をオンにしましょう。画面のゼロに近い数字、デジタルな静けさを眺めることが、疲れたママの脳にはいちばんの視覚マッサージになります。', body_ko = '집 안의 소음에 귀가 울리나요? 아이가 드디어 잠들면 소음 측정기를 켜 보세요. 화면 속 0에 가까운 숫자, 그 디지털 고요를 보는 것이 지친 엄마의 머리에 가장 좋은 시각 마사지예요.', body_nl = 'Het lawaai in huis laat je oren suizen. Zet de Geluidsmeter aan als hij eindelijk slaapt. Kijken naar die getallen bij nul op het scherm, die digitale stilte, is de fijnste visuele massage voor het brein van een vermoeide mama.', body_pl = 'Hałas w domu dzwoni ci w uszach. Gdy w końcu zaśnie, włącz Miernik dźwięku. Patrzenie na liczby bliskie zera na ekranie, na tę cyfrową ciszę, to najpiękniejszy wizualny masaż dla mózgu zmęczonej mamy.', body_pt = 'O barulho da casa faz-lhe zumbir os ouvidos. Quando ele finalmente adormecer, ative o Medidor de Som. Ver os números perto de zero no ecrã, o silêncio digital, é a melhor massagem visual para o cérebro de uma mãe cansada.', body_sv = 'Oljudet hemma får det att ringa i öronen. När barnet äntligen har somnat, aktivera verktyget Ljudmätare. Att se siffrorna nära noll på skärmen, den digitala tystnaden, är den skönaste visuella massagen för en trött mammas hjärna.', body_vi = 'Tiếng ồn trong nhà làm tai mẹ ù đi. Khi bé cuối cùng cũng ngủ, hãy bật Đo âm thanh. Nhìn những con số gần về không trên màn hình, sự im lặng hiện ra bằng con số ấy chính là màn mát-xa thị giác tuyệt vời nhất cho não bộ của người mẹ mệt mỏi.', body_zh = '家里的噪音让你耳朵嗡嗡作响。宝宝终于睡着后，打开分贝仪。看着屏幕上那些接近零的数字，看着这份数字化的安静，对疲惫的妈妈来说就是最美好的视觉按摩。' WHERE id = '4b721431-3565-4047-8fb3-144c9d3a8f8b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo un nuevo idioma 🗣️', body_es = 'Ha descubierto palabras compuestas y raras inventadas por él, como «vuela-corre» o «calienti-frío». Su vocabulario crece una barbaridad. Guarda sin falta estas palabras tan cómicas en el Seguimiento del desarrollo como un archivo inolvidable.', title_fr = 'La découverte d''une nouvelle langue 🗣️', body_fr = 'Il a inventé des mots composés étranges, comme « vole-court » ou « chaud-froid ». Son vocabulaire s''enrichit de façon spectaculaire. Notez absolument ces mots comiques dans le Suivi de développement comme des archives inoubliables.', title_hi = 'नई भाषा की खोज 🗣️', body_hi = 'उसने ‘उड़ता-दौड़ता’, ‘गरम-ठंडा’ जैसे अपने गढ़े पेचीदा और अजीब शब्द खोज लिए हैं। उसकी शब्दावली गज़ब की रफ़्तार से बढ़ रही है। ग्रोथ ट्रैकर में उसके इन गढ़े मज़ेदार शब्दों को एक अविस्मरणीय याद की तरह ज़रूर दर्ज कीजिए।', title_id = 'Penemuan bahasa baru 🗣️', body_id = 'Ia menemukan kata-kata rumit dan aneh karangannya sendiri, seperti ''terbang-lari'' atau ''panas-dingin''. Kosakatanya berkembang luar biasa pesat. Pastikan mencatat kata-kata lucu karangannya ini di Pelacak Perkembangan sebagai arsip yang tak terlupakan.', title_ja = '新しい言葉の発見 🗣️', body_ja = '「とぶはしる」「あつつめたい」のような、自分で考えたふくざつでへんてこな言葉を発見しています。語彙がものすごい勢いで増えていますね。このおかしな造語を、忘れられない記録として「発達トラッカー」にぜひ残しましょう。', title_ko = '새로운 언어의 발견 🗣️', body_ko = '''날아뛰기'', ''뜨거차갑다''처럼 자기가 지어낸 복잡하고 이상한 단어를 발견했나요? 어휘가 엄청나게 늘고 있어요. 성장 기록에 이 웃긴 신조어들을 잊지 못할 기록으로 꼭 남겨 두세요.', title_nl = 'Een nieuwe taal ontdekken 🗣️', body_nl = 'Hij heeft eigen ingewikkelde en rare woorden bedacht, zoals ''vliegrennen'' of ''warmkoud''. Zijn woordenschat groeit razendsnel. Leg deze grappige verzonnen woordjes zeker vast in de Groeitracker, als onvergetelijk archief.', title_pl = 'Odkrywanie nowego języka 🗣️', body_pl = 'Odkrył złożone i dziwne słowa własnego pomysłu, takie jak „latobieg” czy „ciepłozimno”. Jego słownictwo rośnie w zawrotnym tempie. Koniecznie zapisz te zabawne wymyślone słówka w Śledzeniu rozwoju jako niezapomnianą pamiątkę.', title_pt = 'A descoberta de uma nova língua 🗣️', body_pt = 'Descobriu palavras compostas e estranhas, inventadas por ele, como "voa-corre" ou "quente-frio". O vocabulário está a crescer de forma impressionante. Não deixe de registar estas palavras cómicas no Registo de Crescimento, como um arquivo inesquecível.', title_sv = 'Upptäckten av ett nytt språk 🗣️', body_sv = 'Barnet har upptäckt egna påhittade, avancerade och konstiga ord som ”flygspringa” och ”varmkall”. Ordförrådet växer otroligt mycket. Anteckna absolut de roliga påhittade orden i Utvecklingsspåraren som ett oförglömligt arkiv.', title_vi = 'Khám phá ngôn ngữ mới 🗣️', body_vi = 'Bé đã "phát minh" ra những từ ghép phức tạp và kỳ lạ như "bay-chạy", "nóng-lạnh". Vốn từ của bé mở rộng với tốc độ chóng mặt. Hãy nhớ ghi lại những từ ngộ nghĩnh tự chế này trong Theo dõi phát triển như một kỷ niệm khó quên.', title_zh = '发现新语言 🗣️', body_zh = '发明了“飞跑跑”“热冷冷”这种复杂又奇怪的自创词。词汇量正在惊人地扩展。一定要在发育追踪里把这些自创的搞笑词语记下来，作为难忘的存档。' WHERE id = '6fcf10ba-99bd-4b23-bbff-0487161fbfe4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un compañero de viaje curioso 🥄', body_es = 'Para ir al parque insiste en llevarse no sus coches, sino un cucharón que ha encontrado en la cocina. ¡No se lo impidas! Hoy ese cucharón será su juguete más original, pero más práctico, para cavar en la arena del parque.', title_fr = 'Un drôle de compagnon de route 🥄', body_fr = 'En allant au parc, il insiste pour emporter non pas ses voitures, mais une louche trouvée dans la cuisine. Ne l''en empêchez pas ! Aujourd''hui, au parc, cette louche sera son jouet le plus insolite, mais le plus pratique pour creuser le sable.', title_hi = 'अजीब हमसफ़र 🥄', body_hi = 'पार्क जाते समय अपनी गाड़ियाँ नहीं, रसोई से मिली एक कलछी साथ ले जाने की ज़िद करता है। मत रोकिए! वह कलछी आज पार्क में रेत खोदने के लिए उसका सबसे अनोखा, पर सबसे काम का खिलौना होगी।', title_id = 'Teman jalan yang aneh 🥄', body_id = 'Saat pergi ke taman, ia bersikeras membawa sendok sayur dari dapur, bukan mobil-mobilannya. Jangan halangi! Sendok sayur itu akan menjadi mainan paling tidak biasa sekaligus paling fungsional untuk menggali pasir di taman hari ini.', title_ja = 'へんてこな旅のおとも 🥄', body_ja = '公園へ行くのに、車のおもちゃではなく、キッチンで見つけたおたまを持っていくと言ってきかない。じゃましないで！今日の公園では、そのおたまが砂を掘るための、いちばん変わっているけれどいちばん役に立つおもちゃになります。', title_ko = '엉뚱한 길동무 🥄', body_ko = '공원에 갈 때 자동차 장난감 대신 부엌에서 찾은 국자를 꼭 가져가겠다고 하나요? 막지 마세요! 그 국자가 오늘 공원에서 모래를 파는 가장 특이하지만 가장 쓸모 있는 장난감이 될 거예요.', title_nl = 'Een rare reisgenoot 🥄', body_nl = 'Op weg naar het park wil hij niet zijn autootjes meenemen, maar per se een soeplepel uit de keuken. Houd hem niet tegen! Die soeplepel wordt vandaag in het park zijn meest ongewone, maar handigste speelgoed om in het zand te graven.', title_pl = 'Dziwny towarzysz podróży 🥄', body_pl = 'Idąc do parku, upiera się, żeby zabrać nie samochodziki, tylko chochlę znalezioną w kuchni. Nie przeszkadzaj! Ta chochla będzie dziś w parku jego najbardziej niezwykłą, ale najbardziej praktyczną zabawką do kopania w piasku.', title_pt = 'Um companheiro de viagem estranho 🥄', body_pt = 'A caminho do parque, em vez dos carrinhos, insiste em levar uma concha que encontrou na cozinha. Não o impeça! Hoje, no parque, essa concha vai ser o brinquedo mais invulgar, mas mais funcional, para escavar na areia.', title_sv = 'En konstig reskamrat 🥄', body_sv = 'På väg till parken insisterar barnet på att ta med en slev från köket istället för sina bilar. Stoppa inte! Sleven blir i dag barnets mest ovanliga men mest funktionella leksak för att gräva i sanden i parken.', title_vi = 'Người bạn đồng hành kỳ lạ 🥄', body_vi = 'Đi công viên, bé không mang ô tô đồ chơi mà nhất quyết mang theo chiếc muôi tìm thấy trong bếp. Đừng ngăn cản! Chiếc muôi đó hôm nay sẽ là món đồ chơi khác thường nhất nhưng hữu dụng nhất để bé đào cát ở công viên.', title_zh = '奇怪的旅伴 🥄', body_zh = '去公园时，不带小汽车，非要带上从厨房找到的一把汤勺。别阻止！今天那把汤勺会是宝宝在公园挖沙子最特别、也最实用的玩具。' WHERE id = '2c413ba6-81fc-4861-95ac-e87a4f29055d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los gatos le temen al agua 🐈', body_es = 'Para no meterse en la bañera dice: «Soy un gato y los gatos no se bañan». Acepta su papel y sigue el juego: «¿Y si este gato quiere jugar con las pompas de jabón?». Engánchale y supera las prohibiciones con imaginación.', title_fr = 'Les chats ont peur de l''eau 🐈', body_fr = 'Pour ne pas aller dans le bain, il dit : « Je suis un chat, les chats ne se lavent pas. » Acceptez son rôle et continuez le jeu : « Et si ce chat voulait jouer avec les bulles de savon ? » Dépassez les interdits grâce à l''imagination.', title_hi = 'बिल्लियाँ पानी से डरती हैं 🐈', body_hi = 'बाथटब में न जाने के लिए कहता है, ‘मैं बिल्ली हूँ, बिल्लियाँ नहीं नहातीं।’ उसकी भूमिका मानकर खेल आगे बढ़ाइए: ‘पर क्या यह बिल्ली साबुन के बुलबुलों से खेलना चाहती है?’ कहकर उसे लुभाइए, पाबंदियों को कल्पना से पार कीजिए।', title_id = 'Kucing takut air 🐈', body_id = 'Agar tidak masuk bak mandi, ia berkata ''Aku kucing, kucing tidak mandi''. Terima perannya dan lanjutkan permainannya: ''Tapi apakah kucing ini mau main busa sabun?''. Tarik minatnya dan atasi larangan dengan kekuatan imajinasi.', title_ja = 'ねこはお水が苦手 🐈', body_ja = 'お風呂に入らないために「わたしはねこ、ねこはお風呂に入らないの」と言う。役を受け入れて遊びを続けましょう：「じゃあ、このねこさんは石けんの泡で遊びたいかな？」と誘って、禁止は想像力で乗りこえて。', title_ko = '고양이는 물을 무서워해 🐈', body_ko = '목욕하지 않으려고 ''나는 고양이야, 고양이는 목욕 안 해''라고 하나요? 역할을 받아들이고 놀이를 이어 가세요: ''그럼 이 고양이는 비눗방울 놀이 하고 싶을까?'' 상상력으로 거부를 넘어서세요.', title_nl = 'Katten zijn bang voor water 🐈', body_nl = 'Om niet in bad te hoeven, zegt hij: ''Ik ben een kat, katten gaan niet in bad.'' Neem zijn rol aan en speel mee: ''Maar wil dit katje misschien met zeepbellen spelen?'' Zo trek je hem over de streep en overwin je verboden met fantasie.', title_pl = 'Koty boją się wody 🐈', body_pl = 'Żeby nie wejść do wanny, mówi: „Jestem kotem, koty się nie kąpią”. Przyjmij jego rolę i ciągnij zabawę: „A czy ten kotek chce pobawić się bańkami mydlanymi?”. Pokonuj zakazy siłą wyobraźni.', title_pt = 'Os gatos têm medo da água 🐈', body_pt = 'Para não entrar na banheira, diz "Sou um gato, os gatos não tomam banho". Aceite o papel e continue o jogo: "E este gato não quer brincar com bolas de sabão?". Cative-o e supere as proibições com imaginação.', title_sv = 'Katter är rädda för vatten 🐈', body_sv = 'För att slippa badet säger barnet: ”Jag är en katt, katter badar inte.” Acceptera rollen och fortsätt leken: säg ”Men den här katten kanske vill leka med såpbubblor?”, locka barnet och övervinn förbuden med fantasi.', title_vi = 'Mèo sợ nước 🐈', body_vi = 'Để khỏi phải vào bồn tắm, bé nói: "Con là mèo, mèo không tắm đâu". Hãy nhận vai và tiếp tục trò chơi: "Thế chú mèo này có muốn chơi với bong bóng xà phòng không?", lôi cuốn bé và vượt qua lệnh cấm bằng trí tưởng tượng.', title_zh = '猫咪怕水 🐈', body_zh = '为了不进浴缸，说“我是小猫，小猫不洗澡”。接受这个角色，把游戏继续下去：“那这只小猫想不想玩肥皂泡泡呀？”用想象力绕过禁令，把宝宝吸引过来。' WHERE id = 'b865240d-5ee4-4c57-917c-6139d1ce4039' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Negociación profesional 🛒', body_es = 'En el súper, en lugar de llorar por un caramelo, negocia: «Si lo compramos, me como la sopa». ¡Enhorabuena, tu pequeño abogado está creciendo! Para no olvidar nada, ten abierta la Lista de la compra y que no se te vaya la cabeza mientras discutes con él.', title_fr = 'Négociation de pro 🛒', body_fr = 'Au supermarché, au lieu de pleurer pour des bonbons, il négocie : « Si on achète ça, je mangerai ma soupe. » Félicitations, votre petit avocat grandit ! Contre les oublis, gardez la Liste de courses ouverte, pour ne pas perdre le fil pendant que vous débattez avec lui.', title_hi = 'पेशेवर मोलभाव 🛒', body_hi = 'बाज़ार में टॉफ़ी के लिए रोने के बजाय मोलभाव करता है, ‘यह ले लें, तो मैं अपना सूप खा लूँगा।’ बधाई हो, आपका नन्हा वकील बड़ा हो रहा है! भूलने से बचने के लिए शॉपिंग लिस्ट खुली रखिए, ताकि उससे बहस में आपका ध्यान न भटके।', title_id = 'Tawar-menawar profesional 🛒', body_id = 'Di supermarket, alih-alih menangis minta permen, ia menawar: ''Kalau kita beli ini, aku makan supku''. Selamat, pengacara kecil Anda sedang tumbuh! Untuk melawan lupa, biarkan Daftar Belanja tetap terbuka agar pikiran Anda tidak teralihkan saat berdebat dengannya.', title_ja = 'プロの交渉術 🛒', body_ja = 'スーパーでお菓子をねだって泣く代わりに「これ買ってくれたら、スープ食べるよ」と交渉してくる。おめでとうございます、小さな弁護士さんが育っています！買い忘れ防止に「買い物リスト」を開いておけば、交渉中も気がそれません。', title_ko = '프로 협상가 🛒', body_ko = '마트에서 사탕 사 달라고 우는 대신 ''이거 사 주면 수프 먹을게''라며 흥정하나요? 축하해요, 꼬마 변호사가 자라고 있어요! 아이와 협상하다 깜빡하지 않도록 쇼핑 목록은 열어 두세요.', title_nl = 'Professioneel onderhandelen 🛒', body_nl = 'In plaats van te huilen om snoep in de supermarkt, onderhandelt hij: ''Als we dit kopen, eet ik mijn soep op.'' Gefeliciteerd, je kleine advocaat wordt groot! Houd tegen vergeetachtigheid het Boodschappenlijstje open, zodat je niet afgeleid raakt terwijl je met hem discussieert.', title_pl = 'Zawodowe targowanie się 🛒', body_pl = 'Zamiast płakać w sklepie o cukierki, targuje się: „Jak to kupimy, zjem zupę”. Gratulacje, twój mały adwokat rośnie! A na zapominalstwo trzymaj otwartą Listę zakupów, żeby nie stracić wątku podczas negocjacji.', title_pt = 'Negociação profissional 🛒', body_pt = 'No supermercado, em vez de chorar por um rebuçado, negoceia: "Se comprarmos isto, como a sopa". Parabéns, o seu pequeno advogado está a crescer! Contra os esquecimentos, mantenha a Lista de Compras aberta para não se distrair enquanto discute com ele.', title_sv = 'Professionell förhandling 🛒', body_sv = 'Istället för att gråta efter godis i butiken förhandlar barnet: ”Om vi köper det här äter jag upp min soppa.” Grattis, din lilla advokat växer! Ha Inköpslistan öppen mot glömskan, så att du inte tappar tråden medan ni diskuterar.', title_vi = 'Mặc cả chuyên nghiệp 🛒', body_vi = 'Ở siêu thị, thay vì khóc đòi kẹo, bé lại mặc cả: "Nếu mua cái này, con sẽ ăn hết súp". Chúc mừng, "luật sư" nhí của mẹ đang lớn! Để khỏi quên đồ, hãy mở sẵn Danh sách mua sắm, để không bị phân tâm khi đang tranh luận với bé.', title_zh = '专业谈判 🛒', body_zh = '在超市里不再为糖果哭闹，而是讨价还价：“买了这个，我就喝汤。”恭喜，你家的小律师在长大！为了对付健忘，让购物清单一直开着，和宝宝讨价还价时也不会分心。' WHERE id = 'f573b98e-335c-4b92-b5f7-06c122ba5b12' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Mírame!» 👀', body_es = 'Salta del sofá y, haciendo el mismo movimiento exactamente 50 veces, espera tu aprobación. Aparta los ojos del móvil. No salta por el movimiento, sino solo por ese brillo de aprobación lleno de amor en tus ojos.', title_fr = 'La période du « Regarde-moi ! » 👀', body_fr = 'Il saute du canapé et refait exactement le même geste 50 fois en attendant votre approbation. Quittez le téléphone des yeux. Il ne saute pas pour le geste, mais pour cette lueur d''approbation pleine d''amour dans vos yeux.', title_hi = '‘मुझे देखो!’ का दौर 👀', body_hi = 'सोफ़े से कूदता है और हर बार पूरे 50 बार वही हरकत करके शाबाशी का इंतज़ार करता है। फ़ोन से नज़र हटाइए। वह हरकत के लिए नहीं, बस आपकी आँखों में प्यार भरी शाबाशी की उस चमक के लिए कूदता है।', title_id = 'Masa ''Lihat aku!'' 👀', body_id = 'Ia melompat dari sofa, mengulang gerakan yang sama tepat 50 kali, dan menunggu pengakuan. Alihkan mata dari ponsel. Ia melompat bukan demi gerakannya, tapi demi kilau pengakuan penuh cinta di mata Anda.', title_ja = '「見て！」の時期 👀', body_ja = 'ソファからジャンプして、同じ動きをちょうど50回くり返すたびに、認めてもらうのを待っている。スマホから目を離して。動きそのもののためではなく、あなたの目に浮かぶ愛情たっぷりの「すごいね」の輝きのために跳んでいるんです。', title_ko = '''나 좀 봐!'' 시기 👀', body_ko = '소파에서 뛰어내리며 똑같은 동작을 50번이나 하고 엄마의 인정을 기다리나요? 휴대폰에서 눈을 떼세요. 동작 때문이 아니라 엄마 눈 속 사랑 가득한 인정의 반짝임을 위해 뛰는 거예요.', title_nl = 'De ''Kijk naar mij!''-fase 👀', body_nl = 'Hij springt van de bank, doet precies 50 keer hetzelfde en wacht elke keer op je goedkeuring. Kijk weg van je telefoon. Hij springt niet om het springen, maar alleen voor die liefdevolle glinstering van goedkeuring in jouw ogen.', title_pl = 'Etap „Patrz na mnie!” 👀', body_pl = 'Skacze z kanapy, powtarza ten sam ruch równo 50 razy i za każdym razem czeka na uznanie. Oderwij wzrok od telefonu. Nie skacze dla samego ruchu, tylko dla tego pełnego miłości błysku uznania w twoich oczach.', title_pt = 'A fase do "Olha para mim!" 👀', body_pt = 'Salta do sofá e, de cada vez, repete o mesmo movimento exatamente 50 vezes à espera de aprovação. Tire os olhos do telemóvel. Ele não salta pelo movimento, salta só por aquele brilho de aprovação cheio de amor nos seus olhos.', title_sv = 'Perioden ”Titta på mig!” 👀', body_sv = 'Barnet hoppar från soffan och gör samma sak precis 50 gånger och väntar på bekräftelse. Ta blicken från telefonen. Barnet hoppar inte för rörelsens skull, utan bara för den kärleksfulla bekräftelsen som glittrar i dina ögon.', title_vi = 'Giai đoạn "Mẹ nhìn này!" 👀', body_vi = 'Bé nhảy từ sofa xuống, lặp lại đúng một động tác tới 50 lần và chờ mẹ công nhận. Hãy rời mắt khỏi điện thoại. Bé nhảy không phải vì động tác, mà chỉ vì ánh mắt công nhận lấp lánh đầy yêu thương của mẹ.', title_zh = '“看我！”时期 👀', body_zh = '从沙发上跳下来，同一个动作做满50遍，等着你的肯定。把目光从手机上移开。宝宝跳，不是为了动作本身，只是为了你眼中那一闪而过、满含爱意的肯定。' WHERE id = '605e9c74-a673-4f1f-9b27-383f6a4810eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un confidente silencioso 📝', body_es = '¿Nadie te entiende y te cansas tanto en casa? Deja a un lado las sonrisas forzadas. Escribe en el Diario de ánimo lo agotada que estás de verdad hoy. Cada palabra que vuelques en la pantalla te quitará un peso de encima.', title_fr = 'Un confident silencieux 📝', body_fr = 'Personne ne vous comprend et vous êtes si fatiguée à la maison ? Laissez de côté les sourires forcés. Écrivez dans le Journal d''humeur à quel point vous êtes vraiment épuisée aujourd''hui. Chaque mot posé à l''écran vous enlèvera un poids des épaules.', title_hi = 'खामोश राज़दार 📝', body_hi = 'कोई आपको नहीं समझता और आप घर में इतना थक जाती हैं? बनावटी मुस्कानें एक तरफ़ रखिए। मूड डायरी में लिखिए कि आज असल में आप कितनी थक चुकी हैं। स्क्रीन पर उतरा हर शब्द आपके कंधों से भारी बोझ उतारेगा।', title_id = 'Teman curhat yang diam 📝', body_id = 'Tak ada yang memahami Anda, dan Anda begitu lelah di rumah? Singkirkan senyum yang dipaksakan. Tuliskan di Buku Harian Suasana Hati betapa sebenarnya Anda kehabisan tenaga hari ini. Setiap kata yang tertuang ke layar akan mengangkat beban berat dari pundak Anda.', title_ja = '静かな打ち明け相手 📝', body_ja = '誰もわかってくれないし、家でこんなに疲れている？作り笑いは脇に置いて。「気分日記」に、今日本当はどれほど疲れきったかを書きましょう。画面に書いた言葉のひとつひとつが、肩の重荷をおろしてくれます。', title_ko = '말없는 비밀 친구 📝', body_ko = '아무도 나를 이해하지 못하고 집에서 이렇게나 지치나요? 억지 미소는 내려놓으세요. 기분 일기에 오늘 사실 얼마나 지쳤는지 적어 보세요. 화면에 쏟아낸 한 마디 한 마디가 어깨의 무거운 짐을 덜어 줄 거예요.', title_nl = 'Een stille vertrouweling 📝', body_nl = 'Begrijpt niemand je en ben je thuis zo moe? Zet die geforceerde glimlach even opzij. Schrijf in je Stemmingsdagboek hoe uitgeput je je vandaag echt voelt. Elk woord op het scherm haalt een zware last van je schouders.', title_pl = 'Cichy powiernik 📝', body_pl = 'Nikt cię nie rozumie, a w domu tak bardzo się męczysz? Odłóż wymuszone uśmiechy. Zapisz w Dzienniku nastroju, jak bardzo jesteś dziś naprawdę wyczerpana. Każde słowo wylane na ekran zdejmie ci z ramion ciężar.', title_pt = 'Um confidente silencioso 📝', body_pt = 'Ninguém a compreende e cansa-se tanto em casa? Ponha de lado os sorrisos forçados. Escreva no Diário de Humor como hoje ficou realmente esgotada. Cada palavra no ecrã vai tirar-lhe um peso dos ombros.', title_sv = 'Den tysta förtrogna 📝', body_sv = 'Förstår ingen dig, och är du så trött hemma? Lägg undan de överdrivna leendena. Skriv i Humördagboken hur slut du egentligen var i dag. Varje ord på skärmen lyfter en tung börda från dina axlar.', title_vi = 'Người bạn tâm giao lặng lẽ 📝', body_vi = 'Không ai hiểu mẹ, và ở nhà mẹ mệt đến thế? Hãy gác lại những nụ cười gượng gạo. Viết vào Nhật ký tâm trạng xem hôm nay mẹ thật sự đã kiệt sức thế nào. Mỗi chữ trút lên màn hình sẽ nhấc đi một gánh nặng trên vai mẹ.', title_zh = '无声的知心朋友 📝', body_zh = '没人理解你，在家里累成这样？把勉强挤出的笑容放到一边。在心情日记里写下今天你其实有多么精疲力竭。倾倒在屏幕上的每一个字，都会从你肩上卸下一份重担。' WHERE id = '61cf1118-2d1d-4e42-9dac-f7a6ca616e71' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormido en el suelo 🥱', body_es = 'Se resistió a la siesta, pero se ha quedado dormido acurrucado sobre la alfombra, en medio de sus juguetes. No le lleves a la cama para no despertarle: deja que disfrute de esa inocencia en medio de la habitación y descansa tú también 1 hora.', title_fr = 'Sieste par terre 🥱', body_fr = 'Il a refusé la sieste et résisté, mais s''est endormi roulé en boule sur le tapis au milieu de ses jouets. Ne le portez pas au lit au risque de le réveiller, laissez-le savourer cette innocence au milieu de la pièce, et reposez-vous 1 heure, vous aussi.', title_hi = 'फ़र्श पर नींद 🥱', body_hi = 'दिन की नींद से इनकार करके अड़ गया, पर खिलौनों के बीच कालीन पर सिमटकर सो गया। उसे उठाकर बिस्तर पर ले जाकर जगाइए मत, कमरे के बीच उस मासूमियत को बने रहने दीजिए, और आप भी 1 घंटा आराम कीजिए।', title_id = 'Tidur di lantai 🥱', body_id = 'Ia menolak tidur siang dan melawan, tapi akhirnya meringkuk dan tertidur di atas karpet di tengah mainannya. Jangan memindahkannya ke tempat tidur dan membangunkannya, biarkan ia menikmati kepolosan itu di tengah kamar, dan Anda pun beristirahat 1 jam.', title_ja = '床でおやすみ 🥱', body_ja = 'お昼寝をいやがってがんばっていたのに、おもちゃのまんなか、じゅうたんの上で丸くなって眠ってしまった。ベッドに運んで起こさないで。部屋のまんなかで、そのあどけなさを味わわせてあげて、あなたも1時間休みましょう。', title_ko = '바닥에서 낮잠 🥱', body_ko = '낮잠을 거부하며 버티더니 장난감 한가운데, 카펫 위에서 몸을 웅크리고 잠들었나요? 침대로 옮기다 깨우지 마세요. 방 한가운데서 그 순수함을 누리게 두고, 엄마도 1시간 쉬세요.', title_nl = 'Slapen op de vloer 🥱', body_nl = 'Hij weigerde zijn middagslaapje en verzette zich, maar viel daarna opgekruld tussen zijn speelgoed op het tapijt in slaap. Draag hem niet naar bed om hem niet wakker te maken. Laat hem midden in de kamer van die onschuld genieten en rust jij ook een uurtje.', title_pl = 'Sen na podłodze 🥱', body_pl = 'Opierał się drzemce, ale zwinął się w kłębek i zasnął na dywanie między zabawkami. Nie przenoś go do łóżka, żeby go nie obudzić, niech na środku pokoju śpi tym niewinnym snem, a ty też odpocznij przez godzinę.', title_pt = 'Sono no chão 🥱', body_pt = 'Recusou a sesta e resistiu, mas adormeceu enroscado no tapete, no meio dos brinquedos. Não o leve para a cama nem o acorde: deixe-o saborear aquela inocência no meio do quarto e descanse também 1 hora.', title_sv = 'Sömn på golvet 🥱', body_sv = 'Barnet vägrade tuppluren och kämpade emot, men somnade ihopkrupet på mattan mitt bland leksakerna. Bär inte till sängen och väck inte barnet, låt det njuta av den oskyldiga stunden mitt i rummet, och vila du också i 1 timme.', title_vi = 'Giấc ngủ trên sàn nhà 🥱', body_vi = 'Bé phản kháng, không chịu ngủ trưa, nhưng rồi lại cuộn tròn ngủ thiếp đi giữa đống đồ chơi trên thảm. Đừng bế bé lên giường làm bé thức giấc, hãy để bé tận hưởng sự hồn nhiên ấy giữa phòng, còn mẹ cũng nghỉ ngơi 1 tiếng.', title_zh = '睡在地板上 🥱', body_zh = '不肯午睡，倔着不睡，结果在玩具堆中间、地毯上蜷成一团睡着了。别把宝宝抱到床上弄醒，就让宝宝在房间中间享受这份天真吧，你也休息1个小时。' WHERE id = 'a2f88e5e-134a-4514-9134-a36d1a155887' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le da miedo la oscuridad? 👻', body_es = 'Cerca de los 3,5 años el miedo a la oscuridad aparece a menudo. Pon una pequeña lamparita de noche en la habitación y crea historias de héroes valientes en Cuentos inteligentes.', title_fr = 'Il a peur du noir ? 👻', body_fr = 'À l''approche des 3 ans et demi, la peur du noir apparaît souvent. Mettez une petite veilleuse dans la chambre et créez des histoires de héros courageux dans les Contes intelligents.', title_hi = 'अँधेरे से डरता है? 👻', body_hi = 'साढ़े 3 साल के करीब अँधेरे का डर अक्सर उभरता है। कमरे में एक छोटी नाइट लैंप रखिए और स्मार्ट कहानियों में बहादुर हीरो की कहानियाँ बनाइए।', title_id = 'Takut gelap? 👻', body_id = 'Menjelang usia 3,5 tahun, rasa takut gelap sering muncul. Letakkan lampu tidur kecil di kamar dan ciptakan kisah pahlawan pemberani di Dongeng Pintar.', title_ja = '暗やみが怖い？ 👻', body_ja = '3歳半が近づくと、暗やみを怖がることがよくあります。部屋に小さなナイトライトを置いて、「スマートおはなし」で勇敢なヒーローのお話をつくりましょう。', title_ko = '어둠이 무서워요? 👻', body_ko = '세 살 반 무렵이면 어둠에 대한 두려움이 자주 고개를 들어요. 방에 작은 수면등을 두고 스마트 동화로 용감한 주인공 이야기를 만들어 보세요.', title_nl = 'Bang in het donker? 👻', body_nl = 'Rond 3,5 jaar steekt angst voor het donker vaak de kop op. Zet een klein nachtlampje in de kamer en maak in Slimme sprookjes verhalen over dappere helden.', title_pl = 'Boi się ciemności? 👻', body_pl = 'W okolicach 3,5 roku często pojawia się lęk przed ciemnością. Postaw w pokoju małą lampkę nocną i twórz w Mądrych bajkach historie o odważnych bohaterach.', title_pt = 'Tem medo do escuro? 👻', body_pt = 'Perto dos 3 anos e meio, o medo do escuro aparece muitas vezes. Ponha no quarto uma pequena luz de presença e crie nas Histórias Inteligentes histórias de heróis corajosos.', title_sv = 'Mörkrädd? 👻', body_sv = 'Närmare 3,5 år dyker mörkrädsla ofta upp. Ställ en liten nattlampa i rummet och skapa berättelser om modiga hjältar i Smarta sagor.', title_vi = 'Bé sợ bóng tối? 👻', body_vi = 'Gần 3,5 tuổi, nỗi sợ bóng tối thường xuất hiện. Hãy đặt một chiếc đèn ngủ nhỏ trong phòng và tạo những câu chuyện về người hùng dũng cảm trong Truyện cổ tích thông minh.', title_zh = '怕黑吗？👻', body_zh = '快3岁半时，怕黑的情况常常冒出来。在房间里放一盏小夜灯，在智慧童话里编一些勇敢英雄的故事吧。' WHERE id = '52a1e30d-f365-493c-8480-78b508714eb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla entre mamás 💬', body_es = '¿Te agota pensar «por qué mi hijo todavía no se ha acostumbrado del todo al orinal»? Entra en la Comunidad Anacan y verás que cada niño tiene su propio ritmo.', title_fr = 'Entre mamans 💬', body_fr = 'La question « Pourquoi mon enfant n''est-il pas encore tout à fait propre ? » vous épuise ? Rejoignez la Communauté Anacan, vous verrez que chaque enfant a son propre rythme.', title_hi = 'माँओं की बातचीत 💬', body_hi = '‘मेरा बच्चा अब तक पॉटी की पूरी आदत क्यों नहीं डाल पाया?’ वाला ख्याल आपको थका रहा है? Anacan कम्युनिटी में जाइए, आप देखेंगी कि हर बच्चे की रफ़्तार अलग होती है।', title_id = 'Obrolan para ibu 💬', body_id = 'Pikiran ''Kenapa anakku belum juga lancar memakai pispot?'' membuat Anda lelah? Masuklah ke Komunitas Anacan, Anda akan melihat bahwa setiap anak punya tempo yang berbeda.', title_ja = 'ママたちのおしゃべり 💬', body_ja = '「どうしてうちの子はまだおまるに慣れないの？」という思いに疲れていませんか？Anacanコミュニティを開いてみて。子どもにはそれぞれのペースがあるとわかります。', title_ko = '엄마들의 수다 💬', body_ko = '''우리 아이는 왜 아직 배변 훈련이 안 될까?''라는 생각에 지쳤나요? Anacan 커뮤니티에 들어가 보면 아이마다 속도가 다르다는 걸 알게 될 거예요.', title_nl = 'Mama''s onder elkaar 💬', body_nl = 'Word je moe van de gedachte ''Waarom is mijn kind nog niet helemaal zindelijk?'' Ga naar de Anacan Community, dan zie je dat elk kind zijn eigen tempo heeft.', title_pl = 'Rozmowy mam 💬', body_pl = 'Męczy cię myśl „Dlaczego moje dziecko wciąż nie przyzwyczaiło się w pełni do nocnika?”? Wejdź do Społeczności Anacan, zobaczysz, że każde dziecko ma swoje tempo.', title_pt = 'Conversa de mães 💬', body_pt = 'Cansa-a pensar "porque é que o meu filho ainda não se habituou totalmente ao bacio?"? Entre na Comunidade Anacan: vai ver que cada criança tem o seu ritmo.', title_sv = 'Mammasnack 💬', body_sv = 'Tröttar tanken ”varför har mitt barn fortfarande inte helt vant sig vid pottan?” ut dig? Gå in i Anacan Community, så ser du att varje barn har sin egen takt.', title_vi = 'Chuyện của các mẹ 💬', body_vi = 'Ý nghĩ "Sao con mình vẫn chưa quen hẳn với bô?" khiến mẹ mệt mỏi? Hãy vào Cộng đồng Anacan, mẹ sẽ thấy mỗi trẻ đều có nhịp độ riêng.', title_zh = '妈妈们的聊天 💬', body_zh = '“为什么我的孩子还没完全学会用便盆？”这个念头让你很累？进入Anacan社区，你会看到每个孩子都有自己不同的节奏。' WHERE id = 'cbfa1fac-401d-41c2-974d-c9424b7436ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambia las palabras? 🗣️', body_es = '¿Cambia algunas letras a propósito, hace sonidos cómicos y se ríe? Está descubriendo lo flexible que es el lenguaje. Únete tú también y jugad con las palabras.', title_fr = 'Il déforme les mots ? 🗣️', body_fr = 'Il change certains sons exprès, fait des bruits comiques et en rit ? Il découvre la souplesse de la langue. Joignez-vous à lui et jouez à des jeux de mots.', title_hi = 'शब्द बदलता है? 🗣️', body_hi = 'कुछ अक्षर जानबूझकर बदलकर मज़ेदार आवाज़ें निकालता है और उस पर हँसता है? वह भाषा का लचीलापन खोज रहा है। आप भी उसके साथ शामिल होइए और शब्दों के खेल खेलिए।', title_id = 'Ia memelesetkan kata? 🗣️', body_id = 'Ia sengaja menukar beberapa huruf, membuat bunyi lucu, lalu menertawakannya? Ia sedang menemukan kelenturan bahasa. Ikutlah bersamanya dan mainkan permainan kata.', title_ja = '言葉を入れかえる？ 🗣️', body_ja = 'いくつかの音をわざと入れかえて、へんてこな音を出して笑っている？言葉のやわらかさを発見しているんです。あなたも一緒に、言葉遊びをしましょう。', title_ko = '단어를 바꿔 말하나요? 🗣️', body_ko = '일부러 몇몇 글자를 바꿔 웃긴 소리를 내고 깔깔 웃나요? 언어의 유연함을 발견하는 중이에요. 엄마도 함께 말놀이를 해 보세요.', title_nl = 'Verdraait hij woorden? 🗣️', body_nl = 'Verandert hij expres sommige letters, maakt hij grappige geluiden en lacht hij erom? Hij ontdekt hoe flexibel taal is. Doe mee en speel woordspelletjes.', title_pl = 'Przekręca słowa? 🗣️', body_pl = 'Celowo zmienia niektóre głoski, wydaje śmieszne dźwięki i się z tego śmieje? Odkrywa elastyczność języka. Dołącz do niego i bawcie się w gry słowne.', title_pt = 'Troca as palavras? 🗣️', body_pt = 'Troca algumas letras de propósito, faz sons cómicos e ri-se com isso? Está a descobrir a elasticidade da língua. Junte-se a ele e façam jogos de palavras.', title_sv = 'Byter barnet ut ord? 🗣️', body_sv = 'Byter barnet med flit ut vissa bokstäver, gör roliga ljud och skrattar åt det? Barnet upptäcker språkets smidighet. Häng med och lek ordlekar.', title_vi = 'Bé nói sai từ? 🗣️', body_vi = 'Bé cố tình đổi một số chữ cái, phát ra những âm thanh buồn cười rồi tự cười? Bé đang khám phá sự linh hoạt của ngôn ngữ. Hãy tham gia cùng bé và chơi các trò chơi chữ.', title_zh = '把词说颠倒？🗣️', body_zh = '故意把某些音换掉，发出搞笑的声音，还自己笑起来？宝宝在发现语言的灵活性。你也加入进来，一起玩文字游戏吧。' WHERE id = 'cde5f67f-33e9-4a06-9155-b70a56cb6c73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sentimientos de amistad 👫', body_es = '¿En el parque ya intenta jugar con otros niños (no en paralelo, sino interactuando)? ¡La socialización empieza oficialmente! Observa este momento vigilando desde lejos.', title_fr = 'Les premiers sentiments d''amitié 👫', body_fr = 'Au parc, il essaie désormais de jouer avec les autres enfants (non plus à côté, mais vraiment avec eux) ? La socialisation commence officiellement ! Observez ce moment de loin, en restant prête à intervenir.', title_hi = 'दोस्ती की भावनाएँ 👫', body_hi = 'पार्क में अब दूसरे बच्चों के साथ मिलकर (पास-पास नहीं, आपस में) खेलने की कोशिश करता है? घुलना-मिलना आधिकारिक तौर पर शुरू हो गया! दूर से निगरानी रखते हुए इस पल को देखिए।', title_id = 'Rasa pertemanan 👫', body_id = 'Di taman ia mulai mencoba bermain bersama anak lain (interaktif, bukan paralel)? Sosialisasi resmi dimulai! Saksikan momen ini sambil mengawasi dari jauh.', title_ja = 'お友だちの気持ち 👫', body_ja = '公園で、ほかの子と一緒に（平行ではなく、かかわり合って）遊ぼうとしている？社会性がいよいよスタートです！遠くから見守りつつ、この瞬間を眺めましょう。', title_ko = '친구가 생기는 마음 👫', body_ko = '공원에서 이제 다른 아이들과 (나란히가 아니라 함께) 놀려고 하나요? 사회생활이 공식적으로 시작됐어요! 멀리서 지켜 주며 이 순간을 바라보세요.', title_nl = 'Gevoelens van vriendschap 👫', body_nl = 'Probeert hij in het park al samen met andere kinderen te spelen (niet parallel, maar interactief)? De sociale ontwikkeling begint officieel! Kijk van een afstand toe en zorg dat het veilig is.', title_pl = 'Pierwsze przyjaźnie 👫', body_pl = 'W parku próbuje już bawić się razem z innymi dziećmi (nie obok, tylko wspólnie)? Uspołecznienie oficjalnie się zaczyna! Obserwuj tę chwilę z daleka, gotowa do asekuracji.', title_pt = 'Sentimento de amizade 👫', body_pt = 'No parque já tenta brincar com outras crianças em conjunto (de forma interativa, não paralela)? A socialização começa oficialmente! Observe este momento à distância, por perto para o proteger.', title_sv = 'Känslor av kamratskap 👫', body_sv = 'Försöker barnet nu leka tillsammans med andra barn i parken (interaktivt, inte parallellt)? Den sociala utvecklingen har officiellt börjat! Titta på stunden och var redo att hjälpa på avstånd.', title_vi = 'Tình bạn chớm nở 👫', body_vi = 'Ở công viên, bé đã cố gắng chơi cùng các bạn khác (có tương tác, không chỉ chơi song song)? Kỹ năng xã hội chính thức bắt đầu! Hãy quan sát khoảnh khắc này từ xa và sẵn sàng hỗ trợ.', title_zh = '伙伴的感觉 👫', body_zh = '在公园里开始试着和其他小朋友一起玩（不是平行游戏，而是互动）了？社交正式开始了！在远处守护着，欣赏这一刻吧。' WHERE id = '57748696-ab80-425d-85cf-6283ca454879' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En el caos diario, ¿se ha acabado el champú o las toallitas? No lo guardes en la cabeza: apúntalo enseguida en la Lista de la compra y sincronízala con tu pareja.', body_fr = 'Dans le chaos du quotidien, plus de shampoing ou de lingettes ? Ne gardez pas tout en tête : notez-le tout de suite dans la Liste de courses et synchronisez-la avec votre partenaire.', body_hi = 'रोज़ की भागदौड़ में शैम्पू या वेट वाइप्स खत्म हो गए? दिमाग में मत रखिए, तुरंत शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ सिंक कीजिए।', body_id = 'Di tengah kekacauan harian, sampo atau tisu basah habis? Jangan disimpan di kepala, segera tulis di Daftar Belanja dan sinkronkan dengan pasangan Anda.', body_ja = '毎日のバタバタの中で、シャンプーやおしりふきが切れた？頭で覚えておかずに、すぐに「買い物リスト」に書いて、パートナーと共有しましょう。', body_ko = '정신없는 일상 속에 샴푸나 물티슈가 떨어졌나요? 머릿속에 담아 두지 말고 바로 쇼핑 목록에 적어 배우자와 공유하세요.', body_nl = 'Is in de dagelijkse chaos de shampoo of zijn de billendoekjes op? Hoef je niet te onthouden: zet het meteen op het Boodschappenlijstje en synchroniseer het met je partner.', body_pl = 'W codziennym chaosie skończył się szampon albo nawilżane chusteczki? Nie trzymaj tego w głowie, od razu wpisz na Listę zakupów i zsynchronizuj z partnerem.', body_pt = 'Na correria do dia acabou o champô ou os toalhetes? Não guarde isso na cabeça: escreva logo na Lista de Compras e sincronize com o seu companheiro.', body_sv = 'Tog schampot eller våtservetterna slut i det dagliga kaoset? Försök inte hålla det i huvudet, skriv genast upp det i Inköpslistan och synka med din partner.', body_vi = 'Giữa bộn bề hằng ngày, dầu gội hay khăn ướt đã hết? Đừng cố nhớ trong đầu, hãy ghi ngay vào Danh sách mua sắm và đồng bộ với chồng.', body_zh = '每天忙忙乱乱，洗发水还是湿巾用完了？别记在脑子里，马上写进购物清单，和伴侣同步。' WHERE id = '9fedc843-d647-418d-b31f-ad9bf956e849' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba los decibelios del ambiente con el Medidor de sonido y limita el volumen de la tele de la habitación de al lado.', body_fr = 'La première demi-heure de sommeil est la plus fragile. Vérifiez le niveau de décibels avec le Sonomètre et limitez le volume de la télé dans la pièce d''à côté.', body_hi = 'सोने के बाद पहला आधा घंटा सबसे संवेदनशील समय होता है। साउंड मीटर से माहौल के डेसिबल जाँचिए और बगल के कमरे में टीवी की आवाज़ कम रखिए।', body_id = 'Setengah jam pertama setelah ia tertidur adalah waktu paling sensitif. Periksa tingkat desibel ruangan dengan Pengukur Suara dan batasi volume TV di kamar sebelah.', body_ja = '眠りについてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」でまわりのデシベルを確認し、となりの部屋のテレビの音をおさえましょう。', body_ko = '잠든 뒤 첫 30분이 가장 예민한 시간이에요. 소음 측정기로 주변 데시벨을 확인하고 옆방 TV 소리를 줄여 주세요.', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer met de Geluidsmeter het aantal decibel in de kamer en zet de tv in de kamer ernaast zachter.', body_pl = 'Pierwsze pół godziny po zaśnięciu to najbardziej wrażliwy czas. Sprawdź Miernikiem dźwięku poziom decybeli w otoczeniu i ścisz telewizor w sąsiednim pokoju.', body_pt = 'A primeira meia hora depois de adormecer é a mais sensível. Verifique os decibéis do ambiente com o Medidor de Som e baixe o som da televisão na divisão ao lado.', body_sv = 'Den första halvtimmen efter att barnet somnat är den känsligaste tiden. Kontrollera decibelnivån med Ljudmätaren och sänk ljudet på tv:n i rummet bredvid.', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra decibel trong phòng bằng Đo âm thanh và vặn nhỏ tiếng tivi ở phòng bên.', body_zh = '入睡后的头半个小时是最敏感的时候。用分贝仪查看环境的分贝，把隔壁房间的电视声音调小。' WHERE id = 'ac1c42c5-b375-4935-bfbe-c3b0f8da74a1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El calor de su respiración 💖', body_es = 'Te ha vuelto loca todo el día y se ha empeñado en todo. Pero ahora está acurrucado en tu pecho en la cama y su respiración rítmica llena la habitación. Esa es la mayor recompensa de la maternidad. Abrázale contra tu pecho y olvida todo el cansancio.', title_fr = 'La chaleur de son souffle 💖', body_fr = 'Il vous a rendue folle toute la journée et s''est entêté sur tout. Mais maintenant, il est blotti contre vous dans le lit, et son souffle régulier remplit la chambre. C''est exactement la plus belle récompense de la maternité. Serrez-le contre votre cœur et oubliez toute votre fatigue.', title_hi = 'उसकी साँसों की गर्माहट 💖', body_hi = 'उसने दिनभर आपको परेशान किया, हर बात पर ज़िद की। पर अब बिस्तर में आपके सीने से सटा है, कमरा उसकी लयबद्ध साँसों से भरा है। माँ बनने का सबसे बड़ा इनाम यही है। उसे सीने से लगाइए और सारी थकान भूल जाइए।', title_id = 'Hangatnya napasnya 💖', body_id = 'Seharian ia membuat Anda hampir gila dan membangkang dalam segala hal. Tapi kini ia meringkuk di dada Anda di tempat tidur, dan napasnya yang berirama memenuhi kamar. Inilah hadiah terbesar menjadi ibu. Peluk ia erat dan lupakan semua rasa lelah.', title_ja = '寝息のぬくもり 💖', body_ja = '一日じゅう振りまわされて、何にでも意地をはっていたのに、今はベッドであなたの胸に寄りそい、部屋はリズミカルな寝息に満ちています。これこそママであることのいちばんのごほうび。ぎゅっと抱きしめて、疲れを全部忘れましょう。', title_ko = '따뜻한 숨결 💖', body_ko = '하루 종일 엄마를 미치게 하고 모든 일에 고집을 부렸죠. 그런데 지금은 침대에서 엄마 가슴에 파고들어, 리듬 있는 숨소리로 방을 채우고 있어요. 이게 엄마가 받는 가장 큰 선물이에요. 꼭 안고 모든 피로를 잊으세요.', title_nl = 'De warmte van zijn adem 💖', body_nl = 'Hij heeft je de hele dag gek gemaakt en was overal koppig in. Maar nu ligt hij in bed tegen je borst gekropen en vult zijn ritmische adem de kamer. Dit is de grootste beloning van het moederschap. Druk hem tegen je aan en vergeet alle vermoeidheid.', title_pl = 'Ciepło jego oddechu 💖', body_pl = 'Cały dzień doprowadzał cię do szału i się upierał. Ale teraz w łóżku przytulił się do twojej piersi, a pokój wypełnia jego miarowy oddech. To właśnie największa nagroda macierzyństwa. Przytul go mocno i zapomnij o całym zmęczeniu.', title_pt = 'O calor da respiração dele 💖', body_pt = 'Passou o dia todo a deixá-la louca e a teimar com tudo. Mas agora está na cama aninhado no seu peito e a respiração ritmada dele enche o quarto. É exatamente esta a maior recompensa da maternidade. Aperte-o contra o peito e esqueça todo o cansaço.', title_sv = 'Värmen i andetaget 💖', body_sv = 'Barnet har gjort dig galen hela dagen och varit envist med allt. Men nu ligger det tryckt mot ditt bröst i sängen och rummet fylls av barnets rytmiska andetag. Det är moderskapets största belöning. Tryck barnet mot bröstet och glöm all trötthet.', title_vi = 'Hơi thở ấm áp 💖', body_vi = 'Cả ngày bé làm mẹ phát điên, bướng bỉnh với mọi thứ. Nhưng giờ bé đang rúc vào ngực mẹ trên giường, hơi thở đều đặn của bé lấp đầy căn phòng. Đó chính là phần thưởng lớn nhất của việc làm mẹ. Hãy ôm chặt bé vào lòng và quên đi mọi mệt mỏi.', title_zh = '呼吸的温度 💖', body_zh = '宝宝把你折腾了一整天，什么都要犟。可现在在床上依偎在你胸前，房间里满是宝宝有节奏的呼吸声。这正是当妈妈最大的奖赏。把宝宝搂在怀里，忘掉所有的疲惫吧。' WHERE id = '2e15df12-458b-434c-ac05-d42b6b0a04b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El orgullo de los zapatos al revés 👟', body_es = 'Se ha puesto los zapatos al revés, pero camina tan orgulloso como si hubiera conquistado el mundo. No intervengas para arreglarlo. Su autoestima y su independencia importan un millón de veces más que lo estética que se vea la ropa.', title_fr = 'La fierté des chaussures inversées 👟', body_fr = 'Il a mis ses chaussures au mauvais pied, mais il marche si fièrement qu''on dirait qu''il a conquis le monde. N''intervenez pas pour corriger. La confiance en soi et l''indépendance de l''enfant comptent mille fois plus qu''une tenue esthétique.', title_hi = 'उलटे जूतों का गर्व 👟', body_hi = 'जूते उलटे पहन लिए, पर इतने गर्व से चल रहा है जैसे दुनिया जीत ली हो। बीच में आकर ठीक करने की कोशिश मत कीजिए। बच्चे का आत्मविश्वास और आत्मनिर्भरता कपड़ों के सुंदर दिखने से लाखों गुना ज़्यादा ज़रूरी है।', title_id = 'Bangga dengan sepatu terbalik 👟', body_id = 'Ia memakai sepatu terbalik, tapi berjalan dengan begitu bangga seolah baru menaklukkan dunia. Jangan campur tangan dan mencoba membetulkannya. Rasa percaya diri dan kemandirian anak jutaan kali lebih penting daripada penampilan pakaian yang estetis.', title_ja = '左右反対の靴の誇り 👟', body_ja = '靴を左右反対にはいているのに、世界を征服したかのように誇らしげに歩いています。手を出して直そうとしないで。子どもの自信と自立心は、見た目のよさより何百万倍も大切です。', title_ko = '거꾸로 신은 신발의 자부심 👟', body_ko = '신발을 좌우 바꿔 신고도 세상을 정복한 듯 당당하게 걷나요? 끼어들어 고치려 하지 마세요. 아이의 자신감과 독립심이 옷차림이 예쁘게 보이는 것보다 백만 배 중요해요.', title_nl = 'Trots op verkeerde schoenen 👟', body_nl = 'Hij heeft zijn schoenen aan de verkeerde voeten, maar loopt zo trots alsof hij de wereld heeft veroverd. Grijp niet in en probeer het niet te verbeteren. Het zelfvertrouwen en de zelfstandigheid van je kind zijn een miljoen keer belangrijker dan hoe zijn kleren eruitzien.', title_pl = 'Duma z butów na odwrót 👟', body_pl = 'Założył buty na odwrót, ale chodzi tak dumny, jakby podbił świat. Nie wtrącaj się i nie próbuj tego poprawiać. Pewność siebie i samodzielność dziecka są milion razy ważniejsze niż estetyczny wygląd stroju.', title_pt = 'O orgulho dos sapatos trocados 👟', body_pt = 'Calçou os sapatos trocados, mas anda tão orgulhoso como se tivesse conquistado o mundo. Não intervenha para os trocar. A autoestima e a independência da criança são um milhão de vezes mais importantes do que a aparência da roupa.', title_sv = 'Stolt med skorna på fel fot 👟', body_sv = 'Barnet har tagit skorna på fel fötter men går så stolt omkring som om det erövrat världen. Försök inte lägga dig i och rätta till. Barnets självförtroende och självständighet är en miljon gånger viktigare än att kläderna ser snygga ut.', title_vi = 'Tự hào đi giày ngược 👟', body_vi = 'Bé đi ngược giày nhưng bước đi kiêu hãnh như vừa chinh phục cả thế giới. Đừng can thiệp hay cố sửa lại. Sự tự tin và tự lập của bé quan trọng hơn gấp triệu lần so với vẻ ngoài của bộ đồ.', title_zh = '穿反鞋的骄傲 👟', body_zh = '鞋穿反了，却走得那么骄傲，好像征服了全世界。别插手去纠正。孩子的自信和独立，比衣服穿得好不好看重要一百万倍。' WHERE id = 'b9503491-2c22-4639-94ac-cc1a79aea888' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La cima de la empatía 🩹', body_es = '¿Le pone una tirita a su osito de peluche porque le duele el brazo y le da un beso? Admira su corazón tan grande y compasivo. Anota con orgullo esta empatía tan profunda en el Seguimiento del desarrollo como el rasgo más bonito de su carácter.', title_fr = 'Le sommet de l''empathie 🩹', body_fr = 'Il colle un pansement sur le bras de son nounours qui « a mal » et lui fait un bisou ? Émerveillez-vous devant ce grand cœur plein de compassion. Notez fièrement ce sentiment d''empathie profond dans le Suivi de développement comme le plus beau trait de caractère.', title_hi = 'सहानुभूति का शिखर 🩹', body_hi = 'टेडी बियर की बाँह में दर्द है, इसलिए उस पर बैंडेज लगाकर चूमता है? उसके इस बड़े, दयालु दिल पर फ़िदा हो जाइए। इस गहरी सहानुभूति को ग्रोथ ट्रैकर में उसके स्वभाव की सबसे प्यारी खूबी के रूप में गर्व से दर्ज कीजिए।', title_id = 'Puncak empati 🩹', body_id = 'Ia menempelkan plester ke lengan beruang mainannya karena ''sakit'', lalu menciumnya? Kagumilah hatinya yang besar dan penuh kasih ini. Catat rasa empati yang dalam ini dengan bangga di Pelacak Perkembangan sebagai salah satu ciri karakter terindahnya.', title_ja = '思いやりのピーク 🩹', body_ja = 'くまさんの腕が痛いからと絆創膏を貼って、キスしてあげている？この大きくてやさしい心に感動しますね。この深い思いやりを、いちばんすてきな性格の一面として「発達トラッカー」に誇らしく記録しましょう。', title_ko = '공감의 정점 🩹', body_ko = '곰 인형 팔이 아프다며 반창고를 붙이고 뽀뽀해 주나요? 이 크고 다정한 마음에 감탄해 주세요. 이 깊은 공감 능력을 가장 아름다운 성격으로 성장 기록에 뿌듯하게 남겨 두세요.', title_nl = 'Het toppunt van empathie 🩹', body_nl = 'Plakt hij een pleister op de arm van zijn beer omdat die pijn heeft, en geeft hij er een kus op? Wees verrukt over zijn grote, meelevende hart. Noteer dit diepe gevoel van empathie trots in de Groeitracker als zijn mooiste karaktertrek.', title_pl = 'Szczyt empatii 🩹', body_pl = 'Przykleja plasterek na łapkę misia, bo go boli, i całuje? Zachwyć się jego wielkim, współczującym sercem. Zapisz z dumą tę głęboką empatię w Śledzeniu rozwoju jako najpiękniejszą cechę charakteru.', title_pt = 'O auge da empatia 🩹', body_pt = 'Põe um penso no braço do ursinho porque lhe dói e dá-lhe um beijo? Admire este coração grande e compassivo. Registe com orgulho este sentimento profundo de empatia no Registo de Crescimento, como o traço de caráter mais bonito.', title_sv = 'Empatins topp 🩹', body_sv = 'Sätter barnet ett plåster på nallen för att armen gör ont och pussar den? Beundra barnets stora, barmhärtiga hjärta. Anteckna stolt den djupa empatin i Utvecklingsspåraren som ett av de vackraste karaktärsdragen.', title_vi = 'Đỉnh cao của sự đồng cảm 🩹', body_vi = 'Bé dán băng cá nhân và hôn lên tay chú gấu bông vì "tay gấu bị đau"? Hãy ngưỡng mộ trái tim lớn lao, giàu lòng trắc ẩn của bé. Hãy tự hào ghi lại sự đồng cảm sâu sắc này như một nét tính cách đẹp nhất trong Theo dõi phát triển.', title_zh = '共情的巅峰 🩹', body_zh = '因为玩具熊的胳膊“疼”，就给它贴上创可贴再亲一下？为宝宝这颗博大又善良的心而惊叹吧。骄傲地把这份深深的共情，作为最美好的性格特点记在发育追踪里。' WHERE id = 'cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te ha acabado la paciencia? Cierra la puerta de la habitación y deja al peque a solas con su padre. Que esta noche él sea el único jefe de los juegos de casa, y tú descansa.', body_fr = 'Votre patience est à bout ? Fermez la porte de la pièce et laissez l''enfant seul avec son papa. Que ce soir, ce soit lui le seul chef des jeux de la maison, et vous, reposez-vous.', body_hi = 'धैर्य जवाब दे रहा है? कमरे का दरवाज़ा बंद कीजिए और बच्चे को पापा के साथ अकेला छोड़िए। आज शाम घर के खेलों के इकलौते मुखिया वही हों, आप आराम कीजिए।', body_id = 'Kesabaran Anda menipis? Tutup pintu kamar dan biarkan anak berdua saja dengan ayahnya. Biarkan malam ini ia menjadi satu-satunya pemimpin permainan di rumah, kamu beristirahatlah.', body_ja = 'もうがまんの限界？部屋のドアを閉めて、子どもはパパとふたりきりに。今夜は家の遊びのリーダーをパパにまかせて、あなたは休んで。', body_ko = '인내심이 바닥났나요? 방문을 닫고 아이를 아빠와 단둘이 두세요. 오늘 저녁 집 안 놀이의 대장은 아빠에게 맡기고 엄마는 쉬세요.', body_nl = 'Raakt je geduld op? Doe de deur van de kamer dicht en laat je kind alleen met zijn papa. Laat hem vanavond de enige baas over de spelletjes in huis zijn, en rust jij uit.', body_pl = 'Kończy ci się cierpliwość? Zamknij drzwi pokoju i zostaw dziecko samo z tatą. Niech dziś wieczorem to on będzie jedynym szefem zabaw w domu, a ty odpocznij.', body_pt = 'Está a perder a paciência? Feche a porta do quarto e deixe a criança sozinha com o pai. Esta noite, que seja ele o único chefe das brincadeiras em casa, e a mãe descansa.', body_sv = 'Har tålamodet tagit slut? Stäng dörren till rummet och lämna barnet ensamt med pappa. Låt honom vara ensam ledare för lekarna hemma i kväll, och vila du.', body_vi = 'Mẹ hết kiên nhẫn rồi? Hãy đóng cửa phòng lại và để bé ở với bố. Tối nay để bố làm "thủ lĩnh" duy nhất của mọi trò chơi trong nhà, còn mẹ nghỉ ngơi.', body_zh = '快没耐心了？关上房门，让宝宝和爸爸单独待着。今晚就让爸爸当家里所有游戏的唯一领导，你好好休息。' WHERE id = '1f4d8560-3286-4e95-8474-fcafd793fada' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mira lo que hago! 🤸‍♂️', body_es = '¿Intenta mantenerse a la pata coja o saltar para llamar tu atención? Quiere que le aprueben. Anota este equilibrio físico en el Seguimiento del desarrollo y aplaúdele.', title_fr = 'Regarde ce que je fais ! 🤸‍♂️', body_fr = 'Il essaie de tenir sur un pied ou de sauter pour attirer votre attention ? Il veut être approuvé. Notez cet équilibre physique dans le Suivi de développement et applaudissez-le.', title_hi = 'देखो, मैं क्या कर रहा हूँ! 🤸‍♂️', body_hi = 'एक पैर पर खड़े होने या कूदने की कोशिश करके आपका ध्यान खींचता है? उसे शाबाशी चाहिए। इस शारीरिक संतुलन को ग्रोथ ट्रैकर में दर्ज कीजिए और उसके लिए तालियाँ बजाइए।', title_id = 'Lihat, aku sedang apa! 🤸‍♂️', body_id = 'Ia mencoba berdiri dengan satu kaki atau melompat untuk menarik perhatian Anda? Ia ingin diakui. Catat keseimbangan fisik ini di Pelacak Perkembangan dan bertepuk tanganlah untuknya.', title_ja = '見て、こんなことできるよ！ 🤸‍♂️', body_ja = '片足で立ったりジャンプしたりして、あなたの注意をひこうとしている？認めてほしいんです。この体のバランスを「発達トラッカー」に記録して、拍手を送りましょう。', title_ko = '봐, 나 이거 한다! 🤸‍♂️', body_ko = '한 발로 서거나 뛰면서 엄마의 관심을 끌려 하나요? 인정받고 싶은 거예요. 이 몸의 균형을 성장 기록에 남기고 박수를 보내 주세요.', title_nl = 'Kijk wat ik doe! 🤸‍♂️', body_nl = 'Probeert hij op één been te staan of te springen om je aandacht te trekken? Hij wil bevestiging. Noteer dit lichamelijke evenwicht in de Groeitracker en applaudisseer voor hem.', title_pl = 'Patrz, co robię! 🤸‍♂️', body_pl = 'Próbuje stać na jednej nodze albo skakać i przyciąga twoją uwagę? Chce uznania. Zapisz tę równowagę w Śledzeniu rozwoju i bij mu brawo.', title_pt = 'Olha o que eu faço! 🤸‍♂️', body_pt = 'Tenta equilibrar-se num pé ou saltar para chamar a sua atenção? Quer ser aprovado. Registe este equilíbrio físico no Registo de Crescimento e aplauda-o.', title_sv = 'Titta vad jag gör! 🤸‍♂️', body_sv = 'Försöker barnet stå på ett ben eller hoppa för att fånga din uppmärksamhet? Barnet vill bli bekräftat. Anteckna den fysiska balansen i Utvecklingsspåraren och applådera.', title_vi = 'Nhìn con làm gì này! 🤸‍♂️', body_vi = 'Bé cố đứng một chân hoặc nhảy để thu hút sự chú ý của mẹ? Bé muốn được công nhận. Hãy ghi lại khả năng giữ thăng bằng này trong Theo dõi phát triển và vỗ tay cổ vũ bé.', title_zh = '看，我在干什么！🤸‍♂️', body_zh = '想单脚站立或者跳起来，好吸引你的注意？宝宝想得到肯定。把这份身体平衡能力记在发育追踪里，为宝宝鼓掌吧。' WHERE id = 'af913905-7dd6-4f3e-bf26-424dee34a1c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra de las verduras 🥦', body_es = '¿Aparta las verduras verdes del plato? No luches. Busca en Recetas saludables trucos astutos para esconder las verduras dentro de magdalenas o albóndigas.', title_fr = 'La guerre des légumes 🥦', body_fr = 'Il pousse les légumes verts sur le bord de l''assiette ? Ne luttez pas. Trouvez dans les Recettes saines des astuces pour cacher les légumes dans des muffins ou des boulettes.', title_hi = 'सब्ज़ियों की जंग 🥦', body_hi = 'प्लेट की हरी सब्ज़ियाँ एक तरफ़ सरका देता है? लड़ाई मत कीजिए। सेहतमंद रेसिपी में सब्ज़ियों को मफ़िन या कटलेट में छिपाने के चालाक तरीके ढूँढिए।', title_id = 'Perang sayur 🥦', body_id = 'Ia mendorong sayur hijau di piringnya ke pinggir? Jangan melawan. Temukan cara cerdik di Resep Sehat untuk menyembunyikan sayur di dalam muffin atau perkedel.', title_ja = '野菜バトル 🥦', body_ja = 'お皿の緑の野菜を脇に押しやっている？戦わないで。「ヘルシーレシピ」から、野菜をマフィンやハンバーグの中に隠す工夫を見つけましょう。', title_ko = '채소 전쟁 🥦', body_ko = '접시 위 초록 채소를 옆으로 밀어내나요? 싸우지 마세요. 건강한 레시피에서 채소를 머핀이나 동그랑땡 속에 숨기는 기발한 방법을 찾아보세요.', title_nl = 'Groenteoorlog 🥦', body_nl = 'Schuift hij de groene groenten op zijn bord aan de kant? Ga de strijd niet aan. Zoek in Gezonde recepten slimme manieren om groenten in muffins of gehaktballetjes te verstoppen.', title_pl = 'Warzywne wojny 🥦', body_pl = 'Odsuwa zielone warzywa na brzeg talerza? Nie walcz. Znajdź w Zdrowych przepisach sprytne sposoby na ukrycie warzyw w babeczkach albo kotlecikach.', title_pt = 'Batalhas de legumes 🥦', body_pt = 'Empurra os legumes verdes do prato para o lado? Não lute. Encontre nas Receitas Saudáveis truques engenhosos para esconder os legumes dentro de queques ou croquetes.', title_sv = 'Grönsakskrig 🥦', body_sv = 'Skjuter barnet de gröna grönsakerna på tallriken åt sidan? Börja inte bråka. Hitta listiga sätt bland Hälsosamma recept att gömma grönsakerna i muffins eller biffar.', title_vi = 'Cuộc chiến rau củ 🥦', body_vi = 'Bé đẩy rau xanh ra mép đĩa? Đừng giằng co. Hãy tìm trong Công thức lành mạnh những cách khéo léo để giấu rau vào bánh nướng xốp hoặc thịt viên.', title_zh = '蔬菜大战 🥦', body_zh = '把盘子里的绿色蔬菜推到一边？别较劲。去健康食谱里找找把蔬菜藏进蛋糕或肉饼里的小妙招。' WHERE id = 'cd8e0cdd-1b7c-42e3-856f-3b4914ee1697' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arte sobre el cuerpo 🖍️', body_es = 'Sospechaste del silencio repentino y le encontraste pintándose una obra de arte en los brazos con rotuladores. No te enfades. Su motricidad fina está haciendo descubrimientos y la piel se lava con agua. Respira hondo y graba este momento tan cómico.', title_fr = 'L''art sur le corps 🖍️', body_fr = 'Ce silence soudain vous a paru suspect, et vous l''avez trouvé en train de se dessiner une œuvre d''art au feutre sur les bras. Ne vous énervez pas. Sa motricité fine fait des découvertes, et la peau se lave à l''eau de toute façon. Respirez profondément et immortalisez ce moment comique.', title_hi = 'शरीर पर कला 🖍️', body_hi = 'अचानक छाई खामोशी पर शक हुआ और आपने उसे अपनी बाहों पर मार्कर से कलाकृति बनाते पाया। नाराज़ मत होइए। उसकी बारीक मोटर स्किल्स खोज कर रही हैं, और त्वचा तो पानी से धुल ही जाती है। गहरी साँस लीजिए और इस मज़ेदार पल को कैमरे में कैद कीजिए।', title_id = 'Seni di tubuh 🖍️', body_id = 'Anda curiga dengan keheningan yang tiba-tiba, lalu menemukannya sedang menggambar karya seni di lengannya dengan spidol. Jangan kesal. Motorik halusnya sedang bereksplorasi, dan kulit toh bisa dicuci dengan air. Tarik napas dalam dan abadikan momen lucu ini.', title_ja = '体の上のアート 🖍️', body_ja = '急な静けさをあやしんで見に行くと、腕にマーカーで作品を描いていた。怒らないで。指先の力が発見を重ねています。肌はどうせ水で洗えば落ちます。深呼吸して、このおかしな瞬間を写真に残しましょう。', title_ko = '몸 위의 예술 🖍️', body_ko = '갑작스러운 고요가 수상해서 가 보니 팔에 사인펜으로 작품을 그리고 있었나요? 화내지 마세요. 소근육이 탐험 중이고, 피부는 어차피 물로 씻겨요. 깊게 숨 쉬고 이 웃긴 순간을 담아 두세요.', title_nl = 'Kunst op het lichaam 🖍️', body_nl = 'Die plotselinge stilte maakte je achterdochtig en je vond hem terwijl hij met stiften een kunstwerk op zijn armen tekende. Word niet boos. Zijn fijne motoriek doet ontdekkingen, en huid is toch met water af te wassen. Haal diep adem en leg dit grappige moment vast.', title_pl = 'Sztuka na ciele 🖍️', body_pl = 'Nagła cisza wydała ci się podejrzana i znalazłaś go, gdy flamastrem malował na rękach dzieło sztuki. Nie denerwuj się. Motoryka mała dokonuje odkryć, a skórę i tak zmyje woda. Weź głęboki oddech i uwiecznij tę zabawną chwilę.', title_pt = 'Arte no corpo 🖍️', body_pt = 'Desconfiou do silêncio repentino e encontrou-o a desenhar uma obra de arte nos braços com marcadores. Não se irrite. A motricidade fina está a fazer descobertas e a pele lava-se com água. Respire fundo e registe este momento cómico.', title_sv = 'Konst på kroppen 🖍️', body_sv = 'Du blev misstänksam mot den plötsliga tystnaden och hittade barnet målande ett konstverk med tusch på armarna. Bli inte arg. Finmotoriken gör upptäckter, och huden tvättas ju ren med vatten. Andas djupt och fånga den roliga stunden på bild.', title_vi = 'Nghệ thuật trên cơ thể 🖍️', body_vi = 'Sự im lặng bất chợt khiến mẹ nghi ngờ, và mẹ thấy bé đang dùng bút dạ vẽ "tác phẩm nghệ thuật" lên cánh tay. Đừng bực mình. Kỹ năng vận động tinh của bé đang khám phá, còn da thì rửa bằng nước là sạch. Hãy hít thở sâu và ghi lại khoảnh khắc hài hước này.', title_zh = '身上的艺术 🖍️', body_zh = '突然的安静让你起了疑心，结果发现宝宝正用水彩笔在自己胳膊上创作艺术品。别生气。宝宝的精细动作在探索，皮肤用水一洗就干净了。深吸一口气，把这个搞笑的时刻拍下来吧。' WHERE id = '465bfed4-fe0b-4cbe-96cc-61ab753a7ff8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hipnosis del susurro 🤫', body_es = 'Está tan activo en la cama que no se duerme. En lugar de levantar la voz, baja de golpe el tono. Háblale solo en susurros. Cuando el niño se concentra para oírte, su cerebro pasa automáticamente al modo sueño.', title_fr = 'L''hypnose du chuchotement 🤫', body_fr = 'Il est si agité dans son lit qu''il ne s''endort pas. Au lieu d''élever la voix, baissez soudain le ton. Ne lui parlez plus qu''en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau passe automatiquement en mode sommeil.', title_hi = 'फुसफुसाहट का सम्मोहन 🤫', body_hi = 'बिस्तर में इतना सक्रिय है कि सो ही नहीं रहा। आवाज़ ऊँची करने के बजाय अचानक अपना लहजा धीमा कर दीजिए। उससे सिर्फ़ फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए पूरा ध्यान लगाता है, तो उसका दिमाग अपने-आप नींद के मोड में चला जाएगा।', title_id = 'Hipnosis bisikan 🤫', body_id = 'Ia begitu aktif di tempat tidur sampai tidak bisa tidur. Daripada meninggikan suara, turunkan nada suara Anda secara tiba-tiba. Bicaralah dengannya hanya sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis beralih ke mode tidur.', title_ja = 'ささやきの催眠術 🤫', body_ja = 'ベッドの上で元気いっぱいで、なかなか寝ない。声を大きくする代わりに、急に声のトーンを落としましょう。ささやき声だけで話しかけて。あなたの声を聞こうと集中すると、脳は自然と眠りモードに切りかわります。', title_ko = '속삭임의 최면 🤫', body_ko = '침대에서 너무 활발해서 잠들지 않나요? 목소리를 높이는 대신 갑자기 톤을 낮추세요. 속삭이듯만 말하세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 수면 모드로 바뀔 거예요.', title_nl = 'De hypnose van het fluisteren 🤫', body_nl = 'Is hij in bed zo actief dat hij niet in slaap valt? Verhef je stem niet, maar ga ineens zachter praten. Spreek alleen nog fluisterend tegen hem. Als hij zijn best doet om je te verstaan, schakelt zijn brein automatisch over naar de slaapstand.', title_pl = 'Hipnoza szeptu 🤫', body_pl = 'W łóżku jest tak aktywny, że nie zasypia. Zamiast podnosić głos, nagle go obniż. Mów do niego wyłącznie szeptem. Gdy dziecko zamieni się w słuch, żeby cię usłyszeć, jego mózg automatycznie przejdzie w tryb snu.', title_pt = 'A hipnose do sussurro 🤫', body_pt = 'Está tão ativo na cama que não adormece. Em vez de levantar a voz, baixe de repente o tom. Fale com ele só a sussurrar. Quando a criança se concentra para a ouvir, o cérebro passa automaticamente para o modo de sono.', title_sv = 'Viskningens hypnos 🤫', body_sv = 'Barnet är så aktivt i sängen att det inte somnar. Istället för att höja rösten, sänk plötsligt tonen. Prata bara viskande. När barnet lyssnar spänt för att höra dig går hjärnan automatiskt över i sömnläge.', title_vi = 'Lời thì thầm thôi miên 🤫', body_vi = 'Bé hiếu động trên giường đến mức không chịu ngủ. Thay vì lớn tiếng, hãy bất ngờ hạ giọng. Chỉ nói thì thầm với bé. Khi bé chú ý để nghe mẹ, não bé sẽ tự động chuyển sang chế độ ngủ.', title_zh = '悄悄话的催眠术 🤫', body_zh = '在床上太活跃，怎么都睡不着。与其提高嗓门，不如突然压低声音。只用悄悄话和宝宝说话。宝宝聚精会神想听清你时，大脑会自动切换到睡眠模式。' WHERE id = '5f1b9ed1-3342-457d-874b-d33366fcceaf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la comunidad de madres 💬', body_es = '¿Te agota pensar «este niño nunca se va a calmar»? Entra en la Comunidad Anacan. Cuando leas las historias de terquedad parecidas, e incluso más cómicas, de otras madres, verás que no estás sola y respirarás hondo.', title_fr = 'La force de la communauté des mamans 💬', body_fr = 'L''idée que « cet enfant ne se calmera jamais » vous épuise ? Rejoignez la Communauté Anacan. En lisant les histoires d''entêtement similaires, et même plus comiques, des autres mamans, vous verrez que vous n''êtes pas seule et vous pourrez enfin souffler.', title_hi = 'माँओं की कम्युनिटी की ताकत 💬', body_hi = '‘यह बच्चा कभी शांत नहीं होगा’ वाला ख्याल आपको थका रहा है? Anacan कम्युनिटी में जाइए। वहाँ की माँओं की मिलती-जुलती और उससे भी मज़ेदार ज़िद की कहानियाँ पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और गहरी राहत की साँस लेंगी।', title_id = 'Kekuatan komunitas ibu 💬', body_id = 'Pikiran ''anak ini tidak akan pernah tenang'' membuat Anda lelah? Masuklah ke Komunitas Anacan. Saat membaca kisah keras kepala yang serupa, bahkan lebih lucu, dari ibu-ibu di sana, Anda akan melihat bahwa Anda tidak sendirian dan bisa bernapas lega.', title_ja = 'ママたちのコミュニティの力 💬', body_ja = '「この子は一生落ち着かないんじゃないか」と思って疲れていませんか？Anacanコミュニティを開いてみて。ママたちの同じような、もっとおかしながんこ話を読めば、ひとりじゃないとわかって、深く息がつけるはずです。', title_ko = '엄마 커뮤니티의 힘 💬', body_ko = '''이 아이는 절대 진정하지 않을 거야''라는 생각에 지쳤나요? Anacan 커뮤니티에 들어가 보세요. 다른 엄마들의 비슷하거나 더 웃긴 고집 이야기를 읽으면 혼자가 아니라는 걸 알고 크게 숨을 돌리게 될 거예요.', title_nl = 'De kracht van de mama-Community 💬', body_nl = 'Word je moe van de gedachte ''dit kind wordt nooit rustig''? Ga naar de Anacan Community. Als je de verhalen van andere mama''s leest over net zulke of nog grappigere koppigheid, zie je dat je niet de enige bent en haal je diep adem.', title_pl = 'Siła społeczności mam 💬', body_pl = 'Męczy cię myśl, że to dziecko nigdy się nie uspokoi? Wejdź do Społeczności Anacan. Gdy przeczytasz podobne, a nawet zabawniejsze historie o uporze od innych mam, zobaczysz, że nie jesteś sama, i odetchniesz z ulgą.', title_pt = 'A força da comunidade de mães 💬', body_pt = 'Cansa-a pensar "esta criança nunca se vai acalmar"? Entre na Comunidade Anacan. Ao ler as histórias de teimosia parecidas, e até mais cómicas, das mães de lá, vai ver que não está sozinha e respirar de alívio.', title_sv = 'Mammagemenskapens kraft 💬', body_sv = 'Tröttar tanken ”det här barnet kommer aldrig att lugna ner sig” ut dig? Gå in i Anacan Community. När du läser mammornas liknande och ännu roligare historier om envishet ser du att du inte är ensam och kan andas ut ordentligt.', title_vi = 'Sức mạnh của cộng đồng các mẹ 💬', body_vi = 'Ý nghĩ "đứa trẻ này sẽ không bao giờ chịu yên" khiến mẹ mệt mỏi? Hãy vào Cộng đồng Anacan. Khi đọc những câu chuyện bướng bỉnh tương tự, thậm chí còn hài hước hơn của các mẹ ở đó, mẹ sẽ thấy mình không đơn độc và thở phào nhẹ nhõm.', title_zh = '妈妈社区的力量 💬', body_zh = '“这孩子永远都安静不下来”的念头让你心累？进入Anacan社区。读到那里的妈妈们类似、甚至更搞笑的“倔强故事”，你会发现自己并不孤单，深深地松一口气。' WHERE id = '6ac2df5a-944c-4a22-9450-7bfad30550c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Profesor de filosofía 🤔', body_es = '«¿Por qué no se ve el viento?», «¿Por qué se cae la hoja?». Las preguntas profundas te queman el cerebro desde primera hora. No intentes dar explicaciones científicas durante horas. A esta edad, respuestas inventadas y dulces como «porque los árboles se cambian de ropa» le dejarán totalmente satisfecho.', title_fr = 'Le professeur de philosophie 🤔', body_fr = '« Pourquoi on ne voit pas le vent ? », « Pourquoi la feuille tombe ? » Dès le matin, ces questions profondes vous font chauffer le cerveau. N''essayez pas de donner des explications scientifiques pendant des heures. À cet âge, des réponses inventées et mignonnes comme « Parce que les arbres changent de vêtements » le satisferont complètement.', title_hi = 'दर्शन के प्रोफ़ेसर 🤔', body_hi = '‘हवा दिखती क्यों नहीं?’, ‘पत्ता क्यों गिरता है?’ गहरे सवाल सुबह-सुबह आपका दिमाग गरम कर देते हैं। घंटों वैज्ञानिक व्याख्या देने की कोशिश मत कीजिए। ‘क्योंकि पेड़ अपने कपड़े बदलते हैं’ जैसे गढ़े हुए, प्यारे जवाब इस उम्र में उसे पूरी तरह संतुष्ट कर देंगे।', title_id = 'Profesor filsafat 🤔', body_id = '''Kenapa angin tidak terlihat?'', ''Kenapa daun jatuh?'' Pertanyaan yang dalam membakar otak Anda sejak pagi. Jangan mencoba memberi penjelasan ilmiah berjam-jam. Jawaban karangan yang manis seperti ''karena pohon sedang ganti baju'' sudah sangat memuaskannya di usia ini.', title_ja = '哲学の教授 🤔', body_ja = '「風はなんで見えないの？」「葉っぱはなんで落ちるの？」朝から深い質問で頭がフル回転。何時間も科学的に説明しようとしないで。「木がお洋服を着がえているんだよ」のような作り話のかわいい答えで、この年ごろは十分満足します。', title_ko = '철학 교수님 🤔', body_ko = '''바람은 왜 안 보여?'', ''나뭇잎은 왜 떨어져?'' 아침부터 깊은 질문이 머리를 달구나요? 몇 시간씩 과학적으로 설명하려 하지 마세요. ''나무가 옷을 갈아입는 거야''처럼 지어낸 달콤한 답이면 이 나이엔 충분해요.', title_nl = 'Professor filosofie 🤔', body_nl = '''Waarom kun je de wind niet zien?'', ''Waarom vallen de blaadjes?'' Al vroeg in de ochtend laten diepe vragen je hoofd roken. Probeer niet urenlang wetenschappelijke uitleg te geven. Verzonnen, lieve antwoorden als ''De bomen trekken andere kleren aan'' zijn op deze leeftijd helemaal genoeg.', title_pl = 'Profesor filozofii 🤔', body_pl = '„Dlaczego nie widać wiatru?”, „Dlaczego liść spada?” Głębokie pytania od rana palą ci mózg. Nie próbuj godzinami tłumaczyć naukowo. W tym wieku w pełni zadowolą go wymyślone, słodkie odpowiedzi w stylu „drzewa zmieniają ubranka”.', title_pt = 'Professor de filosofia 🤔', body_pt = '"Porque é que não se vê o vento?", "Porque é que as folhas caem?" Perguntas profundas queimam-lhe o cérebro logo de manhã. Não tente dar explicações científicas durante horas. Nesta idade, respostas inventadas e doces como "Porque as árvores estão a mudar de roupa" deixam-no totalmente satisfeito.', title_sv = 'Filosofiprofessorn 🤔', body_sv = '”Varför syns inte vinden?”, ”Varför faller lövet?” Djupa frågor tidigt på morgonen får hjärnan att gå varm. Försök inte ge vetenskapliga förklaringar i timmar. Påhittade och söta svar som ”För att träden byter kläder” räcker helt i den här åldern.', title_vi = 'Giáo sư triết học 🤔', body_vi = '"Sao không nhìn thấy gió?", "Sao lá rụng?" Những câu hỏi sâu xa làm đầu mẹ nóng lên từ sáng sớm. Đừng cố giải thích khoa học hàng giờ. Những câu trả lời ngọt ngào, tưởng tượng như "Vì cây đang thay áo" sẽ khiến bé ở tuổi này hoàn toàn hài lòng.', title_zh = '哲学教授 🤔', body_zh = '“风为什么看不见？”“叶子为什么会掉？”一大早，深奥的问题就让你脑袋发烫。别花几个小时做科学解释。像“因为树在换衣服”这样编出来的甜甜答案，在这个年龄就能让宝宝完全满意。' WHERE id = '7b051600-3f87-4940-baec-461cd64e5af1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile con las sombras 🐰', body_es = 'Con la excusa de que le da miedo la oscuridad, se escapa de la cama. Apaga todas las luces de la habitación, enciende una linterna y haz con las manos sombras de pájaros y perros en la pared. La oscuridad que le asusta se convertirá en segundos en un teatro.', title_fr = 'Danser avec les ombres 🐰', body_fr = 'Il prétexte avoir peur du noir pour s''échapper du lit. Éteignez toutes les lumières de la chambre, allumez une lampe de poche et créez avec vos mains des ombres d''oiseau et de chien sur le mur. En quelques secondes, le noir qui lui faisait peur deviendra un théâtre.', title_hi = 'परछाइयों के साथ नृत्य 🐰', body_hi = 'अँधेरे से डर का बहाना बनाकर बिस्तर से भागता है। कमरे की सारी लाइटें बंद कीजिए, टॉर्च जलाइए और दीवार पर हाथों से चिड़िया, कुत्ते की परछाइयाँ बनाइए। जिस अँधेरे से वह डरता है, वह सेकंडों में उसके लिए थिएटर बन जाएगा।', title_id = 'Berdansa dengan bayangan 🐰', body_id = 'Ia menjadikan takut gelap sebagai alasan untuk kabur dari tempat tidur. Matikan semua lampu kamar, nyalakan senter, dan buat bayangan burung dan anjing di dinding dengan tangan Anda. Dalam hitungan detik, gelap yang ia takuti akan berubah menjadi teater.', title_ja = '影とダンス 🐰', body_ja = '暗いのが怖いと言いわけしてベッドから逃げだす。部屋の明かりを全部消して懐中電灯をつけ、壁に手で鳥や犬の影絵をつくりましょう。怖がっていた暗やみが、あっという間に劇場に変わります。', title_ko = '그림자와 춤을 🐰', body_ko = '어둠이 무섭다는 핑계로 침대에서 도망치나요? 방의 불을 모두 끄고 손전등을 켜서 손으로 벽에 새와 강아지 그림자를 만들어 보세요. 무서웠던 어둠이 몇 초 만에 극장으로 바뀔 거예요.', title_nl = 'Dansen met schaduwen 🐰', body_nl = 'Hij gebruikt zijn angst voor het donker als smoes om uit bed te gaan. Doe alle lichten in de kamer uit, zet een zaklamp aan en maak met je handen schaduwen van vogels en honden op de muur. Het donker waar hij bang voor was, wordt binnen een paar seconden een theater.', title_pl = 'Taniec z cieniami 🐰', body_pl = 'Wymawia się strachem przed ciemnością i ucieka z łóżka. Zgaś wszystkie światła w pokoju, włącz latarkę i zrób dłońmi na ścianie cienie ptaka i pieska. Ciemność, której się bał, w kilka sekund zmieni się dla niego w teatr.', title_pt = 'Dançar com as sombras 🐰', body_pt = 'Usa o medo do escuro como desculpa para fugir da cama. Apague todas as luzes do quarto, acenda a lanterna e faça com as mãos sombras de pássaros e cães na parede. Em segundos, o escuro de que tem medo vai transformar-se num teatro.', title_sv = 'Dans med skuggorna 🐰', body_sv = 'Barnet skyller på att det är mörkrädd och springer ur sängen. Släck alla lampor i rummet, tänd ficklampan och forma fåglar och hundar som skuggor på väggen med händerna. Mörkret som barnet är rädd för blir på några sekunder en teater.', title_vi = 'Khiêu vũ cùng những cái bóng 🐰', body_vi = 'Bé lấy cớ sợ bóng tối để trốn khỏi giường. Hãy tắt hết đèn trong phòng, bật đèn pin và dùng tay tạo bóng chim, bóng chó trên tường. Bóng tối bé sợ sẽ biến thành nhà hát chỉ trong vài giây.', title_zh = '和影子跳舞 🐰', body_zh = '拿怕黑当借口从床上溜走。关掉房间所有的灯，打开手电筒，用手在墙上做出小鸟、小狗的影子。宝宝害怕的黑暗，几秒钟就会变成一座剧场。' WHERE id = '7bab0bc1-e2b8-4588-8d81-ecc8ddbde523' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La inteligencia artificial al rescate 🤖', body_es = '¿No encuentras respuesta a las preguntas o a los comportamientos raros de tu peque? Recurre a Anacan AI. Te explicará cómo funciona el cerebro de los niños de más de 3 años en lenguaje de pediatra, de forma breve y muy tranquilizadora.', title_fr = 'L''intelligence artificielle à la rescousse 🤖', body_fr = 'Vous ne trouvez pas de réponse à ses questions ou à ses comportements étranges ? Faites appel à Anacan AI. Il vous expliquera, avec les mots d''un pédiatre, de façon courte et très rassurante, comment fonctionne le cerveau des enfants de plus de 3 ans.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस बचाने आया 🤖', body_hi = 'बच्चे के सवालों या अजीब व्यवहार का जवाब नहीं मिल रहा? Anacan AI से पूछिए। वह आपको बाल रोग विशेषज्ञ की भाषा में, बहुत सुकून भरे और छोटे रूप में समझाएगा कि 3 साल से बड़े बच्चों का दिमाग कैसे काम करता है।', title_id = 'Penyelamat kecerdasan buatan 🤖', body_id = 'Tidak menemukan jawaban atas pertanyaan atau perilaku aneh anak Anda? Tanyakan pada Anacan AI. Ia akan menjelaskan cara kerja otak anak di atas 3 tahun dengan bahasa dokter anak, secara singkat dan sangat menenangkan.', title_ja = 'AIが助けてくれる 🤖', body_ja = '子どもの質問やふしぎな行動に、答えが見つからない？Anacan AIに聞いてみましょう。3歳を過ぎた子どもの脳がどう働くのかを、小児科医の言葉で、とても安心できるように短く説明してくれます。', title_ko = '구원 투수 인공지능 🤖', body_ko = '아이의 질문이나 이상한 행동에 답을 못 찾겠나요? Anacan AI에게 물어보세요. 세 살이 넘은 아이의 뇌가 어떻게 움직이는지 소아과 의사의 언어로, 아주 차분하고 짧게 설명해 줄 거예요.', title_nl = 'Redder in nood: kunstmatige intelligentie 🤖', body_nl = 'Vind je geen antwoord op de vragen of het rare gedrag van je kind? Vraag het Anacan AI. Die legt je in de taal van een kinderarts, kort en heel geruststellend uit hoe het brein van kinderen boven de 3 jaar werkt.', title_pl = 'Sztuczna inteligencja na ratunek 🤖', body_pl = 'Nie znajdujesz odpowiedzi na pytania albo dziwne zachowania dziecka? Zwróć się do Anacan AI. Wyjaśni ci językiem pediatry, bardzo spokojnie i krótko, jak działa mózg dzieci powyżej 3 lat.', title_pt = 'A inteligência artificial ao resgate 🤖', body_pt = 'Não encontra resposta para as perguntas ou os comportamentos estranhos da criança? Recorra ao Anacan AI. Vai explicar-lhe, em linguagem de pediatra, de forma curta e muito tranquilizadora, como funciona o cérebro das crianças com mais de 3 anos.', title_sv = 'AI som räddare 🤖', body_sv = 'Hittar du inga svar på barnets frågor eller konstiga beteenden? Vänd dig till Anacan AI. Den förklarar hur hjärnan fungerar hos barn över 3 år på barnläkarspråk, kort och väldigt lugnande.', title_vi = 'Trí tuệ nhân tạo cứu nguy 🤖', body_vi = 'Không tìm được câu trả lời cho những câu hỏi hay hành vi kỳ lạ của bé? Hãy hỏi Anacan AI. Anacan AI sẽ giải thích cho mẹ não bộ của trẻ trên 3 tuổi hoạt động thế nào bằng ngôn ngữ của bác sĩ nhi khoa, ngắn gọn và giúp mẹ yên tâm.', title_zh = '人工智能救星 🤖', body_zh = '不知道怎么回答孩子的问题，或者理解不了孩子奇怪的行为？问问Anacan AI。它会用儿科医生的语言，简短又让人安心地告诉你，3岁以上孩子的大脑是怎样运作的。' WHERE id = 'd0ef94fa-1acc-4932-b3b2-947791c88119' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Puzles y lógica 🧩', body_es = '¿Intenta montar puzles de 5-6 piezas? Está aprendiendo geometría y lógica. No frenes estos movimientos repetitivos, pero tan educativos.', title_fr = 'Puzzle et logique 🧩', body_fr = 'Il essaie d''assembler des puzzles de 5 ou 6 pièces ? Il apprend la géométrie et la logique. Ne freinez pas ces gestes répétitifs mais si formateurs.', title_hi = 'पज़ल और तर्क 🧩', body_hi = '5-6 टुकड़ों वाली पज़ल जोड़ने की कोशिश करता है? वह ज्यामिति और तर्क सीख रहा है। उसकी इन बार-बार दोहराई जाने वाली, पर सिखाने वाली कोशिशों में रुकावट मत डालिए।', title_id = 'Puzzle dan logika 🧩', body_id = 'Ia mencoba menyusun puzzle 5-6 keping? Ia sedang belajar geometri dan logika. Jangan halangi gerakannya yang berulang namun mendidik ini.', title_ja = 'パズルと論理 🧩', body_ja = '5〜6ピースのパズルをつなげようとしている？図形と論理を学んでいます。くり返しだけれど学びのあるこの動きを、じゃましないであげて。', title_ko = '퍼즐과 논리 🧩', body_ko = '5~6조각 퍼즐을 맞추려 하나요? 도형과 논리를 배우는 중이에요. 반복되지만 배움이 되는 이 행동을 방해하지 마세요.', title_nl = 'Puzzels en logica 🧩', body_nl = 'Probeert hij puzzels van 5-6 stukjes te maken? Hij leert meetkunde en logica. Houd deze herhaalde maar leerzame bezigheden niet tegen.', title_pl = 'Puzzle i logika 🧩', body_pl = 'Próbuje układać puzzle z 5-6 elementów? Uczy się geometrii i logiki. Nie przerywaj mu tych powtarzalnych, ale uczących czynności.', title_pt = 'Puzzles e lógica 🧩', body_pt = 'Tenta montar puzzles de 5-6 peças? Está a aprender geometria e lógica. Não interrompa estes movimentos repetitivos, mas educativos.', title_sv = 'Pussel och logik 🧩', body_sv = 'Försöker barnet lägga pussel med 5-6 bitar? Barnet lär sig geometri och logik. Stoppa inte de upprepade men lärorika försöken.', title_vi = 'Xếp hình và tư duy logic 🧩', body_vi = 'Bé cố ghép những bộ xếp hình 5-6 mảnh? Bé đang học hình học và logic. Đừng cản trở những động tác lặp đi lặp lại nhưng đầy tính học hỏi này.', title_zh = '拼图和逻辑 🧩', body_zh = '想把5-6块的拼图拼起来？宝宝在学习几何和逻辑。别打断这些反复却很有教育意义的动作。' WHERE id = '6701933c-47e8-4c97-996b-a27409d87c3c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apoyo de papá 🫂', title_fr = 'Le soutien de papa 🫂', title_hi = 'पापा का सहारा 🫂', title_id = 'Dukungan Ayah 🫂', title_ja = 'パパのサポート 🫂', title_ko = '아빠의 응원 🫂', title_nl = 'Steun van papa 🫂', title_pl = 'Wsparcie taty 🫂', title_pt = 'O apoio do pai 🫂', title_sv = 'Pappas stöd 🫂', title_vi = 'Hậu thuẫn từ bố 🫂', title_zh = '爸爸的支持 🫂' WHERE id = 'a0d7169c-229c-430c-a926-4c31eef15e2c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exige una manzana azul 🍏', body_es = 'Nada más abrir los ojos te pide a gritos una manzana azul. No le expliques que eso no existe en la naturaleza ni le des una clase de física o biología. Responde a su lógica absurda con una respuesta igual de absurda pero eficaz: «Las manzanas azules todavía duermen, vamos a despertar a la roja».', title_fr = 'Il veut une pomme bleue 🍏', body_fr = 'À peine les yeux ouverts, il vous réclame en criant une pomme bleue. Ne vous lancez pas dans un cours de physique ou de biologie pour expliquer que ça n''existe pas dans la nature. Répondez à sa logique absurde par une réponse tout aussi absurde mais efficace : « Les pommes bleues dorment encore, viens, on va réveiller une rouge. »', title_hi = 'नीले सेब की माँग 🍏', body_hi = 'आँख खुलते ही चिल्लाकर आपसे नीला सेब माँगता है। प्रकृति में ऐसा कुछ न होने की व्याख्या करके भौतिकी या जीव विज्ञान का पाठ मत पढ़ाइए। ‘नीले सेब अभी सो रहे हैं, आओ लाल वाले को जगाएँ’ कहकर उसके बेतुके तर्क का उतना ही बेतुका, पर काम का जवाब दीजिए।', title_id = 'Tuntutan apel biru 🍏', body_id = 'Begitu membuka mata, ia berteriak meminta apel biru. Jangan memberi pelajaran fisika atau biologi bahwa benda seperti itu tidak ada di alam. Beri jawaban yang sama absurdnya dengan logikanya tapi berhasil: ''Apel birunya masih tidur, ayo kita bangunkan yang merah''.', title_ja = '青いりんごがほしい 🍏', body_ja = '目を開けるなり、大声で青いりんごをほしがる。自然界にそんなものはないと説明して、物理や生物の授業を始めないで。「青いりんごはまだ寝てるの、赤いのを起こしてあげよう」と、おかしな理屈には同じくらいおかしいけれど効果的な答えを返しましょう。', title_ko = '파란 사과를 달라고요 🍏', body_ko = '눈 뜨자마자 소리치며 파란 사과를 달라고 하나요? 자연에는 그런 게 없다며 물리, 생물 수업을 하지 마세요. ''파란 사과는 아직 자고 있어, 우리 빨간 사과를 깨워 볼까?''처럼 엉뚱한 논리엔 똑같이 엉뚱하지만 통하는 답을 해 주세요.', title_nl = 'De eis van een blauwe appel 🍏', body_nl = 'Zodra hij zijn ogen opendoet, schreeuwt hij om een blauwe appel. Ga niet uitleggen dat zoiets in de natuur niet bestaat en geef geen les natuurkunde of biologie. Geef zijn absurde logica een net zo absurd, maar werkend antwoord: ''De blauwe appels slapen nog, laten we de rode wakker maken.''', title_pl = 'Żądanie niebieskiego jabłka 🍏', body_pl = 'Ledwo otworzył oczy, a już z krzykiem żąda niebieskiego jabłka. Nie prowadź lekcji fizyki czy biologii, że w przyrodzie czegoś takiego nie ma. Odpowiedz na jego absurdalną logikę równie absurdalną, ale skuteczną odpowiedzią: „Niebieskie jabłka jeszcze śpią, obudźmy czerwone”.', title_pt = 'A exigência da maçã azul 🍏', body_pt = 'Mal abre os olhos, pede-lhe aos gritos uma maçã azul. Não dê uma aula de física ou biologia a explicar que isso não existe na natureza. Responda à lógica absurda dele com uma resposta igualmente absurda, mas eficaz: "As maçãs azuis ainda estão a dormir, vamos acordar a vermelha".', title_sv = 'Kravet på ett blått äpple 🍏', body_sv = 'Så fort barnet öppnar ögonen skriker det och vill ha ett blått äpple. Förklara inte att sådant inte finns i naturen och håll ingen lektion i fysik eller biologi. Säg ”De blå äpplena sover fortfarande, kom så väcker vi det röda” och svara barnets absurda logik med ett lika absurt men fungerande svar.', title_vi = 'Đòi táo màu xanh dương 🍏', body_vi = 'Vừa mở mắt, bé đã hét lên đòi một quả táo màu xanh dương. Đừng giải thích rằng trong tự nhiên không có thứ đó và giảng bài vật lý hay sinh học. Hãy đáp lại logic ngộ nghĩnh của bé bằng một câu trả lời ngộ nghĩnh không kém nhưng hiệu quả: "Táo xanh dương vẫn đang ngủ, mình đánh thức quả táo đỏ nhé".', title_zh = '要蓝色的苹果 🍏', body_zh = '一睁眼就大喊着要蓝色的苹果。别去解释大自然里没有这种东西，也别上物理或生物课。说一句“蓝苹果还在睡觉呢，我们去把红苹果叫醒吧”，用同样荒诞却管用的回答，回应宝宝的荒诞逻辑。' WHERE id = '55bba77e-306b-49e8-94ad-180de8387a8b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La obsesión de la manta 🛏️', body_es = 'Justo cuando se va a dormir, de repente rompe a llorar: «¡La manta me toca el pie izquierdo!». Sonríe por dentro ante esta nueva obsesión que se inventan los 3 años y medio para retrasar el sueño. Sin decir nada, coloca la manta y apaga con firmeza todas las luces de la habitación.', title_fr = 'L''obsession de la couverture 🛏️', body_fr = 'Il est sur le point de s''endormir et se met soudain à pleurer : « La couverture touche mon pied gauche ! » Souriez intérieurement de cette nouvelle obsession inventée à 3 ans et demi pour retarder le sommeil. Sans un mot, arrangez la couverture et éteignez complètement la lumière, avec fermeté.', title_hi = 'रज़ाई की सनक 🛏️', body_hi = 'बस सोने ही वाला है कि अचानक ‘रज़ाई मेरे बाएँ पैर को छू रही है!’ कहकर रोने लगता है। साढ़े 3 साल की उम्र में नींद टालने के लिए गढ़ी इस नई सनक पर मन ही मन मुस्कुराइए। कुछ कहे बिना रज़ाई ठीक कीजिए और पक्के इरादे से कमरे की सारी लाइटें बंद कर दीजिए।', title_id = 'Obsesi selimut 🛏️', body_id = 'Tepat saat akan terlelap, tiba-tiba ia menangis: ''Selimutnya menyentuh kaki kiriku!'' Tersenyumlah dalam hati pada obsesi baru karangan anak 3,5 tahun untuk menunda tidur ini. Tanpa berkata apa-apa, rapikan selimutnya dan matikan semua lampu kamar dengan tegas.', title_ja = '毛布へのこだわり 🛏️', body_ja = 'もう少しで寝つくところで、急に「毛布が左足にさわってる！」と泣きだす。3歳半の、寝る時間を遅らせるための新しいこだわりに、心の中でほほえみましょう。何も言わずに毛布を直して、きっぱりと部屋の明かりを全部消して。', title_ko = '이불 집착 🛏️', body_ko = '막 잠들려는데 갑자기 ''이불이 왼발에 닿았어!'' 하며 우나요? 세 살 반이 잠을 미루려고 만들어 낸 새로운 집착에 속으로 미소 지으세요. 아무 말 없이 이불을 정리하고 단호하게 방의 불을 완전히 끄세요.', title_nl = 'Dekenobsessie 🛏️', body_nl = 'Net als hij in slaap valt, begint hij ineens te huilen: ''De deken raakt mijn linkervoet!'' Glimlach vanbinnen om deze nieuwe obsessie die een kind van 3,5 bedenkt om het slapen uit te stellen. Leg zonder iets te zeggen de deken recht en doe vastberaden alle lichten in de kamer uit.', title_pl = 'Kołdrowa obsesja 🛏️', body_pl = 'Już ma zasnąć, a nagle zaczyna płakać: „Kołdra dotyka mojej lewej stopy!”. Uśmiechnij się w duchu do tej nowej obsesji, którą 3,5-latek wymyślił, by odwlec sen. Bez słowa popraw kołdrę i stanowczo zgaś wszystkie światła w pokoju.', title_pt = 'A obsessão do cobertor 🛏️', body_pt = 'Está quase a adormecer e de repente começa a chorar: "O cobertor está a tocar no meu pé esquerdo!" Sorria por dentro desta nova obsessão inventada aos 3 anos e meio para adiar o sono. Sem dizer nada, ajeite o cobertor e apague com firmeza todas as luzes do quarto.', title_sv = 'Täckebesatthet 🛏️', body_sv = 'Precis när barnet ska somna börjar det plötsligt gråta: ”Täcket rör vid min vänstra fot!” Le inombords åt den nya besattheten som barnet på 3,5 år hittat på för att skjuta upp sömnen. Rätta till täcket utan ett ord och släck bestämt alla lampor i rummet.', title_vi = 'Ám ảnh chiếc chăn 🛏️', body_vi = 'Sắp ngủ thì bé bỗng bật khóc: "Chăn chạm vào chân trái của con!". Hãy thầm mỉm cười trước "nỗi ám ảnh" mới mà bé 3 tuổi rưỡi nghĩ ra để trì hoãn giấc ngủ. Không nói gì, hãy chỉnh lại chăn và dứt khoát tắt hết đèn trong phòng.', title_zh = '被子强迫症 🛏️', body_zh = '马上就要睡着了，突然哭了起来：“被子碰到我的左脚了！”对这个3岁半宝宝为了拖延睡觉发明的新“强迫症”，在心里偷偷笑一笑吧。什么都别说，把被子整理好，然后坚定地把房间的灯全部关掉。' WHERE id = '5d5d4766-5ced-4cf7-8ea9-3acdffe118cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El precio del silencio sospechoso 💄', body_es = 'El final de 10 minutos de silencio repentino en casa: entras en la habitación y se ha pintado la cara y también el espejo con tu pintalabios favorito. Ya es tarde para enfadarse.', title_fr = 'Le prix d''un silence suspect 💄', body_fr = 'La fin de 10 minutes de silence soudain dans la maison : vous entrez dans la pièce et il a peint son visage et le miroir avec votre rouge à lèvres préféré. Trop tard pour vous énerver.', title_hi = 'संदिग्ध खामोशी की कीमत 💄', body_hi = 'घर में अचानक छाई 10 मिनट की खामोशी का अंत: आप कमरे में जाती हैं और उसने आपकी सबसे पसंदीदा लिपस्टिक से अपना चेहरा और आईना दोनों रंग दिए हैं। अब नाराज़ होने का समय निकल चुका।', title_id = 'Harga dari hening yang mencurigakan 💄', body_id = 'Akhir dari 10 menit hening yang tiba-tiba di rumah: Anda masuk kamar dan ia sudah mewarnai wajahnya dan cermin dengan lipstik favorit Anda. Sudah terlambat untuk marah.', title_ja = 'あやしい静けさの代償 💄', body_ja = '家の中に急に訪れた10分間の静けさの結末：部屋に入ると、あなたのお気に入りの口紅で、自分の顔も鏡もぬりぬり。怒るにはもう遅すぎます。', title_ko = '수상한 고요의 대가 💄', body_ko = '집 안에 찾아온 10분간의 갑작스러운 고요의 끝: 방에 들어가 보니 엄마가 가장 아끼는 립스틱으로 얼굴과 거울을 칠해 놓았네요. 화내기엔 이미 늦었어요.', title_nl = 'De prijs van verdachte stilte 💄', body_nl = 'Het einde van 10 minuten plotselinge stilte in huis: je komt de kamer binnen en hij heeft met jouw favoriete lippenstift zijn eigen gezicht én de spiegel ingekleurd. Boos worden is te laat.', title_pl = 'Cena podejrzanej ciszy 💄', body_pl = 'Koniec nagłej 10-minutowej ciszy w domu: wchodzisz do pokoju, a on twoją ulubioną szminką pomalował i swoją twarz, i lustro. Na złość jest już za późno.', title_pt = 'O preço do silêncio suspeito 💄', body_pt = 'O fim de 10 minutos de silêncio repentino em casa: entra no quarto e ele pintou a cara e o espelho com o seu batom preferido. Já é tarde para se irritar.', title_sv = 'Priset för en misstänkt tystnad 💄', body_sv = 'Slutet på 10 minuters plötslig tystnad hemma: du kommer in i rummet och barnet har målat både sitt ansikte och spegeln med ditt favoritläppstift. Det är för sent att bli arg.', title_vi = 'Cái giá của sự im lặng đáng ngờ 💄', body_vi = 'Kết thúc của 10 phút im lặng bất chợt trong nhà: mẹ bước vào phòng và thấy bé đã dùng thỏi son yêu thích nhất của mẹ tô cả lên mặt mình lẫn tấm gương. Bực mình thì đã muộn rồi.', title_zh = '可疑安静的代价 💄', body_zh = '家里突然安静了10分钟，结局是：你走进房间，发现宝宝用你最心爱的口红，把自己的脸和镜子都涂满了。现在生气已经晚了。' WHERE id = '8bcf9de1-187f-451e-8f68-1235d768b6ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los brazos mágicos de papá ✈️', body_es = 'Tienes los brazos destrozados de cargarle todo el día, pero él sigue lleno de energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo levanta en el aire y hace el avión, las carcajadas llenan la habitación y toda esa energía sin fin acumulada se pone a cero en segundos.', title_fr = 'Les bras magiques de papa ✈️', body_fr = 'Vos bras n''en peuvent plus de l''avoir porté toute la journée, mais lui déborde encore d''énergie et refuse d''aller au lit. Appelez papa en renfort. Quand il le soulève pour jouer à l''avion, les éclats de rire remplissent la pièce et toute cette énergie sans fin retombe à zéro en quelques secondes.', title_hi = 'पापा की जादुई बाहें ✈️', body_hi = 'दिनभर उठाते-उठाते आपकी बाहें टूट रही हैं, पर उसमें अब भी ऊर्जा है और वह सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ बनाते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुई वह अंतहीन ऊर्जा सेकंडों में शून्य हो जाती है।', title_id = 'Lengan ajaib Ayah ✈️', body_id = 'Lengan Anda serasa copot karena menggendongnya seharian, tapi ia masih berenergi dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah mengangkatnya tinggi dan membuatnya ''terbang seperti pesawat'', tawa memenuhi kamar dan semua energi yang tak habis-habis itu kembali nol dalam hitungan detik.', title_ja = 'パパの魔法の腕 ✈️', body_ja = '一日じゅう抱っこで腕がちぎれそうなのに、まだ元気いっぱいで寝るのをいやがる。パパに助けを求めましょう。パパが子どもを持ち上げて飛行機ごっこをすると、部屋は笑い声でいっぱいになり、たまっていた尽きないエネルギーがあっという間にリセットされます。', title_ko = '아빠의 마법 같은 팔 ✈️', body_ko = '하루 종일 안고 다니느라 팔이 빠질 것 같은데 아이는 아직도 에너지가 넘쳐 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 번쩍 들어 비행기를 태우면 웃음소리가 방을 채우고, 쌓인 끝없는 에너지가 몇 초 만에 리셋돼요.', title_nl = 'Papa''s magische armen ✈️', body_nl = 'Je armen vallen er bijna af van het hele dag dragen, maar hij zit nog vol energie en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem optilt en als een vliegtuig laat vliegen, vult de kamer zich met geschater en is al die eindeloze opgebouwde energie binnen een paar seconden weg.', title_pl = 'Magiczne ramiona taty ✈️', body_pl = 'Ręce odpadają ci od noszenia go przez cały dzień, a on wciąż ma energię i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy podrzuci go w górę i zrobi „samolot”, śmiech wypełni pokój, a cała ta niewyczerpana energia wyzeruje się w kilka sekund.', title_pt = 'Os braços mágicos do pai ✈️', body_pt = 'Tem os braços a cair de o carregar o dia todo, mas ele continua cheio de energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele o levanta no ar e faz de avião, as gargalhadas enchem o quarto e toda aquela energia sem fim chega a zero em segundos.', title_sv = 'Pappas magiska armar ✈️', body_sv = 'Armarna värker efter att ha burit hela dagen, men barnet är fortfarande fullt av energi och vägrar gå och lägga sig. Kalla på pappa. När han lyfter upp barnet i luften och flyger flygplan fylls rummet av skratt, och all den ändlösa energin nollställs på några sekunder.', title_vi = 'Vòng tay diệu kỳ của bố ✈️', body_vi = 'Tay mẹ đã rã rời vì bế bé cả ngày, nhưng bé vẫn tràn năng lượng và không chịu lên giường. Hãy gọi bố đến giúp. Khi bố nhấc bé lên cao "làm máy bay", tiếng cười ngập tràn căn phòng và mọi năng lượng bất tận dồn nén sẽ về không chỉ trong vài giây.', title_zh = '爸爸神奇的手臂 ✈️', body_zh = '抱了一整天，你的胳膊都快断了，可宝宝还精力充沛，就是不肯上床。叫爸爸来帮忙吧。当爸爸把宝宝举高高“开飞机”时，笑声充满房间，积攒的那些用不完的精力几秒钟就清零了。' WHERE id = '42ac5c0d-b412-4999-8839-ddf0e44a9d4b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paseo con un perro invisible 🐕', body_es = 'En medio de la habitación baja la mano, acaricia a un perro invisible y habla con él. Es la fase más inocente de la imaginación. Pregúntale «¿Cómo se llama el perro?», pon un cuenco de agua imaginario en un rincón y sé actriz secundaria de este teatro maravilloso.', title_fr = 'Promenade avec un chien invisible 🐕', body_fr = 'Au milieu de la pièce, il tend la main vers le bas pour caresser un chien invisible et lui parle. C''est la phase la plus innocente de l''imagination. Demandez-lui « Comment s''appelle ton chien ? » et posez une gamelle d''eau imaginaire dans un coin pour devenir second rôle de ce formidable théâtre.', title_hi = 'अदृश्य कुत्ते के साथ सैर 🐕', body_hi = 'कमरे के बीच हाथ नीचे बढ़ाकर एक अदृश्य कुत्ते को सहलाता है और उससे बातें करता है। यह कल्पना का सबसे मासूम दौर है। पूछिए, ‘कुत्ते का नाम क्या है?’ और कमरे के एक कोने में काल्पनिक पानी का कटोरा रखकर इस शानदार नाटक की सहायक कलाकार बन जाइए।', title_id = 'Jalan-jalan dengan anjing tak kasatmata 🐕', body_id = 'Di tengah kamar ia menjulurkan tangan ke bawah, mengelus anjing tak terlihat, dan berbicara dengannya. Ini fase imajinasi yang paling polos. Tanyakan ''Siapa nama anjingnya?'', letakkan mangkuk air khayalan di sudut kamar, dan jadilah pemeran pendukung di teater hebat ini.', title_ja = '見えない犬とお散歩 🐕', body_ja = '部屋のまんなかで手を下にのばし、見えない犬をなでて話しかけている。想像力のいちばんあどけない時期です。「わんちゃんのお名前は？」と聞いて、部屋のすみに空想の水入れを置き、このすばらしい劇の脇役になりましょう。', title_ko = '보이지 않는 강아지와 산책 🐕', body_ko = '방 한가운데서 손을 아래로 뻗어 보이지 않는 강아지를 쓰다듬으며 이야기하나요? 상상력의 가장 순수한 시기예요. ''강아지 이름이 뭐야?'' 물어보고 방 한쪽에 상상의 물그릇을 놓으며 이 멋진 연극의 조연이 되어 주세요.', title_nl = 'Wandelen met een onzichtbare hond 🐕', body_nl = 'Midden in de kamer steekt hij zijn hand uit, aait een onzichtbare hond en praat ermee. Dit is de meest onschuldige fase van de fantasie. Vraag ''Hoe heet de hond?'', zet een denkbeeldig waterbakje in een hoek van de kamer en word bijrolspeler in dit prachtige theater.', title_pl = 'Spacer z niewidzialnym psem 🐕', body_pl = 'Na środku pokoju wyciąga rękę w dół, głaszcze niewidzialnego psa i z nim rozmawia. To najbardziej niewinna faza wyobraźni. Zapytaj: „Jak ma na imię piesek?”, postaw w kącie pokoju wymyśloną miskę z wodą i zostań aktorem drugoplanowym tego wspaniałego teatru.', title_pt = 'Passeio com um cão invisível 🐕', body_pt = 'No meio do quarto, estica a mão para baixo, faz festas a um cão invisível e fala com ele. É a fase mais inocente da imaginação. Pergunte "Como se chama o cão?", ponha uma tigela de água imaginária num canto do quarto e seja ator secundário deste espetáculo fantástico.', title_sv = 'Promenad med en osynlig hund 🐕', body_sv = 'Mitt i rummet sträcker barnet ner handen, klappar en osynlig hund och pratar med den. Det är fantasins mest oskyldiga fas. Fråga ”Vad heter hunden?”, ställ en låtsasvattenskål i ett hörn av rummet och bli biroll i den fantastiska teatern.', title_vi = 'Dắt chú chó vô hình đi dạo 🐕', body_vi = 'Giữa phòng, bé đưa tay xuống vuốt ve một chú chó vô hình và trò chuyện với nó. Đây là giai đoạn hồn nhiên nhất của trí tưởng tượng. Hãy hỏi bé: "Chú chó tên gì thế?" và đặt một bát nước tưởng tượng ở góc phòng, trở thành diễn viên phụ trong vở kịch tuyệt vời này.', title_zh = '和看不见的小狗散步 🐕', body_zh = '在房间中间把手伸向下面，抚摸着一只看不见的小狗，还和它说话。这是想象力最天真的阶段。问问“小狗叫什么名字？”，在房间一角放一个想象中的水碗，当好这出精彩戏剧的配角吧。' WHERE id = 'fd37073a-86b1-4420-9d46-293b17c2e64b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rebelión del armario 🕶️', body_es = 'Ha venido a desayunar con gafas de sol y gorro de invierno y se niega rotundamente a quitárselos. Olvídate de la estética y del «qué dirán». La libertad de tomar sus propias decisiones y defenderlas es una base psicológica mucho más grande que llevar ropa que combine.', title_fr = 'La révolte de la garde-robe 🕶️', body_fr = 'Il arrive au petit-déjeuner avec des lunettes de soleil et un bonnet d''hiver et refuse catégoriquement de les enlever. Laissez tomber l''esthétique et le qu''en-dira-t-on. La liberté de prendre sa propre décision et de la défendre est une base psychologique bien plus importante qu''une tenue assortie.', title_hi = 'अलमारी की बगावत 🕶️', body_hi = 'नाश्ते पर धूप का चश्मा और सर्दियों की टोपी पहनकर आता है और उतारने से साफ़ मना करता है। सुंदरता और ‘लोग क्या कहेंगे’ को छोड़िए। अपना फ़ैसला लेने और उस पर टिके रहने की आज़ादी कपड़ों के मेल से कहीं बड़ी मनोवैज्ञानिक नींव है।', title_id = 'Pemberontakan lemari baju 🕶️', body_id = 'Ia datang sarapan memakai kacamata hitam dan topi musim dingin, dan tegas menolak melepasnya. Lupakan estetika dan apa kata orang. Kebebasan membuat keputusan sendiri dan membelanya adalah fondasi psikologis yang jauh lebih besar daripada keserasian pakaian.', title_ja = 'クローゼットの反乱 🕶️', body_ja = '朝ごはんにサングラスと冬の帽子で現れ、はずすのをきっぱり拒否。見た目も「人にどう思われるか」も気にしないで。自分で決めてそれを守る自由は、服の組み合わせよりずっと大きな心の土台です。', title_ko = '옷장 반란 🕶️', body_ko = '아침 식사에 선글라스와 겨울 모자를 쓰고 와서 절대 벗지 않겠다고 하나요? 보기 좋은 것과 남들 시선은 잊으세요. 스스로 정하고 그 결정을 지키는 자유는 옷차림이 어울리는 것보다 훨씬 큰 심리적 바탕이에요.', title_nl = 'Opstand in de kledingkast 🕶️', body_nl = 'Hij komt ontbijten met een zonnebril en een wintermuts op en weigert ze af te zetten. Laat esthetiek en ''wat zullen de mensen zeggen'' maar zitten. De vrijheid om zelf te beslissen en die keuze te verdedigen is een veel grotere psychologische basis dan kleding die bij elkaar past.', title_pl = 'Bunt w garderobie 🕶️', body_pl = 'Przyszedł na śniadanie w okularach przeciwsłonecznych i zimowej czapce i stanowczo odmawia ich zdjęcia. Odpuść estetykę i to, co powiedzą ludzie. Wolność podejmowania własnych decyzji i ich obrony to psychologiczny fundament o wiele ważniejszy niż dopasowanie stroju.', title_pt = 'Revolta no guarda-roupa 🕶️', body_pt = 'Vem tomar o pequeno-almoço com óculos de sol e gorro de inverno e recusa terminantemente tirá-los. Esqueça a estética e o "que vão dizer". A liberdade de tomar uma decisão e defendê-la é uma base psicológica muito maior do que a roupa combinar.', title_sv = 'Garderobsuppror 🕶️', body_sv = 'Barnet kommer till frukosten i solglasögon och vintermössa och vägrar bestämt ta av dem. Strunta i estetiken och vad folk säger. Friheten att fatta sina egna beslut och försvara dem är en mycket större psykologisk grund än att kläderna passar.', title_vi = 'Cuộc nổi loạn tủ quần áo 🕶️', body_vi = 'Bé đến bàn ăn sáng với kính râm và mũ len mùa đông, kiên quyết không chịu bỏ ra. Kệ thẩm mỹ và chuyện "người ta nói gì". Quyền tự đưa ra quyết định và bảo vệ nó là nền tảng tâm lý lớn hơn nhiều so với việc ăn mặc phù hợp.', title_zh = '衣柜大叛乱 🕶️', body_zh = '戴着太阳镜和冬天的帽子来吃早餐，还坚决不肯摘。别管好不好看，也别管别人怎么说。自己做决定并捍卫它的自由，是比衣服搭不搭重要得多的心理基础。' WHERE id = '29371981-c485-4102-9d09-323cae4a8b4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El ruido de casa te hace pitar los oídos. Cuando por fin se duerma, activa el Medidor de sonido. Mirar el silencio digital de la pantalla bajando hasta 0-10 decibelios es el masaje visual más bonito y relajante para el cerebro de una madre cansada.', body_fr = 'Le bruit de la maison vous fait bourdonner les oreilles. Quand il s''endort enfin, activez le Sonomètre. Regarder ce silence numérique descendre à 0 à 10 décibels à l''écran, c''est le plus beau des massages visuels et apaisants pour le cerveau d''une maman fatiguée.', body_hi = 'घर के शोर से कान झनझना रहे हैं। जब वह आखिरकार सो जाए, तो साउंड मीटर टूल चालू कीजिए। स्क्रीन पर 0-10 डेसिबल तक गिरती डिजिटल खामोशी देखना थकी माँ के दिमाग के लिए सबसे प्यारी और सुकून भरी विज़ुअल मसाज है।', body_id = 'Kebisingan di rumah membuat telinga Anda berdenging. Saat akhirnya ia tertidur, aktifkan Pengukur Suara. Melihat keheningan digital di layar yang turun hingga 0-10 desibel adalah pijatan visual terindah dan paling menenangkan untuk otak ibu yang lelah.', body_ja = '家の中の騒がしさで耳鳴りがしそう。やっと寝てくれたら、「サウンドメーター」をオンにしましょう。画面の0〜10デシベルへと下がっていくデジタルな静けさを眺めることが、疲れたママの脳にとっていちばんすてきな、目で見る癒やしのマッサージです。', body_ko = '집 안의 소음에 귀가 울리나요? 아이가 드디어 잠들면 소음 측정기를 켜 보세요. 화면 속 0~10데시벨까지 내려가는 디지털 고요를 보는 것이 지친 엄마의 머리에 가장 아름답고 편안한 시각 마사지예요.', body_nl = 'Het lawaai in huis laat je oren suizen. Zet de Geluidsmeter aan als hij eindelijk slaapt. Kijken hoe de digitale stilte op het scherm zakt tot 0-10 decibel is de fijnste, visueel kalmerende massage voor het brein van een vermoeide mama.', body_pl = 'Hałas w domu dzwoni ci w uszach. Gdy w końcu zaśnie, włącz Miernik dźwięku. Patrzenie, jak cyfrowa cisza na ekranie spada do 0-10 decybeli, to najpiękniejszy, wizualnie kojący masaż dla mózgu zmęczonej mamy.', body_pt = 'O barulho da casa faz-lhe zumbir os ouvidos. Quando ele finalmente adormecer, ative o Medidor de Som. Ver o silêncio digital no ecrã descer até aos 0-10 decibéis é a melhor massagem visual e calmante para o cérebro de uma mãe cansada.', body_sv = 'Oljudet hemma får det att ringa i öronen. När barnet äntligen har somnat, aktivera verktyget Ljudmätare. Att se den digitala tystnaden sjunka till 0-10 decibel på skärmen är den skönaste och mest lugnande visuella massagen för en trött mammas hjärna.', body_vi = 'Tiếng ồn trong nhà làm tai mẹ ù đi. Khi bé cuối cùng cũng ngủ, hãy bật Đo âm thanh. Nhìn sự im lặng hạ dần về 0-10 decibel trên màn hình là màn mát-xa thị giác êm dịu và tuyệt vời nhất cho não bộ của người mẹ mệt mỏi.', body_zh = '家里的噪音让你耳朵嗡嗡作响。宝宝终于睡着后，打开分贝仪。看着屏幕上一路降到0-10分贝的数字化安静，对疲惫的妈妈来说，就是最美好、看得见的放松按摩。' WHERE id = '51cdbeb9-6ab2-41f5-bfe2-9e148aedb489' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El rescatador de hormigas 🐜', body_es = '¿En el parque se ha puesto delante llorando para proteger a una hormiga de que la pisen? Admira su empatía tan enorme y compasiva.', title_fr = 'Le sauveur de fourmis 🐜', body_fr = 'Au parc, il vous a barré la route en pleurant pour protéger une fourmi par terre ? Émerveillez-vous devant son immense empathie pleine de compassion.', title_hi = 'चींटी का रक्षक 🐜', body_hi = 'पार्क में ज़मीन पर एक चींटी को कुचलने से बचाने के लिए रोते हुए रास्ता रोककर खड़ा हो गया? उसकी इस बड़ी, दयालु सहानुभूति पर फ़िदा हो जाइए।', title_id = 'Penyelamat semut 🐜', body_id = 'Di taman ia menangis dan menghalangi jalan demi melindungi seekor semut di tanah agar tidak terinjak? Kagumilah empatinya yang begitu besar dan penuh kasih.', title_ja = 'アリの救助隊 🐜', body_ja = '公園で、地面のアリがふまれないように、泣きながら通せんぼしている？この大きくてやさしい思いやりに、感動しますね。', title_ko = '개미 구조대 🐜', body_ko = '공원에서 바닥의 개미가 밟히지 않게 울면서 길을 막았나요? 이 크고 다정한 공감 능력에 감탄해 주세요.', title_nl = 'Mierenredder 🐜', body_nl = 'Ging hij in het park huilend voor je staan om een mier op de grond te redden van platgetrapt worden? Wees verrukt over zijn enorme, meelevende empathie.', title_pl = 'Wybawca mrówek 🐜', body_pl = 'W parku z płaczem zagrodził ci drogę, żeby ochronić mrówkę na ziemi przed zdeptaniem? Zachwyć się jego ogromną, pełną współczucia empatią.', title_pt = 'O salvador de formigas 🐜', body_pt = 'No parque, pôs-se a chorar à frente de uma formiga no chão para não deixar que fosse esmagada? Admire esta empatia enorme e compassiva.', title_sv = 'Myrornas räddare 🐜', body_sv = 'Har barnet gråtande ställt sig i vägen för att skydda en myra på marken i parken från att bli trampad? Beundra barnets enorma, barmhärtiga empati.', title_vi = 'Người giải cứu kiến 🐜', body_vi = 'Ở công viên, bé khóc và chắn đường để bảo vệ một chú kiến khỏi bị giẫm phải? Hãy ngưỡng mộ sự đồng cảm lớn lao, giàu lòng trắc ẩn của bé.', title_zh = '蚂蚁救星 🐜', body_zh = '在公园里为了保护地上的一只蚂蚁不被踩到，哭着挡在前面？为宝宝这份博大又善良的共情而惊叹吧。' WHERE id = 'fca5f016-a334-4b48-86a0-e10c617f28f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tienes las cuerdas vocales cansadas de leer los libros de siempre. Abre Cuentos inteligentes. Diseña una historia con tu peque como protagonista y sonidos relajantes del bosque de fondo, y crea una sesión de sueño hipnótica y original que no exige ningún esfuerzo.', body_fr = 'Votre voix est fatiguée d''avoir lu les livres classiques. Ouvrez les Contes intelligents. Faites de votre enfant le héros, avec des sons apaisants de la forêt en fond, et créez une séance d''endormissement hypnotique et originale qui ne demande aucun effort.', body_hi = 'पुरानी किताबें पढ़ते-पढ़ते आपका गला थक गया है। स्मार्ट कहानियाँ खोलिए। मुख्य हीरो अपने बच्चे को और बैकग्राउंड में सुकून भरी जंगल की आवाज़ें रखकर एक अनोखा, बिना मेहनत वाला, सम्मोहक नींद का सत्र बनाइए।', body_id = 'Pita suara Anda lelah membacakan buku-buku klasik. Buka Dongeng Pintar. Jadikan anak Anda tokoh utamanya dan suara hutan yang menenangkan sebagai latar, lalu ciptakan sesi tidur hipnotis yang tidak biasa tanpa usaha apa pun.', body_ja = '定番の絵本の読み聞かせで、声が疲れてしまいましたね。「スマートおはなし」を開きましょう。主人公はお子さん、背景には心落ち着く森の音を選んで、いつもとちがう、まったく手間のかからない催眠のような寝かしつけタイムをつくりましょう。', body_ko = '늘 읽던 책을 읽느라 목이 지쳤나요? 스마트 동화를 열어 보세요. 주인공은 아이로, 배경은 차분한 숲 소리로 꾸며 특별하고 힘들이지 않는 최면 같은 잠자리 시간을 만들어 보세요.', body_nl = 'Je stembanden zijn moe van het voorlezen van klassieke boeken. Open Slimme sprookjes. Maak je kind de hoofdpersoon, kies rustgevende bosgeluiden als achtergrond en creëer een bijzondere, hypnotiserende slaapsessie die je geen moeite kost.', body_pl = 'Twoje struny głosowe są zmęczone czytaniem klasycznych książeczek. Otwórz Mądre bajki. Uczyń głównym bohaterem swoje dziecko, a tłem kojące odgłosy lasu, i stwórz niezwykły, hipnotyczny seans usypiania, który nie wymaga żadnego wysiłku.', body_pt = 'As suas cordas vocais estão cansadas de ler livros clássicos. Abra as Histórias Inteligentes. Crie uma história com o seu filho como herói principal e sons calmantes da floresta como fundo, e prepare uma sessão de sono hipnótica e fora do comum, sem esforço nenhum.', body_sv = 'Stämbanden är trötta av att läsa klassiska böcker. Öppna Smarta sagor. Gör barnet till huvudperson och lugnande skogsljud till bakgrund, så skapar du en ovanlig, hypnotisk sovstund som inte kräver någon ansträngning.', body_vi = 'Giọng mẹ đã mỏi vì đọc những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh. Thiết kế một buổi ru ngủ khác lạ, như thôi miên mà chẳng tốn chút công sức: bé là nhân vật chính, còn nền là âm thanh rừng xanh êm dịu.', body_zh = '读经典故事书读得嗓子都累了。打开智慧童话。把宝宝设计成主角，背景配上安神的森林声，打造一场不寻常、毫不费力、像催眠一样的哄睡时光。' WHERE id = '02c49204-da15-4fa6-aab8-953dbda0aa33' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El consuelo silencioso de la Comunidad 💬', body_es = '¿De repente te ahoga el pensamiento «Nunca volveré a ser la de antes, libre y despreocupada»? Entra en la Comunidad Anacan. Encuentra consuelo leyendo que otras madres también pasan por estos sentimientos pesados pero muy naturales, y que es una fase de la maternidad.', title_fr = 'Le réconfort silencieux de la Communauté 💬', body_fr = 'La pensée « Je ne serai plus jamais la femme libre et insouciante d''avant » vous étouffe soudain ? Rejoignez la Communauté Anacan. Trouvez du réconfort en lisant que d''autres mamans traversent aussi ces sentiments lourds mais très naturels, et que c''est une phase de la maternité.', title_hi = 'कम्युनिटी की खामोश सांत्वना 💬', body_hi = '‘मैं फिर कभी पहले वाली आज़ाद, बेफ़िक्र मैं नहीं बन पाऊँगी’ वाला ख्याल अचानक आपका दम घोंट रहा है? Anacan कम्युनिटी में जाइए। पढ़िए कि दूसरी माँएँ भी इन भारी, पर बहुत स्वाभाविक भावनाओं से गुज़रती हैं, कि यह माँ बनने का एक दौर है, और सांत्वना पाइए।', title_id = 'Penghiburan diam dari komunitas 💬', body_id = 'Pikiran ''Aku tidak akan pernah bisa menjadi diriku yang dulu, bebas dan tanpa beban'' tiba-tiba membuat Anda sesak? Masuklah ke Komunitas Anacan. Bacalah bahwa ibu-ibu lain juga melalui perasaan berat namun sangat wajar ini, bahwa ini salah satu fase menjadi ibu, dan temukan penghiburan.', title_ja = 'コミュニティの静かななぐさめ 💬', body_ja = '「もう前の自由で気楽な自分には戻れない」という思いに、急に胸がつまることはありませんか？Anacanコミュニティを開いてみて。ほかのママたちも、この重いけれどとても自然な気持ちを経験していて、それがママ業のひとつの段階だと読めば、なぐさめが見つかります。', title_ko = '커뮤니티의 조용한 위로 💬', body_ko = '''다시는 예전의 자유롭고 걱정 없는 나로 돌아갈 수 없을 거야''라는 생각이 갑자기 숨을 막히게 하나요? Anacan 커뮤니티에 들어가 보세요. 다른 엄마들도 이 무겁지만 아주 자연스러운 감정을 겪고, 이것이 엄마가 되는 과정의 한 시기라는 걸 읽으며 위로를 얻으세요.', title_nl = 'De stille troost van de Community 💬', body_nl = 'Overvalt de gedachte ''Ik word nooit meer de oude, vrije, zorgeloze ik'' je ineens? Ga naar de Anacan Community. Lees dat andere mama''s ook door deze zware maar heel natuurlijke gevoelens gaan, dat het een fase van het moederschap is, en vind troost.', title_pl = 'Ciche pocieszenie Społeczności 💬', body_pl = 'Nagle dławi cię myśl „Już nigdy nie będę dawną, wolną, beztroską sobą”? Wejdź do Społeczności Anacan. Przeczytaj, że inne mamy też przechodzą przez te ciężkie, ale bardzo naturalne uczucia, że to jeden z etapów macierzyństwa, i znajdź pocieszenie.', title_pt = 'O conforto silencioso da comunidade 💬', body_pt = 'De repente sufoca-a o pensamento "nunca mais vou voltar a ser a pessoa livre e despreocupada que era"? Entre na Comunidade Anacan. Ao ler que outras mães também passam por estes sentimentos pesados, mas muito naturais, e que isto é uma fase da maternidade, vai encontrar conforto.', title_sv = 'Gemenskapens tysta tröst 💬', body_sv = 'Kväver tanken ”jag kommer aldrig att kunna bli mitt gamla, fria, bekymmerslösa jag igen” dig plötsligt? Gå in i Anacan Community. Läs att andra mammor också går igenom de här tunga men helt naturliga känslorna, att det är en fas i moderskapet, och finn tröst.', title_vi = 'Sự an ủi lặng lẽ từ Cộng đồng 💬', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ được tự do, vô tư như ngày xưa nữa" bỗng khiến mẹ nghẹt thở? Hãy vào Cộng đồng Anacan. Đọc thấy các mẹ khác cũng trải qua những cảm xúc nặng nề nhưng rất tự nhiên này, rằng đó chỉ là một giai đoạn của việc làm mẹ, mẹ sẽ tìm được sự an ủi.', title_zh = '社区里无声的安慰 💬', body_zh = '“我再也回不到从前那个自由、无忧无虑的自己了”，这个念头突然让你喘不过气？进入Anacan社区。读到其他妈妈也经历过这些沉重却非常自然的感受，知道这只是当妈妈的一个阶段，你会得到安慰。' WHERE id = 'b5cdd715-cb24-4a73-93b6-d40eb1d78c2e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Remix de palabras 🗣️', body_es = 'Junta las palabras «agua» y «leche» y crea palabras totalmente inventadas como «aguleche», y se ríe. ¡Hace remixes con su vocabulario! Únete a carcajadas a sus juegos de palabras: así es como su cerebro aprende los límites del lenguaje.', title_fr = 'Le remix des mots 🗣️', body_fr = 'Il mélange les mots « eau » et « lait » pour inventer des mots comme « laiteau » et en rit. Il fait des remix avec son vocabulaire ! Rejoignez ses jeux de langage en riant aux éclats, c''est exactement par ces essais que son cerveau découvre les limites de la langue.', title_hi = 'शब्दों का रीमिक्स 🗣️', body_hi = '‘पानी’ और ‘दूध’ को जोड़कर ‘दूधानी’ जैसे बिल्कुल गढ़े हुए शब्द बनाता है और हँसता है। वह अपनी शब्दावली का रीमिक्स कर रहा है! उसके इन शब्दों के खेल में ठहाकों के साथ शामिल होइए, उसका दिमाग ऐसे ही प्रयोगों से भाषा की सीमाएँ सीखता है।', title_id = 'Remix kata-kata 🗣️', body_id = 'Ia menggabungkan kata ''air'' dan ''susu'' menjadi kata karangan seperti ''susair'' lalu tertawa. Ia sedang me-remix kosakatanya! Ikutlah tertawa dalam permainan bahasanya, begitulah otaknya mempelajari batas-batas bahasa.', title_ja = '言葉のリミックス 🗣️', body_ja = '「おみず」と「ミルク」をくっつけて「おみるく」のような、まったく新しい言葉をつくって笑っている。語彙でリミックスしているんです！この言葉遊びに大笑いで加わりましょう。脳はこうした実験で、言葉の境界を学んでいきます。', title_ko = '단어 리믹스 🗣️', body_ko = '''물''과 ''우유''를 합쳐 ''우물유'' 같은 완전히 새로운 말을 만들고 깔깔 웃나요? 어휘를 리믹스하는 중이에요! 이 말놀이에 크게 웃으며 함께해 주세요, 뇌는 이런 시도로 언어의 경계를 배워요.', title_nl = 'Woordremix 🗣️', body_nl = 'Plakt hij ''melk'' en ''water'' aan elkaar tot een compleet verzonnen woord als ''melkwater'' en lacht hij erom? Hij remixt zijn woordenschat! Doe lachend mee met zijn taalspelletjes, zo ontdekt zijn brein de grenzen van taal.', title_pl = 'Remiks słów 🗣️', body_pl = 'Łączy słowa „woda” i „mleko” i tworzy zupełnie wymyślone słowa w stylu „mlekoda”, i się śmieje. Robi remiks swojego słownictwa! Dołącz ze śmiechem do tych gier językowych, właśnie takimi próbami jego mózg poznaje granice języka.', title_pt = 'Remix de palavras 🗣️', body_pt = 'Junta as palavras "água" e "leite" e cria palavras totalmente inventadas como "leitágua", e ri-se. Está a fazer remixes com o vocabulário! Entre nestes jogos de palavras às gargalhadas: é com testes destes que o cérebro aprende os limites da língua.', title_sv = 'Ordremix 🗣️', body_sv = 'Barnet slår ihop orden vatten och mjölk till helt påhittade ord som ”vattmjölk” och skrattar. Barnet gör en remix av sitt ordförråd! Häng med skrattande i språklekarna, det är just genom sådana försök som hjärnan lär sig språkets gränser.', title_vi = 'Bản phối lại của từ ngữ 🗣️', body_vi = 'Bé ghép từ "nước" và "sữa" thành những từ hoàn toàn tự chế như "sữa-nước" rồi bật cười? Bé đang "remix" vốn từ của mình! Hãy cười thật to cùng bé trong những trò chơi chữ này, não bé học được giới hạn của ngôn ngữ chính qua những thử nghiệm như thế.', title_zh = '词语混音 🗣️', body_zh = '把“水”和“奶”拼在一起，造出“奶水水”这种完全编出来的词，还哈哈大笑。宝宝在给词汇做“混音”！笑着加入宝宝的语言游戏吧，大脑正是通过这样的尝试来学习语言的边界。' WHERE id = 'dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una explosión de amor repentina 🫂', body_es = 'El niño que por la mañana te decía «vete», al meterse en la cama te rodea el cuello con fuerza y te dice «te quiero muchísimo». ¡Esa es la paradoja de la maternidad! Respira ese aliento cálido y deja que todo el cansancio del día se vaya volando.', title_fr = 'Une explosion d''amour soudaine 🫂', body_fr = 'L''enfant qui vous disait « Va-t''en » ce matin vous serre fort le cou au moment du coucher en disant « Je t''aime gros comme le monde ». Voilà le paradoxe de la maternité ! Respirez ce souffle chaud et laissez toute la fatigue de la journée s''envoler.', title_hi = 'अचानक प्यार का विस्फोट 🫂', body_hi = 'सुबह जिसने आपसे ‘जाओ’ कहा था, वही बच्चा बिस्तर में जाते समय बाहें गले में कसकर डालकर कहता है, ‘मैं तुमसे दुनिया जितना प्यार करता हूँ।’ यही है माँ बनने का विरोधाभास! उस गर्म साँस को अपने अंदर भर लीजिए और दिन की सारी थकान उड़ जाने दीजिए।', title_id = 'Ledakan cinta tiba-tiba 🫂', body_id = 'Anak yang pagi tadi menyuruh Anda ''pergi'', saat naik ke tempat tidur melingkarkan lengannya erat di leher Anda dan berkata ''Aku sayang Mama seluas dunia''. Itulah paradoks menjadi ibu! Hirup napasnya yang hangat dan biarkan semua lelah hari ini terbang pergi.', title_ja = '不意打ちの愛の爆発 🫂', body_ja = '朝はあなたに「あっち行って」と言っていた子が、ベッドに入ると首にぎゅっと腕をまわして「世界でいちばん大好き」と言う。ほら、これがママ業のパラドックス！その温かい息を吸いこんで、一日の疲れを全部飛ばしてしまいましょう。', title_ko = '갑작스러운 사랑 폭발 🫂', body_ko = '아침엔 ''엄마 저리 가''라던 아이가 잠자리에 들며 목을 꼭 끌어안고 ''세상만큼 사랑해''라고 하나요? 이게 엄마가 된다는 것의 역설이에요! 그 따뜻한 숨결을 들이마시고 하루의 피로를 모두 날려 보내세요.', title_nl = 'Een plotselinge liefdesuitbarsting 🫂', body_nl = 'Het kind dat ''s ochtends ''ga weg'' tegen je zei, slaat bij het slapengaan zijn armen stevig om je nek en zegt: ''Ik hou van je tot de maan en terug.'' Kijk, dat is de paradox van het moederschap! Adem die warme adem in en laat alle vermoeidheid van de dag wegvliegen.', title_pl = 'Nagły wybuch miłości 🫂', body_pl = 'Dziecko, które rano mówiło ci „idź sobie”, w łóżku mocno obejmuje cię za szyję i mówi: „Kocham cię najbardziej na świecie”. Oto paradoks macierzyństwa! Wdychaj ten ciepły oddech i pozwól, by całe zmęczenie dnia odleciało.', title_pt = 'Explosão de amor repentina 🫂', body_pt = 'A criança que de manhã lhe disse "vai-te embora", ao deitar-se põe-lhe os braços à volta do pescoço com força e diz "Amo-te mais do que tudo". Pois é, este é o paradoxo da maternidade! Respire aquele hálito quente e deixe todo o cansaço do dia desaparecer.', title_sv = 'En plötslig kärleksexplosion 🫂', body_sv = 'Barnet som på morgonen sa ”gå” till dig slår armarna hårt om din hals när det kommer i säng och säger ”Jag älskar dig mer än allt i världen”. Titta, det är moderskapets paradox! Andas in den varma andedräkten och låt all dagens trötthet flyga bort.', title_vi = 'Tình yêu bùng nổ bất chợt 🫂', body_vi = 'Đứa trẻ sáng nay bảo mẹ "Mẹ đi đi" giờ lên giường lại vòng tay ôm chặt cổ mẹ: "Con yêu mẹ nhiều như cả thế giới". Đó chính là nghịch lý của việc làm mẹ! Hãy hít thật sâu hơi thở ấm áp ấy và để mọi mệt mỏi trong ngày bay đi.', title_zh = '突然爆发的爱 🫂', body_zh = '早上还对你说“走开”的孩子，上床时却紧紧搂住你的脖子说：“我爱你，比全世界还爱。”看，这就是当妈妈的矛盾！深深吸一口那份温暖的气息，让一天的疲惫都飞走吧。' WHERE id = '4d3c3b0d-80ec-45f4-815f-fb2e6cc34948' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mamá, vete de aquí! 💔', body_es = 'Cuando no consigue lo que quiere, te mira y dice: «¡No te quiero, vete de aquí!». Que no se te rompa el corazón. Todavía no sabe gestionar su rabia. No te lo tomes como algo personal: dile «Estoy aquí, hablamos cuando te calmes» y dale espacio para vivir sus emociones.', title_fr = 'Maman, va-t''en ! 💔', body_fr = 'Quand il n''obtient pas ce qu''il veut, il vous regarde et dit « Je veux pas de toi, va-t''en ! ». Ne vous laissez pas blesser. Il ne sait pas encore gérer sa colère. Ne le prenez pas personnellement, dites « Je suis là, on parlera quand tu seras calmé » et laissez-lui de l''espace pour vivre ses émotions.', title_hi = '‘माँ, यहाँ से जाओ!’ 💔', body_hi = 'जब मन का कुछ न हो, तो आपकी ओर देखकर कहता है, ‘मुझे तुम नहीं चाहिए, यहाँ से जाओ!’ दिल मत तोड़िए। उसे अभी नहीं पता कि गुस्सा कैसे सँभाले। इसे दिल पर मत लीजिए, ‘मैं यहीं हूँ, जब तुम शांत हो जाओगे, तब बात करेंगे’ कहकर उसे अपनी भावनाएँ जीने की जगह दीजिए।', title_id = 'Mama, pergi sana! 💔', body_id = 'Saat keinginannya tak terpenuhi, ia menatap Anda dan berkata ''Aku nggak mau Mama, pergi sana!''. Jangan sakit hati. Ia belum tahu cara mengendalikan amarahnya. Jangan dimasukkan ke hati, katakan ''Mama di sini, kita bicara kalau kamu sudah tenang'', dan beri ia ruang untuk merasakan emosinya.', title_ja = '「ママ、あっち行って！」 💔', body_ja = '思いどおりにならないと、あなたを見て「ママなんていらない、あっち行って！」と言う。傷つかないで。まだ怒りをどうコントロールすればいいかわからないんです。自分へのことと受けとめず、「ここにいるよ、落ち着いたらお話ししようね」と言って、気持ちを感じるための場所をあげましょう。', title_ko = '엄마, 저리 가! 💔', body_ko = '원하는 대로 안 되면 엄마를 보며 ''엄마 싫어, 저리 가!''라고 하나요? 상처받지 마세요. 아직 화를 다루는 법을 모르는 거예요. 마음에 담아 두지 말고 ''엄마 여기 있어, 진정되면 이야기하자''라며 감정을 느낄 공간을 주세요.', title_nl = 'Mama, ga weg! 💔', body_nl = 'Krijgt hij zijn zin niet, dan kijkt hij je aan en zegt: ''Ik wil jou niet, ga weg!'' Laat je hart niet breken. Hij weet nog niet hoe hij met zijn boosheid moet omgaan. Neem het niet persoonlijk, zeg ''Ik ben hier, we praten als je rustig bent'' en geef hem ruimte om zijn gevoelens te voelen.', title_pl = 'Mamo, idź sobie! 💔', body_pl = 'Gdy coś idzie nie po jego myśli, patrzy na ciebie i mówi: „Nie chcę cię, idź sobie!”. Nie bierz tego do serca. Nie umie jeszcze panować nad złością. Nie traktuj tego osobiście, powiedz: „Jestem tutaj, porozmawiamy, gdy się uspokoisz”, i daj mu przestrzeń na przeżycie emocji.', title_pt = 'Mãe, vai-te embora! 💔', body_pt = 'Quando não consegue o que quer, olha para si e diz "Não te quero, vai-te embora!". Não fique de coração partido. Ainda não sabe gerir a raiva. Não leve a peito: diga "Estou aqui, falamos quando estiveres mais calmo" e dê-lhe espaço para viver as emoções.', title_sv = 'Mamma, gå härifrån! 💔', body_sv = 'När barnet inte får som det vill tittar det på dig och säger ”Jag vill inte ha dig, gå härifrån!”. Bli inte sårad. Barnet vet ännu inte hur det ska hantera sin ilska. Ta det inte personligt, säg ”Jag är här, vi pratar när du har lugnat dig” och ge barnet utrymme att känna sina känslor.', title_vi = '"Mẹ đi đi!" 💔', body_vi = 'Khi không được như ý, bé nhìn mẹ và nói "Con không cần mẹ, mẹ đi đi!". Đừng buồn lòng. Bé chưa biết kiểm soát cơn giận. Đừng để bụng, hãy nói "Mẹ ở đây, khi nào con bình tĩnh mình nói chuyện nhé" và cho bé không gian để trải qua cảm xúc của mình.', title_zh = '“妈妈，走开！” 💔', body_zh = '没如愿时，看着你说：“我不要你，走开！”别伤心。宝宝还不知道怎么管理自己的怒气。别往心里去，说一句“我就在这里，等你平静下来我们再聊”，给宝宝经历情绪的空间。' WHERE id = '50186ca0-d65c-4eb2-80df-487222e57b43' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El abogado del súper 🛒', body_es = 'En el súper, en lugar de tirarse al suelo por un caramelo, negocia: «Si lo compramos, en casa me como la sopa». ¡Enhorabuena, tu pequeño abogado está creciendo! Y para no olvidar nada, ten abierta la Lista de la compra para no desviarte del objetivo mientras discutes con él.', title_fr = 'L''avocat du supermarché 🛒', body_fr = 'Au supermarché, au lieu de se jeter par terre pour des bonbons, il négocie : « Si on achète ça, je mangerai ma soupe à la maison. » Félicitations, votre petit avocat grandit ! Et contre les oublis, gardez la Liste de courses ouverte, pour ne pas perdre de vue l''essentiel pendant que vous débattez avec lui.', title_hi = 'बाज़ार का वकील 🛒', body_hi = 'बाज़ार में टॉफ़ी के लिए ज़मीन पर लोटने के बजाय मोलभाव करता है, ‘यह ले लें, तो घर पर मैं अपना सूप खा लूँगा।’ बधाई हो, आपका नन्हा वकील बड़ा हो रहा है! और भूलने से बचने के लिए शॉपिंग लिस्ट खुली रखिए, ताकि उससे बहस में आप असली मकसद से न भटकें।', title_id = 'Pengacara di supermarket 🛒', body_id = 'Di supermarket, alih-alih menjatuhkan diri ke lantai demi permen, ia menawar: ''Kalau kita beli ini, aku makan supku di rumah''. Selamat, pengacara kecil Anda sedang tumbuh! Untuk melawan lupa, biarkan Daftar Belanja tetap terbuka agar tidak melenceng dari tujuan utama saat berdebat dengannya.', title_ja = 'スーパーの弁護士 🛒', body_ja = 'スーパーでお菓子をねだって床に寝ころぶ代わりに「これ買ってくれたら、おうちでスープ食べるよ」と交渉してくる。おめでとうございます、小さな弁護士さんが育っています！買い忘れ防止に「買い物リスト」を開いておけば、交渉中も本来の目的を見失いません。', title_ko = '마트의 꼬마 변호사 🛒', body_ko = '마트에서 사탕 때문에 바닥에 드러눕는 대신 ''이거 사 주면 집에서 수프 먹을게''라며 흥정하나요? 축하해요, 꼬마 변호사가 자라고 있어요! 협상하다 원래 목적을 잊지 않도록 쇼핑 목록은 열어 두세요.', title_nl = 'Advocaat in de supermarkt 🛒', body_nl = 'In plaats van zich in de supermarkt op de grond te gooien voor snoep, onderhandelt hij: ''Als we dit kopen, eet ik thuis mijn soep op.'' Gefeliciteerd, je kleine advocaat wordt groot! Houd tegen vergeetachtigheid het Boodschappenlijstje open, zodat je tijdens de discussie je hoofddoel niet uit het oog verliest.', title_pl = 'Sklepowy adwokat 🛒', body_pl = 'Zamiast rzucać się na ziemię w sklepie o cukierki, targuje się: „Jak to kupimy, w domu zjem zupę”. Gratulacje, twój mały adwokat rośnie! A na zapominalstwo trzymaj otwartą Listę zakupów, żeby podczas negocjacji nie zboczyć z głównego celu.', title_pt = 'O advogado do supermercado 🛒', body_pt = 'No supermercado, em vez de se atirar ao chão por um rebuçado, negoceia: "Se comprarmos isto, como a sopa em casa". Parabéns, o seu pequeno advogado está a crescer! E contra os esquecimentos, mantenha a Lista de Compras aberta para não perder o objetivo principal enquanto discute com ele.', title_sv = 'Butiksadvokaten 🛒', body_sv = 'Istället för att kasta sig på golvet för godis i butiken förhandlar barnet: ”Om vi köper det här äter jag upp min soppa hemma.” Grattis, din lilla advokat växer! Och mot glömskan, ha Inköpslistan öppen så att du inte tappar huvudmålet medan ni diskuterar.', title_vi = '"Luật sư" ở siêu thị 🛒', body_vi = 'Ở siêu thị, thay vì lăn ra đất đòi kẹo, bé lại mặc cả: "Nếu mua cái này, về nhà con sẽ ăn hết súp". Chúc mừng, "luật sư" nhí của mẹ đang lớn! Còn để khỏi quên đồ, hãy mở sẵn Danh sách mua sắm để không lạc khỏi mục tiêu chính khi đang tranh luận với bé.', title_zh = '超市里的小律师 🛒', body_zh = '在超市里不再为糖果躺地打滚，而是讨价还价：“买了这个，我回家就喝汤。”恭喜，你家的小律师在长大！为了对付健忘，让购物清单一直开着，和宝宝讨价还价时也不会偏离主要目标。' WHERE id = 'ee0e20bd-35e2-417c-adfc-d1000ee7da40' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un tsunami en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de crear un pequeño tsunami. Deja que el agua salpique. Ese efecto imán, místico y que absorbe energía, del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'Tsunami dans la baignoire 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu pour créer un petit tsunami. Laissez l''eau éclabousser. L''effet magnétique, presque magique, de l''eau qui absorbe l''énergie emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'बाथटब में सुनामी 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, एक छोटी सुनामी बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए। पानी का वह रहस्यमयी, ऊर्जा सोखने वाला चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Tsunami di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat tsunami kecil. Biarkan air memercik ke mana-mana. Efek magnet air yang ajaib dan menyerap energi akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = 'お風呂の津波 🌊', body_ja = 'お風呂はもうきれいにするためではなく、小さな津波をつくる遊びです。水しぶきが飛んでもいいんです。お湯のふしぎで、エネルギーを吸いとる磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '욕조 속 쓰나미 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 작은 쓰나미 만들기 놀이예요. 물이 사방으로 튀어도 괜찮아요. 에너지를 흡수하는 물의 신비한 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'Tsunami in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met een kleine tsunami. Laat het water maar spetteren. Het mystieke, energie opnemende magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Tsunami w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w małe tsunami. Niech woda chlapie dookoła. Tajemniczy, pochłaniający energię magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia i spłynie z nim do kanalizacji.', title_pt = 'Tsunami na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer pequenos tsunamis. Deixe a água salpicar à volta. O efeito magnético, místico e que absorve energia da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Tsunami i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att skapa en liten tsunami. Låt vattnet stänka. Vattnets mystiska, energiupptagande magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Sóng thần trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo ra một trận sóng thần nhỏ. Cứ để nước bắn tung tóe. Sức hút huyền bí, hút đi năng lượng của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '浴缸里的海啸 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起小海啸的游戏。让水花四溅吧。水那种神奇的、吸走能量的磁力效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = '2ee42120-6dce-4972-a1f5-41636027a46e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El derecho de mamá a la pereza 🍕', body_es = '¿Hoy te dan ganas de gritar por todo? ¿La casa está patas arriba? Olvídate de limpiar y no enciendas el fuego. Pide una pizza o lo más sencillo que haya. Rompe la ilusión de la madre perfecta: tu salud mental vale mucho más que la comida casera.', title_fr = 'Le droit à la paresse de maman 🍕', body_fr = 'Aujourd''hui, vous avez envie de crier sur tout ? La maison est sens dessus dessous ? Laissez tomber le ménage, n''allumez pas les fourneaux. Commandez une pizza ou ce qu''il y a de plus simple. Brisez l''illusion de la maman parfaite : votre santé psychologique vaut bien plus qu''un repas fait maison.', title_hi = 'माँ का आलस का हक 🍕', body_hi = 'आज हर बात पर चिल्लाने का मन है? घर बिखरा पड़ा है? सफ़ाई छोड़िए, चूल्हा मत जलाइए। बाहर से पिज़्ज़ा या जो भी सबसे आसान हो, मँगवा लीजिए। परफ़ेक्ट माँ का भ्रम तोड़िए, आपका मानसिक स्वास्थ्य घर के खाने से कहीं ज़्यादा कीमती है।', title_id = 'Hak Ibu untuk bermalas-malasan 🍕', body_id = 'Hari ini ingin berteriak pada segala hal? Rumah berantakan? Lupakan bersih-bersih, jangan nyalakan kompor. Pesan pizza atau apa saja yang paling mudah. Patahkan ilusi ibu sempurna, kesehatan jiwa Anda jauh lebih berharga daripada masakan rumahan.', title_ja = 'ママのなまける権利 🍕', body_ja = '今日は何にでも叫びたくなる？家はぐちゃぐちゃ？掃除はやめて、コンロに火もつけないで。ピザかいちばん手軽なものをデリバリーしましょう。完璧なママという幻想をこわして。あなたの心の健康は、手料理よりずっと大切です。', title_ko = '엄마의 게으를 권리 🍕', body_ko = '오늘 모든 것에 소리치고 싶나요? 집은 엉망인가요? 청소는 잊고 불도 켜지 마세요. 피자나 가장 간단한 걸 배달시키세요. 완벽한 엄마라는 환상은 깨 버리세요, 엄마의 마음 건강이 집밥보다 훨씬 소중해요.', title_nl = 'Mama''s recht op luiheid 🍕', body_nl = 'Wil je vandaag tegen alles schreeuwen? Is het huis een puinhoop? Laat het schoonmaken zitten en zet het fornuis niet aan. Bestel een pizza of wat het makkelijkst is. Doorbreek de illusie van de perfecte moeder: je mentale gezondheid is veel meer waard dan zelfgekookt eten.', title_pl = 'Mama ma prawo do lenistwa 🍕', body_pl = 'Dziś chce ci się krzyczeć na wszystko? W domu totalny bałagan? Odpuść sprzątanie, nie włączaj kuchenki. Zamów pizzę albo cokolwiek najprostszego. Rozbij iluzję idealnej mamy, twoje zdrowie psychiczne jest dużo cenniejsze niż domowy obiad.', title_pt = 'O direito da mãe à preguiça 🍕', body_pt = 'Hoje apetece-lhe gritar com tudo? A casa está um caos? Esqueça a limpeza e não acenda o fogão. Encomende uma pizza ou o que houver de mais simples. Quebre a ilusão da mãe perfeita: a sua saúde psicológica vale muito mais do que comida caseira.', title_sv = 'Mammas rätt att vara lat 🍕', body_sv = 'Vill du skrika åt allt i dag? Är hemmet i kaos? Strunta i städningen och sätt inte på spisen. Beställ pizza eller det enklaste som finns. Krossa illusionen om den perfekta mamman, din psykiska hälsa är mycket mer värd än hemlagad mat.', title_vi = 'Quyền được lười của mẹ 🍕', body_vi = 'Hôm nay mẹ muốn hét lên với mọi thứ? Nhà cửa bừa bộn? Kệ việc dọn dẹp, đừng bật bếp. Hãy gọi pizza hoặc món gì dễ nhất. Phá bỏ ảo tưởng về người mẹ hoàn hảo, sức khỏe tinh thần của mẹ quý giá hơn nhiều so với bữa cơm nhà.', title_zh = '妈妈有偷懒的权利 🍕', body_zh = '今天看什么都想吼？家里一团乱？别管打扫了，也别开火做饭。点个披萨或者最简单的外卖。打破“完美妈妈”的幻象，你的心理健康比家常饭重要得多。' WHERE id = '3a758cd5-028f-4ac8-be02-5dda6a95b453' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad de servirse solo 💧', body_es = 'Se servirá él solito el agua de la jarra grande al vaso pequeño. El agua cae a la mesa y de ahí al suelo. Pero mira esas manitas que han cogido un trapo e intentan limpiarlo. Aprende responsabilidad equivocándose: ese caos es el desarrollo en sí.', title_fr = 'L''entêtement de verser tout seul 💧', body_fr = 'Il tient absolument à verser lui-même l''eau de la grande carafe dans le petit gobelet. L''eau se renverse sur la table, puis par terre. Mais regardez ses petites mains qui attrapent le chiffon pour essayer de nettoyer. Il apprend la responsabilité en se trompant, ce chaos, c''est le développement lui-même.', title_hi = 'खुद डालने की ज़िद 💧', body_hi = 'बड़े जग से छोटे गिलास में पानी उसे खुद ही डालना है। पानी मेज़ पर और वहाँ से फ़र्श पर गिर जाता है। पर उन छोटे हाथों को देखिए जो कपड़ा लेकर सब साफ़ करने की कोशिश कर रहे हैं। वह गलतियों से ज़िम्मेदारी सीख रहा है, यह अफ़रा-तफ़री ही विकास है।', title_id = 'Ngotot menuang sendiri 💧', body_id = 'Ia bersikeras menuang air sendiri dari teko besar ke gelas kecil. Air tumpah ke meja, lalu ke lantai. Tapi lihat tangan kecilnya yang mengambil lap dan berusaha membersihkannya. Ia belajar tanggung jawab dari kesalahannya, kekacauan itu adalah perkembangan itu sendiri.', title_ja = '自分で注ぎたい 💧', body_ja = '大きなピッチャーから小さなコップへ、どうしても自分でお水を注ぎたい。お水はテーブルに、そして床へとこぼれます。でも、ふきんを持ってきて一生けんめい拭こうとする小さな手を見てあげて。失敗しながら責任を学んでいます。そのカオスこそが成長そのものです。', title_ko = '''내가 따를 거야'' 고집 💧', body_ko = '큰 물병에서 작은 컵으로 물을 꼭 자기가 따르겠다더니 식탁에, 바닥에 쏟았나요? 그래도 걸레를 집어 닦으려는 그 작은 손을 보세요. 실수하면서 책임감을 배우는 중이에요, 그 혼돈이 바로 성장이에요.', title_nl = 'Per se zelf inschenken 💧', body_nl = 'Hij moet en zal zelf water uit de grote kan in een klein bekertje schenken. Het water loopt over de tafel en zo op de grond. Maar kijk eens naar die kleine handjes die een doekje pakken om het op te ruimen. Hij leert verantwoordelijkheid door fouten te maken, die chaos is ontwikkeling zelf.', title_pl = 'Upór „Sam naleję” 💧', body_pl = 'Koniecznie chce sam nalać wody z dużego dzbanka do małego kubeczka. Woda rozlewa się na stół, a stamtąd na podłogę. Ale spójrz na te małe rączki, które chwyciły ściereczkę i próbują wytrzeć. Uczy się odpowiedzialności na błędach, ten chaos to sam rozwój.', title_pt = 'A teimosia de servir sozinho 💧', body_pt = 'Quer mesmo deitar sozinho a água do jarro grande para o copo pequeno. A água cai na mesa e daí para o chão. Mas olhe para aquelas mãozinhas a pegar no pano para tentar limpar. Está a aprender a ser responsável com os erros: esse caos é o próprio desenvolvimento.', title_sv = 'Envisheten att hälla upp själv 💧', body_sv = 'Barnet ska absolut hälla vatten själv från den stora kannan till det lilla glaset. Vattnet hamnar på bordet och därifrån på golvet. Men titta på de små händerna som tar trasan och försöker torka upp. Barnet lär sig ansvar genom misstag, det kaoset är själva utvecklingen.', title_vi = 'Bướng bỉnh đòi tự rót 💧', body_vi = 'Bé nhất định tự rót nước từ bình lớn vào chiếc cốc nhỏ. Nước đổ ra bàn, rồi xuống sàn. Nhưng hãy nhìn đôi bàn tay nhỏ đang cầm khăn cố lau chỗ đó. Bé đang học trách nhiệm qua chính lỗi sai của mình, sự hỗn loạn ấy chính là sự phát triển.', title_zh = '非要自己倒水 💧', body_zh = '非要自己从大水壶往小杯子里倒水。水洒到桌上，又流到地上。可你看看那双拿起抹布、努力想擦干净的小手。宝宝正在从错误中学会责任，那片混乱本身就是成长。' WHERE id = 'd683b351-38a0-49ed-a8b1-b2fe98cd3d08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Conociendo las tijeras pequeñas ✂️', body_es = '¿Intenta cortar papel con unas tijeras de plástico seguras para niños? ¡Es un ejercicio estupendo para la motricidad fina! Anótalo sin falta en el Seguimiento del desarrollo.', title_fr = 'Découvrir les petits ciseaux ✂️', body_fr = 'Il essaie de découper du papier avec des ciseaux en plastique sans danger pour enfants ? C''est un excellent exercice de motricité fine ! Notez-le absolument dans le Suivi de développement.', title_hi = 'छोटी कैंची से पहचान ✂️', body_hi = 'बच्चों की सुरक्षित प्लास्टिक कैंची से कागज़ काटने की कोशिश करता है? यह बारीक मोटर स्किल्स के लिए शानदार अभ्यास है! इसे ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Berkenalan dengan gunting kecil ✂️', body_id = 'Ia mencoba menggunting kertas dengan gunting plastik khusus anak yang aman? Latihan yang hebat untuk motorik halus! Pastikan mencatatnya di Pelacak Perkembangan.', title_ja = '小さなはさみとの出会い ✂️', body_ja = '子ども用の安全なプラスチックのはさみで、紙を切ろうとしている？指先の力のすばらしい練習です！ぜひ「発達トラッカー」に記録しましょう。', title_ko = '작은 가위와 첫 만남 ✂️', body_ko = '어린이용 안전 플라스틱 가위로 종이를 자르려 하나요? 소근육에 아주 좋은 연습이에요! 성장 기록에 꼭 남겨 두세요.', title_nl = 'Kennismaken met een kinderschaartje ✂️', body_nl = 'Probeert hij met een veilig plastic kinderschaartje papier te knippen? Een geweldige oefening voor de fijne motoriek! Noteer het zeker in de Groeitracker.', title_pl = 'Pierwsze nożyczki ✂️', body_pl = 'Próbuje ciąć papier bezpiecznymi plastikowymi nożyczkami dla dzieci? To świetne ćwiczenie motoryki małej! Koniecznie zapisz to w Śledzeniu rozwoju.', title_pt = 'A descoberta da tesourinha ✂️', body_pt = 'Tenta cortar papel com uma tesoura de plástico segura para crianças? É um ótimo exercício para a motricidade fina! Não deixe de o registar no Registo de Crescimento.', title_sv = 'Första mötet med små saxar ✂️', body_sv = 'Försöker barnet klippa papper med en säker plastsax för barn? Utmärkt träning för finmotoriken! Anteckna det absolut i Utvecklingsspåraren.', title_vi = 'Làm quen với chiếc kéo nhỏ ✂️', body_vi = 'Bé cố cắt giấy bằng chiếc kéo nhựa an toàn cho trẻ? Đây là bài tập tuyệt vời cho kỹ năng vận động tinh! Hãy nhớ ghi lại trong Theo dõi phát triển.', title_zh = '认识小剪刀 ✂️', body_zh = '想用儿童安全塑料剪刀剪纸？这是锻炼精细动作的好方法！一定要记在发育追踪里。' WHERE id = '746ce0d9-945c-4d05-9518-1097d9f22fcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del «¡Mírame!» 👀', body_es = '¿Cuando miras el móvil o haces otra cosa, viene y te gira la cara hacia él? Quiere toda tu atención. Mírale a los ojos y hazle sentir que le escuchas.', title_fr = 'L''insistance du « Regarde-moi ! » 👀', body_fr = 'Quand vous regardez votre téléphone ou faites autre chose, il vient tourner votre visage vers lui ? Il veut toute votre attention. Regardez-le dans les yeux pour lui faire sentir que vous l''écoutez.', title_hi = '‘मुझे देखो!’ की ज़िद 👀', body_hi = 'जब आप फ़ोन या किसी और काम में लगी होती हैं, वह आकर आपका चेहरा अपनी ओर घुमा देता है? उसे पूरा ध्यान चाहिए। आँख मिलाकर उसे महसूस कराइए कि आप उसे सुन रही हैं।', title_id = 'Ngotot ''Lihat aku!'' 👀', body_id = 'Saat Anda melihat ponsel atau mengerjakan hal lain, ia datang dan memalingkan wajah Anda ke arahnya? Ia ingin perhatian penuh. Tatap matanya dan buat ia merasa didengarkan.', title_ja = '「見て！」の意地 👀', body_ja = 'あなたがスマホやほかのことに目を向けていると、やってきてあなたの顔を自分のほうへ向ける？まるごとの注目がほしいんです。目を合わせて、ちゃんと聞いていると感じさせてあげましょう。', title_ko = '''나 좀 봐!'' 고집 👀', body_ko = '엄마가 휴대폰이나 다른 일을 보고 있으면 와서 엄마 얼굴을 자기 쪽으로 돌리나요? 온전한 관심을 원하는 거예요. 눈을 맞추며 듣고 있다는 걸 느끼게 해 주세요.', title_nl = 'De ''Kijk naar mij!''-koppigheid 👀', body_nl = 'Draait hij je gezicht naar zich toe als jij op je telefoon kijkt of met iets anders bezig bent? Hij wil je volle aandacht. Maak oogcontact en laat merken dat je naar hem luistert.', title_pl = 'Upór „Patrz na mnie!” 👀', body_pl = 'Gdy patrzysz w telefon albo zajmujesz się czymś innym, podchodzi i odwraca twoją twarz do siebie? Chce pełnej uwagi. Nawiąż kontakt wzrokowy, żeby poczuł, że go słuchasz.', title_pt = 'A teimosia do "Olha para mim!" 👀', body_pt = 'Quando está a olhar para o telemóvel ou para outra coisa, ele vem e vira-lhe a cara para ele? Quer atenção total. Faça contacto visual e mostre-lhe que o está a ouvir.', title_sv = 'Envisheten ”Titta på mig!” 👀', body_sv = 'Kommer barnet och vänder ditt ansikte mot sig när du tittar på telefonen eller gör något annat? Barnet vill ha full uppmärksamhet. Ta ögonkontakt och låt barnet känna att du lyssnar.', title_vi = 'Sự bướng bỉnh "Mẹ nhìn con này!" 👀', body_vi = 'Khi mẹ nhìn điện thoại hay làm việc khác, bé đến xoay mặt mẹ về phía mình? Bé muốn mẹ chú ý trọn vẹn. Hãy nhìn vào mắt bé để bé cảm nhận được mẹ đang lắng nghe.', title_zh = '“看我！”的坚持 👀', body_zh = '你看手机或忙别的事时，宝宝就过来把你的脸转向自己？宝宝想要你全部的注意力。和宝宝对视，让宝宝感受到你在认真听。' WHERE id = 'd01a4de6-1799-4ace-b8f9-b22ea720b143' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En Cuentos inteligentes crea una historia especial cuyo héroe sea tu peque: «El pequeño valiente que llena el mundo de color con unas tijeras mágicas».', body_fr = 'Dans les Contes intelligents, créez une histoire spéciale dont votre enfant est le héros : « Le petit courageux qui colorie le monde avec des ciseaux magiques ».', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: ‘जादुई कैंची से दुनिया को रंगने वाला बहादुर नन्हा।’', body_id = 'Di Dongeng Pintar, ciptakan cerita istimewa dengan anak Anda sebagai tokohnya: ''Si kecil pemberani yang mewarnai dunia dengan gunting ajaib''.', body_ja = '「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう：「魔法のはさみで世界をカラフルにする勇敢なおちびさん」。', body_ko = '스마트 동화에서 아이가 주인공인 특별한 이야기를 만들어 보세요: ''마법 가위로 세상을 색칠하는 용감한 꼬마''.', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kind als held: ''Het dappere kleintje dat de wereld kleurt met een magische schaar.''', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Odważny maluch, który koloruje świat magicznymi nożyczkami”.', body_pt = 'Crie nas Histórias Inteligentes uma história especial com o seu filho como herói: "O pequeno corajoso que pinta o mundo com uma tesoura mágica".', body_sv = 'Skapa en särskild berättelse i Smarta sagor med ditt barn som hjälte: Den modiga lilla som färglägger världen med en magisk sax.', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh một câu chuyện đặc biệt mà nhân vật chính là bé: "Cô bé/cậu bé dũng cảm tô màu thế giới bằng chiếc kéo thần kỳ".', body_zh = '在智慧童话里编一个主角是你家宝宝的专属故事：“用魔法剪刀给世界涂上颜色的勇敢小家伙”。' WHERE id = '7d3efca9-83bd-4ef7-a064-007baae56a2f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cuando doblas la ropa intenta quitártela de las manos? Ya se siente mayor. Dale una toallita y deja que te ayude.', body_fr = 'Quand vous pliez le linge, il essaie de vous le prendre des mains ? Il se sent déjà grand. Donnez-lui une petite serviette et laissez-le vous aider.', body_hi = 'आप कपड़े तह करती हैं तो वह आपके हाथ से छीनने की कोशिश करता है? वह खुद को अब बड़ा महसूस करता है। उसे एक छोटा तौलिया देकर मदद करने दीजिए।', body_id = 'Saat Anda melipat baju, ia mencoba merebutnya dari tangan Anda? Ia sudah merasa besar. Beri ia handuk kecil dan biarkan ia membantu.', body_ja = 'あなたが洗濯物をたたんでいると、手から取ろうとする？もう自分は大きいと感じているんです。小さなタオルを渡して、お手伝いさせてあげましょう。', body_ko = '엄마가 빨래를 갤 때 손에서 빼앗으려 하나요? 벌써 다 컸다고 느끼는 거예요. 작은 수건을 건네주고 돕게 해 주세요.', body_nl = 'Probeert hij de kleren uit je handen te pakken als jij de was opvouwt? Hij voelt zich al groot. Geef hem een kleine handdoek en laat hem helpen.', body_pl = 'Gdy składasz pranie, próbuje wyrywać ci je z rąk? Czuje się już duży. Daj mu mały ręcznik i pozwól pomóc.', body_pt = 'Quando dobra a roupa, tenta tirar-lha das mãos? Já se sente crescido. Dê-lhe uma toalhinha e deixe-o ajudar.', body_sv = 'Försöker barnet ta kläderna ur händerna på dig när du viker tvätt? Barnet känner sig redan stort. Ge barnet en liten handduk och låt det hjälpa till.', body_vi = 'Khi mẹ gấp quần áo, bé cố giành lấy từ tay mẹ? Bé đã thấy mình lớn rồi. Hãy đưa bé một chiếc khăn nhỏ và để bé giúp mẹ.', body_zh = '你叠衣服时，宝宝想从你手里抢过去？宝宝觉得自己已经长大了。给宝宝一条小毛巾，让宝宝来帮忙吧。' WHERE id = 'fa3aa9fa-1390-45bd-833a-86ce9790410b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te voy a contar un secreto 🤫', body_es = 'Ya en la cama, cuando se le están cerrando los ojos, de repente dice «Mamá, te voy a contar un secreto» para espantar el sueño. Oficialmente se doctoran en el arte de retrasar el sueño. Sonríe, dile «Me cuentas tu secreto en sueños» y apaga las luces con firmeza.', title_fr = 'Je vais te dire un secret 🤫', body_fr = 'Une fois au lit, au moment où ses yeux se ferment, il dit soudain « Maman, je vais te dire un secret » pour chasser le sommeil. Il est officiellement en train de passer son doctorat dans l''art de retarder le coucher. Souriez, dites « Tu me raconteras ton secret dans ton rêve » et éteignez la lumière avec fermeté.', title_hi = 'तुम्हें एक राज़ बताऊँगा 🤫', body_hi = 'बिस्तर में जाकर, आँखें बंद होने ही वाली हों कि अचानक ‘माँ, तुम्हें एक राज़ बताऊँगा’ कहकर नींद भगाने की कोशिश करता है। नींद टालने की कला में तो ये बाकायदा पीएचडी कर रहे हैं। मुस्कुराइए, ‘अपना राज़ सपने में बताना’ कहिए और पक्के इरादे से लाइटें बंद कर दीजिए।', title_id = 'Aku punya rahasia 🤫', body_id = 'Sudah di tempat tidur, matanya hampir terpejam, tiba-tiba ia berkata ''Ma, aku punya rahasia'' untuk mengusir kantuk. Dalam seni menunda tidur, mereka praktis sudah meraih gelar doktor. Tersenyumlah, katakan ''Ceritakan rahasiamu di dalam mimpi'', lalu matikan lampu dengan tegas.', title_ja = 'ひみつを教えてあげる 🤫', body_ja = 'ベッドに入って、まぶたが閉じかけたところで、急に「ママ、ひみつを教えてあげる」と言って眠気を追いはらおうとする。寝る時間を遅らせる技で、正式に博士号を取ったみたいですね。ほほえんで「ひみつは夢の中で教えてね」と言って、きっぱり明かりを消しましょう。', title_ko = '엄마한테 비밀 말해 줄게 🤫', body_ko = '침대에 누워 눈이 막 감기려는 순간 갑자기 ''엄마, 비밀 말해 줄게'' 하며 잠을 쫓으려 하나요? 잠 미루기 기술로 박사 학위를 받는 중이에요. 미소 지으며 ''비밀은 꿈속에서 말해 줘''라고 하고 단호하게 불을 끄세요.', title_nl = 'Ik vertel je een geheimpje 🤫', body_nl = 'Hij ligt in bed en zijn ogen vallen bijna dicht, als hij ineens zegt: ''Mama, ik vertel je een geheimpje'', om de slaap te verjagen. Ze promoveren officieel in de kunst van het slapen uitstellen. Glimlach, zeg ''Vertel je geheimpje maar in je droom'' en doe vastberaden het licht uit.', title_pl = 'Zdradzę ci sekret 🤫', body_pl = 'Leży w łóżku, oczy już mu się zamykają, a nagle mówi: „Mamo, zdradzę ci sekret” i próbuje odpędzić sen. W sztuce odwlekania snu dzieci oficjalnie bronią doktoratu. Uśmiechnij się, powiedz „Sekret opowiesz mi we śnie” i stanowczo zgaś światło.', title_pt = 'Vou contar-te um segredo 🤫', body_pt = 'Deita-se e, quando os olhos já se estão a fechar, diz de repente "Mãe, vou contar-te um segredo" para tentar espantar o sono. Na arte de adiar o sono, já estão oficialmente a defender o doutoramento. Sorria, diga "Contas-me o segredo no sonho" e apague as luzes com firmeza.', title_sv = 'Jag ska berätta en hemlighet 🤫', body_sv = 'I sängen, när ögonen håller på att falla ihop, säger barnet plötsligt ”Mamma, jag ska berätta en hemlighet” och försöker hålla sömnen borta. De försvarar officiellt en doktorsavhandling i konsten att skjuta upp sömnen. Le, säg ”Du kan berätta hemligheten i drömmen” och släck bestämt lampan.', title_vi = 'Con kể mẹ nghe bí mật 🤫', body_vi = 'Lên giường rồi, mắt sắp díp lại, bé bỗng nói "Mẹ ơi, con kể mẹ nghe một bí mật" để cố xua cơn buồn ngủ. Bé đang chính thức "bảo vệ luận án tiến sĩ" về nghệ thuật trì hoãn giấc ngủ. Hãy mỉm cười: "Con kể bí mật trong mơ nhé" và dứt khoát tắt đèn.', title_zh = '告诉你一个秘密 🤫', body_zh = '躺到床上，眼睛快闭上时，突然说“妈妈，我要告诉你一个秘密”，想把睡意赶跑。在拖延睡觉的艺术上，宝宝们简直能拿博士学位了。笑一笑，说“秘密到梦里再讲吧”，然后坚定地关灯。' WHERE id = '9049cae3-8dbb-4e95-8c21-0965664d904f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo la crema de la galleta 🍪', body_es = '¿Ha lamido la crema del centro de las galletas redondas y ha alineado la parte seca en el borde de la mesa? Enhorabuena: oficialmente conoces la filosofía alimentaria de los 3 años y medio. Descubre en Recetas saludables tentempiés más lógicos, pero divertidos, que le llamen la atención.', title_fr = 'Juste la crème du biscuit 🍪', body_fr = 'Il a léché la crème au milieu des biscuits ronds et aligné les parties sèches au bord de la table ? Félicitations, vous faites officiellement connaissance avec la philosophie alimentaire des 3 ans et demi. Découvrez dans les Recettes saines des collations plus logiques mais amusantes qui attireront son attention.', title_hi = 'बिस्कुट की सिर्फ़ क्रीम 🍪', body_hi = 'गोल बिस्कुटों के बीच की क्रीम चाटकर सूखे हिस्से मेज़ के किनारे सजा दिए? बधाई हो, आप आधिकारिक तौर पर साढ़े 3 साल के खाने के दर्शन से मिल चुकी हैं। सेहतमंद रेसिपी में उसका ध्यान खींचने वाले, ज़्यादा समझदारी भरे, पर मज़ेदार स्नैक्स खोजिए।', title_id = 'Hanya krim biskuitnya 🍪', body_id = 'Ia menjilat krim di tengah biskuit bundar, lalu menjajarkan bagian keringnya di pinggir meja? Selamat, Anda resmi berkenalan dengan filsafat makanan anak 3,5 tahun. Temukan camilan yang lebih masuk akal tapi tetap seru di Resep Sehat untuk menarik perhatiannya.', title_ja = 'クッキーのクリームだけ 🍪', body_ja = '丸いクッキーのまんなかのクリームだけなめて、かわいた部分はテーブルのはしに並べている？おめでとうございます、あなたは正式に3歳半の食の哲学に出会いました。「ヘルシーレシピ」で、もっと理にかなっていて、しかも楽しく食いつけるおやつを見つけましょう。', title_ko = '과자 속 크림만 쏙 🍪', body_ko = '동그란 과자 가운데 크림만 핥아 먹고 마른 부분은 식탁 가장자리에 줄 세워 놓았나요? 축하해요, 세 살 반의 음식 철학을 공식적으로 만나셨어요. 건강한 레시피에서 아이의 눈길을 끌 더 알차면서도 재미있는 간식을 찾아보세요.', title_nl = 'Alleen de crème van het koekje 🍪', body_nl = 'Heeft hij de crème uit het midden van de ronde koekjes gelikt en de droge helften op de rand van de tafel gelegd? Gefeliciteerd, je hebt officieel kennisgemaakt met de eetfilosofie van een kind van 3,5. Ontdek in Gezonde recepten logischere maar leuke tussendoortjes die zijn aandacht trekken.', title_pl = 'Sam krem z ciastka 🍪', body_pl = 'Wylizał krem ze środka okrągłych ciastek, a suche połówki ułożył na brzegu stołu? Gratulacje, oficjalnie poznałaś filozofię jedzenia 3,5-latka. Odkryj w Zdrowych przepisach bardziej sensowne, ale zabawne przekąski, które przyciągną jego uwagę.', title_pt = 'Só o creme da bolacha 🍪', body_pt = 'Lambeu o creme do meio das bolachas redondas e alinhou as partes secas na borda da mesa? Parabéns, acaba de conhecer oficialmente a filosofia alimentar dos 3 anos e meio. Descubra nas Receitas Saudáveis snacks mais sensatos, mas divertidos, que lhe captem a atenção.', title_sv = 'Bara krämen i kakan 🍪', body_sv = 'Har barnet slickat bort krämen i mitten av de runda kexen och radat upp de torra delarna på kanten av bordet? Grattis, nu har du officiellt bekantat dig med 3,5-åringens matfilosofi. Upptäck mer logiska men roliga mellanmål bland Hälsosamma recept som fångar barnets intresse.', title_vi = 'Chỉ ăn phần kem của bánh quy 🍪', body_vi = 'Bé liếm hết phần kem ở giữa những chiếc bánh quy tròn rồi xếp phần bánh khô ở mép bàn? Chúc mừng, mẹ đã chính thức làm quen với "triết lý ăn uống" của tuổi 3,5. Hãy khám phá trong Công thức lành mạnh những món ăn nhẹ hợp lý hơn nhưng vẫn vui mắt để thu hút bé.', title_zh = '只吃饼干的夹心 🍪', body_zh = '把圆饼干中间的夹心舔光，干巴巴的饼干排在桌边？恭喜，你正式认识了3岁半的饮食哲学。去健康食谱里发现更合理、但同样有趣、能吸引宝宝的小零食吧。' WHERE id = 'a097a156-cfb7-4bbb-a187-0b6a9ba7dade' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La prohibición del «¡Tú no cantes!» 🛑', body_es = 'Te has puesto a tararear la canción infantil que sonaba de fondo y al instante ha gritado: «¡Tú no cantes!». El único solista de la habitación es él, y tus intentos vocales le quitan escenario. No te ofendas: deja el escenario a este pequeño egoísta.', title_fr = 'L''interdit du « Chante pas ! » 🛑', body_fr = 'Vous avez fredonné la chanson pour enfants qui passait en fond et il a aussitôt crié : « Chante pas ! » C''est lui le seul soliste de la pièce, vos tentatives vocales empiètent sur sa scène. Ne le prenez pas mal, laissez la scène à ce petit égoïste.', title_hi = '‘तुम मत गाओ!’ की पाबंदी 🛑', body_hi = 'पीछे चल रहे बच्चों के गाने के साथ आपने गुनगुनाना शुरू किया और वह तुरंत चिल्लाया: ‘तुम मत गाओ!’ कमरे का इकलौता सोलो गायक वही है, आपकी गायकी की कोशिशें उसका मंच छोटा कर देती हैं। बुरा मत मानिए, मंच इस नन्हे स्वार्थी के लिए छोड़ दीजिए।', title_id = 'Larangan ''Mama jangan nyanyi!'' 🛑', body_id = 'Anda ikut bersenandung mengikuti lagu anak yang diputar, dan ia langsung berteriak: ''Mama jangan nyanyi!'' Dialah satu-satunya penyanyi di ruangan ini, usaha vokal Anda mempersempit panggungnya. Jangan tersinggung, serahkan panggung kepada si egois kecil ini.', title_ja = '「ママは歌わないで！」禁止令 🛑', body_ja = '流れている子どもの歌に合わせてハミングしたら、すぐに「ママは歌わないで！」と叫ばれた。部屋のソリストはこの子だけ。あなたの歌声は、この子のステージをせまくしてしまうんです。気を悪くしないで、ステージはこの小さなわがままさんにゆずりましょう。', title_ko = '''엄마는 노래하지 마!'' 금지령 🛑', body_ko = '배경에 흐르는 동요를 따라 흥얼거렸더니 바로 ''엄마는 노래하지 마!''라고 소리쳤나요? 이 방의 유일한 솔로 가수는 아이고, 엄마의 노래는 무대를 좁히는 거죠. 서운해하지 말고 무대는 이 작은 욕심쟁이에게 양보하세요.', title_nl = 'Het ''Niet zingen!''-verbod 🛑', body_nl = 'Je neuriede mee met het kinderliedje op de achtergrond en hij riep meteen: ''Niet zingen!'' Hij is de enige solist in de kamer, jouw zangpogingen maken zijn podium kleiner. Voel je niet gekwetst en laat het podium aan deze kleine egoïst.', title_pl = 'Zakaz „Nie śpiewaj!” 🛑', body_pl = 'Zanuciłaś do dziecięcej piosenki lecącej w tle, a on od razu krzyknął: „Nie śpiewaj!”. To on jest jedynym solistą w pokoju, a twoje próby wokalne zabierają mu scenę. Nie obrażaj się, zostaw scenę temu małemu egoiście.', title_pt = 'A proibição do "Não cantes!" 🛑', body_pt = 'Começou a trautear a canção infantil que tocava de fundo e ele gritou logo: "Não cantes!". O único solista do quarto é ele, e as suas tentativas vocais roubam-lhe o palco. Não se ofenda: deixe o palco a este pequeno egoísta.', title_sv = 'Förbudet ”Sjung inte!” 🛑', body_sv = 'Du nynnade med i barnlåten som spelades i bakgrunden, och barnet skrek genast: ”Sjung inte!” Barnet är rummets enda solist, och dina sångförsök gör scenen för trång. Bli inte sårad, lämna scenen åt den lilla egoisten.', title_vi = 'Lệnh cấm "Mẹ đừng hát!" 🛑', body_vi = 'Mẹ ngân nga theo bài hát thiếu nhi đang phát, và bé lập tức hét lên: "Mẹ đừng hát!". Bé là ca sĩ hát đơn duy nhất trong phòng, giọng hát của mẹ đang lấn sân khấu của bé. Đừng phật lòng, hãy nhường sân khấu cho "kẻ ích kỷ" bé nhỏ này.', title_zh = '“你别唱！”禁令 🛑', body_zh = '你跟着背景里的儿歌哼了几句，宝宝马上大喊：“你别唱！”房间里唯一的独唱家是宝宝，你的演唱抢了宝宝的舞台。别难过，把舞台让给这个小小的“自私鬼”吧。' WHERE id = 'bf046ede-b62a-43aa-8a59-9305494237e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá mirando a la pared 🛋️', body_es = 'Hay ruido en la habitación, él choca sus juguetes uno contra otro y tú solo miras una pared vacía, desconectada («zoned out»). Es el mecanismo de protección de tu cerebro. No te niegues esos 5 minutos de bloqueo: los necesitas para volver a la vida.', title_fr = 'Maman qui fixe le mur 🛋️', body_fr = 'Il y a du bruit dans la pièce, il cogne ses jouets les uns contre les autres, et vous, vous fixez simplement le mur, complètement déconnectée. C''est le mécanisme de protection de votre cerveau. Ne vous refusez pas ces 5 minutes de pause figée, vous en avez besoin pour revenir à la vie.', title_hi = 'माँ और दीवार की टकटकी 🛋️', body_hi = 'कमरे में शोर है, वह खिलौने आपस में टकरा रहा है, और आप बस खाली दीवार को देखती हुई कहीं खो गई हैं (ज़ोन्ड आउट)। यह आपके दिमाग का बचाव तंत्र है। उन 5 मिनट के ठहराव को खुद से मत छीनिए, ज़िंदगी में फिर से लौटने के लिए यह आपको चाहिए।', title_id = 'Ibu beradu tatap dengan dinding 🛋️', body_id = 'Kamar penuh kebisingan, ia membentur-benturkan mainannya, sementara kamu hanya menatap dinding kosong dan pikiranmu melayang (zoned out). Ini mekanisme perlindungan otakmu. Jangan merasa bersalah atas 5 menit membeku itu, kamu membutuhkannya untuk kembali ke kehidupan.', title_ja = 'ママ、壁とにらめっこ 🛋️', body_ja = '部屋は騒がしく、この子はおもちゃをぶつけ合い、あなたはただ空っぽの壁を見つめてぼーっとしている（zoned out）。これは脳の防衛機能です。その5分間のフリーズを自分に許してあげて。また日常に戻るために必要な時間です。', title_ko = '엄마와 벽의 눈싸움 🛋️', body_ko = '방은 시끄럽고 아이는 장난감을 서로 부딪치는데, 엄마는 멍하니 빈 벽만 보고 있나요(zoned out)? 뇌를 지키는 방어 기제예요. 그 5분간의 멈춤을 아까워하지 마세요, 다시 일상으로 돌아가려면 필요해요.', title_nl = 'Mama staart naar de muur 🛋️', body_nl = 'Er is lawaai in de kamer, hij slaat zijn speelgoed tegen elkaar, en jij staart alleen naar een lege muur, helemaal weg (zoned out). Dat is het beschermingsmechanisme van je brein. Gun jezelf die 5 minuten bevriezen, je hebt ze nodig om weer terug te komen.', title_pl = 'Mama kontra ściana 🛋️', body_pl = 'W pokoju hałas, on stuka zabawkami jedną o drugą, a ty po prostu patrzysz w pustą ścianę, całkiem wyłączona (zoned out). To mechanizm obronny twojego mózgu. Nie żałuj sobie tych 5 minut zawieszenia, potrzebujesz ich, by wrócić do życia.', title_pt = 'A mãe a olhar para a parede 🛋️', body_pt = 'Há barulho no quarto, ele bate os brinquedos uns nos outros e a mãe só está a olhar para a parede vazia, completamente desligada ("zoned out"). É o mecanismo de proteção do seu cérebro. Não negue a si própria esses 5 minutos de pausa: precisa deles para voltar à vida.', title_sv = 'Mamma stirrar in i väggen 🛋️', body_sv = 'Det är bullrigt i rummet, barnet slår ihop leksakerna, och du stirrar bara tomt in i väggen och har zonat ut (zoned out). Det är hjärnans skyddsmekanism. Unna dig de 5 minuterna av att frysa, du behöver dem för att komma tillbaka till livet.', title_vi = 'Mẹ nhìn chằm chằm vào bức tường 🛋️', body_vi = 'Trong phòng ồn ào, bé đập đồ chơi vào nhau, còn mẹ chỉ nhìn vào bức tường trống, đầu óc trống rỗng (zoned out). Đây là cơ chế tự bảo vệ của não bộ. Đừng tiếc cho mình 5 phút "đóng băng" ấy, mẹ cần nó để quay lại với cuộc sống.', title_zh = '妈妈和墙壁的对视 🛋️', body_zh = '房间里吵吵闹闹，宝宝把玩具撞来撞去，你却只是盯着空白的墙发呆（zoned out）。这是你大脑的自我保护机制。别舍不得给自己这5分钟的“冻结”时刻，你需要它才能重新回到生活里。' WHERE id = '6b819068-b681-48a9-82bf-6d4801827c9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preguntas que dejan en shock en público 😳', body_es = '¿En el autobús o en el súper ha preguntado en voz alta: «¿Por qué esta señora tiene la nariz tan grande?»? ¡Ese momento en que deseas que te trague la tierra! En lugar de hacerle callar y avergonzarle, dirige enseguida su atención a otro objeto de colores y sal de la situación con diplomacia.', title_fr = 'Questions gênantes en public 😳', body_fr = 'Dans le bus ou au supermarché, il a demandé à voix haute « Pourquoi la dame a un si gros nez ? » ? Ce moment où vous voudriez que le sol s''ouvre sous vos pieds ! Au lieu de le faire taire et de lui faire honte, détournez aussitôt son attention vers un autre objet coloré et sortez-vous de la situation avec diplomatie.', title_hi = 'सबके सामने चौंकाने वाले सवाल 😳', body_hi = 'बस या बाज़ार में ज़ोर से पूछ लिया, ‘इन आंटी की नाक इतनी बड़ी क्यों है?’ वही पल जब आप चाहती हैं कि ज़मीन फट जाए और आप उसमें समा जाएँ! उसे चुप कराकर शर्मिंदा करने के बजाय, तुरंत उसका ध्यान किसी रंगीन चीज़ की ओर ले जाइए और समझदारी से हालात से निकल आइए।', title_id = 'Pertanyaan mengejutkan di tempat umum 😳', body_id = 'Di bus atau supermarket ia bertanya keras-keras ''Kenapa hidung tante itu besar sekali?''? Momen ketika Anda ingin ditelan bumi! Daripada membungkamnya dan membuatnya malu, segera alihkan perhatiannya ke benda lain yang berwarna-warni dan keluarlah dari situasi itu dengan diplomatis.', title_ja = '人前でのびっくり質問 😳', body_ja = 'バスやスーパーで大きな声で「このおばさん、なんでお鼻がこんなに大きいの？」と聞かれた？穴があったら入りたい、あの瞬間！黙らせて恥ずかしい思いをさせる代わりに、すぐに別のカラフルなものに気をそらして、上手にその場を切りぬけましょう。', title_ko = '공공장소의 충격 질문 😳', body_ko = '버스나 마트에서 큰 소리로 ''저 아줌마 코는 왜 이렇게 커?''라고 물었나요? 땅이 꺼져 숨고 싶은 그 순간! 입을 막고 창피를 주는 대신 바로 다른 알록달록한 물건으로 관심을 돌려 슬기롭게 빠져나오세요.', title_nl = 'Schokkende vragen in het openbaar 😳', body_nl = 'Vroeg hij in de bus of de supermarkt hardop: ''Waarom heeft die mevrouw zo''n grote neus?'' Zo''n moment waarop je door de grond wilt zakken! Laat hem niet beschaamd zwijgen, maar richt zijn aandacht meteen op een ander kleurrijk voorwerp en red je diplomatiek uit de situatie.', title_pl = 'Szokujące pytania przy ludziach 😳', body_pl = 'W autobusie albo w sklepie zapytał na głos: „Dlaczego ta pani ma taki duży nos?”. Ta chwila, gdy chcesz zapaść się pod ziemię! Zamiast go uciszać i zawstydzać, od razu skieruj jego uwagę na inny kolorowy przedmiot i dyplomatycznie wybrnij z sytuacji.', title_pt = 'Perguntas chocantes em público 😳', body_pt = 'No autocarro ou no supermercado, perguntou bem alto "Porque é que aquela senhora tem o nariz tão grande?" Aquele momento em que só quer que a terra se abra! Em vez de o calar e envergonhar, desvie logo a atenção dele para outro objeto colorido e saia da situação com diplomacia.', title_sv = 'Chockerande frågor bland folk 😳', body_sv = 'Frågade barnet högt på bussen eller i butiken: ”Varför har den där damen så stor näsa?” Det är stunden då du önskar att marken öppnade sig och du kunde krypa ner! Istället för att tysta och skämma ut barnet, led genast uppmärksamheten till ett annat färgglatt föremål och ta dig diplomatiskt ur situationen.', title_vi = 'Những câu hỏi gây sốc nơi công cộng 😳', body_vi = 'Trên xe buýt hay ở siêu thị, bé hỏi thật to: "Sao mũi cô kia to thế?". Khoảnh khắc mẹ chỉ mong có cái lỗ để chui xuống! Thay vì bắt bé im và làm bé xấu hổ, hãy lập tức chuyển sự chú ý của bé sang một đồ vật nhiều màu sắc khác và khéo léo thoát khỏi tình huống.', title_zh = '公共场合的惊人提问 😳', body_zh = '在公交车上或超市里大声问：“这个阿姨的鼻子为什么这么大？”那一刻你真恨不得找个地缝钻进去！与其让宝宝闭嘴、让宝宝难堪，不如马上把宝宝的注意力转到另一样彩色的东西上，巧妙地化解尴尬。' WHERE id = '6b9b4528-1015-4f69-940f-0bb0951b3bab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las condiciones sin lógica de papá 🎲', body_es = 'Por la noche corretea por casa para no ponerse el pijama. Papá lanza un juego absurdo: «¿A ver si eres capaz de ponerte este pijama con los ojos cerrados?». ¡Y bum! El peque se lo ha puesto sin darse cuenta. A estos juegos de papá sin lógica pero eficaces solo cabe aplaudirles desde fuera.', title_fr = 'Les conditions absurdes de papa 🎲', body_fr = 'Le soir, il court dans la maison pour ne pas mettre son pyjama. Son papa lance un jeu absurde : « Voyons si tu arrives à mettre ce pyjama les yeux fermés ? » Et boum ! L''enfant s''est habillé sans s''en rendre compte. Ces jeux sans logique mais efficaces des papas méritent juste des applaudissements.', title_hi = 'पापा की बेतुकी शर्तें 🎲', body_hi = 'रात को पजामा न पहनने के लिए घर में दौड़ता है। पापा एक बेतुका खेल छेड़ते हैं: ‘देखें, क्या तुम यह पजामा आँखें बंद करके पहन पाओगे?’ और धड़ाम! बच्चे ने बिना जाने पहन लिया। पापाओं के इन बेतुके, पर कारगर खेलों के लिए बस दूर से तालियाँ बनती हैं।', title_id = 'Syarat konyol Ayah 🎲', body_id = 'Malam hari ia berlarian di rumah agar tidak memakai piyama. Ayahnya melontarkan permainan absurd: ''Coba kita lihat, kamu bisa pakai piyama ini sambil tutup mata?'' Dan bum! Tanpa sadar anak sudah berpakaian. Permainan para ayah yang tak masuk akal namun berhasil ini pantas mendapat tepuk tangan.', title_ja = 'パパのめちゃくちゃな条件 🎲', body_ja = '夜、パジャマを着たくなくて家じゅうを走りまわる。パパが「目をつぶったままこのパジャマを着られるかな？」とおかしな遊びをしかけると…ドーン！子どもは気づかないうちに着ています。パパたちのこの理屈ぬきだけれど効果的な遊びには、ただ拍手あるのみです。', title_ko = '아빠의 엉뚱한 조건 🎲', body_ko = '밤에 잠옷을 안 입으려고 집 안을 뛰어다니나요? 아빠가 ''눈 감고 이 잠옷 입을 수 있나 볼까?'' 하는 엉뚱한 놀이를 던지면, 짠! 아이는 자기도 모르게 입고 있어요. 아빠들의 엉뚱하지만 통하는 놀이엔 옆에서 박수만 보내면 돼요.', title_nl = 'Papa''s onlogische voorwaarden 🎲', body_nl = '''s Avonds rent hij door het huis om zijn pyjama niet aan te hoeven. Papa bedenkt een absurd spelletje: ''Zullen we eens kijken of je deze pyjama met je ogen dicht kunt aantrekken?'' En boem! Zonder het te merken heeft hij hem aan. Voor deze onlogische maar werkende spelletjes van papa''s kun je alleen maar applaudisseren.', title_pl = 'Nielogiczne warunki taty 🎲', body_pl = 'Wieczorem biega po domu, żeby nie zakładać piżamy. Tata rzuca absurdalną zabawę: „Zobaczymy, czy założysz tę piżamę z zamkniętymi oczami?”. I bum! Dziecko ubrane, nawet nie wiedząc kiedy. Tym nielogicznym, ale skutecznym zabawom taty można tylko bić brawo z boku.', title_pt = 'As condições sem lógica do pai 🎲', body_pt = 'À noite corre pela casa para não vestir o pijama. O pai lança um jogo absurdo: "Vamos ver se consegues vestir este pijama de olhos fechados?". E pronto! A criança vestiu-se sem dar por isso. Às brincadeiras sem lógica, mas eficazes, dos pais, só resta aplaudir.', title_sv = 'Pappas ologiska villkor 🎲', body_sv = 'På kvällen springer barnet runt hemma för att slippa ta på pyjamasen. Pappa slänger fram en absurd lek: ”Får se om du kan ta på pyjamasen med förbundna ögon?” Och pang! Barnet har klätt på sig utan att märka det. Åt pappornas ologiska men fungerande lekar finns bara applåder kvar.', title_vi = 'Những điều kiện phi lý của bố 🎲', body_vi = 'Buổi tối, bé chạy khắp nhà để khỏi phải mặc đồ ngủ. Bố đưa ra một trò chơi ngớ ngẩn: "Xem con có mặc được bộ đồ ngủ này khi nhắm mắt không nào?". Và bùm! Bé đã mặc xong mà không hề hay biết. Những trò chơi phi lý nhưng hiệu quả này của các ông bố chỉ đáng nhận tràng pháo tay.', title_zh = '爸爸没逻辑的条件 🎲', body_zh = '晚上为了不穿睡衣满屋子跑。爸爸抛出一个荒诞的游戏：“看看你能不能闭着眼睛穿上这套睡衣？”然后，砰！宝宝不知不觉就穿好了。对爸爸们这种没逻辑却管用的游戏，你只需在一旁鼓掌。' WHERE id = '8d369fcb-2b04-4658-a824-5b34c817cbfd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La nostalgia del «¡Soy un bebé!» 🍼', body_es = '¿De repente ha empezado a gatear, a llorar como un bebé y a decir «soy un bebé, cógeme»? Crecer a veces también les asusta y quieren refugiarse en sus antiguos y seguros días de bebé. Abrázale y acaríciale unos minutos como en aquellos días.', title_fr = 'La nostalgie du « Je suis un bébé ! » 🍼', body_fr = 'Il s''est soudain mis à marcher à quatre pattes, à pleurer et à dire « Je suis un bébé, prends-moi dans tes bras » ? Grandir leur fait parfois peur, à eux aussi, et ils veulent se réfugier dans les jours rassurants où ils étaient bébés. Prenez-le dans vos bras et câlinez-le quelques minutes, comme avant.', title_hi = '‘मैं बेबी हूँ!’ वाली याद 🍼', body_hi = 'अचानक छोटे बच्चे की तरह रेंगने, रोने और ‘मैं बेबी हूँ, मुझे गोद लो’ कहने लगा? बड़ा होना कभी-कभी उन्हें भी डराता है और वे पुराने, सुरक्षित बचपन के दिनों में पनाह लेना चाहते हैं। कुछ मिनट उसे उन पुराने दिनों की तरह गोद में लेकर सहलाइए।', title_id = 'Nostalgia ''Aku bayi!'' 🍼', body_id = 'Tiba-tiba ia mulai merangkak seperti bayi, menangis, dan berkata ''Aku bayi, peluk aku''? Tumbuh besar kadang juga menakutkan bagi mereka, dan mereka ingin berlindung ke masa bayi yang lama dan aman. Peluk dan elus ia beberapa menit seperti di masa-masa itu.', title_ja = '「わたし、赤ちゃん！」のなつかしさ 🍼', body_ja = '急に赤ちゃんのようにハイハイしたり泣いたりして、「赤ちゃんだから抱っこして」と言いだした？大きくなることは、ときに子どもにとっても怖いもの。安心できた赤ちゃん時代に戻りたくなるんです。数分間、あのころのように抱きしめて、なでてあげましょう。', title_ko = '''나 아기야!'' 향수 🍼', body_ko = '갑자기 아기처럼 기고, 울고, ''나 아기야, 안아 줘''라고 하나요? 자라는 게 가끔은 아이에게도 무서워서, 예전의 안전한 아기 시절로 숨고 싶은 거예요. 몇 분만 그때처럼 안아 주고 쓰다듬어 주세요.', title_nl = '''Ik ben een baby!''-nostalgie 🍼', body_nl = 'Begint hij ineens als een baby te kruipen, te huilen en te zeggen ''Ik ben een baby, knuffel me''? Groot worden maakt hen soms ook bang en dan willen ze terug naar de oude, veilige babytijd. Knuffel en aai hem een paar minuten zoals in die oude dagen.', title_pl = 'Nostalgia „Jestem dzidziusiem!” 🍼', body_pl = 'Nagle zaczął raczkować jak niemowlę, płakać i mówić „jestem dzidziusiem, przytul mnie”? Dorastanie czasem ich też przeraża i chcą schronić się w dawnych, bezpiecznych czasach niemowlęctwa. Przytul go i pogłaszcz przez kilka minut jak kiedyś.', title_pt = 'A nostalgia do "Sou um bebé!" 🍼', body_pt = 'De repente começou a gatinhar como um bebé, a chorar e a dizer "sou um bebé, pega-me ao colo"? Crescer às vezes também os assusta e querem refugiar-se nos tempos seguros de bebé. Pegue nele ao colo e faça-lhe festas uns minutos, como antigamente.', title_sv = 'Nostalgin ”Jag är en bebis!” 🍼', body_sv = 'Började barnet plötsligt krypa och gråta som en bebis och säga ”jag är en bebis, krama mig”? Att växa upp skrämmer ibland dem också, och de vill söka skydd i de gamla, trygga bebisdagarna. Krama och smek barnet några minuter precis som förr.', title_vi = 'Nỗi nhớ "Con là em bé!" 🍼', body_vi = 'Bé bỗng dưng bò như em bé, khóc và nói "Con là em bé, mẹ bế con đi"? Lớn lên đôi khi cũng làm bé sợ, và bé muốn tìm về những ngày tháng bé bỏng an toàn ngày xưa. Hãy ôm ấp, vuốt ve bé vài phút như những ngày ấy.', title_zh = '“我是小宝宝！”的怀旧 🍼', body_zh = '突然像小婴儿一样爬、哭，说“我是小宝宝，抱抱我”？长大有时也会让他们害怕，想躲回从前那些安全的婴儿时光里。像从前那样，抱着宝宝抚摸几分钟吧。' WHERE id = '5eac5298-1552-4198-9ef8-4a16006b3701' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sopa de barro 🍲', body_es = 'En el parque mezcla agua y tierra y te ofrece el barro diciendo: «Mamá, te he hecho sopa». ¡Nada de poner cara de asco! Tómate esa sopa en tu imaginación como si fuera la comida más rica.', title_fr = 'Soupe de boue 🍲', body_fr = 'Au parc, il mélange l''eau et la terre et vous tend la boue en disant « Maman, je t''ai fait de la soupe ». Pas question de faire la grimace ! Buvez cette soupe en imaginant que c''est le plat le plus délicieux du monde.', title_hi = 'कीचड़ का सूप 🍲', body_hi = 'पार्क में पानी और मिट्टी मिलाकर ‘माँ, तुम्हारे लिए सूप बनाया’ कहकर वह कीचड़ आपकी ओर बढ़ाता है। नाक-भौं सिकोड़ना मना है! उस सूप को कल्पना में सबसे स्वादिष्ट खाने की तरह पी लीजिए।', title_id = 'Sup lumpur 🍲', body_id = 'Di taman ia mencampur air dan tanah, lalu menyodorkan lumpur itu kepada Anda: ''Ma, aku masak sup untukmu''. Dilarang jijik! Minumlah sup itu dalam khayalan seolah itu makanan paling lezat.', title_ja = 'どろんこスープ 🍲', body_ja = '公園で水と土をまぜて、「ママ、スープつくったよ」とどろんこを差し出してくる。いやな顔はなしです！そのスープを、空想の中でいちばんおいしいごちそうとして飲みましょう。', title_ko = '진흙 수프 🍲', body_ko = '공원에서 물과 흙을 섞어 ''엄마, 수프 끓였어'' 하며 진흙을 내미나요? 질색하면 안 돼요! 그 수프를 세상에서 가장 맛있는 음식처럼 상상으로 드세요.', title_nl = 'Moddersoep 🍲', body_nl = 'In het park mengt hij water en aarde en geeft je die modder: ''Mama, ik heb soep voor je gemaakt.'' Niet vies doen! Eet die soep in gedachten op alsof het het lekkerste gerecht is.', title_pl = 'Zupa z błota 🍲', body_pl = 'W parku miesza wodę z ziemią, podaje ci to błoto i mówi „Mamo, ugotowałem ci zupę”. Żadnego obrzydzenia! Wypij tę zupę w wyobraźni jak najpyszniejsze danie.', title_pt = 'Sopa de lama 🍲', body_pt = 'No parque, mistura água e terra e estende-lhe a lama: "Mãe, fiz-te uma sopa". Nada de nojo! Beba essa sopa na imaginação como se fosse a comida mais saborosa.', title_sv = 'Lersoppa 🍲', body_sv = 'I parken blandar barnet vatten och jord och räcker dig leran: ”Mamma, jag har lagat soppa åt dig.” Inget äckel! Drick soppan i fantasin som om den vore den godaste maten.', title_vi = 'Súp bùn 🍲', body_vi = 'Ở công viên, bé trộn nước với đất rồi đưa mẹ đống bùn: "Mẹ ơi, con nấu súp cho mẹ này". Không được nhăn mặt nhé! Hãy "uống" bát súp ấy trong tưởng tượng như món ngon nhất trên đời.', title_zh = '泥巴汤 🍲', body_zh = '在公园把水和泥土搅在一起，说“妈妈，我给你做了汤”，把那团泥巴递给你。不许嫌弃！在想象中把那碗汤当作最好喝的美味喝下去吧。' WHERE id = 'bb01fed8-0d6f-4127-8a47-f959e37b46e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer digital del silencio 🤫', body_es = 'El caos de casa por fin se ha acabado y se ha dormido. Abre el Medidor de sonido y mira en la pantalla el nivel de silencio de la habitación (0-10 decibelios). Ver esos números cercanos a cero es para el cerebro de una madre cansada como la sesión de spa más cara del mundo.', title_fr = 'Le plaisir numérique du silence 🤫', body_fr = 'Le chaos de la maison est enfin terminé et il s''est endormi. Ouvrez le Sonomètre et regardez à l''écran le niveau de silence de la pièce (0 à 10 décibels). Voir ces chiffres proches de zéro agit sur le cerveau d''une maman fatiguée comme la séance de spa la plus luxueuse du monde.', title_hi = 'खामोशी का डिजिटल सुकून 🤫', body_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई और वह सो गया। साउंड मीटर खोलिए, स्क्रीन पर कमरे की खामोशी का स्तर (0-10 डेसिबल) देखिए। शून्य के करीब के अंक देखना थकी माँ के दिमाग पर दुनिया के सबसे महँगे स्पा सत्र जैसा असर करता है।', title_id = 'Nikmatnya hening secara digital 🤫', body_id = 'Kekacauan di rumah akhirnya berakhir dan ia tertidur. Buka Pengukur Suara dan lihat tingkat keheningan kamar (0-10 desibel) di layar. Melihat angka yang mendekati nol terasa seperti sesi spa termahal di dunia untuk otak ibu yang lelah.', title_ja = '静けさをデジタルで味わう 🤫', body_ja = '家の中のカオスがようやく終わって、眠りにつきました。「サウンドメーター」を開いて、部屋の静けさ（0〜10デシベル）を画面で眺めましょう。ゼロに近い数字を見ることは、疲れたママの脳にとって、世界でいちばん高級なスパのようなものです。', title_ko = '고요의 디지털 즐거움 🤫', body_ko = '집 안의 혼돈이 드디어 끝나고 아이가 잠들었어요. 소음 측정기를 열고 방의 고요(0~10데시벨)를 화면으로 지켜보세요. 0에 가까운 숫자를 보는 것만으로도 지친 엄마의 머리엔 세상에서 가장 비싼 스파 같아요.', title_nl = 'Het digitale genot van stilte 🤫', body_nl = 'De chaos in huis is eindelijk voorbij en hij slaapt. Open de Geluidsmeter en volg op het scherm hoe stil de kamer is (0-10 decibel). Die getallen bij nul zien werkt voor het brein van een vermoeide mama als de duurste spabehandeling ter wereld.', title_pl = 'Cyfrowa rozkosz ciszy 🤫', body_pl = 'Domowy chaos wreszcie się skończył, a on zasnął. Otwórz Miernik dźwięku i obserwuj na ekranie poziom ciszy w pokoju (0-10 decybeli). Widok liczb bliskich zera działa na mózg zmęczonej mamy jak najdroższy seans w spa.', title_pt = 'O prazer digital do silêncio 🤫', body_pt = 'O caos da casa finalmente acabou e ele adormeceu. Abra o Medidor de Som e veja no ecrã o nível de silêncio do quarto (0-10 decibéis). Ver os números perto de zero funciona para o cérebro de uma mãe cansada como a sessão de spa mais cara do mundo.', title_sv = 'Tystnadens digitala njutning 🤫', body_sv = 'Kaoset hemma är äntligen över och barnet har somnat. Öppna Ljudmätaren och följ tystnadsnivån i rummet (0-10 decibel) på skärmen. Att se siffrorna nära noll verkar på en trött mammas hjärna som världens dyraste spabehandling.', title_vi = 'Niềm vui số của sự yên lặng 🤫', body_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc và bé đã ngủ. Hãy mở Đo âm thanh, nhìn mức độ im lặng của căn phòng (0-10 decibel) trên màn hình. Nhìn những con số gần về không ấy giống như buổi spa đắt nhất thế giới cho não bộ của người mẹ mệt mỏi.', title_zh = '安静的数字享受 🤫', body_zh = '家里的混乱终于结束，宝宝睡着了。打开分贝仪，在屏幕上看着房间的安静程度（0-10分贝）。看到那些接近零的数字，对疲惫妈妈的大脑来说，就像一次世界上最昂贵的水疗。' WHERE id = 'c5e8c723-3ce3-424f-8294-5aece5936ca5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rayita del plátano 🍌', body_es = 'Al pelar el plátano ha visto una rayita diminuta, de un milímetro, y grita: «¡Está estropeado!». La búsqueda de perfección visual de los niños roza la locura. Corta esa parte con un cuchillo, di «¡Lo he salvado!» y pon fin a este minidrama.', title_fr = 'La rayure sur la banane 🍌', body_fr = 'En épluchant la banane, il a vu une minuscule rayure d''un millimètre et crie « Elle est pourrie ! ». La quête de perfection visuelle des enfants frôle la folie. Coupez ce morceau au couteau et dites « Je l''ai sauvée ! » pour mettre fin à ce mini-drame.', title_hi = 'केले पर खरोंच 🍌', body_hi = 'केला छीलते समय उस पर एक छोटी, मिलीमीटर भर की खरोंच देखी और चिल्लाया, ‘यह खराब हो गया!’ बच्चों की दिखने में परफ़ेक्शन की तलाश पागलपन के स्तर पर होती है। वह हिस्सा चाकू से काटिए और ‘बचा लिया!’ कहकर इस छोटे ड्रामे का अंत कीजिए।', title_id = 'Goresan di pisang 🍌', body_id = 'Saat mengupas pisang, ia melihat goresan kecil seukuran milimeter dan berteriak ''Ini sudah busuk!''. Pencarian kesempurnaan visual anak-anak sudah di level gila. Potong bagian itu dengan pisau, katakan ''Sudah Mama selamatkan!'', dan akhiri drama mini ini.', title_ja = 'バナナの小さなキズ 🍌', body_ja = 'バナナの皮をむいたら、ミリ単位の小さなキズを見つけて「これ、くさってる！」と叫ぶ。子どもの見た目の完璧さへのこだわりは、とんでもないレベルです。その部分をナイフで切りとって「助けたよ！」と言い、このミニドラマを終わらせましょう。', title_ko = '바나나 위의 흠집 🍌', body_ko = '바나나 껍질을 벗기다 1밀리미터짜리 작은 흠집을 보고 ''이거 상했어!'' 하고 소리치나요? 아이들의 시각적 완벽주의는 상상 이상이에요. 그 부분을 칼로 잘라 내고 ''엄마가 구했어!''라며 이 작은 드라마를 끝내세요.', title_nl = 'Het krasje op de banaan 🍌', body_nl = 'Bij het pellen ziet hij een piepklein krasje op de banaan en roept: ''Hij is kapot!'' De zoektocht van kinderen naar visuele perfectie grenst aan waanzin. Snijd dat stukje eraf met een mes, zeg ''Gered!'' en maak een einde aan dit minidrama.', title_pl = 'Rysa na bananie 🍌', body_pl = 'Obierając banana, zobaczył na nim malutką, milimetrową rysę i krzyczy: „Zepsuty!”. Dziecięce poszukiwanie wizualnej doskonałości sięga szaleństwa. Odkrój ten kawałek nożem, powiedz „Uratowałam go!” i zakończ ten mini dramat.', title_pt = 'O risquinho na banana 🍌', body_pt = 'Ao descascar a banana, viu um risquinho minúsculo e grita: "Esta está estragada!". A busca da perfeição visual nas crianças chega ao nível da loucura. Corte essa parte com uma faca, diga "Salvei-a!" e acabe com este minidrama.', title_sv = 'Repan på bananen 🍌', body_sv = 'När du skalade bananen såg barnet en liten, millimeterstor repa på den och skriker: ”Den är förstörd!” Barns jakt på visuell perfektion är på galenskapsnivå. Skär bort biten med en kniv, säg ”Jag räddade den!” och avsluta minidramat.', title_vi = 'Vết xước trên quả chuối 🍌', body_vi = 'Khi bóc chuối, bé thấy một vết xước nhỏ xíu cỡ milimét và hét lên: "Hỏng rồi!". Sự cầu toàn về hình thức của trẻ đạt đến mức "điên rồ". Hãy dùng dao cắt bỏ chỗ đó và nói "Mẹ cứu được rồi!" để kết thúc vở bi kịch nhỏ này.', title_zh = '香蕉上的一道划痕 🍌', body_zh = '剥香蕉时看到上面有一道细小的、毫米级的划痕，就大喊：“这个坏了！”孩子对视觉完美的追求简直到了疯狂的程度。用刀把那一小块切掉，说一句“我救好它了！”，结束这场小小的戏剧吧。' WHERE id = '204c6838-b697-4616-9592-52e0162c6a92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Misión cerrar puertas 🚪', body_es = 'Le encanta cerrar las puertas de todas las habitaciones desde dentro y dejarte fuera. El concepto de espacio personal está en plena revolución. Toma medidas para que no se pille los dedos, pero no estropees este juego de declarar su propio territorio.', title_fr = 'Mission : fermer les portes 🚪', body_fr = 'Il prend un malin plaisir à fermer derrière lui les portes de toutes les pièces de la maison et à vous laisser dehors. Sa notion d''espace personnel est en pleine révolution. Prenez des précautions pour qu''il ne se coince pas les doigts, mais ne gâchez pas ce jeu où il proclame son territoire.', title_hi = 'दरवाज़ा बंद करने का मिशन 🚪', body_hi = 'घर के सारे कमरों के दरवाज़े अंदर से बंद करके आपको बाहर छोड़ने में खास मज़ा लेता है। निजी जगह की समझ में क्रांति आ रही है। उँगलियाँ न दबें, इसका इंतज़ाम कीजिए, पर अपना इलाका घोषित करने के उसके इस खेल को गंभीर ठेस मत पहुँचाइए।', title_id = 'Misi mengunci pintu 🚪', body_id = 'Ia sangat senang menutup pintu semua kamar di rumah dari dalam dan membiarkan Anda di luar. Konsep ruang pribadinya sedang berevolusi. Ambil langkah agar jarinya tidak terjepit, tapi jangan merusak permainannya mengumumkan wilayahnya sendiri.', title_ja = 'ドアのカギかけミッション 🚪', body_ja = '家じゅうの部屋のドアを閉めて、あなたを外に締め出すのが楽しくてしかたない。プライベートな空間の感覚が革命を起こしています。指をはさまないよう対策をしたうえで、この「ここはぼくの場所」宣言ごっこを、むやみにじゃましないであげましょう。', title_ko = '문 잠그기 미션 🚪', body_ko = '집 안 모든 방의 문을 닫고 엄마를 밖에 두는 걸 유난히 즐기나요? 개인 공간에 대한 개념이 혁명 중이에요. 손가락이 끼지 않게 대비는 하되, 자기 영역을 선포하는 이 놀이를 크게 막지는 마세요.', title_nl = 'Missie deuren op slot 🚪', body_nl = 'Hij geniet er enorm van om alle deuren in huis dicht te doen en jou buiten te laten staan. Zijn besef van een eigen ruimte maakt een revolutie door. Zorg dat zijn vingers niet klem komen te zitten, maar verstoor zijn spel van het opeisen van zijn eigen terrein niet te veel.', title_pl = 'Misja zamykania drzwi 🚪', body_pl = 'Z wyjątkową przyjemnością zamyka za sobą drzwi wszystkich pokoi w domu i zostawia cię na zewnątrz. Poczucie przestrzeni osobistej przechodzi rewolucję. Zabezpiecz drzwi, żeby nie przytrzasnął palców, ale nie psuj mu zabawy w ogłaszanie własnego terytorium.', title_pt = 'Missão trancar portas 🚪', body_pt = 'Fecha as portas de todas as divisões da casa e adora deixá-la do lado de fora. A noção de espaço pessoal está em plena revolução. Tome medidas para que não entale os dedos, mas não estrague a sério este jogo de declarar o seu território.', title_sv = 'Uppdrag: lås dörren 🚪', body_sv = 'Barnet stänger dörrarna till alla rum hemma bakom sig och njuter särskilt av att lämna dig utanför. Begreppet personligt utrymme genomgår en revolution. Se till att fingrarna inte kläms, men skada inte allvarligt barnets lek med att utropa sitt eget territorium.', title_vi = 'Nhiệm vụ khóa cửa 🚪', body_vi = 'Bé đặc biệt thích đóng hết cửa các phòng trong nhà và để mẹ ở bên ngoài. Khái niệm không gian riêng đang "bùng nổ". Hãy đề phòng để bé không bị kẹp tay, nhưng đừng phá hỏng trò chơi "tuyên bố lãnh thổ" này của bé.', title_zh = '锁门任务 🚪', body_zh = '特别喜欢把家里所有房间的门都从里面关上，把你关在外面。私人空间的概念正在发生一场“革命”。做好防夹手的措施，但别严重破坏宝宝这个宣告自己领地的游戏。' WHERE id = '49d8e195-1371-46c6-a98a-c6f38e78e098' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Voces distintas en el cuento 🪄', body_es = 'Esta noche abre Cuentos inteligentes, pero lee el texto de otra manera. Pon voz grave al oso y voz fina al pájaro y crea un pequeño teatro en la habitación. Así rompes la monotonía y atraes al instante su atención al cuento, y de ahí al sueño.', title_fr = 'Différentes voix dans le conte 🪄', body_fr = 'Ce soir, ouvrez les Contes intelligents, mais lisez le texte autrement. Prenez une grosse voix pour l''ours et une petite voix fine pour l''oiseau, et créez un petit théâtre dans la chambre. Cela casse la monotonie et attire aussitôt l''enfant dans l''histoire, puis dans le sommeil.', title_hi = 'कहानी में अलग-अलग आवाज़ें 🪄', body_hi = 'आज शाम स्मार्ट कहानियाँ खोलिए, पर पढ़िए अलग अंदाज़ में। भालू की आवाज़ मोटी, चिड़िया की पतली निकालकर कमरे में छोटा-सा थिएटर बनाइए। यह एकरसता तोड़ता है और बच्चे का ध्यान तुरंत कहानी में, और वहाँ से नींद में खींच लेता है।', title_id = 'Nada suara berbeda dalam dongeng 🪄', body_id = 'Malam ini buka Dongeng Pintar, tapi bacakan teksnya dengan cara berbeda. Buat suara beruang yang berat dan suara burung yang tinggi, ciptakan teater kecil di kamar. Ini memecah kebosanan dan langsung menarik perhatian anak ke dalam dongeng, lalu ke dalam tidur.', title_ja = 'お話でいろんな声色を 🪄', body_ja = '今夜は「スマートおはなし」を開いて、いつもとちがう読み方をしてみましょう。クマは太い声、鳥は細い声で読んで、部屋に小さな劇場をつくって。単調さがやぶれて、子どもの心はすぐにお話の中へ、そして眠りへと引きこまれます。', title_ko = '동화 속 다양한 목소리 🪄', body_ko = '오늘 저녁 스마트 동화를 열되 다르게 읽어 보세요. 곰 목소리는 굵게, 새 목소리는 가늘게 내며 방에 작은 극장을 만들어 보세요. 단조로움이 깨지고 아이의 관심이 바로 이야기 속으로, 그리고 잠 속으로 빠져들 거예요.', title_nl = 'Verschillende stemmen in het sprookje 🪄', body_nl = 'Open vanavond Slimme sprookjes, maar lees de tekst anders voor. Geef de beer een zware stem en de vogel een hoge, en maak zo een klein theater in de kamer. Dat doorbreekt de eentonigheid en trekt de aandacht van je kind meteen het verhaal in, en van daaruit de slaap in.', title_pl = 'Różne głosy w bajce 🪄', body_pl = 'Dziś wieczorem otwórz Mądre bajki, ale czytaj tekst inaczej. Niech niedźwiedź mówi grubym głosem, a ptaszek cienkim, i stwórz w pokoju mały teatr. To przerywa monotonię i od razu wciąga dziecko w bajkę, a stamtąd w sen.', title_pt = 'Vozes diferentes na história 🪄', body_pt = 'Esta noite abra as Histórias Inteligentes, mas leia o texto de outra forma. Faça a voz do urso grossa e a do pássaro fininha e crie no quarto um pequeno teatro. Isto quebra a monotonia e leva logo a atenção da criança para dentro da história e, dali, para o sono.', title_sv = 'Olika röster i sagan 🪄', body_sv = 'Öppna Smarta sagor i kväll, men läs texten på ett annat sätt. Gör björnens röst grov och fågelns röst ljus, och skapa en liten teater i rummet. Det bryter enformigheten och drar genast in barnets uppmärksamhet i sagan, och därifrån in i sömnen.', title_vi = 'Những giọng kể khác nhau 🪄', body_vi = 'Tối nay hãy mở Truyện cổ tích thông minh, nhưng đọc theo cách khác. Giả giọng gấu trầm ồm, giọng chim thanh mảnh để tạo nên một nhà hát nhỏ trong phòng. Điều này phá vỡ sự đơn điệu, kéo bé ngay vào câu chuyện và từ đó vào giấc ngủ.', title_zh = '童话里不同的声音 🪄', body_zh = '今晚打开智慧童话，但换一种方式来读。小熊用低沉的声音，小鸟用细细的声音，在房间里打造一个小剧场。这能打破单调，马上把宝宝的注意力吸进故事里，再从故事带进梦乡。' WHERE id = '524b4634-31bf-4fa3-860b-d29e08cc3c10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos susurrados en la oscuridad 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, muy bajito, lo que ha pasado durante el día o el detalle de su carácter que más te gusta. Susurrar es el método más místico para preparar el cerebro para dormir y olvidar el ruido.', title_fr = 'Découvertes chuchotées dans le noir 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et chuchotez-lui à l''oreille, tout bas, ce qui s''est passé dans la journée ou le détail que vous préférez dans son caractère. Le chuchotement est la façon la plus mystérieuse de préparer le cerveau au sommeil et de lui faire oublier le bruit.', title_hi = 'अँधेरे में फुसफुसाती खोजें 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें या उसके स्वभाव की आपकी सबसे पसंदीदा बात बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने और शोर भुलाने का सबसे रहस्यमयी तरीका है।', title_id = 'Penemuan berbisik dalam gelap 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan ke telinganya dengan suara sangat pelan kejadian hari ini, atau hal yang paling Anda sukai dari karakternya. Bisikan adalah cara paling ajaib untuk menyiapkan otak tidur dan melupakan kebisingan.', title_ja = '暗やみでささやく発見 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことや、この子のいちばん好きなところを、耳もとでとても小さな声でささやいてあげて。ささやき声は、脳を眠りへ導き、にぎやかさを忘れさせる、いちばん神秘的な方法です。', title_ko = '어둠 속 속삭임 탐험 🌙', body_ko = '방의 불을 모두 끄세요. 옆에 누워 오늘 있었던 일이나 아이 성격에서 가장 좋아하는 점을 아주 낮은 목소리로 귓가에 속삭여 주세요. 속삭임은 뇌를 잠들 준비시키고 소음을 잊게 하는 가장 신비로운 방법이에요.', title_nl = 'Fluisterend ontdekken in het donker 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en fluister heel zachtjes in zijn oor wat er vandaag is gebeurd, of wat jij het allerleukst vindt aan zijn karakter. Fluisteren is de meest mystieke manier om het brein klaar te maken voor de slaap en het lawaai te vergeten.', title_pl = 'Szeptane odkrycia w ciemności 🌙', body_pl = 'Zgaś całkowicie światła w pokoju. Połóż się obok i bardzo cicho wyszeptaj mu do ucha, co wydarzyło się w ciągu dnia albo co najbardziej kochasz w jego charakterze. Szept to najbardziej tajemniczy sposób, by przygotować mózg do snu i zapomnieć o hałasie.', title_pt = 'Descobertas sussurradas no escuro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, o que aconteceu durante o dia ou o pormenor de que mais gosta no caráter dele. Sussurrar é o método mais místico para preparar o cérebro para o sono e esquecer o barulho.', title_sv = 'Viskade upptäckter i mörkret 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och viska mycket tyst i örat om det som hänt under dagen, eller om den detalj i barnets personlighet som du älskar mest. Viskningar är den mest mystiska metoden för att förbereda hjärnan för sömn och glömma oväsendet.', title_vi = 'Khám phá thì thầm trong bóng tối 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ vào tai bé về những gì đã xảy ra trong ngày, hoặc nét tính cách mẹ yêu nhất ở bé. Thì thầm là cách huyền diệu nhất giúp não bộ chuẩn bị cho giấc ngủ, quên đi những ồn ào.', title_zh = '黑暗中的悄悄话发现 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，在宝宝耳边悄悄讲今天发生的事，或者你最喜欢宝宝性格里的哪一点。悄悄话是帮大脑准备入睡、忘掉喧嚣最神奇的方法。' WHERE id = '603225e8-0807-426b-b793-892dfeb9e281' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paraguas dentro de casa ☂️', body_es = 'Fuera hace sol, pero quiere andar por casa con el paraguas abierto. Su imaginación no acepta el entorno físico. Si hay sitio libre en casa, deja que monte un pequeño campamento bajo el paraguas. No ahogues la lógica de los niños con normas sociales.', title_fr = 'Un parapluie dans la maison ☂️', body_fr = 'Dehors, il fait soleil, mais il veut se promener dans la maison avec un parapluie ouvert. Son imagination ne tient pas compte de l''environnement physique. S''il y a de la place, laissez-le se construire un petit campement sous ce parapluie. N''étouffez pas la logique des enfants sous les normes sociales.', title_hi = 'घर के अंदर छाता ☂️', body_hi = 'बाहर धूप है, पर वह घर में खुला छाता लेकर घूमना चाहता है। उसकी कल्पना भौतिक माहौल को नहीं मानती। अगर घर में खाली जगह है, तो उसे उस छाते के नीचे अपना छोटा-सा कैंप बनाने दीजिए। बच्चों के तर्क को लोगों के कायदों से मत दबाइए।', title_id = 'Payung di dalam rumah ☂️', body_id = 'Di luar matahari bersinar, tapi ia ingin berkeliling rumah dengan payung terbuka. Imajinasinya tidak mengakui lingkungan fisik. Jika ada ruang kosong, biarkan ia membuat perkemahan kecil di bawah payung itu. Jangan tenggelamkan logika anak dengan norma masyarakat.', title_ja = '家の中で傘 ☂️', body_ja = '外は晴れているのに、家の中で傘を開いて歩きたがる。想像力は、目の前の環境なんて受けつけません。家に空いたスペースがあれば、その傘の下に小さなキャンプをつくらせてあげましょう。子どもの理屈を、世間の常識でおさえこまないで。', title_ko = '집 안의 우산 ☂️', body_ko = '밖엔 해가 떴는데 집 안에서 우산을 펴고 다니고 싶어 하나요? 상상력은 물리적 환경을 따지지 않아요. 집에 빈 공간이 있다면 그 우산 아래 작은 캠프를 차리게 해 주세요. 아이의 논리를 사회적 기준으로 누르지 마세요.', title_nl = 'Een paraplu in huis ☂️', body_nl = 'Buiten schijnt de zon, maar hij wil met een open paraplu door het huis lopen. Zijn fantasie trekt zich niets aan van de fysieke omgeving. Is er ruimte genoeg, laat hem dan onder die paraplu een kampje bouwen. Smoor de logica van kinderen niet met wat ''hoort''.', title_pl = 'Parasol w domu ☂️', body_pl = 'Na dworze świeci słońce, a on chce chodzić po domu z otwartym parasolem. Jego wyobraźnia nie uznaje fizycznego otoczenia. Jeśli w domu jest miejsce, niech zrobi sobie pod tym parasolem mały obóz. Nie duś dziecięcej logiki normami społecznymi.', title_pt = 'Guarda-chuva dentro de casa ☂️', body_pt = 'Lá fora está sol, mas ele quer andar pela casa de guarda-chuva aberto. A imaginação dele não aceita o ambiente físico. Se houver espaço livre em casa, deixe-o montar um pequeno acampamento debaixo do guarda-chuva. Não sufoque a lógica das crianças com normas sociais.', title_sv = 'Paraply inomhus ☂️', body_sv = 'Solen skiner ute, men barnet vill gå runt hemma med uppfällt paraply. Fantasin accepterar inte den fysiska miljön. Om det finns plats hemma, låt barnet bygga ett litet läger åt sig under paraplyet. Kväv inte barnets logik med samhällets normer.', title_vi = 'Che ô trong nhà ☂️', body_vi = 'Ngoài trời nắng đẹp, nhưng bé lại muốn che ô đi lại trong nhà. Trí tưởng tượng của bé không chấp nhận môi trường vật lý. Nếu nhà có chỗ trống, hãy để bé dựng một "khu cắm trại" nhỏ dưới chiếc ô. Đừng bóp nghẹt logic của trẻ bằng chuẩn mực xã hội.', title_zh = '家里的雨伞 ☂️', body_zh = '外面出太阳了，宝宝却想在家里撑着伞走来走去。宝宝的想象力不接受现实的环境。如果家里有空地方，就让宝宝在伞下给自己搭个小营地吧。别用社会规范压住孩子的逻辑。' WHERE id = '60fcf611-529f-4586-9532-af738483766f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La prueba del «No» en el súper 🛒', body_es = 'En pleno súper ha pedido un caramelo, le has dicho «no» y se ha puesto a llorar. A pesar de las miradas aleccionadoras de alrededor, no has cambiado de opinión. ¡Eres una madre perfecta! Y para no olvidar nada, ten un ojo en la Lista de la compra para salir cuanto antes.', title_fr = 'L''épreuve du « Non » au supermarché 🛒', body_fr = 'En plein milieu du supermarché, il a réclamé des bonbons, vous avez dit « Non » et il s''est mis à pleurer. Malgré les regards moralisateurs autour, vous n''êtes pas revenue sur votre décision. Vous êtes une maman formidable ! Et contre les oublis, gardez un œil sur la Liste de courses pour sortir vite.', title_hi = 'बाज़ार में ‘ना’ की परीक्षा 🛒', body_hi = 'बाज़ार के ठीक बीच टॉफ़ी माँगी, आपने ‘ना’ कहा और वह रोने लगा। आसपास की नसीहत भरी नज़रों के बावजूद आप अपने फ़ैसले पर टिकी रहीं। आप बेहतरीन माँ हैं! और भूलने से बचने के लिए नज़र शॉपिंग लिस्ट पर रखिए, ताकि जल्दी निकल सकें।', title_id = 'Ujian ''Tidak'' di supermarket 🛒', body_id = 'Tepat di tengah supermarket ia minta permen, Anda berkata ''Tidak'' dan ia mulai menangis. Meski ada tatapan menghakimi dari orang sekitar, Anda tidak mengubah keputusan. Kamu ibu yang hebat! Untuk melawan lupa, pastikan mata Anda pada Daftar Belanja agar bisa cepat keluar.', title_ja = 'スーパーでの「だめ」の試練 🛒', body_ja = 'スーパーのどまんなかでお菓子をほしがり、あなたが「だめ」と言うと泣きだした。まわりの説教じみた視線にも負けず、決めたことをまげなかった。あなたは完璧なママです！買い忘れ防止に「買い物リスト」を見ながら、さっと買い物を終えましょう。', title_ko = '마트에서의 ''안 돼'' 시험 🛒', body_ko = '마트 한가운데서 사탕을 달라기에 ''안 돼''라고 했더니 울기 시작했나요? 주변의 훈수 섞인 시선에도 결정을 바꾸지 않았죠. 정말 멋진 엄마예요! 빨리 나올 수 있게 깜빡하지 말고 쇼핑 목록을 보세요.', title_nl = 'De nee-test in de supermarkt 🛒', body_nl = 'Midden in de supermarkt wilde hij snoep, jij zei nee en hij begon te huilen. Ondanks de belerende blikken van anderen bleef je bij je besluit. Je bent een geweldige mama! En tegen vergeetachtigheid: houd je ogen op het Boodschappenlijstje, zodat je snel weer buiten staat.', title_pl = 'Test „Nie” w sklepie 🛒', body_pl = 'Na samym środku sklepu chciał cukierka, ty powiedziałaś „Nie”, a on zaczął płakać. Mimo pouczających spojrzeń dookoła nie zmieniłaś zdania. Jesteś wspaniałą mamą! A na zapominalstwo miej oko na Liście zakupów, żeby szybko wyjść.', title_pt = 'O teste do "Não" no supermercado 🛒', body_pt = 'Mesmo no meio do supermercado pediu um rebuçado, disse "Não" e ele começou a chorar. Apesar dos olhares moralistas à volta, não voltou atrás. É uma mãe perfeita! E contra os esquecimentos, mantenha os olhos na Lista de Compras para sair depressa.', title_sv = '”Nej”-provet i butiken 🛒', body_sv = 'Mitt i butiken ville barnet ha godis, du sa ”Nej” och barnet började gråta. Trots de dömande blickarna runt omkring stod du fast vid ditt beslut. Du är en fantastisk mamma! Och mot glömskan, ha blicken på Inköpslistan så att ni kan komma ut snabbt.', title_vi = 'Thử thách chữ "Không" ở siêu thị 🛒', body_vi = 'Giữa siêu thị, bé đòi kẹo, mẹ nói "Không" và bé bắt đầu khóc. Bất chấp những ánh mắt "dạy đời" xung quanh, mẹ vẫn giữ quyết định của mình. Mẹ thật tuyệt vời! Còn để khỏi quên đồ và ra về nhanh, hãy luôn để mắt đến Danh sách mua sắm.', title_zh = '超市里的“不行”考验 🛒', body_zh = '在超市正中间要糖果，你说了“不行”，宝宝就哭了起来。尽管周围投来“说教”的目光，你还是坚持了自己的决定。你是一位很棒的妈妈！至于健忘，眼睛盯着购物清单，好快点离开。' WHERE id = '831decae-1343-4bbb-bf11-1f398cc1bc2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El «¿Por qué has dicho mi nombre?» sin motivo 😤', body_es = 'Tú solo has dicho «Ven, la comida está lista», y él se ha enfadado y se ha puesto a llorar: «¿Por qué has dicho mi nombre?». A esta edad las emociones están tan revueltas que a veces se enfadan hasta con el aire. No expliques nada: en 2 minutos correrá él solo a comer.', title_fr = '« Pourquoi tu as dit mon prénom ? » sans raison 😤', body_fr = 'Vous avez simplement dit « Viens, le repas est prêt », et il s''est fâché en pleurant : « Pourquoi tu as dit mon prénom ? » À cet âge, les émotions sont si embrouillées qu''ils boudent parfois pour un rien. N''expliquez rien, dans 2 minutes il courra manger de lui-même.', title_hi = 'बेवजह ‘मेरा नाम क्यों लिया?’ 😤', body_hi = 'आपने बस कहा, ‘आओ, खाना तैयार है’, और वह गुस्से में ‘मेरा नाम क्यों लिया?’ कहकर रोने लगा। इस उम्र में भावनाएँ इतनी उलझी होती हैं कि कभी-कभी हवा से भी रूठ जाते हैं। कुछ मत समझाइए, 2 मिनट बाद वह खुद खाने की ओर दौड़ेगा।', title_id = '''Kenapa sebut namaku?'' tanpa sebab 😤', body_id = 'Anda hanya berkata ''Ayo, makanan sudah siap'', tapi ia marah dan menangis: ''Kenapa sebut namaku?''. Di usia ini emosinya begitu campur aduk sampai kadang merajuk tanpa alasan. Jangan menjelaskan apa pun, 2 menit kemudian ia akan lari sendiri ke meja makan.', title_ja = '理由なき「なんで名前呼んだの？」 😤', body_ja = 'ただ「おいで、ごはんできたよ」と言っただけなのに、怒って「なんでわたしの名前を言ったの？」と泣きだした。この年ごろは気持ちがとても入りまじっていて、ときには空気にさえすねるんです。何も説明しないで。2分後には自分からごはんに走ってきます。', title_ko = '이유 없는 ''왜 내 이름 불렀어?'' 😤', body_ko = '그냥 ''와, 밥 다 됐어''라고 했을 뿐인데 화를 내며 ''왜 내 이름 불렀어?'' 하고 울었나요? 이 나이엔 감정이 너무 뒤엉켜 있어서 가끔은 허공에도 삐져요. 아무것도 설명하지 마세요, 2분 뒤면 스스로 밥 먹으러 달려올 거예요.', title_nl = '''Waarom zei je mijn naam?'' zonder reden 😤', body_nl = 'Je zei alleen ''Kom, het eten is klaar'', en hij werd boos en begon te huilen: ''Waarom zei je mijn naam?'' Op deze leeftijd zijn emoties zo verward dat ze soms om niets boos worden. Leg niets uit, over 2 minuten rent hij vanzelf naar tafel.', title_pl = '„Czemu powiedziałaś moje imię?” 😤', body_pl = 'Powiedziałaś tylko „Chodź, jedzenie gotowe”, a on się rozzłościł i zaczął płakać: „Czemu powiedziałaś moje imię?”. W tym wieku emocje są tak splątane, że czasem obrażają się o nic. Niczego nie tłumacz, za 2 minuty sam przybiegnie jeść.', title_pt = '"Porque disseste o meu nome?" sem razão 😤', body_pt = 'Só disse "Anda, a comida está pronta" e ele zangou-se e começou a chorar: "Porque é que disseste o meu nome?". Nesta idade as emoções estão tão baralhadas que às vezes ficam amuados com o ar. Não explique nada: 2 minutos depois corre ele próprio para a mesa.', title_sv = 'Ett omotiverat ”Varför sa du mitt namn?” 😤', body_sv = 'Du sa bara ”Kom, maten är klar”, och barnet blev argt och började gråta: ”Varför sa du mitt namn?” I den här åldern är känslorna så röriga att de ibland tjurar för ingenting. Förklara ingenting, efter 2 minuter springer barnet själv till maten.', title_vi = '"Sao mẹ gọi tên con?" vô cớ 😤', body_vi = 'Mẹ chỉ nói "Lại đây con, cơm xong rồi", bé lại nổi giận và khóc: "Sao mẹ gọi tên con?". Ở tuổi này, cảm xúc rối rắm đến mức đôi khi bé giận dỗi chẳng vì lý do gì. Đừng giải thích gì cả, 2 phút sau bé sẽ tự chạy đến ăn.', title_zh = '莫名其妙的“你为什么叫我名字？” 😤', body_zh = '你只是说了句“过来，饭做好了”，宝宝却生气地哭了：“你为什么叫我的名字？”这个年龄的情绪乱成一团，有时连空气都能惹他们生气。什么都别解释，2分钟后宝宝自己就会跑来吃饭。' WHERE id = '1d613098-d421-410e-ae85-8cfd9552b432' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y fobias raras 🤖', body_es = '¿De repente le ha empezado a dar miedo el coche rojo con el que siempre jugaba? Si te preocupan estas fobias inexplicables, cierra los foros traumatizantes de internet. Obtén de Anacan AI una respuesta científica y tranquilizadora sobre las rarezas de la imaginación a los 3 años y medio.', title_fr = 'Intelligence artificielle et phobies étranges 🤖', body_fr = 'Il s''est soudain mis à avoir peur de la voiture rouge avec laquelle il joue depuis toujours ? Si ces phobies inexplicables vous inquiètent, fermez les forums traumatisants d''Internet. Obtenez d''Anacan AI une réponse scientifique et rassurante sur les bizarreries de l''imagination à 3 ans et demi.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और अजीब डर 🤖', body_hi = 'अचानक उस लाल गाड़ी से डरने लगा जिससे हमेशा खेलता था? अगर बेवजह के डर आपको परेशान कर रहे हैं, तो इंटरनेट के परेशान करने वाले फ़ोरम बंद कीजिए। Anacan AI से साढ़े 3 साल की कल्पना की अजीब बातों के बारे में वैज्ञानिक और सुकून देने वाला जवाब पाइए।', title_id = 'Kecerdasan buatan dan fobia aneh 🤖', body_id = 'Tiba-tiba ia takut pada mobil merah yang selalu ia mainkan? Jika fobia yang tak terjelaskan membuat Anda cemas, tutup forum-forum traumatis di internet. Dapatkan jawaban ilmiah dan menenangkan dari Anacan AI tentang keanehan imajinasi anak usia 3,5 tahun.', title_ja = 'AIとふしぎな怖がり 🤖', body_ja = '急に、いつも遊んでいた赤い車を怖がりだした？説明のつかない怖がりが心配なら、ネットのショッキングな掲示板は閉じましょう。Anacan AIに、3歳半の想像力のふしぎについて、科学的で安心できる答えをもらいましょう。', title_ko = '인공지능과 별난 공포증 🤖', body_ko = '늘 가지고 놀던 빨간 자동차를 갑자기 무서워하나요? 설명할 수 없는 두려움이 걱정된다면 충격적인 인터넷 게시판은 닫으세요. Anacan AI에게 세 살 반 상상력의 신기한 특징에 대해 과학적이고 안심되는 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en rare angsten 🤖', body_nl = 'Is hij ineens bang voor de rode auto waar hij altijd mee speelde? Maken onverklaarbare angsten je ongerust, sluit dan die traumatiserende fora op internet. Krijg van Anacan AI een wetenschappelijk, geruststellend antwoord over de eigenaardigheden van de fantasie van een kind van 3,5.', title_pl = 'Sztuczna inteligencja i dziwne fobie 🤖', body_pl = 'Nagle zaczął bać się czerwonego samochodu, którym zawsze się bawił? Jeśli martwią cię niewytłumaczalne fobie, zamknij traumatyzujące fora w internecie. Uzyskaj od Anacan AI naukową i uspokajającą odpowiedź na temat dziwactw wyobraźni 3,5-latka.', title_pt = 'Inteligência artificial e fobias estranhas 🤖', body_pt = 'De repente começou a ter medo do carro vermelho com que sempre brincou? Se as fobias inexplicáveis a preocupam, feche os fóruns traumatizantes da internet. Obtenha do Anacan AI uma resposta científica e tranquilizadora sobre as estranhezas da imaginação aos 3 anos e meio.', title_sv = 'Artificiell intelligens och konstiga fobier 🤖', body_sv = 'Har barnet plötsligt blivit rädd för den röda bilen det alltid lekt med? Om oförklarliga fobier oroar dig, stäng de traumatiska forumen på nätet. Få ett vetenskapligt och lugnande svar om 3,5-åringens fantasifulla egenheter från Anacan AI.', title_vi = 'Trí tuệ nhân tạo và những nỗi sợ kỳ lạ 🤖', body_vi = 'Bé bỗng sợ chiếc ô tô đỏ vẫn chơi hằng ngày? Nếu những nỗi sợ khó giải thích khiến mẹ lo lắng, hãy đóng những diễn đàn gây hoang mang trên mạng. Hãy hỏi Anacan AI để nhận câu trả lời khoa học, giúp mẹ yên tâm về những điều kỳ lạ trong trí tưởng tượng của tuổi 3,5.', title_zh = '人工智能与奇怪的恐惧 🤖', body_zh = '突然开始害怕一直在玩的红色小汽车？如果莫名其妙的恐惧让你担心，就关掉网上那些让人焦虑的论坛。问问Anacan AI关于3岁半想象力的奇怪之处，得到科学又安心的回答。' WHERE id = 'ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ver una peli en pareja... 🎬', body_es = '¡El peque se ha dormido! Por fin os sentáis en el sofá tú y tu pareja a ver una peli, pero en el minuto 10 los dos estáis profundamente dormidos. Esta es vuestra realidad. Esa imagen cansada de dormiros apoyados el uno en el otro es el reflejo de un verdadero trabajo en equipo.', title_fr = 'Regarder un film en couple... 🎬', body_fr = 'L''enfant dort ! Vous vous installez enfin sur le canapé avec votre partenaire pour regarder un film, mais à la 10e minute, vous dormez tous les deux profondément. C''est votre réalité. Cette image fatiguée de vous endormir l''un contre l''autre est la preuve d''un vrai travail d''équipe.', title_hi = 'जोड़े के रूप में फ़िल्म देखना... 🎬', body_hi = 'बच्चा सो गया! आखिरकार साथी के साथ फ़िल्म देखने सोफ़े पर बैठे, पर 10वें मिनट में दोनों गहरी नींद में थे। यही आपकी हकीकत है। एक-दूसरे से टिककर सोने का वह थका हुआ नज़ारा सच्चे टीमवर्क की पहचान है।', title_id = 'Menonton film berdua... 🎬', body_id = 'Anak sudah tidur! Akhirnya Anda duduk di sofa bersama pasangan untuk menonton film, tapi di menit ke-10 kalian berdua sudah tertidur pulas. Inilah kenyataan kalian. Pemandangan lelah saat tertidur saling bersandar itu adalah wujud kerja sama tim yang sesungguhnya.', title_ja = 'ふたりで映画を見る…はずが 🎬', body_ja = '子どもが寝ました！やっとパートナーと映画を見ようとソファに座ったのに、10分目にはふたりともぐっすり。これがあなたたちのリアルです。寄りかかり合って眠る、その疲れた姿こそ、本物のチームワークのあらわれです。', title_ko = '부부의 영화 보기... 🎬', body_ko = '아이가 잠들었어요! 드디어 배우자와 영화를 보려고 소파에 앉았는데 10분 만에 둘 다 깊이 잠들었나요? 이게 지금의 현실이죠. 서로에게 기대어 잠든 그 지친 모습이야말로 진짜 팀워크예요.', title_nl = 'Samen een film kijken... 🎬', body_nl = 'Je kind slaapt! Eindelijk zitten jullie op de bank voor een film, maar na 10 minuten zijn jullie allebei diep in slaap. Dat is jullie realiteit. Dat vermoeide beeld van tegen elkaar aan in slaap vallen is echt teamwerk.', title_pl = 'Film we dwoje... 🎬', body_pl = 'Dziecko śpi! W końcu usiedliście z partnerem na kanapie, żeby obejrzeć film, ale w 10. minucie oboje zasnęliście głęboko. Taka jest wasza rzeczywistość. Ten zmęczony widok, gdy śpicie oparci o siebie, to prawdziwa praca zespołowa.', title_pt = 'Ver um filme a dois... 🎬', body_pt = 'A criança adormeceu! Finalmente sentaram-se no sofá para ver um filme com o seu companheiro, mas ao 10.º minuto estavam os dois a dormir profundamente. Esta é a vossa realidade. Essa imagem cansada de adormecerem encostados um ao outro é a prova de um verdadeiro trabalho de equipa.', title_sv = 'Att se en film som par... 🎬', body_sv = 'Barnet sover! Äntligen satte du dig i soffan med din partner för att se en film, men efter 10 minuter hade ni båda somnat djupt. Det är er verklighet. Den trötta bilden av er som sover lutade mot varandra är ett tecken på verkligt lagarbete.', title_vi = 'Hai vợ chồng xem phim... 🎬', body_vi = 'Bé đã ngủ! Cuối cùng hai vợ chồng cũng ngồi xuống sofa xem phim, nhưng đến phút thứ 10 cả hai đã ngủ say. Đó là thực tế của mẹ. Khung cảnh mệt mỏi khi tựa vào nhau ngủ thiếp đi chính là biểu hiện của tinh thần đồng đội thật sự.', title_zh = '夫妻一起看电影…… 🎬', body_zh = '宝宝睡着了！你和伴侣终于坐到沙发上准备看部电影，可到第10分钟你们俩都睡熟了。这就是你们的现实。互相依偎着睡着的那副疲惫画面，正是真正团队合作的体现。' WHERE id = 'cacabcad-105f-4eff-bcae-aa81bf6e1cbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Migas en la cama 🍞', body_es = 'Abres los ojos por la mañana y la cama está llena de migas de galletas saladas. Resulta que al amanecer se ha organizado él solo el desayuno. En lugar de gritar, anota esta capacidad de resolver problemas por sí mismo en el Seguimiento del desarrollo como un recuerdo cómico.', title_fr = 'Des miettes dans le lit 🍞', body_fr = 'Vous ouvrez les yeux le matin et le lit est plein de miettes de crackers. Il s''est en fait organisé un petit-déjeuner tout seul à l''aube. Au lieu de crier, notez cette capacité à résoudre seul un problème dans le Suivi de développement, comme un souvenir comique.', title_hi = 'बिस्तर में टुकड़े 🍞', body_hi = 'सुबह आँख खोलती हैं और बिस्तर क्रैकर के टुकड़ों से भरा है। पता चला, उसने तड़के खुद ही अपना नाश्ता इंतज़ाम कर लिया। चिल्लाने के बजाय उसकी इस आज़ादी से समस्या सुलझाने की काबिलियत को ग्रोथ ट्रैकर में एक मज़ेदार याद की तरह दर्ज कीजिए।', title_id = 'Remah di tempat tidur 🍞', body_id = 'Pagi hari Anda membuka mata dan tempat tidur penuh remah kerupuk. Ternyata pagi-pagi buta ia sudah menyiapkan sarapan sendiri. Daripada berteriak, catat kemampuannya memecahkan masalah secara mandiri ini di Pelacak Perkembangan sebagai kenangan lucu.', title_ja = 'ベッドの中のくず 🍞', body_ja = '朝目を開けると、ベッドの中がクラッカーのくずだらけ。どうやら夜明け前に、自分で朝ごはんを用意したようです。どなる代わりに、この自分で問題を解決する力を、おかしな思い出として「発達トラッカー」に記録しましょう。', title_ko = '침대 속 부스러기 🍞', body_ko = '아침에 눈을 떴더니 침대가 크래커 부스러기투성이인가요? 알고 보니 새벽에 스스로 아침을 차려 먹었대요. 소리치는 대신 이 스스로 문제를 해결하는 능력을 웃긴 추억으로 성장 기록에 남겨 두세요.', title_nl = 'Kruimels in bed 🍞', body_nl = 'Je doet ''s ochtends je ogen open en het bed ligt vol crackerkruimels. Blijkbaar heeft hij al vroeg zijn eigen ontbijt geregeld. Ga niet schreeuwen, maar noteer dit zelfstandige probleemoplossende vermogen als grappige herinnering in de Groeitracker.', title_pl = 'Okruszki w łóżku 🍞', body_pl = 'Rano otwierasz oczy, a łóżko jest pełne okruchów krakersów. Okazuje się, że o świcie sam zorganizował sobie śniadanie. Zamiast krzyczeć, zapisz tę umiejętność samodzielnego rozwiązywania problemów w Śledzeniu rozwoju jako zabawne wspomnienie.', title_pt = 'Migalhas na cama 🍞', body_pt = 'Abre os olhos de manhã e a cama está cheia de migalhas de bolachas. Afinal, de madrugada organizou sozinho o pequeno-almoço. Em vez de gritar, registe esta capacidade de resolver problemas sozinho no Registo de Crescimento, como uma recordação cómica.', title_sv = 'Smulor i sängen 🍞', body_sv = 'Du öppnar ögonen på morgonen och sängen är full av kexsmulor. Det visar sig att barnet ordnat frukost åt sig själv i gryningen. Istället för att skrika, anteckna barnets förmåga att lösa problem på egen hand i Utvecklingsspåraren som ett roligt minne.', title_vi = 'Vụn bánh trên giường 🍞', body_vi = 'Sáng mở mắt ra, mẹ thấy giường đầy vụn bánh quy giòn. Hóa ra bé đã tự tổ chức bữa sáng từ tờ mờ sáng. Thay vì quát, hãy ghi lại khả năng tự giải quyết vấn đề này trong Theo dõi phát triển như một kỷ niệm hài hước.', title_zh = '床上的碎屑 🍞', body_zh = '早上睁开眼，床上满是饼干碎屑。原来宝宝天一亮就给自己安排了早餐。与其吼，不如把宝宝这种自己解决问题的能力，当作一段搞笑的回忆记在发育追踪里。' WHERE id = '45baf1a1-9599-41ad-8361-b1f8a05e79a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El masaje de hombros de papá 💆‍♂️', body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de él y recoger juguetes del suelo. En cuanto se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el pilar de la casa, y los pilares necesitan descansar y recuperarse sí o sí.', title_fr = 'Le massage des épaules par papa 💆‍♂️', body_fr = 'Vous êtes restée debout toute la journée et votre dos est en miettes à force de lui courir après et de ramasser les jouets. Dès que l''enfant dort, demandez à votre partenaire 10 minutes de massage des épaules. Vous êtes le pilier de la maison, et les piliers doivent absolument se reposer et se restaurer.', title_hi = 'पापा की कंधों वाली मालिश 💆‍♂️', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते, ज़मीन से खिलौने उठाते-उठाते कमर टूट रही है। बच्चे के सोते ही अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप घर का खंभा हैं, और खंभों को आराम करना और फिर से मज़बूत होना ज़रूरी है।', title_id = 'Pijat bahu dari pasangan 💆‍♂️', body_id = 'Hari ini kamu terlalu lama berdiri, punggungmu serasa patah karena mengejarnya dan memunguti mainan dari lantai. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasanganmu. Kamu tiang rumah ini, dan tiang wajib beristirahat dan dipulihkan.', title_ja = 'パパの肩もみ 💆‍♂️', body_ja = '今日は立ちっぱなしで、追いかけまわして、床のおもちゃを拾って、腰がくたくたですね。子どもが寝たらすぐ、パートナーに10分の肩もみをお願いして。あなたはこの家の柱です。柱だって、ちゃんと休んで回復しなくちゃ。', title_ko = '아빠의 어깨 마사지 💆‍♂️', body_ko = '오늘 하루 종일 서 있었고 아이를 쫓아다니며 장난감을 줍느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 이 집의 기둥이고, 기둥도 꼭 쉬고 회복해야 해요.', title_nl = 'Papa''s schoudermassage 💆‍♂️', body_nl = 'Je hebt vandaag veel op je benen gestaan en je rug breekt van het achter hem aan rennen en speelgoed oprapen. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de pijler van het huis, en pijlers moeten zeker rusten en hersteld worden.', title_pl = 'Masaż ramion od taty 💆‍♂️', body_pl = 'Dziś długo byłaś na nogach, plecy bolą cię od biegania za nim i zbierania zabawek z podłogi. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś filarem domu, a filary muszą odpoczywać i się regenerować.', title_pt = 'Massagem nos ombros do pai 💆‍♂️', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de correr atrás dele e apanhar brinquedos do chão. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o pilar desta casa, e os pilares precisam de descansar e ser restaurados.', title_sv = 'Axelmassage av pappa 💆‍♂️', body_sv = 'Du har stått på benen länge i dag och ryggen värker av allt springande efter barnet och plockande av leksaker från golvet. Så fort barnet somnar, be din partner om 10 minuters axelmassage. Du är hemmets pelare, och pelare måste vila och återhämta sig.', title_vi = 'Mát-xa vai từ chồng 💆‍♂️', body_vi = 'Hôm nay mẹ đứng cả ngày, lưng như muốn gãy vì chạy theo bé và nhặt đồ chơi dưới sàn. Ngay khi bé ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là trụ cột của gia đình, và trụ cột thì nhất định phải được nghỉ ngơi, phục hồi.', title_zh = '爸爸的肩膀按摩 💆‍♂️', body_zh = '今天你站了太久，追着宝宝跑、从地上捡玩具，腰都快断了。宝宝一睡着，就请伴侣给你按摩10分钟肩膀。你是这个家的顶梁柱，顶梁柱也一定要好好休息、好好修复。' WHERE id = '5b590891-270c-48fa-a5d7-d69f319ed48e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo hago yo solo! 🛑', body_es = 'Se empeña en atarse él solo los cordones, no lo consigue, se enfada, pero rechaza tu ayuda de malas maneras. Respira hondo. Para su futuro importa más un ego sin heridas que un horario sin retrasos. Espera.', title_fr = 'Je vais le faire tout seul ! 🛑', body_fr = 'Il veut absolument faire ses lacets tout seul, n''y arrive pas, s''énerve, mais refuse aussi votre aide avec agressivité. Respirez profondément. Pour son avenir, un ego intact compte bien plus qu''un emploi du temps chamboulé. Attendez.', title_hi = 'मैं खुद करूँगा! 🛑', body_hi = 'जूतों के फीते ज़रूर खुद बाँधना चाहता है, नहीं बाँध पाता, चिढ़ता है, पर आपकी मदद भी गुस्से से ठुकरा देता है। गहरी साँस लीजिए। बिगड़े हुए टाइम-टेबल से ज़्यादा, बिना ठेस पहुँचा अहं उसके भविष्य के लिए ज़रूरी है। इंतज़ार कीजिए।', title_id = 'Aku mau sendiri! 🛑', body_id = 'Ia bersikeras mengikat tali sepatunya sendiri, tidak bisa, kesal, tapi menolak bantuan Anda dengan galak. Tarik napas dalam. Ego yang tidak terluka jauh lebih penting bagi masa depannya daripada jadwal yang tidak berantakan. Tunggulah.', title_ja = '自分でやる！ 🛑', body_ja = '靴ひもをどうしても自分で結びたいのに、うまくいかずにイライラ。でもあなたが手伝おうとすると、激しく拒否します。深呼吸して。時間どおりに進むことより、傷つかない自尊心のほうが、この子の未来にはずっと大切です。待ちましょう。', title_ko = '내가 할 거야! 🛑', body_ko = '신발 끈을 꼭 자기가 묶겠다는데 안 되니까 화내면서도 엄마의 도움은 거칠게 거부하나요? 깊게 숨 쉬세요. 아이의 미래에는 망가진 일정보다 다치지 않은 자존감이 더 중요해요. 기다려 주세요.', title_nl = 'Ik doe het zelf! 🛑', body_nl = 'Hij wil per se zelf zijn veters strikken, het lukt niet, hij wordt boos, maar wijst jouw hulp agressief af. Haal diep adem. Een ongeschonden ego is voor zijn toekomst veel belangrijker dan een verstoorde planning. Wacht maar.', title_pl = 'Ja sam zrobię! 🛑', body_pl = 'Koniecznie chce sam zawiązać sznurówki, nie umie, denerwuje się, ale agresywnie odrzuca twoją pomoc. Weź głęboki oddech. Dla jego przyszłości nienaruszone ego jest ważniejsze niż naruszony harmonogram. Poczekaj.', title_pt = 'Eu é que faço! 🛑', body_pt = 'Quer mesmo atar sozinho os atacadores, não consegue, irrita-se, mas recusa a sua ajuda de forma agressiva. Respire fundo. Para o futuro dele, um ego que não sai ferido é mais importante do que um horário que fica estragado. Espere.', title_sv = 'Jag gör det själv! 🛑', body_sv = 'Barnet vill absolut knyta skosnörena själv, klarar det inte och blir arg, men avvisar ändå aggressivt din hjälp. Andas djupt. För barnets framtid är ett oskadat ego viktigare än ett schema som spricker. Vänta.', title_vi = 'Con tự làm! 🛑', body_vi = 'Bé nhất định tự buộc dây giày, làm không được thì bực bội, nhưng lại gạt phắt sự giúp đỡ của mẹ. Hãy hít thở sâu. Một cái tôi không bị tổn thương quan trọng cho tương lai của bé hơn nhiều so với một lịch trình bị lỡ. Hãy chờ đợi.', title_zh = '我自己来！🛑', body_zh = '非要自己系鞋带，系不好，生气了，却又激烈地拒绝你的帮忙。深吸一口气。对宝宝的将来来说，一个没受伤的自我，比一个被打乱的时间表重要得多。等一等吧。' WHERE id = '5ff3402c-285a-4d58-a123-bc33ce162448' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia del «¡Me ha mirado!» 👀', body_es = '¿En el parque ha roto a llorar a lágrima viva solo porque otro niño le ha mirado? Para un niño que está descubriendo sus límites sociales, hasta la mirada de otro puede ser una intromisión. Abrázale y distráele: «Solo estaba mirando tu camiseta tan bonita».', title_fr = 'Le drame du « Il m''a regardé ! » 👀', body_fr = 'Au parc, il a éclaté en sanglots simplement parce qu''un autre enfant l''a regardé ? Pour un enfant qui découvre ses limites sociales, même un regard peut sembler une intrusion. Serrez-le dans vos bras et détournez son attention : « Il regardait juste ton joli t-shirt. »', title_hi = '‘उसने मुझे देखा!’ की त्रासदी 👀', body_hi = 'पार्क में किसी दूसरे बच्चे ने बस उसकी ओर देखा, और वह फूट-फूटकर रोने लगा? जो बच्चा अपनी सामाजिक सीमाएँ अभी खोज रहा है, उसके लिए किसी की नज़र भी दखल लग सकती है। उसे गले लगाइए और ‘वह तो बस तुम्हारी सुंदर कमीज़ देख रहा था’ कहकर ध्यान बँटाइए।', title_id = 'Tragedi ''Dia lihat aku!'' 👀', body_id = 'Di taman ia menangis tersedu-sedu hanya karena anak lain melihatnya? Bagi anak yang baru menemukan batas sosialnya, tatapan orang lain pun bisa dianggap gangguan. Peluk ia, katakan ''Dia cuma melihat bajumu yang bagus'', dan alihkan pikirannya.', title_ja = '「あの子がこっち見た！」の悲劇 👀', body_ja = '公園でほかの子にただ見られただけで、大泣きしてしまった？社会的な境界を発見したばかりの子にとっては、人の視線さえ「入りこまれた」と感じることがあります。抱きしめて「あなたのすてきなシャツを見てたんだよ」と言って、気をそらしてあげましょう。', title_ko = '''쟤가 나 쳐다봤어!'' 대참사 👀', body_ko = '공원에서 다른 아이가 그저 쳐다봤다는 이유로 엉엉 울었나요? 사회적 경계를 막 발견하는 아이에게는 남의 시선조차 침범처럼 느껴질 수 있어요. 안아 주며 ''네 멋진 셔츠를 본 거야''라고 관심을 돌려 주세요.', title_nl = 'Het drama van ''Hij keek naar mij!'' 👀', body_nl = 'Begon hij in het park tranen met tuiten te huilen omdat een ander kind alleen maar naar hem keek? Voor een kind dat net zijn sociale grenzen ontdekt, kan zelfs een blik van een ander als inbreuk voelen. Knuffel hem en leid hem af: ''Hij keek alleen naar je mooie shirt.''', title_pl = 'Tragedia „On na mnie spojrzał!” 👀', body_pl = 'W parku rozpłakał się w głos tylko dlatego, że inne dziecko na niego spojrzało? Dla dziecka, które dopiero odkrywa granice społeczne, nawet cudze spojrzenie może być naruszeniem. Przytul go, powiedz „Patrzył tylko na twoją ładną koszulkę” i odwróć jego uwagę.', title_pt = 'A tragédia do "Ele olhou para mim!" 👀', body_pt = 'No parque, começou a chorar desalmadamente só porque outra criança olhou para ele? Para quem está a descobrir os limites sociais, até o olhar dos outros pode parecer uma intromissão. Abrace-o e distraia-o: "Estava só a olhar para a tua camisola tão bonita".', title_sv = 'Tragedin ”Hen tittade på mig!” 👀', body_sv = 'Började barnet gråta hejdlöst för att ett annat barn i parken bara tittade på det? För ett barn som just upptäcker sina sociala gränser kan till och med någon annans blick räknas som intrång. Krama barnet, säg ”Hen tittade bara på din fina tröja” och led bort tankarna.', title_vi = 'Bi kịch "Bạn ấy nhìn con!" 👀', body_vi = 'Ở công viên, bé khóc nức nở chỉ vì một bạn khác nhìn mình? Với đứa trẻ mới khám phá ranh giới xã hội, ngay cả ánh nhìn của người khác cũng có thể bị coi là xâm phạm. Hãy ôm bé và nói "Bạn ấy chỉ đang ngắm chiếc áo đẹp của con thôi" để đánh lạc hướng.', title_zh = '“他看我了！”的悲剧 👀', body_zh = '在公园里，就因为另一个孩子看了宝宝一眼，宝宝就嚎啕大哭？对刚开始发现社交边界的孩子来说，连别人的目光都可能算是“入侵”。抱住宝宝，说一句“他只是在看你漂亮的衣服”，转移宝宝的注意力。' WHERE id = '8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma con Cuentos inteligentes 🪄', body_es = 'Corretea por la habitación y se niega a meterse en la cama. Baja las luces. Crea una historia interesante en Cuentos inteligentes y léesela.', title_fr = 'Le calme avec les Contes intelligents 🪄', body_fr = 'Il court dans la chambre et refuse d''aller au lit. Baissez les lumières. Créez une histoire captivante dans les Contes intelligents et lisez-la-lui.', title_hi = 'स्मार्ट कहानियों से सुकून 🪄', body_hi = 'कमरे में दौड़ता है और बिस्तर में जाने से मना करता है। रोशनी धीमी कीजिए। स्मार्ट कहानियों में एक दिलचस्प कहानी बनाइए और पढ़िए।', title_id = 'Tenang bersama Dongeng Pintar 🪄', body_id = 'Ia berlarian di kamar dan menolak naik ke tempat tidur. Redupkan lampu. Ciptakan cerita yang menarik di Dongeng Pintar dan bacakan.', title_ja = 'スマートおはなしで落ち着こう 🪄', body_ja = '部屋を走りまわって、ベッドに入るのをいやがる。明かりを落としましょう。「スマートおはなし」でおもしろいお話をつくって、読んであげて。', title_ko = '스마트 동화로 차분하게 🪄', body_ko = '방을 뛰어다니며 침대에 들어가길 거부하나요? 불을 낮추세요. 스마트 동화에서 재미있는 이야기를 만들어 읽어 주세요.', title_nl = 'Rust met Slimme sprookjes 🪄', body_nl = 'Hij rent door de kamer en weigert in bed te gaan. Dim de lichten. Maak in Slimme sprookjes een spannend verhaal en lees het voor.', title_pl = 'Spokój z Mądrymi bajkami 🪄', body_pl = 'Biega po pokoju i nie chce wejść do łóżka. Przygaś światła. Stwórz w Mądrych bajkach ciekawą historię i przeczytaj ją.', title_pt = 'Calma com as Histórias Inteligentes 🪄', body_pt = 'Corre pelo quarto e recusa ir para a cama. Baixe as luzes. Crie uma história interessante nas Histórias Inteligentes e leia-a.', title_sv = 'Lugn med Smarta sagor 🪄', body_sv = 'Barnet springer runt i rummet och vägrar gå och lägga sig. Dämpa ljuset. Skapa en spännande berättelse i Smarta sagor och läs den.', title_vi = 'Bình yên cùng Truyện cổ tích thông minh 🪄', body_vi = 'Bé chạy quanh phòng và không chịu lên giường. Hãy giảm đèn. Tạo một câu chuyện thú vị trong Truyện cổ tích thông minh và đọc cho bé nghe.', title_zh = '用智慧童话安静下来 🪄', body_zh = '在房间里跑来跑去，就是不肯上床。把灯光调暗。在智慧童话里编一个有趣的故事，读给宝宝听吧。' WHERE id = 'b272e283-3b37-4825-9917-d8f7f4f54d69' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Poner los juguetes en fila 🚗', body_es = 'Ha puesto todos sus coches en fila de una punta a otra de la habitación con precisión milimétrica y no deja que ninguno cambie de sitio. Es una búsqueda de orden visual. Observa en silencio el trabajo de este pequeño arquitecto y no lo estropees.', title_fr = 'Aligner les jouets 🚗', body_fr = 'Il a aligné toutes ses voitures au millimètre près d''un bout à l''autre de la pièce et ne permet pas qu''on en déplace une seule. C''est une quête d''ordre visuel. Admirez en silence, de loin, le travail de ce petit architecte et ne le dérangez pas.', title_hi = 'खिलौनों को लाइन में लगाना 🚗', body_hi = 'कमरे के एक छोर से दूसरे छोर तक सारी गाड़ियाँ मिलीमीटर की सटीकता से लाइन में लगा दी हैं और एक की भी जगह बदलने नहीं देता। यह दिखने वाले क्रम की तलाश है। दूर से इस नन्हे वास्तुकार का काम चुपचाप देखिए और उसे मत बिगाड़िए।', title_id = 'Menjajarkan mainan 🚗', body_id = 'Ia menjajarkan semua mobilnya dengan ketelitian milimeter dari ujung kamar ke ujung lainnya, dan tidak membiarkan satu pun berpindah tempat. Ini pencarian keteraturan visual. Saksikan karya arsitek kecil ini diam-diam dari jauh dan jangan merusaknya.', title_ja = 'おもちゃを一列に並べる 🚗', body_ja = '部屋のはしからはしまで、車を全部ミリ単位の正確さで並べて、ひとつでも動かすのを許さない。これは目で見る秩序へのこだわりです。この小さな建築家の仕事を、そっと見守って、くずさないであげましょう。', title_ko = '장난감 줄 세우기 🚗', body_ko = '방 이쪽 끝부터 저쪽 끝까지 자동차를 밀리미터 단위로 정확하게 줄 세우고 하나도 못 옮기게 하나요? 시각적 질서를 찾는 중이에요. 이 작은 건축가의 작품을 멀리서 조용히 감상하고 흐트러뜨리지 마세요.', title_nl = 'Speelgoed op een rij zetten 🚗', body_nl = 'Hij heeft al zijn auto''s op de millimeter nauwkeurig op een rij gezet, van de ene kant van de kamer tot de andere, en niemand mag er ook maar één verplaatsen. Hij zoekt visuele orde. Kijk stil van een afstand naar het werk van deze kleine architect en verstoor het niet.', title_pl = 'Zabawki w rzędzie 🚗', body_pl = 'Ustawił wszystkie samochodziki w rzędzie z milimetrową dokładnością od jednego końca pokoju do drugiego i nie pozwala przesunąć ani jednego. To poszukiwanie wizualnego porządku. Obserwuj w ciszy z boku pracę tego małego architekta i jej nie psuj.', title_pt = 'Brinquedos em fila 🚗', body_pt = 'Pôs todos os carrinhos em fila, de uma ponta à outra do quarto, com precisão milimétrica, e não deixa mudar nem um de lugar. É uma procura de ordem visual. Assista em silêncio, à distância, ao trabalho deste pequeno arquiteto e não o estrague.', title_sv = 'Leksaker på rad 🚗', body_sv = 'Barnet har ställt upp alla sina bilar på rad med millimeterprecision från ena änden av rummet till den andra och låter inte ens en av dem flyttas. Det är ett sökande efter visuell ordning. Titta tyst från sidan på den lilla arkitektens arbete och stör inte.', title_vi = 'Xếp đồ chơi thành hàng 🚗', body_vi = 'Bé xếp tất cả ô tô thành hàng từ đầu này đến đầu kia căn phòng, chính xác đến từng milimét, và không cho xê dịch dù chỉ một chiếc. Đây là sự tìm kiếm trật tự thị giác. Hãy lặng lẽ ngắm "kiến trúc sư" tí hon làm việc từ xa và đừng phá hỏng.', title_zh = '把玩具排成一排 🚗', body_zh = '从房间这头到那头，把所有小汽车以毫米级的精准排成一排，一辆都不许挪动。这是在追求视觉上的秩序。在一旁静静地欣赏这位小建筑师的作品，别去破坏。' WHERE id = 'ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lectora secreta en la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie ni desahogarte. Entra en la Comunidad Anacan y limítate a leer. Ver cómo otras madres lidian con las mismas crisis absurdas es la terapia silenciosa más poderosa.', title_fr = 'Lire en secret la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie ni de rien expliquer à personne, ni de vous confier. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir comment d''autres mamans font face aux mêmes crises absurdes est la plus puissante des thérapies silencieuses.', title_hi = 'कम्युनिटी की चुपचाप पाठक बनना 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना या दिल की बात कहना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। यह देखना कि दूसरी माँएँ भी ऐसे ही बेतुके संकटों से कैसे जूझती हैं, सबसे ताकतवर खामोश थेरेपी है।', title_id = 'Menjadi pembaca diam di komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun atau curhat kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat bagaimana ibu-ibu lain menghadapi krisis absurd yang sama adalah terapi diam yang paling ampuh.', title_ja = 'コミュニティで読むだけの人に 💬', body_ja = 'とても疲れていて、誰にも何も説明したくないし、話したくもない。Anacanコミュニティを開いて、読むだけにしましょう。ほかのママたちが同じようなおかしなかんしゃくとどう向き合っているかを見ることが、いちばん強い静かなセラピーになります。', title_ko = '커뮤니티의 숨은 독자 되기 💬', body_ko = '너무 지쳐서 누구에게도 설명하거나 털어놓고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들이 똑같이 엉뚱한 위기를 어떻게 헤쳐 가는지 보는 것이 가장 강력한 조용한 치료예요.', title_nl = 'Stiekem meelezen in de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen of je hart luchten. Ga naar de Anacan Community en lees alleen mee. Zien hoe andere mama''s met precies dezelfde absurde crisissen omgaan, is de sterkste stille therapie.', title_pl = 'Cichy czytelnik w Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć ani się zwierzać. Wejdź do Społeczności Anacan i tylko czytaj. Widok tego, jak inne mamy radzą sobie z tymi samymi absurdalnymi kryzysami, to najsilniejsza cicha terapia.', title_pt = 'Leitora secreta na comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém nem desabafar. Entre na Comunidade Anacan e limite-se a ler. Ver como outras mães lidam com as mesmas crises absurdas é a terapia silenciosa mais poderosa.', title_sv = 'Att vara en dold läsare i gemenskapen 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon eller prata av dig. Gå in i Anacan Community och bara läs. Att se hur andra mammor hanterar samma absurda kriser är den starkaste tysta terapin.', title_vi = 'Làm người đọc thầm trong Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích hay tâm sự với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác đối mặt với những cơn khủng hoảng "khó đỡ" giống hệt thế nào chính là liệu pháp thầm lặng mạnh mẽ nhất.', title_zh = '在社区里悄悄当个读者 💬', body_zh = '累坏了，什么都不想跟任何人解释，也不想倾诉？进入Anacan社区，只当个读者就好。看到其他妈妈怎样应对同样荒诞的崩溃，就是最有力的无声疗愈。' WHERE id = '0136ed32-a803-4c48-aa0d-ab3379945e1c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la cuchara del tamaño equivocado 🥄', body_es = 'Casi estalla una revolución porque le diste la sopa con la cuchara grande: «¡Yo quería la cuchara pequeña!». Aunque la comida sea la misma, en su lógica el tamaño de la cuchara cambia el sabor. No discutas: cambia la cuchara y guarda tu energía.', title_fr = 'La crise de la mauvaise taille de cuillère 🥄', body_fr = 'Une révolution a failli éclater parce que vous lui avez donné la soupe avec une grande cuillère. « Je voulais la petite cuillère ! » Même si le plat est le même, dans sa logique, la taille de la cuillère change le goût. Ne discutez pas, changez simplement de cuillère et préservez votre énergie.', title_hi = 'गलत चम्मच का संकट 🥄', body_hi = 'सूप बड़े चम्मच से दिया, तो लगभग क्रांति छिड़ गई। ‘मुझे छोटा चम्मच चाहिए था!’ खाना वही हो, फिर भी उसके तर्क में चम्मच का आकार खाने का स्वाद बदल देता है। बहस मत कीजिए, बस चम्मच बदल दीजिए और अपनी ऊर्जा बचाइए।', title_id = 'Krisis salah ukuran sendok 🥄', body_id = 'Hampir terjadi revolusi karena Anda memberinya sup dengan sendok besar. ''Aku maunya sendok kecil!'' Meski makanannya sama, menurut logikanya ukuran sendok mengubah rasa makanan. Jangan berdebat, cukup ganti sendoknya dan hemat energi Anda.', title_ja = 'スプーンのサイズ大問題 🥄', body_ja = 'スープを大きいスプーンで出したら、あやうく革命が起きるところでした。「小さいスプーンがよかったの！」中身が同じでも、この子の理屈では、スプーンの大きさで料理の味が変わるんです。言い合わずに、スプーンをかえてエネルギーを守りましょう。', title_ko = '숟가락 크기 위기 🥄', body_ko = '수프를 큰 숟가락으로 줬다고 혁명이 날 뻔했나요? ''작은 숟가락 원했단 말이야!'' 음식은 같아도 아이의 논리에선 숟가락 크기가 맛을 바꿔요. 따지지 말고 숟가락만 바꿔 주고 에너지를 아끼세요.', title_nl = 'De crisis van de verkeerde lepel 🥄', body_nl = 'Er brak bijna een revolutie uit omdat je de soep met een grote lepel gaf: ''Ik wilde de kleine lepel!'' Ook al is het eten hetzelfde, in zijn logica verandert de grootte van de lepel de smaak. Ga niet in discussie, wissel gewoon de lepel en spaar je energie.', title_pl = 'Kryzys złej łyżki 🥄', body_pl = 'O mało nie wybuchła rewolucja, bo podałaś zupę dużą łyżką. „Chciałem małą łyżkę!” Choć jedzenie jest to samo, w jego logice rozmiar łyżki zmienia smak jedzenia. Nie kłóć się, po prostu zmień łyżkę i oszczędzaj energię.', title_pt = 'A crise da colher do tamanho errado 🥄', body_pt = 'Quase houve uma revolução porque lhe deu a sopa com a colher grande: "Eu queria a colher pequena!". Mesmo que a comida seja igual, na lógica dele o tamanho da colher muda o sabor. Não discuta: troque a colher e poupe a sua energia.', title_sv = 'Krisen med fel skedstorlek 🥄', body_sv = 'Det blev nästan revolution för att du gav soppan med en stor sked. ”Jag ville ha en liten sked!” Även om maten är densamma ändrar skedens fysiska storlek smaken på maten i barnets logik. Bråka inte, byt bara sked och spara din energi.', title_vi = 'Khủng hoảng sai cỡ thìa 🥄', body_vi = 'Suýt nữa thì nổ ra "cách mạng" chỉ vì mẹ đút súp bằng thìa to: "Con muốn thìa nhỏ cơ!". Dù thức ăn vẫn thế, trong logic của bé, kích cỡ chiếc thìa làm thay đổi hương vị món ăn. Đừng tranh cãi, chỉ cần đổi thìa và giữ năng lượng cho bản thân.', title_zh = '勺子大小不对的危机 🥄', body_zh = '就因为你用大勺子喂汤，差点爆发一场“革命”：“我要的是小勺子！”食物虽然一样，但在宝宝的逻辑里，勺子的大小会改变饭菜的味道。别争了，换个勺子，保存你的精力吧。' WHERE id = 'b9bc7eed-7b9f-4aa8-8301-118abf554ade' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La obsesión del «¡Tápame!» 🛏️', body_es = 'Justo cuando se va a dormir, grita: «¡Se ha destapado la punta de la manta, tápame!». Que los bordes de la manta estén rectos es para él cuestión de vida o muerte. Estírala como si estuviera planchada y sonríe por dentro ante estos rituales tan cómicos para dormir.', title_fr = 'L''obsession du « Couvre-moi ! » 🛏️', body_fr = 'Il est sur le point de s''endormir et crie : « Le coin de la couverture s''est ouvert, couvre-moi ! » Pour lui, des bords de couverture parfaitement droits sont vitaux. Lissez la couverture comme si vous la repassiez et souriez intérieurement de ces rituels du coucher comiques.', title_hi = '‘मुझे ढको!’ की सनक 🛏️', body_hi = 'बस सोने ही वाला है कि चिल्लाता है, ‘रज़ाई का कोना खुल गया, मुझे ढको!’ रज़ाई के किनारों का बिल्कुल सीधा होना उसके लिए ज़िंदगी-मौत का सवाल है। रज़ाई को इस्त्री जैसा सीधा कीजिए और सोने की इन मज़ेदार रस्मों पर मन ही मन मुस्कुराइए।', title_id = 'Obsesi ''Selimuti aku!'' 🛏️', body_id = 'Tepat saat akan terlelap, ia berteriak: ''Ujung selimutnya terbuka, selimuti aku!'' Bagi dia, pinggir selimut harus benar-benar lurus. Rapikan selimut itu seolah baru disetrika, dan tersenyumlah dalam hati pada ritual tidur yang lucu ini.', title_ja = '「かけて！」へのこだわり 🛏️', body_ja = 'もう少しで寝つくところで「毛布のはしがめくれた、かけて！」と叫ぶ。毛布のふちがまっすぐであることが、この子には一大事なんです。毛布をアイロンをかけたようにきれいに整えて、このおかしな寝る前の儀式に、心の中でほほえみましょう。', title_ko = '''이불 덮어 줘!'' 집착 🛏️', body_ko = '막 잠들려는데 ''이불 끝이 열렸어, 덮어 줘!'' 하고 소리치나요? 이불 가장자리가 반듯한 게 아이에게는 아주 중요해요. 다림질하듯 이불을 펴 주고 이 웃긴 잠자리 의식에 속으로 미소 지어 보세요.', title_nl = 'De ''Dek me toe!''-obsessie 🛏️', body_nl = 'Net als hij in slaap valt, roept hij: ''Het puntje van de deken is open, dek me toe!'' Dat de randen van de deken perfect recht liggen, is voor hem van levensbelang. Strijk die deken glad alsof hij gestreken is en glimlach vanbinnen om deze grappige slaaprituelen.', title_pl = 'Obsesja „Przykryj mnie!” 🛏️', body_pl = 'Już ma zasnąć, a krzyczy: „Róg kołdry się odkrył, przykryj mnie!”. Idealnie proste brzegi kołdry mają dla niego życiowe znaczenie. Wygładź kołdrę jak wyprasowaną i uśmiechnij się w duchu do tych zabawnych rytuałów zasypiania.', title_pt = 'A obsessão do "Tapa-me!" 🛏️', body_pt = 'Está quase a adormecer e grita: "A ponta do cobertor destapou-se, tapa-me!". Que as bordas do cobertor estejam bem direitas é de importância vital para ele. Estique o cobertor como se estivesse passado a ferro e sorria por dentro destes rituais de deitar tão cómicos.', title_sv = 'Besattheten ”Täck över mig!” 🛏️', body_sv = 'Precis när barnet ska somna skriker det: ”Hörnet på täcket åkte av, täck över mig!” Att täckets kanter ligger helt raka är livsviktigt för barnet. Släta till täcket som om det vore struket och le inombords åt de roliga läggningsritualerna.', title_vi = 'Ám ảnh "Đắp chăn cho con!" 🛏️', body_vi = 'Sắp ngủ thì bé hét lên: "Góc chăn bị hở rồi, mẹ đắp cho con!". Với bé, mép chăn nhất định phải phẳng phiu là chuyện sống còn. Hãy vuốt phẳng chiếc chăn như vừa là ủi và thầm mỉm cười trước những nghi thức đi ngủ ngộ nghĩnh này.', title_zh = '“给我盖好！”的执着 🛏️', body_zh = '马上就要睡着了，大喊：“被子角掀开了，给我盖好！”被子边一定要平平整整，对宝宝来说是天大的事。把被子弄得像熨过一样平，在心里对这些搞笑的睡前仪式笑一笑吧。' WHERE id = 'c2cb9b1d-61a5-43c0-97ec-813152f9cfe1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por las tiritas 🩹', body_es = 'Ha encontrado una herida invisible en su cuerpo e insiste en que le pongas una tirita. No es dolor físico, es pura necesidad de atención y cariño de mamá. Ponle la tirita y dale un beso: créeme, el día estará salvado.', title_fr = 'L''amour des pansements 🩹', body_fr = 'Il a trouvé une blessure invisible sur son corps et exige que vous y colliez un pansement. Ce n''est pas une douleur physique, mais un pur besoin d''attention et de tendresse de maman. Collez ce petit pansement et faites un bisou, croyez-nous, votre journée sera sauvée.', title_hi = 'बैंडेज से प्यार 🩹', body_hi = 'शरीर पर एक अदृश्य चोट ढूँढ ली और ज़िद करता है कि वहाँ बैंडेज लगाई जाए। यह शारीरिक दर्द नहीं, बस माँ के ध्यान और प्यार की ज़रूरत है। वह छोटी बैंडेज लगाकर चूम लीजिए, यकीन मानिए, आपका दिन बच जाएगा।', title_id = 'Cinta plester 🩹', body_id = 'Ia menemukan luka tak terlihat di tubuhnya dan bersikeras meminta Anda menempelkan plester di sana. Ini bukan rasa sakit fisik, murni kebutuhan akan perhatian dan kasih sayang ibunya. Tempelkan plester kecil itu lalu cium, percayalah, hari Anda akan terselamatkan.', title_ja = '絆創膏が大好き 🩹', body_ja = '体に見えない傷を見つけて、どうしても絆創膏を貼ってとせがむ。これは体の痛みではなく、ママからの注目とやさしさがほしいだけ。小さな絆創膏を貼ってキスしてあげて。きっと一日が救われますよ。', title_ko = '반창고 사랑 🩹', body_ko = '몸에서 보이지 않는 상처를 찾아내고 꼭 반창고를 붙여 달라고 하나요? 몸이 아픈 게 아니라 엄마의 관심과 다정함이 필요한 거예요. 작은 반창고를 붙이고 뽀뽀해 주세요, 정말 하루가 평화로워질 거예요.', title_nl = 'Pleisterliefde 🩹', body_nl = 'Hij heeft een onzichtbaar wondje gevonden en wil per se dat je er een pleister op plakt. Dit is geen lichamelijke pijn, maar puur behoefte aan aandacht en medeleven van mama. Plak dat kleine pleistertje en geef er een kus op: geloof ons, je dag is gered.', title_pl = 'Miłość do plasterków 🩹', body_pl = 'Znalazł na ciele niewidzialną ranę i uparcie domaga się plasterka. To nie fizyczny ból, tylko potrzeba uwagi i czułości mamy. Przyklej mały plasterek i pocałuj, uwierz, uratujesz dzień.', title_pt = 'O amor pelos pensos 🩹', body_pt = 'Descobriu no corpo uma ferida invisível e insiste que lhe ponha um penso. Não é dor física, é pura necessidade da atenção e do carinho da mãe. Cole o pensinho e dê-lhe um beijo: acredite, o dia vai ficar salvo.', title_sv = 'Kärlek till plåster 🩹', body_sv = 'Barnet har hittat ett osynligt sår på kroppen och kräver envist att du sätter ett plåster där. Det är inte fysisk smärta, utan ett rent behov av uppmärksamhet och omtanke från mamma. Sätt på det lilla plåstret och pussa, tro mig, dagen är räddad.', title_vi = 'Tình yêu với băng cá nhân 🩹', body_vi = 'Bé phát hiện một vết thương vô hình trên người và nhất quyết đòi mẹ dán băng cá nhân. Đây không phải là đau thể chất, mà chỉ là nhu cầu được mẹ quan tâm và thương yêu. Hãy dán miếng băng nhỏ và hôn một cái, tin đi, ngày của mẹ sẽ được cứu.', title_zh = '对创可贴的爱 🩹', body_zh = '在身上找到一个看不见的伤口，坚持要你在那儿贴上创可贴。这不是身体上的疼，纯粹是需要妈妈的关注和疼爱。贴上那个小创可贴，再亲一下，相信我，这一天就得救了。' WHERE id = '4aca275a-17a5-44c6-88b5-fa54de701839' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El placer visual del silencio 🤫', body_es = 'El caos de casa por fin se ha acabado y se ha dormido. ¡No corras a fregar los platos! Abre el Medidor de sonido y, mirando el silencio absoluto de la habitación (0-10 decibelios), siente durante 15 minutos cómo descansa tu cerebro y cómo te cura este silencio visual.', title_fr = 'Le plaisir visuel du silence 🤫', body_fr = 'Le chaos de la maison est enfin terminé et il s''est endormi. Ne courez pas faire la vaisselle ! Ouvrez le Sonomètre et, en regardant le silence absolu de la pièce (0 à 10 décibels), sentez pendant 15 minutes votre cerveau se reposer et ce silence visuel vous réparer.', title_hi = 'खामोशी का दिखने वाला सुकून 🤫', body_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई और वह सो गया। बर्तन धोने मत दौड़िए! साउंड मीटर खोलिए, कमरे की पूरी खामोशी (0-10 डेसिबल) देखते हुए 15 मिनट में महसूस कीजिए कि आपका दिमाग कैसे आराम पाता है और यह दिखती खामोशी आपको कैसे ठीक करती है।', title_id = 'Nikmatnya hening secara visual 🤫', body_id = 'Kekacauan di rumah akhirnya berakhir dan ia tertidur. Jangan buru-buru mencuci piring! Buka Pengukur Suara, lihat keheningan total kamar (0-10 desibel), dan selama 15 menit rasakan bagaimana otak Anda beristirahat dan keheningan visual ini memulihkan Anda.', title_ja = '静けさを目で味わう 🤫', body_ja = '家の中のカオスがようやく終わって、眠りにつきました。洗いものに走らないで！「サウンドメーター」を開いて、部屋の完全な静けさ（0〜10デシベル）を眺めながら、15分で脳がどれほど休まるか、この目に見える静けさがどれほど癒やしてくれるかを感じましょう。', title_ko = '고요의 시각적 즐거움 🤫', body_ko = '집 안의 혼돈이 드디어 끝나고 아이가 잠들었어요. 설거지하러 달려가지 마세요! 소음 측정기를 열고 방의 완전한 고요(0~10데시벨)를 보며 15분 동안 머리가 쉬고, 이 시각적 고요가 나를 치유하는 걸 느껴 보세요.', title_nl = 'Het visuele genot van stilte 🤫', body_nl = 'De chaos in huis is eindelijk voorbij en hij slaapt. Ren niet naar de afwas! Open de Geluidsmeter, kijk naar die absolute stilte (0-10 decibel) in de kamer en voel 15 minuten lang hoe je brein tot rust komt en hoe deze visuele stilte je heelt.', title_pl = 'Wizualna rozkosz ciszy 🤫', body_pl = 'Domowy chaos wreszcie się skończył, a on zasnął. Nie biegnij zmywać naczyń! Otwórz Miernik dźwięku i patrząc na absolutną ciszę w pokoju (0-10 decybeli), poczuj przez 15 minut, jak twój mózg odpoczywa, a ta wizualna cisza cię leczy.', title_pt = 'O prazer visual do silêncio 🤫', body_pt = 'O caos da casa finalmente acabou e ele adormeceu. Não corra a lavar a loiça! Abra o Medidor de Som e, a olhar para o silêncio absoluto do quarto (0-10 decibéis), sinta durante 15 minutos como o seu cérebro descansa e como este silêncio visual a cura.', title_sv = 'Tystnadens visuella njutning 🤫', body_sv = 'Kaoset hemma är äntligen över och barnet har somnat. Spring inte iväg och diska! Öppna Ljudmätaren och titta på den totala tystnaden i rummet (0-10 decibel), så känner du under 15 minuter hur hjärnan vilar och hur den visuella stillheten läker dig.', title_vi = 'Niềm vui nhìn thấy sự im lặng 🤫', body_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc và bé đã ngủ. Đừng vội đi rửa bát! Hãy mở Đo âm thanh, nhìn sự im lặng tuyệt đối trong phòng (0-10 decibel) và cảm nhận trong 15 phút não bộ mình được nghỉ ngơi, sự tĩnh lặng hiện ra trước mắt đang chữa lành cho mẹ thế nào.', title_zh = '看得见的安静享受 🤫', body_zh = '家里的混乱终于结束，宝宝睡着了。别急着去洗碗！打开分贝仪，看着房间里那份绝对的安静（0-10分贝），在15分钟里感受大脑是怎样休息下来、这份看得见的安静又是怎样治愈你的。' WHERE id = '6549682b-784d-4e30-b184-53c2ea51b45f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arquitectura de arena 🏰', body_es = 'En el arenero del parque cava tan hondo como si buscara un tesoro. Va lleno de barro. Pero no interrumpas su momento de descubrimiento. La ropa apta para ensuciarse que elegiste antes con Tiempo y ropa te permite disfrutar de la escena sin estrés.', title_fr = 'Architecture de sable 🏰', body_fr = 'Dans le bac à sable du parc, il creuse si profond qu''on dirait qu''il cherche un trésor. Il est couvert de boue. Mais n''interrompez pas ce moment de découverte. Les vêtements adaptés aux salissures, choisis à l''avance avec Météo et tenue, vous permettent de regarder la scène sans stress.', title_hi = 'रेत की वास्तुकला 🏰', body_hi = 'पार्क के सैंडपिट में इतना गहरा खोद रहा है जैसे खज़ाना ढूँढ रहा हो। कपड़े कीचड़ से सने हैं। पर उसकी इस खोज के पल को मत तोड़िए। मौसम और कपड़े से पहले से चुने गंदे होने लायक कपड़े आपको यह नज़ारा बिना तनाव देखने का मौका देते हैं।', title_id = 'Arsitektur pasir 🏰', body_id = 'Di bak pasir taman ia menggali begitu dalam seolah mencari harta karun. Seluruh tubuhnya penuh lumpur. Tapi jangan ganggu momen penemuannya ini. Pakaian yang tahan kotor, yang sudah Anda pilih sebelumnya lewat Cuaca dan Pakaian, memberi Anda kesempatan menyaksikan pemandangan ini tanpa stres.', title_ja = '砂の建築 🏰', body_ja = '公園の砂場で、宝物をさがしているかのように深く深く掘っています。体じゅう泥だらけ。でも、この発見の瞬間をじゃましないで。「天気と服装」で前もって選んでおいた、汚れてもいい服のおかげで、この光景をストレスなく見守れます。', title_ko = '모래 건축 🏰', body_ko = '공원 모래밭에서 보물이라도 찾듯 깊이 파고 온몸이 흙투성이인가요? 그래도 이 발견의 순간을 깨지 마세요. 날씨와 옷차림 도구로 미리 고른 더러워져도 괜찮은 옷 덕분에 이 장면을 스트레스 없이 지켜볼 수 있어요.', title_nl = 'Zandarchitectuur 🏰', body_nl = 'In de zandbak in het park graaft hij zo diep alsof hij een schat zoekt. Hij zit onder de modder. Maar verstoor dit ontdekkingsmoment niet. Dankzij de kleren die je vooraf met Weer en kleding hebt gekozen en die vies mogen worden, kun je stressvrij toekijken.', title_pl = 'Architektura z piasku 🏰', body_pl = 'W piaskownicy w parku kopie tak głęboko, jakby szukał skarbu. Cały jest w błocie. Ale nie przerywaj mu tej chwili odkrywania. Ubrania na brudzenie, które wybrałaś wcześniej z narzędziem Pogoda i ubiór, pozwalają ci spokojnie, bez stresu obserwować ten widok.', title_pt = 'Arquitetura de areia 🏰', body_pt = 'Na caixa de areia do parque, escava tão fundo que parece andar à procura de um tesouro. Está todo sujo. Mas não interrompa este momento de descoberta. A roupa própria para sujar, escolhida antes com o Tempo e Roupa, dá-lhe a hipótese de ver esta cena sem stress.', title_sv = 'Sandarkitektur 🏰', body_sv = 'I sandlådan i parken gräver barnet så djupt att det verkar leta efter en skatt. Kläderna är fulla av lera. Men avbryt inte upptäckarstunden. Kläder som tål smuts, som du valt i förväg med hjälp av Väder och kläder, ger dig chansen att titta på utan stress.', title_vi = 'Kiến trúc cát 🏰', body_vi = 'Ở hố cát công viên, bé đào sâu như đang tìm kho báu. Người ngợm lấm lem bùn đất. Nhưng đừng cắt ngang khoảnh khắc khám phá này. Bộ đồ "chịu bẩn" mẹ đã chọn trước nhờ Thời tiết và trang phục sẽ giúp mẹ ngắm cảnh này mà không căng thẳng.', title_zh = '沙子建筑 🏰', body_zh = '在公园的沙坑里挖得那么深，好像在寻宝。浑身都是泥。但别打断这个探索的时刻。借助天气与穿衣提前挑好不怕弄脏的衣服，让你可以毫无压力地欣赏这幅画面。' WHERE id = 'c51feab8-8101-47a7-82b7-0a8e946ff974' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deporte de tarde: saltar encima de papá 🤸‍♂️', body_es = 'No ha podido gastar energía y no quiere ir a la cama. Tumba a papá en el sofá y deja que el peque salte encima de él. Los ruidos cómicos de papá llenarán la habitación de carcajadas y toda esa energía sobrante se agotará en segundos.', title_fr = 'Sport du soir : sauter sur papa 🤸‍♂️', body_fr = 'Il n''a pas pu se dépenser et ne veut pas aller au lit. Allongez papa sur le canapé et laissez l''enfant sauter sur lui. Les bruits comiques de papa rempliront la pièce d''éclats de rire et tout ce surplus d''énergie s''épuisera en quelques secondes.', title_hi = 'शाम का व्यायाम: पापा पर कूदना 🤸‍♂️', body_hi = 'ऊर्जा निकाल नहीं पाया और सोने नहीं जाना चाहता। पापा को सोफ़े पर लिटाइए और बच्चे को उन पर कूदने दीजिए। पापा की मज़ेदार आवाज़ें कमरे को ठहाकों से भर देंगी और वह सारी अतिरिक्त ऊर्जा सेकंडों में खत्म हो जाएगी।', title_id = 'Olahraga malam: melompat di atas Ayah 🤸‍♂️', body_id = 'Ia belum sempat menyalurkan energinya dan tidak mau tidur. Minta Ayah berbaring di sofa dan biarkan anak melompat-lompat di atasnya. Suara lucu Ayah akan membuat kamar penuh tawa dan semua energi berlebih itu habis dalam hitungan detik.', title_ja = '夜の運動 - パパの上でジャンプ 🤸‍♂️', body_ja = 'エネルギーを発散しきれず、寝たがらない。パパにソファで横になってもらい、子どもにその上でジャンプさせてあげましょう。パパのおもしろい声で部屋は笑い声でいっぱいになり、あり余ったエネルギーはあっという間に使いきれます。', title_ko = '저녁 운동 - 아빠 위에서 점프 🤸‍♂️', body_ko = '에너지를 다 쓰지 못해 자러 가기 싫어하나요? 아빠를 소파에 눕히고 아이가 그 위에서 뛰게 해 주세요. 아빠의 웃긴 소리가 방을 웃음바다로 만들고, 남은 에너지가 몇 초 만에 바닥날 거예요.', title_nl = 'Avondsport: springen op papa 🤸‍♂️', body_nl = 'Hij is zijn energie niet kwijtgeraakt en wil niet naar bed. Laat papa op de bank gaan liggen en laat je kind op hem springen. Papa''s grappige geluiden vullen de kamer met geschater en al die extra energie is binnen een paar seconden op.', title_pl = 'Wieczorny trening: skakanie po tacie 🤸‍♂️', body_pl = 'Nie wyładował energii i nie chce iść do łóżka. Połóż tatę na kanapie i pozwól dziecku po nim skakać. Śmieszne odgłosy taty wypełnią pokój śmiechem, a cała nadmiarowa energia zniknie w kilka sekund.', title_pt = 'Desporto ao fim do dia: saltar em cima do pai 🤸‍♂️', body_pt = 'Não conseguiu gastar a energia e não quer ir para a cama. Deite o pai no sofá e deixe a criança saltar-lhe para cima. Os sons cómicos do pai vão encher o quarto de gargalhadas e toda aquela energia a mais esgota-se em segundos.', title_sv = 'Kvällsträning: hoppa på pappa 🤸‍♂️', body_sv = 'Barnet har inte fått ur sig energin och vill inte gå och lägga sig. Låt pappa lägga sig i soffan och låt barnet hoppa på honom. Pappas roliga ljud fyller rummet med skratt, och all överskottsenergi tar slut på några sekunder.', title_vi = 'Thể dục buổi tối: nhảy trên người bố 🤸‍♂️', body_vi = 'Bé chưa xả hết năng lượng và không muốn lên giường. Hãy để bố nằm trên sofa và cho bé nhảy trên người bố. Những âm thanh hài hước của bố sẽ khiến cả phòng cười vang và mọi năng lượng dư thừa sẽ cạn sạch chỉ trong vài giây.', title_zh = '晚间运动：在爸爸身上蹦蹦跳 🤸‍♂️', body_zh = '精力没释放完，就是不想上床。让爸爸躺在沙发上，让宝宝在他身上蹦。爸爸发出的搞笑声音会让房间里充满笑声，多余的精力几秒钟就耗光了。' WHERE id = '95e37724-7f25-4dc6-a06e-d194ca45d333' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá también se cuida 🥗', body_es = '¿Has pensado 3 menús distintos para que él coma y tú te has vuelto a quedar con hambre? Elige en el Plan de alimentación una comida energizante, rica en hierro y calcio, que se prepara en 10 minutos y que no es solo para niños, sino también para mamás, y siéntete valorada.', title_fr = 'Maman prend soin d''elle 🥗', body_fr = 'Vous avez imaginé 3 menus différents pour le nourrir, et vous, vous êtes encore restée le ventre vide ? Dans le Plan de nutrition, choisissez un déjeuner énergisant riche en fer et en calcium, prêt en 10 minutes, pensé non seulement pour les enfants mais aussi pour les mamans, et prenez soin de vous.', title_hi = 'माँ का अपना ख्याल 🥗', body_hi = 'उसका पेट भरने के लिए 3 अलग मेन्यू सोचे, और आप फिर से भूखी रह गईं? फ़ीडिंग प्लान सेक्शन से, जो सिर्फ़ बच्चों के लिए नहीं, माँओं के लिए भी है, 10 मिनट में बनने वाला, ऊर्जा देने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और खुद को कीमती महसूस कीजिए।', title_id = 'Ibu merawat diri sendiri 🥗', body_id = 'Anda memikirkan 3 menu berbeda untuk membuatnya kenyang, tapi Anda sendiri kelaparan lagi? Dari Rencana Nutrisi, yang bukan hanya untuk anak tapi juga untuk ibu, pilih makan siang berenergi kaya zat besi dan kalsium yang siap dalam 10 menit, dan rasakan bahwa Anda berharga.', title_ja = 'ママのセルフケア 🥗', body_ja = 'この子のために3種類のメニューを考えたのに、自分はまた食べそびれた？「栄養管理ツール」から、子どもだけでなくママにも元気をくれる、10分でできる鉄分とカルシウムたっぷりのランチを選んで、自分を大切にしましょう。', title_ko = '엄마의 셀프 케어 🥗', body_ko = '아이를 먹이려고 메뉴를 3가지나 고민했는데 정작 엄마는 또 굶었나요? 식단 계획 섹션에서 아이뿐 아니라 엄마에게도 힘이 되는, 10분이면 만드는 철분과 칼슘이 풍부한 식사를 골라 나를 소중히 대해 주세요.', title_nl = 'Mama zorgt voor zichzelf 🥗', body_nl = 'Drie verschillende menu''s bedacht om hem te eten te geven, maar zelf weer niets gegeten? Kies in het Voedingsplan een energierijke lunch, rijk aan ijzer en calcium en in 10 minuten klaar, niet alleen voor kinderen maar ook voor mama''s, en voel dat je ertoe doet.', title_pl = 'Mama dba o siebie 🥗', body_pl = 'Wymyśliłaś 3 różne menu, żeby go nakarmić, a sama znowu zostałaś głodna? Wybierz w sekcji plan karmienia energetyczny obiad bogaty w żelazo i wapń, gotowy w 10 minut, nie tylko dla dzieci, ale i dla mam, i poczuj, że jesteś ważna.', title_pt = 'A mãe também cuida de si 🥗', body_pt = 'Pensou em 3 menus diferentes para ele comer, mas a mãe voltou a ficar com fome? Escolha no Registo de Alimentação um almoço energético, rico em ferro e cálcio, pronto em 10 minutos, não só para crianças mas também para mães, e sinta-se valorizada.', title_sv = 'Mammas omsorg om sig själv 🥗', body_sv = 'Du hittade på 3 olika menyer för att få barnet mätt, men själv blev du hungrig igen? Välj i matplanen en energigivande lunch rik på järn och kalcium, som inte bara är för barn utan också för mammor och tar 10 minuter, och känn dig värdefull.', title_vi = 'Mẹ chăm sóc bản thân 🥗', body_vi = 'Mẹ nghĩ ra 3 thực đơn khác nhau để bé ăn no, còn bản thân thì lại nhịn đói? Hãy vào Kế hoạch dinh dưỡng, chọn một bữa trưa giàu sắt và canxi, nạp năng lượng, nấu trong 10 phút, không chỉ cho trẻ mà cho cả mẹ, và cảm nhận giá trị của chính mình.', title_zh = '妈妈的自我照顾 🥗', body_zh = '为了喂饱宝宝想了3种不同的菜单，结果自己又饿着？在喂养计划板块里，挑一道不只适合孩子、也适合妈妈的补充能量、10分钟就能做好、富含铁和钙的午餐，让自己感受到被珍视。' WHERE id = '9680e706-6c53-46d8-b37d-e2b2ed358ee7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego del «¿Quién eres?» 🎭', body_es = 'Por la mañana te mira con una cara muy seria y dice: «¿Quién eres tú? ¿Dónde está mi mamá?». ¡El punto álgido del desarrollo de la imaginación! Únete al juego: cambia el tono de voz, di «Soy la vecina, tu mamá viene ahora» y sigue con este teatro maravilloso.', title_fr = 'Le jeu du « Qui es-tu ? » 🎭', body_fr = 'Le matin, il vous regarde d''un air très sérieux : « Qui es-tu ? Où est ma maman ? » C''est le sommet du développement de l''imagination ! Entrez dans le jeu : « Je suis la voisine, ta maman va arriver », changez votre voix et continuez ce formidable théâtre.', title_hi = '‘तुम कौन हो?’ वाला खेल 🎭', body_hi = 'सुबह आपको देखकर बहुत गंभीर चेहरे से कहता है, ‘तुम कौन हो? मेरी माँ कहाँ है?’ कल्पना के विकास का शिखर! खेल में शामिल होइए: ‘मैं पड़ोस वाली आंटी हूँ, तुम्हारी माँ अभी आती है’ कहकर आवाज़ बदलिए और इस शानदार नाटक को आगे बढ़ाइए।', title_id = 'Permainan ''Kamu siapa?'' 🎭', body_id = 'Pagi hari ia menatap Anda dengan wajah sangat serius dan berkata ''Kamu siapa? Mamaku mana?''. Puncak perkembangan imajinasi! Ikutlah bermain: ubah nada suara Anda, katakan ''Aku tante tetangga, mamamu sebentar lagi datang'', dan lanjutkan teater hebat ini.', title_ja = '「あなたは誰？」ごっこ 🎭', body_ja = '朝、あなたを見てとても真剣な顔で「あなたは誰？ぼくのママはどこ？」と言う。想像力の発達のピークです！遊びに乗りましょう：声を変えて「となりのおばさんよ、ママはすぐ来るからね」と言って、このすばらしい劇を続けて。', title_ko = '''누구세요?'' 놀이 🎭', body_ko = '아침에 엄마를 보며 아주 진지한 표정으로 ''누구세요? 우리 엄마 어디 있어요?''라고 하나요? 상상력 발달의 정점이에요! 놀이에 함께하세요: 목소리를 바꿔 ''나는 옆집 아줌마야, 엄마 곧 오실 거야''라며 이 멋진 연극을 이어 가세요.', title_nl = 'Het ''Wie ben jij?''-spel 🎭', body_nl = '''s Ochtends kijkt hij je met een heel serieus gezicht aan en zegt: ''Wie ben jij? Waar is mijn mama?'' Het hoogtepunt van zijn fantasieontwikkeling! Doe mee: zeg met een andere stem ''Ik ben de buurvrouw, je mama komt zo'' en speel dit prachtige theater verder.', title_pl = 'Zabawa „Kim jesteś?” 🎭', body_pl = 'Rano patrzy na ciebie z bardzo poważną miną i mówi: „Kim jesteś? Gdzie moja mama?”. Szczyt rozwoju wyobraźni! Dołącz do zabawy: zmień głos, powiedz „Jestem sąsiadką, mama zaraz przyjdzie” i ciągnij ten wspaniały teatr.', title_pt = 'O jogo do "Quem és tu?" 🎭', body_pt = 'De manhã olha para si com uma cara muito séria e diz: "Quem és tu? Onde está a minha mãe?". O auge do desenvolvimento da imaginação! Entre no jogo: mude o tom de voz, diga "Sou a vizinha, a tua mãe já vem" e continue este teatro fantástico.', title_sv = 'Leken ”Vem är du?” 🎭', body_sv = 'På morgonen tittar barnet på dig med en väldigt allvarlig min och säger: ”Vem är du? Var är min mamma?” Fantasiutvecklingens topp! Häng med i leken: säg med ändrad röst ”Jag är grannen, din mamma kommer snart” och fortsätt den fantastiska teatern.', title_vi = 'Trò chơi "Cô là ai?" 🎭', body_vi = 'Buổi sáng, bé nhìn mẹ với vẻ mặt cực kỳ nghiêm túc: "Cô là ai? Mẹ con đâu rồi?". Đỉnh cao của sự phát triển trí tưởng tượng! Hãy tham gia trò chơi: đổi giọng và nói "Cô là cô hàng xóm, mẹ con sắp về rồi" để tiếp tục vở kịch tuyệt vời này.', title_zh = '“你是谁？”游戏 🎭', body_zh = '早上看着你，一脸严肃地说：“你是谁？我妈妈在哪儿？”这是想象力发展的巅峰！加入游戏吧，换个声音说“我是邻居阿姨，你妈妈马上就来”，把这出精彩的戏演下去。' WHERE id = 'c0f71481-4d8f-40e3-87af-c4432426cfab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte del papel higiénico 🧻', body_es = 'Unos minutos de silencio... ¡Y al entrar en la habitación ves todo el papel higiénico desenrollado por la casa! En lugar de enfadarte, recoged el papel y haced juntos un muñeco de nieve o una pelota. Vence al caos no con gritos, sino con creatividad.', title_fr = 'L''art du papier toilette 🧻', body_fr = 'Quelques minutes de silence... Et en entrant dans la pièce, vous découvrez tout le rouleau de papier toilette déroulé à travers la maison ! Au lieu de vous énerver, ramassez le papier et faites ensemble un bonhomme de neige ou une balle. Battez le chaos non pas en criant, mais par la créativité.', title_hi = 'टॉयलेट पेपर की कला 🧻', body_hi = 'कुछ मिनट की खामोशी... और कमरे में जाकर देखती हैं कि पूरा टॉयलेट पेपर खुलकर घर में फैला है! नाराज़ होने के बजाय वह कागज़ इकट्ठा करके साथ में स्नोमैन या गेंद बनाइए। अफ़रा-तफ़री को चिल्लाकर नहीं, रचनात्मकता से जीतिए।', title_id = 'Seni tisu toilet 🧻', body_id = 'Beberapa menit hening... Lalu saat masuk kamar, Anda melihat seluruh tisu toilet terurai dan tersebar di rumah! Daripada kesal, kumpulkan tisu itu dan buatlah boneka salju atau bola bersama. Kalahkan kekacauan dengan kreativitas, bukan dengan berteriak.', title_ja = 'トイレットペーパーアート 🧻', body_ja = '数分間の静けさ…。そして部屋に入ると、トイレットペーパーが全部ほどかれて家じゅうに広がっていた！怒るより、紙を集めて一緒に雪だるまやボールを作りましょう。カオスには、叫び声ではなくクリエイティブに勝つんです。', title_ko = '휴지 예술 🧻', body_ko = '몇 분간의 고요... 그리고 방에 들어가 보니 휴지가 다 풀려 온 집에 퍼져 있나요? 화내는 대신 휴지를 모아 함께 눈사람이나 공을 만들어 보세요. 혼돈은 소리치기가 아니라 창의력으로 이겨요.', title_nl = 'Wc-papierkunst 🧻', body_nl = 'Een paar minuten stilte... En als je de kamer binnenkomt, is de hele rol wc-papier afgerold en door het huis verspreid! Word niet boos, maar verzamel het papier en maak er samen een sneeuwpop of een bal van. Versla chaos niet met schreeuwen, maar met creativiteit.', title_pl = 'Sztuka z papieru toaletowego 🧻', body_pl = 'Kilka minut ciszy... A gdy wchodzisz do pokoju, widzisz cały papier toaletowy rozwinięty po domu! Zamiast się denerwować, zbierzcie papier i ulepcie razem bałwana albo kulę. Pokonaj chaos nie krzykiem, a kreatywnością.', title_pt = 'A arte do papel higiénico 🧻', body_pt = 'Uns minutos de silêncio... E ao entrar no quarto vê o rolo de papel higiénico todo desenrolado e espalhado pela casa! Em vez de se irritar, apanhem o papel e façam juntos um boneco de neve ou uma bola. Vença o caos não com gritos, mas com criatividade.', title_sv = 'Toalettpapperskonst 🧻', body_sv = 'Några minuters tystnad... Och när du kommer in i rummet ser du att hela toalettpappersrullen är upprullad och utspridd i hemmet! Istället för att bli arg, samla ihop pappret och gör en snögubbe eller en boll tillsammans. Besegra kaoset med kreativitet, inte med skrik.', title_vi = 'Nghệ thuật giấy vệ sinh 🧻', body_vi = 'Vài phút im lặng... Và khi bước vào phòng, mẹ thấy cả cuộn giấy vệ sinh đã bị kéo tung khắp nhà! Thay vì bực mình, hãy gom chỗ giấy đó lại và cùng bé làm người tuyết hoặc quả bóng. Hãy chiến thắng sự hỗn loạn bằng sáng tạo, không phải bằng tiếng quát.', title_zh = '卫生纸艺术 🧻', body_zh = '几分钟的安静……走进房间才发现，整卷卫生纸都被拉开铺满了家！与其生气，不如把纸收起来，一起堆个雪人或团个球。战胜混乱靠的不是吼，而是创意。' WHERE id = '17737c7f-74cb-4797-867c-90a8c03b4bfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Palabras de amor susurradas al oído 💖', body_es = 'Te ha vuelto loca todo el día y se ha empeñado en todo. Pero ahora duerme en la cama tan inocente... Túmbate a su lado y susúrrale al oído cuánto le quieres y las cosas buenas que ha hecho hoy. Los niños sienten la voz llena de amor de mamá incluso dormidos.', title_fr = 'Des mots d''amour chuchotés à l''oreille 💖', body_fr = 'Il vous a rendue folle toute la journée et s''est entêté sur tout. Mais maintenant, il dort si innocemment dans son lit... Allongez-vous près de lui et chuchotez-lui à l''oreille combien vous l''aimez et les belles choses qu''il a faites aujourd''hui. Même endormis, les enfants sentent la voix aimante de leur maman.', title_hi = 'कान में फुसफुसाए प्यार भरे शब्द 💖', body_hi = 'उसने दिनभर आपको परेशान किया, हर बात पर ज़िद की। पर अब बिस्तर में इतना मासूम सोया है... उसके पास लेटिए और उसके कान में फुसफुसाइए कि आप उसे कितना प्यार करती हैं और आज उसने क्या-क्या अच्छे काम किए। बच्चे नींद में भी माँ की प्यार भरी आवाज़ महसूस करते हैं।', title_id = 'Kata-kata cinta yang dibisikkan 💖', body_id = 'Seharian ia membuat Anda hampir gila dan membangkang dalam segala hal. Tapi kini ia tidur begitu polos... Berbaringlah di sampingnya dan bisikkan ke telinganya betapa Anda menyayanginya dan hal-hal baik yang ia lakukan hari ini. Bahkan dalam tidur, anak bisa merasakan suara ibu yang penuh cinta.', title_ja = '耳もとでささやく愛の言葉 💖', body_ja = '一日じゅう振りまわされて、何にでも意地をはっていたのに、今はベッドでこんなにあどけなく眠っています…。そばに横になって、どれほど愛しているか、今日したいいことを耳もとでささやいてあげましょう。子どもは眠っていても、ママの愛情たっぷりの声を感じています。', title_ko = '귓가에 속삭이는 사랑의 말 💖', body_ko = '하루 종일 엄마를 미치게 하고 모든 일에 고집을 부렸죠. 그런데 지금 침대에서 이렇게 순하게 자고 있어요... 옆에 누워 얼마나 사랑하는지, 오늘 잘한 일들을 귓가에 속삭여 주세요. 아이들은 자면서도 엄마의 사랑 가득한 목소리를 느껴요.', title_nl = 'Lieve woordjes in zijn oor 💖', body_nl = 'Hij heeft je de hele dag gek gemaakt en was overal koppig in. Maar nu ligt hij zo onschuldig in bed... Ga naast hem liggen en fluister in zijn oor hoeveel je van hem houdt en welke goede dingen hij vandaag deed. Kinderen voelen zelfs in hun slaap de liefdevolle stem van hun mama.', title_pl = 'Słowa miłości szeptane do ucha 💖', body_pl = 'Cały dzień doprowadzał cię do szału i się upierał. Ale teraz śpi w łóżku tak niewinnie... Połóż się obok i wyszeptaj mu do ucha, jak bardzo go kochasz i co dobrego dziś zrobił. Dzieci nawet we śnie czują pełen miłości głos mamy.', title_pt = 'Palavras de amor sussurradas ao ouvido 💖', body_pt = 'Passou o dia todo a deixá-la louca e a teimar com tudo. Mas agora dorme na cama com um ar tão inocente... Deite-se ao lado dele e sussurre-lhe ao ouvido o quanto o ama e as coisas boas que fez hoje. Mesmo a dormir, as crianças sentem a voz carinhosa da mãe.', title_sv = 'Kärleksord viskade i örat 💖', body_sv = 'Barnet har gjort dig galen hela dagen och varit envist med allt. Men nu ligger det så oskyldigt i sängen... Lägg dig bredvid och viska i barnets öra hur mycket du älskar det och om de fina saker det gjorde i dag. Barn känner mammas kärleksfulla röst även i sömnen.', title_vi = 'Lời yêu thương thì thầm bên tai 💖', body_vi = 'Cả ngày bé làm mẹ phát điên, bướng bỉnh với mọi thứ. Nhưng giờ bé ngủ say trên giường thật ngây thơ... Hãy nằm cạnh bé và thì thầm vào tai bé rằng mẹ yêu bé nhường nào, kể những điều tốt bé đã làm hôm nay. Ngay cả trong giấc ngủ, trẻ vẫn cảm nhận được giọng nói đầy yêu thương của mẹ.', title_zh = '在耳边悄悄说的情话 💖', body_zh = '宝宝把你折腾了一整天，什么都要犟。可现在在床上睡得那么天真……躺在宝宝身边，在耳边悄悄告诉宝宝你有多爱宝宝，以及宝宝今天做的那些好事。孩子们哪怕在睡梦中，也能感受到妈妈充满爱的声音。' WHERE id = '300e5d4c-57c8-45bf-bdcd-829a6024697a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo la lavadora 🧺', body_es = 'Sentado delante de la lavadora, mira la ropa girar tan concentrado como si viera dibujos animados. Es una diversión totalmente gratis que calma la mente. No le interrumpas: aprovecha tú también para descansar.', title_fr = 'La découverte de la machine à laver 🧺', body_fr = 'Assis devant la machine à laver, il est si concentré sur le linge qui tourne qu''on dirait qu''il regarde un dessin animé. C''est un divertissement totalement gratuit qui apaise l''esprit. Ne le dérangez pas, profitez-en pour vous reposer, vous aussi.', title_hi = 'वॉशिंग मशीन की खोज 🧺', body_hi = 'वॉशिंग मशीन के सामने बैठकर घूमते कपड़ों पर ऐसे ध्यान लगाए है जैसे कार्टून देख रहा हो। यह पूरी तरह मुफ़्त और मन को शांत करने वाला मनोरंजन है। उसे मत रोकिए, आप भी मौके का फ़ायदा उठाकर आराम कीजिए।', title_id = 'Penemuan mesin cuci 🧺', body_id = 'Ia duduk di depan mesin cuci dan begitu fokus memandangi baju yang berputar seolah sedang menonton kartun. Ini hiburan yang sepenuhnya gratis dan menenangkan pikiran. Jangan ganggu dia, manfaatkan kesempatan ini untuk beristirahat juga.', title_ja = '洗濯機の発見 🧺', body_ja = '洗濯機の前に座って、回る洗濯物にアニメを見ているかのように夢中になっています。これは完全に無料で、心を落ち着かせてくれるエンターテインメント。じゃまをしないで、あなたもこのチャンスに休みましょう。', title_ko = '세탁기의 발견 🧺', body_ko = '세탁기 앞에 앉아 돌아가는 빨래를 만화라도 보듯 집중해서 보고 있나요? 완전히 공짜에 마음까지 차분해지는 놀이예요. 방해하지 말고 엄마도 이 기회에 쉬세요.', title_nl = 'De wasmachine ontdekken 🧺', body_nl = 'Hij zit voor de wasmachine en is zo gefocust op de draaiende kleren alsof hij naar een tekenfilm kijkt. Helemaal gratis vermaak dat het hoofd tot rust brengt. Stoor hem niet en grijp de kans om zelf ook even te ontspannen.', title_pl = 'Odkrycie pralki 🧺', body_pl = 'Siedzi przed pralką i tak się skupia na kręcącym się praniu, jakby oglądał bajkę. To zupełnie darmowa rozrywka, która wycisza umysł. Nie przeszkadzaj mu, a sama skorzystaj z okazji i odpocznij.', title_pt = 'A descoberta da máquina de lavar 🧺', body_pt = 'Está sentado em frente à máquina de lavar, tão concentrado na roupa a girar como se estivesse a ver desenhos animados. É uma diversão totalmente gratuita que acalma a mente. Não o interrompa e aproveite também para descansar.', title_sv = 'Upptäckten av tvättmaskinen 🧺', body_sv = 'Barnet sitter framför tvättmaskinen så fokuserat på de snurrande kläderna som om det tittade på tecknat. Det är ett helt gratis nöje som lugnar sinnet. Stör inte, passa på att vila du också.', title_vi = 'Khám phá máy giặt 🧺', body_vi = 'Bé ngồi trước máy giặt, chăm chú nhìn quần áo quay tròn như đang xem phim hoạt hình. Đây là trò giải trí hoàn toàn miễn phí và giúp tinh thần dịu lại. Đừng làm phiền bé, mẹ cũng tranh thủ nghỉ ngơi nhé.', title_zh = '发现洗衣机 🧺', body_zh = '坐在洗衣机前，盯着转动的衣服看得那么入迷，就像在看动画片。这是完全免费、还能让头脑平静下来的娱乐。别打扰宝宝，你也趁机休息一下吧。' WHERE id = '42d87f04-8d19-4c11-b1e4-703ee34de8db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de huir del cuento 🏃‍♂️', body_es = 'Mientras lees el cuento, a la mínima salta de la cama diciendo «voy a por mi juguete». No quiere rendirse al sueño. Baja de golpe el tono y empieza a leer susurrando. Para oírte tendrá que volver a la cama, concentrarse, y se dormirá.', title_fr = 'Tentatives d''évasion pendant le conte 🏃‍♂️', body_fr = 'Pendant le conte, il saute du lit à la moindre occasion pour aller chercher un jouet. Il ne veut pas se rendre au sommeil. Baissez soudain fortement le ton et lisez en chuchotant. Pour vous entendre, il sera obligé de revenir au lit et de se concentrer, et il s''endormira.', title_hi = 'कहानी से भागने की कोशिशें 🏃‍♂️', body_hi = 'कहानी पढ़ते समय हर मौके पर बिस्तर से कूदकर ‘मेरा खिलौना ले आऊँ’ कहकर भागता है। नींद के आगे हार नहीं मानना चाहता। अचानक अपनी आवाज़ बहुत धीमी कीजिए और फुसफुसाकर पढ़ना शुरू कीजिए। आपको सुनने के लिए उसे बिस्तर पर लौटकर ध्यान लगाना ही पड़ेगा, और वह सो जाएगा।', title_id = 'Usaha kabur dari dongeng 🏃‍♂️', body_id = 'Saat Anda membacakan dongeng, ia terus melompat dari tempat tidur dan berlari dengan alasan ''mau ambil mainanku''. Ia tak mau menyerah pada kantuk. Turunkan nada suara Anda tiba-tiba dan mulailah membaca sambil berbisik. Untuk mendengar Anda, ia terpaksa kembali ke tempat tidur, memusatkan perhatian, dan tertidur.', title_ja = 'お話からの脱走 🏃‍♂️', body_ja = '読み聞かせのあいだ、すきを見てはベッドから飛びおりて「おもちゃ持ってくる」と走っていく。眠りに降参したくないんです。急に声のトーンをぐっと落として、ささやき声で読み始めましょう。あなたの声を聞くためにベッドに戻って集中し、そのまま眠りにつきます。', title_ko = '동화 탈출 시도 🏃‍♂️', body_ko = '동화를 읽어 줄 때마다 ''장난감 가져올게'' 하며 침대에서 뛰쳐나가나요? 잠에 항복하기 싫은 거예요. 갑자기 톤을 아주 낮춰 속삭이듯 읽어 보세요. 들으려고 침대로 돌아와 집중하다 보면 잠이 들 거예요.', title_nl = 'Pogingen om aan het sprookje te ontsnappen 🏃‍♂️', body_nl = 'Tijdens het voorlezen springt hij bij elke kans uit bed: ''Ik ga mijn knuffel halen!'' Hij wil zich niet aan de slaap overgeven. Ga ineens heel zacht praten en lees fluisterend verder. Om je te verstaan moet hij wel terug in bed en goed opletten, en zo valt hij in slaap.', title_pl = 'Próby ucieczki od bajki 🏃‍♂️', body_pl = 'Podczas czytania bajki przy każdej okazji wyskakuje z łóżka i biegnie „po zabawkę”. Nie chce poddać się snu. Nagle bardzo obniż głos i zacznij czytać szeptem. Żeby cię usłyszeć, będzie musiał wrócić do łóżka, zamieni się w słuch i zaśnie.', title_pt = 'Tentativas de fugir à história 🏃‍♂️', body_pt = 'Enquanto lê a história, salta da cama a cada oportunidade e foge: "Vou buscar o meu brinquedo". Não se quer render ao sono. Baixe de repente muito o tom de voz e comece a ler a sussurrar. Para a ouvir, vai ter de voltar para a cama, concentrar-se e adormecer.', title_sv = 'Försök att fly från sagan 🏃‍♂️', body_sv = 'Under sagoläsningen hoppar barnet ur sängen vid varje tillfälle och springer iväg: ”Jag ska bara hämta min leksak.” Barnet vill inte ge sig åt sömnen. Sänk plötsligt rösten mycket och börja läsa viskande. För att höra dig måste barnet komma tillbaka till sängen, lyssna spänt och somnar.', title_vi = 'Những lần trốn giờ đọc truyện 🏃‍♂️', body_vi = 'Khi mẹ đọc truyện, cứ có dịp là bé nhảy khỏi giường, chạy đi "lấy đồ chơi". Bé không muốn đầu hàng giấc ngủ. Hãy bất ngờ hạ giọng thật thấp và đọc thì thầm. Để nghe được mẹ, bé buộc phải quay lại giường, chăm chú lắng nghe và chìm vào giấc ngủ.', title_zh = '想从故事里逃跑 🏃‍♂️', body_zh = '讲故事时，一有机会就从床上跳起来跑掉：“我去拿我的玩具”。宝宝不想向睡意投降。突然把声音压得很低，用气声读下去。为了听清你，宝宝只好回到床上集中注意力，然后就睡着了。' WHERE id = '56f07d8f-4184-4cda-b356-e566ad65a81d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ya soy mayor, quiero café! ☕', body_es = 'Alarga la mano hacia tu taza y dice decidido: «Ya soy mayor, yo también quiero café». Solo quiere entrar en tu mundo. Echa en su tacita un poco de leche con cacao, dile «Mira, este es tu café de niño» y brindad juntos.', title_fr = 'Je suis grand, je vais boire du café ! ☕', body_fr = 'Il tend la main vers votre tasse et dit avec détermination : « Je suis grand, moi aussi je vais boire du café. » Il veut simplement entrer dans votre monde. Versez un peu de lait et de cacao dans sa petite tasse, dites « Regarde, voilà ton café d''enfant » et trinquez ensemble.', title_hi = 'मैं बड़ा हूँ, कॉफ़ी पिऊँगा! ☕', body_hi = 'आपके कप की ओर हाथ बढ़ाकर पक्के इरादे से कहता है, ‘मैं बड़ा हो गया हूँ, मैं भी कॉफ़ी पिऊँगा।’ वह बस आपकी दुनिया में शामिल होना चाहता है। उसके छोटे कप में थोड़ा दूध और कोको डालिए, ‘देखो, यह तुम्हारी बच्चों वाली कॉफ़ी है’ कहिए और उसके साथ कप टकराइए।', title_id = 'Aku sudah besar, aku mau minum kopi! ☕', body_id = 'Ia meraih cangkir Anda dan dengan tegas berkata ''Aku sudah besar, aku juga mau minum kopi''. Ia hanya ingin masuk ke dunia Anda. Tuang sedikit susu dan kakao ke cangkir kecilnya, katakan ''Lihat, ini kopi anak untukmu'', lalu bersulanglah bersamanya.', title_ja = 'もう大きいから、コーヒー飲む！ ☕', body_ja = 'あなたのカップに手をのばして、きっぱり「もう大きいから、ぼくもコーヒー飲む」と言う。あなたの世界に入りたいだけなんです。小さなカップに牛乳とココアを少し入れて「ほら、これがあなたのキッズコーヒーよ」と言って、一緒に乾杯しましょう。', title_ko = '나도 컸으니까 커피 마실래! ☕', body_ko = '엄마 잔에 손을 뻗으며 ''나도 컸으니까 커피 마실래''라고 단호하게 말하나요? 엄마의 세계에 들어오고 싶은 거예요. 작은 컵에 우유와 코코아를 조금 따라 ''봐, 이건 네 어린이 커피야''라며 함께 건배해 주세요.', title_nl = 'Ik ben groot, ik drink koffie! ☕', body_nl = 'Hij grijpt naar je kopje en zegt vastberaden: ''Ik ben groot, ik drink ook koffie.'' Hij wil gewoon deel zijn van jouw wereld. Doe wat melk en cacao in zijn kleine kopje, zeg ''Kijk, dit is jouw kinderkoffie'' en klink samen.', title_pl = 'Jestem duży, napiję się kawy! ☕', body_pl = 'Sięga po twoją filiżankę i stanowczo mówi: „Jestem już duży, ja też napiję się kawy”. Po prostu chce wejść do twojego świata. Nalej do jego małego kubeczka trochę mleka z kakao, powiedz „Zobacz, to twoja dziecięca kawa” i stuknijcie się kubkami.', title_pt = 'Sou crescido, vou beber café! ☕', body_pt = 'Estica-se para a sua chávena e diz decidido: "Já sou crescido, também vou beber café". Só quer entrar no seu mundo. Deite na chávena pequena dele um pouco de leite e cacau, diga "Olha, este é o teu café de criança" e brinde com ele.', title_sv = 'Jag är stor, jag ska dricka kaffe! ☕', body_sv = 'Barnet sträcker sig efter din kopp och säger bestämt: ”Jag är stor, jag ska också dricka kaffe.” Barnet vill bara komma in i din värld. Häll lite mjölk och kakao i barnets lilla kopp, säg ”Titta, det här är ditt barnkaffe” och skåla tillsammans.', title_vi = 'Con lớn rồi, con uống cà phê! ☕', body_vi = 'Bé với lấy tách của mẹ và kiên quyết nói: "Con lớn rồi, con cũng uống cà phê". Bé chỉ muốn bước vào thế giới của mẹ. Hãy rót chút sữa và ca cao vào chiếc tách nhỏ của bé, nói "Đây là cà phê trẻ em của con này" và cùng bé cụng ly.', title_zh = '我长大了，我要喝咖啡！☕', body_zh = '伸手去够你的杯子，坚定地说：“我长大了，我也要喝咖啡。”宝宝只是想走进你的世界。在宝宝的小杯子里倒点牛奶和可可，说一句“看，这是你的儿童咖啡”，和宝宝碰个杯吧。' WHERE id = '6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica del tiempo y las capas ⛅', body_es = 'Al acercarse la primavera el tiempo es cambiante: frío por la mañana y calor a mediodía. La herramienta Tiempo y ropa te recuerda vestirle con el efecto cebolla (por capas). En el parque, quítale una capa a medida que entre en calor y evita que sude y que tú te estreses.', title_fr = 'Météo et tactique des couches ⛅', body_fr = 'À l''approche du printemps, le temps est indécis : froid le matin, chaud l''après-midi. Météo et tenue vous rappelle de l''habiller en couches (l''effet oignon). Au parc, enlevez une couche à mesure qu''il se réchauffe, pour éviter qu''il transpire et vous épargner du stress.', title_hi = 'मौसम और परतों वाले कपड़ों की तरकीब ⛅', body_hi = 'बसंत के करीब मौसम का कोई भरोसा नहीं; सुबह ठंड, दोपहर गर्मी। मौसम और कपड़े टूल आपको प्याज़ की तरह परत-दर-परत कपड़े पहनाने की याद दिलाता है। पार्क में गर्मी बढ़ने पर एक परत उतारकर उसका पसीना भी रोकिए और अपना तनाव भी।', title_id = 'Taktik cuaca dan pakaian berlapis ⛅', body_id = 'Menjelang musim semi cuaca tidak menentu; pagi dingin, siang panas. Cuaca dan Pakaian mengingatkan Anda untuk memakaikan pakaian berlapis seperti bawang. Saat ia mulai kepanasan di taman, lepas satu lapis untuk mencegah ia berkeringat sekaligus mencegah stres Anda.', title_ja = '天気と重ね着作戦 ⛅', body_ja = '春が近づくと天気は気まぐれ。朝は寒く、お昼は暑い。「天気と服装」が、玉ねぎのような重ね着を思い出させてくれます。公園で暑くなったら1枚脱がせて、汗をかくのも、あなたのストレスも防ぎましょう。', title_ko = '날씨와 겹겹이 입기 작전 ⛅', body_ko = '봄이 다가오면 날씨가 변덕스러워요. 아침엔 춥고 낮엔 덥죠. 날씨와 옷차림 도구가 양파처럼 겹겹이 입히라고 알려 줘요. 공원에서 더워지면 한 겹씩 벗겨 아이가 땀 흘리는 것도, 엄마의 스트레스도 막으세요.', title_nl = 'Weer en de laagjestactiek ⛅', body_nl = 'Richting de lente is het weer wisselvallig: ''s ochtends koud, ''s middags warm. De tool Weer en kleding herinnert je eraan hem in laagjes aan te kleden (het uieffect). Trek in het park een laagje uit als hij het warm krijgt, zo voorkom je dat hij gaat zweten en heb jij minder stress.', title_pl = 'Pogoda i taktyka na cebulkę ⛅', body_pl = 'Pod koniec zimy pogoda jest niezdecydowana: rano zimno, w południe ciepło. Narzędzie Pogoda i ubiór przypomina, by ubrać go na cebulkę. Gdy w parku zrobi mu się ciepło, zdejmij jedną warstwę i zapobiegnij i jego poceniu się, i swojemu stresowi.', title_pt = 'Tempo e a tática das camadas ⛅', body_pt = 'Perto da primavera o tempo anda indeciso: frio de manhã, calor ao meio-dia. A ferramenta Tempo e Roupa lembra-lhe que o vista "à cebola" (por camadas). No parque, tire-lhe uma camada à medida que aquece e evite que ele transpire e que a mãe se stresse.', title_sv = 'Väder och lager på lager-taktiken ⛅', body_sv = 'Närmare våren är vädret ombytligt; kallt på morgonen och varmt mitt på dagen. Verktyget Väder och kläder påminner dig om löktekniken (lager på lager). Ta av ett lager när barnet blir varmt i parken och förebygg både barnets svettningar och din egen stress.', title_vi = 'Thời tiết và mẹo mặc nhiều lớp ⛅', body_vi = 'Gần mùa xuân, thời tiết thất thường: sáng lạnh, trưa nóng. Thời tiết và trang phục nhắc mẹ cho bé mặc nhiều lớp như "củ hành". Ở công viên, khi bé nóng lên thì cởi bớt một lớp, vừa tránh cho bé đổ mồ hôi, vừa tránh căng thẳng cho mẹ.', title_zh = '天气与洋葱式穿衣法 ⛅', body_zh = '快到春天时天气反复无常：早上冷，中午热。天气与穿衣工具会提醒你采用“洋葱式”（一层层）穿法。在公园里热了就脱掉一层，既能防止宝宝出汗，也能减少你自己的压力。' WHERE id = '7a51f55e-c494-489a-927c-6f2193813549' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de la nariz robada 👃', body_es = 'Le enseñas el pulgar diciendo «¡Te he quitado la nariz!» y él se lo cree de verdad y se pone a llorar. La imaginación de los 3 años y medio a veces no sabe separar realidad e ilusión. Dile enseguida «¡Ajá, ya te la he devuelto!», bésale la nariz y convierte este pequeño trauma en una sonrisa.', title_fr = 'Le jeu du nez volé 👃', body_fr = 'Vous dites « Je t''ai pris le nez ! » en montrant votre pouce, et il y croit vraiment et se met à pleurer ! À 3 ans et demi, l''imagination ne sait parfois pas faire la différence entre réalité et illusion. Dites aussitôt « Voilà, je l''ai remis ! » et embrassez son nez pour transformer ce petit traumatisme en sourire.', title_hi = 'चुराई हुई नाक का खेल 👃', body_hi = '‘तुम्हारी नाक ले ली!’ कहकर अँगूठा दिखाती हैं और वह सच में मानकर रोने लगता है! साढ़े 3 साल की कल्पना कभी-कभी सच और भ्रम में फ़र्क नहीं कर पाती। तुरंत ‘अरे, वापस लगा दी’ कहकर उसकी नाक चूमिए और इस छोटे से सदमे को मुस्कान में बदल दीजिए।', title_id = 'Permainan hidung dicuri 👃', body_id = 'Anda berkata ''Hidungmu Mama ambil!'' sambil menunjukkan ibu jari, dan ia benar-benar percaya lalu menangis! Imajinasi anak 3,5 tahun kadang belum bisa memisahkan kenyataan dan ilusi. Segera katakan ''Aha, sudah Mama kembalikan'', cium hidungnya, dan ubah trauma kecil ini menjadi senyuman.', title_ja = 'お鼻とったよ遊び 👃', body_ja = '「お鼻とった！」と親指を見せたら、本気にして泣きだした！3歳半の想像力は、ときに現実と空想を区別できません。すぐに「はい、もとに戻したよ」と言ってお鼻にキスして、この小さなショックを笑顔に変えましょう。', title_ko = '코 훔치기 놀이 👃', body_ko = '''코 가져갔다!'' 하며 엄지를 보여 줬더니 진짜로 믿고 울기 시작했나요? 세 살 반의 상상력은 가끔 현실과 착각을 구분하지 못해요. 바로 ''아하, 다시 붙여 놨어'' 하며 코에 뽀뽀해서 이 작은 충격을 웃음으로 바꿔 주세요.', title_nl = 'Het gestolen-neusspel 👃', body_nl = 'Je zegt ''Ik heb je neus!'' en laat je duim zien, en hij gelooft het echt en begint te huilen! Met 3,5 jaar kan de fantasie werkelijkheid en illusie soms nog niet scheiden. Zeg meteen ''Hop, ik heb hem teruggezet'', geef een kus op zijn neus en verander dit kleine trauma in een glimlach.', title_pl = 'Zabawa w ukradziony nos 👃', body_pl = 'Mówisz „Mam twój nos!” i pokazujesz kciuk, a on naprawdę w to wierzy i zaczyna płakać! Wyobraźnia 3,5-latka czasem nie odróżnia rzeczywistości od iluzji. Od razu powiedz „Aha, oddałam!”, pocałuj go w nos i zamień tę małą traumę w uśmiech.', title_pt = 'O jogo do nariz roubado 👃', body_pt = 'Diz "Roubei-te o nariz!", mostra-lhe o polegar e ele acredita mesmo e começa a chorar! Aos 3 anos e meio, a imaginação às vezes não separa a realidade da ilusão. Diga logo "Pronto, já o pus no sítio", dê-lhe um beijo no nariz e transforme este pequeno trauma num sorriso.', title_sv = 'Leken med den stulna näsan 👃', body_sv = 'Du visar tummen och säger ”Jag tog din näsa!”, och barnet tror verkligen på det och börjar gråta! 3,5-åringens fantasi kan ibland inte skilja verklighet från illusion. Säg genast ”Aha, jag satte tillbaka den”, pussa näsan och gör det lilla traumat till ett leende.', title_vi = 'Trò chơi lấy trộm mũi 👃', body_vi = 'Mẹ nói "Mẹ lấy mũi con rồi!" và giơ ngón cái ra, bé tin thật và bật khóc! Trí tưởng tượng của tuổi 3,5 đôi khi chưa phân biệt được thực tế và ảo tưởng. Hãy nói ngay "A, mẹ trả lại rồi đây" và hôn lên mũi bé, biến "chấn thương" nhỏ này thành nụ cười.', title_zh = '偷鼻子游戏 👃', body_zh = '你说“我拿走你的鼻子啦！”，伸出大拇指，宝宝却当真了，哭了起来！3岁半的想象力有时还分不清现实和幻象。马上说“啊，我放回去了”，亲亲宝宝的鼻子，把这个小小的“创伤”变成笑容。' WHERE id = '063d0e5f-8a19-45c6-b301-96c01e527e0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una mirada en silencio con tu pareja 🥂', body_es = 'Por fin se ha dormido. Tú y tu pareja estáis sentados juntos en el sofá y no tenéis fuerzas ni para hablar. Simplemente os miráis en silencio y sonreís. Esa mirada silenciosa es la forma más bonita de decir «lo estamos haciendo de maravilla con este caos».', title_fr = 'Un regard silencieux avec votre partenaire 🥂', body_fr = 'L''enfant dort enfin. Vous êtes assis côte à côte sur le canapé avec votre partenaire et vous n''avez même plus la force de parler. Vous vous regardez simplement en silence et vous souriez. Ce regard silencieux est la plus belle façon de dire « on vient parfaitement à bout de ce chaos ».', title_hi = 'साथी के साथ खामोश नज़रें 🥂', body_hi = 'बच्चा आखिरकार सो गया। आप और आपके साथी सोफ़े पर साथ बैठे हैं और बात करने की भी ताकत नहीं। बस खामोशी में एक-दूसरे को देखकर मुस्कुरा रहे हैं। यह खामोश नज़र ‘हम इस अफ़रा-तफ़री को बखूबी संभाल रहे हैं’ कहने का सबसे प्यारा तरीका है।', title_id = 'Saling tatap tanpa kata dengan pasangan 🥂', body_id = 'Anak akhirnya tidur. Anda dan pasangan duduk berdampingan di sofa, bahkan tak punya tenaga untuk bicara. Kalian hanya saling memandang dalam hening dan tersenyum. Tatapan tanpa kata ini adalah cara terindah untuk berkata ''Kita menghadapi kekacauan ini dengan sempurna''.', title_ja = 'パートナーと言葉のない見つめ合い 🥂', body_ja = 'やっと子どもが寝ました。あなたとパートナーはソファに並んで座り、話す元気さえ残っていません。ただ静けさの中で見つめ合って、ほほえむだけ。この無言の見つめ合いこそ「わたしたち、このカオスを見事に乗りこえている」と伝えるいちばんすてきな方法です。', title_ko = '배우자와의 말없는 눈맞춤 🥂', body_ko = '아이가 드디어 잠들었어요. 배우자와 소파에 나란히 앉았지만 말할 힘조차 없죠. 그저 조용히 서로를 보며 미소 짓나요? 이 말없는 눈맞춤이 ''우리 이 혼돈을 완벽하게 해내고 있어''라고 말하는 가장 아름다운 방법이에요.', title_nl = 'Een stille blik met je partner 🥂', body_nl = 'Je kind slaapt eindelijk. Jij en je partner zitten naast elkaar op de bank en hebben niet eens de energie om te praten. Jullie kijken elkaar alleen in stilte aan en glimlachen. Die stille blik is de mooiste manier om te zeggen: ''We kunnen deze chaos perfect aan.''', title_pl = 'Ciche spojrzenie z partnerem 🥂', body_pl = 'Dziecko w końcu zasnęło. Siedzicie z partnerem obok siebie na kanapie i nie macie siły nawet rozmawiać. Po prostu patrzycie na siebie w ciszy i się uśmiechacie. To ciche spojrzenie to najpiękniejszy sposób, by powiedzieć „świetnie dajemy radę z tym chaosem”.', title_pt = 'Contacto visual silencioso com o companheiro 🥂', body_pt = 'A criança finalmente adormeceu. Está sentada no sofá ao lado do seu companheiro e nem têm forças para falar. Limitam-se a olhar um para o outro e a sorrir em silêncio. Este olhar silencioso é a forma mais bonita de dizer "estamos a dar conta deste caos na perfeição".', title_sv = 'Tyst ögonkontakt med partnern 🥂', body_sv = 'Äntligen sover barnet. Du och din partner sitter bredvid varandra i soffan och orkar inte ens prata. Ni bara tittar på varandra i tystnad och ler. Den tysta blicken är det vackraste sättet att säga ”vi klarar det här kaoset perfekt”.', title_vi = 'Ánh mắt lặng lẽ cùng chồng 🥂', body_vi = 'Cuối cùng bé cũng ngủ. Hai vợ chồng ngồi cạnh nhau trên sofa, mệt đến mức chẳng còn sức nói. Chỉ nhìn nhau trong im lặng và mỉm cười. Ánh mắt lặng lẽ ấy là cách đẹp nhất để nói "Chúng ta đang vượt qua mớ hỗn loạn này thật hoàn hảo".', title_zh = '和伴侣无声的对视 🥂', body_zh = '宝宝终于睡着了。你和伴侣并排坐在沙发上，连说话的力气都没有了。只是在安静中看着对方笑一笑。这无声的对视，就是说“这场混乱我们搞定得很漂亮”最美的方式。' WHERE id = '31689193-e8a3-408a-bec9-cc30d1fc08c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y terquedades repentinas 🤖', body_es = '¿El niño que hasta ayer estaba tranquilo hoy reacciona de forma agresiva a todo? No busques causas que den miedo en internet. Pregunta a Anacan AI por las causas psicológicas de este salto de desarrollo («mental leap») y pon a cero tu inquietud con una respuesta avalada por pediatras.', title_fr = 'Intelligence artificielle et entêtements soudains 🤖', body_fr = 'L''enfant si calme jusqu''à hier réagit aujourd''hui à tout avec agressivité ? Ne cherchez pas de causes effrayantes sur Internet. Demandez à Anacan AI les raisons psychologiques de ce bond de développement (mental leap) et apaisez votre inquiétude avec une réponse validée par des pédiatres.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और अचानक की ज़िद 🤖', body_hi = 'कल तक शांत रहने वाला बच्चा आज हर बात पर गुस्से से प्रतिक्रिया देता है? इंटरनेट पर डरावनी वजहें मत ढूँढिए। Anacan AI से इस विकास की छलाँग (मेंटल लीप) की मनोवैज्ञानिक वजहें पूछिए और बाल रोग विशेषज्ञ द्वारा पुष्ट जवाब से अपनी घबराहट खत्म कीजिए।', title_id = 'Kecerdasan buatan dan keras kepala mendadak 🤖', body_id = 'Anak yang sampai kemarin tenang, hari ini bereaksi agresif pada segala hal? Jangan mencari penyebab menakutkan di internet. Tanyakan pada Anacan AI penyebab psikologis lompatan perkembangan (mental leap) ini, dan redakan kecemasan Anda dengan jawaban yang disetujui dokter anak.', title_ja = 'AIと急ながんこさ 🤖', body_ja = '昨日までおだやかだった子が、今日は何にでも激しく反応する？ネットで怖い理由をさがさないで。Anacan AIに、この発達の飛躍（mental leap）の心理的な理由をたずねて、小児科医も認める答えで不安をリセットしましょう。', title_ko = '인공지능과 갑작스러운 고집 🤖', body_ko = '어제까지 순하던 아이가 오늘은 모든 일에 공격적으로 반응하나요? 인터넷에서 무서운 이유를 찾지 마세요. Anacan AI에게 이 발달 도약(mental leap)의 심리적 이유를 물어보고, 소아과 의사가 확인한 답으로 걱정을 내려놓으세요.', title_nl = 'Kunstmatige intelligentie en plotselinge koppigheid 🤖', body_nl = 'Reageert je kind dat tot gisteren rustig was, vandaag overal agressief op? Zoek op internet niet naar enge oorzaken. Vraag Anacan AI naar de psychologische oorzaken van deze ontwikkelingssprong (mental leap) en zet je ongerustheid op nul met een door kinderartsen bevestigd antwoord.', title_pl = 'Sztuczna inteligencja i nagły upór 🤖', body_pl = 'Dziecko, które do wczoraj było spokojne, dziś na wszystko reaguje agresywnie? Nie szukaj strasznych przyczyn w internecie. Zapytaj Anacan AI o psychologiczne przyczyny tego skoku rozwojowego (mental leap) i wyzeruj niepokój odpowiedzią potwierdzoną przez pediatrów.', title_pt = 'Inteligência artificial e teimosias repentinas 🤖', body_pt = 'A criança que até ontem era calma hoje reage a tudo com agressividade? Não procure causas assustadoras na internet. Pergunte ao Anacan AI as causas psicológicas deste salto de desenvolvimento (mental leap) e acabe com a aflição com uma resposta validada por pediatras.', title_sv = 'Artificiell intelligens och plötslig envishet 🤖', body_sv = 'Reagerar barnet som var lugnt fram till i går i dag aggressivt på allt? Leta inte efter skrämmande orsaker på nätet. Fråga Anacan AI om de psykologiska orsakerna till det här utvecklingssprånget (mental leap) och nollställ oron med ett barnläkargodkänt svar.', title_vi = 'Trí tuệ nhân tạo và những lúc bướng bỉnh bất chợt 🤖', body_vi = 'Đứa trẻ đến hôm qua còn ngoan hiền, hôm nay lại phản ứng gay gắt với mọi thứ? Đừng tìm những lý do đáng sợ trên mạng. Hãy hỏi Anacan AI về nguyên nhân tâm lý của bước nhảy vọt phát triển này (mental leap) và xua tan lo lắng với câu trả lời được bác sĩ nhi khoa xác nhận.', title_zh = '人工智能与突然的倔强 🤖', body_zh = '直到昨天还很安静的孩子，今天对什么都反应激烈？别在网上找那些吓人的原因。问问Anacan AI这次发育飞跃（mental leap）背后的心理原因，用经儿科医生认可的答案让焦虑归零。' WHERE id = '7834ecb1-6218-4b7b-a3ed-c138894407b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Esto lo he encontrado yo»: el peque posesivo 🔑', body_es = 'Coge del suelo el mando o las llaves de papá y proclama: «¡Esto lo he encontrado yo, es mío!». Para él encontrar significa poseer. No se lo quites a la fuerza: dile «Gracias por encontrarlo para mí», dirige su atención a otro juguete y recupéralo.', title_fr = '« C''est moi qui l''ai trouvé » : le tout-petit possessif 🔑', body_fr = 'Il ramasse par terre la télécommande ou les clés de papa et déclare : « C''est moi qui l''ai trouvé, c''est à moi ! » Pour lui, trouver, c''est posséder. Ne le lui arrachez pas des mains : dites « Merci de l''avoir trouvé pour moi », détournez son attention vers un autre jouet et récupérez l''objet.', title_hi = '‘यह मुझे मिला’: हक जताने वाला टॉडलर 🔑', body_hi = 'घर का रिमोट या पापा की चाबी ज़मीन से उठाकर दावा करता है, ‘यह मुझे मिला, यह मेरा है!’ उसके लिए ढूँढने का मतलब मालिक बनना है। ज़बरदस्ती मत छीनिए, ‘शुक्रिया, तुमने मेरे लिए ढूँढ दिया’ कहिए और उसका ध्यान किसी और खिलौने की ओर ले जाकर वापस ले लीजिए।', title_id = '''Aku yang menemukan'', balita yang posesif 🔑', body_id = 'Ia memungut remote atau kunci Ayah dari lantai dan bersikeras ''Aku yang menemukan, ini punyaku!''. Baginya, menemukan berarti memiliki. Jangan merebutnya dengan paksa, katakan ''Terima kasih sudah menemukannya untuk Mama'', lalu ambil kembali sambil mengalihkan perhatiannya ke mainan lain.', title_ja = '「ぼくが見つけた」持ち主宣言 🔑', body_ja = '家のリモコンやパパのカギを床から拾って「ぼくが見つけたから、ぼくの！」と主張する。この子にとって、見つけることは自分のものにすることなんです。無理に取りあげず、「見つけてくれてありがとう」と言って、別のおもちゃに気をそらしながら返してもらいましょう。', title_ko = '''내가 찾았어'' - 소유욕 강한 아이 🔑', body_ko = '바닥에서 리모컨이나 아빠 열쇠를 주워 ''내가 찾았으니까 내 거야!''라고 우기나요? 아이에게는 찾는 게 곧 갖는 거예요. 억지로 빼앗지 말고 ''찾아 줘서 고마워''라고 한 뒤 다른 장난감으로 관심을 돌려 돌려받으세요.', title_nl = '''Ik heb het gevonden'': de bezitterige peuter 🔑', body_nl = 'Hij raapt de afstandsbediening of papa''s sleutels van de grond en roept: ''Ik heb het gevonden, het is van mij!'' Voor hem betekent vinden ook hebben. Pak het niet met geweld af, maar zeg ''Dankjewel dat je het voor me hebt gevonden'', leid zijn aandacht af met ander speelgoed en neem het terug.', title_pl = '„Ja to znalazłem” - maluch właściciel 🔑', body_pl = 'Podnosi z podłogi pilota albo klucze taty i ogłasza: „Ja to znalazłem, to moje!”. Dla niego znaleźć znaczy mieć. Nie wyrywaj mu tego siłą, powiedz „Dziękuję, że znalazłeś to dla mnie”, odwróć jego uwagę inną zabawką i odbierz.', title_pt = 'Fui eu que encontrei: a criança possessiva 🔑', body_pt = 'Apanha do chão o comando ou as chaves do pai e diz "Fui eu que encontrei, é meu!". Para ele, encontrar significa possuir. Não lho tire à força: diga "Obrigada por o teres encontrado para mim", desvie a atenção dele para outro brinquedo e recupere-o.', title_sv = 'Jag hittade den: den ägande 3-åringen 🔑', body_sv = 'Barnet tar upp fjärrkontrollen eller pappas nycklar från golvet och hävdar: ”Jag hittade den, den är min!” För barnet betyder att hitta att äga. Ta den inte med våld, säg ”Tack för att du hittade den åt mig”, led över uppmärksamheten till en annan leksak och ta tillbaka den.', title_vi = '"Con tìm thấy" - Bé thích chiếm hữu 🔑', body_vi = 'Bé nhặt điều khiển hay chìa khóa của bố dưới sàn lên và tuyên bố: "Con tìm thấy, của con!". Với bé, tìm thấy nghĩa là sở hữu. Đừng giật lấy, hãy nói "Cảm ơn con đã tìm giúp mẹ" và chuyển sự chú ý của bé sang đồ chơi khác để lấy lại.', title_zh = '“这是我找到的”：爱占有的幼儿 🔑', body_zh = '从地上捡起家里的遥控器或爸爸的钥匙，宣称：“这是我找到的，是我的！”对宝宝来说，找到就意味着拥有。别硬抢，说一句“谢谢你帮我找到了”，再把宝宝的注意力转到别的玩具上，把东西拿回来。' WHERE id = '9dcc2901-fb6b-4d84-a478-46c76064f671' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mini spa en el baño 🛀', body_es = 'Esta noche no le bañes solo a él: báñate tú también. Cuando el peque se duerma: agua caliente, un poco de espuma y una sola vela encendida en el baño. Cierra la puerta con pestillo y durante solo 15 minutos deja el papel de madre y vuelve a ser tú.', title_fr = 'Mini-spa dans la salle de bain 🛀', body_fr = 'Ce soir, ce n''est pas seulement lui qui prendra un bain, vous aussi. Une fois l''enfant couché : eau chaude, un peu de mousse et une seule bougie allumée dans la salle de bain. Fermez la porte à clé et, pendant 15 minutes, quittez votre rôle de maman pour redevenir vous-même.', title_hi = 'बाथरूम में मिनी-स्पा 🛀', body_hi = 'आज शाम बाथटब में सिर्फ़ उसे नहीं, खुद को भी ले जाइए। बच्चे के सोने के बाद गरम पानी, थोड़ा झाग और बाथरूम में जलती एक अकेली मोमबत्ती। दरवाज़ा बंद कीजिए और बस 15 मिनट के लिए माँ की भूमिका से बाहर आकर फिर से खुद बनिए।', title_id = 'Mini spa di kamar mandi 🛀', body_id = 'Malam ini, jangan hanya ia yang masuk bak mandi, Anda juga. Setelah anak tidur: air hangat, sedikit busa, dan sebatang lilin yang menyala di kamar mandi. Kunci pintu dan selama 15 menit saja, keluarlah dari peran ibu dan jadilah diri Anda sendiri lagi.', title_ja = 'バスルームでミニスパ 🛀', body_ja = '今夜は、この子だけでなく、あなたもお風呂に入りましょう。子どもが寝たら、温かいお湯、少しの泡、バスルームにはキャンドルをひとつ。ドアにカギをかけて、15分だけママをお休みして、あなた自身に戻りましょう。', title_ko = '욕실 속 미니 스파 🛀', body_ko = '오늘 저녁엔 아이만이 아니라 엄마도 욕조에 들어가세요. 아이가 잠들면 따뜻한 물, 약간의 거품, 그리고 욕실에 켠 초 하나. 문을 잠그고 딱 15분만 엄마 역할에서 벗어나 다시 나 자신이 되어 보세요.', title_nl = 'Minispa in de badkamer 🛀', body_nl = 'Zet vanavond niet alleen hem in bad, maar ook jezelf. Als je kind slaapt: warm water, wat schuim en één brandend kaarsje in de badkamer. Doe de deur op slot en wees 15 minuten even geen mama, maar weer gewoon jezelf.', title_pl = 'Mini spa w łazience 🛀', body_pl = 'Dziś wieczorem nie tylko jego wsadź do wanny, ale i siebie. Gdy dziecko zaśnie: gorąca woda, trochę piany i jedna świeca w łazience. Zamknij drzwi na klucz i choć na 15 minut wyjdź z roli mamy, znów bądź sobą.', title_pt = 'Mini-spa na casa de banho 🛀', body_pt = 'Esta noite, ponha na banheira não só ele, mas também a si própria. Depois de a criança adormecer: água quente, um pouco de espuma e uma única vela acesa na casa de banho. Tranque a porta e, só durante 15 minutos, deixe de ser mãe e volte a ser você.', title_sv = 'Minispa i badrummet 🛀', body_sv = 'I kväll är det inte bara barnet som ska i badet, utan du också. När barnet har somnat: varmt vatten, lite skum och ett enda tänt ljus i badrummet. Lås dörren och kliv ur mammarollen i bara 15 minuter, var dig själv igen.', title_vi = 'Mini-spa trong phòng tắm 🛀', body_vi = 'Tối nay, không chỉ bé mà mẹ cũng hãy ngâm mình trong bồn. Sau khi bé ngủ: nước ấm, chút bọt xà phòng và một ngọn nến duy nhất trong phòng tắm. Khóa cửa lại và chỉ trong 15 phút, hãy tạm gác vai trò làm mẹ để lại là chính mình.', title_zh = '浴室里的迷你水疗 🛀', body_zh = '今晚不只让宝宝泡澡，你自己也去泡一泡。宝宝睡着后，热水、一点泡泡，再在浴室里点一支蜡烛。锁上门，就15分钟，放下妈妈的角色，重新做回你自己。' WHERE id = 'c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intento de peluquero ✂️', body_es = 'Al entrar en la habitación ves que intenta cortarle el pelo a su muñeca con unas tijeras. Vivir este momento es la pesadilla de toda madre. Sin enfadarte, quítale las tijeras y guarda este intento de peluquero en la Sesión de fotos del bebé como un archivo cómico.', title_fr = 'Apprenti coiffeur ✂️', body_fr = 'En entrant dans la pièce, vous le découvrez ciseaux en main en train de couper les cheveux de sa poupée. Le cauchemar de toute maman ! Sans vous énerver, reprenez les ciseaux et gardez cette tentative de coiffeur comme un souvenir comique dans la Séance photo bébé.', title_hi = 'नाई बनने की कोशिश ✂️', body_hi = 'कमरे में जाती हैं तो देखती हैं कि वह हाथ में कैंची लेकर अपनी गुड़िया के बाल काटने की कोशिश कर रहा है। यह पल हर माँ का डरावना सपना है। नाराज़ हुए बिना कैंची ले लीजिए और नाई बनने की इस कोशिश को बेबी फ़ोटोशूट में एक मज़ेदार याद के रूप में सँजो लीजिए।', title_id = 'Percobaan jadi tukang cukur ✂️', body_id = 'Saat masuk kamar, Anda melihatnya memegang gunting dan mencoba memotong rambut bonekanya. Mengalami momen ini adalah mimpi buruk setiap ibu. Tanpa kesal, ambil guntingnya dan simpan percobaan tukang cukur ini di Pemotretan Bayi sebagai arsip lucu.', title_ja = '美容師さんのチャレンジ ✂️', body_ja = '部屋に入ると、はさみを手に人形の髪を切ろうとしている。どのママにとっても悪夢のような瞬間です。怒らずにはさみを受けとって、この美容師チャレンジを「ベビーフォトセッション」で、おかしな記録として残しておきましょう。', title_ko = '미용사 도전 ✂️', body_ko = '방에 들어가니 가위를 들고 인형 머리를 자르려 하고 있나요? 모든 엄마의 악몽 같은 순간이죠. 화내지 말고 가위를 받아 든 뒤, 이 미용사 도전을 아기 사진 촬영으로 웃긴 기록으로 남겨 두세요.', title_nl = 'Kapperspoging ✂️', body_nl = 'Je komt de kamer binnen en ziet dat hij met een schaar het haar van zijn pop probeert te knippen. Dit is de nachtmerrie van elke mama. Neem zonder boos te worden de schaar af en bewaar deze kapperspoging als grappig archief met de Babyfotoshoot.', title_pl = 'Próba fryzjerska ✂️', body_pl = 'Wchodzisz do pokoju i widzisz, jak z nożyczkami w ręku próbuje obciąć włosy lalce. To koszmar każdej mamy. Bez nerwów zabierz nożyczki, a tę próbę fryzjerską zachowaj w Sesji zdjęciowej dziecka jako zabawną pamiątkę.', title_pt = 'Tentativa de cabeleireiro ✂️', body_pt = 'Entra no quarto e vê-o de tesoura na mão a tentar cortar o cabelo à boneca. Viver este momento é o pesadelo de qualquer mãe. Sem se irritar, tire-lhe a tesoura e guarde esta tentativa de cabeleireiro na Sessão Fotográfica do Bebé, como arquivo cómico.', title_sv = 'Frisörförsök ✂️', body_sv = 'När du kommer in i rummet ser du att barnet försöker klippa dockans hår med en sax. Att uppleva den stunden är varje mammas mardröm. Ta saxen utan att bli arg och spara frisörförsöket som ett roligt minne med Babyfotografering.', title_vi = 'Thử làm thợ cắt tóc ✂️', body_vi = 'Bước vào phòng, mẹ thấy bé đang cầm kéo cố cắt tóc cho búp bê. Đây là cơn ác mộng của mọi bà mẹ. Đừng bực mình, hãy lấy kéo đi và lưu giữ màn "thợ cắt tóc" này bằng Chụp ảnh cho bé như một kỷ niệm hài hước.', title_zh = '理发尝试 ✂️', body_zh = '走进房间，发现宝宝正拿着剪刀给布娃娃剪头发。经历这一刻，是每个妈妈的噩梦。别生气，把剪刀拿过来，用宝宝写真把这次“理发尝试”当作搞笑的纪念保存下来吧。' WHERE id = 'cfb02ba9-2584-45e0-a1c3-ce6672adabe6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Devuélveme la canción! 🎶', body_es = 'Quiere otra vez la canción que sonaba en la radio y que ya ha terminado. Le explicas que era en directo y que se ha acabado. Pero llora: «¡Devuélvemela!». El cerebro infantil no entiende la lógica de la emisión en directo. Para distraerle, ponte a cantar tú la canción con una voz distinta y cómica.', title_fr = 'Remets la chanson ! 🎶', body_fr = 'Il réclame la chanson qui vient de passer à la radio. Vous lui expliquez que c''était en direct et que c''est fini, mais il pleure : « Remets-la ! » Le cerveau de l''enfant ne comprend pas la logique du direct. Pour détourner son attention, chantez vous-même la chanson avec une voix différente et comique.', title_hi = 'गाना वापस लाओ! 🎶', body_hi = 'रेडियो पर बजकर खत्म हुआ गाना फिर से चाहता है। आप समझाती हैं कि वह लाइव प्रसारण था, खत्म हो गया। पर वह ‘वापस लाओ!’ कहकर रोता है। बच्चे का दिमाग लाइव प्रसारण का तर्क नहीं समझता। ध्यान बँटाने के लिए वही गाना खुद अलग, मज़ेदार आवाज़ में गाना शुरू कीजिए।', title_id = 'Putar lagi lagunya! 🎶', body_id = 'Ia ingin lagu yang tadi diputar di radio dan sudah selesai diputar lagi. Anda menjelaskan bahwa itu siaran langsung dan sudah selesai. Tapi ia menangis ''Putar lagi!''. Otak anak belum memahami logika siaran langsung. Untuk mengalihkan perhatiannya, nyanyikan sendiri lagu itu dengan suara yang lucu dan berbeda.', title_ja = '歌をもう一回！ 🎶', body_ja = 'ラジオで流れて終わった歌を、もう一度聞きたがる。生放送だったから終わったんだよ、と説明しても「もう一回！」と泣く。子どもの脳には、生放送の理屈がわからないんです。気をそらすために、あなたがへんてこな声でその歌を歌ってあげましょう。', title_ko = '노래 다시 틀어 줘! 🎶', body_ko = '라디오에서 나오다 끝난 노래를 다시 틀어 달라고 하나요? 생방송이라 끝났다고 설명해도 ''다시 틀어 줘!'' 하며 울죠. 아이의 뇌는 생방송의 논리를 이해하지 못해요. 관심을 돌리려면 엄마가 그 노래를 웃긴 목소리로 불러 주세요.', title_nl = 'Zet het liedje terug! 🎶', body_nl = 'Hij wil het liedje dat op de radio speelde en net is afgelopen nog een keer horen. Je legt uit dat het live was en voorbij is. Maar hij huilt: ''Zet het terug!'' Een kinderbrein begrijpt de logica van een live-uitzending niet. Zing het liedje zelf met een andere, grappige stem om hem af te leiden.', title_pl = 'Puść piosenkę jeszcze raz! 🎶', body_pl = 'Chce, żeby piosenka, która właśnie skończyła się w radiu, poleciała jeszcze raz. Tłumaczysz, że to była transmisja na żywo i się skończyła. A on płacze: „Puść jeszcze raz!”. Dziecięcy mózg nie rozumie logiki transmisji na żywo. Żeby odwrócić jego uwagę, zacznij sama śpiewać tę piosenkę innym, zabawnym głosem.', title_pt = 'Volta a pôr a música! 🎶', body_pt = 'Quer outra vez a canção que tocou na rádio e acabou. Explica-lhe que era uma emissão em direto e que acabou. Mas ele chora: "Volta a pôr!". O cérebro da criança não percebe a lógica do direto. Para o distrair, comece a cantar a canção com uma voz diferente e cómica.', title_sv = 'Spela låten igen! 🎶', body_sv = 'Barnet vill höra låten som spelades på radion och tog slut igen. Du förklarar att det var en direktsändning och att den är slut. Men barnet gråter: ”Spela den igen!” Barnets hjärna förstår inte logiken bakom direktsändning. Avled uppmärksamheten genom att själv börja sjunga låten med en annan, rolig röst.', title_vi = 'Trả bài hát lại đây! 🎶', body_vi = 'Bé muốn nghe lại bài hát vừa phát xong trên đài. Mẹ giải thích đó là phát trực tiếp, đã hết rồi. Nhưng bé khóc: "Trả lại đây!". Não bộ trẻ chưa hiểu logic của phát trực tiếp. Để đánh lạc hướng, hãy tự hát bài đó bằng một giọng khác, thật hài hước.', title_zh = '把歌还回来！🎶', body_zh = '收音机里播完的歌，宝宝还想再听。你解释说那是直播，已经结束了。可宝宝哭着喊“还回来！”孩子的大脑还理解不了直播的逻辑。为了转移注意力，你自己用不同的、搞笑的声音把那首歌唱起来吧。' WHERE id = '175e4578-dab7-4e75-8a87-dd96baf6d2c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cosas innecesarias en la lista de la compra 🛒', body_es = 'Antes de ir al súper abriste la Lista de la compra y viste que se había acercado por detrás, había tocado la pantalla y había añadido letras sin sentido seguidas y chocolate. ¡Sí, descubren el mundo digital muy deprisa!', title_fr = 'Des choses inutiles sur la liste de courses 🛒', body_fr = 'Avant d''aller au supermarché, vous avez ouvert la Liste de courses, et il est arrivé derrière vous pour taper sur l''écran et y ajouter une suite de lettres incompréhensibles et du chocolat. Eh oui, ils découvrent le monde numérique à toute vitesse !', title_hi = 'शॉपिंग लिस्ट में बेकार की चीज़ें 🛒', body_hi = 'बाज़ार जाने से पहले आपने शॉपिंग लिस्ट खोली और देखा कि उसने पीछे से आकर स्क्रीन पर टैप करके एक के बाद एक बेमतलब अक्षर और चॉकलेट जोड़ दी है। हाँ, वे डिजिटल दुनिया बहुत तेज़ी से खोजते हैं!', title_id = 'Barang tak perlu di Daftar Belanja 🛒', body_id = 'Sebelum ke supermarket Anda membuka Daftar Belanja, lalu ia datang dari belakang, menekan layar ponsel, dan menambahkan deretan huruf tak jelas dan cokelat. Ya, mereka menjelajahi dunia digital dengan sangat cepat!', title_ja = '買い物リストの中のいらないもの 🛒', body_ja = '買い物の前に「買い物リスト」を開いたら、後ろから来て画面をタップし、わけのわからない文字とチョコを次々に追加していた。そう、子どもたちはデジタルの世界をものすごい速さで発見しているんです！', title_ko = '쇼핑 목록 속 엉뚱한 것들 🛒', body_ko = '마트에 가기 전 쇼핑 목록을 열었는데, 아이가 뒤에서 와서 화면을 눌러 알 수 없는 글자와 초콜릿을 줄줄이 넣었나요? 네, 아이들은 디지털 세상을 정말 빠르게 탐험해요!', title_nl = 'Overbodige dingen op het boodschappenlijstje 🛒', body_nl = 'Je opende voor het boodschappen doen je Boodschappenlijstje en zag dat hij van achteren op het scherm drukte en een reeks onbegrijpelijke letters en chocola toevoegde. Ja, ze ontdekken de digitale wereld razendsnel!', title_pl = 'Zbędne rzeczy na liście zakupów 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś Listę zakupów, a on podszedł od tyłu, stuknął w ekran i dopisał ciąg niezrozumiałych liter i czekoladę. Tak, dzieci bardzo szybko odkrywają cyfrowy świat!', title_pt = 'Coisas inúteis na lista de compras 🛒', body_pt = 'Antes de ir ao supermercado abriu a Lista de Compras e viu-o vir por trás, carregar no ecrã do telemóvel e acrescentar letras sem sentido umas atrás das outras e chocolate. Pois é, descobrem o mundo digital muito depressa!', title_sv = 'Onödiga saker på inköpslistan 🛒', body_sv = 'Innan du gick till butiken öppnade du Inköpslistan, och barnet kom bakifrån och tryckte på skärmen och lade till obegripliga bokstäver och choklad i rad. Ja, de upptäcker den digitala världen väldigt snabbt!', title_vi = 'Những thứ "thừa" trong danh sách mua sắm 🛒', body_vi = 'Trước khi đi siêu thị, mẹ mở Danh sách mua sắm và thấy bé từ phía sau chạm vào màn hình, thêm vào một loạt chữ cái khó hiểu và cả sô-cô-la. Đúng vậy, trẻ khám phá thế giới số nhanh đến chóng mặt!', title_zh = '购物清单里的“没用东西” 🛒', body_zh = '去超市前你打开了购物清单，结果发现宝宝从背后过来，在手机屏幕上一通乱点，加了一串看不懂的字母和巧克力。没错，他们探索数字世界的速度非常快！' WHERE id = 'a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un té en silencio ☕', body_es = 'En medio de la habitación pone sus juguetes en fila y juega solo. ¡Por favor, no dediques ese momento a barrer la casa! Siéntate en el sofá, tómate el café o el té calentito y durante 10 minutos disfruta de este silencio sin pensar en nada.', title_fr = 'Un thé dans le silence ☕', body_fr = 'Au milieu de la pièce, il aligne ses jouets et joue tout seul. Par pitié, ne passez pas ce moment à balayer la maison ! Asseyez-vous sur le canapé, buvez votre café ou votre thé bien chaud et savourez simplement ce silence 10 minutes, sans penser à rien.', title_hi = 'खामोशी में चाय ☕', body_hi = 'कमरे के बीच खिलौने लाइन में लगाकर अकेले खेल रहा है। मेरी जान, वह पल झाड़ू लगाने में मत गँवाइए! सोफ़े पर बैठिए, अपनी कॉफ़ी या चाय गरम-गरम पीजिए और 10 मिनट कुछ सोचे बिना बस इस खामोशी का मज़ा लीजिए।', title_id = 'Teh dalam keheningan ☕', body_id = 'Ia bermain sendiri di tengah kamar sambil menjajarkan mainannya. Kumohon, jangan pakai momen itu untuk menyapu rumah! Duduklah di sofa, minum kopi atau tehmu selagi panas, dan selama 10 menit nikmati saja keheningan ini tanpa memikirkan apa pun.', title_ja = '静けさの中のお茶 ☕', body_ja = '部屋のまんなかでおもちゃを並べて、ひとりで遊んでいます。お願い、その時間を床そうじに使わないで！ソファに座って、コーヒーかお茶を温かいうちに飲み、10分間何も考えずに、この静けさを味わいましょう。', title_ko = '고요 속의 차 한 잔 ☕', body_ko = '방 한가운데서 장난감을 줄 세우며 혼자 놀고 있나요? 제발 그 시간에 집을 쓸지 마세요! 소파에 앉아 커피나 차를 따뜻할 때 마시고, 10분 동안 아무 생각 없이 이 고요를 누리세요.', title_nl = 'Thee in stilte ☕', body_nl = 'Hij zet midden in de kamer zijn speelgoed op een rij en speelt in zijn eentje. Alsjeblieft, besteed dat moment niet aan het vegen van het huis! Ga op de bank zitten, drink je koffie of thee lekker warm en geniet 10 minuten van de stilte zonder ergens aan te denken.', title_pl = 'Herbata w ciszy ☕', body_pl = 'Ustawia na środku pokoju zabawki w rzędzie i bawi się sam. Błagam, nie przeznaczaj tej chwili na zamiatanie! Usiądź na kanapie, wypij gorącą kawę albo herbatę i przez 10 minut, o niczym nie myśląc, po prostu delektuj się tą ciszą.', title_pt = 'Chá em silêncio ☕', body_pt = 'No meio do quarto, pôs os brinquedos em fila e brinca sozinho. Por amor de Deus, não gaste esse momento a varrer a casa! Sente-se no sofá, beba o café ou o chá bem quente e, durante 10 minutos, saboreie este silêncio sem pensar em nada.', title_sv = 'Te i tystnaden ☕', body_sv = 'Barnet har ställt upp sina leksaker på rad mitt i rummet och leker ensamt. Lilla vän, använd inte den stunden till att dammsuga! Sätt dig i soffan, drick ditt kaffe eller te medan det är varmt och njut bara av tystnaden i 10 minuter utan att tänka på något.', title_vi = 'Trà trong im lặng ☕', body_vi = 'Bé đang xếp đồ chơi thành hàng và chơi một mình giữa phòng. Mẹ ơi, đừng dùng khoảnh khắc đó để quét nhà! Hãy ngồi xuống sofa, uống cà phê hay trà khi còn nóng và trong 10 phút, không nghĩ gì cả, chỉ tận hưởng sự yên tĩnh này.', title_zh = '安静中的一杯茶 ☕', body_zh = '在房间中间把玩具排成一排，一个人玩着。亲爱的，别把这段时间花在扫地上！坐到沙发上，趁热喝完你的咖啡或茶，在10分钟里什么都不想，只是享受这份安静。' WHERE id = 'f9e8851b-f40e-4ed9-a246-2e1405232755' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica del temporizador para dormir ⏱️', body_es = '¿Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared? Pon un temporizador. Aplica la norma «cuando suena la campanita, todos a dormir» y líbrate sin discusiones de esta despedida sin fin, de esta manipulación tan experta.', title_fr = 'La tactique du minuteur pour dormir ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde dort » et échappez sans dispute à ces adieux sans fin, à cette manipulation de maître.', title_hi = 'नींद के लिए टाइमर की तरकीब ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है? टाइमर लगाइए। ‘घंटी बजते ही सब सो जाते हैं’ का नियम लागू करके इस अंतहीन अलविदा, इस माहिर चाल से बिना बहस के बच निकलिए।', title_id = 'Taktik timer untuk tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua tidur'' dan bebaskan diri tanpa berdebat dari perpisahan tanpa akhir dan manipulasi cerdik ini.', title_ja = '寝かしつけのタイマー作戦 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり？タイマーをセットしましょう。「ベルが鳴ったらみんな寝る」のルールで、この終わらないおやすみのあいさつ、この見事な作戦から、言い合わずに抜け出して。', title_ko = '잠을 위한 타이머 작전 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 잔다'' 규칙을 정해 이 끝없는 작별 인사, 이 노련한 작전에서 실랑이 없이 벗어나세요.', title_nl = 'Timertactiek voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaat iedereen slapen'' in en verlos jezelf zonder discussie van dit eindeloze afscheid, deze meesterlijke manipulatie.', title_pl = 'Taktyka z minutnikiem przed snem ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą? Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy śpią” i bez kłótni uwolnij się od tych niekończących się pożegnań, tej mistrzowskiej manipulacji.', title_pt = 'A tática do temporizador para dormir ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede? Programe um temporizador. Aplique a regra "quando a campainha toca, todos dormem" e livre-se sem discussões desta despedida sem fim, desta manipulação de mestre.', title_sv = 'Timertaktik för sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla” och rädda dig utan bråk från det ändlösa farvälet och den här mästerliga manipulationen.', title_vi = 'Chiến thuật hẹn giờ đi ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà đi ngủ" để thoát khỏi những lời tạm biệt bất tận, màn "thao túng" bậc thầy này mà không cần tranh cãi.', title_zh = '用计时器哄睡的战术 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见？设个计时器。立下“铃声一响，大家都睡觉”的规矩，不争不吵地摆脱这没完没了的告别和高明的“操控”吧。' WHERE id = '92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un verdadero artista elige la pared 🖍️', body_es = 'Unos segundos de silencio acabaron en peligro. Entraste en la habitación y viste que había pintado una obra de arte en la pared con rotuladores. Respira hondo. Su motricidad fina se desarrolla y la pared se limpia. Hazle sin falta una foto a esta obra maestra para reírte en el futuro.', title_fr = 'Un vrai artiste choisit le mur 🖍️', body_fr = 'Quelques secondes de silence ont mal tourné. En entrant dans la pièce, vous l''avez trouvé en train de dessiner une œuvre d''art au feutre sur le mur. Respirez profondément. Sa motricité fine se développe, et le mur se nettoie de toute façon. Prenez absolument ce chef-d''œuvre en photo pour en rire plus tard.', title_hi = 'सच्चा कलाकार दीवार चुनता है 🖍️', body_hi = 'कुछ सेकंड की खामोशी खतरे में बदल गई। कमरे में जाकर देखा कि उसने दीवार पर मार्कर से कलाकृति बना दी है। गहरी साँस लीजिए। उसकी बारीक मोटर स्किल्स बढ़ रही हैं, और दीवार तो साफ़ हो ही जाती है। इस शाहकार की तस्वीर ज़रूर लीजिए, ताकि आगे हँस सकें।', title_id = 'Seniman sejati memilih dinding 🖍️', body_id = 'Hening beberapa detik berujung bahaya. Anda masuk kamar dan melihat ia melukis karya seni di dinding dengan spidol. Tarik napas dalam. Motorik halusnya berkembang, dan dinding toh bisa dibersihkan. Pastikan memotret mahakarya ini agar kelak bisa ditertawakan.', title_ja = '本物の画家は壁を選ぶ 🖍️', body_ja = '数秒の静けさは、危険の合図でした。部屋に入ると、壁にマーカーで作品を描いていた。深呼吸して。指先の力が育っていますし、壁はどうせ拭けば落ちます。この傑作は、将来笑えるようにぜひ写真に撮っておきましょう。', title_ko = '진짜 화가는 벽을 고른다 🖍️', body_ko = '몇 초간의 고요가 사고로 이어졌나요? 방에 들어가니 벽에 사인펜으로 작품을 그리고 있네요. 깊게 숨 쉬세요. 소근육이 자라고 있고, 벽은 어차피 닦여요. 나중에 웃을 수 있게 이 걸작을 꼭 사진으로 남겨 두세요.', title_nl = 'Een echte kunstenaar kiest de muur 🖍️', body_nl = 'Een paar seconden stilte bleken gevaarlijk. Je kwam de kamer binnen en zag dat hij met een stift een kunstwerk op de muur tekende. Haal diep adem. Zijn fijne motoriek ontwikkelt zich, en de muur is toch af te wassen. Maak zeker een foto van dit meesterwerk om er later om te lachen.', title_pl = 'Prawdziwy artysta wybiera ścianę 🖍️', body_pl = 'Kilka sekund ciszy skończyło się katastrofą. Wchodzisz do pokoju, a on flamastrem rysuje dzieło sztuki na ścianie. Weź głęboki oddech. Rozwija się motoryka mała, a ścianę i tak da się zmyć. Koniecznie zrób zdjęcie temu arcydziełu, żeby kiedyś się z niego pośmiać.', title_pt = 'Um verdadeiro artista escolhe a parede 🖍️', body_pt = 'Uns segundos de silêncio acabaram em perigo. Entrou no quarto e viu que fez uma obra de arte na parede com marcadores. Respire fundo. A motricidade fina está a desenvolver-se e a parede limpa-se. Não deixe de fotografar esta obra-prima para se rir dela no futuro.', title_sv = 'En riktig konstnär väljer väggen 🖍️', body_sv = 'Några sekunders tystnad slutade i fara. Du kom in i rummet och såg att barnet målat ett konstverk på väggen med tusch. Andas djupt. Finmotoriken utvecklas, och väggen går ju att torka av. Ta absolut ett foto av mästerverket att skratta åt i framtiden.', title_vi = 'Họa sĩ thực thụ thì chọn bức tường 🖍️', body_vi = 'Vài giây im lặng đã dẫn đến "thảm họa". Mẹ bước vào phòng và thấy bé đang dùng bút dạ vẽ "tác phẩm nghệ thuật" lên tường. Hãy hít thở sâu. Kỹ năng vận động tinh của bé đang phát triển, còn tường thì lau được. Nhất định hãy chụp lại "kiệt tác" này để sau này cùng cười.', title_zh = '真正的画家都选墙 🖍️', body_zh = '几秒钟的安静带来了“危险”。走进房间，发现宝宝正用水彩笔在墙上创作艺术品。深吸一口气。精细动作在发展，墙反正也能擦干净。一定要把这幅杰作拍下来，留着将来笑一笑。' WHERE id = '9d39f5c1-6418-4ab4-8bba-64b21fccd4ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la Comunidad Anacan 💬', body_es = 'El pensamiento «¿Por qué mi hijo es tan tozudo?» te está comiendo por dentro. Entra en la Comunidad Anacan. Cuando leas las crisis absurdas parecidas que estallan en casa de otras madres, verás que no estás sola y que vas por un camino totalmente normal.', title_fr = 'La force de la Communauté Anacan 💬', body_fr = 'La pensée « Pourquoi mon enfant est-il si têtu ? » vous ronge ? Rejoignez la Communauté Anacan. En lisant les crises absurdes qui éclatent chez d''autres mamans, vous verrez que vous n''êtes pas seule et que vous êtes sur une voie tout à fait normale.', title_hi = 'Anacan कम्युनिटी की ताकत 💬', body_hi = '‘मेरा बच्चा इतना ज़िद्दी क्यों है?’ वाला ख्याल आपका दिमाग खा रहा है। Anacan कम्युनिटी में जाइए। दूसरी माँओं के घरों में होने वाले ऐसे ही बेतुके नखरे पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और बिल्कुल सही रास्ते पर हैं।', title_id = 'Kekuatan Komunitas Anacan 💬', body_id = 'Pikiran ''Kenapa anakku keras kepala sekali?'' terus menggerogoti otak Anda. Masuklah ke Komunitas Anacan. Saat membaca krisis absurd serupa di rumah ibu-ibu lain, Anda akan melihat bahwa Anda tidak sendirian dan sedang berada di jalur yang sepenuhnya normal.', title_ja = 'Anacanコミュニティの力 💬', body_ja = '「うちの子はどうしてこんなにがんこなの？」という思いが頭から離れない。Anacanコミュニティを開いてみましょう。ほかのママたちの家で起きている、同じようなおかしなかんしゃくを読めば、ひとりじゃないこと、ごく普通の道を歩んでいることがわかります。', title_ko = 'Anacan 커뮤니티의 힘 💬', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각이 머리를 갉아먹나요? Anacan 커뮤니티에 들어가 보세요. 다른 집에서 터지는 비슷하게 엉뚱한 떼쓰기를 읽으면 혼자가 아니고 아주 정상적인 길을 걷고 있다는 걸 알게 될 거예요.', title_nl = 'De kracht van de Anacan Community 💬', body_nl = 'Vreet de gedachte ''Waarom is mijn kind zo koppig?'' aan je? Ga naar de Anacan Community. Als je leest over net zulke absurde buien bij andere mama''s thuis, zie je dat je niet de enige bent en dat je helemaal op de normale weg zit.', title_pl = 'Siła Społeczności Anacan 💬', body_pl = 'Myśl „Dlaczego moje dziecko jest takie uparte?” nie daje ci spokoju. Wejdź do Społeczności Anacan. Gdy przeczytasz o podobnych absurdalnych kryzysach w domach innych mam, zobaczysz, że nie jesteś sama i wszystko idzie zupełnie normalnym torem.', title_pt = 'A força da Comunidade Anacan 💬', body_pt = 'O pensamento "Porque é que o meu filho é tão teimoso?" não lhe sai da cabeça. Entre na Comunidade Anacan. Ao ler as crises absurdas parecidas que rebentam em casa de outras mães, vai ver que não está sozinha e que está no caminho perfeitamente normal.', title_sv = 'Anacan Communitys kraft 💬', body_sv = 'Tanken ”Varför är mitt barn så envist?” äter upp dig. Gå in i Anacan Community. När du läser om liknande absurda kriser hemma hos andra mammor ser du att du inte är ensam och att du är helt på rätt väg.', title_vi = 'Sức mạnh của Cộng đồng Anacan 💬', body_vi = 'Ý nghĩ "Sao con mình bướng thế?" cứ ám ảnh mẹ. Hãy vào Cộng đồng Anacan. Khi đọc về những cơn khủng hoảng "khó đỡ" tương tự ở nhà các mẹ khác, mẹ sẽ thấy mình không đơn độc và mọi thứ đều hoàn toàn bình thường.', title_zh = 'Anacan社区的力量 💬', body_zh = '“我的孩子怎么这么倔？”这个念头一直折磨着你。进入Anacan社区。读到其他妈妈家里也在上演类似的荒诞崩溃，你就会发现自己并不孤单，一切完全正常。' WHERE id = 'dda9eb22-cebb-4f1b-962b-3223d17b83eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite a primera hora 🙈', body_es = 'Llegas tarde al trabajo o a la guardería y él se esconde detrás de la cortina diciendo: «¡Encuéntrame!». Aunque tengas los nervios a flor de piel, gritar alargará aún más el proceso. Únete 2 minutos al juego: «¿Dónde estará mi niño tan bonito?», encuéntrale y sácale de ahí.', title_fr = 'Cache-cache au petit matin 🙈', body_fr = 'Vous êtes en retard pour le travail ou la crèche, et lui se cache derrière le rideau en disant « Trouve-moi ! ». Même si vos nerfs sont à vif, crier ne fera que rallonger les choses. Entrez 2 minutes dans le jeu, « Mais où est passé mon beau bébé ? », puis trouvez-le et sortez-le de là.', title_hi = 'सुबह-सुबह छुपन-छुपाई 🙈', body_hi = 'आपको काम या प्ले स्कूल के लिए देर हो रही है, और वह पर्दे के पीछे छिपकर कहता है, ‘मुझे ढूँढो!’ नसें तनी हों, फिर भी चिल्लाने से काम और लंबा खिंचेगा। ‘मेरा प्यारा बच्चा कहाँ है?’ कहकर 2 मिनट खेल में शामिल होइए और उसे ढूँढकर बाहर निकाल लीजिए।', title_id = 'Petak umpet pagi-pagi 🙈', body_id = 'Anda terlambat ke kantor atau TK, sementara ia bersembunyi di balik gorden dan berkata ''Cari aku!''. Meski saraf Anda menegang, berteriak hanya akan membuat semuanya makin lama. Ikutlah bermain 2 menit: ''Di mana ya anak Mama yang cantik?'', temukan ia dan bawa keluar.', title_ja = '朝からかくれんぼ 🙈', body_ja = '仕事や保育園に遅れそうなのに、カーテンの後ろに隠れて「見つけて！」と言う。神経がピンと張りつめても、叫べばよけいに長引きます。「わたしのかわいい子はどこかな？」と2分だけ遊びに乗って、見つけて連れ出しましょう。', title_ko = '아침 숨바꼭질 🙈', body_ko = '출근이나 어린이집에 늦었는데 커튼 뒤에 숨어 ''나 찾아 봐!''라고 하나요? 신경이 곤두서도 소리치면 시간만 더 걸려요. 2분만 놀이에 함께하며 ''우리 예쁜 아기 어디 있지?'' 하고 찾아서 데리고 나오세요.', title_nl = 'Verstoppertje in de ochtend 🙈', body_nl = 'Jullie zijn te laat voor werk of opvang, en hij verstopt zich achter het gordijn: ''Zoek me!'' Ook al staan je zenuwen strak gespannen, schreeuwen maakt het alleen maar langer. Doe 2 minuten mee met ''Waar is mijn mooie kindje nou?'', vind hem en haal hem tevoorschijn.', title_pl = 'Poranna zabawa w chowanego 🙈', body_pl = 'Spóźniacie się do pracy albo przedszkola, a on chowa się za zasłoną i woła „Znajdź mnie!”. Choć nerwy masz napięte do granic, krzyk tylko wszystko przedłuży. Dołącz do zabawy na 2 minuty: „Gdzie jest mój śliczny skarb?”, znajdź go i wyprowadź.', title_pt = 'Escondidas logo de manhã 🙈', body_pt = 'Está atrasada para o trabalho ou para o jardim de infância e ele escondeu-se atrás da cortina: "Encontra-me!". Mesmo com os nervos em franja, gritar só vai prolongar tudo. Entre no jogo 2 minutos, "Onde estará o meu menino lindo?", encontre-o e tire-o de lá.', title_sv = 'Kurragömma tidigt på morgonen 🙈', body_sv = 'Ni är sena till jobbet eller förskolan, och barnet gömmer sig bakom gardinen och säger ”Hitta mig!”. Även om nerverna är på helspänn förlänger skrik bara det hela. Säg ”Undrar var min fina lilla är?”, var med i leken i 2 minuter, hitta barnet och ta fram det.', title_vi = 'Trốn tìm buổi sáng 🙈', body_vi = 'Mẹ đang trễ giờ làm hoặc giờ đi mầm non, còn bé trốn sau rèm cửa và nói "Mẹ tìm con đi!". Dù mẹ căng như dây đàn, quát mắng chỉ khiến mọi việc kéo dài hơn. Hãy tham gia trò chơi 2 phút: "Bé cưng xinh đẹp của mẹ đâu rồi nhỉ?" rồi tìm thấy và đưa bé ra.', title_zh = '一大早玩捉迷藏 🙈', body_zh = '你上班或送幼儿园已经要迟到了，宝宝却躲在窗帘后面喊“来找我！”。虽然你的神经已经绷紧了，但吼叫只会让事情拖得更久。说一句“我漂亮的小宝贝在哪儿呢？”，花2分钟加入游戏，把宝宝找出来吧。' WHERE id = '1c56259d-5943-4110-9eaf-5c1870b222b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Separar la comida por colores 🍅', body_es = 'Separa la comida del plato por colores y formas y empuja lo verde a un lado. Entra en el Plan de alimentación. Descubre cómo convertir esas verduras en un puré invisible y esconderlas en salsas ricas, y gana este juego a escondidas.', title_fr = 'Trier la nourriture par couleur 🍅', body_fr = 'Il trie les aliments de son assiette par couleur et par forme, et pousse les verts sur le côté. Ouvrez le Plan de nutrition. Gagnez discrètement cette partie en découvrant comment transformer ces légumes en purée invisible à cacher dans de délicieuses sauces.', title_hi = 'खाना रंग के हिसाब से अलग करना 🍅', body_hi = 'प्लेट का खाना रंग और आकार के हिसाब से अलग करता है, और हरी चीज़ें एक तरफ़ सरका देता है। फ़ीडिंग प्लान खोलिए। जानिए कि उन सब्ज़ियों की अदृश्य प्यूरी बनाकर स्वादिष्ट सॉस में कैसे छिपाएँ, और इस खेल में चुपके से जीत जाइए।', title_id = 'Memisahkan makanan berdasarkan warna 🍅', body_id = 'Ia memisahkan makanan di piring berdasarkan warna dan bentuknya, lalu mendorong yang hijau ke pinggir. Buka Rencana Nutrisi. Menangkan permainan ini diam-diam dengan menemukan cara menghaluskan sayur hingga tak terlihat dan menyembunyikannya dalam saus yang lezat.', title_ja = '食べ物を色で分ける 🍅', body_ja = 'お皿の料理を色や形で分けて、緑のものは脇に押しやっている。「栄養管理ツール」を開いてみましょう。野菜を見えないピューレにして、おいしいソースに隠す方法を見つけて、このゲームにこっそり勝ちましょう。', title_ko = '음식 색깔별로 나누기 🍅', body_ko = '접시 위 음식을 색깔과 모양별로 나누고 초록색은 옆으로 밀어내나요? 식단 계획에 들어가 보세요. 채소를 감쪽같은 퓌레로 만들어 맛있는 소스에 숨기는 법을 찾아 이 게임에서 몰래 이기세요.', title_nl = 'Eten sorteren op kleur 🍅', body_nl = 'Hij sorteert het eten op zijn bord op kleur en vorm en schuift alles wat groen is aan de kant. Open het Voedingsplan. Win dit spel stiekem door te ontdekken hoe je die groenten onzichtbaar pureert en in lekkere sausjes verstopt.', title_pl = 'Sortowanie jedzenia według kolorów 🍅', body_pl = 'Rozdziela jedzenie na talerzu według kolorów i kształtów, a zielone odsuwa na bok. Zajrzyj do planu karmienia. Odkryj, jak zamienić te warzywa w niewidzialne purée i ukryć je w pysznych sosach, i po cichu wygraj tę grę.', title_pt = 'Separar a comida pela cor 🍅', body_pt = 'Separa a comida do prato por cores e formas e empurra o que é verde para o lado. Entre no Registo de Alimentação. Descubra como transformar esses legumes num puré invisível e escondê-los em molhos saborosos, e ganhe este jogo às escondidas.', title_sv = 'Sortera maten efter färg 🍅', body_sv = 'Barnet sorterar maten på tallriken efter färg och form och skjuter de gröna bitarna åt sidan. Gå in i matplanen. Vinn leken i smyg genom att upptäcka hur du gör grönsakerna till osynligt mos och gömmer dem i goda såser.', title_vi = 'Phân loại thức ăn theo màu sắc 🍅', body_vi = 'Bé phân loại thức ăn trên đĩa theo màu sắc và hình dạng, còn những thứ màu xanh thì đẩy ra một bên. Hãy vào Kế hoạch dinh dưỡng. Khám phá cách xay rau thành dạng nhuyễn "vô hình" để giấu vào những món sốt ngon lành và âm thầm chiến thắng trò chơi này.', title_zh = '按颜色分开吃 🍅', body_zh = '把盘子里的食物按颜色和形状分开，绿色的全推到一边。去喂养计划里看看，学会把那些蔬菜做成看不见的泥，藏进美味的酱汁里，悄悄赢下这场游戏吧。' WHERE id = '7b148d61-8829-4863-ab9e-6d4a0bb51f81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las historias inventadas de papá 📖', body_es = 'Esta noche la voz de la habitación no es la tuya. Dale el libro de cuentos a papá y deja que cuente la historia a propósito al revés, de forma cómica y absurda. Mira desde fuera cómo disfruta el peque corrigiéndole y cómo se ríe a carcajadas con su padre.', title_fr = 'Les histoires inventées de papa 📖', body_fr = 'Ce soir, ce n''est pas votre voix qu''on entendra dans la chambre. Donnez le livre de contes à papa et laissez-le raconter l''histoire à l''envers, exprès, de façon comique et absurde. Regardez de loin le plaisir de l''enfant à le corriger et ses éclats de rire.', title_hi = 'पापा की गढ़ी कहानियाँ 📖', body_hi = 'आज शाम कमरे में आवाज़ आपकी नहीं होगी। कहानी की किताब पापा को दीजिए और उन्हें कहानी जानबूझकर उलटी, मज़ेदार और बेतुकी तरह सुनाने दीजिए। दूर से देखिए कि बच्चा उन्हें सुधारने में कितना मज़ा लेता है और पापा पर कैसे ठहाके लगाता है।', title_id = 'Cerita karangan Ayah 📖', body_id = 'Malam ini suara di kamar bukan milik Anda. Serahkan buku dongeng kepada Ayah dan biarkan ia sengaja menceritakan kisahnya terbalik, lucu, dan absurd. Saksikan dari samping betapa anak senang membetulkannya dan tertawa terbahak-bahak pada ayahnya.', title_ja = 'パパの作り話 📖', body_ja = '今夜の部屋の主役は、あなたの声ではありません。絵本をパパに渡して、お話をわざとあべこべに、おもしろおかしく話してもらいましょう。子どもがそれを直すのを楽しんで、パパに大笑いする姿をそばで眺めて。', title_ko = '아빠의 지어낸 이야기 📖', body_ko = '오늘 저녁 방 안의 목소리는 엄마 몫이 아니에요. 동화책을 아빠에게 건네고 일부러 거꾸로, 웃기고 엉뚱하게 이야기하게 하세요. 아이가 아빠를 고쳐 주며 얼마나 즐거워하고 깔깔 웃는지 옆에서 지켜보세요.', title_nl = 'Papa''s verzonnen verhalen 📖', body_nl = 'Vanavond is de stem in de kamer niet die van jou. Geef het sprookjesboek aan papa en laat hem het verhaal expres achterstevoren, grappig en absurd vertellen. Kijk van een afstand hoe je kind geniet van het verbeteren en hoe hij om zijn papa schatert.', title_pl = 'Wymyślone historie taty 📖', body_pl = 'Dziś wieczorem w pokoju nie słychać twojego głosu. Daj tacie książkę z bajkami i niech celowo opowie historię na opak, zabawnie i absurdalnie. Obserwuj z boku, z jaką przyjemnością dziecko go poprawia i jak zaśmiewa się z taty.', title_pt = 'As histórias inventadas do pai 📖', body_pt = 'Esta noite a voz no quarto não é a sua. Dê o livro de histórias ao pai e deixe-o contar a história ao contrário de propósito, de forma cómica e absurda. Observe à distância como a criança adora corrigi-lo e se ri às gargalhadas com o pai.', title_sv = 'Pappas påhittade historier 📖', body_sv = 'I kväll är det inte din röst som hörs i rummet. Ge sagoboken till pappa och låt honom berätta historien medvetet bakvänt, roligt och absurt. Titta från sidan på hur barnet njuter av att rätta honom och skrattar åt pappa.', title_vi = 'Những câu chuyện tự chế của bố 📖', body_vi = 'Tối nay giọng nói trong phòng không phải của mẹ. Hãy đưa cuốn truyện cho bố và để bố cố tình kể ngược, hài hước và ngớ ngẩn. Ngắm nhìn từ xa bé thích thú sửa lời bố và cười ngặt nghẽo thế nào.', title_zh = '爸爸编的故事 📖', body_zh = '今晚房间里的声音不属于你。把故事书交给爸爸，让他故意把故事讲反、讲得搞笑又荒诞。在一旁看看宝宝多么享受纠正爸爸，又是怎样对着爸爸哈哈大笑的。' WHERE id = 'b42730c5-7949-4ebf-93b6-63b027cfa615' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vuelca tu rabia en el Diario de ánimo 📝', body_es = '¿Nadie ve lo cansada que estás en casa? El Diario de ánimo es tu confidente más silencioso. Escribe ahí todos los detalles que hoy te han sacado de quicio y mira en la pantalla cómo se aligera tu mente y cómo se van volando las penas.', title_fr = 'Déverser sa colère dans le Journal d''humeur 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison ? Le Journal d''humeur est votre confident le plus discret. Écrivez-y tous les détails qui vous ont rendue folle aujourd''hui et voyez à l''écran votre esprit s''alléger et vos soucis s''envoler.', title_hi = 'मूड डायरी में गुस्सा उतारना 📝', body_hi = 'किसी को नहीं दिखता कि आप घर में कितना थकती हैं? मूड डायरी आपकी सबसे खामोश राज़दार है। आज जिन बातों ने आपको पागल किया, सब वहाँ लिखिए और स्क्रीन देखते हुए महसूस कीजिए कि दिमाग कैसे हल्का होता है और परेशानियाँ कैसे उड़ जाती हैं।', title_id = 'Tumpahkan amarah ke Buku Harian Suasana Hati 📝', body_id = 'Tak ada yang melihat betapa lelahnya Anda di rumah? Buku Harian Suasana Hati adalah teman curhat Anda yang paling diam. Tuliskan di sana semua detail yang membuat Anda gila hari ini, lalu lihat di layar betapa ringannya pikiran Anda dan bagaimana beban itu terbang pergi.', title_ja = '「気分日記」に怒りをはき出そう 📝', body_ja = '家であなたがどれほど疲れているか、誰も気づいてくれない？「気分日記」は、いちばん静かな打ち明け相手です。今日あなたをいらだたせたことを全部書いて、頭がどれほど軽くなり、悩みがどれほど飛んでいくかを画面で確かめて。', title_ko = '기분 일기에 화 쏟아내기 📝', body_ko = '집에서 얼마나 지쳤는지 아무도 몰라주나요? 기분 일기는 가장 조용한 비밀 친구예요. 오늘 나를 미치게 한 모든 일을 적고, 화면을 보며 머리가 가벼워지고 걱정이 날아가는 걸 느껴 보세요.', title_nl = 'Boosheid kwijt in je Stemmingsdagboek 📝', body_nl = 'Ziet niemand hoe moe je thuis bent? Je Stemmingsdagboek is je stilste vertrouweling. Schrijf daar alle details op die je vandaag gek maakten en zie op het scherm hoe je hoofd lichter wordt en je zorgen wegvliegen.', title_pl = 'Wylej złość w Dzienniku nastroju 📝', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu? Dziennik nastroju to twój najcichszy powiernik. Zapisz w nim wszystkie szczegóły, które dziś doprowadziły cię do szału, i zobacz na ekranie, jak lżej robi się w głowie, a zmartwienia odlatują.', title_pt = 'Despejar a raiva no Diário de Humor 📝', body_pt = 'Ninguém vê o quanto se cansa em casa? O Diário de Humor é o seu confidente mais silencioso. Escreva lá todos os pormenores que hoje a deixaram louca e veja no ecrã como o seu cérebro fica mais leve e as mágoas desaparecem.', title_sv = 'Häll ut ilskan i Humördagboken 📝', body_sv = 'Ser ingen hur trött du är hemma? Humördagboken är din tystaste förtrogna. Skriv ner alla detaljer som gjorde dig galen i dag och se på skärmen hur hjärnan blir lättare och bekymren flyger iväg.', title_vi = 'Trút giận vào Nhật ký tâm trạng 📝', body_vi = 'Không ai thấy mẹ mệt mỏi thế nào khi ở nhà? Nhật ký tâm trạng là người bạn tâm giao lặng lẽ nhất của mẹ. Hãy viết vào đó mọi chi tiết khiến mẹ phát điên hôm nay và nhìn màn hình để thấy đầu óc nhẹ nhõm hơn, nỗi buồn bay đi thế nào.', title_zh = '把火气倒进心情日记 📝', body_zh = '没人看见你在家有多累？心情日记是你最安静的知心朋友。把今天让你抓狂的所有细节都写进去，看着屏幕，感受大脑如何变得轻松，烦恼如何飞走。' WHERE id = '4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Con gorro dentro de casa 🧢', body_es = 'Quiere llevar el gorro de invierno dentro de casa. Insiste y no se lo quita. Olvida las normas sociales. Para no romper su creatividad ni su libertad de decidir, deja que pase el día con ese aspecto tan distinto y cómico: si la temperatura de la habitación es normal, que lo lleve.', title_fr = 'Un bonnet dans la maison 🧢', body_fr = 'Il veut porter son bonnet d''hiver dans la maison. Il insiste et refuse de l''enlever. Oubliez les normes sociales. Pour ne pas briser sa créativité et sa liberté de décider, laissez-le passer la journée avec ce look original et comique : si la température de la pièce est normale, laissez-le faire.', title_hi = 'घर में टोपी पहनकर घूमना 🧢', body_hi = 'सर्दियों की टोपी घर में पहनना चाहता है। ज़िद करता है, उतारता नहीं। लोगों के कायदे भूल जाइए। उसकी रचनात्मकता और फ़ैसले की आज़ादी न टूटे, इसलिए उसे आज का दिन इसी अनोखे, मज़ेदार रूप में बिताने दीजिए; अगर कमरे का तापमान सामान्य है, तो घूमने दीजिए।', title_id = 'Memakai topi di dalam rumah 🧢', body_id = 'Ia ingin memakai topi musim dingin di dalam rumah. Ia ngotot dan tidak mau melepasnya. Lupakan norma sosial. Agar kreativitas dan kebebasannya memutuskan tidak patah, biarkan ia melewati hari dengan penampilan unik dan lucu itu, asalkan suhu ruangan normal.', title_ja = '家の中で帽子 🧢', body_ja = '冬の帽子を家の中でかぶりたがり、ゆずらず、はずさない。世間の常識は忘れましょう。創造力と自分で決める自由をくじかないように、そのちょっと変わったおもしろい格好で一日を過ごさせてあげて。部屋の温度がふつうなら、そのままで大丈夫です。', title_ko = '집 안에서 모자 쓰기 🧢', body_ko = '집 안에서 겨울 모자를 쓰겠다며 절대 벗지 않나요? 사회적 기준은 잊으세요. 창의력과 선택의 자유를 꺾지 않도록 그 독특하고 웃긴 모습으로 하루를 보내게 해 주세요. 방 온도가 적당하다면 그냥 두세요.', title_nl = 'Met een muts door het huis 🧢', body_nl = 'Hij wil zijn wintermuts in huis op. Hij houdt vol en zet hem niet af. Vergeet wat ''hoort''. Laat hem de dag in die aparte, grappige look doorbrengen, zodat je zijn creativiteit en keuzevrijheid niet breekt. Is de temperatuur in huis normaal, laat hem dan zo rondlopen.', title_pl = 'W czapce po domu 🧢', body_pl = 'Chce nosić zimową czapkę w domu. Upiera się, nie zdejmuje. Zapomnij o normach społecznych. Żeby nie łamać jego kreatywności i swobody decydowania, niech spędzi dzień w tym nietypowym, zabawnym wydaniu. Jeśli w pokoju jest normalna temperatura, niech chodzi.', title_pt = 'De gorro dentro de casa 🧢', body_pt = 'Quer usar o gorro de inverno dentro de casa. Insiste e não o tira. Esqueça as normas sociais. Para não quebrar a criatividade e a liberdade de decidir, deixe-o passar o dia com esse visual diferente e cómico: se a temperatura do quarto for normal, deixe-o andar assim.', title_sv = 'Mössa på inomhus 🧢', body_sv = 'Barnet vill ha vintermössan på sig inne. Barnet insisterar och tar inte av den. Glöm samhällets normer. För att inte knäcka barnets kreativitet och frihet att bestämma, låt barnet tillbringa dagen i den annorlunda, roliga looken; om temperaturen i rummet är normal, låt barnet gå så.', title_vi = 'Đội mũ đi lại trong nhà 🧢', body_vi = 'Bé muốn đội mũ len mùa đông trong nhà. Bé nhất quyết không bỏ ra. Hãy quên chuẩn mực xã hội đi. Để không bẻ gãy sự sáng tạo và quyền tự quyết của bé, cứ để bé trải qua ngày với vẻ ngoài khác lạ, hài hước ấy, nếu nhiệt độ trong phòng bình thường thì cứ để bé đội.', title_zh = '在家里戴帽子 🧢', body_zh = '想在家里戴着冬天的帽子。坚持不肯摘。忘掉那些社会规范吧。为了不挫伤宝宝的创造力和自己做决定的自由，就让宝宝带着这副与众不同又搞笑的样子过一天吧，只要房间温度正常，就随宝宝去。' WHERE id = '5c983784-bca8-4998-adca-b16664e5be99' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El golpe del «¡No me escuchas!» 😠', body_es = 'Mientras miras el móvil o remueves la comida, viene y te gira la cara hacia él: «¡Mírame!». Tiene razón. No quiere tu presencia física, sino tu atención completa. Deja lo que estés haciendo y escúchale solo 3 minutos con contacto visual pleno.', title_fr = 'L''attaque du « Tu m''écoutes pas ! » 😠', body_fr = 'Pendant que vous regardez votre téléphone ou remuez le repas, il vient tourner votre visage vers lui : « Regarde-moi ! » Il a raison. Il ne veut pas votre présence physique, mais toute votre attention. Arrêtez ce que vous faites et écoutez-le juste 3 minutes en le regardant vraiment dans les yeux.', title_hi = '‘तुम मेरी नहीं सुनतीं!’ वाला वार 😠', body_hi = 'आप फ़ोन देख रही हैं या खाना चला रही हैं, और वह आकर आपका चेहरा अपनी ओर घुमाता है: ‘मुझे देखो!’ वह सही है। उसे आपकी मौजूदगी नहीं, आपका पूरा ध्यान चाहिए। काम रोकिए और सिर्फ़ 3 मिनट पूरी तरह आँख मिलाकर उसे सुनिए।', title_id = 'Ledakan ''Mama nggak dengar aku!'' 😠', body_id = 'Saat Anda melihat ponsel atau mengaduk masakan, ia datang dan memalingkan wajah Anda ke arahnya: ''Lihat aku!''. Ia benar. Ia tidak menginginkan kehadiran fisik Anda, melainkan perhatian Anda yang utuh. Hentikan pekerjaan dan dengarkan ia hanya 3 menit dengan kontak mata penuh.', title_ja = '「聞いてないでしょ！」の一撃 😠', body_ja = 'スマホを見たり料理をまぜたりしていると、やってきてあなたの顔を自分のほうへ向けます：「こっち見て！」その通りです。そばにいることではなく、まるごとの注目がほしいんです。手を止めて、3分だけしっかり目を合わせて聞いてあげましょう。', title_ko = '''엄마 내 말 안 듣잖아!'' 폭발 😠', body_ko = '엄마가 휴대폰을 보거나 음식을 저을 때 와서 얼굴을 자기 쪽으로 돌리며 ''나 봐!''라고 하나요? 아이가 옳아요. 몸만 곁에 있는 엄마가 아니라 온전한 관심을 원하는 거예요. 하던 일을 멈추고 딱 3분만 눈을 맞추며 들어 주세요.', title_nl = 'De ''Je luistert niet naar me!''-uitval 😠', body_nl = 'Terwijl jij op je telefoon kijkt of in een pan roert, komt hij je gezicht naar zich toe draaien: ''Kijk naar mij!'' Hij heeft gelijk. Hij wil niet alleen dat je er bent, hij wil je onverdeelde aandacht. Stop met wat je doet en luister 3 minuten naar hem met volledig oogcontact.', title_pl = 'Cios „Nie słuchasz mnie!” 😠', body_pl = 'Gdy patrzysz w telefon albo mieszasz w garnku, podchodzi i odwraca twoją twarz do siebie: „Patrz na mnie!”. Ma rację. Nie chce twojej fizycznej obecności, tylko niepodzielnej uwagi. Przerwij to, co robisz, i choć przez 3 minuty słuchaj go z pełnym kontaktem wzrokowym.', title_pt = 'O golpe do "Não me estás a ouvir!" 😠', body_pt = 'Enquanto olha para o telemóvel ou mexe a comida, ele vem e vira-lhe a cara para ele: "Olha para mim!". Tem razão. Não quer a sua presença física, quer a sua atenção total. Pare o que está a fazer e ouça-o só 3 minutos, com contacto visual total.', title_sv = 'Smällen ”Du hör inte vad jag säger!” 😠', body_sv = 'Medan du tittar på telefonen eller rör i grytan kommer barnet och vänder ditt ansikte mot sig: ”Titta på mig!” Barnet har rätt. Det vill inte ha din fysiska närvaro, utan din odelade uppmärksamhet. Avbryt det du gör och lyssna på barnet med full ögonkontakt i bara 3 minuter.', title_vi = 'Cú "Mẹ không nghe con nói!" 😠', body_vi = 'Khi mẹ nhìn điện thoại hay đang khuấy nồi, bé đến xoay mặt mẹ về phía mình: "Mẹ nhìn con này!". Bé có lý đấy. Bé không cần sự hiện diện của mẹ, mà cần sự chú ý trọn vẹn. Hãy dừng việc đang làm và chỉ cần 3 phút nhìn vào mắt bé để lắng nghe.', title_zh = '“你都不听我说！”的一击 😠', body_zh = '你看手机或搅着锅时，宝宝跑过来把你的脸转向自己：“看我！”宝宝说得对。宝宝要的不是你人在这里，而是你全心全意的关注。停下手里的事，只要3分钟，和宝宝对视，认真听宝宝说。' WHERE id = '9d6dd60c-7863-4418-b9e4-e9cffd903339' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de hacer amigos en el parque 🤝', body_es = 'En el parque se acerca a un niño que no conoce y se presenta: «Me llamo...». Sus habilidades sociales se forman a una velocidad asombrosa. Guarda estos valientes intentos de comunicarse en el Seguimiento del desarrollo como un registro del que estar orgullosa en el desarrollo de su personalidad.', title_fr = 'Premières rencontres au parc 🤝', body_fr = 'Au parc, il va vers un enfant qu''il ne connaît pas et se présente : « Je m''appelle... » Ses compétences sociales se forment à une vitesse étonnante. Gardez ces tentatives de communication courageuses dans le Suivi de développement comme une étape dont être fière.', title_hi = 'पार्क में जान-पहचान की कोशिशें 🤝', body_hi = 'पार्क में किसी अनजान बच्चे के पास जाकर ‘मेरा नाम...’ कहकर अपना परिचय देता है। सामाजिक कौशल गज़ब की रफ़्तार से बन रहे हैं। ग्रोथ ट्रैकर में बातचीत की उसकी इन हिम्मत भरी कोशिशों को व्यक्तित्व के विकास के गर्व भरे रिकॉर्ड की तरह सँजोइए।', title_id = 'Mencoba berkenalan di taman 🤝', body_id = 'Di taman ia mendekati anak yang tidak ia kenal dan memperkenalkan diri: ''Namaku...''. Kemampuan sosialnya terbentuk dengan kecepatan menakjubkan. Simpan usaha komunikasi beraninya ini di Pelacak Perkembangan sebagai catatan membanggakan perkembangan kepribadiannya.', title_ja = '公園で友だちづくりのチャレンジ 🤝', body_ja = '公園で知らない子のところへ行って「ぼくの名前は…」と自己紹介している。社会性がおどろくほどの速さで育っています。この勇気あるコミュニケーションのチャレンジを、人格の成長の誇らしい記録として「発達トラッカー」に残しましょう。', title_ko = '공원에서 친구 사귀기 🤝', body_ko = '공원에서 처음 보는 아이에게 다가가 ''내 이름은...'' 하며 자기소개를 하나요? 사회성이 놀라운 속도로 자라고 있어요. 이 용감한 소통 시도를 인격 발달의 뿌듯한 기록으로 성장 기록에 남겨 두세요.', title_nl = 'Kennismaken in het park 🤝', body_nl = 'In het park loopt hij naar een onbekend kind en stelt zich voor: ''Ik heet...'' Zijn sociale vaardigheden ontwikkelen zich verbazingwekkend snel. Bewaar deze dappere communicatiepogingen in de Groeitracker als trotse mijlpaal in zijn persoonlijkheidsontwikkeling.', title_pl = 'Próby zawierania znajomości w parku 🤝', body_pl = 'W parku podchodzi do nieznajomego dziecka i przedstawia się: „Mam na imię...”. Umiejętności społeczne kształtują się w zdumiewającym tempie. Zachowaj w Śledzeniu rozwoju te odważne próby komunikacji jako powód do dumy w rozwoju jego osobowości.', title_pt = 'Tentativas de fazer amigos no parque 🤝', body_pt = 'No parque, vai ter com uma criança que não conhece e apresenta-se: "Eu chamo-me...". As capacidades sociais estão a formar-se a uma velocidade impressionante. Guarde no Registo de Crescimento estas tentativas corajosas de comunicação, como um registo de orgulho do desenvolvimento da personalidade.', title_sv = 'Försök att få nya vänner i parken 🤝', body_sv = 'I parken går barnet fram till ett okänt barn och presenterar sig: ”Jag heter...” De sociala färdigheterna formas otroligt snabbt. Spara barnets modiga kommunikationsförsök i Utvecklingsspåraren som en stolt anteckning om personlighetsutvecklingen.', title_vi = 'Làm quen ở công viên 🤝', body_vi = 'Ở công viên, bé đến gần một bạn lạ và tự giới thiệu: "Tên mình là...". Kỹ năng xã hội đang hình thành với tốc độ đáng kinh ngạc. Hãy lưu lại những nỗ lực giao tiếp dũng cảm này trong Theo dõi phát triển như một dấu mốc đáng tự hào về nhân cách của bé.', title_zh = '在公园里交朋友 🤝', body_zh = '在公园走到不认识的小朋友身边，自我介绍：“我叫……”社交能力正以惊人的速度形成。把宝宝这些勇敢的沟通尝试，作为人格发展中值得骄傲的记录保存在发育追踪里吧。' WHERE id = '45e62ed0-8906-4bfa-998b-97725faac7dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «No» tozudo 🛑', body_es = '«¿Quieres agua?» «¡No!». Pero 5 segundos después llora por el agua. Es la etapa de comprobar las consecuencias de sus decisiones. Dicen que no incluso a lo que en realidad quieren. Deja el agua en la mesa sin obligarle: cuando termine su lucha interior, se la beberá.', title_fr = 'La période du « Non » têtu 🛑', body_fr = '« Tu veux de l''eau ? » « Non ! » Mais 5 secondes plus tard, il pleure pour avoir de l''eau. C''est la période où il teste les conséquences de ses décisions. Il dit non même à ce qu''il veut vraiment. Posez l''eau sur la table, ne le forcez pas : il finira son débat intérieur et boira.', title_hi = 'ज़िद्दी ‘ना’ का दौर 🛑', body_hi = '‘पानी चाहिए?’ ‘ना!’ पर 5 सेकंड बाद पानी के लिए रोता है। यह फ़ैसलों के नतीजे परखने का दौर है। जो चीज़ें उन्हें असल में चाहिए, उन्हें भी ‘ना’ कहते हैं। पानी मेज़ पर रख दीजिए, ज़बरदस्ती मत कीजिए, वह अपनी अंदरूनी लड़ाई खत्म करके पी लेगा।', title_id = 'Masa ''Tidak'' yang keras kepala 🛑', body_id = '''Mau minum?'' ''Tidak!'' Tapi 5 detik kemudian ia menangis minta air. Ini masa menguji akibat dari keputusannya. Mereka bahkan berkata tidak pada hal yang sebenarnya mereka inginkan. Letakkan airnya di meja, jangan memaksa, ia akan meminumnya setelah pergulatan batinnya selesai.', title_ja = 'がんこな「いや」の時期 🛑', body_ja = '「お水ほしい？」「いや！」でも5秒後には、お水がほしくて泣いている。これは、自分の決めたことの結果を試す時期です。本当はほしいものにも「いや」と言ってしまうんです。お水をテーブルに置いて、無理強いしないで。心の中の戦いが終われば、自分で飲みますよ。', title_ko = '고집스러운 ''싫어'' 시기 🛑', body_ko = '''물 줄까?'' ''싫어!'' 그런데 5초 뒤 물 달라고 우나요? 자기 결정의 결과를 시험하는 시기예요. 사실 원하는 것에도 ''싫어''라고 해요. 물을 식탁에 놓아두고 강요하지 마세요, 마음속 싸움이 끝나면 마실 거예요.', title_nl = 'De koppige nee-fase 🛑', body_nl = '''Wil je water?'' ''Nee!'' Maar 5 seconden later huilt hij om water. Dit is de fase waarin hij de gevolgen van zijn beslissingen test. Ze zeggen zelfs nee tegen dingen die ze eigenlijk willen. Zet het water op tafel en dwing hem niet, als zijn innerlijke strijd voorbij is, drinkt hij het wel.', title_pl = 'Uparty etap „Nie” 🛑', body_pl = '„Chcesz wody?” „Nie!” A 5 sekund później płacze o wodę. To etap sprawdzania skutków własnych decyzji. Mówią „nie” nawet temu, czego naprawdę chcą. Postaw wodę na stole i nie zmuszaj, skończy swoją wewnętrzną walkę i się napije.', title_pt = 'A fase teimosa do "Não" 🛑', body_pt = '"Queres água?" "Não!" Mas 5 segundos depois chora por água. É a fase de testar as consequências das decisões. Dizem "não" até ao que, na verdade, querem. Ponha a água na mesa e não insista: ele acaba a luta interior e bebe.', title_sv = 'Den envisa ”Nej”-perioden 🛑', body_sv = '”Vill du ha vatten?” ”Nej!” Men 5 sekunder senare gråter barnet efter vatten. Det är en period då barnet testar följderna av sina beslut. De säger nej även till det de egentligen vill ha. Ställ vattnet på bordet, tvinga inte, barnet avslutar sin inre kamp och dricker.', title_vi = 'Giai đoạn "Không!" bướng bỉnh 🛑', body_vi = '"Con muốn uống nước không?" - "Không!". Nhưng 5 giây sau bé lại khóc đòi nước. Đây là giai đoạn thử nghiệm hệ quả của các quyết định. Bé nói "không" cả với những thứ thật ra mình muốn. Hãy đặt cốc nước lên bàn, đừng ép, bé sẽ tự kết thúc "cuộc đấu tranh nội tâm" và uống.', title_zh = '倔强的“不要”期 🛑', body_zh = '“要喝水吗？”“不要！”可5秒后又为了水哭起来。这是测试决定后果的阶段。他们连自己其实想要的东西也会说不要。把水放在桌上，别强迫，等宝宝结束内心的“斗争”，自己就会喝了。' WHERE id = '6538fe5a-5021-49de-8c05-b4294e3a7259' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir fácil con Cuentos inteligentes 🪄', body_es = 'Te sabes de memoria los libros de siempre. Abre Cuentos inteligentes, diseña una historia con tu peque como protagonista y su habitación como el lugar por conquistar, crea una sesión de sueño sonora y original que no exige ningún esfuerzo y descansa tú también.', title_fr = 'S''endormir facilement avec les Contes intelligents 🪄', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents : faites de votre enfant le héros et de sa chambre le territoire à conquérir, créez une séance d''endormissement sonore originale qui ne demande aucun effort, et reposez-vous aussi.', title_hi = 'स्मार्ट कहानियों से आसान नींद 🪄', body_hi = 'पुरानी किताबें आपको रट चुकी हैं। स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाकर एक अनोखा, बिना मेहनत वाला आवाज़ों भरा नींद का सत्र बनाइए, और आप भी आराम कीजिए।', title_id = 'Tidur mudah dengan Dongeng Pintar 🪄', body_id = 'Anda sudah hafal buku-buku klasik. Buka Dongeng Pintar, jadikan anak Anda tokoh utamanya dan kamarnya sendiri sebagai tempat yang akan ditaklukkan, ciptakan sesi tidur bersuara yang tidak biasa tanpa usaha apa pun, dan Anda pun beristirahat.', title_ja = 'スマートおはなしで楽に寝かしつけ 🪄', body_ja = '定番の絵本はもう暗記してしまいましたね。「スマートおはなし」を開いて、主人公はお子さん、征服する場所はこの子の部屋にして、いつもとちがう、まったく手間のかからない音声の寝かしつけタイムをつくり、あなたも休みましょう。', title_ko = '스마트 동화로 쉽게 잠들기 🪄', body_ko = '늘 읽던 책은 다 외웠나요? 스마트 동화를 열고 주인공은 아이로, 정복할 장소는 아이의 방으로 정해 특별하고 힘들이지 않는 소리 잠자리 시간을 만들고, 엄마도 쉬세요.', title_nl = 'Makkelijk slapen met Slimme sprookjes 🪄', body_nl = 'Je kent de klassieke boeken uit je hoofd. Open Slimme sprookjes, maak je kind de hoofdpersoon en zijn kamer het land dat veroverd moet worden, creëer een bijzondere luistersessie om in slaap te vallen die je geen moeite kost, en rust zelf ook uit.', title_pl = 'Łatwe zasypianie z Mądrymi bajkami 🪄', body_pl = 'Klasyczne książeczki znasz już na pamięć. Otwórz Mądre bajki, uczyń głównym bohaterem swoje dziecko, a krainą do podbicia jego pokój, stwórz niezwykły dźwiękowy seans usypiania, który nie wymaga żadnego wysiłku, i sama też odpocznij.', title_pt = 'Adormecer facilmente com as Histórias Inteligentes 🪄', body_pt = 'Já sabe os livros clássicos de cor. Abra as Histórias Inteligentes, crie uma história com o seu filho como herói principal e o quarto dele como terra a conquistar, prepare uma sessão de sono sonora fora do comum, sem esforço nenhum, e descanse também.', title_sv = 'Lätt sömn med Smarta sagor 🪄', body_sv = 'Du kan de klassiska böckerna utantill. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska erövras, skapa en ovanlig ljudsovstund som inte kräver någon ansträngning och vila du också.', title_vi = 'Dễ ngủ cùng Truyện cổ tích thông minh 🪄', body_vi = 'Mẹ đã thuộc lòng những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh, thiết kế một buổi ru ngủ bằng âm thanh khác lạ, chẳng tốn chút công sức: bé là nhân vật chính, còn vùng đất cần chinh phục chính là căn phòng của bé, và mẹ cũng được nghỉ ngơi.', title_zh = '用智慧童话轻松入睡 🪄', body_zh = '经典故事书你都背熟了。打开智慧童话，把宝宝设计成主角，把要征服的地方设定为宝宝的房间，打造一场不寻常、毫不费力的有声哄睡时光，你自己也休息一下。' WHERE id = 'c5259254-085d-4cab-81d7-de92adaaa126' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Teatro de sombras en la habitación oscura 🐰', body_es = 'Con la excusa de que le da miedo la oscuridad, se escapa de la cama. Apaga todas las luces de la habitación, enciende una linterna y haz con las manos sombras de pájaros y perros en la pared. La oscuridad que le asusta se convertirá en segundos en un teatro.', title_fr = 'Théâtre d''ombres dans la chambre noire 🐰', body_fr = 'Il prétexte avoir peur du noir pour s''échapper du lit. Éteignez toutes les lumières de la chambre, allumez une lampe de poche et créez avec vos mains des ombres d''oiseau et de chien sur le mur. En quelques secondes, le noir qui lui faisait peur deviendra un théâtre.', title_hi = 'अँधेरे कमरे में परछाइयों का थिएटर 🐰', body_hi = 'अँधेरे से डर का बहाना बनाकर बिस्तर से भागता है। कमरे की सारी लाइटें बंद कीजिए, टॉर्च जलाइए और दीवार पर हाथों से चिड़िया, कुत्ते की परछाइयाँ बनाइए। जिस अँधेरे से वह डरता है, वह सेकंडों में उसके लिए थिएटर बन जाएगा।', title_id = 'Teater bayangan di kamar gelap 🐰', body_id = 'Ia menjadikan takut gelap sebagai alasan untuk kabur dari tempat tidur. Matikan semua lampu kamar, nyalakan senter, dan buat bayangan burung dan anjing di dinding dengan tangan Anda. Dalam hitungan detik, gelap yang ia takuti akan berubah menjadi teater.', title_ja = '暗い部屋で影絵劇場 🐰', body_ja = '暗いのが怖いと言いわけしてベッドから逃げだす。部屋の明かりを全部消して懐中電灯をつけ、壁に手で鳥や犬の影絵をつくりましょう。怖がっていた暗やみが、あっという間に劇場に変わります。', title_ko = '어두운 방의 그림자 극장 🐰', body_ko = '어둠이 무섭다는 핑계로 침대에서 도망치나요? 방의 불을 모두 끄고 손전등을 켜서 손으로 벽에 새와 강아지 그림자를 만들어 보세요. 무서웠던 어둠이 몇 초 만에 극장으로 바뀔 거예요.', title_nl = 'Schaduwtheater in een donkere kamer 🐰', body_nl = 'Hij gebruikt zijn angst voor het donker als smoes om uit bed te gaan. Doe alle lichten in de kamer uit, zet een zaklamp aan en maak met je handen schaduwen van vogels en honden op de muur. Het donker waar hij bang voor was, wordt binnen een paar seconden een theater.', title_pl = 'Teatr cieni w ciemnym pokoju 🐰', body_pl = 'Wymawia się strachem przed ciemnością i ucieka z łóżka. Zgaś wszystkie światła w pokoju, włącz latarkę i zrób dłońmi na ścianie cienie ptaka i pieska. Ciemność, której się bał, w kilka sekund zmieni się dla niego w teatr.', title_pt = 'Teatro de sombras no quarto escuro 🐰', body_pt = 'Usa o medo do escuro como desculpa para fugir da cama. Apague todas as luzes do quarto, acenda a lanterna e faça com as mãos sombras de pássaros e cães na parede. Em segundos, o escuro de que tem medo vai transformar-se num teatro.', title_sv = 'Skuggteater i ett mörkt rum 🐰', body_sv = 'Barnet skyller på att det är mörkrädd och springer ur sängen. Släck alla lampor i rummet, tänd ficklampan och forma fåglar och hundar som skuggor på väggen med händerna. Mörkret som barnet är rädd för blir på några sekunder en teater.', title_vi = 'Kịch bóng trong phòng tối 🐰', body_vi = 'Bé lấy cớ sợ bóng tối để trốn khỏi giường. Hãy tắt hết đèn trong phòng, bật đèn pin và dùng tay tạo bóng chim, bóng chó trên tường. Bóng tối bé sợ sẽ biến thành nhà hát chỉ trong vài giây.', title_zh = '黑暗房间里的影子戏 🐰', body_zh = '拿怕黑当借口从床上溜走。关掉房间所有的灯，打开手电筒，用手在墙上做出小鸟、小狗的影子。宝宝害怕的黑暗，几秒钟就会变成一座剧场。' WHERE id = '3267eb25-4eba-48a9-b86e-272c45f62299' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Proteger la calma con el Medidor de sonido 🤫', body_es = 'El ruido de casa te hace pitar los oídos. Cuando por fin se duerma, activa el Medidor de sonido. Mirar esos números cercanos a cero de la pantalla, ese silencio digital, es el mejor masaje visual para el cerebro de una madre cansada.', title_fr = 'Préserver le calme avec le Sonomètre 🤫', body_fr = 'Le bruit de la maison vous fait bourdonner les oreilles. Quand il s''endort enfin, activez le Sonomètre. Regarder ces chiffres proches de zéro à l''écran, ce silence numérique, c''est le plus beau massage visuel pour le cerveau d''une maman fatiguée.', title_hi = 'साउंड मीटर से शांति की रक्षा 🤫', body_hi = 'घर के शोर से कान झनझना रहे हैं। जब वह आखिरकार सो जाए, तो साउंड मीटर टूल चालू कीजिए। स्क्रीन पर शून्य के करीब के अंक, वह डिजिटल खामोशी देखना थकी माँ के दिमाग के लिए सबसे प्यारी विज़ुअल मसाज है।', title_id = 'Menjaga hening dengan Pengukur Suara 🤫', body_id = 'Kebisingan di rumah membuat telinga Anda berdenging. Saat akhirnya ia tertidur, aktifkan Pengukur Suara. Melihat angka mendekati nol di layar, keheningan digital itu, adalah pijatan visual terindah untuk otak ibu yang lelah.', title_ja = 'サウンドメーターで静けさを守ろう 🤫', body_ja = '家の中の騒がしさで耳鳴りがしそう。やっと寝てくれたら、「サウンドメーター」をオンにしましょう。画面のゼロに近い数字、デジタルな静けさを眺めることが、疲れたママの脳にはいちばんの視覚マッサージになります。', title_ko = '소음 측정기로 고요 지키기 🤫', body_ko = '집 안의 소음에 귀가 울리나요? 아이가 드디어 잠들면 소음 측정기를 켜 보세요. 화면 속 0에 가까운 숫자, 그 디지털 고요를 보는 것이 지친 엄마의 머리에 가장 좋은 시각 마사지예요.', title_nl = 'Rust bewaken met de Geluidsmeter 🤫', body_nl = 'Het lawaai in huis laat je oren suizen. Zet de Geluidsmeter aan als hij eindelijk slaapt. Kijken naar die getallen bij nul op het scherm, die digitale stilte, is de fijnste visuele massage voor het brein van een vermoeide mama.', title_pl = 'Ochrona ciszy z Miernikiem dźwięku 🤫', body_pl = 'Hałas w domu dzwoni ci w uszach. Gdy w końcu zaśnie, włącz Miernik dźwięku. Patrzenie na liczby bliskie zera na ekranie, na tę cyfrową ciszę, to najpiękniejszy wizualny masaż dla mózgu zmęczonej mamy.', title_pt = 'Proteger o sossego com o Medidor de Som 🤫', body_pt = 'O barulho da casa faz-lhe zumbir os ouvidos. Quando ele finalmente adormecer, ative o Medidor de Som. Ver os números perto de zero no ecrã, o silêncio digital, é a melhor massagem visual para o cérebro de uma mãe cansada.', title_sv = 'Skydda lugnet med Ljudmätaren 🤫', body_sv = 'Oljudet hemma får det att ringa i öronen. När barnet äntligen har somnat, aktivera verktyget Ljudmätare. Att se siffrorna nära noll på skärmen, den digitala tystnaden, är den skönaste visuella massagen för en trött mammas hjärna.', title_vi = 'Giữ yên tĩnh với Đo âm thanh 🤫', body_vi = 'Tiếng ồn trong nhà làm tai mẹ ù đi. Khi bé cuối cùng cũng ngủ, hãy bật Đo âm thanh. Nhìn những con số gần về không trên màn hình, sự im lặng hiện ra bằng con số ấy chính là màn mát-xa thị giác tuyệt vời nhất cho não bộ của người mẹ mệt mỏi.', title_zh = '用分贝仪守护安静 🤫', body_zh = '家里的噪音让你耳朵嗡嗡作响。宝宝终于睡着后，打开分贝仪。看着屏幕上那些接近零的数字，看着这份数字化的安静，对疲惫的妈妈来说就是最美好的视觉按摩。' WHERE id = '4ac972f2-0058-41fe-9a63-593036a6aa46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La dictadura del «¡Tú no te sientes!» 🪑', body_es = 'Quieres sentarte en el sofá y él corre y dice: «¡Ahí se sienta mi osito, levántate!». Intenta mandar en la casa. Sin romper su voluntad de golpe, mantén el equilibrio y la paz diciendo: «Tu osito aquí y yo me siento a su lado».', title_fr = 'La dictature du « Assieds-toi pas ! » 🪑', body_fr = 'Vous voulez vous asseoir sur le canapé, et il accourt : « C''est la place de mon nounours, lève-toi ! » Il essaie de diriger la maison. Sans briser sa volonté, préservez l''équilibre et la paix : « Ton nounours est là, et moi je m''assieds à côté de lui. »', title_hi = '‘तुम मत बैठो!’ वाली तानाशाही 🪑', body_hi = 'आप सोफ़े पर बैठना चाहती हैं, और वह दौड़कर कहता है, ‘वहाँ मेरा टेडी बैठेगा, तुम उठो!’ वह घर चलाने की कोशिश कर रहा है। उसकी इच्छा को एकदम से तोड़े बिना, ‘तुम्हारा टेडी यहाँ, और मैं उसके पास बैठ जाती हूँ’ कहकर संतुलन और कमरे की शांति बनाए रखिए।', title_id = 'Kediktatoran ''Jangan duduk!'' 🪑', body_id = 'Anda ingin duduk di sofa, tapi ia berlari dan berkata ''Itu tempat beruangku, Mama berdiri!''. Ia sedang mencoba mengatur rumah. Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dan kedamaian dengan berkata ''Beruangnya di sini, Mama duduk di sebelahnya''.', title_ja = '「座っちゃだめ！」の独裁 🪑', body_ja = 'ソファに座ろうとすると、走ってきて「そこはくまさんが座るの、どいて！」と言う。家を仕切ろうとしているんです。意志をばっさり折らずに、「くまさんはここね、ママはそのとなりに座ろうかな」と言って、バランスと部屋の平和を守りましょう。', title_ko = '''엄마 앉지 마!'' 독재 🪑', body_ko = '소파에 앉으려는데 달려와서 ''거기 곰돌이가 앉을 거야, 엄마는 일어나!''라고 하나요? 집을 다스리려는 거예요. 의지를 확 꺾지 말고 ''곰돌이는 여기, 엄마는 그 옆에 앉을게''라며 균형과 평화를 지켜 주세요.', title_nl = 'De ''Daar mag jij niet zitten!''-dictatuur 🪑', body_nl = 'Je wilt op de bank gaan zitten, maar hij rent erheen: ''Daar zit mijn beertje, sta op!'' Hij probeert het huis te besturen. Breek zijn wil niet hard, maar bewaar de balans en de vrede: ''Je beertje zit hier, en ik ga naast hem zitten.''', title_pl = 'Dyktatura „Nie siadaj!” 🪑', body_pl = 'Chcesz usiąść na kanapie, a on przybiega i mówi: „Tu usiądzie mój miś, wstań!”. Próbuje rządzić domem. Nie łamiąc ostro jego woli, zachowaj równowagę i spokój: „Miś usiądzie tutaj, a ja obok niego”.', title_pt = 'A ditadura do "Não te sentes!" 🪑', body_pt = 'Quer sentar-se no sofá e ele corre e diz: "Aí senta-se o meu ursinho, levanta-te!". Está a tentar mandar na casa. Sem quebrar a vontade dele de forma brusca, diga "O ursinho fica aqui e eu sento-me ao lado dele" e mantenha o equilíbrio e a paz.', title_sv = 'Diktaturen ”Du får inte sitta!” 🪑', body_sv = 'Du vill sitta i soffan, men barnet springer fram och säger: ”Där ska min nalle sitta, res dig!” Barnet försöker styra hemmet. Utan att knäcka barnets vilja, säg ”Nallen sitter här och jag sitter bredvid den” och behåll balansen och freden i rummet.', title_vi = 'Chế độ "độc tài" "Mẹ đừng ngồi!" 🪑', body_vi = 'Mẹ muốn ngồi xuống sofa, nhưng bé chạy đến: "Gấu bông của con ngồi đó, mẹ đứng lên!". Bé đang cố gắng điều khiển cả nhà. Để không bẻ gãy ý chí của bé, hãy giữ cân bằng và hòa khí bằng câu: "Gấu bông ngồi đây, mẹ ngồi cạnh bạn ấy nhé".', title_zh = '“你别坐！”的独裁 🪑', body_zh = '你想坐到沙发上，宝宝却跑过来说：“那儿是我的小熊坐的，你起来！”宝宝在试着管理这个家。别硬生生地压下宝宝的意愿，说一句“小熊坐这儿，我坐在它旁边”，守住平衡和房间里的和平。' WHERE id = 'b4510edb-beed-40b8-b0ad-884291f78f89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Anacan AI: ¿Por qué mienten los niños? 🤥', body_es = 'Dice: «El agua no la he tirado yo, la ha tirado el juguete». ¿Miente o es su imaginación trabajando? No busques respuestas que den miedo en internet. Descubre con Anacan AI que estas ilusiones a los 3 años y medio son una etapa del desarrollo totalmente normal y quédate tranquila.', title_fr = 'Anacan AI : pourquoi les enfants mentent-ils ? 🤥', body_fr = 'Il a dit « C''est pas moi qui ai renversé l''eau, c''est le jouet ». Ment-il, ou est-ce son imagination qui travaille ? Ne cherchez pas de réponses effrayantes sur Internet. Apprenez avec Anacan AI que ces illusions sont une étape du développement tout à fait normale à 3 ans et demi, et soufflez.', title_hi = 'Anacan AI: बच्चे झूठ क्यों बोलते हैं? 🤥', body_hi = 'बोला, ‘पानी मैंने नहीं गिराया, खिलौने ने गिराया।’ वह झूठ बोल रहा है या उसकी कल्पना काम कर रही है? इंटरनेट पर डरावने जवाब मत ढूँढिए। Anacan AI से जानिए कि साढ़े 3 साल के बच्चे के ये भ्रम विकास की बिल्कुल सामान्य सीढ़ी हैं, और निश्चिंत हो जाइए।', title_id = 'Anacan AI: Kenapa anak berbohong? 🤥', body_id = 'Ia berkata ''Bukan aku yang menumpahkan air, mainannya yang tumpahkan''. Apakah ia berbohong, atau imajinasinya sedang bekerja? Jangan mencari jawaban menakutkan di internet. Pelajari dari Anacan AI bahwa ilusi seperti ini adalah tahap perkembangan yang sepenuhnya normal di usia 3,5 tahun, dan tenanglah.', title_ja = 'Anacan AI：子どもはなぜうそをつくの？ 🤥', body_ja = '「お水こぼしたのはぼくじゃない、おもちゃがこぼした」と言った。うそをついているの？それとも想像力が働いているの？ネットで怖い答えをさがさないで。Anacan AIで、3歳半のこうした思いこみが、ごく普通の発達の一段階だと知って安心しましょう。', title_ko = 'Anacan AI: 아이들은 왜 거짓말을 할까요? 🤥', body_ko = '''물은 내가 안 쏟았어, 장난감이 쏟았어''라고 했나요? 거짓말일까요, 상상력일까요? 인터넷에서 무서운 답을 찾지 마세요. Anacan AI에게서 세 살 반 아이의 이런 착각이 아주 정상적인 발달 단계라는 걸 알고 마음을 놓으세요.', title_nl = 'Anacan AI: waarom liegen kinderen? 🤥', body_nl = 'Hij zei: ''Ik heb het water niet gemorst, de knuffel deed het.'' Liegt hij, of werkt zijn fantasie? Zoek op internet niet naar enge antwoorden. Leer van Anacan AI dat deze illusies bij een kind van 3,5 een heel normale ontwikkelingsstap zijn, en ontspan.', title_pl = 'Anacan AI: dlaczego dzieci kłamią? 🤥', body_pl = 'Powiedział: „To nie ja rozlałem wodę, to zabawka”. Kłamie czy działa jego wyobraźnia? Nie szukaj strasznych odpowiedzi w internecie. Dowiedz się od Anacan AI, że takie iluzje u 3,5-latka to zupełnie normalny etap rozwoju, i odetchnij.', title_pt = 'Anacan AI: porque é que as crianças mentem? 🤥', body_pt = 'Disse "Não fui eu que entornei a água, foi o brinquedo". Está a mentir ou é a imaginação a trabalhar? Não procure respostas assustadoras na internet. Descubra com o Anacan AI que estas ilusões aos 3 anos e meio são uma fase totalmente normal do desenvolvimento e fique tranquila.', title_sv = 'Anacan AI: Varför ljuger barn? 🤥', body_sv = '”Det var inte jag som spillde vattnet, det var leksaken.” Ljuger barnet, eller är det fantasin som arbetar? Leta inte efter skrämmande svar på nätet. Lär dig av Anacan AI att de här illusionerna hos en 3,5-åring är ett helt normalt utvecklingssteg och slappna av.', title_vi = 'Anacan AI: Vì sao trẻ nói dối? 🤥', body_vi = 'Bé nói: "Không phải con làm đổ nước, là đồ chơi làm đổ". Bé đang nói dối, hay trí tưởng tượng đang hoạt động? Đừng tìm những câu trả lời đáng sợ trên mạng. Hãy hỏi Anacan AI để biết những ảo tưởng này của trẻ 3,5 tuổi là một bước phát triển hoàn toàn bình thường, và yên tâm.', title_zh = 'Anacan AI：孩子为什么会撒谎？🤥', body_zh = '“水不是我洒的，是玩具洒的。”宝宝是在撒谎，还是想象力在运转？别在网上找那些吓人的答案。问问Anacan AI，了解3岁半孩子的这些“幻象”完全是正常的发育阶段，放下心来。' WHERE id = 'a33e5975-6dcb-4e61-93db-f52a429ffcb8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ataque de risa en pareja 🥂', body_es = 'Por fin se ha dormido. Mientras le cuentas a tu pareja ese suceso absurdo que te ha vuelto loca durante el día, de repente los dos os partís de risa. Sí, estas risas son la recompensa más dulce de ser padres.', title_fr = 'Fou rire à deux 🥂', body_fr = 'L''enfant dort enfin. En racontant à votre partenaire l''épisode absurde qui vous a rendue folle dans la journée, vous éclatez soudain de rire tous les deux. Oui, ces rires sont la plus savoureuse récompense de la vie de parents.', title_hi = 'साथी के साथ हँसी का दौरा 🥂', body_hi = 'बच्चा आखिरकार सो गया। दिनभर आपको परेशान करने वाली वह बेतुकी घटना साथी को सुनाते हुए अचानक आप दोनों ठहाकों से लोटपोट हो जाते हैं। हाँ, यह हँसी पेरेंटिंग का सबसे मीठा इनाम है।', title_id = 'Tertawa lepas bersama pasangan 🥂', body_id = 'Anak akhirnya tidur. Saat menceritakan kejadian absurd yang membuat Anda hampir gila hari ini kepada pasangan, tiba-tiba kalian berdua tertawa terbahak-bahak. Ya, tawa seperti ini adalah hadiah paling nikmat menjadi orang tua.', title_ja = 'パートナーと笑いが止まらない 🥂', body_ja = 'やっと子どもが寝ました。今日あなたを振りまわしたおかしなできごとをパートナーに話していると、急にふたりとも大笑い。そう、この笑いこそ、子育てのいちばんおいしいごほうびです。', title_ko = '배우자와 웃음 폭발 🥂', body_ko = '아이가 드디어 잠들었어요. 낮에 엄마를 미치게 한 엉뚱한 사건을 배우자에게 이야기하다가 갑자기 둘 다 웃음이 터졌나요? 네, 이런 웃음이 육아의 가장 달콤한 보상이에요.', title_nl = 'Slappe lach met je partner 🥂', body_nl = 'Je kind slaapt eindelijk. Terwijl je je partner vertelt over dat absurde voorval dat je vandaag gek maakte, liggen jullie ineens allebei dubbel van het lachen. Ja, dit lachen is de heerlijkste beloning van het ouderschap.', title_pl = 'Napad śmiechu we dwoje 🥂', body_pl = 'Dziecko w końcu zasnęło. Gdy opowiadasz partnerowi o absurdalnej sytuacji, która doprowadziła cię dziś do szału, nagle oboje wybuchacie śmiechem. Tak, ten śmiech to najsłodsza nagroda rodzicielstwa.', title_pt = 'Ataque de riso a dois 🥂', body_pt = 'A criança finalmente adormeceu. Ao contar ao seu companheiro aquele episódio absurdo que hoje a deixou louca, desatam os dois a rir às gargalhadas. Pois é, estas gargalhadas são a recompensa mais deliciosa da parentalidade.', title_sv = 'Skrattkris med partnern 🥂', body_sv = 'Äntligen sover barnet. När du berättar för din partner om den absurda händelsen som gjorde dig galen under dagen börjar ni plötsligt båda kikna av skratt. Ja, de skratten är föräldraskapets ljuvligaste belöning.', title_vi = 'Cười không ngừng cùng chồng 🥂', body_vi = 'Cuối cùng bé cũng ngủ. Khi kể cho chồng nghe chuyện ngớ ngẩn khiến mẹ phát điên trong ngày, bỗng cả hai cùng cười phá lên. Đúng vậy, những tràng cười ấy là phần thưởng ngọt ngào nhất của việc làm cha mẹ.', title_zh = '和伴侣笑到停不下来 🥂', body_zh = '宝宝终于睡着了。你给伴侣讲着白天那件让你抓狂的荒诞事，讲着讲着你们俩突然都笑得前仰后合。是的，这些笑声是为人父母最甜美的奖赏。' WHERE id = 'f03a726a-5a9c-4eda-ab04-4d6b21a432cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Llevar los juguetes al baño 🛀', body_es = 'No quiere bañarse, pero acepta meterse en el agua después de llevar a la bañera todos sus coches y sus osos de plástico. No se lo impidas. Esos juguetes de la bañera son los mejores mediadores para que se rinda al efecto relajante del agua.', title_fr = 'Emmener les jouets dans le bain 🛀', body_fr = 'Il ne veut pas se laver, mais accepte d''entrer dans l''eau une fois toutes ses voitures et ses ours en plastique installés dans la baignoire. Ne l''en empêchez pas. Ces jouets sont les meilleurs intermédiaires pour le laisser se rendre à l''effet apaisant de l''eau.', title_hi = 'खिलौने नहाने ले जाना 🛀', body_hi = 'नहाना नहीं चाहता, पर अपनी सारी गाड़ियाँ और प्लास्टिक के भालू बाथटब में डालने के बाद पानी में जाने को मान जाता है। मत रोकिए। बाथटब के वे खिलौने ही उसे पानी के सुकून भरे असर तक ले जाने वाले सबसे बड़े मददगार हैं।', title_id = 'Membawa mainan ke kamar mandi 🛀', body_id = 'Ia tak mau mandi, tapi setelah semua mobil dan beruang plastiknya dimasukkan ke bak, ia mau masuk ke air. Jangan halangi. Mainan di bak mandi itu adalah perantara terbesar yang membuatnya menyerah pada efek air yang menenangkan.', title_ja = 'おもちゃをお風呂へ 🛀', body_ja = 'お風呂に入りたがらないのに、車やプラスチックのくまさんを全部バスタブに入れたら、お湯に入ってくれる。じゃましないで。お風呂の中のおもちゃたちは、この子をお湯の心落ち着く力へと導いてくれる、いちばんの仲介役です。', title_ko = '장난감 데리고 목욕하기 🛀', body_ko = '목욕은 싫다더니 자동차와 플라스틱 곰을 욕조에 다 넣고 나서야 물에 들어가겠다고 하나요? 막지 마세요. 욕조 속 장난감들이 물의 차분한 힘에 아이를 맡기게 해 주는 가장 큰 중재자예요.', title_nl = 'Speelgoed mee in bad 🛀', body_nl = 'Hij wil niet in bad, maar als hij al zijn auto''s en plastic beertjes in het bad heeft gezet, gaat hij wel het water in. Houd hem niet tegen. Dat speelgoed in bad is de beste bemiddelaar om hem over te geven aan het kalmerende effect van het water.', title_pl = 'Zabawki do kąpieli 🛀', body_pl = 'Nie chce się kąpać, ale gdy zgromadzi w wannie wszystkie samochodziki i plastikowe misie, zgadza się wejść do wody. Nie przeszkadzaj. Te zabawki w wannie to najlepsi pośrednicy, dzięki którym poddaje się kojącej mocy wody.', title_pt = 'Levar os brinquedos para o banho 🛀', body_pt = 'Não quer tomar banho, mas aceita entrar na água depois de pôr todos os carrinhos e ursinhos de plástico na banheira. Não o impeça. Esses brinquedos na banheira são os maiores intermediários para o entregar ao efeito calmante da água.', title_sv = 'Ta med leksakerna i badet 🛀', body_sv = 'Barnet vill inte bada, men går med på att gå i vattnet först när alla bilar och plastnallar har samlats i badkaret. Stoppa inte. Leksakerna i badkaret är de största mellanhänderna som får barnet att ge sig åt vattnets lugnande effekt.', title_vi = 'Mang đồ chơi vào bồn tắm 🛀', body_vi = 'Bé không muốn tắm, nhưng sau khi đã mang hết ô tô và gấu nhựa vào bồn thì bé mới chịu xuống nước. Đừng ngăn cản. Những món đồ chơi trong bồn chính là "người trung gian" lớn nhất giúp bé đầu hàng tác dụng êm dịu của nước.', title_zh = '带玩具去洗澡 🛀', body_zh = '不想洗澡，可把所有小汽车和塑料小熊都放进浴缸后，就愿意下水了。别阻止。浴缸里的那些玩具，是让宝宝接受水的安抚作用最大的“中间人”。' WHERE id = 'fce85c76-de6a-416c-a8d9-e7fd462bd967' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy rechaza la carne que hasta ayer le encantaba, pero quiere comer pasta todo el día. No luches contra su voluntad. Aprende en Recetas saludables a meter las proteínas y las verduras dentro de la pasta como una salsa invisible, y gana tú.', body_fr = 'Il refuse aujourd''hui la viande qu''il adorait encore hier et veut manger des pâtes toute la journée. Ne luttez pas contre sa volonté. Apprenez dans les Recettes saines à intégrer les protéines et les légumes dans les pâtes sous forme de sauce invisible, et c''est vous qui gagnerez.', body_hi = 'कल तक जो मांस पसंद था, आज उसे ठुकराता है, पर दिनभर पास्ता खाना चाहता है। उसकी इच्छा से मत लड़िए। सेहतमंद रेसिपी में सीखिए कि पास्ता में प्रोटीन और सब्ज़ियाँ अदृश्य सॉस की तरह कैसे मिलाएँ, और जीत जाइए।', body_id = 'Daging yang sampai kemarin ia suka, hari ini ditolak, dan ia hanya ingin makan pasta seharian. Jangan melawan kemauannya. Pelajari di Resep Sehat cara mencampurkan protein dan sayur ke dalam pasta sebagai saus yang tak terlihat, dan jadilah pemenangnya.', body_ja = '昨日まで好きだったお肉を今日は拒否して、一日じゅうパスタばかり食べたがる。意志と戦わないで。「ヘルシーレシピ」で、たんぱく質や野菜を見えないソースにしてパスタにまぜる方法を覚えて、勝ちをつかみましょう。', body_ko = '어제까지 좋아하던 고기를 오늘은 거부하고 하루 종일 파스타만 먹겠다고 하나요? 의지와 싸우지 마세요. 건강한 레시피에서 단백질과 채소를 파스타에 감쪽같은 소스로 넣는 법을 배워 이기세요.', body_nl = 'Het vlees waar hij tot gisteren dol op was, weigert hij vandaag, maar hij wil de hele dag pasta. Vecht niet tegen zijn wil. Leer in Gezonde recepten hoe je eiwitten en groenten onzichtbaar als saus door de pasta verwerkt, en win.', body_pl = 'Mięso, które do wczoraj lubił, dziś odrzuca, a przez cały dzień chce jeść tylko makaron. Nie walcz z jego wolą. Naucz się w Zdrowych przepisach, jak niewidocznie dodać białko i warzywa do makaronu w formie sosu, i wygraj.', body_pt = 'Recusa hoje a carne de que gostava até ontem, mas quer comer massa o dia todo. Não lute contra a vontade dele. Aprenda nas Receitas Saudáveis a juntar proteínas e legumes à massa como um molho invisível, e ganhe.', body_sv = 'Köttet som barnet älskade fram till i går vägrar det i dag, men vill äta pasta hela dagen. Kämpa inte mot barnets vilja. Lär dig bland Hälsosamma recept hur du blandar in proteiner och grönsaker i pastan som en osynlig sås, och vinn.', body_vi = 'Món thịt đến hôm qua bé còn thích, hôm nay lại từ chối, chỉ muốn ăn mì ống cả ngày. Đừng đấu với ý chí của bé. Hãy học trong Công thức lành mạnh cách đưa chất đạm và rau củ vào mì ống dưới dạng nước sốt "vô hình" và giành chiến thắng.', body_zh = '直到昨天还喜欢的肉，今天却拒绝，一整天只想吃意面。别和宝宝的意志较劲。去健康食谱里学学，如何把蛋白质和蔬菜做成看不见的酱汁拌进意面里，赢下这一局。' WHERE id = '383239b8-7f85-4507-9f51-cdc8a13d1e8f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bailes frente al espejo 🪞', body_es = 'Se pone delante del espejo, canta y prueba distintos pasos de baile. ¡Está comprobando el ritmo de su cuerpo y cómo se ve! Anota con alegría en el Seguimiento del desarrollo esta conciencia corporal y su sentido del ritmo.', title_fr = 'Danses devant le miroir 🪞', body_fr = 'Devant le miroir, il chante et essaie différents pas de danse. Il teste le rythme de son corps et son apparence ! Notez avec joie dans le Suivi de développement cette conscience de son corps et son sens du rythme.', title_hi = 'आईने के सामने नाच 🪞', body_hi = 'आईने के सामने खड़े होकर गाना गाता है और नाचने के अलग-अलग अंदाज़ आज़माता है। वह अपने शरीर की लय और खुद कैसा दिखता है, यह परख रहा है! ग्रोथ ट्रैकर में उसकी इस शरीर की समझ और लय की भावना को खुशी से दर्ज कीजिए।', title_id = 'Menari di depan cermin 🪞', body_id = 'Ia berdiri di depan cermin, bernyanyi, dan mencoba berbagai gerakan tari. Ia sedang menguji irama tubuhnya dan bagaimana penampilannya! Catat dengan gembira kesadaran tubuh dan rasa iramanya ini di Pelacak Perkembangan.', title_ja = '鏡の前でダンス 🪞', body_ja = '鏡の前で歌って、いろいろなダンスの動きを試しています。自分の体のリズムと見え方を確かめているんです！この体への気づきとリズム感を、「発達トラッカー」に喜んで記録しましょう。', title_ko = '거울 앞의 춤 🪞', body_ko = '거울 앞에서 노래하며 여러 가지 춤 동작을 시험하나요? 자기 몸의 리듬과 모습을 시험하는 중이에요! 이 몸에 대한 인식과 리듬감을 성장 기록에 기쁘게 남겨 두세요.', title_nl = 'Dansen voor de spiegel 🪞', body_nl = 'Hij gaat voor de spiegel staan, zingt en probeert verschillende danspasjes uit. Hij test het ritme van zijn lichaam en hoe hij eruitziet! Noteer dit lichaamsbewustzijn en ritmegevoel blij in de Groeitracker.', title_pl = 'Tańce przed lustrem 🪞', body_pl = 'Staje przed lustrem, śpiewa i próbuje różnych ruchów tanecznych. Sprawdza rytm swojego ciała i to, jak wygląda! Z radością zapisz w Śledzeniu rozwoju tę świadomość ciała i poczucie rytmu.', title_pt = 'Danças ao espelho 🪞', body_pt = 'Põe-se em frente ao espelho a cantar e experimenta diferentes passos de dança. Está a testar o ritmo do próprio corpo e o aspeto que tem! Registe com alegria esta consciência corporal e o sentido de ritmo no Registo de Crescimento.', title_sv = 'Dans framför spegeln 🪞', body_sv = 'Barnet ställer sig framför spegeln, sjunger och provar olika dansrörelser. Barnet testar kroppens rytm och hur det ser ut! Anteckna glatt barnets kroppsmedvetenhet och rytmkänsla i Utvecklingsspåraren.', title_vi = 'Điệu nhảy trước gương 🪞', body_vi = 'Bé đứng trước gương hát và thử những điệu nhảy khác nhau. Bé đang thử nghiệm nhịp điệu cơ thể và xem mình trông thế nào! Hãy vui vẻ ghi lại khả năng nhận thức cơ thể và cảm thụ nhịp điệu này trong Theo dõi phát triển.', title_zh = '镜子前的舞蹈 🪞', body_zh = '站在镜子前唱歌，试着跳各种舞蹈动作。宝宝在测试自己身体的节奏和看起来的样子！开心地在发育追踪里记下宝宝的身体意识和节奏感吧。' WHERE id = '6fb57a61-aa7b-441f-afc3-ed5b09208ed5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dúo susurrado para dormir 🌙', body_es = 'Está tan activo en la cama que no se duerme. En lugar de levantar la voz, baja de golpe el tono y empieza a cantarle en susurros su canción favorita. Cuando el niño se concentra para oírte, su cerebro se hipnotiza automáticamente y pasa al modo sueño.', title_fr = 'Duo chuchoté pour s''endormir 🌙', body_fr = 'Il est si agité dans son lit qu''il ne s''endort pas. Au lieu d''élever la voix, baissez soudain le ton et chantez en chuchotant sa chanson préférée. Quand l''enfant se concentre pour vous entendre, son cerveau entre automatiquement dans une sorte d''hypnose et passe en mode sommeil.', title_hi = 'फुसफुसाती नींद की जुगलबंदी 🌙', body_hi = 'बिस्तर में इतना सक्रिय है कि सो ही नहीं रहा। आवाज़ ऊँची करने के बजाय अचानक अपना लहजा धीमा कीजिए, उसका पसंदीदा गाना फुसफुसाकर गाना शुरू कीजिए। जब बच्चा आपको सुनने के लिए पूरा ध्यान लगाता है, तो उसका दिमाग अपने-आप सम्मोहित होकर नींद के मोड में चला जाएगा।', title_id = 'Duet tidur berbisik 🌙', body_id = 'Ia begitu aktif di tempat tidur sampai tidak bisa tidur. Daripada meninggikan suara, turunkan nada suara Anda tiba-tiba dan mulailah menyanyikan lagu kesukaannya sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis terhipnosis dan beralih ke mode tidur.', title_ja = 'ささやきのおやすみデュエット 🌙', body_ja = 'ベッドの上で元気いっぱいで、なかなか寝ない。声を大きくする代わりに、急に声のトーンを落として、この子の好きな歌をささやき声で歌い始めましょう。あなたの声を聞こうと集中すると、脳は自然と催眠にかかったように眠りモードへ切りかわります。', title_ko = '속삭이는 잠자리 듀엣 🌙', body_ko = '침대에서 너무 활발해서 잠들지 않나요? 목소리를 높이는 대신 갑자기 톤을 낮춰 좋아하는 노래를 속삭이듯 불러 주세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 최면에 걸린 듯 수면 모드로 바뀔 거예요.', title_nl = 'Fluisterend slaapduet 🌙', body_nl = 'Is hij in bed zo actief dat hij niet in slaap valt? Verhef je stem niet, maar ga ineens zachter praten en zing fluisterend zijn lievelingsliedje. Als hij zijn best doet om je te verstaan, raakt zijn brein vanzelf in een soort hypnose en schakelt het over naar de slaapstand.', title_pl = 'Szeptany duet na dobranoc 🌙', body_pl = 'W łóżku jest tak aktywny, że nie zasypia. Zamiast podnosić głos, nagle go obniż i zacznij szeptem śpiewać jego ulubioną piosenkę. Gdy dziecko zamieni się w słuch, żeby cię usłyszeć, jego mózg automatycznie wpadnie w hipnozę i przejdzie w tryb snu.', title_pt = 'Dueto de sono em sussurro 🌙', body_pt = 'Está tão ativo na cama que não adormece. Em vez de levantar a voz, baixe de repente o tom e comece a cantar a sussurrar a canção de que ele gosta. Quando a criança se concentra para a ouvir, o cérebro fica automaticamente hipnotizado e passa para o modo de sono.', title_sv = 'Viskad sömnduett 🌙', body_sv = 'Barnet är så aktivt i sängen att det inte somnar. Istället för att höja rösten, sänk plötsligt tonen och börja viska barnets favoritlåt. När barnet lyssnar spänt för att höra dig blir hjärnan automatiskt hypnotiserad och går över i sömnläge.', title_vi = 'Song ca thì thầm ru ngủ 🌙', body_vi = 'Bé hiếu động trên giường đến mức không chịu ngủ. Thay vì lớn tiếng, hãy bất ngờ hạ giọng và thì thầm hát bài hát bé thích. Khi bé chú ý để nghe mẹ, não bé sẽ tự động như bị thôi miên và chuyển sang chế độ ngủ.', title_zh = '悄悄话哄睡二重唱 🌙', body_zh = '在床上太活跃，怎么都睡不着。与其提高嗓门，不如突然压低声音，用悄悄话唱起宝宝喜欢的歌。宝宝聚精会神想听清你时，大脑会自动被“催眠”，切换到睡眠模式。' WHERE id = '86182307-b484-4518-a023-a22ef5f8216d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El peine es el enemigo 🪮', body_es = 'En cuanto ve el peine, sale corriendo de la habitación a gritos. Detén la lucha. Primero dale el peine y deja que te peine a ti o a su muñeca. Cuando sienta que el control lo tiene él, te dejará que llegue tu turno.', title_fr = 'Le peigne, cet ennemi 🪮', body_fr = 'Dès qu''il voit le peigne, il s''enfuit de la pièce en hurlant. Arrêtez la lutte. Donnez-lui d''abord le peigne et laissez-le coiffer vos cheveux ou ceux de sa poupée. Quand il sentira qu''il a le contrôle, il vous laissera votre tour.', title_hi = 'कंघी दुश्मन है 🪮', body_hi = 'कंघी देखते ही चीखते हुए कमरे से भाग जाता है। लड़ाई रोकिए। पहले कंघी उसे दीजिए, उसे आपके या उसकी गुड़िया के बाल सँवारने दीजिए। जब उसे लगेगा कि नियंत्रण उसके हाथ में है, तब वह आपकी बारी आने देगा।', title_id = 'Menyisir rambut adalah musuh 🪮', body_id = 'Begitu melihat sisir, ia menjerit dan lari dari kamar. Hentikan perlawanan. Pertama, berikan sisirnya kepadanya, biarkan ia menyisir rambut Anda atau rambut bonekanya. Setelah merasa memegang kendali, ia akan membiarkan giliran beralih kepada Anda.', title_ja = '髪をとかすのは敵 🪮', body_ja = 'くしを見るなり、泣き叫んで部屋から逃げだす。戦いはやめましょう。まずはくしを渡して、あなたの髪や人形の髪をとかさせてあげて。主導権が自分にあると感じたら、あなたの番にもさせてくれます。', title_ko = '빗질은 적이에요 🪮', body_ko = '빗만 보면 소리치며 방에서 도망가나요? 싸움을 멈추세요. 먼저 빗을 아이에게 주고 엄마 머리나 인형 머리를 빗게 해 주세요. 자기가 주도권을 쥐었다고 느끼면 엄마 차례도 허락할 거예요.', title_nl = 'Haren kammen is de vijand 🪮', body_nl = 'Zodra hij de kam ziet, rent hij krijsend de kamer uit. Stop de strijd. Geef hem eerst de kam en laat hem jouw haar of het haar van zijn pop kammen. Als hij voelt dat hij de controle heeft, laat hij jou daarna ook aan de beurt.', title_pl = 'Czesanie to wróg 🪮', body_pl = 'Na widok grzebienia z krzykiem ucieka z pokoju. Przerwij walkę. Najpierw daj mu grzebień i niech uczesze twoje włosy albo włosy lalki. Gdy poczuje, że ma kontrolę, pozwoli, by przyszła twoja kolej.', title_pt = 'O pente é o inimigo 🪮', body_pt = 'Mal vê o pente, foge do quarto aos gritos. Pare a luta. Primeiro dê-lhe o pente e deixe-o pentear o seu cabelo ou o da boneca. Depois de sentir que tem o controlo, vai deixar que chegue a sua vez.', title_sv = 'Hårborstning är fienden 🪮', body_sv = 'Så fort barnet ser kammen springer det skrikande ut ur rummet. Avbryt kampen. Ge först kammen till barnet och låt det kamma ditt eller dockans hår. När barnet känner att det har kontrollen låter det turen gå över till dig.', title_vi = 'Chải tóc là kẻ thù 🪮', body_vi = 'Vừa thấy chiếc lược, bé đã gào lên và chạy khỏi phòng. Hãy dừng cuộc chiến. Trước tiên đưa lược cho bé, để bé chải tóc cho mẹ hoặc cho búp bê. Khi cảm thấy mình được kiểm soát, bé sẽ cho phép đến lượt mẹ.', title_zh = '梳头是敌人 🪮', body_zh = '一看到梳子就大哭着跑出房间。先停止这场“斗争”。先把梳子给宝宝，让宝宝给你或布娃娃梳头。等宝宝感觉到掌控权在自己手里后，就会愿意轮到你了。' WHERE id = '4cd431fe-3e79-44d3-a7ca-53965a307626' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo en la Comunidad Anacan 💬', body_es = '¿De repente te ahoga el pensamiento «Nunca volveré a ser la de antes, la que era libre»? Comparte este sentimiento pasajero pero muy pesado y profundo con las madres de la Comunidad Anacan y recibe consuelo y apoyo de quienes han pasado por lo mismo.', title_fr = 'Du soutien dans la Communauté Anacan 💬', body_fr = 'La pensée « Je ne serai plus jamais la femme libre d''avant » vous étouffe soudain ? Partagez ce sentiment passager, mais très lourd et profond, avec les mamans de la Communauté Anacan et recevez le réconfort et le soutien de celles qui sont passées par là.', title_hi = 'Anacan कम्युनिटी में सहारा 💬', body_hi = '‘मैं फिर कभी पहले वाली आज़ाद मैं नहीं बन पाऊँगी’ वाला ख्याल अचानक आपका दम घोंट रहा है? Anacan कम्युनिटी की माँओं के साथ यह अस्थायी, पर बहुत भारी और गहरी भावना बाँटिए और उनसे सांत्वना और सहारा पाइए, जो इसी राह से गुज़र चुकी हैं।', title_id = 'Dukungan di Komunitas Anacan 💬', body_id = 'Pikiran ''Aku tidak akan pernah bisa menjadi diriku yang dulu dan bebas'' tiba-tiba membuat Anda sesak? Bagikan perasaan yang sementara namun sangat berat dan dalam ini dengan para ibu di Komunitas Anacan, dan dapatkan penghiburan serta dukungan dari mereka yang pernah melalui jalan yang sama.', title_ja = 'Anacanコミュニティで支え合い 💬', body_ja = '「もう前の自由な自分には戻れない」という思いに、急に胸がつまることはありませんか？Anacanコミュニティのママたちと、この一時的だけれどとても重くて深い気持ちを分かち合いましょう。同じ道を通ってきた人たちから、なぐさめと支えをもらえます。', title_ko = 'Anacan 커뮤니티의 응원 💬', body_ko = '''다시는 예전의 자유로운 나로 돌아갈 수 없을 거야''라는 생각이 갑자기 숨을 막히게 하나요? 이 지나가지만 무겁고 깊은 감정을 Anacan 커뮤니티의 엄마들과 나누고, 같은 길을 걸어온 이들에게 위로와 응원을 받으세요.', title_nl = 'Steun in de Anacan Community 💬', body_nl = 'Overvalt de gedachte ''Ik word nooit meer de oude, vrije ik'' je ineens? Deel dit tijdelijke maar heel zware, diepe gevoel met de mama''s in de Anacan Community en krijg troost en steun van wie dezelfde weg is gegaan.', title_pl = 'Wsparcie w Społeczności Anacan 💬', body_pl = 'Nagle dławi cię myśl „Już nigdy nie będę dawną, wolną sobą”? Podziel się tym przemijającym, ale bardzo ciężkim, głębokim uczuciem z mamami w Społeczności Anacan i znajdź pocieszenie i wsparcie u tych, które przeszły tę samą drogę.', title_pt = 'Apoio na Comunidade Anacan 💬', body_pt = 'De repente sufoca-a o pensamento "nunca mais vou voltar a ser a pessoa livre que era"? Partilhe este sentimento passageiro, mas muito pesado e profundo, com as mães da Comunidade Anacan e receba conforto e apoio de quem já passou pelo mesmo.', title_sv = 'Stöd i Anacan Community 💬', body_sv = 'Kväver tanken ”jag kommer aldrig att kunna bli mitt gamla, fria jag igen” dig plötsligt? Dela den här övergående men väldigt tunga, djupa känslan med mammorna i Anacan Community och få tröst och stöd från dem som gått samma väg.', title_vi = 'Sự hỗ trợ trong Cộng đồng Anacan 💬', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ được tự do như ngày xưa nữa" bỗng khiến mẹ nghẹt thở? Hãy chia sẻ cảm xúc thoáng qua nhưng nặng nề, sâu sắc này với các mẹ trong Cộng đồng Anacan, và nhận sự an ủi, hỗ trợ từ những người đã đi qua cùng con đường.', title_zh = 'Anacan社区里的支持 💬', body_zh = '“我再也回不到从前那个自由的自己了”，这个念头突然让你喘不过气？在Anacan社区和妈妈们分享这份短暂却沉重、深刻的感受，从走过同样道路的她们那里得到安慰和支持。' WHERE id = '7de027d7-5609-44f6-aeb7-25a62639a344' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de agua 🌊', body_es = 'A veces nada funciona y llora por todo. Mételo en una bañera de agua templada y échale un poco de espuma. Ese efecto imán, místico y que quita la tensión, del agua llenará de calma al instante la habitación y su sistema nervioso.', title_fr = 'Thérapie par l''eau 🌊', body_fr = 'Parfois, rien ne marche, il pleure pour tout. Mettez-le dans un bain d''eau tiède avec un peu de mousse. L''effet magnétique, presque magique, de l''eau qui absorbe la tension apportera aussitôt la paix à toute la pièce et à son système nerveux.', title_hi = 'पानी की थेरेपी 🌊', body_hi = 'कभी-कभी कुछ भी काम नहीं करता, वह बस हर बात पर रोता है। उसे गुनगुने पानी से भरे टब में बिठाइए, थोड़ा झाग डाल दीजिए। पानी का वह रहस्यमयी, तनाव सोखने वाला चुंबकीय असर पूरे कमरे और उसके तंत्रिका तंत्र में तुरंत सुकून ले आएगा।', title_id = 'Terapi air 🌊', body_id = 'Kadang tak ada yang berhasil, ia menangisi segala hal. Masukkan ia ke bak berisi air hangat dan tambahkan sedikit busa. Efek magnet air yang ajaib dan meredakan ketegangan akan langsung membawa ketenangan ke seluruh ruangan dan sistem sarafnya.', title_ja = 'お湯のセラピー 🌊', body_ja = '何をしてもうまくいかず、ただ何にでも泣いてしまう日もあります。ぬるめのお湯をはったバスタブに入れて、泡を少し加えてみましょう。お湯のふしぎな、緊張をほぐす磁石のような力が、部屋全体とこの子の神経にすぐに落ち着きをもたらします。', title_ko = '물 테라피 🌊', body_ko = '가끔은 아무것도 통하지 않고 모든 일에 울기만 하죠. 따뜻한 물을 받은 욕조에 거품을 조금 풀고 들어가게 해 주세요. 긴장을 풀어 주는 물의 신비한 힘이 방 안과 아이의 신경계에 바로 평온을 가져다줄 거예요.', title_nl = 'Watertherapie 🌊', body_nl = 'Soms werkt niets en huilt hij gewoon om alles. Zet hem in een bad met lauw water en doe er wat schuim in. Het mystieke, ontspannende magnetische effect van het water brengt meteen rust in de hele kamer en in zijn zenuwstelsel.', title_pl = 'Terapia wodą 🌊', body_pl = 'Czasem nic nie działa, a on po prostu płacze o wszystko. Włóż go do wanny z ciepłą wodą i dodaj trochę piany. Tajemniczy, kojący magnetyczny efekt wody od razu wniesie spokój do całego pokoju i do jego układu nerwowego.', title_pt = 'Terapia com água 🌊', body_pt = 'Às vezes nada resulta, ele simplesmente chora por tudo. Ponha-o numa banheira com água morna e junte um pouco de espuma. O efeito magnético e místico da água, que alivia a tensão, vai trazer logo calma a todo o quarto e ao sistema nervoso dele.', title_sv = 'Vattenterapi 🌊', body_sv = 'Ibland hjälper ingenting, barnet gråter bara åt allt. Sätt barnet i ett badkar med ljummet vatten och lite skum. Vattnets mystiska, spänningsdämpande magnetiska effekt ger direkt lugn åt hela rummet och barnets nervsystem.', title_vi = 'Liệu pháp nước 🌊', body_vi = 'Đôi khi chẳng cách nào hiệu quả, bé cứ khóc vì mọi thứ. Hãy cho bé vào bồn nước ấm, thêm chút bọt xà phòng. Sức hút huyền bí, xua tan căng thẳng của nước sẽ lập tức mang lại bình yên cho cả căn phòng và hệ thần kinh của bé.', title_zh = '水疗法 🌊', body_zh = '有时候什么办法都不管用，宝宝就是什么都哭。把宝宝放进装满温水的浴缸，再加一点泡泡。水那种神奇的、能吸走紧张的磁力效果，会马上给整个房间和宝宝的神经系统带来安宁。' WHERE id = 'f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del masaje de papá 💆‍♂️', body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de él y recoger juguetes del suelo. En cuanto se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el pilar de la casa, y los pilares necesitan descansar y recuperarse sí o sí.', title_fr = 'L''heure du massage par papa 💆‍♂️', body_fr = 'Vous êtes restée debout toute la journée et votre dos est en miettes à force de lui courir après et de ramasser les jouets. Dès que l''enfant dort, demandez à votre partenaire 10 minutes de massage des épaules. Vous êtes le pilier de la maison, et les piliers doivent absolument se reposer et se restaurer.', title_hi = 'पापा का मालिश का समय 💆‍♂️', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते, ज़मीन से खिलौने उठाते-उठाते कमर टूट रही है। बच्चे के सोते ही अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप घर का खंभा हैं, और खंभों को आराम करना और फिर से मज़बूत होना ज़रूरी है।', title_id = 'Waktu pijat dari pasangan 💆‍♂️', body_id = 'Hari ini kamu terlalu lama berdiri, punggungmu serasa patah karena mengejarnya dan memunguti mainan dari lantai. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasanganmu. Kamu tiang rumah ini, dan tiang wajib beristirahat dan dipulihkan.', title_ja = 'パパのマッサージタイム 💆‍♂️', body_ja = '今日は立ちっぱなしで、追いかけまわして、床のおもちゃを拾って、腰がくたくたですね。子どもが寝たらすぐ、パートナーに10分の肩もみをお願いして。あなたはこの家の柱です。柱だって、ちゃんと休んで回復しなくちゃ。', title_ko = '아빠의 마사지 시간 💆‍♂️', body_ko = '오늘 하루 종일 서 있었고 아이를 쫓아다니며 장난감을 줍느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 이 집의 기둥이고, 기둥도 꼭 쉬고 회복해야 해요.', title_nl = 'Papa''s massage-uurtje 💆‍♂️', body_nl = 'Je hebt vandaag veel op je benen gestaan en je rug breekt van het achter hem aan rennen en speelgoed oprapen. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de pijler van het huis, en pijlers moeten zeker rusten en hersteld worden.', title_pl = 'Pora na masaż od taty 💆‍♂️', body_pl = 'Dziś długo byłaś na nogach, plecy bolą cię od biegania za nim i zbierania zabawek z podłogi. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś filarem domu, a filary muszą odpoczywać i się regenerować.', title_pt = 'A hora da massagem do pai 💆‍♂️', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de correr atrás dele e apanhar brinquedos do chão. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o pilar desta casa, e os pilares precisam de descansar e ser restaurados.', title_sv = 'Pappas massagestund 💆‍♂️', body_sv = 'Du har stått på benen länge i dag och ryggen värker av allt springande efter barnet och plockande av leksaker från golvet. Så fort barnet somnar, be din partner om 10 minuters axelmassage. Du är hemmets pelare, och pelare måste vila och återhämta sig.', title_vi = 'Giờ mát-xa cùng chồng 💆‍♂️', body_vi = 'Hôm nay mẹ đứng cả ngày, lưng như muốn gãy vì chạy theo bé và nhặt đồ chơi dưới sàn. Ngay khi bé ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là trụ cột của gia đình, và trụ cột thì nhất định phải được nghỉ ngơi, phục hồi.', title_zh = '爸爸的按摩时间 💆‍♂️', body_zh = '今天你站了太久，追着宝宝跑、从地上捡玩具，腰都快断了。宝宝一睡着，就请伴侣给你按摩10分钟肩膀。你是这个家的顶梁柱，顶梁柱也一定要好好休息、好好修复。' WHERE id = '11b4acb5-0c50-4711-bda6-86d12a2c254b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ego de la camiseta del revés 👕', body_es = 'Se ha puesto la camiseta del revés y lo luce con tanto orgullo como si hubiera conquistado el mundo. El niño que sale a la calle con la ropa del revés es un niño que defiende su decisión. No intervengas lo más mínimo: envidia su autoestima.', title_fr = 'L''ego du t-shirt à l''envers 👕', body_fr = 'Il a mis son t-shirt à l''envers et l''exhibe fièrement comme s''il avait conquis le monde. Un enfant qui sort habillé à l''envers est un enfant qui défend sa décision. N''intervenez surtout pas, admirez plutôt sa confiance en lui.', title_hi = 'उलटी कमीज़ वाला आत्मविश्वास 👕', body_hi = 'कमीज़ उलटी पहन ली और ऐसे गर्व से दिखा रहा है जैसे दुनिया जीत ली हो। उलटे कपड़ों में लोगों के बीच जाने वाला बच्चा अपने फ़ैसले पर टिकने वाला बच्चा है। ज़रा भी दखल मत दीजिए, उसके इस आत्मविश्वास पर नाज़ कीजिए।', title_id = 'Ego kaus terbalik 👕', body_id = 'Ia memakai kausnya terbalik dan memamerkannya dengan bangga seolah baru menaklukkan dunia. Anak yang keluar dengan pakaian terbalik adalah anak yang membela keputusannya sendiri. Jangan ikut campur sedikit pun, kagumi saja rasa percaya dirinya.', title_ja = '裏返しシャツのプライド 👕', body_ja = 'シャツを裏返しに着て、世界を征服したかのように誇らしげに見せてくれる。ちぐはぐな服で人前に出る子は、自分の決めたことを守っている子です。少しも手を出さず、この自信をうらやましく思うくらいでいましょう。', title_ko = '뒤집어 입은 셔츠의 자존감 👕', body_ko = '셔츠를 뒤집어 입고 세상을 정복한 듯 당당하게 뽐내나요? 뒤집어 입은 채 사람들 앞에 나서는 아이는 자기 결정을 지키는 아이예요. 조금도 끼어들지 말고 그 자신감을 부러워해 주세요.', title_nl = 'Het ego van het binnenstebuiten shirt 👕', body_nl = 'Hij heeft zijn shirt binnenstebuiten aan en laat het trots zien alsof hij de wereld heeft veroverd. Een kind dat met binnenstebuiten kleren naar buiten gaat, is een kind dat zijn eigen beslissing verdedigt. Grijp niet in, echt helemaal niet, en bewonder zijn zelfvertrouwen.', title_pl = 'Ego koszulki na lewą stronę 👕', body_pl = 'Założył koszulkę na lewą stronę i z dumą ją prezentuje, jakby podbił świat. Dziecko, które wychodzi między ludzi w ubraniu na lewą stronę, broni własnej decyzji. Nie ingeruj ani trochę, pozazdrość mu tej pewności siebie.', title_pt = 'O ego da camisola ao contrário 👕', body_pt = 'Vestiu a camisola ao contrário e exibe-a com orgulho, como se tivesse conquistado o mundo. A criança que sai à rua com a roupa ao contrário é uma criança que defende a sua decisão. Não intervenha nem um bocadinho: admire esta autoestima.', title_sv = 'Egot med tröjan ut och in 👕', body_sv = 'Barnet har tagit tröjan ut och in och visar stolt upp den som om det erövrat världen. Ett barn som går ut bland folk med kläderna ut och in är ett barn som försvarar sitt beslut. Lägg dig inte i det minsta, var avundsjuk på barnets självförtroende.', title_vi = 'Cái tôi mặc áo trái 👕', body_vi = 'Bé mặc áo trái và tự hào khoe như vừa chinh phục cả thế giới. Đứa trẻ dám ra ngoài với bộ đồ mặc trái là đứa trẻ biết bảo vệ quyết định của mình. Đừng can thiệp dù chỉ một chút, hãy ngưỡng mộ sự tự tin ấy của bé.', title_zh = '穿反衬衫的骄傲 👕', body_zh = '把衬衫穿反了，还像征服了世界一样骄傲地展示。穿着反了的衣服出门的孩子，是捍卫自己决定的孩子。一点都别插手，羡慕一下宝宝这份自信吧。' WHERE id = '48e0f071-5110-45a7-a007-23be77bbd305' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pruebas en el súper 🛒', body_es = 'Al llegar a la caja, del carro han salido 3 chocolates distintos que tú no elegiste. Está poniendo a prueba tus límites. Devuélvelos con una maniobra rápida. Y para no olvidar nada, ten siempre un ojo en la Lista de la compra de la app.', title_fr = 'Les tests du supermarché 🛒', body_fr = 'En arrivant à la caisse, vous trouvez dans le chariot 3 chocolats différents que vous n''avez pas choisis. Il teste vos limites. Remettez-les en place d''une manœuvre rapide. Et contre les oublis, gardez toujours un œil sur la Liste de courses de l''application.', title_hi = 'बाज़ार में परीक्षाएँ 🛒', body_hi = 'काउंटर के पास पहुँचीं तो ट्रॉली से 3 अलग चॉकलेट निकलीं, जो आपने नहीं चुनी थीं। वह आपकी सीमाएँ परख रहा है। फुर्ती से वे चीज़ें वापस रखिए। और भूलने से बचने के लिए नज़र हमेशा ऐप की शॉपिंग लिस्ट पर रखिए।', title_id = 'Ujian di supermarket 🛒', body_id = 'Saat mendekati kasir, dari troli muncul 3 cokelat berbeda yang tidak Anda pilih. Ia sedang menguji batasan Anda. Kembalikan barang-barang itu dengan manuver cepat. Untuk melawan lupa, pastikan mata Anda selalu pada Daftar Belanja di aplikasi.', title_ja = 'スーパーでのテスト 🛒', body_ja = 'レジに近づくと、カートからあなたが選んでいないチョコが3種類出てきた。あなたの境界線を試しているんです。すばやくもとの場所に戻しましょう。買い忘れ防止には、いつもアプリの「買い物リスト」に目を向けてね。', title_ko = '마트에서의 시험 🛒', body_ko = '계산대에 다가가니 카트에서 엄마가 고르지 않은 초콜릿 3개가 나왔나요? 엄마의 경계를 시험하는 거예요. 재빠르게 제자리로 돌려놓으세요. 깜빡하지 않게 늘 앱의 쇼핑 목록을 보세요.', title_nl = 'Tests in de supermarkt 🛒', body_nl = 'Bij de kassa komen er uit je karretje 3 verschillende chocoladerepen die jij niet koos. Hij test je grenzen. Breng ze met een snelle manoeuvre terug. En tegen vergeetachtigheid: houd je ogen op het Boodschappenlijstje in de app.', title_pl = 'Testy w sklepie 🛒', body_pl = 'Przy kasie z wózka wyłoniły się 3 różne czekolady, których nie wybierałaś. Sprawdza twoje granice. Szybkim manewrem odłóż je z powrotem. A na zapominalstwo stale miej oko na Liście zakupów w aplikacji.', title_pt = 'Testes no supermercado 🛒', body_pt = 'Ao chegar à caixa, saíram do carrinho 3 chocolates diferentes que não escolheu. Ele está a testar os seus limites. Devolva-os com uma manobra rápida. E contra os esquecimentos, mantenha os olhos sempre na Lista de Compras da app.', title_sv = 'Prov i butiken 🛒', body_sv = 'När ni närmar er kassan dyker 3 olika chokladkakor som du inte valt upp ur kundvagnen. Barnet testar dina gränser. Ställ snabbt tillbaka sakerna. Och mot glömskan, ha alltid blicken på Inköpslistan i appen.', title_vi = 'Những thử thách ở siêu thị 🛒', body_vi = 'Khi đến gần quầy thanh toán, từ xe đẩy lôi ra 3 loại sô-cô-la khác nhau mà mẹ không hề chọn. Bé đang thử giới hạn của mẹ. Hãy nhanh tay trả chúng về chỗ cũ. Còn để khỏi quên đồ, hãy luôn để mắt đến Danh sách mua sắm trong ứng dụng.', title_zh = '超市里的试探 🛒', body_zh = '快到收银台时，购物车里冒出了3种你没挑过的巧克力。宝宝在测试你的边界。迅速出手把它们放回去。至于健忘，眼睛要一直盯着应用里的购物清单。' WHERE id = 'b20bcc48-1ecb-4706-9d32-0f8329c7cd46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Servirte el café y bebértelo helado 3 horas después es la ley oficial de la maternidad. ¡Pero hoy haz algo distinto! Déjale a solas con sus dibujos favoritos y tómate ese café caliente. No eres un robot, tienes derecho a descansar.', body_fr = 'Se servir un café et le boire glacé 3 heures plus tard, c''est la loi officielle de la maternité. Mais aujourd''hui, changez les règles ! Laissez-le en tête-à-tête avec son dessin animé préféré et buvez ce café bien chaud. Vous n''êtes pas un robot, vous avez droit au repos.', body_hi = 'कॉफ़ी बनाकर 3 घंटे बाद बर्फ़ जैसी ठंडी पीना माँ बनने का आधिकारिक नियम है। पर आज कुछ अलग कीजिए! उसे उसके पसंदीदा कार्टून के साथ छोड़िए और वह कॉफ़ी गरम-गरम पीजिए। आप रोबोट नहीं हैं, आराम आपका हक है।', body_id = 'Menuang kopi lalu meminumnya sedingin es 3 jam kemudian adalah hukum resmi menjadi ibu. Tapi hari ini buatlah perbedaan! Biarkan ia berdua dengan kartun favoritnya, dan minum kopi itu selagi panas. Anda bukan robot, Anda berhak beristirahat.', body_ja = 'コーヒーをいれて、3時間後に氷のように冷めてから飲むのは、ママ業の公式ルール。でも今日はちがうことをしましょう！大好きなアニメにこの子をまかせて、そのコーヒーを温かいうちに飲んで。あなたはロボットではありません。休む権利があります。', body_ko = '커피를 따라 놓고 3시간 뒤 얼음처럼 식은 걸 마시는 건 엄마들의 공식 법칙이죠. 하지만 오늘은 다르게 해 보세요! 아이에게 좋아하는 만화를 틀어 주고 그 커피를 따뜻할 때 마시세요. 엄마는 로봇이 아니에요, 쉴 권리가 있어요.', body_nl = 'Koffie inschenken en die 3 uur later ijskoud opdrinken is de officiële wet van het moederschap. Maar doe het vandaag anders! Laat hem even alleen met zijn lievelingstekenfilm en drink die koffie warm. Je bent geen robot, je hebt recht op rust.', body_pl = 'Zaparzyć kawę i wypić ją 3 godziny później lodowatą to oficjalne prawo macierzyństwa. Ale dziś zrób wyjątek! Zostaw go sam na sam z ulubioną bajką i wypij tę kawę gorącą. Nie jesteś robotem, masz prawo do odpoczynku.', body_pt = 'Servir o café e bebê-lo gelado 3 horas depois é a lei oficial da maternidade. Mas hoje faça diferente! Deixe-o a sós com os desenhos animados preferidos e beba esse café quente. Não é um robô, tem direito a descansar.', body_sv = 'Att hälla upp kaffe och dricka det iskallt 3 timmar senare är moderskapets officiella lag. Men gör ett undantag i dag! Lämna barnet ensamt med favoritfilmen och drick kaffet medan det är varmt. Du är ingen robot, du har rätt till vila.', body_vi = 'Pha cà phê rồi 3 tiếng sau uống nguội ngắt là "luật chính thức" của việc làm mẹ. Nhưng hôm nay hãy làm khác đi! Để bé xem bộ phim hoạt hình yêu thích, còn mẹ uống cà phê khi còn nóng. Mẹ không phải là robot, mẹ có quyền được nghỉ ngơi.', body_zh = '倒好咖啡，3小时后再喝冰凉的，是当妈妈的“官方法则”。不过今天换个做法吧！让宝宝和最爱的动画片待在一起，你趁热把那杯咖啡喝完。你不是机器人，你有权利休息。' WHERE id = '229bf8d4-9bef-44e1-90de-84a850188af4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El silencio digital del Medidor de sonido 🤫', body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro se recupera poco a poco.', title_fr = 'Le silence numérique du Sonomètre 🤫', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau récupérer peu à peu.', title_hi = 'साउंड मीटर की डिजिटल खामोशी 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे ठीक हो रहा है।', title_id = 'Hening digital Pengukur Suara 🤫', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan secara visual bagaimana otak Anda perlahan pulih.', title_ja = 'サウンドメーターのデジタルな静けさ 🤫', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ回復していくのを目で感じてみましょう。', title_ko = '소음 측정기의 디지털 고요 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 회복되는 걸 눈으로 느껴 보세요.', title_nl = 'De digitale stilte van de Geluidsmeter 🤫', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam herstelt.', title_pl = 'Cyfrowa cisza w Mierniku dźwięku 🤫', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli dochodzi do siebie.', title_pt = 'O silêncio digital do Medidor de Som 🤫', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta visualmente o seu cérebro a recuperar devagarinho.', title_sv = 'Ljudmätarens digitala tystnad 🤫', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du visuellt hur hjärnan sakta återhämtar sig.', title_vi = 'Sự im lặng kỹ thuật số của Đo âm thanh 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần hồi phục.', title_zh = '分贝仪的数字安静 🤫', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，直观地感受大脑正在一点点恢复。' WHERE id = '78ebbc01-68e9-48f1-b518-6ad7212482ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Yo soy tu mamá! 👩‍👧', body_es = '¡Ha empezado el juego del cambio de papeles! Te da órdenes: «Ven aquí, métete en la cama, no llores». Acepta encantada esta experiencia de liderazgo y haz de su niña sin rechistar: así se desarrolla la empatía.', title_fr = 'C''est moi ta maman ! 👩‍👧', body_fr = 'Le jeu de l''inversion des rôles a commencé ! Il vous donne des ordres : « Viens ici, va au lit, pleure pas ! » Accueillez avec grand plaisir cette expérience de chef et jouez sans broncher le rôle de son enfant : c''est ainsi que se développe l''empathie.', title_hi = 'मैं तुम्हारी माँ हूँ! 👩‍👧', body_hi = 'भूमिका बदलने का खेल शुरू हो गया! वह आपको ‘इधर आओ, बिस्तर में जाओ, रोओ मत’ जैसे आदेश दे रहा है। उसके इस नेतृत्व के अभ्यास को बड़े मज़े से स्वीकार कीजिए और चुपचाप उसके बच्चे की भूमिका निभाइए, यही सहानुभूति का विकास है।', title_id = 'Aku mamamu! 👩‍👧', body_id = 'Permainan tukar peran dimulai! Ia memberi Anda perintah: ''Sini, naik ke tempat tidur, jangan menangis''. Terima pengalaman memimpinnya ini dengan senang hati dan mainkan peran sebagai anaknya tanpa membantah, inilah perkembangan empati.', title_ja = 'わたしがあなたのママよ！ 👩‍👧', body_ja = '役割交代ごっこが始まりました！「ここにおいで、ベッドに入って、泣かないの」とあなたに指示を出しています。このリーダー体験を楽しく受け入れて、黙ってこの子の子ども役を演じましょう。これが思いやりの発達です。', title_ko = '내가 엄마야! 👩‍👧', body_ko = '역할 바꾸기 놀이가 시작됐어요! ''이리 와, 침대에 누워, 울지 마''라며 엄마에게 지시하나요? 이 리더십 체험을 즐겁게 받아들이고 조용히 아이 역할을 해 주세요. 이것이 공감 능력의 발달이에요.', title_nl = 'Ik ben jouw mama! 👩‍👧', body_nl = 'Het rollenspel is begonnen! Hij geeft jou opdrachten: ''Kom hier, ga in bed liggen, niet huilen!'' Geniet volop van zijn leiderschap en speel zonder morren de rol van zijn kind: zo ontwikkelt hij empathie.', title_pl = 'Jestem twoją mamą! 👩‍👧', body_pl = 'Zaczęła się zabawa w zamianę ról! Wydaje ci polecenia: „Chodź tu, wejdź do łóżka, nie płacz”. Przyjmij jego doświadczenie w roli lidera z wielką przyjemnością i bez sprzeciwu zagraj jego dziecko, to rozwój empatii.', title_pt = 'Eu sou a tua mãe! 👩‍👧', body_pt = 'Começou o jogo da troca de papéis! Ele dá-lhe ordens: "Anda cá, vai para a cama, não chores". Aceite com muito gosto esta experiência de liderança e faça de criança dele, sem refilar: isto é desenvolvimento da empatia.', title_sv = 'Jag är din mamma! 👩‍👧', body_sv = 'Rollbyteslek har börjat! Barnet kommenderar dig: ”Kom hit, gå och lägg dig, gråt inte.” Ta emot barnets ledarerfarenhet med stor förtjusning och spela tyst barnets barn, det är empatiutveckling.', title_vi = 'Mẹ là mẹ của con đấy! 👩‍👧', body_vi = 'Trò chơi đổi vai đã bắt đầu! Bé ra lệnh cho mẹ: "Lại đây, lên giường đi, đừng khóc!". Hãy vui vẻ đón nhận trải nghiệm làm "thủ lĩnh" này của bé và ngoan ngoãn đóng vai con của bé, đó chính là sự phát triển lòng đồng cảm.', title_zh = '我是你妈妈！👩‍👧', body_zh = '角色互换游戏开始了！宝宝对你发号施令：“过来，上床去，别哭。”开开心心地接受宝宝这次当领导的体验，乖乖地扮演宝宝的“孩子”吧，这就是共情的发展。' WHERE id = '83129caa-97cc-414e-93e5-8bffa69fcbb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación vitaminas secretas 🥣', body_es = 'La comida que hasta ayer le encantaba hoy no hay manera de que la pruebe. No luches contra su voluntad. Usa en Recetas saludables recetas de tentempiés que den a las proteínas formas diferentes, coloridas e interesantes, y gana tú.', title_fr = 'Opération vitamines cachées 🥣', body_fr = 'Le plat qu''il adorait encore hier, impossible de le lui faire goûter aujourd''hui. Ne luttez pas contre sa volonté. Essayez dans les Recettes saines des collations qui donnent aux protéines des formes différentes, colorées et amusantes, et c''est vous qui gagnerez.', title_hi = 'छिपे विटामिनों का ऑपरेशन 🥣', body_hi = 'कल तक जो खाना पसंद था, आज उसे मुँह तक नहीं लगाता। उसकी इच्छा से मत लड़िए। सेहतमंद रेसिपी में प्रोटीन को अलग, रंगीन और दिलचस्प आकार देने वाली स्नैक रेसिपी आज़माइए और जीत आपकी हो।', title_id = 'Operasi vitamin tersembunyi 🥣', body_id = 'Makanan yang sampai kemarin ia suka, hari ini sama sekali tak mau ia makan. Jangan melawan kemauannya. Terapkan resep camilan di Resep Sehat yang mengubah protein menjadi bentuk berbeda, berwarna, dan menarik, dan jadilah pemenangnya.', title_ja = 'こっそりビタミン作戦 🥣', body_ja = '昨日まで大好きだった料理を、今日はひと口も食べない。意志と戦わないで。「ヘルシーレシピ」で、たんぱく質をカラフルで楽しい形に変えるおやつのレシピを試して、勝ちをつかみましょう。', title_ko = '비밀 비타민 작전 🥣', body_ko = '어제까지 좋아하던 음식을 오늘은 입에도 대지 않나요? 의지와 싸우지 마세요. 건강한 레시피에서 단백질을 색다르고 알록달록하고 재미있는 모양으로 바꾸는 간식 레시피를 활용해 승자가 되세요.', title_nl = 'Operatie verborgen vitamines 🥣', body_nl = 'Het eten waar hij tot gisteren dol op was, wil hij vandaag niet eens proeven. Vecht niet tegen zijn wil. Probeer de snackrecepten uit Gezonde recepten die eiwitten in andere, kleurrijke en leuke vormen gieten, en win.', title_pl = 'Tajna operacja witaminy 🥣', body_pl = 'Jedzenia, które jeszcze wczoraj uwielbiał, dziś nie chce tknąć. Nie walcz z jego wolą. Wypróbuj ze Zdrowych przepisów przekąski, które nadadzą białku inne, kolorowe i ciekawe kształty, i to ty wygrywasz.', title_pt = 'Operação vitaminas escondidas 🥣', body_pt = 'A comida de que gostava até ontem, hoje nem a deixa chegar à boca. Não lute contra a vontade dele. Experimente nas Receitas Saudáveis snacks que dão às proteínas formas diferentes, coloridas e interessantes, e seja a mãe a ganhar.', title_sv = 'Operation hemliga vitaminer 🥣', body_sv = 'Maten som barnet älskade fram till i går får du i dag inte ens i barnets mun. Kämpa inte mot barnets vilja. Använd mellanmålsrecept från Hälsosamma recept som ger proteinerna nya, färgglada och spännande former, och vinn.', title_vi = 'Chiến dịch vitamin bí mật 🥣', body_vi = 'Món đến hôm qua bé còn thích, hôm nay mẹ lại không cho bé ăn nổi một miếng. Đừng đấu với ý chí của bé. Hãy áp dụng trong Công thức lành mạnh những công thức món ăn nhẹ biến chất đạm thành những hình dạng khác lạ, nhiều màu sắc, thú vị và giành chiến thắng.', title_zh = '秘密维生素行动 🥣', body_zh = '直到昨天还喜欢的食物，今天碰都不肯碰。别和宝宝的意志较劲。用上健康食谱里那些把蛋白质做成不同、彩色又有趣造型的小零食，赢下这一局吧。' WHERE id = '257a6a67-1139-417f-a422-373f16be4a85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mi juguete está malito 🩺', body_es = 'Coge su estetoscopio de juguete, examina muy en serio a su osito y le pone una tirita. A través del juego simbólico procesa la compasión y el mundo. Únete al juego haciendo de paciente en el hospital.', title_fr = 'Mon jouet est malade 🩺', body_fr = 'Avec son stéthoscope en plastique, il examine très sérieusement son nounours et lui colle un pansement. À travers le jeu symbolique, il apprivoise la compassion et le monde. Entrez dans le jeu en jouant le rôle d''un patient à l''hôpital.', title_hi = 'मेरा खिलौना बीमार है 🩺', body_hi = 'खिलौने वाला स्टेथोस्कोप लेकर अपने टेडी की गंभीरता से जाँच करता है और उसे बैंडेज लगाता है। प्रतीकात्मक खेलों के ज़रिए वह दया और दुनिया को समझ रहा है। आप भी अस्पताल में मरीज़ की भूमिका निभाकर खेल में शामिल हो जाइए।', title_id = 'Mainanku sakit 🩺', body_id = 'Ia mengambil stetoskop mainan, memeriksa beruangnya dengan serius, lalu menempelkan plester. Lewat permainan simbolis, ia mengolah rasa kasih sayang dan dunia. Ikutlah bermain dengan memerankan pasien di rumah sakitnya.', title_ja = 'おもちゃが病気なの 🩺', body_ja = 'おもちゃの聴診器でくまさんを真剣に診察して、絆創膏を貼ってあげている。象徴遊びを通して、思いやりと世界を整理しているんです。あなたも病院の患者さん役になって、遊びに加わりましょう。', title_ko = '내 장난감이 아파요 🩺', body_ko = '장난감 청진기로 곰 인형을 진지하게 진찰하고 반창고를 붙여 주나요? 상징 놀이로 다정함과 세상을 소화하는 중이에요. 엄마도 병원의 환자 역할을 맡아 놀이에 함께하세요.', title_nl = 'Mijn knuffel is ziek 🩺', body_nl = 'Hij pakt zijn speelgoedstethoscoop, onderzoekt heel serieus zijn beertje en plakt er een pleister op. Via symbolisch spel verwerkt hij medeleven en de wereld. Doe mee en speel een patiënt in zijn ziekenhuis.', title_pl = 'Moja zabawka jest chora 🩺', body_pl = 'Bierze zabawkowy stetoskop, z powagą bada misia i przykleja mu plasterek. Przez zabawę symboliczną przetwarza współczucie i świat. Dołącz do zabawy w roli pacjenta w jego szpitalu.', title_pt = 'O meu brinquedo está doente 🩺', body_pt = 'Pega no estetoscópio de brincar, examina o ursinho muito a sério e põe-lhe um penso. Através do jogo simbólico, processa a compaixão e o mundo. Entre também no jogo, no papel de paciente do hospital.', title_sv = 'Min leksak är sjuk 🩺', body_sv = 'Barnet tar sitt leksaksstetoskop, undersöker nallen på största allvar och sätter ett plåster på den. Genom symbolisk lek bearbetar barnet medkänsla och världen. Häng med i leken och spela patient på sjukhuset.', title_vi = 'Đồ chơi của con bị ốm 🩺', body_vi = 'Bé cầm ống nghe đồ chơi, nghiêm túc khám cho gấu bông và dán băng cá nhân cho bạn ấy. Qua trò chơi biểu tượng, bé đang học về lòng trắc ẩn và thế giới. Mẹ cũng hãy tham gia bằng cách đóng vai bệnh nhân ở "bệnh viện" của bé.', title_zh = '我的玩具生病了 🩺', body_zh = '拿起玩具听诊器，认真地给小熊做检查，还给它贴上创可贴。宝宝通过象征性游戏来理解同情心和这个世界。你也扮演医院里的一位病人，加入游戏吧。' WHERE id = 'e8a36b6d-250c-4114-bd67-1068cf626c68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Soñar con Cuentos inteligentes 🪄', body_es = 'Te sabes de memoria los libros de siempre. Abre Cuentos inteligentes, diseña una historia con tu peque como protagonista y su habitación como el lugar por conquistar, y crea una sesión de sueño sonora y original que no exige ningún esfuerzo.', title_fr = 'Rêver avec les Contes intelligents 🪄', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents : faites de votre enfant le héros et de sa chambre le territoire à conquérir, et créez une séance d''endormissement sonore originale qui ne demande aucun effort.', title_hi = 'स्मार्ट कहानियों के साथ सपने 🪄', body_hi = 'पुरानी किताबें आपको रट चुकी हैं। स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाकर एक अनोखा, बिना मेहनत वाला आवाज़ों भरा नींद का सत्र बनाइए।', title_id = 'Khayalan bersama Dongeng Pintar 🪄', body_id = 'Anda sudah hafal buku-buku klasik. Buka Dongeng Pintar, jadikan anak Anda tokoh utamanya dan kamarnya sendiri sebagai tempat yang akan ditaklukkan, lalu ciptakan sesi tidur bersuara yang tidak biasa tanpa usaha apa pun.', title_ja = 'スマートおはなしで空想の世界へ 🪄', body_ja = '定番の絵本はもう暗記してしまいましたね。「スマートおはなし」を開いて、主人公はお子さん、征服する場所はこの子の部屋にして、いつもとちがう、まったく手間のかからない音声の寝かしつけタイムをつくりましょう。', title_ko = '스마트 동화와 꿈나라 🪄', body_ko = '늘 읽던 책은 다 외웠나요? 스마트 동화를 열고 주인공은 아이로, 정복할 장소는 아이의 방으로 정해 특별하고 힘들이지 않는 소리 잠자리 시간을 만들어 보세요.', title_nl = 'Dromen met Slimme sprookjes 🪄', body_nl = 'Je kent de klassieke boeken uit je hoofd. Open Slimme sprookjes, maak je kind de hoofdpersoon en zijn kamer het land dat veroverd moet worden, en creëer een bijzondere luistersessie om in slaap te vallen die je geen moeite kost.', title_pl = 'Marzenia z Mądrymi bajkami 🪄', body_pl = 'Klasyczne książeczki znasz już na pamięć. Otwórz Mądre bajki, uczyń głównym bohaterem swoje dziecko, a krainą do podbicia jego pokój, i stwórz niezwykły dźwiękowy seans usypiania, który nie wymaga żadnego wysiłku.', title_pt = 'Sonhos com as Histórias Inteligentes 🪄', body_pt = 'Já sabe os livros clássicos de cor. Abra as Histórias Inteligentes, crie uma história com o seu filho como herói principal e o quarto dele como terra a conquistar, e prepare uma sessão de sono sonora fora do comum, sem esforço nenhum.', title_sv = 'Drömmar med Smarta sagor 🪄', body_sv = 'Du kan de klassiska böckerna utantill. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska erövras, och skapa en ovanlig ljudsovstund som inte kräver någon ansträngning.', title_vi = 'Giấc mơ cùng Truyện cổ tích thông minh 🪄', body_vi = 'Mẹ đã thuộc lòng những cuốn sách quen thuộc. Hãy mở Truyện cổ tích thông minh, thiết kế một buổi ru ngủ bằng âm thanh khác lạ, chẳng tốn chút công sức: bé là nhân vật chính, còn vùng đất cần chinh phục chính là căn phòng của bé.', title_zh = '和智慧童话一起做梦 🪄', body_zh = '经典故事书你都背熟了。打开智慧童话，把宝宝设计成主角，把要征服的地方设定为宝宝的房间，打造一场不寻常、毫不费力的有声哄睡时光。' WHERE id = 'fc4c9174-8969-47bc-b1ba-7be545e849f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesiones en el Diario de ánimo 📝', body_es = '¿Nadie ve lo cansada que estás en casa? El Diario de ánimo es tu confidente más silencioso. Escribe ahí todos los detalles que hoy te han sacado de quicio y mira en la pantalla cómo se aligera tu mente y cómo se van volando las penas.', title_fr = 'Confidences au Journal d''humeur 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée à la maison ? Le Journal d''humeur est votre confident le plus discret. Écrivez-y tous les détails qui vous ont rendue folle aujourd''hui et voyez à l''écran votre esprit s''alléger et vos soucis s''envoler.', title_hi = 'मूड डायरी के इकरार 📝', body_hi = 'किसी को नहीं दिखता कि आप घर में कितना थकती हैं? मूड डायरी आपकी सबसे खामोश राज़दार है। आज जिन बातों ने आपको पागल किया, सब वहाँ लिखिए और स्क्रीन देखते हुए महसूस कीजिए कि दिमाग कैसे हल्का होता है और परेशानियाँ कैसे उड़ जाती हैं।', title_id = 'Pengakuan di Buku Harian Suasana Hati 📝', body_id = 'Tak ada yang melihat betapa lelahnya Anda di rumah? Buku Harian Suasana Hati adalah teman curhat Anda yang paling diam. Tuliskan di sana semua detail yang membuat Anda gila hari ini, lalu lihat di layar betapa ringannya pikiran Anda dan bagaimana beban itu terbang pergi.', title_ja = '「気分日記」での打ち明け話 📝', body_ja = '家であなたがどれほど疲れているか、誰も気づいてくれない？「気分日記」は、いちばん静かな打ち明け相手です。今日あなたをいらだたせたことを全部書いて、頭がどれほど軽くなり、悩みがどれほど飛んでいくかを画面で確かめて。', title_ko = '기분 일기 속 고백 📝', body_ko = '집에서 얼마나 지쳤는지 아무도 몰라주나요? 기분 일기는 가장 조용한 비밀 친구예요. 오늘 나를 미치게 한 모든 일을 적고, 화면을 보며 머리가 가벼워지고 걱정이 날아가는 걸 느껴 보세요.', title_nl = 'Bekentenissen in je Stemmingsdagboek 📝', body_nl = 'Ziet niemand hoe moe je thuis bent? Je Stemmingsdagboek is je stilste vertrouweling. Schrijf daar alle details op die je vandaag gek maakten en zie op het scherm hoe je hoofd lichter wordt en je zorgen wegvliegen.', title_pl = 'Wyznania w Dzienniku nastroju 📝', body_pl = 'Nikt nie widzi, jak bardzo męczysz się w domu? Dziennik nastroju to twój najcichszy powiernik. Zapisz w nim wszystkie szczegóły, które dziś doprowadziły cię do szału, i zobacz na ekranie, jak lżej robi się w głowie, a zmartwienia odlatują.', title_pt = 'Confissões no Diário de Humor 📝', body_pt = 'Ninguém vê o quanto se cansa em casa? O Diário de Humor é o seu confidente mais silencioso. Escreva lá todos os pormenores que hoje a deixaram louca e veja no ecrã como o seu cérebro fica mais leve e as mágoas desaparecem.', title_sv = 'Bekännelser i Humördagboken 📝', body_sv = 'Ser ingen hur trött du är hemma? Humördagboken är din tystaste förtrogna. Skriv ner alla detaljer som gjorde dig galen i dag och se på skärmen hur hjärnan blir lättare och bekymren flyger iväg.', title_vi = 'Lời thú nhận trong Nhật ký tâm trạng 📝', body_vi = 'Không ai thấy mẹ mệt mỏi thế nào khi ở nhà? Nhật ký tâm trạng là người bạn tâm giao lặng lẽ nhất của mẹ. Hãy viết vào đó mọi chi tiết khiến mẹ phát điên hôm nay và nhìn màn hình để thấy đầu óc nhẹ nhõm hơn, nỗi buồn bay đi thế nào.', title_zh = '心情日记里的心里话 📝', body_zh = '没人看见你在家有多累？心情日记是你最安静的知心朋友。把今天让你抓狂的所有细节都写进去，看着屏幕，感受大脑如何变得轻松，烦恼如何飞走。' WHERE id = '3bc4e55a-369a-4bca-8a42-e2a95a607168' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas sin lógica ☀️', body_es = '¿Ha llorado a lágrima viva diciendo «el sol me mira a los ojos»? No busques lógica. Para él es una tristeza realmente profunda: se enfada porque no puede controlar el mundo. Simplemente valida su emoción diciendo: «He corrido la cortina y he escondido el sol».', title_fr = 'Des larmes sans logique ☀️', body_fr = 'Il a éclaté en sanglots parce que « le soleil me regarde dans les yeux » ? Ne cherchez pas de logique. Pour lui, c''est un vrai et profond chagrin : il est en colère de ne pas pouvoir contrôler le monde. Validez simplement son émotion : « J''ai tiré le rideau, j''ai caché le soleil. »', title_hi = 'बेतुके आँसू ☀️', body_hi = '‘सूरज मेरी आँख में देख रहा है’ कहकर फूट-फूटकर रोया? यहाँ तर्क मत ढूँढिए। उसके लिए यह सच में गहरा दुख है, वह इस बात पर गुस्सा है कि दुनिया उसके बस में नहीं। ‘पर्दा खींचकर सूरज को छिपा दिया’ कहकर बस उसकी भावना को मान दीजिए।', title_id = 'Air mata tanpa logika ☀️', body_id = 'Ia menangis tersedu-sedu karena ''Mataharinya melihat mataku''? Jangan mencari logika. Baginya ini benar-benar kesedihan yang dalam, ia marah karena tidak bisa mengatur dunia. Cukup akui perasaannya dengan berkata ''Mama tutup gordennya, mataharinya sudah Mama sembunyikan''.', title_ja = '理屈のない涙 ☀️', body_ja = '「お日さまがこっちを見てる」と大泣き？そこに理屈を求めないで。この子にとっては本当に深い悲しみで、世界を思いどおりにできないことに怒っているんです。「カーテンを閉めて、お日さまを隠したよ」と言って、ただ気持ちを受けとめてあげましょう。', title_ko = '논리 없는 눈물 ☀️', body_ko = '''해가 나를 쳐다봐'' 하며 엉엉 울었나요? 논리를 찾지 마세요. 아이에게는 정말 깊은 슬픔이에요, 세상을 마음대로 할 수 없어 화가 나는 거죠. ''커튼 쳐서 해를 숨겨 줬어''라며 감정을 인정해 주세요.', title_nl = 'Onlogische tranen ☀️', body_nl = 'Huilde hij tranen met tuiten omdat ''de zon in zijn ogen kijkt''? Zoek er geen logica achter. Voor hem is dit echt diep verdriet, hij is boos dat hij de wereld niet kan besturen. Bevestig gewoon zijn gevoel: ''Ik heb het gordijn dichtgedaan en de zon verstopt.''', title_pl = 'Łzy bez logiki ☀️', body_pl = 'Rozpłakał się w głos, bo „słońce patrzy mi w oczy”? Nie szukaj w tym logiki. Dla niego to naprawdę głęboki smutek, złości się, że nie może rządzić światem. Po prostu uznaj jego emocje: „Zasłoniłam zasłonę i schowałam słońce”.', title_pt = 'Lágrimas sem lógica ☀️', body_pt = 'Chorou desalmadamente a dizer "O sol está a olhar para os meus olhos"? Não procure lógica. Para ele, é mesmo uma tristeza profunda: está zangado por não conseguir controlar o mundo. Corra a cortina, diga "Escondi o sol" e valide simplesmente a emoção dele.', title_sv = 'Ologiska tårar ☀️', body_sv = 'Grät barnet hejdlöst och sa ”Solen tittar på mitt öga”? Leta inte efter logik. För barnet är det verkligen en djup sorg, det är argt över att inte kunna styra världen. Dra för gardinen, säg ”Jag gömde solen” och bekräfta bara känslan.', title_vi = 'Những giọt nước mắt vô lý ☀️', body_vi = 'Bé khóc nức nở vì "mặt trời nhìn vào mắt con"? Đừng tìm logic ở đây. Với bé, đó thật sự là một nỗi buồn sâu sắc, bé tức giận vì không điều khiển được thế giới. Chỉ cần công nhận cảm xúc của bé: "Mẹ kéo rèm giấu mặt trời đi rồi nhé".', title_zh = '没有逻辑的眼泪 ☀️', body_zh = '哭着说“太阳看我的眼睛”？别在这里找逻辑。对宝宝来说，这真的是很深的难过，宝宝是在为没法掌控世界而生气。说一句“我拉上窗帘，把太阳藏起来了”，肯定宝宝的情绪就好。' WHERE id = 'be5cb204-e61d-452b-9a0e-bb977bd6249c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de soledad 🚪', body_es = 'El ruido te taladra el cerebro y te dan ganas de gritar por todo. Déjale en un lugar seguro, métete en el baño y cierra la puerta. Mira la pared solo 5 minutos sin hacer nada. Esta breve pausa te preparará de nuevo para tu papel de madre.', title_fr = 'Envie de solitude 🚪', body_fr = 'Le bruit vous transperce le cerveau, vous avez envie de crier sur tout. Mettez-le dans un endroit sûr, allez aux toilettes et fermez la porte. Regardez simplement le mur 5 minutes, sans rien faire. Cette courte pause vous préparera à reprendre votre rôle de maman.', title_hi = 'अकेलेपन की चाह 🚪', body_hi = 'शोर दिमाग में चुभ रहा है, हर बात पर चिल्लाने का मन है। उसे किसी सुरक्षित जगह पर रखिए, बाथरूम में जाकर दरवाज़ा बंद कीजिए। बस 5 मिनट दीवार को देखिए, कुछ मत कीजिए। यह छोटा ब्रेक आपको फिर से माँ की भूमिका के लिए तैयार करेगा।', title_id = 'Rindu menyendiri 🚪', body_id = 'Kebisingan menembus otak Anda, Anda ingin berteriak pada segala hal. Letakkan ia di tempat yang aman, masuk ke toilet, dan tutup pintunya. Tatap dinding 5 menit saja, jangan lakukan apa pun. Jeda singkat ini akan menyiapkan Anda kembali untuk peran sebagai ibu.', title_ja = 'ひとりになりたい 🚪', body_ja = '騒がしさが頭に突きささり、何にでも叫びたくなる。子どもを安全な場所に置いてトイレに入り、ドアを閉めましょう。5分だけ壁を見つめて、何もしないで。この短い休けいが、もう一度ママに戻る準備をしてくれます。', title_ko = '혼자 있고 싶은 마음 🚪', body_ko = '소음이 머리를 뚫고 모든 것에 소리치고 싶나요? 아이를 안전한 곳에 두고 화장실에 들어가 문을 닫으세요. 딱 5분만 벽을 보며 아무것도 하지 마세요. 이 짧은 쉼이 엄마를 다시 엄마 역할로 돌아갈 수 있게 해 줄 거예요.', title_nl = 'Verlangen naar alleen zijn 🚪', body_nl = 'Het lawaai boort door je hoofd en je wilt tegen alles schreeuwen. Zet hem op een veilige plek, ga naar de wc en doe de deur dicht. Kijk 5 minuten gewoon naar de muur en doe niets. Deze korte pauze maakt je weer klaar voor je rol als mama.', title_pl = 'Tęsknota za samotnością 🚪', body_pl = 'Hałas świdruje ci w głowie, chce ci się krzyczeć na wszystko. Zostaw go w bezpiecznym miejscu, wejdź do toalety i zamknij drzwi. Przez 5 minut po prostu patrz w ścianę i nic nie rób. Ta krótka przerwa znów przygotuje cię do roli mamy.', title_pt = 'Saudades de estar sozinha 🚪', body_pt = 'O barulho fura-lhe o cérebro e apetece-lhe gritar com tudo. Ponha-o num sítio seguro, entre na casa de banho e feche a porta. Olhe para a parede só 5 minutos, sem fazer nada. Esta pequena pausa vai prepará-la para voltar ao papel de mãe.', title_sv = 'Längtan efter ensamhet 🚪', body_sv = 'Oljudet borrar sig in i hjärnan och du vill skrika åt allt. Lägg barnet på ett säkert ställe, gå in på toaletten och stäng dörren. Stirra bara in i väggen i 5 minuter och gör ingenting. Den korta pausen förbereder dig för mammarollen igen.', title_vi = 'Khao khát được ở một mình 🚪', body_vi = 'Tiếng ồn như khoan vào đầu, mẹ muốn hét lên với mọi thứ. Hãy đặt bé ở chỗ an toàn, vào nhà vệ sinh và đóng cửa lại. Chỉ cần nhìn vào tường 5 phút, không làm gì cả. Khoảng nghỉ ngắn này sẽ giúp mẹ sẵn sàng trở lại vai trò làm mẹ.', title_zh = '渴望独处 🚪', body_zh = '噪音快把脑袋钻穿了，你看什么都想吼。把宝宝放在安全的地方，走进卫生间关上门。就盯着墙看5分钟，什么都别做。这短短的休息，会让你重新准备好回到妈妈的角色。' WHERE id = '05028726-3b26-4576-b76c-968926aa3c37' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ley de los pies descalzos 👣', body_es = 'Le encanta andar descalzo y tocar la alfombra, las piedras de la habitación o las baldosas frías. Estimular los nervios de la planta del pie es muy importante para su equilibrio y su desarrollo neurológico: mientras no tenga frío, no le impidas de ninguna manera andar sin calcetines.', title_fr = 'La loi des pieds nus 👣', body_fr = 'Il adore marcher pieds nus et toucher le tapis, les cailloux ou le carrelage froid. L''éveil des nerfs de la plante des pieds est très important pour son équilibre et son développement neurologique : tant qu''il n''a pas froid, ne l''empêchez surtout pas de marcher sans chaussettes.', title_hi = 'नंगे पैरों का नियम 👣', body_hi = 'नंगे पैर चलने, कालीन, कमरे के पत्थरों या ठंडी टाइलों को छूने में उसे मज़ा आता है। तलवों की नसों का जागना उसके संतुलन और तंत्रिका विकास के लिए बहुत ज़रूरी है, जब तक उसे ठंड न लगे, उसे बिना मोज़ों के चलने से बिल्कुल मत रोकिए।', title_id = 'Hukum telanjang kaki 👣', body_id = 'Ia senang berjalan tanpa alas kaki, menyentuh karpet, batu-batu di kamar, atau ubin yang dingin. Rangsangan saraf di telapak kaki sangat penting untuk keseimbangan dan perkembangan sarafnya, selama ia tidak kedinginan, jangan sekali-kali melarangnya berjalan tanpa kaus kaki.', title_ja = 'はだしのおきて 👣', body_ja = 'はだしで歩いて、じゅうたんや部屋の石、冷たいタイルにふれるのが大好き。足の裏の神経が目覚めることは、バランスと神経の発達にとってとても大切です。寒くないかぎり、靴下なしで歩くのを決してじゃましないで。', title_ko = '맨발의 법칙 👣', body_ko = '맨발로 걸으며 카펫, 방의 돌, 차가운 타일을 만지는 걸 좋아하나요? 발바닥 신경을 깨우는 건 균형 감각과 신경 발달에 아주 중요해요. 춥지 않다면 양말 없이 걷는 걸 절대 막지 마세요.', title_nl = 'De blotevoetenwet 👣', body_nl = 'Hij geniet ervan om op blote voeten te lopen en het tapijt, de steentjes of de koude tegels te voelen. Het prikkelen van de zenuwen onder zijn voeten is heel belangrijk voor zijn evenwicht en neurologische ontwikkeling, houd hem dus zeker niet tegen als hij zonder sokken wil lopen, zolang hij het niet koud krijgt.', title_pl = 'Prawo bosej stopy 👣', body_pl = 'Uwielbia chodzić boso, dotykać dywanu, kamyków na podłodze i zimnych kafelków. Pobudzanie nerwów na stopach jest bardzo ważne dla jego równowagi i rozwoju neurologicznego, dopóki nie marznie, nie przeszkadzaj mu chodzić bez skarpetek.', title_pt = 'A lei dos pés descalços 👣', body_pt = 'Adora andar descalço e tocar no tapete, nas pedras do quarto ou no azulejo frio. Estimular os nervos da planta dos pés é muito importante para o equilíbrio e o desenvolvimento neurológico: desde que não tenha frio, não o impeça de andar sem meias.', title_sv = 'Barfotalagen 👣', body_sv = 'Barnet njuter av att gå barfota och känna mattan, stenarna i rummet eller det kalla kaklet under fötterna. När nerverna under fötterna väcks är det väldigt viktigt för balansen och den neurologiska utvecklingen, så länge barnet inte fryser, hindra absolut inte barnet från att gå utan strumpor.', title_vi = 'Luật đi chân trần 👣', body_vi = 'Bé thích đi chân trần, cảm nhận tấm thảm, những viên sỏi hay sàn gạch mát lạnh. Việc kích thích các dây thần kinh ở lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng và sự phát triển thần kinh của bé, miễn là bé không bị lạnh, tuyệt đối đừng ngăn bé đi không tất.', title_zh = '光脚法则 👣', body_zh = '喜欢光着脚走路，喜欢触摸地毯、房间里的石头和冰凉的瓷砖。脚底神经被唤醒，对宝宝的平衡和神经发展非常重要，只要不着凉，千万别阻止宝宝不穿袜子走路。' WHERE id = '3d57cc08-81bc-4a6c-804c-4488f1dababe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando lo que haces ya no funciona, los ruidos de animales raros y las caras graciosas de papá salvan la situación al instante. En las crisis de la tarde, pásale la pelota enseguida y mira descansando desde fuera.', body_fr = 'Quand vos astuces ne marchent plus, les drôles de cris d''animaux et les grimaces de papa sauvent aussitôt la situation. Pendant les crises du soir, passez-lui vite le relais et regardez de loin en vous reposant.', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तब पापा की जानवरों जैसी अजीब आवाज़ें और मज़ेदार चेहरे हालात तुरंत सँभाल लेते हैं। शाम के बिगड़े मूड में ज़िम्मेदारी तुरंत उन्हें सौंप दीजिए और आराम करते हुए दूर से देखिए।', body_id = 'Saat cara Anda tak lagi berhasil, suara binatang yang aneh dan wajah lucu Ayah langsung menyelamatkan keadaan. Saat krisis sore hari, segera oper bolanya ke Ayah dan saksikan dari samping sambil beristirahat.', body_ja = 'あなたの手が通用しなくなったら、パパのへんてこな動物の鳴きまねやおどけた顔がすぐに状況を救ってくれます。夕方のぐずりタイムは、すぐにバトンをパパに渡して、そばで休みながら見守りましょう。', body_ko = '엄마의 방법이 더는 통하지 않을 때, 아빠의 이상한 동물 소리와 웃긴 표정이 바로 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기고 옆에서 쉬며 지켜보세요.', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke dierengeluiden en grappige gezichten meteen de situatie. Speel bij avondbuien de bal direct naar hem door en kijk ontspannen toe.', body_pl = 'Gdy twoje sposoby już nie działają, śmieszne zwierzęce odgłosy i miny taty od razu ratują sytuację. Podczas wieczornych kryzysów od razu przekaż mu pałeczkę i odpoczywaj, obserwując z boku.', body_pt = 'Quando os seus truques já não funcionam, os sons de animais estranhos e as caretas cómicas do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola de imediato e observe à distância, a descansar.', body_sv = 'När ditt eget inte längre fungerar räddar pappas konstiga djurläten och roliga miner situationen direkt. Vid kvällskriserna, skicka genast bollen till honom och vila medan du tittar på.', body_vi = 'Khi mọi chiêu của mẹ không còn hiệu quả, những tiếng kêu con vật kỳ quặc và gương mặt hài hước của bố sẽ cứu nguy ngay lập tức. Trong những cơn khủng hoảng buổi tối, hãy "chuyền bóng" ngay cho bố và nghỉ ngơi quan sát từ xa.', body_zh = '当你的办法都不管用时，爸爸学的奇怪动物叫声和搞怪表情马上就能化解局面。傍晚闹脾气时，赶紧把“球”传给爸爸，你在一旁休息着看就好。' WHERE id = '903639ea-1976-4233-a451-64887050fd95' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy cocino yo 🧑‍🍳', body_es = '¿Mientras extiendes la masa, se sube a una silla a tu lado y se mete en el proceso? En realidad no quiere ayudar, quiere estar en el centro mismo de la acción. Dale una bolita de masa. La cocina acabará hecha un desastre, pero su ego y su creatividad se harán gigantes.', title_fr = 'Aujourd''hui, c''est moi qui cuisine 🧑‍🍳', body_fr = 'Quand vous étalez la pâte, il installe forcément une chaise à côté de vous pour s''en mêler ? En réalité, il ne veut pas tant aider qu''être au cœur même de l''action. Donnez-lui un petit pâton. La cuisine sera sens dessus dessous, mais son ego et sa créativité deviendront immenses.', title_hi = 'आज खाना मैं बनाऊँगा 🧑‍🍳', body_hi = 'आप आटा बेलती हैं तो वह ज़रूर पास में कुर्सी लगाकर काम में हाथ डालता है? असल में वह मदद नहीं, काम के ठीक बीचोंबीच रहना चाहता है। उसे आटे की एक छोटी लोई दीजिए। रसोई गंदी होगी, पर उसका आत्मविश्वास और रचनात्मकता आसमान छू लेंगे।', title_id = 'Hari ini aku yang masak 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia pasti menaruh kursi di samping dan ikut campur? Sebenarnya ia bukan ingin membantu, tapi ingin berada tepat di pusat kegiatan. Beri ia sejumput kecil adonan. Dapur akan berantakan, tapi ego dan kreativitasnya akan tumbuh besar.', title_ja = '今日はぼくが作る 🧑‍🍳', body_ja = 'あなたが生地をのばしていると、必ずそばにいすを持ってきて手を出してきます。本当はお手伝いではなく、その場のど真ん中にいたいんです。小さな生地のかたまりを渡しましょう。キッチンは粉だらけになるけれど、この子の自信と創造力はぐんと大きくなります。', title_ko = '오늘은 내가 요리사 🧑‍🍳', body_ko = '반죽을 밀 때 꼭 옆에 의자를 놓고 끼어드나요? 사실 돕기보다는 일의 한가운데에 있고 싶은 거예요. 작은 반죽 덩어리를 하나 주세요. 부엌은 엉망이 되겠지만 아이의 자존감과 창의력은 쑥쑥 자랄 거예요.', title_nl = 'Vandaag kook ik 🧑‍🍳', body_nl = 'Zet hij als jij deeg uitrolt per se een stoel ernaast en bemoeit hij zich ermee? Eigenlijk wil hij niet helpen, maar helemaal midden in de actie zijn. Geef hem een klein bolletje deeg. De keuken wordt een zooi, maar zijn ego en creativiteit groeien enorm.', title_pl = 'Dziś ja gotuję 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, koniecznie przystawia obok krzesło i wtrąca się w pracę? Tak naprawdę nie chce pomagać, tylko być w samym centrum wydarzeń. Daj mu mały kawałek ciasta. Kuchnia będzie w opłakanym stanie, ale jego ego i kreatywność urosną do wielkich rozmiarów.', title_pt = 'Hoje cozinho eu 🧑‍🍳', body_pt = 'Enquanto estende a massa, ele põe uma cadeira ao seu lado e mete-se no processo? Na verdade não quer ajudar, quer estar mesmo no centro do processo. Dê-lhe uma bolinha de massa. A cozinha vai ficar um caos, mas o ego e a criatividade dele vão ficar gigantes.', title_sv = 'I dag lagar jag mat 🧑‍🍳', body_sv = 'Ställer barnet absolut en stol bredvid dig och lägger sig i när du kavlar deg? Egentligen vill barnet inte hjälpa till, utan vara mitt i centrum av det som händer. Ge barnet en liten degklump. Köket blir nedkladdat, men barnets ego och kreativitet växer sig enorma.', title_vi = 'Hôm nay con nấu ăn 🧑‍🍳', body_vi = 'Khi mẹ cán bột, bé nhất định kê ghế đứng cạnh và "nhúng tay" vào? Thật ra bé không muốn giúp, mà muốn được ở ngay trung tâm của mọi việc. Hãy đưa bé một nắm bột nhỏ. Căn bếp sẽ bừa bộn, nhưng cái tôi và sự sáng tạo của bé sẽ lớn bổng lên.', title_zh = '今天我来做饭 🧑‍🍳', body_zh = '你擀面团时，宝宝非要搬张椅子到旁边“参与”？其实宝宝不是想帮忙，而是想成为整件事的正中心。给宝宝一小团面吧。厨房会被弄得一团糟，但宝宝的自信和创造力会变得超级强大。' WHERE id = '4cb1e963-5e79-4f65-b536-3c251c29e851' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Registro de palabras nuevas 📈', body_es = 'Pone a las cosas nombres nuevos inventados por él que no existen en ningún idioma. ¡Y exige que tú también uses esa palabra! Abre el Seguimiento del desarrollo y archiva sin falta estas palabras tan cómicas para leerlas en el futuro y reírte.', title_fr = 'Noter les nouveaux mots 📈', body_fr = 'Il donne aux objets des noms tout neufs qu''il a inventés, qui n''existent dans aucune langue. Et il exige que vous les utilisiez aussi ! Ouvrez le Suivi de développement et archivez absolument ces mots comiques pour les relire plus tard en riant.', title_hi = 'नए शब्दों का रिकॉर्ड 📈', body_hi = 'चीज़ों को अपने गढ़े, किसी भाषा में न होने वाले नए नाम देता है। और ज़िद करता है कि आप भी वही शब्द बोलें! ग्रोथ ट्रैकर खोलिए और उसके इन मज़ेदार शब्दों को ज़रूर सँजोकर रखिए, ताकि आगे पढ़कर हँस सकें।', title_id = 'Mencatat kata-kata baru 📈', body_id = 'Ia memberi benda-benda nama baru karangannya sendiri yang tidak ada dalam bahasa mana pun. Dan ia bersikeras Anda juga harus memakai kata itu! Buka Pelacak Perkembangan dan pastikan mengarsipkan kata-kata lucunya agar kelak bisa dibaca sambil tertawa.', title_ja = '新しい言葉の記録 📈', body_ja = 'ものに、どの言語にもない自分で考えた新しい名前をつけている。しかも、あなたにもその言葉を使うよう強く求めてくる！「発達トラッカー」を開いて、このおかしな言葉を、将来読み返して笑えるようにぜひ保存しておきましょう。', title_ko = '새로운 단어 기록 📈', body_ko = '어떤 언어에도 없는, 자기가 지어낸 새 이름을 물건에 붙이고 엄마도 그 말을 쓰라고 고집하나요! 성장 기록을 열고 나중에 읽으며 웃을 수 있게 이 웃긴 단어들을 꼭 보관해 두세요.', title_nl = 'Nieuwe woordjes vastleggen 📈', body_nl = 'Hij geeft dingen nieuwe namen die hij zelf verzint en die in geen enkele taal bestaan. En hij wil per se dat jij die woorden ook gebruikt! Open de Groeitracker en archiveer deze grappige woorden zeker, zodat je ze later kunt teruglezen en erom kunt lachen.', title_pl = 'Zapisujemy nowe słowa 📈', body_pl = 'Nadaje rzeczom zupełnie nowe, wymyślone nazwy, których nie ma w żadnym języku. I uparcie wymaga, żebyś też ich używała! Otwórz Śledzenie rozwoju i koniecznie zarchiwizuj te zabawne słowa, żeby kiedyś je przeczytać i się pośmiać.', title_pt = 'Registo de palavras novas 📈', body_pt = 'Dá às coisas nomes novos, inventados por ele, que não existem em língua nenhuma. E insiste que também os use! Abra o Registo de Crescimento e não deixe de arquivar estas palavras cómicas para as ler e rir no futuro.', title_sv = 'Anteckna nya ord 📈', body_sv = 'Barnet ger saker helt egna, påhittade namn som inte finns på något språk. Och kräver envist att du också använder ordet! Öppna Utvecklingsspåraren och spara absolut de roliga orden, så att ni kan läsa och skratta åt dem i framtiden.', title_vi = 'Ghi lại những từ mới 📈', body_vi = 'Bé đặt cho đồ vật những cái tên mới hoàn toàn do mình nghĩ ra, chẳng có trong ngôn ngữ nào. Và còn bắt mẹ phải dùng những từ đó! Hãy mở Theo dõi phát triển và nhất định lưu lại những từ ngộ nghĩnh này để sau này đọc lại và bật cười.', title_zh = '记录新词 📈', body_zh = '给东西起了完全是自己发明的、任何语言里都没有的新名字。还坚持要你也用那个词！打开发育追踪，一定要把这些搞笑的词存档，将来读起来乐一乐。' WHERE id = '7f5013df-f5cb-4869-9600-c6ec01184189' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces sobrantes y las pantallas de las tabletas de la habitación 1 hora antes de dormir. La melatonina solo se libera rápido en un ambiente oscuro y sin tecnología, y asegura el paso al sueño.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre 1 heure avant le coucher. La mélatonine n''est sécrétée rapidement que dans le noir et sans écran, ce qui assure le passage au sommeil.', body_hi = 'उसे जल्दी नींद आए, इसके लिए सोने से 1 घंटा पहले कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीनें बंद कर दीजिए। मेलाटोनिन सिर्फ़ अँधेरे और बिना तकनीक वाले माहौल में तेज़ी से बनता है और नींद में जाना पक्का करता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar 1 jam sebelum tidur. Melatonin hanya diproduksi dengan cepat di lingkungan yang gelap dan bebas teknologi, sehingga peralihan ke tidur lebih terjamin.', body_ja = '早く寝つけるように、寝る1時間前に部屋の余分な明かりやタブレットの画面をすべて消しましょう。メラトニンは暗くてデジタル機器のない環境でこそすばやく分泌され、眠りへの切りかえを確かなものにしてくれます。', body_ko = '더 빨리 잠들 수 있게 자기 1시간 전에 방의 불필요한 조명과 태블릿 화면을 모두 끄세요. 멜라토닌은 어둡고 기기가 없는 환경에서만 빠르게 분비되어 잠으로 넘어가는 걸 도와줘요.', body_nl = 'Zet 1 uur voor het slapengaan alle extra lampen en tabletschermen in de kamer uit, zodat hij sneller in slaap valt. Melatonine wordt alleen in een donkere omgeving zonder technologie snel aangemaakt en zorgt voor een soepele overgang naar de slaap.', body_pl = 'Aby szybciej zasnął, godzinę przed snem wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina szybko wydziela się tylko w ciemnym otoczeniu bez technologii i zapewnia płynne przejście w sen.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets 1 hora antes de dormir. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia, o que garante a passagem para o sono.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplatteskärmar i rummet 1 timme före läggdags. Melatonin utsöndras snabbt bara i en mörk och teknikfri miljö och säkrar övergången till sömn.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng 1 tiếng trước giờ ngủ. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ, giúp bé vào giấc trọn vẹn.', body_zh = '想让宝宝更快入睡，睡前1小时就关掉房间里所有多余的灯和平板屏幕。褪黑素只有在昏暗、没有电子产品的环境里才会快速分泌，让入睡更有保障。' WHERE id = 'df048442-7c05-4ccf-850d-802c3f348e55' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga las luces, escucha el silencio 🤫', body_es = 'Por fin se ha dormido. Ahora hasta el ruido más pequeño de la casa te molesta. Baja las luces, apaga la tele y disfruta en medio de la oscuridad de ese silencio tan raro y tan dulce. Así se limpia el cansancio de todo el día.', title_fr = 'Éteignez la lumière, écoutez le silence 🤫', body_fr = 'Il dort enfin. Maintenant, le moindre bruit de la maison vous dérange. Baissez les lumières, éteignez la télé et savourez dans l''obscurité la douceur de ce silence si rare. C''est ainsi que s''efface la fatigue de toute la journée.', title_hi = 'लाइटें बंद, खामोशी सुनिए 🤫', body_hi = 'आखिरकार वह सो गया। अब घर की सबसे छोटी आवाज़ भी आपको परेशान करती है। रोशनी धीमी कीजिए, टीवी बंद कीजिए और अँधेरे के बीच उस दुर्लभ खामोशी की मीठी राहत का आनंद लीजिए। दिनभर की थकान ऐसे ही उतरती है।', title_id = 'Matikan lampu, dengarkan keheningan 🤫', body_id = 'Akhirnya ia tertidur. Kini suara sekecil apa pun di rumah membuat Anda gelisah. Redupkan lampu, matikan TV, dan nikmati manisnya keheningan langka di tengah gelap. Begitulah rasa lelah seharian dibersihkan.', title_ja = '明かりを消して、静けさに耳をすませて 🤫', body_ja = 'やっと眠ってくれました。今は家の中の小さな音さえ気になりますね。明かりを落とし、テレビを消して、暗やみの中でめったにない静けさをたっぷり味わいましょう。一日の疲れは、こうして洗い流されます。', title_ko = '불을 끄고 고요를 들어요 🤫', body_ko = '드디어 잠들었어요. 이제 집 안의 아주 작은 소리도 신경 쓰이죠. 불을 낮추고 TV를 끄고, 어둠 속에서 귀한 고요의 달콤함을 누리세요. 하루의 피로는 이렇게 씻겨 나가요.', title_nl = 'Lichten uit, luister naar de stilte 🤫', body_nl = 'Hij slaapt eindelijk. Nu stoort zelfs het kleinste geluid in huis je. Dim de lichten, zet de tv uit en geniet midden in het donker van die zeldzame, heerlijke stilte. Zo spoel je de vermoeidheid van de hele dag weg.', title_pl = 'Zgaś światło, posłuchaj ciszy 🤫', body_pl = 'W końcu zasnął. Teraz przeszkadza ci nawet najcichszy dźwięk w domu. Przygaś światła, wyłącz telewizor i delektuj się słodyczą tej rzadkiej ciszy w ciemności. Tak oczyszcza się zmęczenie całego dnia.', title_pt = 'Apague as luzes, ouça o silêncio 🤫', body_pt = 'Finalmente adormeceu. Agora até o mais pequeno som da casa a incomoda. Baixe as luzes, desligue a televisão e saboreie, no meio do escuro, a doçura deste silêncio raro. É assim que se limpa o cansaço do dia inteiro.', title_sv = 'Släck ljuset, lyssna på tystnaden 🤫', body_sv = 'Äntligen har barnet somnat. Nu stör till och med det minsta ljud i hemmet dig. Dämpa ljuset, stäng av tv:n och njut av den sällsynta, ljuva tystnaden mitt i mörkret. Så rensas hela dagens trötthet.', title_vi = 'Tắt đèn, lắng nghe sự tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng đã ngủ. Giờ đây ngay cả tiếng động nhỏ nhất trong nhà cũng làm mẹ khó chịu. Hãy giảm đèn, tắt tivi và tận hưởng vị ngọt ngào của sự tĩnh lặng hiếm hoi giữa bóng tối. Mệt mỏi của cả ngày được gột rửa như thế đấy.', title_zh = '关上灯，听听安静 🤫', body_zh = '宝宝终于睡着了。现在家里哪怕一点点声音都让你心烦。把灯光调暗，关掉电视，在黑暗中好好享受这难得的、甜甜的安静。一整天的疲惫就这样被清空了。' WHERE id = '18eabc56-86a4-4978-a5a6-151a3c410b3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enfados sin motivo 😤', body_es = 'Tú solo has dicho «Ven, la comida está lista», y él se cruza de brazos, mira a la pared y se enfurruña contigo. A esta edad las emociones están tan revueltas que a veces se enfadan hasta con el aire. No expliques nada: en 2 minutos correrá él solo a comer.', title_fr = 'Bouderies sans raison 😤', body_fr = 'Vous avez simplement dit « Viens, le repas est prêt », et il croise les bras, regarde le mur et vous boude. À cet âge, les émotions sont si embrouillées qu''ils boudent parfois pour un rien. N''expliquez rien, dans 2 minutes il courra manger de lui-même.', title_hi = 'बेवजह का रूठना 😤', body_hi = 'आपने बस कहा, ‘आओ, खाना तैयार है’, और वह हाथ बाँधकर, दीवार की ओर देखकर आपसे रूठ जाता है। इस उम्र में भावनाएँ इतनी उलझी होती हैं कि कभी-कभी हवा से भी रूठ जाते हैं। कुछ मत समझाइए, 2 मिनट बाद वह खुद खाने की ओर दौड़ेगा।', title_id = 'Merajuk tanpa sebab 😤', body_id = 'Anda hanya berkata ''Ayo, makanan sudah siap'', tapi ia menyilangkan tangan, menghadap dinding, dan merajuk pada Anda. Di usia ini emosinya begitu campur aduk sampai kadang merajuk tanpa alasan. Jangan menjelaskan apa pun, 2 menit kemudian ia akan lari sendiri ke meja makan.', title_ja = 'わけもなくすねる 😤', body_ja = 'ただ「おいで、ごはんできたよ」と言っただけなのに、腕を組んで壁のほうを向き、すねてしまう。この年ごろは気持ちがとても入りまじっていて、ときには空気にさえすねるんです。何も説明しないで。2分後には自分からごはんに走ってきます。', title_ko = '이유 없는 삐짐 😤', body_ko = '그냥 ''와, 밥 다 됐어''라고 했을 뿐인데 팔짱을 끼고 벽을 보며 삐졌나요? 이 나이엔 감정이 너무 뒤엉켜 있어서 가끔은 허공에도 삐져요. 아무것도 설명하지 마세요, 2분 뒤면 스스로 밥 먹으러 달려올 거예요.', title_nl = 'Boos zonder reden 😤', body_nl = 'Je zei alleen ''Kom, het eten is klaar'', en hij slaat zijn armen over elkaar, kijkt naar de muur en is boos op je. Op deze leeftijd zijn emoties zo verward dat ze soms om niets boos worden. Leg niets uit, over 2 minuten rent hij vanzelf naar tafel.', title_pl = 'Fochy bez powodu 😤', body_pl = 'Powiedziałaś tylko „Chodź, jedzenie gotowe”, a on skrzyżował ręce, odwrócił się do ściany i się obraził. W tym wieku emocje są tak splątane, że czasem obrażają się o nic. Niczego nie tłumacz, za 2 minuty sam przybiegnie jeść.', title_pt = 'Amuos sem razão 😤', body_pt = 'Só disse "Anda, a comida está pronta" e ele cruza os braços, vira-se para a parede e fica amuado consigo. Nesta idade as emoções estão tão baralhadas que às vezes ficam amuados com o ar. Não explique nada: 2 minutos depois corre ele próprio para a mesa.', title_sv = 'Omotiverat tjurande 😤', body_sv = 'Du sa bara ”Kom, maten är klar”, och barnet korsar armarna, tittar in i väggen och tjurar mot dig. I den här åldern är känslorna så röriga att de ibland tjurar för ingenting. Förklara ingenting, efter 2 minuter springer barnet själv till maten.', title_vi = 'Giận dỗi vô cớ 😤', body_vi = 'Mẹ chỉ nói "Lại đây con, cơm xong rồi", bé lại khoanh tay, quay mặt vào tường và giận dỗi mẹ. Ở tuổi này, cảm xúc rối rắm đến mức đôi khi bé giận dỗi chẳng vì lý do gì. Đừng giải thích gì cả, 2 phút sau bé sẽ tự chạy đến ăn.', title_zh = '莫名其妙地生气 😤', body_zh = '你只是说了句“过来，饭做好了”，宝宝却双臂抱胸、对着墙生你的气。这个年龄的情绪乱成一团，有时连空气都能惹他们生气。什么都别解释，2分钟后宝宝自己就会跑来吃饭。' WHERE id = '90892878-829c-442e-a1ef-747f03a0affd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Anacan AI: los miedos infantiles 🤖', body_es = '¿De repente le ha empezado a dar miedo el coche rojo con el que siempre jugaba? Si te preocupan estas fobias inexplicables, cierra los foros traumatizantes de internet. Obtén de Anacan AI una respuesta científica y tranquilizadora sobre las rarezas de la imaginación a los 3 años y medio.', title_fr = 'Anacan AI : les peurs des enfants 🤖', body_fr = 'Il s''est soudain mis à avoir peur de la voiture rouge avec laquelle il joue depuis toujours ? Si ces phobies inexplicables vous inquiètent, fermez les forums traumatisants d''Internet. Obtenez d''Anacan AI une réponse scientifique et rassurante sur les bizarreries de l''imagination à 3 ans et demi.', title_hi = 'Anacan AI: बच्चों के डर 🤖', body_hi = 'अचानक उस लाल गाड़ी से डरने लगा जिससे हमेशा खेलता था? अगर बेवजह के डर आपको परेशान कर रहे हैं, तो इंटरनेट के परेशान करने वाले फ़ोरम बंद कीजिए। Anacan AI से साढ़े 3 साल की कल्पना की अजीब बातों के बारे में वैज्ञानिक और सुकून देने वाला जवाब पाइए।', title_id = 'Anacan AI: Ketakutan anak 🤖', body_id = 'Tiba-tiba ia takut pada mobil merah yang selalu ia mainkan? Jika fobia yang tak terjelaskan membuat Anda cemas, tutup forum-forum traumatis di internet. Dapatkan jawaban ilmiah dan menenangkan dari Anacan AI tentang keanehan imajinasi anak usia 3,5 tahun.', title_ja = 'Anacan AI：子どもの怖がり 🤖', body_ja = '急に、いつも遊んでいた赤い車を怖がりだした？説明のつかない怖がりが心配なら、ネットのショッキングな掲示板は閉じましょう。Anacan AIに、3歳半の想像力のふしぎについて、科学的で安心できる答えをもらいましょう。', title_ko = 'Anacan AI: 아이의 두려움 🤖', body_ko = '늘 가지고 놀던 빨간 자동차를 갑자기 무서워하나요? 설명할 수 없는 두려움이 걱정된다면 충격적인 인터넷 게시판은 닫으세요. Anacan AI에게 세 살 반 상상력의 신기한 특징에 대해 과학적이고 안심되는 답을 받으세요.', title_nl = 'Anacan AI: kinderangsten 🤖', body_nl = 'Is hij ineens bang voor de rode auto waar hij altijd mee speelde? Maken onverklaarbare angsten je ongerust, sluit dan die traumatiserende fora op internet. Krijg van Anacan AI een wetenschappelijk, geruststellend antwoord over de eigenaardigheden van de fantasie van een kind van 3,5.', title_pl = 'Anacan AI: dziecięce lęki 🤖', body_pl = 'Nagle zaczął bać się czerwonego samochodu, którym zawsze się bawił? Jeśli martwią cię niewytłumaczalne fobie, zamknij traumatyzujące fora w internecie. Uzyskaj od Anacan AI naukową i uspokajającą odpowiedź na temat dziwactw wyobraźni 3,5-latka.', title_pt = 'Anacan AI: os medos das crianças 🤖', body_pt = 'De repente começou a ter medo do carro vermelho com que sempre brincou? Se as fobias inexplicáveis a preocupam, feche os fóruns traumatizantes da internet. Obtenha do Anacan AI uma resposta científica e tranquilizadora sobre as estranhezas da imaginação aos 3 anos e meio.', title_sv = 'Anacan AI: Barns rädslor 🤖', body_sv = 'Har barnet plötsligt blivit rädd för den röda bilen det alltid lekt med? Om oförklarliga fobier oroar dig, stäng de traumatiska forumen på nätet. Få ett vetenskapligt och lugnande svar om 3,5-åringens fantasifulla egenheter från Anacan AI.', title_vi = 'Anacan AI: Nỗi sợ của trẻ 🤖', body_vi = 'Bé bỗng sợ chiếc ô tô đỏ vẫn chơi hằng ngày? Nếu những nỗi sợ khó giải thích khiến mẹ lo lắng, hãy đóng những diễn đàn gây hoang mang trên mạng. Hãy hỏi Anacan AI để nhận câu trả lời khoa học, giúp mẹ yên tâm về những điều kỳ lạ trong trí tưởng tượng của tuổi 3,5.', title_zh = 'Anacan AI：孩子的恐惧 🤖', body_zh = '突然开始害怕一直在玩的红色小汽车？如果莫名其妙的恐惧让你担心，就关掉网上那些让人焦虑的论坛。问问Anacan AI关于3岁半想象力的奇怪之处，得到科学又安心的回答。' WHERE id = 'e85911c9-eb5a-4470-b9d6-9a1a5872b746' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hipnosis del susurro 🌙', body_es = 'Tumbado en la cama levanta los pies al aire y no quiere dormirse de ninguna manera. En lugar de gritar, baja de golpe el tono y háblale solo en susurros. Cuando el niño se concentra para oírte, su cerebro se hipnotiza automáticamente y pasa al modo sueño.', title_fr = 'L''hypnose du chuchotement 🌙', body_fr = 'Allongé dans son lit, il lève les jambes en l''air et refuse catégoriquement de dormir. Au lieu de crier, baissez soudain le ton et ne lui parlez plus qu''en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau entre automatiquement dans une sorte d''hypnose et passe en mode sommeil.', title_hi = 'फुसफुसाहट का सम्मोहन 🌙', body_hi = 'बिस्तर में लेटकर पैर हवा में उठाता है, सोना बिल्कुल नहीं चाहता। चिल्लाने के बजाय अचानक आवाज़ धीमी कीजिए, उससे सिर्फ़ फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए पूरा ध्यान लगाता है, तो उसका दिमाग अपने-आप सम्मोहित होकर नींद के मोड में चला जाएगा।', title_id = 'Hipnosis bisikan 🌙', body_id = 'Ia berbaring di tempat tidur sambil mengangkat kaki ke udara dan sama sekali tidak mau tidur. Daripada berteriak, turunkan nada suara Anda tiba-tiba dan bicaralah dengannya hanya sambil berbisik. Saat anak memusatkan perhatian untuk mendengar Anda, otaknya otomatis terhipnosis dan beralih ke mode tidur.', title_ja = 'ささやきの催眠術 🌙', body_ja = 'ベッドに寝ころんで足を宙にあげ、まったく眠ろうとしない。どなる代わりに急に声のトーンを落として、ささやき声だけで話しかけてみましょう。あなたの声を聞こうと集中すると、脳は自然と催眠にかかったように眠りモードへ切りかわります。', title_ko = '속삭임의 최면 🌙', body_ko = '침대에 누워 다리를 허공에 들고 절대 잠들기 싫어하나요? 소리치는 대신 갑자기 톤을 낮춰 속삭이듯만 말하세요. 엄마 말을 들으려고 집중하는 순간 뇌가 저절로 최면에 걸린 듯 수면 모드로 바뀔 거예요.', title_nl = 'De hypnose van het fluisteren 🌙', body_nl = 'Hij ligt in bed met zijn benen in de lucht en wil absoluut niet slapen. Ga niet schreeuwen, maar ga ineens zachter praten en spreek alleen nog fluisterend tegen hem. Als hij zijn best doet om je te verstaan, raakt zijn brein vanzelf in een soort hypnose en schakelt het over naar de slaapstand.', title_pl = 'Hipnoza szeptu 🌙', body_pl = 'Leży w łóżku z nogami w górze i za nic nie chce zasnąć. Zamiast krzyczeć, nagle ścisz głos i mów do niego wyłącznie szeptem. Gdy dziecko zamieni się w słuch, żeby cię usłyszeć, jego mózg automatycznie wpadnie w hipnozę i przejdzie w tryb snu.', title_pt = 'A hipnose do sussurro 🌙', body_pt = 'Deitado na cama, levanta as pernas no ar e não quer mesmo nada adormecer. Em vez de gritar, baixe de repente o tom de voz e fale com ele só a sussurrar. Quando a criança se concentra para a ouvir, o cérebro fica automaticamente hipnotizado e passa para o modo de sono.', title_sv = 'Viskningens hypnos 🌙', body_sv = 'Barnet ligger i sängen med benen i luften och vill absolut inte somna. Istället för att skrika, sänk plötsligt rösten och prata bara viskande. När barnet lyssnar spänt för att höra dig blir hjärnan automatiskt hypnotiserad och går över i sömnläge.', title_vi = 'Lời thì thầm thôi miên 🌙', body_vi = 'Bé nằm trên giường, giơ chân lên trời và nhất quyết không chịu ngủ. Thay vì quát, hãy bất ngờ hạ giọng và chỉ thì thầm với bé. Khi bé chú ý để nghe mẹ, não bé sẽ tự động như bị thôi miên và chuyển sang chế độ ngủ.', title_zh = '悄悄话的催眠术 🌙', body_zh = '躺在床上把腿翘到半空，怎么都不想睡。别吼，突然压低声音，只用悄悄话和宝宝说话。宝宝聚精会神想听清你时，大脑会自动被“催眠”，切换到睡眠模式。' WHERE id = '037f6c5f-0014-4a61-89cc-f6268f8f792a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alivio en la Comunidad Anacan 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie. Entra en la Comunidad Anacan y limítate a leer. Ver que otras madres sienten el mismo cansancio te hace sentir «no estoy sola», y esa es la mejor terapia.', title_fr = 'Souffler grâce à la Communauté Anacan 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie de rien expliquer à personne. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir la même fatigue chez d''autres mamans donne le sentiment de ne pas être seule, c''est la meilleure thérapie.', title_hi = 'Anacan कम्युनिटी में राहत 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। दूसरी माँओं की मिलती-जुलती थकान देखकर ‘मैं अकेली नहीं हूँ’ का एहसास होता है, यही सबसे अच्छी थेरेपी है।', title_id = 'Lega di Komunitas Anacan 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat ibu-ibu lain merasakan lelah yang sama menumbuhkan rasa ''aku tidak sendirian'', dan itu terapi terbaik.', title_ja = 'Anacanコミュニティでほっとひと息 💬', body_ja = 'とても疲れていて、誰にも何も説明したくない。そんなときはAnacanコミュニティを開いて、読むだけにしましょう。ほかのママたちの同じような疲れを見ると「ひとりじゃない」と感じられて、いちばんのセラピーになります。', title_ko = 'Anacan 커뮤니티에서 얻는 위안 💬', body_ko = '너무 지쳐서 누구에게도 아무것도 설명하고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들의 비슷한 피로를 보면 ''나만 그런 게 아니구나'' 싶어 최고의 치료가 돼요.', title_nl = 'Tot rust komen in de Anacan Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen. Ga naar de Anacan Community en lees alleen mee. Zien dat andere mama''s net zo moe zijn geeft je het gevoel ''ik ben niet de enige'' en dat is de beste therapie.', title_pl = 'Ulga w Społeczności Anacan 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć. Wejdź do Społeczności Anacan i tylko czytaj. Widok podobnego zmęczenia u innych mam daje poczucie „nie jestem sama” i jest najlepszą terapią.', title_pt = 'Alívio na Comunidade Anacan 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém. Entre na Comunidade Anacan e limite-se a ler. Ver o cansaço parecido de outras mães dá a sensação de "não estou sozinha", e essa é a melhor terapia.', title_sv = 'Lättnad i Anacan Community 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon. Gå in i Anacan Community och bara läs. Att se andra mammors liknande trötthet ger känslan ”jag är inte ensam” och blir den bästa terapin.', title_vi = 'Nhẹ lòng trong Cộng đồng Anacan 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích gì với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác cũng mệt mỏi giống mình sẽ mang lại cảm giác "mình không đơn độc", đó là liệu pháp tốt nhất.', title_zh = '在Anacan社区里放松一下 💬', body_zh = '累坏了，什么都不想跟任何人解释？进入Anacan社区，只当个读者就好。看到其他妈妈也有同样的疲惫，会让你觉得“我不是一个人”，这就是最好的疗愈。' WHERE id = 'b0b14a33-4ccb-42a3-a0a7-0359199a066c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ráfaga de preguntas: ¿por qué? 🌪️', body_es = '«¿Por qué los peces no andan?», «¿Adónde se ha ido el sol?». Desde primera hora su cerebro busca filosofía a un ritmo de 100 preguntas por hora. Aunque estés cansada, dale respuestas cortas. Aprende los secretos del universo a través de tu tono de voz.', title_fr = 'Feu de questions : « Pourquoi ? » 🌪️', body_fr = '« Pourquoi les poissons ne marchent pas ? », « Où est parti le soleil ? » Dès le matin, son cerveau cherche de la philosophie au rythme de 100 questions à l''heure. Même si vous êtes fatiguée, donnez-lui des réponses courtes. Il apprend les secrets de l''univers à travers le ton de votre voix.', title_hi = 'सवालों की बौछार: क्यों? 🌪️', body_hi = '‘मछलियाँ चलती क्यों नहीं?’, ‘सूरज कहाँ गया?’ सुबह-सुबह उसका दिमाग 100 सवाल प्रति घंटे की रफ़्तार से दर्शन खोजता है। थक भी जाएँ, तो उसे छोटे जवाब दीजिए। वह दुनिया के रहस्य आपकी आवाज़ के लहजे से सीखता है।', title_id = 'Hujan pertanyaan: Kenapa? 🌪️', body_id = '''Kenapa ikan tidak berjalan?'', ''Mataharinya pergi ke mana?'' Sejak pagi otaknya mencari filsafat dengan kecepatan 100 pertanyaan per jam. Meski lelah, beri ia jawaban singkat. Ia mempelajari rahasia alam semesta dari nada suara Anda.', title_ja = '質問の集中砲火「なんで？」 🌪️', body_ja = '「なんでお魚は歩かないの？」「お日さまはどこへ行ったの？」朝早くから、1時間に100問のペースで哲学を追い求めています。疲れていても、短い答えを返してあげて。宇宙のふしぎを、あなたの声のトーンから学んでいるんです。', title_ko = '질문 폭격 - 왜? 🌪️', body_ko = '''물고기는 왜 안 걸어?'', ''해는 어디 갔어?'' 아침부터 머리가 시간당 100개의 질문 속도로 철학을 찾나요? 지쳐도 짧게 답해 주세요. 아이는 엄마의 목소리 톤에서 우주의 비밀을 배워요.', title_nl = 'Een spervuur van waaroms 🌪️', body_nl = '''Waarom lopen vissen niet?'', ''Waar is de zon gebleven?'' Al vroeg in de ochtend zoekt zijn brein filosofie met een snelheid van 100 vragen per uur. Ook al ben je moe, geef hem korte antwoorden. Hij leert de geheimen van het universum via de toon van jouw stem.', title_pl = 'Ostrzał pytań: „Dlaczego?” 🌪️', body_pl = '„Dlaczego ryby nie chodzą?”, „Gdzie poszło słońce?” Od samego rana jego mózg szuka filozofii w tempie 100 pytań na godzinę. Nawet gdy jesteś zmęczona, odpowiadaj mu krótko. Tajemnic wszechświata uczy się z tonu twojego głosu.', title_pt = 'Rajada de perguntas: porquê? 🌪️', body_pt = '"Porque é que os peixes não andam?", "Para onde foi o sol?" Logo de manhã cedo, o cérebro dele procura filosofia à velocidade de 100 perguntas por hora. Mesmo cansada, dê-lhe respostas curtas. Ele aprende os segredos do universo pelo seu tom de voz.', title_sv = 'Frågeeld: Varför? 🌪️', body_sv = '”Varför går inte fiskarna?”, ”Vart tog solen vägen?” Tidigt på morgonen söker barnets hjärna filosofi i en takt av 100 frågor i timmen. Även om du är trött, ge barnet korta svar. Barnet lär sig universums hemligheter genom din röst.', title_vi = 'Cơn mưa câu hỏi "Tại sao?" 🌪️', body_vi = '"Sao cá không đi bộ?", "Mặt trời đi đâu rồi?" Sáng sớm, não bé đã đi tìm triết học với tốc độ 100 câu hỏi mỗi giờ. Dù mệt, hãy trả lời bé thật ngắn gọn. Bé học những bí mật của vũ trụ qua giọng nói của mẹ.', title_zh = '问题连环炮：为什么？🌪️', body_zh = '“鱼为什么不走路？”“太阳去哪儿了？”一大早，宝宝的大脑就以每小时100个问题的速度探寻哲学。就算累了，也给宝宝简短的回答。宝宝正从你的语气里学习宇宙的奥秘。' WHERE id = 'b51e5eaf-9b52-4501-9631-0ad7c9e7aebd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«¡Es mío!»: quererlo todo para sí 🧸', body_es = 'Abraza cualquier objeto de la casa, grita «¡esto es mío!» y no se lo da a nadie. Está descubriendo los límites de la propiedad. No le acuses de egoísta: dirige su atención a otro juego y recupera el objeto.', title_fr = '« C''est à moi ! » : tout posséder 🧸', body_fr = 'Il serre dans ses bras un objet quelconque de la maison en criant « C''est à moi ! » et ne le donne à personne. Il découvre les limites de la propriété. Ne l''accusez pas d''égoïsme, détournez son attention vers un autre jeu pour récupérer l''objet.', title_hi = '‘यह मेरा है!’: हर चीज़ पर हक 🧸', body_hi = 'घर की कोई भी चीज़ गले लगाकर ‘यह मेरा है!’ चिल्लाता है और किसी को नहीं देता। वह अपनी चीज़ों की सीमाएँ खोज रहा है। उसे स्वार्थी मत कहिए, उसका ध्यान किसी और खेल की ओर ले जाकर चीज़ वापस ले लीजिए।', title_id = 'Itu punyaku! Ingin memiliki segalanya 🧸', body_id = 'Ia memeluk benda apa saja di rumah sambil berteriak ''Ini punyaku!'' dan tidak mau memberikannya kepada siapa pun. Ia sedang menemukan batas kepemilikan. Jangan menuduhnya egois, ambil kembali bendanya sambil mengalihkan perhatiannya ke permainan lain.', title_ja = '「ぼくの！」なんでも自分のもの 🧸', body_ja = '家にある適当なものを抱きかかえて「これ、ぼくの！」と叫び、誰にも渡さない。自分のものという境界を発見しているんです。わがままだと責めずに、別の遊びに気をそらしながら返してもらいましょう。', title_ko = '''내 거야!'' - 모든 걸 갖고 싶어요 🧸', body_ko = '집 안의 아무 물건이나 끌어안고 ''이건 내 거야!''라고 소리치며 아무에게도 주지 않나요? 소유의 경계를 발견하는 중이에요. 이기적이라고 탓하지 말고 다른 놀이로 관심을 돌려 물건을 돌려받으세요.', title_nl = 'Dat is van mij! Alles willen hebben 🧸', body_nl = 'Hij knuffelt een willekeurig ding in huis, roept ''Dit is van mij!'' en geeft het aan niemand. Hij ontdekt de grenzen van bezit. Beschuldig hem niet van egoïsme, maar leid zijn aandacht naar een ander spel en neem het ding dan terug.', title_pl = '„To moje!”, czyli wszystko na własność 🧸', body_pl = 'Przytula jakąkolwiek przypadkową rzecz w domu, krzyczy „To moje!” i nikomu jej nie daje. Odkrywa granice własności. Nie zarzucaj mu egoizmu, odwróć jego uwagę inną zabawą i odbierz tę rzecz.', title_pt = '"É meu!": querer ser dono de tudo 🧸', body_pt = 'Agarra-se a um objeto qualquer da casa, grita "Isto é meu!" e não o dá a ninguém. Está a descobrir os limites da posse. Não o acuse de egoísmo: desvie a atenção dele para outra brincadeira e recupere o objeto.', title_sv = 'Den är min! Att vilja äga allt 🧸', body_sv = 'Barnet kramar en slumpmässig sak hemma, skriker ”Den är min!” och ger den inte till någon. Barnet upptäcker gränserna för ägande. Anklaga inte barnet för egoism, led över uppmärksamheten till en annan lek och ta tillbaka saken.', title_vi = '"Của con!" - Muốn sở hữu mọi thứ 🧸', body_vi = 'Bé ôm chặt một món đồ ngẫu nhiên trong nhà và hét lên "Cái này của con!", không cho ai đụng vào. Bé đang khám phá ranh giới sở hữu. Đừng trách bé ích kỷ, hãy chuyển sự chú ý của bé sang trò chơi khác để lấy lại món đồ.', title_zh = '“这是我的！”：什么都要占有 🧸', body_zh = '抱着家里随便一样东西大喊“这是我的！”，谁都不给。宝宝在探索所有权的边界。别指责宝宝自私，把宝宝的注意力转到别的游戏上，再把东西拿回来。' WHERE id = '56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La parte de mamá 🥗', body_es = '¿Has pensado 3 menús distintos para que él coma y tú te has vuelto a quedar con hambre? Elige en el Plan de alimentación una comida energizante, rica en hierro y calcio, que se prepara en 10 minutos y que no es solo para niños, sino también para mamás, y siéntete valorada.', title_fr = 'La part de maman 🥗', body_fr = 'Vous avez imaginé 3 menus différents pour le nourrir, et vous, vous êtes encore restée le ventre vide ? Dans le Plan de nutrition, choisissez un déjeuner énergisant riche en fer et en calcium, prêt en 10 minutes, pensé non seulement pour les enfants mais aussi pour les mamans, et prenez soin de vous.', title_hi = 'माँ का अपना हिस्सा 🥗', body_hi = 'उसका पेट भरने के लिए 3 अलग मेन्यू सोचे, और आप फिर से भूखी रह गईं? फ़ीडिंग प्लान सेक्शन से, जो सिर्फ़ बच्चों के लिए नहीं, माँओं के लिए भी है, 10 मिनट में बनने वाला, ऊर्जा देने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और खुद को कीमती महसूस कीजिए।', title_id = 'Jatah untuk Ibu 🥗', body_id = 'Anda memikirkan 3 menu berbeda untuk membuatnya kenyang, tapi Anda sendiri kelaparan lagi? Dari Rencana Nutrisi, yang bukan hanya untuk anak tapi juga untuk ibu, pilih makan siang berenergi kaya zat besi dan kalsium yang siap dalam 10 menit, dan rasakan bahwa Anda berharga.', title_ja = 'ママの分 🥗', body_ja = 'この子のために3種類のメニューを考えたのに、自分はまた食べそびれた？「栄養管理ツール」から、子どもだけでなくママにも元気をくれる、10分でできる鉄分とカルシウムたっぷりのランチを選んで、自分を大切にしましょう。', title_ko = '엄마의 몫 🥗', body_ko = '아이를 먹이려고 메뉴를 3가지나 고민했는데 정작 엄마는 또 굶었나요? 식단 계획 섹션에서 아이뿐 아니라 엄마에게도 힘이 되는, 10분이면 만드는 철분과 칼슘이 풍부한 식사를 골라 나를 소중히 대해 주세요.', title_nl = 'Mama''s eigen portie 🥗', body_nl = 'Drie verschillende menu''s bedacht om hem te eten te geven, maar zelf weer niets gegeten? Kies in het Voedingsplan een energierijke lunch, rijk aan ijzer en calcium en in 10 minuten klaar, niet alleen voor kinderen maar ook voor mama''s, en voel dat je ertoe doet.', title_pl = 'Porcja dla mamy 🥗', body_pl = 'Wymyśliłaś 3 różne menu, żeby go nakarmić, a sama znowu zostałaś głodna? Wybierz w sekcji plan karmienia energetyczny obiad bogaty w żelazo i wapń, gotowy w 10 minut, nie tylko dla dzieci, ale i dla mam, i poczuj, że jesteś ważna.', title_pt = 'A parte da mãe 🥗', body_pt = 'Pensou em 3 menus diferentes para ele comer, mas a mãe voltou a ficar com fome? Escolha no Registo de Alimentação um almoço energético, rico em ferro e cálcio, pronto em 10 minutos, não só para crianças mas também para mães, e sinta-se valorizada.', title_sv = 'Mammas egen portion 🥗', body_sv = 'Du hittade på 3 olika menyer för att få barnet mätt, men själv blev du hungrig igen? Välj i matplanen en energigivande lunch rik på järn och kalcium, som inte bara är för barn utan också för mammor och tar 10 minuter, och känn dig värdefull.', title_vi = 'Phần ăn của riêng mẹ 🥗', body_vi = 'Mẹ nghĩ ra 3 thực đơn khác nhau để bé ăn no, còn bản thân thì lại nhịn đói? Hãy vào Kế hoạch dinh dưỡng, chọn một bữa trưa giàu sắt và canxi, nạp năng lượng, nấu trong 10 phút, không chỉ cho trẻ mà cho cả mẹ, và cảm nhận giá trị của chính mình.', title_zh = '妈妈自己的那一份 🥗', body_zh = '为了喂饱宝宝想了3种不同的菜单，结果自己又饿着？在喂养计划板块里，挑一道不只适合孩子、也适合妈妈的补充能量、10分钟就能做好、富含铁和钙的午餐，让自己感受到被珍视。' WHERE id = '77d341ac-ecee-44bc-a34c-b8046e7ebe38' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sirve en los vasos un simple té caliente. Sentaos frente a frente en el sofá tú y tu pareja y brindad diciendo: «Hoy también hemos sobrevivido a este caos». Sois los comandantes de la casa y también un equipo.', body_fr = 'Après cette journée difficile, versez du simple thé chaud dans des verres. Asseyez-vous face à votre partenaire sur le canapé et trinquez : « On a survécu à ce chaos aujourd''hui aussi ! » Vous êtes à la fois les commandants et l''équipe de cette maison.', body_hi = 'मुश्किल दिन के बाद गिलासों में सादी गरम चाय डालिए। अपने साथी के साथ सोफ़े पर आमने-सामने बैठिए और ‘आज उस अफ़रा-तफ़री से भी सही-सलामत निकल आए’ कहकर गिलास टकराइए। आप इस घर के सेनापति भी हैं और टीम भी।', body_id = 'Setelah hari yang berat, tuang teh hangat biasa ke gelas. Duduklah berhadapan dengan pasangan di sofa dan bersulanglah sambil berkata ''Hari ini pun kita selamat dari kekacauan itu''. Kalian adalah panglima sekaligus tim di rumah ini.', body_ja = '大変な一日のあと、コップにふつうの温かいお茶を注ぎましょう。パートナーとソファで向かい合って「今日もあのカオスを無事に乗りきったね」と乾杯を。ふたりはこの家の司令官であり、チームでもあります。', body_ko = '힘든 하루가 끝나면 컵에 평범한 따뜻한 차를 따르세요. 배우자와 소파에 마주 앉아 ''오늘 그 혼돈에서도 살아남았어''라며 건배하세요. 두 사람은 이 집의 사령관이자 한 팀이에요.', body_nl = 'Schenk na een zware dag gewone warme thee in. Ga tegenover je partner op de bank zitten en klink: ''Ook die chaos van vandaag hebben we overleefd.'' Jullie zijn de aanvoerders en tegelijk het team van dit huis.', body_pl = 'Po trudnym dniu nalejcie do szklanek zwykłej gorącej herbaty. Usiądźcie z partnerem na kanapie twarzą w twarz i stuknijcie się szklankami: „Z tego chaosu też dziś wyszliśmy cało”. Jesteście i dowódcami, i drużyną tego domu.', body_pt = 'Depois de um dia difícil, sirvam simplesmente chá quente nos copos. Sentem-se frente a frente no sofá com o seu companheiro e brindem: "Hoje também sobrevivemos ao caos". São os comandantes desta casa e também uma equipa.', body_sv = 'Efter den tuffa dagen, häll upp vanligt varmt te i glasen. Sätt dig mitt emot din partner i soffan och skåla: ”I dag överlevde vi det här kaoset också.” Ni är både hemmets befälhavare och dess lag.', body_vi = 'Sau một ngày vất vả, hãy rót trà nóng bình thường vào cốc. Ngồi đối diện chồng trên sofa và cụng ly: "Hôm nay mình lại sống sót qua mớ hỗn loạn đó rồi!". Hai người vừa là những vị chỉ huy, vừa là một đội của ngôi nhà này.', body_zh = '艰难的一天过后，往杯子里倒上普通的热茶。和伴侣面对面坐在沙发上，碰个杯：“今天这场混乱，我们也挺过来了。”你们既是这个家的指挥官，也是一个团队。' WHERE id = '97e76dee-bae4-4d8b-bffd-646b99d0b6bc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad de servirse solo 💧', body_es = 'Se servirá él solito el agua de la jarra grande al vaso pequeño. El agua cae a la mesa y de ahí al suelo. Pero mira esas manitas que han cogido un trapo e intentan limpiarlo. Aprende responsabilidad equivocándose, no te enfades.', title_fr = 'L''entêtement de verser tout seul 💧', body_fr = 'Il tient absolument à verser lui-même l''eau de la grande carafe dans le petit gobelet. L''eau se renverse sur la table, puis par terre. Mais regardez ses petites mains qui attrapent le chiffon pour essayer de nettoyer. Il apprend la responsabilité en se trompant, ne vous énervez pas.', title_hi = 'खुद डालने की ज़िद 💧', body_hi = 'बड़े जग से छोटे गिलास में पानी उसे खुद ही डालना है। पानी मेज़ पर और वहाँ से फ़र्श पर गिर जाता है। पर उन छोटे हाथों को देखिए जो कपड़ा लेकर सब साफ़ करने की कोशिश कर रहे हैं। वह गलतियों से ज़िम्मेदारी सीख रहा है, नाराज़ मत होइए।', title_id = 'Ngotot menuang sendiri 💧', body_id = 'Ia bersikeras menuang air sendiri dari teko besar ke gelas kecil. Air tumpah ke meja, lalu ke lantai. Tapi lihat tangan kecilnya yang mengambil lap dan berusaha membersihkannya. Ia belajar tanggung jawab dari kesalahannya, jangan kesal.', title_ja = '自分で注ぎたい 💧', body_ja = '大きなピッチャーから小さなコップへ、どうしても自分でお水を注ぎたい。お水はテーブルに、そして床へとこぼれます。でも、ふきんを持ってきて一生けんめい拭こうとする小さな手を見てあげて。失敗しながら責任を学んでいます。怒らないでね。', title_ko = '''내가 따를 거야'' 고집 💧', body_ko = '큰 물병에서 작은 컵으로 물을 꼭 자기가 따르겠다더니 식탁에, 바닥에 쏟았나요? 그래도 걸레를 집어 닦으려는 그 작은 손을 보세요. 실수하면서 책임감을 배우는 중이에요. 화내지 마세요.', title_nl = 'Per se zelf inschenken 💧', body_nl = 'Hij moet en zal zelf water uit de grote kan in een klein bekertje schenken. Het water loopt over de tafel en zo op de grond. Maar kijk eens naar die kleine handjes die een doekje pakken om het op te ruimen. Hij leert verantwoordelijkheid door fouten te maken, word niet boos.', title_pl = 'Upór „Sam naleję” 💧', body_pl = 'Koniecznie chce sam nalać wody z dużego dzbanka do małego kubeczka. Woda rozlewa się na stół, a stamtąd na podłogę. Ale spójrz na te małe rączki, które chwyciły ściereczkę i próbują wytrzeć. Uczy się odpowiedzialności na błędach, nie denerwuj się.', title_pt = 'A teimosia de servir sozinho 💧', body_pt = 'Quer mesmo deitar sozinho a água do jarro grande para o copo pequeno. A água cai na mesa e daí para o chão. Mas olhe para aquelas mãozinhas a pegar no pano para tentar limpar. Está a aprender a ser responsável com os erros, não se zangue.', title_sv = 'Envisheten att hälla upp själv 💧', body_sv = 'Barnet ska absolut hälla vatten själv från den stora kannan till det lilla glaset. Vattnet hamnar på bordet och därifrån på golvet. Men titta på de små händerna som tar trasan och försöker torka upp. Barnet lär sig ansvar genom misstag, bli inte arg.', title_vi = 'Bướng bỉnh đòi tự rót 💧', body_vi = 'Bé nhất định tự rót nước từ bình lớn vào chiếc cốc nhỏ. Nước đổ ra bàn, rồi xuống sàn. Nhưng hãy nhìn đôi bàn tay nhỏ đang cầm khăn cố lau chỗ đó. Bé đang học trách nhiệm qua chính lỗi sai của mình, mẹ đừng bực nhé.', title_zh = '非要自己倒水 💧', body_zh = '非要自己从大水壶往小杯子里倒水。水洒到桌上，又流到地上。可你看看那双拿起抹布、努力想擦干净的小手。宝宝正在从错误中学会责任，别生气。' WHERE id = '0dc18b7e-e572-47af-8c7b-0d7785728f82' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un océano en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de hacer olas. Deja que el agua salpique. Ese efecto imán del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'L''océan dans la baignoire 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu de vagues. Laissez l''eau éclabousser. L''effet magnétique de l''eau emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'बाथटब में समुद्र 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, लहरें बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए। पानी का वह चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Samudra di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat ombak. Biarkan air memercik ke mana-mana. Efek magnet air akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = 'お風呂の中の海 🌊', body_ja = 'お風呂はもうきれいにするためではなく、波をつくる遊びです。水しぶきが飛んでもいいんです。お湯の磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '욕조 속 바다 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 파도 만들기 놀이예요. 물이 사방으로 튀어도 괜찮아요. 물의 자석 같은 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'De oceaan in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met golven maken. Laat het water maar spetteren. Het magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Ocean w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w robienie fal. Niech woda chlapie dookoła. Magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia i spłynie z nim do kanalizacji.', title_pt = 'O oceano na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer ondas. Deixe a água salpicar à volta. O efeito magnético da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Havet i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att göra vågor. Låt vattnet stänka. Vattnets magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Đại dương trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo sóng. Cứ để nước bắn tung tóe. Sức hút kỳ diệu của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '浴缸里的海洋 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起浪花的游戏。让水花四溅吧。水那种磁力般的效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = '4f75092c-a7ba-4a8b-9f64-4af1718f2cab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista de la compra: lo olvidado 🛒', body_es = '¿Siempre se te olvida lo más importante al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que haga falta y que tu pareja lo compre con precisión al volver del trabajo. No sobrecargues tu mente sin necesidad.', title_fr = 'Liste de courses : les oublis 🛒', body_fr = 'Vous oubliez toujours le plus important en allant au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins pour que votre partenaire rapporte tout avec précision en rentrant du travail. Ne surchargez pas inutilement votre cerveau.', title_hi = 'शॉपिंग लिस्ट: भूली हुई चीज़ें 🛒', body_hi = 'बाज़ार जाते समय सबसे ज़रूरी चीज़ ज़रूर भूल जाती हैं? शॉपिंग लिस्ट ऐप में आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके साथी काम से लौटते समय ठीक-ठीक सामान ले आएँ, आप दिमाग पर बेवजह बोझ मत डालिए।', title_id = 'Daftar Belanja: yang terlupakan 🛒', body_id = 'Selalu lupa barang paling penting saat ke supermarket? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan Anda membelinya dengan tepat sepulang kerja, dan Anda tak perlu membebani otak tanpa perlu.', title_ja = '買い物リスト：忘れもの 🛒', body_ja = '買い物に行くと、必ずいちばん大事なものを忘れる？アプリの「買い物リスト」が待っています。必要なものを書きこんで、パートナーが仕事帰りにきっちり買ってこられるようにしましょう。よけいなことで頭をいっぱいにしないで。', title_ko = '쇼핑 목록 - 깜빡한 것들 🛒', body_ko = '마트에 가면 꼭 가장 중요한 걸 잊나요? 앱에서 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요. 머리를 쓸데없이 혹사하지 마세요.', title_nl = 'Boodschappenlijstje: wat je vergeet 🛒', body_nl = 'Vergeet je altijd het belangrijkste als je naar de supermarkt gaat? Het Boodschappenlijstje wacht in de app op je. Zet er alles op wat je nodig hebt, zodat je partner het op weg naar huis precies kan meenemen. Zo belast je je hoofd niet onnodig.', title_pl = 'Lista zakupów: zapomniane rzeczy 🛒', body_pl = 'Idąc do sklepu, zawsze zapominasz o najważniejszej rzeczy? Lista zakupów czeka na ciebie w aplikacji. Zapisuj tam potrzeby, niech partner w drodze z pracy dokładnie wszystko kupi, a ty nie obciążaj niepotrzebnie głowy.', title_pt = 'Lista de compras: o que fica esquecido 🛒', body_pt = 'Quando vai ao supermercado, esquece-se sempre da coisa mais importante? A Lista de Compras está à sua espera na app. Registe lá o que faz falta para que o seu companheiro compre tudo certinho ao voltar do trabalho, e não sobrecarregue a cabeça sem necessidade.', title_sv = 'Inköpslistan: det som glöms 🛒', body_sv = 'Glömmer du alltid det allra viktigaste när du går till butiken? Inköpslistan väntar på dig i appen. Skriv upp behoven där, så kan din partner handla exakt rätt på vägen hem från jobbet, och du slipper belasta hjärnan i onödan.', title_vi = 'Danh sách mua sắm - những thứ hay quên 🛒', body_vi = 'Đi siêu thị lần nào cũng quên món quan trọng nhất? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó, để chồng trên đường đi làm về mua đầy đủ, chính xác, còn mẹ khỏi phải nhọc đầu vô ích.', title_zh = '购物清单：那些忘了的东西 🛒', body_zh = '去超市总会忘掉最重要的那样东西？购物清单在应用里等着你。把需要的东西记进去，让伴侣下班回家时准确买齐，你就别再给大脑增加不必要的负担了。' WHERE id = 'd4d0d422-f5f6-490e-8c72-e88ef36a1315' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arquitectura en el parque 🏰', body_es = 'En el arenero del parque cava tan hondo como si buscara un tesoro. Va lleno de barro. Pero no interrumpas su momento de descubrimiento. La ropa apta para ensuciarse que elegiste antes con Tiempo y ropa te permite disfrutar de la escena sin estrés.', title_fr = 'Architecture au parc 🏰', body_fr = 'Dans le bac à sable du parc, il creuse si profond qu''on dirait qu''il cherche un trésor. Il est couvert de boue. Mais n''interrompez pas ce moment de découverte. Les vêtements adaptés aux salissures, choisis à l''avance avec Météo et tenue, vous permettent de regarder la scène sans stress.', title_hi = 'पार्क की वास्तुकला 🏰', body_hi = 'पार्क के सैंडपिट में इतना गहरा खोद रहा है जैसे खज़ाना ढूँढ रहा हो। कपड़े कीचड़ से सने हैं। पर उसकी इस खोज के पल को मत तोड़िए। मौसम और कपड़े से पहले से चुने गंदे होने लायक कपड़े आपको यह नज़ारा बिना तनाव देखने का मौका देते हैं।', title_id = 'Arsitektur di taman 🏰', body_id = 'Di bak pasir taman ia menggali begitu dalam seolah mencari harta karun. Seluruh tubuhnya penuh lumpur. Tapi jangan ganggu momen penemuannya ini. Pakaian yang tahan kotor, yang sudah Anda pilih sebelumnya lewat Cuaca dan Pakaian, memberi Anda kesempatan menyaksikan pemandangan ini tanpa stres.', title_ja = '公園の建築 🏰', body_ja = '公園の砂場で、宝物をさがしているかのように深く深く掘っています。体じゅう泥だらけ。でも、この発見の瞬間をじゃましないで。「天気と服装」で前もって選んでおいた、汚れてもいい服のおかげで、この光景をストレスなく見守れます。', title_ko = '공원의 건축 🏰', body_ko = '공원 모래밭에서 보물이라도 찾듯 깊이 파고 온몸이 흙투성이인가요? 그래도 이 발견의 순간을 깨지 마세요. 날씨와 옷차림 도구로 미리 고른 더러워져도 괜찮은 옷 덕분에 이 장면을 스트레스 없이 지켜볼 수 있어요.', title_nl = 'Architectuur in het park 🏰', body_nl = 'In de zandbak in het park graaft hij zo diep alsof hij een schat zoekt. Hij zit onder de modder. Maar verstoor dit ontdekkingsmoment niet. Dankzij de kleren die je vooraf met Weer en kleding hebt gekozen en die vies mogen worden, kun je stressvrij toekijken.', title_pl = 'Architektura w parku 🏰', body_pl = 'W piaskownicy w parku kopie tak głęboko, jakby szukał skarbu. Cały jest w błocie. Ale nie przerywaj mu tej chwili odkrywania. Ubrania na brudzenie, które wybrałaś wcześniej z narzędziem Pogoda i ubiór, pozwalają ci spokojnie, bez stresu obserwować ten widok.', title_pt = 'Arquitetura no parque 🏰', body_pt = 'Na caixa de areia do parque, escava tão fundo que parece andar à procura de um tesouro. Está todo sujo. Mas não interrompa este momento de descoberta. A roupa própria para sujar, escolhida antes com o Tempo e Roupa, dá-lhe a hipótese de ver esta cena sem stress.', title_sv = 'Arkitektur i parken 🏰', body_sv = 'I sandlådan i parken gräver barnet så djupt att det verkar leta efter en skatt. Kläderna är fulla av lera. Men avbryt inte upptäckarstunden. Kläder som tål smuts, som du valt i förväg med hjälp av Väder och kläder, ger dig chansen att titta på utan stress.', title_vi = 'Kiến trúc ở công viên 🏰', body_vi = 'Ở hố cát công viên, bé đào sâu như đang tìm kho báu. Người ngợm lấm lem bùn đất. Nhưng đừng cắt ngang khoảnh khắc khám phá này. Bộ đồ "chịu bẩn" mẹ đã chọn trước nhờ Thời tiết và trang phục sẽ giúp mẹ ngắm cảnh này mà không căng thẳng.', title_zh = '公园里的建筑 🏰', body_zh = '在公园的沙坑里挖得那么深，好像在寻宝。浑身都是泥。但别打断这个探索的时刻。借助天气与穿衣提前挑好不怕弄脏的衣服，让你可以毫无压力地欣赏这幅画面。' WHERE id = '418c1711-4059-4957-81d3-edd1c0d2c899' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amistades raras con objetos 🗣️', body_es = 'En el parque le cuenta cosas muy en serio a una piedra, o en casa a una silla, y hasta les riñe. A través del juego simbólico procesa el mundo. Anota sin falta estos guiones tan especiales en el Seguimiento del desarrollo.', title_fr = 'D''étranges amitiés avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et les gronde ? Il comprend le monde à travers le jeu symbolique. Notez absolument ces scénarios particuliers dans le Suivi de développement.', title_hi = 'बेजान चीज़ों से अजीब दोस्तियाँ 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ कहता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया को समझ रहा है। उसकी इन खास कहानियों को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Persahabatan aneh dengan benda mati 🗣️', body_id = 'Di taman ia berbicara serius dengan sebuah batu, atau di rumah memarahi kursi. Lewat permainan simbolis, ia mengolah dunia. Pastikan menandai skenario istimewanya ini di Pelacak Perkembangan.', title_ja = 'ものとのふしぎな友情 🗣️', body_ja = '公園の石や家のいすに、すっかり真剣に話しかけたり、しかったりしています。象徴遊びを通して世界を整理しているんです。この特別なシナリオを、ぜひ「発達トラッカー」に記録しておきましょう。', title_ko = '사물과의 엉뚱한 우정 🗣️', body_ko = '공원의 돌이나 집의 의자에게 아주 진지하게 무언가를 이야기하고 혼내기도 하나요? 상징 놀이로 세상을 소화하는 중이에요. 이 특별한 시나리오를 성장 기록에 꼭 표시해 두세요.', title_nl = 'Rare vriendschappen met dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld. Noteer deze bijzondere scenario''s zeker in de Groeitracker.', title_pl = 'Dziwne przyjaźnie z przedmiotami 🗣️', body_pl = 'W parku zupełnie poważnie coś opowiada kamieniowi albo w domu beszta krzesło. Przez zabawę symboliczną przetwarza świat. Koniecznie zaznacz te wyjątkowe scenariusze w Śledzeniu rozwoju.', title_pt = 'Amizades estranhas com objetos 🗣️', body_pt = 'No parque, fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo. Não deixe de registar estes enredos especiais no Registo de Crescimento.', title_sv = 'Konstiga vänskaper med livlösa saker 🗣️', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen. Anteckna absolut barnets speciella scenarier i Utvecklingsspåraren.', title_vi = 'Tình bạn kỳ lạ với đồ vật 🗣️', body_vi = 'Ở công viên, bé nói chuyện rất nghiêm túc với một hòn đá, ở nhà thì "mắng" chiếc ghế? Bé đang xử lý thế giới qua trò chơi biểu tượng. Hãy nhớ đánh dấu những kịch bản đặc biệt này trong Theo dõi phát triển.', title_zh = '和没有生命的东西结下奇怪的友谊 🗣️', body_zh = '在公园对着一块石头、在家对着一把椅子，非常认真地说着什么，还训它们。宝宝通过象征性游戏来理解世界。一定要把这些特别的小剧本记在发育追踪里。' WHERE id = '4690cd10-6ebf-45be-8b49-fc76a078e4f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Yo en el Cuento inteligente 🪄', body_es = 'Esta noche, en Cuentos inteligentes, ponle al héroe el nombre de tu peque. Cuenta que el personaje recogió su habitación y luego durmió a gusto, y transmítele las normas de forma indirecta, no a gritos.', title_fr = 'Moi, dans le Conte intelligent 🪄', body_fr = 'Ce soir, dans les Contes intelligents, donnez directement au héros le prénom de votre enfant. Racontez que le personnage range sa chambre puis s''endort paisiblement, pour transmettre les règles de façon indirecte, sans crier.', title_hi = 'स्मार्ट कहानी में मैं 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में हीरो का नाम सीधे अपने बच्चे के नाम पर रखिए। कहानी के किरदार के कमरा समेटने और फिर आराम से सो जाने की बात सुनाकर, नियम चिल्लाकर नहीं, घुमा-फिराकर सिखाइए।', title_id = 'Aku di Dongeng Pintar 🪄', body_id = 'Malam ini di Dongeng Pintar, beri tokoh utamanya nama anak Anda. Ceritakan bahwa tokoh dalam dongeng itu juga membereskan kamarnya lalu tidur nyenyak, dan tanamkan aturan secara tidak langsung, bukan dengan berteriak.', title_ja = 'スマートおはなしの主人公はわたし 🪄', body_ja = '今夜は「スマートおはなし」で、主人公にお子さんの名前をつけましょう。お話の主人公も部屋を片づけてから気持ちよく眠った、という話を通して、ルールを叫んで伝えるのではなく、さりげなく伝えましょう。', title_ko = '스마트 동화 속의 나 🪄', body_ko = '오늘 저녁 스마트 동화에서 주인공 이름을 아이 이름으로 지어 보세요. 이야기 속 주인공도 방을 정리하고 푹 잤다고 들려주며, 규칙을 소리쳐 말하는 대신 자연스럽게 전해 주세요.', title_nl = 'Ik in het Slimme sprookje 🪄', body_nl = 'Geef de held vanavond in Slimme sprookjes de naam van je kind. Vertel dat het personage ook zijn kamer opruimde en daarna lekker sliep, en breng zo regels niet met schreeuwen maar op een indirecte manier over.', title_pl = 'Ja w Mądrej bajce 🪄', body_pl = 'Dziś wieczorem w Mądrych bajkach nazwij bohatera imieniem twojego dziecka. Opowiadając, że postać z bajki też posprzątała pokój, a potem spokojnie zasnęła, przekazuj zasady nie krzykiem, tylko w pośredni sposób.', title_pt = 'Eu nas Histórias Inteligentes 🪄', body_pt = 'Esta noite, dê ao herói das Histórias Inteligentes o nome do seu filho. Conte que a personagem também arrumou o quarto e depois dormiu tranquila, e transmita as regras de forma indireta, sem gritar.', title_sv = 'Jag i den smarta sagan 🪄', body_sv = 'Ge hjälten i kvällens Smarta sagor barnets eget namn. Berätta att sagofiguren också städade sitt rum och sedan sov gott, så förmedlar du reglerna indirekt istället för att skrika ut dem.', title_vi = 'Con trong Truyện cổ tích thông minh 🪄', body_vi = 'Tối nay, trong Truyện cổ tích thông minh, hãy đặt tên nhân vật chính theo tên của bé. Kể rằng nhân vật trong truyện cũng dọn phòng rồi ngủ thật ngon, để dạy bé các quy tắc một cách gián tiếp chứ không phải bằng tiếng quát.', title_zh = '智慧童话里的“我” 🪄', body_zh = '今晚在智慧童话里，直接用宝宝的名字给主角命名。讲讲故事里的角色也把房间收拾好，然后舒舒服服地睡着了，不用吼，而是用间接的方式教会宝宝规矩。' WHERE id = 'a43560ca-6c77-420e-beaa-23a6e7c51732' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario de ánimo: momento de desahogo 📝', body_es = 'Coge el móvil. En lugar de deslizar la vida de otros en redes sociales, abre el Diario de ánimo y anota para el futuro el momento más gracioso que ha tenido hoy. La terapia digital también te hará descansar a ti.', title_fr = 'Journal d''humeur : le moment de vider son sac 📝', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée. Cette thérapie numérique vous reposera aussi.', title_hi = 'मूड डायरी: मन हल्का करने का पल 📝', body_hi = 'फ़ोन उठाइए। सोशल मीडिया पर दूसरों की ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसने जो सबसे मज़ेदार काम किया, उसे भविष्य के लिए लिख लीजिए। डिजिटल थेरेपी आपको भी आराम देगी।', title_id = 'Buku Harian Suasana Hati: saat melepas beban 📝', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini untuk masa depan. Terapi digital ini juga akan membuat Anda rileks.', title_ja = '気分日記：はき出す時間 📝', body_ja = 'スマホを手に取って。SNSでほかの人の暮らしをスクロールする代わりに、「気分日記」を開いて、今日この子がしたいちばんおもしろい瞬間を未来のために記録しましょう。デジタルセラピーは、あなたも癒やしてくれます。', title_ko = '기분 일기 - 털어내는 순간 📝', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃긴 순간을 기록해 두세요. 디지털 치료가 엄마도 쉬게 해 줄 거예요.', title_nl = 'Stemmingsdagboek: even ontladen 📝', body_nl = 'Pak je telefoon. Open in plaats van door andermans leven op social media te scrollen je Stemmingsdagboek en schrijf het grappigste moment van vandaag op voor later. Digitale therapie ontspant jou ook.', title_pl = 'Dziennik nastroju: chwila ulgi 📝', body_pl = 'Weź telefon do ręki. Zamiast przewijać cudze życie w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował. Cyfrowa terapia pozwoli też tobie odpocząć.', title_pt = 'Diário de Humor: momento de desabafo 📝', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje. A terapia digital também a vai descansar.', title_sv = 'Humördagboken: en stund att släppa ut 📝', body_sv = 'Ta upp telefonen. Istället för att scrolla igenom andras liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet för framtiden. Den digitala terapin låter dig också vila.', title_vi = 'Nhật ký tâm trạng - Khoảnh khắc trút bỏ 📝', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc hài hước nhất bé làm hôm nay để dành cho tương lai. Liệu pháp số cũng sẽ giúp mẹ thư giãn.', title_zh = '心情日记：释放的时刻 📝', body_zh = '拿起手机。与其刷社交网络看别人的生活，不如打开心情日记，把宝宝今天最搞笑的一刻记下来留给将来。数字疗愈也会让你放松下来。' WHERE id = '9e327ded-a5c0-48ad-901c-52606eb80762' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar toda su energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo sube a caballito y galopa, las carcajadas llenan la habitación y todo el estrés físico acumulado, esa energía sin fin, desaparece en segundos con el sudor.', body_fr = 'Il n''a pas pu se dépenser complètement et refuse d''aller au lit. Appelez papa en renfort. Quand il le prend sur son dos pour jouer au cheval, les éclats de rire remplissent la pièce, et toute la tension physique accumulée, cette énergie sans fin, s''évacue en quelques secondes.', body_hi = 'पूरी ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक तनाव, वह अंतहीन ऊर्जा पसीने के साथ सेकंडों में गायब हो जाती है।', body_id = 'Ia belum sempat menyalurkan seluruh energinya dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar, dan semua stres fisik serta energi yang tak habis-habis itu lenyap dalam hitungan detik bersama keringat.', body_ja = 'エネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを背中にのせてお馬さんになれば、部屋は笑い声でいっぱいになり、たまっていた体のストレスも尽きないエネルギーも、汗と一緒にあっという間に消えていきます。', body_ko = '에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음소리가 방을 채우고, 쌓인 몸의 스트레스와 끝없는 에너지가 땀과 함께 몇 초 만에 사라져요.', body_nl = 'Hij is zijn energie niet helemaal kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem op zijn rug neemt en paardje speelt, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke stress en die eindeloze energie zwetend in een paar seconden.', body_pl = 'Nie wyładował do końca energii i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy weźmie go na barana i pogalopuje jak koń, śmiech wypełni pokój, a całe nagromadzone napięcie i ta niewyczerpana energia znikną w kilka sekund.', body_pt = 'Não conseguiu gastar toda a energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele põe a criança às costas e faz de cavalo a galopar, as gargalhadas enchem o quarto e todo o stress físico acumulado, aquela energia sem fim, desaparece em segundos, a suar.', body_sv = 'Barnet har inte fått ur sig all energi och vägrar gå och lägga sig. Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och all ansamlad fysisk stress och den ändlösa energin försvinner på några sekunder i form av svett.', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố cõng bé chơi trò cưỡi ngựa, tiếng cười ngập tràn căn phòng, mọi căng thẳng thể chất và nguồn năng lượng bất tận ấy sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', body_zh = '精力还没释放完，就是不肯上床。叫爸爸来帮忙吧。爸爸把宝宝驮在背上“骑大马”时，笑声充满房间，积攒的所有身体压力和用不完的精力，几秒钟内就随着汗水消失了。' WHERE id = 'a7cb2140-287a-4406-a2b5-5d7c82c31a2d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Mírame!» 👀', body_es = 'Salta del sofá y, haciendo el mismo movimiento exactamente 50 veces, dice cada vez: «¡Mamá, mírame!». Aparta los ojos del móvil. No salta por el movimiento en sí, sino por ese brillo de aprobación en tus ojos. Dale 5 minutos sin interrupciones para que se llene.', title_fr = 'La période du « Regarde-moi ! » 👀', body_fr = 'Il saute du canapé et refait exactement le même geste 50 fois en criant « Maman, regarde-moi ! ». Quittez le téléphone des yeux. Il ne saute pas pour le geste lui-même, mais pour cette lueur d''approbation dans vos yeux. Donnez-lui 5 minutes sans interruption, qu''il soit comblé.', title_hi = '‘मुझे देखो!’ का दौर 👀', body_hi = 'सोफ़े से कूदता है और पूरे 50 बार वही हरकत करके कहता है, ‘माँ, मुझे देखो!’ फ़ोन से नज़र हटाइए। वह हरकत के लिए नहीं, आपकी आँखों में शाबाशी की उस चमक के लिए कूदता है। उसे बिना रुकावट 5 मिनट दीजिए, ताकि उसका मन भर जाए।', title_id = 'Masa ''Lihat aku!'' 👀', body_id = 'Ia melompat dari sofa, mengulang gerakan yang sama tepat 50 kali, dan setiap kali berkata ''Ma, lihat aku!''. Alihkan mata dari ponsel. Ia melompat bukan demi gerakannya, tapi demi kilau pengakuan di mata Anda. Beri ia 5 menit tanpa gangguan, biar ia puas.', title_ja = '「見て！」の時期 👀', body_ja = 'ソファからジャンプして、同じ動きをちょうど50回くり返すたびに「ママ、見て！」。スマホから目を離して。ジャンプそのもののためではなく、あなたの目に浮かぶ「すごいね」の輝きのために跳んでいるんです。とぎれない5分をあげて、満たしてあげましょう。', title_ko = '''나 좀 봐!'' 시기 👀', body_ko = '소파에서 뛰어내리며 똑같은 동작을 50번이나 하고 매번 ''엄마, 나 좀 봐!''라고 하나요? 휴대폰에서 눈을 떼세요. 동작 자체가 아니라 엄마 눈 속 인정의 반짝임을 위해 뛰는 거예요. 5분만 온전히 봐 주면 마음이 채워질 거예요.', title_nl = 'De ''Kijk naar mij!''-fase 👀', body_nl = 'Hij springt van de bank en doet precies 50 keer hetzelfde, en elke keer roept hij ''Mama, kijk naar mij!''. Kijk weg van je telefoon. Hij springt niet om het springen, maar voor die glinstering van goedkeuring in jouw ogen. Geef hem 5 minuten ononderbroken aandacht, tot hij vol is.', title_pl = 'Etap „Patrz na mnie!” 👀', body_pl = 'Skacze z kanapy, powtarza ten sam ruch równo 50 razy i za każdym razem woła „Mamo, patrz na mnie!”. Oderwij wzrok od telefonu. Nie skacze dla samego ruchu, tylko dla tego błysku uznania w twoich oczach. Daj mu 5 minut nieprzerwanej uwagi, niech się nasyci.', title_pt = 'A fase do "Olha para mim!" 👀', body_pt = 'Salta do sofá e, de cada vez, repete o mesmo movimento exatamente 50 vezes a dizer "Mãe, olha para mim!". Tire os olhos do telemóvel. Ele não salta pelo movimento em si, mas por aquele brilho de aprovação nos seus olhos. Dê-lhe 5 minutos sem interrupções e ele fica satisfeito.', title_sv = 'Perioden ”Titta på mig!” 👀', body_sv = 'Barnet hoppar från soffan och gör samma sak precis 50 gånger och säger varje gång ”Mamma, titta på mig!”. Ta blicken från telefonen. Barnet hoppar inte för rörelsens skull, utan för bekräftelsen som glittrar i dina ögon. Ge barnet 5 oavbrutna minuter, så blir det mätt på det.', title_vi = 'Giai đoạn "Mẹ nhìn này!" 👀', body_vi = 'Bé nhảy từ sofa xuống, lặp lại đúng một động tác tới 50 lần và lần nào cũng nói "Mẹ ơi, nhìn con này!". Hãy rời mắt khỏi điện thoại. Bé nhảy không phải vì động tác, mà vì ánh mắt công nhận lấp lánh của mẹ. Hãy dành cho bé 5 phút trọn vẹn để bé thấy đủ đầy.', title_zh = '“看我！”时期 👀', body_zh = '从沙发上跳下来，同一个动作做了整整50遍，每次都喊“妈妈，看我！”。把目光从手机上移开。宝宝跳，不是为了动作本身，而是为了你眼中那一闪而过的肯定。给宝宝不被打断的5分钟，让宝宝满足吧。' WHERE id = 'e21478c9-e278-43bf-8cfc-ce997f28ab6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '0 decibelios con el Medidor de sonido 🤫', body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro descansa poco a poco y cómo te masajea este silencio visual.', title_fr = '0 décibel avec le Sonomètre 🤫', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau se reposer peu à peu et ce silence visuel vous masser.', title_hi = 'साउंड मीटर के साथ 0 डेसिबल 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे आराम पा रहा है और यह दिखती खामोशी कैसे आपकी मसाज करती है।', title_id = '0 desibel dengan Pengukur Suara 🤫', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan bagaimana otak Anda perlahan beristirahat dan keheningan visual ini memijat Anda.', title_ja = 'サウンドメーターで0デシベル 🤫', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ休まっていくのを、この目に見える静けさがマッサージしてくれるのを感じてみましょう。', title_ko = '소음 측정기로 0데시벨 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬고, 이 시각적인 고요가 마사지해 주는 걸 느껴 보세요.', title_nl = '0 decibel met de Geluidsmeter 🤫', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam tot rust komt en hoe deze visuele stilte je masseert.', title_pl = '0 decybeli w Mierniku dźwięku 🤫', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli odpoczywa, a ta wizualna cisza robi ci masaż.', title_pt = '0 decibéis com o Medidor de Som 🤫', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta o seu cérebro a descansar devagarinho e este silêncio visual a fazer-lhe uma massagem.', title_sv = '0 decibel med Ljudmätaren 🤫', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen. Känn hur hjärnan sakta vilar och hur den visuella tystnaden masserar dig.', title_vi = '0 decibel cùng Đo âm thanh 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần được nghỉ ngơi, sự tĩnh lặng hiện ra trước mắt đang mát-xa cho mẹ thế nào.', title_zh = '用分贝仪看到0分贝 🤫', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，感受大脑正在一点点休息下来，这份看得见的安静又是怎样给你做按摩的。' WHERE id = '4a32ef42-8519-4a15-ae15-b2e86c604165' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile libre 🎶', body_es = 'Con el primer ritmo que oye, ya sea un anuncio o el claxon de un coche, se pone a bailar. ¡Mira la vida con su alegría! Únete a él en la habitación y bailad como locos unos minutos: todo tu estrés se irá volando.', title_fr = 'Danse libre 🎶', body_fr = 'Au premier rythme qu''il entend, que ce soit une pub ou un klaxon, il se met à danser. Regardez la vie avec sa joie ! Rejoignez-le dans la pièce pour quelques minutes de danse folle, tout votre stress s''envolera.', title_hi = 'खुलकर नाच 🎶', body_hi = 'पहली ही लय पर, चाहे विज्ञापन की धुन हो या गाड़ी का हॉर्न, नाचने लगता है। ज़िंदगी को उसकी तरह खुशी से देखिए! कमरे में उसके साथ कुछ मिनट धमाकेदार नाच कीजिए, आपका सारा तनाव उड़ जाएगा।', title_id = 'Menari bebas 🎶', body_id = 'Ia mulai menari mengikuti irama pertama yang ia dengar, entah suara iklan atau klakson mobil. Pandanglah hidup seceria dia! Ikutlah menari gila-gilaan bersamanya di kamar beberapa menit, dan semua stres Anda akan terbang pergi.', title_ja = '自由なダンス 🎶', body_ja = 'CMの音でも車のクラクションでも、最初に聞こえたリズムで踊りだします。この子のように、明るく暮らしを見てみましょう！部屋で一緒に数分間めちゃくちゃに踊れば、ストレスは全部飛んでいきます。', title_ko = '자유로운 춤 🎶', body_ko = '광고 음악이든 자동차 경적이든 처음 들리는 리듬에 바로 춤추기 시작하나요? 아이처럼 즐겁게 삶을 바라보세요! 방에서 함께 몇 분간 신나게 막춤을 추면 스트레스가 다 날아갈 거예요.', title_nl = 'Vrij dansen 🎶', body_nl = 'Bij het eerste ritme dat hij hoort, of het nu een reclamedeuntje of een autotoeter is, begint hij te dansen. Kijk net zo vrolijk naar het leven als hij! Doe in de kamer een paar minuten mee met een gekke dans, en al je stress vliegt weg.', title_pl = 'Swobodny taniec 🎶', body_pl = 'Zaczyna tańczyć do pierwszego rytmu, jaki usłyszy, czy to dżingla z reklamy, czy klaksonu samochodu. Patrz na życie tak radośnie jak on! Dołącz do niego w pokoju na kilka minut szalonego tańca, a cały stres odleci.', title_pt = 'Dança livre 🎶', body_pt = 'Ao primeiro ritmo que ouve, seja o som de um anúncio ou a buzina de um carro, começa a dançar. Encare a vida com a alegria dele! Junte-se a ele no quarto e façam uns minutos de dança maluca: todo o seu stress vai desaparecer.', title_sv = 'Fri dans 🎶', body_sv = 'Vid första rytmen barnet hör, vare sig det är en reklam eller en biltuta, börjar det dansa. Se på livet lika glatt som barnet! Häng med i rummet och dansa galet i några minuter, så flyger all stress iväg.', title_vi = 'Nhảy múa tự do 🎶', body_vi = 'Bé bắt đầu nhảy theo bất cứ nhịp điệu nào nghe thấy đầu tiên, dù là nhạc quảng cáo hay tiếng còi xe. Hãy nhìn cuộc sống vui vẻ như bé! Cùng bé nhảy điên cuồng trong phòng vài phút, mọi căng thẳng của mẹ sẽ bay biến.', title_zh = '自由舞蹈 🎶', body_zh = '听到第一个节奏就跳起舞来，不管是广告声还是汽车喇叭声。像宝宝一样快乐地看待生活吧！在房间里加入宝宝，疯狂地跳上几分钟，所有的压力都会飞走。' WHERE id = '5db98ad2-4a41-4a94-8924-de68639a6a28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimiento: orgullo por su desarrollo 📈', body_es = '¡Ya no es un bebé! Es una persona completa, con sus propias decisiones, sus preguntas curiosas y un corazón enorme. ¡Lo estás haciendo de maravilla!', title_fr = 'Le Suivi, fierté du développement 📈', body_fr = 'Ce n''est plus un bébé ! C''est une vraie personne, avec ses propres décisions, ses questions étonnantes et un cœur immense. Vous faites un travail formidable !', title_hi = 'ट्रैकर: विकास पर गर्व 📈', body_hi = 'वह अब छोटा बच्चा नहीं! वह अपने फ़ैसलों, अजीब सवालों और बड़े दिल वाला पूरा इंसान है। आप बहुत अच्छा काम कर रही हैं!', title_id = 'Pelacak: bangga pada perkembangan 📈', body_id = 'Ia bukan bayi lagi! Ia sudah menjadi pribadi utuh dengan keputusannya sendiri, pertanyaan-pertanyaan aneh, dan hati yang besar. Kamu melakukannya dengan sangat baik!', title_ja = 'トラッカー：成長の誇り 📈', body_ja = 'もう赤ちゃんじゃない！自分の考えと、ふしぎな質問と、大きな心を持った、ひとりの立派な人です。あなたは本当によくやっています！', title_ko = '기록 - 성장의 자부심 📈', body_ko = '이제 아기가 아니에요! 자기 결정과 엉뚱한 질문, 커다란 마음을 가진 온전한 한 사람이에요. 엄마는 정말 잘하고 있어요!', title_nl = 'Groeitracker: trots op zijn ontwikkeling 📈', body_nl = 'Hij is geen baby meer! Hij is een compleet mensje met zijn eigen beslissingen, rare vragen en een enorm groot hart. Je doet het geweldig!', title_pl = 'Śledzenie rozwoju: powód do dumy 📈', body_pl = 'To już nie maluszek! To pełny człowiek z własnymi decyzjami, dziwnymi pytaniami i ogromnym sercem. Świetnie sobie radzisz!', title_pt = 'Registo: orgulho do desenvolvimento 📈', body_pt = 'Já não é um bebé! É uma pessoa completa, com decisões próprias, perguntas estranhas e um coração enorme. Está a fazer um trabalho excelente!', title_sv = 'Spåraren: stolt över utvecklingen 📈', body_sv = 'Barnet är ingen bebis längre! Barnet är en hel människa med egna beslut, konstiga frågor och ett enormt hjärta. Du gör ett fantastiskt jobb!', title_vi = 'Theo dõi - Niềm tự hào phát triển 📈', body_vi = 'Bé không còn là em bé nữa! Bé đã là một con người trọn vẹn với những quyết định riêng, những câu hỏi kỳ lạ và một trái tim to lớn. Mẹ đang làm rất tuyệt!', title_zh = '发育追踪：成长的骄傲 📈', body_zh = '宝宝已经不是小婴儿了！而是一个有自己主见、有奇怪问题、有一颗大大的心的完整的人。你做得非常棒！' WHERE id = '8095b6da-2b93-462b-bce2-881fa1732924' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las fronteras de la alfombra 🗺️', body_es = 'Ha dictado una ley: de la habitación a la cocina solo se va pisando las líneas rojas de la alfombra. La motricidad gruesa y la atención trabajan juntas. No rompas esta norma sin lógica: baila tú también con él sobre las líneas y haz así tu ejercicio de la mañana.', title_fr = 'Les frontières du tapis 🗺️', body_fr = 'Il a décrété une loi : pour aller de la chambre à la cuisine, on ne marche que sur les lignes rouges du tapis. Sa motricité globale et son attention travaillent ensemble. Ne brisez pas cette règle sans logique, dansez avec lui sur les lignes et faites-en votre gym du matin.', title_hi = 'कालीन पर सीमा रेखाएँ 🗺️', body_hi = 'उसने नियम बना दिया है कि कमरे से रसोई तक सिर्फ़ कालीन की लाल लकीरों पर पैर रखकर जाना है। बड़ी मोटर स्किल्स और ध्यान साथ काम कर रहे हैं। इस बेतुके नियम को मत तोड़िए, आप भी उसके साथ लकीरों पर नाचते हुए सुबह का व्यायाम कीजिए।', title_id = 'Garis batas di karpet 🗺️', body_id = 'Ia membuat aturan: dari kamar ke dapur hanya boleh berjalan dengan menginjak garis merah di karpet. Motorik kasar dan perhatiannya bekerja bersama. Jangan langgar aturan tak masuk akal ini, ikutlah menari di atas garis bersamanya dan jadikan olahraga pagi Anda.', title_ja = 'じゅうたんの国境線 🗺️', body_ja = '部屋からキッチンまで、じゅうたんの赤い線だけをふんで行くという法律をつくりました。体の大きな動きと注意力が一緒に働いています。この理屈のないルールをやぶらないで、あなたも一緒に線の上で踊って、朝の運動にしましょう。', title_ko = '카펫 위의 국경선 🗺️', body_ko = '방에서 부엌까지 카펫의 빨간 선만 밟고 가야 한다는 법을 만들었나요? 대근육 운동과 집중력이 함께 일하고 있어요. 이 엉뚱한 규칙을 깨지 말고 엄마도 함께 선 위에서 춤추며 아침 운동을 해 보세요.', title_nl = 'Grenslijnen op het tapijt 🗺️', body_nl = 'Hij heeft een wet bedacht: van de kamer naar de keuken mag je alleen over de rode lijnen van het tapijt lopen. Grove motoriek en concentratie werken samen. Breek deze onlogische regel niet, maar dans met hem mee over de lijnen en doe zo je ochtendgymnastiek.', title_pl = 'Linie graniczne na dywanie 🗺️', body_pl = 'Ustanowił prawo, że z pokoju do kuchni można przejść tylko po czerwonych liniach dywanu. Motoryka duża i uwaga pracują razem. Nie łam tej nielogicznej zasady, zatańcz z nim na liniach i zrób tak swoją poranną gimnastykę.', title_pt = 'Linhas de fronteira no tapete 🗺️', body_pt = 'Criou a lei de que do quarto à cozinha só se pode ir pisando as linhas vermelhas do tapete. A motricidade grossa e a atenção trabalham em conjunto. Não quebre esta regra sem lógica: dance também com ele por cima das linhas e faça o seu exercício matinal.', title_sv = 'Gränslinjer på mattan 🗺️', body_sv = 'Barnet har stiftat en lag om att man bara får gå från rummet till köket på mattans röda linjer. Grovmotorik och uppmärksamhet arbetar tillsammans. Bryt inte den ologiska regeln, dansa med på linjerna och gör din morgongymnastik.', title_vi = 'Đường ranh giới trên thảm 🗺️', body_vi = 'Bé đặt ra luật: từ phòng xuống bếp chỉ được giẫm lên những đường kẻ đỏ trên thảm. Kỹ năng vận động thô và sự tập trung đang cùng hoạt động. Đừng phá quy tắc "vô lý" này, hãy cùng bé nhảy múa trên các đường kẻ như một bài tập thể dục buổi sáng.', title_zh = '地毯上的边界线 🗺️', body_zh = '定了条“法律”：从房间到厨房，只能踩着地毯上的红色线条走。大动作和注意力一起在运转。别破坏这条没逻辑的规矩，你也和宝宝一起在线条上跳着舞，做做晨练吧。' WHERE id = '064149bc-eacb-463c-b371-3ee4af7db167' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Teatro bajo la almohada 🎪', body_es = 'Se ha metido en la cama, pero ha puesto la cabeza debajo de la almohada y habla solo. Oscurece del todo la habitación. Deja que en ese refugio oscuro y seguro monte sus propios guiones y pase poco a poco al mundo del sueño. No intervengas.', title_fr = 'Théâtre sous l''oreiller 🎪', body_fr = 'Il est au lit, mais la tête sous l''oreiller, et se parle tout seul. Faites le noir complet dans la chambre. Laissez-le construire ses propres scénarios dans ce refuge sombre et rassurant et glisser peu à peu dans le monde du sommeil, n''intervenez pas.', title_hi = 'तकिए के नीचे थिएटर 🎪', body_hi = 'बिस्तर में तो आ गया, पर सिर तकिए के नीचे डालकर खुद से बातें करता है। कमरा पूरी तरह अँधेरा कीजिए। उसे उस अँधेरे, सुरक्षित ठिकाने में अपनी कहानियाँ गढ़ते हुए धीरे-धीरे नींद की दुनिया में जाने दीजिए, बीच में मत आइए।', title_id = 'Teater di bawah bantal 🎪', body_id = 'Ia sudah di tempat tidur, tapi menyembunyikan kepala di bawah bantal dan berbicara sendiri. Gelapkan kamar sepenuhnya. Biarkan ia menyusun skenarionya sendiri di tempat berlindung yang gelap dan aman itu, lalu perlahan beralih ke dunia mimpi. Jangan ikut campur.', title_ja = '枕の下の劇場 🎪', body_ja = 'ベッドに入ったのに、頭を枕の下につっこんでひとりでおしゃべりしています。部屋を真っ暗にしましょう。その暗くて安全な隠れ家で、自分のシナリオをつくりながら、少しずつ夢の世界へ移っていけるように、じゃましないで。', title_ko = '베개 밑 극장 🎪', body_ko = '침대에 누웠는데 머리를 베개 밑에 넣고 혼잣말을 하나요? 방을 완전히 어둡게 하세요. 그 어둡고 안전한 은신처에서 자기만의 이야기를 만들며 천천히 꿈나라로 넘어가게 두고, 끼어들지 마세요.', title_nl = 'Theater onder het kussen 🎪', body_nl = 'Hij ligt in bed, maar met zijn hoofd onder het kussen, en praat in zichzelf. Maak de kamer helemaal donker. Laat hem in die donkere, veilige schuilplek zijn eigen verhaaltjes bedenken en langzaam overgaan naar dromenland. Grijp niet in.', title_pl = 'Teatr pod poduszką 🎪', body_pl = 'Leży w łóżku, ale z głową pod poduszką i mówi coś do siebie. Zaciemnij pokój całkowicie. Niech w tej ciemnej, bezpiecznej kryjówce układa własne scenariusze i powoli przenosi się do krainy snu, nie przeszkadzaj.', title_pt = 'Teatro debaixo da almofada 🎪', body_pt = 'Deitou-se, mas pôs a cabeça debaixo da almofada e fala sozinho. Escureça bem o quarto. Deixe-o criar os seus enredos neste refúgio escuro e seguro e passar devagar para o mundo do sono, sem intervir.', title_sv = 'Teater under kudden 🎪', body_sv = 'Barnet har gått och lagt sig men stoppat huvudet under kudden och pratar för sig själv. Gör rummet helt mörkt. Låt barnet bygga sina egna scenarier i det mörka, trygga gömstället och sakta glida in i drömvärlden, lägg dig inte i.', title_vi = 'Nhà hát dưới gối 🎪', body_vi = 'Bé đã lên giường nhưng lại vùi đầu dưới gối và tự nói chuyện một mình. Hãy làm tối hẳn căn phòng. Để bé tự dựng kịch bản trong "nơi trú ẩn" tối và an toàn ấy rồi dần chìm vào thế giới giấc ngủ, đừng can thiệp.', title_zh = '枕头下的剧场 🎪', body_zh = '上了床，却把头埋在枕头底下自言自语。把房间完全调暗。让宝宝在那个黑暗又安全的小窝里编自己的剧本，慢慢过渡到梦乡吧，别打扰。' WHERE id = '2980ee34-de75-4617-8093-160c3c2da3a0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El examen de la pasta en el bolsillo 🍝', body_es = '¿Del bolsillo del pantalón que echaste a la lavadora ha salido pasta seca? Para ti es basura; para él, quizá una reserva por si le entraba hambre por el camino. No le reproches nada: anota estos primeros destellos de su capacidad de planificar en el Seguimiento del desarrollo como un recuerdo cómico.', title_fr = 'L''énigme des pâtes dans la poche 🍝', body_fr = 'Des pâtes sèches sont sorties de la poche du pantalon que vous avez mis à la machine ? Pour vous, un déchet, pour lui, peut-être une réserve au cas où il aurait faim en route. Ne le jugez pas, notez ces premières étincelles de planification dans le Suivi de développement, comme un souvenir comique.', title_hi = 'जेब में पास्ता की परीक्षा 🍝', body_hi = 'वॉशिंग मशीन में डाली पैंट की जेब से सूखा पास्ता निकला? आपके लिए कचरा, उसके लिए शायद ‘रास्ते में भूख लगी तो’ वाला स्टॉक। उसे दोष मत दीजिए, योजना बनाने की इस काबिलियत की पहली झलक को ग्रोथ ट्रैकर में मज़ेदार याद की तरह दर्ज कीजिए।', title_id = 'Ujian pasta di saku 🍝', body_id = 'Dari saku celana yang Anda masukkan ke mesin cuci keluar pasta kering? Bagi Anda sampah, baginya mungkin bekal ''kalau lapar di jalan''. Jangan menyalahkannya, catat percikan pertama kemampuan merencanakan ini di Pelacak Perkembangan sebagai kenangan lucu.', title_ja = 'ポケットのパスタ検査 🍝', body_ja = '洗濯機に入れようとしたズボンのポケットから、かわいたパスタが出てきた？あなたにはゴミでも、この子には「途中でおなかがすいたとき用」の備えかもしれません。責めないで。この計画する力の最初のきざしを、おかしな思い出として「発達トラッカー」に記録しましょう。', title_ko = '주머니 속 파스타 시험 🍝', body_ko = '세탁기에 넣은 바지 주머니에서 마른 파스타가 나왔나요? 엄마에겐 쓰레기지만 아이에겐 ''가다가 배고플지도 몰라'' 비상식량일지도 몰라요. 탓하지 말고 계획 능력의 첫 불씨를 웃긴 추억으로 성장 기록에 남겨 두세요.', title_nl = 'Pasta in de broekzak 🍝', body_nl = 'Kwam er uit de broekzak die je in de wasmachine gooide een gedroogde macaroni? Voor jou afval, voor hem misschien een noodvoorraad voor als hij onderweg honger krijgt. Veroordeel hem niet, maar noteer deze eerste vonkjes van plannen als grappige herinnering in de Groeitracker.', title_pl = 'Makaronowa niespodzianka w kieszeni 🍝', body_pl = 'Z kieszeni spodni wrzuconych do pralki wypadł suchy makaron? Dla ciebie to śmieć, dla niego może zapas na wypadek głodu w drodze. Nie obwiniaj go, zapisz te pierwsze przebłyski umiejętności planowania w Śledzeniu rozwoju jako zabawne wspomnienie.', title_pt = 'O mistério da massa no bolso 🍝', body_pt = 'Do bolso das calças que pôs na máquina saiu massa seca? Para si é lixo, para ele talvez seja uma reserva "para o caso de ter fome pelo caminho". Não o censure: registe estes primeiros sinais de capacidade de planeamento no Registo de Crescimento, como recordação cómica.', title_sv = 'Pastaprovet i fickan 🍝', body_sv = 'Hittade du torkad pasta i fickan på byxorna du lade i tvättmaskinen? För dig är det skräp, för barnet kanske en reserv ”ifall jag blir hungrig på vägen”. Döm inte barnet, anteckna de första gnistorna av planeringsförmåga i Utvecklingsspåraren som ett roligt minne.', title_vi = 'Bí ẩn mì ống trong túi quần 🍝', body_vi = 'Mẹ lôi ra một miếng mì ống khô từ túi quần vừa bỏ vào máy giặt? Với mẹ là rác, còn với bé có lẽ là "đồ dự trữ phòng khi đói trên đường". Đừng trách bé, hãy ghi lại những tia sáng đầu tiên của khả năng lập kế hoạch này trong Theo dõi phát triển như một kỷ niệm hài hước.', title_zh = '口袋里的意面考验 🍝', body_zh = '从扔进洗衣机的裤子口袋里掏出了干掉的意面？在你看来是垃圾，对宝宝来说也许是“路上饿了”的储备粮。别责怪宝宝，把这份计划能力最初的火花，当作搞笑的回忆记在发育追踪里吧。' WHERE id = 'af38ac43-154c-4c60-9f01-51c84d74b264' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La exigencia de «¡Sécame el agua!» 💧', body_es = 'En lugar de beberse el agua del vaso, grita: «Está muy mojada, ¡sécala!». Bienvenida al absurdo de los 3 años y medio. Intentar explicárselo agotará tu energía. Dile «Vale, te traigo otra agua seca» y dale la misma agua en un vaso de otro color.', title_fr = 'Il veut qu''on « sèche l''eau » ! 💧', body_fr = 'Au lieu de boire l''eau de son gobelet, il crie : « Elle est trop mouillée, sèche-la ! » Bienvenue dans l''absurdité des 3 ans et demi. Essayer d''expliquer va vous vider de votre énergie. Dites « D''accord, je t''apporte une autre eau sèche » et servez la même eau dans un gobelet d''une autre couleur.', title_hi = '‘पानी सुखाओ!’ की माँग 💧', body_hi = 'गिलास का पानी पीने के बजाय चिल्लाता है, ‘यह बहुत गीला है, इसे सुखाओ।’ साढ़े 3 साल के बेतुकेपन में आपका स्वागत है। समझाने की कोशिश आपकी ऊर्जा खत्म कर देगी। ‘ठीक है, दूसरा सूखा पानी लाती हूँ’ कहकर अलग रंग के गिलास में वही पानी दे दीजिए।', title_id = 'Tuntutan ''Keringkan airnya!'' 💧', body_id = 'Alih-alih meminum air di gelas, ia berteriak ''Ini terlalu basah, keringkan!''. Selamat datang di absurditas usia 3,5 tahun. Berusaha menjelaskan hanya akan menghabiskan energi Anda. Katakan ''Baik, Mama ambilkan air kering yang lain'', lalu berikan air yang sama di gelas berwarna lain.', title_ja = '「お水をかわかして！」 💧', body_ja = 'コップのお水を飲む代わりに「これ、ぬれすぎ、かわかして」と叫ぶ。3歳半のおかしな世界へようこそ。説明しようとすると、エネルギーを使いはたしてしまいます。「わかった、かわいたお水を持ってくるね」と言って、別の色のコップで同じお水を出しましょう。', title_ko = '''물 말려 줘!'' 요구 💧', body_ko = '컵의 물을 마시는 대신 ''이거 너무 젖었어, 말려 줘!''라고 소리치나요? 세 살 반의 엉뚱함에 오신 걸 환영해요. 설명하려 하면 에너지만 바닥나요. ''알았어, 마른 물 가져올게'' 하고 다른 색 컵에 같은 물을 주세요.', title_nl = 'De eis: ''Maak het water droog!'' 💧', body_nl = 'In plaats van zijn water te drinken, roept hij: ''Dit is te nat, maak het droog!'' Welkom bij de absurditeit van 3,5 jaar. Proberen het uit te leggen kost je al je energie. Zeg ''Goed, ik haal ander, droog water'' en geef hem hetzelfde water in een beker met een andere kleur.', title_pl = 'Żądanie „Wysusz wodę!” 💧', body_pl = 'Zamiast pić wodę ze szklanki, krzyczy: „Jest za mokra, wysusz ją!”. Witaj w absurdzie 3,5-latka. Próby tłumaczenia wyczerpią twoją energię. Powiedz „Dobrze, przyniosę inną, suchą wodę” i podaj tę samą wodę w kubku innego koloru.', title_pt = 'A exigência do "Seca a água!" 💧', body_pt = 'Em vez de beber a água do copo, grita "Isto está muito molhado, seca-a". Bem-vinda ao absurdo dos 3 anos e meio. Tentar explicar só lhe vai gastar a energia. Diga "Está bem, vou buscar água seca" e dê-lhe a mesma água num copo de outra cor.', title_sv = 'Kravet ”Torka vattnet!” 💧', body_sv = 'Istället för att dricka vattnet i glaset skriker barnet: ”Det här är för blött, torka det!” Välkommen till 3,5-åringens absurditet. Att försöka förklara tar slut på din energi. Säg ”Okej, jag hämtar annat, torrt vatten” och ge samma vatten i ett glas med en annan färg.', title_vi = 'Đòi "Làm khô nước đi!" 💧', body_vi = 'Thay vì uống nước trong cốc, bé hét lên: "Nước ướt quá, làm khô đi!". Chào mừng đến với sự ngộ nghĩnh của tuổi 3,5. Cố giải thích chỉ làm cạn năng lượng của mẹ. Hãy nói "Được rồi, mẹ mang nước khô khác cho con" và đưa đúng chỗ nước đó trong một chiếc cốc màu khác.', title_zh = '“把水弄干！”的要求 💧', body_zh = '不喝杯子里的水，反而大喊：“这个太湿了，把它弄干！”欢迎来到3岁半的荒诞世界。试图解释只会耗光你的精力。说一句“好，我去拿别的干水”，用另一个颜色的杯子装上同样的水给宝宝。' WHERE id = '881d0866-6df6-4dec-801b-67b99df853c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El soborno secreto de papá 🤫', body_es = 'No quiere lavarse los dientes. Papá se le acerca a escondidas y le dice: «Si te lavas los dientes, te enseño la piedra mágica que llevo en el bolsillo». A veces las reglas de mamá tienen que romperse con estos juegos originales de papá, astutos pero que funcionan al instante.', title_fr = 'Le « pot-de-vin » secret de papa 🤫', body_fr = 'Il ne veut pas se brosser les dents. Papa s''approche discrètement : « Si tu te brosses les dents, je te montre la pierre magique dans ma poche. » Parfois, les règles de maman doivent céder devant ces jeux insolites, rusés mais aussitôt efficaces, des papas.', title_hi = 'पापा की गुप्त रिश्वत 🤫', body_hi = 'दाँत ब्रश नहीं करना चाहता। पापा चुपके से उसके पास जाकर कहते हैं, ‘दाँत साफ़ करोगे, तो जेब का जादुई पत्थर दिखाऊँगा।’ माँ के नियम कभी-कभी पापाओं के इन चालाक, पर तुरंत काम करने वाले अनोखे खेलों से टूटने ही चाहिए।', title_id = 'Suap rahasia Ayah 🤫', body_id = 'Ia tidak mau menggosok gigi. Ayah diam-diam mendekat dan berkata ''Kalau kamu sikat gigi, Ayah tunjukkan batu ajaib di saku Ayah''. Aturan ibu kadang memang harus dipatahkan oleh permainan tak biasa para ayah yang cerdik namun langsung berhasil.', title_ja = 'パパのひみつのごほうび 🤫', body_ja = '歯みがきをしたがらない。パパがこっそり近づいて「歯をみがいたら、ポケットの魔法の石を見せてあげる」と言う。ママのルールは、ときにパパたちのこうした巧妙だけれど、すぐに効くちょっと変わった遊びでやぶられるべきなんです。', title_ko = '아빠의 비밀 뇌물 🤫', body_ko = '이를 닦기 싫어하나요? 아빠가 몰래 다가가 ''이 닦으면 아빠 주머니 속 마법의 돌을 보여 줄게''라고 속삭여요. 엄마의 규칙도 가끔은 아빠들의 이런 꾀 많지만 바로 통하는 특별한 놀이로 깨질 필요가 있어요.', title_nl = 'Papa''s geheime omkoping 🤫', body_nl = 'Hij wil zijn tanden niet poetsen. Papa komt stiekem naast hem zitten: ''Als je je tanden poetst, laat ik je de magische steen in mijn zak zien.'' De regels van mama moeten soms wijken voor deze slimme, ongewone maar meteen werkende spelletjes van papa.', title_pl = 'Tajna „łapówka” taty 🤫', body_pl = 'Nie chce myć zębów. Tata podchodzi po cichu i mówi: „Jak umyjesz zęby, pokażę ci magiczny kamień z mojej kieszeni”. Mamine zasady czasem trzeba złamać takimi sprytnymi, niezwykłymi zabawami taty, które działają od razu.', title_pt = 'O "suborno" secreto do pai 🤫', body_pt = 'Não quer lavar os dentes. O pai aproxima-se às escondidas e diz: "Se lavares os dentes, mostro-te a pedra mágica que tenho no bolso". As regras da mãe às vezes têm de ser quebradas por estas brincadeiras invulgares e espertas dos pais, que funcionam logo.', title_sv = 'Pappas hemliga muta 🤫', body_sv = 'Barnet vill inte borsta tänderna. Pappa smyger fram och säger: ”Om du borstar tänderna ska jag visa dig den magiska stenen i min ficka.” Mammareglerna måste ibland brytas av pappornas listiga, ovanliga men direkt fungerande lekar.', title_vi = '"Hối lộ" bí mật của bố 🤫', body_vi = 'Bé không chịu đánh răng. Bố lén lại gần thì thầm: "Nếu con đánh răng, bố sẽ cho con xem viên đá thần kỳ trong túi bố". Đôi khi các quy tắc làm mẹ cần được phá vỡ bằng những trò chơi khác thường, khéo léo nhưng hiệu quả tức thì như thế của các ông bố.', title_zh = '爸爸的秘密“贿赂” 🤫', body_zh = '不肯刷牙。爸爸悄悄凑过去说：“刷完牙，就给你看我口袋里的魔法石头。”妈妈的规矩，有时就得靠爸爸们这些狡猾却立竿见影的特别游戏来打破。' WHERE id = 'd2f34bfd-32c7-43f7-89fd-d8226236a390' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mirando al mundo desde el balcón 👀', body_es = 'Sale al balcón, saluda a gritos con la mano a todo el que pasa y se ofende cuando no le responden. Su necesidad de contacto social está en su punto máximo. No le metas dentro de un tirón: protege su empatía sin herirla diciendo «Están muy lejos, a lo mejor no te han oído».', title_fr = 'Observer le monde depuis le balcon 👀', body_fr = 'Sur le balcon, il fait de grands signes en criant à chaque passant et se vexe quand personne ne répond. Son besoin de lien social est au maximum. Ne le tirez pas à l''intérieur : « Ils sont très loin, ils ne t''ont peut-être pas entendu », protégez son empathie sans la blesser.', title_hi = 'बालकनी से दुनिया को देखना 👀', body_hi = 'बालकनी में जाकर हर राहगीर को चिल्लाकर हाथ हिलाता है और जवाब न मिलने पर बुरा मान जाता है। लोगों से जुड़ने की ज़रूरत चरम पर है। उसे अंदर मत खींचिए, ‘वे बहुत दूर हैं, शायद सुन नहीं पाए’ कहकर उसकी सहानुभूति को ठेस पहुँचाए बिना सँभालिए।', title_id = 'Melihat dunia dari balkon 👀', body_id = 'Ia keluar ke balkon, melambai sambil berteriak kepada setiap orang yang lewat, lalu tersinggung saat tidak dibalas. Kebutuhannya akan hubungan sosial sedang di puncak. Jangan menariknya masuk, lindungi empatinya tanpa menyakitinya dengan berkata ''Mereka jauh sekali, mungkin tidak dengar''.', title_ja = 'バルコニーから世間をながめる 👀', body_ja = 'バルコニーに出て、通りかかる人みんなに大声で手をふり、返事がないとすねてしまう。人とつながりたい気持ちがピークです。部屋に引っぱりこまないで、「遠くにいるから、聞こえなかったのかもね」と言って、思いやりの気持ちを傷つけずに守りましょう。', title_ko = '베란다에서 세상 구경 👀', body_ko = '베란다에 나가 지나가는 모든 사람에게 소리치며 손을 흔들고, 대답이 없으면 서운해하나요? 사회적 연결 욕구가 한창이에요. 안으로 끌어들이지 말고 ''너무 멀어서 못 들었나 봐''라며 공감하는 마음을 다치지 않게 지켜 주세요.', title_nl = 'Vanaf het balkon de wereld bekijken 👀', body_nl = 'Hij staat op het balkon, roept en zwaait naar iedereen die voorbijkomt, en is beledigd als niemand terugzwaait. Zijn behoefte aan sociaal contact is op zijn hoogst. Trek hem niet naar binnen, maar bescherm zijn empathie: ''Ze zijn heel ver weg, misschien hoorden ze je niet.''', title_pl = 'Widok z balkonu na świat 👀', body_pl = 'Wychodzi na balkon, z krzykiem macha do wszystkich przechodniów i obraża się, gdy nie odpowiadają. Potrzeba kontaktu społecznego jest u szczytu. Nie wciągaj go do środka, chroń jego empatię bez ranienia: „Są bardzo daleko, może nie usłyszeli”.', title_pt = 'Olhar o mundo da varanda 👀', body_pt = 'Vai para a varanda, acena aos gritos a todos os que passam e fica ofendido quando não lhe respondem. A necessidade de contacto social está no auge. Não o puxe para dentro: diga "Estão muito longe, se calhar não ouviram" e proteja a empatia dele sem a magoar.', title_sv = 'Utsikt över samhället från balkongen 👀', body_sv = 'Barnet går ut på balkongen, ropar och vinkar till alla som går förbi och blir sårat när ingen svarar. Behovet av social kontakt är på topp. Dra inte in barnet, säg ”De är väldigt långt bort, de kanske inte hörde” och skydda barnets empati utan att såra.', title_vi = 'Ngắm thế giới từ ban công 👀', body_vi = 'Bé ra ban công, hét to vẫy tay với mọi người đi ngang qua, và giận dỗi khi không ai đáp lại. Nhu cầu kết nối xã hội đang ở đỉnh điểm. Đừng lôi bé vào trong, hãy nói "Họ ở xa quá, có lẽ không nghe thấy con" để bảo vệ sự đồng cảm của bé mà không làm bé tổn thương.', title_zh = '从阳台看世界 👀', body_zh = '跑到阳台上，对着每个路过的人大喊挥手，没人回应就伤心。社交连接的需求正处于高峰。别把宝宝拽回屋里，说一句“他们离得太远了，可能没听见”，在不伤害共情的前提下保护宝宝。' WHERE id = 'f968f309-08cf-46ae-901b-44ed8420ced0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sesión de lectura en silencio 📖', body_es = 'Esta noche nadie habla. Abre Cuentos inteligentes y, en lugar de leer el texto en voz alta, mirad las imágenes en silencio acompañados de los suaves sonidos de la naturaleza del dispositivo. La memoria visual le cansará y le llevará al sueño automáticamente.', title_fr = 'Séance de lecture silencieuse 📖', body_fr = 'Ce soir, personne ne parle. Ouvrez les Contes intelligents et, au lieu de lire le texte à voix haute, regardez les images en silence, accompagnés des doux sons de la nature de l''appareil. La mémoire visuelle le fatiguera et l''emmènera automatiquement vers le sommeil.', title_hi = 'चुपचाप किताब पढ़ने का सत्र 📖', body_hi = 'आज शाम कोई नहीं बोलेगा। स्मार्ट कहानियाँ खोलिए, कहानी ज़ोर से पढ़ने के बजाय डिवाइस से आती प्रकृति की धीमी आवाज़ों के साथ चुपचाप तस्वीरें देखिए। दिखने वाली याददाश्त उसे थकाकर अपने-आप नींद में ले जाएगी।', title_id = 'Sesi membaca tanpa suara 📖', body_id = 'Malam ini tidak ada yang bicara. Buka Dongeng Pintar, dan alih-alih membaca teks keras-keras, pandangi gambarnya diam-diam diiringi suara alam yang lembut dari perangkat. Memori visual akan membuatnya lelah dan otomatis membawanya tidur.', title_ja = '静かな絵本の時間 📖', body_ja = '今夜は誰も話しません。「スマートおはなし」を開いて、文章を声に出して読む代わりに、端末から流れるやさしい自然の音を聞きながら、静かに絵を眺めましょう。目で覚えることに疲れて、自然と眠りへ導かれます。', title_ko = '조용한 책 읽기 시간 📖', body_ko = '오늘 저녁엔 아무도 말하지 않아요. 스마트 동화를 열고 글을 소리 내어 읽는 대신, 기기에서 나오는 잔잔한 자연의 소리와 함께 그림만 조용히 보세요. 시각적 기억이 아이를 지치게 해 저절로 잠들게 할 거예요.', title_nl = 'Stil boekjesuurtje 📖', body_nl = 'Vanavond praat niemand. Open Slimme sprookjes en lees de tekst niet voor, maar kijk samen stil naar de plaatjes met de zachte natuurgeluiden uit je telefoon op de achtergrond. Zijn visuele geheugen raakt moe en hij valt vanzelf in slaap.', title_pl = 'Ciche czytanie książeczki 📖', body_pl = 'Dziś wieczorem nikt nie mówi. Otwórz Mądre bajki i zamiast czytać na głos, w ciszy oglądajcie obrazki przy łagodnych odgłosach natury płynących z urządzenia. Pamięć wzrokowa go zmęczy i sama zaprowadzi w sen.', title_pt = 'Sessão de leitura silenciosa 📖', body_pt = 'Esta noite ninguém fala. Abra as Histórias Inteligentes e, em vez de ler o texto em voz alta, vejam as imagens em silêncio, acompanhados por suaves sons da natureza do aparelho. A memória visual vai cansá-lo e levá-lo automaticamente para o sono.', title_sv = 'Tyst lässtund 📖', body_sv = 'I kväll pratar ingen. Öppna Smarta sagor, och istället för att läsa texten högt, titta tyst på bilderna till milda naturljud från enheten. Det visuella minnet tröttar ut barnet och för det automatiskt in i sömnen.', title_vi = 'Buổi đọc sách yên lặng 📖', body_vi = 'Tối nay không ai nói gì cả. Hãy mở Truyện cổ tích thông minh, thay vì đọc to, hãy lặng lẽ cùng bé ngắm tranh, kèm theo âm thanh thiên nhiên êm dịu phát ra từ thiết bị. Trí nhớ thị giác sẽ khiến bé mỏi mệt và tự động đưa bé vào giấc ngủ.', title_zh = '无声读书时光 📖', body_zh = '今晚谁都不说话。打开智慧童话，不出声朗读，而是伴着设备里传来的轻柔大自然声音，安静地看图画。视觉记忆会让宝宝累了，自动带宝宝进入梦乡。' WHERE id = '01eb4758-ff80-4ee6-b2d8-884207fd7862' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lado «equivocado» del huevo 🍳', body_es = 'Hay una gran crisis porque cortaste el huevo duro por la mitad: «¡Yo lo quería entero!». La presentación de la comida es su punto más sensible. Mira en Recetas saludables cómo presentar la comida con la forma adecuada y con cortes divertidos.', title_fr = 'Le « mauvais » côté de l''œuf 🍳', body_fr = 'Grosse crise parce que vous avez coupé l''œuf dur en deux. « Je le voulais entier ! » La présentation des aliments est leur point le plus sensible. Parcourez les Recettes saines pour apprendre à présenter les aliments sous la bonne forme et avec des découpes amusantes.', title_hi = 'अंडे की ‘गलत’ तरफ़ 🍳', body_hi = 'उबला अंडा बीच से काट दिया, तो बड़ा संकट खड़ा हो गया। ‘मुझे पूरा चाहिए था!’ खाने का रूप उनकी सबसे नाज़ुक नस है। सेहतमंद रेसिपी देखकर सीखिए कि खाना सही आकार में और मज़ेदार कटिंग के साथ कैसे परोसें।', title_id = 'Sisi telur yang ''salah'' 🍳', body_id = 'Terjadi krisis besar karena Anda memotong telur rebus di tengah. ''Aku maunya utuh!'' Tampilan makanan adalah titik paling sensitif mereka. Lihat Resep Sehat dan pelajari cara menyajikan makanan dalam bentuk yang tepat dan potongan yang seru.', title_ja = '卵の「まちがった」切り方 🍳', body_ja = 'ゆで卵をまんなかで切ったら、大きなかんしゃくに。「まるごとがよかったの！」見た目のデザインは、この子たちのいちばん敏感なポイントです。「ヘルシーレシピ」で、食べ物をちょうどいい形や楽しい切り方で出すコツを学びましょう。', title_ko = '달걀의 ''잘못된'' 쪽 🍳', body_ko = '삶은 달걀을 반으로 잘랐다고 큰 위기가 터졌나요? ''통째로 먹고 싶었단 말이야!'' 음식 모양은 아이들의 가장 예민한 부분이에요. 건강한 레시피를 보며 음식을 알맞은 모양과 재미있는 썰기로 차려 내는 법을 배워 보세요.', title_nl = 'De ''verkeerde'' kant van het ei 🍳', body_nl = 'Er breekt een grote crisis uit omdat je het gekookte ei doormidden sneed: ''Ik wilde hem heel!'' Hoe het eten eruitziet, is hun gevoeligste punt. Kijk in Gezonde recepten en leer hoe je eten in de juiste vorm en met leuke snijtechnieken opdient.', title_pl = '„Zła” strona jajka 🍳', body_pl = 'Wielki kryzys, bo przekroiłaś ugotowane jajko na pół. „Chciałem całe!” Wygląd jedzenia to ich najczulszy punkt. Zajrzyj do Zdrowych przepisów i dowiedz się, jak podawać jedzenie we właściwej formie i w zabawnych kształtach.', title_pt = 'O "lado errado" do ovo 🍳', body_pt = 'Há uma grande crise porque cortou o ovo cozido ao meio: "Eu queria-o inteiro!". O design da comida é o ponto mais sensível deles. Veja nas Receitas Saudáveis como apresentar os alimentos na forma certa e com cortes divertidos.', title_sv = 'Äggets ”fel” sida 🍳', body_sv = 'Det blir en stor kris för att du skar det kokta ägget på mitten. ”Jag ville ha det helt!” Matens utseende är deras mest känsliga punkt. Titta i Hälsosamma recept och lär dig hur du serverar maten i rätt form och med roliga snitt.', title_vi = 'Mặt "sai" của quả trứng 🍳', body_vi = 'Một cơn khủng hoảng lớn nổ ra chỉ vì mẹ bổ đôi quả trứng luộc: "Con muốn nguyên quả cơ!". Cách bày biện thức ăn là điểm nhạy cảm nhất của bé. Hãy xem Công thức lành mạnh để học cách trình bày món ăn đúng hình dạng và cắt tỉa vui mắt.', title_zh = '鸡蛋“切错了” 🍳', body_zh = '就因为你把煮鸡蛋从中间切开，一场大危机爆发了：“我要的是完整的！”食物的样子是他们最敏感的地方。去健康食谱里看看，学学如何用正确的形状和有趣的切法来呈现食物。' WHERE id = 'fae36977-58eb-48b1-8551-438307ad854b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detective en la naturaleza 🔍', body_es = 'En el parque se ha quedado 20 minutos inmóvil solo para observar un hormiguero. No le metas prisa. Si con el asistente Tiempo y ropa le vestiste de antemano según el tiempo y con una capa gruesa por debajo, deja que este pequeño biólogo descubra el mundo.', title_fr = 'Le détective de la nature 🔍', body_fr = 'Au parc, il est resté 20 minutes immobile juste pour observer une fourmilière. Ne le pressez pas. Si vous l''avez habillé chaudement et selon la météo à l''avance grâce à Météo et tenue, laissez ce petit biologiste explorer le monde.', title_hi = 'प्रकृति का जासूस 🔍', body_hi = 'पार्क में बस चींटियों का बिल देखने के लिए 20 मिनट बिना हिले बैठा रहा। जल्दी मत कराइए। अगर आपने मौसम और कपड़े असिस्टेंट से पहले ही मौसम के हिसाब से मोटे कपड़े पहनाए हैं, तो इस नन्हे जीव विज्ञानी को दुनिया खोजने दीजिए।', title_id = 'Detektif di alam 🔍', body_id = 'Di taman ia duduk diam 20 menit hanya untuk mengamati sarang semut. Jangan terburu-buru. Jika sebelumnya Anda sudah memakaikan pakaian sesuai cuaca dan alas yang tebal dengan bantuan Cuaca dan Pakaian, biarkan ahli biologi kecil ini menjelajahi dunia.', title_ja = '自然の中の探偵 🔍', body_ja = '公園で、アリの巣を眺めるためだけに20分も動かずに座っていた。急がせないで。「天気と服装」で前もって天気に合った、あたたかい服を着せておいたなら、この小さな生物学者に世界を発見させてあげましょう。', title_ko = '자연 속 탐정 🔍', body_ko = '공원에서 개미집을 보느라 20분 동안 꼼짝 않고 앉아 있었나요? 재촉하지 마세요. 날씨와 옷차림 도우미로 미리 날씨에 맞게 따뜻하게 입혔다면, 이 작은 생물학자가 마음껏 세상을 탐험하게 해 주세요.', title_nl = 'Natuurdetective 🔍', body_nl = 'In het park zat hij 20 minuten stil om alleen maar een mierennest te bekijken. Haast hem niet. Heb je hem vooraf met de assistent Weer en kleding passend en warm genoeg aangekleed, laat deze kleine bioloog dan de wereld ontdekken.', title_pl = 'Detektyw na łonie natury 🔍', body_pl = 'W parku przez 20 minut siedział bez ruchu, tylko obserwując mrowisko. Nie poganiaj go. Jeśli wcześniej z narzędziem Pogoda i ubiór ubrałaś go odpowiednio do pogody i ciepło od spodu, niech ten mały biolog odkrywa świat.', title_pt = 'O detetive da natureza 🔍', body_pt = 'No parque, ficou 20 minutos sentado sem se mexer só para observar um formigueiro. Não o apresse. Se com o assistente Tempo e Roupa já o vestiu de acordo com o tempo, com roupa quente por baixo, deixe este pequeno biólogo descobrir o mundo.', title_sv = 'Detektiv i naturen 🔍', body_sv = 'I parken satt barnet orörligt i 20 minuter bara för att titta på en myrstack. Stressa inte barnet. Om du i förväg har klätt barnet efter vädret med hjälpen Väder och kläder, med varma kläder under, låt den lilla biologen upptäcka världen.', title_vi = 'Thám tử thiên nhiên 🔍', body_vi = 'Ở công viên, bé ngồi im 20 phút chỉ để quan sát tổ kiến. Đừng giục bé. Nếu mẹ đã dùng Thời tiết và trang phục để mặc cho bé đồ phù hợp với thời tiết, quần dày dặn từ trước, cứ để "nhà sinh vật học" nhí này khám phá thế giới.', title_zh = '大自然里的小侦探 🔍', body_zh = '在公园里一动不动地坐了20分钟，只为观察蚂蚁窝。别催。如果你已经用天气与穿衣助手提前按天气给宝宝穿好、下身穿得厚厚的，就让这位小小的生物学家去探索世界吧。' WHERE id = 'fed4ec8b-badd-4ae2-b8cd-74446e67eee7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Minilaboratorio en la bañera 🛀', body_es = 'Echa al agua jabones de distintos colores y prepara pociones. El baño acaba empapado, sí. Pero está aprendiendo sobre disolventes y mezclas de sustancias. Esta exploración científica es la mejor forma de quitarle el cansancio de la tarde y prepararle para un sueño tranquilo.', title_fr = 'Mini-laboratoire dans la baignoire 🛀', body_fr = 'Il mélange des savons de différentes couleurs dans l''eau pour préparer une potion. La salle de bain est inondée, oui. Mais il découvre les solvants et le mélange des substances. Cette exploration scientifique est le meilleur moyen d''évacuer la fatigue du soir et de le préparer à un sommeil paisible.', title_hi = 'बाथटब में मिनी प्रयोगशाला 🛀', body_hi = 'पानी में अलग-अलग रंग के साबुन मिलाकर जादुई घोल बना रहा है। बाथरूम गंदा हो रहा है, हाँ। पर वह घुलना और चीज़ों का मिलना सीख रहा है। यह वैज्ञानिक खोज शाम की थकान उतारकर उसे शांत नींद के लिए तैयार करने का सबसे अच्छा ज़रिया है।', title_id = 'Laboratorium mini di bak mandi 🛀', body_id = 'Ia mencampur sabun berwarna-warni ke dalam air dan membuat ramuan. Ya, kamar mandi jadi basah kuyup. Tapi ia sedang belajar tentang pelarut dan pencampuran zat. Penjelajahan ilmiah ini adalah cara terindah untuk menghilangkan lelah malam hari dan menyiapkannya untuk tidur yang tenang.', title_ja = 'お風呂のミニ実験室 🛀', body_ja = 'お湯にいろいろな色の石けんを入れて、魔法の薬をつくっています。バスルームは大変なことに、そうですね。でも、溶けることやまざることを学んでいるんです。この科学の探検は、夜の疲れをとって、静かな眠りへ導いてくれるいちばんの方法です。', title_ko = '욕조 속 미니 실험실 🛀', body_ko = '물에 여러 색깔 비누를 섞어 물약을 만드나요? 네, 욕실은 엉망이 되죠. 하지만 녹이는 것, 물질이 섞이는 것을 배우는 중이에요. 이런 과학 탐험은 저녁의 피로를 덜고 차분한 잠을 준비시키는 가장 좋은 방법이에요.', title_nl = 'Minilaboratorium in bad 🛀', body_nl = 'Hij mengt verschillende kleuren zeep in het water en maakt een toverdrankje. Ja, de badkamer wordt een zooi. Maar hij leert over oplosmiddelen en hoe stoffen zich mengen. Deze wetenschappelijke ontdekkingstocht neemt de vermoeidheid van de avond weg en maakt hem klaar voor een rustige slaap.', title_pl = 'Mini laboratorium w wannie 🛀', body_pl = 'Miesza w wodzie mydła w różnych kolorach i przygotowuje eliksir. Tak, łazienka jest w opłakanym stanie. Ale uczy się o rozpuszczalnikach i mieszaniu substancji. Ta naukowa wyprawa to najpiękniejszy sposób, by zabrać wieczorne zmęczenie i przygotować go do spokojnego snu.', title_pt = 'Minilaboratório na banheira 🛀', body_pt = 'Mistura na água sabonetes de várias cores e faz poções. A casa de banho fica uma desgraça, sim. Mas está a aprender sobre dissolventes e misturas de substâncias. Esta exploração científica é a melhor forma de lhe tirar o cansaço da noite e o preparar para um sono tranquilo.', title_sv = 'Minilaboratorium i badkaret 🛀', body_sv = 'Barnet blandar tvålar i olika färger i vattnet och gör trolldrycker. Ja, badrummet blir blött. Men barnet lär sig om lösningsmedel och hur ämnen blandas. Den vetenskapliga upptäcktsfärden tar bort kvällens trötthet och är det bästa sättet att förbereda barnet för en lugn sömn.', title_vi = 'Phòng thí nghiệm mini trong bồn tắm 🛀', body_vi = 'Bé pha các loại xà phòng màu khác nhau vào nước để chế "thuốc thần". Phòng tắm bừa bộn, đúng vậy. Nhưng bé đang học về sự hòa tan, cách các chất trộn lẫn. Cuộc khám phá khoa học này là cách tuyệt vời nhất để xua tan mệt mỏi buổi tối và chuẩn bị cho bé một giấc ngủ yên bình.', title_zh = '浴缸里的迷你实验室 🛀', body_zh = '往水里加入不同颜色的肥皂，调制“魔法药水”。是的，浴室被弄得一团糟。但宝宝在学习溶解和物质的混合。这场科学探索能带走傍晚的疲惫，是让宝宝准备好安稳入睡的最好方式。' WHERE id = '0601b05e-a2e4-4730-b08b-f661e0e89b2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aislarse del mundo dentro del armario 🚪', body_es = 'De repente se ha cortado el ruido en casa. Le has encontrado jugando solo, a oscuras, dentro del armario de la ropa. No es depresión, es solo un momento de reinicio emocional. Entorna la puerta suavemente y reconócele este lujo del espacio personal.', title_fr = 'S''isoler dans le placard 🚪', body_fr = 'Le bruit s''est arrêté au milieu de la maison. Vous l''avez trouvé dans l''armoire, jouant seul dans le noir. Ce n''est pas de la déprime, juste un moment de redémarrage émotionnel. Fermez doucement la porte et accordez-lui ce luxe d''un espace personnel.', title_hi = 'अलमारी के अंदर दुनिया से दूरी 🚪', body_hi = 'घर के बीच शोर थम गया। आपने उसे कपड़ों की अलमारी के अंदर अँधेरे में अकेले खेलते पाया। यह उदासी नहीं, बस भावनाओं का रीस्टार्ट पल है। दरवाज़ा हल्का-सा भिड़ा दीजिए और उसे निजी जगह की यह खास सुविधा दीजिए।', title_id = 'Menyendiri di dalam lemari 🚪', body_id = 'Kebisingan di tengah rumah tiba-tiba berhenti. Anda menemukannya bermain sendirian dalam gelap di dalam lemari baju. Ini bukan depresi, hanya momen restart emosional. Tutup pintunya sedikit dan akui haknya atas kemewahan ruang pribadi ini.', title_ja = 'クローゼットにこもる 🚪', body_ja = '家の中の騒がしさがぴたりとやんで、見ると暗いクローゼットの中でひとりで遊んでいた。これは落ちこみではなく、ただ気持ちを再起動している時間です。ドアをそっと閉めて、このプライベートな空間というぜいたくを認めてあげましょう。', title_ko = '옷장 속 나만의 공간 🚪', body_ko = '집 안의 소음이 뚝 끊겼어요. 옷장 안 어둠 속에서 혼자 놀고 있는 아이를 발견했나요? 우울한 게 아니라 감정을 재시작하는 순간일 뿐이에요. 문을 살짝 닫아 주고 이 개인 공간의 사치를 인정해 주세요.', title_nl = 'Even weg van de wereld in de kast 🚪', body_nl = 'Midden in huis viel het lawaai stil. Je vond hem alleen spelend in het donker in de kledingkast. Dat is geen depressie, maar gewoon een moment van emotionele herstart. Doe de deur zachtjes op een kier en gun hem de luxe van een eigen plekje.', title_pl = 'Odosobnienie w szafie 🚪', body_pl = 'W środku domu nagle ucichło. Znalazłaś go w szafie z ubraniami, gdzie bawił się sam w ciemności. To nie depresja, tylko chwila emocjonalnego restartu. Lekko przymknij drzwi i przyznaj mu ten luksus przestrzeni osobistej.', title_pt = 'Isolamento social dentro do armário 🚪', body_pt = 'O barulho no meio da casa parou. Encontrou-o dentro do roupeiro, às escuras, a brincar sozinho. Não é depressão, é apenas um momento de restart emocional. Encoste a porta de leve e reconheça-lhe este luxo do espaço pessoal.', title_sv = 'Isolering från samhället i garderoben 🚪', body_sv = 'Mitt i hemmet tystnade oväsendet. Du hittade barnet lekande ensamt i mörkret inne i klädgarderoben. Det är inte depression, bara en emotionell omstart. Dra försiktigt igen dörren och ge barnet lyxen av eget utrymme.', title_vi = 'Ẩn mình trong tủ quần áo 🚪', body_vi = 'Giữa nhà, tiếng ồn bỗng im bặt. Mẹ thấy bé đang một mình chơi trong bóng tối, bên trong tủ quần áo. Đây không phải trầm cảm, mà chỉ là lúc bé "khởi động lại" cảm xúc. Hãy khép hờ cửa và tôn trọng sự "xa xỉ" về không gian riêng này của bé.', title_zh = '衣柜里的“与世隔绝” 🚪', body_zh = '家里的吵闹声突然停了。你发现宝宝一个人在衣柜里、在黑暗中玩着。这不是抑郁，只是情绪“重启”的时刻。把门轻轻掩上，承认宝宝享受这份私人空间的“奢侈”吧。' WHERE id = '15d2ba80-4fad-4f86-8e70-6261ae666ebc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La revolución del contacto 🔋', body_es = 'Estás agotada físicamente de un peque que se te sube encima y te tira del pelo todo el día. Déjale ya en un lugar seguro y vete a otra habitación. Escribe en el Diario de ánimo «Mi cuerpo no me pertenece» y suelta la carga psicológica de este síndrome «touched out».', title_fr = 'La révolution du toucher 🔋', body_fr = 'Vous êtes physiquement épuisée par cet enfant qui vous a grimpé dessus et tiré les cheveux toute la journée. Mettez-le tout de suite dans un endroit sûr et passez dans une autre pièce. Écrivez dans le Journal d''humeur « Mon corps ne m''appartient plus » pour vous libérer du poids psychologique de ce syndrome « touched out ».', title_hi = 'छुए जाने के खिलाफ़ बगावत 🔋', body_hi = 'दिनभर आपके शरीर पर चढ़ने, बाल खींचने वाले बच्चे से आप शारीरिक रूप से थक चुकी हैं। तुरंत उसे किसी सुरक्षित जगह छोड़कर दूसरे कमरे में जाइए। मूड डायरी में ‘मेरा शरीर मेरा नहीं रहा’ लिखकर इस ‘टच्ड आउट’ हालत का मानसिक बोझ उतारिए।', title_id = 'Revolusi sentuhan 🔋', body_id = 'Anda kehabisan tenaga fisik karena anak yang seharian memanjat tubuh Anda dan menarik rambut Anda. Segera letakkan ia di tempat yang aman dan pindah ke ruangan lain. Tulis ''Tubuhku bukan milikku'' di Buku Harian Suasana Hati dan lepaskan beban psikologis sindrom lelah disentuh (touched out) ini.', title_ja = 'さわられ疲れの反乱 🔋', body_ja = '一日じゅう体によじのぼり、髪を引っぱる子どもに、体はもうへとへと。すぐに子どもを安全な場所に置いて、別の部屋へ移りましょう。「気分日記」に「わたしの体はわたしのものじゃない」と書いて、さわられ疲れ（touched out）の心の重荷をおろして。', title_ko = '스킨십 혁명 🔋', body_ko = '하루 종일 몸에 기어오르고 머리카락을 잡아당기는 아이 때문에 몸이 완전히 지쳤나요? 바로 아이를 안전한 곳에 두고 다른 방으로 가세요. 기분 일기에 ''내 몸이 내 것 같지 않아''라고 적으며 스킨십 피로(touched out)의 마음의 짐을 털어내세요.', title_nl = 'De aanraakrevolutie 🔋', body_nl = 'Je bent lichamelijk uitgeput van een kind dat de hele dag op je klimt en aan je haar trekt. Zet hem meteen op een veilige plek en ga naar een andere kamer. Schrijf in je Stemmingsdagboek ''Mijn lichaam is niet van mij'' en gooi de mentale last van dit touched-out-gevoel van je af.', title_pl = 'Rewolucja dotyku 🔋', body_pl = 'Jesteś fizycznie wyczerpana dzieckiem, które cały dzień wspinało się na ciebie i ciągnęło za włosy. Od razu zostaw go w bezpiecznym miejscu i przejdź do innego pokoju. Napisz w Dzienniku nastroju „Moje ciało nie należy do mnie” i zrzuć psychiczny ciężar syndromu touched out.', title_pt = 'A revolução do toque 🔋', body_pt = 'Está fisicamente esgotada da criança que lhe trepa pelo corpo e lhe puxa o cabelo o dia todo. Deixe-a já num sítio seguro e passe para outra divisão. Escreva no Diário de Humor "O meu corpo não me pertence" e liberte o peso psicológico desta síndrome "touched out".', title_sv = 'Beröringsrevolutionen 🔋', body_sv = 'Du är fysiskt slut efter barnet som klättrat på dig och dragit i håret hela dagen. Lägg genast barnet på ett säkert ställe och gå in i ett annat rum. Skriv ”Min kropp tillhör inte mig” i Humördagboken och släpp den psykiska bördan av touched out-syndromet.', title_vi = 'Cuộc cách mạng của sự đụng chạm 🔋', body_vi = 'Mẹ kiệt sức về thể chất vì bé cả ngày trèo lên người, giật tóc mẹ. Hãy đặt bé vào chỗ an toàn ngay và sang phòng khác. Viết vào Nhật ký tâm trạng: "Cơ thể mình không còn là của mình" để trút bỏ gánh nặng tâm lý của hội chứng "touched out" này.', title_zh = '触碰的“革命” 🔋', body_zh = '一整天孩子往你身上爬、扯你头发，你的身体已经精疲力竭。马上把宝宝放在安全的地方，去另一个房间。在心情日记里写下“我的身体不属于我”，卸下这种“触碰疲劳”（touched out）带来的心理负担。' WHERE id = '869bedae-ce51-4c50-8799-4b322d523e09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paz interior con el Medidor de sonido 🤫', body_es = 'Por fin se ha dormido. El pitido de tus oídos no se acaba. Abre el Medidor de sonido de la app. Mirando los 0 decibelios de la pantalla, siente cómo el silencio de la habitación penetra en tu cerebro y te cura.', title_fr = 'La paix intérieure avec le Sonomètre 🤫', body_fr = 'Il dort enfin. Le bourdonnement dans vos oreilles ne s''arrête pas. Ouvrez le Sonomètre dans l''application. En regardant les 0 décibel à l''écran, sentez le silence de la pièce pénétrer votre cerveau et vous réparer.', title_hi = 'साउंड मीटर के साथ अंदरूनी शांति 🤫', body_hi = 'आखिरकार वह सो गया। कानों की झनझनाहट खत्म नहीं हो रही। ऐप में साउंड मीटर खोलिए। स्क्रीन पर 0 डेसिबल देखते हुए महसूस कीजिए कि कमरे की खामोशी आपके दिमाग में कैसे उतरती है और आपको कैसे ठीक करती है।', title_id = 'Damai batin dengan Pengukur Suara 🤫', body_id = 'Akhirnya ia tidur. Dengingan di telinga Anda tak juga berhenti. Buka Pengukur Suara di aplikasi. Lihat tulisan 0 desibel di layar dan rasakan bagaimana keheningan kamar meresap ke otak Anda dan memulihkan Anda.', title_ja = 'サウンドメーターで心の平和 🤫', body_ja = 'やっと寝てくれました。耳鳴りがおさまりませんね。アプリで「サウンドメーター」を開きましょう。画面の「0デシベル」を見つめながら、部屋の静けさが脳にしみこみ、あなたを癒やしてくれるのを感じて。', title_ko = '소음 측정기로 찾는 마음의 평화 🤫', body_ko = '드디어 잠들었어요. 그런데 귀에서 울리는 소리가 멈추지 않나요? 앱에서 소음 측정기를 여세요. 화면 속 ''0데시벨''을 보며 방의 고요가 머릿속에 스며들어 나를 치유하는 걸 느껴 보세요.', title_nl = 'Innerlijke rust met de Geluidsmeter 🤫', body_nl = 'Hij slaapt eindelijk. Maar het gesuis in je oren houdt niet op. Open de Geluidsmeter in de app. Kijk naar de 0 decibel op het scherm en voel hoe de stilte in de kamer tot in je brein doordringt en je heelt.', title_pl = 'Wewnętrzny spokój z Miernikiem dźwięku 🤫', body_pl = 'W końcu zasnął. A dzwonienie w uszach nie mija. Otwórz w aplikacji Miernik dźwięku. Patrząc na napis 0 decybeli na ekranie, poczuj, jak cisza w pokoju przenika do twojego mózgu i cię leczy.', title_pt = 'Paz interior com o Medidor de Som 🤫', body_pt = 'Finalmente adormeceu. O zumbido nos ouvidos não passa. Abra o Medidor de Som na app. A ver os 0 decibéis no ecrã, sinta como o silêncio do quarto lhe penetra no cérebro e a cura.', title_sv = 'Inre frid med Ljudmätaren 🤫', body_sv = 'Äntligen sover barnet. Det slutar inte ringa i öronen. Öppna Ljudmätaren i appen. Titta på texten 0 decibel på skärmen och känn hur tystnaden i rummet tränger in i hjärnan och läker dig.', title_vi = 'Bình yên nội tâm cùng Đo âm thanh 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Tiếng ù trong tai mẹ vẫn chưa dứt. Hãy mở Đo âm thanh trong ứng dụng. Nhìn dòng chữ 0 decibel trên màn hình và cảm nhận sự tĩnh lặng trong phòng đang thấm vào não bộ, chữa lành cho mẹ thế nào.', title_zh = '用分贝仪找回内心的平静 🤫', body_zh = '宝宝终于睡着了。你耳朵里的嗡嗡声却停不下来。在应用里打开分贝仪。看着屏幕上的“0分贝”，感受房间里的安静如何渗入你的大脑，如何治愈你。' WHERE id = '18c831a2-2a8d-41b4-aec0-3fc3423e4549' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ladrón de móviles 📱', body_es = 'Al servirte un té ves que tu móvil ha desaparecido y que él está detrás del sofá diciendo «¿Diga?» como tú. Está escaneando tus hábitos digitales. Al recuperar el aparato, hazlo jugando: «Mi móvil también quería hablar contigo».', title_fr = 'Le voleur de téléphone 📱', body_fr = 'En vous servant un thé, vous remarquez que votre téléphone a disparu, et derrière le canapé, il dit « Allô » comme vous. Il scanne vos habitudes numériques. Reprenez l''appareil en jouant : « Mon téléphone voulait te parler, lui aussi. »', title_hi = 'फ़ोन चोर 📱', body_hi = 'अपने लिए चाय डालते समय देखा कि फ़ोन गायब है, और वह सोफ़े के पीछे आपकी तरह ‘हैलो’ कह रहा है। वह आपकी डिजिटल आदतें स्कैन कर रहा है। फ़ोन लेते समय ‘मेरा फ़ोन भी तुमसे बात करना चाहता था’ कहकर खेल-खेल में वापस ले लीजिए।', title_id = 'Pencuri ponsel 📱', body_id = 'Saat menuang teh, Anda sadar ponsel Anda hilang, dan ia sedang berkata ''Halo'' seperti Anda di balik sofa. Ia sedang memindai kebiasaan digital Anda. Saat mengambil ponsel, kembalikan lewat permainan: ''Ponsel Mama juga ingin bicara denganmu''.', title_ja = 'スマホどろぼう 📱', body_ja = 'お茶をいれていたら、スマホが消えていて、ソファの後ろであなたそっくりに「もしもし」と話していた。あなたのデジタルな習慣をコピーしているんです。返してもらうときは「スマホもあなたとお話ししたかったんだって」と、遊びにして受けとりましょう。', title_ko = '휴대폰 도둑 📱', body_ko = '차를 따르다 보니 휴대폰이 사라졌고, 소파 뒤에서 엄마처럼 ''여보세요'' 하는 소리가 들리나요? 엄마의 디지털 습관을 스캔하는 중이에요. 기기를 돌려받을 때 ''엄마 휴대폰도 너랑 이야기하고 싶었대''라며 놀이처럼 받아 오세요.', title_nl = 'De telefoondief 📱', body_nl = 'Terwijl je thee inschenkt, zie je dat je telefoon weg is, en achter de bank hoor je hem net als jij ''Hallo?'' zeggen. Hij scant je digitale gewoontes. Neem het toestel speels terug: ''Mijn telefoon wilde ook even met jou praten.''', title_pl = 'Złodziej telefonu 📱', body_pl = 'Gdy nalewasz sobie herbatę, zauważasz, że telefon zniknął, a on za kanapą mówi „Halo” zupełnie jak ty. Skanuje twoje cyfrowe nawyki. Odbierając urządzenie, zamień to w zabawę: „Mój telefon też chciał z tobą porozmawiać”.', title_pt = 'O ladrão de telemóveis 📱', body_pt = 'Ao servir-se de um chá, reparou que o telemóvel desapareceu e que ele está atrás do sofá a dizer "Estou?", tal como a mãe. Está a digitalizar os seus hábitos digitais. Ao recuperar o aparelho, diga "O meu telemóvel também queria falar contigo" e recupere-o a brincar.', title_sv = 'Telefontjuven 📱', body_sv = 'När du hällde upp te såg du att telefonen försvunnit, och bakom soffan säger barnet ”Hallå” precis som du. Barnet skannar dina digitala vanor. När du tar tillbaka den, säg ”Min telefon ville visst också prata med dig” och gör det till en lek.', title_vi = 'Kẻ trộm điện thoại 📱', body_vi = 'Đang rót trà, mẹ nhận ra điện thoại biến mất, còn bé đang ở sau sofa nói "A lô" y như mẹ. Bé đang "quét" thói quen dùng thiết bị số của mẹ. Khi lấy lại, hãy nói vui: "Điện thoại của mẹ cũng muốn nói chuyện với con đấy" và lấy về bằng trò chơi.', title_zh = '手机小偷 📱', body_zh = '你给自己倒茶时，发现手机不见了，而宝宝正躲在沙发后面像你一样说“喂”。宝宝在“扫描”你的数字习惯。拿回手机时，说一句“我的手机也想和你说话呢”，用游戏的方式把它拿回来。' WHERE id = '64255b01-33d4-405e-b645-f0ff22d8defe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La política del «¡Vísteme tú!» 👖', body_es = 'Levanta los pies al aire y dice: «Soy un bebé, vísteme tú». Van y vienen entre la independencia y la dependencia. No le vistas a la fuerza. Deja la ropa a su lado y manipúlale con cariño: «Este pantalón de superhéroe espera a su dueño».', title_fr = 'La politique du « Habille-toi tout seul ! » 👖', body_fr = 'Il lève les jambes en l''air : « Je suis un bébé, habille-moi. » Il oscille entre indépendance et dépendance. Ne l''habillez pas de force. Posez les vêtements à côté de lui et manipulez gentiment : « Ce pantalon de super-héros attend son propriétaire. »', title_hi = '‘तुम खुद पहनो!’ वाली नीति 👖', body_hi = 'पैर हवा में उठाकर कहता है, ‘मैं बेबी हूँ, तुम पहनाओ।’ वे आत्मनिर्भरता और निर्भरता के बीच झूलते रहते हैं। ज़बरदस्ती मत पहनाइए। कपड़े उसके पास रखिए और ‘यह सुपरहीरो पैंट अपने मालिक का इंतज़ार कर रही है’ कहकर उसे चतुराई से मनाइए।', title_id = 'Politik ''Pakai sendiri!'' 👖', body_id = 'Ia mengangkat kaki ke atas dan berkata ''Aku bayi, Mama yang pakaikan''. Mereka bolak-balik antara mandiri dan bergantung. Jangan memakaikannya dengan paksa. Letakkan pakaian di sampingnya dan bujuk dengan berkata ''Celana superhero ini sedang menunggu pemiliknya''.', title_ja = '「自分で着て！」の方針 👖', body_ja = '足を宙にあげて「赤ちゃんだから、ママが着せて」と言う。自立と甘えのあいだを行ったり来たりしているんです。無理に着せないで。服をそばに置いて「このスーパーヒーローのズボンが、持ち主を待ってるよ」と、うまく誘いましょう。', title_ko = '''네가 입어!'' 정책 👖', body_ko = '다리를 하늘로 들고 ''나 아기야, 엄마가 입혀 줘''라고 하나요? 독립과 의존 사이를 오가는 중이에요. 억지로 입히지 마세요. 옷을 옆에 두고 ''이 슈퍼히어로 바지가 주인을 기다리고 있대''라며 슬쩍 유도해 보세요.', title_nl = 'Het ''Kleed jezelf aan!''-beleid 👖', body_nl = 'Hij steekt zijn benen in de lucht: ''Ik ben een baby, kleed jij mij aan.'' Ze schommelen tussen zelfstandigheid en afhankelijkheid. Kleed hem niet met dwang aan. Leg de kleren naast hem en verleid hem: ''Deze superheldenbroek wacht op zijn eigenaar.''', title_pl = 'Polityka „Ubierz się sam!” 👖', body_pl = 'Podnosi nogi do góry i mówi: „Jestem dzidziusiem, ty mnie ubierz”. Dzieci krążą między samodzielnością a zależnością. Nie ubieraj go na siłę. Połóż ubranie obok i sprytnie powiedz: „Te spodnie superbohatera czekają na swojego właściciela”.', title_pt = 'A política do "Veste-te tu!" 👖', body_pt = 'Levanta as pernas para o ar e diz "Sou um bebé, veste-me tu". Andam entre a independência e a dependência. Não o vista à força. Ponha a roupa ao lado dele e use um pouco de manipulação: "Estas calças de super-herói estão à espera do dono".', title_sv = 'Politiken ”Klä på dig själv!” 👖', body_sv = 'Barnet lyfter benen mot taket och säger: ”Jag är en bebis, klä på mig.” De pendlar mellan självständighet och beroende. Klä inte på barnet med tvång. Lägg kläderna bredvid och manipulera lite: ”De här superhjältebyxorna väntar på sin ägare.”', title_vi = 'Chính sách "Con tự mặc đi!" 👖', body_vi = 'Bé giơ chân lên trời và nói "Con là em bé, mẹ mặc cho con đi". Bé đang dao động giữa tự lập và phụ thuộc. Đừng ép bé mặc. Hãy đặt quần áo bên cạnh và "dụ" bé: "Chiếc quần siêu anh hùng này đang chờ chủ nhân của nó đấy".', title_zh = '“你自己穿！”的政策 👖', body_zh = '把腿翘到天上说：“我是小宝宝，你给我穿。”他们在独立和依赖之间来回摇摆。别强行给宝宝穿。把衣服放在宝宝旁边，说一句“这条超级英雄裤子在等它的主人呢”，巧妙地引导一下。' WHERE id = 'd0533c80-d46b-4d9f-9654-8ce50e72523b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder místico del susurro 🌙', body_es = 'Inventa excusas para escaparse de la cama. Baja del todo la voz y háblale solo en susurros. Para entenderte tendrá que concentrarse físicamente, y esa concentración hipnotizará su cerebro y le dormirá.', title_fr = 'Le pouvoir mystérieux du chuchotement 🌙', body_fr = 'Il invente des excuses pour s''échapper du lit. Baissez complètement la voix et ne parlez plus qu''en chuchotant. Pour vous comprendre, il sera obligé de se concentrer physiquement, et cette concentration hypnotisera son cerveau et l''endormira.', title_hi = 'फुसफुसाहट की रहस्यमयी ताकत 🌙', body_hi = 'बिस्तर से भागने के लिए बहाने गढ़ता है। अपनी आवाज़ पूरी तरह धीमी कीजिए, सिर्फ़ फुसफुसाकर बात कीजिए। आपको समझने के लिए उसे शारीरिक रूप से ध्यान लगाना ही पड़ेगा, और यह एकाग्रता उसके दिमाग को सम्मोहित करके नींद में ले जाएगी।', title_id = 'Kekuatan ajaib bisikan 🌙', body_id = 'Ia mengarang alasan untuk kabur dari tempat tidur. Kecilkan suara Anda sepenuhnya dan bicaralah hanya sambil berbisik. Untuk memahami Anda, ia terpaksa memusatkan perhatian secara fisik, dan fokus ini akan menghipnotis otaknya hingga tertidur.', title_ja = 'ささやきのふしぎな力 🌙', body_ja = 'ベッドから逃げるための言いわけを考えだす。声をぐっと小さくして、ささやき声だけで話しましょう。あなたの言葉を聞きとるために、体ごと集中しなければならず、その集中が脳に催眠術をかけて眠りへ導きます。', title_ko = '속삭임의 신비한 힘 🌙', body_ko = '침대에서 도망치려고 핑계를 지어내나요? 목소리를 한껏 낮추고 속삭이듯만 말하세요. 엄마 말을 알아들으려면 온몸으로 집중해야 하고, 그 집중이 뇌를 최면에 걸린 듯 잠들게 할 거예요.', title_nl = 'De mystieke kracht van fluisteren 🌙', body_nl = 'Hij verzint smoesjes om uit bed te gaan. Ga helemaal zacht praten en spreek alleen fluisterend. Om je te verstaan moet hij zich echt concentreren, en die focus brengt zijn brein in een soort hypnose en laat hem in slaap vallen.', title_pl = 'Tajemnicza moc szeptu 🌙', body_pl = 'Wymyśla wymówki, żeby uciec z łóżka. Ścisz głos całkowicie i mów tylko szeptem. Żeby cię zrozumieć, będzie musiał się fizycznie skupić, a to skupienie zahipnotyzuje jego mózg i ukołysze go do snu.', title_pt = 'O poder místico do sussurro 🌙', body_pt = 'Inventa desculpas para fugir da cama. Baixe totalmente a voz e fale só a sussurrar. Para a perceber, vai ter de concentrar a atenção fisicamente, e essa concentração vai hipnotizar-lhe o cérebro e fazê-lo adormecer.', title_sv = 'Viskningens mystiska kraft 🌙', body_sv = 'Barnet hittar på ursäkter för att fly från sängen. Sänk rösten helt och prata bara viskande. För att förstå dig måste barnet fysiskt koncentrera sig, och fokuseringen hypnotiserar hjärnan och får barnet att somna.', title_vi = 'Sức mạnh huyền bí của lời thì thầm 🌙', body_vi = 'Bé nghĩ ra đủ lý do để trốn khỏi giường. Hãy hạ giọng hẳn xuống và chỉ nói thì thầm. Để hiểu được mẹ, bé buộc phải tập trung, và sự tập trung đó sẽ "thôi miên" não bé, đưa bé vào giấc ngủ.', title_zh = '悄悄话的神奇力量 🌙', body_zh = '为了从床上溜走编各种借口。把声音彻底压低，只用悄悄话说话。为了听懂你，宝宝不得不集中注意力，而这份专注会像催眠一样，让宝宝的大脑进入睡眠。' WHERE id = '5d82c548-2228-430b-916c-6c21c900e5fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consuelo en la Comunidad Anacan 💬', body_es = '¿Te ahoga la sensación de que nunca podrás ser perfecta? Borra esa ilusión de las madres de Instagram. Entra en la Comunidad Anacan, lee las confesiones sinceras de madres con la casa patas arriba y con hijos que rayan las paredes, y di: «Soy totalmente normal».', title_fr = 'Du réconfort dans la Communauté Anacan 💬', body_fr = 'Le sentiment « Je ne serai jamais parfaite » vous étouffe ? Effacez cette illusion des mamans d''Instagram. Entrez dans la Communauté Anacan, lisez les confidences sincères des mamans dont la maison est sens dessus dessous et dont l''enfant a gribouillé les murs, et dites-vous : « Je suis tout à fait normale. »', title_hi = 'Anacan कम्युनिटी में सांत्वना 💬', body_hi = '‘मैं कभी परफ़ेक्ट नहीं बन पाऊँगी’ वाला एहसास आपका दम घोंट रहा है? इंस्टाग्राम वाली माँओं का वह भ्रम मिटा दीजिए। Anacan कम्युनिटी में जाइए, बिखरे घरों वाली और दीवार पर लकीरें खींचने वाले बच्चों की माँओं के सच्चे इकरार पढ़िए और कहिए, ‘मैं बिल्कुल सामान्य हूँ।’', title_id = 'Penghiburan di Komunitas Anacan 💬', body_id = 'Perasaan ''Aku tidak akan pernah bisa sempurna'' membuat Anda sesak? Hapus ilusi ibu-ibu Instagram itu. Masuklah ke Komunitas Anacan, baca pengakuan tulus para ibu yang rumahnya berantakan dan anaknya mencoret dinding, lalu katakan ''Aku sepenuhnya normal''.', title_ja = 'Anacanコミュニティでなぐさめを 💬', body_ja = '「わたしは一生完璧になれない」という気持ちに押しつぶされそう？インスタのママたちという幻想は消しましょう。Anacanコミュニティを開いて、家がぐちゃぐちゃだったり、子どもが壁に落書きしたりしているママたちの正直な打ち明け話を読んで、「わたし、まったく普通だ」と言いましょう。', title_ko = 'Anacan 커뮤니티의 위로 💬', body_ko = '''난 절대 완벽해질 수 없을 거야''라는 마음에 숨이 막히나요? 인스타그램 속 엄마라는 환상은 지우세요. Anacan 커뮤니티에 들어가 집은 엉망이고 아이가 벽에 낙서한 엄마들의 솔직한 고백을 읽으며 ''나 완전히 정상이야''라고 말해 주세요.', title_nl = 'Troost in de Anacan Community 💬', body_nl = 'Overvalt je het gevoel ''Ik word nooit perfect''? Wis die illusie van Instagram-mama''s. Ga naar de Anacan Community, lees de eerlijke bekentenissen van mama''s met een puinhoop in huis en kinderen die op de muur tekenen, en zeg tegen jezelf: ''Ik ben heel normaal.''', title_pl = 'Pocieszenie w Społeczności Anacan 💬', body_pl = 'Dławi cię poczucie „Nigdy nie będę idealna”? Wymaż iluzję mam z Instagrama. Wejdź do Społeczności Anacan, przeczytaj szczere wyznania mam, które mają w domu bałagan, a ich dzieci rysują po ścianach, i powiedz sobie: „Jestem zupełnie normalna”.', title_pt = 'Conforto na Comunidade Anacan 💬', body_pt = 'Sufoca-a a sensação de que "nunca vou ser perfeita"? Apague a ilusão das mães do Instagram. Entre na Comunidade Anacan, leia os desabafos sinceros de mães com a casa de pernas para o ar e filhos que riscam as paredes, e diga "Sou totalmente normal".', title_sv = 'Tröst i Anacan Community 💬', body_sv = 'Kväver känslan ”jag kommer aldrig att kunna bli perfekt” dig? Radera illusionen om Instagrammammor. Gå in i Anacan Community, läs uppriktiga bekännelser från mammor vars hem är i kaos och vars barn klottrar på väggarna, och säg ”Jag är helt normal”.', title_vi = 'Niềm an ủi trong Cộng đồng Anacan 💬', body_vi = 'Cảm giác "Mình sẽ không bao giờ hoàn hảo được" khiến mẹ nghẹt thở? Hãy xóa bỏ ảo tưởng về những bà mẹ Instagram. Vào Cộng đồng Anacan, đọc những lời thú nhận chân thành của các mẹ có nhà cửa bừa bộn, con vẽ bậy lên tường, và tự nhủ: "Mình hoàn toàn bình thường".', title_zh = '在Anacan社区里得到安慰 💬', body_zh = '“我永远都不可能完美”的感觉让你喘不过气？抹掉那些Instagram妈妈的幻象吧。进入Anacan社区，读读那些家里乱成一团、孩子在墙上乱画的妈妈们真诚的心里话，然后告诉自己：“我完全正常。”' WHERE id = 'e401c834-583c-49ec-8d04-289b6b62d99b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lógica del dinosaurio 🦖', body_es = 'Por la mañana no responde a ninguna pregunta, solo ruge. Hoy es un T-Rex. Adáptate a la identidad que se ha inventado preguntándole «¿Y los T-Rex comen gachas?» y completa la rutina de la mañana sin una sola lágrima.', title_fr = 'La logique du dinosaure 🦖', body_fr = 'Le matin, il ne répond à aucune question, il ne fait que rugir. Aujourd''hui, c''est un T-Rex. « Et les T-Rex, ils mangent de la bouillie ? » Adaptez-vous à cette identité inventée et terminez le rituel du matin sans une seule larme.', title_hi = 'डायनासोर का तर्क 🦖', body_hi = 'सुबह किसी सवाल का जवाब नहीं देता, बस दहाड़ता है। आज वह टी-रेक्स है। ‘तो क्या टी-रेक्स दलिया खाते हैं?’ कहकर उसकी गढ़ी इस पहचान के हिसाब से ढलिए और सुबह की रस्म बिना एक भी आँसू के पूरी कीजिए।', title_id = 'Logika dinosaurus 🦖', body_id = 'Pagi ini ia tidak menjawab pertanyaan apa pun, hanya mengaum. Hari ini ia T-Rex. Sesuaikan diri dengan identitas karangannya dengan bertanya ''Apakah T-Rex makan bubur?'', dan selesaikan ritual pagi tanpa air mata.', title_ja = '恐竜の理屈 🦖', body_ja = '朝、どんな質問にも答えず、ただガオーとほえるだけ。今日のこの子はティラノサウルスです。「ティラノサウルスって、おかゆ食べるのかな？」と、考えたキャラクターに合わせて、朝の習慣を涙なしで終わらせましょう。', title_ko = '공룡의 논리 🦖', body_ko = '아침에 어떤 질문에도 대답하지 않고 으르렁거리기만 하나요? 오늘은 티라노사우루스예요. ''티라노사우루스도 죽을 먹을까?'' 하며 아이가 만든 이 정체성에 맞춰 주면 아침 의식을 눈물 없이 끝낼 수 있어요.', title_nl = 'Dinosauruslogica 🦖', body_nl = '''s Ochtends beantwoordt hij geen enkele vraag, hij brult alleen. Vandaag is hij een T-rex. Pas je aan aan de identiteit die hij heeft bedacht, ''Eten T-rexen eigenlijk pap?'', en rond het ochtendritueel af zonder één traan.', title_pl = 'Logika dinozaura 🦖', body_pl = 'Rano nie odpowiada na żadne pytanie, tylko ryczy. Dziś jest T-Rexem. Zapytaj: „A czy T-Rexy jedzą kaszkę?”, dopasuj się do jego wymyślonej postaci i przejdź przez poranny rytuał bez ani jednej łzy.', title_pt = 'Lógica de dinossauro 🦖', body_pt = 'De manhã não responde a nenhuma pergunta, só ruge. Hoje é um T-Rex. Adapte-se a esta personalidade inventada: "E os T-Rex comem papa?", e termine o ritual da manhã sem uma única lágrima.', title_sv = 'Dinosaurielogik 🦖', body_sv = 'På morgonen svarar barnet inte på någon fråga utan bara ryter. I dag är barnet en T-Rex. Anpassa dig efter den påhittade identiteten, fråga ”Men äter T-Rexar gröt?” och avsluta morgonritualen utan en enda tår.', title_vi = 'Logic khủng long 🦖', body_vi = 'Buổi sáng, bé không trả lời câu hỏi nào, chỉ gầm gừ. Hôm nay bé là khủng long bạo chúa T-Rex. Hãy hòa theo nhân vật bé tự nghĩ ra: "Thế khủng long T-Rex có ăn cháo không nhỉ?" và hoàn thành nghi thức buổi sáng mà không có giọt nước mắt nào.', title_zh = '恐龙的逻辑 🦖', body_zh = '早上什么问题都不回答，只会“嗷呜”。今天宝宝是一只霸王龙。问一句“那霸王龙吃不吃粥呢？”，顺着宝宝编出来的这个身份，不掉一滴眼泪地完成早晨的流程。' WHERE id = 'fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los héroes inventados de papá 🦸‍♂️', body_es = 'Esta noche olvidaos de los cuentos del libro. Que papá cuente una historia inventada y fantástica cuyo protagonista sea el propio peque. Frases como «Y desenvainó su espada y... ¡se lavó los dientes!» le harán reír a carcajadas y le prepararán para dormir.', title_fr = 'Les héros inventés de papa 🦸‍♂️', body_fr = 'Ce soir, oubliez les contes du livre. Que papa raconte une histoire inventée et fantastique dont l''enfant est le héros. Des phrases comme « Et il a sorti son épée... et il s''est brossé les dents ! » le feront éclater de rire et le prépareront au sommeil.', title_hi = 'पापा के गढ़े हुए हीरो 🦸‍♂️', body_hi = 'आज शाम किताब की कहानियाँ भूल जाइए। पापा एक गढ़ी हुई, फ़ैंटेसी कहानी सुनाएँ जिसका मुख्य हीरो खुद बच्चा हो। ‘और उसने तलवार निकाली और... दाँत ब्रश कर लिए!’ जैसे वाक्य बच्चे को हँसा-हँसाकर नींद के लिए तैयार कर देंगे।', title_id = 'Pahlawan karangan Ayah 🦸‍♂️', body_id = 'Malam ini lupakan dongeng di buku. Biarkan Ayah menceritakan kisah karangan yang fantastis dengan anak sendiri sebagai tokoh utamanya. Kalimat seperti ''Lalu ia menghunus pedangnya... dan menggosok gigi!'' akan membuat anak tertawa terbahak-bahak dan siap tidur.', title_ja = 'パパの作り話のヒーロー 🦸‍♂️', body_ja = '今夜は絵本のお話は忘れましょう。パパに、主人公が子ども自身の、作り話のファンタジーを話してもらいましょう。「そして剣をぬいて…歯をみがいた！」のような一言で、子どもは大笑いしながら眠りの準備ができます。', title_ko = '아빠가 지어낸 영웅들 🦸‍♂️', body_ko = '오늘 저녁엔 책 속 동화는 잊으세요. 아빠가 아이가 주인공인 지어낸 환상적인 이야기를 들려주게 하세요. ''그리고 칼을 뽑아 들고는... 이를 닦았어!'' 같은 문장이 아이를 웃음바다에 빠뜨리며 잠을 준비시킬 거예요.', title_nl = 'Papa''s verzonnen helden 🦸‍♂️', body_nl = 'Vergeet vanavond de sprookjes uit het boek. Laat papa een verzonnen, fantastisch verhaal vertellen met je kind als hoofdpersoon. Zinnen als ''En hij trok zijn zwaard... en poetste zijn tanden!'' laten je kind schateren en maken hem klaar voor de slaap.', title_pl = 'Wymyśleni bohaterowie taty 🦸‍♂️', body_pl = 'Dziś wieczorem zapomnij o bajkach z książek. Niech tata opowie wymyśloną, fantastyczną historię, w której głównym bohaterem jest samo dziecko. Zdania w stylu „I wyciągnął miecz... i umył zęby!” rozśmieszą go do łez i przygotują do snu.', title_pt = 'Os heróis inventados do pai 🦸‍♂️', body_pt = 'Esta noite esqueça as histórias do livro. Que o pai conte uma história inventada e fantástica com a própria criança como herói principal. Frases como "E ele tirou a espada e... lavou os dentes!" vão fazê-lo rir às gargalhadas e prepará-lo para o sono.', title_sv = 'Pappas påhittade hjältar 🦸‍♂️', body_sv = 'Glöm sagorna i boken i kväll. Låt pappa berätta en påhittad och fantastisk historia där barnet självt är huvudperson. Meningar som ”Och hen drog sitt svärd och... borstade tänderna!” får barnet att kikna av skratt och förbereder det för sömnen.', title_vi = 'Những người hùng tưởng tượng của bố 🦸‍♂️', body_vi = 'Tối nay hãy quên những câu chuyện trong sách. Để bố kể một câu chuyện tưởng tượng, kỳ ảo mà nhân vật chính là bé. Những câu như "Và cậu ấy rút thanh gươm ra... rồi đánh răng!" sẽ khiến bé cười ngặt nghẽo và sẵn sàng đi ngủ.', title_zh = '爸爸编的英雄 🦸‍♂️', body_zh = '今晚忘掉书里的童话吧。让爸爸讲一个主角就是宝宝自己的、天马行空的奇幻故事。像“然后他拔出宝剑……刷了刷牙！”这样的句子，会把宝宝逗得哈哈大笑，也让宝宝准备好入睡。' WHERE id = '5a7d778f-6e03-4003-a60c-0214c0dc5a0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Critica su propio dibujo 🖍️', body_es = 'Te enseña sus garabatos negros, dice «Eras tú, pero me ha salido mal» y los rompe. ¡Está naciendo su capacidad de autocrítica! No le quites importancia a lo que siente: apoya su desarrollo diciendo «¿Y si en el próximo dibujo pruebas también el rojo?».', title_fr = 'Il critique son propre dessin 🖍️', body_fr = 'Il vous montre son gribouillage noir : « C''était toi, mais c''est raté », puis le déchire et le jette. La capacité à s''autocritiquer apparaît ! Ne minimisez pas ce qu''il ressent, soutenez son développement : « Au prochain dessin, tu pourrais peut-être essayer le rouge ? »', title_hi = 'अपनी ड्रॉइंग की आलोचना 🖍️', body_hi = 'अपनी बनाई काली आड़ी-तिरछी लकीरें दिखाकर कहता है, ‘यह तुम थीं, पर अच्छी नहीं बनी’ और फाड़कर फेंक देता है। खुद की आलोचना करने की क्षमता जाग रही है! उसकी भावनाओं को छोटा मत कीजिए, ‘अगली ड्रॉइंग में शायद लाल रंग भी आज़माओ?’ कहकर विकास में साथ दीजिए।', title_id = 'Mengkritik gambarnya sendiri 🖍️', body_id = 'Ia menunjukkan coretan hitamnya, berkata ''Ini Mama, tapi jelek'', lalu menyobek dan membuangnya. Kemampuan mengkritik diri sendiri mulai muncul! Jangan meremehkan perasaannya, dukung perkembangannya dengan berkata ''Di gambar berikutnya, mungkin coba pakai warna merah juga?''.', title_ja = '自分の絵にダメ出し 🖍️', body_ja = '描いた黒いぐちゃぐちゃを見せて「これ、ママだったけど、へたになった」と言って、破って捨ててしまう。自分を批評する力が育っています！気持ちを小さく扱わず、「次の絵では、赤も使ってみる？」と言って、成長を応援しましょう。', title_ko = '자기 그림 비평 🖍️', body_ko = '검은 낙서를 보여 주며 ''이거 엄마인데, 별로야'' 하고 찢어 버리나요? 스스로를 평가하는 능력이 생기고 있어요! 감정을 가볍게 여기지 말고 ''다음 그림엔 빨간색도 써 볼까?''라며 성장을 응원해 주세요.', title_nl = 'Kritiek op zijn eigen tekening 🖍️', body_nl = 'Hij laat zijn zwarte gekrabbel zien, zegt ''Dit was jij, maar het is lelijk geworden'' en scheurt het kapot. Hij begint zichzelf kritisch te bekijken! Maak zijn gevoelens niet kleiner, maar steun zijn ontwikkeling: ''Misschien kun je in je volgende tekening ook rood proberen?''', title_pl = 'Krytyka własnego rysunku 🖍️', body_pl = 'Pokazuje swoje czarne bazgroły, mówi „To byłaś ty, ale wyszło brzydko” i drze kartkę. Rodzi się umiejętność samokrytyki! Nie umniejszaj jego uczuć, wspieraj rozwój: „Może w następnym rysunku spróbujesz też czerwonego?”.', title_pt = 'Criticar o próprio desenho 🖍️', body_pt = 'Mostra os rabiscos pretos que desenhou, diz "Eras tu, mas ficou mal" e rasga-os. Está a nascer a capacidade de autocrítica! Não desvalorize o que sente: diga "No próximo desenho, experimentas também o vermelho?" e apoie o desenvolvimento.', title_sv = 'Kritik mot sin egen teckning 🖍️', body_sv = 'Barnet visar sitt svarta klotter, säger ”Det här var du, men det blev dåligt” och river sönder det. Förmågan till självkritik växer fram! Förminska inte barnets känslor, säg ”Kanske kan du testa rött också i nästa teckning?” och stöd utvecklingen.', title_vi = 'Tự phê bình tranh của mình 🖍️', body_vi = 'Bé chỉ vào bức vẽ nguệch ngoạc màu đen và nói "Đây là mẹ, nhưng xấu quá", rồi xé đi. Khả năng tự phê bình đang hình thành! Đừng xem nhẹ cảm xúc của bé, hãy hỗ trợ sự phát triển: "Lần vẽ sau con thử dùng thêm màu đỏ xem sao?".', title_zh = '批评自己的画 🖍️', body_zh = '指着自己画的黑乎乎的涂鸦说“这是你，可是画坏了”，然后撕掉扔了。自我批评的能力正在出现！别轻视宝宝的感受，说一句“下一张也许可以试试红色？”，支持宝宝的成长。' WHERE id = '732719f9-46cf-4097-a068-781df2eeaf00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Esto lo he encontrado yo» en el súper 🛒', body_es = 'Al llegar a la caja sale del carro un paquete de galletas que tú no pusiste. Ha hecho una exploración silenciosa. Abre la Lista de la compra y deja la norma en manos de una autoridad digital: «Mira, esto no está en nuestra lista, la próxima vez lo apuntamos».', title_fr = '« C''est moi qui l''ai trouvé » au supermarché 🛒', body_fr = 'En arrivant à la caisse, un paquet de biscuits que vous n''avez pas mis sort du chariot. Il a mené son exploration en silence. Ouvrez la Liste de courses et dites « Regarde, ce n''est pas sur notre liste, on l''ajoutera la prochaine fois » pour confier la règle à une autorité numérique.', title_hi = 'बाज़ार में ‘यह मुझे मिला’ 🛒', body_hi = 'काउंटर के पास पहुँचते ही ट्रॉली से बिस्कुट का एक पैकेट निकलता है, जो आपने नहीं रखा था। उसने चुपचाप खोजबीन की है। शॉपिंग लिस्ट खोलिए और ‘देखो, यह हमारी लिस्ट में नहीं है, अगली बार लिखेंगे’ कहकर नियम का भार एक डिजिटल अधिकारी पर डाल दीजिए।', title_id = '''Aku yang menemukan'' di supermarket 🛒', body_id = 'Saat mendekati kasir, dari troli muncul sebungkus biskuit yang tidak Anda masukkan. Ia diam-diam melakukan penjelajahan. Buka Daftar Belanja dan katakan ''Lihat, ini tidak ada di daftar kita, nanti kita tulis untuk lain kali'', dan serahkan aturan itu pada otoritas digital.', title_ja = 'スーパーで「ぼくが見つけた」 🛒', body_ja = 'レジに近づくと、あなたが入れていないクッキーがひと袋カートから出てくる。こっそり探検していたんです。「買い物リスト」を開いて「ほら、リストにはないね、次は書いておこう」と言い、ルールをデジタルな権威にまかせましょう。', title_ko = '마트에서 ''내가 찾았어'' 🛒', body_ko = '계산대에 다가가니 카트에서 엄마가 넣지 않은 과자 한 봉지가 나왔나요? 조용히 탐험을 다녀온 거예요. 쇼핑 목록을 열고 ''봐, 우리 목록에 이건 없어, 다음에 적자''라며 규칙을 디지털 권위에 맡기세요.', title_nl = '''Dit heb ik gevonden'' in de supermarkt 🛒', body_nl = 'Bij de kassa komt er uit het karretje een pak koekjes dat jij er niet in hebt gelegd. Hij heeft stilletjes op verkenning gezeten. Open het Boodschappenlijstje en laat de regel over aan een digitale autoriteit: ''Kijk, dit staat niet op ons lijstje, we zetten het er volgende keer op.''', title_pl = '„Ja to znalazłem” w sklepie 🛒', body_pl = 'Przy kasie z wózka wyłania się paczka ciastek, której nie wkładałaś. Po cichu prowadził zwiad. Otwórz Listę zakupów, powiedz „Zobacz, tego nie ma na naszej liście, dopiszemy następnym razem” i zrzuć zasadę na cyfrowy autorytet.', title_pt = '"Fui eu que encontrei" no supermercado 🛒', body_pt = 'Ao chegar à caixa, sai do carrinho um pacote de bolachas que não pôs lá. Fez uma exploração silenciosa. Abra a Lista de Compras, diga "Olha, isto não está na nossa lista, da próxima vez escrevemos" e passe a regra para uma autoridade digital.', title_sv = '”Jag hittade den” i butiken 🛒', body_sv = 'När ni närmar er kassan dyker ett kexpaket som du inte lagt dit upp ur vagnen. Barnet har gjort en tyst spaningsrunda. Öppna Inköpslistan, säg ”Titta, det här står inte på vår lista, vi skriver upp det nästa gång” och lägg regeln på en digital auktoritet.', title_vi = '"Con tìm thấy cái này" ở siêu thị 🛒', body_vi = 'Khi đến gần quầy thanh toán, từ xe đẩy lôi ra một gói bánh quy mà mẹ không bỏ vào. Bé đã lặng lẽ "thám hiểm". Hãy mở Danh sách mua sắm và nói: "Nhìn này, trong danh sách của mình không có món này, lần sau mình ghi vào nhé", để "quyền lực số" gánh hộ quy tắc.', title_zh = '超市里：“这是我找到的” 🛒', body_zh = '快到收银台时，购物车里冒出了一包你没放过的饼干。宝宝悄悄完成了一次“侦察”。打开购物清单，说一句“你看，我们的清单上没有这个，下次再写上”，把规矩交给一个“数字权威”来执行。' WHERE id = 'aa506c93-122a-43f1-8742-2605113c516c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un inventor genial 👟', body_es = 'Se pone el zapato en la oreja y, muy serio, dice «¿Diga?» y se pone a hablar. ¡Inventa nuevas funciones para las cosas! No te pierdas esta escena absurda y genial. Graba a este inventor tan cómico con la Sesión de fotos del bebé y ponlo en el lugar más destacado del archivo.', title_fr = 'Un inventeur de génie 👟', body_fr = 'Il tient sa chaussure contre son oreille et dit très sérieusement « Allô ? » avant de bavarder. Il invente de nouvelles fonctions aux objets ! Ne manquez pas cette scène absurde et géniale. Immortalisez ce drôle d''inventeur avec la Séance photo bébé et donnez-lui la plus belle place de vos archives.', title_hi = 'जीनियस आविष्कारक 👟', body_hi = 'जूता कान से लगाकर गंभीरता से ‘हैलो’ कहकर बातें कर रहा है। वह चीज़ों के नए काम गढ़ रहा है! यह बेतुका और शानदार पल मत चूकिए। बेबी फ़ोटोशूट से इस मज़ेदार आविष्कारक को कैद कीजिए और यादों में सबसे चमकती जगह दीजिए।', title_id = 'Penemu jenius 👟', body_id = 'Ia menempelkan sepatu ke telinga dan dengan serius berkata ''Halo'' lalu bercerita? Ia sedang menciptakan fungsi baru untuk benda-benda! Jangan lewatkan momen absurd sekaligus jenius ini. Abadikan penemu lucu ini dengan Pemotretan Bayi dan taruh di tempat paling bersinar di arsip Anda.', title_ja = '天才発明家 👟', body_ja = '靴を耳にあてて、真剣に「もしもし」と何か話している。ものに新しい役割を考え出しているんです！このおかしくて天才的な一枚を見逃さないで。「ベビーフォトセッション」でこの愉快な発明家を撮って、アルバムのいちばん目立つところに残しましょう。', title_ko = '천재 발명가 👟', body_ko = '신발을 귀에 대고 진지하게 ''여보세요'' 하며 이야기하나요? 물건에 새로운 기능을 만들어 내는 중이에요! 이 엉뚱하고 천재적인 장면을 놓치지 마세요. 아기 사진 촬영으로 이 웃긴 발명가를 담아 기록의 가장 빛나는 자리에 두세요.', title_nl = 'Geniale uitvinder 👟', body_nl = 'Hij houdt zijn schoen tegen zijn oor en zegt heel serieus ''Hallo?''. Hij bedenkt nieuwe functies voor dingen! Mis dit absurde, geniale plaatje niet. Leg deze grappige uitvinder vast met de Babyfotoshoot en geef hem de mooiste plek in je archief.', title_pl = 'Genialny wynalazca 👟', body_pl = 'Przykłada but do ucha i całkiem poważnie mówi „Halo”, coś opowiadając. Wymyśla przedmiotom nowe funkcje! Nie przegap tego absurdalnego i genialnego kadru. Uwiecznij tego zabawnego wynalazcę w Sesji zdjęciowej dziecka i daj mu najjaśniejsze miejsce w archiwum.', title_pt = 'O inventor genial 👟', body_pt = 'Põe o sapato ao ouvido e diz muito a sério "Estou?", a conversar? Está a inventar novas funções para os objetos! Não perca este momento absurdo e genial. Registe este inventor cómico com a Sessão Fotográfica do Bebé e ponha-o no lugar de maior destaque do arquivo.', title_sv = 'Den geniala uppfinnaren 👟', body_sv = 'Barnet håller skon mot örat och pratar på största allvar: ”Hallå?” Barnet hittar på nya funktioner för saker! Missa inte den absurda och geniala bilden. Fånga den roliga uppfinnaren med Babyfotografering och ge bilden den mest lysande platsen i arkivet.', title_vi = 'Nhà phát minh thiên tài 👟', body_vi = 'Bé áp chiếc giày lên tai và nghiêm túc nói "A lô". Bé đang nghĩ ra những công dụng mới cho đồ vật! Đừng bỏ lỡ khoảnh khắc ngộ nghĩnh mà thiên tài này. Hãy ghi lại "nhà phát minh" hài hước này bằng Chụp ảnh cho bé và đặt vào vị trí nổi bật nhất trong kho kỷ niệm.', title_zh = '天才发明家 👟', body_zh = '把鞋贴在耳朵上，一本正经地说“喂”，聊了起来。宝宝在给东西发明新功能！别错过这个荒诞又天才的画面。用宝宝写真把这位搞笑的小发明家拍下来，放在相册最闪亮的位置。' WHERE id = 'd3d2b281-0b44-4f04-8791-8ceca32ccdb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un té a solas los dos 🥂', body_es = 'Después de un día difícil, sirve en los vasos un simple té caliente. Sentaos frente a frente en el sofá tú y tu pareja y brindad diciendo: «Hoy también hemos sobrevivido a este caos, somos un gran equipo». Sois los cimientos inquebrantables de la casa.', title_fr = 'Le plaisir d''un thé à deux 🥂', body_fr = 'Après une journée difficile, versez du simple thé chaud dans des verres. Asseyez-vous face à votre partenaire sur le canapé et trinquez : « On a survécu à ce chaos aujourd''hui aussi, on fait une super équipe. » Vous êtes les fondations inébranlables de cette maison.', title_hi = 'आमने-सामने चाय का मज़ा 🥂', body_hi = 'मुश्किल दिन के बाद गिलासों में सादी गरम चाय डालिए। अपने साथी के साथ सोफ़े पर आमने-सामने बैठिए और ‘आज उस अफ़रा-तफ़री से भी निकल आए, हम कमाल की टीम हैं’ कहकर गिलास टकराइए। आप इस घर की अटूट नींव हैं।', title_id = 'Teh berdua 🥂', body_id = 'Setelah hari yang berat, tuang teh hangat biasa ke gelas. Duduklah berhadapan dengan pasangan di sofa dan bersulanglah sambil berkata ''Hari ini pun kita selamat dari kekacauan itu, kita tim yang hebat''. Kalian adalah fondasi rumah yang tak tergoyahkan.', title_ja = 'ふたりでお茶タイム 🥂', body_ja = '大変な一日のあと、コップにふつうの温かいお茶を注ぎましょう。パートナーとソファで向かい合って「今日もあのカオスを乗りきったね、最高のチームだね」と乾杯を。ふたりはこの家の揺るがない土台です。', title_ko = '둘만의 차 한 잔 🥂', body_ko = '힘든 하루가 끝나면 컵에 평범한 따뜻한 차를 따르세요. 배우자와 소파에 마주 앉아 ''오늘 그 혼돈에서도 살아남았어, 우리 최고의 팀이야''라며 건배하세요. 두 사람은 이 집의 흔들림 없는 기둥이에요.', title_nl = 'Samen theedrinken 🥂', body_nl = 'Schenk na een zware dag gewone warme thee in. Ga tegenover je partner op de bank zitten en klink: ''Ook die chaos van vandaag hebben we overleefd, we zijn een top-team.'' Jullie zijn het onverwoestbare fundament van dit huis.', title_pl = 'Herbatka we dwoje 🥂', body_pl = 'Po trudnym dniu nalejcie do szklanek zwykłej gorącej herbaty. Usiądźcie z partnerem na kanapie twarzą w twarz i stuknijcie się szklankami: „Z tego chaosu też dziś wyszliśmy cało, jesteśmy świetną drużyną”. Jesteście niezłomnym fundamentem tego domu.', title_pt = 'Um chá a dois 🥂', body_pt = 'Depois de um dia difícil, sirvam simplesmente chá quente nos copos. Sentem-se frente a frente no sofá com o seu companheiro e brindem: "Hoje também sobrevivemos ao caos, somos uma ótima equipa". São os alicerces inabaláveis desta casa.', title_sv = 'Teestund på tu man hand 🥂', body_sv = 'Efter den tuffa dagen, häll upp vanligt varmt te i glasen. Sätt dig mitt emot din partner i soffan och skåla: ”I dag överlevde vi det här kaoset också, vi är ett toppenlag.” Ni är hemmets orubbliga grund.', title_vi = 'Trà riêng hai người 🥂', body_vi = 'Sau một ngày vất vả, hãy rót trà nóng bình thường vào cốc. Ngồi đối diện chồng trên sofa và cụng ly: "Hôm nay mình lại sống sót qua mớ hỗn loạn đó rồi, mình là một đội tuyệt vời". Hai người là nền móng vững chắc của ngôi nhà này.', title_zh = '两个人的喝茶时光 🥂', body_zh = '艰难的一天过后，往杯子里倒上普通的热茶。和伴侣面对面坐在沙发上，碰个杯：“今天这场混乱我们也挺过来了，我们是最棒的团队。”你们是这个家坚不可摧的基石。' WHERE id = '0b6916b1-4773-417f-aed4-71c7ff7f85e9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Encuentra ese único grano de arroz o trocito de zanahoria en la sopa y dice: «Esto no me lo como». Entra en el Plan de alimentación. Aprende a convertir las proteínas y las verduras en magdalenas de colores y engaña al cerebro de este cocinero tan tozudo.', body_fr = 'Il a trouvé l''unique grain de riz ou morceau de carotte de la soupe et dit « Je mange pas ça ». Ouvrez le Plan de nutrition. Apprenez à transformer protéines et légumes en muffins colorés et déjouez ce petit chef têtu.', body_hi = 'सूप में वह एक चावल का दाना या गाजर ढूँढकर कहता है, ‘मैं यह नहीं खाऊँगा।’ फ़ीडिंग प्लान खोलिए। सीखिए कि प्रोटीन और सब्ज़ियों को रंगीन मफ़िन का रूप कैसे दें, और इस ज़िद्दी शेफ़ के दिमाग को चकमा दीजिए।', body_id = 'Ia menemukan sebutir nasi atau sepotong wortel di supnya dan berkata ''Aku nggak mau makan ini''. Buka Rencana Nutrisi. Pelajari cara mengubah protein dan sayur menjadi bentuk muffin berwarna-warni dan kelabui otak koki keras kepala ini.', body_ja = 'スープの中のたったひと粒のお米やにんじんを見つけて「これ食べない」と言う。「栄養管理ツール」を開いてみましょう。たんぱく質や野菜をカラフルなマフィンの形にする方法を覚えて、このがんこなシェフの頭をうまくだましましょう。', body_ko = '수프 속 쌀 한 톨이나 당근 하나를 찾아내고 ''이거 안 먹어''라고 하나요? 식단 계획에 들어가 보세요. 단백질과 채소를 알록달록한 머핀 모양으로 만드는 법을 배워 이 고집쟁이 요리사를 속여 보세요.', body_nl = 'Vindt hij dat ene rijstkorreltje of stukje wortel in zijn soep en zegt hij ''Dit eet ik niet''? Open het Voedingsplan. Leer hoe je eiwitten en groenten in kleurrijke muffinvormpjes verwerkt en fop het brein van deze koppige kok.', body_pl = 'Znalazł w zupie to jedno ziarenko ryżu albo kawałek marchewki i mówi „Tego nie zjem”. Zajrzyj do planu karmienia. Naucz się, jak zamienić białko i warzywa w kolorowe babeczki, i przechytrz tego upartego kucharza.', body_pt = 'Encontra aquele único grão de arroz ou pedaço de cenoura na sopa e diz "Não como isto". Entre no Registo de Alimentação. Aprenda a dar às proteínas e aos legumes a forma de queques coloridos e engane o cérebro deste cozinheiro teimoso.', body_sv = 'Barnet hittar det enda riskornet eller den enda morotsbiten i soppan och säger ”Det här äter jag inte”. Gå in i matplanen. Lär dig hur du gör proteiner och grönsaker till färgglada muffins och lura den envisa kockens hjärna.', body_vi = 'Bé tìm thấy đúng một hạt cơm hay miếng cà rốt trong bát súp và nói "Con không ăn cái này". Hãy vào Kế hoạch dinh dưỡng. Học cách biến chất đạm và rau củ thành những chiếc bánh nướng xốp nhiều màu để "đánh lừa" vị đầu bếp bướng bỉnh này.', body_zh = '在汤里发现一粒米或一块胡萝卜，就说“我不吃这个”。去喂养计划里看看，学学如何把蛋白质和蔬菜做成彩色的小蛋糕，骗过这位倔强小厨师的大脑吧。' WHERE id = '8bce8353-bf73-417b-8a15-56b41142ba18' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las olimpiadas de trepar por los muebles 🧗‍♂️', body_es = 'Trepa por el borde del sofá hacia la ventana. Para ti la casa está llena de peligros; para él es un gimnasio. En lugar de crear pánico con «¡Cuidado, que te caes!», dirige bien esta necesidad de moverse diciendo «Pon la mano ahí».', title_fr = 'Les olympiades d''escalade des meubles 🧗‍♂️', body_fr = 'Il escalade le bord du canapé en direction de la fenêtre. Pour vous, la maison est pleine de dangers, pour lui, c''est une salle de sport. Au lieu de semer la panique avec « Attention, tu vas tomber ! », guidez correctement ce besoin de bouger : « Mets ta main là. »', title_hi = 'फ़र्नीचर पर चढ़ने का ओलंपिक 🧗‍♂️', body_hi = 'सोफ़े के किनारे से खिड़की की ओर चढ़ रहा है। घर आपके लिए खतरों से भरा है, उसके लिए जिम। ‘सँभलकर, गिर जाओगे!’ कहकर घबराहट फैलाने के बजाय ‘अपना हाथ वहाँ रखो’ कहकर हिलने-डुलने की इस ज़रूरत को सही दिशा दीजिए।', title_id = 'Olimpiade memanjat perabot 🧗‍♂️', body_id = 'Ia memanjat pinggiran sofa menuju jendela. Bagi Anda rumah penuh bahaya, baginya rumah adalah pusat kebugaran. Daripada panik dan berteriak ''Hati-hati, nanti jatuh!'', arahkan kebutuhannya untuk bergerak dengan benar: ''Taruh tanganmu di situ''.', title_ja = '家具のぼりオリンピック 🧗‍♂️', body_ja = 'ソファのはしから窓のほうへよじのぼっていく。家はあなたにとって危険だらけでも、この子にとってはジムなんです。「気をつけて、落ちるよ！」とあわてる代わりに「手はそこに置いてね」と言って、体を動かしたい気持ちを正しい方向へ導きましょう。', title_ko = '가구 오르기 올림픽 🧗‍♂️', body_ko = '소파 가장자리를 따라 창문 쪽으로 기어오르나요? 엄마에게 집은 위험투성이지만 아이에게는 체육관이에요. ''조심해, 떨어져!'' 하며 겁주는 대신 ''손은 여기 짚어''라며 움직이고 싶은 마음을 올바르게 이끌어 주세요.', title_nl = 'Olympische spelen meubelklimmen 🧗‍♂️', body_nl = 'Hij klimt langs de rand van de bank richting het raam. Voor jou zit het huis vol gevaren, voor hem is het een sportschool. Roep niet in paniek ''Pas op, je valt!'', maar stuur zijn behoefte aan beweging de goede kant op: ''Zet je hand daar.''', title_pl = 'Olimpiada wspinaczki po meblach 🧗‍♂️', body_pl = 'Wspina się po brzegu kanapy w stronę okna. Dla ciebie dom jest pełen zagrożeń, dla niego to siłownia. Zamiast panikować „Uważaj, spadniesz!”, właściwie pokieruj tą potrzebą ruchu: „Połóż rękę tutaj”.', title_pt = 'As olimpíadas de trepar móveis 🧗‍♂️', body_pt = 'Trepa pela borda do sofá em direção à janela. Para si, a casa está cheia de perigos; para ele, é um ginásio. Em vez de criar pânico com "Cuidado, vais cair!", diga "Põe a mão ali" e oriente bem esta necessidade de movimento.', title_sv = 'Möbelklättringsolympiaden 🧗‍♂️', body_sv = 'Barnet klättrar längs soffkanten mot fönstret. För dig är hemmet fullt av faror, för barnet ett gym. Istället för att skapa panik med ”Akta dig, du ramlar!”, säg ”Sätt handen där” och styr behovet av rörelse åt rätt håll.', title_vi = 'Thế vận hội leo trèo đồ đạc 🧗‍♂️', body_vi = 'Bé trèo theo mép sofa về phía cửa sổ. Với mẹ, căn nhà đầy nguy hiểm, còn với bé là phòng tập thể dục. Thay vì hoảng hốt hét lên "Cẩn thận, con ngã đấy!", hãy hướng dẫn đúng nhu cầu vận động này: "Con đặt tay vào chỗ này".', title_zh = '爬家具奥运会 🧗‍♂️', body_zh = '顺着沙发边往窗户那边爬。对你来说，家里处处是危险；对宝宝来说，却是一座健身房。与其惊慌地喊“小心，会摔下来的！”，不如说“把手放在这里”，正确地引导宝宝对运动的需要。' WHERE id = 'ef39807d-1235-46a3-9ca8-a0f70bb2fa23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y calma 🤖', body_es = '¿Un tartamudeo repentino o las crisis de rabia de tu peque te han llevado a buscar enfermedades graves en internet? ¡Para! Pregunta a Anacan AI si es un salto de desarrollo de los 3 años y obtén una respuesta tranquilizadora avalada por pediatras.', title_fr = 'Intelligence artificielle et sérénité 🤖', body_fr = 'Un bégaiement soudain ou des crises de colère vous ont poussée à chercher des maladies graves sur Internet ? Stop ! Demandez à Anacan AI s''il s''agit d''un bond de développement des 3 ans et obtenez une réponse rassurante, validée par des pédiatres.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और सुकून 🤖', body_hi = 'बच्चे का अचानक हकलाना या गुस्से के दौरे आपको इंटरनेट पर बुरी बीमारियाँ ढूँढने पर मजबूर कर गए? रुकिए! Anacan AI से पूछिए कि क्या यह 3 साल की विकास की छलाँग है, और बाल रोग विशेषज्ञ द्वारा पुष्ट, राहत देने वाला जवाब पाइए।', title_id = 'Kecerdasan buatan dan ketenangan 🤖', body_id = 'Gagap atau ledakan amarah yang tiba-tiba muncul membuat Anda mencari penyakit menakutkan di internet? Berhenti! Tanyakan pada Anacan AI apakah ini lompatan perkembangan usia 3 tahun, dan dapatkan jawaban menenangkan yang disetujui dokter anak.', title_ja = 'AIと安心 🤖', body_ja = '急に始まった吃音やかんしゃくに、ネットで悪い病気をさがしてしまった？ストップ！Anacan AIに、3歳の発達の飛躍かどうかをたずねて、小児科医も認める安心できる答えをもらいましょう。', title_ko = '인공지능과 평온 🤖', body_ko = '아이의 갑작스러운 말더듬이나 분노 폭발에 인터넷에서 무서운 병을 찾아보게 됐나요? 멈추세요! Anacan AI에게 세 살의 발달 도약인지 물어보고 소아과 의사가 확인한 안심되는 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en rust 🤖', body_nl = 'Zette het plotselinge stotteren of de woedeaanvallen van je kind je aan het zoeken naar enge ziektes op internet? Stop! Vraag Anacan AI of het een ontwikkelingssprong rond 3 jaar is en krijg een geruststellend, door kinderartsen bevestigd antwoord.', title_pl = 'Sztuczna inteligencja i spokój 🤖', body_pl = 'Nagłe jąkanie się albo wybuchy złości dziecka sprawiły, że zaczęłaś szukać w internecie groźnych chorób? Stop! Zapytaj Anacan AI, czy to skok rozwojowy 3-latka, i uzyskaj uspokajającą odpowiedź potwierdzoną przez pediatrów.', title_pt = 'Inteligência artificial e serenidade 🤖', body_pt = 'A gaguez repentina ou as crises de raiva do seu filho levaram-na a procurar doenças graves na internet? Pare! Pergunte ao Anacan AI se é um salto de desenvolvimento dos 3 anos e obtenha uma resposta tranquilizadora, validada por pediatras.', title_sv = 'Artificiell intelligens och lugn 🤖', body_sv = 'Fick barnets plötsliga stamning eller vredesutbrott dig att söka efter allvarliga sjukdomar på nätet? Stopp! Fråga Anacan AI om det är ett utvecklingssprång vid 3 år och få ett barnläkargodkänt, lugnande svar.', title_vi = 'Trí tuệ nhân tạo và sự bình yên 🤖', body_vi = 'Việc bé bỗng nói lắp hay nổi giận dữ dội khiến mẹ lên mạng tìm những căn bệnh đáng sợ? Dừng lại! Hãy hỏi Anacan AI xem đó có phải bước nhảy vọt phát triển của tuổi lên 3 không và nhận câu trả lời được bác sĩ nhi khoa xác nhận, giúp mẹ nhẹ lòng.', title_zh = '人工智能与平静 🤖', body_zh = '孩子突然出现的口吃或发脾气，让你忍不住在网上搜各种可怕的疾病？停下！问问Anacan AI，这是否是3岁的发育飞跃，得到经儿科医生认可、让人安心的答案。' WHERE id = '000abcf3-b4c9-4928-8d58-c7a8f138f07f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Efectos de sonido en la habitación 🪄', body_es = 'Abre Cuentos inteligentes. Mientras lees la historia, crea un teatro sonoro en la habitación imitando el chirrido de una puerta, el viento y los susurros. Estas ondas sonoras tan originales atraerán al instante su atención al cuento, y de ahí a un sueño profundo.', title_fr = 'Effets sonores dans la chambre 🪄', body_fr = 'Ouvrez les Contes intelligents. En lisant l''histoire, faites simplement le grincement de la porte, le bruit du vent et des chuchotements pour créer un théâtre sonore dans la chambre. Ces ondes sonores inhabituelles attireront aussitôt son attention dans le conte, puis dans un sommeil profond.', title_hi = 'कमरे में आवाज़ों के इफ़ेक्ट 🪄', body_hi = 'स्मार्ट कहानियाँ खोलिए। कहानी पढ़ते समय बस दरवाज़े की चरमराहट, हवा की आवाज़ और सरसराहट निकालकर कमरे में आवाज़ों का थिएटर बनाइए। ये अनोखी आवाज़ की लहरें उसका ध्यान तुरंत कहानी में, और वहाँ से गहरी नींद में खींच लेंगी।', title_id = 'Efek suara di kamar 🪄', body_id = 'Buka Dongeng Pintar. Saat membacakan cerita, cukup tirukan derit pintu, suara angin, dan desisan untuk menciptakan teater suara di kamar. Gelombang suara yang tak biasa ini akan langsung menarik perhatiannya ke dalam dongeng, lalu ke dalam tidur yang nyenyak.', title_ja = '部屋の効果音 🪄', body_ja = '「スマートおはなし」を開きましょう。お話を読みながら、ドアのきしむ音や風の音、ひそひそ声を出して、部屋に音の劇場をつくって。このいつもとちがう音の波が、すぐにお話の中へ、そして深い眠りへと引きこんでくれます。', title_ko = '방 안의 음향 효과 🪄', body_ko = '스마트 동화를 열어 보세요. 이야기를 읽으며 문 삐걱거리는 소리, 바람 소리, 속삭임만 내어 방에 소리 극장을 만들어 보세요. 이 색다른 소리가 아이의 관심을 바로 이야기 속으로, 그리고 깊은 잠으로 이끌 거예요.', title_nl = 'Geluidseffecten in de kamer 🪄', body_nl = 'Open Slimme sprookjes. Maak tijdens het voorlezen gewoon het kraken van een deur, het geluid van de wind en een gefluister na, en bouw zo een geluidstheater in de kamer. Die ongewone geluidsgolven trekken zijn aandacht meteen het verhaal in, en van daaruit een diepe slaap in.', title_pl = 'Efekty dźwiękowe w pokoju 🪄', body_pl = 'Otwórz Mądre bajki. Czytając historię, naśladuj skrzypienie drzwi, szum wiatru i szept, tworząc w pokoju teatr dźwięku. Te niezwykłe fale dźwięku od razu wciągną jego uwagę w bajkę, a stamtąd w głęboki sen.', title_pt = 'Efeitos sonoros no quarto 🪄', body_pt = 'Abra as Histórias Inteligentes. Enquanto lê a história, faça apenas o ranger da porta, o som do vento e sussurros, e crie no quarto um teatro de sons. Estas ondas sonoras fora do comum vão levar logo a atenção dele para dentro da história e, dali, para um sono profundo.', title_sv = 'Ljudeffekter i rummet 🪄', body_sv = 'Öppna Smarta sagor. Medan du läser berättelsen, gör bara dörrknarr, vindsus och viskningar och bygg en ljudteater i rummet. De ovanliga ljudvågorna drar genast in barnets uppmärksamhet i sagan, och därifrån in i djup sömn.', title_vi = 'Hiệu ứng âm thanh trong phòng 🪄', body_vi = 'Hãy mở Truyện cổ tích thông minh. Khi đọc truyện, chỉ cần tạo tiếng cửa kẽo kẹt, tiếng gió và tiếng thì thầm để dựng một nhà hát âm thanh trong phòng. Những làn sóng âm thanh khác lạ này sẽ lập tức kéo bé vào câu chuyện, rồi từ đó vào giấc ngủ sâu.', title_zh = '房间里的音效 🪄', body_zh = '打开智慧童话。读故事时，只要发出门的吱呀声、风声和沙沙的悄悄声，就能在房间里搭起一座声音剧场。这些不寻常的声波会马上把宝宝的注意力吸进故事里，再从故事带进深深的梦乡。' WHERE id = 'ac974535-4db4-4ecb-aa90-d75a7dabe40a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Huyendo de la sombra 👻', body_es = 'Andando por la calle, de repente se asustó de su sombra y se refugió detrás de ti. No busques lógica: así funciona la imaginación de los 3 años y medio. Convierte al instante lo que le asusta en un juego físico: «¡Vamos a saltar encima de la sombra!».', title_fr = 'Fuir son ombre 👻', body_fr = 'En marchant dans la rue, il a soudain eu peur de son ombre et s''est réfugié derrière vous. Ne cherchez pas de logique, l''imagination des 3 ans et demi fonctionne ainsi. Transformez aussitôt l''objet de sa peur en jeu physique : « Viens, on saute sur l''ombre ! »', title_hi = 'परछाईं से भागना 👻', body_hi = 'सड़क पर चलते-चलते अचानक अपनी परछाईं से डरकर आपके पीछे छिप गया। तर्क मत ढूँढिए, साढ़े 3 साल की कल्पना ऐसे ही काम करती है। ‘आओ, परछाईं पर कूदें’ कहकर जिस चीज़ से वह डरता है, उसे तुरंत एक शारीरिक खेल में बदल दीजिए।', title_id = 'Kabur dari bayangan 👻', body_id = 'Saat berjalan di jalan, tiba-tiba ia takut pada bayangannya sendiri dan berlindung di belakang Anda. Jangan mencari logika, begitulah imajinasi anak 3,5 tahun bekerja. Ubah benda yang ia takuti menjadi permainan fisik dengan berkata ''Ayo kita lompati bayangannya!''.', title_ja = '影から逃げろ 👻', body_ja = '道を歩いていて、急に自分の影が怖くなってあなたの後ろに隠れた。理屈を求めないで。3歳半の想像力はこう働くんです。「影の上にジャンプしよう」と言って、怖いものをすぐに体を使う遊びに変えましょう。', title_ko = '그림자에게서 도망치기 👻', body_ko = '길을 걷다 갑자기 자기 그림자가 무서워 엄마 뒤에 숨었나요? 논리를 찾지 마세요, 세 살 반의 상상력은 원래 그래요. ''우리 그림자 위로 뛰어 볼까?''라며 무서운 대상을 바로 몸 놀이로 바꿔 주세요.', title_nl = 'Op de vlucht voor de schaduw 👻', body_nl = 'Op straat schrok hij ineens van zijn eigen schaduw en kroop hij achter je weg. Zoek geen logica, zo werkt de fantasie van een kind van 3,5. Maak van waar hij bang voor is meteen een lichamelijk spel: ''Kom, we springen op de schaduw!''', title_pl = 'Ucieczka przed cieniem 👻', body_pl = 'Idąc ulicą, nagle przestraszył się swojego cienia i schował się za tobą. Nie szukaj logiki, tak działa wyobraźnia 3,5-latka. Od razu zamień to, czego się boi, w zabawę ruchową: „Wskoczmy na cień!”.', title_pt = 'Fugir da sombra 👻', body_pt = 'A andar na rua, assustou-se de repente com a própria sombra e escondeu-se atrás de si. Não procure lógica: a imaginação dos 3 anos e meio funciona assim. Diga "Vamos saltar para cima da sombra" e transforme logo o que o assusta num jogo físico.', title_sv = 'Flykt från skuggan 👻', body_sv = 'När ni gick på gatan blev barnet plötsligt rädd för sin skugga och sökte skydd bakom dig. Leta inte efter logik, det är så 3,5-åringens fantasi fungerar. Säg ”Kom så hoppar vi på skuggan” och gör genast det barnet är rädd för till en fysisk lek.', title_vi = 'Chạy trốn cái bóng 👻', body_vi = 'Đang đi ngoài đường, bé bỗng sợ cái bóng của mình và nấp sau lưng mẹ. Đừng tìm logic, trí tưởng tượng của tuổi 3,5 là như vậy. Hãy lập tức biến thứ bé sợ thành trò chơi vận động: "Mình cùng nhảy lên cái bóng nào!".', title_zh = '逃离影子 👻', body_zh = '走在街上，突然被自己的影子吓得躲到你身后。别找逻辑，3岁半的想象力就是这样运作的。说一句“我们来跳到影子上吧”，马上把宝宝害怕的东西变成一个活动身体的游戏。' WHERE id = 'e9945ad4-3802-48f8-b0bf-d94527c3999b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El masaje de hombros de papá 💆‍♂️', body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de él y recoger juguetes del suelo. En cuanto se duerma, pídele a tu pareja un masaje de hombros de 10 minutos. Eres el motor de la casa, y el motor necesita descansar y recuperarse sí o sí.', title_fr = 'Le massage des épaules par papa 💆‍♂️', body_fr = 'Vous êtes restée debout toute la journée et votre dos est en miettes à force de lui courir après et de ramasser les jouets. Dès que l''enfant dort, demandez à votre partenaire 10 minutes de massage des épaules. Vous êtes le moteur de la maison, et un moteur doit absolument se reposer et se recharger.', title_hi = 'पापा की कंधों वाली मालिश 💆‍♂️', body_hi = 'आज आप बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते, ज़मीन से खिलौने उठाते-उठाते कमर टूट रही है। बच्चे के सोते ही अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप घर का इंजन हैं, और इंजन को आराम करना और फिर से तैयार होना ज़रूरी है।', title_id = 'Pijat bahu dari pasangan 💆‍♂️', body_id = 'Hari ini kamu terlalu lama berdiri, punggungmu serasa patah karena mengejarnya dan memunguti mainan dari lantai. Begitu anak tidur, mintalah pijat bahu 10 menit dari pasanganmu. Kamu mesin rumah ini, dan mesin wajib beristirahat dan dipulihkan.', title_ja = 'パパの肩もみ 💆‍♂️', body_ja = '今日は立ちっぱなしで、追いかけまわして、床のおもちゃを拾って、腰がくたくたですね。子どもが寝たらすぐ、パートナーに10分の肩もみをお願いして。あなたはこの家のエンジンです。エンジンだって、ちゃんと休んで回復しなくちゃ。', title_ko = '아빠의 어깨 마사지 💆‍♂️', body_ko = '오늘 하루 종일 서 있었고 아이를 쫓아다니며 장난감을 줍느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 이 집의 엔진이고, 엔진도 꼭 쉬고 회복해야 해요.', title_nl = 'Papa''s schoudermassage 💆‍♂️', body_nl = 'Je hebt vandaag veel op je benen gestaan en je rug breekt van het achter hem aan rennen en speelgoed oprapen. Vraag je partner om een schoudermassage van 10 minuten zodra je kind slaapt. Jij bent de motor van het huis, en een motor moet zeker rusten en hersteld worden.', title_pl = 'Masaż ramion od taty 💆‍♂️', body_pl = 'Dziś długo byłaś na nogach, plecy bolą cię od biegania za nim i zbierania zabawek z podłogi. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś silnikiem tego domu, a silnik musi odpoczywać i się regenerować.', title_pt = 'Massagem nos ombros do pai 💆‍♂️', body_pt = 'Hoje esteve muito tempo de pé e as costas doem-lhe de correr atrás dele e apanhar brinquedos do chão. Assim que a criança adormecer, peça ao seu companheiro 10 minutos de massagem nos ombros. É o motor desta casa, e o motor precisa de descansar e ser restaurado.', title_sv = 'Axelmassage av pappa 💆‍♂️', body_sv = 'Du har stått på benen länge i dag och ryggen värker av allt springande efter barnet och plockande av leksaker från golvet. Så fort barnet somnar, be din partner om 10 minuters axelmassage. Du är hemmets motor, och en motor måste vila och återhämta sig.', title_vi = 'Mát-xa vai từ chồng 💆‍♂️', body_vi = 'Hôm nay mẹ đứng cả ngày, lưng như muốn gãy vì chạy theo bé và nhặt đồ chơi dưới sàn. Ngay khi bé ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là động cơ của ngôi nhà này, và động cơ thì nhất định phải được nghỉ ngơi, phục hồi.', title_zh = '爸爸的肩膀按摩 💆‍♂️', body_zh = '今天你站了太久，追着宝宝跑、从地上捡玩具，腰都快断了。宝宝一睡着，就请伴侣给你按摩10分钟肩膀。你是这个家的发动机，发动机也一定要好好休息、好好修复。' WHERE id = '06d21315-e90d-4d7c-a84d-b0f3acd86dc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te ha dicho «¡Eres mala madre!»? 💔', body_es = 'Te ha soltado esa frase porque no le compraste el coche que quería. Se te ha encogido el corazón. Pero debes saber que todavía no sabe expresar bien sus emociones; en realidad quiere decir «estoy decepcionado». Simplemente abrázale y acepta lo que siente.', title_fr = 'Il vous a dit « T''es une mauvaise maman » ? 💔', body_fr = 'Il a dit cette phrase parce que vous ne lui avez pas acheté la voiture qu''il voulait. Votre cœur s''est serré. Mais sachez qu''il ne sait pas encore exprimer correctement ses émotions : il veut en fait dire « je suis déçu ». Serrez-le simplement dans vos bras et accueillez ce qu''il ressent.', title_hi = 'कहा, ‘तुम बुरी माँ हो!’? 💔', body_hi = 'उसकी मनपसंद गाड़ी नहीं दिलाई, इसलिए उसने यह वाक्य कहा। दिल में चुभन हुई। पर जान लीजिए कि वह अभी अपनी भावनाएँ ठीक से नहीं कह पाता, असल में वह कहना चाहता है, ‘मैं निराश हूँ।’ बस गले लगाइए और उसकी भावना को स्वीकार कीजिए।', title_id = 'Ia bilang ''Mama jahat!''? 💔', body_id = 'Ia mengucapkan kalimat itu karena Anda tidak membelikan mobil-mobilan yang ia mau. Hati Anda terasa perih. Tapi ketahuilah, ia belum bisa mengungkapkan perasaannya dengan tepat, sebenarnya ia ingin berkata ''aku kecewa''. Peluk saja ia dan terima perasaannya.', title_ja = '「ママ、いじわる！」と言われた？ 💔', body_ja = 'ほしかった車を買ってあげなかったから、その言葉を口にした。胸がちくりと痛みますね。でも知っておいて。まだ気持ちを正しく表せないだけで、本当は「がっかりしたの」と言いたいんです。ただ抱きしめて、気持ちを受けとめてあげましょう。', title_ko = '''엄마 나빠!''라고 했나요? 💔', body_ko = '원하는 자동차를 안 사 줬다고 그런 말을 했나요? 가슴이 철렁했죠. 하지만 아이는 아직 감정을 제대로 표현하지 못해요, 사실은 ''나 실망했어''라고 말하고 싶은 거예요. 그냥 안아 주고 그 마음을 받아 주세요.', title_nl = 'Zei hij ''Jij bent een slechte mama!''? 💔', body_nl = 'Hij zei die zin omdat je de auto die hij wilde niet kocht. Je hart kromp ineen. Maar weet dat hij zijn gevoelens nog niet goed kan uitdrukken, eigenlijk wil hij zeggen: ''Ik ben teleurgesteld.'' Knuffel hem gewoon en erken zijn gevoel.', title_pl = 'Powiedział „Jesteś złą mamą!”? 💔', body_pl = 'Powiedział to, bo nie kupiłaś mu wymarzonego samochodzika. Zakłuło cię w sercu. Ale wiedz, że nie umie jeszcze właściwie wyrazić uczuć, tak naprawdę chce powiedzieć „Jestem rozczarowany”. Po prostu go przytul i przyjmij jego uczucia.', title_pt = 'Disse "És uma má mãe!"? 💔', body_pt = 'Disse esta frase porque não lhe comprou o carro que queria. Doeu-lhe no coração. Mas saiba que ainda não consegue exprimir bem as emoções: na verdade quer dizer "fiquei desiludido". Abrace-o simplesmente e aceite o que sente.', title_sv = 'Sa barnet ”Du är en dålig mamma!”? 💔', body_sv = 'Barnet sa så för att du inte köpte bilen det ville ha. Det högg till i hjärtat. Men vet att barnet ännu inte kan uttrycka sina känslor rätt, egentligen vill det säga ”jag blev besviken”. Krama bara barnet och ta emot känslan.', title_vi = 'Bé nói "Mẹ là mẹ xấu!"? 💔', body_vi = 'Bé nói câu ấy vì mẹ không mua chiếc ô tô bé muốn. Tim mẹ nhói đau. Nhưng hãy biết rằng bé chưa thể diễn đạt cảm xúc đúng cách, thật ra bé muốn nói "Con thất vọng lắm". Chỉ cần ôm bé và đón nhận cảm xúc của bé.', title_zh = '说你“是个坏妈妈”？💔', body_zh = '就因为你没给买想要的小汽车，宝宝说出了这句话。你的心一阵刺痛。但要知道，宝宝还不会正确地表达情绪，其实是想说“我很失望”。抱抱宝宝，接纳这份感受就好。' WHERE id = '3d278e8d-5fc9-46fa-ad40-bcef90b99e90' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sentido de la moda 👗', body_es = 'Quiere ir al parque con sandalias de verano encima de los calcetines de invierno. Insiste y no se las quita. Olvida las normas sociales. Para no romper su creatividad, deja que pase el día con ese aspecto tan distinto y cómico: está aprendiendo libertad.', title_fr = 'Le sens de la mode 👗', body_fr = 'Il veut aller au parc avec des sandales d''été par-dessus ses chaussettes d''hiver. Il insiste et refuse de les enlever. Oubliez les normes sociales. Pour ne pas briser sa créativité, laissez-le passer la journée avec ce look original et comique : il apprend la liberté.', title_hi = 'फ़ैशन की समझ 👗', body_hi = 'सर्दियों के मोज़ों के ऊपर गर्मियों की सैंडल पहनकर पार्क जाना चाहता है। ज़िद करता है, उतारता नहीं। लोगों के कायदे भूल जाइए। उसकी रचनात्मकता न टूटे, इसलिए उसे आज का दिन इसी अनोखे, मज़ेदार रूप में बिताने दीजिए, वह आज़ादी सीख रहा है।', title_id = 'Selera busana 👗', body_id = 'Ia ingin ke taman memakai sandal musim panas di atas kaus kaki musim dingin. Ia ngotot dan tidak mau melepasnya. Lupakan norma sosial. Agar kreativitasnya tidak patah, biarkan ia melewati hari dengan penampilan unik dan lucu itu, ia sedang belajar tentang kebebasan.', title_ja = 'ファッションセンス 👗', body_ja = '冬の靴下の上に夏のサンダルをはいて公園へ行きたがり、ゆずらず、脱がない。世間の常識は忘れましょう。創造力をくじかないように、そのちょっと変わったおもしろい格好で一日を過ごさせてあげて。自由を学んでいるんです。', title_ko = '패션 감각 👗', body_ko = '겨울 양말 위에 여름 샌들을 신고 공원에 가겠다며 절대 벗지 않나요? 사회적 기준은 잊으세요. 창의력을 꺾지 않도록 그 독특하고 웃긴 차림으로 하루를 보내게 해 주세요, 자유로움을 배우는 중이에요.', title_nl = 'Gevoel voor mode 👗', body_nl = 'Hij wil met zomersandalen over zijn wintersokken naar het park. Hij houdt vol en doet ze niet uit. Vergeet wat ''hoort''. Laat hem de dag in die aparte, grappige look doorbrengen, zodat je zijn creativiteit niet breekt: hij leert vrijheid.', title_pl = 'Wyczucie mody 👗', body_pl = 'Chce iść do parku w letnich sandałach założonych na zimowe skarpetki. Upiera się, nie zdejmuje. Zapomnij o normach społecznych. Żeby nie łamać jego kreatywności, niech spędzi dzień w tym nietypowym, zabawnym wydaniu, uczy się swobody.', title_pt = 'Sentido de moda 👗', body_pt = 'Quer ir ao parque com sandálias de verão por cima das meias de inverno. Insiste e não as tira. Esqueça as normas sociais. Para não quebrar a criatividade dele, deixe-o passar o dia com esse visual diferente e cómico: está a aprender a liberdade.', title_sv = 'Modekänsla 👗', body_sv = 'Barnet vill gå till parken i sommarsandaler utanpå vintersockorna. Barnet insisterar och tar inte av dem. Glöm samhällets normer. För att inte knäcka barnets kreativitet, låt barnet tillbringa dagen i den annorlunda, roliga looken, barnet lär sig frihet.', title_vi = 'Gu thời trang 👗', body_vi = 'Bé muốn đi dép quai hậu mùa hè bên ngoài tất mùa đông để ra công viên. Bé nhất quyết không cởi ra. Hãy quên chuẩn mực xã hội đi. Để không bẻ gãy sự sáng tạo của bé, cứ để bé trải qua ngày với vẻ ngoài khác lạ, hài hước ấy, bé đang học về sự tự do.', title_zh = '时尚观 👗', body_zh = '想在冬天的袜子外面穿上夏天的凉鞋去公园。坚持不肯脱。忘掉那些社会规范吧。为了不挫伤宝宝的创造力，就让宝宝带着这副与众不同又搞笑的样子过一天吧，宝宝正在学习自由。' WHERE id = 'd54e4e25-89e6-430d-b9c4-307312ee2246' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El rival del espejo 🪞', body_es = 'Delante del espejo frunce el ceño y pone caras enfadadas y raras. Está comprobando cómo se ven las emociones en su cara. Disfruta observando sin hacer ruido el ensayo de este pequeño actor de teatro.', title_fr = 'Le rival dans le miroir 🪞', body_fr = 'Devant le miroir, il fronce les sourcils et fait des grimaces fâchées ou bizarres. Il teste à quoi ressemblent les émotions sur son visage. Observez sans bruit, avec plaisir, la répétition de ce petit acteur de théâtre.', title_hi = 'आईने में प्रतिद्वंद्वी 🪞', body_hi = 'आईने के सामने खड़े होकर खुद ही भौंहें चढ़ाता है, गुस्से वाले और अजीब चेहरे बनाता है। वह परख रहा है कि भावनाएँ चेहरे पर कैसी दिखती हैं। बिना आवाज़ किए दूर से इस नन्हे थिएटर कलाकार की रिहर्सल का मज़ा लीजिए।', title_id = 'Saingan di cermin 🪞', body_id = 'Ia berdiri di depan cermin, mengerutkan alis dan membuat ekspresi marah dan aneh pada dirinya sendiri. Ia sedang menguji bagaimana emosi terlihat di wajahnya. Saksikan latihan aktor teater mini ini dengan senang hati dari jauh tanpa bersuara.', title_ja = '鏡の中のライバル 🪞', body_ja = '鏡の前に立って、ひとりで眉をしかめたり、怒った顔やへんな顔をしたりしている。気持ちが顔にどう表れるかを試しているんです。音を立てずに、この小さな舞台俳優の練習を楽しく見守りましょう。', title_ko = '거울 속 라이벌 🪞', body_ko = '거울 앞에 서서 혼자 눈살을 찌푸리고 화난 표정, 이상한 표정을 짓나요? 감정이 얼굴에 어떻게 보이는지 시험하는 중이에요. 옆에서 소리 내지 말고 이 작은 연극배우의 연습을 즐겁게 지켜보세요.', title_nl = 'De rivaal in de spiegel 🪞', body_nl = 'Hij staat voor de spiegel en fronst zijn wenkbrauwen, trekt boze en rare gezichten. Hij test hoe emoties eruitzien op zijn gezicht. Geniet zonder geluid te maken van een afstand van de repetitie van deze kleine toneelspeler.', title_pl = 'Rywal w lustrze 🪞', body_pl = 'Stoi przed lustrem, marszczy brwi i robi do siebie złe i dziwne miny. Sprawdza, jak emocje wyglądają na jego twarzy. Bezgłośnie, z boku, z przyjemnością obserwuj próbę tego miniaturowego aktora teatralnego.', title_pt = 'O rival no espelho 🪞', body_pt = 'Põe-se em frente ao espelho a franzir a testa e a fazer caras zangadas e estranhas para si próprio. Está a testar como as emoções aparecem no rosto. Observe com gosto, à distância e sem fazer barulho, o ensaio deste pequeno ator de teatro.', title_sv = 'Rivalen i spegeln 🪞', body_sv = 'Barnet står framför spegeln och rynkar pannan, gör arga och konstiga miner. Barnet testar hur känslorna syns i ansiktet. Titta njutningsfullt och tyst från sidan på den lilla teaterskådespelarens repetition.', title_vi = 'Đối thủ trong gương 🪞', body_vi = 'Bé đứng trước gương, tự nhíu mày, làm những biểu cảm giận dữ và kỳ quặc. Bé đang thử xem cảm xúc hiện lên trên khuôn mặt mình ra sao. Hãy lặng lẽ, thích thú theo dõi buổi tập của "diễn viên kịch" tí hon này từ xa.', title_zh = '镜子里的对手 🪞', body_zh = '站在镜子前，对着自己皱眉，做出生气又奇怪的表情。宝宝在测试情绪在脸上是什么样子。在一旁别出声，好好欣赏这位迷你剧场演员的排练吧。' WHERE id = '9fab66ef-18f3-4cdb-8e01-0a4f9485cffe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de aislamiento de mamá 🚪', body_es = 'El ruido te taladra el cerebro y te dan ganas de gritar por todo. Déjale en un lugar seguro, métete en el baño y cierra la puerta. Abre el Diario de ánimo. Escribe ahí libremente todo tu agotamiento. Esta breve terapia te reiniciará.', title_fr = 'L''heure d''isolement de maman 🚪', body_fr = 'Le bruit vous transperce le cerveau, vous avez envie de crier sur tout. Mettez-le dans un endroit sûr, allez aux toilettes et fermez la porte. Ouvrez le Journal d''humeur. Écrivez-y librement tout votre épuisement. Cette courte thérapie vous remettra à zéro.', title_hi = 'माँ के लिए अकेले रहने का समय 🚪', body_hi = 'शोर दिमाग में चुभ रहा है, हर बात पर चिल्लाने का मन है। उसे किसी सुरक्षित जगह पर रखिए, बाथरूम में जाकर दरवाज़ा बंद कीजिए। मूड डायरी खोलिए। अपनी सारी थकान खुलकर वहाँ लिखिए। यह छोटी थेरेपी आपको रीसेट कर देगी।', title_id = 'Waktu menyendiri untuk Ibu 🚪', body_id = 'Kebisingan menembus otak Anda, Anda ingin berteriak pada segala hal. Letakkan ia di tempat yang aman, masuk ke toilet, dan tutup pintunya. Buka Buku Harian Suasana Hati. Tuliskan semua rasa lelah Anda di sana dengan bebas. Terapi singkat ini akan me-reset Anda.', title_ja = 'ママのひとり時間 🚪', body_ja = '騒がしさが頭に突きささり、何にでも叫びたくなる。子どもを安全な場所に置いてトイレに入り、ドアを閉めましょう。「気分日記」を開いて、疲れきった気持ちを全部自由に書きだして。この短いセラピーが、あなたをリセットしてくれます。', title_ko = '엄마를 위한 혼자만의 시간 🚪', body_ko = '소음이 머리를 뚫고 모든 것에 소리치고 싶나요? 아이를 안전한 곳에 두고 화장실에 들어가 문을 닫으세요. 기분 일기를 열고 지친 마음을 자유롭게 적어 보세요. 이 짧은 치료가 엄마를 리셋해 줄 거예요.', title_nl = 'Isolatie-uurtje voor mama 🚪', body_nl = 'Het lawaai boort door je hoofd en je wilt tegen alles schreeuwen. Zet hem op een veilige plek, ga naar de wc en doe de deur dicht. Open je Stemmingsdagboek. Schrijf daar vrijuit al je uitputting op. Deze korte therapie zet je weer op reset.', title_pl = 'Godzina odosobnienia dla mamy 🚪', body_pl = 'Hałas świdruje ci w głowie, chce ci się krzyczeć na wszystko. Zostaw go w bezpiecznym miejscu, wejdź do toalety i zamknij drzwi. Otwórz Dziennik nastroju. Wypisz tam swobodnie całe swoje wyczerpanie. Ta krótka terapia cię zresetuje.', title_pt = 'Hora de isolamento para a mãe 🚪', body_pt = 'O barulho fura-lhe o cérebro e apetece-lhe gritar com tudo. Ponha-o num sítio seguro, entre na casa de banho e feche a porta. Abra o Diário de Humor. Escreva lá à vontade todo o seu esgotamento. Esta curta terapia vai fazer-lhe um reset.', title_sv = 'Isoleringsstund för mamma 🚪', body_sv = 'Oljudet borrar sig in i hjärnan och du vill skrika åt allt. Lägg barnet på ett säkert ställe, gå in på toaletten och stäng dörren. Öppna Humördagboken. Skriv fritt ner all din utmattning där. Den här korta terapin återställer dig.', title_vi = 'Giờ ở một mình của mẹ 🚪', body_vi = 'Tiếng ồn như khoan vào đầu, mẹ muốn hét lên với mọi thứ. Hãy đặt bé ở chỗ an toàn, vào nhà vệ sinh và đóng cửa lại. Mở Nhật ký tâm trạng. Viết thoải mái mọi kiệt sức của mình vào đó. Liệu pháp ngắn ngủi này sẽ giúp mẹ "khởi động lại".', title_zh = '妈妈的独处时间 🚪', body_zh = '噪音快把脑袋钻穿了，你看什么都想吼。把宝宝放在安全的地方，走进卫生间关上门。打开心情日记，把所有的疲惫都自由地写进去。这短短的疗愈会帮你“重启”。' WHERE id = 'b8be3052-4ca5-4460-8506-d2c5926555b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con la oscuridad 🐰', body_es = 'Con la excusa de que le da miedo la oscuridad, se escapa de la cama. Apaga todas las luces de la habitación, enciende una linterna y haz con las manos sombras de pájaros y perros en la pared. La oscuridad que le asusta se convertirá en segundos en un teatro.', title_fr = 'Se réconcilier avec le noir 🐰', body_fr = 'Il prétexte avoir peur du noir pour s''échapper du lit. Éteignez toutes les lumières de la chambre, allumez une lampe de poche et créez avec vos mains des ombres d''oiseau et de chien sur le mur. En quelques secondes, le noir qui lui faisait peur deviendra un théâtre.', title_hi = 'अँधेरे से दोस्ती 🐰', body_hi = 'अँधेरे से डर का बहाना बनाकर बिस्तर से भागता है। कमरे की सारी लाइटें बंद कीजिए, टॉर्च जलाइए और दीवार पर हाथों से चिड़िया, कुत्ते की परछाइयाँ बनाइए। जिस अँधेरे से वह डरता है, वह सेकंडों में उसके लिए थिएटर बन जाएगा।', title_id = 'Berdamai dengan gelap 🐰', body_id = 'Ia menjadikan takut gelap sebagai alasan untuk kabur dari tempat tidur. Matikan semua lampu kamar, nyalakan senter, dan buat bayangan burung dan anjing di dinding dengan tangan Anda. Dalam hitungan detik, gelap yang ia takuti akan berubah menjadi teater.', title_ja = '暗やみと仲直り 🐰', body_ja = '暗いのが怖いと言いわけしてベッドから逃げだす。部屋の明かりを全部消して懐中電灯をつけ、壁に手で鳥や犬の影絵をつくりましょう。怖がっていた暗やみが、あっという間に劇場に変わります。', title_ko = '어둠과 화해하기 🐰', body_ko = '어둠이 무섭다는 핑계로 침대에서 도망치나요? 방의 불을 모두 끄고 손전등을 켜서 손으로 벽에 새와 강아지 그림자를 만들어 보세요. 무서웠던 어둠이 몇 초 만에 극장으로 바뀔 거예요.', title_nl = 'Vrede sluiten met het donker 🐰', body_nl = 'Hij gebruikt zijn angst voor het donker als smoes om uit bed te gaan. Doe alle lichten in de kamer uit, zet een zaklamp aan en maak met je handen schaduwen van vogels en honden op de muur. Het donker waar hij bang voor was, wordt binnen een paar seconden een theater.', title_pl = 'Pogodzić się z ciemnością 🐰', body_pl = 'Wymawia się strachem przed ciemnością i ucieka z łóżka. Zgaś wszystkie światła w pokoju, włącz latarkę i zrób dłońmi na ścianie cienie ptaka i pieska. Ciemność, której się bał, w kilka sekund zmieni się dla niego w teatr.', title_pt = 'Fazer as pazes com o escuro 🐰', body_pt = 'Usa o medo do escuro como desculpa para fugir da cama. Apague todas as luzes do quarto, acenda a lanterna e faça com as mãos sombras de pássaros e cães na parede. Em segundos, o escuro de que tem medo vai transformar-se num teatro.', title_sv = 'Bli vän med mörkret 🐰', body_sv = 'Barnet skyller på att det är mörkrädd och springer ur sängen. Släck alla lampor i rummet, tänd ficklampan och forma fåglar och hundar som skuggor på väggen med händerna. Mörkret som barnet är rädd för blir på några sekunder en teater.', title_vi = 'Làm hòa với bóng tối 🐰', body_vi = 'Bé lấy cớ sợ bóng tối để trốn khỏi giường. Hãy tắt hết đèn trong phòng, bật đèn pin và dùng tay tạo bóng chim, bóng chó trên tường. Bóng tối bé sợ sẽ biến thành nhà hát chỉ trong vài giây.', title_zh = '和黑暗和解 🐰', body_zh = '拿怕黑当借口从床上溜走。关掉房间所有的灯，打开手电筒，用手在墙上做出小鸟、小狗的影子。宝宝害怕的黑暗，几秒钟就会变成一座剧场。' WHERE id = 'cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica para explorar el tiempo ⛅', body_es = 'Fuera hace sol, pero también sopla viento. No te fíes solo de lo que ves por la ventana. Deja que la herramienta Tiempo y ropa te diga al instante la temperatura que no se ve y el conjunto por capas adecuado, y sal de paseo con salud sin perder tiempo dudando en la puerta.', title_fr = 'La tactique de l''éclaireur météo ⛅', body_fr = 'Dehors, il y a du soleil, mais aussi du vent. Ne vous fiez pas à ce que vous voyez par la fenêtre. Laissez Météo et tenue vous indiquer aussitôt la température invisible et la bonne tenue en couches, et partez en promenade en bonne santé, sans perdre de temps à hésiter sur le pas de la porte.', title_hi = 'मौसम की जासूसी वाली तरकीब ⛅', body_hi = 'बाहर धूप है, पर हवा भी चल रही है। खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े टूल आपको न दिखने वाला तापमान और सही परतों वाले कपड़े तुरंत बताए, ताकि दरवाज़े पर दुविधा में समय गँवाए बिना, सेहत का ख्याल रखते हुए सैर पर निकल सकें।', title_id = 'Taktik mengintai cuaca ⛅', body_id = 'Di luar ada matahari, tapi angin juga bertiup. Jangan tertipu hanya dengan melihat dari jendela. Biarkan Cuaca dan Pakaian langsung memberi tahu suhu yang tak terlihat dan setelan berlapis yang tepat, lalu pergilah jalan-jalan dengan sehat tanpa membuang waktu ragu-ragu di depan pintu.', title_ja = '天気を調べる作戦 ⛅', body_ja = '外は晴れているけれど、風も吹いている。窓の外の様子にだまされないで。「天気と服装」に、見えない気温とぴったりの重ね着コーデをすぐに教えてもらいましょう。玄関で迷って時間をむだにせず、元気にお散歩へ出かけましょう。', title_ko = '날씨 정찰 작전 ⛅', body_ko = '해는 났는데 바람도 부나요? 창밖만 보고 속지 마세요. 보이지 않는 기온과 알맞은 겹쳐 입기를 날씨와 옷차림 도구가 바로 알려 줄 거예요. 현관에서 망설이며 시간 보내지 말고 건강하게 산책을 나가세요.', title_nl = 'Weerverkenningstactiek ⛅', body_nl = 'Buiten schijnt de zon, maar het waait ook. Laat je niet misleiden door een blik uit het raam. Laat de tool Weer en kleding je meteen de temperatuur die je niet ziet en de juiste laagjesoutfit vertellen, en ga gezond wandelen zonder twijfelend tijd te verliezen bij de deur.', title_pl = 'Taktyka pogodowego zwiadu ⛅', body_pl = 'Na dworze świeci słońce, ale wieje też wiatr. Nie daj się zwieść widokowi za oknem. Niech narzędzie Pogoda i ubiór od razu poda ci temperaturę, której nie widać, i właściwy zestaw na cebulkę. Wyjdźcie na zdrowy spacer, nie tracąc czasu na wahanie w progu.', title_pt = 'Tática de exploração do tempo ⛅', body_pt = 'Lá fora há sol, mas também vento. Não se deixe enganar pelo que vê da janela. Deixe que a ferramenta Tempo e Roupa lhe diga logo a temperatura que não se vê e a combinação certa por camadas, e saia para um passeio saudável sem perder tempo indecisa à porta.', title_sv = 'Spaningstaktik för vädret ⛅', body_sv = 'Solen skiner ute, men det blåser också. Låt dig inte luras av att titta ut genom fönstret. Låt verktyget Väder och kläder direkt visa den temperatur du inte ser och rätt klädsel i lager, så kommer ni ut på en hälsosam promenad utan att stå villrådiga och förlora tid i dörren.', title_vi = 'Chiến thuật trinh sát thời tiết ⛅', body_vi = 'Ngoài trời có nắng nhưng cũng có gió. Đừng để bị đánh lừa khi chỉ nhìn qua cửa sổ. Hãy để Thời tiết và trang phục cho mẹ biết ngay nhiệt độ mà mắt không thấy được và cách phối nhiều lớp phù hợp, để ra ngoài đi dạo khỏe mạnh mà không mất thời gian lưỡng lự ở cửa.', title_zh = '侦察天气的战术 ⛅', body_zh = '外面有太阳，但也刮着风。别只看窗外就被骗了。让天气与穿衣工具马上告诉你看不见的温度和正确的分层搭配，别在门口犹豫着浪费时间，健健康康地出门散步吧。' WHERE id = '217250d8-e2a0-42ca-ac61-232ced171632' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No es culpa mía! 🤷‍♂️', body_es = 'Ha tirado el agua al suelo a propósito, pero le echa la culpa a su juguete: «Me ha empujado». No es una mentira, es el mecanismo de protección del cerebro infantil. No discutas: engaña a su cerebro diciendo «Vamos a enseñarle también a ese juguete cómo se limpia».', title_fr = 'C''est pas ma faute ! 🤷‍♂️', body_fr = 'Il a renversé l''eau exprès, mais a rejeté la faute sur son jouet : « C''est lui qui m''a poussé ». Ce n''est pas un mensonge, c''est un mécanisme de protection du cerveau de l''enfant. Ne vous entêtez pas, déjouez-le gentiment : « Viens, on va apprendre à ce jouet comment on nettoie. »', title_hi = 'यह मेरी गलती नहीं है! 🤷‍♂️', body_hi = 'जानबूझकर पानी गिराया, पर दोष अपने खिलौने पर डालकर बोला, ‘उसने धक्का दिया।’ यह झूठ नहीं, बच्चे के दिमाग का बचाव तंत्र है। ज़िद मत कीजिए, ‘आओ, उस खिलौने को भी सिखाएँ कि सफ़ाई कैसे करते हैं’ कहकर उसके दिमाग को चकमा दीजिए।', title_id = 'Ini bukan salahku! 🤷‍♂️', body_id = 'Ia sengaja menumpahkan air ke lantai, tapi menyalahkan mainannya: ''Dia yang dorong''. Ini bukan bohong, ini mekanisme perlindungan otak anak. Jangan berdebat, kelabui otaknya dengan berkata ''Ayo kita ajari mainan itu juga cara membersihkannya''.', title_ja = 'ぼくのせいじゃない！ 🤷‍♂️', body_ja = 'わざとお水を床にこぼしたのに、おもちゃのせいにして「この子が押した」と言う。これはうそではなく、子どもの脳の防衛機能です。言い合わずに「じゃあ、このおもちゃにもお掃除のしかたを教えてあげよう」と言って、うまく誘導しましょう。', title_ko = '내 잘못 아니야! 🤷‍♂️', body_ko = '일부러 물을 쏟고는 ''얘가 밀었어''라며 장난감 탓을 하나요? 거짓말이 아니라 아이 뇌의 방어 기제예요. 고집 싸움 말고 ''그 장난감한테도 닦는 법을 가르쳐 주자''라며 슬쩍 마음을 돌려 보세요.', title_nl = 'Het is niet mijn schuld! 🤷‍♂️', body_nl = 'Hij gooide expres water op de grond, maar gaf zijn knuffel de schuld: ''Hij duwde.'' Dat is geen liegen, maar een beschermingsmechanisme van het kinderbrein. Ga er niet tegenin, maar fop zijn brein: ''Kom, we leren die knuffel ook hoe je opruimt.''', title_pl = 'To nie moja wina! 🤷‍♂️', body_pl = 'Celowo wylał wodę na podłogę, ale zwalił winę na zabawkę: „To ona mnie popchnęła”. To nie kłamstwo, tylko mechanizm obronny dziecięcego mózgu. Nie kłóć się, przechytrz go: „Chodź, nauczmy tę zabawkę, jak się sprząta”.', title_pt = 'A culpa não é minha! 🤷‍♂️', body_pt = 'Entornou a água no chão de propósito, mas culpou o brinquedo: "Foi ele que empurrou". Não é mentira, é o mecanismo de proteção do cérebro infantil. Não teime: diga "Vamos ensinar também o brinquedo a limpar" e engane-lhe o cérebro.', title_sv = 'Det är inte mitt fel! 🤷‍♂️', body_sv = 'Barnet hällde ut vattnet på golvet med flit men skyllde på sin leksak: ”Den knuffade.” Det är ingen lögn, det är barnhjärnans skyddsmekanism. Bråka inte, säg ”Kom så lär vi leksaken också hur man torkar upp” och lura hjärnan.', title_vi = 'Không phải lỗi của con! 🤷‍♂️', body_vi = 'Bé cố tình đổ nước ra sàn, nhưng lại đổ lỗi cho đồ chơi: "Nó đẩy con". Đây không phải nói dối, mà là cơ chế tự vệ của não bộ trẻ. Đừng giằng co, hãy "đánh lừa" não bé: "Mình cùng dạy món đồ chơi đó cách lau dọn nhé".', title_zh = '不是我的错！🤷‍♂️', body_zh = '故意把水洒在地上，却把责任推给玩具：“是它推的。”这不是撒谎，而是孩子大脑的自我保护机制。别较劲，说一句“我们也来教教这个玩具怎么擦干净吧”，巧妙地引导宝宝。' WHERE id = '4a193a83-4450-45ef-8b03-b9487c79d984' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta oceánica en la bañera 🌊', body_es = 'El baño ya no es higiene, es un juego de crear un pequeño tsunami. Deja que el agua salpique. Ese efecto imán, místico y que absorbe energía, del agua se llevará por el desagüe toda la energía tozuda y negativa que ha acumulado durante el día.', title_fr = 'Tempête océanique dans la baignoire 🌊', body_fr = 'Le bain n''est plus une question de propreté, c''est un jeu pour créer un petit tsunami. Laissez l''eau éclabousser. L''effet magnétique, presque magique, de l''eau qui absorbe l''énergie emportera dans le siphon toute l''énergie têtue et négative accumulée dans la journée.', title_hi = 'बाथटब में समुद्री तूफ़ान 🌊', body_hi = 'बाथटब में नहाना अब सफ़ाई नहीं, एक छोटी सुनामी बनाने का खेल है। पानी को चारों ओर छिटकने दीजिए। पानी का वह रहस्यमयी, ऊर्जा सोखने वाला चुंबकीय असर दिनभर में उसमें जमा ज़िद्दी, नकारात्मक ऊर्जा को धोकर बहा ले जाएगा।', title_id = 'Badai samudra di bak mandi 🌊', body_id = 'Mandi di bak kini bukan soal bersih-bersih, tapi permainan membuat tsunami kecil. Biarkan air memercik ke mana-mana. Efek magnet air yang ajaib dan menyerap energi akan membasuh energi negatif dan sikap keras kepala yang menumpuk sepanjang hari, lalu membawanya ke saluran pembuangan.', title_ja = 'お風呂の海の嵐 🌊', body_ja = 'お風呂はもうきれいにするためではなく、小さな津波をつくる遊びです。水しぶきが飛んでもいいんです。お湯のふしぎで、エネルギーを吸いとる磁石のような力が、一日たまったがんこでネガティブなエネルギーを洗い流して、排水口へ運んでくれます。', title_ko = '욕조 속 바다 폭풍 🌊', body_ko = '이제 목욕은 씻는 시간이 아니라 작은 쓰나미 만들기 놀이예요. 물이 사방으로 튀어도 괜찮아요. 에너지를 흡수하는 물의 신비한 힘이 하루 동안 쌓인 고집과 부정적인 에너지를 씻어 배수구로 흘려보낼 거예요.', title_nl = 'Oceaanstorm in bad 🌊', body_nl = 'In bad gaan is geen schoonmaakbeurt meer, maar een spel met een kleine tsunami. Laat het water maar spetteren. Het mystieke, energie opnemende magnetische effect van het water spoelt alle koppige, negatieve energie van de dag weg, het putje in.', title_pl = 'Sztorm na oceanie w wannie 🌊', body_pl = 'Kąpiel w wannie to już nie mycie, tylko zabawa w małe tsunami. Niech woda chlapie dookoła. Tajemniczy, pochłaniający energię magnetyczny efekt wody zmyje cały uparty, negatywny ładunek nagromadzony w ciągu dnia i spłynie z nim do kanalizacji.', title_pt = 'Tempestade oceânica na banheira 🌊', body_pt = 'O banho já não é limpeza, é um jogo de fazer pequenos tsunamis. Deixe a água salpicar à volta. O efeito magnético, místico e que absorve energia da água vai lavar e levar pelo ralo a energia teimosa e negativa acumulada durante o dia.', title_sv = 'Havsstorm i badkaret 🌊', body_sv = 'Badet handlar inte längre om renlighet, det är en lek med att skapa en liten tsunami. Låt vattnet stänka. Vattnets mystiska, energiupptagande magnetiska effekt sköljer bort den envisa, negativa energi som samlats under dagen, rakt ner i avloppet.', title_vi = 'Bão đại dương trong bồn tắm 🌊', body_vi = 'Tắm không còn là chuyện vệ sinh nữa, mà là trò chơi tạo ra một trận sóng thần nhỏ. Cứ để nước bắn tung tóe. Sức hút huyền bí, hút đi năng lượng của nước sẽ cuốn trôi mọi năng lượng bướng bỉnh, tiêu cực bé tích tụ suốt cả ngày xuống cống.', title_zh = '浴缸里的海上风暴 🌊', body_zh = '在浴缸里洗澡已经不是为了干净，而是一场掀起小海啸的游戏。让水花四溅吧。水那种神奇的、吸走能量的磁力效果，会把宝宝一整天积攒的倔强和负面能量都冲进下水道。' WHERE id = 'c170e0aa-73e3-4e36-8c66-e8887556d5ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La llamada del cuerpo 🩸', body_es = 'No te rindas a la irritación y el cansancio sin motivo. Mira el Calendario menstrual: tu cuerpo te está mandando señales. En lugar de culparte, descansa con un tentempié rico en magnesio de Recetas saludables.', title_fr = 'Le cri du corps 🩸', body_fr = 'Ne cédez pas à l''irritabilité et à la fatigue sans raison. Regardez le Suivi des règles, votre corps vous envoie des signaux. Au lieu de vous blâmer, reposez-vous avec une collation riche en magnésium des Recettes saines.', title_hi = 'शरीर की पुकार 🩸', body_hi = 'बिना वजह की चिढ़ और थकान के आगे हार मत मानिए। पीरियड ट्रैकर देखिए, आपका शरीर संकेत दे रहा है। खुद को दोष देने के बजाय सेहतमंद रेसिपी से मैग्नीशियम वाले स्नैक के साथ आराम कीजिए।', title_id = 'Jeritan tubuh 🩸', body_id = 'Jangan menyerah pada rasa kesal dan lelah tanpa sebab. Lihat Pelacak Menstruasi, tubuh Anda sedang memberi sinyal. Daripada menyalahkan diri, beristirahatlah dengan camilan kaya magnesium dari Resep Sehat.', title_ja = '体のSOS 🩸', body_ja = '理由のないイライラや疲れに負けないで。「生理トラッカー」を見てみましょう。体がサインを出しています。自分を責める代わりに、「ヘルシーレシピ」のマグネシウムたっぷりのおやつで休みましょう。', title_ko = '몸이 보내는 외침 🩸', body_ko = '이유 없는 짜증과 피로에 지지 마세요. 생리 주기 기록을 확인해 보세요, 몸이 신호를 보내고 있어요. 자책하는 대신 건강한 레시피의 마그네슘이 든 간식으로 쉬어 가세요.', title_nl = 'De roep van je lichaam 🩸', body_nl = 'Geef niet toe aan onverklaarbare prikkelbaarheid en vermoeidheid. Kijk in je Cyclustracker, je lichaam geeft signalen. Veroordeel jezelf niet, maar ontspan met een magnesiumrijk tussendoortje uit Gezonde recepten.', title_pl = 'Wołanie ciała 🩸', body_pl = 'Nie poddawaj się drażliwości i zmęczeniu bez powodu. Zajrzyj do Kalendarza miesiączkowego, twoje ciało wysyła sygnały. Zamiast się obwiniać, odpocznij z przekąską bogatą w magnez ze Zdrowych przepisów.', title_pt = 'O grito do corpo 🩸', body_pt = 'Não se renda à irritação e ao cansaço sem razão. Veja o Registo do Período: o seu corpo está a dar sinais. Em vez de se culpar, descanse com um snack rico em magnésio das Receitas Saudáveis.', title_sv = 'Kroppens rop 🩸', body_sv = 'Ge inte efter för omotiverad irritation och trötthet. Titta i Mensspåraren, kroppen skickar signaler. Istället för att döma dig själv, vila med ett magnesiumrikt mellanmål från Hälsosamma recept.', title_vi = 'Tiếng gọi của cơ thể 🩸', body_vi = 'Đừng đầu hàng sự cáu kỉnh và mệt mỏi không rõ lý do. Hãy xem Theo dõi kỳ kinh, cơ thể mẹ đang gửi tín hiệu. Thay vì tự trách mình, hãy nghỉ ngơi với một món ăn nhẹ giàu magie từ Công thức lành mạnh.', title_zh = '身体的呼唤 🩸', body_zh = '别向莫名的烦躁和疲惫投降。看看经期记录，你的身体在发出信号。与其责怪自己，不如从健康食谱里做一份富含镁的小零食，好好休息。' WHERE id = '28383f04-88e3-44f0-b462-99283a8b08f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filosofía a primera hora 🤔', body_es = '«¿Por qué no se caen los pájaros?», «¿Por qué el árbol se ha vuelto verde?». A primera hora se declara abierto el congreso científico. Si estás cansada de dar explicaciones exactas, devuélvele la pregunta: «¿Tú por qué crees?», y escucha sus respuestas maravillosas e inventadas.', title_fr = 'Philosophie au petit matin 🤔', body_fr = '« Pourquoi les oiseaux ne tombent pas ? », « Pourquoi l''arbre est devenu vert ? » Dès le matin, la conférence scientifique est officiellement ouverte. Si vous êtes fatiguée de donner des explications précises, renvoyez-lui la question : « À ton avis, pourquoi ? » et écoutez ses réponses inventées et merveilleuses.', title_hi = 'सुबह-सुबह दर्शन 🤔', body_hi = '‘पक्षी गिरते क्यों नहीं?’, ‘पेड़ हरा क्यों हो गया?’ तड़के ही वैज्ञानिक सम्मेलन खुला घोषित हो चुका है। अगर सटीक व्याख्या देते-देते थक गई हैं, तो ‘तुम्हें क्या लगता है, क्यों?’ कहकर सवाल उसी को लौटाइए और उसके वे अद्भुत, गढ़े हुए जवाब सुनिए।', title_id = 'Filsafat pagi-pagi 🤔', body_id = '''Kenapa burung tidak jatuh?'', ''Kenapa pohon jadi hijau?'' Pagi-pagi konferensi ilmiah sudah resmi dibuka. Jika Anda lelah memberi penjelasan yang tepat, kembalikan pertanyaannya dengan berkata ''Menurutmu kenapa?'', lalu dengarkan jawaban karangannya yang menakjubkan.', title_ja = '朝から哲学 🤔', body_ja = '「鳥はなんで落ちないの？」「木はなんで緑になったの？」朝早くから科学会議が開幕です。正確な説明に疲れたら、「あなたはどうしてだと思う？」と質問を返して、すてきな作り話の答えを聞いてみましょう。', title_ko = '아침의 철학 🤔', body_ko = '''새는 왜 안 떨어져?'', ''나무는 왜 초록색이 됐어?'' 아침부터 과학 학회가 열렸나요? 정확한 설명에 지쳤다면 ''너는 왜 그런 것 같아?''라고 되물어 보고, 그 놀랍고 엉뚱한 대답을 들어 보세요.', title_nl = 'Filosofie in de vroege ochtend 🤔', body_nl = '''Waarom vallen vogels niet?'', ''Waarom is de boom groen geworden?'' Al vroeg in de ochtend is het wetenschappelijk congres geopend. Ben je het moe om precieze uitleg te geven, stel de vraag dan terug: ''Waarom denk jij?'' en luister naar zijn prachtige, verzonnen antwoorden.', title_pl = 'Poranna filozofia 🤔', body_pl = '„Dlaczego ptaki nie spadają?”, „Dlaczego drzewo zrobiło się zielone?” O świcie oficjalnie otwarto konferencję naukową. Jeśli masz dość dokładnych wyjaśnień, odwróć pytanie: „A jak myślisz, dlaczego?” i posłuchaj jego cudownych, wymyślonych odpowiedzi.', title_pt = 'Filosofia logo de manhã 🤔', body_pt = '"Porque é que os pássaros não caem?", "Porque é que a árvore ficou verde?" Logo de manhã cedo, está aberta a conferência científica. Se está cansada de dar explicações exatas, devolva-lhe a pergunta, "E tu, porque achas?", e ouça aquelas respostas inventadas e maravilhosas.', title_sv = 'Filosofi tidigt på morgonen 🤔', body_sv = '”Varför ramlar inte fåglarna?”, ”Varför blev trädet grönt?” Tidigt på morgonen har en vetenskaplig konferens förklarats öppnad. Om du är trött på att ge exakta förklaringar, ställ tillbaka frågan: ”Vad tror du?” och lyssna på de underbara, påhittade svaren.', title_vi = 'Triết học buổi sáng 🤔', body_vi = '"Sao chim không rơi xuống?", "Sao cây lại màu xanh?" Hội nghị khoa học đã chính thức khai mạc từ sáng sớm. Nếu mẹ đã mệt vì phải giải thích chính xác, hãy hỏi ngược lại bé: "Con nghĩ vì sao?" và lắng nghe những câu trả lời tưởng tượng tuyệt vời.', title_zh = '一大早的哲学 🤔', body_zh = '“鸟为什么不会掉下来？”“树为什么变绿了？”一大早，科学研讨会就宣布开幕了。如果你已经累得没法给出准确的解释，就把问题抛回去：“你觉得为什么呢？”然后听听那些奇妙的、编出来的答案吧。' WHERE id = '4c7f9f66-bdd5-4db6-8e78-8af325982d85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El acuerdo del temporizador para dormir ⏱️', body_es = 'Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared. Pon un temporizador. Aplica la norma «cuando suena la campanita, todos apagamos las luces» y líbrate con paciencia de esta despedida sin fin, de esta manipulación tan experta.', title_fr = 'L''accord du minuteur pour dormir ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur. Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde éteint la lumière » et échappez avec patience à ces adieux sans fin, à cette manipulation de maître.', title_hi = 'नींद के लिए टाइमर वाला समझौता ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है। टाइमर लगाइए। ‘घंटी बजते ही सब लाइटें बंद कर देते हैं’ का नियम लागू करके इस अंतहीन अलविदा, इस माहिर चाल से धैर्य के साथ बच निकलिए।', title_id = 'Kesepakatan timer untuk tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding. Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua lampu dimatikan'' dan bebaskan diri dengan sabar dari perpisahan tanpa akhir dan manipulasi cerdik ini.', title_ja = '寝かしつけのタイマー約束 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり。タイマーをセットしましょう。「ベルが鳴ったらみんな明かりを消す」のルールで、この終わらないおやすみのあいさつ、見事な作戦から根気よく抜け出して。', title_ko = '잠을 위한 타이머 약속 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 불을 끈다'' 규칙을 정해 이 끝없는 작별 인사, 노련한 작전에서 차분하게 벗어나세요.', title_nl = 'Timerafspraak voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaan alle lichten uit'' in en verlos jezelf geduldig van dit eindeloze afscheid, deze meesterlijke manipulatie.', title_pl = 'Umowa z minutnikiem przed snem ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą. Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy gaszą światło” i cierpliwie uwolnij się od tych niekończących się pożegnań i mistrzowskiej manipulacji.', title_pt = 'O acordo do temporizador para dormir ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede. Programe um temporizador. Aplique a regra "quando a campainha toca, todos apagam as luzes" e livre-se com paciência desta despedida sem fim, desta manipulação de mestre.', title_sv = 'Timeravtal inför sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen. Ställ in en timer. Inför regeln ”när klockan ringer släcker alla” och rädda dig tålmodigt från det ändlösa farvälet och den mästerliga manipulationen.', title_vi = 'Thỏa thuận hẹn giờ đi ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường. Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà tắt đèn" để kiên nhẫn thoát khỏi những lời tạm biệt bất tận, màn "thao túng" bậc thầy này.', title_zh = '和计时器的睡觉约定 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见。设个计时器。立下“铃声一响，大家都关灯”的规矩，耐心地摆脱这没完没了的告别和高明的“操控”吧。' WHERE id = 'ab1d1514-de05-4637-8009-2407cc320f46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis del «¡Lo quiero!» en el súper 🛒', body_es = '¿Grita por unas chuches delante de la caja? No hagas ningún caso a las miradas de «niño malcriado» de alrededor. Con calma, mírale a los ojos, explícale la norma y no cambies de postura. Si no está en tu lista, no se compra.', title_fr = 'La crise du « Je veux » au supermarché 🛒', body_fr = 'Il hurle pour des bonbons devant la caisse ? N''accordez aucune importance aux regards qui disent « enfant mal élevé ». Regardez-le calmement dans les yeux, expliquez la règle et ne changez pas de position. Si ce n''est pas sur votre liste, on ne l''achète pas.', title_hi = 'बाज़ार में ‘मुझे चाहिए’ वाला संकट 🛒', body_hi = 'काउंटर के सामने मिठाई के लिए चिल्लाता है? आसपास वालों की ‘बिगड़ा बच्चा’ वाली नज़रों की बिल्कुल परवाह मत कीजिए। शांति से आँख मिलाकर नियम समझाइए और अपनी बात पर टिकी रहिए। अगर आपकी लिस्ट में नहीं है, तो नहीं खरीदा जाएगा।', title_id = 'Krisis ''Aku mau!'' di supermarket 🛒', body_id = 'Ia berteriak minta permen di depan kasir? Jangan pedulikan sama sekali tatapan ''anak nakal'' dari orang sekitar. Tatap matanya dengan tenang, jelaskan aturannya, dan jangan goyah. Kalau tidak ada di daftar Anda, tidak akan dibeli.', title_ja = 'スーパーで「ほしい！」の大騒ぎ 🛒', body_ja = 'レジの前でお菓子をほしがって叫んでいる？まわりの「悪い子ね」という視線は、まったく気にしないで。落ち着いて目を合わせ、ルールを説明して、態度をくずさないで。リストにないものは、買いません。', title_ko = '마트에서의 ''사 줘'' 위기 🛒', body_ko = '계산대 앞에서 사탕 사 달라고 소리치나요? 주변의 ''버릇없는 아이'' 같은 시선은 절대 신경 쓰지 마세요. 차분히 눈을 맞추고 규칙을 설명하고 흔들리지 마세요. 목록에 없으면 사지 않아요.', title_nl = 'De ''Ik wil!''-crisis in de supermarkt 🛒', body_nl = 'Schreeuwt hij bij de kassa om snoep? Trek je helemaal niets aan van de ''stout kind''-blikken van anderen. Maak rustig oogcontact, leg de regel uit en blijf bij je standpunt. Staat het niet op je lijstje, dan wordt het niet gekocht.', title_pl = 'Kryzys „Chcę!” w sklepie 🛒', body_pl = 'Przy kasie krzyczy o słodycze? Nie przejmuj się wcale spojrzeniami innych, w stylu „co za niegrzeczne dziecko”. Spokojnie nawiąż kontakt wzrokowy, wyjaśnij zasadę i nie zmieniaj postawy. Jeśli tego nie ma na liście, nie kupujemy.', title_pt = 'A crise do "Quero!" no supermercado 🛒', body_pt = 'Grita por doces em frente à caixa? Não ligue nada aos olhares de "criança mal-educada" à volta. Estabeleça contacto visual com calma, explique a regra e não mude de posição. Se não está na sua lista, não se compra.', title_sv = '”Jag vill ha”-krisen i butiken 🛒', body_sv = 'Skriker barnet efter godis framför kassan? Bry dig inte alls om blickarna runt omkring som säger ”stygg unge”. Ta lugnt ögonkontakt, förklara regeln och stå fast. Om det inte står på listan blir det inget köp.', title_vi = 'Khủng hoảng "Con muốn!" ở siêu thị 🛒', body_vi = 'Bé hét lên đòi đồ ngọt trước quầy thanh toán? Tuyệt đối đừng bận tâm đến những ánh mắt "đứa trẻ hư" xung quanh. Hãy bình tĩnh nhìn vào mắt bé, giải thích quy tắc và giữ vững lập trường. Không có trong danh sách thì không mua.', title_zh = '超市里的“我要”危机 🛒', body_zh = '在收银台前为了糖果大喊大叫？完全不用在意旁人“坏孩子”的目光。平静地和宝宝对视，解释规矩，别动摇你的立场。清单上没有的，就不买。' WHERE id = '310065f1-7769-41dc-b05f-15aba7ca4982' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego del «¿Quién eres?» 🎭', body_es = 'Te mira con una cara muy seria y dice: «¿Quién eres tú? ¿Dónde está mi mamá?». ¡Está jugando contigo a hacer teatro! Cambia el tono de voz, di «Soy la vecina, tu mamá viene ahora» y sigue con este teatro maravilloso.', title_fr = 'Le jeu du « Qui es-tu ? » 🎭', body_fr = 'Il vous regarde d''un air très sérieux : « Qui es-tu ? Où est ma maman ? » Il joue la comédie avec vous ! Dites « Je suis la voisine, ta maman va arriver », changez votre voix et continuez ce formidable théâtre.', title_hi = '‘तुम कौन हो?’ वाला खेल 🎭', body_hi = 'आपको देखकर बहुत गंभीर चेहरे से कहता है, ‘तुम कौन हो? मेरी माँ कहाँ है?’ वह आपके साथ अदाकारी का खेल खेल रहा है! ‘मैं पड़ोस वाली आंटी हूँ, तुम्हारी माँ अभी आती है’ कहकर आवाज़ बदलिए और इस शानदार नाटक को आगे बढ़ाइए।', title_id = 'Permainan ''Kamu siapa?'' 🎭', body_id = 'Ia menatap Anda dengan wajah sangat serius dan berkata ''Kamu siapa? Mamaku mana?''. Ia sedang bermain akting dengan Anda! Ubah nada suara Anda, katakan ''Aku tante tetangga, mamamu sebentar lagi datang'', dan lanjutkan teater hebat ini.', title_ja = '「あなたは誰？」ごっこ 🎭', body_ja = 'あなたを見て、とても真剣な顔で「あなたは誰？ぼくのママはどこ？」と言う。あなたとお芝居ごっこをしているんです！声を変えて「となりのおばさんよ、ママはすぐ来るからね」と言って、このすばらしい劇を続けましょう。', title_ko = '''누구세요?'' 놀이 🎭', body_ko = '엄마를 보며 아주 진지한 표정으로 ''누구세요? 우리 엄마 어디 있어요?''라고 하나요? 엄마와 연기 놀이를 하는 거예요! 목소리를 바꿔 ''나는 옆집 아줌마야, 엄마 곧 오실 거야''라며 이 멋진 연극을 이어 가세요.', title_nl = 'Het ''Wie ben jij?''-spel 🎭', body_nl = 'Hij kijkt je met een heel serieus gezicht aan en zegt: ''Wie ben jij? Waar is mijn mama?'' Hij speelt toneel met je! Zeg met een andere stem ''Ik ben de buurvrouw, je mama komt zo'' en speel dit prachtige theater verder.', title_pl = 'Zabawa „Kim jesteś?” 🎭', body_pl = 'Patrzy na ciebie z bardzo poważną miną i mówi: „Kim jesteś? Gdzie moja mama?”. Gra z tobą w aktorstwo! Zmień głos, powiedz „Jestem sąsiadką, mama zaraz przyjdzie” i ciągnij ten wspaniały teatr.', title_pt = 'O jogo do "Quem és tu?" 🎭', body_pt = 'Olha para si com uma cara muito séria e diz: "Quem és tu? Onde está a minha mãe?". Está a fazer um jogo de representação consigo! Mude o tom de voz, diga "Sou a vizinha, a tua mãe já vem" e continue este teatro fantástico.', title_sv = 'Leken ”Vem är du?” 🎭', body_sv = 'Barnet tittar på dig med en väldigt allvarlig min och säger: ”Vem är du? Var är min mamma?” Barnet leker en skådespelarlek med dig! Säg med ändrad röst ”Jag är grannen, din mamma kommer snart” och fortsätt den fantastiska teatern.', title_vi = 'Trò chơi "Cô là ai?" 🎭', body_vi = 'Bé nhìn mẹ với vẻ mặt cực kỳ nghiêm túc: "Cô là ai? Mẹ con đâu rồi?". Bé đang chơi trò diễn kịch với mẹ đấy! Hãy đổi giọng và nói "Cô là cô hàng xóm, mẹ con sắp về rồi" để tiếp tục vở kịch tuyệt vời này.', title_zh = '“你是谁？”游戏 🎭', body_zh = '看着你，一脸严肃地说：“你是谁？我妈妈在哪儿？”宝宝在和你玩表演游戏！换个声音说“我是邻居阿姨，你妈妈马上就来”，把这出精彩的戏演下去吧。' WHERE id = 'd64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un «te quiero» por sorpresa 💖', body_es = 'Jugando en medio de la habitación, de repente te mira, viene corriendo y se te cuelga del cuello. ¡Vale la pena por todas las noches sin dormir y todo el cansancio! Disfruta de la paz profunda y única de este momento: olvidarás todo el caos al instante.', title_fr = 'Un « Je t''aime » soudain 💖', body_fr = 'En jouant au milieu de la pièce, il vous regarde soudain, accourt et se jette à votre cou. Cela vaut toutes les nuits blanches et toute la fatigue ! Savourez la paix profonde et unique de ce moment, vous oublierez aussitôt tout le chaos.', title_hi = 'अचानक ‘आई लव यू’ 💖', body_hi = 'कमरे के बीच खेलते-खेलते अचानक आपकी ओर देखकर दौड़ता आता है और गले से लिपट जाता है। सारी जागी रातें, सारी थकान इसके लायक थी! इस पल के गहरे, अनोखे सुकून का आनंद लीजिए, सारी अफ़रा-तफ़री आप पल में भूल जाएँगी।', title_id = '''Aku sayang Mama'' yang tiba-tiba 💖', body_id = 'Sedang bermain di tengah kamar, tiba-tiba ia menatap Anda, berlari, dan memeluk leher Anda. Itu sepadan dengan semua malam tanpa tidur dan rasa lelah! Nikmati ketenangan yang dalam dan istimewa dari momen ini, Anda akan langsung melupakan semua kekacauan.', title_ja = '不意打ちの「大好き」 💖', body_ja = '部屋のまんなかで遊んでいたのに、ふとあなたを見て走ってきて、首にぎゅっと抱きついてくる。眠れない夜も疲れも、すべて報われますね！この瞬間がくれる深くて特別な幸せをかみしめて。カオスのことなんて、すぐに忘れてしまいます。', title_ko = '갑작스러운 ''사랑해'' 💖', body_ko = '방 한가운데서 놀다가 갑자기 엄마를 보고 달려와 목을 꼭 끌어안나요? 잠 못 잔 밤과 피로가 모두 보상받는 순간이에요! 이 순간의 깊고 특별한 평온을 누리면 그 모든 혼돈을 금세 잊게 될 거예요.', title_nl = 'Een onverwacht ''Ik hou van je'' 💖', body_nl = 'Midden in het spelen kijkt hij je ineens aan, rent naar je toe en slaat zijn armpjes om je nek. Dat is alle slapeloze nachten en vermoeidheid waard! Geniet van de diepe, unieke rust die dit moment je geeft, en je vergeet meteen alle chaos.', title_pl = 'Nagłe „Kocham cię” 💖', body_pl = 'Bawiąc się na środku pokoju, nagle na ciebie spojrzał, przybiegł i objął cię za szyję. To jest warte wszystkich nieprzespanych nocy i zmęczenia! Delektuj się tym głębokim, wyjątkowym spokojem tej chwili, a cały chaos od razu pójdzie w niepamięć.', title_pt = 'Um "Amo-te" de repente 💖', body_pt = 'A brincar no meio do quarto, olha de repente para si, vem a correr e abraça-se ao seu pescoço. Valeu todas as noites sem dormir e todo o cansaço! Saboreie a calma profunda e única deste momento: vai esquecer logo todo aquele caos.', title_sv = 'Ett plötsligt ”Jag älskar dig” 💖', body_sv = 'Mitt i leken tittar barnet plötsligt på dig, springer fram och kramar dig om halsen. Det var värt alla sömnlösa nätter och all trötthet! Njut av det djupa, unika lugn som stunden ger, du glömmer genast allt kaos.', title_vi = '"Con yêu mẹ" bất ngờ 💖', body_vi = 'Đang chơi giữa phòng, bé bỗng nhìn mẹ, chạy đến và ôm chầm lấy cổ mẹ. Thật xứng đáng với mọi đêm mất ngủ và mệt mỏi! Hãy tận hưởng cảm giác bình yên sâu lắng, đặc biệt mà khoảnh khắc này mang lại, mẹ sẽ quên ngay mọi hỗn loạn.', title_zh = '突然的“我爱你” 💖', body_zh = '在房间中间玩着玩着，突然看你一眼，跑过来搂住你的脖子。所有不眠的夜晚、所有的疲惫都值了！好好享受这一刻带来的那份深深的、独一无二的安宁，所有的混乱都会瞬间被忘掉。' WHERE id = 'f9b49a33-7a6d-4463-b26d-b51d28283257' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es arte 🎨', body_es = 'Ha creado en medio de la habitación una gran obra de arte con trocitos de papel e hilos cortados y no te deja tirarla. Deja a un lado la obsesión por la limpieza. Respeta el caos que ha creado: la limpieza puede esperar a mañana.', title_fr = 'Ce n''est pas du désordre, c''est de l''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art faite de petits bouts de papier et de ficelles coupées, et refuse que vous la jetiez. Laissez de côté votre obsession du rangement. Respectez le chaos qu''il a créé, le ménage peut attendre demain.', title_hi = 'कचरा नहीं, कला 🎨', body_hi = 'कमरे के बीच कागज़ के छोटे टुकड़ों और कटे धागों से एक बड़ी कलाकृति बना ली है और फेंकने नहीं देता। सफ़ाई की सनक एक तरफ़ रखिए। उसकी रची अफ़रा-तफ़री का सम्मान कीजिए, सफ़ाई कल तक भी रुक सकती है।', title_id = 'Bukan sampah, tapi seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari sobekan kertas dan potongan benang, dan tidak mengizinkan Anda membuangnya. Singkirkan dulu obsesi kebersihan. Hargai kekacauan yang ia ciptakan, bersih-bersih bisa menunggu besok.', title_ja = 'ゴミじゃない、アートです 🎨', body_ja = '部屋のまんなかに、小さな紙くずや切った毛糸で大作をつくり、捨てさせてくれない。きれい好きはちょっとお休みして、この子がつくったカオスを尊重しましょう。お掃除は明日でも大丈夫です。', title_ko = '쓰레기가 아니라 예술 🎨', body_ko = '방 한가운데 작은 종이 조각과 잘린 실로 커다란 작품을 만들고 버리지 못하게 하나요? 깔끔함에 대한 집착은 잠시 내려놓으세요. 아이가 만든 혼돈을 존중해 주세요, 청소는 내일 해도 돼요.', title_nl = 'Geen rommel, maar kunst 🎨', body_nl = 'Hij heeft midden in de kamer een groot kunstwerk gemaakt van papiersnippers en stukjes touw, en hij laat het je niet weggooien. Zet je opruimdrang even opzij. Respecteer de chaos die hij heeft gemaakt, opruimen kan ook morgen.', title_pl = 'To nie śmieci, to sztuka 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki ze skrawków papieru i pociętych sznurków i nie pozwala go wyrzucić. Odłóż na bok obsesję porządku. Uszanuj chaos, który stworzył, sprzątanie może poczekać do jutra.', title_pt = 'Não é lixo, é arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com pedacinhos de papel e fios cortados e não a deixa deitar fora. Ponha de lado a obsessão pela limpeza. Respeite o caos que ele criou, a limpeza pode ficar para amanhã.', title_sv = 'Inte skräp, utan konst 🎨', body_sv = 'Mitt i rummet har barnet skapat ett stort konstverk av små pappersbitar och avklippta snören och låter dig inte slänga det. Lägg städmanin åt sidan. Respektera kaoset barnet har skapat, städningen kan vänta till i morgon.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Giữa phòng, bé đã tạo ra một "tác phẩm nghệ thuật" lớn từ những mẩu giấy vụn và sợi dây cắt nhỏ, và không cho mẹ vứt đi. Hãy gác lại nỗi ám ảnh sạch sẽ. Tôn trọng sự hỗn loạn bé tạo ra, việc dọn dẹp có thể để đến mai.', title_zh = '不是垃圾，是艺术 🎨', body_zh = '在房间中间用碎纸片、剪断的线头创作了一件大型艺术品，还不让你扔。把洁癖先放一边。尊重宝宝创造的混乱吧，打扫可以留到明天。' WHERE id = '3674bd2e-5c13-4e77-8d3d-732d072d4226' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Completa las frases a medias 🗣️', body_es = 'Cuando olvida una palabra hace gestos con las manos, frunce el ceño y espera que la adivines. Su vocabulario crece, solo que su cerebro va más rápido que su lengua. Cuando completes su frase con paciencia, fíjate en ese alivio de «¡sí, eso es lo que decía!» en su cara.', title_fr = 'Finir ses phrases 🗣️', body_fr = 'Quand il oublie un mot, il fait des gestes, fronce les sourcils et attend que vous trouviez. Son vocabulaire grandit, c''est juste que son cerveau va plus vite que sa langue. Quand vous finissez patiemment sa phrase, observez ce soulagement sur son visage : « Oui, c''est exactement ça ! »', title_hi = 'अधूरे वाक्य पूरे कीजिए 🗣️', body_hi = 'कोई शब्द भूल जाने पर हाथ से इशारे करके, भौंहें चढ़ाकर आपके समझने का इंतज़ार करता है। उसकी शब्दावली बढ़ रही है, बस उसका दिमाग ज़ुबान से तेज़ चलता है। जब आप धैर्य से उसका वाक्य पूरा करती हैं, तो उसके चेहरे पर आई ‘हाँ, यही कह रहा था’ वाली राहत देखिए।', title_id = 'Lengkapi kalimatku 🗣️', body_id = 'Saat lupa satu kata, ia memberi isyarat dengan tangan, mengerutkan alis, dan menunggu Anda menebak. Kosakatanya bertambah, hanya saja otaknya bekerja lebih cepat daripada lidahnya. Saat Anda dengan sabar melengkapi kalimatnya, perhatikan rasa lega di wajahnya: ''Iya, itu maksudku!''.', title_ja = '途中の言葉を当ててあげよう 🗣️', body_ja = '言葉を忘れると、手でジェスチャーをして眉をしかめ、あなたが当てるのを待っています。語彙は増えています。ただ、頭の回転が口より速いだけ。根気よく文を完成させてあげたときの、「そう、それが言いたかったの」というほっとした顔を見てあげて。', title_ko = '끝맺지 못한 문장 채워 주기 🗣️', body_ko = '단어가 생각 안 나면 손짓하고 눈살을 찌푸리며 엄마가 맞혀 주길 기다리나요? 어휘는 늘고 있어요, 그저 뇌가 혀보다 빠를 뿐이에요. 문장을 인내심 있게 완성해 줄 때 아이 얼굴에 떠오르는 ''맞아, 그거야!'' 하는 안도감을 지켜보세요.', title_nl = 'Maak de zin af 🗣️', body_nl = 'Vergeet hij een woord, dan maakt hij gebaren, fronst hij en wacht hij tot jij het raadt. Zijn woordenschat groeit, zijn brein werkt alleen sneller dan zijn tong. Kijk naar die opluchting op zijn gezicht als jij geduldig zijn zin afmaakt: ''Ja, dát bedoelde ik!''', title_pl = 'Dokończ moje zdanie 🗣️', body_pl = 'Gdy zapomni słowa, pokazuje coś rękami, marszczy brwi i czeka, aż zgadniesz. Słownictwo mu rośnie, po prostu mózg pracuje szybciej niż język. Gdy cierpliwie dokończysz jego zdanie, zobacz tę ulgę na jego twarzy: „Aaa, właśnie o to mi chodziło”.', title_pt = 'Completar frases a meio 🗣️', body_pt = 'Quando se esquece de uma palavra, faz gestos com as mãos, franze a testa e espera que a adivinhe. O vocabulário está a crescer, o cérebro só trabalha mais depressa do que a língua. Quando completa a frase com paciência, repare no alívio na cara dele: "Ah, é isso mesmo que eu queria dizer".', title_sv = 'Fyll i de halva meningarna 🗣️', body_sv = 'När barnet glömmer ett ord gör det tecken med händerna, rynkar pannan och väntar på att du ska gissa. Ordförrådet växer, hjärnan arbetar bara snabbare än tungan. När du tålmodigt fyller i meningen, lägg märke till lättnaden i barnets ansikte: ”Jaa, det var precis det jag menade.”', title_vi = 'Hoàn thành câu nói dở 🗣️', body_vi = 'Khi quên một từ, bé ra hiệu bằng tay, nhíu mày và chờ mẹ đoán. Vốn từ của bé đang lớn dần, chỉ là não bé chạy nhanh hơn lưỡi thôi. Hãy để ý vẻ nhẹ nhõm "À, đúng cái đó đấy" trên gương mặt bé khi mẹ kiên nhẫn nói nốt câu giúp bé.', title_zh = '帮宝宝补完半句话 🗣️', body_zh = '忘了某个词时，就用手比画、皱着眉，等你猜出来。词汇量在增长，只是大脑转得比嘴巴还快。当你耐心地帮宝宝把句子补完时，看看宝宝脸上那种“对，我就是想说这个”的如释重负吧。' WHERE id = 'f14df610-5f47-47f4-b085-7728f03a38c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego a caballito de papá 🐴', body_es = 'No ha podido gastar toda su energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo sube a caballito y galopa, las carcajadas llenan la habitación y todo el estrés físico acumulado, esa energía sin fin, desaparece en segundos con el sudor.', title_fr = 'Jeu sur le dos de papa 🐴', body_fr = 'Il n''a pas pu se dépenser complètement et refuse d''aller au lit. Appelez papa en renfort. Quand il le prend sur son dos pour jouer au cheval, les éclats de rire remplissent la pièce, et toute la tension physique accumulée, cette énergie sans fin, s''évacue en quelques secondes.', title_hi = 'पापा की पीठ पर खेल 🐴', body_hi = 'पूरी ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक तनाव, वह अंतहीन ऊर्जा पसीने के साथ सेकंडों में गायब हो जाती है।', title_id = 'Main kuda-kudaan di punggung Ayah 🐴', body_id = 'Ia belum sempat menyalurkan seluruh energinya dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar, dan semua stres fisik serta energi yang tak habis-habis itu lenyap dalam hitungan detik bersama keringat.', title_ja = 'パパの背中で遊ぼう 🐴', body_ja = 'エネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを背中にのせてお馬さんになれば、部屋は笑い声でいっぱいになり、たまっていた体のストレスも尽きないエネルギーも、汗と一緒にあっという間に消えていきます。', title_ko = '아빠 등 위의 말 타기 🐴', body_ko = '에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음소리가 방을 채우고, 쌓인 몸의 스트레스와 끝없는 에너지가 땀과 함께 몇 초 만에 사라져요.', title_nl = 'Spelen op papa''s rug 🐴', body_nl = 'Hij is zijn energie niet helemaal kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem op zijn rug neemt en paardje speelt, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke stress en die eindeloze energie zwetend in een paar seconden.', title_pl = 'Zabawa na plecach taty 🐴', body_pl = 'Nie wyładował do końca energii i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy weźmie go na barana i pogalopuje jak koń, śmiech wypełni pokój, a całe nagromadzone napięcie i ta niewyczerpana energia znikną w kilka sekund.', title_pt = 'Brincadeira às costas do pai 🐴', body_pt = 'Não conseguiu gastar toda a energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele põe a criança às costas e faz de cavalo a galopar, as gargalhadas enchem o quarto e todo o stress físico acumulado, aquela energia sem fim, desaparece em segundos, a suar.', title_sv = 'Lek på pappas rygg 🐴', body_sv = 'Barnet har inte fått ur sig all energi och vägrar gå och lägga sig. Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och all ansamlad fysisk stress och den ändlösa energin försvinner på några sekunder i form av svett.', title_vi = 'Trò cưỡi ngựa trên lưng bố 🐴', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố cõng bé chơi trò cưỡi ngựa, tiếng cười ngập tràn căn phòng, mọi căng thẳng thể chất và nguồn năng lượng bất tận ấy sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', title_zh = '在爸爸背上玩耍 🐴', body_zh = '精力还没释放完，就是不肯上床。叫爸爸来帮忙吧。爸爸把宝宝驮在背上“骑大马”时，笑声充满房间，积攒的所有身体压力和用不完的精力，几秒钟内就随着汗水消失了。' WHERE id = '489e6dea-7ed3-426f-a373-fa7b11cafdff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Has preparado 4 menús distintos para que coma, pero ¿y tú qué has comido? Elige en Recetas saludables un tentempié especial rico en calcio que se hace en 5 minutos y disfrútalo aunque sea de pie: eres el motor de esta casa y necesitas recargarte.', body_fr = 'Vous avez imaginé 4 menus différents pour le nourrir, mais vous, qu''avez-vous mangé ? Choisissez dans les Recettes saines une collation spéciale riche en calcium, prête en 5 minutes, et savourez-la, même debout : vous êtes le moteur de cette maison, vous devez vous recharger.', body_hi = 'उसे खिलाने के लिए 4 तरह का मेन्यू बनाया, और आपने क्या खाया? सेहतमंद रेसिपी से 5 मिनट में बनने वाला, कैल्शियम से भरपूर एक खास स्नैक चुनिए और खड़े-खड़े ही सही, उसका मज़ा लीजिए, आप इस घर का इंजन हैं, आपका चार्ज रहना ज़रूरी है।', body_id = 'Kamu menyusun menu dengan 4 cara berbeda untuk menyuapinya, lalu kamu sendiri makan apa? Pilih camilan istimewa kaya kalsium dari Resep Sehat yang siap dalam 5 menit, dan nikmati meski sambil berdiri. Kamu adalah mesin rumah ini, kamu harus mengisi ulang tenaga.', body_ja = 'この子に食べさせるために4通りもメニューを考えたけれど、あなたは何を食べた？「ヘルシーレシピ」から5分でできる、カルシウムたっぷりの特別なおやつを選んで、立ったままでも味わって。あなたはこの家のエンジン、充電が必要です。', body_ko = '아이를 먹이려고 메뉴를 4가지나 짰는데, 엄마는 뭘 드셨나요? 건강한 레시피에서 5분이면 되는 칼슘이 풍부한 특별한 간식을 골라 서서라도 맛있게 드세요. 엄마는 이 집의 엔진이고, 충전이 필요해요.', body_nl = 'Je hebt op 4 manieren een menu bedacht om hem te laten eten, maar wat heb jij gegeten? Kies uit Gezonde recepten een speciaal, calciumrijk tussendoortje dat in 5 minuten klaar is en geniet ervan, al is het staand. Jij bent de motor van dit huis, je moet opladen.', body_pl = 'Wymyśliłaś menu na 4 różne sposoby, żeby go nakarmić, a ty co zjadłaś? Wybierz ze Zdrowych przepisów wyjątkową przekąskę bogatą w wapń, gotową w 5 minut, i delektuj się nią, nawet na stojąco. Jesteś silnikiem tego domu, musisz się naładować.', body_pt = 'Preparou 4 menus diferentes para ele comer, mas e a mãe, o que comeu? Escolha nas Receitas Saudáveis um snack especial rico em cálcio, pronto em 5 minutos, e saboreie-o, nem que seja de pé: é o motor desta casa e precisa de recarregar.', body_sv = 'Du gjorde 4 olika menyer för att få barnet att äta, men vad åt du själv? Välj ett särskilt kalciumrikt mellanmål från Hälsosamma recept som tar 5 minuter och njut av det, även om du står upp. Du är det här hemmets motor, du måste ladda.', body_vi = 'Mẹ đã nghĩ ra thực đơn theo 4 cách khác nhau để bé chịu ăn, còn mẹ đã ăn gì chưa? Hãy chọn từ Công thức lành mạnh một món ăn nhẹ đặc biệt giàu canxi, làm xong trong 5 phút, và thưởng thức dù chỉ đứng ăn, mẹ là động cơ của ngôi nhà này, mẹ cần được sạc pin.', body_zh = '为了让宝宝吃饭，你想了4种不同的菜单，那你自己吃了什么？从健康食谱里挑一份5分钟搞定、富含钙的特别小零食，哪怕站着吃也好好享受，你是这个家的发动机，得充好电。' WHERE id = '654f0e0a-2920-4fe5-8cf5-be2fa96fa926' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertar de gato 🐾', body_es = 'Esta mañana no es una persona. Anda a cuatro patas, se frota contra tus piernas y solo se comunica diciendo «miau». Es el punto más dulce de la imaginación. En lugar de poner normas, ofrécele tú también un cuenco de leche imaginario y disfruta del juego.', title_fr = 'Un réveil de chat 🐾', body_fr = 'Ce matin, ce n''est pas un être humain. Il marche à quatre pattes, se frotte contre vos jambes et ne communique qu''en disant « miaou ». C''est le moment le plus mignon de l''imagination. Au lieu de poser des règles, tendez-lui une gamelle de lait imaginaire et savourez ce jeu.', title_hi = 'बिल्ली की तरह जागना 🐾', body_hi = 'आज सुबह वह इंसान नहीं है। चारों हाथ-पैरों पर चलता है, आपके पैरों से लिपटता है और बस ‘म्याऊँ’ कहकर बात करता है। यह कल्पना का सबसे प्यारा पल है। नियम बनाने के बजाय आप भी उसकी ओर काल्पनिक दूध का कटोरा बढ़ाकर इस खेल का मज़ा लीजिए।', title_id = 'Bangun seperti kucing 🐾', body_id = 'Pagi ini ia bukan manusia. Ia berjalan merangkak, menggosokkan tubuh ke kaki Anda, dan berkomunikasi hanya dengan ''meong''. Ini titik imajinasi yang paling manis. Daripada membuat aturan, sodorkan juga mangkuk susu khayalan dan nikmati permainan ini.', title_ja = 'ねこの目覚め 🐾', body_ja = '今朝のこの子は人間ではありません。よつんばいで歩き、あなたの足にすりよって、「にゃー」とだけ言ってお話しします。想像力のいちばんかわいい瞬間です。ルールを決める代わりに、空想のミルク皿を差し出して、この遊びを楽しみましょう。', title_ko = '고양이처럼 기상 🐾', body_ko = '오늘 아침 아이는 사람이 아니에요. 네 발로 걷고, 엄마 다리에 몸을 비비고, ''야옹''으로만 대화하나요? 상상력의 가장 사랑스러운 순간이에요. 규칙을 세우는 대신 상상의 우유 그릇을 내밀며 이 놀이를 즐겨 보세요.', title_nl = 'Wakker worden als een kat 🐾', body_nl = 'Vanochtend is hij geen mens. Hij loopt op handen en voeten, wrijft langs je benen en communiceert alleen met ''miauw''. Dit is het liefste punt van zijn fantasie. Stel geen regels, maar geef hem een denkbeeldig bakje melk en geniet van het spel.', title_pl = 'Kocia pobudka 🐾', body_pl = 'Dziś rano nie jest człowiekiem. Chodzi na czworakach, ociera się o twoje nogi i porozumiewa się tylko przez „miau”. To najsłodszy moment wyobraźni. Zamiast ustalać zasady, podsuń mu wymyśloną miseczkę mleka i ciesz się tą zabawą.', title_pt = 'Acordar como um gato 🐾', body_pt = 'Esta manhã ele não é uma pessoa. Anda de gatas, roça-se nas suas pernas e só comunica com "miau". É o ponto mais doce da imaginação. Em vez de impor regras, estenda-lhe também uma tigela de leite imaginária e aproveite a brincadeira.', title_sv = 'Vaknar som en katt 🐾', body_sv = 'I morse är barnet ingen människa. Det går på alla fyra, stryker sig mot dina ben och kommunicerar bara med ”mjau”. Det är fantasins sötaste punkt. Istället för att sätta regler, räck fram en låtsasmjölkskål och njut av leken du också.', title_vi = 'Thức dậy như một chú mèo 🐾', body_vi = 'Sáng nay bé không phải là con người. Bé bò bằng bốn chân, cọ vào chân mẹ và chỉ giao tiếp bằng tiếng "meo". Đây là khoảnh khắc đáng yêu nhất của trí tưởng tượng. Thay vì đặt quy tắc, hãy đưa bé một bát sữa tưởng tượng và tận hưởng trò chơi này.', title_zh = '像小猫一样醒来 🐾', body_zh = '今天早上宝宝不是人。四脚着地走来走去，蹭你的腿，只用“喵”来交流。这是想象力最可爱的时刻。别急着定规矩，你也递给它一个想象中的牛奶碗，好好享受这个游戏吧。' WHERE id = 'f72407e2-133f-448d-813f-15315e00fa30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hipnosis musical 🎶', body_es = 'Han empezado las tormentas sin motivo del atardecer y las crisis de llanto. Apaga la tele, baja las luces y pon en la habitación una música clásica muy suave. La frecuencia profunda de la música cambiará el ambiente como por arte de magia y traerá calma a la habitación.', title_fr = 'Hypnose musicale 🎶', body_fr = 'Les tempêtes sans raison et les crises de larmes de fin de journée ont commencé. Éteignez la télé, baissez les lumières et mettez une musique classique très douce dans la pièce. La fréquence profonde de la musique changera l''atmosphère comme par magie et apportera la paix dans la pièce.', title_hi = 'संगीत का सम्मोहन 🎶', body_hi = 'शाम को बिना वजह के तूफ़ान, रोने के दौर शुरू हो गए हैं। टीवी बंद कीजिए, रोशनी धीमी कीजिए और कमरे में बहुत हल्का शास्त्रीय संगीत चलाइए। संगीत की वह गहरी तरंग माहौल को जादुई तरीके से बदल देगी और कमरे में सुकून लाएगी।', title_id = 'Hipnosis musik 🎶', body_id = 'Badai tanpa sebab dan krisis tangis menjelang malam sudah dimulai. Matikan TV, redupkan lampu, dan putar musik klasik yang sangat lembut di kamar. Frekuensi musik yang dalam akan mengubah suasana secara ajaib dan menghadirkan ketenangan di kamar.', title_ja = '音楽の催眠術 🎶', body_ja = '夕方のわけのわからない嵐や、泣きじゃくりが始まりました。テレビを消して明かりを落とし、部屋にとてもやさしいクラシック音楽を流しましょう。音楽の深い響きが空気を魔法のように変えて、部屋に落ち着きをもたらしてくれます。', title_ko = '음악 최면 🎶', body_ko = '저녁 무렵 이유 없는 폭풍과 울음이 시작됐나요? TV를 끄고 불을 낮춘 뒤 아주 잔잔한 클래식 음악을 틀어 주세요. 음악의 깊은 울림이 분위기를 마법처럼 바꾸고 방에 평온을 가져다줄 거예요.', title_nl = 'Muzikale hypnose 🎶', body_nl = 'De onverklaarbare stormen en huilbuien van eind van de middag zijn begonnen. Zet de tv uit, dim de lichten en zet heel zachte klassieke muziek op. De diepe frequentie van de muziek verandert de sfeer op magische wijze en brengt rust in de kamer.', title_pl = 'Muzyczna hipnoza 🎶', body_pl = 'Zaczęły się wieczorne burze bez powodu i kryzysy z płaczem. Wyłącz telewizor, przygaś światła i puść w pokoju bardzo cichą muzykę klasyczną. Głęboka częstotliwość muzyki magicznie zmieni atmosferę i wniesie do pokoju spokój.', title_pt = 'Hipnose musical 🎶', body_pt = 'Começaram as tempestades sem razão e as crises de choro do fim da tarde. Desligue a televisão, baixe as luzes e ponha no quarto uma música clássica muito suave. A frequência profunda da música vai mudar o ambiente como por magia e trazer calma ao quarto.', title_sv = 'Musikalisk hypnos 🎶', body_sv = 'Omotiverade stormar och gråtkriser framåt kvällen har börjat. Stäng av tv:n, dämpa ljuset och sätt på mycket lätt klassisk musik i rummet. Musikens djupa frekvens förändrar stämningen magiskt och ger rummet lugn.', title_vi = 'Thôi miên bằng âm nhạc 🎶', body_vi = 'Những cơn bùng nổ vô cớ, những trận khóc lúc chiều tối đã bắt đầu. Hãy tắt tivi, giảm đèn và bật thật khẽ một bản nhạc cổ điển nhẹ nhàng. Tần số sâu lắng của âm nhạc sẽ thay đổi bầu không khí một cách kỳ diệu và mang lại bình yên cho căn phòng.', title_zh = '音乐催眠 🎶', body_zh = '傍晚莫名的小风暴和哭闹开始了。关掉电视，把灯光调暗，在房间里放一点很轻柔的古典音乐。音乐深沉的频率会神奇地改变气氛，给房间带来安宁。' WHERE id = '784cb32f-466a-4d9b-9df3-23fb3c0de764' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desayuno que no se comparte 🍳', body_es = 'No te da nada de su plato, pero viene e insiste en comer del huevo de tu plato. Los niños siempre confían plenamente en lo que eligen sus padres. No luches: pásale tu bocado con cariño y sonríe.', title_fr = 'Un petit-déjeuner qui ne se partage pas 🍳', body_fr = 'Il refuse catégoriquement de vous donner quoi que ce soit de son assiette, mais vient réclamer avec insistance l''œuf de la vôtre. Les enfants font toujours entièrement confiance aux choix de leurs parents. Ne luttez pas, cédez-lui votre bouchée avec amour et souriez.', title_hi = 'न बँटने वाला नाश्ता 🍳', body_hi = 'अपनी प्लेट का कुछ भी आपको बिल्कुल नहीं देता, पर आकर ज़िद से आपकी प्लेट का अंडा खाना चाहता है। बच्चे हमेशा माता-पिता की पसंद पर पूरा भरोसा करते हैं। लड़ाई मत कीजिए, अपना निवाला प्यार से उसे दीजिए और मुस्कुराइए।', title_id = 'Sarapan yang tak bisa dibagi 🍳', body_id = 'Ia sama sekali tak mau memberi isi piringnya kepada Anda, tapi bersikeras ingin makan telur dari piring Anda. Anak selalu percaya penuh pada pilihan orang tuanya. Jangan melawan, berikan suapan Anda kepadanya dengan penuh kasih dan tersenyumlah.', title_ja = '分けてくれない朝ごはん 🍳', body_ja = '自分のお皿のものは絶対にくれないのに、あなたのお皿の卵はどうしても食べたがる。子どもはいつも、親が選んだものを心から信頼するんです。戦わずに、あなたのひと口を愛をこめて渡して、ほほえんであげましょう。', title_ko = '나눌 수 없는 아침 식사 🍳', body_ko = '자기 접시는 절대 안 주면서 엄마 접시의 달걀은 꼭 먹겠다고 하나요? 아이는 늘 부모의 선택을 온전히 믿어요. 싸우지 말고 한 입을 사랑으로 건네며 미소 지어 주세요.', title_nl = 'Ontbijt dat niet gedeeld wordt 🍳', body_nl = 'Van zijn eigen bord geeft hij je absoluut niets, maar hij wil per se van het ei op jouw bord eten. Kinderen vertrouwen altijd volledig op de keuze van hun ouders. Ga de strijd niet aan, geef je hapje liefdevol aan hem en glimlach.', title_pl = 'Śniadanie nie do podziału 🍳', body_pl = 'Ze swojego talerza nie da ci ani kęsa, ale uparcie chce jeść jajko z twojego. Dzieci zawsze w pełni ufają wyborom rodziców. Nie walcz, z miłością oddaj mu swój kęs i się uśmiechnij.', title_pt = 'Um pequeno-almoço que não se partilha 🍳', body_pt = 'Não lhe dá nada do prato dele, mas insiste em comer o ovo do seu prato. As crianças confiam sempre totalmente nas escolhas dos pais. Não lute: passe-lhe o seu bocado com amor e sorria.', title_sv = 'Frukosten som inte delas 🍳', body_sv = 'Barnet ger dig absolut ingenting från sin egen tallrik, men kommer och vill envist äta av ägget på din. Barn litar alltid helt på föräldrarnas val. Börja inte bråka, ge din tugga till barnet med kärlek och le.', title_vi = 'Bữa sáng không chia sẻ 🍳', body_vi = 'Bé nhất quyết không cho mẹ chút gì trong đĩa của mình, nhưng lại cứ đòi ăn trứng trong đĩa của mẹ. Trẻ con luôn tin tưởng tuyệt đối vào lựa chọn của bố mẹ. Đừng giằng co, hãy yêu thương nhường miếng ăn của mình cho bé và mỉm cười.', title_zh = '不肯分享的早餐 🍳', body_zh = '自己盘子里的东西绝对不给你，却偏要来吃你盘子里的鸡蛋。孩子总是完全相信父母的选择。别较劲，带着爱把你的那一口递给宝宝，再笑一笑。' WHERE id = '791a6f93-24a4-4445-acfb-0bee156d7b20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas con objetos 🗣️', body_es = 'En el parque le cuenta cosas muy en serio a una piedra, o en casa a una silla, y hasta les riñe. A través del juego simbólico procesa el mundo. Anota sin falta estos guiones tan especiales en el Seguimiento del desarrollo: ¡es creatividad de alto nivel!', title_fr = 'Conversations avec les objets 🗣️', body_fr = 'Au parc, il parle très sérieusement à un caillou ou, à la maison, à une chaise, et les gronde. À travers le jeu symbolique, il comprend le monde. Notez absolument ces scénarios particuliers dans le Suivi de développement, c''est une grande créativité !', title_hi = 'बेजान चीज़ों से बातचीत 🗣️', body_hi = 'पार्क में किसी पत्थर से या घर में कुर्सी से पूरी गंभीरता से कुछ कहता है, उन्हें डाँटता है। प्रतीकात्मक खेलों के ज़रिए वह दुनिया को समझ रहा है। उसकी इन खास कहानियों को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए, यह ऊँचे दर्जे की रचनात्मकता है!', title_id = 'Mengobrol dengan benda mati 🗣️', body_id = 'Di taman ia berbicara serius dengan sebuah batu, atau di rumah memarahi kursi. Lewat permainan simbolis, ia mengolah dunia. Pastikan menandai skenario istimewanya ini di Pelacak Perkembangan, ini kreativitas tingkat tinggi!', title_ja = 'ものとのおしゃべり 🗣️', body_ja = '公園の石や家のいすに、すっかり真剣に話しかけたり、しかったりしています。象徴遊びを通して世界を整理しているんです。この特別なシナリオを、ぜひ「発達トラッカー」に記録しておきましょう。すばらしい創造力です！', title_ko = '사물과의 대화 🗣️', body_ko = '공원의 돌이나 집의 의자에게 아주 진지하게 무언가를 이야기하고 혼내기도 하나요? 상징 놀이로 세상을 소화하는 중이에요. 이 특별한 시나리오를 성장 기록에 꼭 표시해 두세요, 대단한 창의력이에요!', title_nl = 'Gesprekken met dingen 🗣️', body_nl = 'Praat hij in het park heel serieus tegen een steen of moppert hij thuis op een stoel? Via symbolisch spel verwerkt hij de wereld. Noteer deze bijzondere scenario''s zeker in de Groeitracker: dit is grote creativiteit!', title_pl = 'Rozmowy z przedmiotami 🗣️', body_pl = 'W parku zupełnie poważnie coś opowiada kamieniowi albo w domu beszta krzesło. Przez zabawę symboliczną przetwarza świat. Koniecznie zaznacz te wyjątkowe scenariusze w Śledzeniu rozwoju, to wysoki poziom kreatywności!', title_pt = 'Conversas com objetos 🗣️', body_pt = 'No parque, fala muito a sério com uma pedra ou, em casa, com uma cadeira, e até lhes ralha. Através do jogo simbólico, ele processa o mundo. Não deixe de registar estes enredos especiais no Registo de Crescimento: é criatividade de alto nível!', title_sv = 'Samtal med livlösa saker 🗣️', body_sv = 'Barnet pratar helt allvarligt med en sten i parken eller en stol hemma och skäller på dem. Genom symbolisk lek bearbetar barnet världen. Anteckna absolut barnets speciella scenarier i Utvecklingsspåraren, det är hög kreativitet!', title_vi = 'Trò chuyện với đồ vật 🗣️', body_vi = 'Ở công viên, bé nói chuyện rất nghiêm túc với một hòn đá, ở nhà thì "mắng" chiếc ghế. Bé đang xử lý thế giới qua trò chơi biểu tượng. Hãy nhớ đánh dấu những kịch bản đặc biệt này trong Theo dõi phát triển, đây là sự sáng tạo tuyệt vời!', title_zh = '和没有生命的东西聊天 🗣️', body_zh = '在公园对着一块石头、在家对着一把椅子，非常认真地说着什么，还训它们。宝宝通过象征性游戏来理解世界。一定要把这些特别的小剧本记在发育追踪里，这是很高的创造力！' WHERE id = '840bd918-95f6-4c59-bcb3-4b0f4eaea73b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Coge el móvil. En lugar de deslizar la vida perfecta de otros en redes sociales, abre el Diario de ánimo y anota para el futuro el momento más gracioso que ha tenido hoy, el que más te hizo reír. Escribir ahí es la terapia más pura.', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler la vie parfaite des autres sur les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard son moment le plus drôle de la journée, celui qui vous a le plus fait rire. Écrire, c''est la thérapie la plus pure.', body_hi = 'फ़ोन उठाइए। सोशल मीडिया पर दूसरों की परफ़ेक्ट ज़िंदगी स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज उसने जो सबसे मज़ेदार, आपको सबसे ज़्यादा हँसाने वाला काम किया, उसे भविष्य के लिए लिख लीजिए। वहाँ लिखना सबसे सच्ची थेरेपी है।', body_id = 'Ambil ponsel Anda. Daripada menggulir kehidupan sempurna orang lain di media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucunya hari ini, yang paling membuat Anda tertawa, untuk masa depan. Menulis di sana adalah terapi paling murni.', body_ja = 'スマホを手に取って。SNSでほかの人の完璧な暮らしをスクロールする代わりに、「気分日記」を開いて、今日この子がした、いちばんおもしろくてあなたをいちばん笑わせた瞬間を未来のために記録しましょう。そこに書くことが、いちばん純粋なセラピーです。', body_ko = '휴대폰을 들어 보세요. SNS에서 남의 완벽한 삶을 넘겨보는 대신 기분 일기를 열고 오늘 아이가 보여 준 가장 웃기고 엄마를 가장 많이 웃게 한 순간을 기록해 두세요. 적는 것이 가장 깨끗한 치료예요.', body_nl = 'Pak je telefoon. Open in plaats van door het perfecte leven van anderen op social media te scrollen je Stemmingsdagboek en schrijf het grappigste moment van vandaag op, het moment waar je het hardst om lachte, voor later. Opschrijven is de zuiverste therapie.', body_pl = 'Weź telefon do ręki. Zamiast przewijać idealne życie innych w mediach społecznościowych, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował i która najbardziej cię rozśmieszyła. Pisanie tam to najczystsza terapia.', body_pt = 'Pegue no telemóvel. Em vez de percorrer a vida perfeita dos outros nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico de hoje, o que mais a fez rir. Escrever lá é a terapia mais pura.', body_sv = 'Ta upp telefonen. Istället för att scrolla igenom andras perfekta liv på sociala medier, öppna Humördagboken och anteckna dagens roligaste stund med barnet, den som fick dig att skratta mest, för framtiden. Att skriva där är den renaste terapin.', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt xem cuộc sống hoàn hảo của người khác trên mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc hài hước nhất, khiến mẹ cười nhiều nhất mà bé làm hôm nay để dành cho tương lai. Viết ra là liệu pháp trong lành nhất.', body_zh = '拿起手机。与其刷社交网络看别人完美的生活，不如打开心情日记，把宝宝今天最搞笑、最让你笑出声的一刻记下来留给将来。写下来，就是最纯粹的疗愈。' WHERE id = '11214951-0661-40fc-a2c7-d7aedff5cf90' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La prohibición del «¡Tú no cantes!» 🛑', body_es = 'Te has puesto a tararear la canción infantil que sonaba de fondo y al instante ha gritado: «¡Tú no cantes!». El único solista de la habitación es él, y tus intentos vocales le quitan escenario. No te ofendas: deja el escenario a este pequeño egoísta.', title_fr = 'L''interdit du « Chante pas ! » 🛑', body_fr = 'Vous avez fredonné la chanson pour enfants qui passait en fond et il a aussitôt crié : « Chante pas ! » C''est lui le seul soliste de la pièce, vos tentatives vocales empiètent sur sa scène. Ne le prenez pas mal, laissez la scène à ce petit égoïste.', title_hi = '‘तुम मत गाओ!’ की पाबंदी 🛑', body_hi = 'पीछे चल रहे बच्चों के गाने के साथ आपने गुनगुनाना शुरू किया और वह तुरंत चिल्लाया: ‘तुम मत गाओ!’ कमरे का इकलौता सोलो गायक वही है, आपकी गायकी की कोशिशें उसका मंच छोटा कर देती हैं। बुरा मत मानिए, मंच इस नन्हे स्वार्थी के लिए छोड़ दीजिए।', title_id = 'Larangan ''Mama jangan nyanyi!'' 🛑', body_id = 'Anda ikut bersenandung mengikuti lagu anak yang diputar, dan ia langsung berteriak: ''Mama jangan nyanyi!'' Dialah satu-satunya penyanyi di ruangan ini, usaha vokal Anda mempersempit panggungnya. Jangan tersinggung, serahkan panggung kepada si egois kecil ini.', title_ja = '「ママは歌わないで！」禁止令 🛑', body_ja = '流れている子どもの歌に合わせてハミングしたら、すぐに「ママは歌わないで！」と叫ばれた。部屋のソリストはこの子だけ。あなたの歌声は、この子のステージをせまくしてしまうんです。気を悪くしないで、ステージはこの小さなわがままさんにゆずりましょう。', title_ko = '''엄마는 노래하지 마!'' 금지령 🛑', body_ko = '배경에 흐르는 동요를 따라 흥얼거렸더니 바로 ''엄마는 노래하지 마!''라고 소리쳤나요? 이 방의 유일한 솔로 가수는 아이고, 엄마의 노래는 무대를 좁히는 거죠. 서운해하지 말고 무대는 이 작은 욕심쟁이에게 양보하세요.', title_nl = 'Het ''Niet zingen!''-verbod 🛑', body_nl = 'Je neuriede mee met het kinderliedje op de achtergrond en hij riep meteen: ''Niet zingen!'' Hij is de enige solist in de kamer, jouw zangpogingen maken zijn podium kleiner. Voel je niet gekwetst en laat het podium aan deze kleine egoïst.', title_pl = 'Zakaz „Nie śpiewaj!” 🛑', body_pl = 'Zanuciłaś do dziecięcej piosenki lecącej w tle, a on od razu krzyknął: „Nie śpiewaj!”. To on jest jedynym solistą w pokoju, a twoje próby wokalne zabierają mu scenę. Nie obrażaj się, zostaw scenę temu małemu egoiście.', title_pt = 'A proibição do "Não cantes!" 🛑', body_pt = 'Começou a trautear a canção infantil que tocava de fundo e ele gritou logo: "Não cantes!". O único solista do quarto é ele, e as suas tentativas vocais roubam-lhe o palco. Não se ofenda: deixe o palco a este pequeno egoísta.', title_sv = 'Förbudet ”Sjung inte!” 🛑', body_sv = 'Du nynnade med i barnlåten som spelades i bakgrunden, och barnet skrek genast: ”Sjung inte!” Barnet är rummets enda solist, och dina sångförsök gör scenen för trång. Bli inte sårad, lämna scenen åt den lilla egoisten.', title_vi = 'Lệnh cấm "Mẹ đừng hát!" 🛑', body_vi = 'Mẹ ngân nga theo bài hát thiếu nhi đang phát, và bé lập tức hét lên: "Mẹ đừng hát!". Bé là ca sĩ hát đơn duy nhất trong phòng, giọng hát của mẹ đang lấn sân khấu của bé. Đừng phật lòng, hãy nhường sân khấu cho "kẻ ích kỷ" bé nhỏ này.', title_zh = '“你别唱！”禁令 🛑', body_zh = '你跟着背景里的儿歌哼了几句，宝宝马上大喊：“你别唱！”房间里唯一的独唱家是宝宝，你的演唱抢了宝宝的舞台。别难过，把舞台让给这个小小的“自私鬼”吧。' WHERE id = '1219c5e2-02af-4f74-a734-ea08c3018209' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Yo en el Cuento inteligente 🪄', body_es = 'Esta noche, en Cuentos inteligentes, ponle al héroe el nombre de tu peque. Cuenta que el personaje recogió su habitación y luego durmió a gusto, y transmítele las normas de forma indirecta, no a gritos.', title_fr = 'Moi, dans le Conte intelligent 🪄', body_fr = 'Ce soir, dans les Contes intelligents, donnez directement au héros le prénom de votre enfant. Racontez que le personnage range sa chambre puis s''endort paisiblement, pour transmettre les règles de façon indirecte, sans crier.', title_hi = 'स्मार्ट कहानी में मैं 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में हीरो का नाम सीधे अपने बच्चे के नाम पर रखिए। कहानी के किरदार के कमरा समेटने और फिर आराम से सो जाने की बात सुनाकर, नियम चिल्लाकर नहीं, घुमा-फिराकर सिखाइए।', title_id = 'Aku di Dongeng Pintar 🪄', body_id = 'Malam ini di Dongeng Pintar, beri tokoh utamanya nama anak Anda. Ceritakan bahwa tokoh dalam dongeng itu juga membereskan kamarnya lalu tidur nyenyak, dan tanamkan aturan secara tidak langsung, bukan dengan berteriak.', title_ja = 'スマートおはなしの主人公はわたし 🪄', body_ja = '今夜は「スマートおはなし」で、主人公にお子さんの名前をつけましょう。お話の主人公も部屋を片づけてから気持ちよく眠った、という話を通して、ルールを叫んで伝えるのではなく、さりげなく伝えましょう。', title_ko = '스마트 동화 속의 나 🪄', body_ko = '오늘 저녁 스마트 동화에서 주인공 이름을 아이 이름으로 지어 보세요. 이야기 속 주인공도 방을 정리하고 푹 잤다고 들려주며, 규칙을 소리쳐 말하는 대신 자연스럽게 전해 주세요.', title_nl = 'Ik in het Slimme sprookje 🪄', body_nl = 'Geef de held vanavond in Slimme sprookjes de naam van je kind. Vertel dat het personage ook zijn kamer opruimde en daarna lekker sliep, en breng zo regels niet met schreeuwen maar op een indirecte manier over.', title_pl = 'Ja w Mądrej bajce 🪄', body_pl = 'Dziś wieczorem w Mądrych bajkach nazwij bohatera imieniem twojego dziecka. Opowiadając, że postać z bajki też posprzątała pokój, a potem spokojnie zasnęła, przekazuj zasady nie krzykiem, tylko w pośredni sposób.', title_pt = 'Eu nas Histórias Inteligentes 🪄', body_pt = 'Esta noite, dê ao herói das Histórias Inteligentes o nome do seu filho. Conte que a personagem também arrumou o quarto e depois dormiu tranquila, e transmita as regras de forma indireta, sem gritar.', title_sv = 'Jag i den smarta sagan 🪄', body_sv = 'Ge hjälten i kvällens Smarta sagor barnets eget namn. Berätta att sagofiguren också städade sitt rum och sedan sov gott, så förmedlar du reglerna indirekt istället för att skrika ut dem.', title_vi = 'Con trong Truyện cổ tích thông minh 🪄', body_vi = 'Tối nay, trong Truyện cổ tích thông minh, hãy đặt tên nhân vật chính theo tên của bé. Kể rằng nhân vật trong truyện cũng dọn phòng rồi ngủ thật ngon, để dạy bé các quy tắc một cách gián tiếp chứ không phải bằng tiếng quát.', title_zh = '智慧童话里的“我” 🪄', body_zh = '今晚在智慧童话里，直接用宝宝的名字给主角命名。讲讲故事里的角色也把房间收拾好，然后舒舒服服地睡着了，不用吼，而是用间接的方式教会宝宝规矩。' WHERE id = '9dfdb936-66eb-43a1-b7d1-6fccd5198f88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Por la noche tarda mucho en dormirse? Mira el gráfico del temporizador de sueño. Quizá ya haya llegado el momento de quitar del todo la siesta y adelantar la hora de dormir.', body_fr = 'L''endormissement du soir s''éternise ? Regardez le graphique du Minuteur de sommeil. Il est peut-être grand temps de supprimer complètement la sieste et d''avancer l''heure du coucher.', body_hi = 'रात को सोने में बहुत देर लगती है? स्लीप टाइमर का शेड्यूल देखिए। शायद दिन की नींद पूरी तरह बंद करने और रात का समय पहले करने का वक्त पूरी तरह आ गया है।', body_id = 'Tidur malamnya butuh waktu terlalu lama? Lihat jadwal di Timer Tidur. Mungkin sudah tiba waktunya menghentikan tidur siang sepenuhnya dan memajukan jam tidur malam.', body_ja = '夜、寝つくまでに時間がかかりすぎる？「睡眠タイマー」の記録を見てみましょう。もしかしたら、お昼寝を完全にやめて、夜の寝る時間を早める時期がちょうど来ているのかもしれません。', body_ko = '밤에 잠드는 데 너무 오래 걸리나요? 수면 타이머의 기록을 확인해 보세요. 낮잠을 완전히 끊고 밤잠 시간을 앞당길 때가 됐을지도 몰라요.', body_nl = 'Duurt het ''s avonds heel lang voor hij slaapt? Kijk naar het schema van de Slaaptimer. Misschien is het nu echt tijd om het middagslaapje helemaal te schrappen en de avond te vervroegen.', body_pl = 'Wieczorne zasypianie bardzo się przeciąga? Spójrz na wykres w timerze snu. Może właśnie przyszedł czas, by całkowicie zrezygnować z drzemki w dzień i przesunąć wieczorny sen wcześniej.', body_pt = 'À noite demora muito a adormecer? Veja o gráfico do temporizador de sono. Talvez já tenha mesmo chegado a altura de acabar de vez com a sesta e antecipar a hora de deitar.', body_sv = 'Tar det lång tid att somna på kvällen? Titta på diagrammet i sömntimern. Kanske är det helt och hållet dags att slopa tuppluren och tidigarelägga kvällen.', body_vi = 'Buổi tối bé mất quá lâu mới ngủ được? Hãy xem lịch trong Bộ hẹn giờ ngủ. Có lẽ đã đến lúc bỏ hẳn giấc ngủ trưa và cho bé đi ngủ sớm hơn vào buổi tối.', body_zh = '晚上入睡要花很久？看看睡眠计时器的图表。也许是时候完全取消午睡，把晚上的睡觉时间提前了。' WHERE id = '28d0f55b-6b15-4788-8b02-4740d679f342' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te cuenta los dibujos que ha visto con su propia gramática y te explica muy serio quién fue adónde. Escúchale con atención, como si te sorprendiera. Deja que su imaginación vuele y que se sienta la persona más lista del mundo.', body_fr = 'Il vous raconte le dessin animé qu''il a vu avec sa propre grammaire et vous explique très sérieusement qui est allé où. Écoutez-le attentivement, comme si vous étiez étonnée. Laissez son imagination s''envoler et laissez-le se sentir le plus intelligent du monde.', body_hi = 'जो कार्टून देखा, वह आपको अपनी व्याकरण में सुनाता है, गंभीरता से समझाता है कि कौन कहाँ गया। उसे ध्यान से, हैरान होने के अंदाज़ में सुनिए। उसकी कल्पना को उड़ान भरने दीजिए और उसे खुद को दुनिया का सबसे समझदार महसूस करने दीजिए।', body_id = 'Ia menceritakan kartun yang ditontonnya dengan tata bahasanya sendiri, menjelaskan dengan serius siapa pergi ke mana. Dengarkan baik-baik, seolah Anda takjub. Biarkan imajinasinya melambung dan ia merasa menjadi orang paling pintar di dunia.', body_ja = '見たアニメの話を自分なりの文法で話してくれて、誰がどこへ行ったかを真剣に説明しています。おどろいたふりをして、しっかり聞いてあげましょう。想像力を思いきりはばたかせて、自分が世界でいちばんかしこいと感じさせてあげて。', body_ko = '본 만화를 자기만의 문법으로 들려주며 누가 어디에 갔는지 진지하게 설명하나요? 놀란 듯 귀 기울여 들어 주세요. 상상력이 마음껏 날아오르고 세상에서 가장 똑똑한 사람이 된 기분을 느끼게 해 주세요.', body_nl = 'Hij vertelt je de tekenfilm die hij keek in zijn eigen grammatica en legt heel serieus uit wie waarheen ging. Luister aandachtig, alsof je verbaasd bent. Laat zijn fantasie de vrije loop en laat hem zich de slimste van de wereld voelen.', body_pl = 'Opowiada ci obejrzaną bajkę po swojemu, z własną gramatyką, i poważnie tłumaczy, kto dokąd poszedł. Słuchaj go uważnie, jakbyś była zdumiona. Niech jego wyobraźnia wzlatuje, a on poczuje się najmądrzejszy na świecie.', body_pt = 'Conta-lhe os desenhos animados que viu com a sua própria gramática e explica muito a sério quem foi para onde. Ouça-o com atenção, como se estivesse surpreendida. Deixe a imaginação dele voar e que se sinta a pessoa mais inteligente do mundo.', body_sv = 'Barnet återberättar tecknade filmen med sin egen grammatik och förklarar på största allvar vem som gick vart. Lyssna uppmärksamt, som om du vore förvånad. Låt fantasin flöda och barnet känna sig som världens klokaste.', body_vi = 'Bé kể lại cho mẹ bộ phim hoạt hình vừa xem bằng "ngữ pháp" của riêng mình, nghiêm túc giải thích ai đi đâu. Hãy chăm chú lắng nghe như thể thật sự ngạc nhiên. Để trí tưởng tượng của bé bay cao và bé cảm thấy mình là người thông minh nhất thế giới.', body_zh = '用自己的语法给你讲正在看的动画片，一本正经地解释谁去了哪里。认真地、带着惊讶的样子听宝宝讲吧。让宝宝的想象力尽情飞翔，觉得自己是世界上最聪明的人。' WHERE id = '2c32efa0-ce45-4ee9-9fb5-78b505fc81dc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apoyo silencioso de la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie ni desahogarte. Entra en la Comunidad Anacan y limítate a leer. Ver cómo otras madres lidian con las mismas crisis absurdas es el consuelo silencioso más poderoso.', title_fr = 'Le soutien silencieux de la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie ni de rien expliquer à personne, ni de vous confier. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir comment d''autres mamans font face aux mêmes crises absurdes est le plus puissant des réconforts silencieux.', title_hi = 'कम्युनिटी का खामोश सहारा 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना या दिल की बात कहना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। यह देखना कि दूसरी माँएँ भी ऐसे ही बेतुके संकटों से कैसे जूझती हैं, सबसे ताकतवर खामोश सांत्वना है।', title_id = 'Dukungan diam dari komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun atau curhat kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat bagaimana ibu-ibu lain menghadapi krisis absurd yang sama adalah penghiburan diam yang paling ampuh.', title_ja = 'コミュニティの静かな支え 💬', body_ja = 'とても疲れていて、誰にも何も説明したくないし、話したくもない。Anacanコミュニティを開いて、読むだけにしましょう。ほかのママたちが同じようなおかしなかんしゃくとどう向き合っているかを見ることが、いちばん強い静かななぐさめになります。', title_ko = '커뮤니티의 조용한 응원 💬', body_ko = '너무 지쳐서 누구에게도 설명하거나 털어놓고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들이 똑같이 엉뚱한 위기를 어떻게 헤쳐 가는지 보는 것이 가장 강력한 조용한 위로예요.', title_nl = 'De stille steun van de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen of je hart luchten. Ga naar de Anacan Community en lees alleen mee. Zien hoe andere mama''s met precies dezelfde absurde crisissen omgaan, is de sterkste stille troost.', title_pl = 'Ciche wsparcie Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć ani się zwierzać. Wejdź do Społeczności Anacan i tylko czytaj. Widok tego, jak inne mamy radzą sobie z tymi samymi absurdalnymi kryzysami, to najsilniejsze ciche pocieszenie.', title_pt = 'O apoio silencioso da comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém nem desabafar. Entre na Comunidade Anacan e limite-se a ler. Ver como outras mães lidam com as mesmas crises absurdas é o conforto silencioso mais poderoso.', title_sv = 'Gemenskapens tysta stöd 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon eller prata av dig. Gå in i Anacan Community och bara läs. Att se hur andra mammor hanterar samma absurda kriser är den starkaste tysta trösten.', title_vi = 'Sự hỗ trợ lặng lẽ từ Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích hay tâm sự với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác đối mặt với những cơn khủng hoảng "khó đỡ" giống hệt thế nào chính là sự an ủi thầm lặng mạnh mẽ nhất.', title_zh = '社区里无声的支持 💬', body_zh = '累坏了，什么都不想跟任何人解释，也不想倾诉？进入Anacan社区，只当个读者就好。看到其他妈妈怎样应对同样荒诞的崩溃，就是最有力的无声安慰。' WHERE id = 'bc152191-c6d9-4a5e-b03a-d59aaa89994d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Huida de la cama 🏃‍♂️', body_es = '«Dame agua», «busca mi juguete»... Las excusas de los 3 años para no dormirse no se acaban nunca. Pon el temporizador de sueño, protege los límites con firmeza y calma la habitación con Ruido blanco.', title_fr = 'L''évasion du lit 🏃‍♂️', body_fr = '« Donne de l''eau », « Trouve mon jouet »... Les excuses des 3 ans pour ne pas dormir sont sans fin. Lancez le Minuteur de sommeil, tenez fermement vos limites et apaisez la chambre avec les Bruits blancs.', title_hi = 'बिस्तर से भागना 🏃‍♂️', body_hi = '‘पानी दो’, ‘मेरा खिलौना ढूँढो’... न सोने के लिए 3 साल के बहाने खत्म ही नहीं होते। स्लीप टाइमर चालू कीजिए, सीमाओं की पक्के इरादे से रक्षा कीजिए और व्हाइट नॉइज़ से कमरे को शांत कीजिए।', title_id = 'Kabur dari tempat tidur 🏃‍♂️', body_id = '''Minta air'', ''Carikan mainanku''... Alasan anak 3 tahun untuk tidak tidur tidak ada habisnya. Nyalakan Timer Tidur, jaga batasan dengan tegas, dan tenangkan kamar dengan Suara Putih.', title_ja = 'ベッドからの脱走 🏃‍♂️', body_ja = '「お水ちょうだい」「おもちゃさがして」…寝ないための3歳の言いわけは尽きません。「睡眠タイマー」をスタートして、きっぱりと境界線を守り、「ホワイトノイズ」で部屋を落ち着かせましょう。', title_ko = '침대 탈출 🏃‍♂️', body_ko = '''물 줘'', ''내 장난감 찾아 줘''... 잠들지 않으려는 세 살의 핑계는 끝이 없어요. 수면 타이머를 켜고, 경계를 단호하게 지키고, 백색소음으로 방을 차분하게 해 주세요.', title_nl = 'Ontsnappen uit bed 🏃‍♂️', body_nl = '''Geef water'', ''Zoek mijn knuffel''... De smoesjes van een 3-jarige om niet te gaan slapen houden nooit op. Zet de Slaaptimer aan, bewaak je grenzen vastberaden en breng rust in de kamer met Witte ruis.', title_pl = 'Ucieczka z łóżka 🏃‍♂️', body_pl = '„Daj wody”, „Znajdź moją zabawkę”... Wymówki 3-latka, żeby nie zasnąć, nie mają końca. Włącz timer snu, stanowczo pilnuj granic i wycisz pokój Białym szumem.', title_pt = 'Fuga da cama 🏃‍♂️', body_pt = '"Dá-me água", "Encontra o meu brinquedo"... As desculpas dos 3 anos para não adormecer nunca acabam. Ligue o temporizador de sono, defenda os limites com firmeza e acalme o quarto com o Ruído Branco.', title_sv = 'Flykt från sängen 🏃‍♂️', body_sv = '”Ge mig vatten”, ”Hitta min leksak”... 3-åringens ursäkter för att slippa somna tar aldrig slut. Starta sömntimern, håll bestämt fast vid gränserna och lugna rummet med Vitt brus.', title_vi = 'Trốn khỏi giường 🏃‍♂️', body_vi = '"Cho con nước", "Tìm đồ chơi cho con"... Lý do để không ngủ của tuổi lên 3 chẳng bao giờ hết. Hãy bật Bộ hẹn giờ ngủ, kiên quyết giữ vững giới hạn và làm dịu căn phòng bằng Tiếng ồn trắng.', title_zh = '从床上逃跑 🏃‍♂️', body_zh = '“给我水”“帮我找玩具”……为了不睡觉，3岁的借口永远说不完。打开睡眠计时器，坚定地守住边界，再用白噪音让房间安静下来。' WHERE id = '487012f7-5a3f-49e2-9f9d-2533c14f18c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño que escribe epopeyas 🗣️', body_es = '¿Ya junta palabras e inventa historias imaginarias y guiones fantásticos? No te pierdas esta maravillosa explosión del lenguaje: grábala enseguida como recuerdo de voz e inmortalízala en el Álbum del bebé.', title_fr = 'Le petit conteur d''épopées 🗣️', body_fr = 'Il assemble déjà les mots pour inventer des histoires imaginaires et des scénarios fantastiques ? Ne manquez pas cette formidable explosion du langage : enregistrez tout de suite un souvenir sonore et immortalisez-le dans l''Album de bébé.', title_hi = 'कहानियाँ गढ़ने वाला नन्हा 🗣️', body_hi = 'अब शब्द जोड़कर काल्पनिक कहानियाँ, फ़ैंटेसी किस्से गढ़ता है? बोली के इस शानदार विस्फोट को चूके बिना तुरंत आवाज़ में रिकॉर्ड कीजिए और बेबी एल्बम में हमेशा के लिए सँजो लीजिए।', title_id = 'Si kecil penulis hikayat 🗣️', body_id = 'Ia sudah merangkai kata menjadi cerita khayalan dan skenario fantastis? Jangan lewatkan ledakan bahasa yang luar biasa ini, segera rekam sebagai memo suara dan abadikan di Album Bayi.', title_ja = '物語をつくる小さな作家 🗣️', body_ja = 'もう言葉をつなげて、空想のお話やファンタジーのシナリオをつくっている？このすばらしい言葉の爆発を見逃さず、すぐに音声で記録して、「ベビーアルバム」に残しましょう。', title_ko = '이야기를 짓는 꼬마 🗣️', body_ko = '벌써 단어를 이어 상상 속 이야기와 환상적인 시나리오를 지어내나요? 이 멋진 언어 폭발을 놓치지 말고 바로 음성으로 녹음해 아기 앨범에 영원히 남겨 두세요.', title_nl = 'Kleine verhalenverteller 🗣️', body_nl = 'Plakt hij al woorden aan elkaar en verzint hij denkbeeldige verhalen en fantastische scenario''s? Mis deze geweldige taalexplosie niet: neem het meteen op als spraakmemo en leg het voor altijd vast in het Babyalbum.', title_pl = 'Mały twórca opowieści 🗣️', body_pl = 'Już łączy słowa i wymyśla wyimaginowane historie i fantastyczne scenariusze? Nie przegap tej wspaniałej eksplozji językowej, od razu nagraj ją jako notatkę głosową i uwiecznij w Albumie dziecka.', title_pt = 'O pequeno contador de epopeias 🗣️', body_pt = 'Já junta palavras e inventa histórias imaginárias e enredos fantásticos? Não perca esta explosão fantástica da linguagem: grave-a já com som e eternize-a no Álbum do Bebé.', title_sv = 'Den lilla berättaren 🗣️', body_sv = 'Sätter barnet redan ihop ord till låtsashistorier och fantastiska scenarier? Missa inte den fantastiska språkexplosionen, spela genast in den som ett ljudminne och förevige den i Babyalbumet.', title_vi = 'Người kể chuyện tí hon 🗣️', body_vi = 'Bé đã biết ghép từ để nghĩ ra những câu chuyện tưởng tượng, những kịch bản kỳ ảo? Đừng bỏ lỡ sự bùng nổ ngôn ngữ tuyệt vời này, hãy ghi âm ngay và lưu giữ mãi mãi trong Album của bé.', title_zh = '会编故事的小家伙 🗣️', body_zh = '已经会把词语串起来，编出想象中的故事和奇幻的剧本了？别错过这场精彩的语言大爆发，马上录成有声回忆，永远保存在宝宝相册里吧。' WHERE id = '543ac832-5997-4074-94fa-e27c0915dc20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para unos huesos que crecen deprisa, el calcio es imprescindible. ¿No bebe leche? Calcula sin falta hoy con el Seguimiento de tomas cuánto queso, yogur o brócoli ha tomado.', body_fr = 'Le calcium est indispensable à des os qui grandissent vite. Il ne boit pas de lait ? Calculez absolument aujourd''hui ses apports en fromage, yaourt ou brocoli avec le Suivi des repas.', body_hi = 'तेज़ी से बढ़ती हड्डियों के लिए कैल्शियम ज़रूरी है। दूध नहीं पीता? फ़ीडिंग ट्रैकर से आज का पनीर, दही या ब्रोकली ज़रूर गिनिए।', body_id = 'Kalsium wajib untuk tulang yang tumbuh cepat. Ia tidak mau minum susu? Pastikan hari ini menghitung asupan keju, yogurt, atau brokoli dengan Pemantau Nutrisi.', body_ja = 'ぐんぐん伸びる骨にはカルシウムが欠かせません。牛乳を飲まない？「栄養管理ツール」で、今日のチーズ、ヨーグルト、ブロッコリーの量をしっかり計算しましょう。', body_ko = '빠르게 자라는 뼈에는 칼슘이 꼭 필요해요. 우유를 안 마시나요? 수유 기록 도구로 오늘 치즈, 요거트, 브로콜리 섭취량을 꼭 계산해 보세요.', body_nl = 'Calcium is onmisbaar voor snelgroeiende botten. Drinkt hij geen melk? Bereken vandaag met de Voedingstracker zeker hoeveel kaas, yoghurt of broccoli hij binnenkrijgt.', body_pl = 'Dla szybko rosnących kości wapń jest niezbędny. Nie pije mleka? Koniecznie policz dziś w narzędziu do śledzenia karmienia, ile zjadł sera, jogurtu albo brokułów.', body_pt = 'Para ossos que crescem depressa, o cálcio é essencial. Não bebe leite? Não deixe de calcular hoje, com o Registo de Alimentação, o consumo de queijo, iogurte ou brócolos.', body_sv = 'Kalcium är ett måste för skelett som växer snabbt. Dricker barnet inte mjölk? Räkna absolut ut dagens intag av ost, yoghurt eller broccoli med verktyget Matningskoll.', body_vi = 'Canxi là điều kiện cần cho xương đang phát triển nhanh. Bé không uống sữa? Hôm nay hãy nhớ tính lượng phô mai, sữa chua hoặc bông cải xanh bé ăn bằng Theo dõi cữ bú.', body_zh = '快速生长的骨骼离不开钙。不肯喝奶？今天一定要用喂养记录工具算一算奶酪、酸奶或西兰花的摄入量。' WHERE id = '75d14b5e-1909-445c-9146-d6cc02f1b594' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pausa de mamá ☕', title_fr = 'La pause de maman ☕', title_hi = 'माँ का ब्रेक ☕', title_id = 'Waktu rehat Ibu ☕', title_ja = 'ママの休憩時間 ☕', title_ko = '엄마의 휴식 시간 ☕', title_nl = 'Pauze voor mama ☕', title_pl = 'Przerwa dla mamy ☕', title_pt = 'A pausa da mãe ☕', title_sv = 'Mammas paus ☕', title_vi = 'Giờ nghỉ của mẹ ☕', title_zh = '妈妈的休息时间 ☕' WHERE id = '4b47f634-fca5-4f0e-a391-d61c2ad9b71e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite a primera hora 🙈', body_es = 'Llegas tarde al trabajo o a la guardería y él se esconde detrás de la cortina diciendo: «¡Encuéntrame!». Aunque tengas los nervios a flor de piel, gritar alargará aún más el proceso. Únete 2 minutos al juego: «¿Dónde estará mi niño tan bonito?», encuéntrale y sácale de ahí.', title_fr = 'Cache-cache au petit matin 🙈', body_fr = 'Vous êtes en retard pour le travail ou la crèche, et lui se cache derrière le rideau en disant « Trouve-moi ! ». Même si vos nerfs sont à vif, crier ne fera que rallonger les choses. Entrez 2 minutes dans le jeu, « Mais où est passé mon beau bébé ? », puis trouvez-le et sortez-le de là.', title_hi = 'सुबह-सुबह छुपन-छुपाई 🙈', body_hi = 'आपको काम या प्ले स्कूल के लिए देर हो रही है, और वह पर्दे के पीछे छिपकर कहता है, ‘मुझे ढूँढो!’ नसें तनी हों, फिर भी चिल्लाने से काम और लंबा खिंचेगा। ‘मेरा प्यारा बच्चा कहाँ है?’ कहकर 2 मिनट खेल में शामिल होइए और उसे ढूँढकर बाहर निकाल लीजिए।', title_id = 'Petak umpet pagi-pagi 🙈', body_id = 'Anda terlambat ke kantor atau TK, sementara ia bersembunyi di balik gorden dan berkata ''Cari aku!''. Meski saraf Anda menegang, berteriak hanya akan membuat semuanya makin lama. Ikutlah bermain 2 menit: ''Di mana ya anak Mama yang cantik?'', temukan ia dan bawa keluar.', title_ja = '朝からかくれんぼ 🙈', body_ja = '仕事や保育園に遅れそうなのに、カーテンの後ろに隠れて「見つけて！」と言う。神経がピンと張りつめても、叫べばよけいに長引きます。「わたしのかわいい子はどこかな？」と2分だけ遊びに乗って、見つけて連れ出しましょう。', title_ko = '아침 숨바꼭질 🙈', body_ko = '출근이나 어린이집에 늦었는데 커튼 뒤에 숨어 ''나 찾아 봐!''라고 하나요? 신경이 곤두서도 소리치면 시간만 더 걸려요. 2분만 놀이에 함께하며 ''우리 예쁜 아기 어디 있지?'' 하고 찾아서 데리고 나오세요.', title_nl = 'Verstoppertje in de ochtend 🙈', body_nl = 'Jullie zijn te laat voor werk of opvang, en hij verstopt zich achter het gordijn: ''Zoek me!'' Ook al staan je zenuwen strak gespannen, schreeuwen maakt het alleen maar langer. Doe 2 minuten mee met ''Waar is mijn mooie kindje nou?'', vind hem en haal hem tevoorschijn.', title_pl = 'Poranna zabawa w chowanego 🙈', body_pl = 'Spóźniacie się do pracy albo przedszkola, a on chowa się za zasłoną i woła „Znajdź mnie!”. Choć nerwy masz napięte do granic, krzyk tylko wszystko przedłuży. Dołącz do zabawy na 2 minuty: „Gdzie jest mój śliczny skarb?”, znajdź go i wyprowadź.', title_pt = 'Escondidas logo de manhã 🙈', body_pt = 'Está atrasada para o trabalho ou para o jardim de infância e ele escondeu-se atrás da cortina: "Encontra-me!". Mesmo com os nervos em franja, gritar só vai prolongar tudo. Entre no jogo 2 minutos, "Onde estará o meu menino lindo?", encontre-o e tire-o de lá.', title_sv = 'Kurragömma tidigt på morgonen 🙈', body_sv = 'Ni är sena till jobbet eller förskolan, och barnet gömmer sig bakom gardinen och säger ”Hitta mig!”. Även om nerverna är på helspänn förlänger skrik bara det hela. Säg ”Undrar var min fina lilla är?”, var med i leken i 2 minuter, hitta barnet och ta fram det.', title_vi = 'Trốn tìm buổi sáng 🙈', body_vi = 'Mẹ đang trễ giờ làm hoặc giờ đi mầm non, còn bé trốn sau rèm cửa và nói "Mẹ tìm con đi!". Dù mẹ căng như dây đàn, quát mắng chỉ khiến mọi việc kéo dài hơn. Hãy tham gia trò chơi 2 phút: "Bé cưng xinh đẹp của mẹ đâu rồi nhỉ?" rồi tìm thấy và đưa bé ra.', title_zh = '一大早玩捉迷藏 🙈', body_zh = '你上班或送幼儿园已经要迟到了，宝宝却躲在窗帘后面喊“来找我！”。虽然你的神经已经绷紧了，但吼叫只会让事情拖得更久。说一句“我漂亮的小宝贝在哪儿呢？”，花2分钟加入游戏，把宝宝找出来吧。' WHERE id = '577db9f8-8f80-4ad0-9e5c-4fd106adca75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Separar la comida por colores 🍅', body_es = 'Separa la comida del plato por colores y formas y empuja lo verde a un lado. Entra en el Plan de alimentación. Descubre cómo convertir esas verduras en un puré invisible y esconderlas en salsas ricas, y gana este juego a escondidas.', title_fr = 'Trier la nourriture par couleur 🍅', body_fr = 'Il trie les aliments de son assiette par couleur et par forme, et pousse les verts sur le côté. Ouvrez le Plan de nutrition. Gagnez discrètement cette partie en découvrant comment transformer ces légumes en purée invisible à cacher dans de délicieuses sauces.', title_hi = 'खाना रंग के हिसाब से अलग करना 🍅', body_hi = 'प्लेट का खाना रंग और आकार के हिसाब से अलग करता है, और हरी चीज़ें एक तरफ़ सरका देता है। फ़ीडिंग प्लान खोलिए। जानिए कि उन सब्ज़ियों की अदृश्य प्यूरी बनाकर स्वादिष्ट सॉस में कैसे छिपाएँ, और इस खेल में चुपके से जीत जाइए।', title_id = 'Memisahkan makanan berdasarkan warna 🍅', body_id = 'Ia memisahkan makanan di piring berdasarkan warna dan bentuknya, lalu mendorong yang hijau ke pinggir. Buka Rencana Nutrisi. Menangkan permainan ini diam-diam dengan menemukan cara menghaluskan sayur hingga tak terlihat dan menyembunyikannya dalam saus yang lezat.', title_ja = '食べ物を色で分ける 🍅', body_ja = 'お皿の料理を色や形で分けて、緑のものは脇に押しやっている。「栄養管理ツール」を開いてみましょう。野菜を見えないピューレにして、おいしいソースに隠す方法を見つけて、このゲームにこっそり勝ちましょう。', title_ko = '음식 색깔별로 나누기 🍅', body_ko = '접시 위 음식을 색깔과 모양별로 나누고 초록색은 옆으로 밀어내나요? 식단 계획에 들어가 보세요. 채소를 감쪽같은 퓌레로 만들어 맛있는 소스에 숨기는 법을 찾아 이 게임에서 몰래 이기세요.', title_nl = 'Eten sorteren op kleur 🍅', body_nl = 'Hij sorteert het eten op zijn bord op kleur en vorm en schuift alles wat groen is aan de kant. Open het Voedingsplan. Win dit spel stiekem door te ontdekken hoe je die groenten onzichtbaar pureert en in lekkere sausjes verstopt.', title_pl = 'Sortowanie jedzenia według kolorów 🍅', body_pl = 'Rozdziela jedzenie na talerzu według kolorów i kształtów, a zielone odsuwa na bok. Zajrzyj do planu karmienia. Odkryj, jak zamienić te warzywa w niewidzialne purée i ukryć je w pysznych sosach, i po cichu wygraj tę grę.', title_pt = 'Separar a comida pela cor 🍅', body_pt = 'Separa a comida do prato por cores e formas e empurra o que é verde para o lado. Entre no Registo de Alimentação. Descubra como transformar esses legumes num puré invisível e escondê-los em molhos saborosos, e ganhe este jogo às escondidas.', title_sv = 'Sortera maten efter färg 🍅', body_sv = 'Barnet sorterar maten på tallriken efter färg och form och skjuter de gröna bitarna åt sidan. Gå in i matplanen. Vinn leken i smyg genom att upptäcka hur du gör grönsakerna till osynligt mos och gömmer dem i goda såser.', title_vi = 'Phân loại thức ăn theo màu sắc 🍅', body_vi = 'Bé phân loại thức ăn trên đĩa theo màu sắc và hình dạng, còn những thứ màu xanh thì đẩy ra một bên. Hãy vào Kế hoạch dinh dưỡng. Khám phá cách xay rau thành dạng nhuyễn "vô hình" để giấu vào những món sốt ngon lành và âm thầm chiến thắng trò chơi này.', title_zh = '按颜色分开吃 🍅', body_zh = '把盘子里的食物按颜色和形状分开，绿色的全推到一边。去喂养计划里看看，学会把那些蔬菜做成看不见的泥，藏进美味的酱汁里，悄悄赢下这场游戏吧。' WHERE id = '61996b98-7da4-41e9-be9f-afe630090cfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro descansa poco a poco y cómo te masajea este silencio visual.', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau se reposer peu à peu et ce silence visuel vous masser.', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे आराम पा रहा है और यह दिखती खामोशी कैसे आपकी मसाज करती है।', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan bagaimana otak Anda perlahan beristirahat dan keheningan visual ini memijat Anda.', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ休まっていくのを、この目に見える静けさがマッサージしてくれるのを感じてみましょう。', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬고, 이 시각적인 고요가 마사지해 주는 걸 느껴 보세요.', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam tot rust komt en hoe deze visuele stilte je masseert.', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli odpoczywa, a ta wizualna cisza robi ci masaż.', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta o seu cérebro a descansar devagarinho e este silêncio visual a fazer-lhe uma massagem.', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen. Känn hur hjärnan sakta vilar och hur den visuella tystnaden masserar dig.', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần được nghỉ ngơi, sự tĩnh lặng hiện ra trước mắt đang mát-xa cho mẹ thế nào.', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，感受大脑正在一点点休息下来，这份看得见的安静又是怎样给你做按摩的。' WHERE id = '01916001-64ad-41ab-8fea-1c1101a3ae1c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tesoros que salen del bolsillo 🪨', body_es = '¿Al lavar su pantalón han salido del bolsillo 2 piedras, una hoja seca y un palito a medias? Lo que para ti es basura es para él una colección valiosa con la que descubre el universo. En lugar de tirarlas, guárdalas en una cajita del tesoro.', title_fr = 'Les trésors des poches 🪨', body_fr = 'En lavant son pantalon, vous avez trouvé dans sa poche 2 cailloux, une feuille séchée et un bout de brindille ? Ces objets qui sont des déchets pour vous forment sa précieuse collection d''explorateur de l''univers. Au lieu de les jeter, rangez-les dans une petite boîte à trésors.', title_hi = 'जेब से निकले खज़ाने 🪨', body_hi = 'पैंट धोते समय उसकी जेब से 2 पत्थर, एक सूखा पत्ता और आधी टहनी निकली? आपके लिए जो कचरा है, वह उसके लिए दुनिया की खोज का कीमती संग्रह है। इन्हें फेंकने के बजाय एक छोटे खज़ाने के डिब्बे में रखिए।', title_id = 'Harta karun dari saku 🪨', body_id = 'Saat mencuci celananya, dari saku keluar 2 batu, sehelai daun kering, dan ranting patah? Benda yang bagi Anda sampah ini adalah koleksi berharganya saat menjelajahi alam semesta. Daripada membuangnya, kumpulkan di kotak harta karun kecil.', title_ja = 'ポケットから出てきた宝物 🪨', body_ja = 'ズボンを洗おうとしたら、ポケットから石が2つ、枯れ葉が1枚、折れた小枝が出てきた？あなたにはゴミでも、この子にとっては宇宙を発見した大切なコレクションです。捨てる代わりに、小さな宝箱に集めてあげましょう。', title_ko = '주머니 속 보물 🪨', body_ko = '바지를 빨려는데 주머니에서 돌 2개, 마른 나뭇잎, 부러진 나뭇가지가 나왔나요? 엄마에겐 쓰레기지만 아이에겐 우주를 탐험하며 모은 귀한 수집품이에요. 버리는 대신 작은 보물 상자에 모아 주세요.', title_nl = 'Schatten uit de broekzak 🪨', body_nl = 'Kwamen er bij het wassen van zijn broek 2 steentjes, een droog blaadje en een half takje uit zijn zak? Wat voor jou afval is, is voor hem een waardevolle verzameling waarmee hij het universum ontdekt. Gooi ze niet weg, maar bewaar ze in een kleine schatkist.', title_pl = 'Skarby z kieszeni 🪨', body_pl = 'Podczas prania spodni wyjęłaś z kieszeni 2 kamyki, suchy liść i złamany patyczek? Te rzeczy, które dla ciebie są śmieciami, to jego cenna kolekcja z odkrywania wszechświata. Zamiast je wyrzucać, włóż je do małego pudełka na skarby.', title_pt = 'Tesouros que saem dos bolsos 🪨', body_pt = 'Ao lavar as calças, saíram do bolso 2 pedras, uma folha seca e um pauzinho partido? Estes objetos, que para si são lixo, são a coleção valiosa com que ele descobre o universo. Em vez de os deitar fora, guarde-os numa pequena caixa do tesouro.', title_sv = 'Skatter ur fickorna 🪨', body_sv = 'När du tvättade byxorna hittade du 2 stenar, ett torkat löv och en halv pinne i fickan? Det som för dig är skräp är barnets värdefulla samling från upptäckten av universum. Istället för att slänga sakerna, lägg dem i en liten skattlåda.', title_vi = 'Kho báu trong túi quần 🪨', body_vi = 'Khi giặt quần cho bé, mẹ lôi ra 2 viên sỏi, một chiếc lá khô và một que củi gãy? Những thứ với mẹ là rác ấy lại là bộ sưu tập quý giá khi bé khám phá vũ trụ. Thay vì vứt đi, hãy gom chúng vào một hộp kho báu nhỏ.', title_zh = '口袋里掏出的宝藏 🪨', body_zh = '洗裤子时，从口袋里掏出2块石头、一片干树叶和半截小木棍？在你看来是垃圾的东西，却是宝宝探索宇宙的珍贵收藏。别扔掉，把它们收进一个小小的宝藏盒里吧。' WHERE id = '95ce868b-b982-4c4e-baa7-7ca7cd3520b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Misión cerrar puertas 🚪', title_fr = 'Mission : fermer les portes 🚪', title_hi = 'दरवाज़ा बंद करने का मिशन 🚪', title_id = 'Misi mengunci pintu 🚪', title_ja = 'ドアのカギかけミッション 🚪', title_ko = '문 잠그기 미션 🚪', title_nl = 'Missie deuren op slot 🚪', title_pl = 'Misja zamykania drzwi 🚪', title_pt = 'Missão trancar portas 🚪', title_sv = 'Uppdrag: lås dörren 🚪', title_vi = 'Nhiệm vụ khóa cửa 🚪', title_zh = '锁门任务 🚪' WHERE id = '97aa3207-a7a2-42a1-9e74-01d2388db3b1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La paz del silencio 🤫', body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro descansa poco a poco y cómo te masajea este silencio visual.', title_fr = 'La paix du silence 🤫', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau se reposer peu à peu et ce silence visuel vous masser.', title_hi = 'खामोशी का सुकून 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे आराम पा रहा है और यह दिखती खामोशी कैसे आपकी मसाज करती है।', title_id = 'Damainya keheningan 🤫', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan bagaimana otak Anda perlahan beristirahat dan keheningan visual ini memijat Anda.', title_ja = '静けさのやすらぎ 🤫', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ休まっていくのを、この目に見える静けさがマッサージしてくれるのを感じてみましょう。', title_ko = '고요의 평온 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬고, 이 시각적인 고요가 마사지해 주는 걸 느껴 보세요.', title_nl = 'De rust van stilte 🤫', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam tot rust komt en hoe deze visuele stilte je masseert.', title_pl = 'Spokój ciszy 🤫', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli odpoczywa, a ta wizualna cisza robi ci masaż.', title_pt = 'A paz do silêncio 🤫', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta o seu cérebro a descansar devagarinho e este silêncio visual a fazer-lhe uma massagem.', title_sv = 'Tystnadens frid 🤫', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen. Känn hur hjärnan sakta vilar och hur den visuella tystnaden masserar dig.', title_vi = 'Bình yên của sự tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần được nghỉ ngơi, sự tĩnh lặng hiện ra trước mắt đang mát-xa cho mẹ thế nào.', title_zh = '安静的宁静 🤫', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，感受大脑正在一点点休息下来，这份看得见的安静又是怎样给你做按摩的。' WHERE id = 'a910e33f-005d-4ed1-a228-647503e47993' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte del papel higiénico 🧻', body_es = 'Unos minutos de silencio... ¡Y al entrar en la habitación ves todo el papel higiénico desenrollado por la casa! En lugar de enfadarte, recoged el papel y haced juntos un muñeco de nieve o una pelota. Vence al caos no con gritos, sino con creatividad.', title_fr = 'L''art du papier toilette 🧻', body_fr = 'Quelques minutes de silence... Et en entrant dans la pièce, vous découvrez tout le rouleau de papier toilette déroulé à travers la maison ! Au lieu de vous énerver, ramassez le papier et faites ensemble un bonhomme de neige ou une balle. Battez le chaos non pas en criant, mais par la créativité.', title_hi = 'टॉयलेट पेपर की कला 🧻', body_hi = 'कुछ मिनट की खामोशी... और कमरे में जाकर देखती हैं कि पूरा टॉयलेट पेपर खुलकर घर में फैला है! नाराज़ होने के बजाय वह कागज़ इकट्ठा करके साथ में स्नोमैन या गेंद बनाइए। अफ़रा-तफ़री को चिल्लाकर नहीं, रचनात्मकता से जीतिए।', title_id = 'Seni tisu toilet 🧻', body_id = 'Beberapa menit hening... Lalu saat masuk kamar, Anda melihat seluruh tisu toilet terurai dan tersebar di rumah! Daripada kesal, kumpulkan tisu itu dan buatlah boneka salju atau bola bersama. Kalahkan kekacauan dengan kreativitas, bukan dengan berteriak.', title_ja = 'トイレットペーパーアート 🧻', body_ja = '数分間の静けさ…。そして部屋に入ると、トイレットペーパーが全部ほどかれて家じゅうに広がっていた！怒るより、紙を集めて一緒に雪だるまやボールを作りましょう。カオスには、叫び声ではなくクリエイティブに勝つんです。', title_ko = '휴지 예술 🧻', body_ko = '몇 분간의 고요... 그리고 방에 들어가 보니 휴지가 다 풀려 온 집에 퍼져 있나요? 화내는 대신 휴지를 모아 함께 눈사람이나 공을 만들어 보세요. 혼돈은 소리치기가 아니라 창의력으로 이겨요.', title_nl = 'Wc-papierkunst 🧻', body_nl = 'Een paar minuten stilte... En als je de kamer binnenkomt, is de hele rol wc-papier afgerold en door het huis verspreid! Word niet boos, maar verzamel het papier en maak er samen een sneeuwpop of een bal van. Versla chaos niet met schreeuwen, maar met creativiteit.', title_pl = 'Sztuka z papieru toaletowego 🧻', body_pl = 'Kilka minut ciszy... A gdy wchodzisz do pokoju, widzisz cały papier toaletowy rozwinięty po domu! Zamiast się denerwować, zbierzcie papier i ulepcie razem bałwana albo kulę. Pokonaj chaos nie krzykiem, a kreatywnością.', title_pt = 'A arte do papel higiénico 🧻', body_pt = 'Uns minutos de silêncio... E ao entrar no quarto vê o rolo de papel higiénico todo desenrolado e espalhado pela casa! Em vez de se irritar, apanhem o papel e façam juntos um boneco de neve ou uma bola. Vença o caos não com gritos, mas com criatividade.', title_sv = 'Toalettpapperskonst 🧻', body_sv = 'Några minuters tystnad... Och när du kommer in i rummet ser du att hela toalettpappersrullen är upprullad och utspridd i hemmet! Istället för att bli arg, samla ihop pappret och gör en snögubbe eller en boll tillsammans. Besegra kaoset med kreativitet, inte med skrik.', title_vi = 'Nghệ thuật giấy vệ sinh 🧻', body_vi = 'Vài phút im lặng... Và khi bước vào phòng, mẹ thấy cả cuộn giấy vệ sinh đã bị kéo tung khắp nhà! Thay vì bực mình, hãy gom chỗ giấy đó lại và cùng bé làm người tuyết hoặc quả bóng. Hãy chiến thắng sự hỗn loạn bằng sáng tạo, không phải bằng tiếng quát.', title_zh = '卫生纸艺术 🧻', body_zh = '几分钟的安静……走进房间才发现，整卷卫生纸都被拉开铺满了家！与其生气，不如把纸收起来，一起堆个雪人或团个球。战胜混乱靠的不是吼，而是创意。' WHERE id = '2f583ff5-e2c4-4fbb-acdc-470ccf241970' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo la lavadora 🧺', title_fr = 'La découverte de la machine à laver 🧺', title_hi = 'वॉशिंग मशीन की खोज 🧺', title_id = 'Penemuan mesin cuci 🧺', title_ja = '洗濯機の発見 🧺', title_ko = '세탁기의 발견 🧺', title_nl = 'De wasmachine ontdekken 🧺', title_pl = 'Odkrycie pralki 🧺', title_pt = 'A descoberta da máquina de lavar 🧺', title_sv = 'Upptäckten av tvättmaskinen 🧺', title_vi = 'Khám phá máy giặt 🧺', title_zh = '发现洗衣机 🧺' WHERE id = '6ae9e7b9-b61e-4945-82bd-3ceb19652949' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Palabras de amor susurradas al oído 💖', body_es = 'Te ha vuelto loca todo el día y se ha empeñado en todo. Pero ahora duerme en la cama tan inocente... Túmbate a su lado y susúrrale al oído cuánto le quieres y las cosas buenas que ha hecho hoy. Los niños sienten la voz llena de amor de mamá incluso dormidos.', title_fr = 'Des mots d''amour chuchotés à l''oreille 💖', body_fr = 'Il vous a rendue folle toute la journée et s''est entêté sur tout. Mais maintenant, il dort si innocemment dans son lit... Allongez-vous près de lui et chuchotez-lui à l''oreille combien vous l''aimez et les belles choses qu''il a faites aujourd''hui. Même endormis, les enfants sentent la voix aimante de leur maman.', title_hi = 'कान में फुसफुसाए प्यार भरे शब्द 💖', body_hi = 'उसने दिनभर आपको परेशान किया, हर बात पर ज़िद की। पर अब बिस्तर में इतना मासूम सोया है... उसके पास लेटिए और उसके कान में फुसफुसाइए कि आप उसे कितना प्यार करती हैं और आज उसने क्या-क्या अच्छे काम किए। बच्चे नींद में भी माँ की प्यार भरी आवाज़ महसूस करते हैं।', title_id = 'Kata-kata cinta yang dibisikkan 💖', body_id = 'Seharian ia membuat Anda hampir gila dan membangkang dalam segala hal. Tapi kini ia tidur begitu polos... Berbaringlah di sampingnya dan bisikkan ke telinganya betapa Anda menyayanginya dan hal-hal baik yang ia lakukan hari ini. Bahkan dalam tidur, anak bisa merasakan suara ibu yang penuh cinta.', title_ja = '耳もとでささやく愛の言葉 💖', body_ja = '一日じゅう振りまわされて、何にでも意地をはっていたのに、今はベッドでこんなにあどけなく眠っています…。そばに横になって、どれほど愛しているか、今日したいいことを耳もとでささやいてあげましょう。子どもは眠っていても、ママの愛情たっぷりの声を感じています。', title_ko = '귓가에 속삭이는 사랑의 말 💖', body_ko = '하루 종일 엄마를 미치게 하고 모든 일에 고집을 부렸죠. 그런데 지금 침대에서 이렇게 순하게 자고 있어요... 옆에 누워 얼마나 사랑하는지, 오늘 잘한 일들을 귓가에 속삭여 주세요. 아이들은 자면서도 엄마의 사랑 가득한 목소리를 느껴요.', title_nl = 'Lieve woordjes in zijn oor 💖', body_nl = 'Hij heeft je de hele dag gek gemaakt en was overal koppig in. Maar nu ligt hij zo onschuldig in bed... Ga naast hem liggen en fluister in zijn oor hoeveel je van hem houdt en welke goede dingen hij vandaag deed. Kinderen voelen zelfs in hun slaap de liefdevolle stem van hun mama.', title_pl = 'Słowa miłości szeptane do ucha 💖', body_pl = 'Cały dzień doprowadzał cię do szału i się upierał. Ale teraz śpi w łóżku tak niewinnie... Połóż się obok i wyszeptaj mu do ucha, jak bardzo go kochasz i co dobrego dziś zrobił. Dzieci nawet we śnie czują pełen miłości głos mamy.', title_pt = 'Palavras de amor sussurradas ao ouvido 💖', body_pt = 'Passou o dia todo a deixá-la louca e a teimar com tudo. Mas agora dorme na cama com um ar tão inocente... Deite-se ao lado dele e sussurre-lhe ao ouvido o quanto o ama e as coisas boas que fez hoje. Mesmo a dormir, as crianças sentem a voz carinhosa da mãe.', title_sv = 'Kärleksord viskade i örat 💖', body_sv = 'Barnet har gjort dig galen hela dagen och varit envist med allt. Men nu ligger det så oskyldigt i sängen... Lägg dig bredvid och viska i barnets öra hur mycket du älskar det och om de fina saker det gjorde i dag. Barn känner mammas kärleksfulla röst även i sömnen.', title_vi = 'Lời yêu thương thì thầm bên tai 💖', body_vi = 'Cả ngày bé làm mẹ phát điên, bướng bỉnh với mọi thứ. Nhưng giờ bé ngủ say trên giường thật ngây thơ... Hãy nằm cạnh bé và thì thầm vào tai bé rằng mẹ yêu bé nhường nào, kể những điều tốt bé đã làm hôm nay. Ngay cả trong giấc ngủ, trẻ vẫn cảm nhận được giọng nói đầy yêu thương của mẹ.', title_zh = '在耳边悄悄说的情话 💖', body_zh = '宝宝把你折腾了一整天，什么都要犟。可现在在床上睡得那么天真……躺在宝宝身边，在耳边悄悄告诉宝宝你有多爱宝宝，以及宝宝今天做的那些好事。孩子们哪怕在睡梦中，也能感受到妈妈充满爱的声音。' WHERE id = 'c8193b18-f83a-473a-bda3-5d573d734271' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El golpe del «¡No me escuchas!» 😠', body_es = 'Mientras miras el móvil o remueves la comida, viene y te gira la cara hacia él: «¡Mírame!». Tiene razón. No quiere tu presencia física, sino tu atención completa. Deja lo que estés haciendo y escúchale solo 3 minutos con contacto visual pleno.', title_fr = 'L''attaque du « Tu m''écoutes pas ! » 😠', body_fr = 'Pendant que vous regardez votre téléphone ou remuez le repas, il vient tourner votre visage vers lui : « Regarde-moi ! » Il a raison. Il ne veut pas votre présence physique, mais toute votre attention. Arrêtez ce que vous faites et écoutez-le juste 3 minutes en le regardant vraiment dans les yeux.', title_hi = '‘तुम मेरी नहीं सुनतीं!’ वाला वार 😠', body_hi = 'आप फ़ोन देख रही हैं या खाना चला रही हैं, और वह आकर आपका चेहरा अपनी ओर घुमाता है: ‘मुझे देखो!’ वह सही है। उसे आपकी मौजूदगी नहीं, आपका पूरा ध्यान चाहिए। काम रोकिए और सिर्फ़ 3 मिनट पूरी तरह आँख मिलाकर उसे सुनिए।', title_id = 'Ledakan ''Mama nggak dengar aku!'' 😠', body_id = 'Saat Anda melihat ponsel atau mengaduk masakan, ia datang dan memalingkan wajah Anda ke arahnya: ''Lihat aku!''. Ia benar. Ia tidak menginginkan kehadiran fisik Anda, melainkan perhatian Anda yang utuh. Hentikan pekerjaan dan dengarkan ia hanya 3 menit dengan kontak mata penuh.', title_ja = '「聞いてないでしょ！」の一撃 😠', body_ja = 'スマホを見たり料理をまぜたりしていると、やってきてあなたの顔を自分のほうへ向けます：「こっち見て！」その通りです。そばにいることではなく、まるごとの注目がほしいんです。手を止めて、3分だけしっかり目を合わせて聞いてあげましょう。', title_ko = '''엄마 내 말 안 듣잖아!'' 폭발 😠', body_ko = '엄마가 휴대폰을 보거나 음식을 저을 때 와서 얼굴을 자기 쪽으로 돌리며 ''나 봐!''라고 하나요? 아이가 옳아요. 몸만 곁에 있는 엄마가 아니라 온전한 관심을 원하는 거예요. 하던 일을 멈추고 딱 3분만 눈을 맞추며 들어 주세요.', title_nl = 'De ''Je luistert niet naar me!''-uitval 😠', body_nl = 'Terwijl jij op je telefoon kijkt of in een pan roert, komt hij je gezicht naar zich toe draaien: ''Kijk naar mij!'' Hij heeft gelijk. Hij wil niet alleen dat je er bent, hij wil je onverdeelde aandacht. Stop met wat je doet en luister 3 minuten naar hem met volledig oogcontact.', title_pl = 'Cios „Nie słuchasz mnie!” 😠', body_pl = 'Gdy patrzysz w telefon albo mieszasz w garnku, podchodzi i odwraca twoją twarz do siebie: „Patrz na mnie!”. Ma rację. Nie chce twojej fizycznej obecności, tylko niepodzielnej uwagi. Przerwij to, co robisz, i choć przez 3 minuty słuchaj go z pełnym kontaktem wzrokowym.', title_pt = 'O golpe do "Não me estás a ouvir!" 😠', body_pt = 'Enquanto olha para o telemóvel ou mexe a comida, ele vem e vira-lhe a cara para ele: "Olha para mim!". Tem razão. Não quer a sua presença física, quer a sua atenção total. Pare o que está a fazer e ouça-o só 3 minutos, com contacto visual total.', title_sv = 'Smällen ”Du hör inte vad jag säger!” 😠', body_sv = 'Medan du tittar på telefonen eller rör i grytan kommer barnet och vänder ditt ansikte mot sig: ”Titta på mig!” Barnet har rätt. Det vill inte ha din fysiska närvaro, utan din odelade uppmärksamhet. Avbryt det du gör och lyssna på barnet med full ögonkontakt i bara 3 minuter.', title_vi = 'Cú "Mẹ không nghe con nói!" 😠', body_vi = 'Khi mẹ nhìn điện thoại hay đang khuấy nồi, bé đến xoay mặt mẹ về phía mình: "Mẹ nhìn con này!". Bé có lý đấy. Bé không cần sự hiện diện của mẹ, mà cần sự chú ý trọn vẹn. Hãy dừng việc đang làm và chỉ cần 3 phút nhìn vào mắt bé để lắng nghe.', title_zh = '“你都不听我说！”的一击 😠', body_zh = '你看手机或搅着锅时，宝宝跑过来把你的脸转向自己：“看我！”宝宝说得对。宝宝要的不是你人在这里，而是你全心全意的关注。停下手里的事，只要3分钟，和宝宝对视，认真听宝宝说。' WHERE id = '8f4abc30-5451-459c-a1af-55ec249af8b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de huir del cuento 🏃‍♂️', title_fr = 'Tentatives d''évasion pendant le conte 🏃‍♂️', title_hi = 'कहानी से भागने की कोशिशें 🏃‍♂️', title_id = 'Usaha kabur dari dongeng 🏃‍♂️', title_ja = 'お話からの脱走 🏃‍♂️', title_ko = '동화 탈출 시도 🏃‍♂️', title_nl = 'Pogingen om aan het sprookje te ontsnappen 🏃‍♂️', title_pl = 'Próby ucieczki od bajki 🏃‍♂️', title_pt = 'Tentativas de fugir à história 🏃‍♂️', title_sv = 'Försök att fly från sagan 🏃‍♂️', title_vi = 'Những lần trốn giờ đọc truyện 🏃‍♂️', title_zh = '想从故事里逃跑 🏃‍♂️' WHERE id = '9069176c-b719-421b-bb4f-85cd101945a6' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica del tiempo y las capas ⛅', body_es = 'Al acercarse la primavera el tiempo es cambiante: frío por la mañana y calor a mediodía. La herramienta Tiempo y ropa te recuerda vestirle con el efecto cebolla (por capas). En el parque, quítale una capa a medida que entre en calor y evita que sude y que tú te estreses.', title_fr = 'Météo et tactique des couches ⛅', body_fr = 'À l''approche du printemps, le temps est indécis : froid le matin, chaud l''après-midi. Météo et tenue vous rappelle de l''habiller en couches (l''effet oignon). Au parc, enlevez une couche à mesure qu''il se réchauffe, pour éviter qu''il transpire et vous épargner du stress.', title_hi = 'मौसम और परतों वाले कपड़ों की तरकीब ⛅', body_hi = 'बसंत के करीब मौसम का कोई भरोसा नहीं; सुबह ठंड, दोपहर गर्मी। मौसम और कपड़े टूल आपको प्याज़ की तरह परत-दर-परत कपड़े पहनाने की याद दिलाता है। पार्क में गर्मी बढ़ने पर एक परत उतारकर उसका पसीना भी रोकिए और अपना तनाव भी।', title_id = 'Taktik cuaca dan pakaian berlapis ⛅', body_id = 'Menjelang musim semi cuaca tidak menentu; pagi dingin, siang panas. Cuaca dan Pakaian mengingatkan Anda untuk memakaikan pakaian berlapis seperti bawang. Saat ia mulai kepanasan di taman, lepas satu lapis untuk mencegah ia berkeringat sekaligus mencegah stres Anda.', title_ja = '天気と重ね着作戦 ⛅', body_ja = '春が近づくと天気は気まぐれ。朝は寒く、お昼は暑い。「天気と服装」が、玉ねぎのような重ね着を思い出させてくれます。公園で暑くなったら1枚脱がせて、汗をかくのも、あなたのストレスも防ぎましょう。', title_ko = '날씨와 겹겹이 입기 작전 ⛅', body_ko = '봄이 다가오면 날씨가 변덕스러워요. 아침엔 춥고 낮엔 덥죠. 날씨와 옷차림 도구가 양파처럼 겹겹이 입히라고 알려 줘요. 공원에서 더워지면 한 겹씩 벗겨 아이가 땀 흘리는 것도, 엄마의 스트레스도 막으세요.', title_nl = 'Weer en de laagjestactiek ⛅', body_nl = 'Richting de lente is het weer wisselvallig: ''s ochtends koud, ''s middags warm. De tool Weer en kleding herinnert je eraan hem in laagjes aan te kleden (het uieffect). Trek in het park een laagje uit als hij het warm krijgt, zo voorkom je dat hij gaat zweten en heb jij minder stress.', title_pl = 'Pogoda i taktyka na cebulkę ⛅', body_pl = 'Pod koniec zimy pogoda jest niezdecydowana: rano zimno, w południe ciepło. Narzędzie Pogoda i ubiór przypomina, by ubrać go na cebulkę. Gdy w parku zrobi mu się ciepło, zdejmij jedną warstwę i zapobiegnij i jego poceniu się, i swojemu stresowi.', title_pt = 'Tempo e a tática das camadas ⛅', body_pt = 'Perto da primavera o tempo anda indeciso: frio de manhã, calor ao meio-dia. A ferramenta Tempo e Roupa lembra-lhe que o vista "à cebola" (por camadas). No parque, tire-lhe uma camada à medida que aquece e evite que ele transpire e que a mãe se stresse.', title_sv = 'Väder och lager på lager-taktiken ⛅', body_sv = 'Närmare våren är vädret ombytligt; kallt på morgonen och varmt mitt på dagen. Verktyget Väder och kläder påminner dig om löktekniken (lager på lager). Ta av ett lager när barnet blir varmt i parken och förebygg både barnets svettningar och din egen stress.', title_vi = 'Thời tiết và mẹo mặc nhiều lớp ⛅', body_vi = 'Gần mùa xuân, thời tiết thất thường: sáng lạnh, trưa nóng. Thời tiết và trang phục nhắc mẹ cho bé mặc nhiều lớp như "củ hành". Ở công viên, khi bé nóng lên thì cởi bớt một lớp, vừa tránh cho bé đổ mồ hôi, vừa tránh căng thẳng cho mẹ.', title_zh = '天气与洋葱式穿衣法 ⛅', body_zh = '快到春天时天气反复无常：早上冷，中午热。天气与穿衣工具会提醒你采用“洋葱式”（一层层）穿法。在公园里热了就脱掉一层，既能防止宝宝出汗，也能减少你自己的压力。' WHERE id = 'e4d134d2-7f4f-4894-b6f3-6051d4c2f528' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y terquedades repentinas 🤖', body_es = '¿El niño que hasta ayer estaba tranquilo hoy reacciona de forma agresiva a todo? No busques causas que den miedo en internet. Pregunta a Anacan AI por las causas psicológicas de este salto de desarrollo («mental leap») y pon a cero tu inquietud con una respuesta avalada por pediatras.', title_fr = 'Intelligence artificielle et entêtements soudains 🤖', body_fr = 'L''enfant si calme jusqu''à hier réagit aujourd''hui à tout avec agressivité ? Ne cherchez pas de causes effrayantes sur Internet. Demandez à Anacan AI les raisons psychologiques de ce bond de développement (mental leap) et apaisez votre inquiétude avec une réponse validée par des pédiatres.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और अचानक की ज़िद 🤖', body_hi = 'कल तक शांत रहने वाला बच्चा आज हर बात पर गुस्से से प्रतिक्रिया देता है? इंटरनेट पर डरावनी वजहें मत ढूँढिए। Anacan AI से इस विकास की छलाँग (मेंटल लीप) की मनोवैज्ञानिक वजहें पूछिए और बाल रोग विशेषज्ञ द्वारा पुष्ट जवाब से अपनी घबराहट खत्म कीजिए।', title_id = 'Kecerdasan buatan dan keras kepala mendadak 🤖', body_id = 'Anak yang sampai kemarin tenang, hari ini bereaksi agresif pada segala hal? Jangan mencari penyebab menakutkan di internet. Tanyakan pada Anacan AI penyebab psikologis lompatan perkembangan (mental leap) ini, dan redakan kecemasan Anda dengan jawaban yang disetujui dokter anak.', title_ja = 'AIと急ながんこさ 🤖', body_ja = '昨日までおだやかだった子が、今日は何にでも激しく反応する？ネットで怖い理由をさがさないで。Anacan AIに、この発達の飛躍（mental leap）の心理的な理由をたずねて、小児科医も認める答えで不安をリセットしましょう。', title_ko = '인공지능과 갑작스러운 고집 🤖', body_ko = '어제까지 순하던 아이가 오늘은 모든 일에 공격적으로 반응하나요? 인터넷에서 무서운 이유를 찾지 마세요. Anacan AI에게 이 발달 도약(mental leap)의 심리적 이유를 물어보고, 소아과 의사가 확인한 답으로 걱정을 내려놓으세요.', title_nl = 'Kunstmatige intelligentie en plotselinge koppigheid 🤖', body_nl = 'Reageert je kind dat tot gisteren rustig was, vandaag overal agressief op? Zoek op internet niet naar enge oorzaken. Vraag Anacan AI naar de psychologische oorzaken van deze ontwikkelingssprong (mental leap) en zet je ongerustheid op nul met een door kinderartsen bevestigd antwoord.', title_pl = 'Sztuczna inteligencja i nagły upór 🤖', body_pl = 'Dziecko, które do wczoraj było spokojne, dziś na wszystko reaguje agresywnie? Nie szukaj strasznych przyczyn w internecie. Zapytaj Anacan AI o psychologiczne przyczyny tego skoku rozwojowego (mental leap) i wyzeruj niepokój odpowiedzią potwierdzoną przez pediatrów.', title_pt = 'Inteligência artificial e teimosias repentinas 🤖', body_pt = 'A criança que até ontem era calma hoje reage a tudo com agressividade? Não procure causas assustadoras na internet. Pergunte ao Anacan AI as causas psicológicas deste salto de desenvolvimento (mental leap) e acabe com a aflição com uma resposta validada por pediatras.', title_sv = 'Artificiell intelligens och plötslig envishet 🤖', body_sv = 'Reagerar barnet som var lugnt fram till i går i dag aggressivt på allt? Leta inte efter skrämmande orsaker på nätet. Fråga Anacan AI om de psykologiska orsakerna till det här utvecklingssprånget (mental leap) och nollställ oron med ett barnläkargodkänt svar.', title_vi = 'Trí tuệ nhân tạo và những lúc bướng bỉnh bất chợt 🤖', body_vi = 'Đứa trẻ đến hôm qua còn ngoan hiền, hôm nay lại phản ứng gay gắt với mọi thứ? Đừng tìm những lý do đáng sợ trên mạng. Hãy hỏi Anacan AI về nguyên nhân tâm lý của bước nhảy vọt phát triển này (mental leap) và xua tan lo lắng với câu trả lời được bác sĩ nhi khoa xác nhận.', title_zh = '人工智能与突然的倔强 🤖', body_zh = '直到昨天还很安静的孩子，今天对什么都反应激烈？别在网上找那些吓人的原因。问问Anacan AI这次发育飞跃（mental leap）背后的心理原因，用经儿科医生认可的答案让焦虑归零。' WHERE id = '918e0a4a-7932-41e0-b1cb-29b726120c0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de la nariz robada 👃', body_es = 'Le enseñas el pulgar diciendo «¡Te he quitado la nariz!» y él se lo cree de verdad y se pone a llorar. La imaginación de los 3 años y medio a veces no sabe separar realidad e ilusión. Dile enseguida «¡Ajá, ya te la he devuelto!», bésale la nariz y convierte este pequeño trauma en una sonrisa.', title_fr = 'Le jeu du nez volé 👃', body_fr = 'Vous dites « Je t''ai pris le nez ! » en montrant votre pouce, et il y croit vraiment et se met à pleurer ! À 3 ans et demi, l''imagination ne sait parfois pas faire la différence entre réalité et illusion. Dites aussitôt « Voilà, je l''ai remis ! » et embrassez son nez pour transformer ce petit traumatisme en sourire.', title_hi = 'चुराई हुई नाक का खेल 👃', body_hi = '‘तुम्हारी नाक ले ली!’ कहकर अँगूठा दिखाती हैं और वह सच में मानकर रोने लगता है! साढ़े 3 साल की कल्पना कभी-कभी सच और भ्रम में फ़र्क नहीं कर पाती। तुरंत ‘अरे, वापस लगा दी’ कहकर उसकी नाक चूमिए और इस छोटे से सदमे को मुस्कान में बदल दीजिए।', title_id = 'Permainan hidung dicuri 👃', body_id = 'Anda berkata ''Hidungmu Mama ambil!'' sambil menunjukkan ibu jari, dan ia benar-benar percaya lalu menangis! Imajinasi anak 3,5 tahun kadang belum bisa memisahkan kenyataan dan ilusi. Segera katakan ''Aha, sudah Mama kembalikan'', cium hidungnya, dan ubah trauma kecil ini menjadi senyuman.', title_ja = 'お鼻とったよ遊び 👃', body_ja = '「お鼻とった！」と親指を見せたら、本気にして泣きだした！3歳半の想像力は、ときに現実と空想を区別できません。すぐに「はい、もとに戻したよ」と言ってお鼻にキスして、この小さなショックを笑顔に変えましょう。', title_ko = '코 훔치기 놀이 👃', body_ko = '''코 가져갔다!'' 하며 엄지를 보여 줬더니 진짜로 믿고 울기 시작했나요? 세 살 반의 상상력은 가끔 현실과 착각을 구분하지 못해요. 바로 ''아하, 다시 붙여 놨어'' 하며 코에 뽀뽀해서 이 작은 충격을 웃음으로 바꿔 주세요.', title_nl = 'Het gestolen-neusspel 👃', body_nl = 'Je zegt ''Ik heb je neus!'' en laat je duim zien, en hij gelooft het echt en begint te huilen! Met 3,5 jaar kan de fantasie werkelijkheid en illusie soms nog niet scheiden. Zeg meteen ''Hop, ik heb hem teruggezet'', geef een kus op zijn neus en verander dit kleine trauma in een glimlach.', title_pl = 'Zabawa w ukradziony nos 👃', body_pl = 'Mówisz „Mam twój nos!” i pokazujesz kciuk, a on naprawdę w to wierzy i zaczyna płakać! Wyobraźnia 3,5-latka czasem nie odróżnia rzeczywistości od iluzji. Od razu powiedz „Aha, oddałam!”, pocałuj go w nos i zamień tę małą traumę w uśmiech.', title_pt = 'O jogo do nariz roubado 👃', body_pt = 'Diz "Roubei-te o nariz!", mostra-lhe o polegar e ele acredita mesmo e começa a chorar! Aos 3 anos e meio, a imaginação às vezes não separa a realidade da ilusão. Diga logo "Pronto, já o pus no sítio", dê-lhe um beijo no nariz e transforme este pequeno trauma num sorriso.', title_sv = 'Leken med den stulna näsan 👃', body_sv = 'Du visar tummen och säger ”Jag tog din näsa!”, och barnet tror verkligen på det och börjar gråta! 3,5-åringens fantasi kan ibland inte skilja verklighet från illusion. Säg genast ”Aha, jag satte tillbaka den”, pussa näsan och gör det lilla traumat till ett leende.', title_vi = 'Trò chơi lấy trộm mũi 👃', body_vi = 'Mẹ nói "Mẹ lấy mũi con rồi!" và giơ ngón cái ra, bé tin thật và bật khóc! Trí tưởng tượng của tuổi 3,5 đôi khi chưa phân biệt được thực tế và ảo tưởng. Hãy nói ngay "A, mẹ trả lại rồi đây" và hôn lên mũi bé, biến "chấn thương" nhỏ này thành nụ cười.', title_zh = '偷鼻子游戏 👃', body_zh = '你说“我拿走你的鼻子啦！”，伸出大拇指，宝宝却当真了，哭了起来！3岁半的想象力有时还分不清现实和幻象。马上说“啊，我放回去了”，亲亲宝宝的鼻子，把这个小小的“创伤”变成笑容。' WHERE id = 'b03065aa-7764-4054-8d16-b42a880815cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una mirada en silencio con tu pareja 🥂', body_es = 'Por fin se ha dormido. Tú y tu pareja estáis sentados juntos en el sofá y no tenéis fuerzas ni para hablar. Simplemente os miráis en silencio y sonreís. Esa mirada silenciosa es la forma más bonita de decir «lo estamos haciendo de maravilla con este caos».', title_fr = 'Un regard silencieux avec votre partenaire 🥂', body_fr = 'L''enfant dort enfin. Vous êtes assis côte à côte sur le canapé avec votre partenaire et vous n''avez même plus la force de parler. Vous vous regardez simplement en silence et vous souriez. Ce regard silencieux est la plus belle façon de dire « on vient parfaitement à bout de ce chaos ».', title_hi = 'साथी के साथ खामोश नज़रें 🥂', body_hi = 'बच्चा आखिरकार सो गया। आप और आपके साथी सोफ़े पर साथ बैठे हैं और बात करने की भी ताकत नहीं। बस खामोशी में एक-दूसरे को देखकर मुस्कुरा रहे हैं। यह खामोश नज़र ‘हम इस अफ़रा-तफ़री को बखूबी संभाल रहे हैं’ कहने का सबसे प्यारा तरीका है।', title_id = 'Saling tatap tanpa kata dengan pasangan 🥂', body_id = 'Anak akhirnya tidur. Anda dan pasangan duduk berdampingan di sofa, bahkan tak punya tenaga untuk bicara. Kalian hanya saling memandang dalam hening dan tersenyum. Tatapan tanpa kata ini adalah cara terindah untuk berkata ''Kita menghadapi kekacauan ini dengan sempurna''.', title_ja = 'パートナーと言葉のない見つめ合い 🥂', body_ja = 'やっと子どもが寝ました。あなたとパートナーはソファに並んで座り、話す元気さえ残っていません。ただ静けさの中で見つめ合って、ほほえむだけ。この無言の見つめ合いこそ「わたしたち、このカオスを見事に乗りこえている」と伝えるいちばんすてきな方法です。', title_ko = '배우자와의 말없는 눈맞춤 🥂', body_ko = '아이가 드디어 잠들었어요. 배우자와 소파에 나란히 앉았지만 말할 힘조차 없죠. 그저 조용히 서로를 보며 미소 짓나요? 이 말없는 눈맞춤이 ''우리 이 혼돈을 완벽하게 해내고 있어''라고 말하는 가장 아름다운 방법이에요.', title_nl = 'Een stille blik met je partner 🥂', body_nl = 'Je kind slaapt eindelijk. Jij en je partner zitten naast elkaar op de bank en hebben niet eens de energie om te praten. Jullie kijken elkaar alleen in stilte aan en glimlachen. Die stille blik is de mooiste manier om te zeggen: ''We kunnen deze chaos perfect aan.''', title_pl = 'Ciche spojrzenie z partnerem 🥂', body_pl = 'Dziecko w końcu zasnęło. Siedzicie z partnerem obok siebie na kanapie i nie macie siły nawet rozmawiać. Po prostu patrzycie na siebie w ciszy i się uśmiechacie. To ciche spojrzenie to najpiękniejszy sposób, by powiedzieć „świetnie dajemy radę z tym chaosem”.', title_pt = 'Contacto visual silencioso com o companheiro 🥂', body_pt = 'A criança finalmente adormeceu. Está sentada no sofá ao lado do seu companheiro e nem têm forças para falar. Limitam-se a olhar um para o outro e a sorrir em silêncio. Este olhar silencioso é a forma mais bonita de dizer "estamos a dar conta deste caos na perfeição".', title_sv = 'Tyst ögonkontakt med partnern 🥂', body_sv = 'Äntligen sover barnet. Du och din partner sitter bredvid varandra i soffan och orkar inte ens prata. Ni bara tittar på varandra i tystnad och ler. Den tysta blicken är det vackraste sättet att säga ”vi klarar det här kaoset perfekt”.', title_vi = 'Ánh mắt lặng lẽ cùng chồng 🥂', body_vi = 'Cuối cùng bé cũng ngủ. Hai vợ chồng ngồi cạnh nhau trên sofa, mệt đến mức chẳng còn sức nói. Chỉ nhìn nhau trong im lặng và mỉm cười. Ánh mắt lặng lẽ ấy là cách đẹp nhất để nói "Chúng ta đang vượt qua mớ hỗn loạn này thật hoàn hảo".', title_zh = '和伴侣无声的对视 🥂', body_zh = '宝宝终于睡着了。你和伴侣并排坐在沙发上，连说话的力气都没有了。只是在安静中看着对方笑一笑。这无声的对视，就是说“这场混乱我们搞定得很漂亮”最美的方式。' WHERE id = 'f9660fac-3163-450f-a18c-f1ac86faf296' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Coge del suelo el mando o las llaves de papá y proclama: «¡Esto lo he encontrado yo, es mío!». Para él encontrar significa poseer. No se lo quites a la fuerza: dile «Gracias por encontrarlo para mí», dirige su atención a otro juguete y recupéralo.', body_fr = 'Il ramasse par terre la télécommande ou les clés de papa et déclare : « C''est moi qui l''ai trouvé, c''est à moi ! » Pour lui, trouver, c''est posséder. Ne le lui arrachez pas des mains : dites « Merci de l''avoir trouvé pour moi », détournez son attention vers un autre jouet et récupérez l''objet.', body_hi = 'घर का रिमोट या पापा की चाबी ज़मीन से उठाकर दावा करता है, ‘यह मुझे मिला, यह मेरा है!’ उसके लिए ढूँढने का मतलब मालिक बनना है। ज़बरदस्ती मत छीनिए, ‘शुक्रिया, तुमने मेरे लिए ढूँढ दिया’ कहिए और उसका ध्यान किसी और खिलौने की ओर ले जाकर वापस ले लीजिए।', body_id = 'Ia memungut remote atau kunci Ayah dari lantai dan bersikeras ''Aku yang menemukan, ini punyaku!''. Baginya, menemukan berarti memiliki. Jangan merebutnya dengan paksa, katakan ''Terima kasih sudah menemukannya untuk Mama'', lalu ambil kembali sambil mengalihkan perhatiannya ke mainan lain.', body_ja = '家のリモコンやパパのカギを床から拾って「ぼくが見つけたから、ぼくの！」と主張する。この子にとって、見つけることは自分のものにすることなんです。無理に取りあげず、「見つけてくれてありがとう」と言って、別のおもちゃに気をそらしながら返してもらいましょう。', body_ko = '바닥에서 리모컨이나 아빠 열쇠를 주워 ''내가 찾았으니까 내 거야!''라고 우기나요? 아이에게는 찾는 게 곧 갖는 거예요. 억지로 빼앗지 말고 ''찾아 줘서 고마워''라고 한 뒤 다른 장난감으로 관심을 돌려 돌려받으세요.', body_nl = 'Hij raapt de afstandsbediening of papa''s sleutels van de grond en roept: ''Ik heb het gevonden, het is van mij!'' Voor hem betekent vinden ook hebben. Pak het niet met geweld af, maar zeg ''Dankjewel dat je het voor me hebt gevonden'', leid zijn aandacht af met ander speelgoed en neem het terug.', body_pl = 'Podnosi z podłogi pilota albo klucze taty i ogłasza: „Ja to znalazłem, to moje!”. Dla niego znaleźć znaczy mieć. Nie wyrywaj mu tego siłą, powiedz „Dziękuję, że znalazłeś to dla mnie”, odwróć jego uwagę inną zabawką i odbierz.', body_pt = 'Apanha do chão o comando ou as chaves do pai e diz "Fui eu que encontrei, é meu!". Para ele, encontrar significa possuir. Não lho tire à força: diga "Obrigada por o teres encontrado para mim", desvie a atenção dele para outro brinquedo e recupere-o.', body_sv = 'Barnet tar upp fjärrkontrollen eller pappas nycklar från golvet och hävdar: ”Jag hittade den, den är min!” För barnet betyder att hitta att äga. Ta den inte med våld, säg ”Tack för att du hittade den åt mig”, led över uppmärksamheten till en annan leksak och ta tillbaka den.', body_vi = 'Bé nhặt điều khiển hay chìa khóa của bố dưới sàn lên và tuyên bố: "Con tìm thấy, của con!". Với bé, tìm thấy nghĩa là sở hữu. Đừng giật lấy, hãy nói "Cảm ơn con đã tìm giúp mẹ" và chuyển sự chú ý của bé sang đồ chơi khác để lấy lại.', body_zh = '从地上捡起家里的遥控器或爸爸的钥匙，宣称：“这是我找到的，是我的！”对宝宝来说，找到就意味着拥有。别硬抢，说一句“谢谢你帮我找到了”，再把宝宝的注意力转到别的玩具上，把东西拿回来。' WHERE id = '48be6a74-039a-47b4-b2e6-38a02b369aa1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Concierto en la cocina 🥄', body_es = 'Saca las ollas y las cucharas de madera y da un concierto en medio de la cocina. Aunque te duela la cabeza, así se desarrollan su sentido del ritmo y su creatividad. No intervengas con prisas: deja unos minutos que esa energía loca se extienda por la habitación en ondas sonoras.', title_fr = 'Concert en cuisine 🥄', body_fr = 'Il sort les casseroles et les cuillères en bois et donne un concert au milieu de la cuisine. Même si vous avez mal à la tête, c''est le développement de son sens du rythme et de sa créativité. N''intervenez pas trop vite, laissez cette énergie folle se répandre quelques minutes en ondes sonores dans la pièce.', title_hi = 'रसोई में कॉन्सर्ट 🥄', body_hi = 'पतीले और लकड़ी के चम्मच निकालकर रसोई के बीच कॉन्सर्ट दे रहा है। सिर भले दुखे, यह उसकी लय की समझ और रचनात्मकता का विकास है। जल्दबाज़ी में बीच में मत आइए, कुछ मिनट उस धमाकेदार ऊर्जा को आवाज़ की लहरों के साथ कमरे में फैलने दीजिए।', title_id = 'Konser di dapur 🥄', body_id = 'Ia mengeluarkan panci dan sendok kayu lalu menggelar konser di tengah dapur. Meski kepala Anda pusing, ini adalah perkembangan rasa irama dan kreativitasnya. Jangan buru-buru campur tangan, biarkan energi gilanya menyebar ke seluruh ruangan lewat gelombang suara selama beberapa menit.', title_ja = 'キッチンでコンサート 🥄', body_ja = '鍋や木のスプーンを取り出して、キッチンのまんなかでコンサート中。頭が痛くても、これはリズム感と創造力の発達です。あわてて止めないで、数分間はそのすごいエネルギーを音の波にのせて部屋に広げさせてあげましょう。', title_ko = '부엌 콘서트 🥄', body_ko = '냄비와 나무 숟가락을 꺼내 부엌 한가운데서 콘서트를 여나요? 머리가 아파도 리듬감과 창의력이 자라는 중이에요. 서둘러 끼어들지 말고 몇 분만 그 넘치는 에너지가 소리로 방을 채우게 해 주세요.', title_nl = 'Concert in de keuken 🥄', body_nl = 'Hij haalt pannen en houten lepels tevoorschijn en geeft midden in de keuken een concert. Ook al krijg je er hoofdpijn van, zo ontwikkelt hij zijn ritmegevoel en creativiteit. Grijp niet te snel in en laat die gekke energie een paar minuten met geluidsgolven door de kamer gaan.', title_pl = 'Koncert w kuchni 🥄', body_pl = 'Wyciągnął garnki i drewniane łyżki i daje koncert na środku kuchni. Nawet jeśli boli cię głowa, to rozwój jego poczucia rytmu i kreatywności. Nie wtrącaj się w pośpiechu, pozwól przez kilka minut tej szalonej energii rozchodzić się po pokoju falami dźwięku.', title_pt = 'Concerto na cozinha 🥄', body_pt = 'Tira as panelas e as colheres de pau e dá um concerto no meio da cozinha. Mesmo com dor de cabeça, isto é o desenvolvimento do sentido de ritmo e da criatividade dele. Não intervenha à pressa: deixe por uns minutos aquela energia louca espalhar-se pelo quarto em ondas sonoras.', title_sv = 'Konsert i köket 🥄', body_sv = 'Barnet plockar fram kastruller och träslevar och ger konsert mitt i köket. Även om du får huvudvärk är det utvecklingen av rytmkänsla och kreativitet. Lägg dig inte i för snabbt, låt den galna energin spridas i rummet med ljudvågorna i några minuter.', title_vi = 'Buổi hòa nhạc trong bếp 🥄', body_vi = 'Bé lôi nồi niêu và thìa gỗ ra, mở một buổi hòa nhạc giữa bếp. Dù mẹ đau đầu, đây là sự phát triển cảm thụ nhịp điệu và khả năng sáng tạo của bé. Đừng vội can thiệp, hãy để nguồn năng lượng "điên rồ" ấy lan tỏa khắp phòng qua những làn sóng âm thanh trong vài phút.', title_zh = '厨房音乐会 🥄', body_zh = '把锅和木勺都拿出来，在厨房中间开起了音乐会。虽然你头都疼了，但这是宝宝节奏感和创造力在发展。别急着插手，让那股疯狂的能量随着声波在房间里飘荡几分钟吧。' WHERE id = '53233246-1c9c-44d8-aa89-08a12ab1932c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Quiere otra vez la canción que sonaba en la radio y que ya ha terminado. Le explicas que era en directo y que se ha acabado. Pero llora: «¡Devuélvemela!». El cerebro infantil no entiende la lógica de la emisión en directo. Para distraerle, ponte a cantar tú la canción con una voz distinta y cómica.', body_fr = 'Il réclame la chanson qui vient de passer à la radio. Vous lui expliquez que c''était en direct et que c''est fini, mais il pleure : « Remets-la ! » Le cerveau de l''enfant ne comprend pas la logique du direct. Pour détourner son attention, chantez vous-même la chanson avec une voix différente et comique.', body_hi = 'रेडियो पर बजकर खत्म हुआ गाना फिर से चाहता है। आप समझाती हैं कि वह लाइव प्रसारण था, खत्म हो गया। पर वह ‘वापस लाओ!’ कहकर रोता है। बच्चे का दिमाग लाइव प्रसारण का तर्क नहीं समझता। ध्यान बँटाने के लिए वही गाना खुद अलग, मज़ेदार आवाज़ में गाना शुरू कीजिए।', body_id = 'Ia ingin lagu yang tadi diputar di radio dan sudah selesai diputar lagi. Anda menjelaskan bahwa itu siaran langsung dan sudah selesai. Tapi ia menangis ''Putar lagi!''. Otak anak belum memahami logika siaran langsung. Untuk mengalihkan perhatiannya, nyanyikan sendiri lagu itu dengan suara yang lucu dan berbeda.', body_ja = 'ラジオで流れて終わった歌を、もう一度聞きたがる。生放送だったから終わったんだよ、と説明しても「もう一回！」と泣く。子どもの脳には、生放送の理屈がわからないんです。気をそらすために、あなたがへんてこな声でその歌を歌ってあげましょう。', body_ko = '라디오에서 나오다 끝난 노래를 다시 틀어 달라고 하나요? 생방송이라 끝났다고 설명해도 ''다시 틀어 줘!'' 하며 울죠. 아이의 뇌는 생방송의 논리를 이해하지 못해요. 관심을 돌리려면 엄마가 그 노래를 웃긴 목소리로 불러 주세요.', body_nl = 'Hij wil het liedje dat op de radio speelde en net is afgelopen nog een keer horen. Je legt uit dat het live was en voorbij is. Maar hij huilt: ''Zet het terug!'' Een kinderbrein begrijpt de logica van een live-uitzending niet. Zing het liedje zelf met een andere, grappige stem om hem af te leiden.', body_pl = 'Chce, żeby piosenka, która właśnie skończyła się w radiu, poleciała jeszcze raz. Tłumaczysz, że to była transmisja na żywo i się skończyła. A on płacze: „Puść jeszcze raz!”. Dziecięcy mózg nie rozumie logiki transmisji na żywo. Żeby odwrócić jego uwagę, zacznij sama śpiewać tę piosenkę innym, zabawnym głosem.', body_pt = 'Quer outra vez a canção que tocou na rádio e acabou. Explica-lhe que era uma emissão em direto e que acabou. Mas ele chora: "Volta a pôr!". O cérebro da criança não percebe a lógica do direto. Para o distrair, comece a cantar a canção com uma voz diferente e cómica.', body_sv = 'Barnet vill höra låten som spelades på radion och tog slut igen. Du förklarar att det var en direktsändning och att den är slut. Men barnet gråter: ”Spela den igen!” Barnets hjärna förstår inte logiken bakom direktsändning. Avled uppmärksamheten genom att själv börja sjunga låten med en annan, rolig röst.', body_vi = 'Bé muốn nghe lại bài hát vừa phát xong trên đài. Mẹ giải thích đó là phát trực tiếp, đã hết rồi. Nhưng bé khóc: "Trả lại đây!". Não bộ trẻ chưa hiểu logic của phát trực tiếp. Để đánh lạc hướng, hãy tự hát bài đó bằng một giọng khác, thật hài hước.', body_zh = '收音机里播完的歌，宝宝还想再听。你解释说那是直播，已经结束了。可宝宝哭着喊“还回来！”孩子的大脑还理解不了直播的逻辑。为了转移注意力，你自己用不同的、搞笑的声音把那首歌唱起来吧。' WHERE id = '8353b398-30f5-4594-98bd-74c894cfb243' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un té en silencio ☕', body_es = 'En medio de la habitación pone sus juguetes en fila y juega solo. ¡Por favor, no dediques ese momento a barrer la casa! Siéntate en el sofá, tómate el café o el té calentito y durante 10 minutos disfruta de este silencio sin pensar en nada.', title_fr = 'Un thé dans le silence ☕', body_fr = 'Au milieu de la pièce, il aligne ses jouets et joue tout seul. Par pitié, ne passez pas ce moment à balayer la maison ! Asseyez-vous sur le canapé, buvez votre café ou votre thé bien chaud et savourez simplement ce silence 10 minutes, sans penser à rien.', title_hi = 'खामोशी में चाय ☕', body_hi = 'कमरे के बीच खिलौने लाइन में लगाकर अकेले खेल रहा है। मेरी जान, वह पल झाड़ू लगाने में मत गँवाइए! सोफ़े पर बैठिए, अपनी कॉफ़ी या चाय गरम-गरम पीजिए और 10 मिनट कुछ सोचे बिना बस इस खामोशी का मज़ा लीजिए।', title_id = 'Teh dalam keheningan ☕', body_id = 'Ia bermain sendiri di tengah kamar sambil menjajarkan mainannya. Kumohon, jangan pakai momen itu untuk menyapu rumah! Duduklah di sofa, minum kopi atau tehmu selagi panas, dan selama 10 menit nikmati saja keheningan ini tanpa memikirkan apa pun.', title_ja = '静けさの中のお茶 ☕', body_ja = '部屋のまんなかでおもちゃを並べて、ひとりで遊んでいます。お願い、その時間を床そうじに使わないで！ソファに座って、コーヒーかお茶を温かいうちに飲み、10分間何も考えずに、この静けさを味わいましょう。', title_ko = '고요 속의 차 한 잔 ☕', body_ko = '방 한가운데서 장난감을 줄 세우며 혼자 놀고 있나요? 제발 그 시간에 집을 쓸지 마세요! 소파에 앉아 커피나 차를 따뜻할 때 마시고, 10분 동안 아무 생각 없이 이 고요를 누리세요.', title_nl = 'Thee in stilte ☕', body_nl = 'Hij zet midden in de kamer zijn speelgoed op een rij en speelt in zijn eentje. Alsjeblieft, besteed dat moment niet aan het vegen van het huis! Ga op de bank zitten, drink je koffie of thee lekker warm en geniet 10 minuten van de stilte zonder ergens aan te denken.', title_pl = 'Herbata w ciszy ☕', body_pl = 'Ustawia na środku pokoju zabawki w rzędzie i bawi się sam. Błagam, nie przeznaczaj tej chwili na zamiatanie! Usiądź na kanapie, wypij gorącą kawę albo herbatę i przez 10 minut, o niczym nie myśląc, po prostu delektuj się tą ciszą.', title_pt = 'Chá em silêncio ☕', body_pt = 'No meio do quarto, pôs os brinquedos em fila e brinca sozinho. Por amor de Deus, não gaste esse momento a varrer a casa! Sente-se no sofá, beba o café ou o chá bem quente e, durante 10 minutos, saboreie este silêncio sem pensar em nada.', title_sv = 'Te i tystnaden ☕', body_sv = 'Barnet har ställt upp sina leksaker på rad mitt i rummet och leker ensamt. Lilla vän, använd inte den stunden till att dammsuga! Sätt dig i soffan, drick ditt kaffe eller te medan det är varmt och njut bara av tystnaden i 10 minuter utan att tänka på något.', title_vi = 'Trà trong im lặng ☕', body_vi = 'Bé đang xếp đồ chơi thành hàng và chơi một mình giữa phòng. Mẹ ơi, đừng dùng khoảnh khắc đó để quét nhà! Hãy ngồi xuống sofa, uống cà phê hay trà khi còn nóng và trong 10 phút, không nghĩ gì cả, chỉ tận hưởng sự yên tĩnh này.', title_zh = '安静中的一杯茶 ☕', body_zh = '在房间中间把玩具排成一排，一个人玩着。亲爱的，别把这段时间花在扫地上！坐到沙发上，趁热喝完你的咖啡或茶，在10分钟里什么都不想，只是享受这份安静。' WHERE id = 'f3893094-7182-4330-982a-7ccd3eced333' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica del temporizador para dormir ⏱️', body_es = '¿Justo a la hora de dormir le entra sed, quiere ir al baño o se despide de la pared? Pon un temporizador. Aplica la norma «cuando suena la campanita, todos a dormir» y líbrate sin discusiones de esta despedida sin fin, de esta manipulación tan experta.', title_fr = 'La tactique du minuteur pour dormir ⏱️', body_fr = 'À l''heure du coucher, il a soudain soif, veut aller aux toilettes ou dit au revoir au mur ? Réglez un minuteur. Appliquez la règle « Quand la sonnerie retentit, tout le monde dort » et échappez sans dispute à ces adieux sans fin, à cette manipulation de maître.', title_hi = 'नींद के लिए टाइमर की तरकीब ⏱️', body_hi = 'सोने का समय आते ही अचानक प्यास लगती है, टॉयलेट जाना होता है या दीवार को अलविदा कहना होता है? टाइमर लगाइए। ‘घंटी बजते ही सब सो जाते हैं’ का नियम लागू करके इस अंतहीन अलविदा, इस माहिर चाल से बिना बहस के बच निकलिए।', title_id = 'Taktik timer untuk tidur ⏱️', body_id = 'Saat waktu tidur tiba, ia tiba-tiba haus, ingin ke toilet, atau berpamitan dengan dinding? Pasang timer. Terapkan aturan ''Saat bel berbunyi, semua tidur'' dan bebaskan diri tanpa berdebat dari perpisahan tanpa akhir dan manipulasi cerdik ini.', title_ja = '寝かしつけのタイマー作戦 ⏱️', body_ja = '寝る時間になると急にのどがかわいたり、トイレに行きたがったり、壁におやすみを言ったり？タイマーをセットしましょう。「ベルが鳴ったらみんな寝る」のルールで、この終わらないおやすみのあいさつ、この見事な作戦から、言い合わずに抜け出して。', title_ko = '잠을 위한 타이머 작전 ⏱️', body_ko = '잘 시간만 되면 갑자기 목마르고, 화장실 가고 싶고, 벽에게 인사하나요? 타이머를 맞추세요. ''종이 울리면 모두 잔다'' 규칙을 정해 이 끝없는 작별 인사, 이 노련한 작전에서 실랑이 없이 벗어나세요.', title_nl = 'Timertactiek voor het slapen ⏱️', body_nl = 'Krijgt hij net als het bedtijd is ineens dorst, moet hij naar de wc of neemt hij afscheid van de muur? Zet een timer. Voer de regel ''als de bel gaat, gaat iedereen slapen'' in en verlos jezelf zonder discussie van dit eindeloze afscheid, deze meesterlijke manipulatie.', title_pl = 'Taktyka z minutnikiem przed snem ⏱️', body_pl = 'Gdy przychodzi pora snu, nagle chce mu się pić, musi iść do toalety albo żegna się ze ścianą? Nastaw minutnik. Wprowadź zasadę „gdy zadzwoni dzwonek, wszyscy śpią” i bez kłótni uwolnij się od tych niekończących się pożegnań, tej mistrzowskiej manipulacji.', title_pt = 'A tática do temporizador para dormir ⏱️', body_pt = 'Na hora de dormir fica de repente com sede, quer ir à casa de banho ou despede-se da parede? Programe um temporizador. Aplique a regra "quando a campainha toca, todos dormem" e livre-se sem discussões desta despedida sem fim, desta manipulação de mestre.', title_sv = 'Timertaktik för sömnen ⏱️', body_sv = 'När det är dags att sova blir barnet plötsligt törstigt, vill gå på toaletten eller säger god natt till väggen? Ställ in en timer. Inför regeln ”när klockan ringer sover alla” och rädda dig utan bråk från det ändlösa farvälet och den här mästerliga manipulationen.', title_vi = 'Chiến thuật hẹn giờ đi ngủ ⏱️', body_vi = 'Đến giờ ngủ, bé bỗng khát nước, đòi đi vệ sinh hay chúc ngủ ngon cả bức tường? Hãy đặt hẹn giờ. Áp dụng quy tắc "Chuông reo là cả nhà đi ngủ" để thoát khỏi những lời tạm biệt bất tận, màn "thao túng" bậc thầy này mà không cần tranh cãi.', title_zh = '用计时器哄睡的战术 ⏱️', body_zh = '一到睡觉时间就突然口渴、想上厕所，或者跟墙说再见？设个计时器。立下“铃声一响，大家都睡觉”的规矩，不争不吵地摆脱这没完没了的告别和高明的“操控”吧。' WHERE id = '52d5f808-8d3e-4769-9814-0abc72834d43' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El pensamiento «¿Por qué mi hijo es tan tozudo?» te está comiendo por dentro. Entra en la Comunidad Anacan. Cuando leas las crisis absurdas parecidas que estallan en casa de otras madres, verás que no estás sola y que vas por un camino totalmente normal.', body_fr = 'La pensée « Pourquoi mon enfant est-il si têtu ? » vous ronge ? Rejoignez la Communauté Anacan. En lisant les crises absurdes qui éclatent chez d''autres mamans, vous verrez que vous n''êtes pas seule et que vous êtes sur une voie tout à fait normale.', body_hi = '‘मेरा बच्चा इतना ज़िद्दी क्यों है?’ वाला ख्याल आपका दिमाग खा रहा है। Anacan कम्युनिटी में जाइए। दूसरी माँओं के घरों में होने वाले ऐसे ही बेतुके नखरे पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और बिल्कुल सही रास्ते पर हैं।', body_id = 'Pikiran ''Kenapa anakku keras kepala sekali?'' terus menggerogoti otak Anda. Masuklah ke Komunitas Anacan. Saat membaca krisis absurd serupa di rumah ibu-ibu lain, Anda akan melihat bahwa Anda tidak sendirian dan sedang berada di jalur yang sepenuhnya normal.', body_ja = '「うちの子はどうしてこんなにがんこなの？」という思いが頭から離れない。Anacanコミュニティを開いてみましょう。ほかのママたちの家で起きている、同じようなおかしなかんしゃくを読めば、ひとりじゃないこと、ごく普通の道を歩んでいることがわかります。', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각이 머리를 갉아먹나요? Anacan 커뮤니티에 들어가 보세요. 다른 집에서 터지는 비슷하게 엉뚱한 떼쓰기를 읽으면 혼자가 아니고 아주 정상적인 길을 걷고 있다는 걸 알게 될 거예요.', body_nl = 'Vreet de gedachte ''Waarom is mijn kind zo koppig?'' aan je? Ga naar de Anacan Community. Als je leest over net zulke absurde buien bij andere mama''s thuis, zie je dat je niet de enige bent en dat je helemaal op de normale weg zit.', body_pl = 'Myśl „Dlaczego moje dziecko jest takie uparte?” nie daje ci spokoju. Wejdź do Społeczności Anacan. Gdy przeczytasz o podobnych absurdalnych kryzysach w domach innych mam, zobaczysz, że nie jesteś sama i wszystko idzie zupełnie normalnym torem.', body_pt = 'O pensamento "Porque é que o meu filho é tão teimoso?" não lhe sai da cabeça. Entre na Comunidade Anacan. Ao ler as crises absurdas parecidas que rebentam em casa de outras mães, vai ver que não está sozinha e que está no caminho perfeitamente normal.', body_sv = 'Tanken ”Varför är mitt barn så envist?” äter upp dig. Gå in i Anacan Community. När du läser om liknande absurda kriser hemma hos andra mammor ser du att du inte är ensam och att du är helt på rätt väg.', body_vi = 'Ý nghĩ "Sao con mình bướng thế?" cứ ám ảnh mẹ. Hãy vào Cộng đồng Anacan. Khi đọc về những cơn khủng hoảng "khó đỡ" tương tự ở nhà các mẹ khác, mẹ sẽ thấy mình không đơn độc và mọi thứ đều hoàn toàn bình thường.', body_zh = '“我的孩子怎么这么倔？”这个念头一直折磨着你。进入Anacan社区。读到其他妈妈家里也在上演类似的荒诞崩溃，你就会发现自己并不孤单，一切完全正常。' WHERE id = '7cbac7ca-9f74-4319-bb84-ce56d77a4832' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un verdadero artista elige la pared 🖍️', body_es = 'Unos segundos de silencio acabaron en peligro. Entraste en la habitación y viste que había pintado una obra de arte en la pared con rotuladores. Respira hondo. Su motricidad fina se desarrolla y la pared se limpia. Hazle sin falta una foto a esta obra maestra para reírte en el futuro.', title_fr = 'Un vrai artiste choisit le mur 🖍️', body_fr = 'Quelques secondes de silence ont mal tourné. En entrant dans la pièce, vous l''avez trouvé en train de dessiner une œuvre d''art au feutre sur le mur. Respirez profondément. Sa motricité fine se développe, et le mur se nettoie de toute façon. Prenez absolument ce chef-d''œuvre en photo pour en rire plus tard.', title_hi = 'सच्चा कलाकार दीवार चुनता है 🖍️', body_hi = 'कुछ सेकंड की खामोशी खतरे में बदल गई। कमरे में जाकर देखा कि उसने दीवार पर मार्कर से कलाकृति बना दी है। गहरी साँस लीजिए। उसकी बारीक मोटर स्किल्स बढ़ रही हैं, और दीवार तो साफ़ हो ही जाती है। इस शाहकार की तस्वीर ज़रूर लीजिए, ताकि आगे हँस सकें।', title_id = 'Seniman sejati memilih dinding 🖍️', body_id = 'Hening beberapa detik berujung bahaya. Anda masuk kamar dan melihat ia melukis karya seni di dinding dengan spidol. Tarik napas dalam. Motorik halusnya berkembang, dan dinding toh bisa dibersihkan. Pastikan memotret mahakarya ini agar kelak bisa ditertawakan.', title_ja = '本物の画家は壁を選ぶ 🖍️', body_ja = '数秒の静けさは、危険の合図でした。部屋に入ると、壁にマーカーで作品を描いていた。深呼吸して。指先の力が育っていますし、壁はどうせ拭けば落ちます。この傑作は、将来笑えるようにぜひ写真に撮っておきましょう。', title_ko = '진짜 화가는 벽을 고른다 🖍️', body_ko = '몇 초간의 고요가 사고로 이어졌나요? 방에 들어가니 벽에 사인펜으로 작품을 그리고 있네요. 깊게 숨 쉬세요. 소근육이 자라고 있고, 벽은 어차피 닦여요. 나중에 웃을 수 있게 이 걸작을 꼭 사진으로 남겨 두세요.', title_nl = 'Een echte kunstenaar kiest de muur 🖍️', body_nl = 'Een paar seconden stilte bleken gevaarlijk. Je kwam de kamer binnen en zag dat hij met een stift een kunstwerk op de muur tekende. Haal diep adem. Zijn fijne motoriek ontwikkelt zich, en de muur is toch af te wassen. Maak zeker een foto van dit meesterwerk om er later om te lachen.', title_pl = 'Prawdziwy artysta wybiera ścianę 🖍️', body_pl = 'Kilka sekund ciszy skończyło się katastrofą. Wchodzisz do pokoju, a on flamastrem rysuje dzieło sztuki na ścianie. Weź głęboki oddech. Rozwija się motoryka mała, a ścianę i tak da się zmyć. Koniecznie zrób zdjęcie temu arcydziełu, żeby kiedyś się z niego pośmiać.', title_pt = 'Um verdadeiro artista escolhe a parede 🖍️', body_pt = 'Uns segundos de silêncio acabaram em perigo. Entrou no quarto e viu que fez uma obra de arte na parede com marcadores. Respire fundo. A motricidade fina está a desenvolver-se e a parede limpa-se. Não deixe de fotografar esta obra-prima para se rir dela no futuro.', title_sv = 'En riktig konstnär väljer väggen 🖍️', body_sv = 'Några sekunders tystnad slutade i fara. Du kom in i rummet och såg att barnet målat ett konstverk på väggen med tusch. Andas djupt. Finmotoriken utvecklas, och väggen går ju att torka av. Ta absolut ett foto av mästerverket att skratta åt i framtiden.', title_vi = 'Họa sĩ thực thụ thì chọn bức tường 🖍️', body_vi = 'Vài giây im lặng đã dẫn đến "thảm họa". Mẹ bước vào phòng và thấy bé đang dùng bút dạ vẽ "tác phẩm nghệ thuật" lên tường. Hãy hít thở sâu. Kỹ năng vận động tinh của bé đang phát triển, còn tường thì lau được. Nhất định hãy chụp lại "kiệt tác" này để sau này cùng cười.', title_zh = '真正的画家都选墙 🖍️', body_zh = '几秒钟的安静带来了“危险”。走进房间，发现宝宝正用水彩笔在墙上创作艺术品。深吸一口气。精细动作在发展，墙反正也能擦干净。一定要把这幅杰作拍下来，留着将来笑一笑。' WHERE id = 'c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitación a la oscuridad 🌙', body_es = '¿Se inquieta cuando se apagan las luces del dormitorio? Pon en un rincón una pequeña lamparita de luz cálida (naranja o roja). El resto de la habitación debe quedar totalmente a oscuras para que se libere la melatonina y tenga un sueño profundo.', title_fr = 'Inviter l''obscurité 🌙', body_fr = 'Il s''inquiète quand on éteint la lumière de la chambre ? Posez dans un coin une petite veilleuse de couleur chaude (orange ou rouge). Le reste de la chambre doit rester complètement sombre pour la sécrétion de mélatonine et un sommeil profond.', title_hi = 'अँधेरे का न्योता 🌙', body_hi = 'सोने के कमरे में लाइटें बुझते ही बेचैन हो जाता है? कमरे के एक कोने में गर्म रंग (नारंगी या लाल) की एक छोटी नाइट लैंप रखिए। बाकी कमरा मेलाटोनिन बनने और गहरी नींद के लिए पूरी तरह अँधेरा रहना चाहिए।', title_id = 'Undangan menuju gelap 🌙', body_id = 'Ia gelisah saat lampu kamar dimatikan? Letakkan lampu tidur kecil berwarna hangat (oranye atau merah) di salah satu sudut kamar. Bagian kamar lainnya harus tetap gelap total untuk produksi melatonin dan tidur yang nyenyak.', title_ja = '暗さへのお誘い 🌙', body_ja = '寝室の明かりを消すと不安になる？部屋のすみに、暖かい色（オレンジや赤）の小さなナイトライトを置きましょう。それ以外の部分は、メラトニンの分泌と深い眠りのために真っ暗にしておいてね。', title_ko = '어둠으로의 초대 🌙', body_ko = '침실 불이 꺼지면 불안해하나요? 방 한쪽에 작고 따뜻한 색(주황색이나 빨간색) 수면등을 두세요. 나머지 공간은 멜라토닌 분비와 깊은 잠을 위해 완전히 어둡게 유지해야 해요.', title_nl = 'Uitnodiging aan het donker 🌙', body_nl = 'Wordt hij onrustig als het licht in de slaapkamer uitgaat? Zet een klein nachtlampje met een warme kleur (oranje of rood) in een hoek van de kamer. De rest van de kamer blijft helemaal donker voor de aanmaak van melatonine en een diepe slaap.', title_pl = 'Zaproszenie do ciemności 🌙', body_pl = 'Niepokoi się, gdy w sypialni gaśnie światło? Postaw w kącie pokoju małą lampkę nocną w ciepłym kolorze (pomarańczowym lub czerwonym). Reszta pokoju powinna pozostać zupełnie ciemna, by wydzielała się melatonina, a sen był głęboki.', title_pt = 'Convite à escuridão 🌙', body_pt = 'Fica inquieto quando se apagam as luzes do quarto? Ponha num canto do quarto uma pequena luz de presença de cor quente (laranja ou vermelha). O resto do quarto deve ficar totalmente escuro para a produção de melatonina e um sono profundo.', title_sv = 'En inbjudan till mörkret 🌙', body_sv = 'Blir barnet oroligt när lampan släcks i sovrummet? Ställ en liten nattlampa med varmt sken (orange eller röd) i ett hörn av rummet. Resten av rummet ska vara helt mörkt för melatoninutsöndringen och en djup sömn.', title_vi = 'Lời mời gọi bóng tối 🌙', body_vi = 'Bé lo lắng khi đèn phòng ngủ tắt? Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm (cam hoặc đỏ) ở một góc phòng. Phần còn lại của căn phòng nên tối hoàn toàn để melatonin được tiết ra và bé ngủ sâu.', title_zh = '邀请黑暗 🌙', body_zh = '卧室一关灯就不安？在房间一角放一盏小小的暖色（橙色或红色）小夜灯。房间其余的地方要保持全黑，才能分泌褪黑素、睡得深沉。' WHERE id = '017dd4ef-6a6d-470c-a536-c9d8157780f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intento de peluquero ✂️', title_fr = 'Apprenti coiffeur ✂️', title_hi = 'नाई बनने की कोशिश ✂️', title_id = 'Percobaan jadi tukang cukur ✂️', title_ja = '美容師さんのチャレンジ ✂️', title_ko = '미용사 도전 ✂️', title_nl = 'Kapperspoging ✂️', title_pl = 'Próba fryzjerska ✂️', title_pt = 'Tentativa de cabeleireiro ✂️', title_sv = 'Frisörförsök ✂️', title_vi = 'Thử làm thợ cắt tóc ✂️', title_zh = '理发尝试 ✂️' WHERE id = '0cf9c44c-98af-4034-b557-39b1dbb9f133' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada obligatoria a la naturaleza ⛅', body_es = 'Entre cuatro paredes su energía se convierte en agresividad y cada frase empieza por «no». Haga el tiempo que haga, abrígale según Tiempo y ropa y sácale fuera sin falta. Tocar la tierra reiniciará su sistema nervioso al instante.', title_fr = 'S''évader absolument dans la nature ⛅', body_fr = 'Entre quatre murs, son énergie se transforme en agressivité et chacune de ses phrases commence par « non ». Quel que soit le temps, équipez-le comme il faut et sortez-le absolument. Toucher la terre remettra aussitôt son système nerveux à zéro.', title_hi = 'प्रकृति की ओर ज़रूर भागिए ⛅', body_hi = 'चार दीवारों के अंदर उसकी ऊर्जा गुस्से में बदल जाती है और उसका हर वाक्य ‘नहीं’ से शुरू होता है। मौसम कैसा भी हो, सही कपड़े पहनाकर उसे बाहर ज़रूर ले जाइए। मिट्टी छूना उसके तंत्रिका तंत्र को तुरंत रीसेट कर देगा।', title_id = 'Wajib kabur ke alam ⛅', body_id = 'Di dalam empat dinding, energinya berubah menjadi agresi dan setiap kalimatnya diawali dengan ''nggak''. Apa pun cuacanya, kenakan pakaian yang sesuai dan pastikan mengajaknya keluar. Menyentuh tanah akan langsung me-reset sistem sarafnya.', title_ja = 'とにかく自然へ ⛅', body_ja = '4つの壁の中で、エネルギーがイライラに変わり、口を開けば「いや」から始まる。天気や服装に関係なく、しっかり準備して必ず外へ連れ出しましょう。土にさわれば、神経がすぐにリセットされます。', title_ko = '꼭 필요한 자연 탈출 ⛅', body_ko = '네 벽 안에서 에너지가 공격성으로 바뀌고 말마다 ''싫어''로 시작하나요? 날씨가 어떻든 알맞게 챙겨 입혀 꼭 밖에 데리고 나가세요. 흙을 만지면 신경계가 바로 초기화돼요.', title_nl = 'Echt even de natuur in ⛅', body_nl = 'Tussen vier muren wordt zijn energie agressie en begint elke zin met ''nee''. Kleed hem passend aan, ongeacht het weer, en ga hoe dan ook naar buiten. Aarde aanraken zet zijn zenuwstelsel meteen op nul.', title_pl = 'Konieczna ucieczka na łono natury ⛅', body_pl = 'W czterech ścianach jego energia zamienia się w agresję, a każde zdanie zaczyna się od „nie”. Bez względu na pogodę ubierz go odpowiednio i koniecznie wyjdźcie na dwór. Dotyk ziemi od razu zresetuje jego układ nerwowy.', title_pt = 'Fuga obrigatória para a natureza ⛅', body_pt = 'Entre quatro paredes, a energia dele transforma-se em agressividade e cada frase começa com "não". Seja qual for o tempo, vista-o de forma adequada e leve-o sem falta para a rua. Tocar na terra vai reiniciar logo o sistema nervoso dele.', title_sv = 'Ut i naturen, absolut ⛅', body_sv = 'Mellan fyra väggar blir barnets energi till ilska och varje mening börjar med ”nej”. Oavsett väder, klä barnet rätt och se till att ni kommer ut. Att röra vid jorden nollställer nervsystemet direkt.', title_vi = 'Nhất định phải ra với thiên nhiên ⛅', body_vi = 'Ở trong bốn bức tường, năng lượng của bé biến thành sự hung hăng và câu nào cũng bắt đầu bằng "không". Dù thời tiết thế nào, hãy chuẩn bị trang phục phù hợp và nhất định đưa bé ra ngoài. Chạm vào đất sẽ lập tức "khởi động lại" hệ thần kinh của bé.', title_zh = '一定要奔向大自然 ⛅', body_zh = '被关在四面墙里，精力就会变成攻击性，每句话都以“不”开头。不管天气如何，穿戴合适，一定要带宝宝出门。摸摸泥土，能让宝宝的神经系统马上重启。' WHERE id = '86c98bc5-4f00-463f-9722-124e19e389a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Abraza cualquier objeto de la casa, grita «¡esto es mío!» y no se lo da a nadie. Está descubriendo los límites de la propiedad. No le acuses de egoísta: dirige su atención a otro juego y recupera el objeto.', body_fr = 'Il serre dans ses bras un objet quelconque de la maison en criant « C''est à moi ! » et ne le donne à personne. Il découvre les limites de la propriété. Ne l''accusez pas d''égoïsme, détournez son attention vers un autre jeu pour récupérer l''objet.', body_hi = 'घर की कोई भी चीज़ गले लगाकर ‘यह मेरा है!’ चिल्लाता है और किसी को नहीं देता। वह अपनी चीज़ों की सीमाएँ खोज रहा है। उसे स्वार्थी मत कहिए, उसका ध्यान किसी और खेल की ओर ले जाकर चीज़ वापस ले लीजिए।', body_id = 'Ia memeluk benda apa saja di rumah sambil berteriak ''Ini punyaku!'' dan tidak mau memberikannya kepada siapa pun. Ia sedang menemukan batas kepemilikan. Jangan menuduhnya egois, ambil kembali bendanya sambil mengalihkan perhatiannya ke permainan lain.', body_ja = '家にある適当なものを抱きかかえて「これ、ぼくの！」と叫び、誰にも渡さない。自分のものという境界を発見しているんです。わがままだと責めずに、別の遊びに気をそらしながら返してもらいましょう。', body_ko = '집 안의 아무 물건이나 끌어안고 ''이건 내 거야!''라고 소리치며 아무에게도 주지 않나요? 소유의 경계를 발견하는 중이에요. 이기적이라고 탓하지 말고 다른 놀이로 관심을 돌려 물건을 돌려받으세요.', body_nl = 'Hij knuffelt een willekeurig ding in huis, roept ''Dit is van mij!'' en geeft het aan niemand. Hij ontdekt de grenzen van bezit. Beschuldig hem niet van egoïsme, maar leid zijn aandacht naar een ander spel en neem het ding dan terug.', body_pl = 'Przytula jakąkolwiek przypadkową rzecz w domu, krzyczy „To moje!” i nikomu jej nie daje. Odkrywa granice własności. Nie zarzucaj mu egoizmu, odwróć jego uwagę inną zabawą i odbierz tę rzecz.', body_pt = 'Agarra-se a um objeto qualquer da casa, grita "Isto é meu!" e não o dá a ninguém. Está a descobrir os limites da posse. Não o acuse de egoísmo: desvie a atenção dele para outra brincadeira e recupere o objeto.', body_sv = 'Barnet kramar en slumpmässig sak hemma, skriker ”Den är min!” och ger den inte till någon. Barnet upptäcker gränserna för ägande. Anklaga inte barnet för egoism, led över uppmärksamheten till en annan lek och ta tillbaka saken.', body_vi = 'Bé ôm chặt một món đồ ngẫu nhiên trong nhà và hét lên "Cái này của con!", không cho ai đụng vào. Bé đang khám phá ranh giới sở hữu. Đừng trách bé ích kỷ, hãy chuyển sự chú ý của bé sang trò chơi khác để lấy lại món đồ.', body_zh = '抱着家里随便一样东西大喊“这是我的！”，谁都不给。宝宝在探索所有权的边界。别指责宝宝自私，把宝宝的注意力转到别的游戏上，再把东西拿回来。' WHERE id = '04ffb755-8100-4999-9284-739b81b180be' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No es basura, es arte 🎨', body_es = 'Ha creado en medio de la habitación una gran obra de arte con trocitos de papel e hilos cortados y no te deja tirarla. Deja a un lado la obsesión por la limpieza. Respeta el caos que ha creado: la limpieza puede esperar a mañana.', title_fr = 'Ce n''est pas du désordre, c''est de l''art 🎨', body_fr = 'Au milieu de la pièce, il a créé une grande œuvre d''art faite de petits bouts de papier et de ficelles coupées, et refuse que vous la jetiez. Laissez de côté votre obsession du rangement. Respectez le chaos qu''il a créé, le ménage peut attendre demain.', title_hi = 'कचरा नहीं, कला 🎨', body_hi = 'कमरे के बीच कागज़ के छोटे टुकड़ों और कटे धागों से एक बड़ी कलाकृति बना ली है और फेंकने नहीं देता। सफ़ाई की सनक एक तरफ़ रखिए। उसकी रची अफ़रा-तफ़री का सम्मान कीजिए, सफ़ाई कल तक भी रुक सकती है।', title_id = 'Bukan sampah, tapi seni 🎨', body_id = 'Di tengah kamar ia membuat karya seni besar dari sobekan kertas dan potongan benang, dan tidak mengizinkan Anda membuangnya. Singkirkan dulu obsesi kebersihan. Hargai kekacauan yang ia ciptakan, bersih-bersih bisa menunggu besok.', title_ja = 'ゴミじゃない、アートです 🎨', body_ja = '部屋のまんなかに、小さな紙くずや切った毛糸で大作をつくり、捨てさせてくれない。きれい好きはちょっとお休みして、この子がつくったカオスを尊重しましょう。お掃除は明日でも大丈夫です。', title_ko = '쓰레기가 아니라 예술 🎨', body_ko = '방 한가운데 작은 종이 조각과 잘린 실로 커다란 작품을 만들고 버리지 못하게 하나요? 깔끔함에 대한 집착은 잠시 내려놓으세요. 아이가 만든 혼돈을 존중해 주세요, 청소는 내일 해도 돼요.', title_nl = 'Geen rommel, maar kunst 🎨', body_nl = 'Hij heeft midden in de kamer een groot kunstwerk gemaakt van papiersnippers en stukjes touw, en hij laat het je niet weggooien. Zet je opruimdrang even opzij. Respecteer de chaos die hij heeft gemaakt, opruimen kan ook morgen.', title_pl = 'To nie śmieci, to sztuka 🎨', body_pl = 'Na środku pokoju stworzył wielkie dzieło sztuki ze skrawków papieru i pociętych sznurków i nie pozwala go wyrzucić. Odłóż na bok obsesję porządku. Uszanuj chaos, który stworzył, sprzątanie może poczekać do jutra.', title_pt = 'Não é lixo, é arte 🎨', body_pt = 'No meio do quarto criou uma grande obra de arte com pedacinhos de papel e fios cortados e não a deixa deitar fora. Ponha de lado a obsessão pela limpeza. Respeite o caos que ele criou, a limpeza pode ficar para amanhã.', title_sv = 'Inte skräp, utan konst 🎨', body_sv = 'Mitt i rummet har barnet skapat ett stort konstverk av små pappersbitar och avklippta snören och låter dig inte slänga det. Lägg städmanin åt sidan. Respektera kaoset barnet har skapat, städningen kan vänta till i morgon.', title_vi = 'Không phải rác, mà là nghệ thuật 🎨', body_vi = 'Giữa phòng, bé đã tạo ra một "tác phẩm nghệ thuật" lớn từ những mẩu giấy vụn và sợi dây cắt nhỏ, và không cho mẹ vứt đi. Hãy gác lại nỗi ám ảnh sạch sẽ. Tôn trọng sự hỗn loạn bé tạo ra, việc dọn dẹp có thể để đến mai.', title_zh = '不是垃圾，是艺术 🎨', body_zh = '在房间中间用碎纸片、剪断的线头创作了一件大型艺术品，还不让你扔。把洁癖先放一边。尊重宝宝创造的混乱吧，打扫可以留到明天。' WHERE id = '1f9e9c23-d051-49a3-8538-a3275546e6a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No ha podido gastar toda su energía y se resiste a ir a la cama. Pide ayuda a papá. Cuando lo sube a caballito y galopa, las carcajadas llenan la habitación y todo el estrés físico acumulado, esa energía sin fin, desaparece en segundos con el sudor.', body_fr = 'Il n''a pas pu se dépenser complètement et refuse d''aller au lit. Appelez papa en renfort. Quand il le prend sur son dos pour jouer au cheval, les éclats de rire remplissent la pièce, et toute la tension physique accumulée, cette énergie sans fin, s''évacue en quelques secondes.', body_hi = 'पूरी ऊर्जा निकाल नहीं पाया और सोने से इनकार कर रहा है। पापा को मदद के लिए बुलाइए। जब वे बच्चे को पीठ पर बिठाकर घोड़ा बनते हैं, तो कमरा ठहाकों से भर जाता है और जमा हुआ सारा शारीरिक तनाव, वह अंतहीन ऊर्जा पसीने के साथ सेकंडों में गायब हो जाती है।', body_id = 'Ia belum sempat menyalurkan seluruh energinya dan menolak tidur. Panggil Ayah untuk membantu. Saat Ayah menggendongnya di punggung dan berlari seperti kuda, tawa memenuhi kamar, dan semua stres fisik serta energi yang tak habis-habis itu lenyap dalam hitungan detik bersama keringat.', body_ja = 'エネルギーを発散しきれず、寝るのをいやがっています。パパに助けを求めましょう。パパが子どもを背中にのせてお馬さんになれば、部屋は笑い声でいっぱいになり、たまっていた体のストレスも尽きないエネルギーも、汗と一緒にあっという間に消えていきます。', body_ko = '에너지를 다 쓰지 못해 잠자리를 거부하나요? 아빠를 불러 주세요. 아빠가 아이를 등에 태우고 말처럼 달리면 웃음소리가 방을 채우고, 쌓인 몸의 스트레스와 끝없는 에너지가 땀과 함께 몇 초 만에 사라져요.', body_nl = 'Hij is zijn energie niet helemaal kwijtgeraakt en verzet zich tegen bedtijd. Roep papa te hulp. Als hij hem op zijn rug neemt en paardje speelt, vult de kamer zich met geschater en verdwijnt alle opgebouwde lichamelijke stress en die eindeloze energie zwetend in een paar seconden.', body_pl = 'Nie wyładował do końca energii i buntuje się przed łóżkiem. Wezwij tatę na pomoc. Gdy weźmie go na barana i pogalopuje jak koń, śmiech wypełni pokój, a całe nagromadzone napięcie i ta niewyczerpana energia znikną w kilka sekund.', body_pt = 'Não conseguiu gastar toda a energia e recusa ir para a cama. Chame o pai para ajudar. Quando ele põe a criança às costas e faz de cavalo a galopar, as gargalhadas enchem o quarto e todo o stress físico acumulado, aquela energia sem fim, desaparece em segundos, a suar.', body_sv = 'Barnet har inte fått ur sig all energi och vägrar gå och lägga sig. Kalla på pappa. När han tar barnet på ryggen och leker häst fylls rummet av skratt, och all ansamlad fysisk stress och den ändlösa energin försvinner på några sekunder i form av svett.', body_vi = 'Bé chưa xả hết năng lượng và nhất quyết không chịu lên giường. Hãy gọi bố đến giúp. Khi bố cõng bé chơi trò cưỡi ngựa, tiếng cười ngập tràn căn phòng, mọi căng thẳng thể chất và nguồn năng lượng bất tận ấy sẽ tan biến chỉ trong vài giây cùng những giọt mồ hôi.', body_zh = '精力还没释放完，就是不肯上床。叫爸爸来帮忙吧。爸爸把宝宝驮在背上“骑大马”时，笑声充满房间，积攒的所有身体压力和用不完的精力，几秒钟内就随着汗水消失了。' WHERE id = '55f7cd1c-adbb-4e6a-bcc0-5847c157d42a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apoyo de la Comunidad 💬', body_es = 'Estás muy cansada y no quieres explicar nada a nadie ni desahogarte. Entra en la Comunidad Anacan y limítate a leer. Ver cómo otras madres lidian con las mismas crisis absurdas es el consuelo silencioso más poderoso.', title_fr = 'Le soutien de la Communauté 💬', body_fr = 'Vous êtes très fatiguée et n''avez envie ni de rien expliquer à personne, ni de vous confier. Entrez dans la Communauté Anacan et contentez-vous de lire. Voir comment d''autres mamans font face aux mêmes crises absurdes est le plus puissant des réconforts silencieux.', title_hi = 'कम्युनिटी का सहारा 💬', body_hi = 'आप बहुत थकी हैं और किसी को कुछ समझाना या दिल की बात कहना नहीं चाहतीं। Anacan कम्युनिटी में जाइए और बस पढ़िए। यह देखना कि दूसरी माँएँ भी ऐसे ही बेतुके संकटों से कैसे जूझती हैं, सबसे ताकतवर खामोश सांत्वना है।', title_id = 'Dukungan komunitas 💬', body_id = 'Anda sangat lelah dan tidak ingin menjelaskan apa pun atau curhat kepada siapa pun. Masuklah ke Komunitas Anacan dan cukup jadi pembaca. Melihat bagaimana ibu-ibu lain menghadapi krisis absurd yang sama adalah penghiburan diam yang paling ampuh.', title_ja = 'コミュニティの支え 💬', body_ja = 'とても疲れていて、誰にも何も説明したくないし、話したくもない。Anacanコミュニティを開いて、読むだけにしましょう。ほかのママたちが同じようなおかしなかんしゃくとどう向き合っているかを見ることが、いちばん強い静かななぐさめになります。', title_ko = '커뮤니티의 응원 💬', body_ko = '너무 지쳐서 누구에게도 설명하거나 털어놓고 싶지 않나요? Anacan 커뮤니티에 들어가 그냥 읽기만 하세요. 다른 엄마들이 똑같이 엉뚱한 위기를 어떻게 헤쳐 가는지 보는 것이 가장 강력한 조용한 위로예요.', title_nl = 'Steun van de Community 💬', body_nl = 'Je bent heel moe en wilt niemand iets uitleggen of je hart luchten. Ga naar de Anacan Community en lees alleen mee. Zien hoe andere mama''s met precies dezelfde absurde crisissen omgaan, is de sterkste stille troost.', title_pl = 'Wsparcie Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i nie chcesz nikomu niczego tłumaczyć ani się zwierzać. Wejdź do Społeczności Anacan i tylko czytaj. Widok tego, jak inne mamy radzą sobie z tymi samymi absurdalnymi kryzysami, to najsilniejsze ciche pocieszenie.', title_pt = 'O apoio da comunidade 💬', body_pt = 'Está muito cansada e não quer explicar nada a ninguém nem desabafar. Entre na Comunidade Anacan e limite-se a ler. Ver como outras mães lidam com as mesmas crises absurdas é o conforto silencioso mais poderoso.', title_sv = 'Gemenskapens stöd 💬', body_sv = 'Du är väldigt trött och vill inte förklara något för någon eller prata av dig. Gå in i Anacan Community och bara läs. Att se hur andra mammor hanterar samma absurda kriser är den starkaste tysta trösten.', title_vi = 'Sự hỗ trợ từ Cộng đồng 💬', body_vi = 'Mẹ quá mệt và không muốn giải thích hay tâm sự với ai. Hãy vào Cộng đồng Anacan và chỉ đọc thôi. Thấy các mẹ khác đối mặt với những cơn khủng hoảng "khó đỡ" giống hệt thế nào chính là sự an ủi thầm lặng mạnh mẽ nhất.', title_zh = '社区的支持 💬', body_zh = '累坏了，什么都不想跟任何人解释，也不想倾诉？进入Anacan社区，只当个读者就好。看到其他妈妈怎样应对同样荒诞的崩溃，就是最有力的无声安慰。' WHERE id = '4418649d-d556-4a03-af91-b1d0242b6324' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dictador matutino en acción 👑', body_es = '«¡Ahí no te sientes tú, se sienta mi osito!». En el desayuno es él quien manda en toda la mesa. Sin romper su voluntad de golpe, mantén el equilibrio y la paz diciendo: «Vale, que el osito se siente ahí y yo aquí».', title_fr = 'Le dictateur du matin est à l''œuvre 👑', body_fr = '« Ne t''assieds pas là, c''est la place de mon nounours ! » Au petit-déjeuner, c''est lui qui dirige toute la table. Sans briser sa volonté, préservez l''équilibre et la paix : « D''accord, ton nounours s''assied là, et moi ici. »', title_hi = 'सुबह का तानाशाह ड्यूटी पर 👑', body_hi = '‘वहाँ तुम मत बैठो, मेरा टेडी बैठेगा!’ नाश्ते पर पूरी मेज़ वही चलाता है। उसकी इच्छा को एकदम से तोड़े बिना, ‘ठीक है, टेडी वहाँ बैठे, मैं यहाँ बैठती हूँ’ कहकर संतुलन और कमरे की शांति बनाए रखिए।', title_id = 'Diktator pagi sedang bertugas 👑', body_id = '''Jangan duduk di situ, itu tempat beruangku!'' Saat sarapan, ia yang mengatur seluruh meja. Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dan kedamaian dengan berkata ''Baik, beruangnya duduk di situ, Mama duduk di sini''.', title_ja = '朝の独裁者、活動中 👑', body_ja = '「そこにママは座らないで、くまさんが座るの！」朝ごはんのテーブルは、すべてこの子が仕切っています。意志をばっさり折らずに、「いいよ、くまさんはそこ、ママはここね」と言って、バランスと部屋の平和を守りましょう。', title_ko = '아침의 독재자 출근 완료 👑', body_ko = '''거기 엄마가 앉지 마, 곰돌이가 앉을 거야!'' 아침 식탁 전체를 아이가 지휘하나요? 의지를 확 꺾지 말고 ''좋아, 곰돌이는 거기 앉고 엄마는 여기 앉을게''라며 균형과 평화를 지켜 주세요.', title_nl = 'De ochtenddictator aan het werk 👑', body_nl = '''Daar mag jij niet zitten, daar zit mijn beertje!'' Bij het ontbijt heeft hij de hele tafel in handen. Breek zijn wil niet hard, maar bewaar de balans en de vrede: ''Goed, het beertje zit daar en ik zit hier.''', title_pl = 'Poranny dyktator w akcji 👑', body_pl = '„Nie siadaj tam, tam usiądzie mój miś!” Przy śniadaniu to on rządzi całym stołem. Nie łamiąc ostro jego woli, zachowaj równowagę i spokój: „Dobrze, miś usiądzie tam, a ja tutaj”.', title_pt = 'O ditador da manhã em ação 👑', body_pt = '"Não te sentes aí, quem se senta é o meu ursinho!" Ao pequeno-almoço é ele quem manda na mesa toda. Sem quebrar a vontade dele de forma brusca, diga "Está bem, o ursinho senta-se aí e eu sento-me aqui" e mantenha o equilíbrio e a paz.', title_sv = 'Morgondiktatorn i tjänst 👑', body_sv = '”Där får du inte sitta, nallen ska sitta där!” Vid frukosten styr barnet hela bordet. Utan att knäcka barnets vilja, säg ”Okej, nallen sitter där och jag sitter här” och behåll balansen och freden i rummet.', title_vi = 'Nhà độc tài buổi sáng đang làm việc 👑', body_vi = '"Mẹ đừng ngồi đó, gấu bông của con sẽ ngồi đấy!" Bé điều khiển cả bàn ăn sáng. Để không bẻ gãy ý chí của bé, hãy giữ cân bằng và hòa khí bằng câu: "Được rồi, gấu bông ngồi đó, còn mẹ ngồi đây".', title_zh = '早晨的小独裁者上岗了 👑', body_zh = '“你别坐那儿，那是小熊的位置！”早餐时整张桌子都归宝宝指挥。别硬生生地压下宝宝的意愿，说一句“好，小熊坐那儿，我坐这儿”，守住平衡和房间里的和平。' WHERE id = '6e6ecb59-b07b-44ae-b10f-31d088fcccf0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rebelión contra la siesta 🥱', body_es = '¿No quiere ir a la cama y llora? No le obligues. Baja las luces de la habitación y crea una rutina nueva anunciando la «hora de hojear libros en silencio»: así descansaréis los dos, cada uno a su manera.', title_fr = 'La révolte de la sieste 🥱', body_fr = 'Il ne veut pas aller au lit et pleure ? Ne le forcez pas. Baissez les lumières de la chambre et annoncez « l''heure des livres en silence » pour créer une nouvelle routine qui vous reposera tous les deux, chacun à votre façon.', title_hi = 'दिन की नींद से बगावत 🥱', body_hi = 'सोने नहीं जाना चाहता और रोता है? ज़बरदस्ती मत कीजिए। कमरे की रोशनी धीमी करके ‘चुपचाप किताब पलटने का समय’ घोषित कीजिए और एक नया रूटीन बनाइए जो आप दोनों को आराम दे, ताकि आप और वह, दोनों अलग तरह से आराम कर सकें।', title_id = 'Pemberontakan tidur siang 🥱', body_id = 'Ia tidak mau tidur dan menangis? Jangan memaksa. Redupkan lampu kamar dan ciptakan rutinitas baru dengan mengumumkan ''Waktu membaca buku dengan tenang'', agar Anda dan ia sama-sama beristirahat dengan cara yang berbeda.', title_ja = 'お昼寝ストライキ 🥱', body_ja = 'ベッドに行きたくなくて泣いている？無理強いしないで。部屋の明かりを落として「静かな絵本の時間」を宣言し、ふたりともほっとできる新しいルーティンをつくりましょう。そうすれば、あなたもこの子も、いつもとちがう形で休めます。', title_ko = '낮잠 반란 🥱', body_ko = '자러 가기 싫다며 우나요? 억지로 재우지 마세요. 방 불을 낮추고 ''조용히 책 넘기는 시간''을 선언해 새로운 루틴을 만들어 보세요. 그러면 엄마도 아이도 색다르게 쉴 수 있어요.', title_nl = 'Opstand bij het middagslaapje 🥱', body_nl = 'Wil hij niet naar bed en huilt hij? Dwing hem niet. Dim de lichten in de kamer en kondig een ''stil boekjesuurtje'' aan, een nieuwe routine waar jullie allebei op een andere manier van tot rust komen.', title_pl = 'Bunt przed drzemką 🥱', body_pl = 'Nie chce iść do łóżka i płacze? Nie zmuszaj. Przygaś światła w pokoju i ogłoś „cichą godzinę z książeczką”, tworząc nową rutynę, dzięki której oboje odpoczniecie, każde na swój sposób.', title_pt = 'A revolta da sesta 🥱', body_pt = 'Não quer ir para a cama e chora? Não o obrigue. Baixe as luzes do quarto e crie uma nova rotina anunciando a "hora de folhear livros em silêncio": assim descansam os dois, cada um à sua maneira.', title_sv = 'Upproret mot tuppluren 🥱', body_sv = 'Vill barnet inte gå och lägga sig och gråter? Tvinga inte. Dämpa ljuset i rummet och utlys en ”tyst bläddra-i-böcker-stund”, så skapar du en ny rutin där både du och barnet får vila på ett annat sätt.', title_vi = 'Cuộc nổi loạn giờ ngủ trưa 🥱', body_vi = 'Bé không muốn lên giường và khóc? Đừng ép. Hãy giảm đèn trong phòng và tuyên bố "Giờ lật sách yên lặng" để tạo một nếp sinh hoạt mới, nhờ đó cả mẹ và bé đều được nghỉ ngơi theo một cách khác.', title_zh = '午睡大反抗 🥱', body_zh = '不肯上床还哭闹？别强迫。把房间灯光调暗，宣布“安静翻书时间”，建立一个新的、让你们俩都能休息的日常流程，这样你和宝宝都能换个方式放松一下。' WHERE id = '1b1ca975-b7c1-4e57-9e31-3f5e83031e0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los dos estáis hartos de los libros de siempre y en la habitación hay un ambiente aburrido. Abre Cuentos inteligentes y esta noche deja que él dirija la historia. Pregúntale: «¿Y ahora adónde va ese coche volador?», y deja que se duerma conquistando su imaginación.', body_fr = 'Vous en avez assez tous les deux des livres classiques, et l''ambiance de la chambre est monotone. Ouvrez les Contes intelligents et, ce soir, laissez-le diriger l''histoire. Demandez : « Où va aller la voiture volante maintenant ? » et laissez-le s''endormir en conquérant le monde dans son imagination.', body_hi = 'आप दोनों पुरानी किताबों से ऊब चुके हैं और कमरे का माहौल उबाऊ है। स्मार्ट कहानियाँ खोलिए और आज शाम कहानी की दिशा उसे तय करने दीजिए। पूछिए, ‘अब वह उड़ने वाली गाड़ी कहाँ जाए?’ और उसे अपनी कल्पना में दुनिया जीतते हुए सोने दीजिए।', body_id = 'Kalian berdua sudah bosan dengan buku klasik dan suasana kamar terasa membosankan. Buka Dongeng Pintar dan malam ini biarkan ia yang mengarahkan alur cerita. Tanyakan ''Sekarang mobil terbang itu pergi ke mana?'', dan biarkan ia tertidur sambil menaklukkan dunia khayalnya.', body_ja = '定番の絵本にはふたりとも飽きて、部屋はなんだかたいくつな雰囲気。「スマートおはなし」を開いて、今夜はストーリーの行き先をこの子にまかせましょう。「この空飛ぶ車、次はどこへ行く？」とたずねて、空想の中で冒険しながら眠りにつかせてあげて。', body_ko = '늘 읽던 책이 둘 다 지겨워지고 방 안 분위기도 따분한가요? 스마트 동화를 열고 오늘 저녁엔 이야기의 방향을 아이에게 맡겨 보세요. ''이제 날아다니는 자동차는 어디로 갈까?'' 묻고, 상상 속 세상을 정복하며 잠들게 해 주세요.', body_nl = 'Jullie zijn allebei de klassieke boeken beu en er hangt een saaie sfeer in de kamer. Open Slimme sprookjes en laat hem vanavond het verhaal sturen. Vraag: ''Waar moet die vliegende auto nu naartoe?'' en laat hem in slaap vallen terwijl hij in zijn fantasie de wereld verovert.', body_pl = 'Klasyczne książeczki znudziły się wam obojgu, a w pokoju panuje nudna atmosfera. Otwórz Mądre bajki i pozwól mu dziś wieczorem kierować fabułą. Zapytaj: „Dokąd teraz ma lecieć to latające auto?” i niech zaśnie, podbijając świat w wyobraźni.', body_pt = 'Estão os dois fartos dos livros clássicos e há um ambiente aborrecido no quarto. Abra as Histórias Inteligentes e deixe que esta noite seja ele a guiar o enredo. Pergunte "E agora, para onde vai aquele carro voador?" e deixe-o adormecer a conquistar mundos na imaginação.', body_sv = 'Ni är båda trötta på de klassiska böckerna och stämningen i rummet är tråkig. Öppna Smarta sagor och låt barnet styra handlingen i kväll. Fråga ”Vart ska den flygande bilen åka nu?” och låt barnet somna medan det erövrar sin drömvärld.', body_vi = 'Cả hai mẹ con đều đã chán những cuốn sách quen thuộc và không khí trong phòng thật tẻ nhạt. Hãy mở Truyện cổ tích thông minh và tối nay để bé dẫn dắt cốt truyện. Hỏi bé: "Giờ chiếc ô tô bay nên đi đâu nhỉ?", rồi để bé chìm vào giấc ngủ trong khi chinh phục thế giới tưởng tượng.', body_zh = '经典故事书你们俩都看腻了，房间里的气氛也有点沉闷。打开智慧童话，今晚让宝宝来决定故事走向。问问：“现在那辆会飞的车该去哪儿？”就让宝宝在想象中征服一切后入睡吧。' WHERE id = '8ca291c9-dcd2-4396-9580-b58e8c48c73a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El rival del espejo 🪞', body_es = 'Delante del espejo frunce el ceño y pone caras enfadadas y raras. Está comprobando cómo se ven las emociones en su cara. Disfruta observando sin hacer ruido el ensayo de este pequeño actor de teatro.', title_fr = 'Le rival dans le miroir 🪞', body_fr = 'Devant le miroir, il fronce les sourcils et fait des grimaces fâchées ou bizarres. Il teste à quoi ressemblent les émotions sur son visage. Observez sans bruit, avec plaisir, la répétition de ce petit acteur de théâtre.', title_hi = 'आईने में प्रतिद्वंद्वी 🪞', body_hi = 'आईने के सामने खड़े होकर खुद ही भौंहें चढ़ाता है, गुस्से वाले और अजीब चेहरे बनाता है। वह परख रहा है कि भावनाएँ चेहरे पर कैसी दिखती हैं। बिना आवाज़ किए दूर से इस नन्हे थिएटर कलाकार की रिहर्सल का मज़ा लीजिए।', title_id = 'Saingan di cermin 🪞', body_id = 'Ia berdiri di depan cermin, mengerutkan alis dan membuat ekspresi marah dan aneh pada dirinya sendiri. Ia sedang menguji bagaimana emosi terlihat di wajahnya. Saksikan latihan aktor teater mini ini dengan senang hati dari jauh tanpa bersuara.', title_ja = '鏡の中のライバル 🪞', body_ja = '鏡の前に立って、ひとりで眉をしかめたり、怒った顔やへんな顔をしたりしている。気持ちが顔にどう表れるかを試しているんです。音を立てずに、この小さな舞台俳優の練習を楽しく見守りましょう。', title_ko = '거울 속 라이벌 🪞', body_ko = '거울 앞에 서서 혼자 눈살을 찌푸리고 화난 표정, 이상한 표정을 짓나요? 감정이 얼굴에 어떻게 보이는지 시험하는 중이에요. 옆에서 소리 내지 말고 이 작은 연극배우의 연습을 즐겁게 지켜보세요.', title_nl = 'De rivaal in de spiegel 🪞', body_nl = 'Hij staat voor de spiegel en fronst zijn wenkbrauwen, trekt boze en rare gezichten. Hij test hoe emoties eruitzien op zijn gezicht. Geniet zonder geluid te maken van een afstand van de repetitie van deze kleine toneelspeler.', title_pl = 'Rywal w lustrze 🪞', body_pl = 'Stoi przed lustrem, marszczy brwi i robi do siebie złe i dziwne miny. Sprawdza, jak emocje wyglądają na jego twarzy. Bezgłośnie, z boku, z przyjemnością obserwuj próbę tego miniaturowego aktora teatralnego.', title_pt = 'O rival no espelho 🪞', body_pt = 'Põe-se em frente ao espelho a franzir a testa e a fazer caras zangadas e estranhas para si próprio. Está a testar como as emoções aparecem no rosto. Observe com gosto, à distância e sem fazer barulho, o ensaio deste pequeno ator de teatro.', title_sv = 'Rivalen i spegeln 🪞', body_sv = 'Barnet står framför spegeln och rynkar pannan, gör arga och konstiga miner. Barnet testar hur känslorna syns i ansiktet. Titta njutningsfullt och tyst från sidan på den lilla teaterskådespelarens repetition.', title_vi = 'Đối thủ trong gương 🪞', body_vi = 'Bé đứng trước gương, tự nhíu mày, làm những biểu cảm giận dữ và kỳ quặc. Bé đang thử xem cảm xúc hiện lên trên khuôn mặt mình ra sao. Hãy lặng lẽ, thích thú theo dõi buổi tập của "diễn viên kịch" tí hon này từ xa.', title_zh = '镜子里的对手 🪞', body_zh = '站在镜子前，对着自己皱眉，做出生气又奇怪的表情。宝宝在测试情绪在脸上是什么样子。在一旁别出声，好好欣赏这位迷你剧场演员的排练吧。' WHERE id = 'bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Minilaboratorio en la bañera 🛀', body_es = 'Echa al agua jabones de distintos colores y prepara pociones. El baño acaba empapado, sí. Pero está aprendiendo sobre disolventes y mezclas de sustancias. Esta exploración científica es la mejor forma de quitarle el cansancio de la tarde y prepararle para un sueño tranquilo.', title_fr = 'Mini-laboratoire dans la baignoire 🛀', body_fr = 'Il mélange des savons de différentes couleurs dans l''eau pour préparer une potion. La salle de bain est inondée, oui. Mais il découvre les solvants et le mélange des substances. Cette exploration scientifique est le meilleur moyen d''évacuer la fatigue du soir et de le préparer à un sommeil paisible.', title_hi = 'बाथटब में मिनी प्रयोगशाला 🛀', body_hi = 'पानी में अलग-अलग रंग के साबुन मिलाकर जादुई घोल बना रहा है। बाथरूम गंदा हो रहा है, हाँ। पर वह घुलना और चीज़ों का मिलना सीख रहा है। यह वैज्ञानिक खोज शाम की थकान उतारकर उसे शांत नींद के लिए तैयार करने का सबसे अच्छा ज़रिया है।', title_id = 'Laboratorium mini di bak mandi 🛀', body_id = 'Ia mencampur sabun berwarna-warni ke dalam air dan membuat ramuan. Ya, kamar mandi jadi basah kuyup. Tapi ia sedang belajar tentang pelarut dan pencampuran zat. Penjelajahan ilmiah ini adalah cara terindah untuk menghilangkan lelah malam hari dan menyiapkannya untuk tidur yang tenang.', title_ja = 'お風呂のミニ実験室 🛀', body_ja = 'お湯にいろいろな色の石けんを入れて、魔法の薬をつくっています。バスルームは大変なことに、そうですね。でも、溶けることやまざることを学んでいるんです。この科学の探検は、夜の疲れをとって、静かな眠りへ導いてくれるいちばんの方法です。', title_ko = '욕조 속 미니 실험실 🛀', body_ko = '물에 여러 색깔 비누를 섞어 물약을 만드나요? 네, 욕실은 엉망이 되죠. 하지만 녹이는 것, 물질이 섞이는 것을 배우는 중이에요. 이런 과학 탐험은 저녁의 피로를 덜고 차분한 잠을 준비시키는 가장 좋은 방법이에요.', title_nl = 'Minilaboratorium in bad 🛀', body_nl = 'Hij mengt verschillende kleuren zeep in het water en maakt een toverdrankje. Ja, de badkamer wordt een zooi. Maar hij leert over oplosmiddelen en hoe stoffen zich mengen. Deze wetenschappelijke ontdekkingstocht neemt de vermoeidheid van de avond weg en maakt hem klaar voor een rustige slaap.', title_pl = 'Mini laboratorium w wannie 🛀', body_pl = 'Miesza w wodzie mydła w różnych kolorach i przygotowuje eliksir. Tak, łazienka jest w opłakanym stanie. Ale uczy się o rozpuszczalnikach i mieszaniu substancji. Ta naukowa wyprawa to najpiękniejszy sposób, by zabrać wieczorne zmęczenie i przygotować go do spokojnego snu.', title_pt = 'Minilaboratório na banheira 🛀', body_pt = 'Mistura na água sabonetes de várias cores e faz poções. A casa de banho fica uma desgraça, sim. Mas está a aprender sobre dissolventes e misturas de substâncias. Esta exploração científica é a melhor forma de lhe tirar o cansaço da noite e o preparar para um sono tranquilo.', title_sv = 'Minilaboratorium i badkaret 🛀', body_sv = 'Barnet blandar tvålar i olika färger i vattnet och gör trolldrycker. Ja, badrummet blir blött. Men barnet lär sig om lösningsmedel och hur ämnen blandas. Den vetenskapliga upptäcktsfärden tar bort kvällens trötthet och är det bästa sättet att förbereda barnet för en lugn sömn.', title_vi = 'Phòng thí nghiệm mini trong bồn tắm 🛀', body_vi = 'Bé pha các loại xà phòng màu khác nhau vào nước để chế "thuốc thần". Phòng tắm bừa bộn, đúng vậy. Nhưng bé đang học về sự hòa tan, cách các chất trộn lẫn. Cuộc khám phá khoa học này là cách tuyệt vời nhất để xua tan mệt mỏi buổi tối và chuẩn bị cho bé một giấc ngủ yên bình.', title_zh = '浴缸里的迷你实验室 🛀', body_zh = '往水里加入不同颜色的肥皂，调制“魔法药水”。是的，浴室被弄得一团糟。但宝宝在学习溶解和物质的混合。这场科学探索能带走傍晚的疲惫，是让宝宝准备好安稳入睡的最好方式。' WHERE id = '3481c7e9-17f1-45e8-b5ca-16ba68fd1628' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La revolución del contacto 🔋', body_es = 'Estás agotada físicamente de un peque que se te sube encima y te tira del pelo todo el día. Déjale ya en un lugar seguro y vete a otra habitación. Escribe en el Diario de ánimo «Mi cuerpo no me pertenece» y suelta la carga psicológica de este síndrome «touched out».', title_fr = 'La révolution du toucher 🔋', body_fr = 'Vous êtes physiquement épuisée par cet enfant qui vous a grimpé dessus et tiré les cheveux toute la journée. Mettez-le tout de suite dans un endroit sûr et passez dans une autre pièce. Écrivez dans le Journal d''humeur « Mon corps ne m''appartient plus » pour vous libérer du poids psychologique de ce syndrome « touched out ».', title_hi = 'छुए जाने के खिलाफ़ बगावत 🔋', body_hi = 'दिनभर आपके शरीर पर चढ़ने, बाल खींचने वाले बच्चे से आप शारीरिक रूप से थक चुकी हैं। तुरंत उसे किसी सुरक्षित जगह छोड़कर दूसरे कमरे में जाइए। मूड डायरी में ‘मेरा शरीर मेरा नहीं रहा’ लिखकर इस ‘टच्ड आउट’ हालत का मानसिक बोझ उतारिए।', title_id = 'Revolusi sentuhan 🔋', body_id = 'Anda kehabisan tenaga fisik karena anak yang seharian memanjat tubuh Anda dan menarik rambut Anda. Segera letakkan ia di tempat yang aman dan pindah ke ruangan lain. Tulis ''Tubuhku bukan milikku'' di Buku Harian Suasana Hati dan lepaskan beban psikologis sindrom lelah disentuh (touched out) ini.', title_ja = 'さわられ疲れの反乱 🔋', body_ja = '一日じゅう体によじのぼり、髪を引っぱる子どもに、体はもうへとへと。すぐに子どもを安全な場所に置いて、別の部屋へ移りましょう。「気分日記」に「わたしの体はわたしのものじゃない」と書いて、さわられ疲れ（touched out）の心の重荷をおろして。', title_ko = '스킨십 혁명 🔋', body_ko = '하루 종일 몸에 기어오르고 머리카락을 잡아당기는 아이 때문에 몸이 완전히 지쳤나요? 바로 아이를 안전한 곳에 두고 다른 방으로 가세요. 기분 일기에 ''내 몸이 내 것 같지 않아''라고 적으며 스킨십 피로(touched out)의 마음의 짐을 털어내세요.', title_nl = 'De aanraakrevolutie 🔋', body_nl = 'Je bent lichamelijk uitgeput van een kind dat de hele dag op je klimt en aan je haar trekt. Zet hem meteen op een veilige plek en ga naar een andere kamer. Schrijf in je Stemmingsdagboek ''Mijn lichaam is niet van mij'' en gooi de mentale last van dit touched-out-gevoel van je af.', title_pl = 'Rewolucja dotyku 🔋', body_pl = 'Jesteś fizycznie wyczerpana dzieckiem, które cały dzień wspinało się na ciebie i ciągnęło za włosy. Od razu zostaw go w bezpiecznym miejscu i przejdź do innego pokoju. Napisz w Dzienniku nastroju „Moje ciało nie należy do mnie” i zrzuć psychiczny ciężar syndromu touched out.', title_pt = 'A revolução do toque 🔋', body_pt = 'Está fisicamente esgotada da criança que lhe trepa pelo corpo e lhe puxa o cabelo o dia todo. Deixe-a já num sítio seguro e passe para outra divisão. Escreva no Diário de Humor "O meu corpo não me pertence" e liberte o peso psicológico desta síndrome "touched out".', title_sv = 'Beröringsrevolutionen 🔋', body_sv = 'Du är fysiskt slut efter barnet som klättrat på dig och dragit i håret hela dagen. Lägg genast barnet på ett säkert ställe och gå in i ett annat rum. Skriv ”Min kropp tillhör inte mig” i Humördagboken och släpp den psykiska bördan av touched out-syndromet.', title_vi = 'Cuộc cách mạng của sự đụng chạm 🔋', body_vi = 'Mẹ kiệt sức về thể chất vì bé cả ngày trèo lên người, giật tóc mẹ. Hãy đặt bé vào chỗ an toàn ngay và sang phòng khác. Viết vào Nhật ký tâm trạng: "Cơ thể mình không còn là của mình" để trút bỏ gánh nặng tâm lý của hội chứng "touched out" này.', title_zh = '触碰的“革命” 🔋', body_zh = '一整天孩子往你身上爬、扯你头发，你的身体已经精疲力竭。马上把宝宝放在安全的地方，去另一个房间。在心情日记里写下“我的身体不属于我”，卸下这种“触碰疲劳”（touched out）带来的心理负担。' WHERE id = '628064ef-a8e4-4e1f-b2f9-27acab4d05cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aislarse del mundo dentro del armario 🚪', body_es = 'De repente se ha cortado el ruido en casa. Le has encontrado jugando solo, a oscuras, dentro del armario de la ropa. No es depresión, es solo un momento de reinicio emocional. Entorna la puerta suavemente y reconócele este lujo del espacio personal.', title_fr = 'S''isoler dans le placard 🚪', body_fr = 'Le bruit s''est arrêté au milieu de la maison. Vous l''avez trouvé dans l''armoire, jouant seul dans le noir. Ce n''est pas de la déprime, juste un moment de redémarrage émotionnel. Fermez doucement la porte et accordez-lui ce luxe d''un espace personnel.', title_hi = 'अलमारी के अंदर दुनिया से दूरी 🚪', body_hi = 'घर के बीच शोर थम गया। आपने उसे कपड़ों की अलमारी के अंदर अँधेरे में अकेले खेलते पाया। यह उदासी नहीं, बस भावनाओं का रीस्टार्ट पल है। दरवाज़ा हल्का-सा भिड़ा दीजिए और उसे निजी जगह की यह खास सुविधा दीजिए।', title_id = 'Menyendiri di dalam lemari 🚪', body_id = 'Kebisingan di tengah rumah tiba-tiba berhenti. Anda menemukannya bermain sendirian dalam gelap di dalam lemari baju. Ini bukan depresi, hanya momen restart emosional. Tutup pintunya sedikit dan akui haknya atas kemewahan ruang pribadi ini.', title_ja = 'クローゼットにこもる 🚪', body_ja = '家の中の騒がしさがぴたりとやんで、見ると暗いクローゼットの中でひとりで遊んでいた。これは落ちこみではなく、ただ気持ちを再起動している時間です。ドアをそっと閉めて、このプライベートな空間というぜいたくを認めてあげましょう。', title_ko = '옷장 속 나만의 공간 🚪', body_ko = '집 안의 소음이 뚝 끊겼어요. 옷장 안 어둠 속에서 혼자 놀고 있는 아이를 발견했나요? 우울한 게 아니라 감정을 재시작하는 순간일 뿐이에요. 문을 살짝 닫아 주고 이 개인 공간의 사치를 인정해 주세요.', title_nl = 'Even weg van de wereld in de kast 🚪', body_nl = 'Midden in huis viel het lawaai stil. Je vond hem alleen spelend in het donker in de kledingkast. Dat is geen depressie, maar gewoon een moment van emotionele herstart. Doe de deur zachtjes op een kier en gun hem de luxe van een eigen plekje.', title_pl = 'Odosobnienie w szafie 🚪', body_pl = 'W środku domu nagle ucichło. Znalazłaś go w szafie z ubraniami, gdzie bawił się sam w ciemności. To nie depresja, tylko chwila emocjonalnego restartu. Lekko przymknij drzwi i przyznaj mu ten luksus przestrzeni osobistej.', title_pt = 'Isolamento social dentro do armário 🚪', body_pt = 'O barulho no meio da casa parou. Encontrou-o dentro do roupeiro, às escuras, a brincar sozinho. Não é depressão, é apenas um momento de restart emocional. Encoste a porta de leve e reconheça-lhe este luxo do espaço pessoal.', title_sv = 'Isolering från samhället i garderoben 🚪', body_sv = 'Mitt i hemmet tystnade oväsendet. Du hittade barnet lekande ensamt i mörkret inne i klädgarderoben. Det är inte depression, bara en emotionell omstart. Dra försiktigt igen dörren och ge barnet lyxen av eget utrymme.', title_vi = 'Ẩn mình trong tủ quần áo 🚪', body_vi = 'Giữa nhà, tiếng ồn bỗng im bặt. Mẹ thấy bé đang một mình chơi trong bóng tối, bên trong tủ quần áo. Đây không phải trầm cảm, mà chỉ là lúc bé "khởi động lại" cảm xúc. Hãy khép hờ cửa và tôn trọng sự "xa xỉ" về không gian riêng này của bé.', title_zh = '衣柜里的“与世隔绝” 🚪', body_zh = '家里的吵闹声突然停了。你发现宝宝一个人在衣柜里、在黑暗中玩着。这不是抑郁，只是情绪“重启”的时刻。把门轻轻掩上，承认宝宝享受这份私人空间的“奢侈”吧。' WHERE id = '6dfd2aa0-4f21-483a-bbab-d26de61eb620' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El ladrón de móviles 📱', title_fr = 'Le voleur de téléphone 📱', title_hi = 'फ़ोन चोर 📱', title_id = 'Pencuri ponsel 📱', title_ja = 'スマホどろぼう 📱', title_ko = '휴대폰 도둑 📱', title_nl = 'De telefoondief 📱', title_pl = 'Złodziej telefonu 📱', title_pt = 'O ladrão de telemóveis 📱', title_sv = 'Telefontjuven 📱', title_vi = 'Kẻ trộm điện thoại 📱', title_zh = '手机小偷 📱' WHERE id = '8d6625c2-a9b5-42f5-804d-da69978a47f8' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La política del «¡Vísteme tú!» 👖', body_es = 'Levanta los pies al aire y dice: «Soy un bebé, vísteme tú». Van y vienen entre la independencia y la dependencia. No le vistas a la fuerza. Deja la ropa a su lado y manipúlale con cariño: «Este pantalón de superhéroe espera a su dueño».', title_fr = 'La politique du « Habille-toi tout seul ! » 👖', body_fr = 'Il lève les jambes en l''air : « Je suis un bébé, habille-moi. » Il oscille entre indépendance et dépendance. Ne l''habillez pas de force. Posez les vêtements à côté de lui et manipulez gentiment : « Ce pantalon de super-héros attend son propriétaire. »', title_hi = '‘तुम खुद पहनो!’ वाली नीति 👖', body_hi = 'पैर हवा में उठाकर कहता है, ‘मैं बेबी हूँ, तुम पहनाओ।’ वे आत्मनिर्भरता और निर्भरता के बीच झूलते रहते हैं। ज़बरदस्ती मत पहनाइए। कपड़े उसके पास रखिए और ‘यह सुपरहीरो पैंट अपने मालिक का इंतज़ार कर रही है’ कहकर उसे चतुराई से मनाइए।', title_id = 'Politik ''Pakai sendiri!'' 👖', body_id = 'Ia mengangkat kaki ke atas dan berkata ''Aku bayi, Mama yang pakaikan''. Mereka bolak-balik antara mandiri dan bergantung. Jangan memakaikannya dengan paksa. Letakkan pakaian di sampingnya dan bujuk dengan berkata ''Celana superhero ini sedang menunggu pemiliknya''.', title_ja = '「自分で着て！」の方針 👖', body_ja = '足を宙にあげて「赤ちゃんだから、ママが着せて」と言う。自立と甘えのあいだを行ったり来たりしているんです。無理に着せないで。服をそばに置いて「このスーパーヒーローのズボンが、持ち主を待ってるよ」と、うまく誘いましょう。', title_ko = '''네가 입어!'' 정책 👖', body_ko = '다리를 하늘로 들고 ''나 아기야, 엄마가 입혀 줘''라고 하나요? 독립과 의존 사이를 오가는 중이에요. 억지로 입히지 마세요. 옷을 옆에 두고 ''이 슈퍼히어로 바지가 주인을 기다리고 있대''라며 슬쩍 유도해 보세요.', title_nl = 'Het ''Kleed jezelf aan!''-beleid 👖', body_nl = 'Hij steekt zijn benen in de lucht: ''Ik ben een baby, kleed jij mij aan.'' Ze schommelen tussen zelfstandigheid en afhankelijkheid. Kleed hem niet met dwang aan. Leg de kleren naast hem en verleid hem: ''Deze superheldenbroek wacht op zijn eigenaar.''', title_pl = 'Polityka „Ubierz się sam!” 👖', body_pl = 'Podnosi nogi do góry i mówi: „Jestem dzidziusiem, ty mnie ubierz”. Dzieci krążą między samodzielnością a zależnością. Nie ubieraj go na siłę. Połóż ubranie obok i sprytnie powiedz: „Te spodnie superbohatera czekają na swojego właściciela”.', title_pt = 'A política do "Veste-te tu!" 👖', body_pt = 'Levanta as pernas para o ar e diz "Sou um bebé, veste-me tu". Andam entre a independência e a dependência. Não o vista à força. Ponha a roupa ao lado dele e use um pouco de manipulação: "Estas calças de super-herói estão à espera do dono".', title_sv = 'Politiken ”Klä på dig själv!” 👖', body_sv = 'Barnet lyfter benen mot taket och säger: ”Jag är en bebis, klä på mig.” De pendlar mellan självständighet och beroende. Klä inte på barnet med tvång. Lägg kläderna bredvid och manipulera lite: ”De här superhjältebyxorna väntar på sin ägare.”', title_vi = 'Chính sách "Con tự mặc đi!" 👖', body_vi = 'Bé giơ chân lên trời và nói "Con là em bé, mẹ mặc cho con đi". Bé đang dao động giữa tự lập và phụ thuộc. Đừng ép bé mặc. Hãy đặt quần áo bên cạnh và "dụ" bé: "Chiếc quần siêu anh hùng này đang chờ chủ nhân của nó đấy".', title_zh = '“你自己穿！”的政策 👖', body_zh = '把腿翘到天上说：“我是小宝宝，你给我穿。”他们在独立和依赖之间来回摇摆。别强行给宝宝穿。把衣服放在宝宝旁边，说一句“这条超级英雄裤子在等它的主人呢”，巧妙地引导一下。' WHERE id = 'e750fc50-e44a-47b8-b631-5ac89b90275d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paz interior con el Medidor de sonido 🤫', title_fr = 'La paix intérieure avec le Sonomètre 🤫', title_hi = 'साउंड मीटर के साथ अंदरूनी शांति 🤫', title_id = 'Damai batin dengan Pengukur Suara 🤫', title_ja = 'サウンドメーターで心の平和 🤫', title_ko = '소음 측정기로 찾는 마음의 평화 🤫', title_nl = 'Innerlijke rust met de Geluidsmeter 🤫', title_pl = 'Wewnętrzny spokój z Miernikiem dźwięku 🤫', title_pt = 'Paz interior com o Medidor de Som 🤫', title_sv = 'Inre frid med Ljudmätaren 🤫', title_vi = 'Bình yên nội tâm cùng Đo âm thanh 🤫', title_zh = '用分贝仪找回内心的平静 🤫' WHERE id = 'fa66784d-c126-46e1-ac35-502bd4ad5f50' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consuelo en la Comunidad Anacan 💬', body_es = '¿Te ahoga la sensación de que nunca podrás ser perfecta? Borra esa ilusión de las madres de Instagram. Entra en la Comunidad Anacan, lee las confesiones sinceras de madres con la casa patas arriba y con hijos que rayan las paredes, y di: «Soy totalmente normal».', title_fr = 'Du réconfort dans la Communauté Anacan 💬', body_fr = 'Le sentiment « Je ne serai jamais parfaite » vous étouffe ? Effacez cette illusion des mamans d''Instagram. Entrez dans la Communauté Anacan, lisez les confidences sincères des mamans dont la maison est sens dessus dessous et dont l''enfant a gribouillé les murs, et dites-vous : « Je suis tout à fait normale. »', title_hi = 'Anacan कम्युनिटी में सांत्वना 💬', body_hi = '‘मैं कभी परफ़ेक्ट नहीं बन पाऊँगी’ वाला एहसास आपका दम घोंट रहा है? इंस्टाग्राम वाली माँओं का वह भ्रम मिटा दीजिए। Anacan कम्युनिटी में जाइए, बिखरे घरों वाली और दीवार पर लकीरें खींचने वाले बच्चों की माँओं के सच्चे इकरार पढ़िए और कहिए, ‘मैं बिल्कुल सामान्य हूँ।’', title_id = 'Penghiburan di Komunitas Anacan 💬', body_id = 'Perasaan ''Aku tidak akan pernah bisa sempurna'' membuat Anda sesak? Hapus ilusi ibu-ibu Instagram itu. Masuklah ke Komunitas Anacan, baca pengakuan tulus para ibu yang rumahnya berantakan dan anaknya mencoret dinding, lalu katakan ''Aku sepenuhnya normal''.', title_ja = 'Anacanコミュニティでなぐさめを 💬', body_ja = '「わたしは一生完璧になれない」という気持ちに押しつぶされそう？インスタのママたちという幻想は消しましょう。Anacanコミュニティを開いて、家がぐちゃぐちゃだったり、子どもが壁に落書きしたりしているママたちの正直な打ち明け話を読んで、「わたし、まったく普通だ」と言いましょう。', title_ko = 'Anacan 커뮤니티의 위로 💬', body_ko = '''난 절대 완벽해질 수 없을 거야''라는 마음에 숨이 막히나요? 인스타그램 속 엄마라는 환상은 지우세요. Anacan 커뮤니티에 들어가 집은 엉망이고 아이가 벽에 낙서한 엄마들의 솔직한 고백을 읽으며 ''나 완전히 정상이야''라고 말해 주세요.', title_nl = 'Troost in de Anacan Community 💬', body_nl = 'Overvalt je het gevoel ''Ik word nooit perfect''? Wis die illusie van Instagram-mama''s. Ga naar de Anacan Community, lees de eerlijke bekentenissen van mama''s met een puinhoop in huis en kinderen die op de muur tekenen, en zeg tegen jezelf: ''Ik ben heel normaal.''', title_pl = 'Pocieszenie w Społeczności Anacan 💬', body_pl = 'Dławi cię poczucie „Nigdy nie będę idealna”? Wymaż iluzję mam z Instagrama. Wejdź do Społeczności Anacan, przeczytaj szczere wyznania mam, które mają w domu bałagan, a ich dzieci rysują po ścianach, i powiedz sobie: „Jestem zupełnie normalna”.', title_pt = 'Conforto na Comunidade Anacan 💬', body_pt = 'Sufoca-a a sensação de que "nunca vou ser perfeita"? Apague a ilusão das mães do Instagram. Entre na Comunidade Anacan, leia os desabafos sinceros de mães com a casa de pernas para o ar e filhos que riscam as paredes, e diga "Sou totalmente normal".', title_sv = 'Tröst i Anacan Community 💬', body_sv = 'Kväver känslan ”jag kommer aldrig att kunna bli perfekt” dig? Radera illusionen om Instagrammammor. Gå in i Anacan Community, läs uppriktiga bekännelser från mammor vars hem är i kaos och vars barn klottrar på väggarna, och säg ”Jag är helt normal”.', title_vi = 'Niềm an ủi trong Cộng đồng Anacan 💬', body_vi = 'Cảm giác "Mình sẽ không bao giờ hoàn hảo được" khiến mẹ nghẹt thở? Hãy xóa bỏ ảo tưởng về những bà mẹ Instagram. Vào Cộng đồng Anacan, đọc những lời thú nhận chân thành của các mẹ có nhà cửa bừa bộn, con vẽ bậy lên tường, và tự nhủ: "Mình hoàn toàn bình thường".', title_zh = '在Anacan社区里得到安慰 💬', body_zh = '“我永远都不可能完美”的感觉让你喘不过气？抹掉那些Instagram妈妈的幻象吧。进入Anacan社区，读读那些家里乱成一团、孩子在墙上乱画的妈妈们真诚的心里话，然后告诉自己：“我完全正常。”' WHERE id = '61c7ca48-5a19-4998-8086-07edd1d4d938' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder místico del susurro 🌙', body_es = 'Inventa excusas para escaparse de la cama. Baja del todo la voz y háblale solo en susurros. Para entenderte tendrá que concentrarse físicamente, y esa concentración hipnotizará su cerebro y le dormirá.', title_fr = 'Le pouvoir mystérieux du chuchotement 🌙', body_fr = 'Il invente des excuses pour s''échapper du lit. Baissez complètement la voix et ne parlez plus qu''en chuchotant. Pour vous comprendre, il sera obligé de se concentrer physiquement, et cette concentration hypnotisera son cerveau et l''endormira.', title_hi = 'फुसफुसाहट की रहस्यमयी ताकत 🌙', body_hi = 'बिस्तर से भागने के लिए बहाने गढ़ता है। अपनी आवाज़ पूरी तरह धीमी कीजिए, सिर्फ़ फुसफुसाकर बात कीजिए। आपको समझने के लिए उसे शारीरिक रूप से ध्यान लगाना ही पड़ेगा, और यह एकाग्रता उसके दिमाग को सम्मोहित करके नींद में ले जाएगी।', title_id = 'Kekuatan ajaib bisikan 🌙', body_id = 'Ia mengarang alasan untuk kabur dari tempat tidur. Kecilkan suara Anda sepenuhnya dan bicaralah hanya sambil berbisik. Untuk memahami Anda, ia terpaksa memusatkan perhatian secara fisik, dan fokus ini akan menghipnotis otaknya hingga tertidur.', title_ja = 'ささやきのふしぎな力 🌙', body_ja = 'ベッドから逃げるための言いわけを考えだす。声をぐっと小さくして、ささやき声だけで話しましょう。あなたの言葉を聞きとるために、体ごと集中しなければならず、その集中が脳に催眠術をかけて眠りへ導きます。', title_ko = '속삭임의 신비한 힘 🌙', body_ko = '침대에서 도망치려고 핑계를 지어내나요? 목소리를 한껏 낮추고 속삭이듯만 말하세요. 엄마 말을 알아들으려면 온몸으로 집중해야 하고, 그 집중이 뇌를 최면에 걸린 듯 잠들게 할 거예요.', title_nl = 'De mystieke kracht van fluisteren 🌙', body_nl = 'Hij verzint smoesjes om uit bed te gaan. Ga helemaal zacht praten en spreek alleen fluisterend. Om je te verstaan moet hij zich echt concentreren, en die focus brengt zijn brein in een soort hypnose en laat hem in slaap vallen.', title_pl = 'Tajemnicza moc szeptu 🌙', body_pl = 'Wymyśla wymówki, żeby uciec z łóżka. Ścisz głos całkowicie i mów tylko szeptem. Żeby cię zrozumieć, będzie musiał się fizycznie skupić, a to skupienie zahipnotyzuje jego mózg i ukołysze go do snu.', title_pt = 'O poder místico do sussurro 🌙', body_pt = 'Inventa desculpas para fugir da cama. Baixe totalmente a voz e fale só a sussurrar. Para a perceber, vai ter de concentrar a atenção fisicamente, e essa concentração vai hipnotizar-lhe o cérebro e fazê-lo adormecer.', title_sv = 'Viskningens mystiska kraft 🌙', body_sv = 'Barnet hittar på ursäkter för att fly från sängen. Sänk rösten helt och prata bara viskande. För att förstå dig måste barnet fysiskt koncentrera sig, och fokuseringen hypnotiserar hjärnan och får barnet att somna.', title_vi = 'Sức mạnh huyền bí của lời thì thầm 🌙', body_vi = 'Bé nghĩ ra đủ lý do để trốn khỏi giường. Hãy hạ giọng hẳn xuống và chỉ nói thì thầm. Để hiểu được mẹ, bé buộc phải tập trung, và sự tập trung đó sẽ "thôi miên" não bé, đưa bé vào giấc ngủ.', title_zh = '悄悄话的神奇力量 🌙', body_zh = '为了从床上溜走编各种借口。把声音彻底压低，只用悄悄话说话。为了听懂你，宝宝不得不集中注意力，而这份专注会像催眠一样，让宝宝的大脑进入睡眠。' WHERE id = '7a600dc5-32dc-4b11-81f6-fb429bfb7588' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lógica del dinosaurio 🦖', body_es = 'Por la mañana no responde a ninguna pregunta, solo ruge. Hoy es un T-Rex. Adáptate a la identidad que se ha inventado preguntándole «¿Y los T-Rex comen gachas?» y completa la rutina de la mañana sin una sola lágrima.', title_fr = 'La logique du dinosaure 🦖', body_fr = 'Le matin, il ne répond à aucune question, il ne fait que rugir. Aujourd''hui, c''est un T-Rex. « Et les T-Rex, ils mangent de la bouillie ? » Adaptez-vous à cette identité inventée et terminez le rituel du matin sans une seule larme.', title_hi = 'डायनासोर का तर्क 🦖', body_hi = 'सुबह किसी सवाल का जवाब नहीं देता, बस दहाड़ता है। आज वह टी-रेक्स है। ‘तो क्या टी-रेक्स दलिया खाते हैं?’ कहकर उसकी गढ़ी इस पहचान के हिसाब से ढलिए और सुबह की रस्म बिना एक भी आँसू के पूरी कीजिए।', title_id = 'Logika dinosaurus 🦖', body_id = 'Pagi ini ia tidak menjawab pertanyaan apa pun, hanya mengaum. Hari ini ia T-Rex. Sesuaikan diri dengan identitas karangannya dengan bertanya ''Apakah T-Rex makan bubur?'', dan selesaikan ritual pagi tanpa air mata.', title_ja = '恐竜の理屈 🦖', body_ja = '朝、どんな質問にも答えず、ただガオーとほえるだけ。今日のこの子はティラノサウルスです。「ティラノサウルスって、おかゆ食べるのかな？」と、考えたキャラクターに合わせて、朝の習慣を涙なしで終わらせましょう。', title_ko = '공룡의 논리 🦖', body_ko = '아침에 어떤 질문에도 대답하지 않고 으르렁거리기만 하나요? 오늘은 티라노사우루스예요. ''티라노사우루스도 죽을 먹을까?'' 하며 아이가 만든 이 정체성에 맞춰 주면 아침 의식을 눈물 없이 끝낼 수 있어요.', title_nl = 'Dinosauruslogica 🦖', body_nl = '''s Ochtends beantwoordt hij geen enkele vraag, hij brult alleen. Vandaag is hij een T-rex. Pas je aan aan de identiteit die hij heeft bedacht, ''Eten T-rexen eigenlijk pap?'', en rond het ochtendritueel af zonder één traan.', title_pl = 'Logika dinozaura 🦖', body_pl = 'Rano nie odpowiada na żadne pytanie, tylko ryczy. Dziś jest T-Rexem. Zapytaj: „A czy T-Rexy jedzą kaszkę?”, dopasuj się do jego wymyślonej postaci i przejdź przez poranny rytuał bez ani jednej łzy.', title_pt = 'Lógica de dinossauro 🦖', body_pt = 'De manhã não responde a nenhuma pergunta, só ruge. Hoje é um T-Rex. Adapte-se a esta personalidade inventada: "E os T-Rex comem papa?", e termine o ritual da manhã sem uma única lágrima.', title_sv = 'Dinosaurielogik 🦖', body_sv = 'På morgonen svarar barnet inte på någon fråga utan bara ryter. I dag är barnet en T-Rex. Anpassa dig efter den påhittade identiteten, fråga ”Men äter T-Rexar gröt?” och avsluta morgonritualen utan en enda tår.', title_vi = 'Logic khủng long 🦖', body_vi = 'Buổi sáng, bé không trả lời câu hỏi nào, chỉ gầm gừ. Hôm nay bé là khủng long bạo chúa T-Rex. Hãy hòa theo nhân vật bé tự nghĩ ra: "Thế khủng long T-Rex có ăn cháo không nhỉ?" và hoàn thành nghi thức buổi sáng mà không có giọt nước mắt nào.', title_zh = '恐龙的逻辑 🦖', body_zh = '早上什么问题都不回答，只会“嗷呜”。今天宝宝是一只霸王龙。问一句“那霸王龙吃不吃粥呢？”，顺着宝宝编出来的这个身份，不掉一滴眼泪地完成早晨的流程。' WHERE id = 'fbad87dc-8f76-4644-9e49-49107be8118b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los héroes inventados de papá 🦸‍♂️', body_es = 'Esta noche olvidaos de los cuentos del libro. Que papá cuente una historia inventada y fantástica cuyo protagonista sea el propio peque. Frases como «Y desenvainó su espada y... ¡se lavó los dientes!» le harán reír a carcajadas y le prepararán para dormir.', title_fr = 'Les héros inventés de papa 🦸‍♂️', body_fr = 'Ce soir, oubliez les contes du livre. Que papa raconte une histoire inventée et fantastique dont l''enfant est le héros. Des phrases comme « Et il a sorti son épée... et il s''est brossé les dents ! » le feront éclater de rire et le prépareront au sommeil.', title_hi = 'पापा के गढ़े हुए हीरो 🦸‍♂️', body_hi = 'आज शाम किताब की कहानियाँ भूल जाइए। पापा एक गढ़ी हुई, फ़ैंटेसी कहानी सुनाएँ जिसका मुख्य हीरो खुद बच्चा हो। ‘और उसने तलवार निकाली और... दाँत ब्रश कर लिए!’ जैसे वाक्य बच्चे को हँसा-हँसाकर नींद के लिए तैयार कर देंगे।', title_id = 'Pahlawan karangan Ayah 🦸‍♂️', body_id = 'Malam ini lupakan dongeng di buku. Biarkan Ayah menceritakan kisah karangan yang fantastis dengan anak sendiri sebagai tokoh utamanya. Kalimat seperti ''Lalu ia menghunus pedangnya... dan menggosok gigi!'' akan membuat anak tertawa terbahak-bahak dan siap tidur.', title_ja = 'パパの作り話のヒーロー 🦸‍♂️', body_ja = '今夜は絵本のお話は忘れましょう。パパに、主人公が子ども自身の、作り話のファンタジーを話してもらいましょう。「そして剣をぬいて…歯をみがいた！」のような一言で、子どもは大笑いしながら眠りの準備ができます。', title_ko = '아빠가 지어낸 영웅들 🦸‍♂️', body_ko = '오늘 저녁엔 책 속 동화는 잊으세요. 아빠가 아이가 주인공인 지어낸 환상적인 이야기를 들려주게 하세요. ''그리고 칼을 뽑아 들고는... 이를 닦았어!'' 같은 문장이 아이를 웃음바다에 빠뜨리며 잠을 준비시킬 거예요.', title_nl = 'Papa''s verzonnen helden 🦸‍♂️', body_nl = 'Vergeet vanavond de sprookjes uit het boek. Laat papa een verzonnen, fantastisch verhaal vertellen met je kind als hoofdpersoon. Zinnen als ''En hij trok zijn zwaard... en poetste zijn tanden!'' laten je kind schateren en maken hem klaar voor de slaap.', title_pl = 'Wymyśleni bohaterowie taty 🦸‍♂️', body_pl = 'Dziś wieczorem zapomnij o bajkach z książek. Niech tata opowie wymyśloną, fantastyczną historię, w której głównym bohaterem jest samo dziecko. Zdania w stylu „I wyciągnął miecz... i umył zęby!” rozśmieszą go do łez i przygotują do snu.', title_pt = 'Os heróis inventados do pai 🦸‍♂️', body_pt = 'Esta noite esqueça as histórias do livro. Que o pai conte uma história inventada e fantástica com a própria criança como herói principal. Frases como "E ele tirou a espada e... lavou os dentes!" vão fazê-lo rir às gargalhadas e prepará-lo para o sono.', title_sv = 'Pappas påhittade hjältar 🦸‍♂️', body_sv = 'Glöm sagorna i boken i kväll. Låt pappa berätta en påhittad och fantastisk historia där barnet självt är huvudperson. Meningar som ”Och hen drog sitt svärd och... borstade tänderna!” får barnet att kikna av skratt och förbereder det för sömnen.', title_vi = 'Những người hùng tưởng tượng của bố 🦸‍♂️', body_vi = 'Tối nay hãy quên những câu chuyện trong sách. Để bố kể một câu chuyện tưởng tượng, kỳ ảo mà nhân vật chính là bé. Những câu như "Và cậu ấy rút thanh gươm ra... rồi đánh răng!" sẽ khiến bé cười ngặt nghẽo và sẵn sàng đi ngủ.', title_zh = '爸爸编的英雄 🦸‍♂️', body_zh = '今晚忘掉书里的童话吧。让爸爸讲一个主角就是宝宝自己的、天马行空的奇幻故事。像“然后他拔出宝剑……刷了刷牙！”这样的句子，会把宝宝逗得哈哈大笑，也让宝宝准备好入睡。' WHERE id = '401f5436-2de1-44e1-911f-f31af21dfae8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Critica su propio dibujo 🖍️', body_es = 'Te enseña sus garabatos negros, dice «Eras tú, pero me ha salido mal» y los rompe. ¡Está naciendo su capacidad de autocrítica! No le quites importancia a lo que siente: apoya su desarrollo diciendo «¿Y si en el próximo dibujo pruebas también el rojo?».', title_fr = 'Il critique son propre dessin 🖍️', body_fr = 'Il vous montre son gribouillage noir : « C''était toi, mais c''est raté », puis le déchire et le jette. La capacité à s''autocritiquer apparaît ! Ne minimisez pas ce qu''il ressent, soutenez son développement : « Au prochain dessin, tu pourrais peut-être essayer le rouge ? »', title_hi = 'अपनी ड्रॉइंग की आलोचना 🖍️', body_hi = 'अपनी बनाई काली आड़ी-तिरछी लकीरें दिखाकर कहता है, ‘यह तुम थीं, पर अच्छी नहीं बनी’ और फाड़कर फेंक देता है। खुद की आलोचना करने की क्षमता जाग रही है! उसकी भावनाओं को छोटा मत कीजिए, ‘अगली ड्रॉइंग में शायद लाल रंग भी आज़माओ?’ कहकर विकास में साथ दीजिए।', title_id = 'Mengkritik gambarnya sendiri 🖍️', body_id = 'Ia menunjukkan coretan hitamnya, berkata ''Ini Mama, tapi jelek'', lalu menyobek dan membuangnya. Kemampuan mengkritik diri sendiri mulai muncul! Jangan meremehkan perasaannya, dukung perkembangannya dengan berkata ''Di gambar berikutnya, mungkin coba pakai warna merah juga?''.', title_ja = '自分の絵にダメ出し 🖍️', body_ja = '描いた黒いぐちゃぐちゃを見せて「これ、ママだったけど、へたになった」と言って、破って捨ててしまう。自分を批評する力が育っています！気持ちを小さく扱わず、「次の絵では、赤も使ってみる？」と言って、成長を応援しましょう。', title_ko = '자기 그림 비평 🖍️', body_ko = '검은 낙서를 보여 주며 ''이거 엄마인데, 별로야'' 하고 찢어 버리나요? 스스로를 평가하는 능력이 생기고 있어요! 감정을 가볍게 여기지 말고 ''다음 그림엔 빨간색도 써 볼까?''라며 성장을 응원해 주세요.', title_nl = 'Kritiek op zijn eigen tekening 🖍️', body_nl = 'Hij laat zijn zwarte gekrabbel zien, zegt ''Dit was jij, maar het is lelijk geworden'' en scheurt het kapot. Hij begint zichzelf kritisch te bekijken! Maak zijn gevoelens niet kleiner, maar steun zijn ontwikkeling: ''Misschien kun je in je volgende tekening ook rood proberen?''', title_pl = 'Krytyka własnego rysunku 🖍️', body_pl = 'Pokazuje swoje czarne bazgroły, mówi „To byłaś ty, ale wyszło brzydko” i drze kartkę. Rodzi się umiejętność samokrytyki! Nie umniejszaj jego uczuć, wspieraj rozwój: „Może w następnym rysunku spróbujesz też czerwonego?”.', title_pt = 'Criticar o próprio desenho 🖍️', body_pt = 'Mostra os rabiscos pretos que desenhou, diz "Eras tu, mas ficou mal" e rasga-os. Está a nascer a capacidade de autocrítica! Não desvalorize o que sente: diga "No próximo desenho, experimentas também o vermelho?" e apoie o desenvolvimento.', title_sv = 'Kritik mot sin egen teckning 🖍️', body_sv = 'Barnet visar sitt svarta klotter, säger ”Det här var du, men det blev dåligt” och river sönder det. Förmågan till självkritik växer fram! Förminska inte barnets känslor, säg ”Kanske kan du testa rött också i nästa teckning?” och stöd utvecklingen.', title_vi = 'Tự phê bình tranh của mình 🖍️', body_vi = 'Bé chỉ vào bức vẽ nguệch ngoạc màu đen và nói "Đây là mẹ, nhưng xấu quá", rồi xé đi. Khả năng tự phê bình đang hình thành! Đừng xem nhẹ cảm xúc của bé, hãy hỗ trợ sự phát triển: "Lần vẽ sau con thử dùng thêm màu đỏ xem sao?".', title_zh = '批评自己的画 🖍️', body_zh = '指着自己画的黑乎乎的涂鸦说“这是你，可是画坏了”，然后撕掉扔了。自我批评的能力正在出现！别轻视宝宝的感受，说一句“下一张也许可以试试红色？”，支持宝宝的成长。' WHERE id = 'cc1183e6-40b5-4a08-b574-b47668387f44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Esto lo he encontrado yo» en el súper 🛒', body_es = 'Al llegar a la caja sale del carro un paquete de galletas que tú no pusiste. Ha hecho una exploración silenciosa. Abre la Lista de la compra y deja la norma en manos de una autoridad digital: «Mira, esto no está en nuestra lista, la próxima vez lo apuntamos».', title_fr = '« C''est moi qui l''ai trouvé » au supermarché 🛒', body_fr = 'En arrivant à la caisse, un paquet de biscuits que vous n''avez pas mis sort du chariot. Il a mené son exploration en silence. Ouvrez la Liste de courses et dites « Regarde, ce n''est pas sur notre liste, on l''ajoutera la prochaine fois » pour confier la règle à une autorité numérique.', title_hi = 'बाज़ार में ‘यह मुझे मिला’ 🛒', body_hi = 'काउंटर के पास पहुँचते ही ट्रॉली से बिस्कुट का एक पैकेट निकलता है, जो आपने नहीं रखा था। उसने चुपचाप खोजबीन की है। शॉपिंग लिस्ट खोलिए और ‘देखो, यह हमारी लिस्ट में नहीं है, अगली बार लिखेंगे’ कहकर नियम का भार एक डिजिटल अधिकारी पर डाल दीजिए।', title_id = '''Aku yang menemukan'' di supermarket 🛒', body_id = 'Saat mendekati kasir, dari troli muncul sebungkus biskuit yang tidak Anda masukkan. Ia diam-diam melakukan penjelajahan. Buka Daftar Belanja dan katakan ''Lihat, ini tidak ada di daftar kita, nanti kita tulis untuk lain kali'', dan serahkan aturan itu pada otoritas digital.', title_ja = 'スーパーで「ぼくが見つけた」 🛒', body_ja = 'レジに近づくと、あなたが入れていないクッキーがひと袋カートから出てくる。こっそり探検していたんです。「買い物リスト」を開いて「ほら、リストにはないね、次は書いておこう」と言い、ルールをデジタルな権威にまかせましょう。', title_ko = '마트에서 ''내가 찾았어'' 🛒', body_ko = '계산대에 다가가니 카트에서 엄마가 넣지 않은 과자 한 봉지가 나왔나요? 조용히 탐험을 다녀온 거예요. 쇼핑 목록을 열고 ''봐, 우리 목록에 이건 없어, 다음에 적자''라며 규칙을 디지털 권위에 맡기세요.', title_nl = '''Dit heb ik gevonden'' in de supermarkt 🛒', body_nl = 'Bij de kassa komt er uit het karretje een pak koekjes dat jij er niet in hebt gelegd. Hij heeft stilletjes op verkenning gezeten. Open het Boodschappenlijstje en laat de regel over aan een digitale autoriteit: ''Kijk, dit staat niet op ons lijstje, we zetten het er volgende keer op.''', title_pl = '„Ja to znalazłem” w sklepie 🛒', body_pl = 'Przy kasie z wózka wyłania się paczka ciastek, której nie wkładałaś. Po cichu prowadził zwiad. Otwórz Listę zakupów, powiedz „Zobacz, tego nie ma na naszej liście, dopiszemy następnym razem” i zrzuć zasadę na cyfrowy autorytet.', title_pt = '"Fui eu que encontrei" no supermercado 🛒', body_pt = 'Ao chegar à caixa, sai do carrinho um pacote de bolachas que não pôs lá. Fez uma exploração silenciosa. Abra a Lista de Compras, diga "Olha, isto não está na nossa lista, da próxima vez escrevemos" e passe a regra para uma autoridade digital.', title_sv = '”Jag hittade den” i butiken 🛒', body_sv = 'När ni närmar er kassan dyker ett kexpaket som du inte lagt dit upp ur vagnen. Barnet har gjort en tyst spaningsrunda. Öppna Inköpslistan, säg ”Titta, det här står inte på vår lista, vi skriver upp det nästa gång” och lägg regeln på en digital auktoritet.', title_vi = '"Con tìm thấy cái này" ở siêu thị 🛒', body_vi = 'Khi đến gần quầy thanh toán, từ xe đẩy lôi ra một gói bánh quy mà mẹ không bỏ vào. Bé đã lặng lẽ "thám hiểm". Hãy mở Danh sách mua sắm và nói: "Nhìn này, trong danh sách của mình không có món này, lần sau mình ghi vào nhé", để "quyền lực số" gánh hộ quy tắc.', title_zh = '超市里：“这是我找到的” 🛒', body_zh = '快到收银台时，购物车里冒出了一包你没放过的饼干。宝宝悄悄完成了一次“侦察”。打开购物清单，说一句“你看，我们的清单上没有这个，下次再写上”，把规矩交给一个“数字权威”来执行。' WHERE id = 'faf3013a-4d98-4178-82f0-b76954e80a74' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las olimpiadas de trepar por los muebles 🧗‍♂️', body_es = 'Trepa por el borde del sofá hacia la ventana. Para ti la casa está llena de peligros; para él es un gimnasio. En lugar de crear pánico con «¡Cuidado, que te caes!», dirige bien esta necesidad de moverse diciendo «Pon la mano ahí».', title_fr = 'Les olympiades d''escalade des meubles 🧗‍♂️', body_fr = 'Il escalade le bord du canapé en direction de la fenêtre. Pour vous, la maison est pleine de dangers, pour lui, c''est une salle de sport. Au lieu de semer la panique avec « Attention, tu vas tomber ! », guidez correctement ce besoin de bouger : « Mets ta main là. »', title_hi = 'फ़र्नीचर पर चढ़ने का ओलंपिक 🧗‍♂️', body_hi = 'सोफ़े के किनारे से खिड़की की ओर चढ़ रहा है। घर आपके लिए खतरों से भरा है, उसके लिए जिम। ‘सँभलकर, गिर जाओगे!’ कहकर घबराहट फैलाने के बजाय ‘अपना हाथ वहाँ रखो’ कहकर हिलने-डुलने की इस ज़रूरत को सही दिशा दीजिए।', title_id = 'Olimpiade memanjat perabot 🧗‍♂️', body_id = 'Ia memanjat pinggiran sofa menuju jendela. Bagi Anda rumah penuh bahaya, baginya rumah adalah pusat kebugaran. Daripada panik dan berteriak ''Hati-hati, nanti jatuh!'', arahkan kebutuhannya untuk bergerak dengan benar: ''Taruh tanganmu di situ''.', title_ja = '家具のぼりオリンピック 🧗‍♂️', body_ja = 'ソファのはしから窓のほうへよじのぼっていく。家はあなたにとって危険だらけでも、この子にとってはジムなんです。「気をつけて、落ちるよ！」とあわてる代わりに「手はそこに置いてね」と言って、体を動かしたい気持ちを正しい方向へ導きましょう。', title_ko = '가구 오르기 올림픽 🧗‍♂️', body_ko = '소파 가장자리를 따라 창문 쪽으로 기어오르나요? 엄마에게 집은 위험투성이지만 아이에게는 체육관이에요. ''조심해, 떨어져!'' 하며 겁주는 대신 ''손은 여기 짚어''라며 움직이고 싶은 마음을 올바르게 이끌어 주세요.', title_nl = 'Olympische spelen meubelklimmen 🧗‍♂️', body_nl = 'Hij klimt langs de rand van de bank richting het raam. Voor jou zit het huis vol gevaren, voor hem is het een sportschool. Roep niet in paniek ''Pas op, je valt!'', maar stuur zijn behoefte aan beweging de goede kant op: ''Zet je hand daar.''', title_pl = 'Olimpiada wspinaczki po meblach 🧗‍♂️', body_pl = 'Wspina się po brzegu kanapy w stronę okna. Dla ciebie dom jest pełen zagrożeń, dla niego to siłownia. Zamiast panikować „Uważaj, spadniesz!”, właściwie pokieruj tą potrzebą ruchu: „Połóż rękę tutaj”.', title_pt = 'As olimpíadas de trepar móveis 🧗‍♂️', body_pt = 'Trepa pela borda do sofá em direção à janela. Para si, a casa está cheia de perigos; para ele, é um ginásio. Em vez de criar pânico com "Cuidado, vais cair!", diga "Põe a mão ali" e oriente bem esta necessidade de movimento.', title_sv = 'Möbelklättringsolympiaden 🧗‍♂️', body_sv = 'Barnet klättrar längs soffkanten mot fönstret. För dig är hemmet fullt av faror, för barnet ett gym. Istället för att skapa panik med ”Akta dig, du ramlar!”, säg ”Sätt handen där” och styr behovet av rörelse åt rätt håll.', title_vi = 'Thế vận hội leo trèo đồ đạc 🧗‍♂️', body_vi = 'Bé trèo theo mép sofa về phía cửa sổ. Với mẹ, căn nhà đầy nguy hiểm, còn với bé là phòng tập thể dục. Thay vì hoảng hốt hét lên "Cẩn thận, con ngã đấy!", hãy hướng dẫn đúng nhu cầu vận động này: "Con đặt tay vào chỗ này".', title_zh = '爬家具奥运会 🧗‍♂️', body_zh = '顺着沙发边往窗户那边爬。对你来说，家里处处是危险；对宝宝来说，却是一座健身房。与其惊慌地喊“小心，会摔下来的！”，不如说“把手放在这里”，正确地引导宝宝对运动的需要。' WHERE id = '064802a6-44a3-418a-af04-e8b21366e4d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Encuentra ese único grano de arroz o trocito de zanahoria en la sopa y dice: «Esto no me lo como». Entra en el Plan de alimentación. Aprende a convertir las proteínas y las verduras en magdalenas de colores y engaña al cerebro de este cocinero tan tozudo.', body_fr = 'Il a trouvé l''unique grain de riz ou morceau de carotte de la soupe et dit « Je mange pas ça ». Ouvrez le Plan de nutrition. Apprenez à transformer protéines et légumes en muffins colorés et déjouez ce petit chef têtu.', body_hi = 'सूप में वह एक चावल का दाना या गाजर ढूँढकर कहता है, ‘मैं यह नहीं खाऊँगा।’ फ़ीडिंग प्लान खोलिए। सीखिए कि प्रोटीन और सब्ज़ियों को रंगीन मफ़िन का रूप कैसे दें, और इस ज़िद्दी शेफ़ के दिमाग को चकमा दीजिए।', body_id = 'Ia menemukan sebutir nasi atau sepotong wortel di supnya dan berkata ''Aku nggak mau makan ini''. Buka Rencana Nutrisi. Pelajari cara mengubah protein dan sayur menjadi bentuk muffin berwarna-warni dan kelabui otak koki keras kepala ini.', body_ja = 'スープの中のたったひと粒のお米やにんじんを見つけて「これ食べない」と言う。「栄養管理ツール」を開いてみましょう。たんぱく質や野菜をカラフルなマフィンの形にする方法を覚えて、このがんこなシェフの頭をうまくだましましょう。', body_ko = '수프 속 쌀 한 톨이나 당근 하나를 찾아내고 ''이거 안 먹어''라고 하나요? 식단 계획에 들어가 보세요. 단백질과 채소를 알록달록한 머핀 모양으로 만드는 법을 배워 이 고집쟁이 요리사를 속여 보세요.', body_nl = 'Vindt hij dat ene rijstkorreltje of stukje wortel in zijn soep en zegt hij ''Dit eet ik niet''? Open het Voedingsplan. Leer hoe je eiwitten en groenten in kleurrijke muffinvormpjes verwerkt en fop het brein van deze koppige kok.', body_pl = 'Znalazł w zupie to jedno ziarenko ryżu albo kawałek marchewki i mówi „Tego nie zjem”. Zajrzyj do planu karmienia. Naucz się, jak zamienić białko i warzywa w kolorowe babeczki, i przechytrz tego upartego kucharza.', body_pt = 'Encontra aquele único grão de arroz ou pedaço de cenoura na sopa e diz "Não como isto". Entre no Registo de Alimentação. Aprenda a dar às proteínas e aos legumes a forma de queques coloridos e engane o cérebro deste cozinheiro teimoso.', body_sv = 'Barnet hittar det enda riskornet eller den enda morotsbiten i soppan och säger ”Det här äter jag inte”. Gå in i matplanen. Lär dig hur du gör proteiner och grönsaker till färgglada muffins och lura den envisa kockens hjärna.', body_vi = 'Bé tìm thấy đúng một hạt cơm hay miếng cà rốt trong bát súp và nói "Con không ăn cái này". Hãy vào Kế hoạch dinh dưỡng. Học cách biến chất đạm và rau củ thành những chiếc bánh nướng xốp nhiều màu để "đánh lừa" vị đầu bếp bướng bỉnh này.', body_zh = '在汤里发现一粒米或一块胡萝卜，就说“我不吃这个”。去喂养计划里看看，学学如何把蛋白质和蔬菜做成彩色的小蛋糕，骗过这位倔强小厨师的大脑吧。' WHERE id = '1c07d667-ff98-498d-8a14-c5dc48ceda8c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sirve en los vasos un simple té caliente. Sentaos frente a frente en el sofá tú y tu pareja y brindad diciendo: «Hoy también hemos sobrevivido a este caos, somos un gran equipo». Sois los cimientos inquebrantables de la casa.', body_fr = 'Après une journée difficile, versez du simple thé chaud dans des verres. Asseyez-vous face à votre partenaire sur le canapé et trinquez : « On a survécu à ce chaos aujourd''hui aussi, on fait une super équipe. » Vous êtes les fondations inébranlables de cette maison.', body_hi = 'मुश्किल दिन के बाद गिलासों में सादी गरम चाय डालिए। अपने साथी के साथ सोफ़े पर आमने-सामने बैठिए और ‘आज उस अफ़रा-तफ़री से भी निकल आए, हम कमाल की टीम हैं’ कहकर गिलास टकराइए। आप इस घर की अटूट नींव हैं।', body_id = 'Setelah hari yang berat, tuang teh hangat biasa ke gelas. Duduklah berhadapan dengan pasangan di sofa dan bersulanglah sambil berkata ''Hari ini pun kita selamat dari kekacauan itu, kita tim yang hebat''. Kalian adalah fondasi rumah yang tak tergoyahkan.', body_ja = '大変な一日のあと、コップにふつうの温かいお茶を注ぎましょう。パートナーとソファで向かい合って「今日もあのカオスを乗りきったね、最高のチームだね」と乾杯を。ふたりはこの家の揺るがない土台です。', body_ko = '힘든 하루가 끝나면 컵에 평범한 따뜻한 차를 따르세요. 배우자와 소파에 마주 앉아 ''오늘 그 혼돈에서도 살아남았어, 우리 최고의 팀이야''라며 건배하세요. 두 사람은 이 집의 흔들림 없는 기둥이에요.', body_nl = 'Schenk na een zware dag gewone warme thee in. Ga tegenover je partner op de bank zitten en klink: ''Ook die chaos van vandaag hebben we overleefd, we zijn een top-team.'' Jullie zijn het onverwoestbare fundament van dit huis.', body_pl = 'Po trudnym dniu nalejcie do szklanek zwykłej gorącej herbaty. Usiądźcie z partnerem na kanapie twarzą w twarz i stuknijcie się szklankami: „Z tego chaosu też dziś wyszliśmy cało, jesteśmy świetną drużyną”. Jesteście niezłomnym fundamentem tego domu.', body_pt = 'Depois de um dia difícil, sirvam simplesmente chá quente nos copos. Sentem-se frente a frente no sofá com o seu companheiro e brindem: "Hoje também sobrevivemos ao caos, somos uma ótima equipa". São os alicerces inabaláveis desta casa.', body_sv = 'Efter den tuffa dagen, häll upp vanligt varmt te i glasen. Sätt dig mitt emot din partner i soffan och skåla: ”I dag överlevde vi det här kaoset också, vi är ett toppenlag.” Ni är hemmets orubbliga grund.', body_vi = 'Sau một ngày vất vả, hãy rót trà nóng bình thường vào cốc. Ngồi đối diện chồng trên sofa và cụng ly: "Hôm nay mình lại sống sót qua mớ hỗn loạn đó rồi, mình là một đội tuyệt vời". Hai người là nền móng vững chắc của ngôi nhà này.', body_zh = '艰难的一天过后，往杯子里倒上普通的热茶。和伴侣面对面坐在沙发上，碰个杯：“今天这场混乱我们也挺过来了，我们是最棒的团队。”你们是这个家坚不可摧的基石。' WHERE id = '7ce3cc61-1a21-499e-a7c2-d24e3693336c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Andando por la calle, de repente se asustó de su sombra y se refugió detrás de ti. No busques lógica: así funciona la imaginación de los 3 años y medio. Convierte al instante lo que le asusta en un juego físico: «¡Vamos a saltar encima de la sombra!».', body_fr = 'En marchant dans la rue, il a soudain eu peur de son ombre et s''est réfugié derrière vous. Ne cherchez pas de logique, l''imagination des 3 ans et demi fonctionne ainsi. Transformez aussitôt l''objet de sa peur en jeu physique : « Viens, on saute sur l''ombre ! »', body_hi = 'सड़क पर चलते-चलते अचानक अपनी परछाईं से डरकर आपके पीछे छिप गया। तर्क मत ढूँढिए, साढ़े 3 साल की कल्पना ऐसे ही काम करती है। ‘आओ, परछाईं पर कूदें’ कहकर जिस चीज़ से वह डरता है, उसे तुरंत एक शारीरिक खेल में बदल दीजिए।', body_id = 'Saat berjalan di jalan, tiba-tiba ia takut pada bayangannya sendiri dan berlindung di belakang Anda. Jangan mencari logika, begitulah imajinasi anak 3,5 tahun bekerja. Ubah benda yang ia takuti menjadi permainan fisik dengan berkata ''Ayo kita lompati bayangannya!''.', body_ja = '道を歩いていて、急に自分の影が怖くなってあなたの後ろに隠れた。理屈を求めないで。3歳半の想像力はこう働くんです。「影の上にジャンプしよう」と言って、怖いものをすぐに体を使う遊びに変えましょう。', body_ko = '길을 걷다 갑자기 자기 그림자가 무서워 엄마 뒤에 숨었나요? 논리를 찾지 마세요, 세 살 반의 상상력은 원래 그래요. ''우리 그림자 위로 뛰어 볼까?''라며 무서운 대상을 바로 몸 놀이로 바꿔 주세요.', body_nl = 'Op straat schrok hij ineens van zijn eigen schaduw en kroop hij achter je weg. Zoek geen logica, zo werkt de fantasie van een kind van 3,5. Maak van waar hij bang voor is meteen een lichamelijk spel: ''Kom, we springen op de schaduw!''', body_pl = 'Idąc ulicą, nagle przestraszył się swojego cienia i schował się za tobą. Nie szukaj logiki, tak działa wyobraźnia 3,5-latka. Od razu zamień to, czego się boi, w zabawę ruchową: „Wskoczmy na cień!”.', body_pt = 'A andar na rua, assustou-se de repente com a própria sombra e escondeu-se atrás de si. Não procure lógica: a imaginação dos 3 anos e meio funciona assim. Diga "Vamos saltar para cima da sombra" e transforme logo o que o assusta num jogo físico.', body_sv = 'När ni gick på gatan blev barnet plötsligt rädd för sin skugga och sökte skydd bakom dig. Leta inte efter logik, det är så 3,5-åringens fantasi fungerar. Säg ”Kom så hoppar vi på skuggan” och gör genast det barnet är rädd för till en fysisk lek.', body_vi = 'Đang đi ngoài đường, bé bỗng sợ cái bóng của mình và nấp sau lưng mẹ. Đừng tìm logic, trí tưởng tượng của tuổi 3,5 là như vậy. Hãy lập tức biến thứ bé sợ thành trò chơi vận động: "Mình cùng nhảy lên cái bóng nào!".', body_zh = '走在街上，突然被自己的影子吓得躲到你身后。别找逻辑，3岁半的想象力就是这样运作的。说一句“我们来跳到影子上吧”，马上把宝宝害怕的东西变成一个活动身体的游戏。' WHERE id = '1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial y calma 🤖', body_es = '¿Un tartamudeo repentino o las crisis de rabia de tu peque te han llevado a buscar enfermedades graves en internet? ¡Para! Pregunta a Anacan AI si es un salto de desarrollo de los 3 años y obtén una respuesta tranquilizadora avalada por pediatras.', title_fr = 'Intelligence artificielle et sérénité 🤖', body_fr = 'Un bégaiement soudain ou des crises de colère vous ont poussée à chercher des maladies graves sur Internet ? Stop ! Demandez à Anacan AI s''il s''agit d''un bond de développement des 3 ans et obtenez une réponse rassurante, validée par des pédiatres.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस और सुकून 🤖', body_hi = 'बच्चे का अचानक हकलाना या गुस्से के दौरे आपको इंटरनेट पर बुरी बीमारियाँ ढूँढने पर मजबूर कर गए? रुकिए! Anacan AI से पूछिए कि क्या यह 3 साल की विकास की छलाँग है, और बाल रोग विशेषज्ञ द्वारा पुष्ट, राहत देने वाला जवाब पाइए।', title_id = 'Kecerdasan buatan dan ketenangan 🤖', body_id = 'Gagap atau ledakan amarah yang tiba-tiba muncul membuat Anda mencari penyakit menakutkan di internet? Berhenti! Tanyakan pada Anacan AI apakah ini lompatan perkembangan usia 3 tahun, dan dapatkan jawaban menenangkan yang disetujui dokter anak.', title_ja = 'AIと安心 🤖', body_ja = '急に始まった吃音やかんしゃくに、ネットで悪い病気をさがしてしまった？ストップ！Anacan AIに、3歳の発達の飛躍かどうかをたずねて、小児科医も認める安心できる答えをもらいましょう。', title_ko = '인공지능과 평온 🤖', body_ko = '아이의 갑작스러운 말더듬이나 분노 폭발에 인터넷에서 무서운 병을 찾아보게 됐나요? 멈추세요! Anacan AI에게 세 살의 발달 도약인지 물어보고 소아과 의사가 확인한 안심되는 답을 받으세요.', title_nl = 'Kunstmatige intelligentie en rust 🤖', body_nl = 'Zette het plotselinge stotteren of de woedeaanvallen van je kind je aan het zoeken naar enge ziektes op internet? Stop! Vraag Anacan AI of het een ontwikkelingssprong rond 3 jaar is en krijg een geruststellend, door kinderartsen bevestigd antwoord.', title_pl = 'Sztuczna inteligencja i spokój 🤖', body_pl = 'Nagłe jąkanie się albo wybuchy złości dziecka sprawiły, że zaczęłaś szukać w internecie groźnych chorób? Stop! Zapytaj Anacan AI, czy to skok rozwojowy 3-latka, i uzyskaj uspokajającą odpowiedź potwierdzoną przez pediatrów.', title_pt = 'Inteligência artificial e serenidade 🤖', body_pt = 'A gaguez repentina ou as crises de raiva do seu filho levaram-na a procurar doenças graves na internet? Pare! Pergunte ao Anacan AI se é um salto de desenvolvimento dos 3 anos e obtenha uma resposta tranquilizadora, validada por pediatras.', title_sv = 'Artificiell intelligens och lugn 🤖', body_sv = 'Fick barnets plötsliga stamning eller vredesutbrott dig att söka efter allvarliga sjukdomar på nätet? Stopp! Fråga Anacan AI om det är ett utvecklingssprång vid 3 år och få ett barnläkargodkänt, lugnande svar.', title_vi = 'Trí tuệ nhân tạo và sự bình yên 🤖', body_vi = 'Việc bé bỗng nói lắp hay nổi giận dữ dội khiến mẹ lên mạng tìm những căn bệnh đáng sợ? Dừng lại! Hãy hỏi Anacan AI xem đó có phải bước nhảy vọt phát triển của tuổi lên 3 không và nhận câu trả lời được bác sĩ nhi khoa xác nhận, giúp mẹ nhẹ lòng.', title_zh = '人工智能与平静 🤖', body_zh = '孩子突然出现的口吃或发脾气，让你忍不住在网上搜各种可怕的疾病？停下！问问Anacan AI，这是否是3岁的发育飞跃，得到经儿科医生认可、让人安心的答案。' WHERE id = '9cee1c64-59c7-411a-9cc4-1d823dfe8c01' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Efectos de sonido en la habitación 🪄', body_es = 'Abre Cuentos inteligentes. Mientras lees la historia, crea un teatro sonoro en la habitación imitando el chirrido de una puerta, el viento y los susurros. Estas ondas sonoras tan originales atraerán al instante su atención al cuento, y de ahí a un sueño profundo.', title_fr = 'Effets sonores dans la chambre 🪄', body_fr = 'Ouvrez les Contes intelligents. En lisant l''histoire, faites simplement le grincement de la porte, le bruit du vent et des chuchotements pour créer un théâtre sonore dans la chambre. Ces ondes sonores inhabituelles attireront aussitôt son attention dans le conte, puis dans un sommeil profond.', title_hi = 'कमरे में आवाज़ों के इफ़ेक्ट 🪄', body_hi = 'स्मार्ट कहानियाँ खोलिए। कहानी पढ़ते समय बस दरवाज़े की चरमराहट, हवा की आवाज़ और सरसराहट निकालकर कमरे में आवाज़ों का थिएटर बनाइए। ये अनोखी आवाज़ की लहरें उसका ध्यान तुरंत कहानी में, और वहाँ से गहरी नींद में खींच लेंगी।', title_id = 'Efek suara di kamar 🪄', body_id = 'Buka Dongeng Pintar. Saat membacakan cerita, cukup tirukan derit pintu, suara angin, dan desisan untuk menciptakan teater suara di kamar. Gelombang suara yang tak biasa ini akan langsung menarik perhatiannya ke dalam dongeng, lalu ke dalam tidur yang nyenyak.', title_ja = '部屋の効果音 🪄', body_ja = '「スマートおはなし」を開きましょう。お話を読みながら、ドアのきしむ音や風の音、ひそひそ声を出して、部屋に音の劇場をつくって。このいつもとちがう音の波が、すぐにお話の中へ、そして深い眠りへと引きこんでくれます。', title_ko = '방 안의 음향 효과 🪄', body_ko = '스마트 동화를 열어 보세요. 이야기를 읽으며 문 삐걱거리는 소리, 바람 소리, 속삭임만 내어 방에 소리 극장을 만들어 보세요. 이 색다른 소리가 아이의 관심을 바로 이야기 속으로, 그리고 깊은 잠으로 이끌 거예요.', title_nl = 'Geluidseffecten in de kamer 🪄', body_nl = 'Open Slimme sprookjes. Maak tijdens het voorlezen gewoon het kraken van een deur, het geluid van de wind en een gefluister na, en bouw zo een geluidstheater in de kamer. Die ongewone geluidsgolven trekken zijn aandacht meteen het verhaal in, en van daaruit een diepe slaap in.', title_pl = 'Efekty dźwiękowe w pokoju 🪄', body_pl = 'Otwórz Mądre bajki. Czytając historię, naśladuj skrzypienie drzwi, szum wiatru i szept, tworząc w pokoju teatr dźwięku. Te niezwykłe fale dźwięku od razu wciągną jego uwagę w bajkę, a stamtąd w głęboki sen.', title_pt = 'Efeitos sonoros no quarto 🪄', body_pt = 'Abra as Histórias Inteligentes. Enquanto lê a história, faça apenas o ranger da porta, o som do vento e sussurros, e crie no quarto um teatro de sons. Estas ondas sonoras fora do comum vão levar logo a atenção dele para dentro da história e, dali, para um sono profundo.', title_sv = 'Ljudeffekter i rummet 🪄', body_sv = 'Öppna Smarta sagor. Medan du läser berättelsen, gör bara dörrknarr, vindsus och viskningar och bygg en ljudteater i rummet. De ovanliga ljudvågorna drar genast in barnets uppmärksamhet i sagan, och därifrån in i djup sömn.', title_vi = 'Hiệu ứng âm thanh trong phòng 🪄', body_vi = 'Hãy mở Truyện cổ tích thông minh. Khi đọc truyện, chỉ cần tạo tiếng cửa kẽo kẹt, tiếng gió và tiếng thì thầm để dựng một nhà hát âm thanh trong phòng. Những làn sóng âm thanh khác lạ này sẽ lập tức kéo bé vào câu chuyện, rồi từ đó vào giấc ngủ sâu.', title_zh = '房间里的音效 🪄', body_zh = '打开智慧童话。读故事时，只要发出门的吱呀声、风声和沙沙的悄悄声，就能在房间里搭起一座声音剧场。这些不寻常的声波会马上把宝宝的注意力吸进故事里，再从故事带进深深的梦乡。' WHERE id = 'd8c70945-12ad-4739-98a0-3d98184c5d44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas con objetos 🗣️', title_fr = 'Conversations avec les objets 🗣️', title_hi = 'बेजान चीज़ों से बातचीत 🗣️', title_id = 'Mengobrol dengan benda mati 🗣️', title_ja = 'ものとのおしゃべり 🗣️', title_ko = '사물과의 대화 🗣️', title_nl = 'Gesprekken met dingen 🗣️', title_pl = 'Rozmowy z przedmiotami 🗣️', title_pt = 'Conversas com objetos 🗣️', title_sv = 'Samtal med livlösa saker 🗣️', title_vi = 'Trò chuyện với đồ vật 🗣️', title_zh = '和没有生命的东西聊天 🗣️' WHERE id = '8d0e8d79-2ed2-4d47-9d71-055f26b53574' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite a primera hora 🙈', body_es = 'Llegas tarde al trabajo o a la guardería y él se esconde detrás de la cortina diciendo: «¡Encuéntrame!». Aunque tengas los nervios a flor de piel, gritar alargará aún más el proceso. Únete 2 minutos al juego: «¿Dónde estará mi niño tan bonito?», encuéntrale y sácale de ahí.', title_fr = 'Cache-cache au petit matin 🙈', body_fr = 'Vous êtes en retard pour le travail ou la crèche, et lui se cache derrière le rideau en disant « Trouve-moi ! ». Même si vos nerfs sont à vif, crier ne fera que rallonger les choses. Entrez 2 minutes dans le jeu, « Mais où est passé mon beau bébé ? », puis trouvez-le et sortez-le de là.', title_hi = 'सुबह-सुबह छुपन-छुपाई 🙈', body_hi = 'आपको काम या प्ले स्कूल के लिए देर हो रही है, और वह पर्दे के पीछे छिपकर कहता है, ‘मुझे ढूँढो!’ नसें तनी हों, फिर भी चिल्लाने से काम और लंबा खिंचेगा। ‘मेरा प्यारा बच्चा कहाँ है?’ कहकर 2 मिनट खेल में शामिल होइए और उसे ढूँढकर बाहर निकाल लीजिए।', title_id = 'Petak umpet pagi-pagi 🙈', body_id = 'Anda terlambat ke kantor atau TK, sementara ia bersembunyi di balik gorden dan berkata ''Cari aku!''. Meski saraf Anda menegang, berteriak hanya akan membuat semuanya makin lama. Ikutlah bermain 2 menit: ''Di mana ya anak Mama yang cantik?'', temukan ia dan bawa keluar.', title_ja = '朝からかくれんぼ 🙈', body_ja = '仕事や保育園に遅れそうなのに、カーテンの後ろに隠れて「見つけて！」と言う。神経がピンと張りつめても、叫べばよけいに長引きます。「わたしのかわいい子はどこかな？」と2分だけ遊びに乗って、見つけて連れ出しましょう。', title_ko = '아침 숨바꼭질 🙈', body_ko = '출근이나 어린이집에 늦었는데 커튼 뒤에 숨어 ''나 찾아 봐!''라고 하나요? 신경이 곤두서도 소리치면 시간만 더 걸려요. 2분만 놀이에 함께하며 ''우리 예쁜 아기 어디 있지?'' 하고 찾아서 데리고 나오세요.', title_nl = 'Verstoppertje in de ochtend 🙈', body_nl = 'Jullie zijn te laat voor werk of opvang, en hij verstopt zich achter het gordijn: ''Zoek me!'' Ook al staan je zenuwen strak gespannen, schreeuwen maakt het alleen maar langer. Doe 2 minuten mee met ''Waar is mijn mooie kindje nou?'', vind hem en haal hem tevoorschijn.', title_pl = 'Poranna zabawa w chowanego 🙈', body_pl = 'Spóźniacie się do pracy albo przedszkola, a on chowa się za zasłoną i woła „Znajdź mnie!”. Choć nerwy masz napięte do granic, krzyk tylko wszystko przedłuży. Dołącz do zabawy na 2 minuty: „Gdzie jest mój śliczny skarb?”, znajdź go i wyprowadź.', title_pt = 'Escondidas logo de manhã 🙈', body_pt = 'Está atrasada para o trabalho ou para o jardim de infância e ele escondeu-se atrás da cortina: "Encontra-me!". Mesmo com os nervos em franja, gritar só vai prolongar tudo. Entre no jogo 2 minutos, "Onde estará o meu menino lindo?", encontre-o e tire-o de lá.', title_sv = 'Kurragömma tidigt på morgonen 🙈', body_sv = 'Ni är sena till jobbet eller förskolan, och barnet gömmer sig bakom gardinen och säger ”Hitta mig!”. Även om nerverna är på helspänn förlänger skrik bara det hela. Säg ”Undrar var min fina lilla är?”, var med i leken i 2 minuter, hitta barnet och ta fram det.', title_vi = 'Trốn tìm buổi sáng 🙈', body_vi = 'Mẹ đang trễ giờ làm hoặc giờ đi mầm non, còn bé trốn sau rèm cửa và nói "Mẹ tìm con đi!". Dù mẹ căng như dây đàn, quát mắng chỉ khiến mọi việc kéo dài hơn. Hãy tham gia trò chơi 2 phút: "Bé cưng xinh đẹp của mẹ đâu rồi nhỉ?" rồi tìm thấy và đưa bé ra.', title_zh = '一大早玩捉迷藏 🙈', body_zh = '你上班或送幼儿园已经要迟到了，宝宝却躲在窗帘后面喊“来找我！”。虽然你的神经已经绷紧了，但吼叫只会让事情拖得更久。说一句“我漂亮的小宝贝在哪儿呢？”，花2分钟加入游戏，把宝宝找出来吧。' WHERE id = 'b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una terquedad que desafía a la física 💧', title_fr = 'Un entêtement qui défie la physique 💧', title_hi = 'भौतिकी को चुनौती देती ज़िद 💧', title_id = 'Keras kepala yang menantang fisika 💧', title_ja = '物理に挑戦するがんこさ 💧', title_ko = '물리 법칙에 도전하는 고집 💧', title_nl = 'Koppigheid die de natuurkunde uitdaagt 💧', title_pl = 'Upór na przekór fizyce 💧', title_pt = 'A teimosia que desafia a física 💧', title_sv = 'Envishet som utmanar fysiken 💧', title_vi = 'Sự bướng bỉnh thách thức vật lý 💧', title_zh = '挑战物理的倔强 💧' WHERE id = '9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Política en el parque 🤝', body_es = '¿Empuja a otro niño en el tobogán para subir él? Compartir todavía es un concepto complicado que no ha asentado del todo. En lugar de avergonzarte o castigarle, recuérdale la norma del sistema diciendo: «Ahora es su turno».', title_fr = 'Diplomatie au parc 🤝', body_fr = 'Il pousse un autre enfant sur le toboggan pour y monter lui-même ? Le partage est encore pour lui une notion complexe, pas tout à fait acquise. Plutôt que d''avoir honte ou de le punir, rappelez simplement la règle : « Maintenant, c''est son tour. »', title_hi = 'पार्क की नीति 🤝', body_hi = 'फिसलपट्टी पर किसी दूसरे बच्चे को धक्का देकर खुद चढ़ना चाहता है? बाँटना उसके लिए अभी पूरी तरह न बैठी, पेचीदा समझ है। शर्मिंदा होने या सज़ा देने के बजाय ‘अब उसकी बारी है’ कहकर बस नियम याद दिलाइए।', title_id = 'Politik di taman 🤝', body_id = 'Ia mendorong anak lain di perosotan karena ingin meluncur sendiri? Berbagi masih konsep rumit yang belum sepenuhnya ia kuasai. Daripada malu atau menghukum, cukup ingatkan aturannya dengan berkata ''Sekarang gilirannya''.', title_ja = '公園での政治 🤝', body_ja = 'すべり台でほかの子を押しのけて、自分がすべりたがる？分け合うことは、この子にとってまだ身についていない、むずかしい考えです。恥ずかしがったり罰したりする代わりに、「今はあの子の番だよ」と、ルールを思い出させるだけにしましょう。', title_ko = '놀이터의 외교 🤝', body_ko = '미끄럼틀에서 다른 아이를 밀치고 자기가 타려 하나요? 나누기는 아직 완전히 자리 잡지 않은 어려운 개념이에요. 창피해하거나 벌주는 대신 ''지금은 저 친구 차례야''라며 규칙만 알려 주세요.', title_nl = 'Politiek in het park 🤝', body_nl = 'Duwt hij op de glijbaan een ander kind weg om zelf te kunnen glijden? Delen is voor hem nog een ingewikkeld begrip dat nog niet helemaal zit. Schaam je niet en straf niet, maar herinner hem gewoon aan de regel: ''Nu is hij aan de beurt.''', title_pl = 'Polityka w parku 🤝', body_pl = 'Odpycha inne dziecko na zjeżdżalni, bo sam chce zjechać? Dzielenie się to dla niego wciąż trudne, jeszcze nieutrwalone pojęcie. Zamiast się wstydzić czy karać, po prostu przypomnij zasadę: „Teraz jego kolej”.', title_pt = 'Política no parque 🤝', body_pt = 'Empurra outra criança no escorrega para ir ele? Partilhar ainda é para ele um conceito complicado e pouco assente. Em vez de ficar envergonhada ou de o castigar, lembre-lhe simplesmente a regra do sistema: "Agora é a vez dele".', title_sv = 'Politik i parken 🤝', body_sv = 'Knuffar barnet bort ett annat barn i rutschkanan för att åka själv? Att dela är fortfarande ett krångligt begrepp som inte riktigt satt sig. Istället för att skämmas eller straffa, påminn bara om regeln: ”Nu är det hens tur.”', title_vi = 'Ngoại giao ở công viên 🤝', body_vi = 'Bé đẩy một bạn khác ở cầu trượt để được trượt trước? Chia sẻ vẫn là khái niệm phức tạp mà bé chưa thật sự nắm được. Thay vì xấu hổ hay phạt bé, hãy nhắc lại quy tắc: "Giờ là lượt của bạn ấy".', title_zh = '公园里的政治 🤝', body_zh = '在滑梯上把别的小朋友推开，想自己先滑？分享对宝宝来说还是个没完全建立起来的复杂概念。别感到丢脸，也别惩罚，只要提醒一下规则：“现在轮到他了。”' WHERE id = '5672be3d-87ec-469d-a4b7-fca0b00ec9ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
