UPDATE public.mommy_day_notifications SET title_es = 'El juego del «¿Quién eres?» 🎭', title_fr = 'Le jeu du « Qui es-tu ? » 🎭', title_hi = '‘तुम कौन हो?’ वाला खेल 🎭', title_id = 'Permainan ''Kamu siapa?'' 🎭', title_ja = '「あなたは誰？」ごっこ 🎭', title_ko = '''누구세요?'' 놀이 🎭', title_nl = 'Het ''Wie ben jij?''-spel 🎭', title_pl = 'Zabawa „Kim jesteś?” 🎭', title_pt = 'O jogo do "Quem és tu?" 🎭', title_sv = 'Leken ”Vem är du?” 🎭', title_vi = 'Trò chơi "Cô là ai?" 🎭', title_zh = '“你是谁？”游戏 🎭' WHERE id = 'a8aeb934-2767-4365-a584-e2b99fc16215' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La llamada del cuerpo 🩸', body_es = 'No te rindas a la irritación y el cansancio sin motivo. Mira el Calendario menstrual: tu cuerpo te está mandando señales. En lugar de culparte, descansa con un tentempié rico en magnesio de Recetas saludables.', title_fr = 'Le cri du corps 🩸', body_fr = 'Ne cédez pas à l''irritabilité et à la fatigue sans raison. Regardez le Suivi des règles, votre corps vous envoie des signaux. Au lieu de vous blâmer, reposez-vous avec une collation riche en magnésium des Recettes saines.', title_hi = 'शरीर की पुकार 🩸', body_hi = 'बिना वजह की चिढ़ और थकान के आगे हार मत मानिए। पीरियड ट्रैकर देखिए, आपका शरीर संकेत दे रहा है। खुद को दोष देने के बजाय सेहतमंद रेसिपी से मैग्नीशियम वाले स्नैक के साथ आराम कीजिए।', title_id = 'Jeritan tubuh 🩸', body_id = 'Jangan menyerah pada rasa kesal dan lelah tanpa sebab. Lihat Pelacak Menstruasi, tubuh Anda sedang memberi sinyal. Daripada menyalahkan diri, beristirahatlah dengan camilan kaya magnesium dari Resep Sehat.', title_ja = '体のSOS 🩸', body_ja = '理由のないイライラや疲れに負けないで。「生理トラッカー」を見てみましょう。体がサインを出しています。自分を責める代わりに、「ヘルシーレシピ」のマグネシウムたっぷりのおやつで休みましょう。', title_ko = '몸이 보내는 외침 🩸', body_ko = '이유 없는 짜증과 피로에 지지 마세요. 생리 주기 기록을 확인해 보세요, 몸이 신호를 보내고 있어요. 자책하는 대신 건강한 레시피의 마그네슘이 든 간식으로 쉬어 가세요.', title_nl = 'De roep van je lichaam 🩸', body_nl = 'Geef niet toe aan onverklaarbare prikkelbaarheid en vermoeidheid. Kijk in je Cyclustracker, je lichaam geeft signalen. Veroordeel jezelf niet, maar ontspan met een magnesiumrijk tussendoortje uit Gezonde recepten.', title_pl = 'Wołanie ciała 🩸', body_pl = 'Nie poddawaj się drażliwości i zmęczeniu bez powodu. Zajrzyj do Kalendarza miesiączkowego, twoje ciało wysyła sygnały. Zamiast się obwiniać, odpocznij z przekąską bogatą w magnez ze Zdrowych przepisów.', title_pt = 'O grito do corpo 🩸', body_pt = 'Não se renda à irritação e ao cansaço sem razão. Veja o Registo do Período: o seu corpo está a dar sinais. Em vez de se culpar, descanse com um snack rico em magnésio das Receitas Saudáveis.', title_sv = 'Kroppens rop 🩸', body_sv = 'Ge inte efter för omotiverad irritation och trötthet. Titta i Mensspåraren, kroppen skickar signaler. Istället för att döma dig själv, vila med ett magnesiumrikt mellanmål från Hälsosamma recept.', title_vi = 'Tiếng gọi của cơ thể 🩸', body_vi = 'Đừng đầu hàng sự cáu kỉnh và mệt mỏi không rõ lý do. Hãy xem Theo dõi kỳ kinh, cơ thể mẹ đang gửi tín hiệu. Thay vì tự trách mình, hãy nghỉ ngơi với một món ăn nhẹ giàu magie từ Công thức lành mạnh.', title_zh = '身体的呼唤 🩸', body_zh = '别向莫名的烦躁和疲惫投降。看看经期记录，你的身体在发出信号。与其责怪自己，不如从健康食谱里做一份富含镁的小零食，好好休息。' WHERE id = 'b9a9483f-7511-4f19-847b-4d0786991104' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
