UPDATE public.mommy_day_notifications SET title_es = 'Un «te quiero» por sorpresa 💖', title_fr = 'Un « Je t''aime » soudain 💖', title_hi = 'अचानक ‘आई लव यू’ 💖', title_id = '''Aku sayang Mama'' yang tiba-tiba 💖', title_ja = '不意打ちの「大好き」 💖', title_ko = '갑작스러운 ''사랑해'' 💖', title_nl = 'Een onverwacht ''Ik hou van je'' 💖', title_pl = 'Nagłe „Kocham cię” 💖', title_pt = 'Um "Amo-te" de repente 💖', title_sv = 'Ett plötsligt ”Jag älskar dig” 💖', title_vi = '"Con yêu mẹ" bất ngờ 💖', title_zh = '突然的“我爱你” 💖' WHERE id = 'b5588608-ef71-4787-b05e-09f4f4f2492a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder místico del susurro 🤫', title_fr = 'Le pouvoir mystérieux du chuchotement 🤫', title_hi = 'फुसफुसाहट की रहस्यमयी ताकत 🤫', title_id = 'Kekuatan ajaib bisikan 🤫', title_ja = 'ささやきのふしぎな力 🤫', title_ko = '속삭임의 신비한 힘 🤫', title_nl = 'De mystieke kracht van fluisteren 🤫', title_pl = 'Tajemnicza moc szeptu 🤫', title_pt = 'O poder místico do sussurro 🤫', title_sv = 'Viskningens mystiska kraft 🤫', title_vi = 'Sức mạnh huyền bí của lời thì thầm 🤫', title_zh = '悄悄话的神奇力量 🤫' WHERE id = 'e2ac4132-1e14-42d5-a828-9c40ffb00179' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La maternidad no es un turno 24/7. ¡Activa la función pareja! Deja que hoy papá le haga gastar en el parque esa energía sin fin y tú disfruta en casa del silencio absoluto.', body_fr = 'La maternité n''est pas une garde 24 h/24 et 7 j/7. Activez le mode Partenaire ! Laissez papa dépenser aujourd''hui au parc cette énergie sans fin, et savourez à la maison un silence absolu.', body_hi = 'माँ बनना 24/7 चलने वाली शिफ़्ट नहीं है। साथी वाला फ़ीचर चालू कीजिए! आज वह अंतहीन ऊर्जा पापा को पार्क में निकलवाने दीजिए, और आप घर पर पूरी खामोशी का मज़ा लीजिए।', body_id = 'Menjadi ibu bukan giliran jaga 24/7. Aktifkan fungsi pasangan! Biarkan hari ini Ayah yang menyalurkan energinya yang tak habis-habis di taman, sementara Anda menikmati keheningan total di rumah.', body_ja = 'ママ業は24時間365日続くシフトではありません。「パートナーモード」をオンにしましょう！今日はあの尽きないエネルギーを、パパに公園で発散させてもらって、あなたは家で完全な静けさを味わって。', body_ko = '엄마 노릇은 24시간 쉬지 않는 근무가 아니에요. 파트너 모드를 켜세요! 오늘은 그 끝없는 에너지를 아빠가 공원에서 풀게 하고, 엄마는 집에서 완전한 고요를 즐기세요.', body_nl = 'Moederschap is geen dienst die 24/7 doorgaat. Zet de partnerfunctie aan! Laat papa die eindeloze energie vandaag in het park laten opbranden, en geniet jij thuis van de absolute stilte.', body_pl = 'Macierzyństwo to nie zmiana 24/7. Włącz tryb Partnera! Niech dziś tata pomoże mu wyładować tę niewyczerpaną energię w parku, a ty delektuj się w domu absolutną ciszą.', body_pt = 'A maternidade não é um turno 24/7. Ative a função de companheiro! Deixe que hoje seja o pai a gastar no parque aquela energia sem fim e saboreie em casa um silêncio absoluto.', body_sv = 'Moderskap är inget skift som pågår dygnet runt. Aktivera partnerfunktionen! Låt pappa få ur barnet den ändlösa energin i parken i dag, medan du njuter av total tystnad hemma.', body_vi = 'Làm mẹ không phải là ca trực 24/7. Hãy bật Chế độ đối tác! Hôm nay để bố cho bé xả hết nguồn năng lượng bất tận ở công viên, còn mẹ ở nhà tận hưởng sự yên tĩnh tuyệt đối.', body_zh = '当妈妈不是一份24/7不停歇的班。启动“伴侣功能”吧！今天就让爸爸带宝宝去公园释放那用不完的精力，你在家里好好享受绝对的安静。' WHERE id = 'e85b3357-f072-4120-8d16-ffdc101f5e86' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El examen del bordillo 🧱', body_es = 'Camino del parque no quiere ir por el camino normal, sino que insiste en andar por el borde más estrecho y alto de la acera, como un funambulista. ¡Su motricidad gruesa y su equilibrio se desarrollan! Asegúrale cogiéndole del brazo y deja que conquiste esta cima pequeña pero tan importante para él.', title_fr = 'L''épreuve du bord du trottoir 🧱', body_fr = 'En allant au parc, il ne veut pas marcher normalement, mais sur le rebord le plus étroit et le plus haut du trottoir, comme un funambule. Sa motricité globale et son équilibre se développent ! Tenez-lui le bras pour l''assurer et laissez-le conquérir ce sommet, petit mais si important pour lui.', title_hi = 'फुटपाथ के किनारे की परीक्षा 🧱', body_hi = 'पार्क जाते समय सामान्य रास्ते से नहीं, ज़िद करके फुटपाथ के सबसे पतले और ऊँचे किनारे पर, रस्सी पर चलने वाले नट की तरह चलना चाहता है। बड़ी मोटर स्किल्स और संतुलन बढ़ रहे हैं! बाँह पकड़कर सँभालिए, और उसे यह छोटा, पर उसके लिए बहुत अहम शिखर जीतने दीजिए।', title_id = 'Ujian di tepi trotoar 🧱', body_id = 'Saat ke taman, ia bersikeras berjalan bukan di jalan biasa, tapi di tepi trotoar yang paling sempit dan tinggi seperti pemain akrobat tali. Motorik kasar dan keseimbangannya sedang berkembang! Jaga ia dengan memegang lengannya, dan biarkan ia menaklukkan puncak kecil yang sangat penting baginya ini.', title_ja = '歩道のふちで試験 🧱', body_ja = '公園へ行くのに、ふつうの道ではなく、歩道のいちばんせまくて高いふちを、綱わたりのように歩きたがる。体の大きな動きとバランス感覚が育っています！腕を持って支えながら、この小さいけれどこの子にはとても大切な頂上を征服させてあげましょう。', title_ko = '보도블록 가장자리 시험 🧱', body_ko = '공원에 갈 때 평범한 길 대신 꼭 보도 가장 좁고 높은 가장자리로 줄타기하듯 걷겠다고 하나요? 대근육과 균형 감각이 자라고 있어요! 팔을 잡아 안전을 지켜 주고, 아이에게는 아주 중요한 이 작은 정상을 정복하게 해 주세요.', title_nl = 'De stoeprandtest 🧱', body_nl = 'Op weg naar het park wil hij niet over het gewone pad, maar per se over de smalste, hoogste rand van de stoep lopen, als een koorddanser. Grove motoriek en evenwicht ontwikkelen zich! Houd zijn arm vast voor de veiligheid en laat hem deze kleine, maar voor hem heel belangrijke top veroveren.', title_pl = 'Egzamin na krawężniku 🧱', body_pl = 'W drodze do parku uparcie chce iść nie zwykłą drogą, tylko najwęższym i najwyższym brzegiem krawężnika, jak linoskoczek. Rozwijają się motoryka duża i równowaga! Asekuruj go, trzymając za rękę, i pozwól mu zdobyć ten mały, ale dla niego bardzo ważny szczyt.', title_pt = 'O teste da borda do passeio 🧱', body_pt = 'A caminho do parque, não quer ir pelo caminho normal, mas pela borda mais estreita e alta do passeio, como um equilibrista. A motricidade grossa e o equilíbrio estão a desenvolver-se! Segure-lhe o braço para o proteger e deixe-o conquistar este pequeno cume, tão importante para ele.', title_sv = 'Prov på trottoarkanten 🧱', body_sv = 'På väg till parken vill barnet envist inte gå på den vanliga vägen, utan balansera på den smalaste och högsta trottoarkanten som en lindansare. Grovmotorik och balans utvecklas! Håll i armen för säkerhets skull och låt barnet erövra den lilla men för barnet så viktiga toppen.', title_vi = 'Thử thách mép vỉa hè 🧱', body_vi = 'Trên đường ra công viên, bé không chịu đi đường bình thường mà nhất định đi trên mép vỉa hè hẹp và cao nhất, như người đi trên dây. Kỹ năng vận động thô và khả năng giữ thăng bằng đang phát triển! Hãy nắm tay để giữ an toàn cho bé, và để bé chinh phục "đỉnh núi" nhỏ nhưng vô cùng quan trọng với bé này.', title_zh = '马路牙子上的考验 🧱', body_zh = '去公园时不走正常的路，非要像走钢丝一样走人行道边最窄、最高的路沿。大动作和平衡能力在发展！拉着宝宝的胳膊保护好，让宝宝去征服这座小小的、对宝宝来说却很重要的“高峰”吧。' WHERE id = '5a50a7bc-7ff1-421e-abac-beffc69e1480' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la Comunidad 💬', body_es = 'El pensamiento «¿Por qué mi hijo es tan tozudo?» te está comiendo por dentro. Entra en la Comunidad Anacan. Cuando leas las crisis absurdas parecidas que estallan en casa de otras madres, verás que no estás sola y que vas por un camino totalmente normal.', title_fr = 'La force de la communauté 💬', body_fr = 'La pensée « Pourquoi mon enfant est-il si têtu ? » vous ronge ? Rejoignez la Communauté Anacan. En lisant les crises absurdes qui éclatent chez d''autres mamans, vous verrez que vous n''êtes pas seule et que vous êtes sur une voie tout à fait normale.', title_hi = 'कम्युनिटी की ताकत 💬', body_hi = '‘मेरा बच्चा इतना ज़िद्दी क्यों है?’ वाला ख्याल आपका दिमाग खा रहा है। Anacan कम्युनिटी में जाइए। दूसरी माँओं के घरों में होने वाले ऐसे ही बेतुके नखरे पढ़कर आप देखेंगी कि आप अकेली नहीं हैं और बिल्कुल सही रास्ते पर हैं।', title_id = 'Kekuatan komunitas 💬', body_id = 'Pikiran ''Kenapa anakku keras kepala sekali?'' terus menggerogoti otak Anda. Masuklah ke Komunitas Anacan. Saat membaca krisis absurd serupa di rumah ibu-ibu lain, Anda akan melihat bahwa Anda tidak sendirian dan sedang berada di jalur yang sepenuhnya normal.', title_ja = 'コミュニティの力 💬', body_ja = '「うちの子はどうしてこんなにがんこなの？」という思いが頭から離れない。Anacanコミュニティを開いてみましょう。ほかのママたちの家で起きている、同じようなおかしなかんしゃくを読めば、ひとりじゃないこと、ごく普通の道を歩んでいることがわかります。', title_ko = '커뮤니티의 힘 💬', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각이 머리를 갉아먹나요? Anacan 커뮤니티에 들어가 보세요. 다른 집에서 터지는 비슷하게 엉뚱한 떼쓰기를 읽으면 혼자가 아니고 아주 정상적인 길을 걷고 있다는 걸 알게 될 거예요.', title_nl = 'De kracht van de Community 💬', body_nl = 'Vreet de gedachte ''Waarom is mijn kind zo koppig?'' aan je? Ga naar de Anacan Community. Als je leest over net zulke absurde buien bij andere mama''s thuis, zie je dat je niet de enige bent en dat je helemaal op de normale weg zit.', title_pl = 'Siła Społeczności 💬', body_pl = 'Myśl „Dlaczego moje dziecko jest takie uparte?” nie daje ci spokoju. Wejdź do Społeczności Anacan. Gdy przeczytasz o podobnych absurdalnych kryzysach w domach innych mam, zobaczysz, że nie jesteś sama i wszystko idzie zupełnie normalnym torem.', title_pt = 'A força da comunidade 💬', body_pt = 'O pensamento "Porque é que o meu filho é tão teimoso?" não lhe sai da cabeça. Entre na Comunidade Anacan. Ao ler as crises absurdas parecidas que rebentam em casa de outras mães, vai ver que não está sozinha e que está no caminho perfeitamente normal.', title_sv = 'Gemenskapens kraft 💬', body_sv = 'Tanken ”Varför är mitt barn så envist?” äter upp dig. Gå in i Anacan Community. När du läser om liknande absurda kriser hemma hos andra mammor ser du att du inte är ensam och att du är helt på rätt väg.', title_vi = 'Sức mạnh của Cộng đồng 💬', body_vi = 'Ý nghĩ "Sao con mình bướng thế?" cứ ám ảnh mẹ. Hãy vào Cộng đồng Anacan. Khi đọc về những cơn khủng hoảng "khó đỡ" tương tự ở nhà các mẹ khác, mẹ sẽ thấy mình không đơn độc và mọi thứ đều hoàn toàn bình thường.', title_zh = '社区的力量 💬', body_zh = '“我的孩子怎么这么倔？”这个念头一直折磨着你。进入Anacan社区。读到其他妈妈家里也在上演类似的荒诞崩溃，你就会发现自己并不孤单，一切完全正常。' WHERE id = '1681892e-80a4-445a-827d-19733c9c6b73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La inquietud del silencio 🤫', body_es = 'Está solo en la habitación mirando dibujos y en casa reina un silencio profundo. Y tú, sospechando de tanto silencio, esperas una catástrofe en cualquier momento. Tranquila. A veces ellos también quieren estar solos. Recuéstate y disfruta de este raro momento offline.', title_fr = 'L''angoisse du silence 🤫', body_fr = 'Il regarde des images tout seul dans sa chambre, un silence profond règne dans la maison. Et vous, méfiante, vous attendez une catastrophe d''une minute à l''autre. Détendez-vous. Parfois, eux aussi ont envie d''être seuls. Calez-vous et savourez ce rare moment hors ligne.', title_hi = 'खामोशी की घबराहट 🤫', body_hi = 'वह कमरे में अकेले तस्वीरें देख रहा है, घर में गहरी खामोशी है। और आप इस चुप्पी पर शक करके हर पल किसी आफ़त का इंतज़ार कर रही हैं। आराम से रहिए। कभी-कभी उन्हें भी अकेले रहना होता है। इस दुर्लभ ऑफ़लाइन पल में पीछे टिककर मज़ा लीजिए।', title_id = 'Panik karena hening 🤫', body_id = 'Ia melihat-lihat gambar sendirian di kamar, dan rumah sangat hening. Anda justru curiga dan menunggu bencana setiap saat. Tenanglah. Kadang mereka juga ingin sendiri. Bersandarlah dan nikmati momen offline yang langka ini.', title_ja = '静けさへの不安 🤫', body_ja = '部屋でひとり絵本を眺めていて、家の中はしーんとしています。あなたはその静けさをあやしんで、何か起きるのではと身構えていますね。大丈夫。子どもだってひとりになりたいときがあります。このめずらしいオフラインの時間を、ゆったり楽しみましょう。', title_ko = '고요의 불안 🤫', body_ko = '아이가 방에서 혼자 그림을 보고 있고 집 안이 아주 조용한가요? 엄마는 이 고요가 의심스러워 언제 사고가 날지 기다리죠. 편히 계세요. 아이들도 가끔은 혼자 있고 싶어 해요. 이 귀한 오프라인 순간을 기대어 앉아 누리세요.', title_nl = 'Paniek om de stilte 🤫', body_nl = 'Hij bekijkt in zijn eentje plaatjes in de kamer en het is doodstil in huis. En jij vertrouwt die stilte niet en verwacht elk moment een ramp. Ontspan. Soms willen ook zij even alleen zijn. Leun achterover en geniet van dit zeldzame offline moment.', title_pl = 'Niepokój ciszy 🤫', body_pl = 'Sam ogląda obrazki w pokoju, a w domu panuje głęboka cisza. A ty, podejrzliwa wobec tej ciszy, w każdej chwili spodziewasz się katastrofy. Spokojnie. Czasem dzieci też chcą pobyć same. Oprzyj się wygodnie i delektuj tą rzadką chwilą offline.', title_pt = 'A inquietação do silêncio 🤫', body_pt = 'Está sozinho no quarto a ver imagens e há um silêncio profundo em casa. E a mãe, desconfiada, espera uma catástrofe a qualquer momento. Fique tranquila. Às vezes eles também querem estar sozinhos. Recoste-se e saboreie este raro momento offline.', title_sv = 'Oro i tystnaden 🤫', body_sv = 'Barnet tittar på bilder ensamt i rummet och det är djupt tyst i hemmet. Och du blir misstänksam mot tystnaden och väntar på en katastrof när som helst. Slappna av. Ibland vill de också vara ensamma. Luta dig tillbaka och njut av den sällsynta offline-stunden.', title_vi = 'Hoảng hốt vì im lặng 🤫', body_vi = 'Bé đang một mình xem tranh trong phòng, cả nhà im phăng phắc. Còn mẹ lại nghi ngờ sự im lặng này và chờ một "thảm họa" bất cứ lúc nào. Thư giãn đi. Đôi khi bé cũng muốn ở một mình. Hãy ngả lưng và tận hưởng khoảnh khắc "offline" hiếm hoi này.', title_zh = '安静带来的不安 🤫', body_zh = '宝宝一个人在房间里看图画书，家里一片安静。你却对这份安静起了疑心，随时等着什么“灾难”发生。放松点。有时候他们也想一个人待着。靠在椅背上，好好享受这难得的离线时光吧。' WHERE id = '7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tiempo y los cambios repentinos ⛅', body_es = '¿Fuera el tiempo no está claro, hace sol pero también sopla viento? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado, y sal de paseo sin perder tiempo dudando en la puerta.', title_fr = 'La météo et ses caprices ⛅', body_fr = 'Le temps dehors n''est pas très clair, du soleil mais aussi du vent ? Laissez Météo et tenue vous indiquer aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue, et partez en promenade sans perdre de temps à hésiter sur le pas de la porte.', title_hi = 'मौसम और अचानक बदलाव ⛅', body_hi = 'बाहर मौसम पूरा साफ़ नहीं, धूप है पर हवा भी चल रही है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताए, ताकि दरवाज़े पर दुविधा में समय गँवाए बिना सैर पर निकल सकें।', title_id = 'Cuaca dan perubahan mendadak ⛅', body_id = 'Cuaca di luar tidak menentu, ada matahari tapi angin juga bertiup? Biarkan Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan setelan yang tepat, lalu pergilah jalan-jalan tanpa membuang waktu ragu-ragu di depan pintu.', title_ja = '天気と急な変化 ⛅', body_ja = '外は晴れているのか、日は出ているけれど風も吹いている？「天気と服装」に、窓からは見えない風の強さとぴったりのコーデをすぐに教えてもらいましょう。玄関で迷って時間をむだにせず、お散歩に出かけましょう。', title_ko = '날씨와 갑작스러운 변화 ⛅', body_ko = '밖의 날씨가 애매하게 해는 났는데 바람도 부나요? 창밖으로는 보이지 않는 풍속과 알맞은 옷차림을 날씨와 옷차림 도구가 바로 알려 줄 거예요. 현관에서 망설이며 시간 보내지 말고 산책을 나가세요.', title_nl = 'Weer en plotselinge omslagen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk, met zon maar ook wind? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je vanuit het raam niet ziet, en de juiste outfit, en ga wandelen zonder twijfelend tijd te verliezen bij de deur.', title_pl = 'Pogoda i nagłe zmiany ⛅', body_pl = 'Pogoda na dworze niepewna, świeci słońce, ale wieje wiatr? Niech narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru, której nie widać przez okno, i właściwy zestaw ubrań. Wyjdźcie na spacer, nie tracąc czasu na wahanie w progu.', title_pt = 'Tempo e mudanças repentinas ⛅', body_pt = 'O tempo lá fora não está bem definido: há sol, mas também vento? Deixe que a ferramenta Tempo e Roupa lhe diga logo a velocidade do vento, que não se vê da janela, e a roupa certa, e saia para passear sem perder tempo indecisa à porta.', title_sv = 'Vädret och plötsliga omslag ⛅', body_sv = 'Är vädret ute inte riktigt klart, solen skiner men det blåser också? Låt verktyget Väder och kläder direkt visa vindhastigheten som inte syns genom fönstret och rätt klädsel, så kommer ni ut på promenad utan att stå villrådiga och förlora tid i dörren.', title_vi = 'Thời tiết thay đổi bất chợt ⛅', body_vi = 'Thời tiết ngoài trời không rõ ràng, có nắng nhưng cũng có gió? Hãy để Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp, để ra ngoài đi dạo mà không mất thời gian lưỡng lự ở cửa.', title_zh = '天气与突然的变化 ⛅', body_zh = '外面天气说不准，有太阳但也刮着风？让天气与穿衣工具马上告诉你从窗户看不出的风速和正确的搭配，别再犹豫着在门口浪费时间，出门散步吧。' WHERE id = '7da1ffab-3792-4ba0-b3b7-ce279478fa15' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Por fin se ha dormido! No te puedes creer el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios de la pantalla, siente cómo tu cerebro se recupera y descansa poco a poco.', body_fr = 'Il dort enfin ! Vous n''en revenez pas du silence qui tombe sur la maison. Activez le Sonomètre et, en regardant les 0 à 10 décibels à l''écran, sentez votre cerveau récupérer et se reposer peu à peu.', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा। साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखकर महसूस कीजिए कि आपका दिमाग धीरे-धीरे कैसे ठीक हो रहा है, आराम पा रहा है।', body_id = 'Akhirnya ia tertidur! Anda tak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara dan lihat angka 0-10 desibel di layar, rasakan secara visual bagaimana otak Anda perlahan pulih dan beristirahat.', body_ja = 'やっと寝てくれました！家に広がる静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、脳が少しずつ回復し、休まっていくのを目で感じてみましょう。', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 회복되고 쉬는 걸 눈으로 느껴 보세요.', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je brein langzaam herstelt en tot rust komt.', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku i patrząc na wynik 0-10 decybeli na ekranie, poczuj, jak twój mózg powoli dochodzi do siebie i odpoczywa.', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para os 0-10 decibéis no ecrã, sinta visualmente o seu cérebro a recuperar e a descansar devagarinho.', body_sv = 'Äntligen har barnet somnat! Du kan inte tro på tystnaden som sänker sig över hemmet. Aktivera verktyget Ljudmätare och titta på siffran 0-10 decibel på skärmen, så känner du visuellt hur hjärnan sakta återhämtar sig och vilar.', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không thể tin vào sự tĩnh lặng đang bao trùm căn nhà. Hãy bật Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận não bộ của mình đang dần hồi phục, được nghỉ ngơi.', body_zh = '宝宝终于睡着了！你简直不敢相信家里这么安静。打开分贝仪，看着屏幕上0-10分贝的数字，直观地感受大脑正在一点点恢复、休息下来。' WHERE id = 'be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Habla como un abogado 🗣️', body_es = '¿Ya intenta negociar contigo con palabras? ¿Te dice «juego un poco más y luego me duermo»? Su habla se desarrolla de maravilla, pero no olvides proteger tus límites.', title_fr = 'Il parle comme un avocat 🗣️', body_fr = 'Il essaie déjà de négocier avec vous par les mots ? Il dit « Je joue encore un peu, après je dors » ? Son langage progresse très bien, mais n''oubliez pas de tenir vos limites.', title_hi = 'वकील की तरह बात करता है 🗣️', body_hi = 'अब शब्दों से आपसे मोलभाव करने की कोशिश करता है? कहता है, ‘थोड़ा और खेल लूँ, फिर सोऊँगा’? उसकी बोली शानदार तरीके से बढ़ रही है, पर अपनी सीमाओं की रक्षा करना मत भूलिए।', title_id = 'Bicara seperti pengacara 🗣️', body_id = 'Ia sudah mencoba tawar-menawar dengan Anda lewat kata-kata? Ia berkata ''Main sebentar lagi ya, nanti aku tidur''? Kemampuan bicaranya berkembang sangat baik, tapi jangan lupa menjaga batasan Anda.', title_ja = '弁護士みたいに話す 🗣️', body_ja = 'もう言葉であなたと交渉しようとしている？「もうちょっと遊んだら寝る」と言ってくる？言葉はすばらしく育っていますが、境界線を守ることも忘れないで。', title_ko = '변호사처럼 말해요 🗣️', body_ko = '벌써 말로 엄마와 흥정하려 하나요? ''조금만 더 놀고 잘게''라고 하나요? 언어 발달이 훌륭하지만, 경계를 지키는 걸 잊지 마세요.', title_nl = 'Hij praat als een advocaat 🗣️', body_nl = 'Probeert hij al met woorden met je te onderhandelen? Zegt hij ''Nog even spelen, dan ga ik slapen''? Zijn taalontwikkeling is prima, maar vergeet niet je grenzen te bewaken.', title_pl = 'Mówi jak adwokat 🗣️', body_pl = 'Już próbuje się z tobą targować słowami? Mówi: „Jeszcze trochę się pobawię, potem pójdę spać”? Mowa świetnie się rozwija, ale nie zapominaj pilnować swoich granic.', title_pt = 'Fala como um advogado 🗣️', body_pt = 'Já tenta negociar consigo com palavras? Diz "Só mais um bocadinho a brincar e depois vou dormir"? A fala está a desenvolver-se muito bem, mas não se esqueça de proteger os seus limites.', title_sv = 'Pratar som en advokat 🗣️', body_sv = 'Försöker barnet redan förhandla med dig med ord? Säger det ”Jag leker lite till, sen sover jag”? Talet utvecklas utmärkt, men glöm inte att hålla fast vid dina gränser.', title_vi = 'Nói chuyện như luật sư 🗣️', body_vi = 'Bé đã biết dùng lời để mặc cả với mẹ? "Cho con chơi thêm chút nữa, rồi con đi ngủ"? Khả năng ngôn ngữ phát triển tuyệt vời, nhưng đừng quên giữ vững giới hạn của mình.', title_zh = '像律师一样说话 🗣️', body_zh = '已经在用语言和你讨价还价了？“再玩一会儿，然后我就睡”？语言发展得很棒，但别忘了守住你的边界。' WHERE id = '602f2986-8e86-421e-ab71-94038d048ccf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Masaje de victoria 💆‍♂️', body_es = 'Cuando el peque se duerma, daos un masaje de hombros tú y tu pareja para soltar el estrés del día. ¡Mañana es el aniversario de los 3 años y entre tanto ajetreo los dos necesitaréis energía!', title_fr = 'La détente de la victoire 💆‍♂️', body_fr = 'Une fois l''enfant couché, massez-vous les épaules l''un l''autre avec votre partenaire pour évacuer le stress de la journée. Pour la fête de ses 3 ans demain et toute l''agitation qui va avec, vous aurez besoin de toute votre énergie !', title_hi = 'जीत की मसाज 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ एक-दूसरे के कंधों की मालिश कीजिए। कल की 3 साल की सालगिरह और भागदौड़ के लिए आप दोनों में ऊर्जा होनी ज़रूरी है!', title_id = 'Relaksasi kemenangan 💆‍♂️', body_id = 'Setelah anak tidur, saling pijat bahu bersama pasangan untuk melepas stres seharian. Besok ulang tahun ke-3 dan segala kesibukannya, jadi kalian berdua harus berenergi!', title_ja = '勝利のマッサージ 💆‍♂️', body_ja = '子どもが寝たら、パートナーと肩をもみ合って一日のストレスを手放しましょう。明日の3歳のお祝いと大忙しの一日のために、ふたりとも元気でいなくちゃ！', title_ko = '승리의 휴식 💆‍♂️', body_ko = '아이가 잠들면 하루의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 내일 세 살 생일과 북새통을 위해 두 사람 모두 에너지가 꼭 필요해요!', title_nl = 'Ontspanning als overwinning 💆‍♂️', body_nl = 'Geef elkaar met je partner een schoudermassage als je kind slaapt, om de stress van de dag kwijt te raken. Voor het 3-jarig jubileum en alle drukte van morgen moeten jullie allebei vol energie zitten!', title_pl = 'Relaks zwycięzców 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres dnia. Na jutrzejsze 3. urodziny i całe zamieszanie oboje potrzebujecie mnóstwa energii!', title_pt = 'Massagem da vitória 💆‍♂️', body_pt = 'Depois de a criança adormecer, façam massagens nos ombros um ao outro para libertar o stress do dia. Para o aniversário de 3 anos e a correria de amanhã, os dois precisam de estar cheios de energia!', title_sv = 'Segermassage 💆‍♂️', body_sv = 'När barnet har somnat kan du och din partner ge varandra en axelmassage för att släppa dagens stress. Inför morgondagens 3-årsfirande och allt springande behöver ni båda ha energi!', title_vi = 'Thư giãn mừng chiến thắng 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng chồng mát-xa vai cho nhau để xua tan căng thẳng cả ngày. Cả hai cần thật nhiều năng lượng cho lễ mừng sinh nhật 3 tuổi và những bận rộn ngày mai!', title_zh = '胜利前的准备 💆‍♂️', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天的压力。为了明天的3岁生日和忙忙碌碌，你们俩一定都要精力充沛！' WHERE id = '08d5ac7d-b540-46e7-9f43-7f771edfd887' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La realidad después de la fiesta 🚀', body_es = 'Tras el gran aniversario de ayer, esta mañana nos hemos despertado otra vez entre juguetes tirados y «¡no me quiero vestir!». La vida ha vuelto a su ritmo. Respira hondo: eres la mejor directora de este caos.', title_fr = 'La réalité d''après la fête 🚀', body_fr = 'Après la grande fête d''hier, ce matin, réveil au milieu des jouets éparpillés et des « Je veux pas m''habiller ! ». La vie a repris son rythme. Respirez profondément, vous êtes la meilleure cheffe d''orchestre de ce chaos.', title_hi = 'जश्न के बाद की हकीकत 🚀', body_hi = 'कल की बड़ी सालगिरह के बाद आज सुबह फिर बिखरे खिलौनों और ‘मुझे कपड़े नहीं पहनने!’ के साथ आँख खुली। ज़िंदगी अपनी लय में लौट आई। गहरी साँस लीजिए, आप इस अफ़रा-तफ़री की सबसे बढ़िया संचालक हैं।', title_id = 'Kenyataan setelah pesta 🚀', body_id = 'Setelah perayaan besar kemarin, pagi ini kita kembali bangun di tengah mainan berserakan dan ''Aku nggak mau pakai baju!''. Hidup kembali ke iramanya. Tarik napas dalam, Anda adalah pengelola terbaik dari kekacauan ini.', title_ja = 'お祝いのあとの現実 🚀', body_ja = '昨日の盛大なお祝いのあと、今朝はまた散らかったおもちゃと「着がえたくない！」で目が覚めました。日常がいつものリズムに戻ったんです。深呼吸して。あなたはこのカオスのいちばんすてきなまとめ役です。', title_ko = '축제 다음 날의 현실 🚀', body_ko = '어제의 큰 생일 잔치가 끝나고, 오늘 아침 다시 흩어진 장난감과 ''옷 안 입을 거야!''로 눈을 떴죠. 일상이 제 리듬으로 돌아왔어요. 깊게 숨 쉬세요, 엄마는 이 혼돈의 가장 멋진 관리자예요.', title_nl = 'De realiteit na het feest 🚀', body_nl = 'Na het grote feest van gisteren werden we vanochtend weer wakker met rondslingerend speelgoed en ''Ik wil me niet aankleden!''. Het leven heeft zijn ritme hervonden. Haal diep adem, jij bent de beste regisseur van deze chaos.', title_pl = 'Rzeczywistość po święcie 🚀', body_pl = 'Po wczorajszym wielkim jubileuszu rano znów obudziły nas porozrzucane zabawki i „Nie chcę się ubierać!”. Życie wróciło do swojego rytmu. Weź głęboki oddech, jesteś najlepszą kierowniczką tego chaosu.', title_pt = 'A realidade depois da festa 🚀', body_pt = 'Depois do grande aniversário de ontem, esta manhã acordámos outra vez com brinquedos espalhados e muitos "Não me quero vestir!". A vida voltou ao seu ritmo. Respire fundo: é a melhor gestora deste caos.', title_sv = 'Verkligheten efter festen 🚀', body_sv = 'Efter gårdagens stora firande vaknade vi i morse återigen till utspridda leksaker och ”jag vill inte klä på mig!”. Livet är tillbaka i sin rytm. Andas djupt, du är den bästa ledaren av det här kaoset.', title_vi = 'Thực tế sau bữa tiệc 🚀', body_vi = 'Sau lễ sinh nhật hoành tráng hôm qua, sáng nay lại thức dậy giữa đồ chơi bừa bộn và những câu "Con không muốn mặc quần áo!". Cuộc sống đã trở lại nhịp quen thuộc. Hãy hít thở sâu, mẹ chính là người quản lý tuyệt vời nhất của sự hỗn loạn này.', title_zh = '节日之后的现实 🚀', body_zh = '昨天的盛大生日过后，今早醒来又是满地的玩具和一声声“我不要穿衣服！”。生活回到了原来的节奏。深吸一口气，你是这场混乱最出色的掌控者。' WHERE id = '278a6dcf-b4d5-435f-bebd-984362b1ec54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Celébralo con tu pareja 🥂', body_es = 'Celebra esta noche con tu pareja el cansancio, las lágrimas y la alegría de estos 3 años. Pon una vela en la mesa y aplaudid con una sonrisa vuestra inquebrantable victoria como equipo.', title_fr = 'Fêtez-le avec votre partenaire 🥂', body_fr = 'Ce soir, célébrez avec votre partenaire 3 années de fatigue, de larmes et de joie. Allumez une bougie sur la table et applaudissez avec un grand sourire votre victoire d''équipe inébranlable !', title_hi = 'साथी के साथ जश्न 🥂', body_hi = '3 साल की थकान, आँसू और खुशियाँ आज शाम अपने साथी के साथ मनाइए। मेज़ पर एक मोमबत्ती रखिए और अपनी अटूट टीम की जीत का बड़ी खुशी और मुस्कान के साथ स्वागत कीजिए!', title_id = 'Rayakan bersama pasangan 🥂', body_id = 'Malam ini rayakan rasa lelah, air mata, dan kebahagiaan 3 tahun bersama pasanganmu. Nyalakan lilin di meja dan sambut kemenangan tim kalian yang tak tergoyahkan dengan penuh suka cita dan senyuman!', title_ja = 'パートナーとお祝いしよう 🥂', body_ja = '3年分の疲れも涙も喜びも、今夜はパートナーと一緒にお祝いしましょう。テーブルにキャンドルを灯して、揺るがないチームの勝利を、笑顔で盛大にたたえて！', title_ko = '배우자와 축하해요 🥂', body_ko = '3년간의 피로와 눈물과 기쁨을 오늘 저녁 배우자와 함께 축하하세요. 식탁에 초를 하나 켜고, 흔들림 없는 팀의 승리를 활짝 웃으며 박수로 축하해 주세요!', title_nl = 'Vier het met je partner 🥂', body_nl = 'Vier vanavond met je partner de vermoeidheid, de tranen en de vreugde van 3 jaar. Zet een kaars op tafel en juich jullie onverwoestbare teamoverwinning met een grote glimlach toe!', title_pl = 'Świętuj z partnerem 🥂', body_pl = 'Uczcij dziś wieczorem z partnerem 3 lata zmęczenia, łez i radości. Postawcie na stole świecę i z uśmiechem oklaskujcie wasze niezłomne, wspólne zwycięstwo!', title_pt = 'Celebre com o seu companheiro 🥂', body_pt = 'Esta noite, celebre com o seu companheiro o cansaço, as lágrimas e a alegria de 3 anos. Ponham uma vela na mesa e aplaudam, com grande alegria e a sorrir, a vitória desta equipa inabalável!', title_sv = 'Fira med din partner 🥂', body_sv = 'Fira 3 års trötthet, tårar och glädje tillsammans med din partner i kväll. Tänd ett ljus på bordet och applådera er orubbliga lagseger med stor glädje och ett leende!', title_vi = 'Ăn mừng cùng chồng 🥂', body_vi = 'Tối nay, hãy cùng chồng ăn mừng 3 năm của mệt mỏi, nước mắt và niềm vui. Thắp một ngọn nến trên bàn, mỉm cười và hân hoan chúc mừng chiến thắng của đội ăn ý không gì lay chuyển được của hai người!', title_zh = '和伴侣一起庆祝 🥂', body_zh = '今晚和伴侣一起庆祝这3年的疲惫、泪水和欢乐。在餐桌上点一支蜡烛，满怀喜悦、笑着为你们这支坚不可摧的团队的胜利鼓掌！' WHERE id = '36c78cd2-37d5-4665-84a1-551e9c9c2557' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Últimos 5 días para los 3 años! 🚀', body_es = '¡Es increíble! Solo quedan 5 días para sus enormes 3 años. Has criado a esta personita que escribe sus propias normas en casa. Encarga ya la tarta en Anacan y empieza los preparativos.', title_fr = 'Plus que 5 jours avant ses 3 ans ! 🚀', body_fr = 'Incroyable ! Plus que 5 jours avant ses grands 3 ans. C''est vous qui avez élevé ce petit être qui écrit ses propres règles à la maison. Commandez dès maintenant le gâteau sur Anacan et lancez les préparatifs.', title_hi = '3 साल में बस 5 दिन! 🚀', body_hi = 'यकीन नहीं होता! उस बड़े 3 साल में सिर्फ़ 5 दिन बचे हैं। घर में अपने नियम खुद बनाने वाले इस नन्हे इंसान को आपने बड़ा किया है। Anacan से केक का ऑर्डर अभी दीजिए और तैयारी शुरू कीजिए।', title_id = '5 hari lagi menuju 3 tahun! 🚀', body_id = 'Luar biasa! Tinggal 5 hari lagi menuju usia 3 tahun yang hebat itu. Andalah yang membesarkan sosok kecil yang kini membuat aturannya sendiri di rumah. Pesan kue dari Anacan sekarang juga dan mulailah persiapannya.', title_ja = '3歳まであと5日！ 🚀', body_ja = '信じられない！あの大きな3歳まで、あとたった5日。家の中で自分のルールをつくるこの小さな個性を、あなたが育ててきたんです。今すぐAnacanでケーキを注文して、準備を始めましょう。', title_ko = '세 살까지 5일! 🚀', body_ko = '믿기지 않아요! 대망의 세 살까지 딱 5일 남았어요. 집 안에서 자기만의 규칙을 만드는 이 작은 사람을 엄마가 키워 냈어요. 지금 Anacan에서 케이크를 주문하고 준비를 시작하세요.', title_nl = 'Nog 5 dagen tot 3 jaar! 🚀', body_nl = 'Ongelooflijk! Nog maar 5 dagen tot die grote 3 jaar. Jij hebt dit kleine mensje grootgebracht dat thuis zijn eigen regels schrijft. Bestel nu een taart via Anacan en begin met de voorbereidingen.', title_pl = 'Ostatnie 5 dni do 3 lat! 🚀', body_pl = 'Niesamowite! Do wielkich 3 lat zostało tylko 5 dni. To ty wychowałaś tego małego człowieka, który pisze w domu własne zasady. Zamów tort w Anacan już teraz i zacznij przygotowania.', title_pt = 'Faltam 5 dias para os 3 anos! 🚀', body_pt = 'É incrível! Faltam apenas 5 dias para os grandes 3 anos. Foi a mãe que criou esta pequena pessoa que escreve as próprias regras cá em casa. Encomende já o bolo na Anacan e comece os preparativos.', title_sv = '5 dagar kvar till 3 år! 🚀', body_sv = 'Otroligt! Bara 5 dagar kvar till de stora 3 åren. Det är du som har fostrat den här lilla personen som skriver sina egna regler hemma. Beställ tårtan från Anacan redan nu och börja förberedelserna.', title_vi = 'Còn 5 ngày nữa là tròn 3 tuổi! 🚀', body_vi = 'Thật khó tin! Chỉ còn 5 ngày nữa là bé tròn 3 tuổi. Chính mẹ đã nuôi lớn "cá nhân" nhỏ bé đang tự đặt ra luật lệ trong nhà này. Hãy đặt bánh kem từ Anacan ngay bây giờ và bắt đầu chuẩn bị nhé.', title_zh = '离3岁只剩5天！🚀', body_zh = '真不可思议！离那个了不起的3岁只剩5天了。这个在家里自己定规矩的小家伙，是你一手带大的。现在就在Anacan订蛋糕，开始准备吧。' WHERE id = '3b764723-4ccb-4ab8-a1ed-3b072c5f8a25' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Unos magníficos 3 años! 👑🎉', body_es = '¡Enhorabuena! ¡Ya tiene 3 años! ¡Llevas exactamente {milestone_days} días recorriendo este camino agitado y agotador, pero el más dulce del mundo! ¡Celebra ya este día especial y comparte tu alegría con todos!', title_fr = 'Ses 3 ans formidables ! 👑🎉', body_fr = 'Félicitations ! Il a 3 ans ! Depuis exactement {milestone_days} jours, vous parcourez ce chemin agité, épuisant, mais le plus délicieux du monde ! Fêtez vite cette journée spéciale et partagez votre joie avec tout le monde !', title_hi = 'शानदार 3 साल! 👑🎉', body_hi = 'बधाई हो! वह अब 3 साल का हो गया! पूरे {milestone_days} दिनों से आप इस तूफ़ानी, थका देने वाले, पर दुनिया के सबसे प्यारे रास्ते पर चल रही हैं! इस खास दिन का तुरंत जश्न मनाइए और अपनी खुशी सबके साथ बाँटिए!', title_id = '3 tahun yang hebat! 👑🎉', body_id = 'Selamat! Kini ia sudah berusia 3 tahun! Tepat {milestone_days} hari Anda menempuh perjalanan yang penuh badai dan melelahkan, namun paling indah di dunia ini! Segera rayakan hari istimewa ini dan bagikan kebahagiaan Anda kepada semua orang!', title_ja = 'すばらしい3歳！ 👑🎉', body_ja = 'おめでとうございます！ついに3歳です！ちょうど{milestone_days}日間、この嵐のようで、くたくたになるけれど、世界でいちばんすてきな道を歩んできました！さっそくこの特別な日を盛大にお祝いして、喜びをみんなと分かち合いましょう！', title_ko = '멋진 세 살! 👑🎉', body_ko = '축하해요! 이제 세 살이에요! 꼬박 {milestone_days}일 동안 폭풍 같고 고되지만 세상에서 가장 달콤한 길을 걸어왔어요! 지금 이 특별한 날을 축하하고 모두와 기쁨을 나누세요!', title_nl = 'Geweldige 3 jaar! 👑🎉', body_nl = 'Gefeliciteerd! Hij is nu 3 jaar! Al precies {milestone_days} dagen loop je deze stormachtige, vermoeiende, maar heerlijkste weg ter wereld! Maak er meteen een feest van en deel je vreugde met iedereen!', title_pl = 'Wspaniałe 3 lata! 👑🎉', body_pl = 'Gratulacje! Ma już 3 lata! Od równych {milestone_days} dni idziesz tą burzliwą, męczącą, ale najsłodszą drogą na świecie! Uczcij hucznie ten wyjątkowy dzień i podziel się radością ze wszystkimi!', title_pt = 'Uns fantásticos 3 anos! 👑🎉', body_pt = 'Parabéns! Já tem 3 anos! Há exatamente {milestone_days} dias que percorre este caminho tempestuoso e cansativo, mas o mais delicioso do mundo! Celebre já este dia especial e partilhe a sua alegria com todos!', title_sv = 'Fantastiska 3 år! 👑🎉', body_sv = 'Grattis! Nu är barnet 3 år! I precis {milestone_days} dagar har du gått den här stormiga, tröttsamma men världens ljuvligaste vägen! Fira den här speciella dagen direkt och dela din glädje med alla!', title_vi = 'Tuổi lên 3 tuyệt vời! 👑🎉', body_vi = 'Chúc mừng! Bé đã tròn 3 tuổi! Đúng {milestone_days} ngày mẹ đã bước trên con đường đầy sóng gió, mệt nhoài nhưng ngọt ngào nhất thế giới này! Hãy ăn mừng ngày đặc biệt này ngay và chia sẻ niềm vui với mọi người!', title_zh = '了不起的3岁！👑🎉', body_zh = '恭喜！宝宝已经3岁了！整整{milestone_days}天，你们一直走在这条风风雨雨、令人疲惫，却也是世界上最甜蜜的路上！马上庆祝这个特别的日子，把喜悦分享给所有人吧！' WHERE id = '6148534d-dac4-4ca6-9b42-87f0242f8cdb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres perfecta! 📈', body_es = '¡Qué largo camino ha recorrido tu peque! El miedo frágil de los primeros días ha dejado paso a una enorme confianza y sabiduría. ¡Has llegado a estos 3 años con mucho orgullo! ¡De verdad eres una madre estupenda!', title_fr = 'Vous êtes formidable ! 📈', body_fr = 'Quel chemin parcouru par votre enfant ! Les peurs fragiles des premiers jours ont laissé place à une immense confiance et à la curiosité. Vous avez traversé ces 3 années avec une grande fierté ! Vous êtes vraiment une maman formidable !', title_hi = 'आप कमाल हैं! 📈', body_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! शुरुआती दिनों के नाज़ुक डर की जगह अब बड़े भरोसे और समझ ने ले ली है। आपने ये 3 साल बड़े गर्व के साथ पूरे किए! आप सच में बेहतरीन माँ हैं!', title_id = 'Kamu luar biasa! 📈', body_id = 'Lihat betapa jauh perjalanan anak Anda! Ketakutan rapuh di hari-hari pertama kini berganti dengan rasa percaya diri dan keingintahuan yang besar. Kamu melalui 3 tahun ini dengan penuh kebanggaan! Kamu sungguh ibu yang hebat!', title_ja = 'あなたは完璧！ 📈', body_ja = 'お子さんはなんて大きく成長したのでしょう！最初のころの壊れそうな不安は、今では大きな自信と知恵に変わりました。あなたはこの3年を誇りをもって歩んできたんです！本当にすばらしいママです！', title_ko = '엄마는 완벽해요! 📈', body_ko = '아이가 얼마나 먼 길을 왔는지 보세요! 첫날의 그 연약한 두려움은 이제 큰 자신감과 호기심이 되었어요. 엄마는 이 3년을 자랑스럽게 지나왔어요! 정말 멋진 엄마예요!', title_nl = 'Je doet het geweldig! 📈', body_nl = 'Wat heeft je kind een lange weg afgelegd! De breekbare angst van de eerste dagen heeft plaatsgemaakt voor groot vertrouwen en nieuwsgierigheid. Je hebt deze 3 jaar met trots doorlopen! Je bent echt een geweldige mama!', title_pl = 'Jesteś wspaniała! 📈', body_pl = 'Jak długą drogę przeszło twoje dziecko! Kruchy lęk pierwszych dni ustąpił miejsca ogromnej pewności siebie i ciekawości. Przeszłaś te 3 lata z wielką dumą! Naprawdę jesteś świetną mamą!', title_pt = 'É perfeita! 📈', body_pt = 'Que caminho tão grande o seu filho percorreu! O medo frágil dos primeiros dias deu lugar a uma enorme confiança e sabedoria. Chegou a estes 3 anos com grande orgulho! É mesmo uma mãe excelente!', title_sv = 'Du är fantastisk! 📈', body_sv = 'Vilken lång väg barnet har gått! Den sköra rädslan från de första dagarna har nu ersatts av en enorm tilltro och kunskap. Du har tagit dig igenom de här 3 åren med stor stolthet! Du är verkligen en fantastisk mamma!', title_vi = 'Mẹ thật tuyệt vời! 📈', body_vi = 'Bé đã đi một chặng đường thật dài! Nỗi sợ mong manh của những ngày đầu giờ đã nhường chỗ cho sự tự tin và ham hiểu biết lớn lao. Mẹ đã đi qua 3 năm này với niềm tự hào to lớn! Mẹ thật sự là một người mẹ tuyệt vời!', title_zh = '你太棒了！📈', body_zh = '你的孩子走过了多么远的路！最初那些日子里脆弱的害怕，如今已变成满满的自信和经验。这3年你走得无比骄傲！你真的是一位很棒的妈妈！' WHERE id = '94dba968-6bd5-4b01-b8ef-b33b80729320' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Víspera de los 3 años! 🎂', body_es = '¡Mañana es un gran día! Qué camino tan largo habéis recorrido desde aquella primera patadita en tu barriga. Hoy míralo largo rato, elige su ropa y prepara la memoria del móvil para la Sesión de fotos del bebé de mañana.', title_fr = 'La veille de ses 3 ans ! 🎂', body_fr = 'Demain, c''est le grand jour ! Quel chemin parcouru depuis son tout premier coup de pied dans votre ventre. Aujourd''hui, regardez-le longuement, choisissez sa tenue et libérez de la place sur votre téléphone pour la Séance photo bébé de demain.', title_hi = '3 साल से एक दिन पहले! 🎂', body_hi = 'कल बड़ा दिन है! पेट में उसकी पहली किक वाले दिन से आपने कितना लंबा सफ़र तय किया है। आज उसे देर तक निहारिए, उसके कपड़े चुनिए, कल के बेबी फ़ोटोशूट के लिए फ़ोन की मेमोरी तैयार कीजिए।', title_id = 'Malam menjelang 3 tahun! 🎂', body_id = 'Besok adalah hari besar! Betapa panjang perjalanan yang sudah Anda lalui sejak tendangan pertamanya di perut. Hari ini pandangi ia lama-lama, pilihkan bajunya, dan kosongkan memori ponsel untuk Pemotretan Bayi besok.', title_ja = '3歳の前夜！ 🎂', body_ja = '明日はビッグな日！おなかの中で初めて蹴ったあの日から、なんて長い道のりを歩いてきたのでしょう。今日はこの子をゆっくり見つめて、服を選び、明日の「ベビーフォトセッション」のためにスマホの容量を空けておきましょう。', title_ko = '세 살 전날! 🎂', body_ko = '내일은 큰 날이에요! 배 속에서 처음 발로 찼던 그날부터 얼마나 먼 길을 왔는지요. 오늘은 아이를 오래오래 바라보고, 옷을 고르고, 내일 아기 사진 촬영을 위해 휴대폰 저장 공간을 비워 두세요.', title_nl = 'De vooravond van 3 jaar! 🎂', body_nl = 'Morgen is een grote dag! Wat een lange weg hebben jullie afgelegd sinds dat eerste trapje in je buik. Kijk vandaag lang naar hem, kies zijn kleren uit en maak ruimte op je telefoon voor de Babyfotoshoot van morgen.', title_pl = 'W przededniu 3 lat! 🎂', body_pl = 'Jutro wielki dzień! Jaką drogę przeszłaś od dnia, gdy pierwszy raz kopnął w brzuchu. Dziś patrz na niego długo, wybierz mu ubranko i zwolnij pamięć w telefonie na jutrzejszą Sesję zdjęciową dziecka.', title_pt = 'Véspera dos 3 anos! 🎂', body_pt = 'Amanhã é um grande dia! Que caminho enorme percorreram desde o primeiro pontapé na sua barriga. Hoje olhe para ele demoradamente, escolha a roupa e prepare a memória do telemóvel para a Sessão Fotográfica do Bebé de amanhã.', title_sv = 'Kvällen före 3 år! 🎂', body_sv = 'I morgon är det en stor dag! Vilken lång resa ni har gjort sedan den dagen barnet sparkade för första gången i magen. Titta länge på barnet i dag, välj kläderna och gör plats i telefonens minne för morgondagens Babyfotografering.', title_vi = 'Đêm trước sinh nhật 3 tuổi! 🎂', body_vi = 'Ngày mai là một ngày trọng đại! Hai mẹ con đã đi một chặng đường dài kể từ cú đạp đầu tiên trong bụng mẹ. Hôm nay hãy ngắm bé thật lâu, chọn quần áo cho bé và dọn bộ nhớ điện thoại cho buổi Chụp ảnh cho bé ngày mai.', title_zh = '3岁生日前夜！🎂', body_zh = '明天是个大日子！从宝宝第一次在你肚子里踢你的那天起，你们一起走过了多么漫长的路。今天好好地多看看宝宝，挑好衣服，为明天的宝宝写真腾出手机空间吧。' WHERE id = 'dd4c2432-4936-49e7-844c-aec9116027b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
